<?php
/**
 * ============================================================================
 * MY MINI MESSENGER (M3) / پیامرسان کوچک من — Single-File Self-Hosted Web Messenger (index.php)
 * ============================================================================
 * Version:      1.0.0
 * Target PHP:   7.2+ (tested up to PHP 8.4)
 * Extensions:   PDO + (pdo_sqlite OR pdo_mysql), json, hash (mbstring optional)
 * Dependencies: ZERO external dependencies (No CDNs, no external fonts/scripts)
 * Typography:   Embedded Vazirmatn WOFF2 (Persian/Arabic + Latin)
 * Architecture:
 *   1. Bootstrap & Portable UTF-8 / String Helpers
 *   2. Config Loader (chat_data/config.php)
 *   3. Database Layer (PDO SQLite & MySQL abstraction + Schema & Migrations)
 *   4. Settings Service (cached, typed, validated)
 *   5. Security Helpers (CSRF, CSP Nonce, Rate Limiting w/o IP, PoW, Pure-PHP TOTP)
 *   6. Installer Wizard (SQLite/MySQL setup, Super-Admin, Default Group & Channel)
 *   7. Auth, Sessions & Referral Lineage Engine
 *   8. Permission Engine (Roles, Group Mute, Default Channel Guard, Secret Chat Guard)
 *   9. Domain Services & Maintenance (Lazy Purge Engine)
 *  10. Asset & API Router (?a=font|manifest|sw|icon|file|cron|api) + Long Polling
 *  11. Front-End SPA (HTML5 + CSS Logical RTL/LTR + Vazirmatn + I18N fa/en + WebCrypto E2EE)
 * ============================================================================
 */

/* ============================================================================
 * 1. BOOTSTRAP: ERROR HANDLING, CONSTANTS, UTF-8 & PATH HELPERS
 * ============================================================================ */
error_reporting(0);
@ini_set('display_errors', '0');
@ini_set('display_startup_errors', '0');
@ini_set('log_errors', '0');

define('APP_VERSION', '1.0.0');
/* Single source of truth for the schema version. To add a migration: add a
   matching $step(N, ...) call in ensure_schema() AND bump this constant. The
   fast-path guard in ensure_schema() reads it, so a step added without bumping
   it would be skipped on every single request. */
define('SCHEMA_TARGET_VERSION', 18);
if (!defined('PAYAMAK_BOOT')) {
    define('PAYAMAK_BOOT', true);
}
define('DATA_DIR', __DIR__ . '/chat_data');
define('FILES_DIR', DATA_DIR . '/files');
define('CONFIG_FILE', DATA_DIR . '/config.php');
define('INSTALL_LOCK', DATA_DIR . '/installed.lock');
define('TICK_FILE', DATA_DIR . '/tick');
define('VAZIRMATN_WOFF2_B64', '');

if (version_compare(PHP_VERSION, '7.2.0', '<')) {
    header('Content-Type: text/plain; charset=utf-8', true, 500);
    exit('PHP 7.2.0 or higher is required. Current version: ' . PHP_VERSION);
}

/* Portable string helpers (PHP 7.2 compatible; no str_contains/str_starts_with) */
function s_starts_with($haystack, $needle) {
    $haystack = (string)$haystack;
    $needle = (string)$needle;
    if ($needle === '') return true;
    return substr($haystack, 0, strlen($needle)) === $needle;
}

function s_ends_with($haystack, $needle) {
    $haystack = (string)$haystack;
    $needle = (string)$needle;
    if ($needle === '') return true;
    $len = strlen($needle);
    return substr($haystack, -$len) === $needle;
}

function s_contains($haystack, $needle) {
    $haystack = (string)$haystack;
    $needle = (string)$needle;
    if ($needle === '') return true;
    return strpos($haystack, $needle) !== false;
}

function u_strlen($str) {
    $str = (string)$str;
    if (function_exists('mb_strlen')) {
        return mb_strlen($str, 'UTF-8');
    }
    return preg_match_all('/[\x00-\x7F\xC2-\xFD]/', $str, $m);
}

function u_substr($str, $start, $len = null) {
    $str = (string)$str;
    if (function_exists('mb_substr')) {
        return $len === null ? mb_substr($str, $start, null, 'UTF-8') : mb_substr($str, $start, $len, 'UTF-8');
    }
    preg_match_all('/./us', $str, $ar);
    $slice = $len === null ? array_slice($ar[0], $start) : array_slice($ar[0], $start, $len);
    return implode('', $slice);
}

function u_lower($str) {
    $str = (string)$str;
    if (function_exists('mb_strtolower')) {
        return mb_strtolower($str, 'UTF-8');
    }
    return strtolower($str);
}

function h($s) {
    return htmlspecialchars((string)$s, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
}

function is_https_request() {
    if (!empty($_SERVER['HTTPS']) && strtolower((string)$_SERVER['HTTPS']) !== 'off') return true;
    if (!empty($_SERVER['HTTP_X_FORWARDED_PROTO']) && strtolower((string)$_SERVER['HTTP_X_FORWARDED_PROTO']) === 'https') return true;
    if (!empty($_SERVER['SERVER_PORT']) && (int)$_SERVER['SERVER_PORT'] === 443) return true;
    return false;
}

function ensure_data_dirs() {
    if (!is_dir(DATA_DIR)) {
        @mkdir(DATA_DIR, 0750, true);
    }
    @chmod(DATA_DIR, 0750);
    if (!is_dir(FILES_DIR)) {
        @mkdir(FILES_DIR, 0750, true);
    }
    @chmod(FILES_DIR, 0750);
    $ht = DATA_DIR . '/.htaccess';
    if (!file_exists($ht)) {
        @file_put_contents($ht, "Options -Indexes\nOrder deny,allow\nDeny from all\n<IfModule mod_authz_core.c>\nRequire all denied\n</IfModule>\n");
    }
    $wc = DATA_DIR . '/web.config';
    if (!file_exists($wc)) {
        @file_put_contents($wc, "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<configuration><system.webServer><security><authorization><deny users=\"*\" /></authorization></security></system.webServer></configuration>\n");
    }
    $idx = DATA_DIR . '/index.html';
    if (!file_exists($idx)) {
        @file_put_contents($idx, '');
    }
    $fht = FILES_DIR . '/.htaccess';
    if (!file_exists($fht)) {
        @file_put_contents($fht, "Options -Indexes -ExecCGI\nOrder deny,allow\nDeny from all\n<IfModule mod_authz_core.c>\nRequire all denied\n</IfModule>\n<IfModule mod_php7.c>\nphp_flag engine off\n</IfModule>\n<IfModule mod_php.c>\nphp_flag engine off\n</IfModule>\n");
    }
    $fidx = FILES_DIR . '/index.html';
    if (!file_exists($fidx)) {
        @file_put_contents($fidx, '');
    }
    if (!file_exists(TICK_FILE)) {
        @file_put_contents(TICK_FILE, (string)time());
    }
}

function bump_tick() {
    ensure_data_dirs();
    $prev = 0;
    if (file_exists(TICK_FILE)) {
        $rawPrev = @file_get_contents(TICK_FILE);
        if ($rawPrev !== false && ctype_digit(trim($rawPrev))) {
            $prev = (int)trim($rawPrev);
        }
    }
    $nowMs = (int)round(microtime(true) * 1000);
    $v = (string)max($nowMs, $prev + 1);
    @file_put_contents(TICK_FILE, $v, LOCK_EX);
    @clearstatcache(true, TICK_FILE);
    if (isset($GLOBALS['M3_ACTIVE_DB']) && ($GLOBALS['M3_ACTIVE_DB'] instanceof DB)) {
        try {
            $GLOBALS['M3_ACTIVE_DB']->upsert('meta', array('k' => 'global_tick', 'v' => $v), 'k');
        } catch (Exception $e) {}
    }
    return $v;
}

function get_tick() {
    @clearstatcache(true, TICK_FILE);
    $fileTick = '0';
    if (file_exists(TICK_FILE)) {
        $c = @file_get_contents(TICK_FILE);
        $fileTick = ($c !== false && trim($c) !== '') ? trim($c) : (string)@filemtime(TICK_FILE);
    }
    if (isset($GLOBALS['M3_ACTIVE_DB']) && ($GLOBALS['M3_ACTIVE_DB'] instanceof DB)) {
        try {
            $dbTick = (string)$GLOBALS['M3_ACTIVE_DB']->val("SELECT v FROM meta WHERE k = 'global_tick'");
            if ($dbTick !== '' && strcmp($dbTick, $fileTick) > 0) {
                return $dbTick;
            }
        } catch (Exception $e) {}
    }
    return $fileTick;
}

function typing_tick_path() {
    return DATA_DIR . '/.typing_tick';
}

function bump_typing_tick() {
    ensure_data_dirs();
    $tp = typing_tick_path();
    $prev = 0;
    if (file_exists($tp)) {
        $rawPrev = @file_get_contents($tp);
        if ($rawPrev !== false && ctype_digit(trim($rawPrev))) {
            $prev = (int)trim($rawPrev);
        }
    }
    $nowMs = (int)round(microtime(true) * 1000);
    $v = (string)max($nowMs, $prev + 1);
    @file_put_contents($tp, $v, LOCK_EX);
    @clearstatcache(true, $tp);
    if (isset($GLOBALS['M3_ACTIVE_DB']) && ($GLOBALS['M3_ACTIVE_DB'] instanceof DB)) {
        try {
            $GLOBALS['M3_ACTIVE_DB']->upsert('meta', array('k' => 'typing_tick', 'v' => $v), 'k');
        } catch (Exception $e) {}
    }
    return $v;
}

function get_typing_tick() {
    $tp = typing_tick_path();
    @clearstatcache(true, $tp);
    $fileTick = '0';
    if (file_exists($tp)) {
        $c = @file_get_contents($tp);
        $fileTick = ($c !== false && trim($c) !== '') ? trim($c) : (string)@filemtime($tp);
    }
    if (isset($GLOBALS['M3_ACTIVE_DB']) && ($GLOBALS['M3_ACTIVE_DB'] instanceof DB)) {
        try {
            $dbTick = (string)$GLOBALS['M3_ACTIVE_DB']->val("SELECT v FROM meta WHERE k = 'typing_tick'");
            if ($dbTick !== '' && strcmp($dbTick, $fileTick) > 0) {
                return $dbTick;
            }
        } catch (Exception $e) {}
    }
    return $fileTick;
}

function json_out($payload, $status = 200) {
    http_response_code($status);
    header('Content-Type: application/json; charset=utf-8');
    header('Cache-Control: no-store, no-cache, must-revalidate');
    header('X-Content-Type-Options: nosniff');
    header('X-Robots-Tag: noindex, nofollow, noarchive, nosnippet, noimageindex');
    echo json_encode($payload, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
    exit;
}

function api_ok($data = array()) {
    json_out(array('ok' => true, 'data' => $data, 'tick' => get_tick()), 200);
}

function api_err($code, $message = '', $status = 200, $details = null) {
    $payload = array(
        'ok'      => false,
        'error'   => (string)$code,
        'message' => (string)$message ?: (string)$code
    );
    if (is_array($details)) {
        $payload['details'] = $details;
    }
    json_out($payload, $status);
}

/* ============================================================================
 * 2. CONFIG LOADER (chat_data/config.php)
 * ============================================================================ */
function load_app_config() {
    if (!file_exists(CONFIG_FILE)) {
        return null;
    }
    $cfg = @include CONFIG_FILE;
    if (!is_array($cfg) || empty($cfg['installed'])) {
        return null;
    }
    $needsRewrite = false;
    if (empty($cfg['secret'])) {
        $cfg['secret'] = bin2hex(random_bytes_safe(32));
        $needsRewrite = true;
    }
    $rawContent = @file_get_contents(CONFIG_FILE);
    if ($rawContent !== false && strpos($rawContent, 'PAYAMAK_BOOT') === false) {
        $needsRewrite = true;
    }
    $drv = isset($cfg['db_driver']) ? $cfg['db_driver'] : 'sqlite';
    if ($drv !== 'mysql') {
        $curPath = isset($cfg['db_path']) && $cfg['db_path'] !== '' ? (string)$cfg['db_path'] : (DATA_DIR . '/messenger.sqlite');
        // Migrate predictable legacy messenger.sqlite to CSPRNG secret filename so Nginx/Caddy without .htaccess cannot guess DB URL
        if (basename($curPath) === 'messenger.sqlite') {
            $secretDb = DATA_DIR . '/db_' . bin2hex(random_bytes_safe(24)) . '.sqlite';
            if (file_exists($curPath)) {
                if (@rename($curPath, $secretDb)) {
                    @chmod($secretDb, 0600);
                    @unlink($curPath . '-wal');
                    @unlink($curPath . '-shm');
                    $cfg['db_path'] = $secretDb;
                    $needsRewrite = true;
                } else {
                    $cfg['db_path'] = $curPath;
                }
            } else {
                $cfg['db_path'] = $secretDb;
                $needsRewrite = true;
            }
        } elseif (file_exists($curPath)) {
            @chmod($curPath, 0600);
        }
    }
    if ($needsRewrite) {
        write_config_file($cfg);
    }
    return $cfg;
}

/* ============================================================================
 * 3. DB LAYER: PDO FACTORY, DRIVER ABSTRACTION, PORTABLE SQL & MIGRATIONS
 * ============================================================================ */
class DB {
    private $pdo;
    private $driver;
    private $sqliteFile = '';

    public function __construct($config) {
        $this->driver = isset($config['db_driver']) ? $config['db_driver'] : 'sqlite';
        if ($this->driver === 'mysql') {
            $host = isset($config['db_host']) ? trim((string)$config['db_host']) : '127.0.0.1';
            if (!preg_match('/^[A-Za-z0-9.\-:\[\]]+$/', $host)) {
                throw new RuntimeException('Invalid database host format.');
            }
            $port = isset($config['db_port']) ? (int)$config['db_port'] : 3306;
            if ($port < 1 || $port > 65535) {
                $port = 3306;
            }
            $name = isset($config['db_name']) ? trim((string)$config['db_name']) : 'messenger';
            if (!preg_match('/^[A-Za-z0-9_\-]+$/', $name)) {
                throw new RuntimeException('Invalid database name format.');
            }
            $user = isset($config['db_user']) ? $config['db_user'] : 'root';
            $pass = isset($config['db_pass']) ? $config['db_pass'] : '';
            $dsn = "mysql:host={$host};port={$port};dbname={$name};charset=utf8mb4";
            $this->pdo = new PDO($dsn, $user, $pass, array(
                PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION,
                PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC,
                PDO::ATTR_EMULATE_PREPARES => false,
                PDO::ATTR_PERSISTENT => false,
            ));
            $this->pdo->exec("SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci");
        } else {
            $this->driver = 'sqlite';
            $path = isset($config['db_path']) && $config['db_path'] !== '' ? (string)$config['db_path'] : (DATA_DIR . '/messenger.sqlite');
            $this->sqliteFile = $path;
            $this->pdo = new PDO('sqlite:' . $path, null, null, array(
                PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION,
                PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC,
            ));
            @chmod($path, 0600);
            if (file_exists($path . '-wal') || file_exists($path . '-shm')) {
                try { $this->pdo->exec('PRAGMA wal_checkpoint(TRUNCATE)'); } catch (Exception $e) {}
                try { $this->pdo->exec('PRAGMA journal_mode = DELETE'); } catch (Exception $e) {}
            }
            try { $this->pdo->exec('PRAGMA journal_mode = MEMORY'); } catch (Exception $e) {}
            try { $this->pdo->exec('PRAGMA temp_store = MEMORY'); } catch (Exception $e) {}
            try { $this->pdo->exec('PRAGMA synchronous = NORMAL'); } catch (Exception $e) {}
            try { $this->pdo->exec('PRAGMA busy_timeout = 5000'); } catch (Exception $e) {}
            try { $this->pdo->exec('PRAGMA foreign_keys = ON'); } catch (Exception $e) {}
        }
    }

    public function driver() { return $this->driver; }
    public function sqlitePath() { return $this->sqliteFile; }
    public function pdo() { return $this->pdo; }
    public function now() { return time(); }

    public function query($sql, $params = array()) {
        $stmt = $this->pdo->prepare($sql);
        $stmt->execute(array_values($params));
        return $stmt;
    }

    public function exec($sql, $params = array()) {
        $stmt = $this->pdo->prepare($sql);
        $stmt->execute(array_values($params));
        return $stmt->rowCount();
    }

    public function one($sql, $params = array()) {
        $stmt = $this->query($sql, $params);
        $row = $stmt->fetch(PDO::FETCH_ASSOC);
        return $row !== false ? $row : null;
    }

    public function all($sql, $params = array()) {
        $stmt = $this->query($sql, $params);
        $rows = $stmt->fetchAll(PDO::FETCH_ASSOC);
        return is_array($rows) ? $rows : array();
    }

    public function val($sql, $params = array()) {
        $stmt = $this->query($sql, $params);
        $v = $stmt->fetchColumn(0);
        return $v !== false ? $v : null;
    }

    public function lastId() {
        return (int)$this->pdo->lastInsertId();
    }

    public function tx($callback) {
        $this->pdo->beginTransaction();
        try {
            $res = call_user_func($callback, $this);
            $this->pdo->commit();
            return $res;
        } catch (Exception $e) {
            if ($this->pdo->inTransaction()) {
                $this->pdo->rollBack();
            }
            throw $e;
        }
    }

    public function upsert($table, $data, $pkCols) {
        if (!is_array($pkCols)) $pkCols = array($pkCols);
        $cols = array_keys($data);
        $placeholders = implode(', ', array_fill(0, count($cols), '?'));
        $colList = implode(', ', $cols);
        $updates = array();
        foreach ($cols as $c) {
            if (!in_array($c, $pkCols, true)) {
                $updates[] = ($this->driver === 'mysql') ? "{$c} = VALUES({$c})" : "{$c} = excluded.{$c}";
            }
        }
        if ($this->driver === 'mysql') {
            if (!empty($updates)) {
                $sql = "INSERT INTO {$table} ({$colList}) VALUES ({$placeholders}) ON DUPLICATE KEY UPDATE " . implode(', ', $updates);
            } else {
                $sql = "INSERT IGNORE INTO {$table} ({$colList}) VALUES ({$placeholders})";
            }
        } else {
            $pkList = implode(', ', $pkCols);
            $sql = "INSERT INTO {$table} ({$colList}) VALUES ({$placeholders})";
            if (!empty($updates)) {
                $sql .= " ON CONFLICT({$pkList}) DO UPDATE SET " . implode(', ', $updates);
            } else {
                $sql .= " ON CONFLICT({$pkList}) DO NOTHING";
            }
        }
        return $this->exec($sql, array_values($data));
    }

    public function insertIgnore($table, $data) {
        $cols = array_keys($data);
        $placeholders = implode(', ', array_fill(0, count($cols), '?'));
        $colList = implode(', ', $cols);
        if ($this->driver === 'mysql') {
            $sql = "INSERT IGNORE INTO {$table} ({$colList}) VALUES ({$placeholders})";
        } else {
            $sql = "INSERT OR IGNORE INTO {$table} ({$colList}) VALUES ({$placeholders})";
        }
        return $this->exec($sql, array_values($data));
    }

    public function limit($limit, $offset = 0) {
        $limit = max(1, (int)$limit);
        $offset = max(0, (int)$offset);
        return $offset > 0 ? " LIMIT {$limit} OFFSET {$offset} " : " LIMIT {$limit} ";
    }

    /* Column names of a table, straight from the live schema. Used so that backup,
       restore and the live driver migration never depend on a hand-written column
       list that drifts out of sync after a migration. */
    public function tableColumns($table) {
        $table = (string)$table;
        if (!preg_match('/^[A-Za-z0-9_]+$/', $table)) return array();
        $cols = array();
        try {
            if ($this->driver === 'mysql') {
                $rows = $this->all(
                    "SELECT column_name FROM information_schema.columns "
                    . "WHERE table_schema = DATABASE() AND table_name = ? ORDER BY ordinal_position",
                    array($table)
                );
                foreach ($rows as $r) {
                    if (isset($r['column_name']) && $r['column_name'] !== '') $cols[] = (string)$r['column_name'];
                }
            } else {
                $rows = $this->all("PRAGMA table_info({$table})");
                foreach ($rows as $r) {
                    if (isset($r['name']) && $r['name'] !== '') $cols[] = (string)$r['name'];
                }
            }
        } catch (Exception $e) { return array(); }
        return $cols;
    }
}

function m3_column_state(DB $db, $table, $col) {
    $table = (string)$table;
    $col = (string)$col;
    if (!preg_match('/^[A-Za-z0-9_]+$/', $table) || !preg_match('/^[A-Za-z0-9_]+$/', $col)) return -1;
    $cols = $db->tableColumns($table);
    if (empty($cols)) return -1;
    foreach ($cols as $c) {
        if (strcasecmp($c, $col) === 0) return 1;
    }
    return 0;
}

function m3_column_exists(DB $db, $table, $col) {
    return m3_column_state($db, $table, $col) === 1;
}

/* Apply one schema migration step and advance the version marker ONLY when every
   column the step declares really exists afterwards. Previously the DDL ran inside
   a bare try/catch and the marker was bumped unconditionally, so a step that half
   applied was recorded as complete forever and the missing columns surfaced much
   later as runtime "no such column" failures. Structural problems are reported to
   super-admins through admin_health -- never written to a log (zero-log policy). */
function m3_schema_step(DB $db, $targetVer, array $stmts, $after = null, $force = false) {
    $targetVer = (int)$targetVer;
    $cur = (int)$db->val("SELECT v FROM meta WHERE k = 'schema_ver'");
    // $force is set by the explicit repair action, which re-walks the whole ladder
    // on an install whose marker already sits at the target version.
    if (!$force && $cur >= $targetVer) return true;

    $expected = array();
    $rejected = array();
    foreach ($stmts as $sql) {
        $isAdd = preg_match('/^\s*ALTER\s+TABLE\s+[`"\']?([A-Za-z0-9_]+)[`"\']?\s+ADD\s+(?:COLUMN\s+)?[`"\']?([A-Za-z0-9_]+)[`"\']?/i', $sql, $m);
        // Skip statements whose column is already in place. A repair run re-walks every
        // step, so re-issuing each ADD COLUMN would throw on everything already applied.
        if ($isAdd && m3_column_exists($db, $m[1], $m[2])) continue;
        try {
            $db->pdo()->exec($sql);
        } catch (Exception $e) {
            // Re-running a step the engine already applied is not a failure.
            $benign = false;
            if ($isAdd) {
                $benign = m3_column_exists($db, $m[1], $m[2]);
            } elseif (preg_match('/^\s*(CREATE\s+INDEX|CREATE\s+TABLE|DROP\s+TABLE)/i', $sql)) {
                $benign = true;
            }
            if (!$benign) $rejected[] = 'v' . $targetVer . ': ' . $e->getMessage();
        }
        if ($isAdd) $expected[] = array($m[1], $m[2]);
    }

    $missing = array();
    $verifiable = 0;
    foreach ($expected as $pair) {
        $state = m3_column_state($db, $pair[0], $pair[1]);
        if ($state === 0) $missing[] = $pair[0] . '.' . $pair[1];
        if ($state !== -1) $verifiable++;
    }
    if (!isset($GLOBALS['M3_SCHEMA_PENDING']) || !is_array($GLOBALS['M3_SCHEMA_PENDING'])) {
        $GLOBALS['M3_SCHEMA_PENDING'] = array();
    }
    // Block only on a definite absence. If the engine will not tell us what it has,
    // fall back to the previous behaviour rather than wedging the upgrade.
    if (!empty($missing) && $verifiable > 0) {
        // Do not advance: the step is retried on the next request.
        $GLOBALS['M3_SCHEMA_PENDING'][] = 'v' . $targetVer . ' incomplete, retrying: ' . implode(', ', $missing);
        return false;
    }
    if (!empty($rejected)) {
        $GLOBALS['M3_SCHEMA_PENDING'] = array_merge($GLOBALS['M3_SCHEMA_PENDING'], $rejected);
    }
    // Data backfills belong to a first-time upgrade only. A repair run must never re-run
    // them: several are one-shot by design (v13 clears cached device labels).
    if ($after !== null && is_callable($after) && $cur < $targetVer) {
        try { call_user_func($after, $db); } catch (Exception $e) {}
    }
    if ($targetVer > $cur) {
        $db->upsert('meta', array('k' => 'schema_ver', 'v' => (string)$targetVer), 'k');
    }
    return true;
}

function m3_schema_pending() {
    return (isset($GLOBALS['M3_SCHEMA_PENDING']) && is_array($GLOBALS['M3_SCHEMA_PENDING']))
        ? array_values($GLOBALS['M3_SCHEMA_PENDING']) : array();
}

/* Columns the target schema declares but the live database does not actually have.
   The version marker alone does not prove the columns exist: on installs upgraded
   before the migration steps became verified, the marker could reach the target
   version while a step had only half applied. */
function m3_schema_missing_columns(DB $db) {
    $missing = array();
    foreach (m3_schema_step_defs($db->driver() === 'mysql') as $def) {
        foreach ($def[1] as $sql) {
            if (!preg_match('/^\s*ALTER\s+TABLE\s+[`\"\']?([A-Za-z0-9_]+)[`\"\']?\s+ADD\s+(?:COLUMN\s+)?[`\"\']?([A-Za-z0-9_]+)[`\"\']?/i', $sql, $m)) continue;
            if (m3_column_state($db, $m[1], $m[2]) === 0) $missing[] = $m[1] . '.' . $m[2];
        }
    }
    return array_values(array_unique($missing));
}

/* Explicit, super-admin-only repair: re-walk the whole ladder regardless of the
   version marker and re-apply whatever is structurally missing. Structural only --
   data backfills are not re-run. Reported through the API, never written to a log. */
function m3_schema_repair(DB $db) {
    // Deliberately does NOT call ensure_schema(): this runs from inside the fast path
    // of ensure_schema, so re-entering it would recurse. Every entry point here is
    // reached on a request that has already created the tables.
    $before = m3_schema_missing_columns($db);
    if (empty($before)) {
        return array('needed' => false, 'missing_before' => array(), 'repaired' => array(), 'failed' => array());
    }
    foreach (m3_schema_step_defs($db->driver() === 'mysql') as $def) {
        m3_schema_step($db, (int)$def[0], $def[1], isset($def[2]) ? $def[2] : null, true);
    }
    $after = m3_schema_missing_columns($db);
    return array(
        'needed'         => true,
        'missing_before' => $before,
        'repaired'       => array_values(array_diff($before, $after)),
        'failed'         => array_values(array_intersect($before, $after))
    );
}

/* The ordered list of versioned migration steps, kept in one place so that the
   normal upgrader and the explicit repair action walk exactly the same ladder.
   Each entry is array(version, statements, after-closure). */
function m3_schema_step_defs($isMysql) {
    $int = $isMysql ? 'BIGINT' : 'INTEGER';
    $txt = $isMysql ? 'LONGTEXT' : 'TEXT';
    $tail = $isMysql ? ' ENGINE=InnoDB ROW_FORMAT=DYNAMIC DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci' : '';

    $defs = array();
    $step = function ($ver, array $stmts, $after = null) use (&$defs) {
        $defs[] = array((int)$ver, $stmts, $after);
    };



    $step(2, array(
        "ALTER TABLE members ADD COLUMN pinned_at {$int} NOT NULL DEFAULT 0"
    ));

    $step(3, $isMysql ? array(
        "ALTER TABLE reactions MODIFY emoji VARCHAR(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL"
    ) : array());

    $step(4, array(
        "DROP TABLE IF EXISTS audit"
    ));

    $step(6, array(
        "ALTER TABLE members ADD COLUMN mute_send INT NOT NULL DEFAULT 0",
        "ALTER TABLE members ADD COLUMN mute_react INT NOT NULL DEFAULT 0",
        "ALTER TABLE chats ADD COLUMN secret_status VARCHAR(16) NOT NULL DEFAULT 'active'",
        "ALTER TABLE chats ADD COLUMN secret_initiator_id {$int} NOT NULL DEFAULT 0"
    ));

    $step(7, array(
        "ALTER TABLE users ADD COLUMN duress_pass_hash VARCHAR(255) NULL",
        "ALTER TABLE chats ADD COLUMN auto_delete_sec INT NOT NULL DEFAULT 0",
        "ALTER TABLE members ADD COLUMN receipt_read_id {$int} NOT NULL DEFAULT 0",
        "ALTER TABLE members ADD COLUMN pinned_msg_id {$int} NOT NULL DEFAULT 0",
        "ALTER TABLE members ADD COLUMN auto_delete_sec INT NOT NULL DEFAULT 0",
        "ALTER TABLE messages ADD COLUMN forward_origin_id {$int} NULL",
        "ALTER TABLE messages ADD COLUMN forward_hide_author INT NOT NULL DEFAULT 0",
        "ALTER TABLE messages ADD COLUMN visible_only_to {$int} NULL",
        "ALTER TABLE files ADD COLUMN sha256 VARCHAR(64) NULL",
        "CREATE INDEX idx_files_sha256 ON files(sha256)",
        "CREATE INDEX idx_messages_fwd_origin ON messages(forward_origin_id)",
        "CREATE INDEX idx_messages_fwd_from ON messages(forward_from_id)"
    ), function ($db) {
        $db->pdo()->exec("UPDATE members SET receipt_read_id = last_read_id WHERE receipt_read_id = 0 AND last_read_id > 0");
        $db->pdo()->exec("UPDATE messages SET forward_origin_id = forward_from_id WHERE forward_origin_id IS NULL AND forward_from_id IS NOT NULL");
        $unhashed = $db->all("SELECT id, stored_name FROM files WHERE sha256 IS NULL AND encrypted = 0");
        foreach ($unhashed as $uf) {
            $sn = basename((string)$uf['stored_name']);
            $fp = FILES_DIR . '/' . $sn;
            if ($sn !== '' && is_file($fp)) {
                $hVal = @hash_file('sha256', $fp);
                if (is_string($hVal) && strlen($hVal) === 64) {
                    $db->exec("UPDATE files SET sha256 = ? WHERE id = ?", array($hVal, (int)$uf['id']));
                }
            }
        }
    });

    $step(8, array(
        "ALTER TABLE users ADD COLUMN lock_pass_hash VARCHAR(255) NULL",
        "ALTER TABLE sessions ADD COLUMN is_locked INT NOT NULL DEFAULT 0"
    ));

    $step(9, array(
        "ALTER TABLE users ADD COLUMN traffic_used_bytes {$int} NOT NULL DEFAULT 0",
        "ALTER TABLE users ADD COLUMN traffic_period_start {$int} NOT NULL DEFAULT 0",
        "ALTER TABLE call_participants ADD COLUMN speak_req_state VARCHAR(16) NOT NULL DEFAULT 'none'"
    ));

    $step(10, array(
        "ALTER TABLE active_calls ADD COLUMN log_msg_id {$int} NOT NULL DEFAULT 0"
    ));

    $step(11, array(
        "ALTER TABLE sessions ADD COLUMN is_persistent INT NOT NULL DEFAULT 1",
        "ALTER TABLE messages ADD COLUMN spoiler INT NOT NULL DEFAULT 0",
        "CREATE TABLE IF NOT EXISTS message_reads (
                message_id {$int} NOT NULL,
                chat_id {$int} NOT NULL,
                user_id {$int} NOT NULL,
                read_at {$int} NOT NULL,
                PRIMARY KEY (message_id, user_id)
            ){$tail}",
        "CREATE INDEX idx_msg_reads_msg ON message_reads(message_id, read_at)",
        "CREATE INDEX idx_msg_reads_chat_user ON message_reads(chat_id, user_id)"
    ));

    $step(12, array(), function ($db) {
        $curMaxMsgRaw = $db->val("SELECT v FROM settings WHERE k = 'max_msg_len'");
        if ($curMaxMsgRaw !== null && ((int)$curMaxMsgRaw === 4000 || trim((string)$curMaxMsgRaw, '"') === '4000')) {
            Settings::set($db, 'max_msg_len', 2000);
        }
    });

    $step(13, array(
        "ALTER TABLE messages ADD COLUMN pinned_at {$int} NOT NULL DEFAULT 0"
    ), function ($db) {
        $db->pdo()->exec("UPDATE sessions SET device_label = ''");
    });

    $step(14, array(
        "ALTER TABLE messages ADD COLUMN edited_silent INT NOT NULL DEFAULT 0",
        "ALTER TABLE messages ADD COLUMN edit_history_json {$txt} NULL"
    ));

    // Per-member "removed from my own list" support for 1:1 chats.
    // left_at        > 0 -> the chat is hidden from this member only.
    // rejoin_msg_id  > 0 -> messages older than this id stay hidden for this
    //                       member even after they reopen the conversation,
    //                       so the chat feels new for them while the other
    //                       side keeps its uninterrupted history.
    $step(15, array(
        "ALTER TABLE members ADD COLUMN left_at {$int} NOT NULL DEFAULT 0",
        "ALTER TABLE members ADD COLUMN rejoin_msg_id {$int} NOT NULL DEFAULT 0"
    ));

    // Shadow-ban: the member keeps their seat in the chat, but everything written
    // after the ban timestamp is invisible to them, and everything they write after
    // it is invisible to everyone except chat admins (who still see it, marked).
    $step(16, array(
        "ALTER TABLE members ADD COLUMN shadow_banned {$int} NOT NULL DEFAULT 0",
        "ALTER TABLE members ADD COLUMN shadow_banned_at {$int} NULL",
        "ALTER TABLE members ADD COLUMN shadow_banned_by {$int} NULL"
    ), function ($db) {
        // The system chat is seeded once per user, so the renamed label has to be
        // carried over to the rows that already exist. Only the exact old title is
        // touched, so a title somebody customised is left alone.
        try {
            $db->exec("UPDATE chats SET title = 'اعلان‌های پیام‌رسان' WHERE type = 'system' AND title = 'اعلان‌های سیستم'");
            $db->exec("UPDATE chats SET title = 'اعلان‌های پیام‌رسان' WHERE type = 'system' AND title = 'System Notifications'");
        } catch (Exception $e) {
        }
    });
    // Site founder (owner) vs appointed super-admins. The account created at
    // install time is the founder; every super-admin appointed afterwards is a
    // peer of the other appointees and can never outrank or manage the founder.
    $step(17, array(
        "ALTER TABLE users ADD COLUMN is_founder INT NOT NULL DEFAULT 0"
    ), function ($db) {
        // Backfill: on an existing install the earliest super-admin is the founder.
        try {
            $hasFounder = (int)$db->val("SELECT COUNT(*) FROM users WHERE is_founder = 1");
            if ($hasFounder === 0) {
                $firstId = (int)$db->val("SELECT id FROM users WHERE role = 'superadmin' ORDER BY id ASC LIMIT 1");
                if ($firstId > 0) {
                    $db->exec("UPDATE users SET is_founder = 1 WHERE id = ?", array($firstId));
                }
            }
        } catch (Exception $e) {
        }
    });
    // Message view counters for groups and channels. Kept as a column rather than a
    // live COUNT() so a long scroll does not cost one aggregate query per message.
    $step(18, array(
        "ALTER TABLE messages ADD COLUMN views {$int} NOT NULL DEFAULT 0"
    ), function ($db) {
        // Backfill from the read receipts that were already being recorded.
        try {
            $db->exec("UPDATE messages SET views = (SELECT COUNT(*) FROM message_reads mr WHERE mr.message_id = messages.id) WHERE EXISTS (SELECT 1 FROM message_reads mr2 WHERE mr2.message_id = messages.id)");
        } catch (Exception $e) {
        }
    });
    return $defs;
}

function ensure_schema(DB $db) {
    // Fast-path: when the schema is already at the target version, skip the DDL and
    // the metadata locks on every request. Both markers are read in one query so this
    // stays a single cheap lookup.
    try {
        $metaRows = $db->all("SELECT k, v FROM meta WHERE k IN ('schema_ver', 'schema_version', 'schema_check_v')");
        $existingVer = 0;
        $checkedVer = 0;
        $hasDeadKey = false;
        foreach ($metaRows as $mr) {
            if ($mr['k'] === 'schema_ver') $existingVer = (int)$mr['v'];
            elseif ($mr['k'] === 'schema_check_v') $checkedVer = (int)$mr['v'];
            else $hasDeadKey = true;
        }
        // meta.schema_version was written once at install time and never read again,
        // and it kept reporting a frozen 1 while the real marker advanced. Drop the
        // stale row so nothing can mistake it for the real schema version.
        if ($hasDeadKey) {
            try { $db->exec("DELETE FROM meta WHERE k = 'schema_version'"); } catch (Exception $e) {}
        }
        if ($existingVer >= SCHEMA_TARGET_VERSION) {
            // The marker only proves the steps ran, not that every column is really
            // there. Without this an install upgraded before the steps became verified
            // could sit at the target version while a column was missing, and every
            // request would then fail with "no such column" -- which also makes the
            // admin panel unreachable, so it could never be repaired by hand.
            // The outcome is cached in meta, so a healthy install pays nothing: the
            // extra key rides along in the query that is already being issued.
            if ($checkedVer < SCHEMA_TARGET_VERSION) {
                m3_schema_repair($db);
                try {
                    $db->upsert('meta', array('k' => 'schema_check_v', 'v' => (string)SCHEMA_TARGET_VERSION), 'k');
                } catch (Exception $e) {}
            }
            return;
        }
    } catch (Exception $e) {
        // Table meta does not exist yet on fresh install; proceed with full schema setup
    }

    $isMysql = ($db->driver() === 'mysql');
    $pk = $isMysql ? 'BIGINT AUTO_INCREMENT PRIMARY KEY' : 'INTEGER PRIMARY KEY AUTOINCREMENT';
    $int = $isMysql ? 'BIGINT' : 'INTEGER';
    $txt = $isMysql ? 'LONGTEXT' : 'TEXT';
    $emojiCol = $isMysql ? 'VARCHAR(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL' : 'VARCHAR(16) NOT NULL';
    $tail = $isMysql ? ' ENGINE=InnoDB ROW_FORMAT=DYNAMIC DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci' : '';

    $tables = array(
        "CREATE TABLE IF NOT EXISTS meta (
            k VARCHAR(64) PRIMARY KEY,
            v {$txt}
        ){$tail}",

        "CREATE TABLE IF NOT EXISTS settings (
            k VARCHAR(64) PRIMARY KEY,
            v {$txt}
        ){$tail}",

        "CREATE TABLE IF NOT EXISTS users (
            id {$pk},
            username VARCHAR(64) NOT NULL UNIQUE,
            name VARCHAR(128) NOT NULL,
            bio {$txt},
            avatar {$txt},
            pass_hash VARCHAR(255) NOT NULL,
            recovery_hash VARCHAR(255) NOT NULL,
            lang VARCHAR(8) NOT NULL DEFAULT 'fa',
            theme VARCHAR(16) NOT NULL DEFAULT 'auto',
            cal VARCHAR(16) NOT NULL DEFAULT 'jalali',
            flags {$txt},
            role VARCHAR(16) NOT NULL DEFAULT 'user',
            status VARCHAR(16) NOT NULL DEFAULT 'active',
            show_admin_badge INT NOT NULL DEFAULT 1,
            totp_secret VARCHAR(64) NULL,
            pubkey {$txt} NULL,
            key_backup {$txt} NULL,
            invite_code VARCHAR(64) UNIQUE,
            invited_by {$int} NULL,
            created_at {$int} NOT NULL,
            last_seen_bucket {$int} NOT NULL DEFAULT 0,
            delete_at {$int} NULL,
            inactive_delete_days INT NULL,
            duress_pass_hash VARCHAR(255) NULL,
            lock_pass_hash VARCHAR(255) NULL,
            traffic_used_bytes {$int} NOT NULL DEFAULT 0,
            traffic_period_start {$int} NOT NULL DEFAULT 0,
            is_founder INT NOT NULL DEFAULT 0
        ){$tail}",

        "CREATE TABLE IF NOT EXISTS sessions (
            id {$pk},
            user_id {$int} NOT NULL,
            token_hash VARCHAR(64) NOT NULL UNIQUE,
            csrf_token VARCHAR(64) NOT NULL,
            created_at {$int} NOT NULL,
            last_used_bucket {$int} NOT NULL,
            device_label VARCHAR(128) NOT NULL,
            expires_at {$int} NOT NULL,
            is_locked INT NOT NULL DEFAULT 0,
            is_persistent INT NOT NULL DEFAULT 1
        ){$tail}",

        "CREATE TABLE IF NOT EXISTS chats (
            id {$pk},
            type VARCHAR(16) NOT NULL,
            handle VARCHAR(64) UNIQUE NULL,
            title VARCHAR(128) NOT NULL,
            description {$txt},
            avatar {$txt},
            visibility VARCHAR(16) NOT NULL DEFAULT 'private',
            owner_id {$int} NOT NULL DEFAULT 0,
            is_default INT NOT NULL DEFAULT 0,
            all_muted INT NOT NULL DEFAULT 0,
            history VARCHAR(16) NOT NULL DEFAULT 'all',
            default_ttl INT NOT NULL DEFAULT 0,
            ttl_mode VARCHAR(24) NOT NULL DEFAULT 'expire_after_send',
            auto_delete_sec INT NOT NULL DEFAULT 0,
            slow_mode INT NOT NULL DEFAULT 0,
            max_members INT NOT NULL DEFAULT 10000,
            perms_json {$txt},
            secret_status VARCHAR(16) NOT NULL DEFAULT 'active',
            secret_initiator_id {$int} NOT NULL DEFAULT 0,
            status VARCHAR(16) NOT NULL DEFAULT 'active',
            created_at {$int} NOT NULL
        ){$tail}",

        "CREATE TABLE IF NOT EXISTS members (
            chat_id {$int} NOT NULL,
            user_id {$int} NOT NULL,
            role VARCHAR(16) NOT NULL DEFAULT 'member',
            perms_json {$txt},
            joined_msg_id {$int} NOT NULL DEFAULT 0,
            last_read_id {$int} NOT NULL DEFAULT 0,
            receipt_read_id {$int} NOT NULL DEFAULT 0,
            pinned_msg_id {$int} NOT NULL DEFAULT 0,
            auto_delete_sec INT NOT NULL DEFAULT 0,
            muted INT NOT NULL DEFAULT 0,
            pinned_at {$int} NOT NULL DEFAULT 0,
            mute_send INT NOT NULL DEFAULT 0,
            mute_react INT NOT NULL DEFAULT 0,
            banned_until {$int} NULL,
            restricted_until {$int} NULL,
            last_msg_at {$int} NOT NULL DEFAULT 0,
            joined_at {$int} NOT NULL,
            left_at {$int} NOT NULL DEFAULT 0,
            rejoin_msg_id {$int} NOT NULL DEFAULT 0,
            shadow_banned {$int} NOT NULL DEFAULT 0,
            shadow_banned_at {$int} NULL,
            shadow_banned_by {$int} NULL,
            PRIMARY KEY (chat_id, user_id)
        ){$tail}",

        "CREATE TABLE IF NOT EXISTS messages (
            id {$pk},
            chat_id {$int} NOT NULL,
            user_id {$int} NOT NULL,
            kind VARCHAR(16) NOT NULL DEFAULT 'text',
            body {$txt},
            cipher {$txt} NULL,
            iv VARCHAR(64) NULL,
            reply_to {$int} NULL,
            forward_from_id {$int} NULL,
            forward_origin_id {$int} NULL,
            forward_from_name VARCHAR(128) NULL,
            forward_hide_author INT NOT NULL DEFAULT 0,
            visible_only_to {$int} NULL,
            file_id {$int} NULL,
            created_at {$int} NOT NULL,
            edited_at {$int} NULL,
            edited_silent INT NOT NULL DEFAULT 0,
            edit_history_json {$txt} NULL,
            deleted_at {$int} NULL,
            hidden_for {$txt} NULL,
            expires_at {$int} NULL,
            burn_after INT NULL,
            first_read_at {$int} NULL,
            pinned INT NOT NULL DEFAULT 0,
            pinned_at {$int} NOT NULL DEFAULT 0,
            spoiler INT NOT NULL DEFAULT 0
        ){$tail}",

        "CREATE TABLE IF NOT EXISTS files (
            id {$pk},
            owner_id {$int} NOT NULL,
            chat_id {$int} NOT NULL,
            stored_name VARCHAR(128) NOT NULL,
            sha256 VARCHAR(64) NULL,
            display_name VARCHAR(255) NOT NULL,
            mime VARCHAR(64) NOT NULL,
            size {$int} NOT NULL,
            encrypted INT NOT NULL DEFAULT 0,
            file_iv VARCHAR(64) NULL,
            created_at {$int} NOT NULL
        ){$tail}",

        "CREATE TABLE IF NOT EXISTS invites (
            id {$pk},
            chat_id {$int} NOT NULL,
            code VARCHAR(64) NOT NULL UNIQUE,
            created_by {$int} NOT NULL,
            max_uses INT NOT NULL DEFAULT 0,
            uses INT NOT NULL DEFAULT 0,
            expires_at {$int} NULL,
            revoked INT NOT NULL DEFAULT 0
        ){$tail}",

        "CREATE TABLE IF NOT EXISTS invite_codes (
            code VARCHAR(64) PRIMARY KEY,
            created_by {$int} NOT NULL,
            max_uses INT NOT NULL DEFAULT 1,
            uses_left INT NOT NULL DEFAULT 1,
            expires_at {$int} NULL,
            created_at {$int} NOT NULL
        ){$tail}",

        "CREATE TABLE IF NOT EXISTS blocks (
            user_id {$int} NOT NULL,
            blocked_id {$int} NOT NULL,
            PRIMARY KEY (user_id, blocked_id)
        ){$tail}",

        "CREATE TABLE IF NOT EXISTS reactions (
            message_id {$int} NOT NULL,
            user_id {$int} NOT NULL,
            emoji {$emojiCol},
            PRIMARY KEY (message_id, user_id, emoji)
        ){$tail}",

        "CREATE TABLE IF NOT EXISTS message_reads (
            message_id {$int} NOT NULL,
            chat_id {$int} NOT NULL,
            user_id {$int} NOT NULL,
            read_at {$int} NOT NULL,
            PRIMARY KEY (message_id, user_id)
        ){$tail}",

        "CREATE TABLE IF NOT EXISTS reports (
            id {$pk},
            reporter_id {$int} NOT NULL,
            target_type VARCHAR(16) NOT NULL,
            target_id {$int} NOT NULL,
            reason VARCHAR(64) NOT NULL,
            description {$txt},
            created_at {$int} NOT NULL,
            status VARCHAR(16) NOT NULL DEFAULT 'pending'
        ){$tail}",

        "CREATE TABLE IF NOT EXISTS attempts (
            k VARCHAR(128) PRIMARY KEY,
            count INT NOT NULL DEFAULT 0,
            window_start {$int} NOT NULL
        ){$tail}",

        "CREATE TABLE IF NOT EXISTS active_calls (
            id {$pk},
            chat_id {$int} NOT NULL,
            created_by {$int} NOT NULL,
            call_type VARCHAR(16) NOT NULL DEFAULT 'voice',
            status VARCHAR(16) NOT NULL DEFAULT 'ringing',
            audio_quality_policy VARCHAR(24) NOT NULL DEFAULT 'free',
            video_quality_policy VARCHAR(24) NOT NULL DEFAULT 'free',
            max_duration_sec INT NOT NULL DEFAULT 0,
            room_secret VARCHAR(64) NOT NULL,
            log_msg_id {$int} NOT NULL DEFAULT 0,
            started_at {$int} NOT NULL DEFAULT 0,
            created_at {$int} NOT NULL,
            updated_at {$int} NOT NULL
        ){$tail}",

        "CREATE TABLE IF NOT EXISTS call_participants (
            call_id {$int} NOT NULL,
            user_id {$int} NOT NULL,
            role VARCHAR(16) NOT NULL DEFAULT 'speaker',
            state VARCHAR(16) NOT NULL DEFAULT 'joined',
            muted INT NOT NULL DEFAULT 0,
            cam_on INT NOT NULL DEFAULT 0,
            on_hold INT NOT NULL DEFAULT 0,
            speak_req_state VARCHAR(16) NOT NULL DEFAULT 'none',
            audio_quality VARCHAR(16) NOT NULL DEFAULT 'auto',
            video_quality VARCHAR(16) NOT NULL DEFAULT 'auto',
            joined_at {$int} NOT NULL,
            last_seen_at {$int} NOT NULL,
            PRIMARY KEY (call_id, user_id)
        ){$tail}",

        "CREATE TABLE IF NOT EXISTS call_signals (
            id {$pk},
            call_id {$int} NOT NULL,
            from_user_id {$int} NOT NULL,
            to_user_id {$int} NOT NULL DEFAULT 0,
            sig_type VARCHAR(24) NOT NULL,
            payload " . ($isMysql ? 'MEDIUMTEXT' : 'TEXT') . " NOT NULL,
            created_at {$int} NOT NULL
        ){$tail}",

        "CREATE TABLE IF NOT EXISTS call_chunks (
            id {$pk},
            call_id {$int} NOT NULL,
            user_id {$int} NOT NULL,
            media_kind VARCHAR(16) NOT NULL DEFAULT 'audio',
            payload " . ($isMysql ? 'MEDIUMTEXT' : 'TEXT') . " NOT NULL,
            created_at {$int} NOT NULL
        ){$tail}"
    );

    foreach ($tables as $ddl) {
        $db->pdo()->exec($ddl);
    }

    $indexes = array(
        "CREATE INDEX idx_sessions_user ON sessions(user_id)",
        "CREATE INDEX idx_members_user ON members(user_id)",
        "CREATE INDEX idx_messages_chat ON messages(chat_id, id)",
        "CREATE INDEX idx_messages_exp ON messages(expires_at)",
        "CREATE INDEX idx_files_chat ON files(chat_id)",
        "CREATE INDEX idx_users_invited ON users(invited_by)",
        "CREATE INDEX idx_reports_status ON reports(status)",
        "CREATE INDEX idx_active_calls_chat ON active_calls(chat_id, status)",
        "CREATE INDEX idx_call_signals_lookup ON call_signals(call_id, id)",
        "CREATE INDEX idx_call_chunks_lookup ON call_chunks(call_id, id)",
        "CREATE INDEX idx_msg_reads_msg ON message_reads(message_id, read_at)",
        "CREATE INDEX idx_msg_reads_chat_user ON message_reads(chat_id, user_id)"
    );
    foreach ($indexes as $idxSql) {
        try { $db->pdo()->exec($idxSql); } catch (Exception $e) {}
    }

    $ver = $db->val("SELECT v FROM meta WHERE k = 'install_id'");
    if ($ver === null) {
        $db->upsert('meta', array('k' => 'install_id', 'v' => bin2hex(random_bytes_safe(16))), 'k');
        $db->upsert('meta', array('k' => 'pepper', 'v' => bin2hex(random_bytes_safe(32))), 'k');
    }

    $migHalt = false;
    foreach (m3_schema_step_defs($isMysql) as $def) {
        if ($migHalt) break;
        if (!m3_schema_step($db, (int)$def[0], $def[1], isset($def[2]) ? $def[2] : null)) { $migHalt = true; }
    }

    if ($migHalt) {
        // A structural step could not be completed this round. The marker was left
        // where it was, so the next request retries; report it to super-admins
        // instead of logging it.
        return;
    }

    init_default_settings($db);
    ensure_default_chats($db);
}

/* ============================================================================
 * 4. SETTINGS SERVICE (CACHED, TYPED, VALIDATED)
 * ============================================================================ */
function default_settings_map() {
    return array(
        'site_name'       => 'My Mini Messenger (M3)',
        'site_name_fa'    => 'پیامرسان کوچک من (M3)',
        'site_name_en'    => 'My Mini Messenger (M3)',
        'site_logo'       => '',
        'site_favicon'    => '',
        'default_lang'    => 'fa',
        'default_theme'   => 'auto',
        'reg_mode'        => 'open', // open | invite_only | closed
        'username_min_len'     => 3,
        'username_max_len'     => 24,
        'display_name_min_len' => 2,
        'display_name_max_len' => 40,
        'max_msg_len'     => 2000,
        'max_total_users' => 2000,
        'max_user_chats'  => 200,
        'max_user_created_groups'   => 10,
        'max_user_created_channels' => 10,
        'max_group_members'   => 500,
        'max_channel_members' => 2000,
        'global_hide_edit_badge' => 0,
        'force_lock_screen'      => 0,
        'force_decoy_screen'     => 0,
        'global_decoy_title'     => '',
