    $trafficInfo = $effDb ? sync_and_get_user_traffic_status($effDb, $u) : array('used_bytes' => 0, 'limit_mb' => 0, 'limit_bytes' => 0, 'remaining_bytes' => null, 'period_days' => 0, 'reset_at' => 0, 'is_permanent' => 1);
