function compute_user_sync_digest(DB $db, $uid) {
    $uid = (int)$uid;
    if ($uid <= 0) return '';
    try {
        $uRow = $db->one("SELECT username, name, bio, avatar, lang, theme, cal, flags, role, status, show_admin_badge, pubkey, key_backup, totp_secret, lock_pass_hash, delete_at, inactive_delete_days FROM users WHERE id = ?", array($uid));
        if (!$uRow) return '';
        $chatCnt = (int)$db->val("SELECT COUNT(*) FROM members WHERE user_id = ? AND role != 'pending'", array($uid));
        $maxPin = (int)$db->val("SELECT COALESCE(MAX(pinned_at), 0) FROM members WHERE user_id = ?", array($uid));
        $muteSum = (int)$db->val("SELECT COALESCE(SUM(muted), 0) FROM members WHERE user_id = ?", array($uid));
        $maxRead = (int)$db->val("SELECT COALESCE(MAX(last_read_id), 0) FROM members WHERE user_id = ?", array($uid));
        $blkCnt = (int)$db->val("SELECT COUNT(*) FROM blocks WHERE user_id = ?", array($uid));
        $sessCnt = (int)$db->val("SELECT COUNT(*) FROM sessions WHERE user_id = ?", array($uid));
        $raw = implode('|', array(
            (string)$uRow['username'], (string)$uRow['name'],
            substr(md5((string)$uRow['bio'] . '|' . (string)$uRow['avatar']), 0, 8),
            (string)$uRow['lang'], (string)$uRow['theme'], (string)$uRow['cal'],
            substr(md5((string)$uRow['flags']), 0, 12),
            (string)$uRow['role'], (string)$uRow['status'], (string)$uRow['show_admin_badge'],
            substr(md5((string)$uRow['pubkey'] . '|' . (string)$uRow['key_backup']), 0, 10),
            !empty($uRow['totp_secret']) ? '1' : '0', !empty($uRow['lock_pass_hash']) ? '1' : '0',
            (string)$uRow['delete_at'], (string)$uRow['inactive_delete_days'],
            $chatCnt, $maxPin, $muteSum, $maxRead, $blkCnt, $sessCnt
        ));
        return substr(sha1($raw), 0, 16);
    } catch (Exception $e) { return ''; }
}

function ensure_saved_chat(DB $db, $uid) {
    $uid = (int)$uid;
    if ($uid <= 0) return 0;
    $existingId = (int)$db->val(
        "SELECT c.id FROM chats c
         JOIN members m ON m.chat_id = c.id AND m.user_id = ?
         WHERE c.type = 'saved' AND c.owner_id = ? LIMIT 1",
        array($uid, $uid)
    );
    if ($existingId > 0) return $existingId;

    $now = time();
    $db->exec(
        "INSERT INTO chats (type, handle, title, description, avatar, visibility, owner_id, is_default, all_muted, history, default_ttl, ttl_mode, slow_mode, max_members, perms_json, status, created_at)
         VALUES ('saved', NULL, 'Saved Messages', '', '', 'private', ?, 0, 0, 'all', 0, 'expire_after_send', 0, 1, ?, 'active', ?)",
        array($uid, json_encode(array('send_text' => 1, 'send_media' => 1, 'send_voice' => 1, 'reactions_enabled' => 1)), $now)
    );
    $cid = $db->lastId();
    $db->insertIgnore('members', array(
        'chat_id'       => $cid,
        'user_id'       => $uid,
        'role'          => 'owner',
        'perms_json'    => '{}',
        'joined_msg_id' => 0,
        'last_read_id'  => 0,
        'muted'         => 0,
        'pinned_at'     => 0,
        'last_msg_at'   => 0,
        'joined_at'     => $now
    ));
    return $cid;
}

function ensure_system_chat(DB $db, $uid) {
    $uid = (int)$uid;
    if ($uid <= 0) return 0;
    $existingId = (int)$db->val(
        "SELECT c.id FROM chats c
         JOIN members m ON m.chat_id = c.id AND m.user_id = ?
         WHERE c.type = 'system' AND c.owner_id = ? LIMIT 1",
        array($uid, $uid)
    );
    if ($existingId > 0) return $existingId;

    $now = time();
    $db->exec(
        "INSERT INTO chats (type, handle, title, description, avatar, visibility, owner_id, is_default, all_muted, history, default_ttl, ttl_mode, slow_mode, max_members, perms_json, status, created_at)
         VALUES ('system', NULL, 'اعلان‌های پیام‌رسان', '', '', 'private', ?, 0, 1, 'all', 0, 'expire_after_send', 0, 1, ?, 'active', ?)",
        array($uid, json_encode(array('send_text' => 0, 'send_media' => 0, 'send_voice' => 0, 'reactions_enabled' => 0, 'allow_copy_msg' => 1, 'allow_select_text' => 1, 'allow_forward_msg' => 0)), $now)
    );
    $cid = $db->lastId();
    $db->insertIgnore('members', array(
        'chat_id'       => $cid,
        'user_id'       => $uid,
        'role'          => 'member',
        'perms_json'    => '{}',
        'joined_msg_id' => 0,
        'last_read_id'  => 0,
        'muted'         => 0,
        'pinned_at'     => 0,
        'last_msg_at'   => 0,
        'joined_at'     => $now
    ));
    return $cid;
}

function post_system_chat_message(DB $db, $uid, $body, $pin = false, $explicitCreatedAt = null) {
    $uid = (int)$uid;
    if ($uid <= 0) return 0;
    $cid = ensure_system_chat($db, $uid);
    if ($cid <= 0) return 0;
    $nowApp = ($explicitCreatedAt !== null) ? (int)$explicitCreatedAt : app_now($db);
    $pinInt = $pin ? 1 : 0;
    $pinAt = $pin ? max(time(), $nowApp) : 0;
    if ($pin) {
        $db->exec("UPDATE messages SET pinned = 0, pinned_at = 0 WHERE chat_id = ? AND pinned = 1", array($cid));
    }
    $db->exec(
        "INSERT INTO messages (chat_id, user_id, kind, body, pinned, pinned_at, created_at) VALUES (?, 0, 'text', ?, ?, ?, ?)",
        array($cid, (string)$body, $pinInt, $pinAt, $nowApp)
    );
    return $db->lastId();
}

function autonomous_mode_system_notice_text() {
    return '🏛️ [M3_SYS_AUTONOMOUS] مدیریت کل سامانه به‌صورت دائمی واگذار شد؛ پیام‌رسان از این پس بدون سوپرادمین و با تنظیمات فعلی به‌صورت خودگردان فعالیت می‌کند. / Super-Admin role has been permanently relinquished; the messenger now operates autonomously.';
}

function record_user_login_system_notice(DB $db, $uid, $isNewRegistration = false) {
    $uid = (int)$uid;
    if ($uid <= 0) return;
    $ts = app_now($db);
    $isoUtc = gmdate('Y-m-d H:i:s', $ts) . ' UTC';
    if ($isNewRegistration) {
        $regMsg = "🎉 [M3_SYS_REGISTER:{$ts}] حساب کاربری شما با موفقیت ایجاد شد. به پیام‌رسان خوش آمدید!\n🕒 زمان ایجاد حساب: {$isoUtc}";
        post_system_chat_message($db, $uid, $regMsg, false, $ts);
    } else {
        $loginMsg = "🔐 [M3_SYS_LOGIN:{$ts}] ورود جدید به حساب کاربری ثبت شد.\n🕒 زمان ورود: {$isoUtc}";
        post_system_chat_message($db, $uid, $loginMsg, false, $ts);
    }
    if ($isNewRegistration && (int)Settings::get($db, 'autonomous_mode', 0) === 1) {
        post_system_chat_message($db, $uid, autonomous_mode_system_notice_text(), true, $ts + 1);
    }
}

/* ---------------------------------------------------------------------------
   Message view counters (groups & channels) and last-message preview control.

   Both features are layered identically:
     1. super-admin / founder switch - global, or scoped to groups, to channels,
        or to one specific chat;
     2. chat-admin switch - stored on the chat itself;
     3. for the preview only, a personal switch every member may set for
        themselves on any chat they belong to.
   A layer can only take something away, never grant it back, so the strictest
   setting always wins.
--------------------------------------------------------------------------- */
function get_global_off_chat_ids(DB $db, $key) {
    $raw = Settings::get($db, $key, array());
    $ids = array();
    if (is_array($raw)) {
        foreach ($raw as $v) { $iv = (int)$v; if ($iv > 0) $ids[$iv] = true; }
    } elseif (is_string($raw) && trim($raw) !== '') {
        foreach (explode(',', $raw) as $v) { $iv = (int)trim($v); if ($iv > 0) $ids[$iv] = true; }
    }
    return $ids;
}

function resolve_message_views_enabled(DB $db, $chat) {
    if (!$chat || !isset($chat['type'])) return false;
    $type = (string)$chat['type'];
    // Counters are a property of the chat the message now sits in, never of the
    // one it came from. A message forwarded out of a private chat shows nothing
    // there; forwarded onward into a group or channel it is counted from zero
    // like any freshly posted message, because the forward inserts a new row and
    // messages.views is never copied across.
    if ($type !== 'group' && $type !== 'channel') return false;
    if (!(int)Settings::get($db, 'msg_views_enabled', 1)) return false;
    if ($type === 'group'   && !(int)Settings::get($db, 'msg_views_enabled_groups', 1)) return false;
    if ($type === 'channel' && !(int)Settings::get($db, 'msg_views_enabled_channels', 1)) return false;
    $off = get_global_off_chat_ids($db, 'msg_views_off_chats');
    if (isset($off[(int)$chat['id']])) return false;
    $cp = parse_json_col(isset($chat['perms_json']) ? $chat['perms_json'] : '', array());
    if (array_key_exists('msg_views', $cp) && !(int)$cp['msg_views']) return false;
    return true;
}

function resolve_chat_preview_enabled(DB $db, $chat, $memberPermsJson = null) {
    if (!$chat || !isset($chat['type'])) return true;
    $type = (string)$chat['type'];
    if (!(int)Settings::get($db, 'chat_preview_enabled', 1)) return false;
    if ($type === 'group'   && !(int)Settings::get($db, 'chat_preview_enabled_groups', 1)) return false;
    if ($type === 'channel' && !(int)Settings::get($db, 'chat_preview_enabled_channels', 1)) return false;
    $off = get_global_off_chat_ids($db, 'chat_preview_off_chats');
    if (isset($off[(int)$chat['id']])) return false;
    $cp = parse_json_col(isset($chat['perms_json']) ? $chat['perms_json'] : '', array());
    if (array_key_exists('chat_preview', $cp) && !(int)$cp['chat_preview']) return false;
    if ($memberPermsJson !== null) {
        $mp = parse_json_col($memberPermsJson, array());
        if (array_key_exists('chat_preview', $mp) && !(int)$mp['chat_preview']) return false;
    }
    return true;
}

/* How far the other side has read, as a single message id watermark.
   This used to come straight from members.receipt_read_id, but that column only
   ever advances inside mark_read and is suppressed entirely in ghost mode and
   when read receipts are switched off - so in groups and channels it sat at 0 for
   nearly every member and an outgoing message never left the single-tick state.
   message_reads is the real per-message record and is written for groups and
   channels too, so the watermark is derived from it here. The legacy column is
   still merged in and whichever is higher wins, so a direct chat whose receipts
   did advance can never appear to go backwards. */
function peer_read_watermarks(DB $db, $uid, $chatIds) {
    $map = array();
    $ids = array();
    foreach ((array)$chatIds as $c) { $iv = (int)$c; if ($iv > 0) $ids[$iv] = true; }
    $ids = array_keys($ids);
    if (!$ids || (int)$uid <= 0) return $map;
    $ph = implode(',', array_fill(0, count($ids), '?'));
    $args = array_merge(array((int)$uid), $ids);
    // Departed and not-yet-approved members no longer count as readers.
    $rows = $db->all(
        "SELECT mr.chat_id AS cid, MAX(mr.message_id) AS wm
           FROM message_reads mr
           JOIN members m ON m.chat_id = mr.chat_id AND m.user_id = mr.user_id
          WHERE mr.user_id != ? AND mr.chat_id IN ($ph)
            AND m.role != 'pending' AND COALESCE(m.left_at, 0) = 0
          GROUP BY mr.chat_id",
        $args
    );
    foreach ($rows as $r) $map[(int)$r['cid']] = (int)$r['wm'];
    $rows2 = $db->all(
        "SELECT m.chat_id AS cid, MAX(m.receipt_read_id) AS wm
           FROM members m
          WHERE m.user_id != ? AND m.chat_id IN ($ph)
            AND m.role != 'pending' AND COALESCE(m.left_at, 0) = 0
          GROUP BY m.chat_id",
        $args
    );
    foreach ($rows2 as $r) {
        $c = (int)$r['cid'];
        $map[$c] = max(isset($map[$c]) ? $map[$c] : 0, (int)$r['wm']);
    }
    return $map;
}

function peer_read_watermark(DB $db, $chat, $uid, $map = null) {
    $cid = (int)$chat['id'];
    if ($chat['type'] === 'saved') return 2147483647;
    if (is_array($map)) return isset($map[$cid]) ? (int)$map[$cid] : 0;
    $single = peer_read_watermarks($db, $uid, array($cid));
    return isset($single[$cid]) ? (int)$single[$cid] : 0;
}

function build_single_chat_descriptor(DB $db, $r, $user, $isGhost = false, $peerReadMap = null) {
    $uid = (int)$user['id'];
    $isSuper = ($user['role'] === 'superadmin');
    $now = time();
    $cid = (int)$r['id'];
    $minMsgId = (!$isSuper && $r['history'] === 'from_join') ? (int)$r['joined_msg_id'] : 0;
    // Per-member cutoff: messages older than this member's re-open point (set when
    // they removed a 1:1 chat from their own list) must not leak into the list
    // preview or the unread badge either.
    if (!$isSuper && !empty($r['rejoin_msg_id'])) {
        $minMsgId = max($minMsgId, (int)$r['rejoin_msg_id']);
    }
    $myLastRead = isset($r['last_read_id']) ? (int)$r['last_read_id'] : 0;

    $peerObj = null;
    $peerLastRead = 0;

    if ($r['type'] === 'dm' || $r['type'] === 'secret') {
        $peerMember = $db->one(
            "SELECT m.user_id, m.last_read_id, m.receipt_read_id, u.*
             FROM members m
             JOIN users u ON u.id = m.user_id
             WHERE m.chat_id = ? AND m.user_id != ? LIMIT 1",
            array($cid, $uid)
        );
        if ($peerMember) {
            $peerObj = format_user_public($peerMember, $isSuper);
            $peerLastRead = max((int)$peerMember['receipt_read_id'], peer_read_watermark($db, $r, $uid, $peerReadMap));
        }
    } elseif ($r['type'] === 'saved') {
        $peerLastRead = 2147483647;
    } else {
        // Only readers who are really in the chat count. A pending request or
        // somebody who already left used to be able to mark a group or channel
        // message as "seen" (or leave it stuck on a stale, too-low value).
        $peerLastRead = peer_read_watermark($db, $r, $uid, $peerReadMap);
    }

    $memberCount = (int)$db->val("SELECT COUNT(*) FROM members WHERE chat_id = ? AND role != 'pending'", array($cid));

    // Shadow-ban context for this chat. The sidebar must respect it too, otherwise
    // a banned member would read other people's new messages straight off the
    // chat-list preview even though the conversation itself withholds them.
    $sbRank = $isSuper ? 3
        : ((!empty($r['owner_id']) && (int)$r['owner_id'] === $uid) ? 2
        : ((isset($r['my_role']) && $r['my_role'] === 'owner') ? 2
        : ((isset($r['my_role']) && $r['my_role'] === 'admin') ? 1 : 0)));
    $sbMap = m3_chat_shadow_map($db, $cid);
    $sbMyAt = isset($sbMap[$uid]) ? (int)$sbMap[$uid] : 0;
    $sbActive = !empty($sbMap);

    $unreadCount = 0;
    if (!$isGhost) {
        $unreadRows = $db->all(
            "SELECT id, user_id, created_at, hidden_for FROM messages
             WHERE chat_id = ? AND id > ? AND id >= ? AND user_id != ?
               AND (visible_only_to IS NULL OR visible_only_to = ?)
               AND deleted_at IS NULL AND (expires_at IS NULL OR expires_at > ?)",
            array($cid, $myLastRead, $minMsgId, $uid, $uid, $now)
        );
        foreach ($unreadRows as $ur) {
            if (is_hidden_for_user($ur['hidden_for'], $uid)) continue;
            if ($sbActive && m3_shadow_hides_row($ur, $uid, $sbRank, $sbMap, $sbMyAt)) continue;
            $unreadCount++;
        }
    }

    $lastCandidates = $db->all(
        "SELECT id, user_id, kind, body, cipher, created_at, deleted_at, hidden_for
         FROM messages
         WHERE chat_id = ? AND id >= ? AND (visible_only_to IS NULL OR visible_only_to = ?)
           AND deleted_at IS NULL AND (expires_at IS NULL OR expires_at > ?)
         ORDER BY id DESC LIMIT 15",
        array($cid, $minMsgId, $uid, $now)
    );
    $lastMsg = null;
    foreach ($lastCandidates as $lc) {
        if (is_hidden_for_user($lc['hidden_for'], $uid)) continue;
        if ($sbActive && m3_shadow_hides_row($lc, $uid, $sbRank, $sbMap, $sbMyAt)) continue;
        $lastMsg = $lc;
        break;
    }
    $fmtMsgShortBody = function($mKind, $mBody, $maxL = 90) use ($r) {
        if ($r['type'] === 'secret') return '🔒 پیام رمزنگاری‌شده (E2EE)';
        if ($mKind === 'location') {
            $lj = json_decode((string)$mBody, true);
            $lbl = (is_array($lj) && !empty($lj['label'])) ? (' — ' . $lj['label']) : '';
            return '📍 موقعیت مکانی' . u_substr($lbl, 0, 50);
        }
        if ($mKind === 'video_note') {
            return trim((string)$mBody) !== '' ? ('🎥 ' . u_substr((string)$mBody, 0, $maxL)) : '🎥 پیام ویدیویی فوری';
        }
        if ($mKind === 'call_log') {
            $cj = json_decode((string)$mBody, true);
            $isVid = (is_array($cj) && isset($cj['call_type']) && $cj['call_type'] === 'video');
            $stC = (is_array($cj) && isset($cj['status'])) ? (string)$cj['status'] : 'ended';
            $stFa = ($stC === 'missed') ? 'بی‌پاسخ' : (($stC === 'declined') ? 'رد شده' : (($stC === 'busy') ? 'خط مشغول' : (($stC === 'ringing') ? 'در حال زنگ...' : (($stC === 'active') ? 'در جریان' : 'پاسخ داده شد'))));
            return ($isVid ? '🎥 تماس تصویری' : '📞 تماس صوتی') . ' (' . $stFa . ')';
        }
        return u_substr((string)$mBody, 0, $maxL);
    };
    $lastMsgPreview = null;
    if ($lastMsg) {
        $lid = (int)$lastMsg['id'];
        $lastMsgPreview = array(
            'id'          => $lid,
            'user_id'     => (int)$lastMsg['user_id'],
            'kind'        => $lastMsg['kind'],
            'body'        => $fmtMsgShortBody($lastMsg['kind'], $lastMsg['body'], 90),
            'created_at'  => (int)$lastMsg['created_at'],
            'tick_status' => ($lid <= $peerLastRead) ? 'seen' : 'sent'
        );
    }

    $pinnedMsg = null;
    $pinnedScope = 'both';
    $hasUnderneathPin = 0;
    $myPermsEarly = parse_json_col(isset($r['my_perms']) ? $r['my_perms'] : '{}', array());
    $myPersonalPinId = isset($myPermsEarly['personal_pin_msg_id']) ? (int)$myPermsEarly['personal_pin_msg_id'] : (isset($r['pinned_msg_id']) ? (int)$r['pinned_msg_id'] : 0);
    if ($myPersonalPinId <= 0 && isset($r['pinned_msg_id']) && (int)$r['pinned_msg_id'] > 0) {
        $myPersonalPinId = (int)$r['pinned_msg_id'];
    }
    $myPersonalPinAt = isset($myPermsEarly['personal_pin_at']) ? (int)$myPermsEarly['personal_pin_at'] : 0;
    $dismissedSharedId = isset($myPermsEarly['dismissed_shared_pin_id']) ? (int)$myPermsEarly['dismissed_shared_pin_id'] : 0;
    $dismissedSharedAt = isset($myPermsEarly['dismissed_shared_pin_at']) ? (int)$myPermsEarly['dismissed_shared_pin_at'] : 0;

    $pmRow = null;
    if ($myPersonalPinId > 0) {
        $candPm = $db->one(
            "SELECT id, user_id, kind, body, created_at, pinned_at, hidden_for FROM messages
             WHERE id = ? AND chat_id = ? AND id >= ? AND (visible_only_to IS NULL OR visible_only_to = ?)
               AND deleted_at IS NULL AND (expires_at IS NULL OR expires_at > ?)",
            array($myPersonalPinId, $cid, $minMsgId, $uid, $now)
        );
        if ($candPm
            && !is_hidden_for_user($candPm['hidden_for'], $uid)
            && !($sbActive && m3_shadow_hides_row($candPm, $uid, $sbRank, $sbMap, $sbMyAt))) {
            $pmRow = $candPm;
            if ($myPersonalPinAt <= 0) {
                $myPersonalPinAt = max(1, (int)$candPm['created_at']);
            }
        }
    }

    $shRow = null;
    $shPinAt = 0;
    $pinnedCandidates = $db->all(
        "SELECT id, user_id, kind, body, created_at, pinned_at, hidden_for FROM messages
         WHERE chat_id = ? AND pinned = 1 AND id >= ? AND (visible_only_to IS NULL OR visible_only_to = ?)
           AND deleted_at IS NULL AND (expires_at IS NULL OR expires_at > ?)
         ORDER BY pinned_at DESC, id DESC LIMIT 10",
        array($cid, $minMsgId, $uid, $now)
    );
    foreach ($pinnedCandidates as $pc) {
        if (is_hidden_for_user($pc['hidden_for'], $uid)) continue;
        if ($sbActive && m3_shadow_hides_row($pc, $uid, $sbRank, $sbMap, $sbMyAt)) continue;
        $candShAt = max((int)$pc['pinned_at'], (int)$pc['created_at']);
        if ($dismissedSharedId === (int)$pc['id'] && $dismissedSharedAt >= $candShAt) {
            continue;
        }
        $shRow = $pc;
        $shPinAt = $candShAt;
        break;
    }

    if ($pmRow && $shRow) {
        if ((int)$pmRow['id'] === (int)$shRow['id']) {
            $pinnedMsg = $pmRow;
            $pinnedScope = ($myPersonalPinAt >= $shPinAt) ? 'me' : 'both';
            $hasUnderneathPin = 1;
        } elseif ($myPersonalPinAt >= $shPinAt) {
            $pinnedMsg = $pmRow;
            $pinnedScope = 'me';
            $hasUnderneathPin = 1;
        } else {
            $pinnedMsg = $shRow;
            $pinnedScope = 'both';
            $hasUnderneathPin = 1;
        }
    } elseif ($pmRow) {
        $pinnedMsg = $pmRow;
        $pinnedScope = 'me';
    } elseif ($shRow) {
        $pinnedMsg = $shRow;
        $pinnedScope = 'both';
    }

    $canLeave = !$isGhost && ($r['type'] === 'group' || $r['type'] === 'channel') && !((int)$r['is_default'] === 1 && $r['type'] === 'channel' && !$isSuper);
    $parsedChatPerms = parse_json_col($r['perms_json'], array(
        'send_text' => 1, 'send_media' => 1, 'send_voice' => 1, 'invite' => 1, 'pin' => 0,
        'join_approval' => 0, 'reactions_enabled' => 1,
        'allow_copy_msg' => 1, 'allow_select_text' => 1, 'allow_file_download' => 1, 'allow_forward_msg' => 1,
        'show_owner_transfer_msg' => 1,
        'idle_mode' => 'off', 'idle_start' => '23:00', 'idle_end' => '07:00', 'idle_tz_offset' => 0
    ));
    $reactionsEnabled = isset($parsedChatPerms['reactions_enabled']) ? ((int)$parsedChatPerms['reactions_enabled'] ? 1 : 0) : 1;
    $chatIdleState = ($r['type'] === 'group' || $r['type'] === 'channel')
        ? evaluate_idle_window($parsedChatPerms['idle_mode'], $parsedChatPerms['idle_start'], $parsedChatPerms['idle_end'], $parsedChatPerms['idle_tz_offset'], app_now($db))
        : array('mode' => 'off', 'active' => false, 'start' => '23:00', 'end' => '07:00', 'tz_offset' => 0);
    $globalAllowFwd = ((int)Settings::get($db, 'allow_forward_msg', 1) !== 0);
    $chatAllowFwd = !isset($parsedChatPerms['allow_forward_msg']) || ((int)$parsedChatPerms['allow_forward_msg'] !== 0);
    $canForwardFrom = ($r['type'] !== 'secret') && ($isSuper || ($globalAllowFwd && $chatAllowFwd && !(($r['type'] === 'group' || $r['type'] === 'channel') && $r['visibility'] === 'private')));
    $pinnedAt = isset($r['pinned_at']) ? (int)$r['pinned_at'] : 0;
    $myPermsParsed = parse_json_col(isset($r['my_perms']) ? $r['my_perms'] : '{}', array());
    if ($isSuper) {
        $myPermsParsed = array_merge($myPermsParsed, array(
            'post_messages'   => 1,
            'edit_info'       => 1,
            'delete_messages' => 1,
            'ban_users'       => 1,
            'pin_messages'    => 1,
            'invite_users'    => 1,
            'manage_admins'   => 1
        ));
    }
    $secretStatus = ($r['type'] === 'secret' && isset($parsedChatPerms['secret_status'])) ? (string)$parsedChatPerms['secret_status'] : 'active';
    $secretInitId = ($r['type'] === 'secret' && isset($parsedChatPerms['secret_initiator_id'])) ? (int)$parsedChatPerms['secret_initiator_id'] : 0;
    $synthMemberRow = $isGhost ? null : array(
        'role'       => isset($r['my_role']) ? $r['my_role'] : 'member',
        'perms_json' => isset($r['my_perms']) ? $r['my_perms'] : '{}'
    );
    $contentPolResolved = get_effective_content_restrictions($db, $r, $synthMemberRow, $user);
    $callPolResolved    = resolve_effective_call_policy($db, $r, $synthMemberRow, $user);
    $activeCallSummary  = ($r['type'] === 'saved' || $r['type'] === 'system') ? null : get_active_call_summary_for_chat($db, $cid, $uid);
    $msgViewersMode     = normalize_msg_viewers_value(isset($parsedChatPerms['msg_viewers_mode']) ? $parsedChatPerms['msg_viewers_mode'] : 'default', 'chat');
    $superMsgViewOvr    = normalize_msg_viewers_value(isset($parsedChatPerms['super_msg_viewers_override']) ? $parsedChatPerms['super_msg_viewers_override'] : 'inherit', 'super_chat');
    $canViewReaders     = can_user_view_message_readers($db, $r, $synthMemberRow, $user) ? 1 : 0;
    $capResolved        = resolve_chat_member_capacity($db, $r);

    return array(
        'id'                  => $cid,
        'type'                => $r['type'],
        'handle'              => $r['handle'],
        'title'               => ($peerObj && ($r['type'] === 'dm' || $r['type'] === 'secret')) ? $peerObj['name'] : $r['title'],
        'description'         => $r['description'],
        'avatar'              => ($peerObj && ($r['type'] === 'dm' || $r['type'] === 'secret')) ? $peerObj['avatar'] : $r['avatar'],
        'visibility'          => $r['visibility'],
        'owner_id'            => (int)$r['owner_id'],
        'is_default'          => (int)$r['is_default'],
        'all_muted'           => (int)$r['all_muted'],
        'history'             => $r['history'],
        'history_vis'         => $r['history'],
        'default_ttl'         => (int)$r['default_ttl'],
        'ttl_mode'            => $r['ttl_mode'],
        'auto_delete_sec'     => isset($r['auto_delete_sec']) ? (int)$r['auto_delete_sec'] : 0,
        'my_auto_delete_sec'  => isset($r['my_auto_delete_sec']) ? (int)$r['my_auto_delete_sec'] : 0,
        'show_owner_transfer_msg' => isset($parsedChatPerms['show_owner_transfer_msg']) ? ((int)$parsedChatPerms['show_owner_transfer_msg'] ? 1 : 0) : (isset($parsedChatPerms['show_admin_transfer_msg']) ? ((int)$parsedChatPerms['show_admin_transfer_msg'] ? 1 : 0) : 1),
        'show_admin_transfer_msg' => isset($parsedChatPerms['show_owner_transfer_msg']) ? ((int)$parsedChatPerms['show_owner_transfer_msg'] ? 1 : 0) : (isset($parsedChatPerms['show_admin_transfer_msg']) ? ((int)$parsedChatPerms['show_admin_transfer_msg'] ? 1 : 0) : 1),
        'admins_only'             => !empty($parsedChatPerms['admins_only']) ? 1 : 0,
        'join_approval'           => !empty($parsedChatPerms['join_approval']) ? 1 : 0,
        'hide_members'            => !empty($parsedChatPerms['hide_members']) ? 1 : 0,
        'member_invite'           => (!isset($parsedChatPerms['invite']) || (int)$parsedChatPerms['invite'] !== 0) ? 1 : 0,
        'member_pin'              => !empty($parsedChatPerms['pin']) ? 1 : 0,
        'msg_viewers_mode'        => $msgViewersMode,
        'super_msg_viewers_override' => $superMsgViewOvr,
        'can_view_readers'        => $canViewReaders,
        'show_typing'             => ($r['type'] === 'group') ? ((!isset($parsedChatPerms['show_typing']) || (int)$parsedChatPerms['show_typing'] !== 0) ? 1 : 0) : 0,
        'my_typing_mode'          => $isGhost ? 'inherit' : normalize_typing_override_val(isset($myPermsParsed['my_typing_mode']) ? $myPermsParsed['my_typing_mode'] : 'inherit', 'personal_chat'),
        'super_typing_override'   => normalize_typing_override_val(isset($parsedChatPerms['super_typing_override']) ? $parsedChatPerms['super_typing_override'] : 'inherit', 'chat'),
        'typing_display_enabled'  => is_chat_typing_display_enabled($db, $r) ? 1 : 0,
        'hide_edit_badge'         => (($r['type'] === 'group' || $r['type'] === 'channel') && !empty($parsedChatPerms['hide_edit_badge'])) ? 1 : 0,
        'slow_mode'           => (int)$r['slow_mode'],
        'max_members'         => (int)$r['max_members'],
        'effective_max_members' => (int)$capResolved['effective_max'],
        'super_max_members'   => (int)$capResolved['super_override'],
        'superadmin_ceiling'  => (int)$capResolved['super_ceiling'],
        'perms'               => $parsedChatPerms,
        'reactions_enabled'   => $reactionsEnabled,
        'idle_mode'           => $chatIdleState['mode'],
        'idle_start'          => $chatIdleState['start'],
        'idle_end'            => $chatIdleState['end'],
        'idle_tz_offset'      => $chatIdleState['tz_offset'],
        'is_idle_active'      => $chatIdleState['active'] ? 1 : 0,
        'status'              => $r['status'],
        'is_ghost'            => $isGhost ? 1 : 0,
        'is_member'           => $isGhost ? 0 : 1,
        'my_role'             => $isGhost ? 'ghost' : (isset($r['my_role']) ? $r['my_role'] : 'member'),
        'my_perms'            => $myPermsParsed,
        'my_mute_send'        => (!$isSuper && !empty($myPermsParsed['mute_send'])) ? 1 : 0,
        'my_mute_react'       => (!$isSuper && !empty($myPermsParsed['mute_react'])) ? 1 : 0,
        'secret_status'       => $secretStatus,
        'secret_initiator_id' => $secretInitId,
        'joined_msg_id'       => $minMsgId,
        'last_read_id'        => $myLastRead,
        'peer_last_read_id'   => $peerLastRead,
        'muted'               => isset($r['muted']) ? (int)$r['muted'] : 0,
        'pinned_at'           => $pinnedAt,
        'is_pinned'           => ($pinnedAt > 0) ? 1 : 0,
        'can_leave'           => $canLeave,
        'read_only'           => ($r['type'] === 'system') ? 1 : 0,
        'can_forward'         => ($r['type'] === 'system') ? false : $canForwardFrom,
        'member_count'        => $memberCount,
        'unread_count'        => $unreadCount,
        'peer'                => $peerObj,
        'active_call'         => $activeCallSummary,
        'call_policy'         => $callPolResolved,
        'content_restrictions'=> $contentPolResolved,
        'last_message'        => $lastMsgPreview,
        'preview_hidden'      => resolve_chat_preview_enabled($db, $r, isset($r['my_perms']) ? $r['my_perms'] : null) ? 0 : 1,
        'msg_views_enabled'   => resolve_message_views_enabled($db, $r) ? 1 : 0,
        'pinned_message'      => $pinnedMsg ? array(
            'id'                 => (int)$pinnedMsg['id'],
            'scope'              => $pinnedScope,
            'has_underneath_pin' => $hasUnderneathPin,
            'has_personal_pin'   => ($pmRow ? 1 : 0),
            'has_shared_pin'     => ($shRow ? 1 : 0),
            'kind'               => $pinnedMsg['kind'],
            'body'               => $fmtMsgShortBody($pinnedMsg['kind'], $pinnedMsg['body'], 120)
        ) : null
    );
}

function fetch_user_chats(DB $db, $user) {
    $uid = (int)$user['id'];
    $isSuper = ($user['role'] === 'superadmin');
    $now = time();

    ensure_saved_chat($db, $uid);
    ensure_system_chat($db, $uid);

    if ($isSuper) {
        $rows = $db->all(
            "SELECT c.*, m.role AS my_role, m.perms_json AS my_perms, m.joined_msg_id, m.rejoin_msg_id, m.last_read_id, m.receipt_read_id, m.pinned_msg_id, m.auto_delete_sec AS my_auto_delete_sec, m.muted, m.pinned_at, m.banned_until, m.restricted_until
             FROM chats c
             JOIN members m ON m.chat_id = c.id AND m.user_id = ?
             WHERE COALESCE(m.left_at, 0) = 0
             ORDER BY c.is_default DESC, c.id DESC",
            array($uid)
        );
    } else {
        $rows = $db->all(
            "SELECT c.*, m.role AS my_role, m.perms_json AS my_perms, m.joined_msg_id, m.rejoin_msg_id, m.last_read_id, m.receipt_read_id, m.pinned_msg_id, m.auto_delete_sec AS my_auto_delete_sec, m.muted, m.pinned_at, m.banned_until, m.restricted_until
             FROM chats c
             JOIN members m ON m.chat_id = c.id AND m.user_id = ?
             WHERE m.role != 'pending' AND (m.banned_until IS NULL OR m.banned_until <= ?)
               AND COALESCE(m.left_at, 0) = 0
             ORDER BY c.is_default DESC, c.id DESC",
            array($uid, $now)
        );
    }

    // One pair of grouped queries for the whole list instead of two per chat.
    $peerReadMap = array();
    foreach ($rows as $r) $peerReadMap[(int)$r['id']] = 0;
    if ($peerReadMap) {
        $peerReadMap = peer_read_watermarks($db, $uid, array_keys($peerReadMap));
    }

    $out = array();
    foreach ($rows as $r) {
        $out[] = build_single_chat_descriptor($db, $r, $user, false, $peerReadMap);
    }

    usort($out, function($a, $b) {
        $aSaved = ($a['type'] === 'saved') ? 1 : 0;
        $bSaved = ($b['type'] === 'saved') ? 1 : 0;
        if ($aSaved !== $bSaved) return $bSaved - $aSaved;

        if ($a['is_pinned'] !== $b['is_pinned']) {
            return $b['is_pinned'] - $a['is_pinned'];
        }
        if ($a['is_pinned'] === 1 && $a['pinned_at'] !== $b['pinned_at']) {
            return $b['pinned_at'] - $a['pinned_at'];
        }

        $ta = $a['last_message'] ? $a['last_message']['created_at'] : 0;
        $tb = $b['last_message'] ? $b['last_message']['created_at'] : 0;
        if ($ta !== $tb) return $tb - $ta;
        return $b['id'] - $a['id'];
    });

    return $out;
}

function hydrate_message_rows(DB $db, $chat, $rows, $uid, $minMsgId, $peerLastRead) {
    $viewsOn = resolve_message_views_enabled($db, $chat);
    $cid = (int)$chat['id'];
    $out = array();
    $chatMemberRoleMap = array();
    if ($chat['type'] === 'group' || $chat['type'] === 'channel') {
        $cmRows = $db->all("SELECT user_id, role FROM members WHERE chat_id = ? AND role IN ('owner', 'admin')", array($cid));
        foreach ($cmRows as $cmr) {
            $chatMemberRoleMap[(int)$cmr['user_id']] = (string)$cmr['role'];
        }
        if (!empty($chat['owner_id'])) {
            $chatMemberRoleMap[(int)$chat['owner_id']] = 'owner';
        }
    }
    $viewerUserRow = ($uid > 0) ? $db->one("SELECT id, role, flags FROM users WHERE id = ?", array((int)$uid)) : null;
    // Shadow-ban: fetch_chat_messages already filters its own SQL, but every other
    // caller of this hydrator (search, previews) has to be covered too, so the
    // verdict is applied here as well. Both lookups are cached per request.
    $shadowView = null;
    if ($uid > 0) {
        $shadowRank = ($viewerUserRow && $viewerUserRow['role'] === 'superadmin') ? 3
            : ((!empty($chat['owner_id']) && (int)$chat['owner_id'] === (int)$uid) ? 2
            : (($viewerChatRole === 'owner') ? 2 : (($viewerChatRole === 'admin') ? 1 : 0)));
        $shadowMap  = m3_chat_shadow_map($db, (int)$chat['id']);
        if (!empty($shadowMap)) {
            $shadowView = array('rank' => $shadowRank, 'map' => $shadowMap,
                                'my_at' => isset($shadowMap[(int)$uid]) ? (int)$shadowMap[(int)$uid] : 0);
        }
    }
    $viewerChatRole = ($uid > 0 && isset($chatMemberRoleMap[(int)$uid])) ? $chatMemberRoleMap[(int)$uid] : '';
    $editedAuthorIds = array();
    foreach ($rows as $preR) {
        if (!empty($preR['edited_at']) && !empty($preR['user_id'])) {
            $editedAuthorIds[(int)$preR['user_id']] = (int)$preR['user_id'];
        }
    }
    $authorFlagsByUid = array();
    if (!empty($editedAuthorIds)) {
        $aph = implode(',', array_fill(0, count($editedAuthorIds), '?'));
        $aRows = $db->all("SELECT id, flags FROM users WHERE id IN ($aph)", array_values($editedAuthorIds));
        foreach ($aRows as $ar) {
            $authorFlagsByUid[(int)$ar['id']] = get_user_flags($ar);
        }
    }
    foreach ($rows as $r) {
        if ($r['visible_only_to'] !== null && (int)$r['visible_only_to'] !== $uid) {
            continue;
        }
        if (!empty($r['hidden_for'])) {
            $hf = json_decode((string)$r['hidden_for'], true);
            if (is_array($hf) && in_array($uid, $hf, true)) {
                continue;
            }
        }
        if ($shadowView !== null
            && m3_shadow_hides_row($r, $uid, $shadowView['rank'], $shadowView['map'], $shadowView['my_at'])) {
            continue;
        }
        $mid = (int)$r['id'];

        $replyPreview = null;
        if (!empty($r['reply_to'])) {
            // A quoted message is subject to the same per-user and expiry rules as the
            // message quoting it, otherwise deleted or expired text resurfaces here.
            $rep = $db->one(
                "SELECT m.id, m.body, m.kind, m.visible_only_to, m.hidden_for, u.name FROM messages m LEFT JOIN users u ON u.id = m.user_id WHERE m.id = ? AND m.chat_id = ? AND m.deleted_at IS NULL AND (m.expires_at IS NULL OR m.expires_at > ?)",
                array((int)$r['reply_to'], $cid, time())
            );
            if ($rep
                && (int)$rep['id'] >= $minMsgId
                && ($rep['visible_only_to'] === null || (int)$rep['visible_only_to'] === $uid)
                && !m3_msg_hidden_for(isset($rep['hidden_for']) ? $rep['hidden_for'] : null, $uid)) {
                $repBodyTxt = ($chat['type'] === 'secret')
                    ? '🔒 E2EE'
                    : ($rep['kind'] === 'location'
                        ? '📍 موقعیت مکانی'
                        : ($rep['kind'] === 'call_log'
                            ? '📞 سابقه تماس'
                            : ($rep['kind'] === 'video_note' && trim((string)$rep['body']) === ''
                                ? '🎥 پیام ویدیویی فوری'
                                : u_substr((string)$rep['body'], 0, 80))));
                $replyPreview = array(
                    'id'   => (int)$rep['id'],
                    'name' => (string)$rep['name'],
                    'body' => $repBodyTxt,
                    'kind' => $rep['kind']
                );
            }
        }

        $fileMeta = null;
        if (!empty($r['file_id'])) {
            $f = $db->one("SELECT id, display_name, mime, size, encrypted, file_iv FROM files WHERE id = ?", array((int)$r['file_id']));
            if ($f) {
                $fileMeta = array(
                    'id'           => (int)$f['id'],
                    'display_name' => $f['display_name'],
                    'mime'         => $f['mime'],
                    'size'         => (int)$f['size'],
                    'encrypted'    => (int)$f['encrypted'],
                    'file_iv'      => $f['file_iv'],
                    'url'          => '?a=file&id=' . (int)$f['id']
                );
            }
        }

        $reactRows = $db->all("SELECT emoji, user_id FROM reactions WHERE message_id = ?", array($mid));
        $reactMap = array();
        foreach ($reactRows as $rr) {
            $em = $rr['emoji'];
            if (!isset($reactMap[$em])) {
                $reactMap[$em] = array('emoji' => $em, 'count' => 0, 'me' => false);
            }
            $reactMap[$em]['count']++;
            if ((int)$rr['user_id'] === $uid) {
                $reactMap[$em]['me'] = true;
            }
        }

        $isSuperAuthor = ($r['author_role'] === 'superadmin');
        $hasBadge = $isSuperAuthor && ((int)$r['author_badge'] === 1);
        $authorUid = (int)$r['user_id'];
        $authorChatRole = ($authorUid > 0 && isset($chatMemberRoleMap[$authorUid])) ? $chatMemberRoleMap[$authorUid] : '';
        $isChatAdminAuthor = ($authorChatRole === 'owner' || $authorChatRole === 'admin');
        $shadowHiddenFlag = ($shadowView !== null
            && m3_shadow_row_marked($r, $uid, $shadowView['rank'], $shadowView['map'])) ? 1 : 0;
        $hideFwdAuthor = !empty($r['forward_hide_author']) || ($chat['type'] === 'secret');
        $authorFlagsRow = ($authorUid > 0 && isset($authorFlagsByUid[$authorUid])) ? $authorFlagsByUid[$authorUid] : null;
        $editVis = resolve_visible_message_edit_meta($db, $r, $chat, $viewerUserRow, $viewerChatRole, $authorFlagsRow);

        $msgOutRow = array(
            'id'                  => $mid,
            'chat_id'             => $cid,
            'user_id'             => $authorUid,
            'author_username'     => ($authorUid === 0) ? '' : (string)$r['username'],
            'author_name'         => ($authorUid === 0) ? 'سامانه' : ($r['author_name'] ? (string)$r['author_name'] : 'کاربر حذف‌شده'),
            'author_avatar'       => ($authorUid === 0) ? '' : (string)$r['author_avatar'],
            'author_role'         => (string)$r['author_role'],
            'author_chat_role'    => $authorChatRole,
            'is_chat_admin'       => $isChatAdminAuthor ? 1 : 0,
            'has_admin_badge'     => $hasBadge,
            'kind'                => $r['kind'],
            'body'                => (string)$r['body'],
            'cipher'              => $r['cipher'],
            'iv'                  => $r['iv'],
            'reply_to'            => $r['reply_to'] ? (int)$r['reply_to'] : null,
            'reply_preview'       => $replyPreview,
            'forward_from_id'     => $hideFwdAuthor ? null : ($r['forward_from_id'] ? (int)$r['forward_from_id'] : null),
            'forward_from_name'   => $hideFwdAuthor ? null : $r['forward_from_name'],
            'forward_hide_author' => !empty($r['forward_hide_author']) ? 1 : 0,
            'file'                => $fileMeta,
            'reactions'           => array_values($reactMap),
            'created_at'          => (int)$r['created_at'],
            'edited_at'           => $editVis['edited_at'],
            'edited_silent'       => $editVis['edited_silent'],
            'expires_at'          => $r['expires_at'] ? (int)$r['expires_at'] : null,
            'burn_after'          => $r['burn_after'] ? (int)$r['burn_after'] : null,
            'first_read_at'       => $r['first_read_at'] ? (int)$r['first_read_at'] : null,
            'pinned'              => (int)$r['pinned'],
            'spoiler'             => !empty($r['spoiler']) ? 1 : 0,
            'shadow_hidden'       => $shadowHiddenFlag,
            'views'               => $viewsOn ? (int)(isset($r['views']) ? $r['views'] : 0) : 0,
            'tick_status'         => ($chat['type'] === 'saved' || $mid <= $peerLastRead) ? 'seen' : 'sent'
        );
        if ($viewerUserRow && isset($viewerUserRow['role']) && $viewerUserRow['role'] === 'superadmin' && !empty($editVis['edit_history'])) {
            $msgOutRow['edit_history'] = $editVis['edit_history'];
        }
        $out[] = $msgOutRow;
    }
    return $out;
}

/* ---------------------------------------------------------------------------
 * SHADOW-BAN
 *
 * A shadow-banned member keeps their seat in the chat: they are still listed as
 * a member, they can still read everything that was written before the ban, and
 * they can still type. What changes is only the traffic after the ban moment:
 *
 *   1. messages other people write after the ban never reach the banned member;
 *   2. messages the banned member writes after the ban never reach anyone else,
 *      except the chat owner / admins (and the global super-admin), who DO see
 *      them, flagged, so the restriction cannot be abused unnoticed;
 *   3. the banned member still sees their own messages, so sending looks normal.
 *
 * Who may ban whom is a strict ladder (super-admin 3 > owner 2 > admin 1 >
 * member 0): a rank can only shadow-ban someone strictly below it, so an admin
 * cannot silence a fellow admin, and nobody can silence their own rank.
 * ------------------------------------------------------------------------- */

/* The per-request cache of "banned user id -> ban moment" for each chat. */
function m3_shadow_forget_cache($chatId = null) {
    if (!isset($GLOBALS['M3_SHADOW_CACHE']) || !is_array($GLOBALS['M3_SHADOW_CACHE'])) {
        $GLOBALS['M3_SHADOW_CACHE'] = array();
    }
    if ($chatId === null) {
        $GLOBALS['M3_SHADOW_CACHE'] = array();
        return;
    }
    unset($GLOBALS['M3_SHADOW_CACHE'][(int)$chatId]);
}

function m3_chat_shadow_map(DB $db, $chatId) {
    $chatId = (int)$chatId;
    if (!isset($GLOBALS['M3_SHADOW_CACHE']) || !is_array($GLOBALS['M3_SHADOW_CACHE'])) {
        $GLOBALS['M3_SHADOW_CACHE'] = array();
    }
    if (isset($GLOBALS['M3_SHADOW_CACHE'][$chatId])) {
        return $GLOBALS['M3_SHADOW_CACHE'][$chatId];
    }
    $map = array();
    try {
        $rows = $db->all(
            "SELECT user_id, shadow_banned_at FROM members WHERE chat_id = ? AND shadow_banned = 1",
            array($chatId)
        );
        foreach ($rows as $r) {
            $map[(int)$r['user_id']] = (int)$r['shadow_banned_at'];
        }
    } catch (Exception $e) {
        /* Migration 16 adds these columns; on an older schema nothing is hidden. */
    }
    $GLOBALS['M3_SHADOW_CACHE'][$chatId] = $map;
    return $map;
}

/* Where does this user stand in the chat's ladder? 3 super-admin, 2 owner,
   1 admin, 0 everyone else. Pass $member when it is already loaded. */
function m3_shadow_rank(DB $db, $chat, $userId, $member = null) {
    $userId = (int)$userId;
    if ($userId <= 0) return 0;
    $u = $db->one("SELECT role FROM users WHERE id = ?", array($userId));
    if ($u && $u['role'] === 'superadmin') return 3;
    if (!empty($chat['owner_id']) && (int)$chat['owner_id'] === $userId) return 2;
    $mem = $member;
    if ($mem === null) {
        $mem = $db->one(
            "SELECT role FROM members WHERE chat_id = ? AND user_id = ?",
            array((int)$chat['id'], $userId)
        );
    }
    $role = $mem ? strtolower((string)$mem['role']) : '';
    if ($role === 'owner') return 2;
    if ($role === 'admin') return 1;
    return 0;
}

/* Only the moderation ranks (admin and up) wield the restriction, and only
   the moderation ranks are trusted to see through it. */
function m3_shadow_can_manage($rank) { return (int)$rank >= 1; }
function m3_shadow_can_see_hidden($rank) { return (int)$rank >= 1; }

function m3_shadow_may_target(DB $db, $chat, $actorRank, $targetUserId, $targetMember = null) {
    if (!m3_shadow_can_manage($actorRank)) return false;
    $targetRank = m3_shadow_rank($db, $chat, $targetUserId, $targetMember);
    return (int)$actorRank > $targetRank;
}

/* Everything the read paths need about the current viewer, in one lookup. */
function m3_shadow_view(DB $db, $chat, $viewerId, $member = null) {
    $rank = m3_shadow_rank($db, $chat, $viewerId, $member);
    $map  = m3_chat_shadow_map($db, (int)$chat['id']);
    $myAt = isset($map[(int)$viewerId]) ? (int)$map[(int)$viewerId] : 0;
    return array('rank' => $rank, 'map' => $map, 'my_at' => $myAt);
}

/* Row-level verdict: must this row be withheld from $viewerId? */
function m3_shadow_hides_row($row, $viewerId, $actorRank, array $shadowMap, $viewerShadowAt) {
    if (empty($shadowMap) && (int)$viewerShadowAt <= 0) return false;
    $authorId = isset($row['user_id']) ? (int)$row['user_id'] : 0;
    $created  = isset($row['created_at']) ? (int)$row['created_at'] : 0;
    $viewerId = (int)$viewerId;
    // 1. The viewer is banned: other people's post-ban messages stay hidden.
    if ((int)$viewerShadowAt > 0 && $authorId !== $viewerId && $created >= (int)$viewerShadowAt) {
        return true;
    }
    // 2. The author is banned: their post-ban messages are hidden from everyone
    //    except themselves and the moderation ranks.
    if (isset($shadowMap[$authorId]) && $created >= (int)$shadowMap[$authorId]) {
        if ($authorId === $viewerId) return false;
        if (m3_shadow_can_see_hidden($actorRank)) return false;
        return true;
    }
    return false;
}

/* Should this row be shown to the moderation ranks with a "hidden" flag?
   Never for the author themselves -- to them the conversation looks normal. */
function m3_shadow_row_marked($row, $viewerId, $actorRank, array $shadowMap) {
    if (empty($shadowMap) || !m3_shadow_can_see_hidden($actorRank)) return false;
    $authorId = isset($row['user_id']) ? (int)$row['user_id'] : 0;
    if ($authorId === (int)$viewerId) return false;
    if (!isset($shadowMap[$authorId])) return false;
    $created = isset($row['created_at']) ? (int)$row['created_at'] : 0;
    return $created >= (int)$shadowMap[$authorId];
}

function fetch_chat_messages(DB $db, $chat, $member, $user, $sinceId = 0, $beforeId = 0, $limit = 60, $ascAfterId = -1) {
    $cid = (int)$chat['id'];
    $uid = (int)$user['id'];
    if (!empty($chat['auto_delete_sec']) || ($member && !empty($member['auto_delete_sec']))) {
        purge_auto_delete_chat_messages($db, $cid);
    }
    $now = time();
    $isSuperViewer = ($user && $user['role'] === 'superadmin');
    $minMsgId = (!$isSuperViewer && $chat['history'] === 'from_join' && $member) ? (int)$member['joined_msg_id'] : 0;
    // Per-member cutoff set when this member reopened a 1:1 chat they had removed
    // from their own list: older messages stay hidden for them only.
    if (!$isSuperViewer && $member && !empty($member['rejoin_msg_id'])) {
        $minMsgId = max($minMsgId, (int)$member['rejoin_msg_id']);
    }

    // Shadow-ban cutoffs are pushed into SQL rather than filtered afterwards so
    // that the LIMIT window stays honest: a page of messages must not come back
    // half empty just because the tail of it was withheld.
    $shadowView   = m3_shadow_view($db, $chat, $uid, $member);
    $shadowJoin   = '';
    $shadowWhere  = '';
    $shadowParams = array();
    if (!empty($shadowView['map'])) {
        $shadowJoin  = " LEFT JOIN members sm ON sm.chat_id = m.chat_id AND sm.user_id = m.user_id AND sm.shadow_banned = 1";
        $shadowWhere = " AND (sm.user_id IS NULL OR m.created_at < sm.shadow_banned_at OR m.user_id = ?";
        $shadowParams[] = $uid;
        if (m3_shadow_can_see_hidden($shadowView['rank'])) {
            $shadowWhere .= " OR 1 = 1";
        }
        $shadowWhere .= ")";
    }
    if ($shadowView['my_at'] > 0) {
        $shadowWhere   .= " AND NOT (m.user_id <> ? AND m.created_at >= ?)";
        $shadowParams[] = $uid;
        $shadowParams[] = $shadowView['my_at'];
    }

    $params = array($cid, $minMsgId, $uid, $now);
    if (!empty($shadowParams)) {
        $params = array_merge($params, $shadowParams);
    }
    $sql = "SELECT m.*, u.username, u.name AS author_name, u.avatar AS author_avatar, u.role AS author_role, u.show_admin_badge AS author_badge
            FROM messages m
            LEFT JOIN users u ON u.id = m.user_id{$shadowJoin}
            WHERE m.chat_id = ? AND m.id >= ? AND (m.visible_only_to IS NULL OR m.visible_only_to = ?)
              AND m.deleted_at IS NULL AND (m.expires_at IS NULL OR m.expires_at > ?){$shadowWhere}";

    $limit = max(1, min(150, (int)$limit));
    if ($ascAfterId >= 0) {
        $sql .= " AND m.id > ? ORDER BY m.id ASC " . $db->limit($limit);
        $params[] = (int)$ascAfterId;
        $rows = $db->all($sql, $params);
    } else {
        if ($sinceId > 0) {
            $sql .= " AND m.id > ?";
            $params[] = (int)$sinceId;
        }
        if ($beforeId > 0) {
            $sql .= " AND m.id < ?";
            $params[] = (int)$beforeId;
        }
        $sql .= " ORDER BY m.id DESC " . $db->limit($limit);
        $rows = array_reverse($db->all($sql, $params));
    }

    // The old top-two-receipt probe went away with the receipt_read_id tick: the
    // watermark below already answers "how far has the other side read".
    $peerLastRead = peer_read_watermark($db, $chat, $uid);
    return hydrate_message_rows($db, $chat, $rows, $uid, $minMsgId, $peerLastRead);
}

/* File Magic Bytes Validation (Zero fileinfo/gd requirement; supports cross-browser MediaRecorder containers) */
function detect_and_validate_magic_bytes($filePath, $ext, $encrypted = 0, $kind = 'file') {
    if ($encrypted === 1) {
        return 'application/octet-stream';
    }
    $fp = @fopen($filePath, 'rb');
    if (!$fp) return false;
    $head = (string)@fread($fp, 64);
    @fclose($fp);
    if ($head === '') {
        return in_array(strtolower($ext), array('txt', 'log', 'md', 'csv', 'json'), true) ? 'text/plain; charset=utf-8' : 'application/octet-stream';
    }

    $ext = strtolower($ext);
    // Block SVG / active scripts unconditionally
    if (in_array($ext, array('svg', 'php', 'phtml', 'phar', 'html', 'htm', 'js', 'sh', 'exe'), true)) {
        return false;
    }
    if (stripos($head, '<svg') !== false || stripos($head, '<?php') !== false || stripos($head, '<script') !== false || stripos($head, '<!doctype html') !== false) {
        return false;
    }

    // Detect by actual binary magic bytes first
    if (substr($head, 0, 3) === "\xFF\xD8\xFF") {
        return 'image/jpeg';
    }
    if (substr($head, 0, 8) === "\x89PNG\r\n\x1A\n") {
        return 'image/png';
    }
    if (substr($head, 0, 6) === 'GIF87a' || substr($head, 0, 6) === 'GIF89a') {
        return 'image/gif';
    }
    if (substr($head, 0, 4) === 'RIFF' && substr($head, 8, 4) === 'WEBP') {
        return 'image/webp';
    }
    if (substr($head, 0, 5) === '%PDF-') {
        return 'application/pdf';
    }
    if (substr($head, 0, 4) === 'OggS') {
        return 'audio/ogg';
    }
    if (substr($head, 0, 4) === 'RIFF' && substr($head, 8, 4) === 'WAVE') {
        return 'audio/wav';
    }
    if (substr($head, 0, 4) === "\x1A\x45\xDF\xA3") {
        return ($kind === 'voice' || $ext === 'weba') ? 'audio/webm' : 'video/webm';
    }
    if (strlen($head) >= 12 && (substr($head, 4, 4) === 'ftyp' || strpos(substr($head, 0, 16), 'ftyp') !== false)) {
        return ($kind === 'voice' || $ext === 'm4a' || $ext === 'aac') ? 'audio/mp4' : 'video/mp4';
    }
    if (substr($head, 0, 3) === 'ID3' || (strlen($head) >= 2 && ord($head[0]) === 0xFF && (ord($head[1]) & 0xE0) === 0xE0)) {
        return 'audio/mpeg';
    }
    if (substr($head, 0, 4) === 'fLaC') {
        return 'audio/flac';
    }
    if (substr($head, 0, 4) === "PK\x03\x04") {
        return 'application/zip';
    }
    if (in_array($ext, array('txt', 'log', 'md', 'csv', 'json'), true) && strpos($head, "\x00") === false) {
        return 'text/plain; charset=utf-8';
    }
    // Fallback for valid browser MediaRecorder blobs (e.g., fragmented webm/mp4/ogg audio streams on iOS/Android)
    if ($kind === 'voice' && in_array($ext, array('webm', 'ogg', 'opus', 'mp4', 'm4a', 'wav', 'mp3', 'aac'), true)) {
        if ($ext === 'ogg' || $ext === 'opus') return 'audio/ogg';
        if ($ext === 'mp4' || $ext === 'm4a' || $ext === 'aac') return 'audio/mp4';
        if ($ext === 'wav') return 'audio/wav';
        if ($ext === 'mp3') return 'audio/mpeg';
        return 'audio/webm';
    }
    // Other unknown / general file types (documents, archives, binaries) are safely stored as octet-stream and served as forced download attachments
    return 'application/octet-stream';
}

/* Asset Endpoints (?a=robots|font|manifest|sw|icon|file|cron) */
function handle_asset_route($action, $cfg) {
    header('X-Robots-Tag: noindex, nofollow, noarchive, nosnippet, noimageindex');

    if ($action === 'robots') {
        header('Content-Type: text/plain; charset=utf-8');
        header('Cache-Control: public, max-age=86400');
        echo "User-agent: *\nDisallow: /\n";
        exit;
    }

    if ($action === 'font') {
        $raw = base64_decode(VAZIRMATN_WOFF2_B64);
        header('Content-Type: font/woff2');
        header('Cache-Control: public, max-age=31536000, immutable');
        header('Content-Length: ' . strlen($raw));
        echo $raw;
        exit;
    }

    if ($action === 'icon') {
        header('X-Content-Type-Options: nosniff');
        header("Content-Security-Policy: default-src 'none'; style-src 'unsafe-inline'");
        if ($cfg) {
            try {
                $iDb = new DB($cfg);
                $favUri = (string)Settings::get($iDb, 'site_favicon', '');
                $logoUri = (string)Settings::get($iDb, 'site_logo', '');
                $parsedIcon = parse_branding_data_uri($favUri !== '' ? $favUri : $logoUri);
                if ($parsedIcon) {
                    header('X-Content-Type-Options: nosniff');
                    header("Content-Security-Policy: default-src 'none'; sandbox");
                    header('Content-Type: ' . $parsedIcon['mime']);
                    header('Cache-Control: no-cache');
                    echo $parsedIcon['bytes'];
                    exit;
                }
            } catch (Exception $e) {}
        }
        header('Content-Type: image/svg+xml; charset=utf-8');
        header('Cache-Control: no-cache');
        echo default_messenger_logo_svg();
        exit;
    }

    if ($action === 'manifest') {
        $mName = 'My Mini Messenger (M3)';
        $mIconMime = 'image/svg+xml';
        if ($cfg) {
            try {
                $mDb = new DB($cfg);
                $mLang = (string)Settings::get($mDb, 'default_lang', 'fa');
                $mName = ($mLang === 'en')
                    ? (string)Settings::get($mDb, 'site_name_en', 'My Mini Messenger (M3)')
                    : (string)Settings::get($mDb, 'site_name_fa', 'پیامرسان کوچک من (M3)');
                $favUri = (string)Settings::get($mDb, 'site_favicon', '');
                $logoUri = (string)Settings::get($mDb, 'site_logo', '');
                $parsedIcon = parse_branding_data_uri($favUri !== '' ? $favUri : $logoUri);
                if ($parsedIcon) $mIconMime = $parsedIcon['mime'];
            } catch (Exception $e) {}
        }
        header('Content-Type: application/manifest+json; charset=utf-8');
        echo json_encode(array(
            'name' => $mName,
            'short_name' => 'M3',
            'start_url' => './',
            'display' => 'standalone',
            'background_color' => '#0f172a',
            'theme_color' => '#009687',
            'icons' => array(
                array('src' => '?a=icon&v=009687', 'sizes' => '192x192 512x512', 'type' => $mIconMime, 'purpose' => 'any maskable')
            )
        ), JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
        exit;
    }

    if ($action === 'sw') {
        header('Content-Type: application/javascript; charset=utf-8');
        header('Service-Worker-Allowed: /');
        header('Cache-Control: no-store, no-cache, must-revalidate, max-age=0');
        echo <<<'M3SWJS'
const CACHE_NAME = 'm3-messenger-shell-v4';
self.addEventListener('install', function (e) {
    e.waitUntil(self.skipWaiting());
});
self.addEventListener('activate', function (e) {
    e.waitUntil(
        caches.keys().then(function (ks) {
            return Promise.all(ks.filter(function (k) { return k !== CACHE_NAME; }).map(function (k) { return caches.delete(k); }));
        }).then(function () { return self.clients.claim(); })
    );
});
self.addEventListener('fetch', function (e) {
    if (e.request.method !== 'GET') return;
    var url = new URL(e.request.url);
    if (url.searchParams.get('a') === 'font') {
        e.respondWith(caches.open(CACHE_NAME).then(function (c) {
            return c.match(e.request).then(function (r) {
                return r || fetch(e.request).then(function (res) {
                    c.put(e.request, res.clone());
                    return res;
                });
            });
        }));
    }
});
M3SWJS;
        echo <<<'M3SWJS2'
var _m3LastSeenMsgId = 0;
var _m3NotifiedCalls = {};
async function m3CheckBackgroundUpdates() {
    try {
        var clientList = await self.clients.matchAll({ type: 'window', includeUncontrolled: true });
        var hasVisibleFocused = false;
        for (var i = 0; i < clientList.length; i++) {
            if (clientList[i].visibilityState === 'visible' && clientList[i].focused) {
                hasVisibleFocused = true;
                break;
            }
        }
        if (hasVisibleFocused) return;
        var resp = await fetch('./?a=sw_sync&since_id=' + encodeURIComponent(String(_m3LastSeenMsgId || 0)), {
            credentials: 'same-origin',
            cache: 'no-store'
        });
        if (!resp || !resp.ok) return;
        var json = await resp.json();
        if (!json || !json.ok || !json.data) return;
        var d = json.data;
        if (typeof d.latest_msg_id === 'number' && d.latest_msg_id > _m3LastSeenMsgId) {
            _m3LastSeenMsgId = d.latest_msg_id;
        }
        if (d.incoming_call && d.incoming_call.id) {
            var cKey = String(d.incoming_call.id) + ':' + Math.floor(Date.now() / 8000);
            if (!_m3NotifiedCalls[cKey]) {
                _m3NotifiedCalls[cKey] = 1;
                await self.registration.showNotification(d.incoming_call.title || '📞 تماس ورودی / Incoming Call', {
                    body: d.incoming_call.body || 'برای پاسخ به تماس ضربه بزنید / Tap to answer call',
                    tag: 'm3-call-' + d.incoming_call.id,
                    renotify: true,
                    requireInteraction: true,
                    silent: false,
                    vibrate: [500, 220, 500, 220, 500, 220, 500],
                    icon: './?a=icon&s=192',
                    badge: './?a=icon&s=96',
                    data: { chat_id: d.incoming_call.chat_id || 0, call_id: d.incoming_call.id }
                });
            }
        }
        if (Array.isArray(d.notifications)) {
            for (var n = 0; n < d.notifications.length; n++) {
                var item = d.notifications[n];
                await self.registration.showNotification(item.title || 'M3', {
                    body: item.body || '',
                    tag: item.tag || ('m3-msg-' + (item.chat_id || n)),
                    renotify: true,
                    silent: !!d.silent,
                    vibrate: d.silent ? [] : [180, 90, 180],
                    icon: './?a=icon&s=192',
                    badge: './?a=icon&s=96',
                    data: { chat_id: item.chat_id || 0 }
                });
            }
        }
    } catch (err) {}
}
self.addEventListener('push', function (e) {
    e.waitUntil(m3CheckBackgroundUpdates());
});
self.addEventListener('sync', function (e) {
    if (e.tag === 'm3-bg-sync') e.waitUntil(m3CheckBackgroundUpdates());
});
self.addEventListener('periodicsync', function (e) {
    if (e.tag === 'm3-bg-periodic') e.waitUntil(m3CheckBackgroundUpdates());
});
self.addEventListener('message', function (e) {
    if (!e.data) return;
    if (e.data.type === 'M3_SYNC_SEEN_ID' && Number(e.data.id || 0) > _m3LastSeenMsgId) {
        _m3LastSeenMsgId = Number(e.data.id || 0);
    } else if (e.data.type === 'M3_BG_CHECK_NOW') {
        e.waitUntil(m3CheckBackgroundUpdates());
    }
});
self.addEventListener('notificationclick', function (e) {
    e.notification.close();
    var targetChatId = (e.notification && e.notification.data && e.notification.data.chat_id) ? Number(e.notification.data.chat_id) : 0;
    var targetUrl = targetChatId > 0 ? ('./?open_chat=' + targetChatId) : './';
    e.waitUntil(self.clients.matchAll({ type: 'window', includeUncontrolled: true }).then(function (list) {
        for (var i = 0; i < list.length; i++) {
            var cl = list[i];
            if ('focus' in cl) {
                try { cl.postMessage({ type: 'M3_OPEN_FROM_NOTIF', chat_id: targetChatId }); } catch (err) {}
                return cl.focus();
            }
        }
        if (self.clients.openWindow) return self.clients.openWindow(targetUrl);
    }));
});
M3SWJS2;
        exit;
    }

    if (!$cfg) {
        api_err('not_installed', 'Application is not installed yet.', 503);
    }

    // Handle lightweight tick long-polling with verified session guard
    if ($action === 'poll') {
        if (!is_dir(DATA_DIR) || !file_exists(CONFIG_FILE)) {
            json_out(array('ok' => false, 'error' => 'messenger_wiped', 'wiped' => true), 200);
        }
        $hasSessCookie = (!empty($_COOKIE['pm_sess']) && is_string($_COOKIE['pm_sess'])) || !empty($_SERVER['HTTP_X_SESSION_TOKEN']);
        if (!$hasSessCookie) {
            api_err('unauthorized', 'Authentication required.', 401);
        }
        try {
            $pollDb = new DB($cfg);
            $schedPollWipe = (int)Settings::get($pollDb, 'messenger_delete_at', 0);
            if ($schedPollWipe > 0 && time() >= $schedPollWipe) {
                execute_full_messenger_wipe($pollDb, true);
                $pollDb = null;
                json_out(array('ok' => false, 'error' => 'messenger_wiped', 'wiped' => true), 200);
            }
            $pollAuth = get_current_auth($pollDb);
            if (!$pollAuth) {
                $pollDb = null;
                api_err('unauthorized', 'Authentication required.', 401);
            }
            if (!empty($pollAuth['session']['is_locked'])) {
                $pollDb = null;
                api_err('session_locked', 'Session is locked.', 423);
            }
            // This route reads the session itself instead of going through
            // require_auth, so it has to apply the maintenance gate on its own -
            // without it a signed-in account would keep receiving live updates
            // while every other action was refused.
            if ((int)Settings::get($pollDb, 'maintenance_mode', 0) === 1
                && $pollAuth['user']['role'] !== 'superadmin') {
                $pollDb = null;
                api_err('maintenance_mode', 'System is currently in maintenance mode.', 503);
            }
            $pollUserSnap = $pollAuth['user'];
            $pollUid = (int)$pollUserSnap['id'];
            $curUdig = compute_user_sync_digest($pollDb, $pollUid);
            $GLOBALS['M3_ACTIVE_DB'] = $pollDb;
            $curTick = get_tick();
            $curTypingTick = get_typing_tick();
            $GLOBALS['M3_ACTIVE_DB'] = null;
            $pollDb = null;
        } catch (Exception $e) {
            api_err('server_error', 'Database unavailable.', 503);
        }
        $clientTick = isset($_GET['tick']) ? trim((string)$_GET['tick']) : (isset($_GET['since_tick']) ? trim((string)$_GET['since_tick']) : '0');
        $clientTypingTick = isset($_GET['typing_tick']) ? trim((string)$_GET['typing_tick']) : '0';
        $activeChatIdPoll = isset($_GET['active_chat_id']) ? max(0, (int)$_GET['active_chat_id']) : 0;
        $clientUdig = isset($_GET['udig']) ? trim((string)$_GET['udig']) : '';
        if (function_exists('session_write_close')) @session_write_close();
        $udigDiff = ($clientUdig !== '' && $curUdig !== '' && $clientUdig !== $curUdig);
        $start = microtime(true);
        $pollMaxWait = (PHP_SAPI === 'cli-server') ? 0.0 : 2.0;
        while (
            !$udigDiff
            && $curTick === $clientTick
            && ($activeChatIdPoll <= 0 || $curTypingTick === $clientTypingTick)
            && (microtime(true) - $start) < $pollMaxWait
        ) {
            usleep(200000);
            if (!is_dir(DATA_DIR) || !file_exists(CONFIG_FILE)) {
                json_out(array('ok' => false, 'error' => 'messenger_wiped', 'wiped' => true), 200);
            }
            $curTick = get_tick();
            if ($activeChatIdPoll > 0) {
                $curTypingTick = get_typing_tick();
            }
        }
        $typingUsersOut = array();
        if ($activeChatIdPoll > 0 && isset($pollUserSnap) && $pollUserSnap) {
            try {
                $pollDbOut = new DB($cfg);
                $typingUsersOut = get_active_typing_users_for_chat($pollDbOut, $activeChatIdPoll, $pollUserSnap);
                $pollDbOut = null;
            } catch (Exception $e) {}
        }
        api_ok(array(
            'tick'           => $curTick,
            'typing_tick'    => $curTypingTick,
            'typing_chat_id' => $activeChatIdPoll,
            'typing_users'   => $typingUsersOut,
            'udig'           => $curUdig,
            'typing_changed' => ($activeChatIdPoll > 0 && $curTypingTick !== $clientTypingTick),
            'changed'        => ($curTick !== $clientTick || $udigDiff)
        ));
    }

    $db = new DB($cfg);
    ensure_schema($db);

    if ($action === 'sw_sync') {
        $swAuth = get_current_auth($db, true);
        if (!$swAuth) {
            api_ok(array('authenticated' => false, 'notifications' => array(), 'incoming_call' => null));
        }
        $swUser = $swAuth['user'];
        $swUid = (int)$swUser['id'];
        $swLang = (isset($swUser['lang']) && $swUser['lang'] === 'en') ? 'en' : 'fa';
        $swFlags = get_user_flags($swUser);
        if (!empty($swFlags['bg_push_enabled']) || !isset($swFlags['bg_push_enabled'])) {
            // Enabled by default
        } else {
            api_ok(array('authenticated' => true, 'notifications' => array(), 'incoming_call' => null));
        }
        $isLockedSw = !empty($swAuth['session']['is_locked']);
        $nowSw = time();
        $incomingCallOut = null;
        $ringRow = $db->one(
            "SELECT ac.id, ac.chat_id, ac.call_type, ac.status, ac.created_by, c.type AS chat_type, c.title AS chat_title, u.name AS caller_name
             FROM active_calls ac
             JOIN chats c ON c.id = ac.chat_id
             JOIN members m ON m.chat_id = ac.chat_id AND m.user_id = ?
             LEFT JOIN users u ON u.id = ac.created_by
             LEFT JOIN call_participants cp ON cp.call_id = ac.id AND cp.user_id = ?
             WHERE ac.created_by != ? AND (m.muted = 0 OR c.type IN ('dm', 'secret'))
               AND ac.status IN ('ringing', 'active')
               AND (cp.user_id IS NULL OR cp.state NOT IN ('joined', 'declined', 'left'))
               AND ac.updated_at >= ?
             ORDER BY ac.id DESC LIMIT 1",
            array($swUid, $swUid, $swUid, $nowSw - 75)
        );
        if ($ringRow) {
            $callerTitle = $isLockedSw
                ? ($swLang === 'en' ? 'Incoming Call' : 'تماس ورودی')
                : ((string)$ringRow['caller_name'] ?: ($swLang === 'en' ? 'Incoming Call' : 'تماس ورودی'));
            $callKindTxt = ($ringRow['call_type'] === 'video')
                ? ($swLang === 'en' ? 'Incoming video call — tap to answer' : 'تماس تصویری ورودی — برای پاسخ ضربه بزنید')
                : ($swLang === 'en' ? 'Incoming voice call — tap to answer' : 'تماس صوتی ورودی — برای پاسخ ضربه بزنید');
            $incomingCallOut = array(
                'id'      => (int)$ringRow['id'],
                'chat_id' => (int)$ringRow['chat_id'],
                'title'   => '📞 ' . $callerTitle,
                'body'    => $callKindTxt
            );
        }

        $sinceMsgId = isset($_GET['since_id']) ? max(0, (int)$_GET['since_id']) : 0;
        $maxUnreadRows = $db->all(
            "SELECT m.id, m.chat_id, m.user_id, m.kind, m.body, m.created_at, c.type AS chat_type, c.title AS chat_title, u.name AS sender_name
             FROM messages m
             JOIN members mem ON mem.chat_id = m.chat_id AND mem.user_id = ?
             JOIN chats c ON c.id = m.chat_id
             LEFT JOIN users u ON u.id = m.user_id
             WHERE m.deleted_at IS NULL AND m.user_id != ? AND m.user_id > 0
               AND mem.muted = 0 AND mem.role != 'pending'
               AND m.id > mem.last_read_id AND m.id > ?
               AND (m.expires_at IS NULL OR m.expires_at > ?)
               AND m.created_at >= ?
             ORDER BY m.id DESC LIMIT 5",
            array($swUid, $swUid, $sinceMsgId, $nowSw, $nowSw - 180)
        );
        // A notification must never carry text the reader cannot open: drop rows
        // written by a shadow-banned member, and rows a banned reader cannot see.
        $notifRankCache = array();
        $hidePreviewSw = (isset($swFlags['notif_preview']) && empty($swFlags['notif_preview']));
        $notifOut = array();
        $latestId = $sinceMsgId;
        foreach ($maxUnreadRows as $ur) {
            $midSw = (int)$ur['id'];
            if ($midSw > $latestId) $latestId = $midSw;
            $ncid = (int)$ur['chat_id'];
            if (!isset($notifRankCache[$ncid])) {
                $notifRankCache[$ncid] = m3_chat_shadow_map($db, $ncid);
            }
            $nMap = $notifRankCache[$ncid];
            if (!empty($nMap)) {
                $nRow = $db->one(
                    "SELECT role FROM members WHERE chat_id = ? AND user_id = ?",
                    array($ncid, $swUid)
                );
                $nChatOwnerId = (int)$db->val("SELECT owner_id FROM chats WHERE id = ?", array($ncid));
                $nRank = ($swUser && $swUser['role'] === 'superadmin') ? 3
                    : (($nChatOwnerId === (int)$swUid) ? 2
                    : (($nRow && $nRow['role'] === 'owner') ? 2 : (($nRow && $nRow['role'] === 'admin') ? 1 : 0)));
                if (m3_shadow_hides_row($ur, $swUid, $nRank, $nMap, isset($nMap[$swUid]) ? (int)$nMap[$swUid] : 0)) {
                    continue;
                }
            }
            $nTitle = ($isLockedSw || $hidePreviewSw)
                ? ($swLang === 'en' ? 'New Message' : 'پیام جدید')
                : (($ur['chat_type'] === 'dm' || $ur['chat_type'] === 'secret')
                    ? ((string)$ur['sender_name'] ?: 'M3')
                    : ((string)$ur['chat_title'] ?: 'M3'));
            $nBody = ($isLockedSw || $hidePreviewSw)
                ? ($swLang === 'en' ? 'Open messenger to view' : 'برای مشاهده وارد پیام‌رسان شوید')
                : (($ur['chat_type'] === 'secret')
                    ? ($swLang === 'en' ? '🔒 Encrypted message' : '🔒 پیام رمزنگاری‌شده')
                    : ($ur['kind'] === 'text' ? u_substr((string)$ur['body'], 0, 90) : '📎 ' . $ur['kind']));
            $notifOut[] = array(
                'chat_id' => (int)$ur['chat_id'],
                'tag'     => 'm3-chat-' . (int)$ur['chat_id'],
                'title'   => $nTitle,
                'body'    => $nBody
            );
        }
        api_ok(array(
            'authenticated' => true,
            'silent'        => (!empty($swFlags['notif_silent']) || !empty($swFlags['app_sounds_muted'])) ? 1 : 0,
            'latest_msg_id' => $latestId,
            'incoming_call' => $incomingCallOut,
            'notifications' => $notifOut
        ));
    }

    if ($action === 'cron') {
        $cAuth = get_current_auth($db);
        $isSuperCron = ($cAuth && isset($cAuth['user']['role']) && $cAuth['user']['role'] === 'superadmin');
        $res = lazy_purge($db, $isSuperCron);
        api_ok($isSuperCron ? $res : array('ok' => true));
    }

    if ($action === 'user_backup_zip') {
        if (!isset($_SERVER['REQUEST_METHOD']) || strtoupper((string)$_SERVER['REQUEST_METHOD']) !== 'POST') {
            api_err('method_not_allowed', 'POST method is required.', 405);
        }
        $auth = require_auth($db, true);
        if (!empty($auth['session']['is_locked'])) {
            api_err('session_locked', 'صفحه‌ی پیام‌رسان قفل است. ابتدا رمز قفل صفحه را وارد کنید. / Session is locked.', 423);
        }
        $meBk = $auth['user'];
        if ((int)Settings::get($db, 'maintenance_mode', 0) === 1 && $meBk['role'] !== 'superadmin') {
            api_err('maintenance_mode', 'سامانه در حالت تعمیر و نگهداری است. / System is in maintenance mode.', 503);
        }
        $infoBk = build_and_stream_user_self_backup_zip($db, $meBk, false);
        $zipBytesBk = (int)$infoBk['zip_bytes'];
        $quotaCheck = evaluate_user_backup_traffic_quota($db, $meBk, $zipBytesBk);
        if (empty($quotaCheck['allowed'])) {
            api_err(
                'backup_traffic_insufficient',
                'به دلیل محدودیت ترافیک حساب کاربری و حجم داده‌های پشتیبان، امکان تهیه نسخه پشتیبان وجود ندارد. / Cannot generate backup because the backup archive size exceeds your remaining allowed traffic quota.',
                429,
                array(
                    'zip_bytes'       => $zipBytesBk,
                    'remaining_bytes' => $quotaCheck['remaining_bytes'],
                    'scope'           => $quotaCheck['scope']
                )
            );
        }
        verify_and_record_traffic($db, $meBk, $zipBytesBk, true);
        build_and_stream_user_self_backup_zip($db, $meBk, true);
    }

    if ($action === 'file') {
        $auth = get_current_auth($db);
        if (!$auth) {
            http_response_code(403);
            exit('Forbidden');
        }
        if (!empty($auth['session']['is_locked'])) {
            http_response_code(423);
            exit('Session Locked');
        }
        if ((int)Settings::get($db, 'maintenance_mode', 0) === 1 && $auth['user']['role'] !== 'superadmin') {
            http_response_code(503);
            exit('Maintenance Mode');
        }
        $fid = isset($_GET['id']) ? (int)$_GET['id'] : 0;
        $f = $db->one("SELECT * FROM files WHERE id = ?", array($fid));
        if (!$f) {
            http_response_code(404);
            exit('File not found');
        }
        $uid = (int)$auth['user']['id'];
        $isSuperViewer = ($auth['user']['role'] === 'superadmin');
        $nowTs = time();
        $refMsgs = $db->all(
            "SELECT m.id, m.chat_id, m.hidden_for, m.burn_after, m.expires_at, c.type AS chat_type, c.history, c.status AS chat_status, c.perms_json
             FROM messages m
             JOIN chats c ON c.id = m.chat_id
             WHERE m.file_id = ? AND m.deleted_at IS NULL AND (m.expires_at IS NULL OR m.expires_at > ?)
               AND (m.visible_only_to IS NULL OR m.visible_only_to = ?)",
            array($fid, $nowTs, $uid)
        );
        if (empty($refMsgs)) {
            $anyHistoricalMsg = (int)$db->val("SELECT COUNT(*) FROM messages WHERE file_id = ?", array($fid));
            if ($anyHistoricalMsg > 0) {
                release_file_if_unreferenced($db, $fid, 0);
                http_response_code(404);
                exit('File not found');
            }
        }
        $isSecretFile = !empty($f['encrypted']);
        $isSelfDestructFile = false;
        $chatDownloadBlocked = false;
        $allowedViaActiveMsg = false;
        foreach ($refMsgs as $rm) {
            if ($rm['chat_type'] === 'secret') {
                $isSecretFile = true;
            }
            if ((!empty($rm['burn_after']) && (int)$rm['burn_after'] > 0) || !empty($rm['expires_at'])) {
                $isSelfDestructFile = true;
            }
            if ($rm['chat_type'] === 'group' || $rm['chat_type'] === 'channel') {
                $cp = parse_json_col($rm['perms_json'], array('allow_file_download' => 1));
                if (isset($cp['allow_file_download']) && (int)$cp['allow_file_download'] === 0) {
                    $chatDownloadBlocked = true;
                }
            }
            if (!$allowedViaActiveMsg) {
                if (is_hidden_for_user($rm['hidden_for'], $uid)) continue;
                $mRow = get_active_member($db, (int)$rm['chat_id'], $uid);
                if (!$mRow) {
                    if ($isSuperViewer && $rm['chat_type'] !== 'secret') {
                        $allowedViaActiveMsg = true;
                    }
                    continue;
                }
                $minAllowedId = ($rm['history'] === 'from_join') ? (int)$mRow['joined_msg_id'] : 0;
                if ((int)$rm['id'] >= $minAllowedId) {
                    $allowedViaActiveMsg = true;
                }
            }
        }
        $allowedFile = $isSecretFile
            ? ($allowedViaActiveMsg || (empty($refMsgs) && (int)$f['owner_id'] === $uid))
            : ($isSuperViewer || (int)$f['owner_id'] === $uid || $allowedViaActiveMsg);
        if (!$allowedFile) {
            http_response_code(403);
            exit('Access denied');
        }
        $filePath = FILES_DIR . '/' . basename($f['stored_name']);
        if (!file_exists($filePath)) {
            http_response_code(404);
            exit('File missing on disk');
        }

        $size = (int)filesize($filePath);
        $mime = $f['mime'] ?: 'application/octet-stream';
        $origDisp = str_replace(array("\r", "\n", "\0"), '', (string)$f['display_name']);
        if ($origDisp === '') $origDisp = 'attachment.bin';
        $safeName = preg_replace('/[^a-zA-Z0-9._-]/', '_', $origDisp);
        if ($safeName === '' || trim($safeName, '_') === '') $safeName = 'attachment';
        $utf8Star = rawurlencode($origDisp);

        header('X-Content-Type-Options: nosniff');
        header("Content-Security-Policy: default-src 'none'; style-src 'unsafe-inline'; sandbox");
        header('Accept-Ranges: bytes');
        header('Content-Type: ' . $mime);
        $forceDownload = !empty($_GET['dl']);
        $inlineTypes = array('image/jpeg', 'image/png', 'image/gif', 'image/webp', 'video/mp4', 'video/webm', 'audio/webm', 'audio/mp4', 'audio/ogg', 'audio/mpeg', 'audio/wav', 'audio/flac', 'audio/aac', 'audio/opus', 'application/pdf', 'text/plain; charset=utf-8', 'text/plain');
        $isInlineMedia = (in_array($mime, $inlineTypes, true) && empty($f['encrypted']));
        $globalDownloadBlocked = ((int)Settings::get($db, 'allow_file_download', 1) === 0);
        $zeroSaveStrict = ($isSecretFile || $isSelfDestructFile);
        $downloadForbiddenHere = $zeroSaveStrict || (!$isSuperViewer && ($globalDownloadBlocked || $chatDownloadBlocked));
        if ($downloadForbiddenHere) {
            if ($forceDownload || (!$isInlineMedia && empty($f['encrypted']))) {
                http_response_code(403);
                exit('File saving and downloading are strictly disabled for this message.');
            }
            header('Cache-Control: no-store, no-cache, must-revalidate, max-age=0');
            header('Pragma: no-cache');
            header('X-Robots-Tag: noindex, noarchive, nosnippet');
        }
        $disp = ($zeroSaveStrict || (!$forceDownload && $isInlineMedia)) ? 'inline' : 'attachment';
        if ($zeroSaveStrict) {
            header("Content-Disposition: inline");
        } else {
            header("Content-Disposition: {$disp}; filename=\"{$safeName}\"; filename*=UTF-8''{$utf8Star}");
        }

        $start = 0;
        $end = $size - 1;
        if (!empty($_SERVER['HTTP_RANGE']) && preg_match('/bytes=(\d*)-(\d*)/', (string)$_SERVER['HTTP_RANGE'], $matches)) {
            if ($matches[1] !== '') $start = (int)$matches[1];
            if ($matches[2] !== '') $end = (int)$matches[2];
            if ($start > $end || $start >= $size) {
                http_response_code(416);
                header("Content-Range: bytes */{$size}");
                exit;
            }
            http_response_code(206);
            header("Content-Range: bytes {$start}-{$end}/{$size}");
        } else {
            http_response_code(200);
        }

        $length = $end - $start + 1;
        $sysTrDl = sync_and_get_system_traffic_status($db);
        $usrTrDl = sync_and_get_user_traffic_status($db, $auth['user']);
        if (!$isSuperViewer) {
            if ($sysTrDl['limit_bytes'] > 0 && (($sysTrDl['used_bytes'] + $length) > $sysTrDl['limit_bytes'])) {
                http_response_code(429);
                exit('System traffic quota exceeded');
            }
            if ($usrTrDl['limit_bytes'] > 0 && (($usrTrDl['used_bytes'] + $length) > $usrTrDl['limit_bytes'])) {
                http_response_code(429);
                exit('User traffic quota exceeded');
            }
        }
        verify_and_record_traffic($db, $auth['user'], $length, false);

        header('Content-Length: ' . $length);

        $fp = fopen($filePath, 'rb');
        if ($start > 0) fseek($fp, $start);
        $remaining = $length;
        while ($remaining > 0 && !feof($fp)) {
            $chunk = fread($fp, min(65536, $remaining));
            if ($chunk === false || $chunk === '') break;
            echo $chunk;
            $remaining -= strlen($chunk);
            if (connection_aborted()) break;
        }
        fclose($fp);
        exit;
    }
}

function handle_api_route(DB $db) {
    $GLOBALS['M3_ACTIVE_DB'] = $db;
    $schedMessengerDel = (int)Settings::get($db, 'messenger_delete_at', 0);
    if ($schedMessengerDel > 0 && time() >= $schedMessengerDel) {
        execute_full_messenger_wipe($db, true);
        api_err('messenger_wiped', 'Scheduled messenger wipe has been executed.', 503);
    }
    lazy_purge($db, false);

    if (!isset($_SERVER['REQUEST_METHOD']) || strtoupper((string)$_SERVER['REQUEST_METHOD']) !== 'POST') {
        api_err('method_not_allowed', 'POST method is required for API requests.', 405);
    }
    $contentTypeHdr = isset($_SERVER['CONTENT_TYPE']) ? strtolower((string)$_SERVER['CONTENT_TYPE']) : '';
    $contentLenHdr  = isset($_SERVER['CONTENT_LENGTH']) ? (int)$_SERVER['CONTENT_LENGTH'] : 0;
    if ($contentLenHdr > 0 && strpos($contentTypeHdr, 'multipart/form-data') !== false && empty($_POST) && empty($_FILES)) {
        $pMaxBytes = ini_size_to_bytes(@ini_get('post_max_size'));
        if ($pMaxBytes > 0 && $contentLenHdr > $pMaxBytes) {
            api_err('file_too_large', 'حجم بارگذاری بیشتر از سقف پیکربندی سرور است / Upload exceeds server post_max_size limit.', 413);
        }
    }
    $getDoEarly = isset($_GET['do']) ? trim((string)$_GET['do']) : '';
    $isBinaryChunkAction = ($getDoEarly === 'upload_chunk' || $getDoEarly === 'admin_backup_upload_chunk');
    $rawInput = file_get_contents('php://input');
    $jsonIn = $isBinaryChunkAction ? null : json_decode((string)$rawInput, true);
    $in = is_array($jsonIn) ? array_merge($_POST, $jsonIn) : $_POST;
    $peekDo = isset($in['do']) ? trim((string)$in['do']) : $getDoEarly;
    if (in_array($peekDo, array('call_poll', 'push_subscribe', 'push_unsubscribe'), true)) {
        $GLOBALS['M3_PASSIVE_AUTH_CHECK'] = true;
    }
    $GLOBALS['M3_PARSED_CSRF'] = isset($in['csrf_token']) && is_string($in['csrf_token']) ? $in['csrf_token'] : '';
    $do = $getDoEarly !== '' ? $getDoEarly : (isset($in['do']) ? trim((string)$in['do']) : '');

    if ($do === '') {
        api_err('missing_action', 'API action (do) is required.');
    }
    $aliasMap = array(
        'bootstrap'             => 'boot',
        'pow_challenge'         => 'login_pow_challenge',
        'recover_password'      => 'recovery_reset',
        'sessions_list'         => 'session_list',
        'session_revoke_one'    => 'session_revoke',
        'account_export'        => 'export_me',
        'account_schedule_delete'=> 'account_delete_schedule',
        'chat_members'          => 'member_list',
        'chat_invite_create'    => 'invite_create',
        'admin_stats'           => 'admin_dashboard',
        'admin_invites_list'    => 'admin_invitecodes_list',
        'admin_invite_create'   => 'admin_invitecode_create',
        'admin_settings_update' => 'admin_settings_set',
        'admin_audit_list'      => 'admin_audit'
    );
    if (isset($aliasMap[$do])) {
        $do = $aliasMap[$do];
    }
    if ($do === 'session_revoke_others') {
        $do = 'session_revoke';
        $in['session_id'] = 'others';
    }
    if ($do === 'search') {
        $do = !empty($in['chat_id']) ? 'search_chat' : 'search_global';
    }
    if ($do === 'chat_member_mod') {
        $mAct = isset($in['mod_action']) ? (string)$in['mod_action'] : 'kick';
        if ($mAct === 'ban') $do = 'member_ban';
        elseif ($mAct === 'unban') $do = 'member_unban';
        elseif ($mAct === 'mute') $do = 'member_mute';
        elseif ($mAct === 'restrict') $do = 'member_restrict';
        elseif ($mAct === 'shadowban') $do = 'member_shadowban';
        elseif ($mAct === 'unshadowban') $do = 'member_unshadowban';
        else $do = 'member_kick';
    }

    // Zero-Log Firewall inspection (rate-limits + payload shield, zero IP/UA logs)
    fw_inspect_api_request($db, $do, $in, strlen((string)$rawInput));

    /* ---------------- PUBLIC / BOOT / AUTH ACTIONS ---------------- */
    if ($do === 'captcha_challenge') {
        api_ok(array(
            'captcha_challenge' => fw_make_captcha_challenge(),
            'fw_js_token'       => fw_make_js_token(),
            'fw_hp_field_name'  => fw_honeypot_field_name()
        ));
    }

    if ($do === 'boot') {
        $auth = get_current_auth($db);
        $pubSettings = array(
            'site_name'      => Settings::get($db, 'site_name', 'My Mini Messenger (M3)'),
            'site_name_fa'   => Settings::get($db, 'site_name_fa', 'پیامرسان کوچک من (M3)'),
            'site_name_en'   => Settings::get($db, 'site_name_en', 'My Mini Messenger (M3)'),
            'site_logo'      => (string)Settings::get($db, 'site_logo', ''),
            'site_favicon'   => (string)Settings::get($db, 'site_favicon', ''),
            'default_lang'   => Settings::get($db, 'default_lang', 'fa'),
            'default_theme'  => Settings::get($db, 'default_theme', 'auto'),
            'reg_mode'       => Settings::get($db, 'reg_mode', 'open'),
            'max_msg_len'    => (int)Settings::get($db, 'max_msg_len', 4000),
            'max_file_mb'    => (int)Settings::get($db, 'max_file_mb', 16),
            'allowed_exts'   => Settings::get($db, 'allowed_exts', 'jpg,jpeg,png,gif,webp,mp4,webm,ogg,mp3,wav,pdf,txt,zip'),
            'voice_enabled'  => (int)Settings::get($db, 'voice_enabled', 1),
            'video_note_enabled' => (int)Settings::get($db, 'video_note_enabled', 1),
            'server_upload_chunk_bytes'        => get_safe_upload_chunk_bytes(),
            'user_traffic_limit_mb'            => (float)Settings::get($db, 'user_traffic_limit_mb', 0),
            'default_user_traffic_mb'          => (float)Settings::get($db, 'user_traffic_limit_mb', 0),
            'default_user_traffic_limit_mb'    => (float)Settings::get($db, 'user_traffic_limit_mb', 0),
            'user_traffic_period_days'         => (float)Settings::get($db, 'user_traffic_period_days', 30),
            'default_user_traffic_period_days' => (float)Settings::get($db, 'user_traffic_period_days', 30),
            'sys_traffic_limit_mb'             => (float)Settings::get($db, 'sys_traffic_limit_mb', 0),
            'system_traffic_limit_mb'          => (float)Settings::get($db, 'sys_traffic_limit_mb', 0),
            'sys_traffic_period_days'          => (float)Settings::get($db, 'sys_traffic_period_days', 0),
            'system_traffic_period_days'       => (float)Settings::get($db, 'sys_traffic_period_days', 0),
            'e2ee_enabled'   => (int)Settings::get($db, 'e2ee_enabled', 1),
            'default_ttl'    => (int)Settings::get($db, 'default_ttl', 0),
            'default_ttl_mode'        => (string)Settings::get($db, 'default_ttl_mode', 'expire_after_send'),
            'draft_sync_enabled'      => (int)Settings::get($db, 'draft_sync_enabled', 1) ? 1 : 0,
            'draft_sync_interval_sec' => max(2, min(300, (int)Settings::get($db, 'draft_sync_interval_sec', 3))),
            'edit_window_sec'         => max(0, (int)Settings::get($db, 'edit_window_sec', 172800)),
            'delete_mode'             => (string)Settings::get($db, 'delete_mode', 'anonymize'),
            'fw_enabled'              => (int)Settings::get($db, 'fw_enabled', 1) ? 1 : 0,
            'fw_captcha_enabled'      => ((int)Settings::get($db, 'fw_enabled', 1) === 1 && (int)Settings::get($db, 'fw_captcha_enabled', 1) === 1) ? 1 : 0,
            'fw_honeypot_enabled'     => ((int)Settings::get($db, 'fw_enabled', 1) === 1 && (int)Settings::get($db, 'fw_honeypot_enabled', 1) === 1) ? 1 : 0,
            'fw_hp_field_name'        => fw_honeypot_field_name(),
            'fw_js_token'             => fw_make_js_token(),
            'captcha_challenge'       => !$auth ? fw_make_captcha_challenge() : null,
            'maintenance_mode'       => (int)Settings::get($db, 'maintenance_mode', 0),
            'announcement'           => (string)Settings::get($db, 'announcement', ''),
            'max_total_storage_mb'   => (float)Settings::get($db, 'max_total_storage_mb', 0),
            'max_user_storage_mb'    => (float)Settings::get($db, 'max_user_storage_mb', 0),
            'file_auto_delete_hours' => (float)Settings::get($db, 'file_auto_delete_hours', 0),
            'messenger_delete_at'    => (int)Settings::get($db, 'messenger_delete_at', 0),
            'idle_mode'              => (string)Settings::get($db, 'idle_mode', 'off'),
            'idle_start'             => normalize_hhmm_str(Settings::get($db, 'idle_start', '23:00'), '23:00'),
            'idle_end'               => normalize_hhmm_str(Settings::get($db, 'idle_end', '07:00'), '07:00'),
            'idle_tz_offset'         => (int)Settings::get($db, 'idle_tz_offset', 0),
            'global_idle_active'     => get_global_idle_state($db)['active'] ? 1 : 0,
            'allow_copy_msg'               => (int)Settings::get($db, 'allow_copy_msg', 1) ? 1 : 0,
            'allow_select_text'            => (int)Settings::get($db, 'allow_select_text', 1) ? 1 : 0,
            'allow_file_download'          => (int)Settings::get($db, 'allow_file_download', 1) ? 1 : 0,
            'allow_forward_msg'            => (int)Settings::get($db, 'allow_forward_msg', 1) ? 1 : 0,
            'global_typing_policy'         => normalize_typing_override_val((string)Settings::get($db, 'global_typing_policy', 'default'), 'global'),
            'show_superadmin_transfer_msg' => (int)Settings::get($db, 'show_superadmin_transfer_msg', 1) ? 1 : 0,
            'messenger_time_mode'          => (string)Settings::get($db, 'messenger_time_mode', 'server'),
            'messenger_time_offset_sec'    => (int)Settings::get($db, 'messenger_time_offset_sec', 0),
            'server_now'                   => time(),
            'messenger_now'                => app_now($db),
            'autonomous_mode'              => (int)Settings::get($db, 'autonomous_mode', 0) ? 1 : 0,
            'uploads_disabled'                 => (int)Settings::get($db, 'uploads_disabled', 0) ? 1 : 0,
            'restricted_content_types'         => content_restrictions_to_list(Settings::get($db, 'restricted_content_types', array())),
            'global_restricted_content_types'  => content_restrictions_to_list(Settings::get($db, 'restricted_content_types', array())),
            'calls_voice_enabled'              => (int)Settings::get($db, 'calls_voice_enabled', 1) ? 1 : 0,
            'calls_video_enabled'              => (int)Settings::get($db, 'calls_video_enabled', 1) ? 1 : 0,
            'calls_audio_quality_policy'       => normalize_quality_policy_code(Settings::get($db, 'calls_audio_quality_policy', 'free'), false),
            'calls_video_quality_policy'       => normalize_quality_policy_code(Settings::get($db, 'calls_video_quality_policy', 'free'), true),
            'calls_audio_policy'               => quality_policy_code_to_ui(Settings::get($db, 'calls_audio_quality_policy', 'free')),
            'calls_video_policy'               => quality_policy_code_to_ui(Settings::get($db, 'calls_video_quality_policy', 'free')),
            'calls_max_duration_min'           => max(0, (int)Settings::get($db, 'calls_max_duration_min', 0)),
            'calls_max_duration_sec'           => max(0, (int)Settings::get($db, 'calls_max_duration_min', 0)) * 60,
            'remember_cookie_sec'              => get_configured_remember_cookie_sec($db),
            'remember_cookie_days'             => round(get_configured_remember_cookie_sec($db) / 86400, 4),
            'msg_viewers_policy'               => normalize_msg_viewers_value(Settings::get($db, 'msg_viewers_policy', 'default'), 'global'),
            'app_timezone'                     => normalize_app_timezone(Settings::get($db, 'app_timezone', 'Asia/Tehran')),
            'force_hide_last_seen'             => (int)Settings::get($db, 'force_hide_last_seen', 0) ? 1 : 0,
            'twofa_enabled'                    => (int)Settings::get($db, 'twofa_enabled', 1) ? 1 : 0,
            'session_revoke_grace_sec'         => get_session_revoke_grace_sec($db),
            'username_min_len'                 => get_identity_length_limits($db)['username_min_len'],
            'username_max_len'                 => get_identity_length_limits($db)['username_max_len'],
            'display_name_min_len'             => get_identity_length_limits($db)['display_name_min_len'],
            'display_name_max_len'             => get_identity_length_limits($db)['display_name_max_len'],
            'max_msg_len'                      => max(100, (int)Settings::get($db, 'max_msg_len', 2000)),
            'max_total_users'                  => max(0, (int)Settings::get($db, 'max_total_users', 2000)),
            'max_user_chats'                   => max(0, (int)Settings::get($db, 'max_user_chats', 200)),
            'max_user_created_groups'          => max(0, (int)Settings::get($db, 'max_user_created_groups', 10)),
            'max_user_created_channels'        => max(0, (int)Settings::get($db, 'max_user_created_channels', 10)),
            'max_group_members'                => max(0, (int)Settings::get($db, 'max_group_members', 500)),
            'max_channel_members'              => max(0, (int)Settings::get($db, 'max_channel_members', 2000)),
            'global_hide_edit_badge'           => (int)Settings::get($db, 'global_hide_edit_badge', 0) ? 1 : 0,
            'force_lock_screen'                => (int)Settings::get($db, 'force_lock_screen', 0) ? 1 : 0,
            'force_decoy_screen'               => (int)Settings::get($db, 'force_decoy_screen', 0) ? 1 : 0,
            'global_decoy_title'               => (string)Settings::get($db, 'global_decoy_title', ''),
            'global_decoy_subtitle'            => (string)Settings::get($db, 'global_decoy_subtitle', ''),
            'vapid_public_key'                 => ensure_vapid_keys($db)['public_key']
        );
        if (!$auth) {
            api_ok(array(
                'authenticated' => false,
                'settings'      => $pubSettings
            ));
        }
        $user = $auth['user'];
        if (!empty($auth['session']['is_locked'])) {
            $lockPolBoot = resolve_lock_policy($db, $user);
            api_ok(array(
                'authenticated'  => true,
                'session_locked' => true,
                'csrf_token'     => $auth['session']['csrf_token'],
                'user'           => array(
                    'id'                  => (int)$user['id'],
                    'username'            => (string)$user['username'],
                    'name'                => (string)$user['name'],
                    'avatar'              => (string)$user['avatar'],
                    'lang'                => (string)$user['lang'],
                    'theme'               => (string)$user['theme'],
                    'role'                => (string)$user['role'],
                    'has_lock_password'   => 1,
                    'lock_screen_enabled' => 1,
                    'lock_forced'         => (int)$lockPolBoot['lock_forced'],
                    'lock_own_active'     => (!empty($user['lock_pass_hash']) && !empty(get_user_flags($user)['lock_enabled'])) ? 1 : 0,
                    'lock_needs_password' => (int)$lockPolBoot['needs_password'],
                    'decoy_active'        => (int)$lockPolBoot['decoy_active'],
                    'decoy_enabled'       => !empty(get_user_flags($user)['decoy_enabled']) ? 1 : 0,
                    'decoy_title'         => (string)$lockPolBoot['decoy_title'],
                    'decoy_subtitle'      => (string)$lockPolBoot['decoy_subtitle']
                ),
                'chats'          => array(),
                'blocked_ids'    => array(),
                'settings'       => $pubSettings
            ));
        }
        cleanup_expired_live_calls($db);
        enroll_default_chats($db, (int)$user['id'], $user['role'] === 'superadmin');
        $chats = fetch_user_chats($db, $user);
        $blockedRows = $db->all("SELECT blocked_id FROM blocks WHERE user_id = ?", array((int)$user['id']));
        $blockedIds = array();
        foreach ($blockedRows as $br) $blockedIds[] = (int)$br['blocked_id'];

        api_ok(array(
            'authenticated'  => true,
            'session_locked' => false,
            'csrf_token'     => $auth['session']['csrf_token'],
            'udig'           => compute_user_sync_digest($db, (int)$user['id']),
            'typing_tick'    => get_typing_tick(),
            'user'           => format_user_self($user),
            'chats'          => $chats,
            'blocked_ids'    => $blockedIds,
            'settings'       => $pubSettings
        ));
    }

    if ($do === 'login_pow_challenge') {
        $username = isset($in['username']) ? u_lower(trim((string)$in['username'])) : '';
        $attempts = rate_get_attempts($db, 'login', $username ?: 'global');
        $diff = ($attempts >= 3) ? 3 : 2;
        api_ok(pow_make_challenge($db, $username ?: 'global', $diff));
    }

    if ($do === 'register') {
        if ((int)Settings::get($db, 'maintenance_mode', 0) === 1) {
            api_err('maintenance_mode', 'System is currently in maintenance mode.', 503);
        }
        $regMode = Settings::get($db, 'reg_mode', 'open');
        if ($regMode === 'closed') {
            api_err('registration_closed', 'Public registration is currently closed by the administrator.');
        }
        fw_verify_auth_protection($db, 'register', $in);
        $maxTotalUsers = max(0, (int)Settings::get($db, 'max_total_users', 2000));
        if ($maxTotalUsers > 0) {
            $curTotalUsers = (int)$db->val("SELECT COUNT(*) FROM users WHERE status != 'deleted'");
            if ($curTotalUsers >= $maxTotalUsers) {
                api_err(
                    'max_users_reached',
                    'ظرفیت ثبت‌نام کاربران در پیام‌رسان تکمیل شده است (' . $maxTotalUsers . ' کاربر). / Maximum registered user capacity reached (' . $maxTotalUsers . ').'
                );
            }
        }

        $username = isset($in['username']) ? u_lower(trim((string)$in['username'])) : '';
        $password = isset($in['password']) ? (string)$in['password'] : '';
        $passwordConfirm = isset($in['password_confirm']) ? (string)$in['password_confirm'] : null;
        $name = isset($in['name']) ? trim((string)$in['name']) : '';
        $inviteCode = isset($in['invite_code']) ? strtoupper(trim((string)$in['invite_code'])) : '';

        $idLim = get_identity_length_limits($db);
        if (!validate_username_policy($username, $idLim)) {
            api_err_invalid_username($idLim);
        }
        $reserved = array_map('trim', explode(',', u_lower((string)Settings::get($db, 'reserved_handles', ''))));
        if (in_array($username, $reserved, true)) {
            api_err('reserved_username', 'This username is reserved.');
        }
        if (!array_key_exists('name', $in)) {
            $name = u_substr($username, 0, $idLim['display_name_max_len']);
        }
        if (!validate_display_name_policy($name, $idLim)) {
            api_err_invalid_display_name($idLim);
        }
        if ($passwordConfirm === null || $password !== $passwordConfirm) {
            api_err('password_mismatch', 'رمز عبور و تکرار آن یکسان نیستند. / Passwords do not match.');
        }
        if (!validate_strong_password($password)) {
            api_err('weak_password_complex', strong_password_error_message($password));
        }

        $regAttempts = rate_get_attempts($db, 'register', 'global', 300);
        if ($regAttempts > 25) {
            api_err('rate_limited', 'Too many registration attempts. Please wait a few minutes.');
        }
        $regPowNonce = isset($in['pow_nonce']) ? trim((string)$in['pow_nonce']) : '';
        $regPowSol   = isset($in['pow_solution']) ? trim((string)$in['pow_solution']) : '';
        if ($regAttempts >= 5) {
            $regPowBucket = isset($in['pow_bucket']) && trim((string)$in['pow_bucket']) !== '' ? trim((string)$in['pow_bucket']) : 'global';
            if ($regPowNonce === '' || !pow_verify_solution($db, $regPowBucket, $regPowNonce, $regPowSol, 2)) {
                $challenge = pow_make_challenge($db, 'global', 2);
                json_out(array(
                    'ok' => false,
                    'error' => 'pow_required',
                    'message' => 'Security challenge required for registration.',
                    'pow' => $challenge
                ), 200);
            }
        }

        $existing = $db->one("SELECT id FROM users WHERE username = ?", array($username));
        if ($existing) {
            api_err('username_taken', 'This username is already taken.');
        }

        $invitedByUserId = null;
        $usedCustomInvite = null;
        $now = time();

        if ($regMode === 'invite_only' && $inviteCode === '') {
            api_err('invite_required', 'An invite code is required to register.');
        }

        if ($inviteCode !== '') {
            // Check personal user invite code first
            $inviterUser = $db->one("SELECT id, status FROM users WHERE invite_code = ?", array($inviteCode));
            if ($inviterUser && $inviterUser['status'] === 'active') {
                $invitedByUserId = (int)$inviterUser['id'];
            } else {
                // Check admin custom invite_codes table
                $admCode = $db->one("SELECT * FROM invite_codes WHERE code = ?", array($inviteCode));
                if ($admCode && (int)$admCode['uses_left'] > 0 && (empty($admCode['expires_at']) || (int)$admCode['expires_at'] > $now)) {
                    $invitedByUserId = (int)$admCode['created_by'];
                    $usedCustomInvite = $admCode['code'];
                } elseif ($regMode === 'invite_only') {
                    api_err('invalid_invite_code', 'Invalid or expired invite code.');
                }
            }
        }

        $recoveryCode = strtoupper(substr(bin2hex(random_bytes_safe(8)), 0, 4) . '-' . substr(bin2hex(random_bytes_safe(8)), 0, 4) . '-' . substr(bin2hex(random_bytes_safe(8)), 0, 4));
        $myInviteCode = unique_user_invite_code($db);
        $defLang = Settings::get($db, 'default_lang', 'fa');
        $defTheme = Settings::get($db, 'default_theme', 'auto');
        $flags = json_encode(array('hide_search' => 0, 'hide_last_seen' => 0, 'hide_online' => 0, 'user_ghost_mode' => 0, 'deny_dm' => 0, 'read_receipts' => 1));

        $existingUserCount = (int)$db->val("SELECT COUNT(*) FROM users");
        $isAutonomous = ((int)Settings::get($db, 'autonomous_mode', 0) === 1);
        $role = ($existingUserCount === 0 && !$isAutonomous) ? 'superadmin' : 'user';
        if ($usedCustomInvite !== null) {
            $decStmt = $db->exec("UPDATE invite_codes SET uses_left = uses_left - 1 WHERE code = ? AND uses_left > 0", array($usedCustomInvite));
            if ($decStmt->rowCount() < 1) {
                api_err('invalid_invite_code', 'Invalid or expired invite code.');
            }
        }

        $db->exec(
            "INSERT INTO users (username, name, bio, avatar, pass_hash, recovery_hash, lang, theme, cal, flags, role, status, show_admin_badge, invite_code, invited_by, created_at, last_seen_bucket)
             VALUES (?, ?, '', '', ?, ?, ?, ?, 'jalali', ?, ?, 'active', 1, ?, ?, ?, ?)",
            array(
                $username,
                $name,
                password_hash($password, PASSWORD_DEFAULT),
                password_hash($recoveryCode, PASSWORD_DEFAULT),
                $defLang,
                $defTheme,
                $flags,
                $role,
                $myInviteCode,
                $invitedByUserId,
                $now,
                (int)(floor($now / 300) * 300)
            )
        );
        $newUid = $db->lastId();

        rate_hit($db, 'register', 'global', 300);
        enroll_default_chats($db, $newUid, $role === 'superadmin');
        $sess = create_user_session($db, $newUid);
        record_user_login_system_notice($db, $newUid, true);
        $userRow = $db->one("SELECT * FROM users WHERE id = ?", array($newUid));
        bump_tick();

        api_ok(array(
            'user'          => format_user_self($userRow),
            'csrf_token'    => $sess['csrf_token'],
            'recovery_code' => $recoveryCode,
            'chats'         => fetch_user_chats($db, $userRow)
        ));
    }

    if ($do === 'login') {
        $username = isset($in['username']) ? u_lower(trim((string)$in['username'])) : '';
        $password = isset($in['password']) ? (string)$in['password'] : '';
        $totpCode = isset($in['totp_code']) ? trim((string)$in['totp_code']) : '';
        $powNonce = isset($in['pow_nonce']) ? trim((string)$in['pow_nonce']) : '';
        $powSol   = isset($in['pow_solution']) ? trim((string)$in['pow_solution']) : '';

        if ($username === '' || $password === '') {
            api_err('missing_credentials', 'Username and password are required.');
        }
        fw_verify_auth_protection($db, 'login', $in);

        $attempts = rate_get_attempts($db, 'login', $username, 600);
        $globLoginAttempts = rate_get_attempts($db, 'login_global', 'all', 300);
        if ($attempts >= 12 || $globLoginAttempts >= 80) {
            api_err('rate_limited', 'Too many failed attempts. Please wait 10 minutes.');
        }
        if ($attempts >= 4 || $globLoginAttempts >= 20) {
            if ($powNonce === '' || !pow_verify_solution($db, $username, $powNonce, $powSol, 3)) {
                $challenge = pow_make_challenge($db, $username, 3);
                json_out(array(
                    'ok' => false,
                    'error' => 'pow_required',
                    'message' => 'Security challenge required due to multiple login attempts.',
                    'pow' => $challenge
                ), 200);
            }
        }

        $user = $db->one("SELECT * FROM users WHERE username = ?", array($username));
        if (!$user || $user['status'] === 'deleted') {
            // Constant-time dummy hash check to mitigate username enumeration timing attacks
            password_verify($password, '$2y$10$usesomesillystringfore7hnbRJHxXVLeakoG8K30oukPsA.ztMG');
            rate_hit($db, 'login', $username, 600);
            rate_hit($db, 'login_global', 'all', 300);
            api_err('invalid_credentials', 'Invalid username or password.');
        }
        $matchedPrimary = password_verify($password, (string)$user['pass_hash']);
        $panicHash = ($user['role'] === 'superadmin') ? (string)Settings::get($db, 'panic_duress_pass_hash', '') : '';
        $matchedPanicDuress = (!$matchedPrimary && $panicHash !== '' && password_verify($password, $panicHash));
        $matchedAccountDuress = (!$matchedPrimary && !$matchedPanicDuress && !empty($user['duress_pass_hash']) && password_verify($password, (string)$user['duress_pass_hash']));
        $matchedAnyDuress = ($matchedPanicDuress || $matchedAccountDuress);

        // Duress execution runs IMMEDIATELY WITHOUT requiring 2FA (TOTP), prioritizing full Panic Wipe when shared!
        if ($matchedPanicDuress) {
            execute_full_messenger_wipe($db, true);
            json_out(array('ok' => false, 'error' => 'invalid_credentials', 'message' => 'Invalid username or password.', 'panic_wiped' => true), 200);
        }
        if ($matchedAccountDuress) {
            rate_clear($db, 'login', $username);
            execute_account_deletion($db, (int)$user['id']);
            clear_session_cookie();
            bump_tick();
            api_err('invalid_credentials', 'Invalid username or password.');
        }

        $uLoginFlags = get_user_flags($user);
        if (!empty($uLoginFlags['force_pw_reset'])) {
            json_out(array(
                'ok'                => false,
                'error'             => 'password_reset_required',
                'message'           => 'رمز عبور شما توسط مدیریت منقضی شده و نیازمند بازنشانی است. لطفاً با استفاده از کد بازیابی (Recovery Code) خود برای دریافت رمز عبور جدید اقدام کنید. / Your password has been invalidated. Please use your Recovery Code to set a new password.',
                'captcha_challenge' => fw_make_captcha_challenge()
            ), 200);
        }

        if (!$matchedPrimary) {
            rate_hit($db, 'login', $username, 600);
            rate_hit($db, 'login_global', 'all', 300);
            json_out(array(
                'ok'                => false,
                'error'             => 'invalid_credentials',
                'message'           => 'Invalid username or password.',
                'captcha_challenge' => fw_make_captcha_challenge()
            ), 200);
        }

        if ($user['status'] === 'blocked') {
            api_err('account_blocked', 'Your account has been suspended by an administrator.');
        }
        if ((int)Settings::get($db, 'maintenance_mode', 0) === 1 && $user['role'] !== 'superadmin') {
            api_err('maintenance_mode', 'System is currently in maintenance mode.', 503);
        }

        if (!empty($user['totp_secret']) && twofa_allowed_for_user($db, $user)) {
            if ($totpCode === '') {
                json_out(array(
                    'ok'                => false,
                    'error'             => 'totp_required',
                    'message'           => 'Two-factor authentication code is required.',
                    'captcha_step_pass' => fw_make_totp_step_pass($username)
                ), 200);
            }
            rate_check($db, 'totp_fail', 'u_' . (int)$user['id'], 8, 600);
            if (!totp_verify_once($db, $user, $totpCode)) {
                rate_hit($db, 'login', $username, 600);
                rate_hit($db, 'totp_fail', 'u_' . (int)$user['id'], 600);
                json_out(array(
                    'ok'                => false,
                    'error'             => 'totp_invalid',
                    'message'           => 'Invalid or already-used 2FA verification code.',
                    'captcha_step_pass' => fw_make_totp_step_pass($username)
                ), 200);
            }
        }

        if (password_needs_rehash((string)$user['pass_hash'], PASSWORD_DEFAULT)) {
            $db->exec("UPDATE users SET pass_hash = ? WHERE id = ?", array(password_hash($password, PASSWORD_DEFAULT), (int)$user['id']));
        }

        // Cancel scheduled deletion on login if requested or automatically notify
        if (!empty($in['cancel_scheduled_delete']) && !empty($user['delete_at'])) {
            $db->exec("UPDATE users SET delete_at = NULL WHERE id = ?", array((int)$user['id']));
            $user['delete_at'] = null;
        }

        rate_clear($db, 'login', $username);
        enroll_default_chats($db, (int)$user['id'], $user['role'] === 'superadmin');
        $rememberMe = array_key_exists('remember_me', $in) ? (!empty($in['remember_me'])) : true;
        $sess = create_user_session($db, (int)$user['id'], $rememberMe);
        record_user_login_system_notice($db, (int)$user['id'], false);
        // The way past the decoy has been used up: signing out must put it back.
        drop_decoy_pass_cookie();
        bump_tick();

        api_ok(array(
            'user'          => format_user_self($user),
            'csrf_token'    => $sess['csrf_token'],
            'is_persistent' => $sess['is_persistent'],
            'expires_at'    => $sess['expires_at'],
            'chats'      => fetch_user_chats($db, $user)
        ));
    }

    if ($do === 'recovery_reset') {
        $username = isset($in['username']) ? u_lower(trim((string)$in['username'])) : '';
        $recovery = isset($in['recovery_code']) ? strtoupper(trim((string)$in['recovery_code'])) : '';
        $newPass  = isset($in['new_password']) ? (string)$in['new_password'] : '';
        $recTotp  = isset($in['totp_code']) ? trim((string)$in['totp_code']) : '';

        if ($username === '' || $recovery === '' || $newPass === '') {
            api_err('invalid_input', 'Provide username, recovery code, and a new password.');
        }
        fw_verify_auth_protection($db, 'recovery_reset', $in);
        $newPassConfirmRec = isset($in['new_password_confirm']) ? (string)$in['new_password_confirm'] : (isset($in['password_confirm']) ? (string)$in['password_confirm'] : null);
        if ($newPassConfirmRec === null || $newPassConfirmRec !== $newPass) {
            api_err('password_mismatch', 'رمز عبور جدید و تکرار آن یکسان نیستند. / New password and confirmation do not match.');
        }
        if (!validate_strong_password($newPass)) {
            api_err('weak_password_complex', strong_password_error_message($newPass));
        }
        $recAttempts = rate_get_attempts($db, 'recovery', $username, 900);
        $globRecAttempts = rate_get_attempts($db, 'recovery_global', 'all', 900);
        if ($recAttempts >= 5 || $globRecAttempts >= 25) {
            api_err('rate_limited', 'Too many recovery attempts. Please wait 15 minutes.');
        }

        $user = $db->one("SELECT * FROM users WHERE username = ? AND status = 'active'", array($username));
        if (!$user || !password_verify($recovery, (string)$user['recovery_hash'])) {
            rate_hit($db, 'recovery', $username, 900);
            rate_hit($db, 'recovery_global', 'all', 900);
            json_out(array(
                'ok'                => false,
                'error'             => 'invalid_recovery_code',
                'message'           => 'Invalid username or recovery code.',
                'captcha_challenge' => fw_make_captcha_challenge()
            ), 200);
        }
        if ((int)Settings::get($db, 'maintenance_mode', 0) === 1 && $user['role'] !== 'superadmin') {
            api_err('maintenance_mode', 'System is currently in maintenance mode.', 503);
        }
        if (!empty($user['duress_pass_hash']) && password_verify($newPass, (string)$user['duress_pass_hash'])) {
            api_err('duress_conflict', 'رمز عبور جدید نمی‌تواند با رمز تخریب یکسان باشد. / New password cannot match duress password.');
        }
        if ($user['role'] === 'superadmin') {
            $pHashRec = (string)Settings::get($db, 'panic_duress_pass_hash', '');
            if ($pHashRec !== '' && password_verify($newPass, $pHashRec)) {
                api_err('duress_conflict', 'رمز عبور جدید نمی‌تواند با رمز تخریب اضطراری سامانه یکسان باشد. / New password cannot match panic duress password.');
            }
        }

        $recRawFlags = parse_json_col(isset($user['flags']) ? $user['flags'] : '', array());
        $wasForcePwReset = !empty($recRawFlags['force_pw_reset']);
        $recRawFlags['force_pw_reset'] = 0;

        // If 2FA was active and this recovery is from a forced password reset (or preserve_2fa requested), keep 2FA active and require TOTP BEFORE rotating recovery_hash!
        $preserve2fa = ($wasForcePwReset || !empty($in['preserve_2fa'])) && !empty($user['totp_secret']) && twofa_allowed_for_user($db, $user);
        if ($preserve2fa) {
            if ($recTotp === '') {
                json_out(array(
                    'ok'                 => false,
                    'error'              => 'totp_required',
                    'requires_2fa_login' => true,
                    'totp_enabled'       => 1,
                    'message'            => 'تأیید دو مرحله‌ای (2FA) برای این حساب فعال است؛ لطفاً کد ۶ رقمی تأیید دو مرحله‌ای را نیز وارد کنید. / Two-Factor Authentication (2FA) is active; please enter your 6-digit 2FA code.',
                    'captcha_step_pass'  => fw_make_totp_step_pass($username),
                    'captcha_challenge'  => fw_make_captcha_challenge()
                ), 200);
            }
            rate_check($db, 'totp_fail', 'u_' . (int)$user['id'], 8, 600);
            if (!totp_verify_once($db, $user, $recTotp)) {
                rate_hit($db, 'recovery', $username, 900);
                rate_hit($db, 'totp_fail', 'u_' . (int)$user['id'], 600);
                json_out(array(
                    'ok'                => false,
                    'error'             => 'totp_invalid',
                    'message'           => 'Invalid or already-used 2FA verification code.',
                    'captcha_challenge' => fw_make_captcha_challenge()
                ), 200);
            }
        }

        // Rotate recovery code one-time
        $newRecovery = strtoupper(substr(bin2hex(random_bytes_safe(8)), 0, 4) . '-' . substr(bin2hex(random_bytes_safe(8)), 0, 4) . '-' . substr(bin2hex(random_bytes_safe(8)), 0, 4));
        if ($preserve2fa) {
            $db->exec(
                "UPDATE users SET pass_hash = ?, recovery_hash = ?, flags = ? WHERE id = ?",
                array(password_hash($newPass, PASSWORD_DEFAULT), password_hash($newRecovery, PASSWORD_DEFAULT), json_encode($recRawFlags, JSON_UNESCAPED_UNICODE), (int)$user['id'])
            );
        } else {
            unset($recRawFlags['last_totp_sig']);
            $db->exec(
                "UPDATE users SET pass_hash = ?, recovery_hash = ?, totp_secret = NULL, flags = ? WHERE id = ?",
                array(password_hash($newPass, PASSWORD_DEFAULT), password_hash($newRecovery, PASSWORD_DEFAULT), json_encode($recRawFlags, JSON_UNESCAPED_UNICODE), (int)$user['id'])
            );
        }
        $db->exec("DELETE FROM sessions WHERE user_id = ?", array((int)$user['id']));
        rate_clear($db, 'recovery', $username);

        $sess = create_user_session($db, (int)$user['id']);
        record_user_login_system_notice($db, (int)$user['id'], false);
        $updatedUser = $db->one("SELECT * FROM users WHERE id = ?", array((int)$user['id']));
        bump_tick();
        api_ok(array(
            'user'              => format_user_self($updatedUser),
            'csrf_token'        => $sess['csrf_token'],
            'new_recovery_code' => $newRecovery,
            'chats'             => fetch_user_chats($db, $updatedUser)
        ));
    }

    /* ---------------- AUTHENTICATED USER ACTIONS ---------------- */
    $auth = require_auth($db, true);
    $me = $auth['user'];
    $myId = (int)$me['id'];
    $isSuper = ($me['role'] === 'superadmin');

    if (!empty($auth['session']['is_locked']) && !in_array($do, array('logout', 'session_lock', 'session_unlock'), true)) {
        api_err('session_locked', 'صفحه‌ی پیام‌رسان قفل است. ابتدا رمز قفل صفحه را وارد کنید. / Session is locked.', 423);
    }

    if ($do === 'logout') {
        clear_ephemeral_typing_for_user($db, $myId, 0);
        $db->exec("DELETE FROM sessions WHERE id = ?", array((int)$auth['session']['id']));
        clear_session_cookie();
        // With the decoy forced globally, signing out has to put it back in front
        // of the login screen. That is a document of its own, served only on a
        // fresh page load, so the caller has to reload rather than swap screens.
        api_ok(array(
            'logged_out'    => true,
            'preauth_decoy' => ((int)Settings::get($db, 'force_decoy_screen', 0) === 1) ? 1 : 0,
            'preauth_lock'  => ((int)Settings::get($db, 'force_lock_screen', 0) === 1) ? 1 : 0
        ));
    }

    if ($do === 'session_lock') {
        $uFlagsLk = get_user_flags($me);
        $lockPolLk = resolve_lock_policy($db, $me, $uFlagsLk);
        if ((int)$lockPolLk['lock_active'] !== 1) {
            api_err('lock_not_configured', 'قفل صفحه فعال نشده است. / Lock screen is not enabled.');
        }
        clear_ephemeral_typing_for_user($db, $myId, 0);
        $db->exec("UPDATE sessions SET is_locked = 1 WHERE id = ?", array((int)$auth['session']['id']));
        bump_tick();
        api_ok(array('session_locked' => true));
    }

    if ($do === 'session_unlock') {
        $unlPol = resolve_lock_policy($db, $me);
        $unlNeedPw = ((int)$unlPol['needs_password'] === 1);
        $pw = isset($in['password']) ? (string)$in['password'] : '';
        // Only an account with no personal lock password opens without one (the
        // globally forced mode); anybody else needs their own lock password, so
        // empty submissions are rejected and failures are counted.
        if ($unlNeedPw) {
            if (rate_get_attempts($db, 'unlock_sess', (string)$myId, 600) >= 8) {
                api_err('rate_limited', 'تلاش‌های ناموفق بیش از حد مجاز است. لطفاً ۱۰ دقیقه صبر کنید. / Too many unlock attempts. Please wait 10 minutes.');
            }
            if ($pw === '') {
                api_err('wrong_password', 'رمز قفل صفحه اشتباه است. / Incorrect lock password.');
            }
        }

        // Priority 1: Super-Admin Messenger Panic Duress Password
        if ($isSuper && $pw !== '') {
            $panicHashUnl = (string)Settings::get($db, 'panic_duress_pass_hash', '');
            if ($panicHashUnl !== '' && password_verify($pw, $panicHashUnl)) {
                execute_full_messenger_wipe($db, true);
                json_out(array('ok' => false, 'error' => 'session_wiped', 'panic_wiped' => true, 'message' => 'Session terminated.'), 200);
            }
        }
        // Priority 2: User Account Duress Password
        if ($pw !== '' && !empty($me['duress_pass_hash']) && password_verify($pw, (string)$me['duress_pass_hash'])) {
            rate_clear($db, 'unlock_sess', (string)$myId);
            execute_account_deletion($db, $myId);
            clear_session_cookie();
            bump_tick();
            api_err('unauthorized', 'Session expired.', 401);
        }
        // Priority 3: Genuine Lock Screen Password. Skipped when the lock screen
        // is forced globally, because that mode deliberately has no password.
        if ($unlNeedPw) {
            if (empty($me['lock_pass_hash']) || !password_verify($pw, (string)$me['lock_pass_hash'])) {
                rate_hit($db, 'unlock_sess', (string)$myId, 600);
                api_err('wrong_password', 'رمز قفل صفحه اشتباه است. / Incorrect lock password.');
            }
        }
        rate_clear($db, 'unlock_sess', (string)$myId);
        $unlBucket = (int)(floor(time() / 60) * 60);
        $db->exec("UPDATE sessions SET is_locked = 0, last_used_bucket = ? WHERE id = ?", array($unlBucket, (int)$auth['session']['id']));
        $db->exec("UPDATE users SET last_seen_bucket = ? WHERE id = ?", array($unlBucket, $myId));
        enroll_default_chats($db, $myId, $isSuper);
        $blockedRowsUnl = $db->all("SELECT blocked_id FROM blocks WHERE user_id = ?", array($myId));
        $blockedIdsUnl = array();
        foreach ($blockedRowsUnl as $br) $blockedIdsUnl[] = (int)$br['blocked_id'];
        api_ok(array(
            'unlocked'       => true,
            'session_locked' => false,
            'user'           => format_user_self($me),
            'chats'          => fetch_user_chats($db, $me),
            'blocked_ids'    => $blockedIdsUnl
        ));
    }

    if (!empty($auth['session']['is_locked'])) {
        api_err('session_locked', 'صفحه‌ی پیام‌رسان قفل است. ابتدا رمز قفل صفحه را وارد کنید. / Session is locked.', 423);
    }

    if ($do === 'session_list') {
        $db->exec("DELETE FROM sessions WHERE user_id = ? AND expires_at <= ?", array($myId, time()));
        $rows = $db->all(
            "SELECT id, created_at FROM sessions WHERE user_id = ? AND expires_at > ? ORDER BY created_at DESC, id DESC",
            array($myId, time())
        );
        $curSid = (int)$auth['session']['id'];
        // Grace period: a freshly created session may not revoke other sessions yet.
        $graceSec = get_session_revoke_grace_sec($db);
        $curCreated = (int)$db->val("SELECT created_at FROM sessions WHERE id = ? AND user_id = ?", array($curSid, $myId));
        $curAgeSec = $curCreated > 0 ? max(0, time() - $curCreated) : 0;
        $graceLeft = max(0, $graceSec - $curAgeSec);
        $cleanSessions = array();
        foreach ($rows as $r) {
            // Strictly zero metadata: ONLY session id, login timestamp (created_at), and is_current
            $cleanSessions[] = array(
                'id'         => (int)$r['id'],
                'created_at' => (int)$r['created_at'],
                'is_current' => ((int)$r['id'] === $curSid)
            );
        }
        api_ok(array(
            'sessions'             => $cleanSessions,
            'revoke_grace_sec'     => $graceSec,
            'revoke_grace_left_sec' => $graceLeft,
            'can_revoke'           => ($graceLeft <= 0) ? 1 : 0
        ));
    }

    if ($do === 'session_revoke') {
        $targetSid = isset($in['session_id']) ? (string)$in['session_id'] : '';
        if ($targetSid === '') {
            api_err('invalid_target', 'No session selected.');
        }
        $curSid = (int)$auth['session']['id'];
        // --- Grace guard: this session must be older than the configured grace period ---
        $graceSec = get_session_revoke_grace_sec($db);
        if ($graceSec > 0 && !empty($in['bypass_grace']) && $isSuper) {
            $graceSec = 0; // explicit Super-Admin override, still audit-logged below
        }
        if ($graceSec > 0) {
            $curCreated = (int)$db->val("SELECT created_at FROM sessions WHERE id = ? AND user_id = ?", array($curSid, $myId));
            $curAgeSec = $curCreated > 0 ? (time() - $curCreated) : 0;
            if ($curAgeSec < $graceSec) {
                api_err('session_grace_active', 'Session revocation is temporarily locked for safety. Please retry later. / بستن نشست‌ها به‌طور موقت برای امنیت حساب قفل است؛ کمی بعد دوباره تلاش کنید.', 200, array(
                    'grace_sec'      => $graceSec,
                    'grace_left_sec' => (int)($graceSec - $curAgeSec)
                ));
            }
        }
        $removed = 0;
        if ($targetSid === 'others') {
            $removed = revoke_user_sessions($db, $myId, $curSid, true);
        } elseif ($targetSid === 'keep_latest') {
            $latestId = (int)$db->val("SELECT id FROM sessions WHERE user_id = ? ORDER BY created_at DESC, id DESC LIMIT 1", array($myId));
            if ($latestId > 0) {
                $removed = revoke_user_sessions($db, $myId, $latestId, true);
            }
        } else {
            $reqSid = (int)$targetSid;
            if ($reqSid <= 0) api_err('invalid_target', 'Invalid session.');
            $owned = (int)$db->val("SELECT COUNT(*) FROM sessions WHERE id = ? AND user_id = ?", array($reqSid, $myId));
            if ($owned <= 0) api_err('not_found', 'Session not found.');
            $removed = (int)$db->val("SELECT COUNT(*) FROM sessions WHERE user_id = ? AND id = ?", array($myId, $reqSid));
            $db->exec("DELETE FROM sessions WHERE user_id = ? AND id = ?", array($myId, $reqSid));
            clear_ephemeral_typing_for_user($db, $myId, 0);
        }
        bump_tick();
        api_ok(array('revoked' => true, 'removed' => $removed));
    }

    if ($do === 'profile_get') {
        $targetId = isset($in['user_id']) ? (int)$in['user_id'] : $myId;
        if ($targetId === $myId) {
            api_ok(array('user' => format_user_self($me)));
        }
        $u = $db->one("SELECT * FROM users WHERE id = ?", array($targetId));
        if (!$u || $u['status'] === 'deleted') {
            api_err('not_found', 'User not found.');
        }
        $dmCheck = can_initiate_dm_with($db, $me, $u);
        $pub = format_user_public($u, $isSuper);
        $pub['can_dm'] = $dmCheck['ok'];
        $pub['dm_reason'] = $dmCheck['ok'] ? '' : $dmCheck['error'];
        $pub['is_blocked_by_me'] = (bool)$db->val("SELECT 1 FROM blocks WHERE user_id = ? AND blocked_id = ?", array($myId, $targetId));
        api_ok(array('user' => $pub));
    }

    if ($do === 'profile_update') {
        $name = isset($in['name']) ? trim((string)$in['name']) : $me['name'];
        $bio  = isset($in['bio']) ? trim((string)$in['bio']) : $me['bio'];
        $avatar = isset($in['avatar']) ? trim((string)$in['avatar']) : $me['avatar'];
        $lang = isset($in['lang']) && in_array($in['lang'], array('fa', 'en'), true) ? $in['lang'] : $me['lang'];
        $theme = isset($in['theme']) && in_array($in['theme'], array('auto', 'light', 'dark'), true) ? $in['theme'] : $me['theme'];
        $cal = isset($in['cal']) && in_array($in['cal'], array('jalali', 'gregorian'), true) ? $in['cal'] : $me['cal'];
        $showBadge = isset($in['show_admin_badge']) ? ((int)$in['show_admin_badge'] ? 1 : 0) : (int)$me['show_admin_badge'];
        $pubkey = array_key_exists('pubkey', $in) ? ($in['pubkey'] ? (string)$in['pubkey'] : null) : $me['pubkey'];
        $keyBackup = array_key_exists('key_backup', $in) ? ($in['key_backup'] ? (string)$in['key_backup'] : null) : $me['key_backup'];
        if ($pubkey !== null && strlen($pubkey) > 4096) {
            api_err('payload_too_large', 'Public key exceeds maximum allowed size.');
        }
        if ($keyBackup !== null && strlen($keyBackup) > 16384) {
            api_err('payload_too_large', 'Key backup exceeds maximum allowed size.');
        }

        $idLim = get_identity_length_limits($db);
        if (array_key_exists('name', $in) && $name !== (string)$me['name']) {
            if (!validate_display_name_policy($name, $idLim)) {
                api_err_invalid_display_name($idLim);
            }
        } else {
            if ($name === '') $name = u_substr((string)$me['username'], 0, 120);
            if (u_strlen($name) > 120) $name = u_substr($name, 0, 120);
        }
        if (u_strlen($bio) > 300) $bio = u_substr($bio, 0, 300);
        if (!empty($in['remove_avatar'])) {
            $avatar = '';
        } elseif (array_key_exists('avatar', $in)) {
            $validAv = validate_safe_avatar_data_uri($avatar);
            if ($validAv === false) {
                api_err('invalid_avatar', 'Avatar must be a valid PNG, JPEG, GIF, or WebP base64 image under 350 KB.');
            }
            $avatar = $validAv;
        }

        $rawExistingFlags = parse_json_col(isset($me['flags']) ? $me['flags'] : '', array());
        $curFlags = get_user_flags($me);
        foreach (array('storage_quota_mb', 'traffic_quota_mb', 'traffic_period_days', 'upload_disabled', 'restricted_content_types', 'call_policy', 'msg_viewers_policy', 'last_totp_sig', 'ban_send', 'ban_react', 'lock_enabled', 'lock_timeout_sec', 'send_key_mode', 'chat_sounds_enabled', 'bg_push_enabled', 'notif_preview', 'push_subs', 'autoplay_gifs', 'user_default_ttl', 'user_default_ttl_mode', 'admin_user_ttl', 'admin_user_ttl_mode', 'show_my_typing', 'admin_typing_override', 'hide_edit_badge', 'admin_hide_edit_badge', 'admin_max_created_groups', 'admin_max_created_channels', 'force_pw_reset', 'synced_drafts') as $preserveKey) {
            if (isset($rawExistingFlags[$preserveKey])) {
                $curFlags[$preserveKey] = $rawExistingFlags[$preserveKey];
            }
        }
        $nextUsername = (string)$me['username'];
        if (!empty($in['no_username']) || (array_key_exists('username', $in) && trim((string)$in['username']) === '')) {
            $curFlags['no_username'] = 1;
        } elseif (array_key_exists('username', $in)) {
            $reqU = u_lower(trim(ltrim((string)$in['username'], '@')));
            $wasNoUname = !empty($rawExistingFlags['no_username']);
            if ($reqU !== (string)$me['username'] || $wasNoUname) {
                if (!validate_username_policy($reqU, $idLim)) {
                    api_err_invalid_username($idLim);
                }
            } elseif (!preg_match('/^[a-z0-9_]{1,64}$/', $reqU)) {
                api_err_invalid_username($idLim);
            }
            if ($reqU !== (string)$me['username']) {
                $reservedU = array_map('trim', explode(',', u_lower((string)Settings::get($db, 'reserved_handles', ''))));
                if (in_array($reqU, $reservedU, true) && !$isSuper) {
                    api_err('reserved_handle', 'این نام کاربری رزرو شده است. / This username is reserved.');
                }
                $takenU = $db->val(
                    "SELECT id FROM users WHERE username = ? AND id != ? UNION SELECT id FROM chats WHERE handle = ?",
                    array($reqU, $myId, $reqU)
                );
                if ($takenU) {
                    api_err('username_taken', 'این نام کاربری قبلاً انتخاب شده است. / Username is already taken.');
                }
                $nextUsername = $reqU;
            }
            $curFlags['no_username'] = 0;
        }
        if (isset($in['hide_search'])) $curFlags['hide_search'] = (int)$in['hide_search'] ? 1 : 0;
        if (isset($in['hide_last_seen'])) $curFlags['hide_last_seen'] = (int)$in['hide_last_seen'] ? 1 : 0;
        if (isset($in['hide_online'])) $curFlags['hide_online'] = (int)$in['hide_online'] ? 1 : 0;
        if (isset($in['hide_edit_badge'])) $curFlags['hide_edit_badge'] = (int)$in['hide_edit_badge'] ? 1 : 0;
        if (isset($in['user_ghost_mode'])) $curFlags['user_ghost_mode'] = (int)$in['user_ghost_mode'] ? 1 : 0;
        if (isset($in['deny_dm'])) $curFlags['deny_dm'] = (int)$in['deny_dm'] ? 1 : 0;
        if (isset($in['deny_calls'])) $curFlags['deny_calls'] = (int)$in['deny_calls'] ? 1 : 0;
        if (isset($in['deny_group_invite'])) $curFlags['deny_group_invite'] = (int)$in['deny_group_invite'] ? 1 : 0;
        if (isset($in['read_receipts'])) $curFlags['read_receipts'] = (int)$in['read_receipts'] ? 1 : 0;
        if (isset($in['auto_dl_images'])) $curFlags['auto_dl_images'] = (int)$in['auto_dl_images'] ? 1 : 0;
        if (isset($in['auto_dl_videos'])) $curFlags['auto_dl_videos'] = (int)$in['auto_dl_videos'] ? 1 : 0;
        if (isset($in['auto_dl_audio'])) $curFlags['auto_dl_audio'] = (int)$in['auto_dl_audio'] ? 1 : 0;
        if (isset($in['autoplay_gifs'])) $curFlags['autoplay_gifs'] = (int)$in['autoplay_gifs'] ? 1 : 0;
        if (array_key_exists('user_default_ttl', $in)) $curFlags['user_default_ttl'] = max(0, min(31536000, (int)$in['user_default_ttl']));
        if (isset($in['user_default_ttl_mode']) && in_array($in['user_default_ttl_mode'], array('expire_after_send', 'burn_after_read'), true)) {
            $curFlags['user_default_ttl_mode'] = $in['user_default_ttl_mode'];
        }
        if (isset($in['browser_notif'])) $curFlags['browser_notif'] = (int)$in['browser_notif'] ? 1 : 0;
        if (isset($in['notif_preview'])) $curFlags['notif_preview'] = (int)$in['notif_preview'] ? 1 : 0;
        if (isset($in['notif_silent'])) $curFlags['notif_silent'] = (int)$in['notif_silent'] ? 1 : 0;
        if (isset($in['app_sounds_muted'])) $curFlags['app_sounds_muted'] = (int)$in['app_sounds_muted'] ? 1 : 0;
        if (isset($in['chat_sounds_enabled'])) $curFlags['chat_sounds_enabled'] = (int)$in['chat_sounds_enabled'] ? 1 : 0;
        if (isset($in['bg_push_enabled'])) $curFlags['bg_push_enabled'] = (int)$in['bg_push_enabled'] ? 1 : 0;
        if (array_key_exists('auto_logout_sec', $in)) $curFlags['auto_logout_sec'] = max(0, min(31536000, (int)$in['auto_logout_sec']));
        if (isset($in['send_key_mode']) && in_array($in['send_key_mode'], array('newline', 'enter', 'ctrl_enter'), true)) {
            $curFlags['send_key_mode'] = $in['send_key_mode'];
        }
        $inactDays = $me['inactive_delete_days'];
        if (array_key_exists('inactivity_days', $in)) {
            $inactDays = (int)$in['inactivity_days'] > 0 ? (int)$in['inactivity_days'] : null;
        }
        if ($name === '') $name = 'User';
        $db->exec(
            "UPDATE users SET username = ?, name = ?, bio = ?, avatar = ?, lang = ?, theme = ?, cal = ?, show_admin_badge = ?, pubkey = ?, key_backup = ?, flags = ?, inactive_delete_days = ? WHERE id = ?",
            array($nextUsername, $name, $bio, $avatar, $lang, $theme, $cal, $showBadge, $pubkey, $keyBackup, json_encode($curFlags), $inactDays, $myId)
        );
        bump_tick();
        $updated = $db->one("SELECT * FROM users WHERE id = ?", array($myId));
        bump_tick();
        api_ok(array('user' => format_user_self($updated)));
    }

    if ($do === 'privacy_update') {
        $rawExistingFlags = parse_json_col(isset($me['flags']) ? $me['flags'] : '', array());
        $curFlags = get_user_flags($me);
        foreach (array('storage_quota_mb', 'traffic_quota_mb', 'traffic_period_days', 'upload_disabled', 'restricted_content_types', 'call_policy', 'msg_viewers_policy', 'last_totp_sig', 'ban_send', 'ban_react', 'no_username', 'lock_enabled', 'lock_timeout_sec', 'send_key_mode', 'chat_sounds_enabled', 'bg_push_enabled', 'notif_preview', 'push_subs', 'autoplay_gifs', 'user_default_ttl', 'user_default_ttl_mode', 'admin_user_ttl', 'admin_user_ttl_mode', 'show_my_typing', 'admin_typing_override', 'hide_edit_badge', 'admin_hide_edit_badge', 'admin_max_created_groups', 'admin_max_created_channels', 'force_pw_reset', 'synced_drafts') as $pk) {
            if (isset($rawExistingFlags[$pk])) $curFlags[$pk] = $rawExistingFlags[$pk];
        }
        foreach (array('hide_search', 'hide_last_seen', 'hide_online', 'show_my_typing', 'hide_edit_badge', 'user_ghost_mode', 'deny_dm', 'deny_calls', 'deny_group_invite', 'read_receipts', 'auto_dl_images', 'auto_dl_videos', 'auto_dl_audio', 'autoplay_gifs', 'browser_notif', 'notif_silent', 'notif_preview', 'app_sounds_muted', 'chat_sounds_enabled', 'bg_push_enabled') as $fk) {
            if (isset($in[$fk])) {
                $curFlags[$fk] = (int)$in[$fk] ? 1 : 0;
            }
        }
        if (array_key_exists('user_default_ttl', $in)) {
            $curFlags['user_default_ttl'] = max(0, min(31536000, (int)$in['user_default_ttl']));
        }
        if (isset($in['user_default_ttl_mode']) && in_array($in['user_default_ttl_mode'], array('expire_after_send', 'burn_after_read'), true)) {
            $curFlags['user_default_ttl_mode'] = $in['user_default_ttl_mode'];
        }
        if (isset($in['last_seen_mode']) && !isset($in['hide_last_seen'])) {
            $lsm = (string)$in['last_seen_mode'];
            $curFlags['hide_last_seen'] = ($lsm === 'recently' || $lsm === 'hidden') ? 1 : 0;
        }
        if (isset($in['show_online']) && !isset($in['hide_online'])) {
            $curFlags['hide_online'] = ((int)$in['show_online'] ? 0 : 1);
        }
        if (array_key_exists('inactive_delete_days', $in)) {
            $inactiveDays = (int)$in['inactive_delete_days'] > 0 ? (int)$in['inactive_delete_days'] : null;
        } elseif (array_key_exists('inactivity_days', $in)) {
            $inactiveDays = (int)$in['inactivity_days'] > 0 ? (int)$in['inactivity_days'] : null;
        } else {
            $inactiveDays = $me['inactive_delete_days'];
        }
        if (!empty($curFlags['user_ghost_mode']) || (isset($curFlags['show_my_typing']) && (int)$curFlags['show_my_typing'] === 0)) {
            clear_ephemeral_typing_for_user($db, $myId, 0);
        }
        $db->exec("UPDATE users SET flags = ?, inactive_delete_days = ? WHERE id = ?", array(json_encode($curFlags), $inactiveDays, $myId));
        bump_tick();
        $updated = $db->one("SELECT * FROM users WHERE id = ?", array($myId));
        api_ok(array('user' => format_user_self($updated)));
    }

    if ($do === 'user_settings_reset') {
        if (empty($in['confirmed'])) {
            api_err('confirmation_required', 'Confirmation checkbox is required.');
        }
        $rawOrig = parse_json_col(isset($me['flags']) ? $me['flags'] : '', array());
        $resetFlags = array(
            'hide_search' => 0, 'hide_last_seen' => 0, 'hide_online' => 0, 'show_my_typing' => 1, 'hide_edit_badge' => 0,
            'user_ghost_mode' => 0, 'deny_dm' => 0, 'deny_calls' => 0, 'deny_group_invite' => 0,
            'read_receipts' => 1, 'auto_dl_images' => 1, 'auto_dl_videos' => 1, 'auto_dl_audio' => 1,
            'autoplay_gifs' => 1, 'browser_notif' => 1, 'notif_silent' => 0, 'notif_preview' => 1,
            'app_sounds_muted' => 0, 'chat_sounds_enabled' => 1, 'bg_push_enabled' => 1, 'auto_logout_sec' => 0,
            'send_key_mode' => 'ctrl_enter', 'user_default_ttl' => 0, 'user_default_ttl_mode' => 'expire_after_send'
        );
        foreach (array('storage_quota_mb', 'traffic_quota_mb', 'traffic_period_days', 'upload_disabled', 'restricted_content_types', 'call_policy', 'msg_viewers_policy', 'last_totp_sig', 'ban_send', 'ban_react', 'no_username', 'lock_enabled', 'lock_timeout_sec', 'push_subs', 'admin_user_ttl', 'admin_user_ttl_mode', 'admin_typing_override', 'admin_hide_edit_badge', 'admin_max_created_groups', 'admin_max_created_channels', 'force_pw_reset', 'synced_drafts') as $keepKey) {
            if (array_key_exists($keepKey, $rawOrig)) $resetFlags[$keepKey] = $rawOrig[$keepKey];
        }
        $defTheme = (string)Settings::get($db, 'default_theme', 'auto');
        if (!in_array($defTheme, array('auto', 'light', 'dark'), true)) $defTheme = 'auto';
        $db->exec(
            "UPDATE users SET theme = ?, cal = 'jalali', show_admin_badge = 1, inactive_delete_days = NULL, flags = ? WHERE id = ?",
            array($defTheme, json_encode($resetFlags, JSON_UNESCAPED_UNICODE), $myId)
        );
        bump_tick();
        $updated = $db->one("SELECT * FROM users WHERE id = ?", array($myId));
        api_ok(array('reset' => true, 'user' => format_user_self($updated)));
    }

    if ($do === 'draft_sync') {
        $syncEnabled = ((int)Settings::get($db, 'draft_sync_enabled', 1) === 1);
        $intervalSec = max(2, min(300, (int)Settings::get($db, 'draft_sync_interval_sec', 3)));
        if (!$syncEnabled) {
            api_ok(array('enabled' => 0, 'interval_sec' => $intervalSec, 'drafts' => array()));
        }
        $freshMe = $db->one("SELECT flags FROM users WHERE id = ?", array($myId));
        $rawFlags = parse_json_col($freshMe ? $freshMe['flags'] : '', array());
        $curDrafts = (isset($rawFlags['synced_drafts']) && is_array($rawFlags['synced_drafts'])) ? $rawFlags['synced_drafts'] : array();
        $updates = (isset($in['updates']) && is_array($in['updates'])) ? $in['updates'] : array();
        $dirty = false;

        // Build allowed non-secret, non-system chat map for this user
        $myChatRows = $db->all(
            "SELECT c.id, c.type FROM chats c JOIN members m ON m.chat_id = c.id AND m.user_id = ? WHERE m.role != 'pending'",
            array($myId)
        );
        $allowedDraftChats = array();
        foreach ($myChatRows as $mcr) {
            if ($mcr['type'] !== 'secret' && $mcr['type'] !== 'system') {
                $allowedDraftChats[(string)(int)$mcr['id']] = true;
            }
        }
        // Purge any draft belonging to secret/system or left chats
        foreach (array_keys($curDrafts) as $existingCidKey) {
            if (!isset($allowedDraftChats[(string)$existingCidKey])) {
                unset($curDrafts[$existingCidKey]);
                $dirty = true;
            }
        }

        $nowMs = (int)round(microtime(true) * 1000);
        $normDraftMs = function($tsVal) use ($nowMs) {
            $v = (int)$tsVal;
            if ($v <= 0) return 0;
            if ($v < 10000000000) $v = $v * 1000;
            if ($v > ($nowMs + 60000)) $v = $nowMs;
            return $v;
        };
        foreach ($updates as $rawCid => $dObj) {
            $cidKey = (string)(int)$rawCid;
            if ((int)$cidKey <= 0 || !isset($allowedDraftChats[$cidKey]) || !is_array($dObj)) {
                continue;
            }
            $updTs = isset($dObj['updated_at']) ? $normDraftMs($dObj['updated_at']) : $nowMs;
            if ($updTs <= 0) $updTs = $nowMs;
            $prevTs = (isset($curDrafts[$cidKey]) && is_array($curDrafts[$cidKey]) && isset($curDrafts[$cidKey]['updated_at']))
                ? $normDraftMs($curDrafts[$cidKey]['updated_at'])
                : 0;
            if ($updTs >= $prevTs) {
                $txt = isset($dObj['text']) ? u_substr((string)$dObj['text'], 0, 4000) : '';
                $rep = isset($dObj['reply_to']) ? max(0, (int)$dObj['reply_to']) : 0;
                $curDrafts[$cidKey] = array(
                    'text'       => $txt,
                    'reply_to'   => $rep,
                    'updated_at' => $updTs
                );
                $dirty = true;
            }
        }
        // Normalize existing stored timestamps & prune empty tombstones older than 10 minutes & cap at 60 entries
        foreach ($curDrafts as $k => $v) {
            if (!is_array($v)) {
                unset($curDrafts[$k]);
                $dirty = true;
                continue;
            }
            $vMs = isset($v['updated_at']) ? $normDraftMs($v['updated_at']) : 0;
            if ($vMs !== (int)(isset($v['updated_at']) ? $v['updated_at'] : 0)) {
                $curDrafts[$k]['updated_at'] = $vMs;
                $dirty = true;
            }
            if ((trim((string)(isset($v['text']) ? $v['text'] : '')) === '') && ($nowMs - $vMs) > 600000) {
                unset($curDrafts[$k]);
                $dirty = true;
            }
        }
        if (count($curDrafts) > 60) {
            uasort($curDrafts, function($a, $b) {
                return ((int)(isset($b['updated_at']) ? $b['updated_at'] : 0)) - ((int)(isset($a['updated_at']) ? $a['updated_at'] : 0));
            });
            $curDrafts = array_slice($curDrafts, 0, 60, true);
            $dirty = true;
        }
        if ($dirty) {
            $rawFlags['synced_drafts'] = $curDrafts;
            $db->exec("UPDATE users SET flags = ? WHERE id = ?", array(json_encode($rawFlags, JSON_UNESCAPED_UNICODE), $myId));
            bump_tick();
        }
        api_ok(array(
            'enabled'      => 1,
            'interval_sec' => $intervalSec,
            'drafts'       => (object)$curDrafts
        ));
    }

    if ($do === 'password_change') {
        if (rate_get_attempts($db, 'pw_change', (string)$myId, 600) >= 8) {
            api_err('rate_limited', 'Too many password attempts. Please wait 10 minutes.');
        }
        $oldPass = isset($in['old_password']) ? (string)$in['old_password'] : '';
        $newPass = isset($in['new_password']) ? (string)$in['new_password'] : '';
        if (!password_verify($oldPass, (string)$me['pass_hash'])) {
            rate_hit($db, 'pw_change', (string)$myId, 600);
            api_err('wrong_password', 'Current password is incorrect.');
        }
        if (!validate_strong_password($newPass)) {
            api_err('weak_password_complex', strong_password_error_message($newPass));
        }
        if (!empty($me['duress_pass_hash']) && password_verify($newPass, (string)$me['duress_pass_hash'])) {
            api_err('duress_conflict', 'رمز عبور اصلی نمی‌تواند با رمز تخریب یکسان باشد. / Primary password cannot match your duress password.');
        }
        if (!empty($me['lock_pass_hash']) && password_verify($newPass, (string)$me['lock_pass_hash'])) {
            api_err('duress_conflict', 'رمز عبور اصلی نمی‌تواند با رمز قفل صفحه یکسان باشد. / Primary password cannot match your lock password.');
        }
        if ($isSuper) {
            $pHashPw = (string)Settings::get($db, 'panic_duress_pass_hash', '');
            if ($pHashPw !== '' && password_verify($newPass, $pHashPw)) {
                api_err('duress_conflict', 'رمز عبور اصلی نمی‌تواند با رمز تخریب اضطراری سامانه یکسان باشد. / Primary password cannot match panic duress password.');
            }
        }
        rate_clear($db, 'pw_change', (string)$myId);
        $db->exec("UPDATE users SET pass_hash = ? WHERE id = ?", array(password_hash($newPass, PASSWORD_DEFAULT), $myId));
        // Revoke ALL other (older) sessions on password change — security events bypass the grace lock
        $curSid = isset($auth['session']['id']) ? (int)$auth['session']['id'] : 0;
        $revokedCount = revoke_user_sessions($db, $myId, $curSid, true);
        bump_tick();
        api_ok(array('changed' => true, 'revoked_sessions' => $revokedCount));
    }

    if ($do === 'recovery_code_regenerate') {
        if (rate_get_attempts($db, 'rec_regen', (string)$myId, 600) >= 8) {
            api_err('rate_limited', 'تلاش‌های ناموفق بیش از حد مجاز است. لطفاً ۱۰ دقیقه صبر کنید. / Too many attempts. Please wait 10 minutes.');
        }
        $curPass = isset($in['current_password']) ? (string)$in['current_password'] : '';
        if (!password_verify($curPass, (string)$me['pass_hash'])) {
            rate_hit($db, 'rec_regen', (string)$myId, 600);
            api_err('wrong_password', 'رمز عبور فعلی اشتباه است. / Current password is incorrect.');
        }
        rate_clear($db, 'rec_regen', (string)$myId);
        $newRecovery = strtoupper(substr(bin2hex(random_bytes_safe(8)), 0, 4) . '-' . substr(bin2hex(random_bytes_safe(8)), 0, 4) . '-' . substr(bin2hex(random_bytes_safe(8)), 0, 4));
        $db->exec("UPDATE users SET recovery_hash = ? WHERE id = ?", array(password_hash($newRecovery, PASSWORD_DEFAULT), $myId));
        api_ok(array('recovery_code' => $newRecovery, 'new_recovery_code' => $newRecovery));
    }

    if ($do === 'duress_password_set') {
        if (rate_get_attempts($db, 'duress_pw', (string)$myId, 600) >= 8) {
            api_err('rate_limited', 'Too many password attempts. Please wait 10 minutes.');
        }
        $curPass = isset($in['current_password']) ? (string)$in['current_password'] : '';
        $duressPass = isset($in['duress_password']) ? (string)$in['duress_password'] : '';
        $duressConfirm = array_key_exists('duress_password_confirm', $in) ? (string)$in['duress_password_confirm'] : $duressPass;
        $remove = !empty($in['remove']);
        if (!password_verify($curPass, (string)$me['pass_hash'])) {
            rate_hit($db, 'duress_pw', (string)$myId, 600);
            api_err('wrong_password', 'Current account password is incorrect.');
        }
        if ($remove) {
            rate_clear($db, 'duress_pw', (string)$myId);
            $db->exec("UPDATE users SET duress_pass_hash = NULL WHERE id = ?", array($myId));
            $updated = $db->one("SELECT * FROM users WHERE id = ?", array($myId));
            api_ok(array('has_duress_password' => 0, 'user' => format_user_self($updated)));
        }
        if (strlen($duressPass) < 6) {
            api_err('weak_password', 'Duress password must be at least 6 characters.');
        }
        if ($duressPass !== $duressConfirm) {
            api_err('password_mismatch', 'رمز جعلی تخریب و تکرار آن یکسان نیستند. / Duress password and confirmation do not match.');
        }
        if (password_verify($duressPass, (string)$me['pass_hash'])) {
            api_err('duress_conflict', 'رمز تخریب نمی‌تواند با رمز عبور اصلی شما یکسان باشد. / Duress password must be different from your login password.');
        }
        if (!empty($me['lock_pass_hash']) && password_verify($duressPass, (string)$me['lock_pass_hash'])) {
            api_err('duress_conflict', 'رمز تخریب نمی‌تواند با رمز قفل صفحه یکسان باشد. / Duress password cannot match your lock password.');
        }
        rate_clear($db, 'duress_pw', (string)$myId);
        $db->exec("UPDATE users SET duress_pass_hash = ? WHERE id = ?", array(password_hash($duressPass, PASSWORD_DEFAULT), $myId));
        $updated = $db->one("SELECT * FROM users WHERE id = ?", array($myId));
        api_ok(array('has_duress_password' => 1, 'user' => format_user_self($updated)));
    }

    if ($do === 'lock_screen_set') {
        if (rate_get_attempts($db, 'lock_cfg', (string)$myId, 600) >= 8) {
            api_err('rate_limited', 'Too many password attempts. Please wait 10 minutes.');
        }
        $curPass = isset($in['current_password']) ? (string)$in['current_password'] : '';
        if (!password_verify($curPass, (string)$me['pass_hash'])) {
            rate_hit($db, 'lock_cfg', (string)$myId, 600);
            api_err('wrong_password', 'Current account password is incorrect.');
        }
        rate_clear($db, 'lock_cfg', (string)$myId);

        $rawOrigFlags = parse_json_col(isset($me['flags']) ? $me['flags'] : '', array());
        $uFlagsLk = get_user_flags($me);
        foreach ($rawOrigFlags as $fk => $fv) $uFlagsLk[$fk] = $fv;

        if (!empty($in['remove']) || !empty($in['remove_password'])) {
            $uFlagsLk['lock_enabled'] = 0;
            // A decoy can only ever run on top of a lock screen, so taking the
            // lock away has to switch the decoy off too - otherwise its checkbox
            // would sit ticked forever while the decoy was in fact dead.
            $uFlagsLk['decoy_enabled'] = 0;
            $db->exec("UPDATE users SET lock_pass_hash = NULL, flags = ? WHERE id = ?", array(json_encode($uFlagsLk, JSON_UNESCAPED_UNICODE), $myId));
            $db->exec("UPDATE sessions SET is_locked = 0 WHERE user_id = ?", array($myId));
            $updated = $db->one("SELECT * FROM users WHERE id = ?", array($myId));
            $selfOut = format_user_self($updated);
            api_ok(array(
                'user'                => $selfOut,
                'lock_screen_enabled' => 0,
                'has_lock_password'   => 0,
                'lock_timeout_sec'    => (int)$selfOut['lock_timeout_sec'],
                'lock_auto_sec'       => (int)$selfOut['lock_auto_sec']
            ));
        }

        $enabled = array_key_exists('enabled', $in) ? ((int)$in['enabled'] ? 1 : 0) : 1;
        $rawTimeoutIn = array_key_exists('timeout_sec', $in) ? $in['timeout_sec'] : (array_key_exists('auto_lock_sec', $in) ? $in['auto_lock_sec'] : null);
        $timeoutSec = ($rawTimeoutIn !== null) ? max(0, min(86400, (int)$rawTimeoutIn)) : (int)$uFlagsLk['lock_timeout_sec'];
        $lockPass = isset($in['lock_password']) ? (string)$in['lock_password'] : '';
        $lockConfirm = array_key_exists('lock_password_confirm', $in) ? (string)$in['lock_password_confirm'] : '';

        $nextHash = $me['lock_pass_hash'];
        // A password is only demanded when one is being set or replaced, or when
        // the lock is being switched on without one yet. Demanding one while the
        // lock was being switched *off* made the save fail for every account that
        // never had a lock password - which is exactly what a globally forced
        // lock leaves behind, and it read as "the settings do not save".
        if ($lockPass !== '' || ($enabled && empty($nextHash))) {
            if (strlen($lockPass) < 4) {
                api_err('weak_password', 'رمز قفل صفحه باید حداقل ۴ کاراکتر باشد. / Lock password must be at least 4 characters.');
            }
            if ($lockPass !== $lockConfirm) {
                api_err('password_mismatch', 'رمز قفل صفحه و تکرار آن یکسان نیستند. / Lock password and confirmation do not match.');
            }
            if (!empty($me['duress_pass_hash']) && password_verify($lockPass, (string)$me['duress_pass_hash'])) {
                api_err('duress_conflict', 'رمز قفل صفحه نمی‌تواند با رمز تخریب یکسان باشد. / Lock password cannot match duress password.');
            }
            if ($isSuper) {
                $pHashChk = (string)Settings::get($db, 'panic_duress_pass_hash', '');
                if ($pHashChk !== '' && password_verify($lockPass, $pHashChk)) {
                    api_err('duress_conflict', 'رمز قفل صفحه نمی‌تواند با رمز تخریب اضطراری یکسان باشد. / Lock password cannot match panic duress password.');
                }
            }
            $nextHash = password_hash($lockPass, PASSWORD_DEFAULT);
        }

        $uFlagsLk['lock_enabled'] = $enabled;
        $uFlagsLk['lock_timeout_sec'] = $timeoutSec;
        // The same rule as removing the password: a decoy can only ever run on
        // top of a lock screen, so switching the lock off has to switch the
        // decoy off too. Without this the flag stays set and the checkbox comes
        // back ticked on the next visit to this screen, describing a decoy that
        // is in fact dead - the panel only clears the box on screen, it never
        // saved it.
        if (!$enabled) $uFlagsLk['decoy_enabled'] = 0;
        $db->exec("UPDATE users SET lock_pass_hash = ?, flags = ? WHERE id = ?", array($nextHash, json_encode($uFlagsLk, JSON_UNESCAPED_UNICODE), $myId));
        if (!$enabled) {
            $db->exec("UPDATE sessions SET is_locked = 0 WHERE user_id = ?", array($myId));
        }
        $updated = $db->one("SELECT * FROM users WHERE id = ?", array($myId));
        $selfOut = format_user_self($updated);
        api_ok(array(
            'user'                => $selfOut,
            'lock_screen_enabled' => (int)$selfOut['lock_screen_enabled'],
            'has_lock_password'   => (int)$selfOut['has_lock_password'],
            'lock_timeout_sec'    => (int)$selfOut['lock_timeout_sec'],
            'lock_auto_sec'       => (int)$selfOut['lock_auto_sec']
        ));
    }

    if ($do === 'decoy_screen_set') {
        $rawOrigFlagsDc = parse_json_col(isset($me['flags']) ? $me['flags'] : '', array());
        $uFlagsDc = get_user_flags($me);
        foreach ($rawOrigFlagsDc as $fk => $fv) $uFlagsDc[$fk] = $fv;

        // A decoy the user switches on for themselves replaces their lock screen,
        // so there must be a personal lock password for it to check against -
        // otherwise the page would open for anybody who pressed Enter. This is
        // required even while the admin is forcing the lock globally.
        if (!empty($in['enabled']) && (empty($me['lock_pass_hash']) || empty($uFlagsDc['lock_enabled']))) {
            api_err('decoy_needs_lock_password', 'برای فعال‌سازی صفحه‌ی جعلی باید ابتدا قفل صفحه را با رمز فعال کنید. / Enable the lock screen with a password first to use the decoy page.');
        }

        $uFlagsDc['decoy_enabled'] = !empty($in['enabled']) ? 1 : 0;
        $uFlagsDc['decoy_title'] = m3_utf8_clip(trim(isset($in['decoy_title']) ? (string)$in['decoy_title'] : ''), 200);
        $uFlagsDc['decoy_subtitle'] = m3_utf8_clip(trim(isset($in['decoy_subtitle']) ? (string)$in['decoy_subtitle'] : ''), 400);
        $db->exec("UPDATE users SET flags = ? WHERE id = ?", array(json_encode($uFlagsDc, JSON_UNESCAPED_UNICODE), $myId));
        $updatedDc = $db->one("SELECT * FROM users WHERE id = ?", array($myId));
        $selfOutDc = format_user_self($updatedDc);
        api_ok(array(
            'user'           => $selfOutDc,
            'decoy_enabled'  => (int)$uFlagsDc['decoy_enabled'],
            'decoy_active'   => (int)$selfOutDc['decoy_active'],
            'decoy_title'    => (string)$selfOutDc['decoy_title'],
            'decoy_subtitle' => (string)$selfOutDc['decoy_subtitle']
        ));
    }

    if ($do === 'totp_setup') {
        if (!twofa_globally_enabled($db)) {
            api_err('twofa_disabled_global', 'تأیید دو مرحله‌ای (2FA) توسط مدیر پیام‌رسان غیرفعال شده است. / Two-Factor Authentication is disabled by the messenger administrator.');
        }
        if (user_twofa_disabled($me)) {
            api_err('twofa_disabled_user', 'تأیید دو مرحله‌ای (2FA) برای حساب شما غیرفعال شده است. / Two-Factor Authentication is disabled for your account.');
        }
        $secret = base32_generate_secret(16);
        $db->upsert('meta', array('k' => "totp_pending_{$myId}", 'v' => $secret), 'k');
        $site = rawurlencode((string)Settings::get($db, 'site_name', 'My Mini Messenger (M3)'));
        $uri = "otpauth://totp/{$site}:{$me['username']}?secret={$secret}&issuer={$site}";
        api_ok(array('secret' => $secret, 'otpauth_uri' => $uri));
    }

    if ($do === 'totp_enable') {
        if (!twofa_globally_enabled($db)) {
            api_err('twofa_disabled_global', 'تأیید دو مرحله‌ای (2FA) توسط مدیر پیام‌رسان غیرفعال شده است. / Two-Factor Authentication is disabled by the messenger administrator.');
        }
        if (user_twofa_disabled($me)) {
            api_err('twofa_disabled_user', 'تأیید دو مرحله‌ای (2FA) برای حساب شما غیرفعال شده است. / Two-Factor Authentication is disabled for your account.');
        }
        if (rate_get_attempts($db, 'totp_chg', (string)$myId, 600) >= 8) {
            api_err('rate_limited', 'Too many 2FA attempts. Please wait 10 minutes.');
        }
        $secret = isset($in['secret']) && trim((string)$in['secret']) !== '' ? strtoupper(trim((string)$in['secret'])) : (string)$db->val("SELECT v FROM meta WHERE k = ?", array("totp_pending_{$myId}"));
        $code   = isset($in['code']) ? trim((string)$in['code']) : '';
        $matchedSlice = null;
        if (!totp_verify($secret, $code, 1, $matchedSlice)) {
            rate_hit($db, 'totp_chg', (string)$myId, 600);
            api_err('totp_invalid', 'Verification code does not match secret.');
        }
        rate_clear($db, 'totp_chg', (string)$myId);
        $flags = parse_json_col(isset($me['flags']) ? $me['flags'] : '', array());
        $flags['last_totp_sig'] = hash('sha256', (string)$matchedSlice . ':' . preg_replace('/\D/', '', $code));
        $db->exec("UPDATE users SET totp_secret = ?, flags = ? WHERE id = ?", array($secret, json_encode($flags, JSON_UNESCAPED_UNICODE), $myId));
        $db->exec("DELETE FROM meta WHERE k = ?", array("totp_pending_{$myId}"));
        api_ok(array('totp_enabled' => 1));
    }

    if ($do === 'totp_disable') {
        if (rate_get_attempts($db, 'totp_chg', (string)$myId, 600) >= 10) {
            api_err('rate_limited', 'Too many attempts. Please wait 10 minutes.');
        }
        $rawPass = isset($in['password']) ? (string)$in['password'] : '';
        $cleanBidi = preg_replace('/[\x{200B}-\x{200F}\x{202A}-\x{202E}\x{2066}-\x{2069}]/u', '', $rawPass);
        if ($cleanBidi === null) $cleanBidi = $rawPass;
        $pass = $rawPass;
        $code = isset($in['code']) ? (string)$in['code'] : $cleanBidi;
        $passAscii = normalize_ascii_digits($cleanBidi);
        $freshHash = (string)$db->val("SELECT pass_hash FROM users WHERE id = ?", array($myId));
        if ($freshHash === '') $freshHash = (string)$me['pass_hash'];
        $validPass = ($pass !== '' && (
            password_verify($pass, $freshHash) ||
            password_verify($cleanBidi, $freshHash) ||
            password_verify(trim($cleanBidi), $freshHash) ||
            password_verify($passAscii, $freshHash) ||
            password_verify(trim($passAscii), $freshHash)
        ));
        $validTotp = (!empty($me['totp_secret']) && $code !== '' && totp_verify((string)$me['totp_secret'], $code, 2));
        if (!$validPass && !$validTotp) {
            rate_hit($db, 'totp_chg', (string)$myId, 600);
            api_err('wrong_password', 'رمز عبور حساب یا کد ۶ رقمی دو مرحله‌ای نادرست است. / Incorrect password or 6-digit 2FA code.');
        }
        rate_clear($db, 'totp_chg', (string)$myId);
        $flagsClean = parse_json_col(isset($me['flags']) ? $me['flags'] : '', array());
        unset($flagsClean['last_totp_sig']);
        $db->exec("UPDATE users SET totp_secret = NULL, flags = ? WHERE id = ?", array(json_encode($flagsClean, JSON_UNESCAPED_UNICODE), $myId));
        api_ok(array('totp_enabled' => 0));
    }

    if ($do === 'blocked_users_list') {
        $bRows = $db->all(
            "SELECT u.id, u.username, u.name, u.avatar, u.flags, u.role
             FROM blocks b
             JOIN users u ON u.id = b.blocked_id
             WHERE b.user_id = ? AND u.status != 'deleted'
             ORDER BY u.name ASC, u.id ASC",
            array($myId)
        );
        $list = array();
        $ids = array();
        foreach ($bRows as $br) {
            $bFl = parse_json_col($br['flags'], array());
            $ids[] = (int)$br['id'];
            $list[] = array(
                'id'       => (int)$br['id'],
                'username' => !empty($bFl['no_username']) ? '' : (string)$br['username'],
                'name'     => (string)$br['name'],
                'avatar'   => (string)$br['avatar']
            );
        }
        api_ok(array('blocked_ids' => $ids, 'blocked_users' => $list));
    }

    if ($do === 'block_user' || $do === 'unblock_user') {
        $targetId = isset($in['user_id']) ? (int)$in['user_id'] : 0;
        $targetUname = isset($in['username']) ? u_lower(trim(ltrim((string)$in['username'], '@'))) : '';
        if ($targetId <= 0 && $targetUname !== '') {
            $tuBlk = $db->one("SELECT id, flags, status FROM users WHERE username = ?", array($targetUname));
            if ($tuBlk && $tuBlk['status'] !== 'deleted') {
                $tuFlBlk = parse_json_col($tuBlk['flags'], array());
                if ((empty($tuFlBlk['no_username']) && empty($tuFlBlk['hide_search'])) || $isSuper) {
                    $targetId = (int)$tuBlk['id'];
                }
            }
        }
        if ($targetId <= 0 || $targetId === $myId) {
            api_err('invalid_target', 'کاربر مورد نظر یافت نشد. / Invalid user.');
        }
        $targetRowChk = $db->one("SELECT id, role, status FROM users WHERE id = ?", array($targetId));
        if (!$targetRowChk || $targetRowChk['status'] === 'deleted') {
            api_err('invalid_target', 'User not found.');
        }
        if ($do === 'block_user') {
            if ($targetRowChk['role'] === 'superadmin') {
                api_err('cannot_block_superadmin', 'مسدودسازی مدیر کل سامانه مجاز نیست. / Blocking the Super-Admin is not permitted.');
            }
            $db->insertIgnore('blocks', array('user_id' => $myId, 'blocked_id' => $targetId));
        } else {
            $db->exec("DELETE FROM blocks WHERE user_id = ? AND blocked_id = ?", array($myId, $targetId));
        }
        $bRows = $db->all(
            "SELECT u.id, u.username, u.name, u.avatar, u.flags
             FROM blocks b
             JOIN users u ON u.id = b.blocked_id
             WHERE b.user_id = ? AND u.status != 'deleted'
             ORDER BY u.name ASC, u.id ASC",
            array($myId)
        );
        $ids = array();
        $list = array();
        foreach ($bRows as $r) {
            $rFl = parse_json_col($r['flags'], array());
            $ids[] = (int)$r['id'];
            $list[] = array(
                'id'       => (int)$r['id'],
                'username' => !empty($rFl['no_username']) ? '' : (string)$r['username'],
                'name'     => (string)$r['name'],
                'avatar'   => (string)$r['avatar']
            );
        }
        bump_tick();
        api_ok(array('blocked_ids' => $ids, 'blocked_users' => $list));
    }

    if ($do === 'account_delete_now') {
        $groupAction = 'transfer';
        $confirmed = !empty($in['confirmed']);
        if (!$confirmed) {
            $pass = isset($in['password']) ? (string)$in['password'] : '';
            if ($pass === '' || !password_verify($pass, (string)$me['pass_hash'])) {
                api_err('confirmation_required', 'تیک تایید الزامی است / Confirmation is required.');
            }
        }
        execute_account_deletion($db, $myId, $groupAction);
        clear_session_cookie();
        api_ok(array('deleted' => true));
    }

    if ($do === 'account_delete_schedule') {
        $now = time();
        $exactTs = isset($in['delete_at']) ? (int)$in['delete_at'] : 0;
        if ($exactTs > $now) {
            $targetTs = $exactTs;
        } elseif (isset($in['amount'])) {
            $amt = (float)$in['amount'];
            if ($amt <= 0) {
                api_err('invalid_schedule_time', 'مدت زمان واردشده باید بزرگ‌تر از صفر باشد. / Custom duration must be greater than zero.');
            }
            $unit = (isset($in['unit']) && $in['unit'] === 'days') ? 'days' : 'hours';
            $sec = ($unit === 'days') ? (int)round($amt * 86400) : (int)round($amt * 3600);
            if ($sec < 60) $sec = 60;
            if ($sec > 3650 * 86400) $sec = 3650 * 86400;
            $targetTs = $now + $sec;
        } else {
            $delayHours = isset($in['delay_hours']) ? (float)$in['delay_hours'] : 0;
            if (isset($in['mode'])) {
                $delayHours = ($in['mode'] === '24h') ? 24 : 168;
            }
            $sec = (int)round(max(1, $delayHours) * 3600);
            $targetTs = $now + $sec;
        }
        $db->exec("UPDATE users SET delete_at = ? WHERE id = ?", array($targetTs, $myId));
        api_ok(array('delete_at' => $targetTs));
    }

    if ($do === 'account_delete_cancel') {
        $db->exec("UPDATE users SET delete_at = NULL WHERE id = ?", array($myId));
        api_ok(array('delete_at' => null));
    }

    if ($do === 'my_files_list') {
        $filterChatId = isset($in['chat_id']) ? (int)$in['chat_id'] : 0;
        if ($filterChatId > 0) {
            $rows = $db->all(
                "SELECT f.*, c.title AS chat_title, c.type AS chat_type, c.handle AS chat_handle
                 FROM files f
                 LEFT JOIN chats c ON c.id = f.chat_id
                 WHERE f.owner_id = ? AND f.chat_id = ?
                 ORDER BY f.created_at DESC, f.id DESC",
                array($myId, $filterChatId)
            );
        } else {
            $rows = $db->all(
                "SELECT f.*, c.title AS chat_title, c.type AS chat_type, c.handle AS chat_handle
                 FROM files f
                 LEFT JOIN chats c ON c.id = f.chat_id
                 WHERE f.owner_id = ?
                 ORDER BY f.created_at DESC, f.id DESC",
                array($myId)
            );
        }
        $totalAccountUsedBytes = (int)$db->val("SELECT COALESCE(SUM(size), 0) FROM files WHERE owner_id = ?", array($myId));
        $filesOut = array();
        $usedBytes = 0;
        foreach ($rows as $r) {
            $sz = (int)$r['size'];
            $usedBytes += $sz;
            $cTitle = (string)$r['chat_title'];
            $cType = (string)$r['chat_type'];
            if (($cType === 'dm' || $cType === 'secret') && $cTitle === '') {
                $peerName = $db->val(
                    "SELECT u.name FROM members m JOIN users u ON u.id = m.user_id WHERE m.chat_id = ? AND m.user_id != ? LIMIT 1",
                    array((int)$r['chat_id'], $myId)
                );
                $cTitle = $peerName ? (string)$peerName : ('Chat #' . (int)$r['chat_id']);
            } elseif ($cTitle === '') {
                $cTitle = 'Chat #' . (int)$r['chat_id'];
            }
            $filesOut[] = array(
                'id'           => (int)$r['id'],
                'chat_id'      => (int)$r['chat_id'],
                'chat_title'   => $cTitle,
                'chat_type'    => $cType ?: 'group',
                'chat_handle'  => (string)$r['chat_handle'],
                'display_name' => (string)$r['display_name'],
                'mime'         => (string)$r['mime'],
                'size'         => $sz,
                'encrypted'    => (int)$r['encrypted'],
                'created_at'   => (int)$r['created_at'],
                'zero_save'    => ($cType === 'secret' || (int)$r['encrypted'] === 1 || (bool)$db->val("SELECT 1 FROM messages WHERE file_id = ? AND deleted_at IS NULL AND ((burn_after IS NOT NULL AND burn_after > 0) OR expires_at IS NOT NULL) LIMIT 1", array((int)$r['id']))) ? 1 : 0,
                'url'          => '?a=file&id=' . (int)$r['id']
            );
        }
        $effQuotaMb = get_user_effective_quota_mb($db, $me);
        $autoDelHours = (float)Settings::get($db, 'file_auto_delete_hours', 0);
        api_ok(array(
            'files'                  => $filesOut,
            'used_bytes'             => ($filterChatId > 0 ? $totalAccountUsedBytes : $usedBytes),
            'scope_used_bytes'       => $usedBytes,
            'filter_chat_id'         => $filterChatId,
            'quota_mb'               => $effQuotaMb,
            'quota_bytes'            => $effQuotaMb > 0 ? (int)round($effQuotaMb * 1048576) : 0,
            'file_auto_delete_hours' => $autoDelHours
        ));
    }

    if ($do === 'my_file_delete') {
        $delAll = !empty($in['delete_all']);
        $filterChatId = isset($in['chat_id']) ? (int)$in['chat_id'] : 0;
        if ($delAll) {
            $myFiles = ($filterChatId > 0)
                ? $db->all("SELECT * FROM files WHERE owner_id = ? AND chat_id = ?", array($myId, $filterChatId))
                : $db->all("SELECT * FROM files WHERE owner_id = ?", array($myId));
            $cnt = 0;
            $freed = 0;
            foreach ($myFiles as $mf) {
                $freed += delete_uploaded_file_and_clean_messages($db, $mf, '🗑️ [فایل توسط فرستنده حذف شد / File deleted by uploader]');
                $cnt++;
            }
            if ($cnt > 0) bump_tick();
            $remBytes = (int)$db->val("SELECT COALESCE(SUM(size), 0) FROM files WHERE owner_id = ?", array($myId));
            api_ok(array('deleted_count' => $cnt, 'freed_bytes' => $freed, 'used_bytes' => $remBytes));
        }

        $fid = isset($in['file_id']) ? (int)$in['file_id'] : 0;
        $f = $db->one("SELECT * FROM files WHERE id = ?", array($fid));
        if (!$f) {
            api_err('not_found', 'فایل یافت نشد / File not found.');
        }
        if ((int)$f['owner_id'] !== $myId && !$isSuper) {
            api_err('forbidden', 'شما فقط مجاز به حذف فایل‌های بارگذاری‌شده خودتان هستید / You can only delete your own uploaded files.');
        }
        $freed = delete_uploaded_file_and_clean_messages($db, $f, '🗑️ [فایل توسط فرستنده حذف شد / File deleted by uploader]');
        bump_tick();
        $remBytes = (int)$db->val("SELECT COALESCE(SUM(size), 0) FROM files WHERE owner_id = ?", array($myId));
        api_ok(array('deleted' => true, 'file_id' => $fid, 'freed_bytes' => $freed, 'used_bytes' => $remBytes));
    }

    if ($do === 'user_backup_preflight') {
        $infoBk = build_and_stream_user_self_backup_zip($db, $me, false);
        $zipBytesBk = (int)$infoBk['zip_bytes'];
        $quotaCheck = evaluate_user_backup_traffic_quota($db, $me, $zipBytesBk);
        if (empty($quotaCheck['allowed'])) {
            api_err(
                'backup_traffic_insufficient',
                'به دلیل محدودیت ترافیک حساب کاربری و حجم داده‌های پشتیبان، امکان تهیه نسخه پشتیبان وجود ندارد. / Cannot generate backup because the backup archive size exceeds your remaining allowed traffic quota.',
                429,
                array(
                    'zip_bytes'       => $zipBytesBk,
                    'remaining_bytes' => $quotaCheck['remaining_bytes'],
                    'scope'           => $quotaCheck['scope'],
                    'messages_count'  => (int)$infoBk['messages_count'],
                    'files_count'     => (int)$infoBk['files_count']
                )
            );
        }
        api_ok(array(
            'allowed'         => true,
            'zip_bytes'       => $zipBytesBk,
            'messages_count'  => (int)$infoBk['messages_count'],
            'files_count'     => (int)$infoBk['files_count'],
            'remaining_bytes' => $quotaCheck['remaining_bytes'],
            'unlimited'       => !empty($quotaCheck['unlimited']) ? 1 : 0
        ));
    }

    if ($do === 'export_me') {
        api_err('export_json_replaced', 'خروجی JSON قدیمی با پشتیبان‌گیری استاندارد ZIP جایگزین شده است. / Legacy JSON export has been replaced by ZIP self-backup.', 410);
    }

    /* ---------------- CHATS, GROUPS & CHANNELS ---------------- */
    if ($do === 'push_subscribe' || $do === 'push_unsubscribe') {
        $rawFlags = parse_json_col(isset($me['flags']) ? $me['flags'] : '', array());
        $subs = (isset($rawFlags['push_subs']) && is_array($rawFlags['push_subs'])) ? $rawFlags['push_subs'] : array();
        $epIn = isset($in['endpoint']) ? trim((string)$in['endpoint']) : '';
        if ($do === 'push_unsubscribe') {
            if ($epIn === '') {
                $subs = array();
            } else {
                $filtered = array();
                foreach ($subs as $sItem) {
                    if (is_array($sItem) && isset($sItem['endpoint']) && $sItem['endpoint'] !== $epIn) {
                        $filtered[] = $sItem;
                    }
                }
                $subs = $filtered;
            }
            $rawFlags['push_subs'] = $subs;
            $db->exec("UPDATE users SET flags = ? WHERE id = ?", array(json_encode($rawFlags), $myId));
            api_ok(array('subscribed' => false, 'count' => count($subs)));
        }
        $validEp = validate_safe_web_push_endpoint($epIn);
        if ($validEp === false) {
            api_err('invalid_push_endpoint', 'Invalid or unsafe Web Push endpoint.');
        }
        $cleanSubs = array();
        foreach ($subs as $sItem) {
            if (is_array($sItem) && !empty($sItem['endpoint']) && $sItem['endpoint'] !== $validEp) {
                if (validate_safe_web_push_endpoint($sItem['endpoint']) !== false) {
                    $cleanSubs[] = array('endpoint' => (string)$sItem['endpoint'], 'ts' => isset($sItem['ts']) ? (int)$sItem['ts'] : time());
                }
            }
        }
        $cleanSubs[] = array('endpoint' => $validEp, 'ts' => time());
        if (count($cleanSubs) > 5) {
            $cleanSubs = array_slice($cleanSubs, -5);
        }
        $rawFlags['push_subs'] = $cleanSubs;
        $db->exec("UPDATE users SET flags = ? WHERE id = ?", array(json_encode($rawFlags), $myId));
        api_ok(array('subscribed' => true, 'count' => count($cleanSubs), 'vapid_public_key' => ensure_vapid_keys($db)['public_key']));
    }

    if ($do === 'resolve_mention') {
        $rawHdlParam = isset($in['handle']) ? (string)$in['handle'] : (isset($in['username']) ? (string)$in['username'] : '');
        $handleRaw = u_lower(trim(ltrim($rawHdlParam, '@')));
        if (!preg_match('/^[a-z0-9_]{3,32}$/', $handleRaw)) {
            api_err('invalid_handle', 'شناسه @ معتبر نیست. / Invalid @handle.');
        }
        if (rate_get_attempts($db, 'mention_lookup', (string)$myId, 60) > 45) {
            api_err('rate_limited', 'تعداد درخواست‌ها بیش از حد مجاز است. کمی صبر کنید. / Too many requests.');
        }
        rate_hit($db, 'mention_lookup', (string)$myId, 60);

        // 1. Check user by @username
        $targetU = $db->one("SELECT * FROM users WHERE username = ? AND status = 'active'", array($handleRaw));
        if ($targetU) {
            $tuFlags = get_user_flags($targetU);
            if ((int)$targetU['id'] === $myId) {
                $savedId = ensure_saved_chat($db, $myId);
                api_ok(array('chat_id' => $savedId, 'kind' => 'saved', 'chats' => fetch_user_chats($db, $me)));
            }
            if ((empty($tuFlags['no_username']) && empty($tuFlags['hide_search'])) || $isSuper) {
                $dmCheck = can_initiate_dm_with($db, $me, $targetU);
                if (!$dmCheck['ok']) {
                    api_err($dmCheck['error'], $dmCheck['message']);
                }
                $tUid = (int)$targetU['id'];
                $existingDm = $db->one(
                    "SELECT c.id FROM chats c
                     JOIN members m1 ON m1.chat_id = c.id AND m1.user_id = ?
                     JOIN members m2 ON m2.chat_id = c.id AND m2.user_id = ?
                     WHERE c.type = 'dm' LIMIT 1",
                    array($myId, $tUid)
                );
                if ($existingDm) {
                    $dmCid = (int)$existingDm['id'];
                } else {
                    verify_user_chat_capacity($db, $me, false);
                    verify_user_chat_capacity($db, $targetU, true);
                    $nowM = time();
                    $db->exec(
                        "INSERT INTO chats (type, handle, title, description, avatar, visibility, owner_id, is_default, all_muted, history, default_ttl, ttl_mode, slow_mode, max_members, perms_json, status, created_at)
                         VALUES ('dm', NULL, ?, '', '', 'private', ?, 0, 0, 'all', 0, 'expire_after_send', 0, 2, '{}', 'active', ?)",
                        array($targetU['name'], $myId, $nowM)
                    );
                    $dmCid = $db->lastId();
                    $db->insertIgnore('members', array(
                        'chat_id' => $dmCid, 'user_id' => $myId, 'role' => 'member',
                        'perms_json' => '{}', 'joined_msg_id' => 0, 'last_read_id' => 0,
                        'muted' => 0, 'last_msg_at' => 0, 'joined_at' => $nowM
                    ));
                    $db->insertIgnore('members', array(
                        'chat_id' => $dmCid, 'user_id' => $tUid, 'role' => 'member',
                        'perms_json' => '{}', 'joined_msg_id' => 0, 'last_read_id' => 0,
                        'muted' => 0, 'last_msg_at' => 0, 'joined_at' => $nowM
                    ));
                    bump_tick();
                }
                api_ok(array('chat_id' => $dmCid, 'kind' => 'dm', 'chats' => fetch_user_chats($db, $me)));
            }
        }

        // 2. Check group/channel by @handle
        $targetChat = $db->one("SELECT * FROM chats WHERE handle = ? AND status = 'active'", array($handleRaw));
        if ($targetChat && in_array($targetChat['type'], array('group', 'channel'), true)) {
            $tcid = (int)$targetChat['id'];
            $exMem = $db->one("SELECT * FROM members WHERE chat_id = ? AND user_id = ?", array($tcid, $myId));
            $nowM = time();
            if ($exMem && (empty($exMem['banned_until']) || (int)$exMem['banned_until'] <= $nowM || $isSuper) && $exMem['role'] !== 'pending') {
                api_ok(array('chat_id' => $tcid, 'kind' => $targetChat['type'], 'chats' => fetch_user_chats($db, $me)));
            }
            if ($targetChat['visibility'] === 'public' || $isSuper) {
                if ($exMem && !empty($exMem['banned_until']) && (int)$exMem['banned_until'] > $nowM && !$isSuper) {
                    api_err('banned_in_chat', 'شما از این گفتگو مسدود شده‌اید. / You are banned from this chat.');
                }
                if (!$exMem) {
                    verify_user_chat_capacity($db, $me, false);
                    $capM = resolve_chat_member_capacity($db, $targetChat);
                    $curCntM = (int)$db->val("SELECT COUNT(*) FROM members WHERE chat_id = ? AND role != 'pending'", array($tcid));
                    if ($capM['effective_max'] > 0 && $curCntM >= $capM['effective_max'] && !$isSuper) {
                        api_err('chat_full', 'ظرفیت اعضای این گفتگو تکمیل شده است. / This chat has reached its maximum member capacity.');
                    }
                    $maxMsgIdM = (int)$db->val("SELECT COALESCE(MAX(id), 0) FROM messages WHERE chat_id = ?", array($tcid));
                    $joinedMsgIdM = (!$isSuper && $targetChat['history'] === 'from_join') ? $maxMsgIdM : 0;
                    $cPermsM = parse_json_col($targetChat['perms_json'], array('join_approval' => 0));
                    $roleM = (!empty($cPermsM['join_approval']) && !$isSuper) ? 'pending' : 'member';
                    $db->insertIgnore('members', array(
                        'chat_id' => $tcid, 'user_id' => $myId, 'role' => $roleM,
                        'perms_json' => '{}', 'joined_msg_id' => $joinedMsgIdM, 'last_read_id' => $maxMsgIdM,
                        'muted' => 0, 'last_msg_at' => 0, 'joined_at' => $nowM
                    ));
                    bump_tick();
                    api_ok(array('chat_id' => $tcid, 'kind' => $targetChat['type'], 'status' => $roleM, 'chats' => fetch_user_chats($db, $me)));
                }
            }
        }
        api_err('user_not_found', 'کاربر یا گفتگویی با شناسه @' . $handleRaw . ' یافت نشد. / No user or public chat found for @' . $handleRaw . '.');
    }

    if ($do === 'chats_list') {
        $freshMeRow = $db->one("SELECT * FROM users WHERE id = ?", array($myId));
        if (!$freshMeRow) $freshMeRow = $me;
        $blkRows = $db->all("SELECT blocked_id FROM blocks WHERE user_id = ?", array($myId));
        $blkIds = array();
        foreach ($blkRows as $brItem) $blkIds[] = (int)$brItem['blocked_id'];
        api_ok(array(
            'chats'                => fetch_user_chats($db, $freshMeRow),
            'user'                 => format_user_self($freshMeRow, $db),
            'blocked_ids'          => $blkIds,
            'udig'                 => compute_user_sync_digest($db, $myId),
            'global_idle'          => get_global_idle_state($db),
            'app_timezone'         => normalize_app_timezone(Settings::get($db, 'app_timezone', 'Asia/Tehran')),
            'force_hide_last_seen' => (int)Settings::get($db, 'force_hide_last_seen', 0) ? 1 : 0,
            'identity_limits'      => get_identity_length_limits($db),
            'content_protections'  => array(
                'allow_copy_msg'      => (int)Settings::get($db, 'allow_copy_msg', 1) ? 1 : 0,
                'allow_select_text'   => (int)Settings::get($db, 'allow_select_text', 1) ? 1 : 0,
                'allow_file_download'  => (int)Settings::get($db, 'allow_file_download', 1) ? 1 : 0,
                'allow_forward_msg'    => (int)Settings::get($db, 'allow_forward_msg', 1) ? 1 : 0,
                'global_typing_policy' => normalize_typing_override_val((string)Settings::get($db, 'global_typing_policy', 'default'), 'global')
            )
        ));
    }

    if ($do === 'chat_open_dm' || $do === 'chat_open_secret') {
        $targetId = isset($in['user_id']) ? (int)$in['user_id'] : 0;
        $targetUsername = isset($in['username']) ? u_lower(trim(ltrim((string)$in['username'], '@'))) : '';
        if ($targetId > 0) {
            $targetUser = $db->one("SELECT * FROM users WHERE id = ?", array($targetId));
        } else {
            $targetUser = $db->one("SELECT * FROM users WHERE username = ?", array($targetUsername));
            if ($targetUser && !$isSuper) {
                $tuFl = get_user_flags($targetUser);
                if (!empty($tuFl['no_username']) || !empty($tuFl['hide_search'])) {
                    $targetUser = null;
                }
            }
        }
        if (!$targetUser || (int)$targetUser['id'] === $myId) {
            api_err('invalid_target', 'کاربر مورد نظر یافت نشد یا امکان گفتگو وجود ندارد. / User not found or unavailable.');
        }
        $targetId = (int)$targetUser['id'];

        $dmCheck = can_initiate_dm_with($db, $me, $targetUser);
        if (!$dmCheck['ok']) {
            api_err($dmCheck['error'], $dmCheck['message']);
        }

        $chatType = ($do === 'chat_open_secret') ? 'secret' : 'dm';
        if ($chatType === 'secret' && !(int)Settings::get($db, 'e2ee_enabled', 1)) {
            api_err('e2ee_disabled', 'Secret DMs are disabled by administrator.');
        }

        $existing = $db->one(
            "SELECT c.id FROM chats c
             JOIN members m1 ON m1.chat_id = c.id AND m1.user_id = ?
             JOIN members m2 ON m2.chat_id = c.id AND m2.user_id = ?
             WHERE c.type = ? LIMIT 1",
            array($myId, $targetId, $chatType)
        );
        $now = time();
        if ($existing) {
            $cid = (int)$existing['id'];
            // Rejoining a chat this member had removed from their own list: bring it
            // back for them, but start their history at the current tip so the
            // conversation reads as new on their side while the other party keeps
            // the full, uninterrupted thread.
            $myRow = $db->one("SELECT * FROM members WHERE chat_id = ? AND user_id = ?", array($cid, $myId));
            if ($myRow && (int)(isset($myRow['left_at']) ? $myRow['left_at'] : 0) > 0) {
                $tipId = (int)$db->val("SELECT COALESCE(MAX(id), 0) FROM messages WHERE chat_id = ?", array($cid));
                // tipId + 1: the cutoff is inclusive in the queries, so the message
                // that was the last one at the moment of removal must stay hidden too.
                $db->exec(
                    "UPDATE members SET left_at = 0, rejoin_msg_id = ?, last_read_id = ?, joined_msg_id = ? WHERE chat_id = ? AND user_id = ?",
                    array($tipId + 1, $tipId, $tipId + 1, $cid, $myId)
                );
                bump_tick();
            }
        } else {
            verify_user_chat_capacity($db, $me, false);
            verify_user_chat_capacity($db, $targetUser, true);
            $initPermsJson = ($chatType === 'secret')
                ? json_encode(array('secret_status' => 'pending', 'secret_initiator_id' => $myId))
                : '{}';
            $db->exec(
                "INSERT INTO chats (type, handle, title, description, avatar, visibility, owner_id, is_default, all_muted, history, default_ttl, ttl_mode, slow_mode, max_members, perms_json, status, created_at)
                 VALUES (?, NULL, ?, '', '', 'private', ?, 0, 0, 'all', 0, 'expire_after_send', 0, 2, ?, 'active', ?)",
                array($chatType, $targetUser['name'], $myId, $initPermsJson, $now)
            );
            $cid = $db->lastId();
            $db->insertIgnore('members', array(
                'chat_id' => $cid, 'user_id' => $myId, 'role' => 'member',
                'perms_json' => '{}', 'joined_msg_id' => 0, 'last_read_id' => 0,
                'muted' => 0, 'last_msg_at' => 0, 'joined_at' => $now
            ));
            $db->insertIgnore('members', array(
                'chat_id' => $cid, 'user_id' => $targetId, 'role' => 'member',
                'perms_json' => '{}', 'joined_msg_id' => 0, 'last_read_id' => 0,
                'muted' => 0, 'last_msg_at' => 0, 'joined_at' => $now
            ));
            if ($chatType === 'secret') {
                $db->exec(
                    "INSERT INTO messages (chat_id, user_id, kind, body, created_at, pinned) VALUES (?, ?, 'system', ?, ?, 0)",
                    array($cid, $myId, '🔒 درخواست گفتگوی محرمانه ارسال شد — در انتظار تایید طرف مقابل...', $now)
                );
            }
            bump_tick();
        }
        api_ok(array('chat_id' => $cid, 'chats' => fetch_user_chats($db, $me)));
    }

    if ($do === 'secret_chat_respond') {
        $cid = isset($in['chat_id']) ? (int)$in['chat_id'] : 0;
        $decision = isset($in['decision']) ? trim((string)$in['decision']) : 'accept';
        $chat = $db->one("SELECT * FROM chats WHERE id = ? AND type = 'secret'", array($cid));
        $mem = $db->one("SELECT * FROM members WHERE chat_id = ? AND user_id = ?", array($cid, $myId));
        if (!$chat || !$mem) {
            api_err('not_found', 'Secret chat request not found.');
        }
        $sPerms = parse_json_col($chat['perms_json'], array('secret_status' => 'active', 'secret_initiator_id' => (int)$chat['owner_id']));
        $initId = isset($sPerms['secret_initiator_id']) ? (int)$sPerms['secret_initiator_id'] : (int)$chat['owner_id'];

        if ($decision === 'decline' || $decision === 'cancel') {
            delete_chat_completely($db, $cid);
            bump_tick();
            api_ok(array('declined' => true, 'chats' => fetch_user_chats($db, $me)));
        }

        if ($myId === $initId) {
            api_err('forbidden', 'فقط طرف مقابل می‌تواند درخواست گفتگوی محرمانه را تایید کند. / Only the recipient can accept the secret chat request.');
        }
        if (!empty($in['pubkey']) && is_string($in['pubkey'])) {
            $cleanAcceptPub = trim($in['pubkey']);
            if (strlen($cleanAcceptPub) > 4096) {
                api_err('bad_pubkey', 'Public key payload is too large.');
            }
            $db->exec("UPDATE users SET pubkey = ? WHERE id = ?", array($cleanAcceptPub, $myId));
            $me['pubkey'] = $cleanAcceptPub;
        }
        $sPerms['secret_status'] = 'active';
        $sPerms['accepted_at'] = time();
        $db->exec("UPDATE chats SET perms_json = ? WHERE id = ?", array(json_encode($sPerms), $cid));
        $db->exec(
            "INSERT INTO messages (chat_id, user_id, kind, body, created_at, pinned) VALUES (?, ?, 'system', ?, ?, 0)",
            array($cid, $myId, '🔐 گفتگوی محرمانه تایید شد و با رمزنگاری سرتاسری (ECDH P-256 + AES-256-GCM) آغاز گردید.', time())
        );
        bump_tick();
        api_ok(array('accepted' => true, 'chat_id' => $cid, 'chats' => fetch_user_chats($db, $me)));
    }

    if ($do === 'chat_create') {
        verify_user_chat_capacity($db, $me, false);
        $type = isset($in['type']) && $in['type'] === 'channel' ? 'channel' : 'group';
        verify_user_created_chat_limit($db, $me, $type, 0);
        $title = isset($in['title']) ? trim((string)$in['title']) : '';
        $desc = isset($in['description']) ? trim((string)$in['description']) : '';
        $vis = isset($in['visibility']) && $in['visibility'] === 'public' ? 'public' : 'private';
        $handle = isset($in['handle']) ? u_lower(trim(ltrim((string)$in['handle'], '@'))) : '';
        $history = (isset($in['history']) && $in['history'] === 'from_join') || (isset($in['history_vis']) && $in['history_vis'] === 'from_join') ? 'from_join' : 'all';

        if ($title === '' || u_strlen($title) > 100) {
            api_err('invalid_title', 'Title is required (max 100 chars).');
        }
        if ($vis === 'private') {
            $handle = null;
        } elseif ($handle !== '') {
            if (!preg_match('/^[a-z0-9_]{3,32}$/', $handle)) {
                api_err('invalid_handle', 'Handle must be 3-32 characters (a-z, 0-9, _).');
            }
            $reserved = array_map('trim', explode(',', u_lower((string)Settings::get($db, 'reserved_handles', ''))));
            if (in_array($handle, $reserved, true) && !$isSuper) {
                api_err('reserved_handle', 'This handle is reserved.');
            }
            $taken = $db->val("SELECT id FROM chats WHERE handle = ? UNION SELECT id FROM users WHERE username = ?", array($handle, $handle));
            if ($taken) {
                api_err('handle_taken', 'This @handle is already in use.');
            }
        } else {
            $handle = null;
        }

        if (u_strlen($desc) > 1000) $desc = u_substr($desc, 0, 1000);
        if (isset($in['avatar']) && trim((string)$in['avatar']) !== '') {
            if (validate_safe_avatar_data_uri(trim((string)$in['avatar'])) === false) {
                api_err('invalid_avatar', 'Chat avatar must be a valid PNG, JPEG, GIF, or WebP base64 image.');
            }
        }
        $initTtl = isset($in['default_ttl']) ? max(0, (int)$in['default_ttl']) : 0;
        $initTtlMode = isset($in['ttl_mode']) && in_array($in['ttl_mode'], array('expire_after_send', 'burn_after_read'), true) ? $in['ttl_mode'] : 'expire_after_send';
        $initJoinApp = (!empty($in['join_approval']) || (isset($in['join_mode']) && $in['join_mode'] === 'approval')) ? 1 : 0;

        $now = time();
        $perms = json_encode(array(
            'send_text' => ($type === 'group' ? 1 : 0),
            'send_media' => ($type === 'group' ? 1 : 0),
            'send_voice' => ($type === 'group' ? 1 : 0),
            'invite' => 1,
            'pin' => 0,
            'join_approval' => $initJoinApp,
            'reactions_enabled' => 1
        ));

        $initAvatar = '';
        if (!empty($in['avatar'])) {
            $validInitAv = validate_safe_avatar_data_uri(trim((string)$in['avatar']));
            if ($validInitAv === false) {
                api_err('invalid_avatar', 'تصویر پروفایل گفتگو معتبر نیست.');
            }
            $initAvatar = $validInitAv;
        }
        $db->exec(
            "INSERT INTO chats (type, handle, title, description, avatar, visibility, owner_id, is_default, all_muted, history, default_ttl, ttl_mode, slow_mode, max_members, perms_json, status, created_at)
             VALUES (?, ?, ?, ?, ?, ?, ?, 0, 0, ?, ?, ?, 0, 0, ?, 'active', ?)",
            array($type, $handle, $title, $desc, $initAvatar, $vis, $myId, $history, $initTtl, $initTtlMode, $perms, $now)
        );
        $cid = $db->lastId();
        $db->insertIgnore('members', array(
            'chat_id' => $cid, 'user_id' => $myId, 'role' => 'owner',
            'perms_json' => '{}', 'joined_msg_id' => 0, 'last_read_id' => 0,
            'muted' => 0, 'last_msg_at' => 0, 'joined_at' => $now
        ));
        // Create default invite link
        $invCode = random_invite_code('J-');
        $db->exec(
            "INSERT INTO invites (chat_id, code, created_by, max_uses, uses, expires_at, revoked) VALUES (?, ?, ?, 0, 0, NULL, 0)",
            array($cid, $invCode, $myId)
        );
        bump_tick();
        api_ok(array('chat_id' => $cid, 'chats' => fetch_user_chats($db, $me)));
    }

    if ($do === 'chat_update') {
        $cid = isset($in['chat_id']) ? (int)$in['chat_id'] : 0;
        $chat = $db->one("SELECT * FROM chats WHERE id = ?", array($cid));
        if ($chat && $chat['type'] === 'system') {
            api_err('forbidden', 'Official System Chat cannot be modified.');
        }
        $mem = $db->one("SELECT * FROM members WHERE chat_id = ? AND user_id = ?", array($cid, $myId));
        $canEditInfo = $chat && has_admin_perm($chat, $mem, $me, 'edit_info');
        $canManageContent = $chat && has_admin_perm($chat, $mem, $me, 'manage_content');
        $canManageCalls = $chat && has_admin_perm($chat, $mem, $me, 'manage_calls');
        if (!$chat || (!$canEditInfo && !$canManageContent && !$canManageCalls)) {
            api_err('forbidden', 'You do not have permission to edit this chat.');
        }

        $title = ($canEditInfo && isset($in['title'])) ? trim((string)$in['title']) : $chat['title'];
        if ($title === '') $title = $chat['title'];
        if (u_strlen($title) > 120) $title = u_substr($title, 0, 120);
        $desc = ($canEditInfo && isset($in['description'])) ? trim((string)$in['description']) : $chat['description'];
        if (u_strlen($desc) > 1000) $desc = u_substr($desc, 0, 1000);
        $avatar = ($canEditInfo && isset($in['avatar'])) ? trim((string)$in['avatar']) : $chat['avatar'];
        if ($canEditInfo && array_key_exists('avatar', $in)) {
            $validAv = validate_safe_avatar_data_uri($avatar);
            if ($validAv === false) {
                api_err('invalid_avatar', 'Chat avatar must be a valid PNG, JPEG, GIF, or WebP base64 image.');
            }
            $avatar = $validAv;
        }
        $nextType = $chat['type'];
        if ($canEditInfo && isset($in['type']) && in_array($in['type'], array('group', 'channel'), true) && in_array($chat['type'], array('group', 'channel'), true) && (int)$chat['is_default'] === 0) {
            $nextType = $in['type'];
            if ($nextType !== $chat['type']) {
                verify_user_created_chat_limit($db, $me, $nextType, $cid);
            }
        }
        $vis = ($canEditInfo && isset($in['visibility']) && in_array($in['visibility'], array('public', 'private'), true)) ? $in['visibility'] : $chat['visibility'];
        $history = ($canEditInfo && isset($in['history']) && in_array($in['history'], array('all', 'from_join'), true)) ? $in['history'] : (($canEditInfo && isset($in['history_vis']) && in_array($in['history_vis'], array('all', 'from_join'), true)) ? $in['history_vis'] : $chat['history']);
        $defTtl = ($canEditInfo && isset($in['default_ttl'])) ? max(0, (int)$in['default_ttl']) : (int)$chat['default_ttl'];
        $ttlMode = ($canEditInfo && isset($in['ttl_mode']) && in_array($in['ttl_mode'], array('expire_after_send', 'burn_after_read'), true)) ? $in['ttl_mode'] : $chat['ttl_mode'];
        $slowMode = (($canManageContent || $canEditInfo) && isset($in['slow_mode'])) ? max(0, (int)$in['slow_mode']) : (int)$chat['slow_mode'];
        $allMuted = (($canManageContent || $canEditInfo) && isset($in['all_muted'])) ? ((int)$in['all_muted'] ? 1 : 0) : (int)$chat['all_muted'];
        $maxMembers = (int)$chat['max_members'];
        if ($canEditInfo && isset($in['max_members'])) {
            $reqMaxM = (int)$in['max_members'];
            $maxMembers = ($reqMaxM <= 0) ? 0 : max(2, min(1000000, $reqMaxM));
        }

        $handle = $chat['handle'];
        if ($canEditInfo && array_key_exists('handle', $in)) {
            $newH = u_lower(trim(ltrim((string)$in['handle'], '@')));
            if ($newH === '') {
                $handle = null;
            } elseif ($newH !== (string)$chat['handle']) {
                if (!preg_match('/^[a-z0-9_]{3,32}$/', $newH)) {
                    api_err('invalid_handle', 'Handle must be 3-32 chars (a-z, 0-9, _).');
                }
                $reservedH = array_map('trim', explode(',', u_lower((string)Settings::get($db, 'reserved_handles', ''))));
                if (in_array($newH, $reservedH, true) && !$isSuper) {
                    api_err('reserved_handle', 'This handle is reserved.');
                }
                $taken = $db->val("SELECT id FROM chats WHERE handle = ? AND id != ? UNION SELECT id FROM users WHERE username = ?", array($newH, $cid, $newH));
                if ($taken) {
                    api_err('handle_taken', 'Handle is already taken.');
                }
                $handle = $newH;
            }
        }

        if ($canEditInfo && $vis === 'private' && $chat['visibility'] === 'public' && !array_key_exists('handle', $in)) {
            $handle = null;
        }
        if ($canEditInfo && $vis === 'private') {
            $hasActiveInv = $db->val("SELECT id FROM invites WHERE chat_id = ? AND revoked = 0 LIMIT 1", array($cid));
            if (!$hasActiveInv) {
                $db->exec(
                    "INSERT INTO invites (chat_id, code, created_by, max_uses, uses, expires_at, revoked) VALUES (?, ?, ?, 0, 0, NULL, 0)",
                    array($cid, random_invite_code('J-'), $myId)
                );
            }
        }

        $curPerms = parse_json_col($chat['perms_json'], array(
            'send_text' => 1, 'send_media' => 1, 'send_voice' => 1, 'invite' => 1, 'pin' => 0,
            'join_approval' => 0, 'reactions_enabled' => 1, 'hide_edit_badge' => 0,
            'allow_copy_msg' => 1, 'allow_select_text' => 1, 'allow_file_download' => 1, 'allow_forward_msg' => 1
        ));
        if ($canEditInfo) {
            if (isset($in['perms']) && is_array($in['perms'])) {
                foreach ($curPerms as $pk => $pv) {
                    if (isset($in['perms'][$pk])) {
                        $curPerms[$pk] = (int)$in['perms'][$pk] ? 1 : 0;
                    }
                }
            }
            foreach (array('reactions_enabled', 'allow_copy_msg', 'allow_select_text', 'allow_file_download', 'allow_forward_msg', 'show_owner_transfer_msg', 'show_admin_transfer_msg', 'admins_only', 'join_approval', 'hide_members', 'hide_edit_badge', 'send_media', 'send_voice') as $topPermKey) {
                if (isset($in[$topPermKey])) {
                    $curPerms[$topPermKey] = (int)$in[$topPermKey] ? 1 : 0;
                }
            }
            if (isset($in['member_invite'])) {
                $curPerms['invite'] = (int)$in['member_invite'] ? 1 : 0;
            }
            if (isset($in['member_pin'])) {
                $curPerms['pin'] = (int)$in['member_pin'] ? 1 : 0;
            }
            if (isset($in['show_admin_transfer_msg']) && !isset($in['show_owner_transfer_msg'])) {
                $curPerms['show_owner_transfer_msg'] = (int)$in['show_admin_transfer_msg'] ? 1 : 0;
            } elseif (isset($in['show_owner_transfer_msg']) && !isset($in['show_admin_transfer_msg'])) {
                $curPerms['show_admin_transfer_msg'] = (int)$in['show_owner_transfer_msg'] ? 1 : 0;
            }
            if (isset($in['msg_viewers_mode'])) {
                $curPerms['msg_viewers_mode'] = normalize_msg_viewers_value($in['msg_viewers_mode'], 'chat');
            }
        } elseif ($canManageContent) {
            foreach (array('reactions_enabled', 'admins_only', 'hide_edit_badge', 'allow_copy_msg', 'allow_select_text', 'allow_file_download', 'allow_forward_msg', 'send_media', 'send_voice') as $contentPermKey) {
                if (isset($in[$contentPermKey])) {
                    $curPerms[$contentPermKey] = (int)$in[$contentPermKey] ? 1 : 0;
                }
            }
        }
        if (($canEditInfo || $canManageContent) && isset($in['show_typing'])) {
            $curPerms['show_typing'] = ($nextType === 'group') ? ((int)$in['show_typing'] ? 1 : 0) : 0;
            if (empty($curPerms['show_typing'])) {
                $db->exec("DELETE FROM meta WHERE k LIKE ?", array('typing_' . $cid . '_%'));
            }
            bump_typing_tick();
        }
        if ($nextType === 'channel') {
            $curPerms['show_typing'] = 0;
        }
        if ($isSuper && isset($in['super_msg_viewers_override'])) {
            $curPerms['super_msg_viewers_override'] = normalize_msg_viewers_value($in['super_msg_viewers_override'], 'super_chat');
        }
        if ($isSuper && isset($in['super_typing_override'])) {
            $curPerms['super_typing_override'] = ($nextType === 'channel')
                ? 'inherit'
                : normalize_typing_override_val($in['super_typing_override'], 'chat');
            if ($curPerms['super_typing_override'] === 'force_off') {
                $db->exec("DELETE FROM meta WHERE k LIKE ?", array('typing_' . $cid . '_%'));
            }
            bump_typing_tick();
        }
        if ($isSuper && array_key_exists('super_max_members', $in)) {
            $smm = (int)$in['super_max_members'];
            $curPerms['super_max_members'] = ($smm === -1) ? -1 : (($smm <= 0) ? 0 : max(2, min(1000000, $smm)));
        }
        if (!$isSuper && $canEditInfo && isset($in['max_members']) && $maxMembers > 0) {
            $capPreview = resolve_chat_member_capacity($db, array(
                'type'        => $nextType,
                'max_members' => 0,
                'perms_json'  => json_encode($curPerms)
            ));
            if ($capPreview['super_ceiling'] > 0 && $maxMembers > $capPreview['super_ceiling']) {
                api_err(
                    'exceeds_superadmin_max_members',
                    'حداکثر ظرفیت مجاز تعیین‌شده توسط مدیر کل برای این گفتگو ' . $capPreview['super_ceiling'] . ' عضو است. / Exceeds Super-Admin maximum capacity (' . $capPreview['super_ceiling'] . ' members).'
                );
            }
        }
        $autoDeleteSec = isset($chat['auto_delete_sec']) ? (int)$chat['auto_delete_sec'] : 0;
        if ($canEditInfo && array_key_exists('auto_delete_sec', $in)) {
            $autoDeleteSec = max(0, min(86400 * 3650, (int)$in['auto_delete_sec']));
        }
        if ($canEditInfo && isset($in['idle_mode'])) {
            $im = trim((string)$in['idle_mode']);
            $curPerms['idle_mode'] = in_array($im, array('off', 'manual', 'auto'), true) ? $im : 'off';
        }
        if ($canEditInfo && isset($in['idle_start'])) {
            $curPerms['idle_start'] = normalize_hhmm_str($in['idle_start'], '23:00');
        }
        if ($canEditInfo && isset($in['idle_end'])) {
            $curPerms['idle_end'] = normalize_hhmm_str($in['idle_end'], '07:00');
        }
        if ($canEditInfo && isset($in['idle_tz_offset'])) {
            $curPerms['idle_tz_offset'] = max(-840, min(840, (int)$in['idle_tz_offset']));
        }
        if (isset($in['restricted_content_types']) && is_array($in['restricted_content_types'])) {
            if (!$canManageContent && !$canEditInfo) {
                api_err('forbidden', 'You do not have permission to manage content restrictions.');
            }
            $curPerms['restricted_content_types'] = normalize_content_restrictions($in['restricted_content_types']);
        }
        if (isset($in['call_policy']) && is_array($in['call_policy'])) {
            if (!$canManageCalls) {
                api_err('forbidden', 'You do not have permission to manage call settings.');
            }
            $curPerms['call_policy'] = normalize_call_policy($in['call_policy'], 'chat');
        }

        $db->exec(
            "UPDATE chats SET type = ?, title = ?, description = ?, avatar = ?, handle = ?, visibility = ?, history = ?, default_ttl = ?, ttl_mode = ?, auto_delete_sec = ?, slow_mode = ?, max_members = ?, all_muted = ?, perms_json = ? WHERE id = ?",
            array($nextType, $title, $desc, $avatar, $handle, $vis, $history, $defTtl, $ttlMode, $autoDeleteSec, $slowMode, $maxMembers, $allMuted, json_encode($curPerms), $cid)
        );
        if ($autoDeleteSec > 0) {
            purge_auto_delete_chat_messages($db, $cid);
        }
        bump_tick();
        api_ok(array('chats' => fetch_user_chats($db, $me)));
    }

    if ($do === 'chat_mute_all_toggle') {
        $cid = isset($in['chat_id']) ? (int)$in['chat_id'] : 0;
        $chat = $db->one("SELECT * FROM chats WHERE id = ?", array($cid));
        $mem = $db->one("SELECT * FROM members WHERE chat_id = ? AND user_id = ?", array($cid, $myId));
        if (!$chat || $chat['type'] !== 'group' || !is_chat_admin_or_owner($chat, $mem, $me)) {
            api_err('forbidden', 'Only group owners or admins can mute/unmute the entire group.');
        }
        $newState = ((int)$chat['all_muted'] === 1) ? 0 : 1;
        if (isset($in['all_muted'])) {
            $newState = (int)$in['all_muted'] ? 1 : 0;
        }
        $db->exec("UPDATE chats SET all_muted = ? WHERE id = ?", array($newState, $cid));
        $sysText = $newState ? '🔇 ارسال پیام در گروه توسط مدیر محدود شد (فقط مدیران).' : '🔊 محدودیت ارسال پیام گروه برداشته شد.';
        $db->exec("INSERT INTO messages (chat_id, user_id, kind, body, created_at) VALUES (?, ?, 'system', ?, ?)", array($cid, $myId, $sysText, time()));
        bump_tick();
        api_ok(array('all_muted' => $newState, 'chats' => fetch_user_chats($db, $me)));
    }

    if ($do === 'chat_mute_toggle') {
        $cid = isset($in['chat_id']) ? (int)$in['chat_id'] : 0;
        $mem = $db->one("SELECT * FROM members WHERE chat_id = ? AND user_id = ?", array($cid, $myId));
        if (!$mem) api_err('not_member', 'Not a member of this chat.');
        $newMuted = ((int)$mem['muted'] === 1) ? 0 : 1;
        $db->exec("UPDATE members SET muted = ? WHERE chat_id = ? AND user_id = ?", array($newMuted, $cid, $myId));
        api_ok(array('muted' => $newMuted));
    }

    /* Layered switches for the chat-list preview and the message view counter.
       scope=me   -> the caller's own override on any chat they belong to
       scope=chat -> the chat-wide switch, for chat admins and super-admins
       A personal override can only hide something for me; it can never force a
       feature back on against a stricter chat-wide or global switch. */
    if ($do === 'chat_feature_set') {
        $cid     = isset($in['chat_id']) ? (int)$in['chat_id'] : 0;
        $feature = isset($in['feature']) ? (string)$in['feature'] : '';
        $enabled = isset($in['enabled']) ? ((int)$in['enabled'] ? 1 : 0) : 1;
        $scope   = (isset($in['scope']) && $in['scope'] === 'chat') ? 'chat' : 'me';
        if (!in_array($feature, array('chat_preview', 'msg_views'), true)) {
            api_err('bad_request', 'Unknown feature.');
        }
        $chat = $db->one("SELECT * FROM chats WHERE id = ?", array($cid));
        if (!$chat) api_err('not_found', 'Chat not found.');
        if ($feature === 'msg_views' && $chat['type'] !== 'group' && $chat['type'] !== 'channel') {
            api_err('not_supported', 'View counters only apply to groups and channels.');
        }
        $isSuper = ($me['role'] === 'superadmin');
        $mem = get_active_member($db, $cid, $myId);
        if (!$mem && !($isSuper && $chat['type'] !== 'secret')) {
            api_err('not_member', 'Not an active member of this chat.');
        }
        if ($scope === 'chat') {
            $canEdit = $isSuper || ($mem && in_array($mem['role'], array('owner', 'admin'), true));
            if (!$canEdit) api_err('forbidden', 'Only chat admins can change this for everyone.');
            $cp = parse_json_col(isset($chat['perms_json']) ? $chat['perms_json'] : '', array());
            $cp[$feature] = $enabled;
            $db->exec("UPDATE chats SET perms_json = ? WHERE id = ?", array(json_encode($cp), $cid));
        } else {
            if (!$mem) api_err('not_member', 'Not an active member of this chat.');
            $mp = parse_json_col(isset($mem['perms_json']) ? $mem['perms_json'] : '', array());
            if ($enabled) unset($mp[$feature]); else $mp[$feature] = 0;
            $db->exec("UPDATE members SET perms_json = ? WHERE chat_id = ? AND user_id = ?", array(json_encode($mp), $cid, $myId));
        }
        bump_tick();
        api_ok(array(
            'chat_id' => $cid,
            'feature' => $feature,
            'scope'   => $scope,
            'enabled' => $enabled,
            'chats'   => fetch_user_chats($db, $me)
        ));
    }

    if ($do === 'chat_personal_typing_set') {
        $cid = isset($in['chat_id']) ? (int)$in['chat_id'] : 0;
        $mode = normalize_typing_override_val(isset($in['mode']) ? $in['mode'] : 'inherit', 'personal_chat');
        $chat = $db->one("SELECT * FROM chats WHERE id = ?", array($cid));
        if (!$chat) api_err('not_found', 'Chat not found.');
        if (!is_chat_typing_supported_type($chat['type'])) {
            api_err('not_supported', 'Typing indicator is not supported in this chat type.');
        }
        $mem = get_active_member($db, $cid, $myId);
        if (!$mem) api_err('not_member', 'Not an active member of this chat.');
        $mPerms = parse_json_col(isset($mem['perms_json']) ? $mem['perms_json'] : '', array());
        $mPerms['my_typing_mode'] = $mode;
        $db->exec("UPDATE members SET perms_json = ? WHERE chat_id = ? AND user_id = ?", array(json_encode($mPerms), $cid, $myId));
        if ($mode === 'off') {
            clear_ephemeral_typing_for_user($db, $myId, $cid);
        } else {
            bump_typing_tick();
        }
        api_ok(array(
            'chat_id'        => $cid,
            'my_typing_mode' => $mode,
            'chats'          => fetch_user_chats($db, $me)
        ));
    }

    if ($do === 'chat_super_typing_set') {
        if (!$isSuper) api_err('forbidden', 'Super-admin access required.', 403);
        $cid = isset($in['chat_id']) ? (int)$in['chat_id'] : 0;
        $ov = normalize_typing_override_val(isset($in['override']) ? $in['override'] : 'inherit', 'chat');
        $chat = $db->one("SELECT * FROM chats WHERE id = ?", array($cid));
        if (!$chat) api_err('not_found', 'Chat not found.');
        if (!is_chat_typing_supported_type($chat['type'])) {
            api_err('not_supported', 'Typing indicator is not supported in channels or system chats.');
        }
        if ($chat['type'] === 'secret') {
            $mySecMem = get_active_member($db, $cid, $myId);
            if (!$mySecMem) api_err('forbidden', 'Secret chats are private to their participants.', 403);
        }
        $cPerms = parse_json_col(isset($chat['perms_json']) ? $chat['perms_json'] : '', array());
        $cPerms['super_typing_override'] = $ov;
        $db->exec("UPDATE chats SET perms_json = ? WHERE id = ?", array(json_encode($cPerms), $cid));
        if ($ov === 'force_off') {
            $db->exec("DELETE FROM meta WHERE k LIKE ?", array('typing_' . $cid . '_%'));
        }
        bump_typing_tick();
        bump_tick();
        $freshChat = $db->one("SELECT * FROM chats WHERE id = ?", array($cid));
        api_ok(array(
            'chat_id'               => $cid,
            'super_typing_override' => $ov,
            'chat'                  => build_single_chat_descriptor($db, $freshChat, $me, true),
            'chats'                 => fetch_user_chats($db, $me)
        ));
    }

    if ($do === 'chat_settings_reset') {
        if (empty($in['confirmed'])) {
            api_err('confirmation_required', 'تأیید عملیات بازنشانی الزامی است. / Confirmation is required.');
        }
        $cid = isset($in['chat_id']) ? (int)$in['chat_id'] : 0;
        $chat = $db->one("SELECT * FROM chats WHERE id = ?", array($cid));
        if (!$chat) api_err('not_found', 'Chat not found.');
        if ($chat['type'] === 'system') {
            api_err('system_chat_readonly', 'اعلان‌های پیام‌رسان یک‌طرفه است و تنظیمات آن قابل تغییر نیست. / Messenger Notifications settings are read-only.');
        }
        $mem = get_active_member($db, $cid, $myId);
        if (!$mem && (!$isSuper || $chat['type'] === 'secret')) {
            api_err('forbidden', 'Access denied.');
        }
        $resetScopes = array();

        // 1. Always reset caller's personal per-chat settings when caller is a member
        if ($mem) {
            $mPermsRst = parse_json_col(isset($mem['perms_json']) ? $mem['perms_json'] : '', array());
            unset($mPermsRst['my_typing_mode']);
            $nextMemPermsJson = empty($mPermsRst) ? '{}' : json_encode($mPermsRst);
            $db->exec(
                "UPDATE members SET muted = 0, pinned_at = 0, auto_delete_sec = 0, perms_json = ? WHERE chat_id = ? AND user_id = ?",
                array($nextMemPermsJson, $cid, $myId)
            );
            $resetScopes[] = 'personal';
        }

        // 2. Saved / DM / Secret: caller has authority over shared chat timers (if active member), and Super-Admin resets super_typing_override
        $resetShared = !isset($in['reset_shared']) || !empty($in['reset_shared']);
        if (in_array($chat['type'], array('saved', 'dm', 'secret'), true)) {
            if ($mem && ($chat['type'] === 'saved' || $resetShared)) {
                $db->exec(
                    "UPDATE chats SET default_ttl = 0, ttl_mode = 'expire_after_send', auto_delete_sec = 0 WHERE id = ?",
                    array($cid)
                );
                $resetScopes[] = 'timers';
            }
            if ($isSuper && $resetShared && ($chat['type'] === 'dm' || $chat['type'] === 'secret')) {
                $dmPermsRst = parse_json_col(isset($chat['perms_json']) ? $chat['perms_json'] : '', array());
                $dmPermsRst['super_typing_override'] = 'inherit';
                $db->exec("UPDATE chats SET perms_json = ? WHERE id = ?", array(json_encode($dmPermsRst), $cid));
                $resetScopes[] = 'superadmin_overrides';
            }
        } elseif (($chat['type'] === 'group' || $chat['type'] === 'channel') && $resetShared) {
            // 3. Group / Channel: strictly respect caller's exact permission level & granular admin flags!
            $isChatOwner = ($isSuper || (int)$chat['owner_id'] === $myId || ($mem && $mem['role'] === 'owner'));
            $isChatAdmin = ($isChatOwner || ($mem && $mem['role'] === 'admin'));
            if ($isChatAdmin) {
                $admPerms = ($isChatOwner)
                    ? array('edit_info' => 1, 'manage_content' => 1, 'manage_calls' => 1)
                    : parse_json_col($mem ? $mem['perms_json'] : '', array());
                $canEditInfoRst    = $isChatOwner || !empty($admPerms['edit_info']);
                $canManageContRst  = $isChatOwner || !empty($admPerms['manage_content']) || !empty($admPerms['delete_msgs']);
                $canManageCallsRst = $isChatOwner || !empty($admPerms['manage_calls']);

                $curPerms = parse_json_col($chat['perms_json'], array());
                $nextHistory = (string)$chat['history'];
                $nextDefTtl  = (int)$chat['default_ttl'];
                $nextTtlMode = (string)($chat['ttl_mode'] ?: 'expire_after_send');
                $nextAutoDel = (int)(isset($chat['auto_delete_sec']) ? $chat['auto_delete_sec'] : 0);
                $nextSlow    = (int)$chat['slow_mode'];
                $nextMaxMem  = (int)$chat['max_members'];
                $nextAllMute = (int)$chat['all_muted'];

                if ($canEditInfoRst) {
                    $nextHistory = 'all';
                    $nextDefTtl  = 0;
                    $nextTtlMode = 'expire_after_send';
                    $nextAutoDel = 0;
                    $nextSlow    = 0;
                    $nextMaxMem  = 0;
                    $nextAllMute = 0;
                    $defPermsInfo = array(
                        'send_text'               => ($chat['type'] === 'channel') ? 0 : 1,
                        'send_media'              => ($chat['type'] === 'channel') ? 0 : 1,
                        'send_voice'              => ($chat['type'] === 'channel') ? 0 : 1,
                        'invite'                  => 1,
                        'pin'                     => 0,
                        'join_approval'           => 0,
                        'reactions_enabled'       => 1,
                        'show_typing'             => ($chat['type'] === 'group') ? 1 : 0,
                        'hide_edit_badge'         => 0,
                        'allow_copy_msg'          => 1,
                        'allow_select_text'       => 1,
                        'allow_file_download'     => 1,
                        'allow_forward_msg'       => 1,
                        'admins_only'             => ($chat['type'] === 'channel') ? 1 : 0,
                        'hide_members'            => ($chat['type'] === 'channel') ? 1 : 0,
                        'show_owner_transfer_msg' => 1,
                        'show_admin_transfer_msg' => 1,
                        'msg_viewers_mode'        => 'default',
                        'idle_mode'               => 'off',
                        'idle_start'              => '23:00',
                        'idle_end'                => '07:00',
                        'idle_tz_offset'          => 0
                    );
                    foreach ($defPermsInfo as $dk => $dv) {
                        $curPerms[$dk] = $dv;
                    }
                    $resetScopes[] = 'edit_info';
                }

                if ($canManageContRst) {
                    $curPerms['restricted_content_types'] = array();
                    if (!$canEditInfoRst) {
                        $curPerms['reactions_enabled'] = 1;
                        if ($chat['type'] === 'group') $curPerms['show_typing'] = 1;
                        $curPerms['admins_only'] = ($chat['type'] === 'channel') ? 1 : 0;
                        $curPerms['hide_edit_badge'] = 0;
                        $curPerms['allow_copy_msg'] = 1;
                        $curPerms['allow_select_text'] = 1;
                        $curPerms['allow_file_download'] = 1;
                        $curPerms['allow_forward_msg'] = 1;
                        $curPerms['send_media'] = ($chat['type'] === 'channel') ? 0 : 1;
                        $curPerms['send_voice'] = ($chat['type'] === 'channel') ? 0 : 1;
                    }
                    $resetScopes[] = 'manage_content';
                }

                if ($canManageCallsRst) {
                    $curPerms['call_policy'] = normalize_call_policy(array(), 'chat');
                    $resetScopes[] = 'manage_calls';
                }

                // Strictly preserve Super-Admin overrides unless caller IS Super-Admin!
                if ($isSuper) {
                    $curPerms['super_max_members'] = 0;
                    $curPerms['super_msg_viewers_override'] = 'inherit';
                    $curPerms['super_typing_override'] = 'inherit';
                    $resetScopes[] = 'superadmin_overrides';
                }

                if ($canEditInfoRst || $canManageContRst || $canManageCallsRst || $isSuper) {
                    $db->exec(
                        "UPDATE chats SET history = ?, default_ttl = ?, ttl_mode = ?, auto_delete_sec = ?, slow_mode = ?, max_members = ?, all_muted = ?, perms_json = ? WHERE id = ?",
                        array($nextHistory, $nextDefTtl, $nextTtlMode, $nextAutoDel, $nextSlow, $nextMaxMem, $nextAllMute, json_encode($curPerms), $cid)
                    );
                }
            }
        }

        bump_tick();
        api_ok(array(
            'reset'        => true,
            'reset_scopes' => $resetScopes,
            'chats'        => fetch_user_chats($db, $me)
        ));
    }

    if ($do === 'chat_join') {
        $handleOrCode = '';
        if (isset($in['target']) && trim((string)$in['target']) !== '') {
            $handleOrCode = trim((string)$in['target']);
        } elseif (isset($in['handle']) && trim((string)$in['handle']) !== '') {
            $handleOrCode = trim((string)$in['handle']);
        } elseif (isset($in['invite_code']) && trim((string)$in['invite_code']) !== '') {
            $handleOrCode = trim((string)$in['invite_code']);
        }
        $chatId = isset($in['chat_id']) ? (int)$in['chat_id'] : 0;
        $now = time();
        $chat = null;
        $usedInvite = null;

        if ($chatId > 0) {
            if ($isSuper) {
                $chat = $db->one("SELECT * FROM chats WHERE id = ?", array($chatId));
            } else {
                $chat = $db->one("SELECT * FROM chats WHERE id = ? AND visibility = 'public' AND status = 'active'", array($chatId));
            }
        } elseif ($handleOrCode !== '') {
            $clean = ltrim($handleOrCode, '@');
            $inv = $db->one("SELECT * FROM invites WHERE code = ? AND revoked = 0", array($clean));
            if ($inv) {
                if (!empty($inv['expires_at']) && (int)$inv['expires_at'] <= $now) {
                    api_err('invite_expired', 'This invite link has expired.');
                }
                if ((int)$inv['max_uses'] > 0 && (int)$inv['uses'] >= (int)$inv['max_uses']) {
                    api_err('invite_exhausted', 'This invite link has reached its maximum uses.');
                }
                $chat = $db->one("SELECT * FROM chats WHERE id = ? AND status = 'active'", array((int)$inv['chat_id']));
                $usedInvite = $inv;
            } else {
                $chat = $db->one("SELECT * FROM chats WHERE handle = ? AND visibility = 'public' AND status = 'active'", array(u_lower($clean)));
            }
        }

        if (!$chat || !in_array($chat['type'], array('group', 'channel'), true)) {
            api_err('chat_not_found', 'Public group/channel or valid invite link not found.');
        }

        $cid = (int)$chat['id'];
        $existingMem = $db->one("SELECT * FROM members WHERE chat_id = ? AND user_id = ?", array($cid, $myId));
        if ($existingMem) {
            if (!empty($existingMem['banned_until']) && (int)$existingMem['banned_until'] > $now && !$isSuper) {
                api_err('banned_in_chat', 'You are banned from this chat.');
            }
            if ($isSuper && ($existingMem['role'] === 'pending' || !empty($existingMem['banned_until']))) {
                $db->exec("UPDATE members SET role = 'member', banned_until = NULL WHERE chat_id = ? AND user_id = ?", array($cid, $myId));
                bump_tick();
            }
            api_ok(array('chat_id' => $cid, 'chats' => fetch_user_chats($db, $me)));
        }

        verify_user_chat_capacity($db, $me, false);
        $capJoin = resolve_chat_member_capacity($db, $chat);
        $curCount = (int)$db->val("SELECT COUNT(*) FROM members WHERE chat_id = ? AND role != 'pending'", array($cid));
        if ($capJoin['effective_max'] > 0 && $curCount >= $capJoin['effective_max'] && !$isSuper) {
            api_err('chat_full', 'ظرفیت اعضای این گفتگو تکمیل شده است (' . $capJoin['effective_max'] . '). / This chat has reached its maximum member capacity (' . $capJoin['effective_max'] . ').');
        }

        $maxMsgId = (int)$db->val("SELECT COALESCE(MAX(id), 0) FROM messages WHERE chat_id = ?", array($cid));
        $joinedMsgId = (!$isSuper && $chat['history'] === 'from_join') ? $maxMsgId : 0;
        $chatPerms = parse_json_col($chat['perms_json'], array('join_approval' => 0));
        $role = (!empty($chatPerms['join_approval']) && !$isSuper) ? 'pending' : 'member';

        $db->insertIgnore('members', array(
            'chat_id'       => $cid,
            'user_id'       => $myId,
            'role'          => $role,
            'perms_json'    => '{}',
            'joined_msg_id' => $joinedMsgId,
            'last_read_id'  => $maxMsgId,
            'muted'         => 0,
            'last_msg_at'   => 0,
            'joined_at'     => $now
        ));
        if ($usedInvite) {
            $db->exec("UPDATE invites SET uses = uses + 1 WHERE id = ?", array((int)$usedInvite['id']));
        }
        bump_tick();
        api_ok(array('chat_id' => $cid, 'status' => $role, 'chats' => fetch_user_chats($db, $me)));
    }

    if ($do === 'chat_auto_delete_set') {
        $cid = isset($in['chat_id']) ? (int)$in['chat_id'] : 0;
        $sec = isset($in['seconds']) ? max(0, min(86400 * 3650, (int)$in['seconds'])) : 0;
        $scope = isset($in['scope']) && $in['scope'] === 'mine' ? 'mine' : 'both';
        $chat = $db->one("SELECT * FROM chats WHERE id = ?", array($cid));
        $mem = get_active_member($db, $cid, $myId);
        if (!$chat) api_err('not_found', 'Chat not found.');
        if ($chat['type'] === 'group' || $chat['type'] === 'channel') {
            if ($scope === 'mine') {
                if (!$mem) api_err('forbidden', 'Not an active member of this chat.');
                $db->exec("UPDATE members SET auto_delete_sec = ? WHERE chat_id = ? AND user_id = ?", array($sec, $cid, $myId));
            } else {
                if (!is_chat_admin_or_owner($chat, $mem, $me)) {
                    api_err('forbidden', 'Only admins can configure shared message auto-delete in groups and channels.');
                }
                $db->exec("UPDATE chats SET auto_delete_sec = ? WHERE id = ?", array($sec, $cid));
            }
        } else {
            if (!$mem && !$isSuper) api_err('forbidden', 'Not an active member of this chat.');
            if ($chat['type'] === 'saved' || $scope === 'both') {
                $db->exec("UPDATE chats SET auto_delete_sec = ? WHERE id = ?", array($sec, $cid));
            } else {
                $db->exec("UPDATE members SET auto_delete_sec = ? WHERE chat_id = ? AND user_id = ?", array($sec, $cid, $myId));
            }
        }
        purge_auto_delete_chat_messages($db, $cid);
        bump_tick();
        api_ok(array('auto_delete_sec' => $sec, 'scope' => $scope, 'chats' => fetch_user_chats($db, $me)));
    }

    if ($do === 'chat_default_ttl_set') {
        $cid = isset($in['chat_id']) ? (int)$in['chat_id'] : 0;
        $ttlSec = isset($in['default_ttl']) ? max(0, min(86400 * 365, (int)$in['default_ttl'])) : 0;
        $ttlMode = (isset($in['ttl_mode']) && in_array($in['ttl_mode'], array('expire_after_send', 'burn_after_read'), true)) ? $in['ttl_mode'] : 'expire_after_send';
        $chat = $db->one("SELECT * FROM chats WHERE id = ?", array($cid));
        $mem = get_active_member($db, $cid, $myId);
        if (!$chat) api_err('not_found', 'Chat not found.');
        if ($chat['type'] === 'group' || $chat['type'] === 'channel') {
            if (!is_chat_admin_or_owner($chat, $mem, $me)) {
                api_err('forbidden', 'Only admins can configure default self-destruct timer in groups and channels.');
            }
        } else {
            if (!$mem && (!$isSuper || $chat['type'] === 'secret')) {
                api_err('forbidden', 'Not an active member of this chat.');
            }
        }
        $db->exec("UPDATE chats SET default_ttl = ?, ttl_mode = ? WHERE id = ?", array($ttlSec, $ttlMode, $cid));
        bump_tick();
        api_ok(array('default_ttl' => $ttlSec, 'ttl_mode' => $ttlMode, 'chats' => fetch_user_chats($db, $me)));
    }

    if ($do === 'chat_call_history') {
        $cid = isset($in['chat_id']) ? (int)$in['chat_id'] : 0;
        $chat = $db->one("SELECT * FROM chats WHERE id = ?", array($cid));
        $mem = get_active_member($db, $cid, $myId);
        if (!$chat || !in_array($chat['type'], array('dm', 'group', 'channel'), true)) {
            api_ok(array('calls' => array()));
        }
        if (!$mem && !$isSuper) {
            api_err('forbidden', 'Access denied.');
        }
        $minId = (!$isSuper && $mem && !empty($mem['joined_msg_id'])) ? (int)$mem['joined_msg_id'] : 0;
        $rowsCh = $db->all(
            "SELECT id, user_id, body, hidden_for, created_at
             FROM messages
             WHERE chat_id = ? AND kind = 'call_log' AND id >= ? AND deleted_at IS NULL
             ORDER BY id DESC " . $db->limit(50),
            array($cid, $minId)
        );
        $callsOut = array();
        foreach ($rowsCh as $rch) {
            if (is_hidden_for_user($rch['hidden_for'], $myId)) continue;
            $cj = json_decode((string)$rch['body'], true);
            if (!is_array($cj)) $cj = array();
            $cNameVal = isset($cj['caller_name']) ? (string)$cj['caller_name'] : (isset($cj['starter_name']) ? (string)$cj['starter_name'] : ('#' . (int)$rch['user_id']));
            $cUnameVal = isset($cj['caller_username']) ? (string)$cj['caller_username'] : (isset($cj['starter_username']) ? (string)$cj['starter_username'] : '');
            $cIdVal = isset($cj['caller_id']) ? (int)$cj['caller_id'] : (isset($cj['starter_id']) ? (int)$cj['starter_id'] : (int)$rch['user_id']);
            $reqTsVal = isset($cj['requested_at']) ? (int)$cj['requested_at'] : (int)$rch['created_at'];
            $callsOut[] = array(
                'message_id'       => (int)$rch['id'],
                'call_type'        => (isset($cj['call_type']) && $cj['call_type'] === 'video') ? 'video' : 'voice',
                'caller_id'        => $cIdVal,
                'starter_id'       => $cIdVal,
                'caller_name'      => $cNameVal,
                'starter_name'     => $cNameVal,
                'caller_username'  => $cUnameVal,
                'starter_username' => $cUnameVal,
                'status'           => isset($cj['status']) ? (string)$cj['status'] : 'ended',
                'requested_at'     => $reqTsVal,
                'created_at'       => $reqTsVal,
                'answered_at'      => isset($cj['answered_at']) ? (int)$cj['answered_at'] : 0,
                'ended_at'         => isset($cj['ended_at']) ? (int)$cj['ended_at'] : 0,
                'duration_sec'     => isset($cj['duration_sec']) ? (int)$cj['duration_sec'] : 0
            );
        }
        api_ok(array('calls' => $callsOut));
    }

    if ($do === 'chat_leave') {
        $cid = isset($in['chat_id']) ? (int)$in['chat_id'] : 0;
        $chat = $db->one("SELECT * FROM chats WHERE id = ?", array($cid));
        if (!$chat) api_err('not_found', 'Chat not found.');

        verify_can_leave_chat($chat, $me);

        if ((int)$chat['owner_id'] === $myId && in_array($chat['type'], array('group', 'channel'), true)) {
            $nextOwner = $db->one(
                "SELECT m.user_id, u.name FROM members m LEFT JOIN users u ON u.id = m.user_id WHERE m.chat_id = ? AND m.user_id != ? AND m.role != 'pending' ORDER BY m.joined_at ASC, m.user_id ASC LIMIT 1",
                array($cid, $myId)
            );
            if ($nextOwner) {
                $newOwnerId = (int)$nextOwner['user_id'];
                $newOwnerName = !empty($nextOwner['name']) ? (string)$nextOwner['name'] : ('#' . $newOwnerId);
                $db->exec("UPDATE chats SET owner_id = ? WHERE id = ?", array($newOwnerId, $cid));
                $db->exec("UPDATE members SET role = 'owner', banned_until = NULL, restricted_until = NULL WHERE chat_id = ? AND user_id = ?", array($cid, $newOwnerId));
                $cPerms = parse_json_col($chat['perms_json'], array('show_owner_transfer_msg' => 1));
                $showTransferAll = (!isset($cPerms['show_owner_transfer_msg']) || (int)$cPerms['show_owner_transfer_msg'] === 1);
                $visTo = $showTransferAll ? null : $newOwnerId;
                $sysBody = ($chat['type'] === 'channel')
                    ? ('👑 مالکیت کانال به قدیمی‌ترین عضو (' . $newOwnerName . ') منتقل شد.')
                    : ('👑 مالکیت گروه به قدیمی‌ترین عضو (' . $newOwnerName . ') منتقل شد.');
                $db->exec(
                    "INSERT INTO messages (chat_id, user_id, kind, body, visible_only_to, created_at) VALUES (?, 0, 'system', ?, ?, ?)",
                    array($cid, $sysBody, $visTo, app_now($db))
                );
            }
        }

        $db->exec("DELETE FROM members WHERE chat_id = ? AND user_id = ?", array($cid, $myId));
        bump_tick();
        api_ok(array('chats' => fetch_user_chats($db, $me)));
    }

    if ($do === 'chat_pin_toggle') {
        $cid = isset($in['chat_id']) ? (int)$in['chat_id'] : 0;
        $mem = $db->one("SELECT * FROM members WHERE chat_id = ? AND user_id = ?", array($cid, $myId));
        if (!$mem) api_err('not_member', 'Not a member of this chat.');
        $curPin = isset($mem['pinned_at']) ? (int)$mem['pinned_at'] : 0;
        if (isset($in['pinned'])) {
            $newPin = (int)$in['pinned'] ? time() : 0;
        } else {
            $newPin = ($curPin > 0) ? 0 : time();
        }
        $db->exec("UPDATE members SET pinned_at = ? WHERE chat_id = ? AND user_id = ?", array($newPin, $cid, $myId));
        api_ok(array('pinned' => ($newPin > 0 ? 1 : 0), 'chats' => fetch_user_chats($db, $me)));
    }

    if ($do === 'chat_notif_mute_toggle') {
        $cid = isset($in['chat_id']) ? (int)$in['chat_id'] : 0;
        $mem = $db->one("SELECT * FROM members WHERE chat_id = ? AND user_id = ?", array($cid, $myId));
        if (!$mem) api_err('not_member', 'Not a member of this chat.');
        $curMute = (int)$mem['muted'];
        $newMute = isset($in['muted']) ? ((int)$in['muted'] ? 1 : 0) : ($curMute === 1 ? 0 : 1);
        $db->exec("UPDATE members SET muted = ? WHERE chat_id = ? AND user_id = ?", array($newMute, $cid, $myId));
        api_ok(array('muted' => $newMute, 'chats' => fetch_user_chats($db, $me)));
    }

    if ($do === 'chat_mark_read') {
        $cid = isset($in['chat_id']) ? (int)$in['chat_id'] : 0;
        $mem = get_active_member($db, $cid, $myId);
        if (!$mem) api_err('not_member', 'Not an active member of this chat.');
        $myFlags = get_user_flags($me);
        $suppressTicks = (!empty($myFlags['user_ghost_mode']) || empty($myFlags['read_receipts']));
        $upToId = (int)$db->val("SELECT COALESCE(MAX(id), 0) FROM messages WHERE chat_id = ? AND deleted_at IS NULL", array($cid));
        if ($upToId > (int)$mem['last_read_id']) {
            if ($suppressTicks) {
                $db->exec("UPDATE members SET last_read_id = ? WHERE chat_id = ? AND user_id = ?", array($upToId, $cid, $myId));
            } else {
                $newReceipt = max((int)$mem['receipt_read_id'], $upToId);
                $db->exec("UPDATE members SET last_read_id = ?, receipt_read_id = ? WHERE chat_id = ? AND user_id = ?", array($upToId, $newReceipt, $cid, $myId));
            }
            bump_tick();
        }
        $activatedBurns = $suppressTicks ? array() : activate_first_view_burns($db, $cid, $upToId, $myId);
        api_ok(array('last_read_id' => $upToId, 'activated_burns' => $activatedBurns, 'chats' => fetch_user_chats($db, $me)));
    }

    if ($do === 'chats_mark_read_bulk') {
        $rawIds = isset($in['chat_ids']) && is_array($in['chat_ids']) ? $in['chat_ids'] : array();
        $myFlags = get_user_flags($me);
        $suppressTicks = (!empty($myFlags['user_ghost_mode']) || empty($myFlags['read_receipts']));
        $markedCount = 0;
        foreach ($rawIds as $rcid) {
            $cid = (int)$rcid;
            if ($cid <= 0) continue;
            $mem = get_active_member($db, $cid, $myId);
            if (!$mem) continue;
            $upToId = (int)$db->val("SELECT COALESCE(MAX(id), 0) FROM messages WHERE chat_id = ? AND deleted_at IS NULL", array($cid));
            if ($upToId > (int)$mem['last_read_id']) {
                if ($suppressTicks) {
                    $db->exec("UPDATE members SET last_read_id = ? WHERE chat_id = ? AND user_id = ?", array($upToId, $cid, $myId));
                } else {
                    $newReceipt = max((int)$mem['receipt_read_id'], $upToId);
                    $db->exec("UPDATE members SET last_read_id = ?, receipt_read_id = ? WHERE chat_id = ? AND user_id = ?", array($upToId, $newReceipt, $cid, $myId));
                }
                $markedCount++;
            }
            if (!$suppressTicks) {
                activate_first_view_burns($db, $cid, $upToId, $myId);
            }
        }
        if ($markedCount > 0) bump_tick();
        api_ok(array('marked_count' => $markedCount, 'chats' => fetch_user_chats($db, $me)));
    }

    if ($do === 'chat_hide_for_me') {
        $cid = isset($in['chat_id']) ? (int)$in['chat_id'] : 0;
        $chat = $db->one("SELECT * FROM chats WHERE id = ?", array($cid));
        if (!$chat) api_err('not_found', 'Chat not found.');
        // Only 1:1 chats support "remove from my list only": a group/channel member
        // simply leaves, and a secret chat is destroyed for both sides by design.
        if ($chat['type'] !== 'dm') {
            api_err('not_supported', 'Only one-to-one chats can be removed for one side only.');
        }
        $mem = $db->one("SELECT * FROM members WHERE chat_id = ? AND user_id = ?", array($cid, $myId));
        if (!$mem && !$isSuper) api_err('not_member', 'Not a member of this chat.');
        if ($mem) {
            $db->exec(
                "UPDATE members SET left_at = ?, last_read_id = (SELECT COALESCE(MAX(id),0) FROM messages WHERE chat_id = ?) WHERE chat_id = ? AND user_id = ?",
                array(time(), $cid, $cid, $myId)
            );
        }
        bump_tick();
        api_ok(array('hidden' => true, 'chats' => fetch_user_chats($db, $me)));
    }

    if ($do === 'chat_delete_conversation') {
        $cid = isset($in['chat_id']) ? (int)$in['chat_id'] : 0;
        $chat = $db->one("SELECT * FROM chats WHERE id = ?", array($cid));
        if (!$chat) api_err('not_found', 'Chat not found.');
        if ($chat['type'] === 'system') {
            api_err('forbidden', 'Official System Chat cannot be deleted or cleared.');
        }
        $mem = $db->one("SELECT * FROM members WHERE chat_id = ? AND user_id = ?", array($cid, $myId));
        if (!$mem && !$isSuper) api_err('not_member', 'Not a member of this chat.');

        if ($chat['type'] === 'saved') {
            $msgFileRows = $db->all("SELECT DISTINCT file_id FROM messages WHERE chat_id = ? AND file_id IS NOT NULL", array($cid));
            $savedFiles = $db->all("SELECT id FROM files WHERE chat_id = ?", array($cid));
            $db->exec("DELETE FROM reactions WHERE message_id IN (SELECT id FROM messages WHERE chat_id = ?)", array($cid));
            $db->exec("DELETE FROM messages WHERE chat_id = ?", array($cid));
            $candIds = array();
            foreach ($msgFileRows as $r) { if (!empty($r['file_id'])) $candIds[(int)$r['file_id']] = true; }
            foreach ($savedFiles as $sf) { if (!empty($sf['id'])) $candIds[(int)$sf['id']] = true; }
            foreach (array_keys($candIds) as $fid) { release_file_if_unreferenced($db, $fid, 0); }
            bump_tick();
            api_ok(array('cleared_saved' => true, 'chats' => fetch_user_chats($db, $me)));
        }

        if ($chat['type'] === 'dm' || $chat['type'] === 'secret') {
            delete_chat_completely($db, $cid);
            bump_tick();
            api_ok(array('deleted' => true, 'chats' => fetch_user_chats($db, $me)));
        }

        if (((int)$chat['owner_id'] === $myId || $isSuper) && (int)$chat['is_default'] !== 1) {
            delete_chat_completely($db, $cid);
            bump_tick();
            api_ok(array('deleted' => true, 'chats' => fetch_user_chats($db, $me)));
        }

        verify_can_leave_chat($chat, $me);
        $db->exec("DELETE FROM members WHERE chat_id = ? AND user_id = ?", array($cid, $myId));
        bump_tick();
        api_ok(array('left' => true, 'chats' => fetch_user_chats($db, $me)));
    }

    if ($do === 'chat_clear_history') {
        $cid = isset($in['chat_id']) ? (int)$in['chat_id'] : 0;
        $mode = (isset($in['mode']) && $in['mode'] === 'everyone') ? 'everyone' : 'me';
        $chat = $db->one("SELECT * FROM chats WHERE id = ?", array($cid));
        if (!$chat) api_err('not_found', 'Chat not found.');
        $mem = get_active_member($db, $cid, $myId);
        if (!$mem && (!$isSuper || $chat['type'] === 'secret')) {
            api_err('forbidden', 'Not an active member of this chat.');
        }

        if ($chat['type'] === 'saved') {
            $mode = 'everyone';
        }

        if ($mode === 'everyone') {
            $canClearEveryone = false;
            if ($chat['type'] === 'saved' || $chat['type'] === 'dm' || $chat['type'] === 'secret') {
                $canClearEveryone = ($mem !== null || ($isSuper && $chat['type'] !== 'secret'));
            } else {
                $canClearEveryone = has_admin_perm($chat, $mem, $me, 'delete_messages');
            }
            if (!$canClearEveryone) {
                api_err('forbidden', 'شما مجوز پاک‌سازی دوطرفه تاریخچه این گفتگو را ندارید. / Permission denied to clear history for everyone.');
            }
            $activeRows = $db->all("SELECT id FROM messages WHERE chat_id = ? AND deleted_at IS NULL", array($cid));
            $seedIds = array();
            foreach ($activeRows as $ar) $seedIds[] = (int)$ar['id'];
            if (!empty($seedIds)) {
                cascade_delete_messages_by_ids($db, $seedIds, false);
            }
            $db->exec("UPDATE messages SET pinned = 0 WHERE chat_id = ?", array($cid));
            $db->exec("UPDATE members SET pinned_msg_id = 0 WHERE chat_id = ?", array($cid));
            bump_tick();
            api_ok(array(
                'cleared'       => true,
                'mode'          => 'everyone',
                'cleared_count' => count($seedIds),
                'chats'         => fetch_user_chats($db, $me)
            ));
        }

        // Personal clear ('me'): hide all current messages in this chat for $myId without affecting others
        $rowsMe = $db->all("SELECT id, hidden_for FROM messages WHERE chat_id = ? AND deleted_at IS NULL", array($cid));
        $clearedCount = 0;
        $maxMid = 0;
        $db->tx(function() use ($db, $rowsMe, $myId, &$clearedCount, &$maxMid) {
            foreach ($rowsMe as $rm) {
                $mid = (int)$rm['id'];
                if ($mid > $maxMid) $maxMid = $mid;
                $hf = !empty($rm['hidden_for']) ? json_decode((string)$rm['hidden_for'], true) : array();
                if (!is_array($hf)) $hf = array();
                if (!in_array($myId, $hf, true)) {
                    $hf[] = $myId;
                    $db->exec("UPDATE messages SET hidden_for = ? WHERE id = ?", array(json_encode($hf), $mid));
                    $clearedCount++;
                }
            }
        });
        if ($mem) {
            $newLastRead = max((int)$mem['last_read_id'], $maxMid);
            $db->exec("UPDATE members SET last_read_id = ?, pinned_msg_id = 0 WHERE chat_id = ? AND user_id = ?", array($newLastRead, $cid, $myId));
        }
        api_ok(array(
            'cleared'       => true,
            'mode'          => 'me',
            'cleared_count' => $clearedCount,
            'chats'         => fetch_user_chats($db, $me)
        ));
    }

    if ($do === 'chat_transfer_ownership') {
        $cid = isset($in['chat_id']) ? (int)$in['chat_id'] : 0;
        $targetUid = isset($in['target_user_id']) ? (int)$in['target_user_id'] : (isset($in['user_id']) ? (int)$in['user_id'] : 0);
        $chat = $db->one("SELECT * FROM chats WHERE id = ? AND type IN ('group', 'channel')", array($cid));
        if (!$chat) api_err('not_found', 'Group or channel not found.');
        $myMem = get_active_member($db, $cid, $myId);
        $isCurrentOwner = ((int)$chat['owner_id'] === $myId) || ($myMem && $myMem['role'] === 'owner');
        if (!$isCurrentOwner && !$isSuper) {
            api_err('forbidden', 'فقط مالک فعلی یا مدیر کل می‌تواند مالکیت را منتقل کند. / Only the current owner or Super-Admin can transfer ownership.');
        }
        if (!$isSuper) {
            $curPass = isset($in['current_password']) ? (string)$in['current_password'] : '';
            if ($curPass === '' || !password_verify($curPass, (string)$me['pass_hash'])) {
                api_err('wrong_password', 'رمز عبور فعلی حساب شما اشتباه است. / Current account password is incorrect.');
            }
        }
        if ($targetUid <= 0 || $targetUid === (int)$chat['owner_id']) {
            api_err('invalid_target', 'عضو مقصد برای انتقال مالکیت معتبر نیست. / Invalid target member.');
        }
        $targetMem = get_active_member($db, $cid, $targetUid);
        $targetUser = $db->one("SELECT id, name, username, status FROM users WHERE id = ?", array($targetUid));
        if (!$targetMem || !$targetUser || $targetUser['status'] !== 'active') {
            api_err('invalid_target', 'کاربر انتخاب‌شده باید عضو فعال این گفتگو باشد. / Target user must be an active member of this chat.');
        }
        $prevOwnerId = (int)$chat['owner_id'];
        $fullAdminPerms = json_encode(array_merge(get_default_admin_perms(), array('manage_admins' => 1)));
        $db->tx(function() use ($db, $cid, $prevOwnerId, $targetUid, $fullAdminPerms) {
            $db->exec("UPDATE chats SET owner_id = ? WHERE id = ?", array($targetUid, $cid));
            if ($prevOwnerId > 0 && $prevOwnerId !== $targetUid) {
                $db->exec("UPDATE members SET role = 'admin', perms_json = ? WHERE chat_id = ? AND user_id = ? AND role = 'owner'", array($fullAdminPerms, $cid, $prevOwnerId));
            }
            $db->exec("UPDATE members SET role = 'owner', perms_json = '{}', banned_until = NULL, restricted_until = NULL WHERE chat_id = ? AND user_id = ?", array($cid, $targetUid));
        });
        $cPermsTr = parse_json_col(isset($chat['perms_json']) ? $chat['perms_json'] : '', array('show_owner_transfer_msg' => 1));
        if (!isset($cPermsTr['show_owner_transfer_msg']) || !empty($cPermsTr['show_owner_transfer_msg'])) {
            $sysTxt = '👑 مالکیت گفتگو به «' . $targetUser['name'] . '» منتقل شد.';
            $db->exec(
                "INSERT INTO messages (chat_id, user_id, kind, body, created_at, pinned) VALUES (?, ?, 'system', ?, ?, 0)",
                array($cid, $targetUid, $sysTxt, app_now($db))
            );
        }
        bump_tick();
        api_ok(array('transferred' => true, 'new_owner_id' => $targetUid, 'chats' => fetch_user_chats($db, $me)));
    }

    if ($do === 'chat_delete') {
        $cid = isset($in['chat_id']) ? (int)$in['chat_id'] : 0;
        $chat = $db->one("SELECT * FROM chats WHERE id = ?", array($cid));
        if (!$chat) api_err('not_found', 'Chat not found.');
        if ($chat['type'] === 'system') {
            api_err('forbidden', 'Official System Chat cannot be deleted.');
        }
        if ((int)$chat['owner_id'] !== $myId && !$isSuper) {
            api_err('forbidden', 'Only the owner or super-admin can delete this chat.');
        }
        if ((int)$chat['is_default'] === 1 && !$isSuper) {
            api_err('forbidden', 'Default system chats cannot be deleted.');
        }
        delete_chat_completely($db, $cid);
        bump_tick();
        api_ok(array('chats' => fetch_user_chats($db, $me)));
    }

    if ($do === 'member_list') {
        $cid = isset($in['chat_id']) ? (int)$in['chat_id'] : 0;
        $chat = $db->one("SELECT * FROM chats WHERE id = ?", array($cid));
        $myMem = get_active_member($db, $cid, $myId);
        if (!$chat || (!$myMem && !$isSuper)) {
            api_err('forbidden', 'Access denied.');
        }
        if (in_array($chat['type'], array('dm', 'secret', 'saved'), true)) {
            api_ok(array('members' => array(), 'invites' => array(), 'members_hidden' => true));
        }
        $canSeeInvites = can_member_invite_in_chat($chat, $myMem, $me);
        if ($chat['type'] === 'channel' && !is_chat_admin_or_owner($chat, $myMem, $me)) {
            $chanInvites = $canSeeInvites ? $db->all("SELECT * FROM invites WHERE chat_id = ? AND revoked = 0 ORDER BY id DESC", array($cid)) : array();
            api_ok(array(
                'members'        => array(),
                'invites'        => $chanInvites,
                'can_invite'     => $canSeeInvites ? 1 : 0,
                'members_hidden' => true
            ));
        }
        if ($chat['type'] === 'group' && !is_chat_admin_or_owner($chat, $myMem, $me)) {
            $grpPermsVis = parse_json_col($chat['perms_json'], array());
            if (!empty($grpPermsVis['hide_members'])) {
                $grpInvites = $canSeeInvites ? $db->all("SELECT * FROM invites WHERE chat_id = ? AND revoked = 0 ORDER BY id DESC", array($cid)) : array();
                api_ok(array(
                    'members'        => array(),
                    'invites'        => $grpInvites,
                    'can_invite'     => $canSeeInvites ? 1 : 0,
                    'members_hidden' => true
                ));
            }
        }
        $isAdmOrOwn = is_chat_admin_or_owner($chat, $myMem, $me);
        // Rank ladder used by shadow-ban: 3 super-admin > 2 owner > 1 admin > 0 member.
        // Sent to the client so the member list never offers an action the server
        // would refuse, and so the client does not have to re-derive the ladder.
        $mlViewerRank = 0;
        if ($isSuper) $mlViewerRank = 3;
        elseif (!empty($chat['owner_id']) && (int)$chat['owner_id'] === (int)$myId) $mlViewerRank = 2;
        elseif ($myMem && $myMem['role'] === 'owner') $mlViewerRank = 2;
        elseif ($myMem && $myMem['role'] === 'admin') $mlViewerRank = 1;
        $nowMl = time();
        $sqlWhereMl = $isAdmOrOwn
            ? "m.chat_id = ? AND m.role != 'pending'"
            : "m.chat_id = ? AND m.role != 'pending' AND (m.banned_until IS NULL OR m.banned_until <= ?)";
        $sqlParamsMl = $isAdmOrOwn ? array($cid) : array($cid, $nowMl);
        $rows = $db->all(
            "SELECT m.*, u.username, u.name, u.bio, u.avatar, u.role AS global_role, u.status AS user_status, u.show_admin_badge, u.flags, u.last_seen_bucket
             FROM members m
             JOIN users u ON u.id = m.user_id
             WHERE {$sqlWhereMl}
             ORDER BY CASE m.role WHEN 'owner' THEN 0 WHEN 'admin' THEN 1 WHEN 'member' THEN 2 ELSE 3 END, m.joined_at ASC",
            $sqlParamsMl
        );
        $members = array();
        foreach ($rows as $r) {
            $uFlags = parse_json_col($r['flags'], array('deny_dm' => 0, 'hide_last_seen' => 0, 'no_username' => 0));
            $isSup = ($r['global_role'] === 'superadmin');
            $hasBadge = $isSup && ((int)$r['show_admin_badge'] === 1);
            $canDm = $isSuper || empty($uFlags['deny_dm']);
            $mPermsRow = parse_json_col($r['perms_json'], array());
            $isBannedRow = ($r['banned_until'] && (int)$r['banned_until'] > $nowMl) ? 1 : 0;
            $mlRank = $isSup ? 3
                : ((!empty($chat['owner_id']) && (int)$chat['owner_id'] === (int)$r['user_id']) ? 2
                : (($r['role'] === 'owner') ? 2 : (($r['role'] === 'admin') ? 1 : 0)));
            $members[] = array(
                'id'               => (int)$r['user_id'],
                'user_id'          => (int)$r['user_id'],
                'username'         => (!empty($uFlags['no_username']) && !$isSuper) ? '' : $r['username'],
                'mute_send'        => !empty($mPermsRow['mute_send']) ? 1 : 0,
                'mute_react'       => !empty($mPermsRow['mute_react']) ? 1 : 0,
                'is_superadmin'    => $isSup ? 1 : 0,
                'name'             => $r['name'],
                'bio'              => $r['bio'],
                'avatar'           => $r['avatar'],
                'chat_role'        => $r['role'],
                'global_role'      => $r['global_role'],
                'has_admin_badge'  => $hasBadge,
                'perms'            => ($r['role'] === 'admin') ? parse_json_col($r['perms_json'], get_default_admin_perms()) : parse_json_col($r['perms_json'], array()),
                'banned_until'     => $r['banned_until'] ? (int)$r['banned_until'] : null,
                'is_banned'        => $isBannedRow,
                'shadow_banned'    => !empty($r['shadow_banned']) ? 1 : 0,
                'shadow_banned_at' => $r['shadow_banned_at'] ? (int)$r['shadow_banned_at'] : null,
                'rank'             => $mlRank,
                'restricted_until' => $r['restricted_until'] ? (int)$r['restricted_until'] : null,
                'can_dm'           => $canDm,
                'deny_dm'          => !empty($uFlags['deny_dm']) ? 1 : 0,
                'joined_at'        => (int)$r['joined_at']
            );
        }
        $invitesList = $canSeeInvites ? $db->all("SELECT * FROM invites WHERE chat_id = ? AND revoked = 0 ORDER BY id DESC", array($cid)) : array();
        api_ok(array('members' => $members, 'invites' => $invitesList, 'can_invite' => $canSeeInvites ? 1 : 0, 'my_rank' => $mlViewerRank));
    }

    if ($do === 'member_add') {
        $cid = isset($in['chat_id']) ? (int)$in['chat_id'] : 0;
        $targetUid = isset($in['user_id']) ? (int)$in['user_id'] : 0;
        $targetUname = isset($in['username']) ? u_lower(trim(ltrim((string)$in['username'], '@'))) : '';
        $chat = $db->one("SELECT * FROM chats WHERE id = ? AND type IN ('group', 'channel')", array($cid));
        if (!$chat) api_err('not_found', 'Group or channel not found.');
        if ($chat['status'] !== 'active' && !$isSuper) api_err('chat_blocked', 'This chat is restricted.');
        $myMem = get_active_member($db, $cid, $myId);
        if (!can_member_invite_in_chat($chat, $myMem, $me)) {
            api_err('forbidden', 'شما مجوز دعوت یا افزودن عضو به این گفتگو را ندارید. / Permission denied to add members.');
        }
        if ($targetUid <= 0 && $targetUname !== '') {
            $tuAdd = $db->one("SELECT * FROM users WHERE username = ? AND status = 'active'", array($targetUname));
            if (!$tuAdd) {
                api_err('user_not_found', 'کاربر @' . $targetUname . ' یافت نشد. / User @' . $targetUname . ' was not found.');
            }
            $tuFlAdd = get_user_flags($tuAdd);
            if ((!empty($tuFlAdd['no_username']) || !empty($tuFlAdd['hide_search'])) && !$isSuper) {
                api_err('user_not_found', 'کاربر @' . $targetUname . ' یافت نشد. / User @' . $targetUname . ' was not found.');
            }
            $targetUid = (int)$tuAdd['id'];
        }
        $targetUserRow = $db->one("SELECT * FROM users WHERE id = ? AND status = 'active'", array($targetUid));
        if (!$targetUserRow) {
            api_err('user_not_found', 'کاربر مورد نظر یافت نشد یا غیرفعال است. / Target user not found.');
        }
        $targetFlagsAdd = get_user_flags($targetUserRow);
        if (!empty($targetFlagsAdd['deny_group_invite']) && !$isSuper) {
            api_err('group_invite_denied_by_user', 'این کاربر افزودن مستقیم به گروه و کانال را در تنظیمات حریم خصوصی خود غیرفعال کرده است. / This user has disabled direct group/channel additions in privacy settings.');
        }
        $blockExistsAdd = $db->val(
            "SELECT 1 FROM blocks WHERE (user_id = ? AND blocked_id = ?) OR (user_id = ? AND blocked_id = ?)",
            array($targetUid, $myId, $myId, $targetUid)
        );
        if ($blockExistsAdd && !$isSuper) {
            api_err('blocked_user', 'به دلیل وجود مسدودسازی، امکان افزودن این کاربر وجود ندارد. / Cannot add user due to block settings.');
        }
        $existingMemAdd = $db->one("SELECT * FROM members WHERE chat_id = ? AND user_id = ?", array($cid, $targetUid));
        if ($existingMemAdd) {
            if (!empty($existingMemAdd['banned_until']) && (int)$existingMemAdd['banned_until'] > time()) {
                if (!has_admin_perm($chat, $myMem, $me, 'ban_users')) {
                    api_err('user_banned', 'این کاربر از گفتگو مسدود شده است؛ ابتدا باید توسط مدیر رفع مسدودیت شود. / User is banned from this chat.');
                }
                $db->exec("UPDATE members SET role = 'member', banned_until = NULL, restricted_until = NULL WHERE chat_id = ? AND user_id = ?", array($cid, $targetUid));
                bump_tick();
                api_ok(array('added' => true, 'unbanned' => true));
            }
            if ($existingMemAdd['role'] === 'pending' && has_admin_perm($chat, $myMem, $me, 'invite_users')) {
                $db->exec("UPDATE members SET role = 'member' WHERE chat_id = ? AND user_id = ?", array($cid, $targetUid));
                bump_tick();
                api_ok(array('added' => true));
            }
            api_err('already_member', 'این کاربر هم‌اکنون عضو این گفتگو است. / User is already a member.');
        }
        verify_user_chat_capacity($db, $targetUserRow, true);
        $capAdd = resolve_chat_member_capacity($db, $chat);
        $curMemCnt = (int)$db->val("SELECT COUNT(*) FROM members WHERE chat_id = ? AND role != 'pending'", array($cid));
        if ($capAdd['effective_max'] > 0 && $curMemCnt >= $capAdd['effective_max'] && !$isSuper) {
            api_err('chat_full', 'ظرفیت اعضای این گفتگو تکمیل شده است (' . $capAdd['effective_max'] . '). / Maximum member limit reached (' . $capAdd['effective_max'] . ').');
        }
        $maxMsgIdAdd = (int)$db->val("SELECT COALESCE(MAX(id), 0) FROM messages WHERE chat_id = ?", array($cid));
        $joinedMsgIdAdd = ($chat['history'] === 'from_join') ? $maxMsgIdAdd : 0;
        $db->insertIgnore('members', array(
            'chat_id'       => $cid,
            'user_id'       => $targetUid,
            'role'          => 'member',
            'perms_json'    => '{}',
            'joined_msg_id' => $joinedMsgIdAdd,
            'last_read_id'  => $maxMsgIdAdd,
            'muted'         => 0,
            'last_msg_at'   => 0,
            'joined_at'     => time()
        ));
        bump_tick();
        api_ok(array('added' => true, 'user_id' => $targetUid, 'chats' => fetch_user_chats($db, $me)));
    }

    if ($do === 'member_role') {
        $cid = isset($in['chat_id']) ? (int)$in['chat_id'] : 0;
        $targetUid = isset($in['user_id']) ? (int)$in['user_id'] : 0;
        $targetUname = isset($in['username']) ? u_lower(trim(ltrim((string)$in['username'], '@'))) : '';
        $newRole = isset($in['role']) && in_array($in['role'], array('admin', 'member'), true) ? $in['role'] : 'member';
        $defaultPerms = get_default_admin_perms();
        $rawPerms = isset($in['perms']) && is_array($in['perms']) ? $in['perms'] : array();
        $cleanPerms = array();
        foreach ($defaultPerms as $pk => $defVal) {
            $cleanPerms[$pk] = array_key_exists($pk, $rawPerms) ? ((int)$rawPerms[$pk] ? 1 : 0) : $defVal;
        }

        $chat = $db->one("SELECT * FROM chats WHERE id = ?", array($cid));
        $myMem = $db->one("SELECT * FROM members WHERE chat_id = ? AND user_id = ?", array($cid, $myId));
        if (!$chat || !in_array($chat['type'], array('group', 'channel'), true)) {
            api_err('not_found', 'Group or channel not found.');
        }
        if (!has_admin_perm($chat, $myMem, $me, 'manage_admins')) {
            api_err('forbidden', 'You do not have permission to manage admins in this chat.');
        }

        if ($targetUid <= 0 && $targetUname !== '') {
            $tu = $db->one("SELECT id, status FROM users WHERE username = ?", array($targetUname));
            if (!$tu || $tu['status'] !== 'active') {
                api_err('user_not_found', 'User @' . $targetUname . ' was not found.');
            }
            $targetUid = (int)$tu['id'];
        }
        if ($targetUid <= 0) {
            api_err('invalid_target', 'Valid user is required.');
        }
        if ((int)$chat['owner_id'] === $targetUid) {
            api_err('forbidden', 'Cannot change role of the chat owner.');
        }
        $targetUserRow = $db->one("SELECT id, role, status FROM users WHERE id = ?", array($targetUid));
        if (!$targetUserRow || $targetUserRow['status'] !== 'active') {
            api_err('user_not_found', 'Target user is not active.');
        }

        $existingTargetMem = $db->one("SELECT * FROM members WHERE chat_id = ? AND user_id = ?", array($cid, $targetUid));
        $isActorOwnerOrSuper = $isSuper || ($myMem && $myMem['role'] === 'owner') || ((int)$chat['owner_id'] === $myId);
        if (!$isActorOwnerOrSuper && $newRole === 'admin') {
            $prevTargetPerms = ($existingTargetMem && $existingTargetMem['role'] === 'admin')
                ? parse_json_col($existingTargetMem['perms_json'], $defaultPerms)
                : array();
            foreach ($defaultPerms as $pk => $defVal) {
                if (!has_admin_perm($chat, $myMem, $me, $pk)) {
                    $cleanPerms[$pk] = !empty($prevTargetPerms[$pk]) ? 1 : 0;
                }
            }
        }
        $preservedPersonalPerms = array();
        if ($existingTargetMem && !empty($existingTargetMem['perms_json'])) {
            $rawPrevMemPerms = parse_json_col($existingTargetMem['perms_json'], array());
            if (isset($rawPrevMemPerms['my_typing_mode'])) {
                $preservedPersonalPerms['my_typing_mode'] = normalize_typing_override_val($rawPrevMemPerms['my_typing_mode'], 'personal_chat');
            }
        }
        $mergedRolePerms = ($newRole === 'admin') ? array_merge($cleanPerms, $preservedPersonalPerms) : $preservedPersonalPerms;
        $permsJson = empty($mergedRolePerms) ? '{}' : json_encode($mergedRolePerms);
        if (!$existingTargetMem) {
            $tFlagsRole = get_user_flags($db->one("SELECT flags FROM users WHERE id = ?", array($targetUid)));
            if (!empty($tFlagsRole['deny_group_invite']) && !$isSuper) {
                api_err('group_invite_denied_by_user', 'این کاربر افزودن مستقیم به گروه و کانال را در تنظیمات حریم خصوصی خود غیرفعال کرده است. / This user has disabled direct group/channel additions in privacy settings.');
            }
            $blockExists = $db->val(
                "SELECT 1 FROM blocks WHERE (user_id = ? AND blocked_id = ?) OR (user_id = ? AND blocked_id = ?)",
                array($targetUid, $myId, $myId, $targetUid)
            );
            if ($blockExists && !$isSuper) {
                api_err('blocked_user', 'Cannot add a user when a block is active between accounts.');
            }
            $maxMsgId = (int)$db->val("SELECT COALESCE(MAX(id), 0) FROM messages WHERE chat_id = ?", array($cid));
            $joinedMsgId = ($chat['history'] === 'from_join') ? $maxMsgId : 0;
            $db->insertIgnore('members', array(
                'chat_id'       => $cid,
                'user_id'       => $targetUid,
                'role'          => $newRole,
                'perms_json'    => $permsJson,
                'joined_msg_id' => $joinedMsgId,
                'last_read_id'  => $maxMsgId,
                'muted'         => 0,
                'last_msg_at'   => 0,
                'joined_at'     => time()
            ));
        } else {
            $db->exec("UPDATE members SET role = ?, perms_json = ?, banned_until = NULL WHERE chat_id = ? AND user_id = ?", array($newRole, $permsJson, $cid, $targetUid));
        }
        bump_tick();
        api_ok(array('updated' => true, 'chats' => fetch_user_chats($db, $me)));
    }

    if ($do === 'member_kick' || $do === 'member_ban' || $do === 'member_unban' || $do === 'member_mute' || $do === 'member_restrict') {
        $cid = isset($in['chat_id']) ? (int)$in['chat_id'] : 0;
        $targetUid = isset($in['user_id']) ? (int)$in['user_id'] : 0;
        $chat = $db->one("SELECT * FROM chats WHERE id = ?", array($cid));
        $myMem = $db->one("SELECT * FROM members WHERE chat_id = ? AND user_id = ?", array($cid, $myId));
        if (!$chat || !has_admin_perm($chat, $myMem, $me, 'ban_users')) {
            api_err('forbidden', 'Moderation permission denied.');
        }
        if ((int)$chat['owner_id'] === $targetUid) {
            api_err('forbidden', 'Cannot moderate chat owner.');
        }
        $targetUserRow = $db->one("SELECT role FROM users WHERE id = ?", array($targetUid));
        if ($targetUserRow && $targetUserRow['role'] === 'superadmin' && !$isSuper && $do !== 'member_restrict') {
            api_err('forbidden', 'Cannot remove or ban global super-admin.');
        }
        $targetMemRow = $db->one("SELECT role FROM members WHERE chat_id = ? AND user_id = ?", array($cid, $targetUid));
        if ($targetMemRow && $targetMemRow['role'] === 'admin' && !has_admin_perm($chat, $myMem, $me, 'manage_admins')) {
            api_err('forbidden', 'Managing other admins requires the Manage Admins privilege.');
        }
        $now = time();
        if ($do === 'member_kick') {
            $db->exec("DELETE FROM members WHERE chat_id = ? AND user_id = ?", array($cid, $targetUid));
        } elseif ($do === 'member_ban') {
            $dur = isset($in['duration_sec']) ? (int)$in['duration_sec'] : (86400 * 365);
            $db->exec("UPDATE members SET role = 'member', perms_json = '{}', banned_until = ? WHERE chat_id = ? AND user_id = ?", array($now + max(60, $dur), $cid, $targetUid));
        } elseif ($do === 'member_unban') {
            $db->exec("UPDATE members SET banned_until = NULL, restricted_until = NULL WHERE chat_id = ? AND user_id = ?", array($cid, $targetUid));
        } elseif ($do === 'member_mute') {
            $dur = isset($in['duration_sec']) ? (int)$in['duration_sec'] : 3600;
            $until = ($dur > 0) ? ($now + $dur) : null;
            $db->exec("UPDATE members SET restricted_until = ? WHERE chat_id = ? AND user_id = ?", array($until, $cid, $targetUid));
        } elseif ($do === 'member_restrict') {
            $fullMem = $db->one("SELECT perms_json FROM members WHERE chat_id = ? AND user_id = ?", array($cid, $targetUid));
            if (!$fullMem) api_err('not_found', 'Member not found.');
            $mp = parse_json_col($fullMem['perms_json'], array());
            if (array_key_exists('mute_send', $in)) {
                $mp['mute_send'] = (int)$in['mute_send'] ? 1 : 0;
                if ($mp['mute_send'] === 0) {
                    $db->exec("UPDATE members SET restricted_until = NULL WHERE chat_id = ? AND user_id = ?", array($cid, $targetUid));
                }
            }
            if (array_key_exists('mute_react', $in)) {
                $mp['mute_react'] = (int)$in['mute_react'] ? 1 : 0;
            }
            $db->exec("UPDATE members SET perms_json = ? WHERE chat_id = ? AND user_id = ?", array(json_encode($mp), $cid, $targetUid));
        }
        clear_ephemeral_typing_for_user($db, $targetUid, $cid);
        bump_tick();
        api_ok(array('moderated' => true));
    }

    /* ---------------- SHADOW-BAN (per chat, strict rank ladder) ----------------
       The member keeps their seat and their history. Only the traffic written
       after the ban moment is affected, in both directions. Lifting the ban is a
       full reversal: because the filter keys on "currently banned", everything
       written during the ban becomes visible again instead of staying lost. */
    if ($do === 'member_shadowban' || $do === 'member_unshadowban') {
        $cid = isset($in['chat_id']) ? (int)$in['chat_id'] : 0;
        $targetUid = isset($in['user_id']) ? (int)$in['user_id'] : 0;
        $chat = $db->one("SELECT * FROM chats WHERE id = ?", array($cid));
        if (!$chat || !in_array((string)$chat['type'], array('group', 'channel'), true)) {
            api_err('not_found', 'Group or channel not found.');
        }
        if ($targetUid <= 0) api_err('not_found', 'Member not found.');
        if ($targetUid === $myId) api_err('forbidden', 'You cannot shadow-ban yourself.');

        $myMem = $db->one("SELECT * FROM members WHERE chat_id = ? AND user_id = ?", array($cid, $myId));
        $targetMem = $db->one("SELECT * FROM members WHERE chat_id = ? AND user_id = ?", array($cid, $targetUid));
        if (!$targetMem) api_err('not_found', 'Member not found.');

        $actorRank = m3_shadow_rank($db, $chat, $myId, $myMem);
        if (!m3_shadow_can_manage($actorRank)) {
            api_err('forbidden', 'Shadow-banning requires chat admin privileges.');
        }
        if (!m3_shadow_may_target($db, $chat, $actorRank, $targetUid, $targetMem)) {
            api_err('shadow_rank_denied', 'A rank can only shadow-ban strictly lower ranks.');
        }

        $now = time();
        $banning = ($do === 'member_shadowban');
        if ($banning) {
            $db->exec(
                "UPDATE members SET shadow_banned = 1, shadow_banned_at = ?, shadow_banned_by = ? WHERE chat_id = ? AND user_id = ?",
                array($now, $myId, $cid, $targetUid)
            );
        } else {
            $db->exec(
                "UPDATE members SET shadow_banned = 0, shadow_banned_at = NULL, shadow_banned_by = NULL WHERE chat_id = ? AND user_id = ?",
                array($cid, $targetUid)
            );
        }
        // Drop the cached map so the very next read in this request sees the change.
        m3_shadow_forget_cache($cid);
        clear_ephemeral_typing_for_user($db, $targetUid, $cid);
        bump_tick();
        api_ok(array(
            'moderated'        => true,
            'shadow_banned'    => $banning ? 1 : 0,
            'shadow_banned_at' => $banning ? $now : null
        ));
    }

    if ($do === 'join_requests_list' || $do === 'join_requests_decide') {
        $cid = isset($in['chat_id']) ? (int)$in['chat_id'] : 0;
        $chat = $db->one("SELECT * FROM chats WHERE id = ?", array($cid));
        $myMem = $db->one("SELECT * FROM members WHERE chat_id = ? AND user_id = ?", array($cid, $myId));
        if (!$chat || !has_admin_perm($chat, $myMem, $me, 'invite_users')) {
            api_err('forbidden', 'Permission denied.');
        }
        if ($do === 'join_requests_list') {
            $reqs = $db->all(
                "SELECT m.user_id, m.joined_at, u.username, u.name, u.avatar FROM members m JOIN users u ON u.id = m.user_id WHERE m.chat_id = ? AND m.role = 'pending'",
                array($cid)
            );
            api_ok(array('requests' => $reqs));
        } else {
            $targetUid = isset($in['user_id']) ? (int)$in['user_id'] : 0;
            $approve = !empty($in['approve']) || (isset($in['decision']) && $in['decision'] === 'approve');
            if ($approve) {
                $tUserPending = $db->one("SELECT * FROM users WHERE id = ?", array($targetUid));
                if ($tUserPending) {
                    verify_user_chat_capacity($db, $tUserPending, true);
                }
                $capApr = resolve_chat_member_capacity($db, $chat);
                $curAprCnt = (int)$db->val("SELECT COUNT(*) FROM members WHERE chat_id = ? AND role != 'pending'", array($cid));
                if ($capApr['effective_max'] > 0 && $curAprCnt >= $capApr['effective_max'] && !$isSuper) {
                    api_err('chat_full', 'ظرفیت اعضای این گفتگو تکمیل شده است (' . $capApr['effective_max'] . '). / Maximum member limit reached.');
                }
                $db->exec("UPDATE members SET role = 'member' WHERE chat_id = ? AND user_id = ? AND role = 'pending'", array($cid, $targetUid));
            } else {
                $db->exec("DELETE FROM members WHERE chat_id = ? AND user_id = ? AND role = 'pending'", array($cid, $targetUid));
            }
            bump_tick();
            api_ok(array('decided' => true));
        }
    }

    if ($do === 'invite_list' || $do === 'invite_create' || $do === 'invite_revoke') {
        $cid = isset($in['chat_id']) ? (int)$in['chat_id'] : 0;
        $chat = $db->one("SELECT * FROM chats WHERE id = ?", array($cid));
        $myMem = get_active_member($db, $cid, $myId);
        if (!$chat || !can_member_invite_in_chat($chat, $myMem, $me)) {
            api_err('forbidden', 'Permission denied.');
        }
        $hasAdminInvPerm = has_admin_perm($chat, $myMem, $me, 'invite_users');
        if ($do === 'invite_create') {
            $maxUses = isset($in['max_uses']) ? max(0, (int)$in['max_uses']) : 0;
            $expSec  = isset($in['expires_in']) && (int)$in['expires_in'] > 0 ? (time() + (int)$in['expires_in']) : null;
            $code = random_invite_code('J-');
            $db->exec(
                "INSERT INTO invites (chat_id, code, created_by, max_uses, uses, expires_at, revoked) VALUES (?, ?, ?, ?, 0, ?, 0)",
                array($cid, $code, $myId, $maxUses, $expSec)
            );
        } elseif ($do === 'invite_revoke') {
            $invId = isset($in['invite_id']) ? (int)$in['invite_id'] : 0;
            $invCode = isset($in['code']) ? strtoupper(trim((string)$in['code'])) : '';
            $targetInv = null;
            if ($invId > 0) {
                $targetInv = $db->one("SELECT * FROM invites WHERE id = ? AND chat_id = ?", array($invId, $cid));
            } elseif ($invCode !== '') {
                $targetInv = $db->one("SELECT * FROM invites WHERE code = ? AND chat_id = ?", array($invCode, $cid));
            }
            if (!$targetInv) {
                api_err('not_found', 'Invite link not found.');
            }
            if (!$hasAdminInvPerm && (int)$targetInv['created_by'] !== $myId) {
                api_err('forbidden', 'فقط مدیران یا سازنده همین لینک می‌توانند آن را لغو کنند. / Only admins or the link creator can revoke this invite link.');
            }
            $db->exec("UPDATE invites SET revoked = 1 WHERE id = ? AND chat_id = ?", array((int)$targetInv['id'], $cid));
        }
        $list = $db->all("SELECT * FROM invites WHERE chat_id = ? AND revoked = 0 ORDER BY id DESC", array($cid));
        api_ok(array('invites' => $list, 'code' => isset($code) ? $code : (!empty($list) ? $list[0]['code'] : '')));
    }

    if ($do === 'pin' || $do === 'unpin') {
        $cid = isset($in['chat_id']) ? (int)$in['chat_id'] : 0;
        $mid = isset($in['message_id']) ? (int)$in['message_id'] : 0;
        if ($cid <= 0 && $mid > 0) {
            $cid = (int)$db->val("SELECT chat_id FROM messages WHERE id = ?", array($mid));
        }
        $rawScopeIn = isset($in['scope']) ? (string)$in['scope'] : '';
        $hasExplicitScope = in_array($rawScopeIn, array('me', 'both', 'dismiss_both'), true);
        $scope = ($rawScopeIn === 'me') ? 'me' : (($rawScopeIn === 'dismiss_both') ? 'me_dismiss_or_unpin' : 'both');
        $chat = $db->one("SELECT * FROM chats WHERE id = ?", array($cid));
        if (!$chat) api_err('not_found', 'Chat not found.');
        if ($chat['type'] === 'system') {
            api_err('forbidden', 'Official System Chat messages cannot be manipulated.');
        }
        $myMem = get_active_member($db, $cid, $myId);
        $canPinBoth = false;
        if ($chat['type'] === 'secret') {
            $canPinBoth = ($myMem !== null);
        } elseif ($chat['type'] === 'saved' || $chat['type'] === 'dm') {
            $canPinBoth = ($myMem !== null || $isSuper);
        } else {
            $cPinPerms = parse_json_col($chat['perms_json'], array('pin' => 0));
            $canPinBoth = has_admin_perm($chat, $myMem, $me, 'pin_messages') || (!empty($cPinPerms['pin']) && $myMem !== null);
        }
        $canPinMe = ($myMem !== null);
        if (!$hasExplicitScope && !$canPinBoth && $canPinMe) {
            $scope = 'me';
        }
        if ($scope === 'me_dismiss_or_unpin' && !$canPinMe) {
            api_err('forbidden', 'Active membership required.');
        }
        if ($scope === 'both' && !$canPinBoth) {
            if ($do === 'unpin' && $canPinMe) {
                // Non-admin member dismissing/unpinning the currently visible pin for themselves
                $scope = 'me_dismiss_or_unpin';
            } else {
                api_err('forbidden', 'Pin permission denied.');
            }
        }
        if ($scope === 'me' && !$canPinMe) {
            api_err('forbidden', 'Personal pin requires active membership.');
        }

        $pinVal = ($do === 'pin') ? 1 : 0;
        $memPermsArr = $myMem ? parse_json_col(isset($myMem['perms_json']) ? $myMem['perms_json'] : '{}', array()) : array();
        $curTopShared = $db->one("SELECT id, pinned_at, created_at FROM messages WHERE chat_id = ? AND pinned = 1 AND deleted_at IS NULL ORDER BY pinned_at DESC, id DESC LIMIT 1", array($cid));
        $curSharedAt = $curTopShared ? max((int)$curTopShared['pinned_at'], (int)$curTopShared['created_at']) : 0;
        $curPersonalId = isset($memPermsArr['personal_pin_msg_id']) ? (int)$memPermsArr['personal_pin_msg_id'] : ($myMem ? (int)$myMem['pinned_msg_id'] : 0);
        $curPersonalAt = isset($memPermsArr['personal_pin_at']) ? (int)$memPermsArr['personal_pin_at'] : 0;

        if ($pinVal === 1) {
            if ($mid <= 0) api_err('invalid_message', 'Message ID is required to pin.');
            $validPinTarget = $db->val("SELECT id FROM messages WHERE id = ? AND chat_id = ? AND deleted_at IS NULL", array($mid, $cid));
            if (!$validPinTarget) api_err('not_found', 'Message not found.');
            if ($scope === 'me') {
                $nextPersonalAt = max(time(), $curSharedAt + 1, $curPersonalAt + 1);
                $memPermsArr['personal_pin_msg_id'] = $mid;
                $memPermsArr['personal_pin_at'] = $nextPersonalAt;
                $db->exec(
                    "UPDATE members SET pinned_msg_id = ?, perms_json = ? WHERE chat_id = ? AND user_id = ?",
                    array($mid, json_encode($memPermsArr, JSON_UNESCAPED_UNICODE), $cid, $myId)
                );
            } else {
                // Compute monotonic timestamp strictly greater than any member's current personal_pin_at in this chat so newer 'both' sits on top!
                $maxMemPinAt = $curPersonalAt;
                $allMemPerms = $db->all("SELECT perms_json FROM members WHERE chat_id = ?", array($cid));
                foreach ($allMemPerms as $amp) {
                    $pp = parse_json_col(isset($amp['perms_json']) ? $amp['perms_json'] : '{}', array());
                    if (isset($pp['personal_pin_at']) && (int)$pp['personal_pin_at'] > $maxMemPinAt) {
                        $maxMemPinAt = (int)$pp['personal_pin_at'];
                    }
                }
                $nextSharedAt = max(time(), $curSharedAt + 1, $maxMemPinAt + 1);
                $db->exec("UPDATE messages SET pinned = 0, pinned_at = 0 WHERE chat_id = ? AND pinned = 1", array($cid));
                $db->exec("UPDATE messages SET pinned = 1, pinned_at = ? WHERE id = ? AND chat_id = ? AND deleted_at IS NULL", array($nextSharedAt, $mid, $cid));
            }
        } else {
            if ($scope === 'me') {
                $memPermsArr['personal_pin_msg_id'] = 0;
                $memPermsArr['personal_pin_at'] = 0;
                $db->exec(
                    "UPDATE members SET pinned_msg_id = 0, perms_json = ? WHERE chat_id = ? AND user_id = ?",
                    array(json_encode($memPermsArr, JSON_UNESCAPED_UNICODE), $cid, $myId)
                );
            } elseif ($scope === 'me_dismiss_or_unpin') {
                // If explicit 'dismiss_both', always dismiss the top shared pin for this user while keeping their personal pin intact!
                if ($rawScopeIn === 'dismiss_both' && $curTopShared) {
                    $memPermsArr['dismissed_shared_pin_id'] = (int)$curTopShared['id'];
                    $memPermsArr['dismissed_shared_pin_at'] = $curSharedAt;
                } elseif ($curPersonalId > 0 && ($curPersonalAt >= $curSharedAt || ($mid > 0 && $curPersonalId === $mid))) {
                    $memPermsArr['personal_pin_msg_id'] = 0;
                    $memPermsArr['personal_pin_at'] = 0;
                } elseif ($curTopShared) {
                    $memPermsArr['dismissed_shared_pin_id'] = (int)$curTopShared['id'];
                    $memPermsArr['dismissed_shared_pin_at'] = $curSharedAt;
                }
                $db->exec(
                    "UPDATE members SET pinned_msg_id = ?, perms_json = ? WHERE chat_id = ? AND user_id = ?",
                    array((int)(isset($memPermsArr['personal_pin_msg_id']) ? $memPermsArr['personal_pin_msg_id'] : 0), json_encode($memPermsArr, JSON_UNESCAPED_UNICODE), $cid, $myId)
                );
            } else {
                // Admin / DM peer unpinning 'both': only unpin the shared layer so any underlying personal ('me') pin reappears!
                if ($mid > 0) {
                    $db->exec("UPDATE messages SET pinned = 0, pinned_at = 0 WHERE id = ? AND chat_id = ?", array($mid, $cid));
                } else {
                    $db->exec("UPDATE messages SET pinned = 0, pinned_at = 0 WHERE chat_id = ? AND pinned = 1", array($cid));
                }
            }
        }
        bump_tick();
        api_ok(array('pinned' => $pinVal, 'scope' => ($scope === 'me_dismiss_or_unpin' ? 'me' : $scope), 'chats' => fetch_user_chats($db, $me)));
    }

    /* ---------------- MESSAGES, MEDIA, TICKS & FORWARDING ---------------- */
    if ($do === 'pinned_messages_list') {
        $cid = isset($in['chat_id']) ? (int)$in['chat_id'] : 0;
        $chat = $db->one("SELECT * FROM chats WHERE id = ?", array($cid));
        $mem = get_active_member($db, $cid, $myId);
        if (!$chat || (!$mem && (!$isSuper || $chat['type'] === 'secret'))) {
            api_err('forbidden', 'Access denied.');
        }
        $minMsgId = (!$isSuper && $chat['history'] === 'from_join' && $mem) ? (int)$mem['joined_msg_id'] : 0;
        $now = time();
        $rows = $db->all(
            "SELECT m.id, m.user_id, m.kind, m.body, m.created_at, m.pinned_at, m.hidden_for,
                    u.username, u.name
             FROM messages m
             LEFT JOIN users u ON u.id = m.user_id
             WHERE m.chat_id = ? AND m.pinned = 1 AND m.id >= ?
               AND (m.visible_only_to IS NULL OR m.visible_only_to = ?)
               AND m.deleted_at IS NULL AND (m.expires_at IS NULL OR m.expires_at > ?)
             ORDER BY m.pinned_at DESC, m.id DESC LIMIT 50",
            array($cid, $minMsgId, $myId, $now)
        );
        $out = array();
        // The pin list is a read path like any other: without this a banned member
        // could read withheld text as a pinned snippet, and a banned author's pinned
        // message would stay visible to everybody.
        $pinShadow = m3_shadow_view($db, $chat, $myId, $mem ? $mem : null);
        foreach ($rows as $r) {
            if (is_hidden_for_user($r['hidden_for'], $myId)) continue;
            if (m3_shadow_hides_row($r, $myId, $pinShadow['rank'], $pinShadow['map'], $pinShadow['my_at'])) continue;
            $out[] = array(
                'id'         => (int)$r['id'],
                'user_id'    => (int)$r['user_id'],
                'kind'       => (string)$r['kind'],
                'body'       => (string)$r['body'],
                'created_at' => (int)$r['created_at'],
                'pinned_at'  => (int)$r['pinned_at'],
                'username'   => (string)($r['username'] !== null ? $r['username'] : ''),
                'name'       => (string)($r['name'] !== null ? $r['name'] : '')
            );
        }
        api_ok(array('messages' => $out));
    }

    if ($do === 'messages_list') {
        $cid = isset($in['chat_id']) ? (int)$in['chat_id'] : 0;
        $sinceId = isset($in['since_id']) ? (int)$in['since_id'] : 0;
        $beforeId = isset($in['before_id']) ? (int)$in['before_id'] : 0;
        $aroundId = isset($in['around_id']) ? (int)$in['around_id'] : 0;
        $unreadAnchor = !empty($in['unread_anchor']);
        $limit = isset($in['limit']) ? (int)$in['limit'] : 60;

        $chat = $db->one("SELECT * FROM chats WHERE id = ?", array($cid));
        $mem = get_active_member($db, $cid, $myId);
        if (!$chat || (!$mem && (!$isSuper || $chat['type'] === 'secret'))) {
            api_err('forbidden', 'Access denied.');
        }
        // A chat this member removed from their own list is off-limits until they
        // reopen it through chat_open_dm.
        if ($mem && !$isSuper && (int)(isset($mem['left_at']) ? $mem['left_at'] : 0) > 0) {
            api_err('forbidden', 'Access denied.');
        }

        $firstUnreadId = 0;
        $hasMoreAfter = false;
        if ($unreadAnchor && $mem) {
            $myLastRead = (int)$mem['last_read_id'];
            $minMsgId = (!$isSuper && $chat['history'] === 'from_join') ? (int)$mem['joined_msg_id'] : 0;
            if (!$isSuper && $mem && !empty($mem['rejoin_msg_id'])) {
                $minMsgId = max($minMsgId, (int)$mem['rejoin_msg_id']);
            }
            $firstUnreadRow = $db->one(
                "SELECT id FROM messages
                 WHERE chat_id = ? AND id > ? AND id >= ? AND user_id != ?
                   AND (visible_only_to IS NULL OR visible_only_to = ?)
                   AND deleted_at IS NULL AND (expires_at IS NULL OR expires_at > ?)
                 ORDER BY id ASC LIMIT 1",
                array($cid, $myLastRead, $minMsgId, $myId, $myId, time())
            );
            if ($firstUnreadRow) {
                $firstUnreadId = (int)$firstUnreadRow['id'];
                $aroundId = $firstUnreadId;
            }
        }

        if ($aroundId > 0) {
            $beforeMsgs = fetch_chat_messages($db, $chat, $mem, $me, 0, $aroundId, 20);
            $afterMsgs = fetch_chat_messages($db, $chat, $mem, $me, 0, 0, 45, $aroundId - 1);
            $msgs = array_merge($beforeMsgs, $afterMsgs);
            if (!empty($afterMsgs)) {
                $lastLoadedId = (int)$afterMsgs[count($afterMsgs) - 1]['id'];
                $maxActiveId = (int)$db->val(
                    "SELECT COALESCE(MAX(id), 0) FROM messages WHERE chat_id = ? AND (visible_only_to IS NULL OR visible_only_to = ?) AND deleted_at IS NULL AND (expires_at IS NULL OR expires_at > ?)",
                    array($cid, $myId, time())
                );
                $hasMoreAfter = ($maxActiveId > $lastLoadedId);
            }
        } elseif (!empty($in['after_id'])) {
            $afterId = (int)$in['after_id'];
            $msgs = fetch_chat_messages($db, $chat, $mem, $me, 0, 0, $limit, $afterId);
            if (!empty($msgs)) {
                $lastLoadedId = (int)$msgs[count($msgs) - 1]['id'];
                $maxActiveId = (int)$db->val(
                    "SELECT COALESCE(MAX(id), 0) FROM messages WHERE chat_id = ? AND (visible_only_to IS NULL OR visible_only_to = ?) AND deleted_at IS NULL AND (expires_at IS NULL OR expires_at > ?)",
                    array($cid, $myId, time())
                );
                $hasMoreAfter = ($maxActiveId > $lastLoadedId);
            }
        } else {
            $msgs = fetch_chat_messages($db, $chat, $mem, $me, $sinceId, $beforeId, $limit);
        }

        $hasMoreBefore = false;
        if (!empty($msgs) && $sinceId <= 0) {
            $firstLoadedId = (int)$msgs[0]['id'];
            $minVisId = (!$isSuper && $mem && $chat['history'] === 'from_join') ? (int)$mem['joined_msg_id'] : 0;
            $olderExists = $db->val(
                "SELECT id FROM messages WHERE chat_id = ? AND id < ? AND id >= ? AND (visible_only_to IS NULL OR visible_only_to = ?) AND deleted_at IS NULL AND (expires_at IS NULL OR expires_at > ?) LIMIT 1",
                array($cid, $firstLoadedId, $minVisId, $myId, time())
            );
            $hasMoreBefore = !empty($olderExists);
        }

        $peerLastRead = peer_read_watermark($db, $chat, $myId);
        api_ok(array(
            'messages'          => $msgs,
            'peer_last_read_id' => $peerLastRead,
            'first_unread_id'   => $firstUnreadId,
            'has_more_before'   => $hasMoreBefore,
            'has_more_after'    => $hasMoreAfter,
            'typing_users'      => get_active_typing_users_for_chat($db, $cid, $me),
            'typing_tick'       => get_typing_tick()
        ));
    }

    if ($do === 'messages_by_date') {
        $cid = isset($in['chat_id']) ? (int)$in['chat_id'] : 0;
        $startTs = isset($in['start_ts']) ? (int)$in['start_ts'] : 0;
        $endTs = isset($in['end_ts']) ? (int)$in['end_ts'] : ($startTs + 86399);
        $chat = $db->one("SELECT * FROM chats WHERE id = ?", array($cid));
        $mem = get_active_member($db, $cid, $myId);
        if (!$chat || (!$mem && (!$isSuper || $chat['type'] === 'secret'))) {
            api_err('forbidden', 'Access denied.');
        }
        $minMsgId = (!$isSuper && $chat['history'] === 'from_join' && $mem) ? (int)$mem['joined_msg_id'] : 0;
        if ($mem && !$isSuper && (int)(isset($mem['left_at']) ? $mem['left_at'] : 0) > 0) {
            api_err('forbidden', 'Access denied.');
        }
        if (!$isSuper && $mem && !empty($mem['rejoin_msg_id'])) {
            $minMsgId = max($minMsgId, (int)$mem['rejoin_msg_id']);
        }
        $now = time();
        $firstInRange = $db->one(
            "SELECT id, created_at FROM messages
             WHERE chat_id = ? AND id >= ? AND created_at >= ? AND created_at <= ?
               AND (visible_only_to IS NULL OR visible_only_to = ?)
               AND deleted_at IS NULL AND (expires_at IS NULL OR expires_at > ?)
             ORDER BY id ASC LIMIT 1",
            array($cid, $minMsgId, $startTs, $endTs, $myId, $now)
        );
        $countInRange = (int)$db->val(
            "SELECT COUNT(*) FROM messages
             WHERE chat_id = ? AND id >= ? AND created_at >= ? AND created_at <= ?
               AND (visible_only_to IS NULL OR visible_only_to = ?)
               AND deleted_at IS NULL AND (expires_at IS NULL OR expires_at > ?)",
            array($cid, $minMsgId, $startTs, $endTs, $myId, $now)
        );
        if (!$firstInRange) {
            // Also find nearest message on or after startTs so user can jump to closest active date if desired
            $nearestAfter = $db->one(
                "SELECT id, created_at FROM messages
                 WHERE chat_id = ? AND id >= ? AND created_at >= ?
                   AND (visible_only_to IS NULL OR visible_only_to = ?)
                   AND deleted_at IS NULL AND (expires_at IS NULL OR expires_at > ?)
                 ORDER BY id ASC LIMIT 1",
                array($cid, $minMsgId, $startTs, $myId, $now)
            );
            api_ok(array(
                'found_exact'     => false,
                'exact_in_range'  => false,
                'count_in_range'  => 0,
                'target_id'       => $nearestAfter ? (int)$nearestAfter['id'] : 0,
                'target_ts'       => $nearestAfter ? (int)$nearestAfter['created_at'] : 0
            ));
        }
        api_ok(array(
            'found_exact'     => true,
            'exact_in_range'  => true,
            'count_in_range'  => $countInRange,
            'target_id'       => (int)$firstInRange['id'],
            'target_ts'       => (int)$firstInRange['created_at']
        ));
    }

    if ($do === 'calendar_month_days') {
        $cid = isset($in['chat_id']) ? (int)$in['chat_id'] : 0;
        $startTs = isset($in['start_ts']) ? (int)$in['start_ts'] : 0;
        $endTs = isset($in['end_ts']) ? (int)$in['end_ts'] : ($startTs + 86400 * 35);
        $tzOffsetMin = isset($in['tz_offset']) ? max(-840, min(840, (int)$in['tz_offset'])) : 0;
        $chat = $db->one("SELECT * FROM chats WHERE id = ?", array($cid));
        $mem = get_active_member($db, $cid, $myId);
        if (!$chat || (!$mem && (!$isSuper || $chat['type'] === 'secret'))) {
            api_err('forbidden', 'Access denied.');
        }
        $minMsgId = (!$isSuper && $chat['history'] === 'from_join' && $mem) ? (int)$mem['joined_msg_id'] : 0;
        $tsRows = $db->all(
            "SELECT created_at FROM messages
             WHERE chat_id = ? AND id >= ? AND created_at >= ? AND created_at <= ?
               AND (visible_only_to IS NULL OR visible_only_to = ?)
               AND deleted_at IS NULL AND (expires_at IS NULL OR expires_at > ?)",
            array($cid, $minMsgId, $startTs, $endTs, $myId, time())
        );
        $timestamps = array();
        $daysMap = array();
        foreach ($tsRows as $tr) {
            $tsVal = (int)$tr['created_at'];
            $timestamps[] = $tsVal;
            $daysMap[gmdate('Y-m-d', $tsVal + ($tzOffsetMin * 60))] = true;
        }
        api_ok(array('timestamps' => $timestamps, 'days' => array_keys($daysMap)));
    }

    if ($do === 'message_send') {
        $cid = isset($in['chat_id']) ? (int)$in['chat_id'] : 0;
        $kind = isset($in['kind']) && in_array($in['kind'], array('text', 'file', 'voice', 'video_note', 'location'), true) ? $in['kind'] : 'text';
        $body = isset($in['body']) ? trim((string)$in['body']) : '';
        $cipher = isset($in['cipher']) ? trim((string)$in['cipher']) : null;
        $iv = isset($in['iv']) ? trim((string)$in['iv']) : null;
        $replyTo = isset($in['reply_to']) && (int)$in['reply_to'] > 0 ? (int)$in['reply_to'] : null;
        $forwardFromId = isset($in['forward_from']) && (int)$in['forward_from'] > 0 ? (int)$in['forward_from'] : null;
        $forwardHideAuthor = !empty($in['hide_author']) ? 1 : 0;
        $forwardOriginId = null;
        $fileId = isset($in['file_id']) && (int)$in['file_id'] > 0 ? (int)$in['file_id'] : null;
        $customTtl = isset($in['ttl']) ? (int)$in['ttl'] : -1;
        $customTtlMode = isset($in['ttl_mode']) ? (string)$in['ttl_mode'] : '';

        $chat = $db->one("SELECT * FROM chats WHERE id = ?", array($cid));
        $mem = $db->one("SELECT * FROM members WHERE chat_id = ? AND user_id = ?", array($cid, $myId));
        if (!$chat) api_err('not_found', 'Chat not found.');
        if ($mem && !$isSuper && (int)(isset($mem['left_at']) ? $mem['left_at'] : 0) > 0) {
            api_err('forbidden', 'This chat was removed from your list. Reopen it before sending messages.');
        }

        verify_can_post($db, $chat, $mem, $me, $kind);

        // Flood control (max 25 messages per 10s per user)
        if (rate_get_attempts($db, 'msg_flood', (string)$myId, 10) > 25) {
            api_err('rate_limited', 'Sending messages too fast. Please slow down.');
        }

        $forwardFromName = null;
        $msgSpoiler = !empty($in['spoiler']) ? 1 : 0;
        if ($forwardFromId !== null) {
            // Strict Secret Chat Forward Guard
            if ($chat['type'] === 'secret') {
                api_err('secret_chat_forward_forbidden', 'Forwarding into Secret Chats is prohibited.');
            }
            $origMsg = $db->one(
                "SELECT m.*, c.type AS source_chat_type, u.name AS orig_author_name
                 FROM messages m
                 JOIN chats c ON c.id = m.chat_id
                 LEFT JOIN users u ON u.id = m.user_id
                 WHERE m.id = ? AND m.deleted_at IS NULL",
                array($forwardFromId)
            );
            if (!$origMsg) {
                api_err('forward_source_not_found', 'Original message to forward was not found.');
            }
            $sourceChat = $db->one("SELECT * FROM chats WHERE id = ?", array((int)$origMsg['chat_id']));
            if ((!empty($origMsg['burn_after']) && (int)$origMsg['burn_after'] > 0) || !empty($origMsg['expires_at'])) {
                api_err('self_destruct_protected', 'Self-destructing messages cannot be saved or forwarded.');
            }
            verify_can_forward($sourceChat, $chat, $db, $me);
            if (!empty($origMsg['cipher'])) {
                api_err('secret_chat_forward_forbidden', 'Encrypted messages cannot be forwarded.');
            }
            if (!empty($origMsg['expires_at']) && (int)$origMsg['expires_at'] <= time()) {
                api_err('forward_source_not_found', 'Original message has expired.');
            }
            if (is_hidden_for_user($origMsg['hidden_for'], $myId)) {
                api_err('forward_source_not_found', 'Original message is not accessible.');
            }
            // Check active membership + from_join visibility in source chat
            $srcMem = get_active_member($db, (int)$origMsg['chat_id'], $myId);
            if (!$srcMem && !$isSuper) {
                api_err('forbidden', 'Cannot forward from a chat you are not an active member of.');
            }
            if ($srcMem && $sourceChat && $sourceChat['history'] === 'from_join' && (int)$origMsg['id'] < (int)$srcMem['joined_msg_id'] && !$isSuper) {
                api_err('forbidden', 'Cannot forward messages sent before you joined.');
            }
            $forwardOriginId = !empty($origMsg['forward_origin_id']) ? (int)$origMsg['forward_origin_id'] : (int)$origMsg['id'];
            if (!empty($origMsg['forward_hide_author'])) {
                $forwardHideAuthor = 1;
            }
            $forwardFromName = $forwardHideAuthor ? null : ($origMsg['orig_author_name'] ?: 'User');
            if (!array_key_exists('spoiler', $in) && !empty($origMsg['spoiler'])) {
                $msgSpoiler = 1;
            }
            if ($body === '') {
                $body = (string)$origMsg['body'];
            }
            if (!empty($origMsg['file_id'])) {
                $fileId = (int)$origMsg['file_id'];
                $kind = $origMsg['kind'];
                $origFileRow = $db->one("SELECT mime, display_name FROM files WHERE id = ?", array($fileId));
                $fwdContentType = classify_content_type_from_upload($kind, $origFileRow ? $origFileRow['mime'] : '', $origFileRow ? $origFileRow['display_name'] : '');
                verify_content_type_allowed($db, $chat, $mem, $me, $fwdContentType);
            } else {
                $fileId = null;
                if ($origMsg['kind'] === 'location') {
                    $kind = 'location';
                    verify_content_type_allowed($db, $chat, $mem, $me, 'location');
                }
            }
        } elseif ($fileId !== null) {
            verify_uploads_allowed_for_user($db, $me);
            // Prevent spoofing file_id of another user's private upload
            $ownedFile = $db->one("SELECT id, mime, display_name FROM files WHERE id = ? AND owner_id = ? AND chat_id = ?", array($fileId, $myId, $cid));
            if (!$ownedFile && !$isSuper) {
                api_err('forbidden', 'Invalid file attachment reference.');
            }
            if ($ownedFile) {
                $attType = classify_content_type_from_upload($kind, $ownedFile['mime'], $ownedFile['display_name']);
                verify_content_type_allowed($db, $chat, $mem, $me, $attType);
            }
        }

        if ($replyTo !== null) {
            $validReply = $db->val("SELECT id FROM messages WHERE id = ? AND chat_id = ? AND deleted_at IS NULL", array($replyTo, $cid));
            if (!$validReply) {
                $replyTo = null;
            }
        }

        if ($kind === 'location') {
            verify_content_type_allowed($db, $chat, $mem, $me, 'location');
        } elseif ($kind === 'voice') {
            verify_content_type_allowed($db, $chat, $mem, $me, 'voice');
        } elseif ($kind === 'video_note') {
            verify_content_type_allowed($db, $chat, $mem, $me, 'video_note');
        }

        $msgUnits = array();
        $maxChunksPerSend = 40;
        if ($chat['type'] === 'secret') {
            $secMaxChars = max(100, (int)Settings::get($db, 'max_msg_len', 2000));
            $secMaxCipherBytes = (($secMaxChars * 4) + 128) * 2;
            if ($forwardFromId !== null) {
                api_err('secret_chat_forward_forbidden', 'Forwarding is forbidden in Secret Chats.');
            }
            if (!empty($in['has_link'])) {
                verify_content_type_allowed($db, $chat, $mem, $me, 'link');
            }
            $body = ''; // Never store plaintext body in secret chats
            if (!empty($in['cipher_chunks']) && is_array($in['cipher_chunks'])) {
                if (count($in['cipher_chunks']) > $maxChunksPerSend) {
                    api_err('message_too_long', "Message exceeds maximum split chunks ({$maxChunksPerSend}).");
                }
                foreach ($in['cipher_chunks'] as $cItem) {
                    if (!is_array($cItem) || empty($cItem['cipher']) || empty($cItem['iv'])) {
                        api_err('e2ee_required', 'Secret chats require client-side AES-256-GCM ciphertext and IV.');
                    }
                    $cc = trim((string)$cItem['cipher']);
                    $ci = trim((string)$cItem['iv']);
                    if (strlen($cc) > $secMaxCipherBytes || strlen($ci) > 256) {
                        api_err('message_too_long', "Message chunk exceeds maximum length ({$secMaxChars} chars).");
                    }
                    $msgUnits[] = array('body' => '', 'cipher' => $cc, 'iv' => $ci);
                }
            } else {
                if (empty($cipher) || empty($iv)) {
                    api_err('e2ee_required', 'Secret chats require client-side AES-256-GCM ciphertext and IV.');
                }
                if (strlen((string)$cipher) > $secMaxCipherBytes || strlen((string)$iv) > 256) {
                    api_err('message_too_long', "Message exceeds maximum length ({$secMaxChars} chars).");
                }
                $msgUnits[] = array('body' => '', 'cipher' => $cipher, 'iv' => $iv);
            }
        } else {
            if ($kind === 'location') {
                $locArr = json_decode($body, true);
                if (!is_array($locArr) && isset($in['lat'], $in['lng'])) {
                    $locArr = array(
                        'lat'   => $in['lat'],
                        'lng'   => $in['lng'],
                        'label' => isset($in['label']) ? (string)$in['label'] : '',
                        'acc'   => isset($in['acc']) ? (int)$in['acc'] : 0
                    );
                } elseif (!is_array($locArr) && isset($in['latitude'], $in['longitude'])) {
                    $locArr = array(
                        'lat'   => $in['latitude'],
                        'lng'   => $in['longitude'],
                        'label' => isset($in['label']) ? (string)$in['label'] : '',
                        'acc'   => isset($in['accuracy']) ? (int)$in['accuracy'] : 0
                    );
                }
                if (!is_array($locArr) || !isset($locArr['lat'], $locArr['lng']) || !is_numeric($locArr['lat']) || !is_numeric($locArr['lng'])) {
                    api_err('invalid_location', 'مختصات مکانی نامعتبر است. / Invalid location coordinates.');
                }
                $latF = round((float)$locArr['lat'], 6);
                $lngF = round((float)$locArr['lng'], 6);
                if ($latF < -90 || $latF > 90 || $lngF < -180 || $lngF > 180) {
                    api_err('invalid_location', 'مختصات خارج از محدوده جغرافیایی مجاز است. / Coordinates out of valid range.');
                }
                $locLbl = isset($locArr['label']) ? u_substr(trim((string)$locArr['label']), 0, 160) : '';
                if ($locLbl !== '' && text_contains_url($locLbl)) {
                    verify_content_type_allowed($db, $chat, $mem, $me, 'link');
                }
                $isLiveLoc = !empty($locArr['is_live']) || !empty($locArr['live']) || !empty($in['is_live']) || !empty($in['live']);
                $liveInterval = isset($locArr['live_interval_sec']) ? (int)$locArr['live_interval_sec'] : (isset($locArr['interval_sec']) ? (int)$locArr['interval_sec'] : (isset($in['live_interval_sec']) ? (int)$in['live_interval_sec'] : (isset($in['interval_sec']) ? (int)$in['interval_sec'] : 15)));
                $liveInterval = max(5, min(3600, $liveInterval));
                $liveDurSec = isset($locArr['live_duration_sec']) ? (int)$locArr['live_duration_sec'] : (isset($locArr['duration_sec']) ? (int)$locArr['duration_sec'] : (isset($in['live_duration_sec']) ? (int)$in['live_duration_sec'] : (isset($in['duration_sec']) ? (int)$in['duration_sec'] : 0)));
                $nowLocTs = app_now($db);
                $liveUntilTs = isset($locArr['live_expires_at']) ? (int)$locArr['live_expires_at'] : (isset($locArr['live_until']) ? (int)$locArr['live_until'] : ($liveDurSec > 0 ? ($nowLocTs + min(86400 * 7, $liveDurSec)) : 0));
                $locPayload = array(
                    'lat'   => $latF,
                    'lng'   => $lngF,
                    'label' => $locLbl,
                    'acc'   => isset($locArr['acc']) ? max(0, min(100000, (int)$locArr['acc'])) : 0
                );
                if ($isLiveLoc) {
                    $locPayload['is_live'] = 1;
                    $locPayload['live'] = 1;
                    $locPayload['live_active'] = 1;
                    $locPayload['stopped'] = 0;
                    $locPayload['live_interval_sec'] = $liveInterval;
                    $locPayload['interval_sec'] = $liveInterval;
                    $locPayload['live_expires_at'] = $liveUntilTs;
                    $locPayload['live_until'] = $liveUntilTs;
                    $locPayload['updated_at'] = $nowLocTs;
                }
                $body = json_encode($locPayload, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
                $msgUnits[] = array('body' => $body, 'cipher' => null, 'iv' => null);
            } else {
                $maxLen = max(100, (int)Settings::get($db, 'max_msg_len', 2000));
                $rawTextChunks = array();
                if (!empty($in['body_chunks']) && is_array($in['body_chunks'])) {
                    foreach ($in['body_chunks'] as $rawBc) {
                        $bcStr = trim((string)$rawBc);
                        if ($bcStr === '') continue;
                        if (u_strlen($bcStr) > $maxLen) {
                            foreach (split_long_message_chunks($bcStr, $maxLen) as $subBc) {
                                $rawTextChunks[] = $subBc;
                            }
                        } else {
                            $rawTextChunks[] = $bcStr;
                        }
                    }
                } elseif ($body !== '' && u_strlen($body) > $maxLen) {
                    $rawTextChunks = split_long_message_chunks($body, $maxLen);
                } elseif ($body !== '') {
                    $rawTextChunks = array($body);
                }

                if (empty($rawTextChunks) && $fileId === null) {
                    api_err('empty_message', 'Message cannot be empty.');
                }
                if (count($rawTextChunks) > $maxChunksPerSend) {
                    api_err('message_too_long', 'پیام بیش از حد طولانی است (حداکثر ' . $maxChunksPerSend . ' بخش). / Message exceeds maximum split parts (' . $maxChunksPerSend . ').');
                }
                if (empty($rawTextChunks)) {
                    $msgUnits[] = array('body' => '', 'cipher' => null, 'iv' => null);
                } else {
                    foreach ($rawTextChunks as $tc) {
                        if ($tc !== '' && text_contains_url($tc)) {
                            verify_content_type_allowed($db, $chat, $mem, $me, 'link');
                        }
                        $msgUnits[] = array('body' => $tc, 'cipher' => null, 'iv' => null);
                    }
                }
            }
        }

        $totalTrafficBytes = 0;
        foreach ($msgUnits as $mu) {
            $totalTrafficBytes += strlen((string)$mu['body']) + strlen((string)$mu['cipher']) + 64;
        }
        verify_and_record_traffic($db, $me, $totalTrafficBytes, true);

        $now = time();
        $resolvedTtl = resolve_effective_message_ttl($db, $chat, $me, $customTtl, $customTtlMode);
        $expiresAt = $resolvedTtl['expires_at'];
        $burnAfter = $resolvedTtl['burn_after'];
        $firstReadAt = $resolvedTtl['first_read_at'];

        $msgCreatedAt = app_now($db);
        $firstMsgId = 0;
        $lastMsgId = 0;
        foreach ($msgUnits as $uIdx => $mu) {
            $unitKind = ($uIdx === 0) ? $kind : 'text';
            $unitFileId = ($uIdx === 0) ? $fileId : null;
            $unitReplyTo = ($uIdx === 0) ? $replyTo : null;
            $db->exec(
                "INSERT INTO messages (chat_id, user_id, kind, body, cipher, iv, reply_to, forward_from_id, forward_origin_id, forward_from_name, forward_hide_author, file_id, created_at, expires_at, burn_after, first_read_at, pinned, spoiler)
                 VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 0, ?)",
                array($cid, $myId, $unitKind, $mu['body'], $mu['cipher'], $mu['iv'], $unitReplyTo, $forwardFromId, $forwardOriginId, $forwardFromName, $forwardHideAuthor, $unitFileId, $msgCreatedAt, $expiresAt, $burnAfter, $firstReadAt, $msgSpoiler)
            );
            $insId = (int)$db->lastId();
            if ($firstMsgId === 0) $firstMsgId = $insId;
            $lastMsgId = $insId;
        }
        $msgId = $lastMsgId;

        $senderFlags = get_user_flags($me);
        if (!empty($senderFlags['user_ghost_mode']) || empty($senderFlags['read_receipts'])) {
            $db->exec("UPDATE members SET last_read_id = ?, last_msg_at = ? WHERE chat_id = ? AND user_id = ?", array($msgId, $now, $cid, $myId));
        } else {
            $db->exec("UPDATE members SET last_read_id = ?, receipt_read_id = ?, last_msg_at = ? WHERE chat_id = ? AND user_id = ?", array($msgId, $msgId, $now, $cid, $myId));
        }
        rate_hit($db, 'msg_flood', (string)$myId, 10);
        if ($chat['type'] !== 'saved') {
            $pushRecipientRows = $db->all(
                "SELECT user_id FROM members WHERE chat_id = ? AND user_id != ? AND muted = 0 AND role != 'pending'",
                array($cid, $myId)
            );
            $pushUids = array();
            foreach ($pushRecipientRows as $prr) $pushUids[] = (int)$prr['user_id'];
            if (!empty($pushUids)) {
                schedule_web_push_wakeup($db, $pushUids, 'normal');
            }
        }
        clear_ephemeral_typing_for_user($db, $myId, $cid);
        bump_tick();

        $fetchLim = max(5, count($msgUnits) + 5);
        $msgs = fetch_chat_messages($db, $chat, $mem, $me, max(0, $firstMsgId - 1), 0, $fetchLim);
        $sentMsgs = array();
        foreach ($msgs as $fm) {
            if ((int)$fm['id'] >= $firstMsgId && (int)$fm['id'] <= $lastMsgId) {
                $sentMsgs[] = $fm;
            }
        }
        if (empty($sentMsgs) && !empty($msgs)) {
            $sentMsgs = array($msgs[count($msgs) - 1]);
        }
        $sentMsg = !empty($sentMsgs) ? $sentMsgs[count($sentMsgs) - 1] : null;
        api_ok(array(
            'message'     => $sentMsg,
            'messages'    => $sentMsgs,
            'chunk_count' => count($sentMsgs)
        ));
    }

    if ($do === 'location_live_update' || $do === 'location_live_stop') {
        $mid = isset($in['message_id']) ? (int)$in['message_id'] : 0;
        $msg = $db->one("SELECT * FROM messages WHERE id = ? AND kind = 'location' AND deleted_at IS NULL", array($mid));
        if (!$msg) api_err('not_found', 'Live location message not found.');
        if ((int)$msg['user_id'] !== $myId && !$isSuper) {
            api_err('forbidden', 'Only the sender can update or stop this live location.');
        }
        $cid = (int)$msg['chat_id'];
        $chat = $db->one("SELECT * FROM chats WHERE id = ?", array($cid));
        $mem = get_active_member($db, $cid, $myId);
        if (!$chat || (!$mem && !$isSuper)) {
            api_err('forbidden', 'Not an active member of this chat.');
        }

        $nowLocTs = app_now($db);
        if ($chat['type'] === 'secret') {
            $newCipher = isset($in['cipher']) ? trim((string)$in['cipher']) : '';
            $newIv = isset($in['iv']) ? trim((string)$in['iv']) : '';
            if ($newCipher === '' || $newIv === '') api_err('e2ee_required', 'Ciphertext required for secret live location.');
            verify_and_record_traffic($db, $me, strlen($newCipher) + 64, true);
            $db->exec("UPDATE messages SET cipher = ?, iv = ? WHERE id = ?", array($newCipher, $newIv, $mid));
        } else {
            $curLoc = json_decode((string)$msg['body'], true);
            if (!is_array($curLoc)) $curLoc = array('lat' => 0, 'lng' => 0, 'label' => '', 'acc' => 0);
            if ($do === 'location_live_stop') {
                $curLoc['is_live'] = 1;
                $curLoc['live'] = 1;
                $curLoc['live_active'] = 0;
                $curLoc['stopped'] = 1;
                $curLoc['stopped_at'] = $nowLocTs;
                if (empty($curLoc['updated_at'])) $curLoc['updated_at'] = (int)$msg['created_at'];
            } else {
                if (!empty($curLoc['stopped']) || (array_key_exists('live_active', $curLoc) && (int)$curLoc['live_active'] === 0)) {
                    api_err('live_location_stopped', 'Live location sharing has already been stopped.');
                }
                $expLim = !empty($curLoc['live_expires_at']) ? (int)$curLoc['live_expires_at'] : (!empty($curLoc['live_until']) ? (int)$curLoc['live_until'] : 0);
                if ($expLim > 0 && $nowLocTs > $expLim) {
                    $curLoc['live_active'] = 0;
                    $curLoc['stopped'] = 1;
                    $db->exec("UPDATE messages SET body = ? WHERE id = ?", array(json_encode($curLoc, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES), $mid));
                    bump_tick();
                    api_err('live_expired', 'Live location duration has ended.');
                }
                $inLatRaw = array_key_exists('latitude', $in) ? $in['latitude'] : (array_key_exists('lat', $in) ? $in['lat'] : null);
                $inLngRaw = array_key_exists('longitude', $in) ? $in['longitude'] : (array_key_exists('lng', $in) ? $in['lng'] : null);
                $inAccRaw = array_key_exists('accuracy', $in) ? $in['accuracy'] : (array_key_exists('acc', $in) ? $in['acc'] : null);
                if ($inLatRaw === null || $inLngRaw === null || !is_numeric($inLatRaw) || !is_numeric($inLngRaw)) {
                    api_err('invalid_location', 'Invalid coordinates.');
                }
                $latF = round((float)$inLatRaw, 6);
                $lngF = round((float)$inLngRaw, 6);
                if ($latF < -90 || $latF > 90 || $lngF < -180 || $lngF > 180) {
                    api_err('invalid_location', 'Coordinates out of range.');
                }
                $curLoc['lat'] = $latF;
                $curLoc['lng'] = $lngF;
                if ($inAccRaw !== null) $curLoc['acc'] = max(0, min(100000, (int)$inAccRaw));
                $curLoc['is_live'] = 1;
                $curLoc['live'] = 1;
                $curLoc['live_active'] = 1;
                $curLoc['stopped'] = 0;
                $curLoc['updated_at'] = $nowLocTs;
            }
            $newBodyLoc = json_encode($curLoc, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
            verify_and_record_traffic($db, $me, strlen($newBodyLoc) + 32, $do !== 'location_live_stop');
            $db->exec("UPDATE messages SET body = ? WHERE id = ?", array($newBodyLoc, $mid));
        }
        bump_tick();
        $updMsgs = fetch_chat_messages($db, $chat, $mem, $me, $mid - 1, $mid + 1, 5);
        $updMsg = null;
        foreach ($updMsgs as $um) {
            if ((int)$um['id'] === $mid) { $updMsg = $um; break; }
        }
        api_ok(array('message' => $updMsg, 'updated_at' => $nowLocTs));
    }

    if ($do === 'message_edit') {
        $mid = isset($in['message_id']) ? (int)$in['message_id'] : 0;
        $newBody = isset($in['body']) ? trim((string)$in['body']) : '';
        $newCipher = isset($in['cipher']) ? trim((string)$in['cipher']) : null;
        $newIv = isset($in['iv']) ? trim((string)$in['iv']) : null;

        $msg = $db->one("SELECT * FROM messages WHERE id = ? AND deleted_at IS NULL", array($mid));
        if (!$msg || $msg['kind'] === 'system' || $msg['kind'] === 'call_log' || $msg['kind'] === 'location') api_err('not_found', 'Message not found.');
        $chat = $db->one("SELECT * FROM chats WHERE id = ?", array((int)$msg['chat_id']));
        if (!$chat) api_err('not_found', 'Chat not found.');
        $mem = get_active_member($db, (int)$msg['chat_id'], $myId);
        if (!$mem && (!$isSuper || $chat['type'] === 'secret')) api_err('forbidden', 'Not an active member of this chat.');
        if ((int)$msg['user_id'] !== $myId && !$isSuper) {
            api_err('forbidden', 'You can only edit your own messages.');
        }
        verify_can_post($db, $chat, $mem, $me, 'text');
        $editWin = (int)Settings::get($db, 'edit_window_sec', 172800);
        if ($editWin > 0 && (time() - (int)$msg['created_at']) > $editWin && !$isSuper) {
            api_err('edit_window_expired', 'Edit time window has expired.');
        }
        $isGhostEditCtx = (!$mem && $isSuper && $chat['type'] !== 'secret');
        $silentCode = resolve_silent_edit_mode_on_save($db, $chat, $me, $isGhostEditCtx);
        $prevHist = array();
        if (!empty($msg['edit_history_json'])) {
            $decodedHist = json_decode((string)$msg['edit_history_json'], true);
            if (is_array($decodedHist)) $prevHist = $decodedHist;
        }
        $editNowTs = time();
        if ($chat['type'] === 'secret') {
            if (empty($newCipher) || empty($newIv)) api_err('e2ee_required', 'Ciphertext required.');
            $secMaxCharsEd = max(100, (int)Settings::get($db, 'max_msg_len', 2000));
            $secMaxCipherBytesEd = (($secMaxCharsEd * 4) + 128) * 2;
            if (strlen($newCipher) > $secMaxCipherBytesEd || strlen($newIv) > 256) api_err('message_too_long', 'Ciphertext exceeds maximum length.');
            if ((string)$msg['cipher'] !== (string)$newCipher || (string)$msg['iv'] !== (string)$newIv) {
                $prevHist[] = array(
                    'cipher'    => (string)$msg['cipher'],
                    'iv'        => (string)$msg['iv'],
                    'ts'        => !empty($msg['edited_at']) ? (int)$msg['edited_at'] : (int)$msg['created_at'],
                    'edited_at' => $editNowTs,
                    'editor_id' => $myId
                );
                if (count($prevHist) > 50) $prevHist = array_slice($prevHist, -50);
            }
            $histJson = !empty($prevHist) ? json_encode($prevHist, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) : null;
            $db->exec("UPDATE messages SET cipher = ?, iv = ?, edited_at = ?, edited_silent = ?, edit_history_json = ? WHERE id = ?", array($newCipher, $newIv, $editNowTs, $silentCode, $histJson, $mid));
        } else {
            // Strict hard limit on message editing (multi-message splitting applies ONLY to normal sending)
            $maxLen = max(100, (int)Settings::get($db, 'max_msg_len', 2000));
            if (u_strlen($newBody) > $maxLen) {
                api_err('message_too_long', "Message exceeds maximum length ({$maxLen} chars).");
            }
            if ($newBody === '' && empty($msg['file_id'])) api_err('empty_message', 'Message body cannot be empty.');
            if ($newBody !== '' && text_contains_url($newBody)) {
                verify_content_type_allowed($db, $chat, $mem, $me, 'link');
            }
            if ((string)$msg['body'] !== $newBody) {
                $prevHist[] = array(
                    'body'      => (string)$msg['body'],
                    'ts'        => !empty($msg['edited_at']) ? (int)$msg['edited_at'] : (int)$msg['created_at'],
                    'edited_at' => $editNowTs,
                    'editor_id' => $myId
                );
                if (count($prevHist) > 50) $prevHist = array_slice($prevHist, -50);
            }
            $histJson = !empty($prevHist) ? json_encode($prevHist, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) : null;
            $db->exec("UPDATE messages SET body = ?, edited_at = ?, edited_silent = ?, edit_history_json = ? WHERE id = ?", array($newBody, $editNowTs, $silentCode, $histJson, $mid));
        }
        bump_tick();
        api_ok(array('edited' => true, 'message_id' => $mid, 'edited_silent' => $silentCode));
    }

    if ($do === 'message_delete') {
        $mid = isset($in['message_id']) ? (int)$in['message_id'] : 0;
        $mode = isset($in['mode']) && $in['mode'] === 'me' ? 'me' : 'everyone';

        $msg = $db->one("SELECT * FROM messages WHERE id = ? AND deleted_at IS NULL", array($mid));
        if (!$msg) api_err('not_found', 'Message not found.');
        $cid = (int)$msg['chat_id'];
        $chat = $db->one("SELECT * FROM chats WHERE id = ?", array($cid));
        $mem = get_active_member($db, $cid, $myId);
        if (!$chat || (!$mem && (!$isSuper || $chat['type'] === 'secret'))) {
            api_err('forbidden', 'Not an active member of this chat.');
        }
        if ($chat['type'] === 'system') {
            api_err('forbidden', 'Official System Chat messages cannot be deleted or manipulated.');
        }

        if ($mode === 'me') {
            $hf = !empty($msg['hidden_for']) ? json_decode((string)$msg['hidden_for'], true) : array();
            if (!is_array($hf)) $hf = array();
            if (!in_array($myId, $hf, true)) $hf[] = $myId;
            $db->exec("UPDATE messages SET hidden_for = ? WHERE id = ?", array(json_encode($hf), $mid));
            api_ok(array('deleted' => true, 'mode' => 'me', 'message_id' => $mid));
        }

        $canDelEveryone = ((int)$msg['user_id'] === $myId) || has_admin_perm($chat, $mem, $me, 'delete_messages');
        if (!$canDelEveryone) {
            api_err('forbidden', 'You do not have permission to delete this message for everyone.');
        }

        $cascadedIds = cascade_delete_messages_by_ids($db, array($mid));
        bump_tick();
        api_ok(array('deleted' => true, 'mode' => 'everyone', 'message_id' => $mid, 'cascaded_ids' => $cascadedIds));
    }

    if ($do === 'messages_bulk_delete') {
        $cid = isset($in['chat_id']) ? (int)$in['chat_id'] : 0;
        $rawIds = isset($in['message_ids']) && is_array($in['message_ids']) ? $in['message_ids'] : array();
        $mode = isset($in['mode']) && $in['mode'] === 'me' ? 'me' : 'everyone';
        $chat = $db->one("SELECT * FROM chats WHERE id = ?", array($cid));
        $mem = get_active_member($db, $cid, $myId);
        if (!$chat || (!$mem && (!$isSuper || $chat['type'] === 'secret'))) {
            api_err('forbidden', 'Not an active member of this chat.');
        }
        $cleanIds = array();
        foreach ($rawIds as $rid) {
            $v = (int)$rid;
            if ($v > 0) $cleanIds[$v] = $v;
        }
        if (empty($cleanIds)) api_ok(array('deleted_ids' => array(), 'mode' => $mode));
        $ph = implode(',', array_fill(0, count($cleanIds), '?'));
        $rows = $db->all("SELECT * FROM messages WHERE chat_id = ? AND id IN ($ph) AND deleted_at IS NULL", array_merge(array($cid), array_values($cleanIds)));
        if (empty($rows)) api_ok(array('deleted_ids' => array(), 'mode' => $mode));

        if ($mode === 'me') {
            $done = array();
            foreach ($rows as $r) {
                $hf = !empty($r['hidden_for']) ? json_decode((string)$r['hidden_for'], true) : array();
                if (!is_array($hf)) $hf = array();
                if (!in_array($myId, $hf, true)) $hf[] = $myId;
                $db->exec("UPDATE messages SET hidden_for = ? WHERE id = ?", array(json_encode($hf), (int)$r['id']));
                $done[] = (int)$r['id'];
            }
            api_ok(array('deleted_ids' => $done, 'mode' => 'me'));
        }

        $hasDelPerm = has_admin_perm($chat, $mem, $me, 'delete_messages');
        $allowedEveryoneIds = array();
        foreach ($rows as $r) {
            if ($r['kind'] === 'system' && !$isSuper && !$hasDelPerm) continue;
            if ((int)$r['user_id'] === $myId || $hasDelPerm) {
                $allowedEveryoneIds[] = (int)$r['id'];
            } else {
                api_err('forbidden', 'You do not have permission to delete all selected messages for everyone.');
            }
        }
        $cascaded = cascade_delete_messages_by_ids($db, $allowedEveryoneIds);
        bump_tick();
        api_ok(array('deleted_ids' => $allowedEveryoneIds, 'cascaded_ids' => $cascaded, 'mode' => 'everyone'));
    }

    if ($do === 'message_read') {
        $cid = isset($in['chat_id']) ? (int)$in['chat_id'] : 0;
        $upToId = isset($in['message_id']) ? (int)$in['message_id'] : 0;

        $chat = $db->one("SELECT id, type FROM chats WHERE id = ?", array($cid));
        if (!$chat) api_err('not_found', 'Chat not found.');
        $mem = get_active_member($db, $cid, $myId);
        if (!$mem) {
            if ($isSuper && $chat['type'] !== 'secret') {
                api_ok(array('last_read_id' => $upToId, 'ghost' => true, 'activated_burns' => array()));
            }
            api_err('not_member', 'Not an active member.');
        }

        if ($upToId <= 0) {
            $upToId = (int)$db->val("SELECT COALESCE(MAX(id), 0) FROM messages WHERE chat_id = ?", array($cid));
        }

        $myFlags = get_user_flags($me);
        $isGhostUserMode = !empty($myFlags['user_ghost_mode']);
        $suppressReceiptTicks = ($isGhostUserMode || empty($myFlags['read_receipts']));
        $prevLastRead = (int)$mem['last_read_id'];
        $prevReceiptRead = (int)$mem['receipt_read_id'];

        // Record Group/Channel message viewers ONLY when NOT in Ghost Mode (Ghost views are NEVER recorded!)
        if (!$isGhostUserMode && in_array((string)$chat['type'], array('group', 'channel'), true) && $upToId > 0) {
            $readFloor = max((int)$mem['joined_msg_id'], $prevReceiptRead);
            if ($upToId > $readFloor) {
                $nowReadTs = app_now($db);
                $unseenRows = $db->all(
                    "SELECT m.id FROM messages m
                     LEFT JOIN message_reads mr ON mr.message_id = m.id AND mr.user_id = ?
                     WHERE m.chat_id = ? AND m.id > ? AND m.id <= ? AND m.user_id != ?
                       AND m.kind != 'system' AND m.deleted_at IS NULL
                       AND mr.user_id IS NULL
                     ORDER BY m.id DESC " . $db->limit(300),
                    array($myId, $cid, $readFloor, $upToId, $myId)
                );
                foreach ($unseenRows as $ur) {
                    // insertIgnore reports 0 affected rows when the (message_id,
                    // user_id) pair already existed, so the counter only ever
                    // moves on a genuinely new viewer. The query above already
                    // excludes the author, matching how channels count views.
                    $added = $db->insertIgnore('message_reads', array(
                        'message_id' => (int)$ur['id'],
                        'chat_id'    => $cid,
                        'user_id'    => $myId,
                        'read_at'    => $nowReadTs
                    ));
                    if ($added) {
                        $db->exec("UPDATE messages SET views = views + 1 WHERE id = ?", array((int)$ur['id']));
                    }
                }
            }
        }

        if ($upToId > $prevLastRead) {
            if ($suppressReceiptTicks) {
                $db->exec("UPDATE members SET last_read_id = ? WHERE chat_id = ? AND user_id = ?", array($upToId, $cid, $myId));
            } else {
                $newReceipt = max($prevReceiptRead, $upToId);
                $db->exec("UPDATE members SET last_read_id = ?, receipt_read_id = ? WHERE chat_id = ? AND user_id = ?", array($upToId, $newReceipt, $cid, $myId));
                bump_tick();
            }
        } elseif (!$suppressReceiptTicks && $upToId > $prevReceiptRead) {
            $db->exec("UPDATE members SET receipt_read_id = ? WHERE chat_id = ? AND user_id = ?", array($upToId, $cid, $myId));
            bump_tick();
        }
        $activatedBurns = $isGhostUserMode ? array() : activate_first_view_burns($db, $cid, $upToId, $myId);
        api_ok(array('last_read_id' => $upToId, 'user_ghost_mode' => $isGhostUserMode ? 1 : 0, 'activated_burns' => $activatedBurns));
    }

    if ($do === 'message_viewers') {
        $mid = isset($in['message_id']) ? (int)$in['message_id'] : 0;
        $q = isset($in['q']) ? trim((string)$in['q']) : '';
        $page = isset($in['page']) ? max(1, (int)$in['page']) : 1;
        $perPage = isset($in['per_page']) ? (int)$in['per_page'] : 20;
        if (!in_array($perPage, array(5, 10, 20, 50, 100), true)) {
            $perPage = max(5, min(100, $perPage > 0 ? $perPage : 20));
        }

        $msg = $db->one("SELECT id, chat_id, user_id, kind, deleted_at, expires_at, hidden_for, visible_only_to FROM messages WHERE id = ?", array($mid));
        if (!$msg || $msg['deleted_at'] !== null || $msg['kind'] === 'system' || (!empty($msg['expires_at']) && (int)$msg['expires_at'] <= time())) {
            api_err('not_found', 'پیام یافت نشد. / Message not found.');
        }
        if ($msg['visible_only_to'] !== null && (int)$msg['visible_only_to'] !== $myId && !$isSuper) {
            api_err('not_found', 'پیام یافت نشد. / Message not found.');
        }
        if (is_hidden_for_user($msg['hidden_for'], $myId) && !$isSuper) {
            api_err('not_found', 'پیام یافت نشد. / Message not found.');
        }

        $cid = (int)$msg['chat_id'];
        $chat = $db->one("SELECT * FROM chats WHERE id = ?", array($cid));
        if (!$chat || !in_array((string)$chat['type'], array('group', 'channel'), true)) {
            api_err('forbidden', 'مشاهده‌کنندگان پیام فقط در گروه‌ها و کانال‌ها در دسترس است. / Message viewers are only available in groups and channels.');
        }
        $mem = get_active_member($db, $cid, $myId);
        if (!$isSuper && (!$mem || ($chat['history'] === 'from_join' && $mid < (int)$mem['joined_msg_id']))) {
            api_err('forbidden', 'شما به این پیام دسترسی ندارید. / Access denied.');
        }
        if (!can_user_view_message_readers($db, $chat, $mem, $me)) {
            api_err('viewers_forbidden', 'مشاهده فهرست بازدیدکنندگان پیام برای شما یا در این گفتگو غیرفعال است. / Viewing message readers is disabled for your role or this chat.');
        }

        $whereSql = "mr.message_id = ? AND mr.user_id != ? AND u.status != 'deleted'";
        $params = array($mid, (int)$msg['user_id']);
        if ($q !== '') {
            $qClean = u_lower(ltrim($q, '@'));
            $likePat = '%' . str_replace(array('%', '_'), array('\\%', '\\_'), $qClean) . '%';
            $whereSql .= " AND (LOWER(u.name) LIKE ? OR LOWER(u.username) LIKE ?)";
            $params[] = $likePat;
            $params[] = $likePat;
        }

        $total = (int)$db->val(
            "SELECT COUNT(*) FROM message_reads mr JOIN users u ON u.id = mr.user_id WHERE {$whereSql}",
            $params
        );
        $totalPages = max(1, (int)ceil($total / $perPage));
        if ($page > $totalPages) $page = $totalPages;
        $offset = ($page - 1) * $perPage;

        $rows = $db->all(
            "SELECT mr.user_id, mr.read_at, u.username, u.name, u.avatar, u.role, u.show_admin_badge, u.flags
             FROM message_reads mr
             JOIN users u ON u.id = mr.user_id
             WHERE {$whereSql}
             ORDER BY mr.read_at DESC, mr.user_id DESC " . $db->limit($perPage, $offset),
            $params
        );
        $items = array();
        foreach ($rows as $vr) {
            $vf = parse_json_col($vr['flags'], array());
            $items[] = array(
                'user_id'         => (int)$vr['user_id'],
                'name'            => (string)$vr['name'],
                'username'        => (!empty($vf['no_username']) && !$isSuper) ? '' : (string)$vr['username'],
                'avatar'          => (string)$vr['avatar'],
                'role'            => (string)$vr['role'],
                'has_admin_badge' => ($vr['role'] === 'superadmin' && (int)$vr['show_admin_badge'] === 1) ? 1 : 0,
                'read_at'         => (int)$vr['read_at']
            );
        }

        api_ok(array(
            'message_id'  => $mid,
            'total'       => $total,
            'page'        => $page,
            'per_page'    => $perPage,
            'total_pages' => $totalPages,
            'items'       => $items
        ));
    }

    if ($do === 'messages_burn_touch') {
        $cid = isset($in['chat_id']) ? (int)$in['chat_id'] : 0;
        $mids = isset($in['message_ids']) && is_array($in['message_ids']) ? $in['message_ids'] : array();
        $maxMid = 0;
        foreach ($mids as $mRaw) {
            $mv = (int)$mRaw;
            if ($mv > $maxMid) $maxMid = $mv;
        }
        $mem = get_active_member($db, $cid, $myId);
        if (!$mem || $maxMid <= 0) {
            api_ok(array('activated_burns' => array()));
        }
        $myFlags = get_user_flags($me);
        $activatedBurns = !empty($myFlags['user_ghost_mode']) ? array() : activate_first_view_burns($db, $cid, $maxMid, $myId);
        api_ok(array('activated_burns' => $activatedBurns));
    }

    if ($do === 'reaction_toggle') {
        $mid = isset($in['message_id']) ? (int)$in['message_id'] : 0;
        $emoji = isset($in['emoji']) ? trim((string)$in['emoji']) : '👍';
        if (u_strlen($emoji) > 8 || $emoji === '') $emoji = '👍';

        $msg = $db->one("SELECT id, chat_id, expires_at, visible_only_to FROM messages WHERE id = ? AND deleted_at IS NULL", array($mid));
        if (!$msg || (!empty($msg['expires_at']) && (int)$msg['expires_at'] <= time())) {
            api_err('not_found', 'Message not found.');
        }
        if ($msg['visible_only_to'] !== null && (int)$msg['visible_only_to'] !== $myId) {
            api_err('not_found', 'Message not found.');
        }
        $cid = (int)$msg['chat_id'];
        $chat = $db->one("SELECT * FROM chats WHERE id = ?", array($cid));
        if (!$chat) api_err('not_found', 'Chat not found.');
        if ($chat['type'] === 'system') {
            api_err('forbidden', 'Reactions are disabled in Official System Chat.');
        }
        $mem = get_active_member($db, $cid, $myId);
        if (!$mem && (!$isSuper || $chat['type'] === 'secret')) api_err('forbidden', 'Not an active member.');
        if ($mem && $chat['history'] === 'from_join' && (int)$msg['id'] < (int)$mem['joined_msg_id'] && !$isSuper) {
            api_err('forbidden', 'Message is not visible.');
        }

        if (!$isSuper && ($chat['type'] === 'group' || $chat['type'] === 'channel')) {
            $cPerms = parse_json_col($chat['perms_json'], array('reactions_enabled' => 1, 'admins_only' => 0));
            if (isset($cPerms['reactions_enabled']) && (int)$cPerms['reactions_enabled'] === 0) {
                api_err('reactions_disabled', 'Message reactions are disabled by admins in this chat.');
            }
            if ($chat['type'] === 'group' && !empty($cPerms['admins_only']) && !is_chat_admin_or_owner($chat, $mem, $me)) {
                api_err('admins_only', 'فعالیت در این گروه به مدیران محدود شده است. / Group activity is restricted to admins only.');
            }
        }

        $sameExists = $db->val("SELECT 1 FROM reactions WHERE message_id = ? AND user_id = ? AND emoji = ?", array($mid, $myId, $emoji));
        if (!$sameExists && !$isSuper) {
            $myReactFlags = get_user_flags($me);
            if (!empty($myReactFlags['ban_react'])) {
                api_err('global_react_banned', 'حساب شما از ثبت واکنش (ری‌اکشن) محدود شده است. / Your account is restricted from adding reactions.');
            }
            if ($mem && !is_chat_admin_or_owner($chat, $mem, $me)) {
                $memReactPerms = parse_json_col($mem['perms_json'], array());
                if (!empty($memReactPerms['mute_react'])) {
                    api_err('member_react_restricted', 'امکان ثبت واکنش شما در این گروه توسط مدیر محدود شده است. / You are restricted from adding reactions in this group.');
                }
            }
        }
        // Enforce strictly ONE reaction per user on every message
        $db->exec("DELETE FROM reactions WHERE message_id = ? AND user_id = ?", array($mid, $myId));
        if (!$sameExists) {
            $db->insertIgnore('reactions', array('message_id' => $mid, 'user_id' => $myId, 'emoji' => $emoji));
        }
        bump_tick();
        api_ok(array('toggled' => true, 'removed' => (bool)$sameExists));
    }

    if ($do === 'typing') {
        $cid = isset($in['chat_id']) ? (int)$in['chat_id'] : 0;
        $isTypingActive = !isset($in['typing']) || !empty($in['typing']);
        if ($cid <= 0) {
            api_ok(array('ok' => true, 'suppressed' => true));
        }
        if (rate_get_attempts($db, 'typing_hb', (string)$myId, 10) >= 30) {
            api_ok(array('ok' => true, 'throttled' => true));
        }
        rate_hit($db, 'typing_hb', (string)$myId, 10);
        if (!$isTypingActive) {
            clear_ephemeral_typing_for_user($db, $myId, $cid);
            api_ok(array('ok' => true, 'typing' => 0, 'typing_tick' => get_typing_tick()));
        }
        $chat = $db->one("SELECT * FROM chats WHERE id = ?", array($cid));
        if (!$chat || !is_chat_typing_supported_type($chat['type']) || $chat['status'] !== 'active') {
            clear_ephemeral_typing_for_user($db, $myId, $cid);
            api_ok(array('ok' => true, 'suppressed' => true));
        }
        $mem = get_active_member($db, $cid, $myId);
        if (!$mem) {
            // Super-Admin Ghost Mode NEVER records or broadcasts typing
            if ($isSuper) api_ok(array('ok' => true, 'ghost' => true, 'suppressed' => true));
            api_err('forbidden', 'Not an active member.');
        }
        if (!is_chat_typing_display_enabled($db, $chat) || !is_sender_typing_broadcast_allowed($db, $chat, $mem, $me)) {
            clear_ephemeral_typing_for_user($db, $myId, $cid);
            api_ok(array('ok' => true, 'suppressed' => true));
        }
        if ($chat['type'] === 'dm' || $chat['type'] === 'secret') {
            $peerMem = $db->one("SELECT user_id FROM members WHERE chat_id = ? AND user_id != ? LIMIT 1", array($cid, $myId));
            if ($peerMem) {
                $pUid = (int)$peerMem['user_id'];
                $blk = $db->val(
                    "SELECT 1 FROM blocks WHERE (user_id = ? AND blocked_id = ?) OR (user_id = ? AND blocked_id = ?)",
                    array($myId, $pUid, $pUid, $myId)
                );
                if ($blk) {
                    clear_ephemeral_typing_for_user($db, $myId, $cid);
                    api_ok(array('ok' => true, 'suppressed' => true));
                }
            }
        }
        prune_expired_ephemeral_typing($db);
        $expTs = (string)(time() + 6);
        $db->upsert('meta', array('k' => "typing_{$cid}_{$myId}", 'v' => $expTs), 'k');
        $nextTypingTick = bump_typing_tick();
        api_ok(array('ok' => true, 'typing' => 1, 'typing_tick' => $nextTypingTick));
    }

    if ($do === 'upload_chunk') {
        verify_uploads_allowed_for_user($db, $me);
        $upId = isset($_GET['upload_id']) ? trim((string)$_GET['upload_id']) : '';
        $chunkIdx = isset($_GET['chunk_index']) ? (int)$_GET['chunk_index'] : -1;
        if (!preg_match('/^[a-f0-9]{24,64}$/', $upId) || $chunkIdx < 0) {
            api_err('invalid_chunk_params', 'Invalid chunk upload parameters.');
        }
        $chunkLen = strlen((string)$rawInput);
        if ($chunkLen <= 0 || $chunkLen > 2 * 1048576) {
            api_err('invalid_chunk_size', 'Invalid chunk size.');
        }
        $maxBytes = (int)round(max(0.5, (float)Settings::get($db, 'max_file_mb', 16)) * 1048576);
        ensure_data_dirs();
        $partPath = DATA_DIR . '/chunk_up_' . $myId . '_' . $upId . '.part';
        if ($chunkIdx === 0 && file_exists($partPath)) {
            @unlink($partPath);
        }
        // Prevent orphaned .part disk exhaustion per user
        if ($chunkIdx === 0 && is_dir(DATA_DIR)) {
            $userPartBytes = 0;
            $nowPartChk = time();
            $dScan = @scandir(DATA_DIR);
            if (is_array($dScan)) {
                $myPrefix = 'chunk_up_' . $myId . '_';
                foreach ($dScan as $df) {
                    if (substr($df, -5) !== '.part') continue;
                    $fullDf = DATA_DIR . '/' . $df;
                    $mtDf = (int)@filemtime($fullDf);
                    if ($mtDf > 0 && ($nowPartChk - $mtDf) > 3600) {
                        @unlink($fullDf);
                        continue;
                    }
                    if (strpos($df, $myPrefix) === 0) {
                        $userPartBytes += (int)@filesize($fullDf);
                    }
                }
            }
            if (!$isSuper && $userPartBytes > ($maxBytes * 3)) {
                api_err('rate_limited', 'Too many incomplete uploads in progress. Please wait or finish current upload.');
            }
        }
        $curBytes = ($chunkIdx === 0 || !file_exists($partPath)) ? 0 : (int)@filesize($partPath);
        if (($curBytes + $chunkLen) > $maxBytes) {
            if (file_exists($partPath)) @unlink($partPath);
            api_err('file_too_large', 'حجم فایل بیشتر از سقف مجاز هر فایل است / File exceeds maximum allowed per-file size.');
        }
        // Pre-flight check traffic quota for projected total size (actual accounting happens once at upload finalize)
        if (!$isSuper) {
            $sysTrPre = sync_and_get_system_traffic_status($db);
            $usrTrPre = sync_and_get_user_traffic_status($db, $me);
            if ($sysTrPre['limit_bytes'] > 0 && (($sysTrPre['used_bytes'] + $curBytes + $chunkLen) > $sysTrPre['limit_bytes'])) {
                if (file_exists($partPath)) @unlink($partPath);
                api_err('system_traffic_exceeded', 'سقف ترافیک کل سامانه تکمیل شده است. / Total system traffic quota has been reached.', 200, array('reset_at' => $sysTrPre['reset_at']));
            }
            if ($usrTrPre['limit_bytes'] > 0 && (($usrTrPre['used_bytes'] + $curBytes + $chunkLen) > $usrTrPre['limit_bytes'])) {
                if (file_exists($partPath)) @unlink($partPath);
                api_err('user_traffic_exceeded', 'سقف مصرف ترافیک حساب کاربری شما تکمیل شده است. / Your account traffic quota has been reached.', 200, array('reset_at' => $usrTrPre['reset_at']));
            }
        }
        $fp = @fopen($partPath, $chunkIdx === 0 ? 'wb' : 'ab');
        if (!$fp) {
            api_err('upload_save_failed', 'Could not write upload chunk.');
        }
        $written = @fwrite($fp, (string)$rawInput);
        @fclose($fp);
        if ($written !== $chunkLen) {
            @unlink($partPath);
            api_err('upload_save_failed', 'Incomplete chunk write.');
        }
        api_ok(array('upload_id' => $upId, 'received_bytes' => $curBytes + $chunkLen));
    }

    if ($do === 'upload') {
        verify_uploads_allowed_for_user($db, $me);
        $cid = isset($in['chat_id']) ? (int)$in['chat_id'] : 0;
        $kind = isset($in['kind']) && in_array($in['kind'], array('voice', 'video_note'), true) ? $in['kind'] : 'file';
        $caption = isset($in['caption']) ? trim((string)$in['caption']) : (isset($in['body']) ? trim((string)$in['body']) : '');
        $encrypted = !empty($in['encrypted']) ? 1 : 0;
        $fileIv = isset($in['file_iv']) ? trim((string)$in['file_iv']) : null;
        $cipherCaption = isset($in['cipher']) ? trim((string)$in['cipher']) : null;
        $captionIv = isset($in['iv']) ? trim((string)$in['iv']) : null;
        $replyTo = isset($in['reply_to']) && (int)$in['reply_to'] > 0 ? (int)$in['reply_to'] : null;

        $chat = $db->one("SELECT * FROM chats WHERE id = ?", array($cid));
        $mem = $db->one("SELECT * FROM members WHERE chat_id = ? AND user_id = ?", array($cid, $myId));
        if (!$chat) api_err('not_found', 'Chat not found.');
        verify_can_post($db, $chat, $mem, $me, $kind);

        if (rate_get_attempts($db, 'msg_flood', (string)$myId, 10) > 25) {
            api_err('rate_limited', 'Uploading too fast. Please slow down.');
        }
        if ($replyTo !== null) {
            $validReply = $db->val("SELECT id FROM messages WHERE id = ? AND chat_id = ? AND deleted_at IS NULL", array($replyTo, $cid));
            if (!$validReply) $replyTo = null;
        }

        if ($kind === 'voice' && !$isSuper && !(int)Settings::get($db, 'voice_enabled', 1)) {
            api_err('voice_disabled', 'Voice messages are disabled by administrator.');
        }
        if ($kind === 'video_note' && !$isSuper && !(int)Settings::get($db, 'video_note_enabled', 1)) {
            api_err('video_note_disabled', 'ارسال پیام ویدیویی فوری توسط مدیر کل غیرفعال شده است. / Instant video messages are disabled by administrator.');
        }

        $chunkUpId = isset($in['chunk_upload_id']) ? trim((string)$in['chunk_upload_id']) : '';
        $isChunkedFile = false;
        $sourceTmpPath = '';
        $rawOrigName = '';
        $fSize = 0;

        if ($chunkUpId !== '') {
            if (!preg_match('/^[a-f0-9]{24,64}$/', $chunkUpId)) {
                api_err('invalid_chunk_params', 'Invalid chunk upload ID.');
            }
            $sourceTmpPath = DATA_DIR . '/chunk_up_' . $myId . '_' . $chunkUpId . '.part';
            if (!is_file($sourceTmpPath)) {
                api_err('no_file', 'Uploaded file chunks were not found.');
            }
            $isChunkedFile = true;
            $fSize = (int)@filesize($sourceTmpPath);
            $rawOrigName = isset($in['file_name']) ? (string)$in['file_name'] : '';
        } else {
            if (empty($_FILES['file']) || !is_uploaded_file($_FILES['file']['tmp_name'])) {
                api_err('no_file', 'No valid uploaded file received.');
            }
            $sourceTmpPath = $_FILES['file']['tmp_name'];
            $fSize = (int)$_FILES['file']['size'];
            $rawOrigName = (string)$_FILES['file']['name'];
        }

        $cleanupChunkOnErr = function() use ($isChunkedFile, $sourceTmpPath) {
            if ($isChunkedFile && $sourceTmpPath !== '' && file_exists($sourceTmpPath)) {
                @unlink($sourceTmpPath);
            }
        };

        $maxBytes = (int)round(max(0.5, (float)Settings::get($db, 'max_file_mb', 16)) * 1048576);
        if ($fSize <= 0 || $fSize > $maxBytes) {
            $cleanupChunkOnErr();
            api_err('file_too_large', 'حجم فایل بیشتر از سقف مجاز هر فایل است / File exceeds maximum allowed per-file size.');
        }

        // Enforce Global Total Dedicated Storage Limit (deduplicated physical disk usage; Super-Admin exempt)
        $maxTotalMb = (float)Settings::get($db, 'max_total_storage_mb', 0);
        if (!$isSuper && $maxTotalMb > 0) {
            $curTotalBytes = (int)$db->val("SELECT COALESCE(SUM(mx_sz), 0) FROM (SELECT MAX(size) AS mx_sz FROM files GROUP BY stored_name) t");
            $limitTotalBytes = (int)round($maxTotalMb * 1048576);
            if (($curTotalBytes + $fSize) > $limitTotalBytes) {
                $cleanupChunkOnErr();
                api_err('global_storage_quota_exceeded', 'ظرفیت کل فضای اختصاصی بارگذاری سرور تکمیل شده است / Dedicated total server upload storage limit reached.');
            }
        }

        // Enforce Per-User Dedicated Storage Limit (Super-Admin exempt)
        $effUserQuotaMb = get_user_effective_quota_mb($db, $me);
        if (!$isSuper && $effUserQuotaMb > 0) {
            $curUserBytes = (int)$db->val("SELECT COALESCE(SUM(size), 0) FROM files WHERE owner_id = ?", array($myId));
            $limitUserBytes = (int)round($effUserQuotaMb * 1048576);
            if (($curUserBytes + $fSize) > $limitUserBytes) {
                $cleanupChunkOnErr();
                api_err('user_storage_quota_exceeded', 'سهمیه فضای بارگذاری شما تکمیل شده است. می‌توانید از بخش «فایل‌های من» فایل‌های قبلی خود را حذف کنید / Your dedicated upload storage quota is full.');
            }
        }

        // Enforce System & Per-User Traffic Quotas (Super-Admin exempt from blocking, traffic still accounted)
        verify_and_record_traffic($db, $me, $fSize, true, $cleanupChunkOnErr);

        $origName = basename($rawOrigName);
        if ($origName === '' || $origName === 'blob') {
            $prefix = ($kind === 'voice') ? 'voice_' : (($kind === 'video_note') ? 'vnote_' : 'file_');
            $defExt = ($kind === 'voice' || $kind === 'video_note') ? '.webm' : '.bin';
            $origName = $prefix . time() . $defExt;
        }
        $ext = strtolower(pathinfo($origName, PATHINFO_EXTENSION));
        $blockedExecExts = array('svg', 'svgz', 'php', 'phtml', 'phar', 'pht', 'phps', 'php3', 'php4', 'php5', 'php7', 'php8', 'html', 'htm', 'xhtml', 'shtml', 'xml', 'xsl', 'js', 'mjs', 'cjs', 'vbs', 'bat', 'cmd', 'sh', 'cgi', 'pl', 'jsp', 'asp', 'aspx', 'cer', 'asa', 'war', 'swf', 'htaccess');
        if (in_array($ext, $blockedExecExts, true)) {
            $cleanupChunkOnErr();
            api_err('invalid_extension', 'File extension (.' . $ext . ') is forbidden for security reasons.');
        }
        if ($encrypted !== 1) {
            $rawAllowedExts = u_lower((string)Settings::get($db, 'allowed_exts', ''));
            $allowedList = array_values(array_filter(array_map('trim', explode(',', $rawAllowedExts))));
            $voiceExts = array('webm', 'ogg', 'opus', 'mp4', 'm4a', 'wav', 'mp3', 'aac');
            $vnoteExts = array('webm', 'mp4', 'ogg', 'mkv', 'mov', 'm4v');
            if ($kind === 'voice') {
                if (!in_array($ext, $voiceExts, true)) {
                    $cleanupChunkOnErr();
                    api_err('invalid_extension', 'Invalid voice recording audio format.');
                }
            } elseif ($kind === 'video_note') {
                if (!in_array($ext, $vnoteExts, true)) {
                    $cleanupChunkOnErr();
                    api_err('invalid_extension', 'Invalid instant video message format.');
                }
            } elseif (!empty($allowedList) && !in_array('*', $allowedList, true)) {
                if ($ext === '' || !in_array($ext, $allowedList, true)) {
                    $cleanupChunkOnErr();
                    api_err('invalid_extension', 'پسوند فایل (.' . $ext . ') در فهرست پسوندهای مجاز مدیریت نیست / File extension (.' . $ext . ') is not in allowed extensions.');
                }
            }
        }

        $mime = detect_and_validate_magic_bytes($sourceTmpPath, $ext, $encrypted, $kind);
        if ($mime === false) {
            $cleanupChunkOnErr();
            api_err('invalid_file_signature', 'File content does not match allowed magic bytes or contains forbidden markup.');
        }

        $declaredCat = isset($in['media_cat']) ? (string)$in['media_cat'] : '';
        $upContentType = classify_content_type_from_upload($kind, $mime, $origName, $declaredCat);
        verify_content_type_allowed($db, $chat, $mem, $me, $upContentType, $cleanupChunkOnErr);
        if ($encrypted !== 1 && $caption !== '' && text_contains_url($caption)) {
            verify_content_type_allowed($db, $chat, $mem, $me, 'link', $cleanupChunkOnErr);
        } elseif ($encrypted === 1 && !empty($in['has_link'])) {
            verify_content_type_allowed($db, $chat, $mem, $me, 'link', $cleanupChunkOnErr);
        }

        ensure_data_dirs();
        $fileSha = @hash_file('sha256', $sourceTmpPath);
        if (!is_string($fileSha) || strlen($fileSha) !== 64) {
            $fileSha = null;
        }
        $storedName = '';
        $deduplicated = false;
        if ($encrypted !== 1 && $fileSha !== null) {
            $dupRow = $db->one("SELECT stored_name FROM files WHERE sha256 = ? AND encrypted = 0 LIMIT 1", array($fileSha));
            if ($dupRow && !empty($dupRow['stored_name'])) {
                $candSn = basename((string)$dupRow['stored_name']);
                if ($candSn !== '' && is_file(FILES_DIR . '/' . $candSn)) {
                    $storedName = $candSn;
                    $deduplicated = true;
                    if ($isChunkedFile && file_exists($sourceTmpPath)) {
                        @unlink($sourceTmpPath);
                    }
                }
            }
        }
        if (!$deduplicated) {
            $storedName = bin2hex(random_bytes_safe(20));
            $destPath = FILES_DIR . '/' . $storedName;
            $savedOk = $isChunkedFile ? @rename($sourceTmpPath, $destPath) : @move_uploaded_file($sourceTmpPath, $destPath);
            if (!$savedOk) {
                $cleanupChunkOnErr();
                api_err('upload_save_failed', 'Could not save uploaded file.');
            }
            @chmod($destPath, 0640);
        }

        $now = time();
        $db->exec(
            "INSERT INTO files (owner_id, chat_id, stored_name, sha256, display_name, mime, size, encrypted, file_iv, created_at)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            array($myId, $cid, $storedName, $fileSha, u_substr($origName, 0, 200), $mime, $fSize, $encrypted, $fileIv, $now)
        );
        $fileId = $db->lastId();

        // Also create message with explicit or default TTL (shortest non-zero duration wins across user/chat/admin)
        $upCustomTtl = isset($in['ttl']) ? (int)$in['ttl'] : -1;
        $upCustomTtlMode = isset($in['ttl_mode']) ? (string)$in['ttl_mode'] : '';
        $upResolvedTtl = resolve_effective_message_ttl($db, $chat, $me, $upCustomTtl, $upCustomTtlMode);
        $expiresAt = $upResolvedTtl['expires_at'];
        $burnAfter = $upResolvedTtl['burn_after'];
        $firstReadAt = $upResolvedTtl['first_read_at'];

        $bodyToStore = ($chat['type'] === 'secret') ? '' : u_substr($caption, 0, 2000);
        $spoilerFlag = (!empty($in['spoiler']) && $kind === 'file' && in_array($upContentType, array('photo', 'video'), true)) ? 1 : (!empty($in['spoiler']) && $encrypted === 1 ? 1 : 0);
        $msgCreatedAt = app_now($db);
        $db->exec(
            "INSERT INTO messages (chat_id, user_id, kind, body, cipher, iv, reply_to, file_id, created_at, expires_at, burn_after, first_read_at, pinned, spoiler)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 0, ?)",
            array($cid, $myId, $kind, $bodyToStore, $cipherCaption, $captionIv, $replyTo, $fileId, $msgCreatedAt, $expiresAt, $burnAfter, $firstReadAt, $spoilerFlag)
        );
        $msgId = $db->lastId();
        $senderFlags = get_user_flags($me);
        if (!empty($senderFlags['user_ghost_mode']) || empty($senderFlags['read_receipts'])) {
            $db->exec("UPDATE members SET last_read_id = ?, last_msg_at = ? WHERE chat_id = ? AND user_id = ?", array($msgId, $now, $cid, $myId));
        } else {
            $db->exec("UPDATE members SET last_read_id = ?, receipt_read_id = ?, last_msg_at = ? WHERE chat_id = ? AND user_id = ?", array($msgId, $msgId, $now, $cid, $myId));
        }
        rate_hit($db, 'msg_flood', (string)$myId, 10);
        bump_tick();

        $msgs = fetch_chat_messages($db, $chat, $mem, $me, $msgId - 1, 0, 5);
        $sentMsg = !empty($msgs) ? $msgs[count($msgs) - 1] : null;
        api_ok(array('file_id' => $fileId, 'deduplicated' => $deduplicated, 'message' => $sentMsg));
    }

    if ($do === 'search_global') {
        $q = isset($in['q']) ? trim((string)$in['q']) : '';
        if (u_strlen($q) < 2) {
            api_ok(array('users' => array(), 'chats' => array()));
        }
        $exactHandle = u_lower(ltrim($q, '@'));
        $likeHandle = '%' . escape_like_bang($exactHandle) . '%';
        $likeRaw    = '%' . escape_like_bang($q) . '%';

        $uRows = $db->all(
            "SELECT * FROM users WHERE status = 'active' AND (username = ? OR username LIKE ? ESCAPE '!' OR name LIKE ? ESCAPE '!') LIMIT 30",
            array($exactHandle, $likeHandle, $likeRaw)
        );
        $usersOut = array();
        foreach ($uRows as $u) {
            $fl = get_user_flags($u);
            // Complete unsearchability when hide_search=1 (even exact @username is hidden from regular users)
            if (!empty($fl['hide_search']) && !$isSuper) {
                continue;
            }
            // If user opted out of having a public @username, do not match via their private login ID
            if (!empty($fl['no_username']) && !$isSuper) {
                if (mb_stripos((string)$u['name'], $q, 0, 'UTF-8') === false) {
                    continue;
                }
            }
            $pub = format_user_public($u, $isSuper);
            $dmCheck = can_initiate_dm_with($db, $me, $u);
            $pub['can_dm'] = $dmCheck['ok'];
            $usersOut[] = $pub;
        }

        $cRows = $db->all(
            "SELECT id, type, handle, title, description, avatar, visibility, is_default FROM chats
             WHERE status = 'active' AND visibility = 'public' AND type IN ('group', 'channel')
               AND (handle = ? OR handle LIKE ? ESCAPE '!' OR title LIKE ? ESCAPE '!') LIMIT 25",
            array($exactHandle, $likeHandle, $likeRaw)
        );

        $nowSg = time();
        $mRowsRaw = $db->all(
            "SELECT m.id, m.chat_id, m.user_id, m.kind, m.body, m.hidden_for, m.created_at,
                    c.type AS chat_type, c.title AS chat_title, c.history AS chat_history,
                    mem.joined_msg_id,
                    mem.role AS my_role,
                    c.owner_id AS chat_owner_id,
                    COALESCE(mem.rejoin_msg_id, 0) AS rejoin_msg_id,
                    u.name AS author_name,
                    f.display_name AS file_name
             FROM messages m
             JOIN members mem ON mem.chat_id = m.chat_id AND mem.user_id = ? AND mem.role != 'pending'
             JOIN chats c ON c.id = m.chat_id
             LEFT JOIN users u ON u.id = m.user_id
             LEFT JOIN files f ON f.id = m.file_id
             WHERE c.status = 'active' AND c.type != 'secret'
               -- a chat this member removed from their own list must not resurface here
               AND COALESCE(mem.left_at, 0) = 0
               AND m.deleted_at IS NULL AND (m.expires_at IS NULL OR m.expires_at > ?)
               AND (m.visible_only_to IS NULL OR m.visible_only_to = ?)
               AND (m.body LIKE ? ESCAPE '!' OR f.display_name LIKE ? ESCAPE '!')
             ORDER BY m.id DESC " . $db->limit(25),
            array($myId, $nowSg, $myId, $likeRaw, $likeRaw)
        );
        $msgsOut = array();
        foreach ($mRowsRaw as $mr) {
            if (!$isSuper && $mr['chat_history'] === 'from_join' && (int)$mr['id'] < (int)$mr['joined_msg_id']) continue;
            // history before this member re-opened a 1:1 chat stays invisible to them
            if (!$isSuper && !empty($mr['rejoin_msg_id']) && (int)$mr['id'] < (int)$mr['rejoin_msg_id']) continue;
            if (is_hidden_for_user($mr['hidden_for'], $myId)) continue;
            // Global search must obey the same shadow cutoffs as the conversation
            // itself, otherwise a banned member reads the withheld text as a snippet.
            $sgMap = m3_chat_shadow_map($db, (int)$mr['chat_id']);
            if (!empty($sgMap)) {
                $sgRank = $isSuper ? 3
                    : ((!empty($mr['chat_owner_id']) && (int)$mr['chat_owner_id'] === $myId) ? 2
                    : (($mr['my_role'] === 'owner') ? 2 : (($mr['my_role'] === 'admin') ? 1 : 0)));
                $sgMyAt = isset($sgMap[$myId]) ? (int)$sgMap[$myId] : 0;
                if (m3_shadow_hides_row($mr, $myId, $sgRank, $sgMap, $sgMyAt)) continue;
            }
            $cTitleOut = (string)$mr['chat_title'];
            if ($mr['chat_type'] === 'dm') {
                $peerNameSg = $db->val(
                    "SELECT u.name FROM members pm JOIN users u ON u.id = pm.user_id WHERE pm.chat_id = ? AND pm.user_id != ? LIMIT 1",
                    array((int)$mr['chat_id'], $myId)
                );
                if ($peerNameSg) $cTitleOut = (string)$peerNameSg;
            } elseif ($mr['chat_type'] === 'system') {
                $cTitleOut = 'اعلان‌های پیام‌رسان';
            }
            $snippet = trim((string)$mr['body']);
            if ($snippet === '' && !empty($mr['file_name'])) $snippet = '📎 ' . (string)$mr['file_name'];
            $msgsOut[] = array(
                'id'          => (int)$mr['id'],
                'chat_id'     => (int)$mr['chat_id'],
                'chat_type'   => (string)$mr['chat_type'],
                'chat_title'  => $cTitleOut,
                'author_name' => (string)$mr['author_name'],
                'kind'        => (string)$mr['kind'],
                'body'        => u_substr($snippet, 0, 160),
                'created_at'  => (int)$mr['created_at']
            );
        }

        api_ok(array('users' => $usersOut, 'chats' => $cRows, 'messages' => $msgsOut));
    }

    if ($do === 'search_chat') {
        $cid = isset($in['chat_id']) ? (int)$in['chat_id'] : 0;
        $q = isset($in['q']) ? trim((string)$in['q']) : '';
        $chat = $db->one("SELECT * FROM chats WHERE id = ?", array($cid));
        $mem = get_active_member($db, $cid, $myId);
        if (!$chat || (!$mem && (!$isSuper || $chat['type'] === 'secret'))) {
            api_err('forbidden', 'Access denied.');
        }
        // Guards first: a chat this member removed from their own list is off-limits
        // for every query shape, including the empty-query shortcut below. Previously
        // the shortcut returned the whole history before these checks ran.
        $minMsgId = (!$isSuper && $chat['history'] === 'from_join' && $mem) ? (int)$mem['joined_msg_id'] : 0;
        if ($mem && !$isSuper && (int)(isset($mem['left_at']) ? $mem['left_at'] : 0) > 0) {
            api_err('forbidden', 'Access denied.');
        }
        if (!$isSuper && $mem && !empty($mem['rejoin_msg_id'])) {
            $minMsgId = max($minMsgId, (int)$mem['rejoin_msg_id']);
        }
        if ($q === '') {
            api_ok(array('messages' => fetch_chat_messages($db, $chat, $mem, $me, 0, 0, 60)));
        }
        $peerLastRead = peer_read_watermark($db, $chat, $myId);
        if ($chat['type'] === 'secret') {
            // Return encrypted messages so client can decrypt E2EE ciphertext in memory and filter locally
            $secRows = $db->all(
                "SELECT m.*, u.username, u.name AS author_name, u.avatar AS author_avatar, u.role AS author_role, u.show_admin_badge AS author_badge
                 FROM messages m
                 LEFT JOIN users u ON u.id = m.user_id
                 WHERE m.chat_id = ? AND m.id >= ? AND (m.visible_only_to IS NULL OR m.visible_only_to = ?)
                   AND m.deleted_at IS NULL AND (m.expires_at IS NULL OR m.expires_at > ?)
                 ORDER BY m.id DESC " . $db->limit(150),
                array($cid, $minMsgId, $myId, time())
            );
            $secRows = array_reverse($secRows);
            api_ok(array('messages' => hydrate_message_rows($db, $chat, $secRows, $myId, $minMsgId, $peerLastRead), 'client_e2ee_filter' => true));
        }
        $likeQ = '%' . escape_like_bang($q) . '%';
        $matchRows = $db->all(
            "SELECT m.*, u.username, u.name AS author_name, u.avatar AS author_avatar, u.role AS author_role, u.show_admin_badge AS author_badge
             FROM messages m
             LEFT JOIN users u ON u.id = m.user_id
             LEFT JOIN files f ON f.id = m.file_id
             WHERE m.chat_id = ? AND m.id >= ? AND (m.visible_only_to IS NULL OR m.visible_only_to = ?)
               AND m.deleted_at IS NULL AND (m.expires_at IS NULL OR m.expires_at > ?)
               AND (m.body LIKE ? ESCAPE '!' OR f.display_name LIKE ? ESCAPE '!')
             ORDER BY m.id ASC " . $db->limit(100),
            array($cid, $minMsgId, $myId, time(), $likeQ, $likeQ)
        );
        api_ok(array('messages' => hydrate_message_rows($db, $chat, $matchRows, $myId, $minMsgId, $peerLastRead)));
    }

    /* ---------------- REPORTING MODULE (WITH DESCRIPTION) ---------------- */
    if ($do === 'report_create') {
        if (!$isSuper && rate_get_attempts($db, 'report_flood', (string)$myId, 60) >= 8) {
            api_err('rate_limited', 'تعداد گزارش‌های ارسالی در دقیقه بیش از حد مجاز است. کمی صبر کنید. / Too many reports submitted. Please wait a minute.');
        }
        $targetType = isset($in['target_type']) ? trim((string)$in['target_type']) : '';
        $targetId   = isset($in['target_id']) ? (int)$in['target_id'] : 0;
        $reason     = isset($in['reason']) ? trim((string)$in['reason']) : 'other';
        $desc       = isset($in['description']) ? trim((string)$in['description']) : '';

        if (!in_array($targetType, array('user', 'group', 'channel', 'message'), true) || $targetId <= 0) {
            api_err('invalid_report_target', 'Invalid report target type or ID.');
        }
        if (u_strlen($desc) < 3) {
            api_err('description_required', 'Please provide a brief description explaining the report.');
        }
        if (u_strlen($desc) > 2000) {
            $desc = u_substr($desc, 0, 2000);
        }

        $db->exec(
            "INSERT INTO reports (reporter_id, target_type, target_id, reason, description, created_at, status)
             VALUES (?, ?, ?, ?, ?, ?, 'pending')",
            array($myId, $targetType, $targetId, u_substr($reason, 0, 64), $desc, time())
        );
        rate_hit($db, 'report_flood', (string)$myId, 60);
        api_ok(array('reported' => true));
    }

    /* ---------------- STANDALONE HYBRID LIVE VOICE & VIDEO CALLS / BROADCASTS ---------------- */
    if (in_array($do, array('call_start', 'call_join', 'call_decline', 'call_leave', 'call_end', 'call_state_update', 'call_speak_request', 'call_speak_decide', 'call_signal', 'call_media_push', 'call_poll'), true)) {
        cleanup_expired_live_calls($db);

        $clampTier = function($reqTier, $maxTier, $lockedTier, $isVideo = false) {
            if ($lockedTier !== null && $lockedTier !== '') return $lockedTier;
            $ranks = $isVideo
                ? array('low' => 1, 'medium' => 2, 'high' => 3, 'hd' => 4)
                : array('low' => 1, 'medium' => 2, 'high' => 3);
            $rev = array_flip($ranks);
            $maxR = isset($ranks[$maxTier]) ? $ranks[$maxTier] : ($isVideo ? 4 : 3);
            $req = strtolower(trim((string)$reqTier));
            if ($req === 'auto' || $req === '') return 'auto';
            if (!isset($ranks[$req])) return 'auto';
            $r = min($maxR, $ranks[$req]);
            return $rev[$r];
        };

        if ($do === 'call_start') {
            verify_and_record_traffic($db, $me, 0, true);
            $cid = isset($in['chat_id']) ? (int)$in['chat_id'] : 0;
            $callType = (isset($in['call_type']) && $in['call_type'] === 'video') ? 'video' : 'voice';
            $chat = $db->one("SELECT * FROM chats WHERE id = ?", array($cid));
            if (!$chat || $chat['type'] === 'saved') api_err('not_found', 'Chat does not support calls.');
            if ($chat['status'] !== 'active' && !$isSuper) api_err('chat_blocked', 'This chat is restricted.');
            $mem = get_active_member($db, $cid, $myId);
            if (!$mem && (!$isSuper || $chat['type'] === 'secret')) {
                api_err('forbidden', 'You are not an active member of this chat.');
            }
            if (($chat['type'] === 'dm' || $chat['type'] === 'secret') && !$isSuper) {
                $peerRow = $db->one("SELECT user_id FROM members WHERE chat_id = ? AND user_id != ? LIMIT 1", array($cid, $myId));
                if ($peerRow) {
                    $pid = (int)$peerRow['user_id'];
                    $blk = $db->val("SELECT 1 FROM blocks WHERE (user_id = ? AND blocked_id = ?) OR (user_id = ? AND blocked_id = ?)", array($pid, $myId, $myId, $pid));
                    if ($blk) api_err('user_blocked', 'Calls are unavailable due to block settings.');
                    $peerUserRow = $db->one("SELECT id, role, flags FROM users WHERE id = ?", array($pid));
                    if ($peerUserRow) {
                        $peerFl = get_user_flags($peerUserRow);
                        if (!empty($peerFl['deny_calls'])) {
                            api_err('calls_disabled_by_user', 'این کاربر دریافت تماس را در تنظیمات حریم خصوصی خود غیرفعال کرده است. / This user has disabled incoming calls in privacy settings.');
                        }
                    }
                }
            }
            $pol = resolve_effective_call_policy($db, $chat, $mem, $me);
            if (empty($pol['can_start'])) {
                api_err('calls_forbidden', 'شما مجوز شروع تماس یا پخش زنده در این گفتگو را ندارید. / You are not permitted to start a call here.');
            }
            if ($callType === 'video' && empty($pol['video_enabled'])) {
                api_err('video_calls_disabled', 'تماس تصویری غیرفعال است. / Video calls are disabled.');
            }
            if ($callType === 'voice' && empty($pol['voice_enabled'])) {
                api_err('voice_calls_disabled', 'تماس صوتی غیرفعال است. / Voice calls are disabled.');
            }

            // Reuse existing active call in chat if already live
            $existing = $db->one("SELECT * FROM active_calls WHERE chat_id = ? ORDER BY id DESC LIMIT 1", array($cid));
            $now = time();
            $audQ = $clampTier(isset($in['audio_quality']) ? $in['audio_quality'] : 'auto', $pol['audio_max_tier'], $pol['audio_locked_tier'], false);
            $vidQ = $clampTier(isset($in['video_quality']) ? $in['video_quality'] : 'auto', $pol['video_max_tier'], $pol['video_locked_tier'], true);
            $isGroupOrChan = ($chat['type'] === 'group' || $chat['type'] === 'channel');

            if ($existing) {
                $callId = (int)$existing['id'];
                $roleInCall = ((int)$existing['created_by'] === $myId) ? 'host' : (!empty($pol['can_broadcast']) ? 'speaker' : 'listener');
                $initMuted = ($isGroupOrChan || $roleInCall === 'listener') ? 1 : 0;
                $camInit = (!$isGroupOrChan && $callType === 'video' && !empty($pol['video_enabled']) && $roleInCall !== 'listener') ? 1 : 0;
                $db->exec("DELETE FROM call_participants WHERE call_id = ? AND user_id = ?", array($callId, $myId));
                $db->exec(
                    "INSERT INTO call_participants (call_id, user_id, role, state, muted, cam_on, on_hold, speak_req_state, audio_quality, video_quality, joined_at, last_seen_at)
                     VALUES (?, ?, ?, 'joined', ?, ?, 0, 'none', ?, ?, ?, ?)",
                    array($callId, $myId, $roleInCall, $initMuted, $camInit, $audQ, $vidQ, $now, $now)
                );
                if ($existing['status'] === 'ringing') {
                    $db->exec("UPDATE active_calls SET status = 'active', started_at = ?, updated_at = ? WHERE id = ?", array($now, $now, $callId));
                    if (!empty($existing['log_msg_id'])) {
                        update_chat_call_log_message($db, (int)$existing['log_msg_id'], array('status' => 'active', 'answered_at' => $now));
                    }
                }
                $roomSecret = (string)$existing['room_secret'];
            } else {
                // Item #7: In 2-way DMs / Secret chats, check if the target user is ALREADY joined in an active call elsewhere!
                $peerTargetId = 0;
                if ($chat['type'] === 'dm' || $chat['type'] === 'secret') {
                    $peerRowChk = $db->one("SELECT user_id FROM members WHERE chat_id = ? AND user_id != ? LIMIT 1", array($cid, $myId));
                    if ($peerRowChk) {
                        $peerTargetId = (int)$peerRowChk['user_id'];
                        $peerBusyInCall = $db->val(
                            "SELECT 1 FROM call_participants cp
                             JOIN active_calls ac ON ac.id = cp.call_id
                             WHERE cp.user_id = ? AND cp.state = 'joined' AND ac.chat_id != ?
                               AND cp.last_seen_at > ? LIMIT 1",
                            array($peerTargetId, $cid, $now - 20)
                        );
                        if ($peerBusyInCall) {
                            insert_chat_call_log_message($db, $chat, $me, $callType, 'busy', $now);
                            bump_tick();
                            api_err(
                                'callee_busy',
                                'کاربر مورد نظر هم‌اکنون در تماس دیگری مشغول است. / This user is currently busy on another call.'
                            );
                        }
                    }
                }

                $initStatus = ($chat['type'] === 'dm' || $chat['type'] === 'secret') ? 'ringing' : 'active';
                $startedAt = ($initStatus === 'active') ? $now : 0;
                $roomSecret = bin2hex(random_bytes_safe(24));
                $logMsgId = insert_chat_call_log_message($db, $chat, $me, $callType, $initStatus, $now);
                $db->exec(
                    "INSERT INTO active_calls (chat_id, created_by, call_type, status, audio_quality_policy, video_quality_policy, max_duration_sec, room_secret, log_msg_id, started_at, created_at, updated_at)
                     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                    array($cid, $myId, $callType, $initStatus, 'auto', 'auto', (int)$pol['max_duration_sec'], $roomSecret, $logMsgId, $startedAt, $now, $now)
                );
                $callId = $db->lastId();
                // In Groups/Channels, entrants always start as Listener/Visitor (mic & cam off) first, then enable mic/cam
                $initMutedHost = $isGroupOrChan ? 1 : 0;
                $camInit = (!$isGroupOrChan && $callType === 'video') ? 1 : 0;
                $db->exec(
                    "INSERT INTO call_participants (call_id, user_id, role, state, muted, cam_on, on_hold, speak_req_state, audio_quality, video_quality, joined_at, last_seen_at)
                     VALUES (?, ?, 'host', 'joined', ?, ?, 0, 'none', ?, ?, ?, ?)",
                    array($callId, $myId, $initMutedHost, $camInit, $audQ, $vidQ, $now, $now)
                );
                if (($chat['type'] === 'dm' || $chat['type'] === 'secret') && $peerTargetId > 0) {
                    $db->exec(
                        "INSERT INTO call_participants (call_id, user_id, role, state, muted, cam_on, on_hold, speak_req_state, audio_quality, video_quality, joined_at, last_seen_at)
                         VALUES (?, ?, 'speaker', 'ringing', 0, 0, 0, 'none', 'auto', 'auto', ?, ?)",
                        array($callId, $peerTargetId, $now, $now)
                    );
                    schedule_web_push_wakeup($db, array($peerTargetId), 'high');
                } else {
                    $callPushRows = $db->all(
                        "SELECT user_id FROM members WHERE chat_id = ? AND user_id != ? AND muted = 0 AND role != 'pending'",
                        array($cid, $myId)
                    );
                    $callPushUids = array();
                    foreach ($callPushRows as $cpr) $callPushUids[] = (int)$cpr['user_id'];
                    if (!empty($callPushUids)) {
                        schedule_web_push_wakeup($db, $callPushUids, 'high');
                    }
                }
            }
            bump_tick();
            $lastChunkSeq = (int)$db->val("SELECT COALESCE(MAX(id), 0) FROM call_chunks WHERE call_id = ?", array($callId));
            $lastSigId = (int)$db->val("SELECT COALESCE(MAX(id), 0) FROM call_signals WHERE call_id = ?", array($callId));
            $startSum = get_active_call_summary_for_chat($db, $cid, $myId);
            if ($startSum) {
                $startSum['room_secret'] = $roomSecret;
                $startSum['policy'] = $pol;
            }
            api_ok(array(
                'call'           => $startSum,
                'participants'   => $startSum ? $startSum['participants'] : array(),
                'room_secret'    => $roomSecret,
                'policy'         => $pol,
                'last_chunk_seq' => $lastChunkSeq,
                'last_sig_id'    => $lastSigId,
                'server_ts_ms'   => (int)round(microtime(true) * 1000)
            ));
        }

        $callId = isset($in['call_id']) ? (int)$in['call_id'] : 0;
        $callRow = $db->one("SELECT * FROM active_calls WHERE id = ?", array($callId));
        if (!$callRow) {
            if ($do === 'call_leave' || $do === 'call_decline' || $do === 'call_end') {
                api_ok(array('ended' => true));
            }
            if ($do === 'call_poll') {
                $endWhy = 'ended';
                $lastLogBody = $db->val(
                    "SELECT body FROM messages WHERE kind = 'call_log' AND user_id = ? AND created_at >= ? ORDER BY id DESC LIMIT 1",
                    array($myId, time() - 90)
                );
                if (is_string($lastLogBody) && $lastLogBody !== '') {
                    $ljEnd = json_decode($lastLogBody, true);
                    if (is_array($ljEnd) && isset($ljEnd['status'])) {
                        if ($ljEnd['status'] === 'busy') $endWhy = 'callee_busy';
                        elseif ($ljEnd['status'] === 'declined') $endWhy = 'declined';
                    }
                }
                api_ok(array('ended' => true, 'reason' => $endWhy, 'end_reason' => $endWhy, 'server_ts_ms' => (int)round(microtime(true) * 1000)));
            }
            api_err('call_not_found', 'تماس به پایان رسیده است. / Call has already ended.');
        }
        $cid = (int)$callRow['chat_id'];
        $chat = $db->one("SELECT * FROM chats WHERE id = ?", array($cid));
        $mem = get_active_member($db, $cid, $myId);
        if (!$chat || (!$mem && (!$isSuper || $chat['type'] === 'secret'))) {
            api_err('forbidden', 'Access to call denied.');
        }
        $pol = resolve_effective_call_policy($db, $chat, $mem, $me);

        if ($do === 'call_join') {
            verify_and_record_traffic($db, $me, 0, true);
            if (empty($pol['can_listen']) && empty($pol['can_broadcast'])) {
                api_err('calls_forbidden', 'شما مجوز پیوستن به این تماس را ندارید. / You are not allowed to join this call.');
            }
            $now = time();
            $isGroupOrChan = ($chat['type'] === 'group' || $chat['type'] === 'channel');
            $roleInCall = ((int)$callRow['created_by'] === $myId) ? 'host' : (!empty($pol['can_broadcast']) ? 'speaker' : 'listener');
            // In Groups & Channels, entrants always join initially as Visitor/Listener (mic & cam off)
            $initMuted = ($isGroupOrChan || $roleInCall === 'listener') ? 1 : 0;
            // The answer button the callee pressed is authoritative. The call may
            // have been *started* as video, but joining it without with_video must
            // never publish a camera - an audio answer stays an audio answer.
            $wantVideo = (!$isGroupOrChan && !empty($in['with_video']) && !empty($pol['video_enabled']) && $roleInCall !== 'listener') ? 1 : 0;
            $audQ = $clampTier(isset($in['audio_quality']) ? $in['audio_quality'] : 'auto', $pol['audio_max_tier'], $pol['audio_locked_tier'], false);
            $vidQ = $clampTier(isset($in['video_quality']) ? $in['video_quality'] : 'auto', $pol['video_max_tier'], $pol['video_locked_tier'], true);

            $db->exec("DELETE FROM call_participants WHERE call_id = ? AND user_id = ?", array($callId, $myId));
            $db->exec(
                "INSERT INTO call_participants (call_id, user_id, role, state, muted, cam_on, on_hold, speak_req_state, audio_quality, video_quality, joined_at, last_seen_at)
                 VALUES (?, ?, ?, 'joined', ?, ?, 0, 'none', ?, ?, ?, ?)",
                array($callId, $myId, $roleInCall, $initMuted, ($wantVideo ? 1 : 0), $audQ, $vidQ, $now, $now)
            );
            if ($callRow['status'] === 'ringing') {
                $effMax = (int)$callRow['max_duration_sec'];
                if ($pol['max_duration_sec'] > 0 && ($effMax === 0 || $pol['max_duration_sec'] < $effMax)) {
                    $effMax = (int)$pol['max_duration_sec'];
                }
                $db->exec("UPDATE active_calls SET status = 'active', started_at = ?, max_duration_sec = ?, updated_at = ? WHERE id = ?", array($now, $effMax, $now, $callId));
                if (!empty($callRow['log_msg_id'])) {
                    update_chat_call_log_message($db, (int)$callRow['log_msg_id'], array('status' => 'active', 'answered_at' => $now));
                }
            }
            // If this user had any OTHER incoming 1-on-1 calls ringing concurrently, terminate them as busy
            $otherRingRows = $db->all(
                "SELECT ac.id AS other_call_id, ac.created_by AS other_caller_id, c2.type AS other_chat_type
                 FROM call_participants cp2
                 JOIN active_calls ac ON ac.id = cp2.call_id
                 JOIN chats c2 ON c2.id = ac.chat_id
                 WHERE cp2.user_id = ? AND cp2.call_id != ? AND cp2.state = 'ringing' AND ac.status = 'ringing'",
                array($myId, $callId)
            );
            foreach ($otherRingRows as $orr) {
                $ocId = (int)$orr['other_call_id'];
                if ($orr['other_chat_type'] === 'dm' || $orr['other_chat_type'] === 'secret') {
                    wipe_call_ephemeral_records($db, $ocId, 'busy');
                }
            }
            bump_tick();
            $lastChunkSeq = (int)$db->val("SELECT COALESCE(MAX(id), 0) FROM call_chunks WHERE call_id = ?", array($callId));
            $lastSigId = (int)$db->val("SELECT COALESCE(MAX(id), 0) FROM call_signals WHERE call_id = ?", array($callId));
            $joinSum = get_active_call_summary_for_chat($db, $cid, $myId);
            if ($joinSum) {
                $joinSum['room_secret'] = (string)$callRow['room_secret'];
                $joinSum['policy'] = $pol;
            }
            api_ok(array(
                'call'           => $joinSum,
                'participants'   => $joinSum ? $joinSum['participants'] : array(),
                'room_secret'    => (string)$callRow['room_secret'],
                'my_call_role'   => $roleInCall,
                'policy'         => $pol,
                'last_chunk_seq' => $lastChunkSeq,
                'last_sig_id'    => $lastSigId,
                'server_ts_ms'   => (int)round(microtime(true) * 1000)
            ));
        }

        if ($do === 'call_decline' || $do === 'call_leave') {
            $nowLeave = time();
            $wasStarter = ((int)$callRow['created_by'] === $myId);
            $starterTier = ($wasStarter && ($chat['type'] === 'group' || $chat['type'] === 'channel'))
                ? get_call_access_tier_for_handover($db, $chat, $myId)
                : 'none';

            $db->exec("DELETE FROM call_participants WHERE call_id = ? AND user_id = ?", array($callId, $myId));
            $remJoinedRows = $db->all(
                "SELECT cp.user_id, cp.role, cp.joined_at, u.name
                 FROM call_participants cp
                 JOIN users u ON u.id = cp.user_id
                 WHERE cp.call_id = ? AND cp.state = 'joined' AND cp.last_seen_at > ?
                 ORDER BY cp.joined_at ASC, cp.user_id ASC",
                array($callId, $nowLeave - 25)
            );
            $remJoined = count($remJoinedRows);

            if ($chat['type'] === 'dm' || $chat['type'] === 'secret' || $remJoined === 0) {
                $reasonEnd = ($do === 'call_decline' && $callRow['status'] === 'ringing') ? 'declined' : 'ended';
                wipe_call_ephemeral_records($db, $callId, $reasonEnd);
                bump_tick();
                api_ok(array('ended' => true, 'room_closed' => true));
            }

            // Item #19: In Groups & Channels, if the starter leaves, transfer call management to the oldest
            // joined participant with the SAME access level; if none exists, end the call for everyone!
            if ($wasStarter && ($chat['type'] === 'group' || $chat['type'] === 'channel')) {
                $nextHost = null;
                foreach ($remJoinedRows as $candRow) {
                    $candUid = (int)$candRow['user_id'];
                    $candTier = get_call_access_tier_for_handover($db, $chat, $candUid);
                    if ($candTier !== 'none' && $candTier === $starterTier) {
                        $nextHost = $candRow;
                        break;
                    }
                }
                if ($nextHost) {
                    $newHostUid = (int)$nextHost['user_id'];
                    $newHostName = (string)$nextHost['name'];
                    $db->exec("UPDATE active_calls SET created_by = ?, updated_at = ? WHERE id = ?", array($newHostUid, $nowLeave, $callId));
                    $db->exec("UPDATE call_participants SET role = 'host' WHERE call_id = ? AND user_id = ?", array($callId, $newHostUid));
                    $db->exec(
                        "INSERT INTO call_signals (call_id, from_user_id, to_user_id, sig_type, payload, created_at) VALUES (?, ?, 0, 'host_changed', ?, ?)",
                        array($callId, $myId, json_encode(array('new_host_id' => $newHostUid, 'new_host_name' => $newHostName), JSON_UNESCAPED_UNICODE), $nowLeave)
                    );
                    bump_tick();
                    api_ok(array('ended' => true, 'room_closed' => false, 'new_host_id' => $newHostUid));
                } else {
                    wipe_call_ephemeral_records($db, $callId, 'ended');
                    bump_tick();
                    api_ok(array('ended' => true, 'room_closed' => true));
                }
            }

            bump_tick();
            api_ok(array('ended' => true, 'room_closed' => false));
        }

        if ($do === 'call_end') {
            $canEndAll = $isSuper
                || ((int)$callRow['created_by'] === $myId)
                || ($chat['type'] === 'dm' || $chat['type'] === 'secret')
                || has_admin_perm($chat, $mem, $me, 'manage_calls');
            if (!$canEndAll) {
                api_err('forbidden', 'Only call hosts or authorized chat admins can end the live call for everyone.');
            }
            wipe_call_ephemeral_records($db, $callId, 'ended');
            bump_tick();
            api_ok(array('ended' => true, 'room_closed' => true));
        }

        $myPart = $db->one("SELECT * FROM call_participants WHERE call_id = ? AND user_id = ? AND state = 'joined'", array($callId, $myId));
        if (!$myPart) {
            api_err('not_in_call', 'You are not currently joined to this call.');
        }

        if ($do === 'call_speak_request') {
            if ($chat['type'] === 'channel' && !$isSuper && !is_chat_admin_or_owner($chat, $mem, $me)) {
                api_err('channel_visitor_only', 'اعضای عادی کانال فقط بازدیدکننده و شنونده هستند و امکان مشارکت ندارند. / Channel members are strictly listeners and cannot participate.');
            }
            $cancelReq = !empty($in['cancel']);
            $nextState = $cancelReq ? 'none' : 'requested';
            $now = time();
            $db->exec(
                "UPDATE call_participants SET speak_req_state = ?, last_seen_at = ? WHERE call_id = ? AND user_id = ?",
                array($nextState, $now, $callId, $myId)
            );
            bump_tick();
            $sumReq = get_active_call_summary_for_chat($db, $cid, $myId);
            api_ok(array(
                'speak_req'       => $cancelReq ? 0 : 1,
                'speak_req_state' => $nextState,
                'call'            => $sumReq,
                'participants'    => $sumReq ? $sumReq['participants'] : array()
            ));
        }

        if ($do === 'call_speak_decide') {
            $canDecide = $isSuper || ((int)$callRow['created_by'] === $myId) || !empty($pol['can_manage_speak']);
            if (!$canDecide) {
                api_err('forbidden', 'You do not have permission to approve or revoke call participation.');
            }
            $targetUid = isset($in['target_user_id']) ? (int)$in['target_user_id'] : (isset($in['user_id']) ? (int)$in['user_id'] : 0);
            $decision = isset($in['decision']) ? strtolower(trim((string)$in['decision'])) : 'approve';
            if ($targetUid <= 0) {
                api_err('invalid_target', 'Valid participant user ID required.');
            }
            if ((int)$chat['owner_id'] === $targetUid && $decision !== 'approve' && !$isSuper) {
                api_err('forbidden', 'Cannot revoke call speaking rights of the chat owner.');
            }
            $tUserRow = $db->one("SELECT id, role FROM users WHERE id = ?", array($targetUid));
            if ($tUserRow && $tUserRow['role'] === 'superadmin' && $decision !== 'approve') {
                api_err('forbidden', 'Cannot revoke call speaking rights of Super-Admin.');
            }
            if ($chat['type'] === 'channel' && $decision === 'approve') {
                $tMemRow = get_active_member($db, $cid, $targetUid);
                if (!($tUserRow && $tUserRow['role'] === 'superadmin') && !is_chat_admin_or_owner($chat, $tMemRow, $tUserRow)) {
                    api_err('channel_visitor_only', 'Regular channel members cannot be granted speaker rights.');
                }
            }
            if ($decision === 'approve') {
                $db->exec(
                    "UPDATE call_participants SET role = 'speaker', speak_req_state = 'approved' WHERE call_id = ? AND user_id = ?",
                    array($callId, $targetUid)
                );
            } else {
                $db->exec(
                    "UPDATE call_participants SET role = 'listener', speak_req_state = 'revoked', muted = 1, cam_on = 0 WHERE call_id = ? AND user_id = ?",
                    array($callId, $targetUid)
                );
            }
            bump_tick();
            $sumDec = get_active_call_summary_for_chat($db, $cid, $myId);
            api_ok(array(
                'updated'      => true,
                'decision'     => $decision,
                'call'         => $sumDec,
                'participants' => $sumDec ? $sumDec['participants'] : array()
            ));
        }

        if ($do === 'call_state_update') {
            $isListener = ($myPart['role'] === 'listener');
            $muted = array_key_exists('muted', $in) ? ((int)$in['muted'] ? 1 : 0) : (int)$myPart['muted'];
            if ($isListener) $muted = 1;
            $camOn = array_key_exists('cam_on', $in) ? ((int)$in['cam_on'] ? 1 : 0) : (int)$myPart['cam_on'];
            if ($isListener || empty($pol['video_enabled'])) $camOn = 0;
            $onHold = array_key_exists('on_hold', $in) ? ((int)$in['on_hold'] ? 1 : 0) : (int)$myPart['on_hold'];
            $audQ = array_key_exists('audio_quality', $in)
                ? $clampTier($in['audio_quality'], $pol['audio_max_tier'], $pol['audio_locked_tier'], false)
                : (string)$myPart['audio_quality'];
            $vidQ = array_key_exists('video_quality', $in)
                ? $clampTier($in['video_quality'], $pol['video_max_tier'], $pol['video_locked_tier'], true)
                : (string)$myPart['video_quality'];

            $now = time();
            $db->exec(
                "UPDATE call_participants SET muted = ?, cam_on = ?, on_hold = ?, audio_quality = ?, video_quality = ?, last_seen_at = ? WHERE call_id = ? AND user_id = ?",
                array($muted, $camOn, $onHold, $audQ, $vidQ, $now, $callId, $myId)
            );
            if ($isSuper && (array_key_exists('room_audio_quality', $in) || array_key_exists('room_video_quality', $in))) {
                $nextRoomAud = isset($in['room_audio_quality']) ? strtolower(trim((string)$in['room_audio_quality'])) : (isset($callRow['audio_quality_policy']) ? (string)$callRow['audio_quality_policy'] : 'auto');
                if (!in_array($nextRoomAud, array('auto', 'low', 'medium', 'high'), true)) $nextRoomAud = 'auto';
                $nextRoomVid = isset($in['room_video_quality']) ? strtolower(trim((string)$in['room_video_quality'])) : (isset($callRow['video_quality_policy']) ? (string)$callRow['video_quality_policy'] : 'auto');
                if (!in_array($nextRoomVid, array('auto', 'low', 'medium', 'high', 'hd'), true)) $nextRoomVid = 'auto';
                $db->exec(
                    "UPDATE active_calls SET audio_quality_policy = ?, video_quality_policy = ?, updated_at = ? WHERE id = ?",
                    array($nextRoomAud, $nextRoomVid, $now, $callId)
                );
                $db->exec(
                    "UPDATE call_participants SET audio_quality = ?, video_quality = ? WHERE call_id = ?",
                    array($nextRoomAud, $nextRoomVid, $callId)
                );
                $qSigPayload = json_encode(array(
                    'room_audio_quality' => $nextRoomAud,
                    'room_video_quality' => $nextRoomVid,
                    'audio_quality'      => $nextRoomAud,
                    'video_quality'      => $nextRoomVid,
                    'updated_by'         => $myId,
                    'ts'                 => $now
                ), JSON_UNESCAPED_UNICODE);
                $db->exec(
                    "INSERT INTO call_signals (call_id, from_user_id, to_user_id, sig_type, payload, created_at) VALUES (?, ?, 0, 'quality_changed', ?, ?)",
                    array($callId, $myId, $qSigPayload, $now)
                );
            }
            if ($camOn && $callRow['call_type'] === 'voice') {
                $db->exec("UPDATE active_calls SET call_type = 'video', updated_at = ? WHERE id = ?", array($now, $callId));
            }
            bump_tick();
            $sumAfterUpd = get_active_call_summary_for_chat($db, $cid, $myId);
            if ($sumAfterUpd) {
                $sumAfterUpd['room_secret'] = (string)$callRow['room_secret'];
                $sumAfterUpd['policy'] = $pol;
            }
            api_ok(array(
                'call'               => $sumAfterUpd,
                'room_audio_quality' => $sumAfterUpd ? $sumAfterUpd['room_audio_quality'] : 'auto',
                'room_video_quality' => $sumAfterUpd ? $sumAfterUpd['room_video_quality'] : 'auto',
                'policy'             => $pol,
                'server_ts_ms'       => (int)round(microtime(true) * 1000)
            ));
        }

        if ($do === 'call_signal') {
            $toUid = isset($in['to_user_id']) ? (int)$in['to_user_id'] : 0;
            $sigType = isset($in['sig_type']) ? trim((string)$in['sig_type']) : '';
            $sigPayload = isset($in['payload']) ? (is_string($in['payload']) ? $in['payload'] : json_encode($in['payload'], JSON_UNESCAPED_UNICODE)) : '';
            if (!in_array($sigType, array('offer', 'answer', 'ice', 'bye', 'renegotiate'), true) || $sigPayload === '' || strlen($sigPayload) > 65536) {
                api_err('invalid_signal', 'Invalid WebRTC signaling payload.');
            }
            $now = time();
            $db->exec("UPDATE call_participants SET last_seen_at = ? WHERE call_id = ? AND user_id = ?", array($now, $callId, $myId));
            $db->exec(
                "INSERT INTO call_signals (call_id, from_user_id, to_user_id, sig_type, payload, created_at) VALUES (?, ?, ?, ?, ?, ?)",
                array($callId, $myId, $toUid, $sigType, $sigPayload, $now)
            );
            api_ok(array('sig_id' => $db->lastId(), 'server_ts_ms' => (int)round(microtime(true) * 1000)));
        }

        if ($do === 'call_media_push') {
            if ($myPart['role'] === 'listener' || !empty($myPart['on_hold'])) {
                api_err('cannot_publish', 'Listeners or participants on hold cannot publish media chunks.');
            }
            $mKind = isset($in['media_kind']) && in_array($in['media_kind'], array('audio', 'video', 'av'), true) ? $in['media_kind'] : 'audio';
            if (($mKind === 'video' || $mKind === 'av') && empty($pol['video_enabled'])) {
                api_err('video_calls_disabled', 'Video transmission is restricted.');
            }
            $chunkPayload = isset($in['payload']) ? (string)$in['payload'] : '';
            if ($chunkPayload === '' || strlen($chunkPayload) > 950000) {
                api_err('invalid_chunk', 'Media packet size out of bounds.');
            }
            verify_and_record_traffic($db, $me, strlen($chunkPayload), true);
            $now = time();
            $db->exec("UPDATE call_participants SET last_seen_at = ? WHERE call_id = ? AND user_id = ?", array($now, $callId, $myId));
            $db->exec(
                "INSERT INTO call_chunks (call_id, user_id, media_kind, payload, created_at) VALUES (?, ?, ?, ?, ?)",
                array($callId, $myId, $mKind, $chunkPayload, $now)
            );
            $seq = $db->lastId();
            if (($seq % 8) === 0) {
                $db->exec("DELETE FROM call_chunks WHERE call_id = ? AND (created_at <= ? OR id < ?)", array($callId, $now - 8, max(0, $seq - 64)));
            }
            api_ok(array('seq' => $seq, 'server_ts_ms' => (int)round(microtime(true) * 1000)));
        }

        if ($do === 'call_poll') {
            $now = time();
            $maxDur = (int)$callRow['max_duration_sec'];
            if ($maxDur > 0 && (int)$callRow['started_at'] > 0 && ($now - (int)$callRow['started_at']) >= $maxDur) {
                wipe_call_ephemeral_records($db, $callId);
                bump_tick();
                api_ok(array('ended' => true, 'reason' => 'duration_limit', 'end_reason' => 'duration_cap', 'server_ts_ms' => (int)round(microtime(true) * 1000)));
            }
            if (!$isSuper) {
                $sysTrPoll = sync_and_get_system_traffic_status($db);
                $usrTrPoll = sync_and_get_user_traffic_status($db, $me);
                if (!empty($sysTrPoll['exceeded']) || !empty($usrTrPoll['exceeded'])) {
                    $db->exec("DELETE FROM call_participants WHERE call_id = ? AND user_id = ?", array($callId, $myId));
                    $remJ = (int)$db->val("SELECT COUNT(*) FROM call_participants WHERE call_id = ? AND state = 'joined'", array($callId));
                    if ($chat['type'] === 'dm' || $chat['type'] === 'secret' || $remJ === 0) {
                        wipe_call_ephemeral_records($db, $callId);
                    }
                    bump_tick();
                    api_ok(array('ended' => true, 'reason' => 'traffic_exceeded', 'end_reason' => 'traffic_exceeded', 'server_ts_ms' => (int)round(microtime(true) * 1000)));
                }
            }
            $db->exec("UPDATE call_participants SET last_seen_at = ? WHERE call_id = ? AND user_id = ?", array($now, $callId, $myId));
            $afterSig = isset($in['after_sig_id']) ? (int)$in['after_sig_id'] : 0;
            $afterSeq = isset($in['after_chunk_seq']) ? (int)$in['after_chunk_seq'] : 0;

            $sigs = $db->all(
                "SELECT id, from_user_id, to_user_id, sig_type, payload, created_at
                 FROM call_signals
                 WHERE call_id = ? AND id > ? AND from_user_id != ? AND (to_user_id = 0 OR to_user_id = ?)
                 ORDER BY id ASC " . $db->limit(40),
                array($callId, $afterSig, $myId, $myId)
            );
            foreach ($sigs as &$sg) {
                $sg['id'] = (int)$sg['id'];
                $sg['from_user_id'] = (int)$sg['from_user_id'];
                $sg['to_user_id'] = (int)$sg['to_user_id'];
            }

            $chunks = array();
            $rxChunkBytes = 0;
            if (empty($myPart['on_hold'])) {
                $cRows = $db->all(
                    "SELECT cc.id, cc.user_id, cc.media_kind, cc.payload, cc.created_at
                     FROM call_chunks cc
                     JOIN call_participants cp ON cp.call_id = cc.call_id AND cp.user_id = cc.user_id
                     WHERE cc.call_id = ? AND cc.id > ? AND cc.user_id != ? AND cp.on_hold = 0
                     ORDER BY cc.id ASC " . $db->limit(36),
                    array($callId, $afterSeq, $myId)
                );
                foreach ($cRows as $cr) {
                    $pl = (string)$cr['payload'];
                    $rxChunkBytes += strlen($pl);
                    $chunks[] = array(
                        'seq'          => (int)$cr['id'],
                        'user_id'      => (int)$cr['user_id'],
                        'from_user_id' => (int)$cr['user_id'],
                        'media_kind'   => (string)$cr['media_kind'],
                        'payload'      => $pl
                    );
                }
            }
            if ($rxChunkBytes > 0) {
                verify_and_record_traffic($db, $me, $rxChunkBytes, false);
            }
            $summary = get_active_call_summary_for_chat($db, $cid, $myId);
            if (!$summary) {
                api_ok(array('ended' => true, 'reason' => 'ended', 'end_reason' => 'ended', 'server_ts_ms' => (int)round(microtime(true) * 1000)));
            }
            $polFresh = resolve_effective_call_policy($db, $chat, $mem, $me);
            $myFreshPart = null;
            foreach ($summary['participants'] as $spItem) {
                if ((int)$spItem['user_id'] === $myId) { $myFreshPart = $spItem; break; }
            }
            if ($myFreshPart) {
                $polFresh['can_publish'] = !empty($myFreshPart['can_publish']) ? 1 : 0;
                $polFresh['speak_req_state'] = isset($myFreshPart['speak_req_state']) ? $myFreshPart['speak_req_state'] : 'none';
            }
            $summary['room_secret'] = (string)$callRow['room_secret'];
            $summary['policy'] = $polFresh;
            $canManagePoll = ($isSuper || ((int)$callRow['created_by'] === $myId) || !empty($polFresh['can_manage_speak']) || has_admin_perm($chat, $mem, $me, 'manage_calls')) ? 1 : 0;
            api_ok(array(
                'ended'            => false,
                'call'             => $summary,
                'participants'     => $summary['participants'],
                'policy'           => $polFresh,
                'can_manage_calls' => $canManagePoll,
                'signals'          => $sigs,
                'chunks'           => $chunks,
                'server_ts_ms'     => (int)round(microtime(true) * 1000)
            ));
        }
    }

    /* ---------------- LONG POLLING WITH TICK-FILE WAKEUP ---------------- */
    if ($do === 'poll') {
        $clientTick = isset($in['since_tick']) ? trim((string)$in['since_tick']) : '0';
        $activeChatId = isset($in['chat_id']) ? (int)$in['chat_id'] : 0;
        $sinceMsgId = isset($in['since_id']) ? (int)$in['since_id'] : 0;
        $noWait = !empty($in['nowrap']);

        $maxWait = $noWait ? 0 : min(10, max(1, (int)Settings::get($db, 'poll_timeout', 6)));
        $start = microtime(true);
        if (function_exists('session_write_close')) @session_write_close();

        $curTick = get_tick();
        while (!$noWait && $curTick === $clientTick && (microtime(true) - $start) < $maxWait) {
            usleep(350000); // 350ms sleep
            $curTick = get_tick();
        }

        $newMessages = array();
        $peerLastRead = 0;
        $typingUsers = array();

        if ($activeChatId > 0) {
            $chat = $db->one("SELECT * FROM chats WHERE id = ?", array($activeChatId));
            $mem = get_active_member($db, $activeChatId, $myId);
            if ($chat && ($mem || ($isSuper && $chat['type'] !== 'secret'))) {
                $newMessages = fetch_chat_messages($db, $chat, $mem, $me, $sinceMsgId, 0, 50);
                // Also sync any live location messages in active chat so live coordinate & timestamp updates arrive instantly
                $locRowsSync = $db->all(
                    "SELECT id FROM messages WHERE chat_id = ? AND kind = 'location' AND deleted_at IS NULL AND id <= ? ORDER BY id DESC " . $db->limit(10),
                    array($activeChatId, max(0, $sinceMsgId))
                );
                if (!empty($locRowsSync)) {
                    $seenNewIds = array();
                    foreach ($newMessages as $nmItem) $seenNewIds[(int)$nmItem['id']] = true;
                    foreach ($locRowsSync as $lrSync) {
                        $lid = (int)$lrSync['id'];
                        if (!isset($seenNewIds[$lid])) {
                            $fLoc = fetch_chat_messages($db, $chat, $mem, $me, $lid - 1, $lid + 1, 3);
                            foreach ($fLoc as $flItem) {
                                if ((int)$flItem['id'] === $lid) {
                                    $newMessages[] = $flItem;
                                    $seenNewIds[$lid] = true;
                                }
                            }
                        }
                    }
                }
                $peerLastRead = peer_read_watermark($db, $chat, $myId);
                $tRows = $db->all("SELECT v FROM meta WHERE k LIKE ?", array("typing_{$activeChatId}_%"));
                $now = time();
                foreach ($tRows as $tr) {
                    $td = json_decode((string)$tr['v'], true);
                    if (is_array($td) && (int)$td['user_id'] !== $myId && ($now - (int)$td['ts']) <= 6) {
                        $typingUsers[] = $td['name'];
                    }
                }
            }
        }

        api_ok(array(
            'tick'              => $curTick,
            'chats'             => fetch_user_chats($db, $me),
            'messages'          => $newMessages,
            'peer_last_read_id' => $peerLastRead,
            'typing'            => $typingUsers,
            'messenger_now'     => app_now($db),
            'autonomous_mode'   => (int)Settings::get($db, 'autonomous_mode', 0) ? 1 : 0
        ));
    }

    /* ---------------- GLOBAL SUPER-ADMIN PANEL API ----------------
       Scoped to the admin_* namespace so that an unknown action keeps falling
       through to the terminal unknown_action error (400) instead of being
       reported as forbidden (403). Still fail-closed: anything named admin_*
       requires a super-admin before any of its code runs. */
    if (strpos($do, 'admin_') === 0) {
        require_superadmin($db);
    }
    // Founder-only tier: appointed super-admins are peers and never get here.
    if (in_array($do, founder_only_actions(), true)) {
        require_founder($db);
    }

    if ($do === 'admin_dashboard') {
        $nowDash = time();
        $todayStart = strtotime('today midnight');
        $totalUsers = (int)$db->val("SELECT COUNT(*) FROM users WHERE status != 'deleted'");
        $onlineUsersCount = count_online_users_now($db, $nowDash);
        $totalChats = (int)$db->val("SELECT COUNT(*) FROM chats");
        $msgsToday  = (int)$db->val("SELECT COUNT(*) FROM messages WHERE created_at >= ?", array($todayStart));
        $totalMsgs  = (int)$db->val("SELECT COUNT(*) FROM messages");
        $pendingReports = (int)$db->val("SELECT COUNT(*) FROM reports WHERE status = 'pending'");
        $filesBytes = (int)$db->val("SELECT COALESCE(SUM(max_sz), 0) FROM (SELECT MAX(size) AS max_sz FROM files GROUP BY stored_name) AS u_blobs");
        $filesCount = (int)$db->val("SELECT COUNT(*) FROM files");
        $dbBytes = 0;
        $sqPath = $db->sqlitePath();
        if ($db->driver() === 'sqlite' && $sqPath !== '' && file_exists($sqPath)) {
            $dbBytes = (int)filesize($sqPath);
        }
        $sysTrafficDash = sync_and_get_system_traffic_status($db);
        api_ok(array(
            'users'              => $totalUsers,
            'users_count'        => $totalUsers,
            'online_users'       => $onlineUsersCount,
            'online_users_count' => $onlineUsersCount,
            'firewall_stats'     => fw_get_stats($db),
            'chats'              => $totalChats,
            'chats_count'      => $totalChats,
            'messages_today'   => $msgsToday,
            'messages_total'   => $totalMsgs,
            'pending_reports'  => $pendingReports,
            'disk_usage_bytes'       => $filesBytes,
            'files_count'            => $filesCount,
            'max_total_storage_mb'   => (float)Settings::get($db, 'max_total_storage_mb', 0),
            'max_user_storage_mb'    => (float)Settings::get($db, 'max_user_storage_mb', 0),
            'system_traffic'         => $sysTrafficDash,
            'file_auto_delete_hours' => (float)Settings::get($db, 'file_auto_delete_hours', 0),
            'messenger_delete_at'    => (int)Settings::get($db, 'messenger_delete_at', 0),
            'storage_bytes'    => $filesBytes,
            'db_size_bytes'    => $dbBytes,
            'db_bytes'         => $dbBytes,
            'php_version'      => PHP_VERSION,
            'db_driver'        => $db->driver()
        ));
    }

    if ($do === 'admin_settings_get') {
        $sysTrafficNow = sync_and_get_system_traffic_status($db);
        $allS = Settings::all($db, true);
        $hasPanicDuress = (!empty($allS['panic_duress_pass_hash'])) ? 1 : 0;
        unset($allS['panic_duress_pass_hash'], $allS['vapid_private_pem']);
        $allS['has_panic_duress_password'] = $hasPanicDuress;
        $rList = content_restrictions_to_list(isset($allS['restricted_content_types']) ? $allS['restricted_content_types'] : array());
        $allS['restricted_content_types'] = $rList;
        $allS['global_restricted_content_types'] = $rList;
        $allS['calls_audio_policy'] = quality_policy_code_to_ui(isset($allS['calls_audio_quality_policy']) ? $allS['calls_audio_quality_policy'] : 'free');
        $allS['calls_video_policy'] = quality_policy_code_to_ui(isset($allS['calls_video_quality_policy']) ? $allS['calls_video_quality_policy'] : 'free');
        $allS['calls_max_duration_sec'] = max(0, (int)(isset($allS['calls_max_duration_min']) ? $allS['calls_max_duration_min'] : 0)) * 60;
        $allS['system_traffic_limit_mb'] = isset($allS['sys_traffic_limit_mb']) ? (float)$allS['sys_traffic_limit_mb'] : 0;
        $allS['system_traffic_period_days'] = isset($allS['sys_traffic_period_days']) ? (float)$allS['sys_traffic_period_days'] : 0;
        $allS['default_user_traffic_mb'] = isset($allS['user_traffic_limit_mb']) ? (float)$allS['user_traffic_limit_mb'] : 0;
        $allS['default_user_traffic_limit_mb'] = $allS['default_user_traffic_mb'];
        $allS['default_user_traffic_period_days'] = isset($allS['user_traffic_period_days']) ? (float)$allS['user_traffic_period_days'] : 30;
        $allS['system_traffic'] = $sysTrafficNow;
        $allS['server_now'] = time();
        $allS = array_merge($allS, get_identity_length_limits($db));
        $allS['messenger_now'] = app_now($db);
        api_ok(array('settings' => $allS));
    }

    if ($do === 'admin_system_traffic_reset') {
        $nowReset = time();
        Settings::set($db, 'sys_traffic_used_bytes', 0);
        Settings::set($db, 'sys_traffic_period_start', $nowReset);
        log_admin_audit($db, $myId, 'system_traffic_reset', array());
        bump_tick();
        api_ok(array('reset' => true, 'system_traffic' => sync_and_get_system_traffic_status($db)));
    }

    if ($do === 'admin_user_traffic_reset') {
        $uid = isset($in['user_id']) ? (int)$in['user_id'] : 0;
        $uTarget = $db->one("SELECT id, role, is_founder FROM users WHERE id = ?", array($uid));
        if (!$uTarget) api_err('not_found', 'User not found.');
        guard_superadmin_target($db, $auth, $uTarget);
        $nowReset = time();
        $db->exec("UPDATE users SET traffic_used_bytes = 0, traffic_period_start = ? WHERE id = ?", array($nowReset, $uid));
        log_admin_audit($db, $myId, 'user_traffic_reset', array('user_id' => $uid));
        bump_tick();
        api_ok(array('reset' => true));
    }

    if ($do === 'admin_analytics') {
        $nowA = app_now($db);
        $realNow = time();
        $rangeKey = isset($in['range']) ? strtolower(trim((string)$in['range'])) : '7d';
        $allowedRanges = array('1h', '24h', '7d', '30d', '90d', '180d', '1y', 'all', 'custom');
        if (!in_array($rangeKey, $allowedRanges, true)) $rangeKey = '7d';

        $toTs = $nowA;
        $fromTs = $nowA - (7 * 86400);
        $bucketCount = 7;

        if ($rangeKey === '1h') { $fromTs = $nowA - 3600; $bucketCount = 12; }
        elseif ($rangeKey === '24h') { $fromTs = $nowA - 86400; $bucketCount = 24; }
        elseif ($rangeKey === '7d') { $fromTs = $nowA - (7 * 86400); $bucketCount = 7; }
        elseif ($rangeKey === '30d') { $fromTs = $nowA - (30 * 86400); $bucketCount = 15; }
        elseif ($rangeKey === '90d') { $fromTs = $nowA - (90 * 86400); $bucketCount = 15; }
        elseif ($rangeKey === '180d') { $fromTs = $nowA - (180 * 86400); $bucketCount = 12; }
        elseif ($rangeKey === '1y') { $fromTs = $nowA - (365 * 86400); $bucketCount = 12; }
        elseif ($rangeKey === 'all') {
            $minU = (int)$db->val("SELECT COALESCE(MIN(created_at), 0) FROM users WHERE created_at > 0");
            $minM = (int)$db->val("SELECT COALESCE(MIN(created_at), 0) FROM messages WHERE created_at > 0");
            $cands = array_filter(array($minU, $minM));
            $earliest = !empty($cands) ? min($cands) : ($nowA - 86400);
            $fromTs = min($earliest, $nowA - 3600);
            $bucketCount = 12;
        } elseif ($rangeKey === 'custom') {
            $reqFrom = isset($in['from_ts']) ? (int)$in['from_ts'] : ($nowA - 7 * 86400);
            $reqTo = isset($in['to_ts']) ? (int)$in['to_ts'] : $nowA;
            if ($reqTo < $reqFrom) { $tmp = $reqFrom; $reqFrom = $reqTo; $reqTo = $tmp; }
            $fromTs = max(0, $reqFrom);
            $toTs = max($fromTs + 60, $reqTo);
            $cSpan = $toTs - $fromTs;
            if ($cSpan <= 86400) $bucketCount = 12;
            elseif ($cSpan <= 14 * 86400) $bucketCount = max(2, min(14, (int)ceil($cSpan / 86400)));
            else $bucketCount = 12;
        }

        $spanSec = max(60, $toTs - $fromTs);
        $prevToTs = $fromTs - 1;
        $prevFromTs = max(0, $fromTs - $spanSec);
        $bucketSec = max(1, (int)ceil($spanSec / max(1, $bucketCount)));

        $buckets = array();
        for ($bi = 0; $bi < $bucketCount; $bi++) {
            $bStart = $fromTs + ($bi * $bucketSec);
            $bEnd = ($bi === $bucketCount - 1) ? $toTs : min($toTs, $bStart + $bucketSec - 1);
            $buckets[$bi] = array('start_ts' => $bStart, 'end_ts' => $bEnd, 'messages' => 0, 'new_users' => 0, 'files' => 0, 'calls' => 0, 'reports' => 0);
        }
        $placeBucket = function($tsVal, $field) use (&$buckets, $fromTs, $bucketSec, $bucketCount) {
            $idx = (int)floor(($tsVal - $fromTs) / $bucketSec);
            if ($idx < 0) $idx = 0;
            if ($idx >= $bucketCount) $idx = $bucketCount - 1;
            $buckets[$idx][$field]++;
        };

        $msgRowsA = $db->all(
            "SELECT m.id, m.chat_id, m.user_id, m.kind, m.body, m.file_id, m.created_at, m.edited_at, m.deleted_at, m.expires_at, m.burn_after, m.pinned, f.mime AS file_mime, f.size AS file_size
             FROM messages m LEFT JOIN files f ON f.id = m.file_id
             WHERE m.created_at >= ? AND m.created_at <= ?",
            array($fromTs, $toTs)
        );
        $msgKinds = array(
            'text' => array('count' => 0, 'bytes' => 0), 'image' => array('count' => 0, 'bytes' => 0),
            'video' => array('count' => 0, 'bytes' => 0), 'voice' => array('count' => 0, 'bytes' => 0),
            'video_note' => array('count' => 0, 'bytes' => 0), 'audio' => array('count' => 0, 'bytes' => 0),
            'file' => array('count' => 0, 'bytes' => 0), 'call_log' => array('count' => 0, 'bytes' => 0),
            'system' => array('count' => 0, 'bytes' => 0)
        );
        $activeSendersMap = array();
        $editedInRange = 0; $ttlInRange = 0; $deletedInRange = 0; $pinnedInRange = 0;
        $callsTotal = 0; $callsVoice = 0; $callsVideo = 0; $callsAnswered = 0; $callsMissed = 0;

        foreach ($msgRowsA as $mr) {
            $mts = (int)$mr['created_at'];
            $placeBucket($mts, 'messages');
            $muid = (int)$mr['user_id'];
            if ($muid > 0) $activeSendersMap[$muid] = true;
            if (!empty($mr['edited_at'])) $editedInRange++;
            if (!empty($mr['expires_at']) || (int)$mr['burn_after'] > 0) $ttlInRange++;
            if (!empty($mr['deleted_at'])) $deletedInRange++;
            if ((int)$mr['pinned'] === 1) $pinnedInRange++;

            $k = (string)$mr['kind'];
            $fSize = isset($mr['file_size']) ? max(0, (int)$mr['file_size']) : 0;
            $fMime = strtolower((string)(isset($mr['file_mime']) ? $mr['file_mime'] : ''));

            if ($k === 'call_log') {
                $placeBucket($mts, 'calls');
                $callsTotal++;
                $bStr = (string)$mr['body'];
                if (strpos($bStr, '📹') !== false || stripos($bStr, 'video') !== false || strpos($bStr, 'تصویری') !== false) $callsVideo++;
                else $callsVoice++;
                if (strpos($bStr, 'بی‌پاسخ') !== false || stripos($bStr, 'missed') !== false || stripos($bStr, 'declined') !== false || strpos($bStr, 'رد شد') !== false || strpos($bStr, 'لغو') !== false) $callsMissed++;
                else $callsAnswered++;
                $msgKinds['call_log']['count']++;
            } elseif (isset($msgKinds[$k]) && $k !== 'file') {
                $msgKinds[$k]['count']++;
                $msgKinds[$k]['bytes'] += $fSize;
            } elseif (!empty($mr['file_id']) || $k === 'file') {
                if (strpos($fMime, 'image/') === 0) { $msgKinds['image']['count']++; $msgKinds['image']['bytes'] += $fSize; }
                elseif (strpos($fMime, 'video/') === 0) { $msgKinds['video']['count']++; $msgKinds['video']['bytes'] += $fSize; }
                elseif (strpos($fMime, 'audio/') === 0) { $msgKinds['audio']['count']++; $msgKinds['audio']['bytes'] += $fSize; }
                else { $msgKinds['file']['count']++; $msgKinds['file']['bytes'] += $fSize; }
            } else {
                $msgKinds['text']['count']++;
            }
        }
        $prevMessagesCount = ($rangeKey === 'all') ? 0 : (int)$db->val("SELECT COUNT(*) FROM messages WHERE created_at >= ? AND created_at <= ?", array($prevFromTs, $prevToTs));

        $newUserRows = $db->all("SELECT id, created_at FROM users WHERE status != 'deleted' AND created_at >= ? AND created_at <= ?", array($fromTs, $toTs));
        foreach ($newUserRows as $nur) $placeBucket((int)$nur['created_at'], 'new_users');
        $newUsersCount = count($newUserRows);
        $prevNewUsersCount = ($rangeKey === 'all') ? 0 : (int)$db->val("SELECT COUNT(*) FROM users WHERE status != 'deleted' AND created_at >= ? AND created_at <= ?", array($prevFromTs, $prevToTs));
        $totalUsersA = (int)$db->val("SELECT COUNT(*) FROM users WHERE status != 'deleted'");
        $onlineNowA = count_online_users_now($db, $realNow);
        $active24hA = (int)$db->val("SELECT COUNT(*) FROM users WHERE status = 'active' AND last_seen_bucket > 0 AND last_seen_bucket >= ?", array($realNow - 86400));
        $totpUsersA = (int)$db->val("SELECT COUNT(*) FROM users WHERE status != 'deleted' AND totp_secret IS NOT NULL AND totp_secret != ''");
        $blockedUsersA = (int)$db->val("SELECT COUNT(*) FROM users WHERE status = 'blocked'");

        $newChatsByType = array('dm' => 0, 'secret' => 0, 'group' => 0, 'channel' => 0);
        $ncRows = $db->all("SELECT type, COUNT(*) AS cnt FROM chats WHERE type IN ('dm', 'secret', 'group', 'channel') AND created_at >= ? AND created_at <= ? GROUP BY type", array($fromTs, $toTs));
        $newChatsTotal = 0;
        foreach ($ncRows as $ncr) {
            $ct = (string)$ncr['type'];
            if (isset($newChatsByType[$ct])) { $newChatsByType[$ct] = (int)$ncr['cnt']; $newChatsTotal += (int)$ncr['cnt']; }
        }
        $prevNewChatsCount = ($rangeKey === 'all') ? 0 : (int)$db->val("SELECT COUNT(*) FROM chats WHERE type IN ('dm', 'secret', 'group', 'channel') AND created_at >= ? AND created_at <= ?", array($prevFromTs, $prevToTs));
        $totalChatsByType = array('dm' => 0, 'secret' => 0, 'group' => 0, 'channel' => 0);
        $tcRows = $db->all("SELECT type, COUNT(*) AS cnt FROM chats WHERE type IN ('dm', 'secret', 'group', 'channel') GROUP BY type");
        foreach ($tcRows as $tcr) {
            $ct = (string)$tcr['type'];
            if (isset($totalChatsByType[$ct])) $totalChatsByType[$ct] = (int)$tcr['cnt'];
        }

        $fileRowsA = $db->all("SELECT id, size, created_at FROM files WHERE created_at >= ? AND created_at <= ?", array($fromTs, $toTs));
        $filesInRangeBytes = 0;
        foreach ($fileRowsA as $fra) { $placeBucket((int)$fra['created_at'], 'files'); $filesInRangeBytes += max(0, (int)$fra['size']); }
        $filesInRangeCount = count($fileRowsA);
        $prevFilesRow = ($rangeKey === 'all') ? array('cnt' => 0, 'sz' => 0) : $db->one("SELECT COUNT(*) AS cnt, COALESCE(SUM(size), 0) AS sz FROM files WHERE created_at >= ? AND created_at <= ?", array($prevFromTs, $prevToTs));
        $totalFilesBytesA = (int)$db->val("SELECT COALESCE(SUM(max_sz), 0) FROM (SELECT MAX(size) AS max_sz FROM files GROUP BY stored_name) AS u_blobs");
        $totalFilesCountA = (int)$db->val("SELECT COUNT(*) FROM files");
        $dbBytesA = 0;
        $sqPathA = $db->sqlitePath();
        if ($db->driver() === 'sqlite' && $sqPathA !== '' && file_exists($sqPathA)) $dbBytesA = (int)filesize($sqPathA);

        $repRowsA = $db->all("SELECT status, created_at FROM reports WHERE created_at >= ? AND created_at <= ?", array($fromTs, $toTs));
        $repSummary = array('total' => 0, 'pending' => 0, 'resolved' => 0, 'dismissed' => 0);
        foreach ($repRowsA as $rra) {
            $placeBucket((int)$rra['created_at'], 'reports');
            $repSummary['total']++;
            $rs = (string)$rra['status'];
            if ($rs === 'pending') $repSummary['pending']++;
            elseif ($rs === 'dismissed') $repSummary['dismissed']++;
            else $repSummary['resolved']++;
        }
        $repSummary['pending_all_time'] = (int)$db->val("SELECT COUNT(*) FROM reports WHERE status = 'pending'");

        $reactionsInRange = (int)$db->val("SELECT COUNT(*) FROM reactions r JOIN messages m ON m.id = r.message_id WHERE m.created_at >= ? AND m.created_at <= ?", array($fromTs, $toTs));
        $newMembershipsInRange = (int)$db->val("SELECT COUNT(*) FROM members m JOIN chats c ON c.id = m.chat_id WHERE c.type IN ('group', 'channel') AND m.joined_at >= ? AND m.joined_at <= ?", array($fromTs, $toTs));
        $sessionsCreatedInRange = (int)$db->val("SELECT COUNT(*) FROM sessions WHERE created_at >= ? AND created_at <= ? AND expires_at > ?", array($fromTs, $toTs, $realNow));
        $activeSessionsTotal = (int)$db->val("SELECT COUNT(*) FROM sessions WHERE expires_at > ?", array($realNow));
        $activeLiveCallsNow = (int)$db->val("SELECT COUNT(*) FROM active_calls WHERE status IN ('ringing', 'active') AND updated_at >= ?", array($realNow - 75));

        $topChatsRows = $db->all(
            "SELECT c.id, c.type, c.title, c.handle, c.visibility, COUNT(m.id) AS msg_cnt
             FROM messages m JOIN chats c ON c.id = m.chat_id
             WHERE c.type IN ('group', 'channel') AND m.created_at >= ? AND m.created_at <= ? AND m.deleted_at IS NULL
             GROUP BY c.id, c.type, c.title, c.handle, c.visibility ORDER BY msg_cnt DESC " . $db->limit(8),
            array($fromTs, $toTs)
        );
        $topChatsOut = array();
        foreach ($topChatsRows as $tcr) {
            $tcid = (int)$tcr['id'];
            $memCnt = (int)$db->val("SELECT COUNT(*) FROM members WHERE chat_id = ? AND role != 'pending'", array($tcid));
            $topChatsOut[] = array('id' => $tcid, 'type' => (string)$tcr['type'], 'title' => (string)$tcr['title'], 'handle' => $tcr['handle'] ? (string)$tcr['handle'] : '', 'visibility' => (string)$tcr['visibility'], 'msg_count' => (int)$tcr['msg_cnt'], 'member_count' => $memCnt);
        }
        $topEmojiRows = $db->all("SELECT r.emoji, COUNT(*) AS cnt FROM reactions r JOIN messages m ON m.id = r.message_id WHERE m.created_at >= ? AND m.created_at <= ? GROUP BY r.emoji ORDER BY cnt DESC " . $db->limit(8), array($fromTs, $toTs));
        $topEmojisOut = array();
        foreach ($topEmojiRows as $ter) $topEmojisOut[] = array('emoji' => (string)$ter['emoji'], 'count' => (int)$ter['cnt']);

        api_ok(array(
            'range'  => $rangeKey,
            'window' => array('from_ts' => $fromTs, 'to_ts' => $toTs, 'span_sec' => $spanSec, 'bucket_sec' => $bucketSec, 'bucket_count' => $bucketCount),
            'kpis' => array(
                'messages_in_range' => count($msgRowsA), 'prev_messages_in_range' => $prevMessagesCount,
                'active_senders_in_range' => count($activeSendersMap), 'edited_in_range' => $editedInRange,
                'ttl_in_range' => $ttlInRange, 'deleted_in_range' => $deletedInRange, 'pinned_in_range' => $pinnedInRange,
                'new_users_in_range' => $newUsersCount, 'prev_new_users' => $prevNewUsersCount,
                'total_users' => $totalUsersA, 'online_users_now' => $onlineNowA, 'active_users_24h' => $active24hA,
                'totp_users_total' => $totpUsersA, 'blocked_users_total' => $blockedUsersA,
                'new_chats_in_range' => $newChatsTotal, 'prev_new_chats' => $prevNewChatsCount,
                'new_chats_by_type' => $newChatsByType, 'total_chats_by_type' => $totalChatsByType,
                'files_in_range_count' => $filesInRangeCount, 'files_in_range_bytes' => $filesInRangeBytes,
                'prev_files_count' => $prevFilesRow ? (int)$prevFilesRow['cnt'] : 0, 'prev_files_bytes' => $prevFilesRow ? (int)$prevFilesRow['sz'] : 0,
                'total_files_count' => $totalFilesCountA, 'total_disk_bytes' => $totalFilesBytesA, 'db_size_bytes' => $dbBytesA,
                'reactions_in_range' => $reactionsInRange, 'new_memberships' => $newMembershipsInRange,
                'sessions_in_range' => $sessionsCreatedInRange, 'active_sessions_total' => $activeSessionsTotal,
                'calls' => array('total' => $callsTotal, 'voice' => $callsVoice, 'video' => $callsVideo, 'answered' => $callsAnswered, 'missed' => $callsMissed, 'active_now' => $activeLiveCallsNow),
                'reports' => $repSummary, 'firewall_stats' => fw_get_stats($db)
            ),
            'timeline' => array_values($buckets), 'message_kinds' => $msgKinds, 'top_chats' => $topChatsOut, 'top_emojis' => $topEmojisOut
        ));
    }

    if ($do === 'admin_settings_reset') {
        if (empty($in['confirmed'])) api_err('confirmation_required', 'Confirmation checkbox is required.');
        $defaults = default_settings_map();
        $protectedKeys = array('panic_duress_pass_hash', 'vapid_public_key', 'vapid_private_pem', 'sys_traffic_used_bytes', 'sys_traffic_period_start', 'messenger_delete_at', 'autonomous_mode');
        foreach ($defaults as $dk => $dv) {
            if (in_array($dk, $protectedKeys, true)) continue;
            Settings::set($db, $dk, $dv);
        }
        bump_tick();
        $sysTrafficOut = sync_and_get_system_traffic_status($db);
        $outS = Settings::all($db, true);
        $hasPanicDuressOut = (!empty($outS['panic_duress_pass_hash'])) ? 1 : 0;
        unset($outS['panic_duress_pass_hash'], $outS['vapid_private_pem']);
        $outS['has_panic_duress_password'] = $hasPanicDuressOut;
        $outRList = content_restrictions_to_list(isset($outS['restricted_content_types']) ? $outS['restricted_content_types'] : array());
        $outS['restricted_content_types'] = $outRList;
        $outS['global_restricted_content_types'] = $outRList;
        $outS['calls_audio_policy'] = quality_policy_code_to_ui(isset($outS['calls_audio_quality_policy']) ? $outS['calls_audio_quality_policy'] : 'free');
        $outS['calls_video_policy'] = quality_policy_code_to_ui(isset($outS['calls_video_quality_policy']) ? $outS['calls_video_quality_policy'] : 'free');
        $outS['calls_max_duration_sec'] = max(0, (int)(isset($outS['calls_max_duration_min']) ? $outS['calls_max_duration_min'] : 0)) * 60;
        $outS['system_traffic_limit_mb'] = isset($outS['sys_traffic_limit_mb']) ? (float)$outS['sys_traffic_limit_mb'] : 0;
        $outS['system_traffic_period_days'] = isset($outS['sys_traffic_period_days']) ? (float)$outS['sys_traffic_period_days'] : 0;
        $outS['default_user_traffic_mb'] = isset($outS['user_traffic_limit_mb']) ? (float)$outS['user_traffic_limit_mb'] : 0;
        $outS['default_user_traffic_limit_mb'] = $outS['default_user_traffic_mb'];
        $outS['default_user_traffic_period_days'] = isset($outS['user_traffic_period_days']) ? (float)$outS['user_traffic_period_days'] : 30;
        $outS['system_traffic'] = $sysTrafficOut;
        $outS['server_now'] = time();
        $outS = array_merge($outS, get_identity_length_limits($db));
        $outS['messenger_now'] = app_now($db);
        api_ok(array('reset' => true, 'settings' => $outS));
    }

    if ($do === 'admin_settings_set') {
        $allowedKeys = array_values(array_diff(array_keys(default_settings_map()), array('panic_duress_pass_hash', 'vapid_public_key', 'vapid_private_pem', 'sys_traffic_used_bytes', 'sys_traffic_period_start')));
        $changes = isset($in['settings']) && is_array($in['settings']) ? $in['settings'] : $in;
        $curIdLim = get_identity_length_limits($db);
        $hasUMin = array_key_exists('username_min_len', $changes);
        $hasUMax = array_key_exists('username_max_len', $changes);
        if ($hasUMin || $hasUMax) {
            $nextUMin = $hasUMin ? max(2, min(32, (int)$changes['username_min_len'])) : $curIdLim['username_min_len'];
            $nextUMax = $hasUMax ? max(3, min(64, (int)$changes['username_max_len'])) : $curIdLim['username_max_len'];
            if ($nextUMin > $nextUMax) {
                if ($hasUMin && !$hasUMax) $nextUMax = max(3, min(64, $nextUMin));
                else $nextUMin = max(2, min(32, $nextUMax));
            }
            $changes['username_min_len'] = $nextUMin;
            $changes['username_max_len'] = $nextUMax;
        }
        $hasNMin = array_key_exists('display_name_min_len', $changes);
        $hasNMax = array_key_exists('display_name_max_len', $changes);
        if ($hasNMin || $hasNMax) {
            $nextNMin = $hasNMin ? max(1, min(60, (int)$changes['display_name_min_len'])) : $curIdLim['display_name_min_len'];
            $nextNMax = $hasNMax ? max(2, min(120, (int)$changes['display_name_max_len'])) : $curIdLim['display_name_max_len'];
            if ($nextNMin > $nextNMax) {
                if ($hasNMin && !$hasNMax) $nextNMax = max(2, min(120, $nextNMin));
                else $nextNMin = max(1, min(60, $nextNMax));
            }
            $changes['display_name_min_len'] = $nextNMin;
            $changes['display_name_max_len'] = $nextNMax;
        }
        if (array_key_exists('max_msg_len', $changes)) {
            $changes['max_msg_len'] = max(100, min(32000, (int)$changes['max_msg_len']));
        }
        if (array_key_exists('max_total_users', $changes)) {
            $changes['max_total_users'] = max(0, min(10000000, (int)$changes['max_total_users']));
        }
        if (array_key_exists('max_user_chats', $changes)) {
            $changes['max_user_chats'] = max(0, min(100000, (int)$changes['max_user_chats']));
        }
        if (array_key_exists('max_user_created_groups', $changes)) {
            $changes['max_user_created_groups'] = max(0, min(100000, (int)$changes['max_user_created_groups']));
        }
        if (array_key_exists('max_user_created_channels', $changes)) {
            $changes['max_user_created_channels'] = max(0, min(100000, (int)$changes['max_user_created_channels']));
        }
        if (array_key_exists('global_hide_edit_badge', $changes)) {
            $changes['global_hide_edit_badge'] = (int)$changes['global_hide_edit_badge'] ? 1 : 0;
        }
        if (array_key_exists('force_lock_screen', $changes)) {
            $changes['force_lock_screen'] = (int)$changes['force_lock_screen'] ? 1 : 0;
        }
        if (array_key_exists('force_decoy_screen', $changes)) {
            $changes['force_decoy_screen'] = (int)$changes['force_decoy_screen'] ? 1 : 0;
        }
        // The two global gates cannot stand together. The decoy always outranks
        // the lock, so allowing both would swallow the lock screen silently and
        // leave the owner facing a switch that does nothing at all. Compared
        // against the state the save would produce, not just against what was
        // sent, because a partial payload only carries the switched keys.
        $nextForceLock  = array_key_exists('force_lock_screen', $changes)
            ? (int)$changes['force_lock_screen']
            : (int)Settings::get($db, 'force_lock_screen', 0);
        $nextForceDecoy = array_key_exists('force_decoy_screen', $changes)
            ? (int)$changes['force_decoy_screen']
            : (int)Settings::get($db, 'force_decoy_screen', 0);
        if ($nextForceLock === 1 && $nextForceDecoy === 1) {
            api_err('lock_decoy_exclusive', 'قفل صفحه و صفحه‌ی جعلی نمی‌توانند هم‌زمان برای همه اجرا شوند. یکی را خاموش کنید. / The lock screen and the decoy page cannot both be enforced for everybody. Turn one of them off.');
        }
        if (array_key_exists('global_decoy_title', $changes)) {
            $changes['global_decoy_title'] = m3_utf8_clip(trim((string)$changes['global_decoy_title']), 200);
        }
        if (array_key_exists('global_decoy_subtitle', $changes)) {
            $changes['global_decoy_subtitle'] = m3_utf8_clip(trim((string)$changes['global_decoy_subtitle']), 400);
        }
        if (array_key_exists('global_typing_policy', $changes)) {
            $changes['global_typing_policy'] = normalize_typing_override_val($changes['global_typing_policy'], 'global');
            if ($changes['global_typing_policy'] === 'force_off') {
                $db->exec("DELETE FROM meta WHERE k LIKE 'typing_%'");
            }
            bump_typing_tick();
        }
        if (array_key_exists('max_group_members', $changes)) {
            $changes['max_group_members'] = max(0, min(1000000, (int)$changes['max_group_members']));
        }
        if (array_key_exists('max_channel_members', $changes)) {
            $changes['max_channel_members'] = max(0, min(1000000, (int)$changes['max_channel_members']));
        }
        if (array_key_exists('max_upload_mb', $changes) && !array_key_exists('max_file_mb', $changes)) {
            $changes['max_file_mb'] = $changes['max_upload_mb'];
        }
        if (array_key_exists('system_traffic_limit_mb', $changes) && !array_key_exists('sys_traffic_limit_mb', $changes)) {
            $changes['sys_traffic_limit_mb'] = $changes['system_traffic_limit_mb'];
        }
        if (array_key_exists('system_traffic_period_days', $changes) && !array_key_exists('sys_traffic_period_days', $changes)) {
            $changes['sys_traffic_period_days'] = $changes['system_traffic_period_days'];
        }
        if (array_key_exists('default_user_traffic_mb', $changes) && !array_key_exists('user_traffic_limit_mb', $changes)) {
            $changes['user_traffic_limit_mb'] = $changes['default_user_traffic_mb'];
        }
        if (array_key_exists('default_user_traffic_limit_mb', $changes) && !array_key_exists('user_traffic_limit_mb', $changes)) {
            $changes['user_traffic_limit_mb'] = $changes['default_user_traffic_limit_mb'];
        }
        if (array_key_exists('default_user_traffic_period_days', $changes) && !array_key_exists('user_traffic_period_days', $changes)) {
            $changes['user_traffic_period_days'] = $changes['default_user_traffic_period_days'];
        }
        if (array_key_exists('max_file_mb', $changes)) {
            $changes['max_file_mb'] = max(0.5, min(2048, round((float)$changes['max_file_mb'], 2)));
        }
        foreach (array('max_total_storage_mb', 'max_user_storage_mb', 'file_auto_delete_hours', 'sys_traffic_limit_mb', 'user_traffic_limit_mb') as $stFloatKey) {
            if (array_key_exists($stFloatKey, $changes)) {
                $changes[$stFloatKey] = max(0, round((float)$changes[$stFloatKey], 4));
            }
        }
        foreach (array('sys_traffic_period_days', 'user_traffic_period_days') as $tpKey) {
            if (array_key_exists($tpKey, $changes)) {
                $changes[$tpKey] = max(0, min(36500, (int)$changes[$tpKey]));
            }
        }
        if (array_key_exists('video_note_enabled', $changes)) {
            $changes['video_note_enabled'] = (int)$changes['video_note_enabled'] ? 1 : 0;
        }
        if (array_key_exists('voice_enabled', $changes)) {
            $changes['voice_enabled'] = (int)$changes['voice_enabled'] ? 1 : 0;
        }
        if (!empty($changes['reset_system_traffic']) || !empty($in['reset_system_traffic'])) {
            $nowReset = time();
            Settings::set($db, 'sys_traffic_used_bytes', 0);
            Settings::set($db, 'sys_traffic_period_start', $nowReset);
        } elseif (array_key_exists('sys_traffic_period_days', $changes)) {
            $prevStart = (int)Settings::get($db, 'sys_traffic_period_start', 0);
            if ($prevStart <= 0 && (int)$changes['sys_traffic_period_days'] > 0) {
                Settings::set($db, 'sys_traffic_period_start', time());
            }
        }
        if (isset($changes['idle_mode'])) {
            $im = trim((string)$changes['idle_mode']);
            $changes['idle_mode'] = in_array($im, array('off', 'manual', 'auto'), true) ? $im : 'off';
        }
        if (isset($changes['idle_start'])) {
            $changes['idle_start'] = normalize_hhmm_str($changes['idle_start'], '23:00');
        }
        if (isset($changes['idle_end'])) {
            $changes['idle_end'] = normalize_hhmm_str($changes['idle_end'], '07:00');
        }
        if (isset($changes['idle_tz_offset'])) {
            $changes['idle_tz_offset'] = max(-840, min(840, (int)$changes['idle_tz_offset']));
        }
        if (array_key_exists('app_timezone', $changes)) {
            $changes['app_timezone'] = normalize_app_timezone($changes['app_timezone']);
        }
        if (array_key_exists('force_hide_last_seen', $changes)) {
            $changes['force_hide_last_seen'] = (int)$changes['force_hide_last_seen'] ? 1 : 0;
        }
        if (isset($changes['messenger_time_mode'])) {
            $tm = trim((string)$changes['messenger_time_mode']);
            $changes['messenger_time_mode'] = ($tm === 'custom') ? 'custom' : 'server';
            if ($changes['messenger_time_mode'] === 'server') {
                $changes['messenger_time_offset_sec'] = 0;
            }
        }
        if (array_key_exists('custom_messenger_ts', $changes)) {
            $customTs = (int)$changes['custom_messenger_ts'];
            if ($customTs > 946684800 && $customTs < 4102444800) {
                $changes['messenger_time_mode'] = 'custom';
                $changes['messenger_time_offset_sec'] = $customTs - time();
            }
            unset($changes['custom_messenger_ts']);
        } elseif (array_key_exists('messenger_time_offset_sec', $changes)) {
            $changes['messenger_time_offset_sec'] = max(-315360000, min(315360000, (int)$changes['messenger_time_offset_sec']));
        }
        if (array_key_exists('show_superadmin_transfer_msg', $changes)) {
            $changes['show_superadmin_transfer_msg'] = (int)$changes['show_superadmin_transfer_msg'] ? 1 : 0;
        }
        if (array_key_exists('site_name_fa', $changes)) {
            $changes['site_name_fa'] = trim((string)$changes['site_name_fa']);
            if ($changes['site_name_fa'] === '') $changes['site_name_fa'] = 'پیامرسان کوچک من (M3)';
        }
        if (array_key_exists('site_name_en', $changes)) {
            $changes['site_name_en'] = trim((string)$changes['site_name_en']);
            if ($changes['site_name_en'] === '') $changes['site_name_en'] = 'My Mini Messenger (M3)';
        }
        foreach (array('site_logo', 'site_favicon') as $brandKey) {
            if (array_key_exists($brandKey, $changes)) {
                $val = trim((string)$changes[$brandKey]);
                if ($val !== '' && !parse_branding_data_uri($val)) {
                    api_err('invalid_image', 'Invalid image format for branding.');
                }
                $changes[$brandKey] = $val;
            }
        }
        if (array_key_exists('uploads_disabled', $changes)) {
            $changes['uploads_disabled'] = (int)$changes['uploads_disabled'] ? 1 : 0;
        }
        if (array_key_exists('global_restricted_content_types', $changes) && !array_key_exists('restricted_content_types', $changes)) {
            $changes['restricted_content_types'] = $changes['global_restricted_content_types'];
        }
        if (array_key_exists('restricted_content_types', $changes)) {
            $changes['restricted_content_types'] = normalize_content_restrictions($changes['restricted_content_types']);
        }
        if (array_key_exists('calls_voice_enabled', $changes)) {
            $changes['calls_voice_enabled'] = (int)$changes['calls_voice_enabled'] ? 1 : 0;
        }
        if (array_key_exists('calls_video_enabled', $changes)) {
            $changes['calls_video_enabled'] = (int)$changes['calls_video_enabled'] ? 1 : 0;
        }
        if (array_key_exists('calls_audio_policy', $changes) && !array_key_exists('calls_audio_quality_policy', $changes)) {
            $changes['calls_audio_quality_policy'] = $changes['calls_audio_policy'];
        }
        if (array_key_exists('calls_video_policy', $changes) && !array_key_exists('calls_video_quality_policy', $changes)) {
            $changes['calls_video_quality_policy'] = $changes['calls_video_policy'];
        }
        if (array_key_exists('calls_audio_quality_policy', $changes)) {
            $changes['calls_audio_quality_policy'] = normalize_quality_policy_code($changes['calls_audio_quality_policy'], false);
        }
        if (array_key_exists('calls_video_quality_policy', $changes)) {
            $changes['calls_video_quality_policy'] = normalize_quality_policy_code($changes['calls_video_quality_policy'], true);
        }
        if (array_key_exists('calls_max_duration_sec', $changes) && !array_key_exists('calls_max_duration_min', $changes)) {
            $secIn = max(0, min(86400, (int)$changes['calls_max_duration_sec']));
            $changes['calls_max_duration_min'] = $secIn > 0 ? max(1, (int)round($secIn / 60)) : 0;
        }
        if (array_key_exists('calls_max_duration_min', $changes)) {
            $changes['calls_max_duration_min'] = max(0, min(1440, (int)$changes['calls_max_duration_min']));
        }
        if (array_key_exists('remember_cookie_days', $changes) && !array_key_exists('remember_cookie_sec', $changes)) {
            $daysIn = max(0.01, min(3650, (float)$changes['remember_cookie_days']));
            $changes['remember_cookie_sec'] = max(300, min(315360000, (int)round($daysIn * 86400)));
        }
        if (array_key_exists('remember_cookie_sec', $changes)) {
            $changes['remember_cookie_sec'] = max(300, min(315360000, (int)$changes['remember_cookie_sec']));
        }
        if (array_key_exists('twofa_enabled', $changes)) {
            $changes['twofa_enabled'] = (int)$changes['twofa_enabled'] ? 1 : 0;
        }
        if (array_key_exists('session_revoke_grace_min', $changes) && !array_key_exists('session_revoke_grace_sec', $changes)) {
            $minIn = max(0, min(1440, (int)$changes['session_revoke_grace_min']));
            $changes['session_revoke_grace_sec'] = $minIn * 60;
        }
        if (array_key_exists('session_revoke_grace_sec', $changes)) {
            $changes['session_revoke_grace_sec'] = max(0, min(86400, (int)$changes['session_revoke_grace_sec']));
        }
        if (array_key_exists('msg_viewers_policy', $changes)) {
            $changes['msg_viewers_policy'] = normalize_msg_viewers_value($changes['msg_viewers_policy'], 'global');
        }
        if (array_key_exists('default_ttl', $changes)) {
            $changes['default_ttl'] = max(0, min(31536000, (int)$changes['default_ttl']));
        }
        if (array_key_exists('default_ttl_mode', $changes)) {
            $changes['default_ttl_mode'] = ($changes['default_ttl_mode'] === 'burn_after_read') ? 'burn_after_read' : 'expire_after_send';
        }
        if (array_key_exists('draft_sync_enabled', $changes)) {
            $changes['draft_sync_enabled'] = (int)$changes['draft_sync_enabled'] ? 1 : 0;
        }
        if (array_key_exists('draft_sync_interval_sec', $changes)) {
            $changes['draft_sync_interval_sec'] = max(2, min(300, (int)$changes['draft_sync_interval_sec']));
        }
        foreach (array('fw_enabled', 'fw_captcha_enabled', 'fw_honeypot_enabled', 'fw_payload_shield') as $fwBoolKey) {
            if (array_key_exists($fwBoolKey, $changes)) {
                $changes[$fwBoolKey] = (int)$changes[$fwBoolKey] ? 1 : 0;
            }
        }
        if (array_key_exists('fw_rate_limit_rpm', $changes)) {
            $changes['fw_rate_limit_rpm'] = max(20, min(5000, (int)$changes['fw_rate_limit_rpm']));
        }
        if (array_key_exists('fw_auth_limit_rpm', $changes)) {
            $changes['fw_auth_limit_rpm'] = max(3, min(300, (int)$changes['fw_auth_limit_rpm']));
        }
        if (array_key_exists('default_lang', $changes)) {
            $changes['default_lang'] = ($changes['default_lang'] === 'en') ? 'en' : 'fa';
        }
        if (array_key_exists('edit_window_sec', $changes)) {
            $changes['edit_window_sec'] = max(0, min(31536000, (int)$changes['edit_window_sec']));
        }
        if (array_key_exists('delete_mode', $changes)) {
            $changes['delete_mode'] = ($changes['delete_mode'] === 'hard_delete') ? 'hard_delete' : 'anonymize';
        }
        if (array_key_exists('allowed_exts', $changes)) {
            $rawExts = explode(',', strtolower((string)$changes['allowed_exts']));
            $forbiddenExts = array('php', 'php3', 'php4', 'php5', 'php7', 'php8', 'phtml', 'phar', 'htaccess', 'htpasswd', 'cgi', 'pl', 'py', 'sh', 'asp', 'aspx', 'jsp', 'shtml');
            $cleanExts = array();
            foreach ($rawExts as $re) {
                $re = preg_replace('/[^a-z0-9]/', '', trim($re));
                if ($re !== '' && strlen($re) <= 12 && !in_array($re, $forbiddenExts, true) && !in_array($re, $cleanExts, true)) {
                    $cleanExts[] = $re;
                }
            }
            if (!empty($cleanExts)) {
                $changes['allowed_exts'] = implode(',', $cleanExts);
            } else {
                unset($changes['allowed_exts']);
            }
        }
        if (array_key_exists('reserved_handles', $changes)) {
            $rawRh = explode(',', strtolower((string)$changes['reserved_handles']));
            $cleanRh = array();
            foreach ($rawRh as $rh) {
                $rh = preg_replace('/[^a-z0-9_]/', '', trim($rh));
                if ($rh !== '' && strlen($rh) <= 32 && !in_array($rh, $cleanRh, true)) {
                    $cleanRh[] = $rh;
                }
            }
            $changes['reserved_handles'] = implode(',', $cleanRh);
        }
        foreach ($allowedKeys as $k) {
            if (array_key_exists($k, $changes)) {
                Settings::set($db, $k, $changes[$k]);
            }
        }
        if (!empty($in['apply_ttl_existing_all']) && (int)Settings::get($db, 'default_ttl', 0) > 0) {
            $applyTtl = (int)Settings::get($db, 'default_ttl', 0);
            $applyMode = (string)Settings::get($db, 'default_ttl_mode', 'expire_after_send');
            $nowApply = time();
            if ($applyMode === 'expire_after_send') {
                $db->exec(
                    "UPDATE messages SET burn_after = ?, first_read_at = COALESCE(first_read_at, ?), expires_at = ?
                     WHERE deleted_at IS NULL AND chat_id NOT IN (SELECT id FROM chats WHERE type = 'system')
                       AND (expires_at IS NULL OR expires_at > ?)",
                    array($applyTtl, $nowApply, $nowApply + $applyTtl, $nowApply + $applyTtl)
                );
            } else {
                $db->exec(
                    "UPDATE messages SET burn_after = ?
                     WHERE deleted_at IS NULL AND chat_id NOT IN (SELECT id FROM chats WHERE type = 'system')
                       AND (burn_after IS NULL OR burn_after = 0 OR burn_after > ?)",
                    array($applyTtl, $applyTtl)
                );
            }
        }
        if (array_key_exists('remember_cookie_sec', $changes)) {
            $updatedCookieSec = (int)$changes['remember_cookie_sec'];
            $db->exec(
                "UPDATE sessions SET expires_at = (CASE WHEN last_used_bucket > created_at THEN last_used_bucket ELSE created_at END) + ? WHERE is_persistent = 1",
                array($updatedCookieSec)
            );
            if (!headers_sent() && isset($_COOKIE['pm_sess']) && $_COOKIE['pm_sess'] !== '' && (!isset($auth['session']['is_persistent']) || (int)$auth['session']['is_persistent'] === 1)) {
                set_session_cookie((string)$_COOKIE['pm_sess'], time() + $updatedCookieSec, false);
            }
        }
        if (isset($changes['site_name_fa']) || isset($changes['site_name_en'])) {
            $curDefLang = (string)Settings::get($db, 'default_lang', 'fa');
            $syncSite = ($curDefLang === 'en')
                ? (string)Settings::get($db, 'site_name_en', 'My Mini Messenger (M3)')
                : (string)Settings::get($db, 'site_name_fa', 'پیامرسان کوچک من (M3)');
            Settings::set($db, 'site_name', $syncSite);
        }
        if (array_key_exists('show_admin_badge', $changes)) {
            $b = (int)$changes['show_admin_badge'] ? 1 : 0;
            $db->exec("UPDATE users SET show_admin_badge = ? WHERE id = ?", array($b, $myId));
        }
        log_admin_audit($db, $myId, 'settings_update', array_keys($changes));
        bump_tick();
        $sysTrafficOut = sync_and_get_system_traffic_status($db);
        $outS = Settings::all($db, true);
        $hasPanicDuressOut = (!empty($outS['panic_duress_pass_hash'])) ? 1 : 0;
        unset($outS['panic_duress_pass_hash'], $outS['vapid_private_pem']);
        $outS['has_panic_duress_password'] = $hasPanicDuressOut;
        $outRList = content_restrictions_to_list(isset($outS['restricted_content_types']) ? $outS['restricted_content_types'] : array());
        $outS['restricted_content_types'] = $outRList;
        $outS['global_restricted_content_types'] = $outRList;
        $outS['calls_audio_policy'] = quality_policy_code_to_ui(isset($outS['calls_audio_quality_policy']) ? $outS['calls_audio_quality_policy'] : 'free');
        $outS['calls_video_policy'] = quality_policy_code_to_ui(isset($outS['calls_video_quality_policy']) ? $outS['calls_video_quality_policy'] : 'free');
        $outS['calls_max_duration_sec'] = max(0, (int)(isset($outS['calls_max_duration_min']) ? $outS['calls_max_duration_min'] : 0)) * 60;
        $outS['system_traffic_limit_mb'] = isset($outS['sys_traffic_limit_mb']) ? (float)$outS['sys_traffic_limit_mb'] : 0;
        $outS['system_traffic_period_days'] = isset($outS['sys_traffic_period_days']) ? (float)$outS['sys_traffic_period_days'] : 0;
        $outS['default_user_traffic_mb'] = isset($outS['user_traffic_limit_mb']) ? (float)$outS['user_traffic_limit_mb'] : 0;
        $outS['default_user_traffic_limit_mb'] = $outS['default_user_traffic_mb'];
        $outS['default_user_traffic_period_days'] = isset($outS['user_traffic_period_days']) ? (float)$outS['user_traffic_period_days'] : 30;
        $outS['system_traffic'] = $sysTrafficOut;
        $outS['server_now'] = time();
        $outS['messenger_now'] = app_now($db);
        $outS['app_timezone'] = normalize_app_timezone(isset($outS['app_timezone']) ? $outS['app_timezone'] : 'Asia/Tehran');
        $outS['force_hide_last_seen'] = !empty($outS['force_hide_last_seen']) ? 1 : 0;
        $outS = array_merge($outS, get_identity_length_limits($db));
        api_ok(array('settings' => $outS));
    }

    if ($do === 'admin_hide_all_last_seen') {
        $allU = $db->all("SELECT id, flags FROM users WHERE status != 'deleted'");
        $updatedCount = 0;
        $db->tx(function() use ($db, $allU, &$updatedCount) {
            foreach ($allU as $ur) {
                $fl = parse_json_col(isset($ur['flags']) ? $ur['flags'] : '', array());
                $needsUpd = empty($fl['hide_last_seen']) || (isset($fl['last_seen_mode']) && $fl['last_seen_mode'] !== 'recently');
                if ($needsUpd) {
                    $fl['hide_last_seen'] = 1;
                    $fl['last_seen_mode'] = 'recently';
                    $db->exec("UPDATE users SET flags = ? WHERE id = ?", array(json_encode($fl), (int)$ur['id']));
                    $updatedCount++;
                }
            }
        });
        if (array_key_exists('force_hide_last_seen', $in)) {
            Settings::set($db, 'force_hide_last_seen', (int)$in['force_hide_last_seen'] ? 1 : 0);
        } elseif (array_key_exists('force_global', $in)) {
            Settings::set($db, 'force_hide_last_seen', (int)$in['force_global'] ? 1 : 0);
        }
        log_admin_audit($db, $myId, 'hide_all_last_seen', array('updated_users' => $updatedCount));
        bump_tick();
        api_ok(array(
            'updated_count'        => $updatedCount,
            'total_users'          => count($allU),
            'force_hide_last_seen' => (int)Settings::get($db, 'force_hide_last_seen', 0) ? 1 : 0
        ));
    }

    if ($do === 'admin_relinquish_superadmin') {
        if (empty($in['confirmed_irreversible']) && empty($in['confirmed'])) {
            api_err('confirmation_required', 'Explicit irreversible confirmation is required.');
        }
        Settings::set($db, 'autonomous_mode', 1);
        $db->exec("UPDATE users SET role = 'user', show_admin_badge = 0 WHERE role = 'superadmin'");
        // Post and pin the autonomous-mode notice inside every user's one-way Official System Chat (NOT in default group/channel)
        $annText = autonomous_mode_system_notice_text();
        $nowApp = app_now($db);
        $allActiveUsers = $db->all("SELECT id FROM users WHERE status != 'deleted'");
        foreach ($allActiveUsers as $auRow) {
            post_system_chat_message($db, (int)$auRow['id'], $annText, true, $nowApp);
        }
        bump_tick();
        $updatedMe = $db->one("SELECT * FROM users WHERE id = ?", array($myId));
        api_ok(array(
            'relinquished'    => true,
            'autonomous_mode' => 1,
            'settings'        => array('autonomous_mode' => 1),
            'user'            => format_user_self($updatedMe),
            'chats'           => fetch_user_chats($db, $updatedMe)
        ));
    }

    if ($do === 'admin_users_list') {
        $q = isset($in['q']) ? trim((string)$in['q']) : '';
        $nowAdmUsers = time();
        $totalOnlineNow = count_online_users_now($db, $nowAdmUsers);
        $params = array();
        $sql = "SELECT u.*, p.username AS inviter_username,
                       (SELECT COALESCE(SUM(f.size), 0) FROM files f WHERE f.owner_id = u.id) AS used_storage_bytes,
                       (SELECT COUNT(*) FROM files f WHERE f.owner_id = u.id) AS files_count,
                       (SELECT COUNT(*) FROM sessions s WHERE s.user_id = u.id AND s.expires_at > " . (int)$nowAdmUsers . ") AS sessions_count
                FROM users u
                LEFT JOIN users p ON p.id = u.invited_by
                WHERE 1=1";
        if ($q !== '') {
            $likeAdminQ = '%' . escape_like_bang($q) . '%';
            $sql .= " AND (u.username LIKE ? ESCAPE '!' OR u.name LIKE ? ESCAPE '!' OR u.invite_code LIKE ? ESCAPE '!')";
            $params[] = $likeAdminQ;
            $params[] = $likeAdminQ;
            $params[] = $likeAdminQ;
        }
        $sql .= " ORDER BY u.id DESC";
        $rows = $db->all($sql, $params);
        $out = array();
        foreach ($rows as $r) {
            $rFlags = get_user_flags($r);
            $uTrafficSt = sync_and_get_user_traffic_status($db, $r);
            $lastSeenTs = (int)$r['last_seen_bucket'];
            $isUserOnline = is_user_online_now_row($db, $r, $nowAdmUsers);
            $out[] = array(
                'id'               => (int)$r['id'],
                'username'         => !empty($rFlags['no_username']) ? '' : $r['username'],
                'login_username'   => $r['username'],
                'no_username'      => !empty($rFlags['no_username']) ? 1 : 0,
                'hide_search'      => !empty($rFlags['hide_search']) ? 1 : 0,
                'deny_dm'          => !empty($rFlags['deny_dm']) ? 1 : 0,
                'deny_calls'       => !empty($rFlags['deny_calls']) ? 1 : 0,
                'deny_group_invite'=> !empty($rFlags['deny_group_invite']) ? 1 : 0,
                'name'             => $r['name'],
                'bio'              => (string)$r['bio'],
                'avatar'           => (string)$r['avatar'],
                'has_2fa'          => !empty($r['totp_secret']) ? 1 : 0,
                'twofa_disabled'   => !empty($rFlags['twofa_disabled']) ? 1 : 0,
                'totp_allowed'     => twofa_allowed_for_user($db, $r) ? 1 : 0,
                'force_pw_reset'   => !empty($rFlags['force_pw_reset']) ? 1 : 0,
                'sessions_count'   => (int)$r['sessions_count'],
                'online'           => $isUserOnline,
                'is_online'        => $isUserOnline,
                'role'             => $r['role'],
                'is_founder'       => is_site_founder($r) ? 1 : 0,
                'status'           => $r['status'],
                'ban_login'        => ($r['status'] === 'blocked') ? 1 : 0,
                'ban_send'         => !empty($rFlags['ban_send']) ? 1 : 0,
                'ban_react'        => !empty($rFlags['ban_react']) ? 1 : 0,
                'show_admin_badge' => (int)$r['show_admin_badge'],
                'invite_code'      => $r['invite_code'],
                'invited_by'       => $r['invited_by'] !== null ? (int)$r['invited_by'] : null,
                'inviter_username' => $r['inviter_username'],
                'used_storage_bytes'=> (int)$r['used_storage_bytes'],
                'files_count'       => (int)$r['files_count'],
                'storage_quota_mb'  => (float)(isset($rFlags['storage_quota_mb']) ? $rFlags['storage_quota_mb'] : 0),
                'traffic_quota_mb'  => isset($rFlags['traffic_quota_mb']) ? (float)$rFlags['traffic_quota_mb'] : -1.0,
                'traffic_period_days' => isset($rFlags['traffic_period_days']) ? (int)$rFlags['traffic_period_days'] : -1,
                'traffic_status'    => $uTrafficSt,
                'upload_disabled'   => !empty($rFlags['upload_disabled']) ? 1 : 0,
                'admin_user_ttl'      => isset($rFlags['admin_user_ttl']) ? max(0, (int)$rFlags['admin_user_ttl']) : 0,
                'admin_user_ttl_mode' => (isset($rFlags['admin_user_ttl_mode']) && $rFlags['admin_user_ttl_mode'] === 'burn_after_read') ? 'burn_after_read' : 'expire_after_send',
                'user_default_ttl'    => isset($rFlags['user_default_ttl']) ? max(0, (int)$rFlags['user_default_ttl']) : 0,
                'user_default_ttl_mode'=> (isset($rFlags['user_default_ttl_mode']) && $rFlags['user_default_ttl_mode'] === 'burn_after_read') ? 'burn_after_read' : 'expire_after_send',
                'restricted_content_types' => content_restrictions_to_list(isset($rFlags['restricted_content_types']) ? $rFlags['restricted_content_types'] : array()),
                'call_policy'       => normalize_call_policy(isset($rFlags['call_policy']) ? $rFlags['call_policy'] : array(), 'user'),
                'msg_viewers_policy'=> normalize_msg_viewers_value(isset($rFlags['msg_viewers_policy']) ? $rFlags['msg_viewers_policy'] : 'inherit', 'user'),
                'show_my_typing'    => (!isset($rFlags['show_my_typing']) || (int)$rFlags['show_my_typing'] !== 0) ? 1 : 0,
                'admin_typing_override' => normalize_typing_override_val(isset($rFlags['admin_typing_override']) ? $rFlags['admin_typing_override'] : 'inherit', 'user'),
                'hide_edit_badge'   => !empty($rFlags['hide_edit_badge']) ? 1 : 0,
                'admin_hide_edit_badge' => (isset($rFlags['admin_hide_edit_badge']) && in_array($rFlags['admin_hide_edit_badge'], array('inherit', 'on', 'off'), true)) ? $rFlags['admin_hide_edit_badge'] : 'inherit',
                'admin_max_created_groups'   => isset($rFlags['admin_max_created_groups']) ? max(-1, (int)$rFlags['admin_max_created_groups']) : -1,
                'admin_max_created_channels' => isset($rFlags['admin_max_created_channels']) ? max(-1, (int)$rFlags['admin_max_created_channels']) : -1,
                'created_groups_count'       => count_user_created_chats_by_type($db, (int)$r['id'], 'group'),
                'created_channels_count'     => count_user_created_chats_by_type($db, (int)$r['id'], 'channel'),
                'created_at'        => (int)$r['created_at'],
                'last_seen_bucket'  => $lastSeenTs,
                'last_seen_at'      => $lastSeenTs
            );
        }
        api_ok(array(
            'users'              => $out,
            'online_users_count' => $totalOnlineNow,
            'online_count'       => $totalOnlineNow
        ));
    }

    if ($do === 'admin_user_create') {
        $username = isset($in['username']) ? u_lower(trim((string)$in['username'])) : '';
        $password = isset($in['password']) ? (string)$in['password'] : '';
        $passwordConfirm = array_key_exists('password_confirm', $in) ? (string)$in['password_confirm'] : $password;
        $name     = isset($in['name']) ? trim((string)$in['name']) : '';
        $role     = (isset($in['role']) && $in['role'] === 'superadmin') ? 'superadmin' : 'user';

        $idLim = get_identity_length_limits($db);
        if (!validate_username_policy($username, $idLim)) {
            api_err_invalid_username($idLim);
        }
        if ($name === '') {
            $name = u_substr($username, 0, $idLim['display_name_max_len']);
            if (u_strlen($name) < $idLim['display_name_min_len']) {
                api_err_invalid_display_name($idLim);
            }
        } elseif (!validate_display_name_policy($name, $idLim)) {
            api_err_invalid_display_name($idLim);
        }
        if ($password !== $passwordConfirm) {
            api_err('password_mismatch', 'رمز عبور و تکرار آن یکسان نیستند. / Passwords do not match.');
        }
        if (!validate_strong_password($password)) {
            api_err('weak_password_complex', strong_password_error_message($password));
        }

        $exists = $db->one("SELECT id FROM users WHERE username = ?", array($username));
        if ($exists) {
            api_err('username_taken', 'Username already exists.');
        }

        $recoveryCode = strtoupper(substr(bin2hex(random_bytes_safe(8)), 0, 4) . '-' . substr(bin2hex(random_bytes_safe(8)), 0, 4) . '-' . substr(bin2hex(random_bytes_safe(8)), 0, 4));
        $invCode = unique_user_invite_code($db);
        $now = time();
        $flags = json_encode(array('hide_search' => 0, 'hide_last_seen' => 0, 'deny_dm' => 0, 'deny_calls' => 0, 'read_receipts' => 1));

        $db->exec(
            "INSERT INTO users (username, name, bio, avatar, pass_hash, recovery_hash, lang, theme, cal, flags, role, status, show_admin_badge, invite_code, invited_by, traffic_used_bytes, traffic_period_start, created_at, last_seen_bucket)
             VALUES (?, ?, '', '', ?, ?, ?, ?, 'jalali', ?, ?, 'active', 1, ?, ?, 0, ?, ?, ?)",
            array(
                $username, $name,
                password_hash($password, PASSWORD_DEFAULT),
                password_hash($recoveryCode, PASSWORD_DEFAULT),
                Settings::get($db, 'default_lang', 'fa'),
                Settings::get($db, 'default_theme', 'auto'),
                $flags, $role, $invCode, $myId, $now, $now, (int)(floor($now / 300) * 300)
            )
        );
        $newUid = $db->lastId();
        enroll_default_chats($db, $newUid, $role === 'superadmin');
        record_user_login_system_notice($db, $newUid, true);
        log_admin_audit($db, $myId, 'user_create', array('user_id' => $newUid, 'username' => $username));
        bump_tick();
        api_ok(array(
            'user'          => array('id' => $newUid, 'username' => $username, 'name' => $name),
            'user_id'       => $newUid,
            'username'      => $username,
            'recovery_code' => $recoveryCode,
            'invite_code'   => $invCode
        ));
    }

    /* Force a feature off for one specific group or channel, on top of the
       global and per-type switches. Super-admin / founder only. */
    if ($do === 'admin_chat_feature_force') {
        require_superadmin($db);
        $cid     = isset($in['chat_id']) ? (int)$in['chat_id'] : 0;
        $feature = isset($in['feature']) ? (string)$in['feature'] : '';
        $enabled = isset($in['enabled']) ? ((int)$in['enabled'] ? 1 : 0) : 1;
        if (!in_array($feature, array('chat_preview', 'msg_views'), true)) {
            api_err('bad_request', 'Unknown feature.');
        }
        $chat = $db->one("SELECT id, type, title FROM chats WHERE id = ?", array($cid));
        if (!$chat) api_err('not_found', 'Chat not found.');
        if ($feature === 'msg_views' && $chat['type'] !== 'group' && $chat['type'] !== 'channel') {
            api_err('not_supported', 'View counters only apply to groups and channels.');
        }
        $settingKey = ($feature === 'msg_views') ? 'msg_views_off_chats' : 'chat_preview_off_chats';
        $raw = Settings::get($db, $settingKey, array());
        $ids = array();
        if (is_array($raw)) {
            foreach ($raw as $v) { $iv = (int)$v; if ($iv > 0 && $iv !== $cid) $ids[$iv] = true; }
        }
        if (!$enabled) $ids[$cid] = true;
        $offList = array_values(array_keys($ids));
        Settings::set($db, $settingKey, $offList);
        log_admin_audit($db, $myId, 'chat_feature_force', array('chat_id' => $cid, 'feature' => $feature, 'enabled' => $enabled));
        bump_tick();
        api_ok(array(
            'chat_id'    => $cid,
            'feature'    => $feature,
            'enabled'    => $enabled,
            'forced_off' => $enabled ? 0 : 1,
            'off_chats'  => $offList
        ));
    }

    if ($do === 'admin_user_action') {
        $uid = isset($in['user_id']) ? (int)$in['user_id'] : 0;
        $uAct = isset($in['user_action']) ? (string)$in['user_action'] : '';
        if ($uAct === 'block' || $uAct === 'unblock') {
            $do = 'admin_user_update';
            $in['status'] = ($uAct === 'block') ? 'blocked' : 'active';
        } elseif ($uAct === 'reset_password') {
            $do = 'admin_user_reset_password';
        } elseif ($uAct === 'delete') {
            $do = 'admin_user_delete';
        }
    }

    if ($do === 'admin_user_update') {
        $uid = isset($in['user_id']) ? (int)$in['user_id'] : 0;
        $u = $db->one("SELECT * FROM users WHERE id = ?", array($uid));
        if (!$u) api_err('not_found', 'User not found.');
        guard_superadmin_target($db, $auth, $u);
        $status = isset($in['status']) && in_array($in['status'], array('active', 'blocked'), true) ? $in['status'] : $u['status'];
        $role = isset($in['role']) && in_array($in['role'], array('user', 'superadmin'), true) ? $in['role'] : $u['role'];
        guard_role_change($db, $auth, $u, $role);
        $badge = isset($in['show_admin_badge']) ? ((int)$in['show_admin_badge'] ? 1 : 0) : (int)$u['show_admin_badge'];

        $rawOrigFlags = parse_json_col(isset($u['flags']) ? $u['flags'] : '', array());
        $uFlags = get_user_flags($u);
        foreach ($rawOrigFlags as $fk => $fv) {
            $uFlags[$fk] = $fv;
        }
        if (array_key_exists('ban_login', $in)) {
            $status = ((int)$in['ban_login'] === 1) ? 'blocked' : 'active';
        }
        if (array_key_exists('ban_send', $in)) {
            $uFlags['ban_send'] = (int)$in['ban_send'] ? 1 : 0;
        }
        if (array_key_exists('ban_react', $in)) {
            $uFlags['ban_react'] = (int)$in['ban_react'] ? 1 : 0;
        }
        if (array_key_exists('storage_quota_mb', $in)) {
            $uFlags['storage_quota_mb'] = max(0, round((float)$in['storage_quota_mb'], 4));
        }
        if (array_key_exists('traffic_quota_mb', $in)) {
            $tqVal = (float)$in['traffic_quota_mb'];
            $uFlags['traffic_quota_mb'] = ($tqVal < 0) ? -1.0 : round($tqVal, 4);
        }
        if (array_key_exists('traffic_period_days', $in)) {
            $tpVal = (int)$in['traffic_period_days'];
            $uFlags['traffic_period_days'] = ($tpVal < 0) ? -1 : max(0, min(36500, $tpVal));
        }
        if (array_key_exists('upload_disabled', $in)) {
            $uFlags['upload_disabled'] = (int)$in['upload_disabled'] ? 1 : 0;
        }
        if (isset($in['restricted_content_types']) && is_array($in['restricted_content_types'])) {
            $uFlags['restricted_content_types'] = normalize_content_restrictions($in['restricted_content_types']);
        }
        if (isset($in['call_policy']) && is_array($in['call_policy'])) {
            $uFlags['call_policy'] = normalize_call_policy($in['call_policy'], 'user');
        }
        if (isset($in['msg_viewers_policy'])) {
            $uFlags['msg_viewers_policy'] = normalize_msg_viewers_value($in['msg_viewers_policy'], 'user');
        }
        if (array_key_exists('admin_user_ttl', $in)) {
            $uFlags['admin_user_ttl'] = max(0, min(31536000, (int)$in['admin_user_ttl']));
        }
        if (isset($in['admin_user_ttl_mode']) && in_array($in['admin_user_ttl_mode'], array('expire_after_send', 'burn_after_read'), true)) {
            $uFlags['admin_user_ttl_mode'] = $in['admin_user_ttl_mode'];
        }
        if (isset($in['admin_hide_edit_badge']) && in_array($in['admin_hide_edit_badge'], array('inherit', 'on', 'off'), true)) {
            $uFlags['admin_hide_edit_badge'] = $in['admin_hide_edit_badge'];
        }
        if (isset($in['admin_typing_override'])) {
            $uFlags['admin_typing_override'] = normalize_typing_override_val($in['admin_typing_override'], 'user');
            if ($uFlags['admin_typing_override'] === 'force_off') {
                clear_ephemeral_typing_for_user($db, $uid, 0);
            } else {
                bump_typing_tick();
            }
        }
        if (array_key_exists('admin_max_created_groups', $in)) {
            $mgv = (int)$in['admin_max_created_groups'];
            $uFlags['admin_max_created_groups'] = ($mgv < 0) ? -1 : min(100000, $mgv);
        }
        if (array_key_exists('admin_max_created_channels', $in)) {
            $mcv = (int)$in['admin_max_created_channels'];
            $uFlags['admin_max_created_channels'] = ($mcv < 0) ? -1 : min(100000, $mcv);
        }
        if ($uid === $myId && $status === 'blocked') {
            api_err('invalid_target', 'Cannot block your own super-admin login.');
        }
        if ($uid === $myId && $role !== 'superadmin') {
            api_err('invalid_target', 'Cannot remove super-admin role from your own active account.');
        }
        $updIdLim = get_identity_length_limits($db);
        $nextAdmName = (string)$u['name'];
        if (array_key_exists('name', $in)) {
            $candAdmName = trim((string)$in['name']);
            if ($candAdmName !== $nextAdmName) {
                if (!validate_display_name_policy($candAdmName, $updIdLim)) {
                    api_err_invalid_display_name($updIdLim);
                }
                $nextAdmName = $candAdmName;
            }
        }
        $nextAdmUsername = (string)$u['username'];
        if (array_key_exists('username', $in)) {
            $candAdmU = u_lower(trim(ltrim((string)$in['username'], '@')));
            if ($candAdmU !== $nextAdmUsername) {
                if (!validate_username_policy($candAdmU, $updIdLim)) {
                    api_err_invalid_username($updIdLim);
                }
                $takenAdmU = $db->val("SELECT id FROM users WHERE username = ? AND id != ? UNION SELECT id FROM chats WHERE handle = ?", array($candAdmU, $uid, $candAdmU));
                if ($takenAdmU) {
                    api_err('username_taken', 'این نام کاربری قبلاً انتخاب شده است. / Username is already taken.');
                }
                $nextAdmUsername = $candAdmU;
            }
        }
        $db->exec("UPDATE users SET username = ?, name = ?, status = ?, role = ?, show_admin_badge = ?, flags = ? WHERE id = ?", array($nextAdmUsername, $nextAdmName, $status, $role, $badge, json_encode($uFlags), $uid));
        if (!empty($in['apply_ttl_existing']) && !empty($uFlags['admin_user_ttl'])) {
            $uApplyTtl = (int)$uFlags['admin_user_ttl'];
            $uApplyMode = isset($uFlags['admin_user_ttl_mode']) ? (string)$uFlags['admin_user_ttl_mode'] : 'expire_after_send';
            $nowUApp = time();
            if ($uApplyMode === 'expire_after_send') {
                $db->exec(
                    "UPDATE messages SET burn_after = ?, first_read_at = COALESCE(first_read_at, ?), expires_at = ?
                     WHERE user_id = ? AND deleted_at IS NULL AND (expires_at IS NULL OR expires_at > ?)",
                    array($uApplyTtl, $nowUApp, $nowUApp + $uApplyTtl, $uid, $nowUApp + $uApplyTtl)
                );
            } else {
                $db->exec(
                    "UPDATE messages SET burn_after = ?
                     WHERE user_id = ? AND deleted_at IS NULL AND (burn_after IS NULL OR burn_after = 0 OR burn_after > ?)",
                    array($uApplyTtl, $uid, $uApplyTtl)
                );
            }
        }
        if (!empty($in['reset_traffic'])) {
            $db->exec("UPDATE users SET traffic_used_bytes = 0, traffic_period_start = ? WHERE id = ?", array(time(), $uid));
        } elseif ((int)$u['traffic_period_start'] <= 0) {
            $db->exec("UPDATE users SET traffic_period_start = ? WHERE id = ?", array(time(), $uid));
        }
        if ($status === 'blocked') {
            $db->exec("DELETE FROM sessions WHERE user_id = ?", array($uid));
        }
        log_admin_audit($db, $myId, 'user_update', array('user_id' => $uid, 'status' => $status, 'role' => $role));
        bump_tick();
        api_ok(array('updated' => true));
    }

    if ($do === 'admin_user_reset_password') {
        $uid = isset($in['user_id']) ? (int)$in['user_id'] : 0;
        $uTarget = $db->one("SELECT id, role, is_founder FROM users WHERE id = ?", array($uid));
        if (!$uTarget) {
            api_err('not_found', 'User not found.');
        }
        guard_superadmin_target($db, $auth, $uTarget);
        $newPass = isset($in['new_password']) ? (string)$in['new_password'] : '';
        $newPassConfirm = isset($in['new_password_confirm']) ? (string)$in['new_password_confirm'] : (isset($in['password_confirm']) ? (string)$in['password_confirm'] : '');
        if ($newPass !== $newPassConfirm) {
            api_err('password_mismatch', 'رمز عبور جدید و تکرار آن یکسان نیستند. / New password and confirmation do not match.');
        }
        if (!validate_strong_password($newPass)) {
            api_err('weak_password_complex', strong_password_error_message($newPass));
        }
        $db->exec("UPDATE users SET pass_hash = ?, totp_secret = NULL WHERE id = ?", array(password_hash($newPass, PASSWORD_DEFAULT), $uid));
        $db->exec("DELETE FROM sessions WHERE user_id = ?", array($uid));
        log_admin_audit($db, $myId, 'user_reset_password', array('user_id' => $uid));
        api_ok(array('reset' => true));
    }

    if ($do === 'admin_user_security_action') {
        $uid = isset($in['user_id']) ? (int)$in['user_id'] : 0;
        $secAct = isset($in['sec_action']) ? trim((string)$in['sec_action']) : (isset($in['security_action']) ? trim((string)$in['security_action']) : '');
        $uTarget = $db->one("SELECT * FROM users WHERE id = ?", array($uid));
        if (!$uTarget || $uTarget['status'] === 'deleted') {
            api_err('not_found', 'User not found.');
        }
        guard_superadmin_target($db, $auth, $uTarget);
        if ($secAct === 'keep_latest_session') {
            assert_session_revoke_grace($db, $auth);
            if ($uid === $myId) {
                $curSidAdm = isset($auth['session']['id']) ? (int)$auth['session']['id'] : 0;
                $db->exec("DELETE FROM sessions WHERE user_id = ? AND id != ?", array($uid, $curSidAdm));
            } else {
                $latestSid = (int)$db->val("SELECT id FROM sessions WHERE user_id = ? ORDER BY created_at DESC, id DESC LIMIT 1", array($uid));
                if ($latestSid > 0) {
                    $db->exec("DELETE FROM sessions WHERE user_id = ? AND id != ?", array($uid, $latestSid));
                }
            }
            api_ok(array('done' => true, 'sec_action' => 'keep_latest_session'));
        } elseif ($secAct === 'revoke_sessions') {
            assert_session_revoke_grace($db, $auth);
            if ($uid === $myId) {
                $curSidAdm = isset($auth['session']['id']) ? (int)$auth['session']['id'] : 0;
                $db->exec("DELETE FROM sessions WHERE user_id = ? AND id != ?", array($uid, $curSidAdm));
            } else {
                $db->exec("DELETE FROM sessions WHERE user_id = ?", array($uid));
            }
            api_ok(array('done' => true, 'sec_action' => 'revoke_sessions'));
        } elseif ($secAct === 'force_pw_reset') {
            if ($uid === $myId) {
                api_err('invalid_target', 'Cannot force password reset on your own active Super-Admin session.');
            }
            // Invalidate current password requiring Recovery Code, while strictly keeping 2FA (totp_secret) intact!
            $uFlReset = parse_json_col(isset($uTarget['flags']) ? $uTarget['flags'] : '', array());
            $uFlReset['force_pw_reset'] = 1;
            $db->exec("UPDATE users SET flags = ? WHERE id = ?", array(json_encode($uFlReset, JSON_UNESCAPED_UNICODE), $uid));
            $db->exec("DELETE FROM sessions WHERE user_id = ?", array($uid));
            api_ok(array('done' => true, 'sec_action' => 'force_pw_reset', 'totp_preserved' => !empty($uTarget['totp_secret']) ? 1 : 0));
        } elseif ($secAct === 'disable_2fa') {
            $uFlClean = parse_json_col(isset($uTarget['flags']) ? $uTarget['flags'] : '', array());
            $uFlClean['twofa_disabled'] = 1;
            unset($uFlClean['last_totp_sig']);
            $db->exec("UPDATE users SET totp_secret = NULL, flags = ? WHERE id = ?", array(json_encode($uFlClean, JSON_UNESCAPED_UNICODE), $uid));
            log_admin_audit($db, $myId, 'user_disable_2fa', array('user_id' => $uid));
            api_ok(array('done' => true, 'sec_action' => 'disable_2fa', 'totp_allowed' => 0));
        } elseif ($secAct === 'enable_2fa') {
            if (!twofa_globally_enabled($db)) {
                api_err('twofa_disabled_global', 'تأیید دو مرحله‌ای (2FA) در سطح کل پیام‌رسان غیرفعال است؛ ابتدا آن را فعال کنید. / Two-Factor Authentication is disabled messenger-wide; enable it first.');
            }
            $uFlOn = parse_json_col(isset($uTarget['flags']) ? $uTarget['flags'] : '', array());
            unset($uFlOn['twofa_disabled']);
            $db->exec("UPDATE users SET flags = ? WHERE id = ?", array(json_encode($uFlOn, JSON_UNESCAPED_UNICODE), $uid));
            log_admin_audit($db, $myId, 'user_enable_2fa', array('user_id' => $uid));
            api_ok(array('done' => true, 'sec_action' => 'enable_2fa', 'totp_allowed' => 1));
        } elseif ($secAct === 'clear_profile') {
            $db->exec("UPDATE users SET avatar = '', bio = '' WHERE id = ?", array($uid));
            bump_tick();
            api_ok(array('done' => true, 'sec_action' => 'clear_profile'));
        } else {
            api_err('invalid_action', 'Invalid security action.');
        }
    }

    if ($do === 'admin_global_security_action') {
        $globAct = isset($in['sec_action']) ? trim((string)$in['sec_action']) : '';
        $curSidAdm = isset($auth['session']['id']) ? (int)$auth['session']['id'] : 0;
        if ($globAct === 'keep_latest_sessions_all') {
            assert_session_revoke_grace($db, $auth);
            $uSessionOwners = $db->all("SELECT DISTINCT user_id FROM sessions");
            $removedCount = 0;
            foreach ($uSessionOwners as $uso) {
                $suid = (int)$uso['user_id'];
                if ($suid === $myId && $curSidAdm > 0) {
                    $removedCount += (int)$db->val("SELECT COUNT(*) FROM sessions WHERE user_id = ? AND id != ?", array($suid, $curSidAdm));
                    $db->exec("DELETE FROM sessions WHERE user_id = ? AND id != ?", array($suid, $curSidAdm));
                } else {
                    $latestSid = (int)$db->val("SELECT id FROM sessions WHERE user_id = ? ORDER BY created_at DESC, id DESC LIMIT 1", array($suid));
                    if ($latestSid > 0) {
                        $removedCount += (int)$db->val("SELECT COUNT(*) FROM sessions WHERE user_id = ? AND id != ?", array($suid, $latestSid));
                        $db->exec("DELETE FROM sessions WHERE user_id = ? AND id != ?", array($suid, $latestSid));
                    }
                }
            }
            api_ok(array('done' => true, 'sec_action' => $globAct, 'removed_sessions' => $removedCount));
        } elseif ($globAct === 'revoke_all_users_sessions') {
            // Revoke all sessions of all users EXCEPT Super-Admins!
            assert_session_revoke_grace($db, $auth);
            $nonSuperRows = $db->all("SELECT id FROM users WHERE role != 'superadmin'");
            $removedCount = 0;
            foreach ($nonSuperRows as $nsr) {
                $tuid = (int)$nsr['id'];
                $removedCount += (int)$db->val("SELECT COUNT(*) FROM sessions WHERE user_id = ?", array($tuid));
                $db->exec("DELETE FROM sessions WHERE user_id = ?", array($tuid));
            }
            api_ok(array('done' => true, 'sec_action' => $globAct, 'removed_sessions' => $removedCount));
        } elseif ($globAct === 'force_pw_reset_all_users') {
            // Force password reset on all users EXCEPT Super-Admins, strictly preserving 2FA (totp_secret)!
            $nonSuperUsers = $db->all("SELECT id, flags FROM users WHERE role != 'superadmin' AND status != 'deleted'");
            $affectedUsers = 0;
            $db->tx(function() use ($db, $nonSuperUsers, &$affectedUsers) {
                foreach ($nonSuperUsers as $nsu) {
                    $tuid = (int)$nsu['id'];
                    $fl = parse_json_col(isset($nsu['flags']) ? $nsu['flags'] : '', array());
                    $fl['force_pw_reset'] = 1;
                    $db->exec("UPDATE users SET flags = ? WHERE id = ?", array(json_encode($fl, JSON_UNESCAPED_UNICODE), $tuid));
                    $db->exec("DELETE FROM sessions WHERE user_id = ?", array($tuid));
                    $affectedUsers++;
                }
            });
            api_ok(array('done' => true, 'sec_action' => $globAct, 'affected_users' => $affectedUsers));
        } else {
            api_err('invalid_action', 'Invalid global security action.');
        }
    }

    if ($do === 'admin_firewall_stats') {
        api_ok(array(
            'stats'    => fw_get_stats($db),
            'settings' => array(
                'fw_enabled'          => (int)Settings::get($db, 'fw_enabled', 1) ? 1 : 0,
                'fw_captcha_enabled'  => (int)Settings::get($db, 'fw_captcha_enabled', 1) ? 1 : 0,
                'fw_honeypot_enabled' => (int)Settings::get($db, 'fw_honeypot_enabled', 1) ? 1 : 0,
                'fw_payload_shield'   => (int)Settings::get($db, 'fw_payload_shield', 1) ? 1 : 0,
                'fw_rate_limit_rpm'   => max(20, (int)Settings::get($db, 'fw_rate_limit_rpm', 180)),
                'fw_auth_limit_rpm'   => max(3, (int)Settings::get($db, 'fw_auth_limit_rpm', 20)),
                'fw_hp_field_name'    => fw_honeypot_field_name()
            )
        ));
    }

    if ($do === 'admin_firewall_reset') {
        $fresh = fw_reset_stats($db);
        api_ok(array('reset' => true, 'stats' => $fresh));
    }

    if ($do === 'admin_user_delete') {
        $uid = isset($in['user_id']) ? (int)$in['user_id'] : 0;
        $uDelTarget = $db->one("SELECT id, role, is_founder FROM users WHERE id = ?", array($uid));
        if (!$uDelTarget) api_err('not_found', 'User not found.');
        guard_superadmin_target($db, $auth, $uDelTarget);
        if ($uid === $myId) api_err('invalid_target', 'Cannot delete your own super-admin account here.');
        execute_account_deletion($db, $uid, 'transfer');
        log_admin_audit($db, $myId, 'user_delete', array('user_id' => $uid));
        api_ok(array('deleted' => true));
    }

    if ($do === 'admin_referral_tree') {
        $targetUid = isset($in['user_id']) ? (int)$in['user_id'] : 0;
        $users = $db->all(
            "SELECT u.id, u.username, u.name, u.role, u.status, u.invite_code, u.invited_by, u.created_at, p.username AS inviter_username
             FROM users u
             LEFT JOIN users p ON p.id = u.invited_by
             ORDER BY u.id ASC"
        );
        $nodes = array();
        foreach ($users as $u) {
            $uid = (int)$u['id'];
            $desc = get_referral_descendants($db, $uid);
            $nodes[] = array(
                'id'               => $uid,
                'username'         => $u['username'],
                'name'             => $u['name'],
                'role'             => $u['role'],
                'status'           => $u['status'],
                'invite_code'      => $u['invite_code'],
                'invited_by'       => $u['invited_by'] !== null ? (int)$u['invited_by'] : null,
                'inviter_username' => $u['inviter_username'],
                'direct_invitees_count'   => (int)$db->val("SELECT COUNT(*) FROM users WHERE invited_by = ?", array($uid)),
                'total_descendants_count' => count($desc),
                'descendant_count'        => count($desc),
                'created_at'              => (int)$u['created_at']
            );
        }
        $chainUp = $targetUid > 0 ? trace_referral_chain_up($db, $targetUid) : array();
        $branchIds = $targetUid > 0 ? get_referral_descendants($db, $targetUid) : array();
        api_ok(array(
            'nodes'      => $nodes,
            'chain_up'   => $chainUp,
            'branch_ids' => $branchIds
        ));
    }

    if ($do === 'admin_referral_branch_action') {
        $rootUid = isset($in['root_user_id']) ? (int)$in['root_user_id'] : (isset($in['user_id']) ? (int)$in['user_id'] : 0);
        $action  = isset($in['branch_action']) ? (string)$in['branch_action'] : 'block_branch';
        $includeRoot = !empty($in['include_root']);

        if ($rootUid <= 0) api_err('invalid_target', 'User ID required.');
        $descendants = get_referral_descendants($db, $rootUid);
        $descendants = array_reverse($descendants);
        if ($includeRoot) {
            $descendants[] = $rootUid;
        }
        $affected = 0;
        foreach ($descendants as $duid) {
            if ((int)$duid === $myId) continue;
            $targetRow = $db->one("SELECT role FROM users WHERE id = ?", array((int)$duid));
            if ($targetRow && $targetRow['role'] === 'superadmin') continue;

            if ($action === 'delete_branch') {
                execute_account_deletion($db, (int)$duid, 'transfer');
                $affected++;
            } elseif ($action === 'block_branch') {
                $db->exec("UPDATE users SET status = 'blocked' WHERE id = ?", array((int)$duid));
                $db->exec("DELETE FROM sessions WHERE user_id = ?", array((int)$duid));
                $affected++;
            } elseif ($action === 'unblock_branch') {
                $db->exec("UPDATE users SET status = 'active' WHERE id = ? AND status = 'blocked'", array((int)$duid));
                $affected++;
            }
        }
        log_admin_audit($db, $myId, 'referral_branch_' . $action, array('root_user_id' => $rootUid, 'affected' => $affected));
        bump_tick();
        api_ok(array('affected' => $affected, 'affected_count' => $affected, 'branch_ids' => $descendants));
    }

    if ($do === 'admin_invites_regenerate_all') {
        $count = regenerate_all_user_invite_codes($db);
        log_admin_audit($db, $myId, 'invites_regenerate_all', array('regenerated_users' => $count));
        $myNewCode = (string)$db->val("SELECT invite_code FROM users WHERE id = ?", array($myId));
        api_ok(array('regenerated_count' => $count, 'my_invite_code' => $myNewCode));
    }

    if ($do === 'admin_invitecodes_list' || $do === 'admin_invitecode_create' || $do === 'admin_invitecode_edit' || $do === 'admin_invitecode_delete') {
        if ($do === 'admin_invitecode_create') {
            $customCode = isset($in['code']) && trim((string)$in['code']) !== '' ? strtoupper(trim((string)$in['code'])) : random_invite_code('ADM-');
            $maxUses = isset($in['max_uses']) ? max(1, (int)$in['max_uses']) : 10;
            $expDays = isset($in['expires_days']) && (int)$in['expires_days'] > 0 ? (time() + ((int)$in['expires_days'] * 86400)) : null;
            $db->upsert('invite_codes', array(
                'code'       => $customCode,
                'created_by' => $myId,
                'max_uses'   => $maxUses,
                'uses_left'  => $maxUses,
                'expires_at' => $expDays,
                'created_at' => time()
            ), 'code');
            log_admin_audit($db, $myId, 'invitecode_create', $customCode);
        } elseif ($do === 'admin_invitecode_edit') {
            $code = isset($in['code']) ? strtoupper(trim((string)$in['code'])) : '';
            $usesLeft = isset($in['uses_left']) ? max(0, (int)$in['uses_left']) : 0;
            $maxUses  = isset($in['max_uses']) ? max(1, (int)$in['max_uses']) : max(1, $usesLeft);
            $db->exec("UPDATE invite_codes SET max_uses = ?, uses_left = ? WHERE code = ?", array($maxUses, $usesLeft, $code));
            log_admin_audit($db, $myId, 'invitecode_edit', $code);
        } elseif ($do === 'admin_invitecode_delete') {
            $code = isset($in['code']) ? strtoupper(trim((string)$in['code'])) : '';
            $db->exec("DELETE FROM invite_codes WHERE code = ?", array($code));
            log_admin_audit($db, $myId, 'invitecode_delete', $code);
        }
        $codes = $db->all("SELECT * FROM invite_codes ORDER BY created_at DESC");
        foreach ($codes as &$cRow) {
            $cRow['uses'] = max(0, (int)$cRow['max_uses'] - (int)$cRow['uses_left']);
        }
        api_ok(array('invite_codes' => $codes, 'invites' => $codes, 'code' => isset($customCode) ? $customCode : ''));
    }

    if ($do === 'admin_reports_list') {
        $statusFilter = isset($in['status']) ? trim((string)$in['status']) : '';
        $typeFilter   = isset($in['target_type']) ? trim((string)$in['target_type']) : '';
        $params = array();
        $sql = "SELECT r.*, u.username AS reporter_username, u.name AS reporter_name
                FROM reports r
                LEFT JOIN users u ON u.id = r.reporter_id
                WHERE 1=1";
        if ($statusFilter !== '' && in_array($statusFilter, array('pending', 'resolved', 'dismissed'), true)) {
            $sql .= " AND r.status = ?";
            $params[] = $statusFilter;
        }
        if ($typeFilter !== '' && in_array($typeFilter, array('user', 'group', 'channel', 'message'), true)) {
            $sql .= " AND r.target_type = ?";
            $params[] = $typeFilter;
        }
        $sql .= " ORDER BY r.id DESC";
        $rows = $db->all($sql, $params);
        foreach ($rows as &$r) {
            $r['id'] = (int)$r['id'];
            $r['target_id'] = (int)$r['target_id'];
            $r['target_summary'] = '';
            $r['target_username'] = '';
            $r['chat_id'] = 0;
            $r['can_ghost'] = 0;
            if ($r['target_type'] === 'user') {
                $tu = $db->one("SELECT username, name, status FROM users WHERE id = ?", array($r['target_id']));
                $r['target_summary'] = $tu ? ("@{$tu['username']} ({$tu['name']}) [{$tu['status']}]") : 'Deleted User';
                if ($tu && !empty($tu['username'])) $r['target_username'] = (string)$tu['username'];
            } elseif ($r['target_type'] === 'group' || $r['target_type'] === 'channel') {
                $tc = $db->one("SELECT id, type, title, handle, status FROM chats WHERE id = ?", array($r['target_id']));
                $r['target_summary'] = $tc ? ("{$tc['title']} (" . ($tc['handle'] ? "@{$tc['handle']}" : 'private') . ") [{$tc['status']}]") : 'Deleted Chat';
                if ($tc) {
                    $r['chat_id'] = (int)$tc['id'];
                    $r['can_ghost'] = 1;
                }
            } elseif ($r['target_type'] === 'message') {
                $tm = $db->one("SELECT m.body, m.user_id, m.chat_id, c.type AS chat_type, u.username FROM messages m LEFT JOIN users u ON u.id = m.user_id LEFT JOIN chats c ON c.id = m.chat_id WHERE m.id = ?", array($r['target_id']));
                $r['target_summary'] = $tm ? ("@{$tm['username']}: " . u_substr((string)$tm['body'], 0, 100)) : 'Deleted Message';
                if ($tm && !empty($tm['username'])) $r['target_username'] = (string)$tm['username'];
                if ($tm && !empty($tm['chat_id']) && $tm['chat_type'] !== 'secret') {
                    $r['chat_id'] = (int)$tm['chat_id'];
                    $r['can_ghost'] = 1;
                }
            }
        }
        api_ok(array('reports' => $rows));
    }

    if ($do === 'admin_report_action') {
        $act   = isset($in['report_action']) ? trim((string)$in['report_action']) : (isset($in['action']) ? trim((string)$in['action']) : 'resolve');
        if ($act === 'clear_handled') {
            $db->exec("DELETE FROM reports WHERE status IN ('resolved', 'dismissed')");
            bump_tick();
            api_ok(array('cleared' => true));
        }
        $repId = isset($in['report_id']) ? (int)$in['report_id'] : 0;
        if ($act === 'ban_target_user') $act = 'ban_target';
        $rep   = $db->one("SELECT * FROM reports WHERE id = ?", array($repId));
        if (!$rep) api_err('not_found', 'Report not found.');

        $tid = (int)$rep['target_id'];
        $ttype = $rep['target_type'];

        if ($act === 'delete_report') {
            $db->exec("DELETE FROM reports WHERE id = ?", array($repId));
            bump_tick();
            api_ok(array('deleted' => true));
        } elseif ($act === 'dismiss') {
            $db->exec("UPDATE reports SET status = 'dismissed' WHERE id = ?", array($repId));
        } elseif ($act === 'ban_target') {
            if ($ttype === 'user' && $tid !== $myId) {
                $db->exec("UPDATE users SET status = 'blocked' WHERE id = ?", array($tid));
                $db->exec("DELETE FROM sessions WHERE user_id = ?", array($tid));
            } elseif ($ttype === 'message') {
                $tm = $db->one("SELECT user_id FROM messages WHERE id = ?", array($tid));
                if ($tm && (int)$tm['user_id'] !== $myId) {
                    $db->exec("UPDATE users SET status = 'blocked' WHERE id = ?", array((int)$tm['user_id']));
                    $db->exec("DELETE FROM sessions WHERE user_id = ?", array((int)$tm['user_id']));
                }
            } elseif ($ttype === 'group' || $ttype === 'channel') {
                $db->exec("UPDATE chats SET status = 'blocked' WHERE id = ?", array($tid));
            }
            $db->exec("UPDATE reports SET status = 'resolved' WHERE id = ?", array($repId));
        } elseif ($act === 'delete_target') {
            if ($ttype === 'message') {
                $tMsg = $db->one("SELECT id, file_id FROM messages WHERE id = ?", array($tid));
                $db->exec("DELETE FROM reactions WHERE message_id = ?", array($tid));
                $db->exec("UPDATE messages SET deleted_at = ?, body = '', cipher = NULL, file_id = NULL WHERE id = ?", array(time(), $tid));
                if ($tMsg && !empty($tMsg['file_id'])) {
                    release_file_if_unreferenced($db, (int)$tMsg['file_id'], $tid);
                }
            } elseif ($ttype === 'group' || $ttype === 'channel') {
                $tChat = $db->one("SELECT id, is_default FROM chats WHERE id = ?", array($tid));
                if ($tChat && (int)$tChat['is_default'] === 0) {
                    delete_chat_completely($db, $tid);
                }
            } elseif ($ttype === 'user' && $tid !== $myId) {
                execute_account_deletion($db, $tid, 'transfer');
            }
            $db->exec("UPDATE reports SET status = 'resolved' WHERE id = ?", array($repId));
        } else {
            $db->exec("UPDATE reports SET status = 'resolved' WHERE id = ?", array($repId));
        }

        log_admin_audit($db, $myId, 'report_' . $act, array('report_id' => $repId, 'target_type' => $ttype, 'target_id' => $tid));
        bump_tick();
        api_ok(array('updated' => true));
    }

    if ($do === 'admin_default_chat_set') {
        $cid = isset($in['chat_id']) ? (int)$in['chat_id'] : 0;
        $isDef = !empty($in['is_default']) ? 1 : 0;
        $db->exec("UPDATE chats SET is_default = ? WHERE id = ?", array($isDef, $cid));
        log_admin_audit($db, $myId, 'default_chat_set', array('chat_id' => $cid, 'is_default' => $isDef));
        bump_tick();
        api_ok(array('updated' => true));
    }

    if ($do === 'admin_bulk_users') {
        $rawIds = isset($in['user_ids']) && is_array($in['user_ids']) ? $in['user_ids'] : array();
        $act = isset($in['bulk_action']) ? trim((string)$in['bulk_action']) : (isset($in['bulk_op']) ? trim((string)$in['bulk_op']) : '');
        $affected = 0;
        foreach ($rawIds as $ruid) {
            $uid = (int)$ruid;
            if ($uid <= 0) continue;
            $u = $db->one("SELECT * FROM users WHERE id = ?", array($uid));
            if (!$u || $u['status'] === 'deleted') continue;
            if (($act === 'block' || $act === 'delete') && $uid === $myId) continue;
            if ($act === 'block') {
                $db->exec("UPDATE users SET status = 'blocked' WHERE id = ?", array($uid));
                $db->exec("DELETE FROM sessions WHERE user_id = ?", array($uid));
                $affected++;
            } elseif ($act === 'unblock') {
                $db->exec("UPDATE users SET status = 'active' WHERE id = ?", array($uid));
                $affected++;
            } elseif ($act === 'mute_send' || $act === 'unmute_send') {
                $uf = parse_json_col($u['flags'], array());
                $uf['ban_send'] = ($act === 'mute_send') ? 1 : 0;
                $db->exec("UPDATE users SET flags = ? WHERE id = ?", array(json_encode($uf), $uid));
                $affected++;
            } elseif ($act === 'delete') {
                execute_account_deletion($db, $uid);
                $affected++;
            }
        }
        if ($affected > 0) bump_tick();
        api_ok(array('affected' => $affected, 'bulk_action' => $act));
    }

    if ($do === 'admin_bulk_chats') {
        $rawIds = isset($in['chat_ids']) && is_array($in['chat_ids']) ? $in['chat_ids'] : array();
        $act = isset($in['bulk_action']) ? trim((string)$in['bulk_action']) : (isset($in['bulk_op']) ? trim((string)$in['bulk_op']) : '');
        $affected = 0;
        foreach ($rawIds as $rcid) {
            $cid = (int)$rcid;
            if ($cid <= 0) continue;
            $tc = $db->one("SELECT id, is_default FROM chats WHERE id = ?", array($cid));
            if (!$tc) continue;
            if ($act === 'block') {
                $db->exec("UPDATE chats SET status = 'blocked' WHERE id = ?", array($cid));
                $affected++;
            } elseif ($act === 'unblock') {
                $db->exec("UPDATE chats SET status = 'active' WHERE id = ?", array($cid));
                $affected++;
            } elseif ($act === 'delete') {
                if ((int)$tc['is_default'] === 0) {
                    delete_chat_completely($db, $cid);
                    $affected++;
                }
            }
        }
        if ($affected > 0) bump_tick();
        api_ok(array('affected' => $affected, 'bulk_action' => $act));
    }

    if ($do === 'admin_dm_block_toggle') {
        $cid = isset($in['chat_id']) ? (int)$in['chat_id'] : 0;
        $tc = $db->one("SELECT id, type, status FROM chats WHERE id = ? AND type IN ('dm', 'secret')", array($cid));
        if (!$tc) api_err('not_found', 'Two-way chat not found.');
        if (isset($in['blocked'])) {
            $nextSt = ((int)$in['blocked'] === 1) ? 'blocked' : 'active';
        } elseif (isset($in['status'])) {
            $nextSt = ($in['status'] === 'blocked') ? 'blocked' : 'active';
        } else {
            $nextSt = ($tc['status'] === 'blocked') ? 'active' : 'blocked';
        }
        $db->exec("UPDATE chats SET status = ? WHERE id = ?", array($nextSt, $cid));
        bump_tick();
        api_ok(array('chat_id' => $cid, 'status' => $nextSt));
    }

    if ($do === 'admin_chats_list' || $do === 'admin_chat_block' || $do === 'admin_chat_delete') {
        if ($do === 'admin_chat_block') {
            $cid = isset($in['chat_id']) ? (int)$in['chat_id'] : 0;
            $st  = isset($in['status']) && $in['status'] === 'blocked' ? 'blocked' : 'active';
            $db->exec("UPDATE chats SET status = ? WHERE id = ?", array($st, $cid));
            log_admin_audit($db, $myId, 'chat_status_' . $st, $cid);
            bump_tick();
        } elseif ($do === 'admin_chat_delete') {
            $cid = isset($in['chat_id']) ? (int)$in['chat_id'] : 0;
            $tChat = $db->one("SELECT id, is_default FROM chats WHERE id = ?", array($cid));
            if ($tChat && (int)$tChat['is_default'] === 0) {
                delete_chat_completely($db, $cid);
            }
            log_admin_audit($db, $myId, 'chat_delete', $cid);
            bump_tick();
        }
        $filterType = isset($in['filter_type']) ? trim((string)$in['filter_type']) : (isset($in['chat_type']) ? trim((string)$in['chat_type']) : '');
        if ($filterType === 'dm_all' || $filterType === 'dm_chats') {
            $rows = $db->all(
                "SELECT c.*,
                        (SELECT COUNT(*) FROM messages mm WHERE mm.chat_id = c.id AND mm.deleted_at IS NULL) AS msg_count
                 FROM chats c WHERE c.type IN ('dm', 'secret') ORDER BY c.id DESC"
            );
            foreach ($rows as &$dmRow) {
                $pRows = $db->all(
                    "SELECT u.id, u.name, u.username, u.flags, u.status
                     FROM members m JOIN users u ON u.id = m.user_id
                     WHERE m.chat_id = ? ORDER BY m.user_id ASC",
                    array((int)$dmRow['id'])
                );
                $parts = array();
                $names = array();
                foreach ($pRows as $pr) {
                    $pf = get_user_flags($pr);
                    $pubU = !empty($pf['no_username']) ? '' : (string)$pr['username'];
                    $parts[] = array(
                        'id'             => (int)$pr['id'],
                        'name'           => (string)$pr['name'],
                        'username'       => $pubU,
                        'login_username' => (string)$pr['username'],
                        'no_username'    => !empty($pf['no_username']) ? 1 : 0,
                        'status'         => (string)$pr['status']
                    );
                    $names[] = (string)$pr['name'];
                }
                $pairTitle = !empty($names) ? implode(' ↔ ', $names) : ('Chat #' . (int)$dmRow['id']);
                $dmRow['participants'] = $parts;
                $dmRow['pair_title'] = $pairTitle;
                $dmRow['dm_title'] = $pairTitle;
                $dmRow['can_ghost'] = ($dmRow['type'] === 'dm') ? 1 : 0;
            }
            unset($dmRow);
            api_ok(array('chats' => $rows));
        } elseif ($filterType === 'group' || $filterType === 'channel') {
            $rows = $db->all(
                "SELECT c.*,
                        (SELECT u.username FROM users u WHERE u.id = c.owner_id) AS owner_username,
                        (SELECT COUNT(*) FROM members m WHERE m.chat_id = c.id AND m.role != 'pending') AS member_count,
                        (SELECT COUNT(*) FROM members pm WHERE pm.chat_id = c.id AND pm.user_id = ? AND pm.role != 'pending') AS am_member
                 FROM chats c WHERE c.type = ? ORDER BY c.is_default DESC, c.id DESC",
                array($myId, $filterType)
            );
            foreach ($rows as &$gcRow) {
                $gcPerms = parse_json_col(isset($gcRow['perms_json']) ? $gcRow['perms_json'] : '', array());
                $gcRow['msg_viewers_mode'] = normalize_msg_viewers_value(isset($gcPerms['msg_viewers_mode']) ? $gcPerms['msg_viewers_mode'] : 'default', 'chat');
                $gcRow['super_msg_viewers_override'] = normalize_msg_viewers_value(isset($gcPerms['super_msg_viewers_override']) ? $gcPerms['super_msg_viewers_override'] : 'inherit', 'super_chat');
                $gcCap = resolve_chat_member_capacity($db, $gcRow);
                $gcRow['effective_max_members'] = (int)$gcCap['effective_max'];
                $gcRow['super_max_members'] = (int)$gcCap['super_override'];
                $gcRow['superadmin_ceiling'] = (int)$gcCap['super_ceiling'];
                // Let the panel show the per-chat override switches in their real
                // position instead of always looking "on".
                $gcRow['preview_forced_off'] = in_array((int)$gcRow['id'], get_global_off_chat_ids($db, 'chat_preview_off_chats'), true) ? 1 : 0;
                $gcRow['views_forced_off']   = in_array((int)$gcRow['id'], get_global_off_chat_ids($db, 'msg_views_off_chats'), true) ? 1 : 0;
            }
            unset($gcRow);
            api_ok(array('chats' => $rows));
        } else {
            $rows = $db->all(
                "SELECT c.*,
                        (SELECT u.username FROM users u WHERE u.id = c.owner_id) AS owner_username,
                        (SELECT COUNT(*) FROM members m WHERE m.chat_id = c.id AND m.role != 'pending') AS member_count,
                        (SELECT COUNT(*) FROM members pm WHERE pm.chat_id = ? AND pm.user_id = ? AND pm.role != 'pending') AS am_member
                 FROM chats c WHERE c.type IN ('group', 'channel') ORDER BY c.is_default DESC, c.id DESC",
                array(0, $myId)
            );
            foreach ($rows as &$gcRow) {
                $gcRow['am_member'] = (int)$db->val("SELECT COUNT(*) FROM members pm WHERE pm.chat_id = ? AND pm.user_id = ? AND pm.role != 'pending'", array((int)$gcRow['id'], $myId));
                $gcPerms = parse_json_col(isset($gcRow['perms_json']) ? $gcRow['perms_json'] : '', array());
                $gcRow['msg_viewers_mode'] = normalize_msg_viewers_value(isset($gcPerms['msg_viewers_mode']) ? $gcPerms['msg_viewers_mode'] : 'default', 'chat');
                $gcRow['super_msg_viewers_override'] = normalize_msg_viewers_value(isset($gcPerms['super_msg_viewers_override']) ? $gcPerms['super_msg_viewers_override'] : 'inherit', 'super_chat');
                $gcCap = resolve_chat_member_capacity($db, $gcRow);
                $gcRow['effective_max_members'] = (int)$gcCap['effective_max'];
                $gcRow['super_max_members'] = (int)$gcCap['super_override'];
                $gcRow['superadmin_ceiling'] = (int)$gcCap['super_ceiling'];
                // Let the panel show the per-chat override switches in their real
                // position instead of always looking "on".
                $gcRow['preview_forced_off'] = in_array((int)$gcRow['id'], get_global_off_chat_ids($db, 'chat_preview_off_chats'), true) ? 1 : 0;
                $gcRow['views_forced_off']   = in_array((int)$gcRow['id'], get_global_off_chat_ids($db, 'msg_views_off_chats'), true) ? 1 : 0;
            }
            unset($gcRow);
            api_ok(array('chats' => $rows));
        }
    }

    if ($do === 'admin_chat_capacity_override') {
        $cid = isset($in['chat_id']) ? (int)$in['chat_id'] : 0;
        $chat = $db->one("SELECT * FROM chats WHERE id = ? AND type IN ('group', 'channel')", array($cid));
        if (!$chat) api_err('not_found', 'Group or channel not found.');
        $curPerms = parse_json_col(isset($chat['perms_json']) ? $chat['perms_json'] : '', array());
        $smm = isset($in['super_max_members']) ? (int)$in['super_max_members'] : 0;
        $curPerms['super_max_members'] = ($smm === -1) ? -1 : (($smm <= 0) ? 0 : max(2, min(1000000, $smm)));
        $nextChatMax = isset($in['max_members']) ? max(0, min(1000000, (int)$in['max_members'])) : (int)$chat['max_members'];
        $db->exec("UPDATE chats SET max_members = ?, perms_json = ? WHERE id = ?", array($nextChatMax, json_encode($curPerms), $cid));
        bump_tick();
        $updChat = $db->one("SELECT * FROM chats WHERE id = ?", array($cid));
        $capNow = resolve_chat_member_capacity($db, $updChat);
        api_ok(array(
            'chat_id'               => $cid,
            'max_members'           => (int)$updChat['max_members'],
            'super_max_members'     => (int)$capNow['super_override'],
            'superadmin_ceiling'    => (int)$capNow['super_ceiling'],
            'effective_max_members' => (int)$capNow['effective_max']
        ));
    }

    if ($do === 'admin_chat_viewers_override') {
        $cid = isset($in['chat_id']) ? (int)$in['chat_id'] : 0;
        $chat = $db->one("SELECT * FROM chats WHERE id = ? AND type IN ('group', 'channel')", array($cid));
        if (!$chat) api_err('not_found', 'Group or channel not found.');
        $curPerms = parse_json_col(isset($chat['perms_json']) ? $chat['perms_json'] : '', array());
        if (isset($in['super_msg_viewers_override'])) {
            $curPerms['super_msg_viewers_override'] = normalize_msg_viewers_value($in['super_msg_viewers_override'], 'super_chat');
        }
        if (isset($in['msg_viewers_mode'])) {
            $curPerms['msg_viewers_mode'] = normalize_msg_viewers_value($in['msg_viewers_mode'], 'chat');
        }
        $db->exec("UPDATE chats SET perms_json = ? WHERE id = ?", array(json_encode($curPerms), $cid));
        bump_tick();
        api_ok(array(
            'chat_id'                    => $cid,
            'msg_viewers_mode'           => normalize_msg_viewers_value(isset($curPerms['msg_viewers_mode']) ? $curPerms['msg_viewers_mode'] : 'default', 'chat'),
            'super_msg_viewers_override' => normalize_msg_viewers_value(isset($curPerms['super_msg_viewers_override']) ? $curPerms['super_msg_viewers_override'] : 'inherit', 'super_chat')
        ));
    }

    if ($do === 'admin_ghost_open') {
        $cid = isset($in['chat_id']) ? (int)$in['chat_id'] : 0;
        $chat = $db->one("SELECT * FROM chats WHERE id = ?", array($cid));
        if (!$chat) {
            api_err('not_found', 'Chat not found.');
        }
        if ($chat['type'] === 'secret') {
            api_err('secret_ghost_forbidden', 'امکان مشاهده روح برای گفتگوی محرمانه (Secret Chat) وجود ندارد. / Ghost view is strictly forbidden for Secret Chats.');
        }
        if (!in_array($chat['type'], array('group', 'channel', 'dm'), true)) {
            api_err('not_found', 'Unsupported chat type for ghost view.');
        }
        $mem = $db->one("SELECT * FROM members WHERE chat_id = ? AND user_id = ? AND role != 'pending'", array($cid, $myId));
        if ($mem) {
            $merged = array_merge($chat, array(
                'my_role'            => $mem['role'],
                'my_perms'           => $mem['perms_json'],
                'joined_msg_id'      => 0,
                'last_read_id'       => (int)$mem['last_read_id'],
                'receipt_read_id'    => (int)$mem['receipt_read_id'],
                'pinned_msg_id'      => (int)$mem['pinned_msg_id'],
                'my_auto_delete_sec' => (int)$mem['auto_delete_sec'],
                'muted'              => (int)$mem['muted'],
                'pinned_at'          => (int)$mem['pinned_at'],
                'banned_until'       => null,
                'restricted_until'   => null
            ));
            $desc = build_single_chat_descriptor($db, $merged, $me, false);
        } else {
            $merged = array_merge($chat, array(
                'my_role'            => 'ghost',
                'my_perms'           => '{}',
                'joined_msg_id'      => 0,
                'last_read_id'       => 0,
                'receipt_read_id'    => 0,
                'pinned_msg_id'      => 0,
                'my_auto_delete_sec' => 0,
                'muted'              => 0,
                'pinned_at'          => 0,
                'banned_until'       => null,
                'restricted_until'   => null
            ));
            $desc = build_single_chat_descriptor($db, $merged, $me, true);
        }
        api_ok(array('chat' => $desc));
    }

    if ($do === 'admin_audit') {
        api_ok(array('audit' => array(), 'logs' => array()));
    }

    if ($do === 'admin_health') {
        $env = check_environment();
        $env['data_dir_exists'] = is_dir(DATA_DIR);
        $env['files_dir_writable'] = is_writable(FILES_DIR);
        $env['htaccess_exists'] = file_exists(DATA_DIR . '/.htaccess');
        $env['zero_log_active'] = !((bool)ini_get('log_errors'));
        api_ok(array(
            'health'              => $env,
            'php_version'         => PHP_VERSION,
            'db_driver'           => $db->driver(),
            'data_dir_writable'   => is_writable(DATA_DIR),
            'files_dir_writable'  => is_writable(FILES_DIR),
            'htaccess_exists'     => file_exists(DATA_DIR . '/.htaccess'),
            'zero_log_active'     => !((bool)ini_get('log_errors')),
            'openssl_ok'          => extension_loaded('openssl'),
            'disk_free_bytes'     => (int)@disk_free_space(DATA_DIR),
            'disk_total_bytes'    => (int)@disk_total_space(DATA_DIR),
            'memory_usage_bytes'  => (int)memory_get_usage(true),
            'memory_limit'        => (string)ini_get('memory_limit'),
            'upload_max_filesize' => (string)ini_get('upload_max_filesize'),
            'schema_target_version'  => SCHEMA_TARGET_VERSION,
            'schema_current_version' => (int)$db->val("SELECT v FROM meta WHERE k = 'schema_ver'"),
            'schema_pending'         => m3_schema_pending(),
            // True when the engine lets us read the live schema, i.e. when backup,
            // restore and driver migration use the real columns instead of the
            // hard-coded fallback list.
            'schema_columns_derived' => !empty($db->tableColumns('members')) ? 1 : 0,
            // The marker says "up to date" but columns are actually absent: an explicit
            // repair is then the only way forward.
            'schema_missing_columns' => m3_schema_missing_columns($db),
            'schema_needs_repair'    => !empty(m3_schema_missing_columns($db)) ? 1 : 0
        ));
    }

    if ($do === 'admin_schema_repair') {
        $rep = m3_schema_repair($db);
        api_ok(array(
            'schema_target_version'  => SCHEMA_TARGET_VERSION,
            'schema_current_version' => (int)$db->val("SELECT v FROM meta WHERE k = 'schema_ver'"),
            'needed'                 => $rep['needed'] ? 1 : 0,
            'missing_before'         => $rep['missing_before'],
            'repaired'               => $rep['repaired'],
            'failed'                 => $rep['failed']
        ));
    }

    if ($do === 'admin_backup') {
        $dump = array(
            'version'     => APP_VERSION,
            'exported_at' => time(),
            'settings'    => $db->all("SELECT * FROM settings"),
            'users'       => $db->all("SELECT id, username, name, bio, role, status, show_admin_badge, invite_code, invited_by, created_at FROM users"),
            'chats'       => $db->all("SELECT * FROM chats"),
            'members'     => $db->all("SELECT * FROM members"),
            'invite_codes'=> $db->all("SELECT * FROM invite_codes"),
            'reports'     => $db->all("SELECT * FROM reports")
        );
        // Deliberately explicit: this endpoint carries no messages and no files, so it
        // must never be mistaken for a restorable backup. Use admin_backup_download
        // (format M3BK0001) for a real one.
        api_ok(array(
            'backup'         => $dump,
            'partial'        => true,
            'restorable'     => false,
            'included'       => array('settings', 'users', 'chats', 'members', 'invite_codes', 'reports'),
            'missing_tables' => array('messages', 'files', 'message_reads', 'reactions', 'invites', 'blocks')
        ));
    }

    if ($do === 'admin_backup_download') {
        $bMode = isset($in['mode']) ? trim((string)$in['mode']) : (isset($_GET['mode']) ? trim((string)$_GET['mode']) : 'full');
        if (!in_array($bMode, array('db', 'files', 'full'), true)) {
            api_err('invalid_backup_mode', 'Invalid backup mode.');
        }
        stream_m3_backup_archive($db, $bMode);
    }

    if ($do === 'admin_backup_upload_chunk') {
        $upId = isset($_GET['upload_id']) ? trim((string)$_GET['upload_id']) : '';
        $chunkIdx = isset($_GET['chunk_index']) ? (int)$_GET['chunk_index'] : -1;
        if (!preg_match('/^[a-f0-9]{24,64}$/', $upId) || $chunkIdx < 0) {
            api_err('invalid_chunk_params', 'Invalid backup chunk parameters.');
        }
        $chunkLen = strlen((string)$rawInput);
        if ($chunkLen <= 0 || $chunkLen > 2 * 1048576) {
            api_err('invalid_chunk_size', 'Invalid backup chunk size.');
        }
        ensure_data_dirs();
        $partPath = DATA_DIR . '/restore_tmp_' . $upId . '.part';
        if ($chunkIdx === 0 && file_exists($partPath)) {
            @unlink($partPath);
        }
        $curBytes = ($chunkIdx === 0 || !file_exists($partPath)) ? 0 : (int)@filesize($partPath);
        if (($curBytes + $chunkLen) > 512 * 1048576) {
            if (file_exists($partPath)) @unlink($partPath);
            api_err('backup_too_large', 'حجم فایل پشتیبان بیش از سقف مجاز است / Backup archive exceeds maximum allowed size.');
        }
        $freeB = (int)@disk_free_space(DATA_DIR);
        if ($freeB > 0 && ($chunkLen * 2 + 8 * 1048576) > $freeB) {
            if (file_exists($partPath)) @unlink($partPath);
            api_err('disk_full', 'فضای کافی روی دیسک سرور برای دریافت بکاپ وجود ندارد / Insufficient server disk space.');
        }
        $fp = @fopen($partPath, $chunkIdx === 0 ? 'wb' : 'ab');
        if (!$fp) {
            api_err('upload_save_failed', 'Could not write backup chunk.');
        }
        $written = @fwrite($fp, (string)$rawInput);
        @fclose($fp);
        if ($written !== $chunkLen) {
            @unlink($partPath);
            api_err('upload_save_failed', 'Incomplete backup chunk write.');
        }
        api_ok(array('upload_id' => $upId, 'received_bytes' => $curBytes + $chunkLen));
    }

    if ($do === 'admin_backup_restore') {
        $upId = isset($in['upload_id']) ? trim((string)$in['upload_id']) : '';
        $rMode = isset($in['restore_mode']) ? trim((string)$in['restore_mode']) : 'full';
        if (!preg_match('/^[a-f0-9]{24,64}$/', $upId)) {
            api_err('invalid_upload_id', 'Invalid restore upload ID.');
        }
        if (!in_array($rMode, array('db', 'files', 'full'), true)) {
            api_err('invalid_restore_mode', 'Invalid restore mode.');
        }
        $partPath = DATA_DIR . '/restore_tmp_' . $upId . '.part';
        if (!is_file($partPath)) {
            api_err('backup_not_found', 'فایل پشتیبان بارگذاری‌شده یافت نشد / Uploaded backup file not found.');
        }
        $res = verify_and_restore_m3_backup($db, $partPath, $rMode, $auth);
        @unlink($partPath);
        if (empty($res['ok'])) {
            api_err(isset($res['error']) ? $res['error'] : 'restore_failed', isset($res['message']) ? $res['message'] : 'Restore failed.');
        }
        api_ok($res);
    }

    if ($do === 'admin_files_purge_older') {
        $amount = isset($in['amount']) ? max(0, (float)$in['amount']) : 24;
        $unit = (isset($in['unit']) && $in['unit'] === 'days') ? 'days' : 'hours';
        $sec = ($unit === 'days') ? (int)round($amount * 86400) : (int)round($amount * 3600);
        $res = purge_files_older_than_seconds($db, $sec);
        $remBytes = (int)$db->val("SELECT COALESCE(SUM(size), 0) FROM files");
        log_admin_audit($db, $myId, 'files_manual_purge', array('amount' => $amount, 'unit' => $unit, 'deleted' => $res['deleted_count'], 'freed_bytes' => $res['freed_bytes']));
        api_ok(array(
            'deleted_count'    => $res['deleted_count'],
            'freed_bytes'      => $res['freed_bytes'],
            'disk_usage_bytes' => $remBytes
        ));
    }

    if ($do === 'admin_messenger_schedule_wipe') {
        $amount = isset($in['amount']) ? (float)$in['amount'] : (isset($in['delay_hours']) ? (float)$in['delay_hours'] : 24);
        $unit = (isset($in['unit']) && $in['unit'] === 'days') ? 'days' : 'hours';
        $sec = ($unit === 'days') ? (int)round($amount * 86400) : (int)round($amount * 3600);
        if ($sec < 60) $sec = 60;
        $targetTs = time() + $sec;
        Settings::set($db, 'messenger_delete_at', $targetTs);
        log_admin_audit($db, $myId, 'messenger_wipe_scheduled', array('delete_at' => $targetTs));
        bump_tick();
        api_ok(array('messenger_delete_at' => $targetTs));
    }

    if ($do === 'admin_messenger_cancel_wipe') {
        Settings::set($db, 'messenger_delete_at', 0);
        log_admin_audit($db, $myId, 'messenger_wipe_cancelled', array());
        bump_tick();
        api_ok(array('messenger_delete_at' => 0));
    }

    if ($do === 'admin_messenger_hard_reset') {
        if (empty($in['confirmed'])) {
            $pw = isset($in['password']) ? (string)$in['password'] : '';
            if ($pw === '' || !password_verify($pw, (string)$me['pass_hash'])) {
                api_err('confirmation_required', 'تیک تایید الزامی است / Confirmation checkbox is required.');
            }
        }
        // Factory Hard Reset: wipe all runtime data, DB, files, sessions & config, keeping index.php so First-Run Installer loads!
        execute_full_messenger_wipe($db, false);
        json_out(array('ok' => true, 'data' => array('hard_reset' => true, 'redirect_install' => true), 'tick' => '0'), 200);
    }

    if ($do === 'admin_panic_duress_set') {
        if (rate_get_attempts($db, 'adm_panic_duress', (string)$myId, 600) >= 8) {
            api_err('rate_limited', 'Too many password attempts. Please wait 10 minutes.');
        }
        $curPass = isset($in['current_password']) ? (string)$in['current_password'] : '';
        if (!password_verify($curPass, (string)$me['pass_hash'])) {
            rate_hit($db, 'adm_panic_duress', (string)$myId, 600);
            api_err('wrong_password', 'Current admin password is incorrect.');
        }
        if (!empty($in['remove'])) {
            rate_clear($db, 'adm_panic_duress', (string)$myId);
            Settings::set($db, 'panic_duress_pass_hash', '');
            api_ok(array('has_panic_duress_password' => 0));
        }
        $dp = isset($in['duress_password']) ? (string)$in['duress_password'] : '';
        $dpConfirm = array_key_exists('duress_password_confirm', $in) ? (string)$in['duress_password_confirm'] : '';
        if (strlen($dp) < 6) {
            api_err('weak_password', 'Panic duress password must be at least 6 characters.');
        }
        if ($dp !== $dpConfirm) {
            api_err('password_mismatch', 'رمز جعلی تخریب اضطراری و تکرار آن یکسان نیستند. / Panic duress password and confirmation do not match.');
        }
        if (password_verify($dp, (string)$me['pass_hash'])) {
            api_err('duress_conflict', 'رمز جعلی تخریب اضطراری نمی‌تواند با رمز عبور اصلی شما یکسان باشد. / Panic duress password cannot match your login password.');
        }
        if (!empty($me['lock_pass_hash']) && password_verify($dp, (string)$me['lock_pass_hash'])) {
            api_err('duress_conflict', 'رمز جعلی تخریب اضطراری نمی‌تواند با رمز قفل صفحه شما یکسان باشد. / Panic duress password cannot match your lock password.');
        }
        rate_clear($db, 'adm_panic_duress', (string)$myId);
        Settings::set($db, 'panic_duress_pass_hash', password_hash($dp, PASSWORD_DEFAULT));
        $sharedWithAccount = (!empty($me['duress_pass_hash']) && password_verify($dp, (string)$me['duress_pass_hash'])) ? 1 : 0;
        api_ok(array(
            'has_panic_duress_password'    => 1,
            'shared_with_account_priority' => $sharedWithAccount,
            'shared_with_account_duress'   => $sharedWithAccount
        ));
    }

    if ($do === 'admin_db_migrate_status') {
        $env = check_environment();
        $curCfg = load_app_config();
        $curDriver = $db->driver();
        $tableCounts = array();
        foreach (array_keys(m3_backup_table_columns($db)) as $tb) {
            $tableCounts[$tb] = (int)$db->val("SELECT COUNT(*) FROM {$tb}");
        }
        $tableCounts['sessions'] = (int)$db->val("SELECT COUNT(*) FROM sessions");
        $hasSq = !empty($env['has_sqlite']) ? 1 : 0;
        $hasMy = !empty($env['has_mysql']) ? 1 : 0;
        $sqFileLabel = ($curCfg && !empty($curCfg['db_path']))
            ? basename((string)$curCfg['db_path'])
            : (($curCfg && !empty($curCfg['db_file'])) ? basename((string)$curCfg['db_file']) : 'chat_data/*.sqlite');
        api_ok(array(
            'current_driver' => $curDriver,
            'has_sqlite'     => $hasSq,
            'has_sqlite_pdo' => $hasSq,
            'has_mysql'      => $hasMy,
            'has_mysql_pdo'  => $hasMy,
            'sqlite_file'    => $sqFileLabel,
            'writable'       => !empty($env['writable']) ? 1 : 0,
            'mysql_host'     => ($curCfg && isset($curCfg['db_host'])) ? (string)$curCfg['db_host'] : '127.0.0.1',
            'mysql_port'     => ($curCfg && isset($curCfg['db_port'])) ? (int)$curCfg['db_port'] : 3306,
            'mysql_name'     => ($curCfg && isset($curCfg['db_name'])) ? (string)$curCfg['db_name'] : 'messenger',
            'mysql_user'     => ($curCfg && isset($curCfg['db_user'])) ? (string)$curCfg['db_user'] : '',
            'table_counts'   => $tableCounts
        ));
    }

    if ($do === 'admin_db_migrate_test' || $do === 'admin_db_migrate_run') {
        $env = check_environment();
        $curCfg = load_app_config();
        if (!is_array($curCfg)) api_err('config_error', 'Active configuration could not be read.');
        $curDriver = $db->driver();
        $targetDriver = isset($in['target_driver']) && in_array($in['target_driver'], array('sqlite', 'mysql'), true)
            ? $in['target_driver']
            : ($curDriver === 'sqlite' ? 'mysql' : 'sqlite');

        if ($targetDriver === 'sqlite' && empty($env['has_sqlite'])) {
            api_err('driver_missing', 'افزونه PDO SQLite روی سرور فعال نیست. / PDO SQLite extension is not enabled on this server.');
        }
        if ($targetDriver === 'mysql' && empty($env['has_mysql'])) {
            api_err('driver_missing', 'افزونه PDO MySQL / MariaDB روی سرور فعال نیست. / PDO MySQL/MariaDB extension is not enabled on this server.');
        }

        $targetCfg = $curCfg;
        $tempSqlitePath = '';
        if ($targetDriver === 'mysql') {
            $mHost = isset($in['db_host']) ? trim((string)$in['db_host']) : '127.0.0.1';
            $mPort = isset($in['db_port']) ? max(1, min(65535, (int)$in['db_port'])) : 3306;
            $mName = isset($in['db_name']) ? trim((string)$in['db_name']) : '';
            $mUser = isset($in['db_user']) ? trim((string)$in['db_user']) : '';
            $mPass = isset($in['db_pass']) ? (string)$in['db_pass'] : '';
            if ($mHost === '' || $mName === '' || $mUser === '') {
                api_err('invalid_db_params', 'لطفاً مشخصات اتصال MariaDB / MySQL (میزبان، نام پایگاه‌داده و نام کاربری) را کامل وارد کنید. / Please provide host, database name, and username.');
            }
            if (!preg_match('/^[A-Za-z0-9.\-:\[\]]+$/', $mHost) || !preg_match('/^[A-Za-z0-9_\-]+$/', $mName)) {
                api_err('invalid_db_params', 'فرمت نشانی میزبان یا نام پایگاه‌داده معتبر نیست. / Invalid database host or name format.');
            }
            if ($curDriver === 'mysql'
                && isset($curCfg['db_host'], $curCfg['db_port'], $curCfg['db_name'])
                && strtolower($mHost) === strtolower((string)$curCfg['db_host'])
                && (int)$mPort === (int)$curCfg['db_port']
                && $mName === (string)$curCfg['db_name']) {
                api_err('same_database', 'پایگاه‌داده مقصد نمی‌تواند دقیقاً همان پایگاه‌داده فعال فعلی باشد. / Target database cannot be the exact same active database.');
            }
            $targetCfg['db_driver'] = 'mysql';
            $targetCfg['db_host']   = $mHost;
            $targetCfg['db_port']   = $mPort;
            $targetCfg['db_name']   = $mName;
            $targetCfg['db_user']   = $mUser;
            $targetCfg['db_pass']   = $mPass;
            unset($targetCfg['sqlite_file'], $targetCfg['db_path']);
        } else {
            ensure_data_dirs();
            if (!is_writable(DATA_DIR)) {
                api_err('not_writable', 'پوشه chat_data برای ساخت پایگاه‌داده SQLite قابل نوشتن نیست. / chat_data directory is not writable.');
            }
            if ($curDriver === 'sqlite' && $do === 'admin_db_migrate_run') {
                api_err('same_database', 'پایگاه‌داده فعلی هم‌اکنون SQLite است. / Current database engine is already SQLite.');
            }
            $newSqName = 'db_' . bin2hex(random_bytes_safe(24)) . '.sqlite';
            $tempSqlitePath = DATA_DIR . '/' . $newSqName;
            $targetCfg['db_driver']   = 'sqlite';
            $targetCfg['db_path']     = $tempSqlitePath;
            $targetCfg['sqlite_file'] = $newSqName;
            unset($targetCfg['db_host'], $targetCfg['db_port'], $targetCfg['db_name'], $targetCfg['db_user'], $targetCfg['db_pass']);
        }

        if ($do === 'admin_db_migrate_test') {
            try {
                if ($targetDriver === 'mysql') {
                    $testDsn = sprintf('mysql:host=%s;port=%d;dbname=%s;charset=utf8mb4', $targetCfg['db_host'], $targetCfg['db_port'], $targetCfg['db_name']);
                    $tPdo = new PDO($testDsn, $targetCfg['db_user'], $targetCfg['db_pass'], array(
                        PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION,
                        PDO::ATTR_TIMEOUT => 5
                    ));
                    $srvVer = (string)$tPdo->query("SELECT VERSION()")->fetchColumn();
                    $tPdo = null;
                    api_ok(array('reachable' => true, 'target_driver' => 'mysql', 'server_version' => $srvVer));
                } else {
                    $testFile = DATA_DIR . '/mig_probe_' . bin2hex(random_bytes_safe(6)) . '.sqlite';
                    $tPdo = new PDO('sqlite:' . $testFile);
                    $srvVer = (string)$tPdo->query("SELECT sqlite_version()")->fetchColumn();
                    $tPdo = null;
                    @unlink($testFile);
                    api_ok(array('reachable' => true, 'target_driver' => 'sqlite', 'server_version' => 'SQLite ' . $srvVer));
                }
            } catch (Exception $e) {
                api_err('db_connect_failed', 'اتصال به پایگاه‌داده مقصد برقرار نشد: ' . $e->getMessage() . ' / Target DB connection failed: ' . $e->getMessage());
            }
        }

        // Execute Full Live Bidirectional Migration
        if (empty($in['confirmed'])) {
            api_err('confirmation_required', 'تیک تایید مهاجرت الزامی است. / Confirmation checkbox is required.');
        }
        $removeOldSqlite = !empty($in['remove_old_sqlite']);
        $oldSqlitePath = ($curDriver === 'sqlite') ? $db->sqlitePath() : '';

        @set_time_limit(300);
        ensure_data_dirs();
        $migLock = @fopen(DATA_DIR . '/db_migration.lck', 'c+');
        if ($migLock && !@flock($migLock, LOCK_EX | LOCK_NB)) {
            @fclose($migLock);
            api_err('migration_busy', 'یک عملیات مهاجرت دیگر هم‌اکنون در حال اجرا است. / Another database migration is already running.');
        }

        try {
            $targetDb = new DB($targetCfg);
            ensure_schema($targetDb);

            $migSchema = m3_backup_table_columns($db);
            $migSchema['meta']     = m3_schema_columns_for($db, 'meta', array('k', 'v'));
            $migSchema['sessions'] = m3_schema_columns_for($db, 'sessions', array('id', 'user_id', 'token_hash', 'csrf_token', 'created_at', 'last_used_bucket', 'device_label', 'expires_at', 'is_locked', 'is_persistent'));

            $orderedTables = array('meta', 'settings', 'users', 'sessions', 'chats', 'members', 'files', 'messages', 'message_reads', 'invites', 'invite_codes', 'blocks', 'reactions', 'reports');
            $tPdo = $targetDb->pdo();

            if ($targetDriver === 'mysql') {
                $tPdo->exec("SET FOREIGN_KEY_CHECKS = 0");
            } else {
                $tPdo->exec("PRAGMA foreign_keys = OFF");
            }

            $tPdo->beginTransaction();
            foreach (array_reverse($orderedTables) as $tb) {
                $tPdo->exec("DELETE FROM {$tb}");
            }
            foreach (array('call_chunks', 'call_signals', 'call_participants', 'active_calls') as $epTb) {
                try { $tPdo->exec("DELETE FROM {$epTb}"); } catch (Exception $e) {}
            }

            $migratedCounts = array();
            foreach ($orderedTables as $tb) {
                $cols = $migSchema[$tb];
                $colListSql = implode(', ', $cols);
                $phSql = implode(', ', array_fill(0, count($cols), '?'));
                $insStmt = $tPdo->prepare("INSERT INTO {$tb} ({$colListSql}) VALUES ({$phSql})");

                $srcStmt = $db->pdo()->query("SELECT {$colListSql} FROM {$tb}");
                $copied = 0;
                if ($srcStmt) {
                    while (($row = $srcStmt->fetch(PDO::FETCH_ASSOC)) !== false) {
                        $vals = array();
                        foreach ($cols as $cName) {
                            $vals[] = array_key_exists($cName, $row) ? $row[$cName] : null;
                        }
                        $insStmt->execute($vals);
                        $copied++;
                    }
                }
                $migratedCounts[$tb] = $copied;
            }
            $tPdo->commit();

            // Verify exact row-count parity before touching config.php
            foreach ($orderedTables as $tb) {
                $dstCnt = (int)$targetDb->val("SELECT COUNT(*) FROM {$tb}");
                if ($dstCnt !== $migratedCounts[$tb]) {
                    throw new RuntimeException("Row count mismatch in table {$tb} ({$dstCnt} != {$migratedCounts[$tb]})");
                }
            }

            // Synchronize auto-increment sequences on target engine
            $autoIncTables = array('users', 'sessions', 'chats', 'messages', 'files', 'invites', 'reports');
            if ($targetDriver === 'mysql') {
                foreach ($autoIncTables as $aiTb) {
                    $maxId = (int)$targetDb->val("SELECT COALESCE(MAX(id), 0) FROM {$aiTb}");
                    $nextId = max(1, $maxId + 1);
                    $tPdo->exec("ALTER TABLE {$aiTb} AUTO_INCREMENT = {$nextId}");
                }
                $tPdo->exec("SET FOREIGN_KEY_CHECKS = 1");
            } else {
                foreach ($autoIncTables as $aiTb) {
                    $maxId = (int)$targetDb->val("SELECT COALESCE(MAX(id), 0) FROM {$aiTb}");
                    try {
                        $tPdo->prepare("DELETE FROM sqlite_sequence WHERE name = ?")->execute(array($aiTb));
                        if ($maxId > 0) {
                            $tPdo->prepare("INSERT INTO sqlite_sequence (name, seq) VALUES (?, ?)")->execute(array($aiTb, $maxId));
                        }
                    } catch (Exception $e) {}
                }
                $tPdo->exec("PRAGMA foreign_keys = ON");
            }

            if (!write_config_file($targetCfg)) {
                throw new RuntimeException('Failed to write updated config.php');
            }
            if (function_exists('opcache_invalidate')) {
                @opcache_invalidate(CONFIG_FILE, true);
            }
            if ($removeOldSqlite && $oldSqlitePath !== '' && is_file($oldSqlitePath) && $oldSqlitePath !== $tempSqlitePath) {
                $db = null;
                @unlink($oldSqlitePath);
            }
            if ($migLock) { @flock($migLock, LOCK_UN); @fclose($migLock); }
            bump_tick();
            api_ok(array(
                'migrated'        => true,
                'previous_driver' => $curDriver,
                'active_driver'   => $targetDriver,
                'migrated_counts' => $migratedCounts
            ));
        } catch (Exception $e) {
            if (isset($tPdo) && $tPdo instanceof PDO && $tPdo->inTransaction()) {
                try { $tPdo->rollBack(); } catch (Exception $re) {}
            }
            if ($tempSqlitePath !== '' && is_file($tempSqlitePath)) {
                @unlink($tempSqlitePath);
            }
            if ($migLock) { @flock($migLock, LOCK_UN); @fclose($migLock); }
            api_err('db_migration_failed', 'خطا در مهاجرت پایگاه‌داده (پیکربندی قبلی دست‌نخورده باقی ماند): ' . $e->getMessage());
        }
    }

    if ($do === 'admin_messenger_panic_wipe') {
        if (empty($in['confirmed'])) {
            $pw = isset($in['password']) ? (string)$in['password'] : '';
            if ($pw === '' || !password_verify($pw, (string)$me['pass_hash'])) {
                api_err('confirmation_required', 'تیک تایید الزامی است / Confirmation checkbox is required.');
            }
        }
        // Total Zero-Trace Panic Self-Destruct: delete DB, all files, chat_data/, AND index.php itself from the server!
        execute_full_messenger_wipe($db, true);
        json_out(array('ok' => true, 'data' => array('wiped' => true, 'self_destructed' => true), 'tick' => '0'), 200);
    }

    api_err('unknown_action', 'Unknown API action: ' . $do);
}



/* ============================================================================
 * 10A-2. STREAMING 3-MODE BACKUP & RESTORE ENGINE (DB / FILES / FULL — M3BK0001)
 * ============================================================================ */
/* Which tables take part in backup / restore / driver migration. Kept as a list on
   purpose: ephemeral state (rate-limit attempts, live call signalling) is excluded
   by design. The COLUMNS, however, are read from the live schema -- a hand-written
   column list silently loses every column added by a later migration (schema v15
   lost members.left_at and members.rejoin_msg_id that way). */
function m3_backup_table_columns($db = null) {
    $live = m3_schema_column_map($db);
    if (!empty($live)) return $live;
    return m3_backup_table_columns_fallback();
}

function m3_schema_columns_for($db, $table, array $fallbackCols) {
    if ($db instanceof DB) {
        $cols = $db->tableColumns($table);
        if (!empty($cols)) return $cols;
    }
    return $fallbackCols;
}

function m3_schema_column_map($db = null) {
    $dbObj = null;
    if ($db instanceof DB) $dbObj = $db;
    elseif (isset($GLOBALS['M3_ACTIVE_DB']) && ($GLOBALS['M3_ACTIVE_DB'] instanceof DB)) $dbObj = $GLOBALS['M3_ACTIVE_DB'];
    $GLOBALS['M3_SCHEMA_MAP_DERIVED'] = 0;
    if (!$dbObj) return array();
    $fallback = m3_backup_table_columns_fallback();
    $map = array();
    $derived = 0;
    foreach ($fallback as $tb => $litCols) {
        $cols = $dbObj->tableColumns($tb);
        if (!empty($cols)) { $map[$tb] = $cols; $derived++; }
        else { $map[$tb] = $litCols; }
    }
    if ($derived === count($fallback)) $GLOBALS['M3_SCHEMA_MAP_DERIVED'] = 1;
    return $map;
}

function m3_backup_table_columns_fallback() {
    return array(
        'settings'     => array('k', 'v'),
        'users'        => array('id', 'username', 'name', 'bio', 'avatar', 'pass_hash', 'duress_pass_hash', 'lock_pass_hash', 'recovery_hash', 'lang', 'theme', 'cal', 'flags', 'role', 'status', 'show_admin_badge', 'totp_secret', 'pubkey', 'key_backup', 'invite_code', 'invited_by', 'traffic_used_bytes', 'traffic_period_start', 'created_at', 'last_seen_bucket', 'delete_at', 'inactive_delete_days'),
        'chats'        => array('id', 'type', 'handle', 'title', 'description', 'avatar', 'visibility', 'owner_id', 'is_default', 'all_muted', 'history', 'default_ttl', 'ttl_mode', 'auto_delete_sec', 'slow_mode', 'max_members', 'perms_json', 'secret_status', 'secret_initiator_id', 'status', 'created_at'),
        'members'      => array('chat_id', 'user_id', 'role', 'perms_json', 'joined_msg_id', 'last_read_id', 'receipt_read_id', 'pinned_msg_id', 'auto_delete_sec', 'muted', 'pinned_at', 'mute_send', 'mute_react', 'banned_until', 'restricted_until', 'last_msg_at', 'joined_at', 'left_at', 'rejoin_msg_id', 'shadow_banned', 'shadow_banned_at', 'shadow_banned_by'),
        'messages'     => array('id', 'chat_id', 'user_id', 'kind', 'body', 'cipher', 'iv', 'reply_to', 'forward_from_id', 'forward_origin_id', 'forward_from_name', 'forward_hide_author', 'visible_only_to', 'file_id', 'created_at', 'edited_at', 'edited_silent', 'edit_history_json', 'deleted_at', 'hidden_for', 'expires_at', 'burn_after', 'first_read_at', 'pinned', 'pinned_at', 'spoiler', 'views'),
        'message_reads'=> array('message_id', 'chat_id', 'user_id', 'read_at'),
        'files'        => array('id', 'owner_id', 'chat_id', 'stored_name', 'sha256', 'display_name', 'mime', 'size', 'encrypted', 'file_iv', 'created_at'),
        'invites'      => array('id', 'chat_id', 'code', 'created_by', 'max_uses', 'uses', 'expires_at', 'revoked'),
        'invite_codes' => array('code', 'created_by', 'max_uses', 'uses_left', 'expires_at', 'created_at'),
        'blocks'       => array('user_id', 'blocked_id'),
        'reactions'    => array('message_id', 'user_id', 'emoji'),
        'reports'      => array('id', 'reporter_id', 'target_type', 'target_id', 'reason', 'description', 'created_at', 'status')
    );
}

function m3_pack_u64_be($val) {
    $v = max(0, (int)$val);
    $hi = (int)floor($v / 4294967296);
    $lo = (int)($v - ($hi * 4294967296));
    return pack('NN', $hi, $lo);
}

function m3_unpack_u64_be($bytes8) {
    $u = unpack('Nhi/Nlo', $bytes8);
    return ((int)$u['hi'] * 4294967296) + (int)$u['lo'];
}

function m3_read_exact($fp, $len, $hashCtx = null) {
    if ($len <= 0) return '';
    $buf = '';
    while (strlen($buf) < $len && !feof($fp)) {
        $chunk = @fread($fp, $len - strlen($buf));
        if ($chunk === false || $chunk === '') break;
        $buf .= $chunk;
    }
    if (strlen($buf) !== $len) {
        return false;
    }
    if ($hashCtx !== null) {
        hash_update($hashCtx, $buf);
    }
    return $buf;
}

function m3_write_stream_record($outFp, $hashCtx, $typeChar, $headerArr, $payloadFilePath = null, $payloadLen = 0) {
    $hJson = json_encode($headerArr, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
    if ($hJson === false) $hJson = '{}';
    $hLen = strlen($hJson);
    $pLen = ($payloadFilePath !== null) ? max(0, (int)$payloadLen) : 0;

    $prefix = substr((string)$typeChar, 0, 1) . pack('N', $hLen) . m3_pack_u64_be($pLen) . $hJson;
    hash_update($hashCtx, $prefix);
    fwrite($outFp, $prefix);

    if ($payloadFilePath !== null && $pLen > 0) {
        $inFp = @fopen($payloadFilePath, 'rb');
        $rem = $pLen;
        if ($inFp) {
            while ($rem > 0 && !feof($inFp)) {
                $toRead = ($rem > 65536) ? 65536 : $rem;
                $buf = @fread($inFp, $toRead);
                if ($buf === false || $buf === '') break;
                $n = strlen($buf);
                hash_update($hashCtx, $buf);
                fwrite($outFp, $buf);
                $rem -= $n;
            }
            @fclose($inFp);
        }
        // Pad zeros if file shrank concurrently so framing never breaks
        while ($rem > 0) {
            $pad = str_repeat("\0", ($rem > 65536) ? 65536 : $rem);
            hash_update($hashCtx, $pad);
            fwrite($outFp, $pad);
            $rem -= strlen($pad);
        }
    }
    if (function_exists('fflush')) @fflush($outFp);
}

function stream_m3_backup_archive(DB $db, $mode) {
    $mode = in_array($mode, array('db', 'files', 'full'), true) ? $mode : 'full';
    lazy_purge($db, true);

    $includeDb = ($mode === 'db' || $mode === 'full');
    $includeFiles = ($mode === 'files' || $mode === 'full');

    $fileRows = array();
    $validFiles = array();
    $totalFileBytes = 0;
    if ($includeFiles) {
        $allFiles = $db->all("SELECT * FROM files ORDER BY id ASC");
        foreach ($allFiles as $fr) {
            $sn = isset($fr['stored_name']) ? basename((string)$fr['stored_name']) : '';
            if (!preg_match('/^[a-f0-9]{16,80}$/', $sn)) continue;
            $fp = FILES_DIR . '/' . $sn;
            if (!is_file($fp)) continue;
            $realSz = (int)@filesize($fp);
            if ($realSz < 0) continue;
            $fr['stored_name'] = $sn;
            $fr['real_size'] = $realSz;
            $validFiles[] = $fr;
            $totalFileBytes += $realSz;
        }
    }

    $stamp = gmdate('Ymd_His');
    $dlName = 'm3_' . $mode . '_backup_' . $stamp . '.m3b';

    while (ob_get_level() > 0) {
        @ob_end_clean();
    }
    http_response_code(200);
    header('Content-Type: application/octet-stream');
    header('Content-Disposition: attachment; filename="' . $dlName . '"');
    header('Cache-Control: no-store, no-cache, must-revalidate');
    header('X-Content-Type-Options: nosniff');

    $outFp = fopen('php://output', 'wb');
    $hashCtx = hash_init('sha256');

    $magic = 'M3BK0001';
    hash_update($hashCtx, $magic);
    fwrite($outFp, $magic);

    m3_write_stream_record($outFp, $hashCtx, 'H', array(
        'format'            => 'M3BK1',
        'mode'              => $mode,
        'app_version'       => APP_VERSION,
        'created_at'        => time(),
        'db_included'       => $includeDb,
        'files_included'    => $includeFiles,
        'files_count'       => count($validFiles),
        'files_total_bytes' => $totalFileBytes,
        // 1 when the column list was read from the live schema, 0 when the
        // hard-coded fallback had to be used (an old archive may then be missing
        // columns added by later migrations).
        'columns_derived'   => !empty($db->tableColumns('members')) ? 1 : 0
    ));

    if ($includeDb) {
        $schemaMap = m3_backup_table_columns($db);
        foreach ($schemaMap as $tableName => $cols) {
            $offset = 0;
            $batchSize = 250;
            while (true) {
                $rows = $db->all("SELECT * FROM {$tableName} LIMIT {$batchSize} OFFSET {$offset}");
                if (empty($rows)) break;
                $cleanRows = array();
                foreach ($rows as $r) {
                    $cr = array();
                    foreach ($cols as $c) {
                        if (array_key_exists($c, $r)) {
                            $cr[$c] = $r[$c];
                        }
                    }
                    $cleanRows[] = $cr;
                }
                m3_write_stream_record($outFp, $hashCtx, 'T', array(
                    'table' => $tableName,
                    'rows'  => $cleanRows
                ));
                if (count($rows) < $batchSize) break;
                $offset += $batchSize;
            }
        }
    }

    if ($includeFiles) {
        // Emit file metadata + message attachment links so files-only restore can reconcile DB links cleanly
        $msgLinks = $db->all("SELECT id, chat_id, kind, body, file_id FROM messages WHERE file_id IS NOT NULL AND deleted_at IS NULL");
        $metaRows = array();
        foreach ($validFiles as $vf) {
            $copy = $vf;
            unset($copy['real_size']);
            $metaRows[] = $copy;
        }
        m3_write_stream_record($outFp, $hashCtx, 'M', array(
            'files'         => $metaRows,
            'message_links' => $msgLinks
        ));

        $emittedBlobs = array();
        foreach ($validFiles as $vf) {
            $sn = $vf['stored_name'];
            if (isset($emittedBlobs[$sn])) continue;
            $emittedBlobs[$sn] = true;
            $fp = FILES_DIR . '/' . $sn;
            $sz = (int)$vf['real_size'];
            $fSha = @hash_file('sha256', $fp);
            if (!is_string($fSha) || strlen($fSha) !== 64) continue;
            m3_write_stream_record($outFp, $hashCtx, 'F', array(
                'id'           => (int)$vf['id'],
                'stored_name'  => $sn,
                'display_name' => (string)$vf['display_name'],
                'mime'         => (string)$vf['mime'],
                'encrypted'    => (int)$vf['encrypted'],
                'size'         => $sz,
                'sha256'       => $fSha
            ), $fp, $sz);
        }
    }

    m3_write_stream_record($outFp, $hashCtx, 'E', array('eof' => 1));
    $digest = hash_final($hashCtx, true);
    fwrite($outFp, $digest);
    if (function_exists('fflush')) @fflush($outFp);
    fclose($outFp);
    exit;
}

function verify_and_restore_m3_backup(DB $db, $archivePath, $restoreMode, $currentAuth) {
    $restoreMode = in_array($restoreMode, array('db', 'files', 'full'), true) ? $restoreMode : 'full';
    if (!is_file($archivePath)) {
        return array('ok' => false, 'error' => 'backup_not_found', 'message' => 'فایل پشتیبان یافت نشد / Backup file not found.');
    }
    $archiveSize = (int)@filesize($archivePath);
    if ($archiveSize < 53) {
        return array('ok' => false, 'error' => 'invalid_backup_format', 'message' => 'فرمت فایل پشتیبان نامعتبر یا ناقص است / Invalid or truncated backup archive.');
    }

    // PASS 1: Strict Zero-Mutation Integrity, Signature & Content Validation
    $fp = @fopen($archivePath, 'rb');
    if (!$fp) {
        return array('ok' => false, 'error' => 'backup_open_failed', 'message' => 'امکان خواندن فایل پشتیبان وجود ندارد / Cannot open backup archive.');
    }
    $hashCtx = hash_init('sha256');
    $magic = m3_read_exact($fp, 8, $hashCtx);
    if ($magic !== 'M3BK0001') {
        @fclose($fp);
        return array('ok' => false, 'error' => 'invalid_backup_format', 'message' => 'این فایل یک بسته پشتیبان معتبر M3 نیست / Invalid M3 backup file header.');
    }

    $schemaMap = m3_backup_table_columns($db);
    $blockedExecExts = array('svg', 'svgz', 'php', 'phtml', 'phar', 'pht', 'phps', 'php3', 'php4', 'php5', 'php7', 'php8', 'html', 'htm', 'xhtml', 'shtml', 'xml', 'xsl', 'js', 'mjs', 'cjs', 'vbs', 'bat', 'cmd', 'sh', 'cgi', 'pl', 'jsp', 'asp', 'aspx', 'cer', 'asa', 'war', 'swf', 'htaccess');

    $archiveHeader = null;
    $sawEof = false;
    $activeSuperAdminsInBackup = 0;
    $verifiedFilesCount = 0;
    $verifiedTableRows = 0;

    while (!feof($fp)) {
        $recPrefix = m3_read_exact($fp, 13, $hashCtx);
        if ($recPrefix === false) {
            @fclose($fp);
            return array('ok' => false, 'error' => 'corrupted_backup', 'message' => 'ساختار رکوردهای فایل پشتیبان آسیب دیده است / Corrupted backup record framing.');
        }
        $rType = $recPrefix[0];
        $hLenArr = unpack('Nhlen', substr($recPrefix, 1, 4));
        $hLen = (int)$hLenArr['hlen'];
        $pLen = m3_unpack_u64_be(substr($recPrefix, 5, 8));

        if ($hLen < 2 || $hLen > 16 * 1048576 || $pLen < 0 || $pLen > 4 * 1073741824) {
            @fclose($fp);
            return array('ok' => false, 'error' => 'corrupted_backup', 'message' => 'اندازه هدر یا داده در فایل پشتیبان نامعتبر است / Invalid record size in backup.');
        }

        $hBytes = m3_read_exact($fp, $hLen, $hashCtx);
        if ($hBytes === false) {
            @fclose($fp);
            return array('ok' => false, 'error' => 'corrupted_backup', 'message' => 'هدر رکورد فایل پشتیبان ناقص است / Truncated record header.');
        }
        $hObj = json_decode($hBytes, true);
        if (!is_array($hObj)) {
            @fclose($fp);
            return array('ok' => false, 'error' => 'corrupted_backup', 'message' => 'متادیتای JSON فایل پشتیبان نامعتبر است / Invalid JSON header in backup.');
        }

        if ($rType === 'H') {
            $archiveHeader = $hObj;
            $hasDb = !empty($hObj['db_included']);
            $hasFiles = !empty($hObj['files_included']);
            if ($restoreMode === 'db' && !$hasDb) {
                @fclose($fp);
                return array('ok' => false, 'error' => 'wrong_backup_type', 'message' => 'این بکاپ فقط شامل فایل‌هاست و حاوی پایگاه‌داده نیست! / Selected backup contains files only, not database.');
            }
            if ($restoreMode === 'files' && !$hasFiles) {
                @fclose($fp);
                return array('ok' => false, 'error' => 'wrong_backup_type', 'message' => 'این بکاپ فقط شامل پایگاه‌داده است و حاوی فایل‌ها نیست! / Selected backup contains database only, not files.');
            }
            if ($restoreMode === 'full' && (!$hasDb || !$hasFiles)) {
                @fclose($fp);
                return array('ok' => false, 'error' => 'wrong_backup_type', 'message' => 'برای بازنشانی جامع باید فایل بکاپ جامع (شامل پایگاه‌داده و فایل‌ها) انتخاب شود! / Full restore requires a comprehensive backup containing both database and files.');
            }
        } elseif ($rType === 'T') {
            $tb = isset($hObj['table']) ? (string)$hObj['table'] : '';
            if (!isset($schemaMap[$tb]) || !isset($hObj['rows']) || !is_array($hObj['rows'])) {
                @fclose($fp);
                return array('ok' => false, 'error' => 'invalid_table_in_backup', 'message' => 'جدول نامعتبر در فایل پشتیبان مشاهده شد / Invalid table in backup.');
            }
            $verifiedTableRows += count($hObj['rows']);
            if ($tb === 'users') {
                foreach ($hObj['rows'] as $ur) {
                    if (is_array($ur) && isset($ur['role'], $ur['status'], $ur['pass_hash'])
                        && $ur['role'] === 'superadmin' && $ur['status'] === 'active' && strlen((string)$ur['pass_hash']) >= 20) {
                        $activeSuperAdminsInBackup++;
                    }
                }
            }
        } elseif ($rType === 'F') {
            $sn = isset($hObj['stored_name']) ? (string)$hObj['stored_name'] : '';
            $dispName = isset($hObj['display_name']) ? basename((string)$hObj['display_name']) : '';
            $dispExt = strtolower(pathinfo($dispName, PATHINFO_EXTENSION));
            $expectedSha = isset($hObj['sha256']) ? strtolower((string)$hObj['sha256']) : '';
            if (!preg_match('/^[a-f0-9]{16,80}$/', $sn) || in_array($dispExt, $blockedExecExts, true) || !preg_match('/^[a-f0-9]{64}$/', $expectedSha)) {
                @fclose($fp);
                return array('ok' => false, 'error' => 'unsafe_file_in_backup', 'message' => 'نام یا پسوند ناامن در فایل‌های بسته پشتیبان شناسایی و مسدود شد / Unsafe file metadata rejected.');
            }
            $fHashCtx = hash_init('sha256');
            $rem = $pLen;
            while ($rem > 0) {
                $chunk = m3_read_exact($fp, ($rem > 65536) ? 65536 : $rem, $hashCtx);
                if ($chunk === false) {
                    @fclose($fp);
                    return array('ok' => false, 'error' => 'corrupted_backup', 'message' => 'جریان بایت‌های فایل در بسته پشتیبان ناقص است / Truncated file stream in backup.');
                }
                hash_update($fHashCtx, $chunk);
                $rem -= strlen($chunk);
            }
            $actualFileSha = hash_final($fHashCtx);
            if (!hash_equals($expectedSha, $actualFileSha)) {
                @fclose($fp);
                return array('ok' => false, 'error' => 'file_checksum_mismatch', 'message' => 'عدم تطابق امضای SHA-256 یکی از فایل‌های درون بکاپ / File SHA-256 mismatch inside backup.');
            }
            $verifiedFilesCount++;
            continue;
        } elseif ($rType === 'E') {
            $sawEof = true;
            break;
        }

        if ($pLen > 0) {
            $remSkip = $pLen;
            while ($remSkip > 0) {
                $sk = m3_read_exact($fp, ($remSkip > 65536) ? 65536 : $remSkip, $hashCtx);
                if ($sk === false) {
                    @fclose($fp);
                    return array('ok' => false, 'error' => 'corrupted_backup', 'message' => 'پایان غیرمنتظره در فایل پشتیبان / Unexpected EOF in backup.');
                }
                $remSkip -= strlen($sk);
            }
        }
    }

    if (!$archiveHeader || !$sawEof) {
        @fclose($fp);
        return array('ok' => false, 'error' => 'corrupted_backup', 'message' => 'انتهای بسته پشتیبان ناقص است / Incomplete backup archive.');
    }

    $expectedDigest = hash_final($hashCtx, true);
    $actualDigest = m3_read_exact($fp, 32, null);
    @fclose($fp);
    if ($actualDigest === false || !hash_equals($expectedDigest, $actualDigest)) {
        return array('ok' => false, 'error' => 'checksum_mismatch', 'message' => 'امضای دیجیتال SHA-256 بسته پشتیبان نامعتبر است (فایل دستکاری یا ناقص شده است) / Archive SHA-256 integrity check failed.');
    }

    if (($restoreMode === 'db' || $restoreMode === 'full') && $activeSuperAdminsInBackup < 1) {
        return array('ok' => false, 'error' => 'no_superadmin_in_backup', 'message' => 'در پایگاه‌داده این بکاپ هیچ حساب مدیرکل فعالی وجود ندارد؛ بازنشانی متوقف شد / Backup DB has no active Super-Admin.');
    }

    // PASS 2: Staged Safe Execution
    $doRestoreDb = ($restoreMode === 'db' || $restoreMode === 'full');
    $doRestoreFiles = ($restoreMode === 'files' || $restoreMode === 'full');

    ensure_data_dirs();
    $stageDir = '';
    if ($doRestoreFiles) {
        $stageDir = DATA_DIR . '/files_stage_' . bin2hex(random_bytes_safe(8));
        if (!@mkdir($stageDir, 0750, true)) {
            return array('ok' => false, 'error' => 'stage_dir_failed', 'message' => 'امکان ایجاد پوشه موقت بازنشانی وجود ندارد / Could not create staging directory.');
        }
    }

    $fp2 = @fopen($archivePath, 'rb');
    @fread($fp2, 8); // skip magic

    $stagedFilesMeta = array();
    $stagedMsgLinks = array();
    $restoredFilesCount = 0;

    // First extract & magic-byte-verify all physical files into $stageDir before touching DB or live FILES_DIR
    if ($doRestoreFiles) {
        while (!feof($fp2)) {
            $recPrefix = m3_read_exact($fp2, 13, null);
            if ($recPrefix === false) break;
            $rType = $recPrefix[0];
            $hLen = (int)unpack('Nhlen', substr($recPrefix, 1, 4))['hlen'];
            $pLen = m3_unpack_u64_be(substr($recPrefix, 5, 8));
            $hObj = json_decode((string)m3_read_exact($fp2, $hLen, null), true);
            if ($rType === 'E') break;

            if ($rType === 'M' && is_array($hObj)) {
                if (!empty($hObj['files']) && is_array($hObj['files'])) {
                    $stagedFilesMeta = $hObj['files'];
                }
                if (!empty($hObj['message_links']) && is_array($hObj['message_links'])) {
                    $stagedMsgLinks = $hObj['message_links'];
                }
            } elseif ($rType === 'F' && is_array($hObj)) {
                $sn = (string)$hObj['stored_name'];
                $destStage = $stageDir . '/' . $sn;
                $outF = @fopen($destStage, 'wb');
                if (!$outF) {
                    remove_directory_recursive($stageDir);
                    @fclose($fp2);
                    return array('ok' => false, 'error' => 'file_write_failed', 'message' => 'خطا در نوشتن فایل بازیابی‌شده / Failed writing staged file.');
                }
                $rem = $pLen;
                while ($rem > 0) {
                    $chunk = m3_read_exact($fp2, ($rem > 65536) ? 65536 : $rem, null);
                    if ($chunk === false) break;
                    @fwrite($outF, $chunk);
                    $rem -= strlen($chunk);
                }
                @fclose($outF);
                @chmod($destStage, 0640);

                $dispExt = strtolower(pathinfo(basename((string)$hObj['display_name']), PATHINFO_EXTENSION));
                $encFlag = !empty($hObj['encrypted']) ? 1 : 0;
                $chkMime = detect_and_validate_magic_bytes($destStage, $dispExt, $encFlag, 'file');
                if ($chkMime === false) {
                    remove_directory_recursive($stageDir);
                    @fclose($fp2);
                    return array('ok' => false, 'error' => 'unsafe_file_signature', 'message' => 'امضای باینری یکی از فایل‌های بکاپ ناامن تشخیص داده شد و بازنشانی متوقف گردید / Unsafe file content signature rejected.');
                }
                $restoredFilesCount++;
                continue;
            }

            if ($pLen > 0) {
                $remSkip = $pLen;
                while ($remSkip > 0) {
                    $sk = m3_read_exact($fp2, ($remSkip > 65536) ? 65536 : $remSkip, null);
                    if ($sk === false) break;
                    $remSkip -= strlen($sk);
                }
            }
        }
    }
    @fclose($fp2);

    $reloginRequired = false;
    $curSession = isset($currentAuth['session']) ? $currentAuth['session'] : null;
    $curAdminUser = isset($currentAuth['user']) ? $currentAuth['user'] : null;

    if ($doRestoreDb) {
        $fp3 = @fopen($archivePath, 'rb');
        @fread($fp3, 8);
        $pdo = $db->pdo();
        $isMysql = ($db->driver() === 'mysql');
        try {
            if ($isMysql) {
                $pdo->exec("SET FOREIGN_KEY_CHECKS = 0");
            }
            $pdo->beginTransaction();

            $clearOrder = array('message_reads', 'reactions', 'blocks', 'reports', 'invites', 'invite_codes', 'messages', 'files', 'members', 'chats', 'sessions', 'attempts', 'settings', 'users');
            foreach ($clearOrder as $tb) {
                $pdo->exec("DELETE FROM {$tb}");
            }

            while (!feof($fp3)) {
                $recPrefix = m3_read_exact($fp3, 13, null);
                if ($recPrefix === false) break;
                $rType = $recPrefix[0];
                $hLen = (int)unpack('Nhlen', substr($recPrefix, 1, 4))['hlen'];
                $pLen = m3_unpack_u64_be(substr($recPrefix, 5, 8));
                $hObj = json_decode((string)m3_read_exact($fp3, $hLen, null), true);
                if ($rType === 'E') break;

                if ($rType === 'T' && is_array($hObj)) {
                    $tb = (string)$hObj['table'];
                    $allowedCols = $schemaMap[$tb];
                    foreach ($hObj['rows'] as $row) {
                        if (!is_array($row)) continue;
                        if ($tb === 'settings' && isset($row['k'], $row['v']) && in_array($row['k'], array('site_logo', 'site_favicon'), true)) {
                            $decVal = json_decode((string)$row['v'], true);
                            if (is_string($decVal) && $decVal !== '' && !parse_branding_data_uri($decVal)) {
                                $row['v'] = json_encode('');
                            }
                        }
                        $insCols = array();
                        $insVals = array();
                        foreach ($allowedCols as $col) {
                            if (array_key_exists($col, $row)) {
                                $insCols[] = $col;
                                $insVals[] = $row[$col];
                            }
                        }
                        if (!empty($insCols)) {
                            $ph = implode(', ', array_fill(0, count($insCols), '?'));
                            $colList = implode(', ', $insCols);
                            $stmt = $pdo->prepare("INSERT INTO {$tb} ({$colList}) VALUES ({$ph})");
                            $stmt->execute($insVals);
                        }
                    }
                }

                if ($pLen > 0) {
                    $remSkip = $pLen;
                    while ($remSkip > 0) {
                        $sk = m3_read_exact($fp3, ($remSkip > 65536) ? 65536 : $remSkip, null);
                        if ($sk === false) break;
                        $remSkip -= strlen($sk);
                    }
                }
            }

            init_default_settings($db);

            // Preserve current Super-Admin session if their account exists as an active superadmin in restored DB
            $matchedAdmin = null;
            if ($curAdminUser) {
                $matchedAdmin = $db->one(
                    "SELECT id FROM users WHERE id = ? AND username = ? AND role = 'superadmin' AND status = 'active'",
                    array((int)$curAdminUser['id'], (string)$curAdminUser['username'])
                );
                if (!$matchedAdmin) {
                    $matchedAdmin = $db->one(
                        "SELECT id FROM users WHERE username = ? AND role = 'superadmin' AND status = 'active'",
                        array((string)$curAdminUser['username'])
                    );
                }
            }
            if ($matchedAdmin && $curSession && !empty($curSession['token_hash']) && !empty($curSession['csrf_token'])) {
                $db->exec(
                    "INSERT INTO sessions (user_id, token_hash, csrf_token, created_at, last_used_bucket, device_label, expires_at, is_locked, is_persistent)
                     VALUES (?, ?, ?, ?, ?, ?, ?, 0, ?)",
                    array(
                        (int)$matchedAdmin['id'],
                        (string)$curSession['token_hash'],
                        (string)$curSession['csrf_token'],
                        (int)$curSession['created_at'],
                        (int)$curSession['last_used_bucket'],
                        (string)$curSession['device_label'],
                        max(time() + 3600, (int)$curSession['expires_at']),
                        !empty($curSession['is_persistent']) ? 1 : 0
                    )
                );
            } else {
                $reloginRequired = true;
            }

            $pdo->commit();
            $autoIncTablesRest = array('users', 'sessions', 'chats', 'messages', 'files', 'invites', 'reports');
            if ($isMysql) {
                foreach ($autoIncTablesRest as $aiTbR) {
                    $maxIdR = (int)$db->val("SELECT COALESCE(MAX(id), 0) FROM {$aiTbR}");
                    $nextIdR = max(1, $maxIdR + 1);
                    try { $pdo->exec("ALTER TABLE {$aiTbR} AUTO_INCREMENT = {$nextIdR}"); } catch (Exception $e) {}
                }
                $pdo->exec("SET FOREIGN_KEY_CHECKS = 1");
            } else {
                foreach ($autoIncTablesRest as $aiTbR) {
                    $maxIdR = (int)$db->val("SELECT COALESCE(MAX(id), 0) FROM {$aiTbR}");
                    try {
                        $pdo->prepare("DELETE FROM sqlite_sequence WHERE name = ?")->execute(array($aiTbR));
                        if ($maxIdR > 0) {
                            $pdo->prepare("INSERT INTO sqlite_sequence (name, seq) VALUES (?, ?)")->execute(array($aiTbR, $maxIdR));
                        }
                    } catch (Exception $e) {}
                }
            }
        } catch (Throwable $e) {
            if ($pdo->inTransaction()) $pdo->rollBack();
            if ($isMysql) { try { $pdo->exec("SET FOREIGN_KEY_CHECKS = 1"); } catch (Exception $ex) {} }
            @fclose($fp3);
            if ($stageDir !== '' && is_dir($stageDir)) remove_directory_recursive($stageDir);
            return array('ok' => false, 'error' => 'db_restore_failed', 'message' => 'خطا هنگام بازنشانی جداول پایگاه‌داده؛ هیچ تغییری اعمال نشد / Database restore rolled back safely.');
        } catch (Exception $e) {
            if ($pdo->inTransaction()) $pdo->rollBack();
            if ($isMysql) { try { $pdo->exec("SET FOREIGN_KEY_CHECKS = 1"); } catch (Exception $ex) {} }
            @fclose($fp3);
            if ($stageDir !== '' && is_dir($stageDir)) remove_directory_recursive($stageDir);
            return array('ok' => false, 'error' => 'db_restore_failed', 'message' => 'خطا هنگام بازنشانی جداول پایگاه‌داده؛ هیچ تغییری اعمال نشد / Database restore rolled back safely.');
        }
        @fclose($fp3);
    }

    if ($doRestoreFiles && $stageDir !== '' && is_dir($stageDir)) {
        // In 'full' mode replace all existing files in FILES_DIR; in 'files' mode sync restored files cleanly
        if ($restoreMode === 'full') {
            $oldItems = @scandir(FILES_DIR);
            if (is_array($oldItems)) {
                foreach ($oldItems as $oi) {
                    if ($oi === '.' || $oi === '..' || $oi === '.htaccess' || $oi === 'index.html') continue;
                    $op = FILES_DIR . '/' . $oi;
                    if (is_file($op)) @unlink($op);
                }
            }
        }
        $newItems = @scandir($stageDir);
        if (is_array($newItems)) {
            foreach ($newItems as $ni) {
                if ($ni === '.' || $ni === '..') continue;
                $srcP = $stageDir . '/' . $ni;
                $dstP = FILES_DIR . '/' . $ni;
                if (is_file($srcP)) {
                    if (file_exists($dstP)) @unlink($dstP);
                    @rename($srcP, $dstP);
                    @chmod($dstP, 0640);
                }
            }
        }
        remove_directory_recursive($stageDir);
        ensure_data_dirs();

        // In 'files'-only mode, also restore missing `files` metadata rows & re-link purged message attachments
        if ($restoreMode === 'files') {
            $fileCols = $schemaMap['files'];
            foreach ($stagedFilesMeta as $fm) {
                if (!is_array($fm) || empty($fm['id']) || empty($fm['stored_name'])) continue;
                $fid = (int)$fm['id'];
                $sn = basename((string)$fm['stored_name']);
                if (!is_file(FILES_DIR . '/' . $sn)) continue;
                $existsF = $db->one("SELECT id FROM files WHERE id = ?", array($fid));
                if (!$existsF) {
                    $ownerExists = $db->val("SELECT id FROM users WHERE id = ?", array((int)$fm['owner_id']));
                    $chatExists = $db->val("SELECT id FROM chats WHERE id = ?", array((int)$fm['chat_id']));
                    if ($ownerExists && $chatExists) {
                        $insC = array();
                        $insV = array();
                        foreach ($fileCols as $fc) {
                            if (array_key_exists($fc, $fm)) {
                                $insC[] = $fc;
                                $insV[] = $fm[$fc];
                            }
                        }
                        if (!empty($insC)) {
                            $ph = implode(', ', array_fill(0, count($insC), '?'));
                            $db->exec("INSERT INTO files (" . implode(', ', $insC) . ") VALUES ({$ph})", $insV);
                        }
                    }
                }
            }
            foreach ($stagedMsgLinks as $ml) {
                if (!is_array($ml) || empty($ml['id']) || empty($ml['file_id'])) continue;
                $mid = (int)$ml['id'];
                $mfid = (int)$ml['file_id'];
                $hasFileRow = $db->val("SELECT id FROM files WHERE id = ?", array($mfid));
                if ($hasFileRow) {
                    $curMsg = $db->one("SELECT id, file_id, body FROM messages WHERE id = ? AND deleted_at IS NULL", array($mid));
                    if ($curMsg && empty($curMsg['file_id'])) {
                        $restKind = isset($ml['kind']) && in_array($ml['kind'], array('file', 'voice', 'video_note'), true) ? $ml['kind'] : 'file';
                        $restBody = isset($ml['body']) ? (string)$ml['body'] : (string)$curMsg['body'];
                        $db->exec("UPDATE messages SET file_id = ?, kind = ?, body = ? WHERE id = ?", array($mfid, $restKind, $restBody, $mid));
                    }
                }
            }
        }
    }

    bump_tick();
    return array(
        'ok'               => true,
        'mode'             => $restoreMode,
        'table_rows'       => $verifiedTableRows,
        'files_restored'   => $restoredFilesCount,
        'relogin_required' => $reloginRequired
    );
}

/* ============================================================================
 * 10B. MAIN HTTP REQUEST DISPATCHER
 * ============================================================================ */
$APP_CFG = load_app_config();
$ROUTE_A = isset($_GET['a']) ? trim((string)$_GET['a']) : '';
$REQ_PATH_ONLY = isset($_SERVER['REQUEST_URI']) ? (string)parse_url((string)$_SERVER['REQUEST_URI'], PHP_URL_PATH) : '';
if ($ROUTE_A === '' && preg_match('#(?:^|/)robots\.txt$#i', $REQ_PATH_ONLY)) {
    $ROUTE_A = 'robots';
}

if ($ROUTE_A === 'install') {
    if (!isset($_SERVER['REQUEST_METHOD']) || strtoupper((string)$_SERVER['REQUEST_METHOD']) !== 'POST') {
        api_err('method_not_allowed', 'POST method is required.', 405);
    }
    if ($APP_CFG) {
        api_err('already_installed', 'Application is already installed.', 403);
    }
    try {
        handle_installer_request();
    } catch (Throwable $e) {
        api_err('server_error', 'Internal server error.', 500);
    } catch (Exception $e) {
        api_err('server_error', 'Internal server error.', 500);
    }
}

if (in_array($ROUTE_A, array('robots', 'font', 'icon', 'manifest', 'sw', 'sw_sync', 'file', 'cron', 'poll', 'user_backup_zip'), true)) {
    try {
        handle_asset_route($ROUTE_A, $APP_CFG);
    } catch (Throwable $e) {
        api_err('server_error', 'Internal server error.', 500);
    } catch (Exception $e) {
        api_err('server_error', 'Internal server error.', 500);
    }
}

if ($ROUTE_A === 'api') {
    if (!$APP_CFG) {
        api_err('not_installed', 'Application is not installed yet.', 503);
    }
    try {
        $db = new DB($APP_CFG);
        ensure_schema($db);
        handle_api_route($db);
    } catch (Throwable $e) {
        api_err('server_error', 'Internal server error.', 500);
    } catch (Exception $e) {
        api_err('server_error', 'Internal server error.', 500);
    }
}

$CSP_NONCE = base64_encode(random_bytes_safe(16));
send_security_headers($CSP_NONCE);
$IS_INSTALLED = ($APP_CFG !== null);
$ENV_STATUS = check_environment();
$INITIAL_LANG = 'fa';
$INITIAL_THEME = 'auto';
$INITIAL_SITE_NAME_FA = 'پیامرسان کوچک من (M3)';
$INITIAL_SITE_NAME_EN = 'My Mini Messenger (M3)';
$INITIAL_SITE_NAME = $INITIAL_SITE_NAME_FA;
$INITIAL_SITE_LOGO = '';
$INITIAL_SITE_FAVICON = '';
$LOCK_BOOT = null;
$LOCK_BOOT_LANG = 'fa';
$LOCK_BOOT_PREAUTH = false;
$LOCK_BOOT_PREAUTH_LOCK = false;

if ($IS_INSTALLED) {
    try {
        $bootDb = new DB($APP_CFG);
        ensure_schema($bootDb);
        $schedWipeAt = (int)Settings::get($bootDb, 'messenger_delete_at', 0);
        if ($schedWipeAt > 0 && time() >= $schedWipeAt) {
            execute_full_messenger_wipe($bootDb, true);
            $bootDb = null;
            header('Cache-Control: no-store, no-cache, must-revalidate');
            echo '<!doctype html><html><head><meta charset="utf-8"><title></title><script nonce="' . h($CSP_NONCE) . '">try{localStorage.clear();sessionStorage.clear();if(window.indexedDB&&indexedDB.databases){indexedDB.databases().then(function(l){(l||[]).forEach(function(d){if(d&&d.name)indexedDB.deleteDatabase(d.name);});});}else if(window.indexedDB){indexedDB.deleteDatabase("m3_e2ee_v1");}}catch(e){}</script></head><body style="margin:0;background:#ffffff;"></body></html>';
            exit;
        } else {
            $INITIAL_LANG = (string)Settings::get($bootDb, 'default_lang', 'fa');
            $INITIAL_THEME = (string)Settings::get($bootDb, 'default_theme', 'auto');
            $dbFa = trim((string)Settings::get($bootDb, 'site_name_fa', ''));
            $dbEn = trim((string)Settings::get($bootDb, 'site_name_en', ''));
            if ($dbFa === '' || $dbFa === 'پیامرسان کوچک من' || $dbFa === 'پیام‌رسان کوچک من') {
                $dbFa = 'پیامرسان کوچک من (M3)';
            }
            if ($dbEn === '') {
                $dbEn = 'My Mini Messenger (M3)';
            }
            $INITIAL_SITE_NAME_FA = $dbFa;
            $INITIAL_SITE_NAME_EN = $dbEn;
            $INITIAL_SITE_NAME = ($INITIAL_LANG === 'en') ? $INITIAL_SITE_NAME_EN : $INITIAL_SITE_NAME_FA;
            // A fresh page load always starts behind the lock screen. When the
            // decoy is active its markup is written straight into the HTML, so
            // the messenger is never painted - not even for one frame - behind it.
            $LOCK_BOOT = null;
            $LOCK_BOOT_LANG = $INITIAL_LANG;
            $LOCK_BOOT_PREAUTH = false;
            $LOCK_BOOT_PREAUTH_LOCK = false;
            try {
                $bootAuth = get_current_auth($bootDb);
                if ($bootAuth && !empty($bootAuth['user']['id'])) {
                    drop_decoy_pass_cookie();
                    $LOCK_BOOT = enforce_lock_on_fresh_page_load($bootDb, $bootAuth);
                    $LOCK_BOOT_LANG = (string)$bootAuth['user']['lang'];
                } else if ((int)Settings::get($bootDb, 'force_decoy_screen', 0) === 1) {
                    // Nobody is logged in, but the decoy is forced for everybody:
                    // it stands in front of the login screen as well, so a visitor
                    // who does not know the way in only ever sees an error page.
                    if (empty($_COOKIE[decoy_pass_cookie_name()])) {
                        $LOCK_BOOT = resolve_preauth_decoy($bootDb, $INITIAL_LANG);
                        $LOCK_BOOT_PREAUTH = is_array($LOCK_BOOT);
                    } else {
                        // The marker is spent the instant it has done its job: it
                        // exists only to let one page load through. Left alive it
                        // would silence the decoy for a whole day after a single
                        // pass, so somebody who never signs in would never see it
                        // again - the exact opposite of forcing it for everybody.
                        drop_decoy_pass_cookie();
                    }
                } else if ((int)Settings::get($bootDb, 'force_lock_screen', 0) === 1) {
                    // Exactly the decoy's rule, for the lock: while nobody is
                    // signed in the login screen's markup is not served at all.
                    // The barrier is a whole document of its own, so there is no
                    // login form in the page - hidden or otherwise.
                    if (empty($_COOKIE[preauth_lock_cookie_name()])) {
                        $LOCK_BOOT_PREAUTH_LOCK = true;
                    } else {
                        // Spent on the first load that uses it, like the decoy
                        // marker, so a single pass cannot silence the barrier.
                        drop_preauth_lock_cookie();
                    }
                }
            } catch (Exception $e) { $LOCK_BOOT = null; $LOCK_BOOT_PREAUTH = false; $LOCK_BOOT_PREAUTH_LOCK = false; } catch (Throwable $e) { $LOCK_BOOT = null; $LOCK_BOOT_PREAUTH = false; $LOCK_BOOT_PREAUTH_LOCK = false; }
            $rawLogo = (string)Settings::get($bootDb, 'site_logo', '');
            $rawFav  = (string)Settings::get($bootDb, 'site_favicon', '');
            if (parse_branding_data_uri($rawLogo)) $INITIAL_SITE_LOGO = $rawLogo;
            if (parse_branding_data_uri($rawFav)) $INITIAL_SITE_FAVICON = $rawFav;
        }
    } catch (Exception $e) {}
}
$DEFAULT_LOGO_DATA_URI = default_messenger_logo_data_uri();
$INITIAL_DISPLAY_LOGO = $INITIAL_SITE_LOGO !== '' ? $INITIAL_SITE_LOGO : $DEFAULT_LOGO_DATA_URI;
$INITIAL_FAVICON_HREF = $INITIAL_SITE_FAVICON !== '' ? $INITIAL_SITE_FAVICON : ($INITIAL_SITE_LOGO !== '' ? $INITIAL_SITE_LOGO : '?a=icon&v=009687');
if (!headers_sent()) {
    header('X-Content-Type-Options: nosniff');
    header('Referrer-Policy: strict-origin-when-cross-origin');
}
/* Serve the decoy as a document of its own before a single byte of the real page
   is written: no login form anywhere in the HTML, not even hidden, and not the
   application script either. This sits outside the try block above so that a
   failure can never fall through and serve everything anyway. */
if ($LOCK_BOOT_PREAUTH) {
    render_preauth_decoy_document($LOCK_BOOT, $LOCK_BOOT_LANG, $CSP_NONCE);
    exit;
}
if ($LOCK_BOOT_PREAUTH_LOCK) {
    render_preauth_lock_document($LOCK_BOOT_LANG, $CSP_NONCE);
    exit;
}
