/* Standalone Hybrid Live Call Window (Popover Manual Top-Layer, Beneath Lock Screen Dialog!) */
#live-call-window {
    position: fixed;
    inset: auto;
    margin: 0;
    padding: 0;
    border: 1px solid rgba(148, 163, 184, 0.28);
    background: #0b1322;
    color: #f8fafc;
    border-radius: 18px;
    box-shadow: 0 22px 60px rgba(0, 0, 0, 0.55);
    display: flex;
    flex-direction: column;
    overflow: hidden;
    z-index: 1800;
}
#live-call-window.hidden { display: none !important; }
#live-call-window[data-mode="normal"] {
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: min(860px, 94vw);
    height: min(600px, 86dvh);
}
#live-call-window[data-mode="maximized"] {
    top: 0 !important;
    left: 0 !important;
    transform: none !important;
    width: 100vw !important;
    height: 100dvh !important;
    border-radius: 0;
    border: none;
}
#live-call-window[data-mode="popup"] {
    top: 72px;
    right: 18px;
    width: min(390px, 92vw);
    height: min(310px, 56dvh);
    transform: none;
}
#live-call-window[data-mode="minimized"] {
    top: calc(12px + var(--min-stack-offset, 0px));
    left: 50%;
    transform: translateX(-50%);
    width: min(440px, 94vw) !important;
    height: 54px !important;
    min-height: 54px !important;
    max-height: 54px !important;
    border-radius: 999px;
}
#live-call-window[data-mode="maximized"] .ump-resizer {
    display: none !important;
}
#live-call-window[data-mode="minimized"] .lcw-stage {
    position: absolute !important;
    width: 1px !important;
    height: 1px !important;
    min-height: 0 !important;
    padding: 0 !important;
    margin: 0 !important;
    opacity: 0 !important;
    pointer-events: none !important;
    overflow: hidden !important;
}
#live-call-window[data-mode="minimized"] .lcw-footer,
#live-call-window[data-mode="minimized"] .lcw-speak-queue-bar,
#live-call-window[data-mode="minimized"] .lcw-quality-drawer,
#live-call-window[data-mode="minimized"] .ump-resizer,
#live-call-window[data-mode="minimized"] #lcw-btn-layout,
#live-call-window[data-mode="minimized"] #lcw-btn-swap,
#live-call-window[data-mode="minimized"] #lcw-btn-quality,
#live-call-window[data-mode="minimized"] #lcw-btn-minimize {
    display: none !important;
}
