.lcw-stage {
    flex: 1 1 0%;
    min-height: 0;
    padding: 10px;
    display: grid;
    gap: 10px;
    background: radial-gradient(circle at center, #132038 0%, #090f1c 100%);
    overflow: auto;
    align-content: stretch;
    box-sizing: border-box;
}
.lcw-stage[data-layout="grid"][data-count="1"] {
    grid-template-columns: 1fr;
    grid-auto-rows: minmax(0, 1fr);
    overflow: hidden;
}
.lcw-stage[data-layout="grid"][data-count="2"] {
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    grid-auto-rows: minmax(0, 1fr);
    overflow: hidden;
}
.lcw-stage[data-layout="grid"]:not([data-count="1"]):not([data-count="2"]) {
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
}
.lcw-stage[data-layout="grid"]:not([data-count="1"]):not([data-count="2"]) .lcw-tile {
    min-height: 120px;
}
.lcw-stage[data-layout="spotlight"] {
    display: flex;
    flex-direction: column;
    gap: 8px;
    overflow: hidden;
}
.lcw-stage[data-layout="spotlight"] .lcw-tile.primary-tile {
    flex: 1 1 0%;
    min-height: 0 !important;
    height: auto;
}
.lcw-Spotlight-strip {
    display: flex;
    gap: 8px;
    overflow-x: auto;
    overflow-y: hidden;
    flex: 0 0 clamp(68px, 21%, 98px);
    height: clamp(68px, 21%, 98px);
    min-height: 0;
    max-height: none;
    align-items: stretch;
    padding-bottom: 2px;
}
.lcw-Spotlight-strip .lcw-tile {
    height: 100% !important;
    min-height: 0 !important;
    width: auto;
    min-width: clamp(90px, 22%, 128px);
    aspect-ratio: 4 / 3;
    flex: 0 0 auto;
    border-radius: 12px !important;
    clip-path: inset(0 round 12px);
}
.lcw-Spotlight-strip .lcw-tile .avatar-lg {
    width: 38px !important;
    height: 38px !important;
    min-width: 38px !important;
    font-size: 15px !important;
}
.lcw-Spotlight-strip .lcw-tile .lcw-tile-avatar {
    padding: 4px;
    gap: 4px;
}
.lcw-tile {
    position: relative;
    background: #162238;
    border: 1.5px solid rgba(148, 163, 184, 0.22);
    border-radius: 16px !important;
    overflow: hidden !important;
    isolation: isolate;
    clip-path: inset(0 round 16px);
    display: flex;
    align-items: center;
    justify-content: center;
    min-height: 0;
    cursor: pointer;
    box-sizing: border-box;
    transition: border-color 0.16s ease, transform 0.16s ease;
}
.lcw-tile .avatar,
#live-call-window .avatar,
#global-incoming-call-bar .avatar {
    border-radius: 50% !important;
    overflow: hidden !important;
    aspect-ratio: 1 / 1;
}
.lcw-tile .avatar img,
#live-call-window .avatar img,
#global-incoming-call-bar .avatar img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    border-radius: 50% !important;
    display: block;
}
.lcw-tile.speaking {
    border-color: #10b981;
    box-shadow: 0 0 0 2px rgba(16, 185, 129, 0.35);
}
.lcw-tile.on-hold {
    filter: grayscale(0.55);
    border-color: #f59e0b;
}
.lcw-tile video,
.lcw-tile canvas.lcw-relay-canvas {
    width: 100%;
    height: 100%;
    object-fit: cover;
    display: block;
    border-radius: inherit;
    transform-origin: center center;
    transform: translate3d(var(--tile-pan-x, 0px), var(--tile-pan-y, 0px), 0) scale(var(--tile-zoom, 1));
    transition: transform 0.16s ease;
    user-select: none;
    -webkit-user-drag: none;
}
.lcw-stage[data-layout="spotlight"] .lcw-tile.primary-tile:not([data-fit="cover"]) video,
.lcw-stage[data-layout="spotlight"] .lcw-tile.primary-tile:not([data-fit="cover"]) canvas.lcw-relay-canvas {
    object-fit: contain;
    background: #070c16;
}
.lcw-tile.is-zoomed {
    cursor: grab;
    touch-action: none;
}
.lcw-tile.is-zoomed.is-panning {
    cursor: grabbing;
}
.lcw-tile.is-panning video,
.lcw-tile.is-panning canvas.lcw-relay-canvas {
    transition: none !important;
}
