}
.fw-stat-card {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 10px 11px;
    border-radius: 12px;
    background: var(--bg-surface);
    border: 1px solid var(--border);
    min-width: 0;
}
.fw-stat-ico {
    width: 36px;
    height: 36px;
    border-radius: 10px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    font-size: 16px;
    flex-shrink: 0;
}
.fw-stat-body {
    display: flex;
    flex-direction: column;
    gap: 1px;
    min-width: 0;
    flex: 1;
}
.fw-stat-val-row {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    gap: 6px;
}
.fw-stat-val {
    font-size: 17px;
    font-weight: 900;
    color: var(--text-main);
    line-height: 1.2;
}
.fw-stat-pct {
    font-size: 11px;
    font-weight: 800;
    color: var(--text-muted);
}
.fw-stat-lbl {
    font-size: 11.5px;
    font-weight: 700;
    color: var(--text-secondary);
    line-height: 1.35;
}
.m3-video-player:fullscreen,
.m3-video-player:-webkit-full-screen,
#universal-media-player:fullscreen,
#universal-media-player:-webkit-full-screen {
    width: 100vw !important;
    height: 100dvh !important;
