    margin: 0 !important;
    background: #000000 !important;
    display: flex !important;
    flex-direction: column !important;
    align-items: center !important;
    justify-content: center !important;
}
.m3-video-player:fullscreen .m3-video-stage,
.m3-video-player:-webkit-full-screen .m3-video-stage,
#universal-media-player:fullscreen .ump-body,
#universal-media-player:-webkit-full-screen .ump-body {
    flex: 1 1 auto !important;
    width: 100% !important;
    height: 100% !important;
    max-width: none !important;
    max-height: none !important;
}
.m3-video-player:fullscreen video,
.m3-video-player:-webkit-full-screen video,
#universal-media-player:fullscreen video,
#universal-media-player:-webkit-full-screen video,
#universal-media-player:fullscreen .ump-body > img,
#universal-media-player:-webkit-full-screen .ump-body > img,
video:fullscreen,
video:-webkit-full-screen {
    width: 100% !important;
