}
.m3-vid-center-btn {
    position: absolute; left: 50%; top: 50%; transform: translate(-50%, -50%);
    width: 54px; height: 54px; border-radius: 50%; border: 1.5px solid rgba(255, 255, 255, 0.35);
    background: rgba(15, 23, 42, 0.68); backdrop-filter: blur(8px); color: #fff;
    display: inline-flex; align-items: center; justify-content: center; cursor: pointer; z-index: 3;
    transition: opacity 0.2s ease, transform 0.18s ease, background 0.18s ease;
}
.m3-vid-center-btn:hover { background: rgba(0, 150, 135, 0.88); transform: translate(-50%, -50%) scale(1.06); }
.m3-vid-center-btn svg { width: 24px; height: 24px; fill: currentColor; }
.m3-video-player.is-playing .m3-vid-center-btn { opacity: 0; pointer-events: none; }
.m3-vid-top-badges {
    position: absolute; top: 8px; left: 8px; right: 8px; display: flex; align-items: center;
    justify-content: space-between; gap: 6px; z-index: 3; pointer-events: none; transition: opacity 0.22s ease;
}
.m3-vid-pill {
    pointer-events: auto; display: inline-flex; align-items: center; gap: 4px; padding: 3px 9px;
    border-radius: 999px; background: rgba(15, 23, 42, 0.72); backdrop-filter: blur(6px);
    color: #f8fafc; border: 1px solid rgba(255, 255, 255, 0.16); font-size: 11px; font-weight: 800; cursor: pointer;
}
.m3-vid-controls {
    position: absolute; left: 0; right: 0; bottom: 0; padding: 16px 10px 8px;
    background: linear-gradient(to top, rgba(9, 13, 22, 0.92), rgba(9, 13, 22, 0.45) 65%, transparent);
    display: flex; flex-direction: column; gap: 3px; z-index: 3; transition: opacity 0.22s ease;
}
.m3-video-player.controls-idle .m3-vid-controls,
.m3-video-player.controls-idle .m3-vid-top-badges { opacity: 0; pointer-events: none; }
.m3-vid-ctrl-row { display: flex; align-items: center; justify-content: space-between; gap: 8px; color: #f8fafc; }
/* One control shell shared by the audio and video players: same geometry, same
   monochrome glyph, same press feedback. Only the tint differs, because the video
   controls float over the picture while the audio controls sit on the bubble. */
.m3-med-btn {
    width: 28px; height: 28px; min-width: 28px; padding: 0; border-radius: 8px; border: none;
    display: inline-flex; align-items: center; justify-content: center;
    cursor: pointer; flex-shrink: 0; line-height: 1;
    transition: background 0.14s ease, color 0.14s ease, border-color 0.14s ease, transform 0.14s ease;
}
.m3-med-btn:active { transform: scale(0.94); }
.m3-med-btn svg {
    width: 15px; height: 15px; display: block;
    fill: none; stroke: currentColor; stroke-width: 2.1;
    stroke-linecap: round; stroke-linejoin: round;
}
.m3-vid-icon-btn { background: rgba(255, 255, 255, 0.1); color: #fff; }
.m3-vid-icon-btn:hover { background: rgba(0, 150, 135, 0.8); }
/* Safety net: the tint class is only ever a skin. If a button is built without
   the shared .m3-med-btn shell it would otherwise have no size at all and its
   glyph would vanish, so the box and the glyph keep a floor of their own. */
.m3-vid-icon-btn:not(.m3-med-btn) {
    width: 28px; height: 28px; min-width: 28px; padding: 0; border-radius: 8px; border: none;
    display: inline-flex; align-items: center; justify-content: center;
    cursor: pointer; flex-shrink: 0; line-height: 1;
}
.m3-vid-icon-btn:not(.m3-med-btn) svg {
    width: 15px; height: 15px; display: block;
    fill: none; stroke: currentColor; stroke-width: 2.1;
    stroke-linecap: round; stroke-linejoin: round;
}
.m3-vid-icon-btn:not(.m3-med-btn) svg.m3-ico-solid,
.m3-vid-icon-btn:not(.m3-med-btn) svg .m3-ico-solid { fill: currentColor; stroke: none; }
.m3-aud-icon-btn { background: var(--bg-subtle); color: var(--text-secondary); }
.m3-aud-icon-btn:hover { background: var(--primary); color: #ffffff; }
/* Filled shapes - play, pause and the speaker cone. The shared rule above strokes
   every glyph, so these opt back out of the stroke and fill instead. */
.m3-med-btn svg.m3-ico-solid,
.m3-med-btn svg .m3-ico-solid,
.m3-aud-play svg.m3-ico-solid,
.m3-aud-play svg .m3-ico-solid,
.ump-ctrl-btn svg.m3-ico-solid,
.ump-ctrl-btn svg .m3-ico-solid { fill: currentColor; stroke: none; }
.adm-feature-block {
    border: 1px dashed var(--border);
    border-radius: 10px;
    padding: 10px 11px 4px;
    margin-block-start: 12px;
}
.adm-feature-head {
    font-size: 12.5px; font-weight: 800; color: var(--text-main); margin-block-end: 3px;
}
.adm-feature-note {
    font-size: 11.5px; color: var(--text-muted); line-height: 1.55; margin: 0 0 8px;
}
.adm-feature-block .input { margin-block-end: 10px; }
.m3-med-rate {
    width: auto; min-width: 30px; padding: 0 5px;
    font-size: 10px; font-weight: 800; font-variant-numeric: tabular-nums;
}
.m3-vid-time {
    line-height: 1.35; font-size: 11px; font-weight: 800; font-family: monospace; color: #e2e8f0; margin-inline-end: auto; }
.m3-vid-seek-toast {
    line-height: 1.35;
    position: absolute; top: 42px; left: 50%; transform: translateX(-50%); padding: 4px 11px;
    border-radius: 999px; background: rgba(15, 23, 42, 0.88); color: #10b981;
    font-size: 12px; font-weight: 900; font-family: monospace; z-index: 4; opacity: 0; pointer-events: none; transition: opacity 0.14s ease;
}
.m3-vid-seek-toast.visible { opacity: 1; }
.m3-vid-docked-placeholder {
    line-height: 1.5;
    width: 100%; min-height: 165px; padding: 20px 14px; display: flex; flex-direction: column;
    align-items: center; justify-content: center; gap: 10px; text-align: center; color: #cbd5e1;
    font-size: 12.5px; font-weight: 700; background: radial-gradient(circle at center, rgba(0, 150, 135, 0.18), #090d16 78%);
}

/* Admin Statistical Reports & Interactive Calendar */
.adm-analytics-toolbar { display: flex; flex-wrap: wrap; gap: 6px; align-items: center; }
.adm-range-chip {
    padding: 6px 11px; border-radius: 999px; border: 1px solid var(--border);
    background: var(--bg-subtle); color: var(--text-secondary); font-size: 12px; font-weight: 700; cursor: pointer; transition: all 0.15s ease;
}
.adm-range-chip.active { background: var(--primary); border-color: var(--primary); color: #fff; }
.adm-cal-drawer { margin-top: 12px; padding: 12px; border-radius: 12px; background: var(--bg-subtle); border: 1px solid var(--border-strong); }
.adm-cal-grid { display: grid; grid-template-columns: repeat(7, minmax(0, 1fr)); gap: 4px; text-align: center; }
.adm-cal-wd { font-size: 11px; font-weight: 800; color: var(--text-muted); padding: 4px 0; }
.adm-cal-day { height: 32px; border-radius: 8px; border: 1px solid transparent; background: var(--bg-surface); color: var(--text-main); font-size: 12px; font-weight: 700; cursor: pointer; }
.adm-cal-day.is-empty { background: transparent; cursor: default; }
.adm-cal-day.is-today { border-color: var(--primary); }
.adm-cal-day.in-range { background: rgba(0, 150, 135, 0.16); color: var(--primary); }
.adm-cal-day.is-start, .adm-cal-day.is-end { background: var(--primary); color: #fff; font-weight: 900; }
.adm-analytics-kpi-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(195px, 1fr)); gap: 10px; margin-bottom: 12px; }
.adm-analytics-kpi-card { padding: 12px 14px; border-radius: 13px; background: var(--bg-surface); border: 1px solid var(--border); display: flex; flex-direction: column; gap: 5px; }
.adm-analytics-kpi-val { font-size: 20px; font-weight: 900; color: var(--text-main); }
.adm-analytics-kpi-sub { font-size: 11px; color: var(--text-muted); line-height: 1.45; }
.adm-analytics-delta { padding: 2px 7px; border-radius: 999px; font-size: 10.5px; font-weight: 800; }
.adm-analytics-delta.up { background: rgba(16, 185, 129, 0.15); color: #10b981; }
.adm-analytics-delta.down { background: rgba(239, 68, 68, 0.14); color: var(--danger); }
.adm-analytics-delta.flat { background: var(--bg-subtle); color: var(--text-muted); }
.adm-svg-chart-wrap { width: 100%; padding: 8px 4px 2px; color: var(--text-main); }
.adm-bar-row { display: flex; flex-direction: column; gap: 4px; margin-bottom: 9px; }
.adm-bar-track { width: 100%; height: 7px; border-radius: 999px; background: var(--bg-subtle); overflow: hidden; }
.adm-bar-fill { height: 100%; border-radius: 999px; background: linear-gradient(90deg, var(--primary), #10b981); }
.btn-amber-action {
    background: rgba(245, 158, 11, 0.14);
    border: 1.5px solid rgba(245, 158, 11, 0.48);
    color: #d97706;
    font-weight: 800;
}
[data-theme="dark"] .btn-amber-action {
    background: rgba(245, 158, 11, 0.16);
    border-color: rgba(245, 158, 11, 0.52);
    color: #fbbf24;
}
.btn-amber-action:hover:not(:disabled) {
    background: rgba(245, 158, 11, 0.24);
}
.settings-save-bar {
    padding: 12px 0 4px;
    margin-top: 12px;
    border-top: 1px solid var(--border);
}
/* The general settings tab runs long enough that its save button could sit far
   below whatever had just been edited. Pinning the bar to the bottom of the
   scroll area keeps it beside the work, the same way the search field is held
   at the top. The negative offset is the same trick used there: the scroll
   container carries 16px of padding, so a plain `bottom: 0` would park the bar
   on the content edge and leave that strip uncovered, letting cards show
   through below it. The offset only applies once the bar is actually stuck. */
.adm-sticky-save-card {
    position: sticky;
    bottom: -16px;
    z-index: 8;
    box-shadow: 0 -6px 18px rgba(0, 0, 0, 0.22);
}
/* While the bar is pinned it sits flush against the bottom edge of the scroll
   area, and a rounded underside leaves the page showing through at the corners.
   Once it settles into its own place at the end of the content it is an ordinary
   card again and is rounded all round. Logical properties, so the corners flip
   correctly in the right-to-left layout. */
.adm-sticky-save-card.adm-save-stuck {
    border-end-start-radius: 0;
    border-end-end-radius: 0;
}
.adm-online-banner {
    display: flex;
    align-items: center;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 10px;
    padding: 10px 14px;
    margin-block-end: 12px;
    border-radius: 13px;
    background: var(--bg-elevated);
    border: 1px solid var(--border-strong);
}
.online-dot-live {
    width: 9px;
    height: 9px;
    border-radius: 50%;
    background: #10b981;
    box-shadow: 0 0 0 3px rgba(16, 185, 129, 0.22);
    display: inline-block;
    flex-shrink: 0;
}
.fw-stat-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(145px, 1fr));
    gap: 10px;
    margin-block: 10px 14px;
}
.fw-stat-card {
    padding: 11px 12px;
    border-radius: 12px;
    background: var(--bg-subtle);
    border: 1px solid var(--border);
    display: flex;
    flex-direction: column;
    gap: 4px;
}
.fw-stat-val {
    font-size: 20px;
    font-weight: 800;
    color: var(--primary);
}
.fw-stat-lbl {
    font-size: 11.5px;
    font-weight: 700;
    color: var(--text-muted);
}
.m3-custom-select-popup {
    position: fixed;
    z-index: 2147483640;
    background: var(--bg-surface);
    color: var(--text-main);
    border: 1px solid var(--border-strong);
    border-radius: 12px;
    box-shadow: 0 14px 38px rgba(0, 0, 0, 0.34);
    padding: 5px;
    max-height: min(320px, 68vh);
    overflow-y: auto;
    overscroll-behavior: contain;
    font-family: var(--font-sans);
    box-sizing: border-box;
}
.m3-custom-select-opt {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 10px;
    width: 100%;
    text-align: start;
    padding: 8px 11px;
    border: none;
    border-radius: 8px;
    background: transparent;
    color: var(--text-main);
    font-family: var(--font-sans);
    font-size: 13px;
    line-height: 1.55;
    cursor: pointer;
    white-space: normal;
    word-break: break-word;
    unicode-bidi: plaintext;
    transition: background 0.12s ease;
}
.m3-custom-select-opt:hover,
.m3-custom-select-opt:focus-visible {
    background: var(--bg-hover);
    outline: none;
}
.m3-custom-select-opt.active {
    background: var(--primary-soft);
    color: var(--primary);
    font-weight: 700;
}
.m3-custom-select-opt[disabled] {
    opacity: 0.45;
    cursor: not-allowed;
}

/* Direct Camera Capture Viewfinder */
.cam-capture-stage {
    position: relative;
    width: 100%;
    aspect-ratio: 4 / 3;
    max-height: 56vh;
    background: #0b1220;
    border-radius: 14px;
    overflow: hidden;
    display: flex;
    align-items: center;
    justify-content: center;
    border: 1px solid var(--border-strong);
}
.cam-capture-stage video,
.cam-capture-stage img {
    width: 100%;
    height: 100%;
    object-fit: contain;
    display: block;
}
.cam-capture-stage video.mirrored {
    transform: scaleX(-1);
}

/* Password Strength Checklist Pill */
.pw-strength-guide {
    margin: 6px 0 12px;
    padding: 7px 10px;
    border-radius: 10px;
    background: var(--bg-subtle);
    border: 1px solid var(--border);
    font-size: 11.5px;
    line-height: 1.55;
    color: var(--text-secondary);
}
.pw-strength-guide.valid {
    border-color: rgba(16, 185, 129, 0.45);
    color: #10b981;
}
.pw-strength-guide.invalid {
    border-color: rgba(239, 68, 68, 0.45);
    color: var(--danger);
}

@media (max-width: 780px) {
    .composer-wrap {
        flex-shrink: 0;
        padding: 7px 8px max(8px, env(safe-area-inset-bottom));
    }
    .composer-bar {
        display: flex;
        flex-wrap: wrap;
        align-items: flex-end;
        gap: 6px;
    }
    .composer-bar > .composer-input-box {
        order: 1;
        flex: 1 1 calc(100% - 50px);
        min-width: 0;
        min-height: 42px;
        align-items: flex-end;
        padding: 4px 8px;
    }
    .composer-bar > .composer-input-box > .icon-btn,
    .composer-bar > .composer-input-box > .ttl-pill-group {
        align-self: flex-end;
        margin-block: 0 2px;
    }
    .composer-bar > .composer-input-box > .composer-input {
        max-height: 132px;
    }
    .composer-bar > #btn-send-msg {
        order: 2;
        flex: 0 0 42px;
        width: 42px;
        height: 42px;
        min-width: 42px;
        align-self: flex-end;
    }
    .composer-bar > #btn-attach-file,
    .composer-bar > .composer-aux-media-btn {
        order: 3;
        flex: 1 1 0;
        height: 36px;
        min-width: 40px;
        padding: 0;
        border-radius: 11px;
        background: var(--bg-subtle);
        border: 1px solid var(--border);
        display: inline-flex;
        align-items: center;
        justify-content: center;
        flex-shrink: 0;
    }
    .composer-bar > .composer-aux-media-btn.hidden,
    .composer-bar > .icon-btn.hidden {
        display: none !important;
    }
    .chat-header { padding: 0 8px; gap: 4px; }
    .chat-header-actions .icon-btn {
        width: 34px;
        height: 34px;
        min-width: 34px;
    }
}

/* Unified Responsive Settings, Sub-Category Pills & Profile/Moderation UX */
.settings-sub-pills {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
    padding: 6px;
    background: var(--bg-elevated);
    border: 1px solid var(--border);
    border-radius: 11px;
    margin-block-end: 12px;
}
.settings-sub-pill {
    padding: 6px 11px;
    border-radius: 8px;
    font-size: 12px;
    font-weight: 700;
    color: var(--text-secondary);
    background: var(--bg-surface);
    border: 1px solid var(--border);
    cursor: pointer;
    white-space: nowrap;
    flex-shrink: 0;
    transition: all 0.14s ease;
}
.settings-sub-pill:hover {
    color: var(--primary);
    border-color: var(--primary);
}
.settings-sub-pill.active {
    background: var(--primary-soft);
    color: var(--primary);
    border-color: var(--primary);
    font-weight: 800;
}
.profile-avatar-editor {
    display: flex;
    align-items: center;
    gap: 12px;
    flex-wrap: wrap;
    padding: 12px;
    border-radius: 12px;
    border: 1px solid var(--border);
    background: var(--bg-subtle);
    margin-block-end: 12px;
}
.profile-avatar-editor .avatar-lg {
    width: 64px;
    height: 64px;
    min-width: 64px;
    font-size: 24px;
}
.profile-avatar-editor-actions {
    display: flex;
    flex-direction: column;
    gap: 6px;
    flex: 1;
    min-width: 180px;
}
.settings-sticky-save-bar {
    position: sticky;
    bottom: -4px;
    z-index: 6;
    padding: 10px 0 4px;
    margin-top: 8px;
    background: linear-gradient(180deg, transparent 0%, var(--bg-surface) 28%);
}
.member-mod-toolbar {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    align-items: center;
    margin-block-end: 10px;
}
.status-chip-banned {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    font-size: 10.5px;
    font-weight: 800;
    padding: 2px 7px;
    border-radius: 999px;
    background: rgba(239, 68, 68, 0.14);
    color: var(--danger);
    border: 1px solid rgba(239, 68, 68, 0.32);
}
.status-chip-shadow {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    font-size: 10.5px;
    font-weight: 800;
    padding: 2px 7px;
    border-radius: 999px;
    background: rgba(99, 102, 241, 0.15);
    color: #6366f1;
    border: 1px solid rgba(99, 102, 241, 0.35);
}
[data-theme="dark"] .status-chip-shadow {
    color: #a5b4fc;
}

/* ---- Member list cards: identity and actions live on separate rows so the
        action buttons can never sit on top of the name or each other. ---- */
.mem-card {
    padding: 10px 12px !important;
    margin-bottom: 8px;
    overflow: hidden;
}
.mem-identity {
    display: flex;
    align-items: center;
    gap: 10px;
    min-width: 0;
    cursor: pointer;
    padding: 2px 0;
    border-radius: 10px;
}
.mem-identity:hover .mem-name {
    color: var(--primary);
}
.mem-identity-text {
    min-width: 0;
    flex: 1 1 auto;
}
.mem-name-line {
    display: flex;
    align-items: center;
    gap: 5px;
    flex-wrap: wrap;
    font-weight: 700;
    font-size: 13.5px;
}
.mem-name {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    max-width: 100%;
    transition: color 0.15s ease;
}
.mem-handle {
    font-size: 11.5px;
    color: var(--text-muted);
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}
.mem-actions {
    display: flex;
    align-items: center;
    gap: 6px;
    flex-wrap: wrap;
    margin-top: 9px;
    padding-top: 9px;
    border-top: 1px solid var(--border);
}
.mem-more-btn {
    min-width: 38px;
    font-weight: 900;
    letter-spacing: 1px;
}
.mem-overflow-head {
    display: flex;
    align-items: center;
    gap: 9px;
    padding: 2px 4px 10px;
    margin-bottom: 6px;
    border-bottom: 1px solid var(--border);
}

/* Marker an admin sees on a message a shadow-banned member cannot publish. */
.msg-shadow-flag {
    display: inline-flex;
    align-items: center;
    gap: 3px;
    font-size: 10px;
    font-weight: 800;
    padding: 1px 6px;
    border-radius: 999px;
    background: rgba(99, 102, 241, 0.15);
    color: #6366f1;
    border: 1px solid rgba(99, 102, 241, 0.35);
    vertical-align: middle;
    margin-inline-start: 6px;
}
[data-theme="dark"] .msg-shadow-flag {
    color: #a5b4fc;
}

.msg-act-btn {
    font-size: 15px;
    line-height: 1;
    color: inherit;
    opacity: 0.75;
    min-width: 28px;
    min-height: 28px;
    padding: 0 6px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border-radius: 50%;
    transition: background 0.15s ease, opacity 0.15s ease;
}
.msg-act-btn:hover,
.msg-act-btn:focus-visible {
    opacity: 1;
    background: var(--bg-hover, rgba(127, 127, 127, 0.16));
}
.settings-chk-row {
    display: flex;
    align-items: center;
    gap: 10px;
    min-height: 36px;
    padding: 4px 8px;
    margin-bottom: 4px;
    font-size: 13px;
    border-radius: var(--radius-sm);
    cursor: pointer;
    transition: background 0.15s ease;
}
.settings-chk-row:hover {
    background: var(--bg-surface);
}
.settings-chk-row input[type="checkbox"] {
    width: 18px;
    height: 18px;
    accent-color: var(--primary);
    flex-shrink: 0;
}
/* This pill toggles a per-user upload block. It shipped with no styling at all,
   so it rendered as a bare browser-default button with no visual state. */
.ban-pill {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 4px;
    padding: 2px 10px;
    min-height: 27px;
    font-size: 11px;
    font-weight: 700;
    border-radius: 999px;
    border: 1px solid var(--border-strong);
    background: var(--bg-subtle);
    color: var(--text-main);
    cursor: pointer;
    transition: background 0.15s ease, border-color 0.15s ease, color 0.15s ease;
}
.ban-pill:hover {
    border-color: var(--danger);
    color: var(--danger);
}
.ban-pill.active {
    border-color: var(--danger);
    background: rgba(239, 68, 68, 0.12);
    color: var(--danger);
}
.status-chip-2fa {
    display: inline-flex;
    align-items: center;
    gap: 3px;
    font-size: 10.5px;
    font-weight: 800;
    padding: 2px 7px;
    border-radius: 999px;
    background: rgba(16, 185, 129, 0.13);
    color: #10b981;
    border: 1px solid rgba(16, 185, 129, 0.3);
}
@media (max-width: 768px) {
    .adm-nav-pills,
    .settings-sub-pills {
        flex-wrap: nowrap;
        overflow-x: auto;
        overflow-y: hidden;
        -webkit-overflow-scrolling: touch;
        scrollbar-width: none;
        padding: 6px;
        gap: 6px;
    }
    .adm-nav-pills::-webkit-scrollbar,
    .settings-sub-pills::-webkit-scrollbar {
        display: none;
    }
    .adm-nav-btn {
        padding: 7px 11px;
        font-size: 12px;
    }
    .profile-avatar-editor {
        padding: 10px;
        gap: 10px;
    }
}
