function t(key) {
    const dict = I18N[store.lang] || I18N.fa;
    return dict[key] !== undefined ? dict[key] : (I18N.fa[key] || key);
}

function formatDisplayName(name) {
    const s = String(name || '');
    if (s.includes('Deleted Account') || s.includes('حساب حذف‌شده') || s === 'کاربر حذف‌شده') {
        return t('deleted_account_name');
    }
    return s;
}

function formatUserBio(bio) {
    const s = String(bio || '');
    if (s === 'مدیر کل سامانه / System Super-Admin') {
        return t('default_admin_bio');
    }
    return s;
}

function formatSiteName() {
    const isEn = store.lang === 'en';
    const s = store.settings || {};
    const fromSettings = isEn ? String(s.site_name_en || '').trim() : String(s.site_name_fa || '').trim();
    if (fromSettings) {
        if (!isEn && (fromSettings === 'پیامرسان کوچک من' || fromSettings === 'پیام‌رسان کوچک من')) {
            return 'پیامرسان کوچک من (M3)';
        }
        return fromSettings;
    }
    const attrName = document.documentElement.getAttribute(isEn ? 'data-site-en' : 'data-site-fa') || '';
    if (attrName.trim()) return attrName.trim();
    const raw = s.site_name ? String(s.site_name).trim() : '';
    const defaultBrandSet = [
        '',
        'My Mini Messenger (M3)',
        'M3',
        'پیامرسان کوچک من',
        'پیامرسان کوچک من (M3)',
        'پیام‌رسان کوچک من',
        'Payamak Messenger',
        'پیامک',
        'پیام‌رسان پیامک',
        'پیامک / Payamak'
    ];
    if (defaultBrandSet.includes(raw)) {
        return t('app_name');
    }
    return raw;
}

function formatHandleLabel(uOrStr) {
    if (!uOrStr) return t('no_username_badge');
    if (typeof uOrStr === 'object' && uOrStr.no_username) return t('no_username_badge');
    const raw = (typeof uOrStr === 'object') ? String(uOrStr.username || '') : String(uOrStr || '');
    const clean = raw.replace(/^@+/, '').trim();
    return clean ? ('@' + clean) : t('no_username_badge');
}

function resizeImageFileToAvatarDataUri(file) {
    return new Promise((resolve, reject) => {
        if (!file) return reject(new Error('No file'));
        const reader = new FileReader();
        reader.onerror = () => reject(new Error('Read failed'));
        reader.onload = ev => {
            const img = new Image();
            img.onerror = () => reject(new Error('Invalid image'));
            img.onload = () => {
                const canvas = document.createElement('canvas');
                const size = 160;
                canvas.width = size;
                canvas.height = size;
                const ctx = canvas.getContext('2d');
                const minSide = Math.min(img.width, img.height);
                const sx = (img.width - minSide) / 2;
                const sy = (img.height - minSide) / 2;
                ctx.drawImage(img, sx, sy, minSide, minSide, 0, 0, size, size);
                let out = canvas.toDataURL('image/webp', 0.84);
                if (!out.startsWith('data:image/webp')) {
                    out = canvas.toDataURL('image/jpeg', 0.84);
                }
                resolve(out);
            };
            img.src = ev.target.result;
        };
        reader.readAsDataURL(file);
    });
}

function formatChatTitle(chat) {
    if (!chat) return '';
    if (chat.type === 'saved') return t('saved_messages_title');
    if (chat.type === 'system') return stripLeadingEmoji(t('system_chat_title'));
    const rawTitle = String(chat.title || '');
    if (Number(chat.is_default) === 1 || rawTitle.includes('General Group') || rawTitle.includes('Official Channel')) {
        if (chat.type === 'group' && (rawTitle.includes('General Group') || rawTitle.includes('گروه عمومی'))) {
            return t('default_group_title');
        }
        if (chat.type === 'channel' && (rawTitle.includes('Official Channel') || rawTitle.includes('کانال اطلاع'))) {
            return t('default_channel_title');
        }
    }
    if ((chat.type === 'dm' || chat.type === 'secret') && chat.peer && chat.peer.name) {
        return formatDisplayName(chat.peer.name);
    }
    return formatDisplayName(rawTitle) || t('app_name');
}

function formatChatDescription(chat) {
    if (!chat) return '';
    if (chat.type === 'saved') return t('saved_messages_desc');
    if (chat.type === 'system') return t('system_chat_desc');
    const d = String(chat.description || '');
    if (d.includes('گروه پیشفرض سامانه') || d.includes('Default system group')) {
        return t('default_group_desc');
    }
    if (d.includes('کانال رسمی اطلاع‌رسانی سامانه') || d.includes('Official announcement channel')) {
        return t('default_channel_desc');
    }
    return d;
}

function formatDynamicServerText(text) {
    const s = String(text || '');
    if (!s) return '';
    const sysRegMatch = s.match(/\[M3_SYS_REGISTER:(\d+)\]/);
    if (sysRegMatch) {
        const tsNum = parseInt(sysRegMatch[1], 10) || Math.floor(Date.now() / 1000);
        return t('sys_account_created_tpl').replace('{time}', formatFullTime(tsNum));
    }
    const sysLoginMatch = s.match(/\[M3_SYS_LOGIN:(\d+)\]/);
    if (sysLoginMatch) {
        const tsNum = parseInt(sysLoginMatch[1], 10) || Math.floor(Date.now() / 1000);
        return t('sys_login_notice_tpl').replace('{time}', formatFullTime(tsNum));
    }
    if (s.includes('[M3_SYS_AUTONOMOUS]')) {
        return t('sys_autonomous_notice_full');
    }
    if (s.startsWith('{') && s.includes('"call_type"')) {
        try {
            const cl = JSON.parse(s);
            const ic = cl.call_type === 'video' ? '🎥 ' + t('call_log_video_lbl') : '📞 ' + t('call_log_audio_lbl');
            const st = ['ringing', 'active', 'started', 'ended', 'missed', 'declined', 'busy'].includes(String(cl.status)) ? t('call_log_status_' + cl.status) : '';
            const dur = Number(cl.duration_sec || 0) > 0 ? (' • ' + formatAudioClock(Number(cl.duration_sec))) : '';
            return st ? `${ic} • ${st}${dur}` : ic;
        } catch (e) {}
    }
    const callPrevMatch = s.match(/^(🎥 تماس تصویری|📞 تماس صوتی)\s*\(([^)]+)\)$/);
    if (callPrevMatch) {
        const isVid = callPrevMatch[1].startsWith('🎥');
        const stRaw = callPrevMatch[2];
        const stMap = {
            'بی‌پاسخ': 'missed',
            'رد شده': 'declined',
            'خط مشغول': 'busy',
            'در حال زنگ...': 'ringing',
            'در جریان': 'active',
            'پاسخ داده شد': 'ended'
        };
        const stKey = stMap[stRaw] || 'ended';
        return `${isVid ? '🎥' : '📞'} ${isVid ? t('call_log_video_lbl') : t('call_log_audio_lbl')} (${t('call_log_status_' + stKey)})`;
    }
    if (s === '🎥 Video Call' || s === '🎥 تماس تصویری') return '🎥 ' + t('call_log_video_lbl');
    if (s === '📞 Audio Call' || s === '📞 تماس صوتی') return '📞 ' + t('call_log_audio_lbl');
    if (s.includes('پیام رمزنگاری‌شده (E2EE)')) return t('e2ee_encrypted_preview');
    if (s.includes('ارسال پیام در گروه توسط مدیر محدود شد')) return t('sys_group_muted');
    if (s.includes('محدودیت ارسال پیام گروه برداشته شد')) return t('sys_group_unmuted');
    if (s.includes('درخواست گفتگوی محرمانه ارسال شد')) return t('sys_secret_req_sent');
    if (s.includes('گفتگوی محرمانه تایید شد') || s.includes('گفتگوی محرمانه تایید و آغاز شد')) return t('sys_secret_accepted');
    if (s.includes('گفتگوی محرمانه با رمزنگاری سرتاسری')) return t('sys_secret_started');
    if (s.includes('Welcome to the Default System Group') || s.includes('این گروه عمومی سامانه است')) return t('sys_welcome_group');
    if (s.includes('Official announcements are posted in this') || s.includes('اطلاعیه‌های مهم مدیریت در این کانال')) return t('sys_welcome_channel');
    if (s.includes('فایل توسط فرستنده حذف شد') || s.includes('File deleted by uploader')) return t('sys_file_deleted_uploader');
    if (s.includes('فایل قدیمی به‌صورت خودکار') || s.includes('Old file purged')) return t('sys_old_file_purged');
    if (s.includes('فایل حذف شد') || s.includes('File deleted]')) return t('sys_file_deleted');
    if (s.includes('مالکیت گروه به قدیمی‌ترین عضو')) {
        const m = s.match(/\(([^)]+)\)/);
        if (store.lang === 'en') return `👑 Group ownership was transferred to the oldest member${m ? ' (' + m[1] + ')' : ''}.`;
        return s;
    }
    if (s.includes('مالکیت کانال به قدیمی‌ترین عضو')) {
        const m = s.match(/\(([^)]+)\)/);
        if (store.lang === 'en') return `👑 Channel ownership was transferred to the oldest member${m ? ' (' + m[1] + ')' : ''}.`;
        return s;
    }
    if (s.includes('سمت سوپرادمین سامانه به قدیمی‌ترین عضو')) {
        const m = s.match(/\(([^)]+)\)/);
        if (store.lang === 'en') return `🛡️ System Super-Admin role was transferred to the oldest member${m ? ' (' + m[1] + ')' : ''}.`;
        return s;
    }
    if (s.includes('به‌صورت خودگردان فعالیت می‌کند')) return t('sys_autonomous_activated');
    return s;
}

// Member counts are always shown as "<n> عضو" (Persian uses the singular after a
// number), and anything from 1000 up is abbreviated so a large group stays on one
// line: 1400 -> 1.4k, 12500 -> 13k, 2400000 -> 2.4M (digits localised, suffix Latin).
function formatMemberCount(val) {
    const n = Number(val);
    if (!Number.isFinite(n) || n < 0) return formatLocalizedCount(0);
    if (n < 1000) return formatLocalizedCount(n);
    const abbrev = (div, suffix) => {
        const v = n / div;
        const s = (v < 10) ? (Math.floor(v * 10) / 10) : Math.round(v);
        return formatLocalizedCount(String(s)) + suffix;
    };
    if (n < 1000000) return abbrev(1000, 'k');
    return abbrev(1000000, 'M');
}

function formatLocalizedCount(val) {
    const s = String(val === null || val === undefined ? '' : val);
    if (store.lang === 'fa') {
        return s.replace(/\d/g, d => '۰۱۲۳۴۵۶۷۸۹'[Number(d)]);
    }
    return s;
}

