function makeHdrSvgNode(svgStr, cls = 'hdr-mono-ico') {
    const sp = document.createElement('span');
    sp.className = cls;
    sp.innerHTML = svgStr;
    return sp;
}

// Site founder (owner) vs appointed super-admins. The server is the real
// boundary - it rejects every founder-only action with 403 - these helpers only
// keep the UI from advertising controls the signed-in admin cannot use.
function isSiteFounder() {
    return !!(store.user && Number(store.user.is_founder) === 1);
}
function markFounderOnly(el) {
    if (!el) return el;
    el.setAttribute('data-founder-only', '1');
    // Hide straight away as well: some of these cards are built asynchronously
    // and would otherwise land after the sweep had already run.
    if (!isSiteFounder()) el.style.display = 'none';
    return el;
}
function applyFounderOnlyVisibility(root) {
    if (isSiteFounder()) return;
    const scope = root || document;
    const nodes = scope.querySelectorAll('[data-founder-only]');
    for (let i = 0; i < nodes.length; i++) {
        nodes[i].style.display = 'none';
    }
}

function stripLeadingEmoji(str) {
    return String(str || '').replace(/^[\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}\u{FE0F}\u{200D}➕✖✓✔•]+\s*/u, '').trim();
}

function getIdentityLenLimits() {
    const s = (store && store.settings) ? store.settings : {};
    let uMin = Math.max(2, Math.min(32, parseInt(s.username_min_len ?? 3, 10) || 3));
    let uMax = Math.max(3, Math.min(64, parseInt(s.username_max_len ?? 24, 10) || 24));
    if (uMin > uMax) uMin = uMax;
    let nMin = Math.max(1, Math.min(60, parseInt(s.display_name_min_len ?? 2, 10) || 2));
    let nMax = Math.max(2, Math.min(120, parseInt(s.display_name_max_len ?? 40, 10) || 40));
    if (nMin > nMax) nMin = nMax;
    return { uMin, uMax, nMin, nMax };
}

function formatIdentityNum(n) {
    return store.lang === 'fa'
        ? String(n).replace(/\d/g, d => '۰۱۲۳۴۵۶۷۸۹'[Number(d)])
        : String(n);
}

function formatUsernameLenHint(customMin, customMax) {
    const lim = getIdentityLenLimits();
    const mn = customMin !== undefined ? customMin : lim.uMin;
    const mx = customMax !== undefined ? customMax : lim.uMax;
    return t('uname_len_hint_tpl')
        .replace('{min}', formatIdentityNum(mn))
        .replace('{max}', formatIdentityNum(mx));
}

function formatDisplayNameLenHint(customMin, customMax) {
    const lim = getIdentityLenLimits();
    const mn = customMin !== undefined ? customMin : lim.nMin;
    const mx = customMax !== undefined ? customMax : lim.nMax;
    return t('dname_len_hint_tpl')
        .replace('{min}', formatIdentityNum(mn))
        .replace('{max}', formatIdentityNum(mx));
}

function formatInvalidUsernameErr(customMin, customMax) {
    const lim = getIdentityLenLimits();
    const mn = customMin !== undefined ? customMin : lim.uMin;
    const mx = customMax !== undefined ? customMax : lim.uMax;
    return t('err_invalid_username_tpl')
        .replace('{min}', formatIdentityNum(mn))
        .replace('{max}', formatIdentityNum(mx));
}

function formatInvalidDisplayNameErr(customMin, customMax) {
    const lim = getIdentityLenLimits();
    const mn = customMin !== undefined ? customMin : lim.nMin;
    const mx = customMax !== undefined ? customMax : lim.nMax;
    return t('err_invalid_display_name_tpl')
        .replace('{min}', formatIdentityNum(mn))
        .replace('{max}', formatIdentityNum(mx));
}

function countUnicodeChars(str) {
    return Array.from(String(str || '')).length;
}

function applyAuthIdentityInputLimits() {
    const lim = getIdentityLenLimits();
    const regU = document.getElementById('reg-username-input');
    if (regU) {
        regU.minLength = lim.uMin;
        regU.maxLength = lim.uMax;
    }
    const regUHint = document.getElementById('reg-username-hint');
    if (regUHint) {
        regUHint.textContent = formatUsernameLenHint(lim.uMin, lim.uMax);
    }
    const regN = document.getElementById('reg-name-input');
    if (regN) {
        regN.minLength = lim.nMin;
        regN.maxLength = lim.nMax;
    }
    const regNHint = document.getElementById('reg-name-hint');
    if (regNHint) {
        regNHint.textContent = formatDisplayNameLenHint(lim.nMin, lim.nMax);
    }
}

/* An explicit language toggle (auth screen / sidebar / installer) is a deliberate
 * user action and must survive login, where the account preference is otherwise
 * pulled from the server. Passing explicit=true records the override; explicit=false
 * clears it (used once the choice has been saved into the account itself). */
function setLangExplicitOverride(on) {
    try {
        if (on) localStorage.setItem('pm_lang_explicit', '1');
        else localStorage.removeItem('pm_lang_explicit');
    } catch (e) {}
}
function hasLangExplicitOverride() {
    try { return localStorage.getItem('pm_lang_explicit') === '1'; } catch (e) { return false; }
}
/* Language to use right after a login/account sync: honour a live explicit
 * override, otherwise fall back to the stored account preference. */
function getLoginLangForUser(userLang, fallbackLang) {
    return hasLangExplicitOverride() ? (fallbackLang || store.lang) : (userLang || fallbackLang || store.lang);
}

function applyLangAndTheme(lang, theme, explicit) {
    if (lang) {
        if (explicit === true) setLangExplicitOverride(true);
        else if (explicit === false) setLangExplicitOverride(false);
        store.lang = (lang === 'en') ? 'en' : 'fa';
        localStorage.setItem('pm_lang', store.lang);
        document.documentElement.lang = store.lang;
        document.documentElement.dir = (store.lang === 'en') ? 'ltr' : 'rtl';
    }
    if (theme) {
        store.theme = ['auto', 'light', 'dark'].includes(theme) ? theme : 'auto';
        localStorage.setItem('pm_theme', store.theme);
        document.documentElement.setAttribute('data-theme', store.theme);
    }
    document.querySelectorAll('[data-i18n]').forEach(el => {
        const k = el.getAttribute('data-i18n');
        if (k) el.textContent = t(k);
    });
    document.querySelectorAll('[data-i18n-ph]').forEach(el => {
        const k = el.getAttribute('data-i18n-ph');
        if (k) el.placeholder = t(k);
    });
    document.querySelectorAll('[data-i18n-title]').forEach(el => {
        const k = el.getAttribute('data-i18n-title');
        if (k) el.title = t(k);
    });
    applyAuthIdentityInputLimits();
    const authLangBtn = document.getElementById('auth-lang-btn');
    if (authLangBtn) {
        authLangBtn.textContent = store.lang === 'fa' ? '🌍 English' : '🌍 فارسی';
        authLangBtn.title = t('tip_lang');
    }
    const instLangBtn = document.getElementById('inst-lang-btn');
    if (instLangBtn) {
        instLangBtn.textContent = store.lang === 'fa' ? '🌍 English' : '🌍 فارسی';
    }
    const sideLangBtn = document.getElementById('btn-lang-toggle');
    if (sideLangBtn) {
        sideLangBtn.title = t('tip_lang');
    }
    document.querySelectorAll('.pw-toggle-btn').forEach(btn => {
        const isShown = btn.classList.contains('is-shown');
        const lbl = t(isShown ? 'hide_password' : 'show_password');
        btn.title = lbl;
        btn.setAttribute('aria-label', lbl);
    });
    const instErrBox = document.getElementById('inst-error-box');
    if (instErrBox && !instErrBox.classList.contains('hidden') && instErrBox._lastErr) {
        instErrBox.textContent = '⚠️ ' + localizeApiError(instErrBox._lastErr.code, instErrBox._lastErr.message, instErrBox._lastErr.details);
    }
    const instLangSel = document.getElementById('inst-lang-select');
    if (instLangSel && instLangSel.value !== store.lang) {
        instLangSel.value = store.lang;
    }
    const instSiteIn = document.getElementById('inst-site-name');
    if (instSiteIn && ['پیامرسان کوچک من', 'پیام‌رسان کوچک من', 'My Mini Messenger (M3)', 'پیام‌رسان پیامک', 'Payamak Messenger'].includes(instSiteIn.value.trim())) {
        instSiteIn.value = t('app_name');
    }
    const instAdmName = document.getElementById('inst-admin-name');
    if (instAdmName && (instAdmName.value === 'مدیر سامانه' || instAdmName.value === 'مدیر کل سامانه' || instAdmName.value === 'System Administrator')) {
        instAdmName.value = t('inst_admin_name_val');
    }
    const authSiteTitle = document.getElementById('auth-site-title');
    if (authSiteTitle) {
        authSiteTitle.textContent = formatSiteName();
    }
    if (!store.user) {
        document.title = formatSiteName();
    }
    updateThemeButtonsUI(store.theme);
    syncTtlControlUI();
    const ttlPop = document.getElementById('ttl-popover');
    if (ttlPop && !ttlPop.classList.contains('hidden')) {
        renderTtlPopoverMenu();
    }
    if (store.user) {
        renderChatList();
        if (store.activeChatId) renderActiveChatHeader();
    }
}

function esc(s) {
    return String(s === null || s === undefined ? '' : s).replace(/[&<>"']/g, ch => ({
        '&': '&amp;',
        '<': '&lt;',
        '>': '&gt;',
        '"': '&quot;',
        "'": '&#39;'
    }[ch]));
}

function isSelfDestructMessage(msg) {
    return Boolean(msg && ((Number(msg.burn_after) > 0) || (Number(msg.expires_at) > 0)));
}

function isZeroSaveProtected(msg, chat) {
    if (isSelfDestructMessage(msg)) return true;
    if (chat && chat.type === 'secret') return true;
    if (msg && (msg.cipher || (msg.file && Number(msg.file.encrypted) === 1))) return true;
    return false;
}

function bindZeroSaveDomGuards(el) {
    if (!el) return;
    el.classList.add('m3-zero-save');
    el.draggable = false;
    el.addEventListener('contextmenu', e => {
        e.preventDefault();
        e.stopPropagation();
    });
    el.addEventListener('dragstart', e => e.preventDefault());
}

// Universal right-click + mouse long-press + touch long-press parity helper (Item 7)
function bindContextAndHold(el, openFn, holdMs = 460, opts = {}) {
    if (!el || typeof openFn !== 'function') return;
    let holdTimer = null;
    let startX = 0;
    let startY = 0;
    let suppressClickUntil = 0;

    const cancelHold = () => {
        if (holdTimer) {
            clearTimeout(holdTimer);
            holdTimer = null;
        }
    };

    el.addEventListener('contextmenu', e => {
        e.preventDefault();
        e.stopPropagation();
        cancelHold();
        openFn(e.clientX, e.clientY, e);
    });

    // Callers can pass { mouseHold: false } to keep right-click and touch long-press
    // but drop the left-button hold. Desktop chat rows do exactly that: holding the
    // left button on a row is far more often a stray press or the start of a drag
    // than a deliberate request for the menu.
    if (opts.mouseHold !== false) {
        el.addEventListener('mousedown', e => {
            if (e.button !== 0) return;
            cancelHold();
            startX = e.clientX;
            startY = e.clientY;
            holdTimer = setTimeout(() => {
                holdTimer = null;
                suppressClickUntil = Date.now() + 550;
                openFn(startX, startY, e);
            }, holdMs);
        });
        el.addEventListener('mousemove', e => {
            if (!holdTimer) return;
            if (Math.hypot(e.clientX - startX, e.clientY - startY) > 8) cancelHold();
        });
        el.addEventListener('mouseup', cancelHold);
        el.addEventListener('mouseleave', cancelHold);
    }

    el.addEventListener('touchstart', e => {
        if (!e.touches || e.touches.length !== 1) return;
        cancelHold();
        startX = e.touches[0].clientX;
        startY = e.touches[0].clientY;
        holdTimer = setTimeout(() => {
            holdTimer = null;
            suppressClickUntil = Date.now() + 650;
            if (navigator.vibrate) { try { navigator.vibrate(16); } catch (err) {} }
            openFn(startX, startY, e);
        }, holdMs);
    }, { passive: true });
    el.addEventListener('touchmove', e => {
        if (!holdTimer || !e.touches || e.touches.length !== 1) return;
        if (Math.hypot(e.touches[0].clientX - startX, e.touches[0].clientY - startY) > 10) cancelHold();
    }, { passive: true });
    el.addEventListener('touchend', cancelHold);
    el.addEventListener('touchcancel', cancelHold);

    el.addEventListener('click', e => {
        if (Date.now() < suppressClickUntil) {
            suppressClickUntil = 0;
            e.preventDefault();
            e.stopPropagation();
        }
    }, true);
}

/* A touch long-press must reach the app's own action sheet, not the browser's.
 * bindContextAndHold already opens ours from a touch timer; what is missing is
 * stopping the platform menu that fires alongside it. Real mouse right-click is
 * untouched, and editable fields keep their native copy/paste menu. */
/* Browsers keep an AudioContext suspended until the user actually interacts.
 * Unlocking it on the very first gesture means the context is already running by
 * the time a call comes in, so the ringtone is audible instead of queued. */
(function unlockCallAudioOnFirstGesture() {
    // LiveCallManager is a top-level const, so it is a lexical binding and NOT a
    // property of window - referencing window.LiveCallManager would be undefined.
    // It is read inside the handler, which runs long after the script is parsed.
    const unlock = () => {
        try { LiveCallManager.ensureAudioContextUnlocked(); } catch (e) {}
        ['pointerdown', 'touchstart', 'keydown'].forEach(ev =>
            window.removeEventListener(ev, unlock, true));
    };
    ['pointerdown', 'touchstart', 'keydown'].forEach(ev =>
        window.addEventListener(ev, unlock, { passive: true, capture: true }));
})();

(function suppressTouchLongPressMenu() {
    let lastTouchAt = 0;
    const noteTouch = () => { lastTouchAt = Date.now(); };
    document.addEventListener('touchstart', noteTouch, { passive: true, capture: true });
    document.addEventListener('touchend', noteTouch, { passive: true, capture: true });
    document.addEventListener('contextmenu', e => {
        const el = e.target;
        if (el && (el.tagName === 'INPUT' || el.tagName === 'TEXTAREA' || el.isContentEditable)) return;
        const fromTouch = e.pointerType === 'touch' || e.pointerType === 'pen'
            || (Date.now() - lastTouchAt) < 1200;
        if (!fromTouch) return;
        e.preventDefault();
        e.stopPropagation();
    }, true);
})();

/* Exact bidirectional Gregorian <-> Jalali calendar conversion (zero external dependencies) */
function gregorianToJalali(gy, gm, gd) {
    const g_d_m = [0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334];
    const gy2 = (gm > 2) ? (gy + 1) : gy;
    let days = 355666 + (365 * gy) + Math.floor((gy2 + 3) / 4) - Math.floor((gy2 + 99) / 100) + Math.floor((gy2 + 399) / 400) + gd + g_d_m[gm - 1];
    let jy = -1595 + (33 * Math.floor(days / 12053));
    days %= 12053;
    jy += 4 * Math.floor(days / 1461);
    days %= 1461;
    if (days > 365) {
        jy += Math.floor((days - 1) / 365);
        days = (days - 1) % 365;
    }
    const jm = (days < 186) ? (1 + Math.floor(days / 31)) : (7 + Math.floor((days - 186) / 30));
    const jd = 1 + ((days < 186) ? (days % 31) : ((days - 186) % 30));
    return [jy, jm, jd];
}

function jalaliToGregorian(jy, jm, jd) {
    const jy1 = jy + 1595;
    let days = -355668 + (365 * jy1) + (Math.floor(jy1 / 33) * 8) + Math.floor(((jy1 % 33) + 3) / 4) + jd + ((jm < 7) ? (jm - 1) * 31 : ((jm - 7) * 30) + 186);
    let gy = 400 * Math.floor(days / 146097);
    days %= 146097;
    if (days > 36524) {
        gy += 100 * Math.floor(--days / 36524);
        days %= 36524;
        if (days >= 365) days++;
    }
    gy += 4 * Math.floor(days / 1461);
    days %= 1461;
    if (days > 365) {
        gy += Math.floor((days - 1) / 365);
        days = (days - 1) % 365;
    }
    let gd = days + 1;
    const isLeap = ((gy % 4 === 0 && gy % 100 !== 0) || (gy % 400 === 0));
    const sal_a = [0, 31, isLeap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
    let gm = 1;
    while (gm <= 12 && gd > sal_a[gm]) {
        gd -= sal_a[gm];
        gm++;
    }
    return [gy, gm, gd];
}

function getJalaliMonthDays(jy, jm) {
    if (jm <= 6) return 31;
    if (jm <= 11) return 30;
    const [gy1, gm1, gd1] = jalaliToGregorian(jy, 12, 30);
    const [rj, rm] = gregorianToJalali(gy1, gm1, gd1);
    return (rj === jy && rm === 12) ? 30 : 29;
}

function getMessengerNowSec() {
    const mode = (store.settings && store.settings.messenger_time_mode) || 'server';
    const offset = Number((store.settings && store.settings.messenger_time_offset_sec) || 0);
    const baseSec = Math.floor(Date.now() / 1000);
    return mode === 'custom' ? (baseSec + offset) : baseSec;
}

function isSuperAdminClient() {
    return Boolean(store.user && store.user.role === 'superadmin');
}

function getChatContentPerm(chat, key) {
    if (!chat || (chat.type !== 'group' && chat.type !== 'channel')) return true;
    const p = chat.perms || {};
    return p[key] === undefined ? true : Number(p[key]) !== 0;
}

function getGlobalContentPerm(key) {
    const s = store.settings || {};
    return s[key] === undefined ? true : Number(s[key]) !== 0;
}

function canCopyMessageAction(msg, chat) {
    if (isZeroSaveProtected(msg, chat)) return false;
    if (isSuperAdminClient()) return true;
    return getGlobalContentPerm('allow_copy_msg') && getChatContentPerm(chat, 'allow_copy_msg');
}

function canSelectMessageText(msg, chat) {
    if (isZeroSaveProtected(msg, chat)) return false;
    if (isSuperAdminClient()) return true;
    return getGlobalContentPerm('allow_select_text') && getChatContentPerm(chat, 'allow_select_text');
}

function canDownloadMessageFile(msg, chat) {
    if (isZeroSaveProtected(msg, chat)) return false;
    if (isSuperAdminClient()) return true;
    return getGlobalContentPerm('allow_file_download') && getChatContentPerm(chat, 'allow_file_download');
}

function canForwardOrSaveMessage(msg, chat) {
    if (!chat || !msg) return false;
    if (msg.kind === 'call_log' || msg.kind === 'system') return false;
    if (isSelfDestructMessage(msg)) return false;
    if (chat.type === 'secret' || msg.cipher) return false;
    if (isSuperAdminClient()) return true;
    if ((chat.type === 'group' || chat.type === 'channel') && chat.visibility === 'private') return false;
    if (chat.can_forward === false) return false;
    return getGlobalContentPerm('allow_forward_msg') && getChatContentPerm(chat, 'allow_forward_msg');
}

function formatAudioClock(sec) {
    const n = Number(sec);
    if (!Number.isFinite(n) || n < 0) return '00:00';
    const whole = Math.floor(n);
    const mm = String(Math.floor(whole / 60)).padStart(2, '0');
    const ss = String(whole % 60).padStart(2, '0');
    return `${mm}:${ss}`;
}

function extractVoiceFilenameDuration(displayName) {
    const m = String(displayName || '').match(/(?:^|_)voice_(\d+)s_/i);
    if (m && m[1]) {
        const v = parseInt(m[1], 10);
        if (v > 0 && v < 86400) return v;
    }
    return 0;
}

async function resolveAudioTrueDuration(url, cacheKey, hintSec = 0) {
    if (hintSec > 0 && Number.isFinite(hintSec)) {
        if (cacheKey) store.audioDurationCache[cacheKey] = hintSec;
        return hintSec;
    }
    if (cacheKey && store.audioDurationCache[cacheKey] > 0) {
        return store.audioDurationCache[cacheKey];
    }
    // 1. Try Web Audio decodeAudioData for exact sample-accurate duration on WebM/Opus/Ogg/MP3
    try {
        const AC = window.AudioContext || window.webkitAudioContext;
        if (AC && url) {
            const resp = await fetch(url, { credentials: 'same-origin' });
            if (resp.ok) {
                const buf = await resp.arrayBuffer();
                if (buf && buf.byteLength > 0 && buf.byteLength <= 16 * 1024 * 1024) {
                    const ctx = new AC();
                    try {
                        const decoded = await ctx.decodeAudioData(buf.slice(0));
                        if (decoded && Number.isFinite(decoded.duration) && decoded.duration > 0) {
                            const dur = decoded.duration;
                            if (cacheKey) store.audioDurationCache[cacheKey] = dur;
                            try { await ctx.close(); } catch (ce) {}
                            return dur;
                        }
                    } finally {
                        try { await ctx.close(); } catch (ce) {}
                    }
                }
            }
        }
    } catch (e) {}

    // 2. Fallback: detached probe element seeking to 1e101 to force WebM stream duration discovery
    return new Promise(resolve => {
        const probe = document.createElement('audio');
        probe.preload = 'metadata';
        let settled = false;
        const finish = val => {
            if (settled) return;
            settled = true;
            probe.removeAttribute('src');
            try { probe.load(); } catch (e) {}
            if (val > 0 && Number.isFinite(val) && cacheKey) {
                store.audioDurationCache[cacheKey] = val;
            }
            resolve(val > 0 && Number.isFinite(val) ? val : 0);
        };
        const timer = setTimeout(() => finish(0), 4000);
        probe.addEventListener('loadedmetadata', () => {
            if (Number.isFinite(probe.duration) && probe.duration > 0) {
                clearTimeout(timer);
                finish(probe.duration);
            } else if (probe.duration === Infinity) {
                const onTime = () => {
                    probe.removeEventListener('timeupdate', onTime);
                    clearTimeout(timer);
                    const d = Number.isFinite(probe.duration) && probe.duration > 0 ? probe.duration : probe.currentTime;
                    probe.currentTime = 0;
                    finish(d);
                };
                probe.addEventListener('timeupdate', onTime);
                try { probe.currentTime = 1e101; } catch (e) { finish(0); }
            }
        }, { once: true });
        probe.addEventListener('error', () => { clearTimeout(timer); finish(0); }, { once: true });
        probe.src = url;
    });
}

const SharedMediaPool = {
    entries: new Map(),
    makeKey(kind, msgId, fileId, url) {
        if (msgId && Number(msgId) > 0) return kind + ':msg:' + Number(msgId);
        if (fileId && Number(fileId) > 0) return kind + ':file:' + Number(fileId);
        return url ? (kind + ':url:' + String(url)) : '';
    },
    acquire(kind, key, url) {
        if (!key) {
            const rawEl = document.createElement(kind === 'video' ? 'video' : 'audio');
            rawEl.preload = 'metadata';
            if (kind === 'video') rawEl.playsInline = true;
            if (url) rawEl.src = url;
            return rawEl;
        }
        let rec = this.entries.get(key);
        if (rec && rec.el) {
            if (url && rec.url !== url) { rec.url = url; rec.el.src = url; }
            return rec.el;
        }
        const el = document.createElement(kind === 'video' ? 'video' : 'audio');
        el.preload = 'metadata';
        if (kind === 'video') el.playsInline = true;
        if (url) el.src = url;
        el._fromSharedPool = true;
        el._poolKey = key;
        this.entries.set(key, { el, url: url || '', kind });
        if (this.entries.size > 40) {
            for (const [k, v] of this.entries) {
                if (k !== key && v.el && v.el.paused && !v.el._dockedInUmp && !document.body.contains(v.el)) {
                    try { v.el.removeAttribute('src'); v.el.load(); } catch (e) {}
                    this.entries.delete(k);
                    break;
                }
            }
        }
        return el;
    },
    evictByIds(msgId, fileId) {
        ['video', 'audio'].forEach(kind => {
            const k1 = msgId ? (kind + ':msg:' + Number(msgId)) : '';
            const k2 = fileId ? (kind + ':file:' + Number(fileId)) : '';
            [k1, k2].forEach(k => {
                if (k && this.entries.has(k)) {
                    const rec = this.entries.get(k);
                    if (rec && rec.el) { try { rec.el.pause(); rec.el.removeAttribute('src'); rec.el.load(); } catch (e) {} }
                    this.entries.delete(k);
                }
            });
        });
    }
};

function pauseOtherActiveInlineMedia(exceptMediaEl) {
    document.querySelectorAll('.m3-audio-player, .m3-video-player').forEach(node => {
        const m = node._audioEl || node._videoEl;
        if (m && m !== exceptMediaEl && !m.paused) {
            try { m.pause(); } catch (e) {}
        }
    });
}

function createInteractiveMediaScrubber(mediaEl, getDurationFn, onPreviewTime) {
    const scrub = document.createElement('div');
    scrub.className = 'm3-media-scrubber';
    scrub.setAttribute('dir', 'ltr');
    const rail = document.createElement('div');
    rail.className = 'm3-scrub-rail';
    const bufBar = document.createElement('div');
    bufBar.className = 'm3-scrub-buf';
    const fillBar = document.createElement('div');
    fillBar.className = 'm3-scrub-fill';
    const thumb = document.createElement('div');
    thumb.className = 'm3-scrub-thumb';
    const tip = document.createElement('div');
    tip.className = 'm3-scrub-tip';
    tip.textContent = '00:00';
    rail.appendChild(bufBar);
    rail.appendChild(fillBar);
    rail.appendChild(thumb);
    scrub.appendChild(rail);
    scrub.appendChild(tip);

    let scrubbing = false;
    let scrubRatio = 0;

    const setVisualRatio = (ratio, durSec) => {
        const clamped = Math.max(0, Math.min(1, Number.isFinite(ratio) ? ratio : 0));
        const pct = (clamped * 100).toFixed(2) + '%';
        fillBar.style.width = pct;
        thumb.style.left = pct;
        if (durSec > 0) tip.textContent = formatAudioClock(clamped * durSec);
        const sRect = scrub.getBoundingClientRect();
        if (sRect && sRect.width > 40) {
            const halfTip = Math.max(22, ((tip.offsetWidth || 44) / 2) + 2);
            const rawPx = clamped * sRect.width;
            const safePx = Math.max(halfTip, Math.min(sRect.width - halfTip, rawPx));
            tip.style.left = safePx.toFixed(1) + 'px';
        } else {
            tip.style.left = Math.max(12, Math.min(88, clamped * 100)).toFixed(1) + '%';
        }
    };

    const syncFromMedia = () => {
        if (scrubbing) return;
        const dur = getDurationFn();
        const cur = (Number.isFinite(mediaEl.currentTime) && mediaEl.currentTime >= 0) ? mediaEl.currentTime : 0;
        if (dur > 0) {
            setVisualRatio(cur / dur, dur);
            try {
                if (mediaEl.buffered && mediaEl.buffered.length > 0) {
                    const bEnd = mediaEl.buffered.end(mediaEl.buffered.length - 1);
                    bufBar.style.width = Math.max(0, Math.min(100, (bEnd / dur) * 100)).toFixed(1) + '%';
                }
            } catch (e) {}
        } else {
            setVisualRatio(0, 0);
        }
    };

    const ratioFromClientX = (clientX) => {
        const rect = scrub.getBoundingClientRect();
        if (!rect || rect.width <= 0) return 0;
        return Math.max(0, Math.min(1, (clientX - rect.left) / rect.width));
    };

    ['touchstart', 'touchmove', 'touchend', 'mousedown', 'click'].forEach(evName => {
        scrub.addEventListener(evName, ev => ev.stopPropagation(), { passive: true });
    });

    scrub.addEventListener('pointerdown', e => {
        if (e.button !== undefined && e.button !== 0) return;
        e.stopPropagation();
        e.preventDefault();
        scrubbing = true;
        scrub.classList.add('is-scrubbing');
        try { scrub.setPointerCapture(e.pointerId); } catch (err) {}
        const dur = getDurationFn();
        scrubRatio = ratioFromClientX(e.clientX);
        setVisualRatio(scrubRatio, dur);
        if (dur > 0 && typeof onPreviewTime === 'function') onPreviewTime(scrubRatio * dur, dur, false);
    });

    scrub.addEventListener('pointermove', e => {
        if (!scrubbing) return;
        e.stopPropagation();
        const dur = getDurationFn();
        scrubRatio = ratioFromClientX(e.clientX);
        setVisualRatio(scrubRatio, dur);
        if (dur > 0) {
            const target = scrubRatio * dur;
            if (typeof onPreviewTime === 'function') onPreviewTime(target, dur, false);
            try { mediaEl.currentTime = target; } catch (err) {}
        }
    });

    const finishScrub = e => {
        if (!scrubbing) return;
        if (e) e.stopPropagation();
        scrubbing = false;
        scrub.classList.remove('is-scrubbing');
        try { if (e && e.pointerId !== undefined) scrub.releasePointerCapture(e.pointerId); } catch (err) {}
        const dur = getDurationFn();
        if (dur > 0) {
            const target = Math.max(0, Math.min(dur, scrubRatio * dur));
            try { mediaEl.currentTime = target; } catch (err) {}
            if (typeof onPreviewTime === 'function') onPreviewTime(target, dur, true);
        }
        syncFromMedia();
    };
    scrub.addEventListener('pointerup', finishScrub);
    scrub.addEventListener('pointercancel', finishScrub);

    return { el: scrub, syncFromMedia, isScrubbing: () => scrubbing };
}

function attachBoxHorizontalScrubGesture(boxEl, mediaEl, getDurationFn, onFeedback) {
    let activePtr = null, startX = 0, startY = 0, baseTime = 0, boxDragging = false;
    boxEl.addEventListener('touchstart', e => {
        if (store.selectedMsgIds && store.selectedMsgIds.size > 0) return;
        e.stopPropagation();
    }, { passive: true });
    boxEl.addEventListener('touchmove', e => {
        if (boxDragging) {
            e.stopPropagation();
            if (e.cancelable) e.preventDefault();
        }
    }, { passive: false });

    boxEl.addEventListener('pointerdown', e => {
        if (store.selectedMsgIds && store.selectedMsgIds.size > 0) return;
        if (e.button !== undefined && e.button !== 0) return;
        if (e.target && e.target.closest('button, a, .m3-media-scrubber, input')) return;
        e.stopPropagation();
        activePtr = e.pointerId;
        startX = e.clientX;
        startY = e.clientY;
        baseTime = Number.isFinite(mediaEl.currentTime) ? mediaEl.currentTime : 0;
        boxDragging = false;
    });

    boxEl.addEventListener('pointermove', e => {
        if (activePtr === null || e.pointerId !== activePtr) return;
        const dx = e.clientX - startX;
        const dy = e.clientY - startY;
        if (!boxDragging) {
            if (Math.abs(dy) > 14 && Math.abs(dy) > Math.abs(dx)) { activePtr = null; return; }
            if (Math.abs(dx) > 10 && Math.abs(dx) > Math.abs(dy) * 1.25) {
                boxDragging = true;
                boxEl._suppressTapUntil = Date.now() + 320;
                try { boxEl.setPointerCapture(e.pointerId); } catch (err) {}
            } else { return; }
        }
        e.stopPropagation();
        const dur = getDurationFn();
        if (dur > 0) {
            const widthPx = Math.max(160, boxEl.getBoundingClientRect().width || 240);
            const spanSec = Math.min(dur, Math.max(15, dur * 0.65));
            const nextT = Math.max(0, Math.min(dur, baseTime + (dx / widthPx) * spanSec));
            try { mediaEl.currentTime = nextT; } catch (err) {}
            if (typeof onFeedback === 'function') onFeedback(nextT, nextT - baseTime, false);
        }
    });

    const endBoxDrag = e => {
        if (activePtr === null || (e && e.pointerId !== undefined && e.pointerId !== activePtr)) return;
        if (boxDragging) {
            if (e) e.stopPropagation();
            boxEl._suppressTapUntil = Date.now() + 260;
            try { if (e && e.pointerId !== undefined) boxEl.releasePointerCapture(e.pointerId); } catch (err) {}
            if (typeof onFeedback === 'function') onFeedback(mediaEl.currentTime || 0, 0, true);
        }
        activePtr = null;
        boxDragging = false;
    };
    boxEl.addEventListener('pointerup', endBoxDrag);
    boxEl.addEventListener('pointercancel', endBoxDrag);
}

function createCustomAudioPlayer(opts = {}) {
    const wrap = document.createElement('div');
    wrap.className = 'm3-audio-player';
    wrap.setAttribute('dir', 'ltr');

    const aud = opts.poolKey
        ? SharedMediaPool.acquire('audio', opts.poolKey, opts.url || '')
        : (() => { const a = document.createElement('audio'); a.preload = 'metadata'; a.src = opts.url || ''; return a; })();

    const playBtn = document.createElement('button');
    playBtn.type = 'button';
    playBtn.className = 'm3-aud-play';
    const syncPlayIcon = () => { playBtn.innerHTML = aud.paused ? MEDIA_ICON.play : MEDIA_ICON.pause; };
    syncPlayIcon();

    const mainCol = document.createElement('div');
    mainCol.className = 'm3-aud-main';
    mainCol.style.overflow = 'visible';
    mainCol.style.paddingTop = '6px';
    const metaRow = document.createElement('div');
    metaRow.className = 'm3-aud-meta';

    const timeLbl = document.createElement('span');
    const hintSec = extractVoiceFilenameDuration(opts.displayName);
    let knownDuration = (Number.isFinite(aud.duration) && aud.duration > 0)
        ? aud.duration
        : ((opts.cacheKey && store.audioDurationCache[opts.cacheKey]) ? store.audioDurationCache[opts.cacheKey] : hintSec);

    const getDur = () => {
        const d = readMediaDuration(aud);
        if (d > 0) {
            knownDuration = d;
            if (opts.cacheKey) store.audioDurationCache[opts.cacheKey] = knownDuration;
        }
        return knownDuration > 0 ? knownDuration : 0;
    };

    const scrubber = createInteractiveMediaScrubber(aud, getDur, (previewSec, durSec) => {
        timeLbl.textContent = `${formatAudioClock(previewSec)} / ${durSec > 0 ? formatAudioClock(durSec) : '--:--'}`;
    });

    const rateBtn = document.createElement('button');
    rateBtn.type = 'button';
    rateBtn.className = 'm3-med-btn m3-med-rate m3-aud-icon-btn';
    rateBtn.title = t('vid_speed_tip');
    rateBtn.textContent = (Number(aud.playbackRate) || 1) + 'x';
    rateBtn.addEventListener('click', e => {
        e.stopPropagation();
        const nextR = nextPlaybackRate(aud.playbackRate);
        aud.playbackRate = nextR;
        rateBtn.textContent = nextR + 'x';
    });

    const muteBtn = document.createElement('button');
    muteBtn.type = 'button';
    muteBtn.className = 'm3-med-btn m3-aud-icon-btn';
    muteBtn.style.marginLeft = 'auto';
    muteBtn.title = t('vid_mute_tip');
    muteBtn.setAttribute('data-i18n-title', 'vid_mute_tip');
    muteBtn.setAttribute('aria-label', t('vid_mute_tip'));
    const syncMuteIcon = () => { muteBtn.innerHTML = aud.muted ? MEDIA_ICON.volOff : MEDIA_ICON.volOn; };
    syncMuteIcon();
    muteBtn.addEventListener('click', e => {
        e.stopPropagation();
        aud.muted = !aud.muted;
        syncMuteIcon();
    });

    metaRow.appendChild(timeLbl);
    metaRow.appendChild(muteBtn);
    metaRow.appendChild(rateBtn);
    mainCol.appendChild(scrubber.el);
    mainCol.appendChild(metaRow);
    wrap.appendChild(playBtn);
    wrap.appendChild(mainCol);

    const syncSliderVisual = () => {
        if (!wrap.isConnected && !opts.inUmp) return;
        const dur = getDur();
        const cur = Number.isFinite(aud.currentTime) && aud.currentTime >= 0 ? aud.currentTime : 0;
        syncPlayIcon();
        syncMuteIcon();
        rateBtn.textContent = (Number(aud.playbackRate) || 1) + 'x';
        if (!scrubber.isScrubbing()) {
            scrubber.syncFromMedia();
            timeLbl.textContent = `${formatAudioClock(cur)} / ${dur > 0 ? formatAudioClock(dur) : '--:--'}`;
        }
    };

    resolveAudioTrueDuration(opts.url, opts.cacheKey, hintSec).then(resolvedDur => {
        if (resolvedDur > 0 && !(Number.isFinite(aud.duration) && aud.duration > 0)) {
            knownDuration = resolvedDur;
            syncSliderVisual();
        }
    });

    aud.addEventListener('loadedmetadata', syncSliderVisual);
    aud.addEventListener('durationchange', syncSliderVisual);
    aud.addEventListener('timeupdate', syncSliderVisual);
    aud.addEventListener('ratechange', syncSliderVisual);
    aud.addEventListener('progress', syncSliderVisual);
    aud.addEventListener('play', () => {
        if (!opts.inUmp) pauseOtherActiveInlineMedia(aud);
        syncPlayIcon();
    });
    aud.addEventListener('pause', () => { syncPlayIcon(); });
    aud.addEventListener('ended', () => {
        syncPlayIcon();
        if (Number.isFinite(aud.currentTime) && aud.currentTime > 0 && !knownDuration) knownDuration = aud.currentTime;
        aud.currentTime = 0;
        syncSliderVisual();
    });

    playBtn.addEventListener('click', e => {
        e.stopPropagation();
        if (aud.paused) aud.play().catch(() => {});
        else aud.pause();
    });

    attachBoxHorizontalScrubGesture(wrap, aud, getDur, (nextT) => {
        const dur = getDur();
        scrubber.syncFromMedia();
        timeLbl.textContent = `${formatAudioClock(nextT)} / ${dur > 0 ? formatAudioClock(dur) : '--:--'}`;
    });

    wrap.addEventListener('click', e => e.stopPropagation());
    wrap._audioEl = aud;
    wrap._rateBtn = rateBtn;
    wrap._syncSliderVisual = syncSliderVisual;
    wrap._reclaimMedia = () => { syncSliderVisual(); };
    syncSliderVisual();

    if (typeof opts.onMediaReady === 'function') opts.onMediaReady(aud);
    if (opts.autoPlay) aud.play().catch(() => {});
    return { wrap, audio: aud, rateBtn, syncSliderVisual };
}

function createCustomVideoPlayer(opts = {}) {
    const wrap = document.createElement('div');
    wrap.className = 'm3-video-player';
    wrap.setAttribute('dir', 'ltr');

    const vid = opts.poolKey
        ? SharedMediaPool.acquire('video', opts.poolKey, opts.url || '')
        : (() => { const v = document.createElement('video'); v.preload = 'metadata'; v.playsInline = true; v.src = opts.url || ''; return v; })();
    vid.controls = false;
    vid.playsInline = true;
    if (opts.msgId) vid.setAttribute('data-inline-msg-id', String(opts.msgId));
    if (opts.fileId) vid.setAttribute('data-inline-file-id', String(opts.fileId));
    if (!opts.allowDownload || opts.zeroSave) {
        vid.setAttribute('controlsList', 'nodownload');
        if (opts.zeroSave) {
            vid.disablePictureInPicture = true;
            bindZeroSaveDomGuards(vid);
        }
    }

    const stage = document.createElement('div');
    stage.className = 'm3-video-stage';
    const seekToast = document.createElement('div');
    seekToast.className = 'm3-vid-seek-toast';
    const topBadges = document.createElement('div');
    topBadges.className = 'm3-vid-top-badges';

    const speedPill = document.createElement('button');
    speedPill.type = 'button';
    speedPill.className = 'm3-vid-pill m3-med-btn m3-med-rate m3-vid-icon-btn';
    speedPill.textContent = (Number(vid.playbackRate) || 1) + 'x';
    speedPill.addEventListener('click', e => {
        e.stopPropagation();
        const next = nextPlaybackRate(vid.playbackRate);
        vid.playbackRate = next;
        speedPill.textContent = next + 'x';
    });
    topBadges.appendChild(speedPill);

    const centerBtn = document.createElement('button');
    centerBtn.type = 'button';
    centerBtn.className = 'm3-vid-center-btn';
    centerBtn.innerHTML = '<svg viewBox="0 0 24 24"><polygon points="6,4 20,12 6,20"/></svg>';

    const controls = document.createElement('div');
    controls.className = 'm3-vid-controls';

    let knownVidDur = readMediaDuration(vid);
    const getVidDur = () => {
        const d = readMediaDuration(vid);
        if (d > 0) knownVidDur = d;
        return knownVidDur > 0 ? knownVidDur : 0;
    };

    const timeLbl = document.createElement('span');
    timeLbl.className = 'm3-vid-time';
    timeLbl.textContent = '00:00 / --:--';

    const scrubber = createInteractiveMediaScrubber(vid, getVidDur, (previewSec, durSec) => {
        timeLbl.textContent = `${formatAudioClock(previewSec)} / ${durSec > 0 ? formatAudioClock(durSec) : '--:--'}`;
    });

    const ctrlRow = document.createElement('div');
    ctrlRow.className = 'm3-vid-ctrl-row';

    const playIconSvg = MEDIA_ICON.play;
    const pauseIconSvg = MEDIA_ICON.pause;
    const volOnSvg = MEDIA_ICON.volOn;
    const volMuteSvg = MEDIA_ICON.volOff;
    const popSvg = '<svg viewBox="0 0 24 24"><path d="M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6"/><polyline points="15 3 21 3 21 9"/><line x1="10" y1="14" x2="21" y2="3"/></svg>';
    const fsSvg = '<svg viewBox="0 0 24 24"><polyline points="15 3 21 3 21 9"/><polyline points="9 21 3 21 3 15"/><line x1="21" y1="3" x2="14" y2="10"/><line x1="3" y1="21" x2="10" y2="14"/></svg>';

    const playSmallBtn = document.createElement('button');
    playSmallBtn.type = 'button';
    playSmallBtn.className = 'm3-med-btn m3-vid-icon-btn';
    playSmallBtn.innerHTML = vid.paused ? playIconSvg : pauseIconSvg;

    const muteBtn = document.createElement('button');
    muteBtn.type = 'button';
    muteBtn.className = 'm3-med-btn m3-vid-icon-btn';
    muteBtn.title = t('vid_mute_tip');
    muteBtn.innerHTML = vid.muted ? volMuteSvg : volOnSvg;
    muteBtn.addEventListener('click', e => {
        e.stopPropagation();
        vid.muted = !vid.muted;
        muteBtn.innerHTML = vid.muted ? volMuteSvg : volOnSvg;
    });

    ctrlRow.appendChild(playSmallBtn);
    ctrlRow.appendChild(timeLbl);
    ctrlRow.appendChild(muteBtn);

    if (!opts.inUmp && typeof opts.onPopOut === 'function') {
        const popSmallBtn = document.createElement('button');
        popSmallBtn.type = 'button';
        popSmallBtn.className = 'm3-med-btn m3-vid-icon-btn';
        popSmallBtn.title = t('open_in_player_btn');
        popSmallBtn.innerHTML = popSvg;
        popSmallBtn.addEventListener('click', e => { e.stopPropagation(); opts.onPopOut(vid); });
        ctrlRow.appendChild(popSmallBtn);
    }

    const fsBtn = document.createElement('button');
    fsBtn.type = 'button';
    fsBtn.className = 'm3-med-btn m3-vid-icon-btn';
    fsBtn.title = t('vid_fullscreen_tip');
    fsBtn.innerHTML = fsSvg;
    fsBtn.addEventListener('click', e => {
        e.stopPropagation();
        if (document.fullscreenElement) document.exitFullscreen().catch(() => {});
        else if (wrap.requestFullscreen) wrap.requestFullscreen().catch(() => {});
        else if (vid.webkitEnterFullscreen) { try { vid.webkitEnterFullscreen(); } catch (err) {} }
    });
    ctrlRow.appendChild(fsBtn);

    controls.appendChild(scrubber.el);
    controls.appendChild(ctrlRow);

    let idleTimer = null;
    const bumpControlsActive = () => {
        wrap.classList.remove('controls-idle');
        if (idleTimer) clearTimeout(idleTimer);
        if (!vid.paused && !vid.ended) {
            idleTimer = setTimeout(() => {
                if (!vid.paused && !scrubber.isScrubbing()) wrap.classList.add('controls-idle');
            }, 2600);
        }
    };
    wrap.addEventListener('pointermove', bumpControlsActive);
    wrap.addEventListener('pointerdown', bumpControlsActive);

    let lockedSpoiler = Boolean(opts.needsSecondClickPlay);
    const togglePlay = e => {
        if (e) e.stopPropagation();
        if (store.selectedMsgIds && store.selectedMsgIds.size > 0) return;
        if (wrap._suppressTapUntil && Date.now() < wrap._suppressTapUntil) return;
        if (lockedSpoiler) {
            lockedSpoiler = false;
            controls.classList.remove('hidden');
            topBadges.classList.remove('hidden');
            if (typeof opts.onSecondClickUnlocked === 'function') opts.onSecondClickUnlocked();
            vid.play().catch(() => {});
            return;
        }
        if (vid.paused) vid.play().catch(() => {});
        else vid.pause();
    };
    if (lockedSpoiler) {
        controls.classList.add('hidden');
        topBadges.classList.add('hidden');
    }

    centerBtn.addEventListener('click', togglePlay);
    playSmallBtn.addEventListener('click', togglePlay);
    stage.addEventListener('click', e => {
        if (e.target && e.target.closest('button, .m3-vid-controls, .m3-vid-top-badges, .m3-vid-docked-placeholder')) return;
        togglePlay(e);
    });

    let toastHideTimer = null;
    attachBoxHorizontalScrubGesture(wrap, vid, getVidDur, (nextT, deltaSec, ended) => {
        scrubber.syncFromMedia();
        const dur = getVidDur();
        timeLbl.textContent = `${formatAudioClock(nextT)} / ${dur > 0 ? formatAudioClock(dur) : '--:--'}`;
        if (!ended) {
            const sign = deltaSec >= 0 ? '+' : '-';
            seekToast.textContent = `${sign}${Math.abs(Math.round(deltaSec))}s • ${formatAudioClock(nextT)}`;
            seekToast.classList.add('visible');
            if (toastHideTimer) clearTimeout(toastHideTimer);
        } else {
            toastHideTimer = setTimeout(() => seekToast.classList.remove('visible'), 550);
        }
    });

    const dockedBox = document.createElement('div');
    dockedBox.className = 'm3-vid-docked-placeholder hidden';
    const dockedLbl = document.createElement('div');
    dockedLbl.textContent = t('vid_docked_in_popup');
    const returnBtn = document.createElement('button');
    returnBtn.type = 'button';
    returnBtn.className = 'btn btn-primary btn-sm';
    returnBtn.textContent = t('vid_return_inline_btn');
    returnBtn.addEventListener('click', e => {
        e.stopPropagation();
        if (typeof UniversalPlayer !== 'undefined' && UniversalPlayer.isOpen) UniversalPlayer.close();
    });
    dockedBox.appendChild(dockedLbl);
    dockedBox.appendChild(returnBtn);

    const mountOrShowPlaceholder = () => {
        if (!opts.inUmp && vid._dockedInUmp) {
            stage.classList.add('hidden');
            controls.classList.add('hidden');
            topBadges.classList.add('hidden');
            dockedBox.classList.remove('hidden');
        } else {
            dockedBox.classList.add('hidden');
            stage.classList.remove('hidden');
            if (!lockedSpoiler) {
                controls.classList.remove('hidden');
                topBadges.classList.remove('hidden');
            }
            if (vid.parentElement !== stage) stage.insertBefore(vid, stage.firstChild);
        }
    };

    stage.appendChild(centerBtn);
    stage.appendChild(seekToast);
    wrap.appendChild(dockedBox);
    wrap.appendChild(stage);
    wrap.appendChild(topBadges);
    wrap.appendChild(controls);

    const syncVidVisual = () => {
        const dur = getVidDur();
        const cur = (Number.isFinite(vid.currentTime) && vid.currentTime >= 0) ? vid.currentTime : 0;
        const playing = !vid.paused && !vid.ended;
        wrap.classList.toggle('is-playing', playing);
        playSmallBtn.innerHTML = playing ? pauseIconSvg : playIconSvg;
        muteBtn.innerHTML = vid.muted ? volMuteSvg : volOnSvg;
        speedPill.textContent = (Number(vid.playbackRate) || 1) + 'x';
        if (!scrubber.isScrubbing()) {
            scrubber.syncFromMedia();
            timeLbl.textContent = `${formatAudioClock(cur)} / ${dur > 0 ? formatAudioClock(dur) : '--:--'}`;
        }
    };

    vid.addEventListener('loadedmetadata', syncVidVisual);
    vid.addEventListener('durationchange', syncVidVisual);
    vid.addEventListener('timeupdate', syncVidVisual);
    vid.addEventListener('progress', syncVidVisual);
    vid.addEventListener('ratechange', syncVidVisual);
    vid.addEventListener('volumechange', syncVidVisual);
    vid.addEventListener('play', () => {
        if (!opts.inUmp) pauseOtherActiveInlineMedia(vid);
        syncVidVisual();
        bumpControlsActive();
    });
    vid.addEventListener('pause', () => { wrap.classList.remove('controls-idle'); syncVidVisual(); });
    vid.addEventListener('ended', () => { wrap.classList.remove('controls-idle'); syncVidVisual(); });

    wrap.addEventListener('click', e => e.stopPropagation());
    wrap._videoEl = vid;
    wrap._speedPill = speedPill;
    wrap._syncVidVisual = syncVidVisual;
    wrap._reclaimMedia = () => { mountOrShowPlaceholder(); syncVidVisual(); };
    wrap._notifyDockedInUmp = () => { mountOrShowPlaceholder(); };

    if (opts.inUmp) vid._dockedInUmp = true;
    mountOrShowPlaceholder();
    syncVidVisual();
    if (opts.autoPlay && !lockedSpoiler) vid.play().catch(() => {});

    return { wrap, video: vid, speedPill, syncVidVisual };
}

function syncComposerHeightVar() {
    const view = document.getElementById('active-chat-view');
    const wrap = document.querySelector('#active-chat-view .composer-wrap');
    if (!view || !wrap) return;
    const h = Math.max(58, Math.ceil(wrap.offsetHeight || 92));
    view.style.setProperty('--composer-height', h + 'px');
}

function autoResizeComposerInput() {
    const ta = document.getElementById('composer-textarea');
    if (!ta) return;
    const compBar = document.getElementById('composer-active-bar');
    if (compBar) {
        compBar.classList.toggle('composer-has-text', ta.value.trim().length > 0);
    }
    const vp = document.getElementById('messages-viewport');
    const prevMaxScroll = vp ? Math.max(0, vp.scrollHeight - vp.clientHeight) : 0;
    // Item #8: Capture bottom proximity BEFORE mutating textarea height so flex reflow never clamps vp.scrollTop upward
    const wasNearBottom = vp ? (prevMaxScroll <= 24 || (prevMaxScroll - vp.scrollTop) <= 95) : false;

    const prevH = ta.offsetHeight || 36;
    const maxH = window.innerWidth <= 780 ? 132 : 144;
    if (!ta.value) {
        ta.style.height = '36px';
        ta.style.overflowY = 'hidden';
        syncComposerHeightVar();
        if (wasNearBottom && vp) vp.scrollTop = vp.scrollHeight;
        updateScrollBottomFab(false);
        return;
    }
    ta.style.overflowY = 'hidden';
    ta.style.height = 'auto';
    const scH = ta.scrollHeight;
    const nextH = Math.max(36, Math.min(maxH, scH));
    ta.style.height = nextH + 'px';
    ta.style.overflowY = scH > maxH ? 'auto' : 'hidden';
    syncComposerHeightVar();
    if (vp) {
        if (wasNearBottom) {
            vp.scrollTop = vp.scrollHeight;
        } else if (nextH !== prevH && (vp.scrollHeight - vp.clientHeight - vp.scrollTop) < 90) {
            vp.scrollTop += Math.max(0, nextH - prevH);
        }
    }
    if (nextH !== prevH && window.innerWidth <= 780 && typeof syncMobileVisualViewportHeight === 'function') {
        syncMobileVisualViewportHeight();
    }
    updateScrollBottomFab(false);
}

function formatBytes(bytes) {
    const b = Number(bytes) || 0;
    if (b <= 0) return '0 ' + t('unit_kb');
    if (b < 1024) return b + ' ' + t('unit_b');
    if (b < 1048576) return (b / 1024).toFixed(1) + ' ' + t('unit_kb');
    return (b / 1048576).toFixed(2) + ' ' + t('unit_mb');
}

function updateThemeButtonsUI(themeMode) {
    const mode = ['auto', 'light', 'dark'].includes(themeMode) ? themeMode : 'auto';
    const sidebarBtn = document.getElementById('btn-theme-toggle');
    const authBtn = document.getElementById('auth-theme-btn');

    if (sidebarBtn) {
        if (mode === 'light') {
            sidebarBtn.title = t('theme_light');
            sidebarBtn.innerHTML = '<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="4.5"/><line x1="12" y1="2" x2="12" y2="4.5"/><line x1="12" y1="19.5" x2="12" y2="22"/><line x1="4.93" y1="4.93" x2="6.7" y2="6.7"/><line x1="17.3" y1="17.3" x2="19.07" y2="19.07"/><line x1="2" y1="12" x2="4.5" y2="12"/><line x1="19.5" y1="12" x2="22" y2="12"/><line x1="4.93" y1="19.07" x2="6.7" y2="17.3"/><line x1="17.3" y1="6.7" x2="19.07" y2="4.93"/></svg>';
        } else if (mode === 'dark') {
            sidebarBtn.title = t('theme_dark');
            sidebarBtn.innerHTML = '<svg viewBox="0 0 24 24"><path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z"/><path d="M19 3v4M17 5h4" stroke-width="1.8"/></svg>';
        } else {
            sidebarBtn.title = t('theme_auto');
            sidebarBtn.innerHTML = '<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="9"/><path d="M12 3a9 9 0 0 1 0 18Z" fill="currentColor" stroke="none"/><circle cx="12" cy="12" r="9" fill="none"/></svg>';
        }
    }

    if (authBtn) {
        if (mode === 'light') {
            authBtn.textContent = (store.lang === 'fa' ? 'روشن' : 'Light');
            authBtn.title = t('theme_light');
        } else if (mode === 'dark') {
            authBtn.textContent = (store.lang === 'fa' ? 'تاریک' : 'Dark');
            authBtn.title = t('theme_dark');
        } else {
            authBtn.textContent = (store.lang === 'fa' ? 'خودکار' : 'Auto');
            authBtn.title = t('theme_auto');
        }
    }
}

function getEffectiveAppTimeZone() {
    const rawTz = String((store.settings && store.settings.app_timezone) || 'Asia/Tehran').trim();
    if (!rawTz || rawTz === 'browser') return undefined;
    return rawTz;
}

function formatDate(ts, includeTime = true) {
    if (!ts) return '';
    const d = new Date(ts * 1000);
    const useJalali = (store.cal !== 'gregorian') && (store.lang === 'fa');
    const locale = useJalali ? 'fa-IR-u-ca-persian' : (store.lang === 'fa' ? 'fa-IR' : 'en-US');
    const tz = getEffectiveAppTimeZone();
    try {
        const opts = includeTime
            ? { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' }
            : { year: 'numeric', month: 'short', day: 'numeric' };
        if (tz) opts.timeZone = tz;
        return new Intl.DateTimeFormat(locale, opts).format(d);
    } catch (e) {
        try {
            const fallbackOpts = includeTime
                ? { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' }
                : { year: 'numeric', month: 'short', day: 'numeric' };
            return new Intl.DateTimeFormat(locale, fallbackOpts).format(d);
        } catch (e2) {
            return d.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
        }
    }
}

function formatFullTime(ts) {
    if (!ts) return '';
    const d = new Date(Number(ts) * 1000);
    const useJalali = (store.cal !== 'gregorian') && (store.lang === 'fa');
    const locale = useJalali ? 'fa-IR-u-ca-persian' : (store.lang === 'fa' ? 'fa-IR' : 'en-US');
    const tz = getEffectiveAppTimeZone();
    try {
        const opts = {
            year: 'numeric',
            month: '2-digit',
            day: '2-digit',
            hour: '2-digit',
            minute: '2-digit',
            second: '2-digit'
        };
        if (tz) opts.timeZone = tz;
        return new Intl.DateTimeFormat(locale, opts).format(d);
    } catch (e) {
        return formatDate(ts, true);
    }
}

function formatTimeOnly(ts) {
    if (!ts) return '';
    const d = new Date(ts * 1000);
    const locale = (store.lang === 'fa') ? 'fa-IR' : 'en-US';
    const tz = getEffectiveAppTimeZone();
    try {
        const opts = { hour: '2-digit', minute: '2-digit' };
        if (tz) opts.timeZone = tz;
        return new Intl.DateTimeFormat(locale, opts).format(d);
    } catch (e) {
        try {
            return new Intl.DateTimeFormat(locale, { hour: '2-digit', minute: '2-digit' }).format(d);
        } catch (e2) {
            return d.toTimeString().slice(0, 5);
        }
    }
}

function promoteToastContainerToTopLayer() {
    const c = document.getElementById('toast-container');
    if (!c || typeof c.showPopover !== 'function') return false;
    try {
        if (c.matches(':popover-open')) {
            c.hidePopover();
        }
        c.showPopover();
        return true;
    } catch (e) {
        return false;
    }
}

function toast(msg, isErr = false) {
    const mainC = document.getElementById('toast-container');
    const confirmC = document.getElementById('confirm-toast-fallback');
    const subC = document.getElementById('sub-modal-toast-fallback');
    const modalC = document.getElementById('modal-toast-container');
    const confirmDlg = document.getElementById('confirm-modal');
    const subDlg = document.getElementById('sub-modal');
    const dlg = document.getElementById('app-modal');
    if (!mainC) return;

    const cleanMsg = String(msg || '').trim();
    if (!cleanMsg) return;

    const el = document.createElement('div');
    el.className = 'toast' + (isErr ? ' err' : '');
    el.textContent = cleanMsg;

    const usedPopover = promoteToastContainerToTopLayer();
    if (!usedPopover && confirmDlg && confirmDlg.open && confirmC) {
        confirmC.appendChild(el);
    } else if (!usedPopover && subDlg && subDlg.open && subC) {
        subC.appendChild(el);
    } else if (!usedPopover && dlg && dlg.open && modalC) {
        modalC.appendChild(el);
    } else {
        mainC.appendChild(el);
    }

    let dismissed = false;
    const finalizeRemove = () => {
        if (dismissed) return;
        dismissed = true;
        el.remove();
        if (usedPopover && mainC.children.length === 0) {
            try { mainC.hidePopover(); } catch (e) {}
        }
    };

    const autoTimer = setTimeout(finalizeRemove, 3800);

    // Swipe left/right (PointerEvents: mouse drag & touch swipe) to dismiss corner toast
    let dragActive = false;
    let startX = 0;
    let curDx = 0;
    let activePid = null;
    el.addEventListener('pointerdown', (ev) => {
        if (ev.pointerType === 'mouse' && ev.button !== 0) return;
        dragActive = true;
        startX = ev.clientX;
        curDx = 0;
        activePid = ev.pointerId;
        el.classList.add('is-swiping');
        try { el.setPointerCapture(ev.pointerId); } catch (e) {}
    });
    el.addEventListener('pointermove', (ev) => {
        if (!dragActive || (activePid !== null && ev.pointerId !== activePid)) return;
        curDx = ev.clientX - startX;
        const absX = Math.abs(curDx);
        el.style.transform = `translateX(${curDx}px)`;
        el.style.opacity = String(Math.max(0.15, 1 - (absX / 200)));
    });
    const endSwipe = (ev) => {
        if (!dragActive) return;
        dragActive = false;
        el.classList.remove('is-swiping');
        try { if (activePid !== null) el.releasePointerCapture(activePid); } catch (e) {}
        activePid = null;
        if (Math.abs(curDx) >= 56) {
            clearTimeout(autoTimer);
            const flyX = (curDx >= 0 ? 1 : -1) * 340;
            el.style.transform = `translateX(${flyX}px)`;
            el.style.opacity = '0';
            setTimeout(finalizeRemove, 180);
        } else {
            el.style.transform = '';
            el.style.opacity = '';
        }
    };
    el.addEventListener('pointerup', endSwipe);
    el.addEventListener('pointercancel', endSwipe);
}

function validateStrongPasswordClient(pw) {
    const s = String(pw || '');
    const missing = [];
    if (s.length <= 8) missing.push(t('pw_req_len9'));
    if (!/[A-Z]/.test(s)) missing.push(t('pw_req_upper'));
    if (!/[a-z]/.test(s)) missing.push(t('pw_req_lower'));
    if (!/[0-9]/.test(s)) missing.push(t('pw_req_digit'));
    if (!/[^A-Za-z0-9]/.test(s)) missing.push(t('pw_req_symbol'));
    const sep = (store.lang === 'fa') ? '، ' : ', ';
    return {
        valid: missing.length === 0,
        missing,
        message: missing.length === 0 ? t('pw_ok_ready') : (t('pw_err_prefix') + missing.join(sep))
    };
}

function renderPasswordStrengthGuideNode(guideEl, pw, confirmPw = null) {
    if (!guideEl) return;
    const p1 = String(pw || '');
    const p2 = confirmPw !== null ? String(confirmPw || '') : null;
    guideEl.innerHTML = '';
    guideEl.className = 'pw-strength-guide';
    if (!p1 && (!p2 || p2 === '')) {
        guideEl.textContent = t('pw_policy_hint');
        return;
    }
    const rules = [
        [p1.length > 8, t('pw_req_len9')],
        [/[A-Z]/.test(p1), t('pw_req_upper')],
        [/[a-z]/.test(p1), t('pw_req_lower')],
        [/[0-9]/.test(p1), t('pw_req_digit')],
        [/[^A-Za-z0-9]/.test(p1), t('pw_req_symbol')]
    ];
    if (p2 !== null && p2.length > 0) {
        rules.push([p1 === p2, p1 === p2 ? t('inst_pass_match_ok') : t('inst_pass_mismatch')]);
    }
    const allOk = rules.every(r => r[0]);
    if (allOk) guideEl.classList.add('all-ok');
    else guideEl.classList.add('has-err');

    const titleDiv = document.createElement('div');
    titleDiv.style.cssText = 'font-weight:800;margin-bottom:4px';
    titleDiv.textContent = allOk ? ('✓ ' + t('pw_ok_ready')) : ('⚠️ ' + t('pw_guide_title'));
    guideEl.appendChild(titleDiv);

    const ul = document.createElement('ul');
    rules.forEach(([ok, labelTxt]) => {
        const li = document.createElement('li');
        li.className = ok ? 'ok' : 'miss';
        li.textContent = (ok ? '✓ ' : '✗ ') + labelTxt;
        ul.appendChild(li);
    });
    guideEl.appendChild(ul);
}

function createCopyUsernameChip(rawUsername) {
    const clean = String(rawUsername || '').replace(/^@+/, '').trim();
    if (!clean) return null;
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'copy-uname-chip';
    btn.title = t('copy_username_btn') + `: @${clean}`;
    btn.textContent = `📋 @${clean}`;
    btn.addEventListener('click', async (ev) => {
        ev.preventDefault();
        ev.stopPropagation();
        await copyTextToClipboard('@' + clean);
        toast(t('username_copied_toast') + '@' + clean);
    });
    return btn;
}

function getDefaultSiteLogoDataUri() {
    const attr = document.documentElement && document.documentElement.getAttribute('data-default-logo');
    return (attr && attr.trim()) ? attr.trim() : '?a=icon&v=009687';
}

function getEffectiveSiteLogoUri(customLogo) {
    const c = typeof customLogo === 'string' ? customLogo.trim() : String((store.settings && store.settings.site_logo) || '').trim();
    return c || getDefaultSiteLogoDataUri();
}

function syncMinimizedPopupsLayout() {
    const lcw = document.getElementById('live-call-window');
    const ump = document.getElementById('universal-media-player');
    const lcwVis = Boolean(lcw && !lcw.classList.contains('hidden'));
    const umpVis = Boolean(ump && !ump.classList.contains('hidden'));
    const lcwMin = lcwVis && lcw.getAttribute('data-mode') === 'minimized';
    const umpMin = umpVis && ump.getAttribute('data-mode') === 'minimize';

    if (lcw) lcw.style.setProperty('--min-stack-offset', '0px');
    if (ump) {
        if (lcwMin && umpMin) {
            ump.style.setProperty('--min-stack-offset', '64px');
        } else {
            ump.style.setProperty('--min-stack-offset', '0px');
        }
    }

    // Also resolve bounding-box overlap if either minimized/floating popup was manually dragged
    if (lcwVis && umpVis && (lcwMin || umpMin || lcw.getAttribute('data-mode') === 'popup' || ump.getAttribute('data-mode') === 'float')) {
        const r1 = lcw.getBoundingClientRect();
        const r2 = ump.getBoundingClientRect();
        if (r1.width > 0 && r2.width > 0 && !(r1.right <= r2.left || r1.left >= r2.right || r1.bottom <= r2.top || r1.top >= r2.bottom)) {
            const vh = window.innerHeight || 800;
            const targetEl = umpMin ? ump : (lcwMin ? lcw : ump);
            const anchorRect = (targetEl === ump) ? r1 : r2;
            const targetH = targetEl.offsetHeight || 50;
            let nextTop = anchorRect.bottom + 10;
            if (nextTop + targetH > vh - 8) {
                nextTop = Math.max(8, anchorRect.top - targetH - 10);
            }
            targetEl.style.top = `${Math.round(nextTop)}px`;
            targetEl.style.bottom = 'auto';
        }
    }
}

async function copyTextToClipboard(text) {
    const val = String(text || '');
    if (!val) return false;
    if (navigator.clipboard && typeof navigator.clipboard.writeText === 'function') {
        try {
            await navigator.clipboard.writeText(val);
            return true;
        } catch (e) {}
    }
    try {
        const ta = document.createElement('textarea');
        ta.value = val;
        ta.setAttribute('readonly', 'readonly');
        ta.style.cssText = 'position:fixed;opacity:0;pointer-events:none;left:-9999px;top:0';
        document.body.appendChild(ta);
        ta.focus();
        ta.select();
        const ok = document.execCommand && document.execCommand('copy');
        ta.remove();
        return Boolean(ok);
    } catch (e) {
        return false;
    }
}

function buildRecoveryCodeDescNode(introText, codeStr) {
    const wrap = document.createElement('div');
    const intro = document.createElement('div');
    intro.style.cssText = 'font-size:13px;line-height:1.65;color:var(--text-secondary)';
    intro.textContent = introText || '';
    wrap.appendChild(intro);

    const codeBox = document.createElement('div');
    codeBox.className = 'clickable-recovery-code';
    codeBox.setAttribute('role', 'button');
    codeBox.setAttribute('tabindex', '0');
    codeBox.title = t('rec_click_to_copy_hint');

    const valSpan = document.createElement('span');
    valSpan.className = 'clickable-recovery-code-val';
    valSpan.textContent = `🔑 ${codeStr}`;

    const hintSpan = document.createElement('span');
    hintSpan.className = 'clickable-recovery-code-hint';
    hintSpan.textContent = t('rec_click_to_copy_hint');

    codeBox.appendChild(valSpan);
    codeBox.appendChild(hintSpan);

    const triggerCopy = async (ev) => {
        if (ev) ev.stopPropagation();
        await copyTextToClipboard(codeStr);
        codeBox.classList.add('copied');
        hintSpan.textContent = t('rec_copied_badge');
        toast(t('rec_copied_toast'));
        setTimeout(() => {
            codeBox.classList.remove('copied');
            hintSpan.textContent = t('rec_click_to_copy_hint');
        }, 2000);
    };
    codeBox.addEventListener('click', triggerCopy);
    codeBox.addEventListener('keydown', ev => {
        if (ev.key === 'Enter' || ev.key === ' ') {
            ev.preventDefault();
            triggerCopy(ev);
        }
    });

    wrap.appendChild(codeBox);
    return wrap;
}

function applySiteBrandingAssets(logoUri, favUri) {
    const logo = typeof logoUri === 'string' ? logoUri.trim() : String((store.settings && store.settings.site_logo) || '').trim();
    const fav = typeof favUri === 'string' ? favUri.trim() : String((store.settings && store.settings.site_favicon) || '').trim();

    let favLink = document.getElementById('dynamic-favicon') || document.querySelector('link[rel="icon"]');
    if (!favLink && document.head) {
        favLink = document.createElement('link');
        favLink.id = 'dynamic-favicon';
        favLink.rel = 'icon';
        document.head.appendChild(favLink);
    }
    if (favLink) {
        const nextHref = fav || logo || '?a=icon&v=009687';
        favLink.href = nextHref;
        if (nextHref.startsWith('data:image/')) {
            const m = nextHref.match(/^data:(image\/[^;]+);/i);
            if (m) favLink.type = m[1];
        } else {
            favLink.removeAttribute('type');
        }
    }

    const effectiveLogo = getEffectiveSiteLogoUri(logo);
    document.querySelectorAll('.brand-logo').forEach(el => {
        el.innerHTML = '';
        el.classList.add('has-custom-logo');
        const img = document.createElement('img');
        img.src = effectiveLogo;
        img.alt = 'Logo';
        el.appendChild(img);
    });
}

function clearAllAuthFormsCompletely(resetTabToLogin = false) {
    const formIds = ['login-form', 'register-form', 'recovery-form'];
    const allInputs = [];
    formIds.forEach(fid => {
        const f = document.getElementById(fid);
        if (!f) return;
        f.reset();
        f.querySelectorAll('input, textarea').forEach(inp => {
            if (inp.type === 'submit' || inp.type === 'button' || inp.type === 'hidden') return;
            inp._userEdited = false;
            inp.value = '';
            inp.defaultValue = '';
            inp.setAttribute('value', '');
            inp.removeAttribute('value');
            if (!inp._boundAuthEditTrack) {
                inp._boundAuthEditTrack = true;
                const markEdited = () => { inp._userEdited = true; };
                inp.addEventListener('keydown', markEdited);
                inp.addEventListener('paste', markEdited);
                inp.addEventListener('input', () => { if (document.activeElement === inp || inp.hasAttribute('data-captcha-ans')) inp._userEdited = true; });
            }
            allInputs.push(inp);
        });
    });

    const totpGrp = document.getElementById('login-totp-group');
    if (totpGrp) totpGrp.classList.add('hidden');

    if (resetTabToLogin) {
        document.querySelectorAll('[data-auth-tab]').forEach(b => {
            b.classList.toggle('active', b.dataset.authTab === 'login');
        });
        const lf = document.getElementById('login-form');
        const rf = document.getElementById('register-form');
        const recf = document.getElementById('recovery-form');
        if (lf) lf.classList.remove('hidden');
        if (rf) rf.classList.add('hidden');
        if (recf) recf.classList.add('hidden');
    }

    // Defeat delayed browser password-manager autofill injections on form reveal unless user actively typed
    [40, 160].forEach(delay => {
        setTimeout(() => {
            allInputs.forEach(inp => {
                if (!inp._userEdited && document.activeElement !== inp) {
                    inp.value = '';
                    inp.defaultValue = '';
                }
            });
        }, delay);
    });
}

const PW_EYE_OPEN_SVG = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></svg>';
const PW_EYE_OFF_SVG = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M17.94 17.94A10.07 10.07 0 0 1 12 20c-7 0-11-8-11-8a18.45 18.45 0 0 1 5.06-5.94M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19m-6.72-1.07a3 3 0 1 1-4.24-4.24"/><line x1="1" y1="1" x2="23" y2="23"/></svg>';

function syncPwToggleBtnState(btn, isShown) {
    if (!btn) return;
    btn.classList.toggle('is-shown', !!isShown);
    btn.innerHTML = isShown ? PW_EYE_OFF_SVG : PW_EYE_OPEN_SVG;
    const lbl = t(isShown ? 'hide_password' : 'show_password');
    btn.title = lbl;
    btn.setAttribute('aria-label', lbl);
}

function enhancePasswordFields(root = document) {
    if (!root || !root.querySelectorAll) return;
    root.querySelectorAll('input[type="password"]').forEach(input => {
        if (input.id === 'confirm-modal-input' || input.id === 'decoy-pw-input' || input.dataset.pwEnhanced === '1') return;
        input.dataset.pwEnhanced = '1';
        if (!input.getAttribute('dir')) input.setAttribute('dir', 'ltr');
        input.classList.add('has-pw-toggle');

        const wrap = document.createElement('div');
        wrap.className = 'pw-field-wrap';
        if (input.parentNode) {
            input.parentNode.insertBefore(wrap, input);
        }
        wrap.appendChild(input);

        const btn = document.createElement('button');
        btn.type = 'button';
        btn.className = 'pw-toggle-btn';
        syncPwToggleBtnState(btn, false);
        btn.addEventListener('click', e => {
            e.preventDefault();
            e.stopPropagation();
            const showNow = input.type === 'password';
            input.type = showNow ? 'text' : 'password';
            syncPwToggleBtnState(btn, showNow);
            try { input.focus({ preventScroll: true }); } catch (_) {}
        });
        wrap.appendChild(btn);
    });
}

let _pwObserverStarted = false;
function startPasswordFieldObserver() {
    if (_pwObserverStarted || typeof MutationObserver === 'undefined' || !document.body) return;
    _pwObserverStarted = true;
    enhancePasswordFields(document);
    const obs = new MutationObserver(mutations => {
        for (const m of mutations) {
            for (const node of m.addedNodes) {
                if (node && node.nodeType === 1) {
                    if (node.tagName === 'INPUT' && node.type === 'password') {
                        enhancePasswordFields(node.parentNode || document);
                    } else if (node.querySelectorAll) {
                        enhancePasswordFields(node);
                    }
                }
            }
        }
    });
    obs.observe(document.body, { childList: true, subtree: true });
}

function askApproval(opts = {}) {
    return new Promise(resolve => {
        const dlg = document.getElementById('confirm-modal');
        const iconEl = document.getElementById('confirm-modal-icon');
        const titleEl = document.getElementById('confirm-modal-title');
        const descEl = document.getElementById('confirm-modal-desc');
        const chkWrap = document.getElementById('confirm-modal-check-wrap');
        const chkLbl = document.getElementById('confirm-modal-check-label');
        const chkIn = document.getElementById('confirm-modal-checkbox');
        const inWrap = document.getElementById('confirm-modal-input-wrap');
        const inLbl = document.getElementById('confirm-modal-input-label');
        const inField = document.getElementById('confirm-modal-input');
        const pwToggle = document.getElementById('confirm-modal-pw-toggle');
        const btnCancel = document.getElementById('confirm-modal-cancel');
        const btnOk = document.getElementById('confirm-modal-ok');

        if (!dlg || !btnOk || !btnCancel) {
            resolve({ approved: false, value: '', checked: false });
            return;
        }

        const isDanger = opts.danger !== false;
        const resolvedCheckboxLabel = opts.checkboxLabel || opts.checkLabel || '';
        const chkRequired = !!(resolvedCheckboxLabel && (opts.checkboxRequired !== undefined ? opts.checkboxRequired : !!opts.checkLabel));

        dlg.classList.toggle('is-danger', isDanger);
        iconEl.textContent = opts.icon || (isDanger ? '⚠️' : '🛡️');
        // An icon is always rendered beside the title, so a leading emoji on
        // the title itself would show twice (e.g. "🗑️ 🗑️ Delete").
        titleEl.textContent = (opts.title ? stripLeadingEmoji(opts.title) : '') || t('confirm_default_title');
        descEl.innerHTML = '';
        if (opts.descNode) {
            descEl.appendChild(opts.descNode);
        } else {
            descEl.textContent = opts.desc || '';
        }

        chkWrap.classList.remove('chk-shake', 'is-required', 'is-checked');
        if (resolvedCheckboxLabel) {
            chkWrap.classList.remove('hidden');
            chkLbl.textContent = resolvedCheckboxLabel;
            chkIn.checked = !!opts.checkboxDefault;
            if (chkRequired) {
                chkWrap.classList.add('is-required');
                chkWrap.classList.toggle('is-checked', chkIn.checked);
            }
        } else {
            chkWrap.classList.add('hidden');
            chkIn.checked = false;
        }

        const isPwInput = !!(opts.input && opts.input.type === 'password');
        if (opts.input) {
            inWrap.classList.remove('hidden');
            inLbl.textContent = opts.input.label || '';
            inField.type = opts.input.type || 'text';
            inField.setAttribute('autocomplete', isPwInput ? 'new-password' : 'off');
            inField.placeholder = opts.input.placeholder || (isPwInput ? '••••••••' : '');
            inField.value = opts.input.defaultValue !== undefined ? String(opts.input.defaultValue) : '';
            inField.dir = opts.input.dir || (isPwInput ? 'ltr' : 'auto');
            inField.classList.toggle('has-pw-toggle', isPwInput);
            if (pwToggle) {
                pwToggle.classList.toggle('hidden', !isPwInput);
                if (isPwInput) syncPwToggleBtnState(pwToggle, false);
            }
        } else {
            inWrap.classList.add('hidden');
            inField.value = '';
            inField.classList.remove('has-pw-toggle');
            if (pwToggle) pwToggle.classList.add('hidden');
        }

        btnCancel.classList.toggle('hidden', !!opts.hideCancel);
        btnCancel.textContent = opts.cancelText || t('confirm_cancel_btn');
        btnOk.textContent = opts.confirmText || opts.okText || t('confirm_approve_btn');
        btnOk.className = isDanger ? 'btn btn-danger' : 'btn btn-primary';
        btnOk.disabled = chkRequired && !chkIn.checked;

        let settled = false;
        const finish = (approved) => {
            if (settled) return;
            settled = true;
            if (approved && chkRequired && !chkIn.checked) {
                settled = false;
                chkWrap.classList.remove('chk-shake');
                void chkWrap.offsetWidth;
                chkWrap.classList.add('chk-shake');
                toast(t('confirm_chk_required_toast'), true);
                chkIn.focus();
                return;
            }
            if (approved && opts.input && opts.input.required && inField.value.trim() === '') {
                settled = false;
                inField.focus();
                return;
            }
            const val = inField.value;
            const chk = chkIn.checked;
            cleanup();
            if (isPwInput) inField.type = 'password';
            if (dlg.open) dlg.close();
            resolve({ approved, value: val, checked: chk });
        };

        const onChkChange = () => {
            if (chkRequired) {
                chkWrap.classList.toggle('is-checked', chkIn.checked);
                btnOk.disabled = !chkIn.checked;
            }
        };
        const onPwToggle = e => {
            e.preventDefault();
            e.stopPropagation();
            if (!isPwInput) return;
            const showNow = inField.type === 'password';
            inField.type = showNow ? 'text' : 'password';
            syncPwToggleBtnState(pwToggle, showNow);
            try { inField.focus({ preventScroll: true }); } catch (_) {}
        };
        const onOk = () => finish(true);
        const onCancel = () => finish(false);
        const onKey = e => {
            if (e.key === 'Enter' && dlg.open) {
                e.preventDefault();
                finish(true);
            }
        };
        const onCloseNative = () => {
            if (!settled) {
                settled = true;
                cleanup();
                if (isPwInput) inField.type = 'password';
                resolve({ approved: false, value: '', checked: false });
            }
        };
        let confirmBackdropDown = false;
        const onBackdropDown = e => {
            confirmBackdropDown = (!opts.hideCancel && isDialogBackdropHit(dlg, e));
        };
        const onBackdrop = e => {
            if (!opts.hideCancel && confirmBackdropDown && isDialogBackdropHit(dlg, e)) {
                confirmBackdropDown = false;
                finish(false);
                return;
            }
            confirmBackdropDown = false;
        };

        function cleanup() {
            chkIn.removeEventListener('change', onChkChange);
            if (pwToggle) pwToggle.removeEventListener('click', onPwToggle);
            btnOk.removeEventListener('click', onOk);
            btnCancel.removeEventListener('click', onCancel);
            inField.removeEventListener('keydown', onKey);
            dlg.removeEventListener('close', onCloseNative);
            dlg.removeEventListener('mousedown', onBackdropDown);
            dlg.removeEventListener('touchstart', onBackdropDown);
            dlg.removeEventListener('click', onBackdrop);
        }

        chkIn.addEventListener('change', onChkChange);
        if (pwToggle) pwToggle.addEventListener('click', onPwToggle);
        btnOk.addEventListener('click', onOk);
        btnCancel.addEventListener('click', onCancel);
        inField.addEventListener('keydown', onKey);
        dlg.addEventListener('close', onCloseNative);
        dlg.addEventListener('mousedown', onBackdropDown);
        dlg.addEventListener('touchstart', onBackdropDown, { passive: true });
        dlg.addEventListener('click', onBackdrop);

        if (!dlg.open) dlg.showModal();
        // Keep #confirm-modal on top of all popovers (call window & media player); only re-promote minimized bar if needed
        if (typeof UniversalPlayer !== 'undefined' && UniversalPlayer.promoteTopLayer && UniversalPlayer.mode === 'minimize') {
            UniversalPlayer.promoteTopLayer();
        }
        if (store.isSessionLocked && typeof showMessengerLockScreen === 'function') {
            showMessengerLockScreen(store.user);
        }
        if (opts.input) {
            setTimeout(() => inField.focus(), 40);
        } else {
            setTimeout(() => btnOk.focus(), 40);
        }
    });
}

/* ---------------- INLINE SVG HELPERS (TICKS, ADMIN BADGE, AVATARS, SAFE AUTOLINKER) ---------------- */
function createTickIcon(status) {
    const span = document.createElement('span');
    span.className = 'msg-tick' + (status === 'seen' ? ' seen' : '');
    if (status === 'pending') {
        span.title = t('tick_pending');
        span.innerHTML = '<svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.6"><circle cx="8" cy="8" r="6"/><path d="M8 4.5V8l2.5 1.5" stroke-linecap="round"/></svg>';
    } else if (status === 'seen') {
        span.title = t('tick_seen');
        span.innerHTML = '<svg viewBox="0 0 18 16" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"><path d="M1.5 8.5l3.5 3.5 7.5-7.5"/><path d="M6.5 8.5l3.5 3.5 6.5-7.5"/></svg>';
    } else {
        span.title = t('tick_sent');
        span.innerHTML = '<svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"><path d="M3 8.5l3.5 3.5 6.5-7.5"/></svg>';
    }
    return span;
}

function createViewsCounter(count) {
    const span = document.createElement('span');
    span.className = 'msg-views';
    span.title = t('msg_views_tip');
    span.setAttribute('data-i18n-title', 'msg_views_tip');
    // Monochrome glyph, matching the rest of the message controls.
    span.innerHTML = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"><path d="M1.8 12S5.4 5.6 12 5.6 22.2 12 22.2 12 18.6 18.4 12 18.4 1.8 12 1.8 12z"/><circle cx="12" cy="12" r="3.1"/></svg>';
    const txt = document.createElement('span');
    txt.textContent = formatMemberCount(count);
    span.appendChild(txt);
    return span;
}

function createAdminBadgeNode() {
    const badge = document.createElement('span');
    badge.className = 'admin-badge';
    badge.title = t('admin_badge');
    badge.innerHTML = '<svg viewBox="0 0 16 16"><path d="M8 1l6 2.5v4.5c0 3.8-2.6 6.8-6 7.8-3.4-1-6-4-6-7.8V3.5L8 1zm-1 9.4l4.3-4.3-1.1-1.1L7 8.2 5.3 6.5 4.2 7.6 7 10.4z"/></svg>';
    const txt = document.createElement('span');
    txt.textContent = t('admin_badge');
    badge.appendChild(txt);
    return badge;
}

function createAuthorAdminBadge(msg, chat) {
    if (!msg) return null;
    if (msg.has_admin_badge) {
        return createAdminBadgeNode();
    }
    if (chat && (chat.type === 'group' || chat.type === 'channel')) {
        const cRole = String(msg.author_chat_role || (Number(chat.owner_id) === Number(msg.user_id) ? 'owner' : ''));
        if (cRole === 'owner' || cRole === 'admin' || Number(msg.is_chat_admin) === 1) {
            const b = document.createElement('span');
            b.className = 'chat-admin-badge';
            b.textContent = (cRole === 'owner' ? '👑 ' + t('chat_owner_badge') : '🛡️ ' + t('chat_admin_role_badge'));
            return b;
        }
    }
    return null;
}

async function openMentionHandle(rawHandle) {
    const clean = String(rawHandle || '').replace(/^@+/, '').trim().toLowerCase();
    if (!/^[a-z0-9_]{3,32}$/.test(clean)) return;
    const localChat = (store.chats || []).find(c => {
        if (c.handle && String(c.handle).toLowerCase() === clean) return true;
        if (c.type === 'dm' && c.peer && c.peer.username && String(c.peer.username).toLowerCase() === clean) return true;
        return false;
    });
    if (localChat) {
        await selectChat(localChat.id);
        return;
    }
    if (store.user && ((store.user.username && String(store.user.username).toLowerCase() === clean) || (store.user.login_username && String(store.user.login_username).toLowerCase() === clean && !store.user.no_username))) {
        const saved = (store.chats || []).find(c => c.type === 'saved');
        if (saved) {
            await selectChat(saved.id);
            return;
        }
    }
    const r = await apiCall('resolve_mention', { handle: clean });
    if (r.ok && r.data && r.data.chat_id) {
        if (Array.isArray(r.data.chats)) {
            store.chats = r.data.chats;
            renderChatList();
        }
        if (r.data.status === 'pending') {
            toast(t('join_req_pending_toast'));
            return;
        }
        await selectChat(Number(r.data.chat_id));
    } else {
        toast((r && r.message) || t('err_generic'), true);
    }
}

function hashStringIdx(str) {
    let h = 0;
    const s = String(str || 'A');
    for (let i = 0; i < s.length; i++) {
        h = ((h << 5) - h) + s.charCodeAt(i);
        h |= 0;
    }
    return Math.abs(h) % AVATAR_GRADIENTS.length;
}

function renderAvatarNode(el, title, avatarData, isSaved = false, isSystem = false) {
    el.innerHTML = '';
    el.classList.toggle('saved-avatar-badge', !!(isSaved || isSystem));
    if (isSaved) {
        el.style.background = '';
        el.textContent = '🔖';
        return;
    }
    if (isSystem) {
        el.style.background = 'linear-gradient(135deg, #009687, #0f766e)';
        el.style.color = '#fff';
        el.textContent = '🛡️';
        return;
    }
    el.style.background = AVATAR_GRADIENTS[hashStringIdx(title)];
    const isSafeDataImg = typeof avatarData === 'string' && /^data:image\/(png|jpeg|jpg|webp|gif);base64,[A-Za-z0-9+/=]+$/i.test(avatarData);
    const isSafeFileUrl = typeof avatarData === 'string' && /^\?a=file&id=\d+$/.test(avatarData);
    if (isSafeDataImg || isSafeFileUrl) {
        const img = document.createElement('img');
        img.src = avatarData;
        img.alt = title || '';
        el.appendChild(img);
    } else {
        const clean = (title || '?').replace(/^[^\p{L}\p{N}]+/u, '').trim();
        const ch = (clean || title || '?').charAt(0).toUpperCase();
        el.textContent = ch || '?';
    }
}

function appendLinkedText(container, text) {
    const str = String(text || '');
    const tokenRegex = /(https?:\/\/[^\s<>"']+)|((?:^|[^A-Za-z0-9_])@[A-Za-z0-9_]{3,32})(?![A-Za-z0-9_])/g;
    let lastIndex = 0;
    let match;
    while ((match = tokenRegex.exec(str)) !== null) {
        if (match[1]) {
            if (match.index > lastIndex) {
                container.appendChild(document.createTextNode(str.slice(lastIndex, match.index)));
            }
            const a = document.createElement('a');
            a.href = match[1];
            a.target = '_blank';
            a.rel = 'noopener noreferrer nofollow';
            a.textContent = match[1];
            container.appendChild(a);
            lastIndex = tokenRegex.lastIndex;
        } else if (match[2]) {
            const fullSeg = match[2];
            const atPos = fullSeg.indexOf('@');
            const prefix = atPos > 0 ? fullSeg.slice(0, atPos) : '';
            const mentionTxt = fullSeg.slice(atPos);
            const beforeEnd = match.index + prefix.length;
            if (beforeEnd > lastIndex) {
                container.appendChild(document.createTextNode(str.slice(lastIndex, beforeEnd)));
            }
            const mLink = document.createElement('a');
            mLink.href = '#' + mentionTxt;
            mLink.className = 'msg-mention-link';
            mLink.dataset.mention = mentionTxt.slice(1);
            mLink.dir = 'ltr';
            mLink.textContent = mentionTxt;
            mLink.addEventListener('click', ev => {
                ev.preventDefault();
                ev.stopPropagation();
                if (store.selectedMsgIds && store.selectedMsgIds.size > 0) return;
                openMentionHandle(mentionTxt.slice(1));
            });
            container.appendChild(mLink);
            lastIndex = tokenRegex.lastIndex;
        }
    }
    if (lastIndex < str.length) {
        container.appendChild(document.createTextNode(str.slice(lastIndex)));
    }
}

