function localizeApiError(code, fallbackMsg, details) {
    const lang = store.lang === 'en' ? 'en' : 'fa';
    const raw = String(fallbackMsg || '');
    const det = details && typeof details === 'object' ? details : {};

    // Also catch legacy/raw SQLSTATE[HY000] [1049] Unknown database '...' strings gracefully
    if (code === 'db_error' || raw.includes('SQLSTATE')) {
        const m1049 = raw.match(/Unknown database\s+'([^']*)'/i);
        if (m1049 || raw.includes('[1049]')) {
            code = 'db_unknown_database';
            if (!det.db_name && m1049) det.db_name = m1049[1];
        } else if (raw.includes('[1045]') || raw.includes('[1044]') || /Access denied/i.test(raw)) {
            code = 'db_access_denied';
        } else if (raw.includes('[2002]') || raw.includes('[2003]') || /Connection refused|No such file/i.test(raw)) {
            code = 'db_connect_failed';
        } else if (/could not find driver/i.test(raw)) {
            code = 'db_driver_missing';
        } else if (code === 'db_error') {
            code = 'db_setup_failed';
        }
    }

    if (code === 'env_error') {
        const parts = [t('inst_env_error_main')];
        if (det && typeof det === 'object') {
            if (det.php_ok === false) parts.push(t('inst_env_err_php'));
            if (det.has_sqlite === false && det.has_mysql === false) parts.push(t('inst_env_err_pdo'));
            if (det.writable === false) parts.push(t('inst_env_err_writable'));
        }
        return parts.join(' ');
    }
    if (code === 'already_installed') return t('inst_err_already_installed');
    if (code === 'invalid_username') {
        return formatInvalidUsernameErr(det && det.min ? Number(det.min) : undefined, det && det.max ? Number(det.max) : undefined);
    }
    if (code === 'invalid_display_name') {
        return formatInvalidDisplayNameErr(det && det.min ? Number(det.min) : undefined, det && det.max ? Number(det.max) : undefined);
    }
    if (code === 'uploads_disabled_globally') return t('err_uploads_disabled_globally');
    if (code === 'uploads_disabled_user') return t('err_uploads_disabled_user');
    if (code === 'system_traffic_exceeded') return t('err_sys_traffic_exceeded');
    if (code === 'user_traffic_exceeded') return t('err_user_traffic_exceeded');
    if (code === 'cannot_block_superadmin') return t('err_cannot_block_superadmin');
    if (code === 'dm_disabled_by_user') return t('err_dm_disabled_by_user');
    if (code === 'calls_disabled_by_user') return t('err_calls_disabled_by_user');
    if (code === 'group_invite_denied_by_user') return t('err_group_invite_denied_by_user');
    if (code === 'callee_busy') return t('call_user_busy_err');
    if (code === 'backup_traffic_insufficient') {
        if (det && det.zip_bytes !== undefined && det.remaining_bytes !== undefined && det.remaining_bytes !== null) {
            return t('user_backup_traffic_err_tpl')
                .replace('{need}', formatBytes(Number(det.zip_bytes) || 0))
                .replace('{rem}', formatBytes(Number(det.remaining_bytes) || 0));
        }
        return t('user_backup_traffic_err_generic');
    }
    if (code === 'video_note_disabled') return t('vnote_disabled_err');
    if (code === 'file_too_large') return t('err_file_too_large_server');
    if (code === 'weak_password') return t('pw_weak_err');
    if (code === 'content_type_restricted') {
        const ct = (det && det.content_type) ? String(det.content_type) : '';
        const ctLbl = ct && I18N[lang]['ctype_' + ct] ? stripLeadingEmoji(I18N[lang]['ctype_' + ct]) : (ct || 'media');
        return t('err_content_restricted_tpl').replace('{type}', ctLbl);
    }
    if (code === 'password_mismatch') return t('pw_mismatch_err');
    if (code === 'duress_confirm_mismatch') return t('duress_pw_mismatch_err');
    if (code === 'wrong_lock_password') return t('lock_screen_wrong_pw');
    if (code === 'session_locked') return t('lock_screen_locked_title');

    if (API_ERR_I18N[lang] && API_ERR_I18N[lang][code]) {
        return API_ERR_I18N[lang][code]
            .replace(/\{db\}/g, det.db_name || 'messenger')
            .replace(/\{user\}/g, det.db_user || 'root')
            .replace(/\{host\}/g, det.db_host || '127.0.0.1')
            .replace(/\{port\}/g, String(det.db_port || 3306));
    }
    if (raw.includes(' / ')) {
        const parts = raw.split(' / ');
        return lang === 'fa' ? parts[0].trim() : parts[parts.length - 1].trim();
    }
    return raw || t('err_generic');
}

let _zeroTraceBlankOutInFlight = false;
async function triggerClientZeroTraceBlankOut() {
    if (_zeroTraceBlankOutInFlight) return;
    _zeroTraceBlankOutInFlight = true;
    try {
        store.user = null;
        store.polling = false;
        if (store.ttlTickerId) { clearInterval(store.ttlTickerId); store.ttlTickerId = null; }
        if (store._idleClockInterval) { clearInterval(store._idleClockInterval); store._idleClockInterval = null; }
    } catch (e) {}
    try { if (typeof E2EE !== 'undefined' && E2EE.wipeLocalKeys) await E2EE.wipeLocalKeys(); } catch (e) {}
    try { localStorage.clear(); } catch (e) {}
    try { sessionStorage.clear(); } catch (e) {}
    try {
        if (window.indexedDB && typeof window.indexedDB.databases === 'function') {
            const dbs = await window.indexedDB.databases();
            (dbs || []).forEach(d => { if (d && d.name) { try { window.indexedDB.deleteDatabase(d.name); } catch (e) {} } });
        } else if (window.indexedDB) {
            try { window.indexedDB.deleteDatabase('m3_e2ee_v1'); } catch (e) {}
        }
    } catch (e) {}
    try {
        if ('serviceWorker' in navigator) {
            const regs = await navigator.serviceWorker.getRegistrations();
            for (const reg of regs) { try { await reg.unregister(); } catch (e) {} }
        }
        if ('caches' in window) {
            const keys = await caches.keys();
            for (const k of keys) { try { await caches.delete(k); } catch (e) {} }
        }
    } catch (e) {}
    try {
        document.querySelectorAll('dialog[open]').forEach(d => { try { d.close(); } catch (e) {} });
        document.title = '';
        document.documentElement.style.cssText = 'margin:0;padding:0;background:#ffffff !important;';
        if (document.body) {
            document.body.innerHTML = '';
            document.body.style.cssText = 'margin:0;padding:0;background:#ffffff !important;';
        }
    } catch (e) {}
    try {
        window.location.replace(window.location.pathname || './');
    } catch (e) {
        try { window.location.reload(); } catch (e2) {}
    }
}

async function refreshCsrfTokenFromBoot() {
    try {
        const r = await fetch('?a=api&do=boot', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ do: 'boot' }),
            credentials: 'same-origin'
        });
        const j = await r.json();
        if (j && j.ok && j.data && j.data.csrf_token) {
            store.csrf = String(j.data.csrf_token);
            return store.csrf;
        }
    } catch (e) {}
    return '';
}

async function apiCall(action, data = {}, isFormData = false, _retriedCsrf = false) {
    const headers = {};
    if (store.csrf) {
        headers['X-CSRF-Token'] = store.csrf;
    }
    let body;
    if (isFormData) {
        if (store.csrf && data && typeof data.set === 'function') {
            data.set('csrf_token', store.csrf);
        }
        body = data;
    } else {
        headers['Content-Type'] = 'application/json';
        body = JSON.stringify(Object.assign({ do: action, csrf_token: store.csrf || '' }, data));
    }
    const urlCsrf = (isFormData && store.csrf) ? '&csrf_token=' + encodeURIComponent(store.csrf) : '';
    const res = await fetch('?a=api&do=' + encodeURIComponent(action) + urlCsrf, {
        method: 'POST',
        headers,
        body,
        credentials: 'same-origin'
    });
    let json = null;
    try {
        json = await res.json();
    } catch (parseErr) {
        if (res.status === 413) {
            return { ok: false, error: 'file_too_large', message: t('err_file_too_large_server') };
        }
        return { ok: false, error: 'network_error', message: t('err_generic') };
    }
    if (json && !json.ok && json.error === 'csrf_invalid' && !_retriedCsrf && action !== 'boot') {
        const freshCsrf = await refreshCsrfTokenFromBoot();
        if (freshCsrf) {
            return apiCall(action, data, isFormData, true);
        }
    }
    if (json && (json.error === 'messenger_wiped' || json.wiped === true || json.panic_wiped === true || (json.data && json.data.self_destructed === true))) {
        await triggerClientZeroTraceBlankOut();
        return json;
    }
    if (json && !json.ok && json.error === 'not_installed') {
        localStorage.clear();
        location.href = './';
        return json;
    }
    if (json && !json.ok && json.error === 'session_locked' && action !== 'session_unlock' && action !== 'logout') {
        // Re-showing it on every poll while it is already up would keep clearing
        // whatever was typed and, with a decoy, look like a flicker.
        const decoyElNow = document.getElementById('decoy-screen');
        const lockDlgNow = document.getElementById('lock-screen-dialog');
        const lockAlreadyUp = (decoyElNow && !decoyElNow.classList.contains('hidden'))
            || (lockDlgNow && (lockDlgNow.open || lockDlgNow.hasAttribute('open')));
        if (!lockAlreadyUp && typeof showMessengerLockScreen === 'function') showMessengerLockScreen(store.user);
    }
    if (json && !json.ok && json.error) {
        if (json.error === 'weak_password_complex' && json.message) {
            const parts = String(json.message).split(' / ');
            json.message = (store.lang === 'fa') ? (parts[0] || json.message) : (parts[1] || parts[0] || json.message);
        } else {
            json.message = localizeApiError(json.error, json.message, json.details);
        }
    }
    if (json && json.tick && (action === 'bootstrap' || action === 'boot')) {
        const nextT = String(json.tick);
        if (!store.tick || nextT.localeCompare(String(store.tick), undefined, { numeric: true }) > 0) {
            store.tick = nextT;
        }
    }
    return json;
}

function sha256BytesPure(bytesIn) {
    const K = [
        0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
        0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
        0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
        0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
        0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
        0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
        0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
        0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2
    ];
    const l = bytesIn.length;
    const bitHi = Math.floor((l * 8) / 0x100000000);
    const bitLo = (l * 8) >>> 0;
    const padLen = ((l + 9 + 63) & ~63);
    const msg = new Uint8Array(padLen);
    msg.set(bytesIn);
    msg[l] = 0x80;
    const dv = new DataView(msg.buffer);
    dv.setUint32(padLen - 8, bitHi, false);
    dv.setUint32(padLen - 4, bitLo, false);

    let h0 = 0x6a09e667, h1 = 0xbb67ae85, h2 = 0x3c6ef372, h3 = 0xa54ff53a;
    let h4 = 0x510e527f, h5 = 0x9b05688c, h6 = 0x1f83d9ab, h7 = 0x5be0cd19;
    const W = new Int32Array(64);
    const rotr = (x, n) => (x >>> n) | (x << (32 - n));

    for (let off = 0; off < padLen; off += 64) {
        for (let i = 0; i < 16; i++) W[i] = dv.getInt32(off + i * 4, false);
        for (let i = 16; i < 64; i++) {
            const s0 = rotr(W[i - 15], 7) ^ rotr(W[i - 15], 18) ^ (W[i - 15] >>> 3);
            const s1 = rotr(W[i - 2], 17) ^ rotr(W[i - 2], 19) ^ (W[i - 2] >>> 10);
            W[i] = (W[i - 16] + s0 + W[i - 7] + s1) | 0;
        }
        let a = h0, b = h1, c = h2, d = h3, e = h4, f = h5, g = h6, h = h7;
        for (let i = 0; i < 64; i++) {
            const S1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25);
            const ch = (e & f) ^ (~e & g);
            const t1 = (h + S1 + ch + K[i] + W[i]) | 0;
            const S0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22);
            const maj = (a & b) ^ (a & c) ^ (b & c);
            const t2 = (S0 + maj) | 0;
            h = g; g = f; f = e; e = (d + t1) | 0;
            d = c; c = b; b = a; a = (t1 + t2) | 0;
        }
        h0 = (h0 + a) | 0; h1 = (h1 + b) | 0; h2 = (h2 + c) | 0; h3 = (h3 + d) | 0;
        h4 = (h4 + e) | 0; h5 = (h5 + f) | 0; h6 = (h6 + g) | 0; h7 = (h7 + h) | 0;
    }
    const out = new Uint8Array(32);
    const odv = new DataView(out.buffer);
    [h0, h1, h2, h3, h4, h5, h6, h7].forEach((v, idx) => odv.setInt32(idx * 4, v, false));
    return out;
}

async function sha256BytesCompat(u8Bytes) {
    if (window.crypto && window.crypto.subtle && typeof window.crypto.subtle.digest === 'function') {
        const buf = await window.crypto.subtle.digest('SHA-256', u8Bytes);
        return new Uint8Array(buf);
    }
    return sha256BytesPure(u8Bytes);
}

async function solvePowChallenge(nonce, difficulty) {
    const prefix = '0'.repeat(difficulty);
    const enc = new TextEncoder();
    const hasSubtle = Boolean(window.crypto && window.crypto.subtle && typeof window.crypto.subtle.digest === 'function');
    for (let i = 0; i < 500000; i++) {
        const bytes = enc.encode(nonce + ':' + i);
        const dig = hasSubtle
            ? new Uint8Array(await window.crypto.subtle.digest('SHA-256', bytes))
            : sha256BytesPure(bytes);
        const hex = Array.from(dig).map(b => b.toString(16).padStart(2, '0')).join('');
        if (hex.startsWith(prefix)) {
            return String(i);
        }
    }
    return '0';
}

/* ---------------- WEB CRYPTO E2EE MODULE (ECDH P-256 + AES-256-GCM) ---------------- */
const E2EE = {
    dbPromise: null,
    openKeyDb() {
        if (this.dbPromise) return this.dbPromise;
        this.dbPromise = new Promise((resolve, reject) => {
            if (!window.indexedDB) return reject(new Error('IndexedDB unavailable'));
            const req = indexedDB.open('M3MessengerE2EE', 1);
            req.onupgradeneeded = e => { e.target.result.createObjectStore('keys'); };
            req.onsuccess = e => resolve(e.target.result);
            req.onerror = e => reject(e.target.error);
        });
        return this.dbPromise;
    },
    async getStoredKeyPair(userId) {
        const db = await this.openKeyDb();
        return new Promise((resolve, reject) => {
            const tx = db.transaction('keys', 'readonly');
            const req = tx.objectStore('keys').get('kp_' + userId);
            req.onsuccess = () => resolve(req.result || null);
            req.onerror = () => reject(req.error);
        });
    },
    async saveKeyPair(userId, kp) {
        const db = await this.openKeyDb();
        return new Promise((resolve, reject) => {
            const tx = db.transaction('keys', 'readwrite');
            const req = tx.objectStore('keys').put(kp, 'kp_' + userId);
            req.onsuccess = () => resolve(true);
            req.onerror = () => reject(req.error);
        });
    },
    async wipeLocalKeys() {
        try {
            const db = await this.openKeyDb();
            const tx = db.transaction('keys', 'readwrite');
            tx.objectStore('keys').clear();
        } catch (e) {}
    },
    _lastPeerRefreshByChat: {},
    canonicalPubString(jwk) {
        if (!jwk || typeof jwk !== 'object' || !jwk.x || !jwk.y) return '';
        return JSON.stringify({
            crv: jwk.crv || 'P-256',
            ext: true,
            key_ops: [],
            kty: jwk.kty || 'EC',
            x: String(jwk.x),
            y: String(jwk.y)
        });
    },
    samePubJwk(pubStrA, pubStrB) {
        if (!pubStrA || !pubStrB) return false;
        if (pubStrA === pubStrB) return true;
        try {
            const a = JSON.parse(pubStrA);
            const b = JSON.parse(pubStrB);
            return Boolean(a && b && a.x && a.y && a.x === b.x && a.y === b.y && (a.crv || 'P-256') === (b.crv || 'P-256'));
        } catch (e) {
            return false;
        }
    },
    clearDerivedCaches() {
        store.sharedKeys = {};
        if (store.decryptedTextCache) store.decryptedTextCache = {};
        if (store.decryptedBlobUrls) store.decryptedBlobUrls = {};
    },
    async syncWithPassword(rawPassword) {
        if (!rawPassword || !window.crypto || !window.crypto.subtle || !store.user) return false;
        try {
            const uid = store.user.id;
            const enc = new TextEncoder();
            const deriveWrapKey = async (saltBytes) => {
                const baseKey = await crypto.subtle.importKey('raw', enc.encode(String(rawPassword)), 'PBKDF2', false, ['deriveKey']);
                return crypto.subtle.deriveKey(
                    { name: 'PBKDF2', salt: saltBytes, iterations: 100000, hash: 'SHA-256' },
                    baseKey,
                    { name: 'AES-GCM', length: 256 },
                    false,
                    ['encrypt', 'decrypt']
                );
            };
            if (store.user.key_backup) {
                try {
                    const bk = JSON.parse(store.user.key_backup);
                    if (bk && bk.s && bk.iv && bk.ct) {
                        const salt = Uint8Array.from(atob(bk.s), c => c.charCodeAt(0));
                        const iv = Uint8Array.from(atob(bk.iv), c => c.charCodeAt(0));
                        const ct = Uint8Array.from(atob(bk.ct), c => c.charCodeAt(0));
                        const wk = await deriveWrapKey(salt);
                        const ptBuf = await crypto.subtle.decrypt({ name: 'AES-GCM', iv }, wk, ct);
                        const jwks = JSON.parse(new TextDecoder().decode(ptBuf));
                        if (jwks && jwks.priv && jwks.pub) {
                            const privKey = await crypto.subtle.importKey('jwk', jwks.priv, { name: 'ECDH', namedCurve: 'P-256' }, true, ['deriveKey', 'deriveBits']);
                            const pubKey = await crypto.subtle.importKey('jwk', jwks.pub, { name: 'ECDH', namedCurve: 'P-256' }, true, []);
                            await this.saveKeyPair(uid, { privateKey: privKey, publicKey: pubKey });
                            const exportedPub = await crypto.subtle.exportKey('jwk', pubKey);
                            const pubStr = this.canonicalPubString(exportedPub) || JSON.stringify(exportedPub);
                            if (!this.samePubJwk(store.user.pubkey, pubStr)) {
                                const upRes = await apiCall('profile_update', { pubkey: pubStr });
                                if (upRes.ok && upRes.data && upRes.data.user) store.user = upRes.data.user;
                                else store.user.pubkey = pubStr;
                            }
                            this.clearDerivedCaches();
                            return true;
                        }
                    }
                } catch (decErr) {}
            }
            let kp = await this.getStoredKeyPair(uid);
            let privJwk = null;
            let pubJwk = null;
            if (kp && kp.privateKey && kp.publicKey) {
                try {
                    privJwk = await crypto.subtle.exportKey('jwk', kp.privateKey);
                    pubJwk = await crypto.subtle.exportKey('jwk', kp.publicKey);
                } catch (expErr) {
                    privJwk = null;
                    pubJwk = null;
                }
            }
            if (!kp || !privJwk || !pubJwk) {
                kp = await crypto.subtle.generateKey({ name: 'ECDH', namedCurve: 'P-256' }, true, ['deriveKey', 'deriveBits']);
                await this.saveKeyPair(uid, kp);
                privJwk = await crypto.subtle.exportKey('jwk', kp.privateKey);
                pubJwk = await crypto.subtle.exportKey('jwk', kp.publicKey);
            }
            if (kp && privJwk && pubJwk) {
                const salt = crypto.getRandomValues(new Uint8Array(16));
                const iv = crypto.getRandomValues(new Uint8Array(12));
                const wk = await deriveWrapKey(salt);
                const payloadBytes = enc.encode(JSON.stringify({ priv: privJwk, pub: pubJwk }));
                const ctBuf = await crypto.subtle.encrypt({ name: 'AES-GCM', iv }, wk, payloadBytes);
                const backupJson = JSON.stringify({
                    v: 1,
                    s: btoa(String.fromCharCode(...salt)),
                    iv: btoa(String.fromCharCode(...iv)),
                    ct: btoa(String.fromCharCode(...new Uint8Array(ctBuf)))
                });
                const pubStr = this.canonicalPubString(pubJwk) || JSON.stringify(pubJwk);
                const res = await apiCall('profile_update', { pubkey: pubStr, key_backup: backupJson });
                if (res.ok && res.data && res.data.user) store.user = res.data.user;
                else {
                    store.user.pubkey = pubStr;
                    store.user.key_backup = backupJson;
                }
                this.clearDerivedCaches();
                return true;
            }
        } catch (e) {}
        return false;
    },
    async ensureIdentityKeys(opts = {}) {
        if (!window.crypto || !window.crypto.subtle || !store.user) return false;
        try {
            const uid = store.user.id;
            let kp = await this.getStoredKeyPair(uid);
            if (!kp || !kp.privateKey || !kp.publicKey) {
                if (opts.waitForPasswordSync && store.user.pubkey && store.user.key_backup) return false;
                kp = await crypto.subtle.generateKey(
                    { name: 'ECDH', namedCurve: 'P-256' },
                    true,
                    ['deriveKey', 'deriveBits']
                );
                await this.saveKeyPair(uid, kp);
                this.clearDerivedCaches();
            }
            const pubJwk = await crypto.subtle.exportKey('jwk', kp.publicKey);
            const pubStr = this.canonicalPubString(pubJwk) || JSON.stringify(pubJwk);
            if (!store.user.pubkey || !this.samePubJwk(store.user.pubkey, pubStr) || opts.forcePublish) {
                const res = await apiCall('profile_update', { pubkey: pubStr });
                if (res.ok && res.data && res.data.user) {
                    store.user = res.data.user;
                } else {
                    store.user.pubkey = pubStr;
                }
                this.clearDerivedCaches();
            }
            return true;
        } catch (e) {
            return false;
        }
    },
    async reSyncKeysForChat(chatId = 0) {
        this.clearDerivedCaches();
        await this.ensureIdentityKeys({ forcePublish: true });
        const bootRes = await apiCall('bootstrap');
        if (bootRes.ok && bootRes.data) {
            if (bootRes.data.user) store.user = bootRes.data.user;
            if (Array.isArray(bootRes.data.chats)) store.chats = bootRes.data.chats;
        }
        if (chatId && Number(store.activeChatId) === Number(chatId)) {
            await selectChat(Number(chatId), { preserveScrollBottom: true });
        }
        return true;
    },
    async deriveChatKey(chat) {
        if (!chat || !store.user) return null;
        const liveChat = (Array.isArray(store.chats) && store.chats.find(c => Number(c.id) === Number(chat.id))) || chat;
        const peerPubRaw = (liveChat && liveChat.peer && liveChat.peer.pubkey) ? String(liveChat.peer.pubkey) : ((chat.peer && chat.peer.pubkey) ? String(chat.peer.pubkey) : '');
        if (!peerPubRaw) return null;
        try {
            const uid = store.user.id;
            let kp = await this.getStoredKeyPair(uid);
            if (!kp || !kp.privateKey || !kp.publicKey) {
                await this.ensureIdentityKeys();
                kp = await this.getStoredKeyPair(uid);
            }
            if (!kp || !kp.privateKey || !kp.publicKey) return null;
            const myExportedPub = await crypto.subtle.exportKey('jwk', kp.publicKey);
            const myPubCanon = this.canonicalPubString(myExportedPub) || JSON.stringify(myExportedPub);
            if (!this.samePubJwk(store.user.pubkey, myPubCanon)) {
                const upRes = await apiCall('profile_update', { pubkey: myPubCanon });
                if (upRes.ok && upRes.data && upRes.data.user) store.user = upRes.data.user;
                else store.user.pubkey = myPubCanon;
            }
            const peerJwk = JSON.parse(peerPubRaw);
            const peerPubCanon = this.canonicalPubString(peerJwk) || peerPubRaw;
            const cacheKey = String(liveChat.id) + '|' + myPubCanon + '|' + peerPubCanon;
            if (store.sharedKeys[cacheKey]) return store.sharedKeys[cacheKey];
            const peerPub = await crypto.subtle.importKey('jwk', peerJwk, { name: 'ECDH', namedCurve: 'P-256' }, true, []);
            const aesKey = await crypto.subtle.deriveKey(
                { name: 'ECDH', public: peerPub },
                kp.privateKey,
                { name: 'AES-GCM', length: 256 },
                false,
                ['encrypt', 'decrypt']
            );
            store.sharedKeys[cacheKey] = aesKey;
            return aesKey;
        } catch (e) {
            return null;
        }
    },
    async encryptText(chat, plainText) {
        const key = await this.deriveChatKey(chat);
        if (!key) throw new Error(t('e2ee_key_not_ready'));
        const iv = crypto.getRandomValues(new Uint8Array(12));
        const encoded = new TextEncoder().encode(plainText);
        const cipherBuf = await crypto.subtle.encrypt({ name: 'AES-GCM', iv }, key, encoded);
        return {
            cipher: btoa(String.fromCharCode(...new Uint8Array(cipherBuf))),
            iv: btoa(String.fromCharCode(...iv))
        };
    },
    async decryptText(chat, cipherB64, ivB64) {
        if (!cipherB64 || !ivB64) return t('e2ee_encrypted_preview');
        let key = await this.deriveChatKey(chat);
        if (!key) return t('e2ee_waiting_key');
        let cipherBytes, ivBytes;
        try {
            cipherBytes = Uint8Array.from(atob(String(cipherB64).trim()), c => c.charCodeAt(0));
            ivBytes = Uint8Array.from(atob(String(ivB64).trim()), c => c.charCodeAt(0));
        } catch (b64Err) {
            return t('e2ee_decrypt_err');
        }
        try {
            const plainBuf = await crypto.subtle.decrypt({ name: 'AES-GCM', iv: ivBytes }, key, cipherBytes);
            return new TextDecoder().decode(plainBuf);
        } catch (e) {
            const cid = Number((chat && chat.id) || 0);
            const nowMs = Date.now();
            if (cid > 0 && (!this._lastPeerRefreshByChat[cid] || (nowMs - this._lastPeerRefreshByChat[cid]) > 8000)) {
                this._lastPeerRefreshByChat[cid] = nowMs;
                try {
                    const br = await apiCall('bootstrap');
                    if (br.ok && br.data && Array.isArray(br.data.chats)) {
                        store.chats = br.data.chats;
                        const updatedChat = store.chats.find(c => Number(c.id) === cid) || chat;
                        key = await this.deriveChatKey(updatedChat);
                        if (key) {
                            const retryBuf = await crypto.subtle.decrypt({ name: 'AES-GCM', iv: ivBytes }, key, cipherBytes);
                            return new TextDecoder().decode(retryBuf);
                        }
                    }
                } catch (retryErr) {}
            }
            return t('e2ee_decrypt_err');
        }
    },
    async encryptBlob(chat, fileOrBlob) {
        const key = await this.deriveChatKey(chat);
        if (!key) throw new Error(t('e2ee_key_not_ready'));
        const iv = crypto.getRandomValues(new Uint8Array(12));
        const plainBuf = await fileOrBlob.arrayBuffer();
        const cipherBuf = await crypto.subtle.encrypt({ name: 'AES-GCM', iv }, key, plainBuf);
        return {
            blob: new Blob([cipherBuf], { type: 'application/octet-stream' }),
            iv: btoa(String.fromCharCode(...iv))
        };
    },
    async decryptFileToObjectUrl(chat, fileObj, mimeHint = '') {
        if (!fileObj || !fileObj.id) return null;
        if (store.decryptedBlobUrls && store.decryptedBlobUrls[fileObj.id]) {
            return store.decryptedBlobUrls[fileObj.id];
        }
        if (!chat || !fileObj.file_iv) return null;
        const key = await this.deriveChatKey(chat);
        if (!key) return null;
        try {
            const res = await fetch(fileObj.url, { credentials: 'same-origin' });
            if (!res.ok) return null;
            const cipherBuf = await res.arrayBuffer();
            const ivBytes = Uint8Array.from(atob(fileObj.file_iv), c => c.charCodeAt(0));
            const plainBuf = await crypto.subtle.decrypt({ name: 'AES-GCM', iv: ivBytes }, key, cipherBuf);
            let outMime = mimeHint || '';
            if (!outMime) {
                const fn = String(fileObj.display_name || '').toLowerCase();
                if (/\.(png)$/i.test(fn)) outMime = 'image/png';
                else if (/\.(jpe?g)$/i.test(fn)) outMime = 'image/jpeg';
                else if (/\.(gif)$/i.test(fn)) outMime = 'image/gif';
                else if (/\.(webp)$/i.test(fn)) outMime = 'image/webp';
                else if (/\.(mp4)$/i.test(fn)) outMime = 'video/mp4';
                else if (/\.(webm)$/i.test(fn)) outMime = 'audio/webm';
                else if (/\.(ogg|opus)$/i.test(fn)) outMime = 'audio/ogg';
                else if (/\.(mp3)$/i.test(fn)) outMime = 'audio/mpeg';
                else if (/\.(m4a|aac)$/i.test(fn)) outMime = 'audio/mp4';
                else if (/\.(wav)$/i.test(fn)) outMime = 'audio/wav';
                else if (/\.(pdf)$/i.test(fn)) outMime = 'application/pdf';
                else if (/\.(txt|log|md|csv|json)$/i.test(fn)) outMime = 'text/plain;charset=utf-8';
                else outMime = 'application/octet-stream';
            }
            const blob = new Blob([plainBuf], { type: outMime });
            const blobUrl = URL.createObjectURL(blob);
            const entry = {
                blobUrl,
                text: outMime.startsWith('text/') ? new TextDecoder().decode(plainBuf) : null
            };
            store.decryptedBlobUrls[fileObj.id] = entry;
            return entry;
        } catch (e) {
            return null;
        }
    },
    async safetyFingerprint(chat) {
        if (!store.user || !store.user.pubkey || !chat.peer || !chat.peer.pubkey) {
            return t('e2ee_waiting_exchange');
        }
        const pair = [store.user.pubkey, chat.peer.pubkey].sort().join('|');
        const digest = await sha256BytesCompat(new TextEncoder().encode(pair));
        const bytes = Array.from(digest).slice(0, 16);
        return bytes.map(b => b.toString(16).padStart(2, '0').toUpperCase()).join(' ');
    }
};

function upsertChatMessage(chatId, msg) {
    if (!chatId || !msg || !msg.id) return;
    if (!store.messages[chatId]) store.messages[chatId] = [];
    const list = store.messages[chatId];
    const existingIdx = list.findIndex(m => Number(m.id) === Number(msg.id));
    if (existingIdx !== -1) {
        list[existingIdx] = msg;
    } else {
        list.push(msg);
        list.sort((a, b) => Number(a.id) - Number(b.id));
    }
}

function resizeImageToDataUrl(file, maxDim = 128, quality = 0.82, preserveAlpha = false) {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = e => {
            const img = new Image();
            img.onload = () => {
                let w = img.width || maxDim, h = img.height || maxDim;
                if (w > maxDim || h > maxDim) {
                    if (w > h) { h = Math.max(1, Math.round((h * maxDim) / w)); w = maxDim; }
                    else { w = Math.max(1, Math.round((w * maxDim) / h)); h = maxDim; }
                }
                const canvas = document.createElement('canvas');
                canvas.width = w;
                canvas.height = h;
                const ctx = canvas.getContext('2d');
                ctx.clearRect(0, 0, w, h);
                ctx.drawImage(img, 0, 0, w, h);
                const keepPng = preserveAlpha && file && /image\/(png|webp|gif|svg|x-icon|vnd\.microsoft\.icon)/i.test(file.type || '');
                resolve(keepPng ? canvas.toDataURL('image/png') : canvas.toDataURL('image/jpeg', quality));
            };
            img.onerror = reject;
            img.src = e.target.result;
        };
        reader.onerror = reject;
        reader.readAsDataURL(file);
    });
}

/* ---------------- MODAL HELPER ---------------- */
function isDialogBackdropHit(dlg, ev) {
    if (!dlg || ev.target !== dlg) return false;
    let cx = null, cy = null;
    if (ev.touches && ev.touches.length > 0) {
        cx = ev.touches[0].clientX;
        cy = ev.touches[0].clientY;
    } else if (ev.changedTouches && ev.changedTouches.length > 0) {
        cx = ev.changedTouches[0].clientX;
        cy = ev.changedTouches[0].clientY;
    } else if (typeof ev.clientX === 'number' && typeof ev.clientY === 'number') {
        if (ev.clientX === 0 && ev.clientY === 0 && ev.detail === 0) return false;
        cx = ev.clientX;
        cy = ev.clientY;
    }
    if (cx === null || cy === null) return false;
    const rect = dlg.getBoundingClientRect();
    if (rect.width === 0 && rect.height === 0) return false;
    return (cx < rect.left || cx > rect.right || cy < rect.top || cy > rect.bottom);
}

function bindAppModalBackdropDismiss(dlg) {
    if (!dlg || dlg._backdropDismissBound) return;
    dlg._backdropDismissBound = true;
    let startedOnBackdrop = false;
    const onDown = ev => {
        const confirmDlg = document.getElementById('confirm-modal');
        if (confirmDlg && confirmDlg.open) {
            startedOnBackdrop = false;
            return;
        }
        startedOnBackdrop = isDialogBackdropHit(dlg, ev);
    };
    dlg.addEventListener('mousedown', onDown);
    dlg.addEventListener('touchstart', onDown, { passive: true });
    dlg.addEventListener('click', ev => {
        if (!dlg.open) {
            startedOnBackdrop = false;
            return;
        }
        const confirmDlg = document.getElementById('confirm-modal');
        if (confirmDlg && confirmDlg.open) {
            startedOnBackdrop = false;
            return;
        }
        if (dlg._openedAt && (Date.now() - dlg._openedAt) < 340) {
            startedOnBackdrop = false;
            return;
        }
        if (startedOnBackdrop && isDialogBackdropHit(dlg, ev)) {
            startedOnBackdrop = false;
            dlg.close();
            return;
        }
        startedOnBackdrop = false;
    });
}

function bindMobileSheetPullToClose(dlg, bodyEl) {
    if (!dlg || dlg._sheetPullBound) return;
    dlg._sheetPullBound = true;
    let pullState = null;

    const resetTransform = (animate) => {
        dlg.style.transition = animate ? 'transform 0.2s cubic-bezier(0.22, 1, 0.36, 1)' : '';
        dlg.style.transform = '';
        if (animate) {
            setTimeout(() => {
                if (dlg && !pullState) dlg.style.transition = '';
            }, 220);
        }
    };

    dlg.addEventListener('touchstart', ev => {
        if (!dlg.open || window.innerWidth > 780 || dlg.id === 'sub-modal' || dlg.classList.contains('confirm-dialog') || dlg.classList.contains('modal-compact-menu') || dlg.classList.contains('modal-centered-mobile')) return;
        const confirmDlg = document.getElementById('confirm-modal');
        if (confirmDlg && confirmDlg.open) return;
        if (!ev.touches || ev.touches.length !== 1) return;
        const t0 = ev.touches[0];
        if (isDialogBackdropHit(dlg, ev)) return;
        const target = ev.target;
        const inHead = Boolean(target && target.closest('.modal-head, .modal-sheet-grabber'));
        if (!inHead && target && target.closest('input, textarea, select, [contenteditable="true"], canvas')) return;
        const scroller = bodyEl || dlg.querySelector('.modal-body');
        let nestedScrollTop = 0;
        if (!inHead && target && scroller) {
            let cur = target;
            while (cur && cur !== dlg) {
                if (cur.scrollHeight > cur.clientHeight + 2 && cur.scrollTop > 2) {
                    nestedScrollTop = cur.scrollTop;
                    break;
                }
                cur = cur.parentElement;
            }
        }
        const atTop = inHead || ((!scroller || scroller.scrollTop <= 2) && nestedScrollTop <= 2);
        if (!atTop) return;

        pullState = {
            startX: t0.clientX,
            startY: t0.clientY,
            dy: 0,
            dragging: false,
            inHead
        };
    }, { passive: true });

    dlg.addEventListener('touchmove', ev => {
        if (!pullState || !ev.touches || ev.touches.length !== 1) return;
        const t0 = ev.touches[0];
        const dx = t0.clientX - pullState.startX;
        const dy = t0.clientY - pullState.startY;
        const scroller = bodyEl || dlg.querySelector('.modal-body');

        if (!pullState.dragging) {
            if (dy < -6 || Math.abs(dx) > Math.abs(dy) * 1.15) {
                pullState = null;
                return;
            }
            if (!pullState.inHead && scroller && scroller.scrollTop > 2) {
                pullState = null;
                return;
            }
            if (dy > 10) {
                pullState.dragging = true;
                dlg.style.transition = 'none';
            } else {
                return;
            }
        }

        if (pullState.dragging) {
            if (ev.cancelable) ev.preventDefault();
            pullState.dy = Math.max(0, dy);
            dlg.style.transform = `translateY(${Math.round(pullState.dy * 0.88)}px)`;
        }
    }, { passive: false });

    const finishPull = () => {
        if (!pullState) return;
        const st = pullState;
        pullState = null;
        if (!st.dragging) return;
        const sheetH = dlg.getBoundingClientRect().height || 360;
        const threshold = Math.min(115, Math.max(68, sheetH * 0.2));
        if (st.dy >= threshold) {
            dlg.style.transition = 'transform 0.16s ease-in';
            dlg.style.transform = 'translateY(100%)';
            setTimeout(() => {
                dlg.style.transition = '';
                dlg.style.transform = '';
                if (dlg.open) dlg.close();
            }, 150);
        } else {
            resetTransform(true);
        }
    };

    dlg.addEventListener('touchend', finishPull, { passive: true });
    dlg.addEventListener('touchcancel', () => {
        if (pullState && pullState.dragging) resetTransform(true);
        pullState = null;
    }, { passive: true });
}

function openModal(title, renderFn, large = false, compact = false, centerMobile = false) {
    const dlg = document.getElementById('app-modal');
    const titleEl = document.getElementById('app-modal-title');
    const bodyEl = document.getElementById('app-modal-body');
    const mainC = document.getElementById('toast-container');
    const modalC = document.getElementById('modal-toast-container');
    if (!dlg || !titleEl || !bodyEl) return;

    bindAppModalBackdropDismiss(dlg);
    bindMobileSheetPullToClose(dlg, bodyEl);

    if (!dlg._toastCloseBound) {
        dlg._toastCloseBound = true;
        dlg.addEventListener('close', () => {
            if (modalC && mainC) {
                while (modalC.firstChild) {
                    mainC.appendChild(modalC.firstChild);
                }
            }
        });
    }

    const wasAlreadyOpen = !!dlg.open;
    const prevScrollTop = wasAlreadyOpen ? bodyEl.scrollTop : 0;
    const renderSeq = (dlg._renderSeq || 0) + 1;
    dlg._renderSeq = renderSeq;

    dlg.classList.toggle('modal-lg', !!large && !compact);
    dlg.classList.toggle('modal-compact-menu', !!compact);
    dlg.classList.toggle('modal-centered-mobile', !!centerMobile);
    dlg.style.transform = '';
    dlg.style.transition = '';
    if (!wasAlreadyOpen) {
        dlg._openedAt = Date.now();
        titleEl.textContent = title;
        bodyEl.innerHTML = '';
        renderFn(bodyEl, () => dlg.close());
        dlg.showModal();
        if (mainC && mainC.children.length > 0) promoteToastContainerToTopLayer();
    } else {
        const stagingBody = document.createElement('div');
        Promise.resolve(renderFn(stagingBody, () => dlg.close())).then(() => {
            if (dlg._renderSeq !== renderSeq || !dlg.open) return;
            titleEl.textContent = title;
            bodyEl.replaceChildren(...stagingBody.childNodes);
            bodyEl.scrollTop = prevScrollTop;
            if (mainC && mainC.children.length > 0) promoteToastContainerToTopLayer();
        }).catch(() => {});
    }
}

function openSubModal(title, renderFn) {
    const dlg = document.getElementById('sub-modal');
    const titleEl = document.getElementById('sub-modal-title');
    const bodyEl = document.getElementById('sub-modal-body');
    const closeBtn = document.getElementById('sub-modal-close');
    const mainC = document.getElementById('toast-container');
    if (!dlg || !titleEl || !bodyEl) return;

    bindAppModalBackdropDismiss(dlg);
    bindMobileSheetPullToClose(dlg, bodyEl);
    if (closeBtn && !closeBtn._subBound) {
        closeBtn._subBound = true;
        closeBtn.addEventListener('click', () => dlg.close());
    }
    dlg._openedAt = Date.now();
    titleEl.textContent = title;
    bodyEl.innerHTML = '';
    renderFn(bodyEl, () => dlg.close());
    if (!dlg.open) dlg.showModal();
    if (mainC && mainC.children.length > 0) {
        promoteToastContainerToTopLayer();
    }
}

function getChatInheritedTtlSec() {
    const chat = typeof getActiveChat === 'function' ? getActiveChat() : null;
    if (chat && Number(chat.default_ttl) > 0) return Number(chat.default_ttl);
    if (store.settings && Number(store.settings.default_ttl) > 0) return Number(store.settings.default_ttl);
    return 0;
}

function formatTtlSecShort(sec) {
    const s = Number(sec || 0);
    if (s <= 0) return '';
    const match = TTL_OPTIONS.find(o => o.val === s);
    if (match) return match.shortKey ? t(match.shortKey) : match.label;
    if (s < 60) return s + 's';
    if (s < 3600) return Math.round(s / 60) + 'm';
    if (s < 86400) return Math.round(s / 3600) + 'h';
    return Math.round(s / 86400) + 'd';
}

function getEffectiveComposerTtlPayload() {
    const cur = TTL_OPTIONS[store.ttlIndex] || TTL_OPTIONS[0];
    if (cur.val > 0) return cur.val;
    if (store.ttlExplicitOff) return 0;
    return -1;
}

function syncTtlControlUI() {
    const cur = TTL_OPTIONS[store.ttlIndex] || TTL_OPTIONS[0];
    const inheritedSec = getChatInheritedTtlSec();
    const effectiveActive = cur.val > 0 || (!store.ttlExplicitOff && inheritedSec > 0);
    const grp = document.getElementById('ttl-pill-group');
    const btnCycle = document.getElementById('btn-ttl-cycle');
    const btnCancel = document.getElementById('btn-ttl-cancel');
    if (grp) grp.classList.toggle('active', effectiveActive);
    if (btnCycle) {
        let shortTxt = '';
        if (cur.val > 0) {
            shortTxt = cur.shortKey ? t(cur.shortKey) : cur.label;
        } else if (!store.ttlExplicitOff && inheritedSec > 0) {
            shortTxt = formatTtlSecShort(inheritedSec);
        }
        btnCycle.innerHTML = HDR_SVG.clock;
        if (shortTxt) {
            const lblSpan = document.createElement('span');
            lblSpan.textContent = formatLocalizedCount(shortTxt);
            btnCycle.appendChild(lblSpan);
        }
        btnCycle.classList.toggle('active', effectiveActive);
        btnCycle.title = t('ttl_menu_title');
    }
    if (btnCancel) {
        btnCancel.classList.toggle('hidden', !effectiveActive);
        btnCancel.title = t('ttl_cancel_tip');
    }
}

function formatCoarseRemainingTtl(remSec) {
    const s = Math.max(0, Math.floor(Number(remSec) || 0));
    if (s <= 59) {
        return `${formatLocalizedCount(s)} ${t('ttl_unit_sec')}`;
    }
    if (s < 3600) {
        return `${formatLocalizedCount(Math.floor(s / 60))} ${t('ttl_unit_min')}`;
    }
    if (s < 86400) {
        return `${formatLocalizedCount(Math.floor(s / 3600))} ${t('ttl_unit_hour')}`;
    }
    return `${formatLocalizedCount(Math.floor(s / 86400))} ${t('ttl_unit_day')}`;
}

function resetComposerTtlAfterSend() {
    if (store.ttlIndex !== 0 || store.ttlExplicitOff) {
        store.ttlIndex = 0;
        store.ttlExplicitOff = false;
        syncTtlControlUI();
    }
}

function setComposerTtl(idx, showFeedback = true) {
    store.ttlIndex = (idx >= 0 && idx < TTL_OPTIONS.length) ? idx : 0;
    store.ttlExplicitOff = (store.ttlIndex === 0);
    syncTtlControlUI();
    const pop = document.getElementById('ttl-popover');
    if (pop) pop.classList.add('hidden');
    if (showFeedback) {
        const cur = TTL_OPTIONS[store.ttlIndex];
        if (cur.val <= 0) {
            toast(t('ttl_off_toast'));
        } else {
            toast(t('ttl_on_toast') + (cur.shortKey ? t(cur.shortKey) : cur.label));
        }
    }
}

function renderTtlPopoverMenu() {
    const pop = document.getElementById('ttl-popover');
    if (!pop) return;
    pop.innerHTML = '';

    const head = document.createElement('div');
    head.className = 'ttl-popover-head';
    head.textContent = t('ttl_menu_title');
    pop.appendChild(head);

    TTL_OPTIONS.forEach((opt, idx) => {
        const b = document.createElement('button');
        b.type = 'button';
        const isSelected = store.ttlIndex === idx;
        b.className = 'ttl-opt-btn' + (opt.val === 0 ? ' off-opt' : '') + (isSelected ? ' selected' : '');
        const lbl = document.createElement('span');
        lbl.textContent = t(opt.i18nKey);
        const chk = document.createElement('span');
        chk.textContent = isSelected ? '✓' : '';
        b.appendChild(lbl);
        b.appendChild(chk);
        b.addEventListener('click', e => {
            e.stopPropagation();
            setComposerTtl(idx, true);
        });
        pop.appendChild(b);
    });
}

/* ---------------- SELF PROFILE DOCK & CHAT LIST RENDERING ---------------- */

/* ---------------- GLOBAL & PER-CHAT IDLE TIME EVALUATION ENGINE ---------------- */
function normalizeHhMm(val, fallback = '23:00') {
    const s = String(val == null ? '' : val).trim();
    const m = s.match(/^(\d{1,2}):(\d{1,2})$/);
    if (m) {
        const hh = Math.max(0, Math.min(23, parseInt(m[1], 10)));
        const mm = Math.max(0, Math.min(59, parseInt(m[2], 10)));
        return String(hh).padStart(2, '0') + ':' + String(mm).padStart(2, '0');
    }
    if (/^\d{1,2}$/.test(s)) {
        const hh = Math.max(0, Math.min(23, parseInt(s, 10)));
        return String(hh).padStart(2, '0') + ':00';
    }
    return fallback;
}

function evaluateIdleWindowJS(mode, startStr, endStr, tzOffsetMin = 0) {
    const m = ['off', 'manual', 'auto'].includes(mode) ? mode : 'off';
    const start = normalizeHhMm(startStr, '23:00');
    const end = normalizeHhMm(endStr, '07:00');
    const tzOff = Number.isFinite(Number(tzOffsetMin)) ? Number(tzOffsetMin) : 0;

    if (m === 'manual') {
        return { mode: 'manual', active: true, start, end, tz_offset: tzOff };
    }
    if (m !== 'auto') {
        return { mode: 'off', active: false, start, end, tz_offset: tzOff };
    }

    const [sh, sm] = start.split(':').map(Number);
    const [eh, em] = end.split(':').map(Number);
    const startMins = sh * 60 + sm;
    const endMins = eh * 60 + em;

    const nowUtcMs = Date.now();
    const targetDate = new Date(nowUtcMs + tzOff * 60000);
    const curMins = targetDate.getUTCHours() * 60 + targetDate.getUTCMinutes();

    let active = false;
    if (startMins === endMins) {
        active = true;
    } else if (startMins < endMins) {
        active = (curMins >= startMins && curMins < endMins);
    } else {
        active = (curMins >= startMins || curMins < endMins);
    }
    return { mode: 'auto', active, start, end, tz_offset: tzOff };
}

function getGlobalIdleStatus() {
    const s = store.settings || {};
    return evaluateIdleWindowJS(s.idle_mode || 'off', s.idle_start || '23:00', s.idle_end || '07:00', s.idle_tz_offset ?? 0);
}

function getChatIdleStatus(chat) {
    if (!chat || (chat.type !== 'group' && chat.type !== 'channel')) {
        return { mode: 'off', active: false, start: '23:00', end: '07:00', tz_offset: 0 };
    }
    const p = chat.perms || {};
    const mode = chat.idle_mode || p.idle_mode || 'off';
    const start = chat.idle_start || p.idle_start || '23:00';
    const end = chat.idle_end || p.idle_end || '07:00';
    const tz = (chat.idle_tz_offset !== undefined) ? chat.idle_tz_offset : (p.idle_tz_offset ?? 0);
    return evaluateIdleWindowJS(mode, start, end, tz);
}

function renderGlobalIdleBanner() {
    const banner = document.getElementById('global-idle-banner');
    if (!banner) return;
    if (!store.user) {
        banner.classList.add('hidden');
        return;
    }
    const gIdle = getGlobalIdleStatus();
    if (!gIdle.active) {
        banner.classList.add('hidden');
        banner.innerHTML = '';
        return;
    }
    banner.innerHTML = '';
    const txt = document.createElement('span');
    txt.textContent = gIdle.mode === 'auto'
        ? t('idle_global_banner_auto').replace('{start}', gIdle.start).replace('{end}', gIdle.end)
        : t('idle_global_banner_manual');
    banner.appendChild(txt);

    if (store.user.role === 'superadmin') {
        const manageBtn = document.createElement('button');
        manageBtn.type = 'button';
        manageBtn.className = 'idle-manage-btn';
        manageBtn.textContent = t('idle_manage_short_btn');
        manageBtn.addEventListener('click', () => {
            if (typeof openAdminPanelModal === 'function') openAdminPanelModal('settings');
        });
        banner.appendChild(manageBtn);
    }
    banner.classList.remove('hidden');
}

function renderSelfDock() {
    if (!store.user) return;
    const av = document.getElementById('self-dock-avatar');
    const nm = document.getElementById('self-dock-name');
    const sb = document.getElementById('self-dock-sub');
    if (av) renderAvatarNode(av, store.user.name, store.user.avatar);
    if (nm) {
        nm.innerHTML = '';
        const s = document.createElement('span');
        s.className = 'user-self-name-text';
        s.textContent = store.user.name;
        nm.appendChild(s);
        if (store.user.has_admin_badge) {
            nm.appendChild(createAdminBadgeNode());
        }
    }
    if (sb) {
        sb.innerHTML = '';
        if (store.user.no_username || !store.user.username) {
            sb.textContent = t('no_username_badge');
        } else {
            const bdi = document.createElement('bdi');
            bdi.setAttribute('dir', 'ltr');
            bdi.textContent = '@' + store.user.username;
            sb.appendChild(bdi);
        }
        if (store.user.user_ghost_mode === 1) {
            const gp = document.createElement('span');
            gp.className = 'user-ghost-pill';
            gp.style.marginInlineStart = '6px';
            gp.textContent = t('user_ghost_active_badge');
            sb.appendChild(gp);
        }
    }
    const admBtn = document.getElementById('btn-admin-panel');
    if (admBtn) {
        admBtn.classList.toggle('hidden', store.user.role !== 'superadmin');
    }
}

function formatPeerPresenceText(peer) {
    if (!peer) return '';
    if (peer.last_seen_mode === 'ghost') return '';
    const forceHidden = !!(store.settings && Number(store.settings.force_hide_last_seen) === 1 && !(store.user && store.user.role === 'superadmin'));
    if (peer.online && !forceHidden) return '● ' + t('online');
    if (forceHidden || peer.last_seen_mode === 'recently' || peer.last_seen_mode === 'hidden' || !peer.last_seen_bucket) {
        return t('last_seen_prefix') + t('last_seen_recently');
    }
    return t('last_seen_prefix') + formatDate(peer.last_seen_bucket);
}

function buildPeerPresenceNode(peer) {
    if (!peer || peer.last_seen_mode === 'ghost') return null;
    const forceHidden = !!(store.settings && Number(store.settings.force_hide_last_seen) === 1 && !(store.user && store.user.role === 'superadmin'));
    if (peer.online && !forceHidden) {
        const wrap = document.createElement('span');
        wrap.className = 'hdr-online-status';
        const dot = document.createElement('span');
        dot.className = 'hdr-online-dot';
        const txt = document.createElement('span');
        txt.textContent = t('online');
        wrap.appendChild(dot);
        wrap.appendChild(txt);
        return wrap;
    }
    const txt = formatPeerPresenceText(peer);
    return txt ? document.createTextNode(txt) : null;
}

function getActiveChat() {
    const joined = store.chats.find(c => c.id === store.activeChatId);
    if (joined) return joined;
    if (store.ghostChat && store.ghostChat.id === store.activeChatId) return store.ghostChat;
    return null;
}

async function enterChatAsGhost(chatId) {
    const r = await apiCall('admin_ghost_open', { chat_id: chatId });
    if (!r.ok || !r.data || !r.data.chat) {
        toast(r.message || t('err_generic'), true);
        return false;
    }
    const c = r.data.chat;
    if (c.is_ghost) {
        store.ghostChat = c;
    } else {
        store.ghostChat = null;
        const cRes = await apiCall('chats_list');
        if (cRes.ok) store.chats = cRes.data.chats;
    }
    await selectChat(c.id);
    if (c.is_ghost) {
        toast(t('ghost_entered_toast') + formatChatTitle(c));
    }
    return true;
}

async function joinGhostChatNormally(chatId) {
    const r = await apiCall('chat_join', { chat_id: chatId });
    if (!r.ok) {
        toast(r.message || t('err_generic'), true);
        return false;
    }
    store.ghostChat = null;
    store.chats = r.data.chats || store.chats;
    renderChatList();
    await selectChat(chatId);
    toast(t('ghost_joined_normal_toast'));
    return true;
}

async function switchChatToGhostMode(chatId, titleTxt) {
    const lr = await apiCall('chat_leave', { chat_id: chatId });
    if (!lr.ok) {
        toast(lr.message || t('err_generic'), true);
        return false;
    }
    store.chats = lr.data.chats || [];
    const gr = await apiCall('admin_ghost_open', { chat_id: chatId });
    if (gr.ok && gr.data && gr.data.chat) {
        store.ghostChat = gr.data.chat;
        renderChatList();
        await selectChat(chatId);
        toast(t('ghost_switched_toast') + (titleTxt || formatChatTitle(gr.data.chat)));
        return true;
    }
    renderChatList();
    return false;
}

/* Show the "pick a conversation" placeholder instead of jumping to whatever
   chat happens to be first in the list. Used whenever the chat being viewed
   stops being available (deleted, left, declined) and on a fresh load. */
function showNoChatSelected() {
    store.activeChatId = null;
    const view = document.getElementById('active-chat-view');
    const empty = document.getElementById('empty-chat-state');
    const shell = document.getElementById('messenger-shell');
    if (view) view.classList.add('hidden');
    if (empty) empty.classList.remove('hidden');
    if (shell) shell.classList.remove('chat-open');
    renderChatList();
}

function exitGhostChatView() {
    store.ghostChat = null;
    showNoChatSelected();
}

/* ---------------- UNIVERSAL ALL-APP POPUP MEDIA & TEXT PLAYER ---------------- */
// One design language for both media players: the same monochrome glyphs and the
// same speed ladder, so the audio and video controls never drift apart.
// Glyphs marked m3-ico-solid are filled shapes (play, pause, the speaker cone);
// everything else is a stroked outline. Without the marker the shared "fill: none"
// rule hollows them out into faint wireframes.
const MEDIA_ICON = {
    play:   '<svg viewBox="0 0 24 24" class="m3-ico-solid"><polygon points="8,5 19,12 8,19"/></svg>',
    pause:  '<svg viewBox="0 0 24 24" class="m3-ico-solid"><rect x="7" y="5" width="3.6" height="14" rx="1"/><rect x="13.4" y="5" width="3.6" height="14" rx="1"/></svg>',
    volOn:  '<svg viewBox="0 0 24 24"><polygon class="m3-ico-solid" points="11 5 6 9 2.5 9 2.5 15 6 15 11 19 11 5"/><path d="M15.54 8.46a5 5 0 0 1 0 7.07"/><path d="M19.07 4.93a10 10 0 0 1 0 14.14"/></svg>',
    volOff: '<svg viewBox="0 0 24 24"><polygon class="m3-ico-solid" points="11 5 6 9 2.5 9 2.5 15 6 15 11 19 11 5"/><line x1="23" y1="9" x2="17" y2="15"/><line x1="17" y1="9" x2="23" y2="15"/></svg>'
};
const MEDIA_PLAYBACK_RATES = [0.5, 0.75, 1, 1.25, 1.5, 2];
function nextPlaybackRate(cur) {
    const c = Number(cur) || 1;
    const idx = MEDIA_PLAYBACK_RATES.findIndex(r => Math.abs(r - c) < 0.02);
    return MEDIA_PLAYBACK_RATES[(idx + 1) % MEDIA_PLAYBACK_RATES.length];
}

function readMediaDuration(mediaEl) {
    if (!mediaEl) return 0;
    if (Number.isFinite(mediaEl.duration) && mediaEl.duration > 0) return mediaEl.duration;
    // MediaRecorder WebM (instant video notes and voice notes) carries no Duration
    // element, so browsers keep reporting duration = Infinity even once the whole
    // clip has buffered. The end of the seekable range is the real end of the stream,
    // so fall back to it instead of showing a dead "--:--" clock and a frozen bar.
    try {
        const sk = mediaEl.seekable;
        if (sk && sk.length > 0) {
            const end = sk.end(sk.length - 1);
            if (Number.isFinite(end) && end > 0) return end;
        }
    } catch (e) {}
    return 0;
}

function seekMediaSafely(mediaEl, targetTime) {
    if (!mediaEl || !Number.isFinite(targetTime) || targetTime <= 0) return;
    let settled = false;
    const applySeek = () => {
        if (settled) return;
        // A stream whose duration is unknown or unbounded (MediaRecorder WebM:
        // duration = Infinity) must never be seeked. Writing currentTime on it
        // leaves the element stuck in `seeking` forever, which is why an instant
        // video note opened in the floating player showed a frame but never
        // advanced. Those simply play from the start instead.
        const dur = readMediaDuration(mediaEl);
        if (!(dur > 0)) return;
        settled = true;
        try {
            mediaEl.currentTime = Math.min(targetTime, Math.max(0, dur - 0.05));
            mediaEl.dispatchEvent(new Event('timeupdate'));
        } catch (e) {}
    };
    applySeek();
    if (settled) return;
    mediaEl.addEventListener('loadedmetadata', applySeek, { once: true });
    mediaEl.addEventListener('durationchange', applySeek, { once: true });
}

function findInlineMediaWrapper(msgId, fileId) {
    const vp = document.getElementById('messages-viewport');
    if (!vp) return null;
    if (msgId) {
        const w = vp.querySelector(`.m3-video-player[data-inline-msg-id="${msgId}"], .m3-audio-player[data-inline-msg-id="${msgId}"]`);
        if (w) return w;
    }
    if (fileId) {
        const w = vp.querySelector(`.m3-video-player[data-inline-file-id="${fileId}"], .m3-audio-player[data-inline-file-id="${fileId}"]`);
        if (w) return w;
    }
    return null;
}

function findInlineMediaElement(msgId, fileId) {
    const w = findInlineMediaWrapper(msgId, fileId);
    if (w) return w._videoEl || w._audioEl || w;
    const vp = document.getElementById('messages-viewport');
    if (!vp) return null;
    if (msgId) {
        const byMsg = vp.querySelector(`[data-inline-msg-id="${msgId}"]`);
        if (byMsg) return byMsg._videoEl || byMsg._audioEl || byMsg;
    }
    if (fileId) {
        const byFile = vp.querySelector(`[data-inline-file-id="${fileId}"]`);
        if (byFile) return byFile._videoEl || byFile._audioEl || byFile;
    }
    return null;
}

function handoffInlineToUniversalPlayer(inlineEl, openOpts = {}) {
    let mediaEl = inlineEl || null;
    if (!mediaEl && (openOpts.sourceMsgId || openOpts.sourceFileId)) {
        mediaEl = findInlineMediaElement(openOpts.sourceMsgId, openOpts.sourceFileId);
    }
    const wasPlaying = Boolean(mediaEl && !mediaEl.paused && !mediaEl.ended);
    const resumeTime = (mediaEl && Number.isFinite(mediaEl.currentTime) && mediaEl.currentTime > 0) ? mediaEl.currentTime : 0;
    const playbackRate = (mediaEl && Number.isFinite(mediaEl.playbackRate) && mediaEl.playbackRate > 0) ? mediaEl.playbackRate : 1;
    const volume = (mediaEl && typeof mediaEl.volume === 'number') ? mediaEl.volume : 1;
    const muted = Boolean(mediaEl && mediaEl.muted);
    const poolKey = (mediaEl && mediaEl._poolKey)
        ? mediaEl._poolKey
        : SharedMediaPool.makeKey(openOpts.type || 'video', openOpts.sourceMsgId, openOpts.sourceFileId, openOpts.url);
    return UniversalPlayer.open(Object.assign({}, openOpts, {
        poolKey,
        sourceMediaEl: mediaEl,
        resumeTime,
        wasInlinePlaying: wasPlaying,
        playbackRate,
        volume,
        muted
    }));
}

const UniversalPlayer = {
    isOpen: false,
    mode: 'normal', // 'normal' | 'float' | 'minimize' | 'maximize'
    prevExpandedMode: 'float',
    mediaType: 'video', // 'video' | 'image' | 'audio' | 'text'
    activeMediaEl: null,
    sourceMediaEl: null,
    sourceMsgId: 0,
    sourceFileId: 0,
    currentTextContent: '',
    currentBlobUrl: null,
    customPos: null,
    _wired: false,

    ensureWired() {
        if (this._wired) return;
        const root = document.getElementById('universal-media-player');
        if (!root) return;
        this._wired = true;

        const btnMin = document.getElementById('ump-btn-minimize');
        const btnFloat = document.getElementById('ump-btn-float');
        const btnNorm = document.getElementById('ump-btn-normal');
        const btnMax = document.getElementById('ump-btn-maximize');
        const btnClose = document.getElementById('ump-btn-close');
        const btnSpeed = document.getElementById('ump-btn-speed');
        const btnPlayPause = document.getElementById('ump-btn-playpause');
        const btnCopy = document.getElementById('ump-btn-copy');
        const handle = document.getElementById('ump-drag-handle');
        if (btnSpeed) {
            btnSpeed.addEventListener('click', e => {
                e.stopPropagation();
                if (!this.activeMediaEl) return;
                const nextR = nextPlaybackRate(this.activeMediaEl.playbackRate);
                this.activeMediaEl.playbackRate = nextR;
                btnSpeed.textContent = nextR + 'x';
                if (this.activeMediaEl._customRateBtn) {
                    this.activeMediaEl._customRateBtn.textContent = nextR + 'x';
                }
            });
        }

        if (btnMin) {
            btnMin.addEventListener('click', e => {
                e.stopPropagation();
                if (this.mode === 'minimize') {
                    this.setMode(this.prevExpandedMode || 'float');
                } else {
                    this.setMode('minimize');
                }
            });
        }
        if (btnFloat) btnFloat.addEventListener('click', e => { e.stopPropagation(); this.setMode('float'); });
        if (btnNorm) btnNorm.addEventListener('click', e => { e.stopPropagation(); this.setMode('normal'); });
        if (btnMax) btnMax.addEventListener('click', e => { e.stopPropagation(); this.setMode('maximize'); });
        if (btnClose) btnClose.addEventListener('click', e => { e.stopPropagation(); this.close(); });

        // Close centered ('normal') popup player when clicking outside on other parts of the site
        let umpOutsideDown = false;
        const isOutsideUmp = (target) => {
            if (!target || !root.contains) return false;
            if (root.contains(target)) return false;
            const tc = document.getElementById('toast-container');
            if (tc && tc.contains(target)) return false;
            const cm = document.getElementById('confirm-modal');
            if (cm && cm.open && cm.contains(target)) return false;
            return true;
        };
        document.addEventListener('mousedown', e => {
            if (!this.isOpen || this.mode !== 'normal') { umpOutsideDown = false; return; }
            if (Date.now() - (this._openedAt || 0) < 120) { umpOutsideDown = false; return; }
            umpOutsideDown = isOutsideUmp(e.target);
        });
        document.addEventListener('click', e => {
            if (!this.isOpen || this.mode !== 'normal') { umpOutsideDown = false; return; }
            if (Date.now() - (this._openedAt || 0) < 120) { umpOutsideDown = false; return; }
            if (umpOutsideDown && isOutsideUmp(e.target)) {
                umpOutsideDown = false;
                this.close();
                return;
            }
            umpOutsideDown = false;
        });

        if (btnPlayPause) {
            btnPlayPause.addEventListener('click', e => {
                e.stopPropagation();
                if (!this.activeMediaEl) return;
                if (this.activeMediaEl.paused) {
                    this.activeMediaEl.play().catch(() => {});
                } else {
                    this.activeMediaEl.pause();
                }
                this.syncPlayPauseIcon();
            });
        }

        if (btnCopy) {
            btnCopy.addEventListener('click', e => {
                e.stopPropagation();
                if (this.currentTextContent) {
                    copyTextToClipboard(this.currentTextContent);
                    toast(t('copied_toast'));
                }
            });
        }

        if (handle) {
            let dragging = false;
            let movedPx = 0;
            let startX = 0, startY = 0, origLeft = 0, origTop = 0;

            const startDrag = (clientX, clientY, target) => {
                if (this.mode === 'maximize') return false;
                if (target && target.closest('button, a, .ump-resizer')) return false;
                const rect = root.getBoundingClientRect();
                dragging = true;
                movedPx = 0;
                startX = clientX;
                startY = clientY;
                origLeft = rect.left;
                origTop = rect.top;
                root.style.transform = 'none';
                root.style.inset = 'auto';
                root.style.bottom = 'auto';
                root.style.right = 'auto';
                root.style.left = origLeft + 'px';
                root.style.top = origTop + 'px';
                return true;
            };

            const moveDrag = (clientX, clientY) => {
                if (!dragging) return;
                const dx = clientX - startX;
                const dy = clientY - startY;
                movedPx = Math.max(movedPx, Math.hypot(dx, dy));
                const maxX = Math.max(0, window.innerWidth - 80);
                const maxY = Math.max(0, window.innerHeight - 44);
                const nextLeft = Math.max(0, Math.min(maxX, origLeft + dx));
                const nextTop = Math.max(0, Math.min(maxY, origTop + dy));
                root.style.left = nextLeft + 'px';
                root.style.top = nextTop + 'px';
                this.customPos = { left: nextLeft, top: nextTop };
            };

            const endDrag = () => {
                dragging = false;
                syncMinimizedPopupsLayout();
            };

            handle.addEventListener('mousedown', e => {
                if (e.button !== 0) return;
                if (!startDrag(e.clientX, e.clientY, e.target)) return;
                const mv = ev => moveDrag(ev.clientX, ev.clientY);
                const up = () => {
                    window.removeEventListener('mousemove', mv);
                    window.removeEventListener('mouseup', up);
                    endDrag();
                };
                window.addEventListener('mousemove', mv);
                window.addEventListener('mouseup', up);
            });

            handle.addEventListener('touchstart', e => {
                if (e.touches.length !== 1) return;
                startDrag(e.touches[0].clientX, e.touches[0].clientY, e.target);
            }, { passive: true });
            handle.addEventListener('touchmove', e => {
                if (!dragging || e.touches.length !== 1) return;
                if (e.cancelable) e.preventDefault();
                moveDrag(e.touches[0].clientX, e.touches[0].clientY);
            }, { passive: false });
            handle.addEventListener('touchend', endDrag);

            const titleWrap = handle.querySelector('.ump-title-wrap');
            if (titleWrap) {
                titleWrap.addEventListener('click', e => {
                    if (this.mode === 'minimize' && movedPx < 5) {
                        e.stopPropagation();
                        this.setMode(this.prevExpandedMode || 'float');
                    }
                });
            }
        }

        // 4-Corner Drag Resizing (nw, ne, sw, se)
        root.querySelectorAll('.ump-resizer').forEach(resizer => {
            const dir = resizer.getAttribute('data-dir') || 'se';
            const beginCornerResize = (startClientX, startClientY) => {
                if (this.mode === 'minimize' || this.mode === 'maximize') return null;
                const rect = root.getBoundingClientRect();
                const startRect = {
                    left: rect.left,
                    top: rect.top,
                    width: Math.max(260, rect.width || 380),
                    height: Math.max(170, rect.height || 260)
                };
                root.classList.add('is-resizing');
                root.setAttribute('data-resized', '1');
                root.style.transform = 'none';
                root.style.inset = 'auto';
                root.style.bottom = 'auto';
                root.style.right = 'auto';
                root.style.left = startRect.left + 'px';
                root.style.top = startRect.top + 'px';
                root.style.width = startRect.width + 'px';
                root.style.height = startRect.height + 'px';

                const minW = 260;
                const minH = 165;
                const onMove = (cx, cy) => {
                    const dx = cx - startClientX;
                    const dy = cy - startClientY;
                    const vw = Math.max(320, window.innerWidth || 1024);
                    const vh = Math.max(240, window.innerHeight || 768);
                    let nextLeft = startRect.left;
                    let nextTop = startRect.top;
                    let nextW = startRect.width;
                    let nextH = startRect.height;

                    if (dir.includes('e')) {
                        nextW = Math.max(minW, Math.min(vw - startRect.left - 6, startRect.width + dx));
                    } else if (dir.includes('w')) {
                        const maxDeltaLeft = startRect.width - minW;
                        const clampedDx = Math.max(-startRect.left + 6, Math.min(maxDeltaLeft, dx));
                        nextLeft = startRect.left + clampedDx;
                        nextW = startRect.width - clampedDx;
                    }

                    if (dir.includes('s')) {
                        nextH = Math.max(minH, Math.min(vh - startRect.top - 6, startRect.height + dy));
                    } else if (dir.includes('n')) {
                        const maxDeltaTop = startRect.height - minH;
                        const clampedDy = Math.max(-startRect.top + 6, Math.min(maxDeltaTop, dy));
                        nextTop = startRect.top + clampedDy;
                        nextH = startRect.height - clampedDy;
                    }

                    root.style.left = Math.round(nextLeft) + 'px';
                    root.style.top = Math.round(nextTop) + 'px';
                    root.style.width = Math.round(nextW) + 'px';
                    root.style.height = Math.round(nextH) + 'px';
                };
                const onEnd = () => {
                    root.classList.remove('is-resizing');
                };
                return { onMove, onEnd };
            };

            resizer.addEventListener('mousedown', e => {
                if (e.button !== 0) return;
                e.preventDefault();
                e.stopPropagation();
                const session = beginCornerResize(e.clientX, e.clientY);
                if (!session) return;
                const mv = ev => session.onMove(ev.clientX, ev.clientY);
                const up = () => {
                    window.removeEventListener('mousemove', mv);
                    window.removeEventListener('mouseup', up);
                    session.onEnd();
                };
                window.addEventListener('mousemove', mv);
                window.addEventListener('mouseup', up);
            });

            resizer.addEventListener('touchstart', e => {
                if (e.touches.length !== 1) return;
                e.stopPropagation();
                const session = beginCornerResize(e.touches[0].clientX, e.touches[0].clientY);
                if (!session) return;
                const mv = ev => {
                    if (ev.touches.length !== 1) return;
                    if (ev.cancelable) ev.preventDefault();
                    session.onMove(ev.touches[0].clientX, ev.touches[0].clientY);
                };
                const up = () => {
                    window.removeEventListener('touchmove', mv);
                    window.removeEventListener('touchend', up);
                    window.removeEventListener('touchcancel', up);
                    session.onEnd();
                };
                window.addEventListener('touchmove', mv, { passive: false });
                window.addEventListener('touchend', up);
                window.addEventListener('touchcancel', up);
            }, { passive: true });
        });
    },

    syncPlayPauseIcon() {
        const btn = document.getElementById('ump-btn-playpause');
        const spBtn = document.getElementById('ump-btn-speed');
        if (spBtn) {
            if (!this.activeMediaEl) {
                spBtn.classList.add('hidden');
            } else {
                spBtn.classList.remove('hidden');
                spBtn.textContent = (Number(this.activeMediaEl.playbackRate) || 1) + 'x';
            }
        }
        if (!btn) return;
        if (!this.activeMediaEl) {
            btn.classList.add('hidden');
            return;
        }
        btn.classList.remove('hidden');
        btn.innerHTML = this.activeMediaEl.paused ? MEDIA_ICON.play : MEDIA_ICON.pause;
    },

    forceBurnClose() {
        const root = document.getElementById('universal-media-player');
        const body = document.getElementById('ump-body');
        SharedMediaPool.evictByIds(this.sourceMsgId, this.sourceFileId);
        if (this.activeMediaEl) {
            this.activeMediaEl._dockedInUmp = false;
            try { this.activeMediaEl.pause(); this.activeMediaEl.removeAttribute('src'); this.activeMediaEl.load(); } catch (e) {}
            this.activeMediaEl = null;
        }
        if (this.currentBlobUrl) {
            try { URL.revokeObjectURL(this.currentBlobUrl); } catch (e) {}
            this.currentBlobUrl = null;
        }
        this.sourceMediaEl = null;
        this.sourceMsgId = 0;
        this.sourceFileId = 0;
        this.currentTextContent = '';
        this.isOpen = false;
        if (body) body.innerHTML = '';
        if (root) {
            if (typeof root.hidePopover === 'function') {
                try { if (root.matches(':popover-open')) root.hidePopover(); } catch (e) {}
            }
            root.classList.add('hidden');
        }
        syncMinimizedPopupsLayout();
    },

    promoteTopLayer() {
        const root = document.getElementById('universal-media-player');
        if (!root || !this.isOpen) return;
        const confirmDlg = document.getElementById('confirm-modal');
        if (confirmDlg && confirmDlg.open) return;
        if (typeof root.showPopover === 'function') {
            try {
                if (root.matches(':popover-open')) root.hidePopover();
                root.showPopover();
            } catch (e) {}
        }
        if (store.isSessionLocked && typeof showMessengerLockScreen === 'function') {
            showMessengerLockScreen(store.user);
        }
    },

    setMode(mode) {
        const root = document.getElementById('universal-media-player');
        if (!root) return;
        if (mode === 'float' || mode === 'normal') {
            this.prevExpandedMode = mode;
        } else if (mode === 'maximize' && this.mode !== 'minimize') {
            this.prevExpandedMode = this.mode || 'float';
        }
        this.mode = mode;
        root.setAttribute('data-mode', mode);
        root.removeAttribute('data-resized');
        // Clear inline geometry so CSS mode presets position cleanly
        root.style.left = '';
        root.style.top = '';
        root.style.right = '';
        root.style.bottom = '';
        root.style.inset = '';
        root.style.width = '';
        root.style.height = '';
        root.style.transform = '';

        ['minimize', 'float', 'normal', 'maximize'].forEach(m => {
            const b = document.getElementById('ump-btn-' + m);
            if (b) b.classList.toggle('active', m === mode);
        });
        const btnMin = document.getElementById('ump-btn-minimize');
        if (btnMin) {
            btnMin.innerHTML = mode === 'minimize'
                ? '<svg viewBox="0 0 24 24"><rect x="5" y="6" width="14" height="12" rx="2"/><line x1="5" y1="10" x2="19" y2="10"/></svg>'
                : '<svg viewBox="0 0 24 24"><line x1="5" y1="12" x2="19" y2="12"/></svg>';
            btnMin.title = mode === 'minimize' ? t('ump_restore_btn') : t('ump_minimize');
        }
        this.syncPlayPauseIcon();
        syncMinimizedPopupsLayout();
    },

    async open(opts = {}) {
        this.ensureWired();
        const root = document.getElementById('universal-media-player');
        const body = document.getElementById('ump-body');
        const titleEl = document.getElementById('ump-title');
        const iconEl = document.getElementById('ump-type-icon');
        const dlBtn = document.getElementById('ump-btn-download');
        const copyBtn = document.getElementById('ump-btn-copy');
        if (!root || !body) return;

        // Clean previous media safely
        if (this.activeMediaEl) {
            try { this.activeMediaEl.pause(); } catch (e) {}
            this.activeMediaEl = null;
        }
        if (this.currentBlobUrl && this.currentBlobUrl !== opts.url) {
            try { URL.revokeObjectURL(this.currentBlobUrl); } catch (e) {}
            this.currentBlobUrl = null;
        }
        if (opts.isBlobUrl && opts.url) {
            this.currentBlobUrl = opts.url;
        }

        this._openedAt = Date.now();
        this.mediaType = opts.type || 'video';
        this.sourceMediaEl = opts.sourceMediaEl || opts.sourceEl || null;
        this.sourceMsgId = Number(opts.sourceMsgId || opts.msgId || 0);
        this.sourceFileId = Number(opts.sourceFileId || opts.fileId || 0);
        this.currentTextContent = '';
        root.setAttribute('data-type', this.mediaType);
        root.setAttribute('data-vnote', (this.mediaType === 'video' && opts.isVideoNote) ? '1' : '0');
        body.innerHTML = '';

        const zeroSave = Boolean(opts.zeroSave || opts.allowDownload === false);
        body.classList.toggle('m3-zero-save', zeroSave);
        if (zeroSave) {
            body.oncontextmenu = e => { e.preventDefault(); return false; };
        } else {
            body.oncontextmenu = null;
        }

        const icons = { video: '🎬', image: '🖼️', audio: '🎵', text: '📄' };
        if (iconEl) iconEl.textContent = icons[this.mediaType] || '🎬';
        if (titleEl) titleEl.textContent = opts.title || 'Media';

        if (dlBtn) {
            if (!zeroSave && opts.allowDownload !== false && (opts.downloadUrl || opts.url)) {
                dlBtn.href = opts.downloadUrl || opts.url;
                dlBtn.setAttribute('download', opts.title || 'download');
                dlBtn.classList.remove('hidden');
            } else {
                dlBtn.removeAttribute('href');
                dlBtn.classList.add('hidden');
            }
        }
        if (copyBtn) copyBtn.classList.toggle('hidden', zeroSave || this.mediaType !== 'text' || opts.allowCopy === false);

        const resumeTime = Number(opts.resumeTime || 0);
        const initRate = (Number.isFinite(opts.playbackRate) && opts.playbackRate > 0) ? opts.playbackRate : 1;
        const initVol = typeof opts.volume === 'number' ? opts.volume : 1;
        const initMuted = Boolean(opts.muted);
        // Opening the pop-out is not a request to play: it only carries on if
        // the media was already playing where it came from.
        const shouldAutoPlay = opts.autoPlay !== undefined ? Boolean(opts.autoPlay) : Boolean(opts.wasInlinePlaying);

        const bindUmpMediaPinchZoomPan = (mediaEl, isImage) => {
            let scale = 1;
            let panX = 0;
            let panY = 0;
            let pinchStartDist = 0;
            let pinchStartScale = 1;
            let dragStartX = 0;
            let dragStartY = 0;
            let dragBaseX = 0;
            let dragBaseY = 0;
            let isDragging = false;
            let lastTapAt = 0;
            let movedDuringGesture = false;

            const applyTransform = () => {
                if (scale <= 1.01) {
                    scale = 1;
                    panX = 0;
                    panY = 0;
                    mediaEl.style.transform = '';
                    mediaEl.classList.remove('zoomed');
                    body.classList.remove('ump-pinch-active');
                    if (isImage) mediaEl.style.cursor = 'zoom-in';
                } else {
                    const maxOff = Math.max(120, Math.round((scale - 1) * 260));
                    panX = Math.max(-maxOff, Math.min(maxOff, panX));
                    panY = Math.max(-maxOff, Math.min(maxOff, panY));
                    mediaEl.style.transform = `translate3d(${panX}px, ${panY}px, 0) scale(${scale})`;
                    if (isImage) mediaEl.style.cursor = 'grab';
                }
            };

            const touchDist = (t0, t1) => Math.hypot(t1.clientX - t0.clientX, t1.clientY - t0.clientY);

            mediaEl.addEventListener('touchstart', e => {
                if (e.touches.length === 2) {
                    e.preventDefault();
                    e.stopPropagation();
                    body.classList.add('ump-pinch-active');
                    pinchStartDist = Math.max(12, touchDist(e.touches[0], e.touches[1]));
                    pinchStartScale = scale;
                    isDragging = false;
                    movedDuringGesture = true;
                } else if (e.touches.length === 1 && scale > 1.02) {
                    body.classList.add('ump-pinch-active');
                    isDragging = true;
                    movedDuringGesture = false;
                    dragStartX = e.touches[0].clientX;
                    dragStartY = e.touches[0].clientY;
                    dragBaseX = panX;
                    dragBaseY = panY;
                } else if (e.touches.length === 1) {
                    movedDuringGesture = false;
                }
            }, { passive: false });

            mediaEl.addEventListener('touchmove', e => {
                if (e.touches.length === 2 && pinchStartDist > 0) {
                    e.preventDefault();
                    e.stopPropagation();
                    const d = touchDist(e.touches[0], e.touches[1]);
                    scale = Math.max(1, Math.min(5, Math.round((pinchStartScale * (d / pinchStartDist)) * 100) / 100));
                    movedDuringGesture = true;
                    applyTransform();
                } else if (e.touches.length === 1 && isDragging && scale > 1.02) {
                    e.preventDefault();
                    e.stopPropagation();
                    const dx = e.touches[0].clientX - dragStartX;
                    const dy = e.touches[0].clientY - dragStartY;
                    if (Math.abs(dx) > 4 || Math.abs(dy) > 4) movedDuringGesture = true;
                    panX = dragBaseX + dx;
                    panY = dragBaseY + dy;
                    applyTransform();
                }
            }, { passive: false });

            const onTouchFinish = e => {
                if (!e.touches || e.touches.length === 0) {
                    pinchStartDist = 0;
                    isDragging = false;
                    if (scale <= 1.02) body.classList.remove('ump-pinch-active');
                    const nowTap = Date.now();
                    if (!movedDuringGesture && isImage && (nowTap - lastTapAt) < 300) {
                        scale = scale > 1.1 ? 1 : 2.2;
                        panX = 0;
                        panY = 0;
                        applyTransform();
                        lastTapAt = 0;
                    } else if (!movedDuringGesture) {
                        lastTapAt = nowTap;
                    }
                } else if (e.touches.length === 1 && scale > 1.02) {
                    pinchStartDist = 0;
                    isDragging = true;
                    dragStartX = e.touches[0].clientX;
                    dragStartY = e.touches[0].clientY;
                    dragBaseX = panX;
                    dragBaseY = panY;
                }
            };
            mediaEl.addEventListener('touchend', onTouchFinish);
            mediaEl.addEventListener('touchcancel', onTouchFinish);

            mediaEl.addEventListener('wheel', e => {
                e.preventDefault();
                const delta = e.deltaY < 0 ? 0.24 : -0.24;
                scale = Math.max(1, Math.min(5, Math.round((scale + delta) * 100) / 100));
                applyTransform();
            }, { passive: false });

            if (isImage) {
                mediaEl.addEventListener('mousedown', e => {
                    if (e.button !== 0 || scale <= 1.02) return;
                    e.preventDefault();
                    isDragging = true;
                    movedDuringGesture = false;
                    dragStartX = e.clientX;
                    dragStartY = e.clientY;
                    dragBaseX = panX;
                    dragBaseY = panY;
                    const mm = ev => {
                        const dx = ev.clientX - dragStartX;
                        const dy = ev.clientY - dragStartY;
                        if (Math.abs(dx) > 3 || Math.abs(dy) > 3) movedDuringGesture = true;
                        panX = dragBaseX + dx;
                        panY = dragBaseY + dy;
                        applyTransform();
                    };
                    const mu = () => {
                        isDragging = false;
                        window.removeEventListener('mousemove', mm);
                        window.removeEventListener('mouseup', mu);
                    };
                    window.addEventListener('mousemove', mm);
                    window.addEventListener('mouseup', mu);
                });
                mediaEl.addEventListener('click', () => {
                    if (movedDuringGesture) {
                        movedDuringGesture = false;
                        return;
                    }
                    scale = scale > 1.05 ? 1 : 1.75;
                    panX = 0;
                    panY = 0;
                    applyTransform();
                });
            }
        };

        if (this.mediaType === 'image') {
            const img = document.createElement('img');
            img.src = opts.url;
            img.alt = opts.title || '';
            if (zeroSave) bindZeroSaveDomGuards(img);
            bindUmpMediaPinchZoomPan(img, true);
            body.appendChild(img);
        } else if (this.mediaType === 'video') {
            const poolKey = opts.poolKey || SharedMediaPool.makeKey('video', this.sourceMsgId, this.sourceFileId, opts.url);
            const inlineWrapBefore = findInlineMediaWrapper(this.sourceMsgId, this.sourceFileId);
            const customVid = createCustomVideoPlayer({
                url: opts.url,
                poolKey,
                msgId: this.sourceMsgId,
                fileId: this.sourceFileId,
                zeroSave,
                allowDownload: !!opts.allowDownload,
                inUmp: true,
                autoPlay: false
            });
            const vid = customVid.video;
            vid._dockedInUmp = true;
            vid.preload = 'auto';
            if (inlineWrapBefore && typeof inlineWrapBefore._notifyDockedInUmp === 'function') {
                inlineWrapBefore._notifyDockedInUmp();
            }
            vid.playbackRate = initRate;
            vid.volume = initVol;
            vid.muted = initMuted;
            if (customVid.speedPill) customVid.speedPill.textContent = initRate + 'x';
            vid._customRateBtn = customVid.speedPill;
            vid.addEventListener('play', () => this.syncPlayPauseIcon());
            vid.addEventListener('pause', () => this.syncPlayPauseIcon());
            vid.addEventListener('ended', () => this.syncPlayPauseIcon());
            vid.addEventListener('ratechange', () => this.syncPlayPauseIcon());
            this.activeMediaEl = vid;
            body.appendChild(customVid.wrap);
            if (resumeTime > 0 && Math.abs((vid.currentTime || 0) - resumeTime) > 0.35) {
                seekMediaSafely(vid, resumeTime);
            }
            customVid.syncVidVisual();
            if (shouldAutoPlay && vid.paused) {
                vid.play().catch(() => {});
            }
        } else if (this.mediaType === 'audio') {
            const stage = document.createElement('div');
            stage.className = 'ump-audio-stage';
            const disc = document.createElement('div');
            disc.className = 'ump-audio-disc';
            disc.textContent = '🎵';
            const lbl = document.createElement('div');
            lbl.style.cssText = 'font-weight:800;font-size:13.5px;text-align:center;word-break:break-word';
            lbl.textContent = opts.title || '';
            const poolKey = opts.poolKey || SharedMediaPool.makeKey('audio', this.sourceMsgId, this.sourceFileId, opts.url);
            const customAud = createCustomAudioPlayer({
                url: opts.url,
                poolKey,
                inUmp: true,
                cacheKey: opts.cacheKey || opts.url,
                displayName: opts.title || '',
                autoPlay: false
            });
            const aud = customAud.audio;
            aud._dockedInUmp = true;
            aud.playbackRate = initRate;
            aud.volume = initVol;
            aud.muted = initMuted;
            if (customAud.rateBtn) customAud.rateBtn.textContent = initRate + 'x';
            aud._customRateBtn = customAud.rateBtn;
            aud.addEventListener('play', () => this.syncPlayPauseIcon());
            aud.addEventListener('pause', () => this.syncPlayPauseIcon());
            aud.addEventListener('ended', () => this.syncPlayPauseIcon());
            aud.addEventListener('ratechange', () => this.syncPlayPauseIcon());
            if (zeroSave) bindZeroSaveDomGuards(stage);
            this.activeMediaEl = aud;
            stage.appendChild(disc);
            stage.appendChild(lbl);
            stage.appendChild(customAud.wrap);
            body.appendChild(stage);
            if (resumeTime > 0 && Math.abs((aud.currentTime || 0) - resumeTime) > 0.35) {
                seekMediaSafely(aud, resumeTime);
            }
            customAud.syncSliderVisual();
            if (shouldAutoPlay && aud.paused) {
                aud.play().catch(() => {});
            }
        } else if (this.mediaType === 'text') {
            const pre = document.createElement('pre');
            pre.className = 'ump-text-reader';
            pre.setAttribute('dir', 'auto');
            if (typeof opts.textContent === 'string') {
                this.currentTextContent = opts.textContent;
                pre.textContent = opts.textContent || t('txt_empty');
            } else if (opts.url) {
                pre.textContent = t('txt_loading');
                fetch(opts.url, { credentials: 'same-origin' })
                    .then(r => r.text())
                    .then(txt => {
                        this.currentTextContent = txt;
                        pre.textContent = txt || t('txt_empty');
                    })
                    .catch(() => {
                        pre.textContent = t('txt_load_err');
                    });
            }
            body.appendChild(pre);
        }

        this.isOpen = true;
        root.classList.remove('hidden');
        this.setMode(opts.mode || 'normal');
        this.promoteTopLayer();
        this.syncPlayPauseIcon();
        syncMinimizedPopupsLayout();
    },

    close() {
        const root = document.getElementById('universal-media-player');
        const body = document.getElementById('ump-body');

        // Capture current playback state BEFORE pausing/cleaning up so we can return seamlessly to inline player
        const umpEl = this.activeMediaEl;
        const umpWasPlaying = Boolean(umpEl && !umpEl.paused && !umpEl.ended);
        const umpTime = (umpEl && Number.isFinite(umpEl.currentTime) && umpEl.currentTime >= 0) ? umpEl.currentTime : 0;
        const umpRate = (umpEl && Number.isFinite(umpEl.playbackRate) && umpEl.playbackRate > 0) ? umpEl.playbackRate : 1;
        const umpVol = (umpEl && typeof umpEl.volume === 'number') ? umpEl.volume : 1;
        const umpMuted = Boolean(umpEl && umpEl.muted);
        const savedSourceEl = this.sourceMediaEl;
        const savedMsgId = this.sourceMsgId;
        const savedFileId = this.sourceFileId;

        const wasPooled = Boolean(this.activeMediaEl && this.activeMediaEl._fromSharedPool);
        if (this.activeMediaEl) {
            this.activeMediaEl._dockedInUmp = false;
            if (!wasPooled) {
                try { this.activeMediaEl.pause(); this.activeMediaEl.src = ''; } catch (e) {}
            }
            this.activeMediaEl = null;
        }
        const savedType = this.mediaType;
        this.sourceMediaEl = null;
        this.sourceMsgId = 0;
        this.sourceFileId = 0;

        if (this.currentBlobUrl) {
            try { URL.revokeObjectURL(this.currentBlobUrl); } catch (e) {}
            this.currentBlobUrl = null;
        }
        this.isOpen = false;
        if (body) body.innerHTML = '';
        if (root) {
            if (typeof root.hidePopover === 'function') {
                try { if (root.matches(':popover-open')) root.hidePopover(); } catch (e) {}
            }
            root.classList.add('hidden');
        }
        syncMinimizedPopupsLayout();

        // Return live shared media element directly into the inline message player with zero re-buffering!
        if (umpEl && (savedType === 'video' || savedType === 'audio')) {
            const inlineWrap = findInlineMediaWrapper(savedMsgId, savedFileId);
            if (inlineWrap && typeof inlineWrap._reclaimMedia === 'function') {
                inlineWrap._reclaimMedia();
                const reclaimedEl = inlineWrap._videoEl || inlineWrap._audioEl || umpEl;
                try {
                    reclaimedEl.playbackRate = umpRate;
                    reclaimedEl.volume = umpVol;
                    reclaimedEl.muted = umpMuted;
                    if (umpWasPlaying && reclaimedEl.paused) reclaimedEl.play().catch(() => {});
                    else if (!umpWasPlaying && !reclaimedEl.paused) reclaimedEl.pause();
                } catch (e) {}
            } else if (umpEl && umpEl._vnoteSlot) {
                // Instant video notes have no .m3-video-player wrapper: put the live
                // element straight back into the circular note's slot.
                const slot = umpEl._vnoteSlot;
                slot.innerHTML = '';
                slot.appendChild(umpEl);
                try {
                    umpEl.playbackRate = umpRate;
                    umpEl.volume = umpVol;
                    umpEl.muted = umpMuted;
                    if (umpWasPlaying && umpEl.paused) umpEl.play().catch(() => {});
                    else if (!umpWasPlaying && !umpEl.paused) umpEl.pause();
                } catch (e) {}
            } else if (wasPooled && !umpWasPlaying) {
                try { umpEl.pause(); } catch (e) {}
            }
        }
    }
};

/* ---------------- SIDEBAR CHAT ACTIONS & RIGHT-CLICK CONTEXT MENU ---------------- */
function closeChatContextMenu() {
    const menu = document.getElementById('chat-context-menu');
    if (menu) {
        menu.classList.add('hidden');
        menu.innerHTML = '';
    }
}

async function markChatAsRead(chatId, showToast = true) {
    const r = await apiCall('chat_mark_read', { chat_id: chatId });
    if (r.ok && r.data) {
        if (r.data.chats) store.chats = r.data.chats;
        renderChatList();
        renderActiveChatHeader();
        if (showToast) toast(t('marked_read_toast'));
    } else if (showToast) {
        toast(r.message || t('err_generic'), true);
    }
}

async function markAllUnreadChatsRead() {
    const unreadChats = store.chats.filter(c => (c.unread_count || 0) > 0);
    if (unreadChats.length === 0) {
        if (store.activeChatId) {
            await markChatAsRead(store.activeChatId, true);
        } else {
            toast(t('all_already_read_toast'));
        }
        return;
    }
    for (const c of unreadChats) {
        const r = await apiCall('chat_mark_read', { chat_id: c.id });
        if (r.ok && r.data && r.data.chats) {
            store.chats = r.data.chats;
        }
    }
    renderChatList();
    renderActiveChatHeader();
    toast(t('marked_read_toast'));
}

async function toggleChatPin(chat) {
    if (!chat || chat.type === 'saved') return;
    const nextPin = chat.is_pinned === 1 ? 0 : 1;
    const r = await apiCall('chat_pin_toggle', { chat_id: chat.id, pinned: nextPin });
    if (r.ok && r.data) {
        store.chats = r.data.chats || store.chats;
        renderChatList();
        toast(r.data.pinned ? t('chat_pinned_toast') : t('chat_unpinned_toast'));
    } else {
        toast(r.message || t('err_generic'), true);
    }
}

async function toggleChatNotifMute(chat) {
    if (!chat) return;
    const nextMute = chat.muted === 1 ? 0 : 1;
    const r = await apiCall('chat_notif_mute_toggle', { chat_id: chat.id, muted: nextMute });
    if (r.ok && r.data) {
        store.chats = r.data.chats || store.chats;
        renderChatList();
        renderActiveChatHeader();
        toast(r.data.muted ? t('chat_notif_muted_toast') : t('chat_notif_unmuted_toast'));
    } else {
        toast(r.message || t('err_generic'), true);
    }
}

async function leaveOrDeleteChatAction(chat, actionMode) {
    if (!chat) return;
    const displayTitle = formatChatTitle(chat);
    if (actionMode === 'leave') {
        // A plain member is never offered "delete" — only leaving, so say exactly
        // that, and word it per chat type (leaving a group vs unsubscribing a channel).
        const lvTitle = (chat.type === 'channel') ? t('del_conv_title_channel_member') : t('del_conv_title_group_member');
        const lvDesc  = (chat.type === 'channel') ? t('del_conv_desc_channel_member')  : t('del_conv_desc_group_member');
        const ap = await askApproval({
            title: lvTitle,
            desc: lvDesc + '\n💬 ' + displayTitle,
            danger: true,
            icon: '👋'
        });
        if (!ap.approved) return;
        const r = await apiCall('chat_leave', { chat_id: chat.id });
        if (r.ok) {
            store.chats = r.data.chats || [];
            if (store.activeChatId === chat.id) {
                showNoChatSelected();
            }
            renderChatList();
            toast(`${t('left_chat_toast')} (${displayTitle})`);
        } else {
            toast(r.message || t('cannot_leave_default_channel'), true);
        }
        return;
    }

        // Delete conversation / leave / erase.
    // The backend outcome differs by chat type AND by whether the actor owns the
    // space: chat_delete_conversation only drops your own membership for a regular
    // member, but it destroys the whole space for a DM/secret chat or for an
    // owner/super-admin of a non-default group or channel. The confirmation must
    // describe what will really happen, never a generic "delete".
    const isSaved = chat.type === 'saved';
    const isSuperActor = !!(store.user && store.user.role === 'superadmin');
    const isSpaceOwner = chat.my_role === 'owner' || (store.user && chat.owner_id === store.user.id);
    const isSuperNotOwner = isSuperActor && !isSpaceOwner;
    const erasesGlobally = (chat.type === 'group' || chat.type === 'channel')
        && (isSpaceOwner || isSuperActor)
        && chat.is_default !== 1;
    let delTitle, delDesc, delIcon;
    if (isSaved) {
        delTitle = t('del_conv_title_saved');  delDesc = t('del_conv_desc_saved');  delIcon = '🧹';
    } else if (chat.type === 'secret') {
        delTitle = t('del_conv_title_secret'); delDesc = t('del_conv_desc_secret'); delIcon = '🗑️';
    } else if (chat.type === 'dm') {
        delTitle = t('del_conv_title_dm');     delDesc = t('del_conv_desc_dm');     delIcon = '🗑️';
    } else if (chat.type === 'group') {
        if (!erasesGlobally) {
            delTitle = t('del_conv_title_group_member'); delDesc = t('del_conv_desc_group_member');
        } else if (isSuperNotOwner) {
            delTitle = t('del_conv_title_group_super');  delDesc = t('del_conv_desc_group_super');
        } else {
            delTitle = t('del_conv_title_group_owner');  delDesc = t('del_conv_desc_group_owner');
        }
        delIcon = erasesGlobally ? '🗑️' : '👋';
    } else if (chat.type === 'channel') {
        if (!erasesGlobally) {
            delTitle = t('del_conv_title_channel_member'); delDesc = t('del_conv_desc_channel_member');
        } else if (isSuperNotOwner) {
            delTitle = t('del_conv_title_channel_super');  delDesc = t('del_conv_desc_channel_super');
        } else {
            delTitle = t('del_conv_title_channel_owner');  delDesc = t('del_conv_desc_channel_owner');
        }
        delIcon = erasesGlobally ? '🗑️' : '👋';
    } else {
        delTitle = t('delete_conv_btn');       delDesc = t('ask_delete_conv');      delIcon = '🗑️';
    }
    const ap = await askApproval({
        title: delTitle,
        desc: delDesc + '\n💬 ' + displayTitle,
        danger: true,
        icon: delIcon
    });
    if (!ap.approved) return;
    const r = await apiCall('chat_delete_conversation', { chat_id: chat.id });
    if (r.ok) {
        store.chats = r.data.chats || [];
        delete store.messages[chat.id];
        if (isSaved) {
            if (store.activeChatId === chat.id) await selectChat(chat.id);
            renderChatList();
            toast(t('saved_cleared_toast'));
        } else {
            if (store.activeChatId === chat.id) {
                showNoChatSelected();
            }
            renderChatList();
            toast(t('conv_deleted_toast'));
        }
    } else {
        toast(r.message || t('err_generic'), true);
    }
}

/* Remove a one-to-one chat from THIS user's list only.
   The chat itself, its members and every message survive untouched for the other
   person. Reopening a chat with the same person restores it, but the history is
   cut at the moment of removal for the remover only, so the conversation reads as
   new on their side while the other party keeps the continuous thread. */
async function deleteDmForMeAction(chat, displayTitle) {
    if (!chat) return;
    if (chat.type !== 'dm') {
        toast(t('err_generic'), true);
        return;
    }
    const title = displayTitle || formatChatTitle(chat);
    const ap = await askApproval({
        title: t('del_dm_for_me_title'),
        desc: t('del_dm_for_me_desc') + '\n\u{1F4AC} ' + title,
        danger: true,
        icon: '🚪'
    });
    if (!ap.approved) return;
    const r = await apiCall('chat_hide_for_me', { chat_id: chat.id });
    if (!r.ok) {
        toast(r.message || t('err_generic'), true);
        return;
    }
    store.chats = r.data.chats || [];
    delete store.messages[chat.id];
    if (store.activeChatId === chat.id) {
        showNoChatSelected();
    }
    renderChatList();
    toast(t('del_dm_for_me_toast'));
}

async function toggleChatFeature(chat, feature, scope) {
    if (!chat || !feature) return;
    const curOn = (feature === 'chat_preview')
        ? (Number(chat.preview_hidden) !== 1)
        : (Number(chat.msg_views_enabled) === 1);
    const label = (feature === 'chat_preview') ? t('chat_preview_lbl') : t('msg_views_lbl');
    try {
        const res = await apiCall('chat_feature_set', {
            chat_id: chat.id,
            feature: feature,
            scope: scope || 'me',
            enabled: curOn ? 0 : 1
        });
        if (!res.ok) { toast(res.message || t('err_generic'), true); return; }
        if (res.data && Array.isArray(res.data.chats)) {
            store.chats = res.data.chats;
            renderChatList();
        }
        toast(label + ': ' + t(curOn ? 'feature_state_off' : 'feature_state_on'));
    } catch (e) {
        toast(t('err_generic'), true);
    }
}

function openChatContextMenu(chat, clientX, clientY) {
    const menu = document.getElementById('chat-context-menu');
    if (!menu || !chat) return;
    menu.innerHTML = '';

    const head = document.createElement('div');
    head.className = 'chat-ctx-head';
    head.textContent = (chat.type === 'saved' ? '🔖 ' : '') + formatChatTitle(chat);
    menu.appendChild(head);

    const addItem = (label, onClick, isDanger = false) => {
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.className = 'chat-ctx-item' + (isDanger ? ' danger' : '');
        btn.textContent = label;
        btn.addEventListener('click', async e => {
            e.stopPropagation();
            closeChatContextMenu();
            await onClick();
        });
        menu.appendChild(btn);
    };

    // 1. Mark as Read
    addItem(t('mark_as_read_btn'), () => markChatAsRead(chat.id, true));

    // 2. Pin / Unpin (Saved Messages is always #1 at top)
    if (chat.type !== 'saved') {
        addItem(chat.is_pinned === 1 ? t('unpin_chat_btn') : t('pin_chat_btn'), () => toggleChatPin(chat));
    }

    // 3. Mute / Unmute Notifications (all chats, channels, groups)
    addItem(chat.muted === 1 ? t('unmute_notif_btn') : t('mute_notif_btn'), () => toggleChatNotifMute(chat));

    // 4. Last-message preview: every member may hide it for themselves.
    addItem(t('chat_preview_lbl') + ' — ' + ((chat.preview_hidden === 1) ? t('feature_off_badge') : t('feature_on_badge')), () => toggleChatFeature(chat, 'chat_preview', 'me'));

    // 5. Open Chat Info & Sent Files in this Chat
    addItem('ℹ️ ' + t('tip_chat_info'), async () => {
        if (store.activeChatId !== chat.id) await selectChat(chat.id);
        openChatInfoModal('overview');
    });
    if (chat.type !== 'system') {
        addItem('📂 ' + t('chat_sent_files_btn'), () => openMyUploadedFilesModal(chat.id));
    }

    // 5. Leave Group / Channel (never allowed for Official System Chat)
    if (chat.type !== 'system' && (chat.type === 'group' || chat.type === 'channel') && chat.can_leave) {
        addItem(t('leave_chat_btn'), () => leaveOrDeleteChatAction(chat, 'leave'), true);
    }

    // 6. Delete Conversation (DM, Secret, Saved clear, or owned non-default Group/Channel — never System Chat)
    const isSuper = store.user && store.user.role === 'superadmin';
    const isOwner = store.user && chat.owner_id === store.user.id;
    if (chat.type === 'dm' || chat.type === 'secret') {
        addItem(t('delete_conv_btn'), () => leaveOrDeleteChatAction(chat, 'delete'), true);
        if (chat.type === 'dm') {
            addItem(t('del_dm_for_me_btn'), () => deleteDmForMeAction(chat, formatChatTitle(chat)), true);
        }
    } else if (chat.type === 'saved') {
        addItem(t('clear_saved_btn'), () => leaveOrDeleteChatAction(chat, 'delete'), true);
    } else if ((chat.type === 'group' || chat.type === 'channel') && (isOwner || isSuper) && chat.is_default !== 1) {
        addItem(t('delete_conv_btn'), () => leaveOrDeleteChatAction(chat, 'delete'), true);
    }

    menu.classList.remove('hidden');
    const rect = menu.getBoundingClientRect();
    const pad = 10;
    const left = Math.max(pad, Math.min(window.innerWidth - rect.width - pad, clientX));
    const top = Math.max(pad, Math.min(window.innerHeight - rect.height - pad, clientY));
    menu.style.left = left + 'px';
    menu.style.top = top + 'px';
}

// Unread total per category, shown on the corner of each filter pill so the row
// also reads as a breakdown of where the unread messages actually are.
function updateChatFilterPillCounts() {
    const counts = { all: 0, unread: 0, dm: 0, group: 0, channel: 0, secret: 0 };
    (store.chats || []).forEach(c => {
        const n = Number(c.unread_count || 0);
        if (n <= 0) return;
        counts.all += n;
        counts.unread += n;
        if (Object.prototype.hasOwnProperty.call(counts, c.type)) counts[c.type] += n;
    });
    document.querySelectorAll('#chat-filter-pills .filter-pill[data-chat-filter]').forEach(pill => {
        const n = counts[pill.dataset.chatFilter] || 0;
        let badge = pill.querySelector('.filter-pill-count');
        if (n <= 0) {
            if (badge) badge.remove();
            return;
        }
        if (!badge) {
            badge = document.createElement('span');
            badge.className = 'filter-pill-count';
            pill.appendChild(badge);
        }
        badge.textContent = formatLocalizedCount(n);
    });
}

function renderChatList() {
    const container = document.getElementById('chat-list-container');
    if (!container) return;
    container.innerHTML = '';

    let totalUnread = 0;
    store.chats.forEach(c => {
        if (c.muted !== 1) totalUnread += (c.unread_count || 0);
    });

    const filteredChats = store.chats.filter(c => {
        if (store.chatFilter === 'unread') return (c.unread_count || 0) > 0;
        if (store.chatFilter === 'dm') return c.type === 'dm';
        if (store.chatFilter === 'group') return c.type === 'group';
        if (store.chatFilter === 'channel') return c.type === 'channel';
        if (store.chatFilter === 'secret') return c.type === 'secret';
        return true;
    });

    if (filteredChats.length === 0) {
        const empty = document.createElement('div');
        empty.style.cssText = 'text-align:center;padding:32px 16px;color:var(--text-muted);font-size:13px';
        empty.textContent = t('no_chats_in_filter');
        container.appendChild(empty);
    }

    filteredChats.forEach(chat => {
        const isSaved = chat.type === 'saved';
        const displayTitle = formatChatTitle(chat);
        const item = document.createElement('div');
        item.className = 'chat-item' + (chat.id === store.activeChatId ? ' active' : '');
        item.dataset.chatId = String(chat.id);
        item.addEventListener('click', () => selectChat(chat.id));

        // Desktop: right-click only. A long left-press on a chat row is usually a
        // stray hold or the start of a drag, not a request for the row menu.
        // Touch keeps the long-press, so mobile behaviour is unchanged.
        bindContextAndHold(item, (cx, cy) => {
            openChatContextMenu(chat, cx, cy);
        }, 460, { mouseHold: false });

        const avWrap = document.createElement('div');
        avWrap.className = 'avatar-wrap';
        const av = document.createElement('div');
        av.className = 'avatar';
        renderAvatarNode(av, displayTitle, chat.avatar, isSaved, chat.type === 'system');
        avWrap.appendChild(av);

        if (!isSaved && chat.type !== 'system' && chat.peer && chat.peer.online) {
            const dot = document.createElement('span');
            dot.className = 'online-dot';
            avWrap.appendChild(dot);
        }

        const body = document.createElement('div');
        body.className = 'chat-item-body';

        const top = document.createElement('div');
        top.className = 'chat-item-top';

        const titleWrap = document.createElement('div');
        titleWrap.className = 'chat-item-title';

        const iconPrefix = document.createElement('span');
        iconPrefix.style.flexShrink = '0';
        if (chat.type === 'saved') iconPrefix.textContent = '🔖';
        else if (chat.type === 'system') iconPrefix.textContent = '🛡️';
        else if (chat.type === 'secret') iconPrefix.textContent = '🔒';
        else if (chat.type === 'channel') iconPrefix.textContent = '📢';
        else if (chat.type === 'group') iconPrefix.textContent = '👥';
        if (iconPrefix.textContent) titleWrap.appendChild(iconPrefix);

        const titleText = document.createElement('span');
        titleText.className = 'chat-title-text';
        titleText.textContent = displayTitle;
        titleWrap.appendChild(titleText);

        if (chat.peer && chat.peer.has_admin_badge) {
            titleWrap.appendChild(createAdminBadgeNode());
        }
        if (chat.is_default === 1) {
            const defTag = document.createElement('span');
            defTag.className = 'sys-pill-tag';
            defTag.textContent = t('official_tag');
            titleWrap.appendChild(defTag);
        }

        const timeSpan = document.createElement('span');
        timeSpan.style.cssText = 'font-size:11px;color:var(--text-muted);display:flex;align-items:center;gap:3px;flex-shrink:0';
        if (chat.last_message) {
            // Compare numerically: the conversation view does the same, and a
            // strict === silently dropped the tick whenever the id arrived as a
            // string. The tick also mirrors the bubble's own rule, falling back to
            // the chat's peer_last_read_id when the preview carries no status.
            if (store.user && Number(chat.last_message.user_id) === Number(store.user.id)) {
                const lastId = Number(chat.last_message.id || 0);
                const peerRead = Number(chat.peer_last_read_id || 0);
                const listTick = (lastId > 0 && peerRead > 0 && lastId <= peerRead)
                    ? 'seen'
                    : (chat.last_message.tick_status || 'sent');
                timeSpan.appendChild(createTickIcon(listTick));
            }
            const tNode = document.createElement('span');
            tNode.textContent = formatTimeOnly(chat.last_message.created_at);
            timeSpan.appendChild(tNode);
        }

        top.appendChild(titleWrap);
        top.appendChild(timeSpan);

        const sub = document.createElement('div');
        sub.className = 'chat-item-sub';

        const prev = document.createElement('div');
        prev.className = 'chat-item-preview';
        const liveAc = chat.active_call && chat.active_call.status !== 'ended' ? chat.active_call : null;
        const isIncomingRingRow = Boolean(liveAc && liveAc.status === 'ringing' && store.user && Number(liveAc.started_by) !== Number(store.user.id));
        // A ringing call always wins: it is an actionable alert, not a preview.
        if (isIncomingRingRow) {
            prev.style.cssText = 'color:#10b981;font-weight:800';
            prev.textContent = (liveAc.call_type === 'video' ? t('global_incoming_video_lbl') : t('global_incoming_audio_lbl'));
        } else if (chat.preview_hidden === 1 && chat.last_message) {
            // The snippet is switched off for this chat (by me, by the chat admins,
            // or globally) - say there is something new without revealing it.
            prev.style.cssText = 'font-style:italic;opacity:0.85';
            prev.textContent = t('new_message_placeholder');
        } else if (chat.last_message && chat.last_message.kind === 'call_log') {
            prev.textContent = formatDynamicServerText(chat.last_message.body) || ('📞 ' + t('call_log_audio_lbl'));
        } else {
            prev.textContent = chat.last_message ? (formatDynamicServerText(chat.last_message.body) || t('media_attachment')) : (formatChatDescription(chat) || t('no_messages_yet'));
        }
        sub.appendChild(prev);

        const badgesRight = document.createElement('div');
        badgesRight.style.cssText = 'display:flex;align-items:center;gap:4px;flex-shrink:0';
        if (liveAc) {
            const callPill = document.createElement('span');
            callPill.style.cssText = 'display:inline-flex;align-items:center;gap:3px;padding:2px 7px;border-radius:999px;font-size:11px;font-weight:800;background:rgba(16,185,129,0.18);color:#10b981;border:1px solid rgba(16,185,129,0.45)';
            callPill.textContent = isIncomingRingRow ? '📲' : '🟢';
            badgesRight.appendChild(callPill);
        }
        if (isSaved || chat.is_pinned === 1) {
            const pIcon = document.createElement('span');
            pIcon.className = 'chat-pin-icon';
            pIcon.textContent = '📌';
            badgesRight.appendChild(pIcon);
        }
        if (chat.muted === 1) {
            const nmIcon = document.createElement('span');
            nmIcon.className = 'chat-notif-mute-icon';
            nmIcon.textContent = '🔕';
            badgesRight.appendChild(nmIcon);
        }
        if ((chat.type === 'group' || chat.type === 'channel') && getChatIdleStatus(chat).active) {
            const iIcon = document.createElement('span');
            iIcon.style.fontSize = '11px';
            iIcon.title = t('idle_short_badge');
            iIcon.textContent = '🌙';
            badgesRight.appendChild(iIcon);
        }
        if (chat.all_muted === 1 && chat.type !== 'system') {
            const mIcon = document.createElement('span');
            mIcon.style.fontSize = '11px';
            mIcon.title = stripLeadingEmoji(t('group_muted_short'));
            mIcon.textContent = '🔇';
            badgesRight.appendChild(mIcon);
        }
        if (chat.unread_count > 0) {
            const badge = document.createElement('span');
            badge.className = 'unread-badge';
            if (chat.muted === 1) badge.style.background = 'var(--text-muted)';
            badge.textContent = formatLocalizedCount(chat.unread_count);
            badgesRight.appendChild(badge);
        }
        sub.appendChild(badgesRight);

        body.appendChild(top);
        body.appendChild(sub);
        item.appendChild(avWrap);
        item.appendChild(body);
        container.appendChild(item);
    });

    updateChatFilterPillCounts();

    const baseTitle = formatSiteName();
    document.title = totalUnread > 0 ? `(${formatLocalizedCount(totalUnread)}) ${baseTitle}` : baseTitle;
}

async function acknowledgeActiveChatBottomRead(chatId) {
    const cid = Number(chatId || store.activeChatId || 0);
    if (!cid) return;
    const prevPending = Number((store.inChatUnreadByChat && store.inChatUnreadByChat[cid]) || 0);
    if (store.inChatUnreadByChat) store.inChatUnreadByChat[cid] = 0;
    const badgeEl = document.getElementById('scroll-bottom-unread-badge');
    if (badgeEl) {
        badgeEl.textContent = '';
        badgeEl.classList.add('hidden');
    }
    const list = store.messages[cid] || [];
    const realMsgs = list.filter(m => !m._optimistic && m.id > 0);
    if (realMsgs.length === 0) return;
    const maxId = realMsgs[realMsgs.length - 1].id;
    const chat = (store.chats || []).find(c => Number(c.id) === cid) || getActiveChat();
    if (chat && chat.is_ghost) return;
    if (prevPending > 0 || (chat && Number(chat.unread_count || 0) > 0) || (chat && maxId > Number(chat.last_read_id || 0))) {
        if (chat) {
            chat.unread_count = 0;
            chat.last_read_id = Math.max(Number(chat.last_read_id || 0), maxId);
        }
        renderChatList();
        const mr = await apiCall('message_read', { chat_id: cid, message_id: maxId });
        if (mr && mr.ok && mr.data && Array.isArray(mr.data.activated_burns) && mr.data.activated_burns.length > 0) {
            applyActivatedBurnsToStore(cid, mr.data.activated_burns);
        }
    }
}

function updateScrollBottomFab(fromUserScroll = false) {
    const vp = document.getElementById('messages-viewport');
    const scrollFab = document.getElementById('btn-scroll-bottom');
    const badgeEl = document.getElementById('scroll-bottom-unread-badge');
    if (!vp || !scrollFab) return;
    const cid = Number(store.activeChatId || 0);
    if (!cid) {
        scrollFab.classList.add('hidden');
        if (badgeEl) badgeEl.classList.add('hidden');
        return;
    }
    const maxScroll = Math.max(0, vp.scrollHeight - vp.clientHeight);
    const dist = Math.max(0, maxScroll - vp.scrollTop);
    let pendingUnread = Number((store.inChatUnreadByChat && store.inChatUnreadByChat[cid]) || 0);
    const hasMoreNewer = Boolean(store.hasMoreAfterByChat && store.hasMoreAfterByChat[cid]);

    // Clear unread badge and mark read once the user actually scrolls down to the latest bottom
    if (fromUserScroll && pendingUnread > 0 && dist <= 24 && !hasMoreNewer) {
        pendingUnread = 0;
        acknowledgeActiveChatBottomRead(cid);
    }

    if (badgeEl) {
        if (pendingUnread > 0) {
            badgeEl.textContent = formatLocalizedCount(pendingUnread > 99 ? '99+' : pendingUnread);
            badgeEl.classList.remove('hidden');
        } else {
            badgeEl.textContent = '';
            badgeEl.classList.add('hidden');
        }
    }

    if (pendingUnread > 0 || hasMoreNewer) {
        scrollFab.classList.remove('hidden');
        return;
    }
    if (maxScroll <= 80) {
        scrollFab.classList.add('hidden');
        return;
    }
    scrollFab.classList.toggle('hidden', dist < 160);
}

function openFilterPillContextMenu(filterKey, x, y) {
    const menu = document.getElementById('chat-context-menu');
    if (!menu) return;
    menu.innerHTML = '';

    const matchingUnreadIds = (store.chats || []).filter(c => {
        if ((c.unread_count || 0) <= 0) return false;
        if (filterKey === 'unread') return true;
        if (filterKey === 'dm') return c.type === 'dm';
        if (filterKey === 'group') return c.type === 'group';
        if (filterKey === 'channel') return c.type === 'channel';
        if (filterKey === 'secret') return c.type === 'secret';
        return true;
    }).map(c => c.id);

    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'chat-ctx-item';
    btn.innerHTML = `<span class="ctx-ico">✓✓</span><span>${esc(t('mark_filter_read_btn'))}${matchingUnreadIds.length > 0 ? ' (' + esc(formatLocalizedCount(matchingUnreadIds.length)) + ')' : ''}</span>`;
    btn.addEventListener('click', async e => {
        e.stopPropagation();
        closeChatContextMenu();
        if (matchingUnreadIds.length === 0) {
            toast(t('no_unread_in_filter_toast'));
            return;
        }
        const r = await apiCall('chats_mark_read_bulk', { chat_ids: matchingUnreadIds });
        if (r.ok) {
            if (r.data && Array.isArray(r.data.chats)) store.chats = r.data.chats;
            renderChatList();
            renderActiveChatHeader();
            toast(t('filter_marked_read_toast'));
        } else {
            toast(r.message || t('err_generic'), true);
        }
    });
    menu.appendChild(btn);

    menu.classList.remove('hidden');
    const vw = window.innerWidth;
    const vh = window.innerHeight;
    const mw = 230;
    const mh = 56;
    const left = Math.max(8, Math.min(vw - mw - 8, x));
    const top = Math.max(8, Math.min(vh - mh - 8, y));
    menu.style.left = left + 'px';
    menu.style.top = top + 'px';
}

function isTouchInsideRowMessageBounds(row, clientX) {
    if (!row || typeof clientX !== 'number' || !Number.isFinite(clientX)) return false;
    let minLeft = Infinity;
    let maxRight = -Infinity;
    const parts = row.querySelectorAll('.msg-bubble, .msg-select-chk, .avatar-sm');
    parts.forEach(el => {
        if (el.offsetParent === null && getComputedStyle(el).display === 'none') return;
        const r = el.getBoundingClientRect();
        if (r.width <= 0 && r.height <= 0) return;
        if (r.left < minLeft) minLeft = r.left;
        if (r.right > maxRight) maxRight = r.right;
    });
    if (!Number.isFinite(minLeft) || !Number.isFinite(maxRight)) return false;
    return clientX >= (minLeft - 6) && clientX <= (maxRight + 6);
}

/* A press that lands on an element's own scrollbar belongs to the scrollbar,
   not to the content inside it. Without this check, grabbing the thumb and
   holding it still armed the drag-select hold timer and selected whichever
   message happened to be level with the pointer. */
function m3PointOnScrollbarGutter(el, cx, cy) {
    if (!el) return false;
    const r = el.getBoundingClientRect();
    const gutX = el.offsetWidth - el.clientWidth;
    const gutY = el.offsetHeight - el.clientHeight;
    if (gutX <= 0 && gutY <= 0) return false;
    // The vertical scrollbar sits on the left in a right-to-left layout and on
    // the right otherwise, so test both edges instead of assuming one side.
    const onVert = gutX > 0 && (cx < r.left + gutX || cx > r.right - gutX);
    const onHorz = gutY > 0 && (cy < r.top + gutY || cy > r.bottom - gutY);
    return !!(onVert || onHorz);
}

const MessageDragSelector = {
    active: false,
    mode: '', // 'mouse' | 'touch'
    targetState: true, // true = select, false = deselect
    anchorMsgId: 0,
    initialSelected: null,
    lastClientY: 0,
    autoScrollRaf: 0,
    suppressClickUntil: 0,
    _mouseCandidate: null,
    _wiredViewport: false,

    getSelectableRows() {
        const vp = document.getElementById('messages-viewport');
        if (!vp) return [];
        return Array.from(vp.querySelectorAll('.msg-row[data-msg-id]'));
    },

    findRowIndexAtY(rows, clientY) {
        if (!rows.length) return -1;
        let bestIdx = 0;
        let bestDist = Infinity;
        for (let i = 0; i < rows.length; i++) {
            const r = rows[i].getBoundingClientRect();
            if (clientY >= r.top && clientY <= r.bottom) {
                return i;
            }
            const dist = clientY < r.top ? (r.top - clientY) : (clientY - r.bottom);
            if (dist < bestDist) {
                bestDist = dist;
                bestIdx = i;
            }
        }
        return bestIdx;
    },

    beginSession(mode, anchorId, clientY) {
        const vp = document.getElementById('messages-viewport');
        if (!vp) return;
        const numId = Number(anchorId);
        if (!numId) return;
        this.initialSelected = new Set(store.selectedMsgIds);
        this.targetState = !this.initialSelected.has(numId);
        this.anchorMsgId = numId;
        this.mode = mode;
        this.active = true;
        this.lastClientY = clientY;
        vp.classList.add('is-drag-selecting');
        if (window.getSelection) {
            try { window.getSelection().removeAllRanges(); } catch (e) {}
        }
        this.applyAtY(clientY);
        this.startAutoScrollLoop();
    },

    applyAtY(clientY) {
        if (!this.active) return;
        this.lastClientY = clientY;
        const rows = this.getSelectableRows();
        if (!rows.length) return;
        let anchorIdx = rows.findIndex(r => Number(r.dataset.msgId) === this.anchorMsgId);
        if (anchorIdx < 0) anchorIdx = 0;
        const curIdx = this.findRowIndexAtY(rows, clientY);
        if (curIdx < 0) return;

        const lo = Math.min(anchorIdx, curIdx);
        const hi = Math.max(anchorIdx, curIdx);

        const nextSet = new Set(this.initialSelected);
        for (let i = lo; i <= hi; i++) {
            const mid = Number(rows[i].dataset.msgId);
            if (!mid) continue;
            if (this.targetState) {
                nextSet.add(mid);
            } else {
                nextSet.delete(mid);
            }
        }
        store.selectedMsgIds = nextSet;
        syncMultiSelectUI();
    },

    startAutoScrollLoop() {
        if (this.autoScrollRaf) cancelAnimationFrame(this.autoScrollRaf);
        const step = () => {
            if (!this.active) {
                this.autoScrollRaf = 0;
                return;
            }
            const vp = document.getElementById('messages-viewport');
            if (vp) {
                const rect = vp.getBoundingClientRect();
                const edgeZone = this.mode === 'touch' ? 78 : 58;
                const maxSpeed = this.mode === 'touch' ? 18 : 14;
                let delta = 0;
                if (this.lastClientY < rect.top + edgeZone) {
                    const ratio = Math.min(1.25, Math.max(0.18, (rect.top + edgeZone - this.lastClientY) / edgeZone));
                    delta = -Math.round(maxSpeed * ratio);
                } else if (this.lastClientY > rect.bottom - edgeZone) {
                    const ratio = Math.min(1.25, Math.max(0.18, (this.lastClientY - (rect.bottom - edgeZone)) / edgeZone));
                    delta = Math.round(maxSpeed * ratio);
                }
                if (delta !== 0) {
                    const prevScroll = vp.scrollTop;
                    vp.scrollTop += delta;
                    if (vp.scrollTop !== prevScroll) {
                        this.applyAtY(this.lastClientY);
                    }
                }
            }
            this.autoScrollRaf = requestAnimationFrame(step);
        };
        this.autoScrollRaf = requestAnimationFrame(step);
    },

    endSession() {
        if (!this.active && !this._mouseCandidate) return;
        const wasActive = this.active;
        this.active = false;
        this.mode = '';
        if (this._mouseHoldTimer) {
            clearTimeout(this._mouseHoldTimer);
            this._mouseHoldTimer = 0;
        }
        this._mouseCandidate = null;
        if (this.autoScrollRaf) {
            cancelAnimationFrame(this.autoScrollRaf);
            this.autoScrollRaf = 0;
        }
        const vp = document.getElementById('messages-viewport');
        if (vp) vp.classList.remove('is-drag-selecting');
        if (wasActive) {
            this.suppressClickUntil = Date.now() + 180;
            if (store.selectedMsgIds.size === 0) {
                clearMessageSelection();
            } else {
                syncMultiSelectUI();
            }
        }
    },

    ensureViewportWired() {
        if (this._wiredViewport) return;
        const vp = document.getElementById('messages-viewport');
        if (!vp) return;
        this._wiredViewport = true;

        vp.addEventListener('selectstart', (e) => {
            e.preventDefault();
        });

        vp.addEventListener('scroll', () => {
            if (this.active) {
                this.applyAtY(this.lastClientY);
            }
        }, { passive: true });

        // Mobile Touch Drag-Select + Simultaneous Auto-Scroll while in Selection Mode
        let touchSelCand = null;
        let touchSelHoldTimer = 0;
        const clearTouchSelCand = () => {
            if (touchSelHoldTimer) {
                clearTimeout(touchSelHoldTimer);
                touchSelHoldTimer = 0;
            }
            touchSelCand = null;
        };

        vp.addEventListener('touchstart', (e) => {
            if (store.selectedMsgIds.size === 0 || e.touches.length !== 1) return;
            const t0 = e.touches[0];
            const anchorRow = (e.target && e.target.closest('.msg-row[data-msg-id]')) || null;
            if (!anchorRow || !anchorRow.dataset.msgId) return;
            // Item #17: Only start touch hold-and-drag selection inside the horizontal alignment zone of the message
            if (!isTouchInsideRowMessageBounds(anchorRow, t0.clientX)) return;
            const anchorId = Number(anchorRow.dataset.msgId);
            if (!anchorId) return;

            clearTouchSelCand();
            touchSelCand = {
                anchorId,
                startX: t0.clientX,
                startY: t0.clientY,
                curY: t0.clientY
            };
            touchSelHoldTimer = setTimeout(() => {
                if (touchSelCand && store.selectedMsgIds.size > 0 && !this.active) {
                    const c = touchSelCand;
                    touchSelCand = null;
                    if (navigator.vibrate) { try { navigator.vibrate(12); } catch (err) {} }
                    this.beginSession('touch', c.anchorId, c.curY);
                }
            }, 175);
        }, { passive: true });

        const onTouchMoveGlobal = (e) => {
            if (!e || e._m3DragHandled) return;
            e._m3DragHandled = true;
            if (this._postHoldDragCandidate && e.touches && e.touches.length === 1) {
                const t0 = e.touches[0];
                const dyHold = t0.clientY - this._postHoldDragCandidate.startY;
                if (Math.abs(dyHold) >= 16) {
                    const cand = this._postHoldDragCandidate;
                    this._postHoldDragCandidate = null;
                    if (e.cancelable) e.preventDefault();
                    const appDlg = document.getElementById('app-modal');
                    if (appDlg && appDlg.open && appDlg.classList.contains('modal-compact-menu')) {
                        closeModal();
                    }
                    this.beginSession('touch', cand.anchorId, t0.clientY);
                    return;
                }
            }
            if (this.active && this.mode === 'touch') {
                if (e.touches && e.touches.length === 1) {
                    if (e.cancelable) e.preventDefault();
                    this.applyAtY(e.touches[0].clientY);
                }
                return;
            }
            if (store.selectedMsgIds.size === 0 || !touchSelCand || !e.touches || e.touches.length !== 1) return;
            const t0 = e.touches[0];
            touchSelCand.curY = t0.clientY;
            const dx = t0.clientX - touchSelCand.startX;
            const dy = t0.clientY - touchSelCand.startY;
            if (Math.abs(dy) >= 7 || Math.abs(dx) >= 12) {
                if (e.cancelable) e.preventDefault();
                const c = touchSelCand;
                clearTouchSelCand();
                this.beginSession('touch', c.anchorId, t0.clientY);
            }
        };
        vp.addEventListener('touchmove', onTouchMoveGlobal, { passive: false });
        window.addEventListener('touchmove', onTouchMoveGlobal, { passive: false });

        const finishTouchDrag = (e) => {
            this._postHoldDragCandidate = null;
            clearTouchSelCand();
            if (this.active && this.mode === 'touch') {
                this.endSession();
                if (e && e.cancelable) e.preventDefault();
            }
        };
        vp.addEventListener('touchend', finishTouchDrag, { passive: false });
        vp.addEventListener('touchcancel', finishTouchDrag, { passive: true });
        window.addEventListener('touchend', finishTouchDrag, { passive: false });
        window.addEventListener('touchcancel', finishTouchDrag, { passive: true });

        // Desktop left-click + hold or drag up/down anywhere across message rows (including opposite empty row space)
        vp.addEventListener('mousedown', (e) => {
            if (e.button !== 0) return;
            if (store.selectedMsgIds.size === 0 && e.target && e.target.closest('button, a, input, textarea, select, .m3-aud-range, .lcw-mini-tool')) return;
            // Pressing and holding the scrollbar thumb is a scroll, never a
            // request to select: the old behaviour selected whatever row sat
            // level with the pointer once the hold timer ran out.
            if (m3PointOnScrollbarGutter(vp, e.clientX, e.clientY)) return;
            const row = (e.target && e.target.closest('.msg-row[data-msg-id]')) || null;
            let anchorRow = row;
            if (!anchorRow) {
                const rows = this.getSelectableRows();
                const idx = this.findRowIndexAtY(rows, e.clientY);
                if (idx >= 0) anchorRow = rows[idx];
            }
            if (!anchorRow || !anchorRow.dataset.msgId) return;
            const anchorId = Number(anchorRow.dataset.msgId);
            if (!anchorId) return;

            this._mouseCandidate = {
                anchorId,
                startX: e.clientX,
                startY: e.clientY,
                curY: e.clientY
            };
            if (this._mouseHoldTimer) clearTimeout(this._mouseHoldTimer);
            this._mouseHoldTimer = setTimeout(() => {
                if (this._mouseCandidate && !this.active) {
                    const cand = this._mouseCandidate;
                    this._mouseCandidate = null;
                    this.beginSession('mouse', cand.anchorId, cand.curY);
                }
            }, 340);

            const onWinMove = (ev) => {
                if (this.active && this.mode === 'mouse') {
                    this.applyAtY(ev.clientY);
                    return;
                }
                if (!this._mouseCandidate) return;
                this._mouseCandidate.curY = ev.clientY;
                const dx = ev.clientX - this._mouseCandidate.startX;
                const dy = ev.clientY - this._mouseCandidate.startY;
                if (Math.abs(dx) > 14 && Math.abs(dx) > Math.abs(dy) * 1.35) {
                    // Horizontal swipe-to-reply gesture: cancel drag-select hold candidate
                    if (this._mouseHoldTimer) { clearTimeout(this._mouseHoldTimer); this._mouseHoldTimer = 0; }
                    this._mouseCandidate = null;
                    return;
                }
                if (Math.abs(dy) >= 8 && Math.abs(dy) >= Math.abs(dx) * 0.75) {
                    if (this._mouseHoldTimer) { clearTimeout(this._mouseHoldTimer); this._mouseHoldTimer = 0; }
                    const cand = this._mouseCandidate;
                    this._mouseCandidate = null;
                    this.beginSession('mouse', cand.anchorId, ev.clientY);
                }
            };

            const onWinUp = () => {
                if (this._mouseHoldTimer) { clearTimeout(this._mouseHoldTimer); this._mouseHoldTimer = 0; }
                window.removeEventListener('mousemove', onWinMove);
                window.removeEventListener('mouseup', onWinUp);
                this.endSession();
            };

            window.addEventListener('mousemove', onWinMove);
            window.addEventListener('mouseup', onWinUp);
        });

        vp.addEventListener('click', (e) => {
            if (Date.now() < this.suppressClickUntil) {
                e.preventDefault();
                e.stopPropagation();
                return;
            }
            if (store.selectedMsgIds.size > 0) {
                const row = e.target && e.target.closest('.msg-row[data-msg-id]');
                if (row && row.dataset.msgId) {
                    e.preventDefault();
                    e.stopPropagation();
                    e.stopImmediatePropagation();
                    toggleMessageSelection(Number(row.dataset.msgId));
                }
            }
        }, true);
    }
};

function clearMessageSelection() {
    store.selectedMsgIds.clear();
    const vp = document.getElementById('messages-viewport');
    if (vp) {
        vp.classList.remove('selection-mode-active');
        vp.querySelectorAll('.msg-row.msg-selected').forEach(r => r.classList.remove('msg-selected'));
        vp.querySelectorAll('.msg-select-chk').forEach(chk => { chk.textContent = ''; });
    }
    const bar = document.getElementById('multi-select-bar');
    if (bar) {
        bar.classList.add('hidden');
        bar.innerHTML = '';
    }
}

function toggleMessageSelection(msgId) {
    const id = Number(msgId);
    if (!id) return;
    if (store.selectedMsgIds.has(id)) {
        store.selectedMsgIds.delete(id);
    } else {
        store.selectedMsgIds.add(id);
    }
    syncMultiSelectUI();
}

function syncMultiSelectUI() {
    const chat = getActiveChat();
    const vp = document.getElementById('messages-viewport');
    const bar = document.getElementById('multi-select-bar');
    if (!chat || !vp || !bar) {
        clearMessageSelection();
        return;
    }
    if (store.selectedMsgIds.size === 0) {
        if (MessageDragSelector.active) {
            vp.classList.add('selection-mode-active');
            vp.querySelectorAll('.msg-row[data-msg-id]').forEach(row => {
                row.classList.remove('msg-selected');
                const chk = row.querySelector('.msg-select-chk');
                if (chk) chk.textContent = '';
            });
            bar.classList.add('hidden');
            bar.innerHTML = '';
            return;
        }
        clearMessageSelection();
        return;
    }

    const list = store.messages[chat.id] || [];
    const selectedMsgs = list.filter(m => m.kind !== 'system' && store.selectedMsgIds.has(Number(m.id)));
    if (selectedMsgs.length === 0) {
        if (!MessageDragSelector.active) clearMessageSelection();
        return;
    }

    vp.classList.add('selection-mode-active');
    vp.querySelectorAll('.msg-row[data-msg-id]').forEach(row => {
        const mid = Number(row.dataset.msgId);
        const sel = store.selectedMsgIds.has(mid);
        row.classList.toggle('msg-selected', sel);
        const chk = row.querySelector('.msg-select-chk');
        if (chk) chk.textContent = sel ? '✓' : '';
    });

    // Compute strict INTERSECTION of allowed actions across ALL selected messages (Item #1 & #12)
    const isSystemChat = (chat.type === 'system');
    const isSuperOrOwner = (store.user && store.user.role === 'superadmin') || chat.my_role === 'owner';
    const myPerms = chat.my_perms || {};
    const canDeleteOthers = !isSystemChat && (isSuperOrOwner || (chat.my_role === 'admin' && myPerms.delete_messages !== 0));

    const allCanCopy = selectedMsgs.every(m => {
        const txt = (store.decryptedTextCache[m.id] || m.body || '').trim();
        return txt.length > 0 && canCopyMessageAction(m, chat);
    });
    const allCanForward = !isSystemChat && selectedMsgs.every(m => canForwardOrSaveMessage(m, chat));
    const allCanDeleteEveryone = !isSystemChat && !chat.is_ghost && selectedMsgs.every(m => (store.user && m.user_id === store.user.id) || canDeleteOthers);
    const allCanDeleteMe = !isSystemChat && !chat.is_ghost && selectedMsgs.length > 0;

    bar.innerHTML = '';
    const left = document.createElement('div');
    left.className = 'multi-select-left';

    const cancelBtn = document.createElement('button');
    cancelBtn.type = 'button';
    cancelBtn.className = 'multi-select-close-btn';
    cancelBtn.title = t('clear_selection_btn');
    cancelBtn.setAttribute('aria-label', t('clear_selection_btn'));
    cancelBtn.textContent = '✕';
    cancelBtn.addEventListener('click', () => clearMessageSelection());

    const cntSpan = document.createElement('span');
    cntSpan.className = 'multi-select-count';
    cntSpan.textContent = t('selected_msgs_count').replace('{n}', formatLocalizedCount(selectedMsgs.length));
    left.appendChild(cancelBtn);
    left.appendChild(cntSpan);

    const actions = document.createElement('div');
    actions.className = 'multi-select-actions';

    const makeMsPill = (ico, lbl, cls, onClick) => {
        const b = document.createElement('button');
        b.type = 'button';
        b.className = 'ms-pill-btn' + (cls ? (' ' + cls) : '');
        const ic = document.createElement('span');
        ic.className = 'ms-ico';
        ic.textContent = ico;
        const tx = document.createElement('span');
        tx.className = 'ms-lbl';
        tx.textContent = stripLeadingEmoji(lbl);
        b.appendChild(ic);
        b.appendChild(tx);
        b.addEventListener('click', onClick);
        return b;
    };

    if (allCanCopy) {
        actions.appendChild(makeMsPill('📋', t('copy_text'), '', async () => {
            const joined = selectedMsgs.map(m => (store.decryptedTextCache[m.id] || m.body || '').trim()).filter(Boolean).join('\n\n');
            await copyTextToClipboard(joined);
            clearMessageSelection();
            toast(t('bulk_copied_toast'));
        }));
    }

    if (allCanForward) {
        actions.appendChild(makeMsPill('↪', t('forward'), 'primary', () => openForwardMessageModal(selectedMsgs, false)));
        actions.appendChild(makeMsPill('🕵️', t('forward_anon_btn'), '', () => openForwardMessageModal(selectedMsgs, true)));
    }

    if (allCanDeleteMe) {
        actions.appendChild(makeMsPill('🗑️', t('delete_me'), '', async () => {
            const ids = selectedMsgs.map(m => m.id);
            const ap = await askApproval({
                title: '🗑️ ' + t('delete_me'),
                desc: t('ask_del_msg_me') + ` (${formatLocalizedCount(ids.length)})`,
                danger: true,
                icon: '🗑️'
            });
            if (!ap.approved) return;
            const r = await apiCall('messages_bulk_delete', { chat_id: chat.id, message_ids: ids, mode: 'me' });
            if (r.ok) {
                clearMessageSelection();
                await selectChat(chat.id, { preserveScrollBottom: true });
                toast(t('bulk_deleted_toast'));
            } else {
                toast(r.message || t('err_generic'), true);
            }
        }));
    }

    if (allCanDeleteEveryone) {
        actions.appendChild(makeMsPill('🗑️', t('delete_all'), 'danger', async () => {
            const ids = selectedMsgs.map(m => m.id);
            const ap = await askApproval({
                title: '🗑️ ' + t('delete_all'),
                desc: t('ask_del_msg_all') + ` (${formatLocalizedCount(ids.length)})`,
                danger: true,
                icon: '🗑️'
            });
            if (!ap.approved) return;
            const r = await apiCall('messages_bulk_delete', { chat_id: chat.id, message_ids: ids, mode: 'everyone' });
            if (r.ok) {
                clearMessageSelection();
                await selectChat(chat.id, { preserveScrollBottom: true });
                toast(t('bulk_deleted_toast'));
            } else {
                toast(r.message || t('err_generic'), true);
            }
        }));
    }

    bar.appendChild(left);
    bar.appendChild(actions);
    bar.classList.remove('hidden');
}

function collectActiveInlineMediaStatesInViewport() {
    const vp = document.getElementById('messages-viewport');
    if (!vp) return [];
    const found = [];
    // 1. Inline <video> (both standard video bubbles and circular video notes — NOT #universal-media-player)
    vp.querySelectorAll('video[data-inline-msg-id]').forEach(vid => {
        const msgId = Number(vid.getAttribute('data-inline-msg-id') || 0);
        if (!msgId) return;
        const wasPlaying = !vid.paused && !vid.ended;
        const curTime = Number(vid.currentTime) || 0;
        if (wasPlaying || curTime > 0.25) {
            found.push({
                kind: 'video',
                msgId,
                fileId: Number(vid.getAttribute('data-inline-file-id') || 0),
                currentTime: curTime,
                playbackRate: Number(vid.playbackRate) || 1,
                unmuted: !vid.muted,
                wasPlaying,
                el: vid
            });
        }
    });
    // 2. Inline custom audio/voice players (.m3-audio-player where wrap._audioEl holds the <audio>)
    vp.querySelectorAll('.m3-audio-player[data-inline-msg-id]').forEach(wrap => {
        const aud = wrap._audioEl;
        const msgId = Number(wrap.getAttribute('data-inline-msg-id') || 0);
        if (!aud || !msgId) return;
        const wasPlaying = !aud.paused && !aud.ended;
        const curTime = Number(aud.currentTime) || 0;
        if (wasPlaying || curTime > 0.25) {
            found.push({
                kind: 'audio',
                msgId,
                fileId: Number(wrap.getAttribute('data-inline-file-id') || 0),
                currentTime: curTime,
                playbackRate: Number(aud.playbackRate) || 1,
                unmuted: !aud.muted,
                wasPlaying,
                el: aud
            });
        }
    });
    return found;
}

function suspendActiveChatInlineMedia(leavingChatId) {
    const cid = Number(leavingChatId || store.activeChatId || 0);
    if (!store.inlineMediaResumeByChat) store.inlineMediaResumeByChat = {};
    if (!store.inlineMediaSavedPosByMsg) store.inlineMediaSavedPosByMsg = {};
    const states = collectActiveInlineMediaStatesInViewport();
    let playingEntry = null;
    for (const st of states) {
        if (st.currentTime > 0.15) {
            store.inlineMediaSavedPosByMsg[st.msgId] = {
                currentTime: st.currentTime,
                playbackRate: st.playbackRate
            };
        }
        if (st.wasPlaying) {
            playingEntry = {
                kind: st.kind,
                msgId: st.msgId,
                fileId: st.fileId,
                currentTime: st.currentTime,
                playbackRate: st.playbackRate,
                unmuted: st.unmuted
            };
            try { st.el.pause(); } catch (e) {}
        }
    }
    if (cid > 0) {
        if (playingEntry) {
            store.inlineMediaResumeByChat[cid] = playingEntry;
        } else {
            delete store.inlineMediaResumeByChat[cid];
        }
    }
}

function applyInlineMediaStateSnapshot(entry) {
    if (!entry || !entry.msgId) return;
    const vp = document.getElementById('messages-viewport');
    if (!vp) return;
    if (entry.fileId && store.loadedMediaIds) {
        store.loadedMediaIds.add(entry.fileId);
    }
    if (entry.kind === 'video') {
        let vid = vp.querySelector(`video[data-inline-msg-id="${entry.msgId}"]`);
        if (!vid) {
            // If lazy placeholder was rendered, trigger load first
            const row = vp.querySelector(`.msg-row[data-msg-id="${entry.msgId}"]`);
            const ph = row ? row.querySelector('.media-lazy-placeholder, .video-note-lazy-placeholder') : null;
            if (ph) ph.click();
            vid = vp.querySelector(`video[data-inline-msg-id="${entry.msgId}"]`);
        }
        if (!vid) return;
        const applyVidSeekAndResume = () => {
            try {
                if (entry.playbackRate && Math.abs((vid.playbackRate || 1) - entry.playbackRate) > 0.02) {
                    vid.playbackRate = entry.playbackRate;
                }
                if (entry.currentTime > 0.1 && Math.abs((vid.currentTime || 0) - entry.currentTime) > 0.35) {
                    vid.currentTime = entry.currentTime;
                }
                if (entry.unmuted !== undefined) {
                    vid.muted = !entry.unmuted;
                }
                if (entry.wasPlaying !== false) {
                    const p = vid.play();
                    if (p && typeof p.catch === 'function') p.catch(() => {});
                    const badge = vid.parentElement && vid.parentElement.querySelector('.video-note-badge');
                    if (badge && !vid.muted) badge.textContent = '🔊';
                }
            } catch (e) {}
        };
        if (vid.readyState >= 1) applyVidSeekAndResume();
        else vid.addEventListener('loadedmetadata', applyVidSeekAndResume, { once: true });
    } else if (entry.kind === 'audio') {
        let wrap = vp.querySelector(`.m3-audio-player[data-inline-msg-id="${entry.msgId}"]`);
        if (!wrap) {
            const row = vp.querySelector(`.msg-row[data-msg-id="${entry.msgId}"]`);
            const ph = row ? row.querySelector('.media-lazy-placeholder') : null;
            if (ph) ph.click();
            wrap = vp.querySelector(`.m3-audio-player[data-inline-msg-id="${entry.msgId}"]`);
        }
        if (!wrap || !wrap._audioEl) return;
        const aud = wrap._audioEl;
        const applyAudSeekAndResume = () => {
            try {
                if (entry.playbackRate && Math.abs((aud.playbackRate || 1) - entry.playbackRate) > 0.02) {
                    aud.playbackRate = entry.playbackRate;
                    if (wrap._rateBtn) wrap._rateBtn.textContent = entry.playbackRate + 'x';
                }
                if (entry.currentTime > 0.1 && Math.abs((aud.currentTime || 0) - entry.currentTime) > 0.35) {
                    aud.currentTime = entry.currentTime;
                }
                if (typeof wrap._syncSliderVisual === 'function') wrap._syncSliderVisual();
                if (entry.wasPlaying !== false) {
                    const p = aud.play();
                    if (p && typeof p.catch === 'function') p.catch(() => {});
                }
            } catch (e) {}
        };
        if (aud.readyState >= 1) applyAudSeekAndResume();
        else aud.addEventListener('loadedmetadata', applyAudSeekAndResume, { once: true });
    }
}

function restoreActiveChatInlineMediaIfAny(chatId) {
    const cid = Number(chatId || 0);
    if (!cid || !store.inlineMediaResumeByChat || !store.inlineMediaResumeByChat[cid]) return;
    const saved = store.inlineMediaResumeByChat[cid];
    delete store.inlineMediaResumeByChat[cid];
    applyInlineMediaStateSnapshot(Object.assign({}, saved, { wasPlaying: true }));
}

function isDraftSyncAllowedForChat(chatId) {
    const cid = Number(chatId || 0);
    if (!cid || !Array.isArray(store.chats)) return false;
    const c = store.chats.find(x => Number(x.id) === cid);
    if (!c) return false;
    // Item #11 & #12: Never sync drafts for Secret Chats or read-only System Chat
    return c.type !== 'secret' && c.type !== 'system';
}

const DraftSyncManager = {
    timer: null,
    debounceTimer: null,
    busy: false,
    _inflightPromise: null,
    lastLocalKeystrokeAt: 0,
    normalizeTsMs(rawTs) {
        const n = Number(rawTs || 0);
        if (!Number.isFinite(n) || n <= 0) return 0;
        return n < 100000000000 ? Math.round(n * 1000) : Math.round(n);
    },
    hasDirtyDrafts() {
        if (!store.draftMetaByChat) return false;
        return Object.keys(store.draftMetaByChat).some(k => {
            const m = store.draftMetaByChat[k];
            return Boolean(m && m.dirty && isDraftSyncAllowedForChat(Number(k)));
        });
    },
    initFromBootUser(userObj) {
        if (!store.chatDrafts) store.chatDrafts = {};
        if (!store.draftMetaByChat) store.draftMetaByChat = {};
        const initMap = (userObj && userObj.synced_drafts && typeof userObj.synced_drafts === 'object') ? userObj.synced_drafts : {};
        Object.keys(initMap).forEach(k => {
            const cid = Number(k);
            if (!cid || !isDraftSyncAllowedForChat(cid)) return;
            const entry = initMap[k];
            if (!entry || typeof entry !== 'object') return;
            const txt = typeof entry.text === 'string' ? entry.text : '';
            const upAt = this.normalizeTsMs(entry.updated_at);
            const loc = store.draftMetaByChat[cid];
            if (loc && (loc.dirty || loc.updated_at > upAt)) return;
            store.draftMetaByChat[cid] = { text: txt, reply_to: Number(entry.reply_to || 0), updated_at: upAt, dirty: false };
            if (txt !== '') store.chatDrafts[cid] = txt;
            else delete store.chatDrafts[cid];
        });
        if (store.activeChatId && !store.editMsg && (Date.now() - this.lastLocalKeystrokeAt) > 1200) {
            restoreChatComposerDraft(store.activeChatId);
        }
        this.restartLoop();
    },
    markDirty(chatId, textVal, replyId = 0) {
        const cid = Number(chatId || 0);
        if (!cid || !isDraftSyncAllowedForChat(cid)) return;
        if (!store.draftMetaByChat) store.draftMetaByChat = {};
        const prevAt = (store.draftMetaByChat[cid] && this.normalizeTsMs(store.draftMetaByChat[cid].updated_at)) || 0;
        const nowMs = Math.max(Date.now(), prevAt + 1);
        store.draftMetaByChat[cid] = {
            text: String(textVal || ''),
            reply_to: Number(replyId || 0),
            updated_at: nowMs,
            dirty: true
        };
        this.lastLocalKeystrokeAt = Date.now();
        if (store.settings && Number(store.settings.draft_sync_enabled) === 0) return;
        if (this.debounceTimer) clearTimeout(this.debounceTimer);
        this.debounceTimer = setTimeout(() => { this.syncNow(false); }, 650);
    },
    restartLoop() {
        if (this.timer) { clearInterval(this.timer); this.timer = null; }
        if (!store.user) return;
        if (store.settings && Number(store.settings.draft_sync_enabled) === 0) return;
        const sec = Math.max(2, Math.min(120, Number((store.settings && store.settings.draft_sync_interval_sec) || 3)));
        this.timer = setInterval(() => {
            if (!store.user || document.hidden) return;
            if (store.settings && Number(store.settings.draft_sync_enabled) === 0) return;
            this.syncNow(false);
        }, sec * 1000);
    },
    async flushBeforeSessionExit() {
        if (!store.user) return;
        if (this.debounceTimer) {
            clearTimeout(this.debounceTimer);
            this.debounceTimer = null;
        }
        if (store.activeChatId && !store.editMsg) {
            saveChatComposerDraft(store.activeChatId);
        }
        await this.syncNow(true);
    },
    resetLocalStateOnLogout() {
        if (this.timer) { clearInterval(this.timer); this.timer = null; }
        if (this.debounceTimer) { clearTimeout(this.debounceTimer); this.debounceTimer = null; }
        store.chatDrafts = {};
        store.draftMetaByChat = {};
        if (typeof TypingIndicatorManager !== 'undefined') TypingIndicatorManager.resetOnLogout();
        const ta = document.getElementById('composer-textarea');
        if (ta) ta.value = '';
    },
    async syncNow(forceFlush = false) {
        if (!store.user) return;
        if (store.settings && Number(store.settings.draft_sync_enabled) === 0) return;
        if (this._inflightPromise) {
            if (!forceFlush) return;
            try { await this._inflightPromise; } catch (e) {}
            if (!this.hasDirtyDrafts()) return;
        }
        this.busy = true;
        const runPass = async () => {
            const sentSnapshot = {};
            const updates = {};
            if (store.draftMetaByChat) {
                Object.keys(store.draftMetaByChat).forEach(k => {
                    const cid = Number(k);
                    const m = store.draftMetaByChat[k];
                    if (m && m.dirty && isDraftSyncAllowedForChat(cid)) {
                        const tsMs = this.normalizeTsMs(m.updated_at) || Date.now();
                        updates[cid] = { text: m.text || '', reply_to: m.reply_to || 0, updated_at: tsMs };
                        sentSnapshot[cid] = tsMs;
                        m.dirty = false;
                    }
                });
            }
            const r = await apiCall('draft_sync', { updates });
            if (!r.ok || !r.data) {
                Object.keys(sentSnapshot).forEach(k => {
                    const m = store.draftMetaByChat && store.draftMetaByChat[k];
                    if (m && m.updated_at === sentSnapshot[k]) m.dirty = true;
                });
                return;
            }
            if (r.data.enabled !== undefined && store.settings) {
                const prevInt = store.settings.draft_sync_interval_sec;
                store.settings.draft_sync_enabled = r.data.enabled ? 1 : 0;
                if (r.data.interval_sec) store.settings.draft_sync_interval_sec = Number(r.data.interval_sec);
                if (!r.data.enabled || prevInt !== store.settings.draft_sync_interval_sec) {
                    this.restartLoop();
                }
            }
            const srvDrafts = (r.data.drafts && typeof r.data.drafts === 'object') ? r.data.drafts : {};
            let listChanged = false;
            const seenServerCids = new Set();
            Object.keys(srvDrafts).forEach(k => {
                const cid = Number(k);
                if (!cid || !isDraftSyncAllowedForChat(cid)) return;
                seenServerCids.add(cid);
                const srv = srvDrafts[k] || {};
                const srvAt = this.normalizeTsMs(srv.updated_at);
                const srvTxt = String(srv.text || '');
                const loc = (store.draftMetaByChat && store.draftMetaByChat[cid]) ? store.draftMetaByChat[cid] : null;
                if (loc && (loc.dirty || this.normalizeTsMs(loc.updated_at) > srvAt)) return;
                const prevTxt = (store.chatDrafts && store.chatDrafts[cid]) || '';
                store.draftMetaByChat[cid] = { text: srvTxt, reply_to: Number(srv.reply_to || 0), updated_at: srvAt, dirty: false };
                if (srvTxt !== '') store.chatDrafts[cid] = srvTxt;
                else delete store.chatDrafts[cid];
                if (prevTxt !== srvTxt) {
                    listChanged = true;
                    if (cid === Number(store.activeChatId) && !store.editMsg && (Date.now() - this.lastLocalKeystrokeAt) > 1200) {
                        const ta = document.getElementById('composer-textarea');
                        if (ta && ta.value !== srvTxt) {
                            ta.value = srvTxt;
                            autoResizeComposerInput();
                        }
                    }
                }
            });
            if (store.draftMetaByChat) {
                Object.keys(store.draftMetaByChat).forEach(k => {
                    const cid = Number(k);
                    if (!cid || seenServerCids.has(cid) || !isDraftSyncAllowedForChat(cid)) return;
                    const loc = store.draftMetaByChat[cid];
                    if (loc && !loc.dirty && store.chatDrafts && store.chatDrafts[cid]) {
                        delete store.chatDrafts[cid];
                        loc.text = '';
                        listChanged = true;
                        if (cid === Number(store.activeChatId) && !store.editMsg && (Date.now() - this.lastLocalKeystrokeAt) > 1200) {
                            const ta = document.getElementById('composer-textarea');
                            if (ta && ta.value !== '') {
                                ta.value = '';
                                autoResizeComposerInput();
                            }
                        }
                    }
                });
            }
            if (listChanged) renderChatList();
        };
        this._inflightPromise = runPass();
        try {
            await this._inflightPromise;
        } finally {
            this._inflightPromise = null;
            this.busy = false;
            if (!forceFlush && this.hasDirtyDrafts()) {
                if (this.debounceTimer) clearTimeout(this.debounceTimer);
                this.debounceTimer = setTimeout(() => { this.syncNow(false); }, 250);
            }
        }
    }
};

/* ---------------- REAL-TIME EPHEMERAL TYPING INDICATOR MANAGER (DM, SECRET & GROUP ONLY; ZERO CHANNEL / ZERO GHOST) ---------------- */
const TypingIndicatorManager = {
    lastSentAtByChat: {},
    activeSentChatId: 0,
    idleStopTimer: null,
    expiryTimer: null,

    isChatTypeSupported(chat) {
        if (!chat || !chat.type) return false;
        return chat.type === 'dm' || chat.type === 'secret' || chat.type === 'group';
    },

    isDisplayEnabledForChat(chat) {
        if (!this.isChatTypeSupported(chat)) return false;
        if (chat.typing_display_enabled !== undefined && Number(chat.typing_display_enabled) === 0) {
            return false;
        }
        const supOv = String(chat.super_typing_override || 'inherit');
        if (supOv === 'force_off') return false;
        if (supOv === 'force_on') return true;
        const globPol = String((store.settings && store.settings.global_typing_policy) || 'default');
        if (globPol === 'force_off') return false;
        if (globPol === 'force_on') return true;
        if (chat.type === 'group' && Number(chat.show_typing ?? 1) === 0) return false;
        return true;
    },

    canBroadcastInChat(chat) {
        if (!store.user || !this.isChatTypeSupported(chat)) return false;
        // 1. Strict Ghost Mode prohibition: Ghost Mode NEVER records or transmits typing
        if (chat.is_ghost || Number(store.user.user_ghost_mode) === 1) return false;
        if (Number(store.user.ban_send) === 1 || Number(chat.my_mute_send) === 1) return false;
        if (chat.type === 'secret' && chat.secret_status && chat.secret_status !== 'active') return false;
        if (chat.type === 'group') {
            const isAdmOrOwn = store.user.role === 'superadmin' || chat.my_role === 'owner' || chat.my_role === 'admin' || Number(chat.owner_id) === Number(store.user.id);
            if (!isAdmOrOwn && Number(chat.all_muted) === 1) return false;
        }
        if (!this.isDisplayEnabledForChat(chat)) return false;

        // 2. Super-Admin Per-Chat Override
        const supChatOv = String(chat.super_typing_override || 'inherit');
        if (supChatOv === 'force_off') return false;
        if (supChatOv === 'force_on') return true;

        // 3. Super-Admin Per-User Override
        const admUserOv = String(store.user.admin_typing_override || 'inherit');
        if (admUserOv === 'force_off') return false;
        if (admUserOv === 'force_on') return true;

        // 4. Super-Admin Global Policy
        const globPol = String((store.settings && store.settings.global_typing_policy) || 'default');
        if (globPol === 'force_off') return false;
        if (globPol === 'force_on') return true;

        // 5. User Per-Chat / Per-Group Personal Mode
        const myMode = String(chat.my_typing_mode || 'inherit');
        if (myMode === 'off') return false;
        if (myMode === 'on') return true;

        // 6. User Global Account Setting
        return Number(store.user.show_my_typing ?? 1) !== 0;
    },

    onComposerInput() {
        const cid = Number(store.activeChatId || 0);
        if (!cid || !store.user || store.editMsg) {
            if (this.activeSentChatId) this.stopTyping(this.activeSentChatId);
            return;
        }
        const ta = document.getElementById('composer-textarea');
        const hasText = Boolean(ta && ta.value.trim().length > 0);
        if (!hasText) {
            if (this.activeSentChatId === cid) this.stopTyping(cid);
            return;
        }
        const chat = getActiveChat();
        if (!this.canBroadcastInChat(chat)) {
            if (this.activeSentChatId === cid) this.stopTyping(cid);
            return;
        }
        if (this.activeSentChatId && this.activeSentChatId !== cid) {
            this.stopTyping(this.activeSentChatId);
        }
        const now = Date.now();
        const lastAt = Number(this.lastSentAtByChat[cid] || 0);
        if ((now - lastAt) >= 2600 || this.activeSentChatId !== cid) {
            this.lastSentAtByChat[cid] = now;
            this.activeSentChatId = cid;
            apiCall('typing', { chat_id: cid, typing: 1 }).then(r => {
                if (r && r.ok && r.data && r.data.typing_tick) {
                    store.typingTick = String(r.data.typing_tick);
                }
            }).catch(() => {});
        }
        if (this.idleStopTimer) clearTimeout(this.idleStopTimer);
        this.idleStopTimer = setTimeout(() => {
            if (this.activeSentChatId === cid) {
                this.stopTyping(cid);
            }
        }, 3600);
    },

    stopTyping(chatId = 0) {
        const cid = Number(chatId || this.activeSentChatId || 0);
        if (this.idleStopTimer) {
            clearTimeout(this.idleStopTimer);
            this.idleStopTimer = null;
        }
        if (!cid) return;
        const wasSent = (this.activeSentChatId === cid) || Boolean(this.lastSentAtByChat[cid]);
        delete this.lastSentAtByChat[cid];
        if (this.activeSentChatId === cid) this.activeSentChatId = 0;
        if (wasSent && store.user) {
            apiCall('typing', { chat_id: cid, typing: 0 }).then(r => {
                if (r && r.ok && r.data && r.data.typing_tick) {
                    store.typingTick = String(r.data.typing_tick);
                }
            }).catch(() => {});
        }
    },

    resetOnLogout() {
        if (this.idleStopTimer) { clearTimeout(this.idleStopTimer); this.idleStopTimer = null; }
        if (this.expiryTimer) { clearTimeout(this.expiryTimer); this.expiryTimer = null; }
        this.lastSentAtByChat = {};
        this.activeSentChatId = 0;
        store.typingByChat = {};
    },

    getActiveTypers(chatId) {
        const cid = Number(chatId || 0);
        if (!cid || !store.typingByChat || !Array.isArray(store.typingByChat[cid])) return [];
        const nowSec = Math.floor(Date.now() / 1000);
        const myUid = store.user ? Number(store.user.id || 0) : 0;
        const fresh = store.typingByChat[cid].filter(u => u && Number(u.id) > 0 && Number(u.id) !== myUid && Number(u.expires_at || 0) > nowSec);
        if (fresh.length !== store.typingByChat[cid].length) {
            if (fresh.length > 0) store.typingByChat[cid] = fresh;
            else delete store.typingByChat[cid];
        }
        return fresh;
    },

    scheduleNextExpirySweep() {
        if (this.expiryTimer) {
            clearTimeout(this.expiryTimer);
            this.expiryTimer = null;
        }
        if (!store.typingByChat) return;
        const nowSec = Math.floor(Date.now() / 1000);
        let minExp = 0;
        Object.keys(store.typingByChat).forEach(k => {
            const arr = store.typingByChat[k];
            if (!Array.isArray(arr)) return;
            arr.forEach(u => {
                const ex = Number(u && u.expires_at ? u.expires_at : 0);
                if (ex > nowSec && (minExp === 0 || ex < minExp)) minExp = ex;
            });
        });
        if (minExp > 0) {
            const delayMs = Math.max(250, (minExp - nowSec) * 1000 + 220);
            this.expiryTimer = setTimeout(() => {
                const activeCid = Number(store.activeChatId || 0);
                if (activeCid > 0) {
                    this.getActiveTypers(activeCid);
                    renderActiveChatHeader();
                }
                this.scheduleNextExpirySweep();
            }, delayMs);
        }
    },

    applyServerTypingUsers(chatId, users, nextTypingTick = null) {
        if (nextTypingTick !== null && nextTypingTick !== undefined && String(nextTypingTick) !== '') {
            store.typingTick = String(nextTypingTick);
        }
        const cid = Number(chatId || 0);
        if (!cid) return;
        if (!store.typingByChat) store.typingByChat = {};
        const prevSig = JSON.stringify((store.typingByChat[cid] || []).map(x => `${x.id}:${x.name}`));
        const nowSec = Math.floor(Date.now() / 1000);
        const myUid = store.user ? Number(store.user.id || 0) : 0;
        const clean = Array.isArray(users)
            ? users
                .filter(u => u && Number(u.id) > 0 && Number(u.id) !== myUid)
                .map(u => ({
                    id: Number(u.id),
                    name: String(u.name || '').trim() || ('#' + u.id),
                    expires_at: Math.max(nowSec + 2, Number(u.expires_at || (nowSec + 6)))
                }))
            : [];
        if (clean.length > 0) {
            store.typingByChat[cid] = clean;
        } else {
            delete store.typingByChat[cid];
        }
        const nextSig = JSON.stringify((store.typingByChat[cid] || []).map(x => `${x.id}:${x.name}`));
        this.scheduleNextExpirySweep();
        if (prevSig !== nextSig && Number(store.activeChatId) === cid) {
            renderActiveChatHeader();
        }
    },

    resolveMaxVisibleGroupNames(names) {
        const vw = Number(window.innerWidth || 1024);
        const hdrInfoEl = document.querySelector('.chat-header-info');
        const hdrW = hdrInfoEl && hdrInfoEl.clientWidth > 0 ? hdrInfoEl.clientWidth : Math.max(140, vw - 170);
        let maxN = 3;
        if (vw <= 440 || hdrW < 210) {
            maxN = 1;
        } else if (vw <= 820 || hdrW < 350) {
            maxN = 2;
        } else {
            maxN = 3;
        }
        if (maxN >= 3 && names.length >= 3) {
            const len3 = (names[0].length + names[1].length + names[2].length);
            if (len3 > 46) maxN = 2;
        }
        if (maxN >= 2 && names.length >= 2) {
            const len2 = (names[0].length + names[1].length);
            if (len2 > (vw <= 820 ? 28 : 40)) maxN = 1;
        }
        return Math.max(1, Math.min(3, maxN));
    },

    formatGroupTypingLabel(typers) {
        const names = (typers || []).map(u => String(u.name || '').trim()).filter(Boolean);
        const total = names.length;
        if (total === 0) return '';
        if (total === 1) {
            return t('typing_one_group_tpl').replace('{n1}', names[0]);
        }
        const maxVis = Math.min(total, this.resolveMaxVisibleGroupNames(names));
        const rest = total - maxVis;
        if (rest <= 0) {
            if (total === 2) {
                return t('typing_two_group_tpl').replace('{n1}', names[0]).replace('{n2}', names[1]);
            }
            return t('typing_three_group_tpl').replace('{n1}', names[0]).replace('{n2}', names[1]).replace('{n3}', names[2]);
        }
        const restStr = formatLocalizedCount(rest);
        if (maxVis === 1) {
            return t('typing_more_one_tpl').replace('{n1}', names[0]).replace('{rest}', restStr);
        }
        if (maxVis === 2) {
            return t('typing_more_two_tpl').replace('{n1}', names[0]).replace('{n2}', names[1]).replace('{rest}', restStr);
        }
        return t('typing_more_three_tpl').replace('{n1}', names[0]).replace('{n2}', names[1]).replace('{n3}', names[2]).replace('{rest}', restStr);
    },

    buildTypingHeaderNode(labelText) {
        const wrap = document.createElement('span');
        wrap.className = 'hdr-typing-pill';
        wrap.id = 'active-chat-typing-pill';
        const dots = document.createElement('span');
        dots.className = 'hdr-typing-dots';
        dots.setAttribute('aria-hidden', 'true');
        dots.appendChild(document.createElement('span'));
        dots.appendChild(document.createElement('span'));
        dots.appendChild(document.createElement('span'));
        const txt = document.createElement('span');
        txt.className = 'hdr-typing-text';
        txt.textContent = labelText;
        wrap.appendChild(dots);
        wrap.appendChild(txt);
        return wrap;
    }
};

window.addEventListener('resize', () => {
    const cid = Number(store.activeChatId || 0);
    if (cid > 0 && TypingIndicatorManager.getActiveTypers(cid).length > 1) {
        renderActiveChatHeader();
    }
});

function clearChatTransientMediaStates() {
    if (store.revealedSpoilerMsgIds && store.revealedSpoilerMsgIds.clear) store.revealedSpoilerMsgIds.clear();
    if (store.playedSpoilerVideoIds && store.playedSpoilerVideoIds.clear) store.playedSpoilerVideoIds.clear();
    if (store.playingGifMsgIds && store.playingGifMsgIds.clear) store.playingGifMsgIds.clear();
}

function saveChatComposerDraft(chatId) {
    const cid = Number(chatId || 0);
    if (!cid) return;
    if (!store.chatDrafts) store.chatDrafts = {};
    const ta = document.getElementById('composer-textarea');
    if (!ta) return;
    if (store.editMsg && Number(store.editMsg.chat_id || cid) === cid) {
        // While editing an existing message, keep the pre-edit unsent draft intact rather than saving the edited body as a draft
        return;
    }
    const val = ta.value || '';
    const prevVal = store.chatDrafts[cid] || '';
    if (val !== '') {
        store.chatDrafts[cid] = val;
    } else {
        delete store.chatDrafts[cid];
    }
    if (val !== prevVal && isDraftSyncAllowedForChat(cid)) {
        DraftSyncManager.markDirty(cid, val, store.replyToMsg ? store.replyToMsg.id : 0);
    }
}

function restoreChatComposerDraft(chatId) {
    const cid = Number(chatId || 0);
    const ta = document.getElementById('composer-textarea');
    if (!ta) return;
    const savedVal = (cid && store.chatDrafts && typeof store.chatDrafts[cid] === 'string') ? store.chatDrafts[cid] : '';
    ta.value = savedVal;
    autoResizeComposerInput();
}

function cancelEditAndRestoreDraft() {
    const cid = Number(store.activeChatId || 0);
    const wasEditing = Boolean(store.editMsg);
    store.replyToMsg = null;
    store.editMsg = null;
    if (wasEditing) {
        const ta = document.getElementById('composer-textarea');
        const restored = (cid && store.preEditDraftByChat && typeof store.preEditDraftByChat[cid] === 'string')
            ? store.preEditDraftByChat[cid]
            : ((cid && store.chatDrafts && typeof store.chatDrafts[cid] === 'string') ? store.chatDrafts[cid] : '');
        if (cid && store.preEditDraftByChat) delete store.preEditDraftByChat[cid];
        if (ta) {
            ta.value = restored;
            if (cid) {
                if (restored !== '') store.chatDrafts[cid] = restored;
                else delete store.chatDrafts[cid];
            }
            autoResizeComposerInput();
        }
    }
    updateComposerContextBar();
}

function exitChatToMobileList() {
    if (store.activeChatId) {
        saveChatComposerDraft(store.activeChatId);
        suspendActiveChatInlineMedia(store.activeChatId);
    }
    if (store.editMsg) {
        cancelEditAndRestoreDraft();
    }
    const ta = document.getElementById('composer-textarea');
    if (ta) {
        ta.value = '';
        autoResizeComposerInput();
    }
    if (store.activeChatId) TypingIndicatorManager.stopTyping(store.activeChatId);
    clearMessageSelection();
    // Item #7: Leaving a chat re-covers all opened 🫣 spoilers and stops transient GIF play
    clearChatTransientMediaStates();
    store.activeChatId = null;
    const vp = document.getElementById('messages-viewport');
    if (vp) vp.replaceChildren();
    const shell = document.getElementById('messenger-shell');
    if (shell) shell.classList.remove('chat-open');
    const activeView = document.getElementById('active-chat-view');
    const emptyState = document.getElementById('empty-chat-state');
    if (activeView) activeView.classList.add('hidden');
    if (emptyState) emptyState.classList.remove('hidden');
    renderChatList();
    if (typeof LiveCallManager !== 'undefined' && LiveCallManager.onChatsSynced) {
        LiveCallManager.onChatsSynced(store.chats || []);
    }
}

/* Put the caret straight into the message box as soon as a chat is opened.
   Skipped on touch-first devices on purpose: focusing there would instantly cover
   the whole conversation with the on-screen keyboard. When the chat already holds an
   unsent draft, the caret lands at the end of that text so typing continues it. */
function focusComposerAfterChatOpen(opts) {
    if (opts && opts.skipComposerFocus) return;
    let finePointer = true;
    try {
        finePointer = !window.matchMedia || window.matchMedia('(hover: hover) and (pointer: fine)').matches;
    } catch (e) { finePointer = true; }
    if (!finePointer) return;
    const ta = document.getElementById('composer-textarea');
    if (!ta || ta.disabled || ta.readOnly) return;
    const actBar = document.getElementById('composer-active-bar');
    if (actBar && actBar.classList.contains('hidden')) return;   // read-only / banned chat
    if (ta.offsetParent === null) return;                        // composer not on screen
    try {
        ta.focus({ preventScroll: true });
        const end = (ta.value || '').length;
        if (typeof ta.setSelectionRange === 'function') ta.setSelectionRange(end, end);
    } catch (e) {
        try { ta.focus(); } catch (e2) {}
    }
}

async function selectChat(chatId, opts = {}) {
    if (store.ghostChat && store.ghostChat.id !== chatId) {
        store.ghostChat = null;
    } else if (store.ghostChat && store.chats.some(c => c.id === chatId)) {
        store.ghostChat = null;
    }
    store.inChatSearchActive = false;
    store.inChatSearchChatId = 0;
    const prevChatId = store.activeChatId;
    const switchedChat = prevChatId !== chatId;
    if (switchedChat && prevChatId) {
        TypingIndicatorManager.stopTyping(prevChatId);
        if (store.editMsg) {
            store.editMsg = null;
            if (store.preEditDraftByChat && typeof store.preEditDraftByChat[prevChatId] === 'string') {
                store.chatDrafts[prevChatId] = store.preEditDraftByChat[prevChatId];
                delete store.preEditDraftByChat[prevChatId];
            }
        } else {
            saveChatComposerDraft(prevChatId);
        }
        suspendActiveChatInlineMedia(prevChatId);
    }
    // Item #7: Switching chats re-covers opened 🫣 spoiler messages
    if (switchedChat) {
        clearChatTransientMediaStates();
    }
    store.activeChatId = chatId;
    store._chatSwitchSeq = Number(store._chatSwitchSeq || 0) + 1;
    const mySwitchSeq = store._chatSwitchSeq;
    const initScrollFab = document.getElementById('btn-scroll-bottom');
    if (initScrollFab && switchedChat) {
        initScrollFab.classList.add('hidden');
    }
    if (switchedChat) {
        clearMessageSelection();
        store.ttlIndex = 0;
        store.ttlExplicitOff = false;
        const searchBar = document.getElementById('in-chat-search-bar');
        const searchIn = document.getElementById('in-chat-search-input');
        if (searchBar) searchBar.classList.add('hidden');
        if (searchIn) searchIn.value = '';
    }
    if (switchedChat) {
        store.replyToMsg = null;
        store.editMsg = null;
        restoreChatComposerDraft(chatId);
    }
    updateComposerContextBar();
    syncTtlControlUI();
    autoResizeComposerInput();

    const shell = document.getElementById('messenger-shell');
    if (shell) shell.classList.add('chat-open');

    document.getElementById('empty-chat-state').classList.add('hidden');
    const activeView = document.getElementById('active-chat-view');
    activeView.classList.remove('hidden');

    renderChatList();
    renderActiveChatHeader();
    syncComposerHeightVar();
    if (typeof LiveCallManager !== 'undefined' && LiveCallManager.onChatsSynced) {
        LiveCallManager.onChatsSynced(store.chats || []);
    }

    const chat = getActiveChat();
    if (chat && chat.type === 'secret') {
        await E2EE.deriveChatKey(chat);
    }

    const wantUnreadAnchor = Boolean(switchedChat && !opts.aroundId && !opts.preserveScrollBottom && chat && (chat.unread_count || 0) > 0 && !chat.is_ghost);

    // Item #27: Immediately swap #messages-viewport before awaiting messages_list so previous chat's messages never flash!
    const vpEarly = document.getElementById('messages-viewport');
    if (switchedChat && vpEarly) {
        const cachedMsgs = store.messages[chatId];
        if (Array.isArray(cachedMsgs) && cachedMsgs.length > 0 && !opts.aroundId && !wantUnreadAnchor) {
            await renderMessagesViewport(true);
        } else {
            vpEarly.replaceChildren();
        }
    }

    const reqPayload = { chat_id: chatId, limit: 80 };
    if (opts.aroundId) {
        reqPayload.around_id = Number(opts.aroundId);
    } else if (wantUnreadAnchor) {
        reqPayload.unread_anchor = 1;
    }

    const res = await apiCall('messages_list', reqPayload);
    if (store._chatSwitchSeq !== mySwitchSeq || store.activeChatId !== chatId) {
        return;
    }
    if (res.ok) {
        store.messages[chatId] = res.data.messages || [];
        if (Array.isArray(res.data.typing_users)) {
            TypingIndicatorManager.applyServerTypingUsers(chatId, res.data.typing_users, res.data.typing_tick);
        }
        if (switchedChat && typeof window._m3WakeSyncPoll === 'function') {
            window._m3WakeSyncPoll();
        }
        if (chat) {
            chat.peer_last_read_id = res.data.peer_last_read_id || 0;
            chat._lastRenderedPeerRead = Number(res.data.peer_last_read_id || 0);
        }
        const anchorMsgId = Number(opts.aroundId || res.data.first_unread_id || 0);
        store.firstUnreadByChat[chatId] = Number(res.data.first_unread_id || 0);
        store.hasMoreBeforeByChat[chatId] = Boolean(res.data.has_more_before);
        store.hasMoreAfterByChat[chatId] = Boolean(res.data.has_more_after);
        store.loadingOlderByChat[chatId] = false;
        store.loadingNewerByChat[chatId] = false;

        await renderMessagesViewport(anchorMsgId <= 0);
        if (switchedChat) {
            restoreActiveChatInlineMediaIfAny(chatId);
        }
        if (anchorMsgId > 0) {
            const vp = document.getElementById('messages-viewport');
            const aroundRow = (opts.aroundId && vp) ? vp.querySelector(`.msg-row[data-msg-id="${Number(opts.aroundId)}"]`) : null;
            const targetEl = vp ? (aroundRow || vp.querySelector('.unread-divider-pill') || vp.querySelector(`.msg-row[data-msg-id="${anchorMsgId}"]`)) : null;
            if (vp && targetEl) {
                const offsetPad = aroundRow ? Math.max(48, Math.floor(vp.clientHeight * 0.28)) : 48;
                vp.scrollTop = Math.max(0, targetEl.offsetTop - offsetPad);
                updateScrollBottomFab();
                if (aroundRow) {
                    const bbl = aroundRow.querySelector('.msg-bubble') || aroundRow;
                    bbl.style.transition = 'box-shadow 0.35s ease, transform 0.25s ease';
                    bbl.style.boxShadow = '0 0 0 2.5px var(--accent), 0 8px 24px rgba(0, 150, 135, 0.28)';
                    setTimeout(() => {
                        if (bbl && bbl.isConnected) bbl.style.boxShadow = '';
                    }, 2200);
                }
            }
        }

        const list = store.messages[chatId];
        if (anchorMsgId > 0) {
            const vpChk = document.getElementById('messages-viewport');
            const distAfterAnchor = vpChk ? Math.max(0, (vpChk.scrollHeight - vpChk.clientHeight) - vpChk.scrollTop) : 0;
            const unreadBelow = list.filter(m => Number(m.id) >= anchorMsgId && Number(m.user_id) !== Number((store.user && store.user.id) || 0) && m.kind !== 'system').length;
            if (distAfterAnchor > 24 && unreadBelow > 0 && !opts.aroundId) {
                store.inChatUnreadByChat[chatId] = unreadBelow;
                updateScrollBottomFab(false);
            } else {
                store.inChatUnreadByChat[chatId] = 0;
            }
        } else {
            store.inChatUnreadByChat[chatId] = 0;
        }
        if (list.length > 0 && !opts.skipMarkRead && !(store.inChatUnreadByChat[chatId] > 0)) {
            // Mark read up to the last loaded message when positioned at bottom
            const maxId = list[list.length - 1].id;
            if (!res.data.has_more_after) {
                const mrRes = await apiCall('message_read', { chat_id: chatId, message_id: maxId });
                if (mrRes && mrRes.ok && mrRes.data && Array.isArray(mrRes.data.activated_burns) && mrRes.data.activated_burns.length > 0) {
                    applyActivatedBurnsToStore(chatId, mrRes.data.activated_burns);
                }
                if (chat) chat.unread_count = 0;
                renderChatList();
            }
        }
        updateScrollBottomFab(false);
        if (store.selectedMsgIds.size > 0) syncMultiSelectUI();
        focusComposerAfterChatOpen(opts);
    }
}

function renderActiveChatHeader() {
    const chat = getActiveChat();
    if (!chat) return;

    const isSaved = chat.type === 'saved';
    const isSystemChat = chat.type === 'system';
    const displayTitle = formatChatTitle(chat);
    renderAvatarNode(document.getElementById('active-chat-avatar'), displayTitle, chat.avatar, isSaved, isSystemChat);

    const titleEl = document.getElementById('active-chat-title');
    titleEl.innerHTML = '';
    if (isSaved) {
        titleEl.appendChild(makeHdrSvgNode(HDR_SVG.bookmark));
    } else if (isSystemChat) {
        titleEl.appendChild(makeHdrSvgNode(HDR_SVG.shield || HDR_SVG.lock));
    } else if (chat.type === 'secret') {
        titleEl.appendChild(makeHdrSvgNode(HDR_SVG.lock));
    }
    const tSpan = document.createElement('span');
    tSpan.className = 'chat-title-text';
    tSpan.textContent = displayTitle;
    titleEl.appendChild(tSpan);
    if (chat.peer && chat.peer.has_admin_badge) {
        titleEl.appendChild(createAdminBadgeNode());
    }
    if (chat.is_ghost) {
        const gPill = document.createElement('span');
        gPill.className = 'ghost-pill-badge';
        gPill.style.cssText = 'display:inline-flex;align-items:center;gap:4px';
        gPill.appendChild(makeHdrSvgNode(HDR_SVG.ghost));
        const gPillTxt = document.createElement('span');
        gPillTxt.textContent = stripLeadingEmoji(t('ghost_badge_short'));
        gPill.appendChild(gPillTxt);
        titleEl.appendChild(gPill);
    }

    const subEl = document.getElementById('active-chat-subtitle');
    subEl.innerHTML = '';
    const activeTypers = TypingIndicatorManager.isDisplayEnabledForChat(chat)
        ? TypingIndicatorManager.getActiveTypers(chat.id)
        : [];
    if (isSaved) {
        subEl.textContent = t('saved_messages_sub');
    } else if (isSystemChat) {
        subEl.textContent = t('system_chat_subtitle');
    } else if (chat.type === 'dm' || chat.type === 'secret') {
        if (chat.peer) {
            if (chat.type === 'secret') {
                subEl.appendChild(makeHdrSvgNode(HDR_SVG.lock));
                subEl.appendChild(document.createTextNode(' ' + stripLeadingEmoji(t('e2ee_header_badge')) + ' '));
            }
            if (activeTypers.length > 0) {
                subEl.appendChild(TypingIndicatorManager.buildTypingHeaderNode(t('typing_dm_active')));
            } else {
                // Item #2: Show only last-seen / online presence in chat header subtitle (do not append @id / @handle)
                const presNode = buildPeerPresenceNode(chat.peer);
                if (presNode) {
                    subEl.appendChild(presNode);
                }
            }
        }
    } else if (chat.type === 'group' && activeTypers.length > 0) {
        const grpTypingLbl = TypingIndicatorManager.formatGroupTypingLabel(activeTypers);
        subEl.appendChild(TypingIndicatorManager.buildTypingHeaderNode(grpTypingLbl));
    } else {
        // Channels & non-typing Groups: Channels NEVER display typing indicator
        let info = chat.type === 'system' ? stripLeadingEmoji(t('system_chat_title')) : `${formatMemberCount(chat.member_count || 1)} ${t('members')}`;
        if (chat.all_muted === 1 && chat.type !== 'system') info += ` • ${stripLeadingEmoji(t('group_muted_short'))}`;
        if (getChatIdleStatus(chat).active) info += ` • ${stripLeadingEmoji(t('idle_short_badge'))}`;
        subEl.textContent = info;
    }

    const notifMuteBtn = document.getElementById('btn-chat-notif-mute');
    if (notifMuteBtn) {
        notifMuteBtn.classList.toggle('hidden', !!chat.is_ghost);
        notifMuteBtn.innerHTML = chat.muted === 1 ? HDR_SVG.bellOff : HDR_SVG.bell;
        notifMuteBtn.title = chat.muted === 1 ? stripLeadingEmoji(t('unmute_notif_btn')) : stripLeadingEmoji(t('mute_notif_btn'));
    }

    const ghostBar = document.getElementById('ghost-mode-bar');
    if (ghostBar) {
        if (chat.is_ghost) {
            ghostBar.innerHTML = '';
            const gTxt = document.createElement('div');
            gTxt.style.cssText = 'font-weight:700;color:var(--text-main);flex:1;min-width:200px;display:flex;align-items:center;gap:6px';
            gTxt.appendChild(makeHdrSvgNode(HDR_SVG.ghost));
            const gBannerSpan = document.createElement('span');
            gBannerSpan.textContent = stripLeadingEmoji(t('ghost_banner_text'));
            gTxt.appendChild(gBannerSpan);
            const gActs = document.createElement('div');
            gActs.style.cssText = 'display:flex;gap:6px;flex-wrap:wrap;align-items:center';

            const joinNormBtn = document.createElement('button');
            joinNormBtn.type = 'button';
            joinNormBtn.className = 'btn btn-primary btn-sm';
            joinNormBtn.style.cssText = 'display:inline-flex;align-items:center;gap:5px';
            joinNormBtn.appendChild(makeHdrSvgNode(HDR_SVG.plus));
            joinNormBtn.appendChild(document.createTextNode(stripLeadingEmoji(t('ghost_join_normal_btn'))));
            joinNormBtn.addEventListener('click', () => joinGhostChatNormally(chat.id));

            const exitGhostBtn = document.createElement('button');
            exitGhostBtn.type = 'button';
            exitGhostBtn.className = 'btn btn-secondary btn-sm';
            exitGhostBtn.style.cssText = 'display:inline-flex;align-items:center;gap:5px';
            exitGhostBtn.appendChild(makeHdrSvgNode(HDR_SVG.close));
            exitGhostBtn.appendChild(document.createTextNode(stripLeadingEmoji(t('ghost_exit_btn'))));
            exitGhostBtn.addEventListener('click', () => exitGhostChatView());

            if (chat.type === 'group' || chat.type === 'channel') {
                gActs.appendChild(joinNormBtn);
            }
            gActs.appendChild(exitGhostBtn);
            ghostBar.appendChild(gTxt);
            ghostBar.appendChild(gActs);
            ghostBar.classList.remove('hidden');
        } else {
            ghostBar.classList.add('hidden');
            ghostBar.innerHTML = '';
        }
    }

    const repHeaderBtn = document.getElementById('btn-chat-report');
    if (repHeaderBtn) {
        repHeaderBtn.classList.toggle('hidden', isSaved || isSystemChat);
    }

    const muteAllBtn = document.getElementById('btn-group-mute-all');
    const isSuperOrOwner = (store.user && store.user.role === 'superadmin') || chat.my_role === 'owner';
    const myPerms = chat.my_perms || {};
    const canEditInfo = !isSystemChat && (isSuperOrOwner || (chat.my_role === 'admin' && myPerms.edit_info !== 0));
    const canPin = !isSystemChat && (isSaved || chat.type === 'dm' || chat.type === 'secret' || isSuperOrOwner || (chat.my_role === 'admin' && myPerms.pin_messages !== 0));
    const canPost = !isSystemChat && (isSuperOrOwner || (chat.my_role === 'admin' && myPerms.post_messages !== 0));

    if (chat.type === 'group' && canEditInfo) {
        muteAllBtn.classList.remove('hidden');
        muteAllBtn.innerHTML = chat.all_muted === 1 ? HDR_SVG.speaker : HDR_SVG.speakerOff;
        muteAllBtn.title = chat.all_muted === 1 ? stripLeadingEmoji(t('unfreeze_group_btn')) : stripLeadingEmoji(t('freeze_group_btn'));
    } else {
        muteAllBtn.classList.add('hidden');
    }

    const pinBar = document.getElementById('pinned-message-bar');
    if (chat.pinned_message) {
        pinBar.classList.remove('hidden');
        const pinLblEl = pinBar.querySelector('[data-i18n="pinned_label_plain"]');
        if (pinLblEl) {
            pinLblEl.textContent = (chat.pinned_message.scope === 'me') ? t('pinned_personal_tag') : t('pinned_label_plain');
        }
        document.getElementById('pinned-message-text').textContent = formatDynamicServerText(chat.pinned_message.body);
        document.getElementById('btn-unpin-msg').classList.toggle('hidden', isSystemChat || Boolean(chat.is_ghost));
    } else {
        pinBar.classList.add('hidden');
    }

    renderGlobalIdleBanner();
    const gIdle = getGlobalIdleStatus();
    const cIdle = getChatIdleStatus(chat);

    const secBar = document.getElementById('secret-approval-bar');
    const isPendingSecret = (chat.type === 'secret' && chat.secret_status === 'pending');
    if (secBar) {
        if (isPendingSecret) {
            secBar.innerHTML = '';
            const isInitiator = store.user && Number(chat.secret_initiator_id) === Number(store.user.id);
            const msgSpan = document.createElement('div');
            msgSpan.style.cssText = 'font-weight:700;flex:1;min-width:200px;display:flex;align-items:center;gap:6px';
            msgSpan.appendChild(makeHdrSvgNode(HDR_SVG.lock));
            msgSpan.appendChild(document.createTextNode(stripLeadingEmoji(isInitiator ? t('secret_req_sender_text') : t('secret_req_recipient_text'))));
            secBar.appendChild(msgSpan);

            const actWrap = document.createElement('div');
            actWrap.style.cssText = 'display:flex;gap:8px;flex-wrap:wrap';
            if (!isInitiator) {
                const accBtn = document.createElement('button');
                accBtn.type = 'button';
                accBtn.className = 'btn btn-primary btn-sm';
                accBtn.style.cssText = 'display:inline-flex;align-items:center;gap:5px';
                accBtn.appendChild(makeHdrSvgNode(HDR_SVG.check));
                accBtn.appendChild(document.createTextNode(stripLeadingEmoji(t('secret_accept_btn'))));
                accBtn.addEventListener('click', async () => {
                    accBtn.disabled = true;
                    await E2EE.ensureIdentityKeys();
                    const r = await apiCall('secret_chat_respond', {
                        chat_id: chat.id,
                        decision: 'accept',
                        pubkey: (store.user && store.user.pubkey) ? store.user.pubkey : ''
                    });
                    if (r.ok) {
                        store.chats = r.data.chats || store.chats;
                        toast(t('secret_accepted_toast'));
                        await selectChat(chat.id);
                    } else {
                        accBtn.disabled = false;
                        toast(r.message || t('err_generic'), true);
                    }
                });
                actWrap.appendChild(accBtn);
            }
            const decBtn = document.createElement('button');
            decBtn.type = 'button';
            decBtn.className = 'btn btn-danger btn-sm';
            decBtn.style.cssText = 'display:inline-flex;align-items:center;gap:5px';
            decBtn.appendChild(makeHdrSvgNode(HDR_SVG.close));
            decBtn.appendChild(document.createTextNode(stripLeadingEmoji(isInitiator ? t('secret_cancel_req_btn') : t('secret_decline_btn'))));
            decBtn.addEventListener('click', async () => {
                decBtn.disabled = true;
                const r = await apiCall('secret_chat_respond', {
                    chat_id: chat.id,
                    decision: isInitiator ? 'cancel' : 'decline'
                });
                if (r.ok) {
                    store.chats = r.data.chats || [];
                    showNoChatSelected();
                    toast(t('secret_declined_toast'));
                } else {
                    decBtn.disabled = false;
                    toast(r.message || t('err_generic'), true);
                }
            });
            actWrap.appendChild(decBtn);
            secBar.appendChild(actWrap);
            secBar.classList.remove('hidden');
        } else {
            secBar.classList.add('hidden');
            secBar.innerHTML = '';
        }
    }

    // Live Call Header Buttons & Active Call Banner (Schema v8)
    const btnVoiceCall = document.getElementById('btn-chat-voice-call');
    const btnVideoCall = document.getElementById('btn-chat-video-call');
    const callPol = chat.call_policy || {};
    const canShowCallBtns = chat.type !== 'saved' && !isSystemChat && !chat.is_ghost && !isPendingSecret;
    if (btnVoiceCall) {
        btnVoiceCall.classList.toggle('hidden', !(canShowCallBtns && callPol.voice_enabled && callPol.can_start));
    }
    if (btnVideoCall) {
        btnVideoCall.classList.toggle('hidden', !(canShowCallBtns && callPol.video_enabled && callPol.can_start));
    }
    if (typeof renderChatActiveCallBanner === 'function') {
        renderChatActiveCallBanner(chat);
    }
    if (typeof syncComposerMediaPolicyButtons === 'function') {
        syncComposerMediaPolicyButtons(chat);
    }

    const roBar = document.getElementById('composer-readonly-bar');
    const actBar = document.getElementById('composer-active-bar');
    const isGlobalSuper = !!(store.user && store.user.role === 'superadmin');
    const isAdminOrOwnerHere = isSuperOrOwner || chat.my_role === 'admin';
    if (isSystemChat) {
        roBar.textContent = t('system_chat_readonly_banner');
        roBar.classList.remove('hidden');
        actBar.classList.add('hidden');
    } else if (isPendingSecret) {
        roBar.textContent = (store.user && Number(chat.secret_initiator_id) === Number(store.user.id))
            ? t('secret_req_sender_text')
            : t('secret_req_recipient_text');
        roBar.classList.remove('hidden');
        actBar.classList.add('hidden');
    } else if (store.user && store.user.ban_send === 1 && store.user.role !== 'superadmin') {
        roBar.textContent = t('global_send_banned_banner');
        roBar.classList.remove('hidden');
        actBar.classList.add('hidden');
    } else if (chat.type === 'group' && chat.my_mute_send === 1 && !isAdminOrOwnerHere) {
        roBar.textContent = t('member_send_restricted_banner');
        roBar.classList.remove('hidden');
        actBar.classList.add('hidden');
    } else if (!isGlobalSuper && gIdle.active) {
        if (store.mediaRecorder && store.mediaRecorder.state === 'recording' && typeof cancelVoiceRecording === 'function') {
            cancelVoiceRecording();
        }
        roBar.textContent = gIdle.mode === 'auto'
            ? t('idle_global_banner_auto').replace('{start}', gIdle.start).replace('{end}', gIdle.end)
            : t('idle_global_banner_manual');
        roBar.classList.remove('hidden');
        actBar.classList.add('hidden');
    } else if (!isGlobalSuper && (chat.type === 'group' || chat.type === 'channel') && cIdle.active) {
        if (store.mediaRecorder && store.mediaRecorder.state === 'recording' && typeof cancelVoiceRecording === 'function') {
            cancelVoiceRecording();
        }
        roBar.textContent = cIdle.mode === 'auto'
            ? t('idle_chat_banner_auto').replace('{start}', cIdle.start).replace('{end}', cIdle.end)
            : t('idle_chat_banner_manual');
        roBar.classList.remove('hidden');
        actBar.classList.add('hidden');
    } else if (chat.type === 'channel' && !canPost) {
        roBar.textContent = t('channel_readonly_banner');
        roBar.classList.remove('hidden');
        actBar.classList.add('hidden');
    } else if (chat.is_ghost && chat.type === 'dm') {
        roBar.textContent = stripLeadingEmoji(t('ghost_banner_text'));
        roBar.classList.remove('hidden');
        actBar.classList.add('hidden');
    } else if (chat.status === 'blocked' && !isGlobalSuper) {
        roBar.textContent = t('status_blocked');
        roBar.classList.remove('hidden');
        actBar.classList.add('hidden');
    } else if (chat.type === 'group' && ((chat.all_muted === 1 && !canPost) || (chat.perms && Number(chat.perms.admins_only) === 1 && !isAdminOrOwnerHere))) {
        roBar.textContent = t('group_muted_banner');
        roBar.classList.remove('hidden');
        actBar.classList.add('hidden');
    } else {
        roBar.classList.add('hidden');
        actBar.classList.remove('hidden');
    }
}


function classifyMessageFile(msg) {
    if (!msg || !msg.file) return 'other';
    const mime = String(msg.file.mime || '').toLowerCase();
    const fname = String(msg.file.display_name || '').toLowerCase();
    if (msg.kind === 'voice' || mime.startsWith('audio/') || /\.(mp3|wav|ogg|m4a|flac|aac|opus)$/i.test(fname)) {
        return 'audio';
    }
    if (mime.startsWith('image/') || /\.(jpg|jpeg|png|gif|webp)$/i.test(fname)) {
        return 'image';
    }
    if (mime.startsWith('video/') || /\.(mp4|webm)$/i.test(fname)) {
        return 'video';
    }
    if (mime.startsWith('text/plain') || /\.(txt|log|md|csv|json)$/i.test(fname)) {
        return 'text';
    }
    return 'other';
}

function shouldAutoDownloadFile(msg, category) {
    if (!msg || !msg.file) return true;
    if (store.loadedMediaIds && store.loadedMediaIds.has(msg.file.id)) return true;
    const u = store.user || {};
    if (category === 'image') return u.auto_dl_images !== 0;
    if (category === 'video') return u.auto_dl_videos !== 0;
    if (category === 'audio') return u.auto_dl_audio !== 0;
    return true;
}

function getFileDownloadUrl(fileObj) {
    if (!fileObj || !fileObj.url) return '#';
    return fileObj.url + (fileObj.url.includes('?') ? '&dl=1' : '?dl=1');
}

async function triggerFileDownloadAndOpen(fileObj, chat = null) {
    if (!fileObj || !fileObj.url) return;
    let dlUrl = getFileDownloadUrl(fileObj);
    let previewUrl = fileObj.url;
    if (fileObj.encrypted && chat && chat.type === 'secret') {
        const dec = await E2EE.decryptFileToObjectUrl(chat, fileObj);
        if (dec && dec.blobUrl) {
            dlUrl = dec.blobUrl;
            previewUrl = dec.blobUrl;
        }
    }
    const mime = String(fileObj.mime || '').toLowerCase();
    const fn = String(fileObj.display_name || '').toLowerCase();
    const a = document.createElement('a');
    a.href = dlUrl;
    a.download = fileObj.display_name || 'download';
    a.rel = 'noopener';
    document.body.appendChild(a);
    a.click();
    a.remove();
    if (mime === 'application/pdf' || fn.endsWith('.pdf')) {
        window.open(previewUrl, '_blank', 'noopener');
    }
}

function renderMessageMediaAttachment(mediaDiv, msg, chat, autoPlayOnManualLoad = false) {
    mediaDiv.innerHTML = '';
    const f = msg.file;
    if (!f) return;

    const category = classifyMessageFile(msg);
    let mediaUrl = f.url;
    let dlUrl = getFileDownloadUrl(f);
    const sizeLabel = formatBytes(f.size || 0);
    const allowDownloadHere = canDownloadMessageFile(msg, chat);
    const allowCopyHere = canCopyMessageAction(msg, chat);

    // Transparent client-side AES-256-GCM decryption for Secret Chat attachments
    if (f.encrypted && chat && chat.type === 'secret') {
        const cachedDec = store.decryptedBlobUrls && store.decryptedBlobUrls[f.id];
        if (!cachedDec) {
            if ((category === 'image' || category === 'video' || category === 'audio') && !shouldAutoDownloadFile(msg, category)) {
                // Fall through to lazy placeholder below first
            } else {
                const waitEl = document.createElement('div');
                waitEl.style.cssText = 'font-size:12px;color:var(--text-muted);padding:6px 0';
                waitEl.textContent = t('e2ee_decrypting_file');
                mediaDiv.appendChild(waitEl);
                E2EE.decryptFileToObjectUrl(chat, f).then(dec => {
                    if (dec && dec.blobUrl) {
                        if (dec.text !== null) store.txtCache[f.id] = dec.text;
                        renderMessageMediaAttachment(mediaDiv, msg, chat, autoPlayOnManualLoad);
                    } else {
                        waitEl.textContent = t('e2ee_decrypt_err');
                    }
                });
                return;
            }
        } else {
            mediaUrl = cachedDec.blobUrl;
            dlUrl = cachedDec.blobUrl;
            if (cachedDec.text !== null) store.txtCache[f.id] = cachedDec.text;
        }
    }

    // Check Auto-Download setting for image, video, and voice/audio (Emoji-covered media uses its own two-step cover first)
    if (!(Number(msg.spoiler) === 1 && (category === 'image' || category === 'video')) && (category === 'image' || category === 'video' || category === 'audio') && !shouldAutoDownloadFile(msg, category)) {
        const ph = document.createElement('div');
        ph.className = 'media-lazy-placeholder';
        const em = document.createElement('div');
        em.className = 'media-lazy-emoji';
        em.textContent = category === 'image' ? '🖼️' : (category === 'video' ? '🎬' : (msg.kind === 'voice' ? '🎤' : '🎵'));

        const meta = document.createElement('div');
        meta.className = 'media-lazy-meta';
        const nm = document.createElement('div');
        nm.className = 'media-lazy-name';
        nm.textContent = f.display_name || t('media_attachment');
        const hint = document.createElement('div');
        hint.className = 'media-lazy-hint';
        const hintTxt = category === 'image' ? t('click_to_load_image') : (category === 'video' ? t('click_to_load_video') : t('click_to_load_voice'));
        hint.textContent = `${hintTxt} • ${sizeLabel}`;
        meta.appendChild(nm);
        meta.appendChild(hint);

        ph.appendChild(em);
        ph.appendChild(meta);
        const revealPreview = e => {
            if (e) e.stopPropagation();
            if (store.selectedMsgIds && store.selectedMsgIds.size > 0) return;
            store.loadedMediaIds.add(f.id);
            renderMessageMediaAttachment(mediaDiv, msg, chat, false);
        };
        ph.addEventListener('click', revealPreview);
        mediaDiv.appendChild(ph);
        return;
    }

    const zeroSaveHere = isZeroSaveProtected(msg, chat);
    if (zeroSaveHere) {
        mediaDiv.classList.add('m3-zero-save');
        bindZeroSaveDomGuards(mediaDiv);
    }

    // Two-Step Emoji-Cover Option (Item #1: 1st click removes emoji cover & reveals preview; 2nd click enlarges photo or plays video)
    const isSpoilerMedia = Number(msg.spoiler) === 1 && (category === 'image' || category === 'video');
    if (isSpoilerMedia && !(store.revealedSpoilerMsgIds && store.revealedSpoilerMsgIds.has(msg.id))) {
        const spCard = document.createElement('div');
        spCard.className = 'media-spoiler-cover';
        const spEm = document.createElement('div');
        spEm.className = 'media-spoiler-emojis';
        spEm.textContent = category === 'image' ? '🫣 🖼️' : '🫣 🎬';
        const spTitle = document.createElement('div');
        spTitle.className = 'media-spoiler-title';
        spTitle.textContent = category === 'image' ? t('spoiler_cover_photo_title') : t('spoiler_cover_video_title');
        const spSub = document.createElement('div');
        spSub.className = 'media-spoiler-sub';
        spSub.textContent = `${t('spoiler_cover_step1_hint')} (${sizeLabel})`;
        spCard.appendChild(spEm);
        spCard.appendChild(spTitle);
        spCard.appendChild(spSub);
        spCard.addEventListener('click', e => {
            e.stopPropagation();
            if (store.selectedMsgIds && store.selectedMsgIds.size > 0) return;
            store.revealedSpoilerMsgIds.add(msg.id);
            store.loadedMediaIds.add(f.id);
            renderMessageMediaAttachment(mediaDiv, msg, chat, false);
        });
        mediaDiv.appendChild(spCard);
        return;
    }

    // 1. Embedded .txt / plain text viewer
    if (category === 'text' && (!f.encrypted || (store.decryptedBlobUrls && store.decryptedBlobUrls[f.id]))) {
        const viewer = document.createElement('div');
        viewer.className = 'embedded-txt-viewer';

        const head = document.createElement('div');
        head.className = 'embedded-txt-head';
        const titleSpan = document.createElement('span');
        titleSpan.style.cssText = 'overflow:hidden;text-overflow:ellipsis;white-space:nowrap';
        titleSpan.textContent = `📄 ${f.display_name} (${sizeLabel})`;
        head.appendChild(titleSpan);
        viewer.appendChild(head);

        const pre = document.createElement('pre');
        pre.className = 'embedded-txt-body';
        pre.setAttribute('dir', 'auto');

        const loadTxtInto = (txt) => {
            const previewSlice = txt.length > 6000 ? (txt.slice(0, 6000) + '\n…') : txt;
            pre.textContent = previewSlice || t('txt_empty');
        };

        if (typeof store.txtCache[f.id] === 'string') {
            loadTxtInto(store.txtCache[f.id]);
        } else {
            pre.textContent = t('txt_loading');
            fetch(mediaUrl, { credentials: 'same-origin' })
                .then(r => r.text())
                .then(txt => {
                    store.txtCache[f.id] = txt;
                    loadTxtInto(txt);
                })
                .catch(() => {
                    pre.textContent = t('txt_load_err');
                });
        }
        viewer.appendChild(pre);
        mediaDiv.appendChild(viewer);

        const bar = document.createElement('div');
        bar.className = 'msg-media-toolbar';

        const popBtn = document.createElement('button');
        popBtn.type = 'button';
        popBtn.className = 'msg-media-tool-btn';
        popBtn.textContent = t('open_txt_reader_btn');
        popBtn.addEventListener('click', e => {
            e.stopPropagation();
            UniversalPlayer.open({
                type: 'text',
                url: mediaUrl,
                sourceMsgId: msg.id,
                sourceFileId: f.id,
                zeroSave: zeroSaveHere,
                downloadUrl: allowDownloadHere ? dlUrl : '',
                allowDownload: allowDownloadHere,
                allowCopy: allowCopyHere,
                title: f.display_name,
                textContent: typeof store.txtCache[f.id] === 'string' ? store.txtCache[f.id] : undefined,
                mode: 'normal'
            });
        });
        bar.appendChild(popBtn);

        if (allowDownloadHere && !zeroSaveHere) {
            const dlLink = document.createElement('a');
            dlLink.className = 'msg-media-tool-btn';
            dlLink.href = dlUrl;
            dlLink.setAttribute('download', f.display_name || 'document.txt');
            dlLink.textContent = t('download_file_btn');
            dlLink.addEventListener('click', e => e.stopPropagation());
            bar.appendChild(dlLink);
        }

        mediaDiv.appendChild(bar);
        return;
    }

    // 2. Picture (with per-user Stop GIF Autoplay support — Item #6)
    if (category === 'image' && (!f.encrypted || (store.decryptedBlobUrls && store.decryptedBlobUrls[f.id]))) {
        const isGifFile = /\.gif($|\?)/i.test(String(f.display_name || mediaUrl || '')) || String(f.mime || '').toLowerCase() === 'image/gif';
        const autoplayGifs = !(store.user && Number(store.user.autoplay_gifs) === 0);
        if (!store.playingGifMsgIds) store.playingGifMsgIds = new Set();
        const isPausedGif = isGifFile && !autoplayGifs && !store.playingGifMsgIds.has(msg.id);

        if (isPausedGif) {
            const gWrap = document.createElement('div');
            gWrap.className = 'gif-paused-wrap';
            gWrap.title = t('gif_tap_to_play_tip');
            const cnv = document.createElement('canvas');
            cnv.width = 240;
            cnv.height = 160;
            const probeImg = new Image();
            probeImg.decoding = 'async';
            probeImg.onload = () => {
                const nw = Math.max(1, probeImg.naturalWidth || 240);
                const nh = Math.max(1, probeImg.naturalHeight || 160);
                const scale = Math.min(1, 360 / nw, 320 / nh);
                cnv.width = Math.max(1, Math.round(nw * scale));
                cnv.height = Math.max(1, Math.round(nh * scale));
                const ctx2d = cnv.getContext('2d');
                if (ctx2d) ctx2d.drawImage(probeImg, 0, 0, cnv.width, cnv.height);
            };
            probeImg.src = mediaUrl;
            const badge = document.createElement('span');
            badge.className = 'gif-badge-pill';
            badge.textContent = '▶ GIF';
            gWrap.appendChild(cnv);
            gWrap.appendChild(badge);
            if (!allowDownloadHere || zeroSaveHere) {
                bindZeroSaveDomGuards(gWrap);
            }
            gWrap.addEventListener('click', e => {
                e.stopPropagation();
                if (store.selectedMsgIds && store.selectedMsgIds.size > 0) return;
                store.playingGifMsgIds.add(msg.id);
                renderMessageMediaAttachment(mediaDiv, msg, chat, false);
            });
            mediaDiv.appendChild(gWrap);
        } else {
            const img = document.createElement('img');
            img.src = mediaUrl;
            img.alt = f.display_name;
            img.loading = 'lazy';
            img.style.cursor = 'pointer';
            if (!allowDownloadHere || zeroSaveHere) {
                bindZeroSaveDomGuards(img);
            }
            img.addEventListener('click', e => {
                e.stopPropagation();
                if (isGifFile && !autoplayGifs && store.playingGifMsgIds.has(msg.id)) {
                    store.playingGifMsgIds.delete(msg.id);
                    renderMessageMediaAttachment(mediaDiv, msg, chat, false);
                    return;
                }
                UniversalPlayer.open({
                    type: 'image',
                    url: mediaUrl,
                    sourceMsgId: msg.id,
                    sourceFileId: f.id,
                    zeroSave: zeroSaveHere,
                    downloadUrl: allowDownloadHere ? dlUrl : '',
                    allowDownload: allowDownloadHere,
                    title: f.display_name,
                    mode: 'normal'
                });
            });
            mediaDiv.appendChild(img);
        }

        const bar = document.createElement('div');
        bar.className = 'msg-media-toolbar';
        const popBtn = document.createElement('button');
        popBtn.type = 'button';
        popBtn.className = 'msg-media-tool-btn';
        popBtn.textContent = t('open_in_player_btn');
        popBtn.addEventListener('click', e => {
            e.stopPropagation();
            UniversalPlayer.open({
                type: 'image',
                url: mediaUrl,
                sourceMsgId: msg.id,
                sourceFileId: f.id,
                zeroSave: zeroSaveHere,
                downloadUrl: allowDownloadHere ? dlUrl : '',
                allowDownload: allowDownloadHere,
                title: f.display_name,
                mode: 'float'
            });
        });
        bar.appendChild(popBtn);
        if (allowDownloadHere) {
            const dlLink = document.createElement('a');
            dlLink.className = 'msg-media-tool-btn';
            dlLink.href = dlUrl;
            dlLink.setAttribute('download', f.display_name || 'image');
            dlLink.textContent = t('download_file_btn');
            dlLink.addEventListener('click', e => e.stopPropagation());
            bar.appendChild(dlLink);
        }
        mediaDiv.appendChild(bar);
        return;
    }

    // 3. Video (Custom Dedicated Video Player + Shared Buffer + Non-Conflicting Scrubber + 2nd-Click Spoiler Guard)
    if (category === 'video' && (!f.encrypted || (store.decryptedBlobUrls && store.decryptedBlobUrls[f.id]))) {
        const needsSecondClickPlay = Number(msg.spoiler) === 1 && !(store.playedSpoilerVideoIds && store.playedSpoilerVideoIds.has(msg.id));
        const vidPoolKey = SharedMediaPool.makeKey('video', msg.id, f.id, mediaUrl);
        const openVidPopup = (liveVid) => {
            handoffInlineToUniversalPlayer(liveVid, {
                type: 'video',
                url: mediaUrl,
                poolKey: vidPoolKey,
                sourceMsgId: msg.id,
                sourceFileId: f.id,
                zeroSave: zeroSaveHere,
                downloadUrl: allowDownloadHere ? dlUrl : '',
                allowDownload: allowDownloadHere,
                title: f.display_name,
                mode: 'float'
            });
        };
        const customVid = createCustomVideoPlayer({
            url: mediaUrl,
            poolKey: vidPoolKey,
            msgId: msg.id,
            fileId: f.id,
            zeroSave: zeroSaveHere,
            allowDownload: allowDownloadHere,
            inUmp: false,
            needsSecondClickPlay,
            onSecondClickUnlocked: () => {
                if (store.playedSpoilerVideoIds) store.playedSpoilerVideoIds.add(msg.id);
            },
            onPopOut: openVidPopup,
            autoPlay: Boolean(autoPlayOnManualLoad)
        });
        const vid = customVid.video;
        customVid.wrap.setAttribute('data-inline-msg-id', String(msg.id || ''));
        if (f.id) customVid.wrap.setAttribute('data-inline-file-id', String(f.id));
        mediaDiv.appendChild(customVid.wrap);

        const bar = document.createElement('div');
        bar.className = 'msg-media-toolbar';

        const popBtn = document.createElement('button');
        popBtn.type = 'button';
        popBtn.className = 'msg-media-tool-btn';
        popBtn.textContent = t('open_in_player_btn');
        popBtn.addEventListener('click', e => {
            e.stopPropagation();
            openVidPopup(vid);
        });
        bar.appendChild(popBtn);
        if (allowDownloadHere) {
            const dlLink = document.createElement('a');
            dlLink.className = 'msg-media-tool-btn';
            dlLink.href = dlUrl;
            dlLink.setAttribute('download', f.display_name || 'video');
            dlLink.textContent = t('download_file_btn');
            dlLink.addEventListener('click', e => e.stopPropagation());
            bar.appendChild(dlLink);
        }
        mediaDiv.appendChild(bar);
        return;
    }

    // 4. Voice / Music / Audio (Shared Buffer + Interactive Scrubber + Horizontal Box Scrub)
    if (category === 'audio' && (!f.encrypted || (store.decryptedBlobUrls && store.decryptedBlobUrls[f.id]))) {
        const audPoolKey = SharedMediaPool.makeKey('audio', msg.id, f.id, mediaUrl);
        const customAud = createCustomAudioPlayer({
            url: mediaUrl,
            poolKey: audPoolKey,
            cacheKey: f.id ? `f_${f.id}` : mediaUrl,
            displayName: f.display_name || '',
            autoPlay: Boolean(autoPlayOnManualLoad)
        });
        customAud.wrap.setAttribute('data-inline-msg-id', String(msg.id || ''));
        if (f.id) customAud.wrap.setAttribute('data-inline-file-id', String(f.id));
        mediaDiv.classList.add('has-audio-player');
        mediaDiv.appendChild(customAud.wrap);

        const bar = document.createElement('div');
        bar.className = 'msg-media-toolbar';
        const popBtn = document.createElement('button');
        popBtn.type = 'button';
        popBtn.className = 'msg-media-tool-btn';
        popBtn.textContent = t('open_in_player_btn');
        popBtn.addEventListener('click', e => {
            e.stopPropagation();
            handoffInlineToUniversalPlayer(customAud.audio, {
                type: 'audio',
                url: mediaUrl,
                cacheKey: f.id ? `f_${f.id}` : mediaUrl,
                sourceMsgId: msg.id,
                sourceFileId: f.id,
                zeroSave: zeroSaveHere,
                downloadUrl: allowDownloadHere ? dlUrl : '',
                allowDownload: allowDownloadHere,
                title: f.display_name,
                mode: 'float'
            });
        });
        bar.appendChild(popBtn);
        if (allowDownloadHere) {
            const dlLink = document.createElement('a');
            dlLink.className = 'msg-media-tool-btn';
            dlLink.href = dlUrl;
            dlLink.setAttribute('download', f.display_name || 'audio');
            dlLink.textContent = t('download_file_btn');
            dlLink.addEventListener('click', e => e.stopPropagation());
            bar.appendChild(dlLink);
        }
        mediaDiv.appendChild(bar);
        return;
    }

    // 5. Unknown / Other file types (documents, archives, binaries, or encrypted blobs)
    const card = document.createElement('div');
    card.className = 'file-attachment-card';
    const fIcon = document.createElement('div');
    fIcon.className = 'media-lazy-emoji';
    const ext = String(f.display_name || '').split('.').pop().toLowerCase();
    fIcon.textContent = f.encrypted ? '🔒' : (['zip', 'rar', '7z', 'tar', 'gz'].includes(ext) ? '📦' : (ext === 'pdf' ? '📕' : '📄'));

    const fMeta = document.createElement('div');
    fMeta.className = 'media-lazy-meta';
    const fName = document.createElement('div');
    fName.className = 'media-lazy-name';
    fName.textContent = f.display_name || 'file';
    const fSub = document.createElement('div');
    fSub.className = 'media-lazy-hint';
    fSub.textContent = allowDownloadHere
        ? `${sizeLabel} • ${t('click_to_download_open')}`
        : `${sizeLabel} • ${t('download_disabled_toast')}`;
    fMeta.appendChild(fName);
    fMeta.appendChild(fSub);

    const dlIcon = document.createElement('span');
    dlIcon.style.cssText = 'font-size:17px;flex-shrink:0';
    dlIcon.textContent = allowDownloadHere ? '⬇️' : '🚫';

    card.appendChild(fIcon);
    card.appendChild(fMeta);
    card.appendChild(dlIcon);
    card.addEventListener('click', e => {
        e.stopPropagation();
        if (!allowDownloadHere) {
            toast(t('download_disabled_toast'), true);
            return;
        }
        triggerFileDownloadAndOpen(f, chat);
    });
    mediaDiv.appendChild(card);
}


function triggerReplyToMessage(msg) {
    const actBar = document.getElementById('composer-active-bar');
    if (actBar && actBar.classList.contains('hidden')) return;
    store.replyToMsg = msg;
    store.editMsg = null;
    updateComposerContextBar();
    const ta = document.getElementById('composer-textarea');
    if (ta) ta.focus();
}

function attachMessageGesturesAndMenu(row, bubble, msg, chat, displayBody) {
    if (msg._optimistic) return;

    const replyBadge = document.createElement('div');
    replyBadge.className = 'swipe-reply-badge';
    replyBadge.textContent = '↩';
    row.appendChild(replyBadge);

    let suppressNextContext = false;

    // 1. Desktop Right-Click -> Open Message Options Modal across text, media, voice & files
    bubble.addEventListener('contextmenu', e => {
        if (store.selectedMsgIds.size > 0) {
            e.preventDefault();
            e.stopPropagation();
            toggleMessageSelection(msg.id);
            return;
        }
        if (e.target && e.target.closest('a[href]')) return;
        e.preventDefault();
        e.stopPropagation();
        if (suppressNextContext) {
            suppressNextContext = false;
            return;
        }
        openMessageActionModal(msg, chat, displayBody);
    });

    // 2. Touch & Pointer Hold (Long-Press for Options) + Horizontal Swipe-to-Side for Reply
    let startX = 0;
    let startY = 0;
    let lastDx = 0;
    let tracking = false;
    let swiping = false;
    let holdTriggered = false;
    let hapticFired = false;
    let holdTimer = null;
    let pressStyleTimer = null;

    const clearTimers = () => {
        if (holdTimer) { clearTimeout(holdTimer); holdTimer = null; }
        if (pressStyleTimer) { clearTimeout(pressStyleTimer); pressStyleTimer = null; }
        bubble.classList.remove('msg-pressing');
    };

    const resetSwipeVisual = () => {
        bubble.style.transition = 'transform 0.22s cubic-bezier(0.2, 0.9, 0.3, 1)';
        bubble.style.transform = '';
        replyBadge.style.opacity = '0';
        replyBadge.style.transform = 'scale(0.5)';
        replyBadge.style.removeProperty('--swipe-ready');
        replyBadge.classList.remove('ready');
    };

    const onStart = (clientX, clientY, targetEl, isTouch) => {
        if (store.selectedMsgIds.size === 0 && targetEl && targetEl.closest('a[href], .msg-quick-btn, .msg-select-chk, .m3-media-scrubber, .m3-audio-player, .m3-video-player, input[type="range"]')) return;
        if (isTouch && !isTouchInsideRowMessageBounds(row, clientX)) return;
        clearTimers();
        startX = clientX;
        startY = clientY;
        lastDx = 0;
        tracking = true;
        swiping = false;
        holdTriggered = false;
        hapticFired = false;

        if (store.selectedMsgIds.size === 0) {
            pressStyleTimer = setTimeout(() => {
                if (tracking && !swiping) bubble.classList.add('msg-pressing');
            }, 90);
        }

        holdTimer = setTimeout(() => {
            if (!tracking || swiping || MessageDragSelector.active) return;
            holdTriggered = true;
            tracking = false;
            bubble.classList.remove('msg-pressing');
            if (window.getSelection) {
                try { window.getSelection().removeAllRanges(); } catch (e) {}
            }
            if (isTouch) suppressNextContext = true;
            if (navigator.vibrate) { try { navigator.vibrate(18); } catch (err) {} }
            // Item #8 & #17: Long-pressing a message selects it (never opens the action menu) and allows vertical drag-select within message bounds
            if (isTouch) {
                MessageDragSelector.suppressClickUntil = Date.now() + 420;
                MessageDragSelector.beginSession('touch', msg.id, startY);
            } else {
                MessageDragSelector.suppressClickUntil = Date.now() + 260;
                toggleMessageSelection(msg.id);
            }
        }, 360);
    };

    const onMove = (clientX, clientY, rawEvent) => {
        if (!tracking || holdTriggered) return;
        const dx = clientX - startX;
        const dy = clientY - startY;

        if (Math.abs(dx) > 10 || Math.abs(dy) > 10) {
            clearTimers();
        }

        // Strict Selection Mode Lock: disallow horizontal swipe-to-reply while selecting messages
        if (store.selectedMsgIds.size > 0) {
            if (Math.abs(dx) > 14 || Math.abs(dy) > 14) {
                tracking = false;
            }
            return;
        }

        if (!swiping) {
            if (Math.abs(dy) > 16 && Math.abs(dy) > Math.abs(dx)) {
                // Vertical scroll — abort gesture tracking cleanly
                tracking = false;
                return;
            }
            if (Math.abs(dx) > 14 && Math.abs(dx) > Math.abs(dy) * 1.3) {
                swiping = true;
            }
        }

        if (swiping) {
            if (rawEvent && rawEvent.cancelable) rawEvent.preventDefault();
            lastDx = dx;
            const damped = Math.max(-68, Math.min(68, dx * 0.68));
            bubble.style.transition = 'none';
            bubble.style.transform = `translateX(${damped}px)`;

            const progress = Math.min(1, Math.abs(dx) / 48);
            const isReady = Math.abs(dx) >= 48;
            replyBadge.style.opacity = String(progress);
            replyBadge.style.transform = `scale(${(0.55 + 0.45 * progress).toFixed(2)})`;
            replyBadge.classList.toggle('ready', isReady);

            if (isReady && !hapticFired) {
                hapticFired = true;
                if (navigator.vibrate) { try { navigator.vibrate(10); } catch (err) {} }
            } else if (!isReady) {
                hapticFired = false;
            }
        }
    };

    let lastTouchTapEnd = 0;
    const onEnd = (isTouchEnd = false, targetEl = null) => {
        clearTimers();
        if (!tracking && !swiping) return;
        const shouldReply = store.selectedMsgIds.size === 0 && swiping && Math.abs(lastDx) >= 48;
        const wasCleanTap = tracking && !swiping && !holdTriggered && Math.abs(lastDx) < 10;
        tracking = false;
        swiping = false;
        resetSwipeVisual();
        if (shouldReply) {
            triggerReplyToMessage(msg);
            return;
        }
        if (isTouchEnd && wasCleanTap) {
            // Item #17: In selection mode on mobile, only toggle selection when tapping inside the message horizontal bounds
            if (store.selectedMsgIds.size > 0) {
                if (!isTouchInsideRowMessageBounds(row, startX)) return false;
                lastTouchTapEnd = Date.now();
                MessageDragSelector.suppressClickUntil = Date.now() + 380;
                toggleMessageSelection(msg.id);
                return true;
            }
            // Item #3: Mobile tap on 🫣 spoiler card, step-2 video overlay, paused GIF, file card, or lazy media card triggers the card directly instead of opening the message action modal
            const directCard = targetEl
                ? targetEl.closest('.media-spoiler-cover, .spoiler-video-step2-wrap, .spoiler-video-play-pill, .media-lazy-placeholder, .video-note-lazy-placeholder, .file-attachment-card, .gif-paused-wrap')
                : null;
            const fallbackCard = (!directCard && targetEl && targetEl.closest('.msg-media'))
                ? row.querySelector('.media-spoiler-cover, .media-lazy-placeholder, .video-note-lazy-placeholder, .gif-paused-wrap')
                : null;
            const tapMediaCard = directCard || fallbackCard;
            if (tapMediaCard) {
                MessageDragSelector.suppressClickUntil = 0;
                if (tapMediaCard.classList.contains('spoiler-video-step2-wrap')) {
                    const pill = tapMediaCard.querySelector('.spoiler-video-play-pill');
                    if (pill) pill.click();
                    else tapMediaCard.click();
                } else {
                    tapMediaCard.click();
                }
                lastTouchTapEnd = Date.now();
                MessageDragSelector.suppressClickUntil = Date.now() + 380;
                return true;
            }
            if (targetEl && targetEl.closest('button, a, .msg-mention-link, .msg-edited-hist-trigger, input, textarea, select, video, audio, img, .m3-audio-player, .m3-video-player, .m3-media-scrubber, .media-spoiler-cover, .spoiler-video-step2-wrap, .spoiler-video-play-pill, .media-lazy-placeholder, .video-note-lazy-placeholder, .file-attachment-card, .gif-paused-wrap, .video-note-bubble, .react-chip, .msg-select-chk, .video-note-circle, .location-card-bubble')) {
                return false;
            }
            lastTouchTapEnd = Date.now();
            store._menuTapGuardUntil = Date.now() + 420;
            openMessageActionModal(msg, chat, displayBody);
            return true;
        }
        return false;
    };

    row.addEventListener('click', e => {
        if (Date.now() < MessageDragSelector.suppressClickUntil) {
            e.preventDefault();
            e.stopPropagation();
            return;
        }
        if (Date.now() - lastTouchTapEnd < 450) return;
        if (store.selectedMsgIds.size > 0) {
            if (window.innerWidth <= 780 && typeof e.clientX === 'number' && e.clientX > 0 && !isTouchInsideRowMessageBounds(row, e.clientX)) {
                return;
            }
            e.preventDefault();
            e.stopPropagation();
            toggleMessageSelection(msg.id);
        }
    });

    // Touch events (Mobile / Tablet)
    row.addEventListener('touchstart', e => {
        if (e.touches.length !== 1) return;
        onStart(e.touches[0].clientX, e.touches[0].clientY, e.target, true);
    }, { passive: true });

    row.addEventListener('touchmove', e => {
        if (MessageDragSelector.active && MessageDragSelector.mode === 'touch' && e.touches.length === 1) {
            if (e.cancelable) e.preventDefault();
            MessageDragSelector.applyAtY(e.touches[0].clientY);
            return;
        }
        if (!tracking || e.touches.length !== 1) return;
        onMove(e.touches[0].clientX, e.touches[0].clientY, e);
    }, { passive: false });

    row.addEventListener('touchend', e => {
        if (MessageDragSelector.active && MessageDragSelector.mode === 'touch') {
            MessageDragSelector.endSession();
            if (e.cancelable) e.preventDefault();
            return;
        }
        const consumedTap = onEnd(true, e.target);
        if (consumedTap && e.cancelable) {
            // Prevent browser synthetic ghost-click from firing onto the newly opened modal item under the finger!
            e.preventDefault();
        }
    }, { passive: false });
    row.addEventListener('touchcancel', () => {
        if (MessageDragSelector.active && MessageDragSelector.mode === 'touch') {
            MessageDragSelector.endSession();
        }
        clearTimers();
        tracking = false;
        swiping = false;
        resetSwipeVisual();
    });

    // Mouse hold & horizontal drag-swipe support (Desktop)
    row.addEventListener('mousedown', e => {
        if (e.button !== 0) return;
        onStart(e.clientX, e.clientY, e.target, false);
        const moveHandler = ev => onMove(ev.clientX, ev.clientY, null);
        const upHandler = () => {
            window.removeEventListener('mousemove', moveHandler);
            window.removeEventListener('mouseup', upHandler);
            onEnd();
        };
        window.addEventListener('mousemove', moveHandler);
        window.addEventListener('mouseup', upHandler);
    });

    // Suppress synthetic click on media/file cards right after a long-press hold completes
    row.addEventListener('click', e => {
        if (holdTriggered) {
            holdTriggered = false;
            e.preventDefault();
            e.stopPropagation();
        }
    }, true);
}


function pinViewportToBottom(vp, holdMs = 420) {
    if (!vp) return;
    let aborted = false;
    const abortPin = () => { aborted = true; };
    vp.addEventListener('wheel', abortPin, { once: true, passive: true });
    vp.addEventListener('touchstart', abortPin, { once: true, passive: true });
    vp.addEventListener('mousedown', abortPin, { once: true, passive: true });
    const snap = () => {
        if (aborted || !vp.isConnected || MessageDragSelector.active) return;
        vp.scrollTop = vp.scrollHeight;
    };
    snap();
    requestAnimationFrame(() => {
        snap();
        requestAnimationFrame(() => {
            snap();
            if (!aborted) updateScrollBottomFab(false);
        });
    });
    const until = Date.now() + holdMs;
    [55, 160, 340].forEach(ms => {
        setTimeout(() => {
            if (!aborted && !MessageDragSelector.active && Date.now() <= until + 80) {
                snap();
                updateScrollBottomFab(false);
            }
        }, ms);
    });
    vp.querySelectorAll('img, video').forEach(mediaEl => {
        const onMediaDim = () => {
            if (!aborted && !MessageDragSelector.active && Date.now() <= until + 200) {
                snap();
                updateScrollBottomFab(false);
            }
        };
        mediaEl.addEventListener('load', onMediaDim, { once: true });
        mediaEl.addEventListener('loadedmetadata', onMediaDim, { once: true });
    });
}

async function jumpToMessageInChat(chatId, messageId) {
    const cid = Number(chatId || 0);
    const mid = Number(messageId || 0);
    if (!cid || !mid) return;
    if (store.activeChatId !== cid) {
        await selectChat(cid, { aroundId: mid });
    }
    let vp = document.getElementById('messages-viewport');
    let row = vp ? vp.querySelector(`.msg-row[data-msg-id="${mid}"]`) : null;
    if (!row) {
        await selectChat(cid, { aroundId: mid });
        vp = document.getElementById('messages-viewport');
        row = vp ? vp.querySelector(`.msg-row[data-msg-id="${mid}"]`) : null;
    }
    if (!vp || !row) {
        toast(t('pinned_msg_not_found'), true);
        return;
    }
    const targetTop = Math.max(0, row.offsetTop - Math.max(40, Math.round((vp.clientHeight - row.offsetHeight) / 2)));
    vp.scrollTo({ top: targetTop, behavior: 'smooth' });
    vp.querySelectorAll('.msg-row.msg-jump-highlight').forEach(el => el.classList.remove('msg-jump-highlight'));
    row.classList.add('msg-jump-highlight');
    setTimeout(() => {
        if (row.isConnected) row.classList.remove('msg-jump-highlight');
    }, 1700);
    setTimeout(() => updateScrollBottomFab(false), 320);
}

const MSG_DOM_WINDOW_CAP = 240;

async function maybePaginateChatMessagesOnScroll() {
    const vp = document.getElementById('messages-viewport');
    const cid = Number(store.activeChatId || 0);
    if (!vp || !cid || MessageDragSelector.active) return;
    if (store._suppressPaginationUntil && Date.now() < store._suppressPaginationUntil) return;
    const searchBarEl = document.getElementById('in-chat-search-bar');
    const searchInEl = document.getElementById('in-chat-search-input');
    if (searchBarEl && !searchBarEl.classList.contains('hidden') && searchInEl && searchInEl.value.trim() !== '') return;

    const list = (store.messages[cid] || []).filter(m => !m._optimistic && Number(m.id) > 0);
    if (!list.length) return;

    // 1. Scroll near TOP -> load older messages incrementally
    if (vp.scrollTop <= 96 && store.hasMoreBeforeByChat[cid] && !store.loadingOlderByChat[cid] && !store.loadingNewerByChat[cid]) {
        store.loadingOlderByChat[cid] = true;
        try {
            const oldestId = Number(list[0].id);
            const r = await apiCall('messages_list', { chat_id: cid, before_id: oldestId, limit: 50 });
            if (r.ok && store.activeChatId === cid) {
                const older = Array.isArray(r.data.messages) ? r.data.messages : [];
                store.hasMoreBeforeByChat[cid] = Boolean(r.data.has_more_before && older.length > 0);
                if (older.length > 0) {
                    const curAll = store.messages[cid] || [];
                    const existingIds = new Set(curAll.map(m => Number(m.id)));
                    const uniqueOlder = older.filter(m => !existingIds.has(Number(m.id)));
                    if (uniqueOlder.length > 0) {
                        const prevScrollHeight = vp.scrollHeight;
                        const prevScrollTop = vp.scrollTop;
                        let combined = uniqueOlder.concat(curAll);
                        if (combined.length > MSG_DOM_WINDOW_CAP) {
                            combined = combined.slice(0, MSG_DOM_WINDOW_CAP);
                            store.hasMoreAfterByChat[cid] = true;
                        }
                        store.messages[cid] = combined;
                        await renderMessagesViewport(false, { skipAutoScrollRestore: true });
                        const addedHeight = vp.scrollHeight - prevScrollHeight;
                        vp.scrollTop = Math.max(0, prevScrollTop + addedHeight);
                        updateScrollBottomFab(false);
                    }
                }
            }
        } finally {
            store.loadingOlderByChat[cid] = false;
        }
        return;
    }

    // 2. Scroll near BOTTOM while viewing older history slice -> load newer messages incrementally
    const distFromBottom = Math.max(0, (vp.scrollHeight - vp.clientHeight) - vp.scrollTop);
    if (distFromBottom <= 110 && store.hasMoreAfterByChat[cid] && !store.loadingNewerByChat[cid] && !store.loadingOlderByChat[cid]) {
        store.loadingNewerByChat[cid] = true;
        try {
            const newestId = Number(list[list.length - 1].id);
            const r = await apiCall('messages_list', { chat_id: cid, after_id: newestId, limit: 50 });
            if (r.ok && store.activeChatId === cid) {
                const newer = Array.isArray(r.data.messages) ? r.data.messages : [];
                store.hasMoreAfterByChat[cid] = Boolean(r.data.has_more_after);
                if (newer.length > 0) {
                    const curAll = store.messages[cid] || [];
                    const existingIds = new Set(curAll.map(m => Number(m.id)));
                    const uniqueNewer = newer.filter(m => !existingIds.has(Number(m.id)));
                    if (uniqueNewer.length > 0) {
                        const prevScrollTop = vp.scrollTop;
                        const anchorId = newestId;
                        const oldAnchorRow = vp.querySelector(`.msg-row[data-msg-id="${anchorId}"]`);
                        const oldAnchorTop = oldAnchorRow ? oldAnchorRow.offsetTop : 0;
                        let combined = curAll.concat(uniqueNewer);
                        if (combined.length > MSG_DOM_WINDOW_CAP) {
                            combined = combined.slice(combined.length - MSG_DOM_WINDOW_CAP);
                            store.hasMoreBeforeByChat[cid] = true;
                        }
                        store.messages[cid] = combined;
                        await renderMessagesViewport(false, { skipAutoScrollRestore: true });
                        const newAnchorRow = vp.querySelector(`.msg-row[data-msg-id="${anchorId}"]`);
                        if (oldAnchorRow && newAnchorRow) {
                            vp.scrollTop = Math.max(0, prevScrollTop + (newAnchorRow.offsetTop - oldAnchorTop));
                        } else {
                            vp.scrollTop = prevScrollTop;
                        }
                        updateScrollBottomFab(false);
                    }
                }
            }
        } finally {
            store.loadingNewerByChat[cid] = false;
        }
    }
}

async function renderMessagesViewport(scrollToBottom = false, renderOpts = {}) {
    const vp = document.getElementById('messages-viewport');
    const chat = getActiveChat();
    if (!vp || !chat) return;
    MessageDragSelector.ensureViewportWired();

    const prevScrollTop = vp.scrollTop;
    const prevMaxScroll = Math.max(0, vp.scrollHeight - vp.clientHeight);
    const wasNearBottom = prevMaxScroll <= 24 || (prevMaxScroll - prevScrollTop) <= 44;
    const forcePinBottom = Boolean(scrollToBottom || (store._forcePinBottomUntil && Date.now() < store._forcePinBottomUntil));

    const list = store.messages[chat.id] || [];
    const frag = document.createDocumentFragment();

    let lastDateStr = '';
    let prevAuthorId = null;
    let prevCreatedAt = 0;
    const firstUnreadId = Number(store.firstUnreadByChat[chat.id] || 0);
    let unreadBannerInserted = false;

    for (const msg of list) {
        if (!unreadBannerInserted && firstUnreadId > 0 && Number(msg.id) >= firstUnreadId) {
            unreadBannerInserted = true;
            const uDiv = document.createElement('div');
            uDiv.className = 'unread-divider-pill';
            uDiv.textContent = '⬇ ' + t('unread_divider_lbl');
            frag.appendChild(uDiv);
            prevAuthorId = null;
        }
        if (msg.created_at) {
            const dStr = formatDate(msg.created_at, false);
            if (dStr && dStr !== lastDateStr) {
                lastDateStr = dStr;
                const divPill = document.createElement('div');
                divPill.className = 'date-divider';
                divPill.textContent = dStr;
                frag.appendChild(divPill);
                prevAuthorId = null;
            }
        }

        if (msg.kind === 'system') {
            const sysRow = document.createElement('div');
            sysRow.className = 'msg-row system-row';
            const pill = document.createElement('div');
            pill.className = 'system-pill';
            pill.textContent = formatDynamicServerText(msg.body);
            sysRow.appendChild(pill);
            frag.appendChild(sysRow);
            prevAuthorId = null;
            continue;
        }

        const isMine = store.user && msg.user_id === store.user.id;
        const isGrouped = (prevAuthorId === msg.user_id) && ((msg.created_at - prevCreatedAt) < 120);
        prevAuthorId = msg.user_id;
        prevCreatedAt = msg.created_at;

        const row = document.createElement('div');
        row.className = 'msg-row ' + (isMine ? 'mine' : 'theirs') + (isGrouped ? ' grouped' : '') + (store.selectedMsgIds.has(Number(msg.id)) ? ' msg-selected' : '');
        row.dataset.msgId = String(msg.id);

        const selChk = document.createElement('span');
        selChk.className = 'msg-select-chk';
        selChk.textContent = store.selectedMsgIds.has(Number(msg.id)) ? '✓' : '';
        selChk.addEventListener('click', e => {
            e.stopPropagation();
            toggleMessageSelection(msg.id);
        });
        row.appendChild(selChk);

        if (!isMine && (chat.type === 'group' || chat.type === 'channel')) {
            const av = document.createElement('div');
            av.className = 'avatar avatar-sm';
            av.style.cursor = 'pointer';
            if (isGrouped) {
                av.style.visibility = 'hidden';
            } else {
                renderAvatarNode(av, msg.author_name, msg.author_avatar);
                av.addEventListener('click', () => openUserMiniProfile(msg.user_id));
            }
            row.appendChild(av);
        }

        const bubble = document.createElement('div');
        bubble.className = 'msg-bubble';

        const adminBadgeEl = createAuthorAdminBadge(msg, chat);
        if (!isMine && !isGrouped && (chat.type === 'group' || chat.type === 'channel')) {
            const authDiv = document.createElement('div');
            authDiv.className = 'msg-author';
            const nameSpan = document.createElement('span');
            nameSpan.textContent = formatDisplayName(msg.author_name);
            authDiv.appendChild(nameSpan);
            if (adminBadgeEl) {
                authDiv.appendChild(adminBadgeEl);
            }
            authDiv.addEventListener('click', () => openUserMiniProfile(msg.user_id));
            bubble.appendChild(authDiv);
        } else if (adminBadgeEl) {
            // Item #24: Always display admin badge above messages written by an admin (including consecutive grouped bursts, own messages, and DMs)
            const authDiv = document.createElement('div');
            authDiv.className = 'msg-author';
            authDiv.style.justifyContent = isMine ? 'flex-end' : 'flex-start';
            authDiv.appendChild(adminBadgeEl);
            if (!isMine && msg.user_id) {
                authDiv.addEventListener('click', () => openUserMiniProfile(msg.user_id));
            }
            bubble.appendChild(authDiv);
        }

        if (chat.type !== 'secret' && msg.forward_from_name && !msg.forward_hide_author) {
            const fwd = document.createElement('div');
            fwd.className = 'msg-forward-tag';
            fwd.textContent = '↪ ' + t('forwarded_from') + formatDisplayName(msg.forward_from_name);
            bubble.appendChild(fwd);
        }

        if (msg.reply_preview) {
            const repBox = document.createElement('div');
            repBox.className = 'msg-reply-box';
            const rAuthor = document.createElement('strong');
            rAuthor.textContent = formatDisplayName(msg.reply_preview.name) + ': ';
            const rBody = document.createElement('span');
            rBody.textContent = formatDynamicServerText(msg.reply_preview.body);
            repBox.appendChild(rAuthor);
            repBox.appendChild(rBody);
            bubble.appendChild(repBox);
        }

        if (msg.file) {
            // Item #5: Compact outer frame for file/media message bubbles
            if (msg.kind !== 'video_note') {
                bubble.classList.add('has-media-card');
            }
            const mediaDiv = document.createElement('div');
            mediaDiv.className = 'msg-media';
            if (msg.kind === 'video_note' && typeof renderCircularVideoNoteAttachment === 'function') {
                renderCircularVideoNoteAttachment(mediaDiv, msg, chat);
            } else {
                renderMessageMediaAttachment(mediaDiv, msg, chat, false);
            }
            bubble.appendChild(mediaDiv);
        }

        let displayBody = msg.body || '';
        if (chat.type === 'secret' && msg.cipher && msg.iv) {
            displayBody = await E2EE.decryptText(chat, msg.cipher, msg.iv);
        }
        if (msg.kind === 'call_log') {
            let clData = {};
            try { clData = JSON.parse(msg.body || '{}') || {}; } catch (e) { clData = {}; }
            const isVideoCall = String(clData.call_type || '') === 'video';
            const stCodeRaw = String(clData.status || 'ended');
            const stCode = ['ringing', 'active', 'started', 'ended', 'missed', 'declined', 'busy'].includes(stCodeRaw) ? stCodeRaw : 'ended';
            const durSec = Math.max(0, Number(clData.duration_sec || 0));
            const typeWord = isVideoCall ? t('call_log_video_lbl') : t('call_log_audio_lbl');
            const stText = t('call_log_status_' + stCode);
            const durText = durSec > 0 ? (' • ' + t('call_log_dur_tpl').replace('{dur}', formatAudioClock(durSec))) : '';
            displayBody = `${isVideoCall ? '📹' : '📞'} ${typeWord} — ${stText}${durText}`;

            const clWrap = document.createElement('div');
            clWrap.className = 'msg-call-entry' + ((stCode === 'missed' || stCode === 'declined' || stCode === 'busy') ? ' is-missed' : '');
            clWrap.style.cssText = 'display:flex;align-items:center;gap:10px;padding:4px 2px;min-width:min(190px, 100%)';

            const clIcon = document.createElement('div');
            const isMissedLike = (stCode === 'missed' || stCode === 'declined' || stCode === 'busy');
            clIcon.style.cssText = 'width:38px;height:38px;border-radius:50%;display:inline-flex;align-items:center;justify-content:center;font-size:18px;flex-shrink:0;' +
                (isMissedLike ? 'background:rgba(239,68,68,0.16);color:#ef4444;' : 'background:rgba(16,185,129,0.16);color:#10b981;');
            clIcon.textContent = isVideoCall ? '📹' : '📞';

            const clInfo = document.createElement('div');
            clInfo.style.cssText = 'display:flex;flex-direction:column;gap:2px;min-width:0;flex:1';

            const clTitle = document.createElement('div');
            clTitle.style.cssText = 'font-weight:800;font-size:13.5px;line-height:1.35';
            clTitle.textContent = typeWord;

            const clSub = document.createElement('div');
            clSub.style.cssText = 'font-size:12px;line-height:1.35;opacity:0.88;' + (isMissedLike ? 'color:#f87171;font-weight:700;' : '');
            const subItems = [stText];
            if (durSec > 0) {
                subItems.push(t('call_log_dur_tpl').replace('{dur}', formatAudioClock(durSec)));
            }
            clSub.textContent = subItems.join(' • ');

            clInfo.appendChild(clTitle);
            clInfo.appendChild(clSub);
            clWrap.appendChild(clIcon);
            clWrap.appendChild(clInfo);
            bubble.appendChild(clWrap);
        }
        store.decryptedTextCache[msg.id] = displayBody;
        if (msg.kind === 'call_log') {
            // Already rendered rich caller bubble card above; msg-meta below adds timestamp & read ticks
        } else if (msg.kind === 'location' && typeof renderLocationCardIntoBubble === 'function') {
            renderLocationCardIntoBubble(bubble, displayBody, msg, chat);
        } else if (displayBody !== '') {
            const txtDiv = document.createElement('div');
            txtDiv.className = 'msg-text';
            txtDiv.setAttribute('dir', 'auto');
            appendLinkedText(txtDiv, formatDynamicServerText(displayBody));
            bubble.appendChild(txtDiv);
        }

        if (!canSelectMessageText(msg, chat)) {
            bubble.classList.add('no-select-msg');
            bubble.addEventListener('copy', e => {
                e.preventDefault();
                toast(t('copy_disabled_toast'), true);
            });
            bubble.addEventListener('cut', e => e.preventDefault());
        }

        const chatReactionsAllowed = !((chat.type === 'group' || chat.type === 'channel') && chat.reactions_enabled === 0);
        const canForwardFromChat = canForwardOrSaveMessage(msg, chat);

        if (chatReactionsAllowed && msg.reactions && msg.reactions.length > 0) {
            const rBar = document.createElement('div');
            rBar.className = 'msg-reactions';
            msg.reactions.forEach(rc => {
                const chip = document.createElement('span');
                chip.className = 'react-chip' + (rc.me ? ' me' : '');
                chip.textContent = `${rc.emoji} ${formatLocalizedCount(rc.count)}`;
                chip.addEventListener('click', async e => {
                    e.stopPropagation();
                    const rr = await apiCall('reaction_toggle', { message_id: msg.id, emoji: rc.emoji });
                    if (!rr.ok) toast(rr.message || t('reactions_disabled_notice'), true);
                    await selectChat(chat.id);
                });
                rBar.appendChild(chip);
            });
            bubble.appendChild(rBar);
        }

        const meta = document.createElement('div');
        meta.className = 'msg-meta';

        // Only the moderation ranks ever receive shadow_hidden, and only for a
        // message the rest of the chat cannot see. Say so openly: silently
        // disagreeing with what the author sees would make moderation useless.
        if (Number(msg.shadow_hidden) === 1) {
            const shFlag = document.createElement('span');
            shFlag.className = 'msg-shadow-flag';
            shFlag.textContent = t('shadow_hidden_badge');
            shFlag.title = t('shadow_ban_desc');
            meta.appendChild(shFlag);
        }

        if (msg.expires_at || msg.burn_after) {
            const ttlSpan = document.createElement('span');
            ttlSpan.className = 'ttl-pill';
            ttlSpan.dataset.msgId = String(msg.id);
            if (msg.expires_at) {
                const rem = Math.max(0, Number(msg.expires_at) - Math.floor(Date.now() / 1000));
                ttlSpan.textContent = `⏱️ ${formatCoarseRemainingTtl(rem)}`;
            } else {
                ttlSpan.textContent = `🔥 ${formatCoarseRemainingTtl(msg.burn_after)} (${t('self_destruct_wait_view')})`;
            }
            meta.appendChild(ttlSpan);
        }

        if (msg.edited_at) {
            const ed = document.createElement('span');
            const isSilentSeen = Number(msg.edited_silent) === 1;
            ed.textContent = isSilentSeen ? t('edited_silent_tag') : t('edited');
            if (isSilentSeen) {
                ed.style.opacity = '0.88';
            }
            if (store.user && store.user.role === 'superadmin' && Array.isArray(msg.edit_history) && msg.edit_history.length > 0) {
                ed.className = 'msg-edited-hist-trigger';
                ed.style.cursor = 'pointer';
                ed.style.textDecoration = 'underline dotted';
                ed.title = t('msg_edit_history_btn');
                ed.addEventListener('click', ev => {
                    ev.stopPropagation();
                    openSuperAdminEditHistoryModal(msg, chat, displayBody);
                });
            }
            meta.appendChild(ed);
        }

        if (store.inChatSearchActive && Number(store.inChatSearchChatId) === Number(chat.id)) {
            const jumpBtn = document.createElement('button');
            jumpBtn.type = 'button';
            jumpBtn.className = 'btn btn-secondary btn-sm msg-search-jump-btn';
            jumpBtn.style.cssText = 'padding:2px 8px;font-size:11px;border-radius:999px;font-weight:700;margin-inline-end:4px';
            jumpBtn.textContent = '↗ ' + t('show_in_chat_btn');
            jumpBtn.addEventListener('click', async ev => {
                ev.stopPropagation();
                const searchBar = document.getElementById('in-chat-search-bar');
                const searchIn = document.getElementById('in-chat-search-input');
                if (searchBar) searchBar.classList.add('hidden');
                if (searchIn) searchIn.value = '';
                store.inChatSearchActive = false;
                store.inChatSearchChatId = 0;
                await selectChat(chat.id, { aroundId: msg.id });
            });
            meta.appendChild(jumpBtn);
        }

        const timeNode = document.createElement('span');
        timeNode.textContent = formatTimeOnly(msg.created_at);
        meta.appendChild(timeNode);

        if (isMine) {
            const tickState = msg._optimistic ? 'pending' : ((msg.id <= (chat.peer_last_read_id || 0)) ? 'seen' : msg.tick_status || 'sent');
            meta.appendChild(createTickIcon(tickState));
        } else if (msg.kind !== 'system') {
            const inTickState = msg.tick_status || 'sent';
            meta.appendChild(createTickIcon(inTickState));
        }

        // View counter. Two rules decide it, both set on the destination chat:
        //   * counters only exist in groups and channels - a message forwarded on
        //     into a private or secret chat shows nothing, whatever it collected
        //     where it came from;
        //   * a forwarded copy starts from zero like any new message, so it never
        //     inherits the counter of the original.
        const viewsAllowed = Boolean(chat && chat.msg_views_enabled === 1
            && (chat.type === 'group' || chat.type === 'channel'));
        if (msg.kind !== 'system' && viewsAllowed && Number(msg.views) > 0) {
            meta.appendChild(createViewsCounter(msg.views));
        }

        const menuBtn = document.createElement('button');
        menuBtn.type = 'button';
        // 28px so it stays comfortably tappable on a phone; a bare 22px glyph was
        // the smallest interactive control anywhere in the app.
        menuBtn.className = 'msg-act-btn';
        menuBtn.textContent = '⋮';
        menuBtn.title = t('msg_actions_title');
        menuBtn.addEventListener('click', e => {
            e.stopPropagation();
            openMessageActionModal(msg, chat, displayBody);
        });
        meta.appendChild(menuBtn);

        bubble.appendChild(meta);
        row.appendChild(bubble);

        if (!msg._optimistic) {
            const qBar = document.createElement('div');
            qBar.className = 'msg-quick-bar';

            if (chatReactionsAllowed) {
                ['👍', '❤️'].forEach(em => {
                    const qb = document.createElement('button');
                    qb.type = 'button';
                    qb.className = 'msg-quick-btn';
                    qb.textContent = em;
                    qb.addEventListener('click', async e => {
                        e.stopPropagation();
                        const rr = await apiCall('reaction_toggle', { message_id: msg.id, emoji: em });
                        if (!rr.ok) toast(rr.message || t('reactions_disabled_notice'), true);
                        await selectChat(chat.id);
                    });
                    qBar.appendChild(qb);
                });
            }

            const qRep = document.createElement('button');
            qRep.type = 'button';
            qRep.className = 'msg-quick-btn';
            qRep.title = t('reply');
            qRep.textContent = '↩';
            qRep.addEventListener('click', e => {
                e.stopPropagation();
                store.replyToMsg = msg;
                store.editMsg = null;
                updateComposerContextBar();
                document.getElementById('composer-textarea').focus();
            });
            qBar.appendChild(qRep);

            if (canForwardFromChat) {
                const qSave = document.createElement('button');
                qSave.type = 'button';
                qSave.className = 'msg-quick-btn';
                qSave.title = t('send_to_saved_btn');
                qSave.textContent = '🔖';
                qSave.addEventListener('click', async e => {
                    e.stopPropagation();
                    await forwardDirectlyToSavedMessages(msg);
                });
                qBar.appendChild(qSave);

                const qFwd = document.createElement('button');
                qFwd.type = 'button';
                qFwd.className = 'msg-quick-btn';
                qFwd.title = t('forward');
                qFwd.textContent = '↪';
                qFwd.addEventListener('click', e => {
                    e.stopPropagation();
                    openForwardMessageModal(msg);
                });
                qBar.appendChild(qFwd);
            }

            const qMore = document.createElement('button');
            qMore.type = 'button';
            qMore.className = 'msg-quick-btn';
            qMore.textContent = '⋯';
            qMore.addEventListener('click', e => {
                e.stopPropagation();
                openMessageActionModal(msg, chat, displayBody);
            });
            qBar.appendChild(qMore);

            row.appendChild(qBar);
            attachMessageGesturesAndMenu(row, bubble, msg, chat, displayBody);
        }

        frag.appendChild(row);
    }

    if (forcePinBottom) {
        store._suppressPaginationUntil = Date.now() + 240;
    }
    if (typeof vp.replaceChildren === 'function') {
        vp.replaceChildren(frag);
    } else {
        vp.innerHTML = '';
        vp.appendChild(frag);
    }

    if (!renderOpts.skipAutoScrollRestore) {
        if (forcePinBottom) {
            const scrollFab = document.getElementById('btn-scroll-bottom');
            if (scrollFab) scrollFab.classList.add('hidden');
            pinViewportToBottom(vp, 420);
        } else if (wasNearBottom && !store.hasMoreAfterByChat[chat.id]) {
            vp.scrollTop = vp.scrollHeight;
            requestAnimationFrame(() => {
                vp.scrollTop = vp.scrollHeight;
                updateScrollBottomFab(false);
            });
        } else {
            vp.scrollTop = prevScrollTop;
            updateScrollBottomFab(false);
        }
    }
}

function openSuperAdminEditHistoryModal(msg, chat, currentDecryptedText) {
    openModal(t('msg_edit_history_modal_title'), async (body) => {
        const curBox = document.createElement('div');
        curBox.className = 'card-box';
        curBox.style.marginBottom = '10px';
        const curHead = document.createElement('div');
        curHead.style.cssText = 'display:flex;justify-content:space-between;align-items:center;gap:8px;font-size:12px;font-weight:800;color:var(--primary);margin-bottom:6px';
        const curTitle = document.createElement('span');
        curTitle.textContent = t('msg_edit_history_current_lbl') + (Number(msg.edited_silent) === 1 ? ' ' + t('edited_silent_tag') : '');
        const curTime = document.createElement('span');
        curTime.style.cssText = 'font-weight:500;color:var(--text-muted);font-size:11.5px';
        curTime.textContent = formatDate(msg.edited_at || msg.created_at, true);
        curHead.appendChild(curTitle);
        curHead.appendChild(curTime);
        curBox.appendChild(curHead);

        const curBodyEl = document.createElement('div');
        curBodyEl.style.cssText = 'white-space:pre-wrap;word-break:break-word;font-size:13.5px;line-height:1.6;padding:8px 10px;border-radius:8px;background:var(--bg-subtle);user-select:text';
        curBodyEl.setAttribute('dir', 'auto');
        curBodyEl.textContent = currentDecryptedText || msg.body || '';
        curBox.appendChild(curBodyEl);
        body.appendChild(curBox);

        const histArr = Array.isArray(msg.edit_history) ? msg.edit_history.slice() : [];
        if (histArr.length === 0) {
            const emp = document.createElement('div');
            emp.style.cssText = 'text-align:center;color:var(--text-muted);padding:16px 8px;font-size:13px';
            emp.textContent = t('msg_edit_history_empty');
            body.appendChild(emp);
            return;
        }

        for (let idx = histArr.length - 1; idx >= 0; idx--) {
            const rev = histArr[idx] || {};
            const revCard = document.createElement('div');
            revCard.className = 'card-box';
            revCard.style.marginBottom = '8px';

            const rHead = document.createElement('div');
            rHead.style.cssText = 'display:flex;justify-content:space-between;align-items:center;gap:8px;font-size:12px;font-weight:700;color:var(--text-secondary);margin-bottom:6px';
            const rLbl = document.createElement('span');
            rLbl.textContent = t('msg_edit_history_rev_lbl').replace('{n}', formatLocalizedCount(idx + 1));
            const rTs = document.createElement('span');
            rTs.style.cssText = 'font-weight:500;color:var(--text-muted);font-size:11.5px';
            rTs.textContent = formatDate(rev.ts || rev.edited_at || msg.created_at, true);
            rHead.appendChild(rLbl);
            rHead.appendChild(rTs);
            revCard.appendChild(rHead);

            let prevTxt = typeof rev.body === 'string' ? rev.body : '';
            if (!prevTxt && rev.cipher && rev.iv && chat && chat.type === 'secret') {
                try {
                    prevTxt = await E2EE.decryptText(chat, rev.cipher, rev.iv);
                } catch (e) {
                    prevTxt = '🔒 [Encrypted E2EE Revision]';
                }
            }
            const rTxtEl = document.createElement('div');
            rTxtEl.style.cssText = 'white-space:pre-wrap;word-break:break-word;font-size:13px;line-height:1.6;padding:8px 10px;border-radius:8px;background:var(--bg-subtle);user-select:text';
            rTxtEl.setAttribute('dir', 'auto');
            rTxtEl.textContent = prevTxt;
            revCard.appendChild(rTxtEl);
            body.appendChild(revCard);
        }
    });
}

/* ---------------- MESSAGE CONTEXT ACTION MENU (WITH SECRET CHAT FORWARD GUARD) ---------------- */
function openMessageActionModal(msg, chat, decryptedText) {
    const modalOpenedAt = Date.now();
    // 5th arg: on phones show this one centred in the viewport rather than
    // pinned to the bottom edge like the other sheets.
    openModal(t('msg_actions_title'), (body, close) => {
        body.addEventListener('click', ev => {
            const guardUntil = Math.max(modalOpenedAt + 340, Number(store._menuTapGuardUntil || 0));
            if (ev.isTrusted && Date.now() < guardUntil) {
                ev.preventDefault();
                ev.stopPropagation();
            }
        }, true);
        const isMine = store.user && msg.user_id === store.user.id;
        const isSystemChat = (chat.type === 'system');
        const isSuperOrOwner = (store.user && store.user.role === 'superadmin') || chat.my_role === 'owner';
        const myPerms = chat.my_perms || {};
        const canPin = !isSystemChat && (isSuperOrOwner || (chat.my_role === 'admin' && myPerms.pin_messages !== 0));
        const canDeleteOthers = !isSystemChat && (isSuperOrOwner || (chat.my_role === 'admin' && myPerms.delete_messages !== 0));

        const stripLeadingIcon = s => String(s || '').replace(/^[☑️🕵️📋🔖🎬⬇️↪↩✏️📌🗑️🚩🙈📜🗔️🖨️]+\s*/u, '');
        const makeMiniItem = (icon, label, onClick, danger = false) => {
            const b = document.createElement('button');
            b.type = 'button';
            b.className = 'msg-mini-item' + (danger ? ' danger' : '');
            const ico = document.createElement('span');
            ico.className = 'mmi-ico';
            ico.textContent = icon;
            const txt = document.createElement('span');
            txt.textContent = stripLeadingIcon(label);
            b.appendChild(ico);
            b.appendChild(txt);
            b.addEventListener('click', onClick);
            return b;
        };

        // Item #12: Official System Chat is strictly one-way & non-manipulable (Copy Text only)
        if (isSystemChat) {
            const sysMenu = document.createElement('div');
            sysMenu.className = 'msg-mini-menu';
            const rawCopy = formatDynamicServerText(decryptedText || msg.body || '').trim();
            if (rawCopy) {
                sysMenu.appendChild(makeMiniItem('📋', t('copy_text'), () => {
                    if (navigator.clipboard) navigator.clipboard.writeText(rawCopy);
                    close();
                    toast(t('copied_toast'));
                }));
            }
            body.appendChild(sysMenu);
            return;
        }

        const chatReactionsAllowed = !((chat.type === 'group' || chat.type === 'channel') && chat.reactions_enabled === 0);
        if (chatReactionsAllowed) {
            const myCurEmoji = ((msg.reactions || []).find(rc => rc.me) || {}).emoji || '';
            const reactRow = document.createElement('div');
            reactRow.className = 'msg-mini-reacts';
            ['👍', '❤️', '🔥', '👏', '😂', '😮', '🎉', '🙏'].forEach(em => {
                const b = document.createElement('button');
                b.type = 'button';
                b.className = 'msg-mini-react-btn';
                if (myCurEmoji === em) {
                    b.style.background = 'var(--primary-soft)';
                    b.style.boxShadow = '0 0 0 1.5px var(--primary)';
                }
                b.textContent = em;
                b.addEventListener('click', async () => {
                    close();
                    const rr = await apiCall('reaction_toggle', { message_id: msg.id, emoji: em });
                    if (!rr.ok) toast(rr.message || t('reactions_disabled_notice'), true);
                    await selectChat(chat.id);
                });
                reactRow.appendChild(b);
            });
            body.appendChild(reactRow);
        }

        const menu = document.createElement('div');
        menu.className = 'msg-mini-menu';

        menu.appendChild(makeMiniItem('☑️', t('select_msg_btn'), () => {
            close();
            toggleMessageSelection(msg.id);
        }));

        menu.appendChild(makeMiniItem('↩', t('reply'), () => {
            close();
            triggerReplyToMessage(msg);
        }));

        const copyableText = (decryptedText || msg.body || '').trim();
        const allowCopyMsg = canCopyMessageAction(msg, chat);
        if ((chat.type === 'group' || chat.type === 'channel') && msg.kind !== 'system' && (Number(chat.can_view_readers) === 1 || (store.user && store.user.role === 'superadmin'))) {
            menu.appendChild(makeMiniItem('👁️', t('msg_viewers_menu_btn'), () => {
                close();
                openMessageViewersModal(msg, chat);
            }));
        }

        const allowDlFile = canDownloadMessageFile(msg, chat);
        if (copyableText && allowCopyMsg) {
            menu.appendChild(makeMiniItem('📋', t('copy_text'), () => {
                if (navigator.clipboard) navigator.clipboard.writeText(copyableText);
                close();
                toast(t('copied_toast'));
            }));
        }

        if (store.user && store.user.role === 'superadmin' && Array.isArray(msg.edit_history) && msg.edit_history.length > 0) {
            menu.appendChild(makeMiniItem('📜', t('msg_edit_history_btn'), () => {
                close();
                openSuperAdminEditHistoryModal(msg, chat, decryptedText || msg.body || '');
            }));
        }

        if (isMine && msg.kind === 'text') {
            menu.appendChild(makeMiniItem('✏️', t('edit'), () => {
                const ta = document.getElementById('composer-textarea');
                if (ta && !store.editMsg && chat && chat.id) {
                    if (!store.preEditDraftByChat) store.preEditDraftByChat = {};
                    store.preEditDraftByChat[chat.id] = ta.value || '';
                }
                store.editMsg = msg;
                store.replyToMsg = null;
                if (ta) {
                    ta.value = decryptedText || msg.body || '';
                    syncComposerEditMaxLength();
                    autoResizeComposerInput();
                }
                updateComposerContextBar();
                close();
                if (ta) ta.focus();
            }));
        }

        if (msg.file && msg.file.url) {
            const cat = classifyMessageFile(msg);
            const dlUrl = getFileDownloadUrl(msg.file);
            if (!msg.file.encrypted && (cat === 'image' || cat === 'video' || cat === 'audio' || cat === 'text')) {
                menu.appendChild(makeMiniItem('🎬', t('open_in_player_btn'), () => {
                    close();
                    handoffInlineToUniversalPlayer(null, {
                        type: cat,
                        url: msg.file.url,
                        cacheKey: msg.file.id ? `f_${msg.file.id}` : msg.file.url,
                        sourceMsgId: msg.id,
                        sourceFileId: msg.file.id,
                        downloadUrl: allowDlFile ? dlUrl : '',
                        allowDownload: allowDlFile,
                        allowCopy: allowCopyMsg,
                        title: msg.file.display_name,
                        textContent: cat === 'text' ? store.txtCache[msg.file.id] : undefined,
                        mode: (cat === 'video' || cat === 'audio') ? 'float' : 'normal',
                        isVideoNote: msg.kind === 'video_note'
                    });
                }));
            }
            if (allowDlFile) {
                const dlLink = document.createElement('a');
                dlLink.className = 'msg-mini-item';
                dlLink.style.textDecoration = 'none';
                dlLink.href = dlUrl;
                dlLink.setAttribute('download', msg.file.display_name || 'file');
                dlLink.innerHTML = `<span class="mmi-ico">⬇️</span><span>${esc(stripLeadingIcon(t('download_file_btn')))}</span>`;
                dlLink.addEventListener('click', () => close());
                menu.appendChild(dlLink);
            }
        }

        const canForwardFromChat = canForwardOrSaveMessage(msg, chat);
        if (canForwardFromChat) {
            menu.appendChild(makeMiniItem('🔖', t('send_to_saved_btn'), async () => {
                close();
                await forwardDirectlyToSavedMessages(msg);
            }));
            menu.appendChild(makeMiniItem('↪', t('forward'), () => {
                close();
                openForwardMessageModal(msg, false);
            }));
            menu.appendChild(makeMiniItem('🕵️', t('forward_anon_btn'), () => {
                close();
                openForwardMessageModal(msg, true);
            }));
        }

        // Item #13: 2-Layer Pinning (Personal 'me' pin + Shared 'both' pin with newest-wins stack)
        if (chat.type === 'saved') {
            menu.appendChild(makeMiniItem('📌', msg.pinned ? t('unpin') : t('pin'), async () => {
                const wasPinned = !!msg.pinned;
                close();
                const pr = await apiCall(wasPinned ? 'unpin' : 'pin', { chat_id: chat.id, message_id: msg.id, scope: 'both' });
                if (pr.ok) {
                    if (pr.data && pr.data.chats) store.chats = pr.data.chats;
                    renderActiveChatHeader();
                    await selectChat(chat.id, { preserveScrollBottom: true });
                    toast(wasPinned ? t('msg_unpinned_toast') : t('msg_pinned_toast'));
                } else {
                    toast(pr.message || t('err_generic'), true);
                }
            }));
        } else if ((chat.type === 'group' || chat.type === 'channel' || chat.type === 'dm' || chat.type === 'secret') && !chat.is_ghost) {
            const myPersonalPinnedId = Number(chat.my_pinned_message_id || ((chat.pinned_message && chat.pinned_message.scope === 'me') ? chat.pinned_message.id : 0));
            const isPinnedMe = myPersonalPinnedId === Number(msg.id);
            const isPinnedBoth = Boolean(msg.pinned);
            const canPinBothHere = (chat.type === 'dm' || chat.type === 'secret') ? true : canPin;
            const sharedPinLabel = (chat.type === 'dm' || chat.type === 'secret') ? t('pin_for_both_btn') : t('pin_for_everyone_btn');

            if (isPinnedMe) {
                menu.appendChild(makeMiniItem('📌', t('unpin_personal_btn'), async () => {
                    close();
                    const pr = await apiCall('unpin', { chat_id: chat.id, message_id: msg.id, scope: 'me' });
                    if (pr.ok) {
                        if (pr.data && pr.data.chats) store.chats = pr.data.chats;
                        renderActiveChatHeader();
                        await selectChat(chat.id, { preserveScrollBottom: true });
                        toast(t('msg_unpinned_toast'));
                    } else {
                        toast(pr.message || t('err_generic'), true);
                    }
                }));
            } else {
                menu.appendChild(makeMiniItem('📌', t('pin_for_me_btn'), async () => {
                    close();
                    const pr = await apiCall('pin', { chat_id: chat.id, message_id: msg.id, scope: 'me' });
                    if (pr.ok) {
                        if (pr.data && pr.data.chats) store.chats = pr.data.chats;
                        renderActiveChatHeader();
                        await selectChat(chat.id, { preserveScrollBottom: true });
                        toast(t('msg_pinned_toast'));
                    } else {
                        toast(pr.message || t('err_generic'), true);
                    }
                }));
            }

            if (canPinBothHere) {
                if (isPinnedBoth) {
                    menu.appendChild(makeMiniItem('📌', t('unpin_shared_btn'), async () => {
                        close();
                        const pr = await apiCall('unpin', { chat_id: chat.id, message_id: msg.id, scope: 'both' });
                        if (pr.ok) {
                            if (pr.data && pr.data.chats) store.chats = pr.data.chats;
                            renderActiveChatHeader();
                            await selectChat(chat.id, { preserveScrollBottom: true });
                            toast(t('msg_unpinned_toast'));
                        } else {
                            toast(pr.message || t('err_generic'), true);
                        }
                    }));
                } else {
                    menu.appendChild(makeMiniItem('📌', sharedPinLabel, async () => {
                        close();
                        const pr = await apiCall('pin', { chat_id: chat.id, message_id: msg.id, scope: 'both' });
                        if (pr.ok) {
                            if (pr.data && pr.data.chats) store.chats = pr.data.chats;
                            renderActiveChatHeader();
                            await selectChat(chat.id, { preserveScrollBottom: true });
                            toast(t('msg_pinned_toast'));
                        } else {
                            toast(pr.message || t('err_generic'), true);
                        }
                    }));
                }
            } else if (isPinnedBoth) {
                menu.appendChild(makeMiniItem('🙈', t('dismiss_shared_pin_btn'), async () => {
                    close();
                    const pr = await apiCall('unpin', { chat_id: chat.id, message_id: msg.id, scope: 'dismiss_both' });
                    if (pr.ok) {
                        if (pr.data && pr.data.chats) store.chats = pr.data.chats;
                        renderActiveChatHeader();
                        await selectChat(chat.id, { preserveScrollBottom: true });
                        toast(t('msg_unpinned_toast'));
                    } else {
                        toast(pr.message || t('err_generic'), true);
                    }
                }));
            }
        }

        const sep = document.createElement('div');
        sep.className = 'msg-mini-sep';
        menu.appendChild(sep);

        menu.appendChild(makeMiniItem('🗑️', t('delete_me'), async () => {
            close();
            const ap = await askApproval({
                title: '🗑️ ' + t('delete_me'),
                desc: t('ask_del_msg_me'),
                danger: true,
                icon: '🗑️'
            });
            if (!ap.approved) return;
            const dr = await apiCall('message_delete', { message_id: msg.id, mode: 'me' });
            if (dr.ok) {
                await selectChat(chat.id);
                toast(t('msg_deleted_me_toast'));
            } else {
                toast(dr.message || t('err_generic'), true);
            }
        }));

        if (isMine || canDeleteOthers) {
            menu.appendChild(makeMiniItem('🗑️', t('delete_all'), async () => {
                close();
                const ap = await askApproval({
                    title: '🗑️ ' + t('delete_all'),
                    desc: t('ask_del_msg_all'),
                    danger: true,
                    icon: '🗑️'
                });
                if (!ap.approved) return;
                const dr = await apiCall('message_delete', { message_id: msg.id, mode: 'everyone' });
                if (dr.ok) {
                    await selectChat(chat.id);
                    toast(t('msg_deleted_all_toast'));
                } else {
                    toast(dr.message || t('err_generic'), true);
                }
            }, true));
        }

        if (!isMine) {
            menu.appendChild(makeMiniItem('🚩', t('report'), () => {
                close();
                openReportModal('message', msg.id, `#${msg.id} (${msg.author_name})`);
            }, true));
        }

        body.appendChild(menu);
    }, false, true);
}

async function forwardDirectlyToSavedMessages(msg, switchChat = false) {
    if (!msg || !msg.id) return false;
    let savedChat = (store.chats || []).find(c => c.type === 'saved');
    if (!savedChat) {
        const cRes = await apiCall('chats_list');
        if (cRes.ok && cRes.data && cRes.data.chats) {
            store.chats = cRes.data.chats;
            savedChat = store.chats.find(c => c.type === 'saved');
        }
    }
    if (!savedChat) {
        toast(t('err_not_found'), true);
        return false;
    }
    const res = await apiCall('message_send', {
        chat_id: savedChat.id,
        forward_from: msg.id,
        body: msg.body || ''
    });
    if (res.ok) {
        const cRes = await apiCall('chats_list');
        if (cRes.ok && cRes.data && cRes.data.chats) {
            store.chats = cRes.data.chats;
            renderChatList();
        }
        if (switchChat || store.activeChatId === savedChat.id) {
            await selectChat(savedChat.id);
        }
        toast(t('sent_to_saved_toast'));
        return true;
    } else {
        toast(res.message || t('err_generic'), true);
        return false;
    }
}

function openForwardMessageModal(msgOrList, hideAuthor = false) {
    const msgs = Array.isArray(msgOrList) ? msgOrList : [msgOrList];
    const modalTitle = hideAuthor ? t('forward_anon_modal_title') : t('forward_modal_title');
    openModal(modalTitle, (body, close) => {
        const selectedIds = new Set();
        let page = 1;
        let perPage = 10;
        let busy = false;

        /* Sends the queued messages to every chosen chat, one chat after another so the
           server sees a steady stream instead of a burst the rate limiter would cut off. */
        const forwardToTargets = async (targets) => {
            busy = true;
            syncFooter();
            let okChats = 0;
            let failChats = 0;
            let lastErr = '';
            let rateLimited = false;
            let lastOkChat = null;
            for (let ti = 0; ti < targets.length; ti++) {
                const targetChat = targets[ti];
                syncFooter(t('forward_sending_tpl')
                    .replace('{i}', formatLocalizedCount(ti + 1))
                    .replace('{n}', formatLocalizedCount(targets.length)));
                let okCount = 0;
                for (const m of msgs) {
                    const res = await apiCall('message_send', {
                        chat_id: targetChat.id,
                        forward_from: m.id,
                        hide_author: hideAuthor ? 1 : 0,
                        body: m.body || ''
                    });
                    if (res.ok) {
                        okCount++;
                    } else {
                        if (res.error === 'firewall_rate_limited') rateLimited = true;
                        lastErr = res.message || t('err_generic');
                    }
                }
                if (okCount === msgs.length) {
                    okChats++;
                    lastOkChat = targetChat;
                } else {
                    failChats++;
                }
                if (rateLimited) break;
            }

            if (okChats > 0) {
                clearMessageSelection();
                const cRes = await apiCall('chats_list');
                if (cRes.ok && cRes.data && cRes.data.chats) {
                    store.chats = cRes.data.chats;
                    renderChatList();
                }
            }

            close();
            busy = false;

            if (okChats === 0) {
                toast(lastErr || t('err_generic'), true);
                return;
            }
            if (failChats === 0) {
                toast(t('forward_done_tpl').replace('{n}', formatLocalizedCount(okChats)));
            } else {
                toast(t('forward_partial_tpl')
                    .replace('{ok}', formatLocalizedCount(okChats))
                    .replace('{fail}', formatLocalizedCount(failChats)), true);
            }
            if (rateLimited) toast(t('forward_rate_limited'), true);
            /* Only jump into the conversation when there was exactly one destination —
               with several there is no single chat to open. */
            if (okChats === 1 && failChats === 0 && lastOkChat) {
                await selectChat(lastOkChat.id);
            }
        };

        const searchIn = document.createElement('input');
        searchIn.type = 'search';
        searchIn.className = 'input';
        searchIn.placeholder = t('forward_search_ph');
        searchIn.style.marginBottom = '8px';
        body.appendChild(searchIn);

        const hint = document.createElement('div');
        hint.style.cssText = 'font-size:12px;color:var(--text-secondary);font-weight:600;margin-bottom:10px;line-height:1.6';
        hint.textContent = t('forward_multi_hint');
        body.appendChild(hint);

        const savedChat = (store.chats || []).find(c => c.type === 'saved');
        if (savedChat) {
            const sendSavedBtn = document.createElement('button');
            sendSavedBtn.type = 'button';
            sendSavedBtn.className = 'btn btn-primary btn-block';
            sendSavedBtn.style.cssText = 'justify-content:center;margin-block-end:10px;font-weight:800';
            sendSavedBtn.textContent = t('send_to_saved_btn');
            sendSavedBtn.addEventListener('click', async () => {
                if (busy) return;
                close();
                await forwardToTargets([savedChat]);
            });
            body.appendChild(sendSavedBtn);
        }

        /* Secret chats and Saved Messages are excluded by rule; the official System chat is
           one-way and always rejects sends, so offering it would only guarantee a failure. */
        const otherPlainChats = (store.chats || []).filter(c => c.type !== 'secret' && c.type !== 'saved' && c.type !== 'system');
        const listWrap = document.createElement('div');
        listWrap.style.cssText = 'display:flex;flex-direction:column;gap:6px';
        body.appendChild(listWrap);

        const pagerMount = document.createElement('div');
        body.appendChild(pagerMount);

        const footer = document.createElement('div');
        footer.style.cssText = 'display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap;margin-top:10px';
        body.appendChild(footer);

        const footerLeft = document.createElement('div');
        footerLeft.style.cssText = 'display:flex;align-items:center;gap:8px;flex-wrap:wrap;min-width:0';
        footer.appendChild(footerLeft);

        const countLbl = document.createElement('span');
        countLbl.id = 'fwd-count-lbl';
        countLbl.style.cssText = 'font-size:12.5px;font-weight:800;color:var(--text-secondary)';
        footerLeft.appendChild(countLbl);

        const pageToggleBtn = document.createElement('button');
        pageToggleBtn.type = 'button';
        pageToggleBtn.id = 'fwd-page-toggle';
        pageToggleBtn.style.cssText = 'border:none;background:none;padding:0;font-size:12px;font-weight:800;color:var(--primary);cursor:pointer';
        footerLeft.appendChild(pageToggleBtn);
        pageToggleBtn.addEventListener('click', () => {
            if (busy) return;
            const ids = currentPageIds();
            const allOn = ids.length > 0 && ids.every(id => selectedIds.has(id));
            ids.forEach(id => { if (allOn) selectedIds.delete(id); else selectedIds.add(id); });
            renderForwardList();
        });

        const clearBtn = document.createElement('button');
        clearBtn.type = 'button';
        clearBtn.id = 'fwd-clear-sel';
        clearBtn.style.cssText = 'border:none;background:none;padding:0;font-size:12px;font-weight:800;color:var(--text-secondary);cursor:pointer;text-decoration:underline';
        clearBtn.textContent = t('forward_clear_sel_btn');
        footerLeft.appendChild(clearBtn);
        clearBtn.addEventListener('click', () => {
            if (busy) return;
            selectedIds.clear();
            renderForwardList();
        });

        const sendBtn = document.createElement('button');
        sendBtn.type = 'button';
        sendBtn.id = 'fwd-send-btn';
        sendBtn.className = 'btn btn-primary';
        sendBtn.style.cssText = 'font-weight:800;min-width:120px;justify-content:center';
        footer.appendChild(sendBtn);
        sendBtn.addEventListener('click', async () => {
            if (busy) return;
            const targets = (store.chats || []).filter(c => selectedIds.has(c.id));
            if (targets.length === 0) {
                toast(t('forward_none_selected'), true);
                return;
            }
            await forwardToTargets(targets);
        });

        let lastPageIds = [];
        const currentPageIds = () => lastPageIds.slice();

        function syncFooter(sendingLabel) {
            const n = selectedIds.size;
            countLbl.textContent = t('forward_recipients_lbl').replace('{n}', formatLocalizedCount(n));
            clearBtn.style.display = n > 0 ? '' : 'none';
            const ids = currentPageIds();
            pageToggleBtn.style.display = ids.length > 1 ? '' : 'none';
            pageToggleBtn.textContent = (ids.length > 0 && ids.every(id => selectedIds.has(id)))
                ? t('forward_deselect_page_btn')
                : t('forward_select_page_btn');
            sendBtn.disabled = busy || n === 0;
            sendBtn.style.opacity = sendBtn.disabled ? '0.55' : '';
            sendBtn.style.cursor = sendBtn.disabled ? 'not-allowed' : 'pointer';
            sendBtn.textContent = sendingLabel
                ? sendingLabel
                : (n > 0 ? t('forward_send_count_btn').replace('{n}', formatLocalizedCount(n)) : t('forward_send_btn'));
        }

        const getFiltered = () => {
            const q = searchIn.value.trim().toLowerCase().replace(/^@+/, '');
            return otherPlainChats.filter(c => {
                if (!q) return true;
                const titleStr = String(formatChatTitle(c) || '').toLowerCase();
                const hdl = String(c.handle || '').toLowerCase();
                const peerU = (c.peer && c.peer.username) ? String(c.peer.username).toLowerCase() : '';
                return titleStr.includes(q) || hdl.includes(q) || peerU.includes(q);
            });
        };

        const renderForwardList = () => {
            listWrap.innerHTML = '';
            pagerMount.innerHTML = '';
            const filtered = getFiltered();

            if (filtered.length === 0) {
                lastPageIds = [];
                const emp = document.createElement('div');
                emp.className = 'settings-search-empty';
                emp.textContent = t('forward_search_empty');
                listWrap.appendChild(emp);
                syncFooter();
                return;
            }

            const pager = buildAdminPaginationControls({
                totalItems: filtered.length,
                page: page,
                pageSize: perPage,
                pageSizeOptions: [5, 10, 20, 50],
                onPageChange: (p) => { if (busy) return; page = p; renderForwardList(); },
                onPageSizeChange: (sz) => { if (busy) return; perPage = sz; page = 1; renderForwardList(); }
            });
            page = pager.curPage;
            const slice = filtered.slice(pager.fromOffset, pager.toOffset);
            lastPageIds = slice.map(c => c.id);
            pagerMount.appendChild(pager.bar);

            slice.forEach(c => {
                const row = document.createElement('label');
                row.className = 'btn btn-secondary btn-block';
                row.style.cssText = 'display:flex;align-items:center;gap:9px;justify-content:flex-start;cursor:pointer;user-select:none;text-align:start';
                row.dataset.fwdRow = String(c.id);

                const cb = document.createElement('input');
                cb.type = 'checkbox';
                cb.checked = selectedIds.has(c.id);
                cb.disabled = busy;
                cb.style.cssText = 'flex:0 0 auto;width:17px;height:17px;accent-color:var(--primary);cursor:pointer;margin:0';
                row.appendChild(cb);

                const txt = document.createElement('span');
                const kindIco = c.type === 'channel' ? '📢' : (c.type === 'group' ? '👥' : '💬');
                const hdlBadge = c.handle ? ` (@${c.handle})` : '';
                txt.textContent = `${kindIco} ${formatChatTitle(c)}${hdlBadge}`;
                txt.style.cssText = 'overflow:hidden;text-overflow:ellipsis;white-space:nowrap;min-width:0;flex:1 1 auto;font-weight:700';
                row.appendChild(txt);

                cb.addEventListener('change', () => {
                    if (cb.checked) selectedIds.add(c.id);
                    else selectedIds.delete(c.id);
                    syncFooter();
                });

                listWrap.appendChild(row);
            });

            syncFooter();
        };

        searchIn.addEventListener('input', () => { page = 1; renderForwardList(); });
        renderForwardList();
    });
}

function splitLongMessageIntoChunks(rawText, maxLen) {
    const L = Math.max(100, Number(maxLen) || 2000);
    const str = String(rawText || '');
    if (!str) return [];
    const chars = Array.from(str);
    if (chars.length <= L) return [str];

    const win = Math.max(1, Math.ceil(L * 0.10));
    const minSplitIdx = Math.max(1, L - win);
    const out = [];
    let offset = 0;
    const total = chars.length;

    while (offset < total) {
        while (offset < total && (chars[offset] === ' ' || chars[offset] === '\t')) {
            offset++;
        }
        if (offset >= total) break;

        const rem = total - offset;
        if (rem <= L) {
            const tail = chars.slice(offset).join('');
            if (tail !== '') out.push(tail);
            break;
        }

        if (/^\s$/u.test(chars[offset + L])) {
            const chunkStr = chars.slice(offset, offset + L).join('').replace(/[ \t]+$/g, '');
            if (chunkStr !== '') out.push(chunkStr);
            offset += L + 1;
            continue;
        }

        let splitRel = -1;
        for (let i = L - 1; i >= minSplitIdx; i--) {
            if (/^\s$/u.test(chars[offset + i])) {
                splitRel = i;
                break;
            }
        }

        if (splitRel > 0) {
            const chunkStr = chars.slice(offset, offset + splitRel).join('').replace(/[ \t]+$/g, '');
            if (chunkStr !== '') {
                out.push(chunkStr);
                offset += splitRel + 1;
            } else {
                out.push(chars.slice(offset, offset + L).join(''));
                offset += L;
            }
        } else {
            out.push(chars.slice(offset, offset + L).join(''));
            offset += L;
        }
    }

    return out.length > 0 ? out : [chars.slice(0, L).join('')];
}

function syncComposerEditMaxLength() {
    const ta = document.getElementById('composer-textarea');
    if (!ta) return;
    if (store.editMsg) {
        const maxCp = Math.max(100, Number((store.settings && store.settings.max_msg_len) || 2000));
        const cps = Array.from(ta.value || '');
        if (cps.length > maxCp) {
            const clamped = cps.slice(0, maxCp).join('');
            ta.value = clamped;
        }
        const curVal = ta.value || '';
        const curCps = Array.from(curVal).length;
        const surrogateExtra = Math.max(0, curVal.length - curCps);
        ta.setAttribute('maxlength', String(maxCp + surrogateExtra));
        ta.dataset.editHardCap = String(maxCp);
        const ctxTxt = document.getElementById('composer-context-text');
        if (ctxTxt) {
            const counterStr = t('edit_len_counter_tpl')
                .replace('{cur}', formatLocalizedCount(curCps))
                .replace('{max}', formatLocalizedCount(maxCp));
            ctxTxt.textContent = `${t('editing_msg')}${store.editMsg.id} ${counterStr}`;
        }
    } else {
        if (ta.hasAttribute('maxlength')) ta.removeAttribute('maxlength');
        delete ta.dataset.editHardCap;
    }
}

function updateComposerContextBar() {
    const bar = document.getElementById('composer-context-bar');
    const txt = document.getElementById('composer-context-text');
    if (store.replyToMsg) {
        bar.classList.remove('hidden');
        txt.textContent = `${t('replying_to')}${store.replyToMsg.author_name}: ${(store.replyToMsg.body || '📎').slice(0, 60)}`;
        syncComposerEditMaxLength();
    } else if (store.editMsg) {
        bar.classList.remove('hidden');
        txt.textContent = `${t('editing_msg')}${store.editMsg.id}`;
        syncComposerEditMaxLength();
    } else {
        bar.classList.add('hidden');
        txt.textContent = '';
        syncComposerEditMaxLength();
    }
}

/* ---------------- OPTIMISTIC SEND MESSAGE WITH STATUS TICKS & SMART MULTI-MESSAGE SPLITTING ---------------- */
async function sendCurrentMessage() {
    const chat = getActiveChat();
    if (!chat) return;
    const ta = document.getElementById('composer-textarea');
    const text = ta.value.trim();
    if (!text) return;
    TypingIndicatorManager.stopTyping(chat.id);
    const maxMsgLen = Math.max(100, Number((store.settings && store.settings.max_msg_len) || 2000));
    const textCpLen = Array.from(text).length;

    if (store.editMsg) {
        // Strict hard limit on message editing ONLY (no multi-message splitting when editing)
        if (textCpLen > maxMsgLen) {
            toast(t('err_msg_too_long_tpl').replace('{max}', formatLocalizedCount(maxMsgLen)), true);
            return;
        }
        if (store.inChatUnreadByChat) store.inChatUnreadByChat[chat.id] = 0;
        const editTarget = store.editMsg;
        let payload = { message_id: editTarget.id, body: text };
        if (chat.type === 'secret') {
            try {
                const enc = await E2EE.encryptText(chat, text);
                payload = { message_id: editTarget.id, cipher: enc.cipher, iv: enc.iv };
            } catch (e) {
                toast(e.message, true);
                return;
            }
        }
        const res = await apiCall('message_edit', payload);
        if (res.ok) {
            store.editMsg = null;
            const restoredAfterEdit = (store.preEditDraftByChat && typeof store.preEditDraftByChat[chat.id] === 'string')
                ? store.preEditDraftByChat[chat.id]
                : '';
            if (store.preEditDraftByChat) delete store.preEditDraftByChat[chat.id];
            ta.value = restoredAfterEdit;
            if (store.chatDrafts) {
                if (restoredAfterEdit !== '') store.chatDrafts[chat.id] = restoredAfterEdit;
                else delete store.chatDrafts[chat.id];
            }
            updateComposerContextBar();
            autoResizeComposerInput();
            toast(t('msg_edited_toast'));
            await selectChat(chat.id);
        } else {
            toast(res.message || t('err_generic'), true);
        }
        return;
    }

    if (store.inChatUnreadByChat) store.inChatUnreadByChat[chat.id] = 0;
    const ttlVal = getEffectiveComposerTtlPayload();
    const chunks = splitLongMessageIntoChunks(text, maxMsgLen);
    if (chunks.length === 0) return;
    if (chunks.length > 40) {
        toast(t('err_msg_too_long_tpl').replace('{max}', formatLocalizedCount(maxMsgLen * 40)), true);
        return;
    }

    const replyId = store.replyToMsg ? store.replyToMsg.id : null;
    store.replyToMsg = null;
    ta.value = '';
    if (store.chatDrafts) delete store.chatDrafts[chat.id];
    if (isDraftSyncAllowedForChat(chat.id)) {
        DraftSyncManager.markDirty(chat.id, '', 0);
    }
    autoResizeComposerInput();
    updateComposerContextBar();

    const wasViewingOlderWindow = Boolean(store.hasMoreAfterByChat && store.hasMoreAfterByChat[chat.id]);
    store._forcePinBottomUntil = Date.now() + 2000;
    store._sendingMessageCount = Number(store._sendingMessageCount || 0) + 1;

    try {
        const baseTemp = -Date.now();
        const tempIds = chunks.map((_, idx) => baseTemp - idx);
        const nowSec = Math.floor(Date.now() / 1000);
        if (!store.messages[chat.id]) store.messages[chat.id] = [];

        if (!wasViewingOlderWindow) {
            const vpNow = document.getElementById('messages-viewport');
            chunks.forEach((chunkTxt, idx) => {
                const tId = tempIds[idx];
                const optimisticMsg = {
                    id: tId,
                    chat_id: chat.id,
                    user_id: store.user.id,
                    author_name: store.user.name,
                    author_chat_role: chat.my_role || '',
                    is_chat_admin: (chat.my_role === 'owner' || chat.my_role === 'admin') ? 1 : 0,
                    has_admin_badge: store.user.has_admin_badge,
                    kind: 'text',
                    body: chunkTxt,
                    created_at: nowSec,
                    tick_status: 'pending',
                    _optimistic: true
                };
                store.messages[chat.id].push(optimisticMsg);
                if (vpNow && store.activeChatId === chat.id) {
                    const optRow = document.createElement('div');
                    optRow.className = 'msg-row mine';
                    optRow.dataset.msgId = String(tId);
                    const optBubble = document.createElement('div');
                    optBubble.className = 'msg-bubble';
                    const optBadge = createAuthorAdminBadge(optimisticMsg, chat);
                    if (optBadge) {
                        const authDiv = document.createElement('div');
                        authDiv.className = 'msg-author';
                        authDiv.style.justifyContent = 'flex-end';
                        authDiv.appendChild(optBadge);
                        optBubble.appendChild(authDiv);
                    }
                    const optTxt = document.createElement('div');
                    optTxt.className = 'msg-text';
                    optTxt.setAttribute('dir', 'auto');
                    appendLinkedText(optTxt, formatDynamicServerText(chunkTxt));
                    optBubble.appendChild(optTxt);
                    const optMeta = document.createElement('div');
                    optMeta.className = 'msg-meta';
                    const optTime = document.createElement('span');
                    optTime.textContent = formatTimeOnly(optimisticMsg.created_at);
                    optMeta.appendChild(optTime);
                    optMeta.appendChild(createTickIcon('pending'));
                    optBubble.appendChild(optMeta);
                    optRow.appendChild(optBubble);
                    vpNow.appendChild(optRow);
                }
            });
            if (vpNow && store.activeChatId === chat.id) {
                vpNow.scrollTop = vpNow.scrollHeight;
            }
        }

        let sendPayload = {
            chat_id: chat.id,
            kind: 'text',
            body: chunks.length === 1 ? chunks[0] : '',
            reply_to: replyId,
            ttl: ttlVal
        };
        if (chunks.length > 1 && chat.type !== 'secret') {
            sendPayload.body_chunks = chunks;
        }

        if (chat.type === 'secret') {
            try {
                if (chunks.length === 1) {
                    const enc = await E2EE.encryptText(chat, chunks[0]);
                    sendPayload.body = '';
                    sendPayload.cipher = enc.cipher;
                    sendPayload.iv = enc.iv;
                } else {
                    const encChunks = [];
                    for (let ci = 0; ci < chunks.length; ci++) {
                        const enc = await E2EE.encryptText(chat, chunks[ci]);
                        encChunks.push({ cipher: enc.cipher, iv: enc.iv });
                    }
                    sendPayload.body = '';
                    sendPayload.cipher_chunks = encChunks;
                }
            } catch (e) {
                const tempSet = new Set(tempIds);
                store.messages[chat.id] = store.messages[chat.id].filter(m => !tempSet.has(m.id));
                tempIds.forEach(tId => {
                    const deadOpt = document.querySelector(`#messages-viewport .msg-row[data-msg-id="${tId}"]`);
                    if (deadOpt) deadOpt.remove();
                });
                toast(e.message, true);
                return;
            }
        }

        const res = await apiCall('message_send', sendPayload);
        const tempSet = new Set(tempIds);
        store.messages[chat.id] = store.messages[chat.id].filter(m => !tempSet.has(m.id));
        if (res.ok && res.data.message) {
            store._forcePinBottomUntil = Date.now() + 1800;
            resetComposerTtlAfterSend();
            if (typeof playChatActionSound === 'function') playChatActionSound('send');
            const returnedMsgs = (Array.isArray(res.data.messages) && res.data.messages.length > 0)
                ? res.data.messages
                : [res.data.message];
            returnedMsgs.forEach((srvMsg, idx) => {
                if (srvMsg && srvMsg.id && chunks[idx] !== undefined) {
                    store.decryptedTextCache[srvMsg.id] = chunks[idx];
                }
            });
            if (returnedMsgs.length > 1) {
                toast(t('multi_split_sent_toast').replace('{n}', formatLocalizedCount(returnedMsgs.length)));
            }
            if (wasViewingOlderWindow) {
                store.hasMoreAfterByChat[chat.id] = false;
                await selectChat(chat.id);
            } else if (returnedMsgs.length === 1) {
                const confirmedMsg = returnedMsgs[0];
                const tempId = tempIds[0];
                upsertChatMessage(chat.id, confirmedMsg);
                // Item #26: Upgrade optimistic DOM row in-place when possible so zero full-DOM blink occurs!
                const vpNow = document.getElementById('messages-viewport');
                const existingOptEl = vpNow ? vpNow.querySelector(`.msg-row[data-msg-id="${tempId}"]`) : null;
                if (vpNow && existingOptEl && store.activeChatId === chat.id && !confirmedMsg.reply_preview && !confirmedMsg.file) {
                    existingOptEl.dataset.msgId = String(confirmedMsg.id);
                    store.decryptedTextCache[confirmedMsg.id] = chunks[0];
                    const selChk = document.createElement('span');
                    selChk.className = 'msg-select-chk';
                    selChk.addEventListener('click', ev => {
                        ev.stopPropagation();
                        toggleMessageSelection(confirmedMsg.id);
                    });
                    existingOptEl.insertBefore(selChk, existingOptEl.firstChild);
                    const bub = existingOptEl.querySelector('.msg-bubble');
                    const meta = existingOptEl.querySelector('.msg-meta');
                    if (meta) {
                        meta.innerHTML = '';
                        if (confirmedMsg.expires_at || confirmedMsg.burn_after) {
                            const ttlSpan = document.createElement('span');
                            ttlSpan.className = 'ttl-pill';
                            ttlSpan.dataset.msgId = String(confirmedMsg.id);
                            if (confirmedMsg.expires_at) {
                                const rem = Math.max(0, Number(confirmedMsg.expires_at) - Math.floor(Date.now() / 1000));
                                ttlSpan.textContent = `⏱️ ${formatCoarseRemainingTtl(rem)}`;
                            } else {
                                ttlSpan.textContent = `🔥 ${formatCoarseRemainingTtl(confirmedMsg.burn_after)} (${t('self_destruct_wait_view')})`;
                            }
                            meta.appendChild(ttlSpan);
                        }
                        const tm = document.createElement('span');
                        tm.textContent = formatTimeOnly(confirmedMsg.created_at);
                        meta.appendChild(tm);
                        const tickSt = (confirmedMsg.id <= (chat.peer_last_read_id || 0)) ? 'seen' : (confirmedMsg.tick_status || 'sent');
                        meta.appendChild(createTickIcon(tickSt));
                        const menuBtn = document.createElement('button');
                        menuBtn.type = 'button';
                        menuBtn.style.cssText = 'font-size:14px;color:inherit;opacity:0.75;padding:0 4px';
                        menuBtn.textContent = '⋮';
                        menuBtn.title = t('msg_actions_title');
                        menuBtn.addEventListener('click', ev => {
                            ev.stopPropagation();
                            openMessageActionModal(confirmedMsg, chat, chunks[0]);
                        });
                        meta.appendChild(menuBtn);
                    }
                    if (bub) {
                        attachMessageGesturesAndMenu(existingOptEl, bub, confirmedMsg, chat, chunks[0]);
                    }
                    chat._lastRenderedPeerRead = Number(chat.peer_last_read_id || 0);
                    vpNow.scrollTop = vpNow.scrollHeight;
                } else {
                    await renderMessagesViewport(true);
                }
            } else {
                returnedMsgs.forEach(cm => upsertChatMessage(chat.id, cm));
                await renderMessagesViewport(true);
            }
            const cRes = await apiCall('chats_list');
            if (cRes.ok) {
                store.chats = cRes.data.chats;
                renderChatList();
            }
        } else {
            let removedAny = false;
            tempIds.forEach(tId => {
                const deadOpt = document.querySelector(`#messages-viewport .msg-row[data-msg-id="${tId}"]`);
                if (deadOpt) {
                    deadOpt.remove();
                    removedAny = true;
                }
            });
            if (!removedAny) await renderMessagesViewport(true);
            toast(res.message || t('err_generic'), true);
        }
    } finally {
        store._sendingMessageCount = Math.max(0, Number(store._sendingMessageCount || 1) - 1);
    }
}

/* ---------------- FILE / VOICE UPLOAD WITH CAPTION MODAL ---------------- */

function makeRandomHexId(byteLen = 16) {
    const arr = new Uint8Array(byteLen);
    if (window.crypto && typeof window.crypto.getRandomValues === 'function') {
        window.crypto.getRandomValues(arr);
    } else {
        for (let i = 0; i < byteLen; i++) arr[i] = Math.floor(Math.random() * 256);
    }
    return Array.from(arr).map(b => b.toString(16).padStart(2, '0')).join('');
}

async function uploadBlobInChunks(actionName, blob, onProgress = null) {
    const uploadId = makeRandomHexId(16);
    const srvMaxChunk = Number((store.settings && store.settings.server_upload_chunk_bytes) || 1048576);
    const chunkSize = Math.min(1048576, Math.max(65536, srvMaxChunk));
    const total = blob.size;
    let offset = 0;
    let chunkIdx = 0;

    const sendSingleSlice = async (sliceBlob, idx, retriedCsrf = false) => {
        const headers = { 'Content-Type': 'application/octet-stream' };
        if (store.csrf) headers['X-CSRF-Token'] = store.csrf;
        const csrfQ = store.csrf ? `&csrf_token=${encodeURIComponent(store.csrf)}` : '';
        const resp = await fetch(`?a=api&do=${encodeURIComponent(actionName)}&upload_id=${uploadId}&chunk_index=${idx}${csrfQ}`, {
            method: 'POST',
            headers,
            credentials: 'same-origin',
            body: sliceBlob
        });
        let json = null;
        try { json = await resp.json(); } catch (e) {
            if (resp.status === 413) {
                return { ok: false, error: 'file_too_large', message: t('err_file_too_large_server') };
            }
        }
        if (json && !json.ok && json.error === 'csrf_invalid' && !retriedCsrf) {
            const fresh = await refreshCsrfTokenFromBoot();
            if (fresh) return sendSingleSlice(sliceBlob, idx, true);
        }
        if (json && !json.ok && json.error) {
            json.message = localizeApiError(json.error, json.message, json.details);
        }
        return json;
    };

    while (offset < total || (total === 0 && chunkIdx === 0)) {
        const end = Math.min(total, offset + chunkSize);
        const slice = blob.slice(offset, end);
        const json = await sendSingleSlice(slice, chunkIdx, false);
        if (!json || !json.ok) {
            return { ok: false, error: (json && json.error) || 'chunk_failed', message: (json && json.message) || t('err_upload_failed') };
        }
        offset = end;
        chunkIdx++;
        if (typeof onProgress === 'function' && total > 0) {
            onProgress(Math.min(100, Math.round((offset / total) * 100)));
        }
        if (total === 0) break;
    }
    return { ok: true, upload_id: uploadId };
}

function buildAdminPaginationControls({ totalItems, page, pageSize, pageSizeOptions = [10, 20, 50, 100], onPageChange, onPageSizeChange }) {
    const bar = document.createElement('div');
    bar.className = 'adm-pager-bar';

    const safeSize = Math.max(1, Number(pageSize) || 20);
    const totalPages = Math.max(1, Math.ceil(totalItems / safeSize));
    const curPage = Math.min(totalPages, Math.max(1, Number(page) || 1));
    const fromIdx = totalItems === 0 ? 0 : ((curPage - 1) * safeSize + 1);
    const toIdx = Math.min(totalItems, curPage * safeSize);

    const info = document.createElement('div');
    info.className = 'adm-pager-info';
    info.textContent = t('adm_page_showing_tpl')
        .replace('{from}', formatLocalizedCount(fromIdx))
        .replace('{to}', formatLocalizedCount(toIdx))
        .replace('{total}', formatLocalizedCount(totalItems));
    bar.appendChild(info);

    const ctrls = document.createElement('div');
    ctrls.className = 'adm-pager-controls';

    const szLbl = document.createElement('span');
    szLbl.style.cssText = 'font-size:12px;color:var(--text-secondary);font-weight:600';
    szLbl.textContent = t('adm_page_size_lbl');
    ctrls.appendChild(szLbl);

    const szSel = document.createElement('select');
    szSel.className = 'adm-pager-size';
    pageSizeOptions.forEach(optVal => {
        const o = document.createElement('option');
        o.value = String(optVal);
        o.textContent = formatLocalizedCount(optVal);
        if (Number(optVal) === safeSize) o.selected = true;
        szSel.appendChild(o);
    });
    szSel.addEventListener('change', () => {
        const nextSz = parseInt(szSel.value, 10) || 20;
        onPageSizeChange(nextSz);
    });
    ctrls.appendChild(szSel);

    const makePageBtn = (txt, targetPage, disabled, isActive = false) => {
        const b = document.createElement('button');
        b.type = 'button';
        b.className = 'adm-pager-btn' + (isActive ? ' active' : '');
        b.disabled = !!disabled;
        b.textContent = txt;
        if (!disabled && !isActive) {
            b.addEventListener('click', () => onPageChange(targetPage));
        }
        return b;
    };

    ctrls.appendChild(makePageBtn(t('adm_page_prev'), curPage - 1, curPage <= 1));

    const pagesToShow = [];
    if (totalPages <= 7) {
        for (let p = 1; p <= totalPages; p++) pagesToShow.push(p);
    } else {
        pagesToShow.push(1);
        const startP = Math.max(2, curPage - 1);
        const endP = Math.min(totalPages - 1, curPage + 1);
        if (startP > 2) pagesToShow.push('...');
        for (let p = startP; p <= endP; p++) pagesToShow.push(p);
        if (endP < totalPages - 1) pagesToShow.push('...');
        pagesToShow.push(totalPages);
    }

    pagesToShow.forEach(p => {
        if (p === '...') {
            const dots = document.createElement('span');
            dots.style.cssText = 'padding:0 4px;color:var(--text-muted);font-weight:700';
            dots.textContent = '…';
            ctrls.appendChild(dots);
        } else {
            ctrls.appendChild(makePageBtn(formatLocalizedCount(p), p, false, p === curPage));
        }
    });

    ctrls.appendChild(makePageBtn(t('adm_page_next'), curPage + 1, curPage >= totalPages));
    bar.appendChild(ctrls);
    return { bar, curPage, totalPages, fromOffset: (curPage - 1) * safeSize, toOffset: (curPage - 1) * safeSize + safeSize };
}

function openMessageViewersModal(msg, chat) {
    if (!msg || !chat) return;
    let curPage = 1;
    let curPerPage = 20;
    let curQuery = '';
    let searchTimer = null;

    openSubModal(t('msg_viewers_modal_title'), (body, closeSub) => {
        const ctrlRow = document.createElement('div');
        ctrlRow.style.cssText = 'display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-bottom:10px';

        const searchIn = document.createElement('input');
        searchIn.type = 'text';
        searchIn.className = 'input';
        searchIn.style.flex = '1 1 180px';
        searchIn.placeholder = t('msg_viewers_search_ph');

        const sizeSel = document.createElement('select');
        sizeSel.className = 'input';
        sizeSel.style.cssText = 'width:auto;min-width:110px;flex:0 0 auto';
        [10, 20, 50, 100].forEach(sz => {
            const opt = document.createElement('option');
            opt.value = String(sz);
            opt.textContent = `${formatLocalizedCount(sz)} / ${t('adm_per_page_lbl') || 'صفحه'}`;
            if (sz === curPerPage) opt.selected = true;
            sizeSel.appendChild(opt);
        });

        ctrlRow.appendChild(searchIn);
        ctrlRow.appendChild(sizeSel);
        body.appendChild(ctrlRow);

        const countBar = document.createElement('div');
        countBar.style.cssText = 'font-size:12px;font-weight:700;color:var(--text-secondary);margin-bottom:8px';
        body.appendChild(countBar);

        const listBox = document.createElement('div');
        listBox.style.cssText = 'display:flex;flex-direction:column;gap:6px;max-height:52dvh;overflow-y:auto';
        body.appendChild(listBox);

        const pagerBox = document.createElement('div');
        pagerBox.style.cssText = 'display:flex;align-items:center;justify-content:space-between;gap:8px;margin-top:10px;flex-wrap:wrap';
        body.appendChild(pagerBox);

        const loadViewers = async () => {
            listBox.innerHTML = '<div style="padding:18px;text-align:center;color:var(--text-muted);font-weight:700">⏳ ...</div>';
            const r = await apiCall('message_viewers', {
                message_id: msg.id,
                q: curQuery,
                page: curPage,
                per_page: curPerPage
            });
            listBox.innerHTML = '';
            pagerBox.innerHTML = '';
            if (!r.ok) {
                const errDiv = document.createElement('div');
                errDiv.className = 'card-box';
                errDiv.style.color = 'var(--danger)';
                errDiv.textContent = r.message || t('err_generic');
                listBox.appendChild(errDiv);
                return;
            }
            const d = r.data || {};
            const total = Number(d.total || 0);
            const totalPages = Math.max(1, Number(d.total_pages || 1));
            curPage = Math.max(1, Math.min(totalPages, Number(d.page || 1)));
            const subTitleEl = document.getElementById('sub-modal-title');
            if (subTitleEl) {
                subTitleEl.textContent = `${t('msg_viewers_modal_title')} (${formatLocalizedCount(total)})`;
            }
            countBar.textContent = `${t('msg_viewers_modal_title')}: ${formatLocalizedCount(total)}`;

            const items = Array.isArray(d.items) ? d.items : [];
            if (items.length === 0) {
                const emp = document.createElement('div');
                emp.className = 'card-box';
                emp.style.cssText = 'text-align:center;color:var(--text-muted);padding:18px';
                emp.textContent = t('msg_viewers_empty');
                listBox.appendChild(emp);
            } else {
                items.forEach(it => {
                    const row = document.createElement('div');
                    row.className = 'card-box';
                    row.style.cssText = 'margin:0;padding:8px 10px;display:flex;align-items:center;justify-content:space-between;gap:10px;cursor:pointer';
                    const left = document.createElement('div');
                    left.style.cssText = 'display:flex;align-items:center;gap:10px;min-width:0;flex:1';
                    const av = document.createElement('div');
                    av.className = 'avatar avatar-sm';
                    renderAvatarNode(av, it.name || 'U', it.avatar || '');
                    left.appendChild(av);

                    const metaCol = document.createElement('div');
                    metaCol.style.cssText = 'min-width:0;flex:1';
                    const nmRow = document.createElement('div');
                    nmRow.style.cssText = 'font-weight:800;font-size:13px;display:flex;align-items:center;gap:5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis';
                    const nmSpan = document.createElement('span');
                    nmSpan.textContent = formatDisplayName(it.name || '');
                    nmRow.appendChild(nmSpan);
                    if (it.has_admin_badge) nmRow.appendChild(createAdminBadgeNode());
                    metaCol.appendChild(nmRow);

                    const subU = document.createElement('div');
                    subU.style.cssText = 'font-size:11.5px;color:var(--text-muted);direction:ltr;text-align:start';
                    subU.textContent = it.username ? `@${it.username}` : `#${it.user_id}`;
                    metaCol.appendChild(subU);
                    left.appendChild(metaCol);

                    const rightTime = document.createElement('div');
                    rightTime.style.cssText = 'font-size:11.5px;color:var(--text-secondary);text-align:end;flex-shrink:0';
                    rightTime.textContent = `🕒 ${formatDate(it.read_at, true)}`;

                    row.appendChild(left);
                    row.appendChild(rightTime);
                    row.addEventListener('click', () => {
                        closeSub();
                        openUserMiniProfile(it.user_id);
                    });
                    listBox.appendChild(row);
                });
            }

            const prevBtn = document.createElement('button');
            prevBtn.type = 'button';
            prevBtn.className = 'btn btn-secondary btn-sm';
            prevBtn.disabled = curPage <= 1;
            prevBtn.textContent = t('adm_page_prev') || '◀';
            prevBtn.addEventListener('click', () => {
                if (curPage > 1) {
                    curPage--;
                    loadViewers();
                }
            });

            const pageInfo = document.createElement('span');
            pageInfo.style.cssText = 'font-size:12px;font-weight:700;color:var(--text-secondary)';
            pageInfo.textContent = `${formatLocalizedCount(curPage)} / ${formatLocalizedCount(totalPages)}`;

            const nextBtn = document.createElement('button');
            nextBtn.type = 'button';
            nextBtn.className = 'btn btn-secondary btn-sm';
            nextBtn.disabled = curPage >= totalPages;
            nextBtn.textContent = t('adm_page_next') || '▶';
            nextBtn.addEventListener('click', () => {
                if (curPage < totalPages) {
                    curPage++;
                    loadViewers();
                }
            });

            pagerBox.appendChild(prevBtn);
            pagerBox.appendChild(pageInfo);
            pagerBox.appendChild(nextBtn);
        };

        searchIn.addEventListener('input', () => {
            clearTimeout(searchTimer);
            searchTimer = setTimeout(() => {
                curQuery = searchIn.value.trim();
                curPage = 1;
                loadViewers();
            }, 220);
        });
        sizeSel.addEventListener('change', () => {
            curPerPage = parseInt(sizeSel.value || '20', 10) || 20;
            curPage = 1;
            loadViewers();
        });

        loadViewers();
    });
}

function openFileUploadWithCaptionModal(file, kind = 'file') {
    const chat = getActiveChat();
    if (!chat || !file) return;

    // Item #8: Transfer any typed draft text from #composer-textarea into the file's caption input,
    // and restore it back into #composer-textarea if sending the file is cancelled!
    const composerTa = document.getElementById('composer-textarea');
    const transferredComposerText = (composerTa && composerTa.value.trim() !== '') ? composerTa.value : '';
    if (transferredComposerText !== '' && composerTa) {
        composerTa.value = '';
        if (typeof autoResizeComposerInput === 'function') autoResizeComposerInput();
    }
    let uploadCommitted = false;

    const rawFn = String(file.name || '').toLowerCase();
    const rawMime = String(file.type || '').toLowerCase();
    const ext = (rawFn.includes('.') ? rawFn.split('.').pop() : '').slice(0, 8);
    const isImageFile = kind === 'file' && (rawMime.startsWith('image/') || ['jpg', 'jpeg', 'png', 'gif', 'webp'].includes(ext));
    const isVideoFile = kind === 'file' && (rawMime.startsWith('video/') || ['mp4', 'webm', 'mov', 'mkv', 'm4v'].includes(ext));
    const isAudioFile = kind === 'voice' || rawMime.startsWith('audio/') || ['mp3', 'ogg', 'opus', 'wav', 'm4a', 'flac', 'aac'].includes(ext);
    const isTextFile = kind === 'file' && !isImageFile && !isVideoFile && !isAudioFile && (rawMime.startsWith('text/') || ['txt', 'md', 'csv', 'json', 'log'].includes(ext));
    const canOfferSpoilerCover = (isImageFile || isVideoFile);
    let previewObjUrl = null;

    openModal(t('upload_modal_title'), (body, close) => {
        // Item #9: Real File Preview or Structured Document Placeholder Card
        const stage = document.createElement('div');
        stage.className = 'upload-preview-stage';

        const coveredBadge = document.createElement('div');
        coveredBadge.className = 'adm-badge-pill primary hidden';
        coveredBadge.textContent = t('upload_preview_badge_covered');

        if (isImageFile) {
            previewObjUrl = URL.createObjectURL(file);
            const pImg = document.createElement('img');
            pImg.src = previewObjUrl;
            pImg.alt = file.name;
            stage.appendChild(pImg);
        } else if (isVideoFile) {
            previewObjUrl = URL.createObjectURL(file);
            const pVid = document.createElement('video');
            pVid.src = previewObjUrl;
            pVid.controls = true;
            pVid.playsInline = true;
            pVid.preload = 'metadata';
            stage.appendChild(pVid);
        } else if (isAudioFile) {
            previewObjUrl = URL.createObjectURL(file);
            const pAud = document.createElement('audio');
            pAud.src = previewObjUrl;
            pAud.controls = true;
            pAud.preload = 'metadata';
            stage.appendChild(pAud);
        } else if (isTextFile && file.size <= 524288) {
            const pre = document.createElement('pre');
            pre.className = 'embedded-txt-body';
            pre.style.cssText = 'width:100%;max-height:150px;margin:0;border-radius:10px';
            pre.setAttribute('dir', 'auto');
            pre.textContent = t('txt_loading');
            if (typeof file.slice === 'function') {
                const reader = new FileReader();
                reader.onload = () => {
                    const txt = String(reader.result || '');
                    pre.textContent = txt.length > 1200 ? (txt.slice(0, 1200) + '\n…') : (txt || t('txt_empty'));
                };
                reader.onerror = () => { pre.textContent = file.name; };
                reader.readAsText(file.slice(0, 4096));
            }
            stage.appendChild(pre);
        } else {
            const docCard = document.createElement('div');
            docCard.className = 'upload-doc-placeholder';
            const badge = document.createElement('div');
            badge.className = 'upload-doc-ext-badge';
            badge.innerHTML = `<svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="2"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/></svg><span>${esc((ext || 'FILE').toUpperCase())}</span>`;
            const docMeta = document.createElement('div');
            docMeta.style.cssText = 'min-width:0;flex:1';
            const dName = document.createElement('div');
            dName.style.cssText = 'font-weight:800;font-size:13px;word-break:break-word';
            dName.textContent = file.name;
            const dSub = document.createElement('div');
            dSub.style.cssText = 'font-size:11.5px;color:var(--text-muted);margin-top:2px';
            dSub.textContent = `${formatBytes(file.size)}${file.type ? ' • ' + file.type : ''}`;
            docMeta.appendChild(dName);
            docMeta.appendChild(dSub);
            docCard.appendChild(badge);
            docCard.appendChild(docMeta);
            stage.appendChild(docCard);
        }

        if (isImageFile || isVideoFile || isAudioFile || isTextFile) {
            const metaFoot = document.createElement('div');
            metaFoot.style.cssText = 'font-size:12px;font-weight:700;color:var(--text-secondary);text-align:center;word-break:break-word';
            metaFoot.textContent = `${file.name} (${formatBytes(file.size)})`;
            stage.appendChild(metaFoot);
        }
        stage.appendChild(coveredBadge);
        body.appendChild(stage);

        // Item #1: Two-Step Emoji-Cover Option for Photos & Videos
        let chkSpoiler = null;
        if (canOfferSpoilerCover) {
            const spLabel = document.createElement('label');
            spLabel.className = 'upload-spoiler-opt-card';
            chkSpoiler = document.createElement('input');
            chkSpoiler.type = 'checkbox';
            chkSpoiler.id = 'upload-spoiler-checkbox';
            const spTxtCol = document.createElement('div');
            spTxtCol.style.cssText = 'min-width:0;flex:1';
            const spMain = document.createElement('div');
            spMain.style.cssText = 'font-size:13px;font-weight:800;color:var(--text-main)';
            spMain.textContent = t('upload_spoiler_opt_lbl');
            const spDesc = document.createElement('div');
            spDesc.style.cssText = 'font-size:11.5px;color:var(--text-secondary);line-height:1.5;margin-top:3px';
            spDesc.textContent = t('upload_spoiler_opt_desc');
            spTxtCol.appendChild(spMain);
            spTxtCol.appendChild(spDesc);
            spLabel.appendChild(chkSpoiler);
            spLabel.appendChild(spTxtCol);
            chkSpoiler.addEventListener('change', () => {
                coveredBadge.classList.toggle('hidden', !chkSpoiler.checked);
            });
            body.appendChild(spLabel);
        }

        const fg = document.createElement('div');
        fg.className = 'form-group';
        const lbl = document.createElement('label');
        lbl.textContent = t('caption_label');
        const capInput = document.createElement('textarea');
        capInput.className = 'input';
        capInput.rows = 3;
        capInput.placeholder = t('caption_placeholder');
        if (transferredComposerText !== '') {
            capInput.value = transferredComposerText;
        }
        fg.appendChild(lbl);
        fg.appendChild(capInput);
        body.appendChild(fg);

        const appDlgEl = document.getElementById('app-modal');
        if (appDlgEl) {
            const onModalDismissRestore = () => {
                if (previewObjUrl) {
                    try { URL.revokeObjectURL(previewObjUrl); } catch (e) {}
                    previewObjUrl = null;
                }
                if (!uploadCommitted && transferredComposerText !== '') {
                    const taNow = document.getElementById('composer-textarea');
                    const textToRestore = capInput.value.trim() !== '' ? capInput.value : transferredComposerText;
                    if (taNow && textToRestore !== '') {
                        taNow.value = taNow.value.trim() !== '' ? (taNow.value + '\n' + textToRestore) : textToRestore;
                        if (typeof autoResizeComposerInput === 'function') autoResizeComposerInput();
                        try { taNow.focus(); } catch (e) {}
                    }
                }
            };
            appDlgEl.addEventListener('close', onModalDismissRestore, { once: true });
        }

        const sendBtn = document.createElement('button');
        sendBtn.className = 'btn btn-primary btn-block';
        sendBtn.textContent = t('upload_send_btn');
        sendBtn.addEventListener('click', async () => {
            const maxMb = Number((store.settings && store.settings.max_file_mb) || 16);
            if (maxMb > 0 && file.size > Math.round(maxMb * 1048576)) {
                toast(`${t('err_upload_failed')} (${formatLocalizedCount(maxMb)} ${t('unit_mb')})`, true);
                return;
            }
            sendBtn.disabled = true;
            sendBtn.textContent = t('uploading_wait');
            uploadCommitted = true;
            const ttlPayloadVal = getEffectiveComposerTtlPayload();
            const spoilerVal = (chkSpoiler && chkSpoiler.checked) ? 1 : 0;
            const capText = capInput.value.trim();
            let uploadBlob = file;
            let encryptedFlag = 0;
            let fileIvStr = '';
            let cipherCap = '';
            let ivCap = '';

            if (chat.type === 'secret') {
                try {
                    const encFile = await E2EE.encryptBlob(chat, file);
                    uploadBlob = encFile.blob;
                    encryptedFlag = 1;
                    fileIvStr = encFile.iv;
                    if (capText) {
                        const enc = await E2EE.encryptText(chat, capText);
                        cipherCap = enc.cipher;
                        ivCap = enc.iv;
                    }
                } catch (e) {
                    sendBtn.disabled = false;
                    sendBtn.textContent = t('upload_send_btn');
                    toast(e.message || t('e2ee_key_not_ready'), true);
                    return;
                }
            }
            let replyMsgId = 0;
            if (store.replyToMsg) {
                replyMsgId = store.replyToMsg.id;
                store.replyToMsg = null;
                updateComposerContextBar();
            }

            let res;
            const srvSafeChunk = Math.min(1048576, Math.max(65536, Number((store.settings && store.settings.server_upload_chunk_bytes) || 1048576)));
            const chunkThreshold = Math.min(900000, Math.floor(srvSafeChunk * 0.85));
            if (uploadBlob.size > chunkThreshold) {
                const chunkRes = await uploadBlobInChunks('upload_chunk', uploadBlob, pct => {
                    sendBtn.textContent = `${t('uploading_wait')} (${formatLocalizedCount(pct)}%)`;
                });
                if (!chunkRes.ok) {
                    sendBtn.disabled = false;
                    sendBtn.textContent = t('upload_send_btn');
                    toast(chunkRes.message || t('err_upload_failed'), true);
                    return;
                }
                const upMeta = {
                    chat_id: chat.id,
                    kind,
                    ttl: ttlPayloadVal,
                    spoiler: spoilerVal,
                    chunk_upload_id: chunkRes.upload_id,
                    file_name: file.name
                };
                if (encryptedFlag) {
                    upMeta.encrypted = 1;
                    upMeta.file_iv = fileIvStr;
                    if (cipherCap) {
                        upMeta.cipher = cipherCap;
                        upMeta.iv = ivCap;
                    }
                } else {
                    upMeta.caption = capText;
                }
                if (replyMsgId > 0) upMeta.reply_to = replyMsgId;
                res = await apiCall('upload', upMeta);
            } else {
                const fd = new FormData();
                fd.append('chat_id', String(chat.id));
                fd.append('kind', kind);
                fd.append('ttl', String(ttlPayloadVal));
                if (spoilerVal) fd.append('spoiler', '1');
                if (encryptedFlag) {
                    fd.append('encrypted', '1');
                    fd.append('file_iv', fileIvStr);
                    if (cipherCap) {
                        fd.append('cipher', cipherCap);
                        fd.append('iv', ivCap);
                    }
                } else {
                    fd.append('caption', capText);
                }
                if (replyMsgId > 0) fd.append('reply_to', String(replyMsgId));
                fd.append('file', uploadBlob, file.name);
                res = await apiCall('upload', fd, true);
            }
            close();
            if (res.ok && res.data.message) {
                store._forcePinBottomUntil = Date.now() + 2200;
                resetComposerTtlAfterSend();
                if (typeof playChatActionSound === 'function') playChatActionSound('send');
                upsertChatMessage(chat.id, res.data.message);
                await renderMessagesViewport(true);
                pinViewportToBottom(document.getElementById('messages-viewport'));
                const cRes = await apiCall('chats_list');
                if (cRes.ok) {
                    store.chats = cRes.data.chats;
                    renderChatList();
                }
                toast(t('file_sent_ok'));
            } else {
                toast(res.message || t('err_upload_failed'), true);
            }
        });
        body.appendChild(sendBtn);
    });
}

/* ---------------- REPORTING MODAL (USERS, GROUPS, CHANNELS, MESSAGES) ---------------- */
function openReportModal(targetType, targetId, targetLabel) {
    openModal('🚩 ' + t('report_title'), (body, close) => {
        const info = document.createElement('div');
        info.className = 'card-box';
        info.textContent = `[${targetType.toUpperCase()}] ${targetLabel || ('#' + targetId)}`;
        body.appendChild(info);

        const fgReason = document.createElement('div');
        fgReason.className = 'form-group';
        const l1 = document.createElement('label');
        l1.textContent = t('report_reason');
        const sel = document.createElement('select');
        sel.className = 'input';
        [
            ['spam', t('rep_reason_spam')],
            ['abuse', t('rep_reason_abuse')],
            ['scam', t('rep_reason_scam')],
            ['illegal', t('rep_reason_illegal')],
            ['other', t('rep_reason_other')]
        ].forEach(([val, txt]) => {
            const o = document.createElement('option');
            o.value = val;
            o.textContent = txt;
            sel.appendChild(o);
        });
        fgReason.appendChild(l1);
        fgReason.appendChild(sel);
        body.appendChild(fgReason);

        const fgDesc = document.createElement('div');
        fgDesc.className = 'form-group';
        const l2 = document.createElement('label');
        l2.textContent = t('report_desc');
        const descTa = document.createElement('textarea');
        descTa.className = 'input';
        descTa.rows = 4;
        descTa.required = true;
        fgDesc.appendChild(l2);
        fgDesc.appendChild(descTa);
        body.appendChild(fgDesc);

        const subBtn = document.createElement('button');
        subBtn.className = 'btn btn-danger btn-block';
        subBtn.textContent = t('submit_report');
        subBtn.addEventListener('click', async () => {
            const d = descTa.value.trim();
            if (d.length < 3) {
                toast(t('report_desc'), true);
                return;
            }
            const res = await apiCall('report_create', {
                target_type: targetType,
                target_id: targetId,
                reason: sel.value,
                description: d
            });
            if (res.ok) {
                close();
                toast(t('report_sent_toast'));
            } else {
                toast(res.message || t('err_generic'), true);
            }
        });
        body.appendChild(subBtn);
    });
}

/* ---------------- USER MINI-PROFILE CARD & DM TRIGGER FROM GROUP MEMBERS ---------------- */
async function openUserMiniProfile(userId) {
    if (!userId) return;
    const res = await apiCall('profile_get', { user_id: userId });
    if (!res.ok || !res.data.user) {
        toast(res.message || t('err_not_found'), true);
        return;
    }
    const u = res.data.user;
    openModal(t('user_profile_title'), (body, close) => {
        const card = document.createElement('div');
        card.className = 'card-box';
        card.style.textAlign = 'center';

        const av = document.createElement('div');
        av.className = 'avatar avatar-lg';
        av.style.margin = '0 auto 12px';
        renderAvatarNode(av, u.name, u.avatar);
        card.appendChild(av);

        const nameLine = document.createElement('div');
        nameLine.style.cssText = 'font-weight:800;font-size:17px;display:flex;align-items:center;justify-content:center;gap:6px;flex-wrap:wrap';
        const ns = document.createElement('span');
        ns.textContent = formatDisplayName(u.name);
        nameLine.appendChild(ns);
        if (u.has_admin_badge) {
            nameLine.appendChild(createAdminBadgeNode());
        }
        card.appendChild(nameLine);

        const uname = document.createElement('div');
        uname.style.cssText = 'color:var(--text-muted);font-size:13px;margin-top:2px';
        const presStr = formatPeerPresenceText(u);
        uname.textContent = formatHandleLabel(u) + (presStr ? ` • ${presStr}` : '');
        card.appendChild(uname);

        if (u.bio) {
            const bio = document.createElement('p');
            bio.style.cssText = 'font-size:13.5px;margin:10px 0 0;color:var(--text-secondary)';
            bio.textContent = formatUserBio(u.bio);
            card.appendChild(bio);
        }
        body.appendChild(card);

        if (store.user && u.id !== store.user.id) {
            const actions = document.createElement('div');
            actions.style.cssText = 'display:flex;flex-direction:column;gap:8px';

            const dmBtn = document.createElement('button');
            dmBtn.className = 'btn btn-primary btn-block';
            if (u.can_dm === false) {
                dmBtn.disabled = true;
                dmBtn.style.opacity = '0.5';
                dmBtn.textContent = t('dm_closed_by_user');
            } else {
                dmBtn.textContent = t('send_dm_btn');
                dmBtn.addEventListener('click', async () => {
                    close();
                    const r = await apiCall('chat_open_dm', { user_id: u.id });
                    if (r.ok) {
                        store.chats = r.data.chats;
                        await selectChat(r.data.chat_id);
                    } else {
                        toast(r.message || t('err_generic'), true);
                    }
                });
            }
            actions.appendChild(dmBtn);

            if (u.can_dm !== false && store.settings.e2ee_enabled) {
                const secBtn = document.createElement('button');
                secBtn.className = 'btn btn-secondary btn-block';
                secBtn.textContent = t('start_secret_btn');
                secBtn.addEventListener('click', async () => {
                    close();
                    const r = await apiCall('chat_open_secret', { user_id: u.id });
                    if (r.ok) {
                        store.chats = r.data.chats;
                        await selectChat(r.data.chat_id);
                    } else {
                        toast(r.message || t('err_generic'), true);
                    }
                });
                actions.appendChild(secBtn);
            }

            const isBlocked = store.blockedIds.includes(u.id);
            const blkBtn = document.createElement('button');
            blkBtn.className = 'btn btn-secondary btn-block';
            blkBtn.textContent = isBlocked ? t('unblock_user_btn') : t('block_user_btn');
            blkBtn.addEventListener('click', async () => {
                const ap = await askApproval({
                    title: isBlocked ? t('unblock_user_btn') : t('block_user_btn'),
                    desc: `${t('ask_block_user')} (${formatHandleLabel(u)})`,
                    danger: !isBlocked,
                    icon: isBlocked ? '✅' : '🚫'
                });
                if (!ap.approved) return;
                const r = await apiCall(isBlocked ? 'unblock_user' : 'block_user', { user_id: u.id });
                if (r.ok) {
                    store.blockedIds = r.data.blocked_ids || [];
                    toast((isBlocked ? t('user_unblocked_toast') : t('user_blocked_toast')) + ` (${formatHandleLabel(u)})`);
                    close();
                } else {
                    toast(r.message || t('err_generic'), true);
                }
            });
            actions.appendChild(blkBtn);

            const repBtn = document.createElement('button');
            repBtn.className = 'btn btn-danger btn-block';
            repBtn.textContent = t('report_user_btn');
            repBtn.addEventListener('click', () => {
                close();
                openReportModal('user', u.id, `${formatHandleLabel(u)} (${u.name})`);
            });
            actions.appendChild(repBtn);

            body.appendChild(actions);
        }
    });
}


/* ---------------- MY UPLOADED FILES MANAGER (ACCESSIBLE EVERYWHERE) ---------------- */
/* Lists every pinned message of a chat and lets the user jump straight to it. */
async function openPinnedMessagesModal(chat) {
    if (!chat) return;
    const res = await apiCall('pinned_messages_list', { chat_id: chat.id });
    const list = (res.ok && Array.isArray(res.data.messages)) ? res.data.messages : [];
    openModal(t('pinned_list_title'), async (body, close) => {
        if (!list.length) {
            const empty = document.createElement('div');
            empty.className = 'pinned-empty-state';
            empty.style.cssText = 'padding:20px 14px;text-align:center;color:var(--text-muted);font-size:13px';
            empty.textContent = t('pinned_list_empty');
            body.appendChild(empty);
            return;
        }
        const hint = document.createElement('div');
        hint.className = 'pinned-list-hint';
        hint.style.cssText = 'font-size:12px;color:var(--text-muted);margin-bottom:10px';
        hint.textContent = t('pinned_list_hint');
        body.appendChild(hint);

        list.forEach(m => {
            const row = document.createElement('button');
            row.type = 'button';
            row.className = 'pinned-msg-row';
            row.style.cssText = 'display:block;width:100%;text-align:start;padding:10px 12px;margin-bottom:8px;background:var(--bg-surface);border:1px solid var(--border);border-radius:10px;cursor:pointer';

            const who = document.createElement('div');
            who.className = 'pinned-msg-author';
            who.style.cssText = 'font-size:12px;font-weight:800;color:var(--primary);margin-bottom:4px';
            who.textContent = (m.name && String(m.name).trim()) ? String(m.name) : ('@' + (m.username || m.user_id));

            const txt = document.createElement('div');
            txt.className = 'pinned-msg-body';
            txt.style.cssText = 'font-size:13px;color:var(--text-main);white-space:pre-wrap;word-break:break-word;max-height:4.6em;overflow:hidden';
            const rawBody = String(m.body || '');
            txt.textContent = rawBody.length > 260 ? (rawBody.slice(0, 260) + '…') : (rawBody || '—');

            row.appendChild(who);
            row.appendChild(txt);
            row.addEventListener('click', async () => {
                close();
                await selectChat(chat.id, { aroundId: m.id });
                requestAnimationFrame(() => {
                    const el = document.querySelector('[data-msg-id="' + m.id + '"]');
                    if (el) {
                        el.scrollIntoView({ behavior: 'smooth', block: 'center' });
                        el.classList.add('msg-flash');
                        setTimeout(() => el.classList.remove('msg-flash'), 1800);
                    } else {
                        toast(t('pinned_jump_fail'), true);
                    }
                });
            });
            body.appendChild(row);
        });
    });
}

async function openMyUploadedFilesModal(filterChatId = 0) {
    if (!store.user) return;
    const scopedChatId = (typeof filterChatId === 'number' || typeof filterChatId === 'string') ? (parseInt(filterChatId, 10) || 0) : 0;
    const scopedChatObj = scopedChatId > 0 ? (store.chats || []).find(c => Number(c.id) === scopedChatId) : null;
    const modalHeading = scopedChatId > 0 ? t('my_files_chat_title') : t('my_files_title');

    openModal(modalHeading, async (body, close) => {
        body.innerHTML = '<div style="padding:24px;text-align:center;color:var(--text-muted);font-weight:700">⏳ ...</div>';
        const res = await apiCall('my_files_list', scopedChatId > 0 ? { chat_id: scopedChatId } : {});
        body.innerHTML = '';
        if (!res.ok) {
            toast(res.message || t('err_generic'), true);
            return;
        }

        let files = res.data.files || [];
        let usedBytes = Number(res.data.used_bytes || 0);
        const quotaMb = Number(res.data.quota_mb || 0);
        const quotaBytes = Number(res.data.quota_bytes || 0);
        const autoDelHours = Number(res.data.file_auto_delete_hours || 0);

        // 1. Storage Usage Meter Card
        const meterWrap = document.createElement('div');
        meterWrap.className = 'storage-meter-wrap';

        const meterTop = document.createElement('div');
        meterTop.className = 'storage-meter-top';
        const meterLbl = document.createElement('span');
        const meterVal = document.createElement('span');
        meterVal.style.color = 'var(--primary)';
        meterTop.appendChild(meterLbl);
        meterTop.appendChild(meterVal);
        meterWrap.appendChild(meterTop);

        const barOuter = document.createElement('div');
        barOuter.className = 'storage-meter-bar';
        const barFill = document.createElement('div');
        barFill.className = 'storage-meter-fill';
        barOuter.appendChild(barFill);
        meterWrap.appendChild(barOuter);

        if (autoDelHours > 0) {
            const autoNote = document.createElement('div');
            autoNote.style.cssText = 'font-size:11.5px;color:var(--text-muted);margin-top:8px';
            const unitStr = (autoDelHours >= 24 && autoDelHours % 24 === 0)
                ? `${autoDelHours / 24} ${t('unit_days')}`
                : `${autoDelHours} ${t('unit_hours')}`;
            autoNote.textContent = t('my_files_auto_del_note') + unitStr;
            meterWrap.appendChild(autoNote);
        }

        const updateMeterUI = () => {
            meterLbl.textContent = `${t('my_files_usage_lbl')} (${formatLocalizedCount(files.length)})`;
            if (quotaBytes > 0) {
                const remBytes = Math.max(0, quotaBytes - usedBytes);
                const pct = Math.min(100, Math.round((usedBytes / quotaBytes) * 100));
                meterVal.textContent = `${formatBytes(usedBytes)} / ${formatBytes(quotaBytes)} • ${t('user_storage_rem_label')}: ${formatBytes(remBytes)} (${formatLocalizedCount(pct)}%)`;
                barFill.style.width = `${pct}%`;
                barFill.classList.toggle('warn', pct >= 80);
                barOuter.classList.remove('hidden');
            } else {
                meterVal.textContent = `${formatBytes(usedBytes)} / ${t('storage_unlimited')}`;
                barFill.style.width = '12%';
            }
        };
        updateMeterUI();
        if (scopedChatId > 0) {
            const scopeRow = document.createElement('div');
            scopeRow.style.cssText = 'display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap;margin-top:8px;padding-top:8px;border-top:1px solid var(--border);font-size:12px';
            const scopeTxt = document.createElement('span');
            scopeTxt.style.color = 'var(--text-secondary)';
            scopeTxt.textContent = t('my_files_chat_scope_note') + (scopedChatObj ? formatChatTitle(scopedChatObj) : ('#' + scopedChatId));
            const viewAllBtn = document.createElement('button');
            viewAllBtn.type = 'button';
            viewAllBtn.className = 'btn btn-secondary btn-sm';
            viewAllBtn.textContent = t('my_files_view_all_btn');
            viewAllBtn.addEventListener('click', () => openMyUploadedFilesModal(0));
            scopeRow.appendChild(scopeTxt);
            scopeRow.appendChild(viewAllBtn);
            meterWrap.appendChild(scopeRow);
        }
        body.appendChild(meterWrap);

        // 2. Search, Type Filter & Delete All Toolbar
        const toolbar = document.createElement('div');
        toolbar.className = 'adm-toolbar';

        const searchIn = document.createElement('input');
        searchIn.className = 'input';
        searchIn.style.flex = '1';
        searchIn.style.minWidth = '180px';
        searchIn.placeholder = t('my_files_search_ph');
        toolbar.appendChild(searchIn);

        const delAllBtn = document.createElement('button');
        delAllBtn.type = 'button';
        delAllBtn.className = 'btn btn-danger btn-sm';
        delAllBtn.textContent = t('my_files_delete_all_btn');
        if (files.length === 0) delAllBtn.classList.add('hidden');
        delAllBtn.addEventListener('click', async () => {
            const ap = await askApproval({
                title: t('my_files_delete_all_btn'),
                desc: `${t('my_files_delete_all_confirm')} (${files.length})`,
                danger: true,
                icon: '🗑️'
            });
            if (!ap.approved) return;
            const r = await apiCall('my_file_delete', scopedChatId > 0 ? { delete_all: 1, chat_id: scopedChatId } : { delete_all: 1 });
            if (r.ok) {
                files = [];
                usedBytes = 0;
                delAllBtn.classList.add('hidden');
                updateMeterUI();
                drawFiles();
                if (store.activeChatId) await selectChat(store.activeChatId);
                toast(`${t('files_deleted_all_toast')} (${r.data.deleted_count || 0})`);
            } else {
                toast(r.message || t('err_generic'), true);
            }
        });
        toolbar.appendChild(delAllBtn);
        body.appendChild(toolbar);

        const filterRow = document.createElement('div');
        filterRow.style.cssText = 'display:flex;gap:6px;flex-wrap:wrap;margin-bottom:12px';
        let activeTypeFilter = 'all';

        const listContainer = document.createElement('div');

        const drawFiles = () => {
            listContainer.innerHTML = '';
            const q = searchIn.value.trim().toLowerCase();
            const filtered = files.filter(f => {
                const mime = (f.mime || '').toLowerCase();
                if (activeTypeFilter === 'img' && !mime.startsWith('image/')) return false;
                if (activeTypeFilter === 'media' && !mime.startsWith('audio/') && !mime.startsWith('video/')) return false;
                if (activeTypeFilter === 'doc' && (mime.startsWith('image/') || mime.startsWith('audio/') || mime.startsWith('video/'))) return false;
                if (!q) return true;
                return (f.display_name || '').toLowerCase().includes(q) || (f.chat_title || '').toLowerCase().includes(q);
            });

            if (filtered.length === 0) {
                const empty = document.createElement('div');
                empty.className = 'card-box';
                empty.style.cssText = 'text-align:center;color:var(--text-muted);padding:22px 14px;font-size:13px';
                empty.textContent = t('my_files_empty');
                listContainer.appendChild(empty);
                return;
            }

            filtered.forEach(f => {
                const card = document.createElement('div');
                card.className = 'my-file-card';

                const left = document.createElement('div');
                left.className = 'my-file-left';

                const iconBox = document.createElement('div');
                iconBox.className = 'my-file-icon';
                const mime = (f.mime || '').toLowerCase();
                if (!f.encrypted && mime.startsWith('image/')) {
                    const img = document.createElement('img');
                    img.src = f.url;
                    img.alt = f.display_name;
                    iconBox.appendChild(img);
                } else if (f.encrypted) {
                    iconBox.textContent = '🔒';
                } else if (mime.startsWith('audio/')) {
                    iconBox.textContent = '🎤';
                } else if (mime.startsWith('video/')) {
                    iconBox.textContent = '🎬';
                } else {
                    iconBox.textContent = '📄';
                }
                left.appendChild(iconBox);

                const info = document.createElement('div');
                info.className = 'my-file-info';
                const nameDiv = document.createElement('div');
                nameDiv.className = 'my-file-name';
                nameDiv.textContent = f.display_name;

                const subDiv = document.createElement('div');
                subDiv.className = 'my-file-sub';
                const szBadge = document.createElement('span');
                szBadge.className = 'adm-badge-pill primary';
                szBadge.textContent = formatBytes(f.size);

                const chatBadge = document.createElement('span');
                chatBadge.className = 'adm-badge-pill';
                chatBadge.textContent = `💬 ${f.chat_title}`;

                const dateSpan = document.createElement('span');
                dateSpan.textContent = formatDate(f.created_at);

                subDiv.appendChild(szBadge);
                subDiv.appendChild(chatBadge);
                subDiv.appendChild(dateSpan);

                info.appendChild(nameDiv);
                info.appendChild(subDiv);
                left.appendChild(info);
                card.appendChild(left);

                const actions = document.createElement('div');
                actions.style.cssText = 'display:flex;align-items:center;gap:6px;flex-wrap:wrap';

                const openChatBtn = document.createElement('button');
                openChatBtn.type = 'button';
                openChatBtn.className = 'btn btn-secondary btn-sm';
                openChatBtn.textContent = t('my_files_open_chat');
                openChatBtn.addEventListener('click', async () => {
                    const existsInList = store.chats.some(c => c.id === f.chat_id);
                    if (existsInList) {
                        close();
                        await selectChat(f.chat_id);
                    } else {
                        toast(t('err_not_found'), true);
                    }
                });
                actions.appendChild(openChatBtn);

                if (!f.encrypted) {
                    const fMime = (f.mime || '').toLowerCase();
                    const fName = (f.display_name || '').toLowerCase();
                    let pType = '';
                    if (fMime.startsWith('image/')) pType = 'image';
                    else if (fMime.startsWith('video/')) pType = 'video';
                    else if (fMime.startsWith('audio/')) pType = 'audio';
                    else if (fMime.startsWith('text/plain') || /\.(txt|log|md|csv|json)$/i.test(fName)) pType = 'text';

                    const isZeroSaveFile = Boolean(f.zero_save);
                    const dlUrl = isZeroSaveFile ? '' : getFileDownloadUrl(f);
                    if (pType) {
                        const playBtn = document.createElement('button');
                        playBtn.type = 'button';
                        playBtn.className = 'btn btn-secondary btn-sm';
                        playBtn.textContent = t('open_in_player_btn');
                        playBtn.addEventListener('click', () => {
                            UniversalPlayer.open({
                                type: pType,
                                url: f.url,
                                sourceFileId: f.id,
                                zeroSave: isZeroSaveFile,
                                allowDownload: !isZeroSaveFile,
                                downloadUrl: dlUrl,
                                title: f.display_name,
                                mode: 'float'
                            });
                        });
                        actions.appendChild(playBtn);
                    }

                    if (!isZeroSaveFile) {
                        const dlLink = document.createElement('a');
                        dlLink.href = dlUrl;
                        dlLink.setAttribute('download', f.display_name || 'file');
                        dlLink.rel = 'noopener';
                        dlLink.className = 'btn btn-secondary btn-sm';
                        dlLink.style.textDecoration = 'none';
                        dlLink.textContent = t('my_files_download');
                        actions.appendChild(dlLink);
                    }
                }

                const delBtn = document.createElement('button');
                delBtn.type = 'button';
                delBtn.className = 'btn btn-danger btn-sm';
                delBtn.textContent = '🗑️ ' + t('adm_delete_btn');
                delBtn.addEventListener('click', async () => {
                    const ap = await askApproval({
                        title: '🗑️ ' + t('adm_delete_btn'),
                        desc: `${t('ask_del_one_file')}
📄 ${f.display_name}`,
                        danger: true,
                        icon: '🗑️'
                    });
                    if (!ap.approved) return;
                    delBtn.disabled = true;
                    const r = await apiCall('my_file_delete', { file_id: f.id });
                    if (r.ok) {
                        files = files.filter(x => x.id !== f.id);
                        usedBytes = Number(r.data.used_bytes || 0);
                        if (files.length === 0) delAllBtn.classList.add('hidden');
                        updateMeterUI();
                        drawFiles();
                        if (store.activeChatId === f.chat_id) {
                            await selectChat(f.chat_id);
                        }
                        toast(t('file_deleted_one_toast') + f.display_name);
                    } else {
                        delBtn.disabled = false;
                        toast(r.message || t('err_generic'), true);
                    }
                });
                actions.appendChild(delBtn);

                card.appendChild(actions);
                listContainer.appendChild(card);
            });
        };

        [
            ['all', t('my_files_filter_all')],
            ['img', t('my_files_filter_img')],
            ['media', t('my_files_filter_media')],
            ['doc', t('my_files_filter_doc')]
        ].forEach(([fid, flbl]) => {
            const p = document.createElement('button');
            p.type = 'button';
            p.className = 'filter-pill' + (activeTypeFilter === fid ? ' active' : '');
            p.textContent = flbl;
            p.addEventListener('click', () => {
                activeTypeFilter = fid;
                Array.from(filterRow.children).forEach(c => c.classList.remove('active'));
                p.classList.add('active');
                drawFiles();
            });
            filterRow.appendChild(p);
        });

        body.appendChild(filterRow);
        body.appendChild(listContainer);
        searchIn.addEventListener('input', drawFiles);
        drawFiles();
    }, true);
}


/* ---------------- GRANULAR GROUP/CHANNEL ADMIN ROLE & ACCESS PRIVILEGES MODAL ---------------- */
function openAdminPrivilegesModal(chat, target) {
    const targetLabel = target.name ? `${target.name} (${formatHandleLabel(target)})` : formatHandleLabel(target);
    const currentRole = target.chat_role === 'admin' ? 'admin' : (target.defaultRole || 'admin');
    const isActorSuperOrOwner = Boolean((store.user && store.user.role === 'superadmin') || chat.my_role === 'owner' || (store.user && chat.owner_id === store.user.id));
    const actorPerms = chat.my_perms || {};
    const existingPerms = Object.assign({
        post_messages: 1,
        edit_info: 1,
        delete_messages: 1,
        ban_users: 1,
        pin_messages: 1,
        invite_users: 1,
        manage_content: 1,
        manage_calls: 1,
        manage_admins: 0,
        control_other_admins: 0
    }, target.perms || {});

    openModal(t('admin_priv_modal_title'), (body, close) => {
        const userBanner = document.createElement('div');
        userBanner.className = 'card-box';
        userBanner.style.cssText = 'display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap';
        const uInfo = document.createElement('div');
        uInfo.style.fontWeight = '800';
        uInfo.textContent = `👤 ${targetLabel}`;
        const chatTag = document.createElement('span');
        chatTag.className = 'adm-badge-pill primary';
        chatTag.textContent = formatChatTitle(chat);
        userBanner.appendChild(uInfo);
        userBanner.appendChild(chatTag);
        body.appendChild(userBanner);

        if (target.is_superadmin) {
            const symNote = document.createElement('div');
            symNote.className = 'card-box';
            symNote.style.cssText = 'font-size:12.5px;color:var(--primary);border-color:var(--primary);background:var(--primary-soft)';
            symNote.textContent = t('symbolic_superadmin_note');
            body.appendChild(symNote);
        }

        const fgRole = document.createElement('div');
        fgRole.className = 'form-group';
        const lblRole = document.createElement('label');
        lblRole.textContent = t('role_select_label');
        const selRole = document.createElement('select');
        selRole.className = 'input';
        [['admin', t('role_admin_opt')], ['member', t('role_member_opt')]].forEach(([v, l]) => {
            const o = document.createElement('option');
            o.value = v;
            o.textContent = l;
            if (currentRole === v) o.selected = true;
            selRole.appendChild(o);
        });
        fgRole.appendChild(lblRole);
        fgRole.appendChild(selRole);
        body.appendChild(fgRole);

        const privSection = document.createElement('div');
        privSection.className = 'card-box';
        const privHeader = document.createElement('div');
        privHeader.className = 'section-header';
        privHeader.textContent = t('priv_list_header');
        privSection.appendChild(privHeader);

        const permGrid = document.createElement('div');
        permGrid.className = 'adm-perm-grid';

        const permDefs = [
            ['post_messages', t('perm_post_messages')],
            ['edit_info', t('adm_perm_edit_info')],
            ['delete_messages', t('adm_perm_delete_msgs')],
            ['pin_messages', t('adm_perm_pin_msgs')],
            ['ban_users', t('adm_perm_ban_users')],
            ['invite_users', t('adm_perm_manage_invites')],
            ['manage_content', t('adm_perm_manage_content')],
            ['manage_calls', t('adm_perm_manage_calls')],
            ['manage_admins', t('adm_perm_manage_admins')],
            ['control_other_admins', t('adm_perm_control_other_admins')]
        ];

        const permInputs = {};
        permDefs.forEach(([key, labelText]) => {
            const actorHasPerm = isActorSuperOrOwner || Boolean(actorPerms[key]);
            const row = document.createElement('label');
            row.className = 'adm-perm-card';
            if (!actorHasPerm) row.style.opacity = '0.6';
            const span = document.createElement('span');
            span.style.cssText = 'font-size:13px;font-weight:600;color:var(--text-main)';
            span.textContent = labelText;
            const chk = document.createElement('input');
            chk.type = 'checkbox';
            chk.checked = actorHasPerm ? !!existingPerms[key] : false;
            if (!actorHasPerm) chk.disabled = true;
            permInputs[key] = chk;
            row.appendChild(span);
            row.appendChild(chk);
            permGrid.appendChild(row);
        });

        privSection.appendChild(permGrid);
        body.appendChild(privSection);

        const syncVisibility = () => {
            privSection.classList.toggle('hidden', selRole.value !== 'admin');
        };
        selRole.addEventListener('change', syncVisibility);
        syncVisibility();

        const saveBtn = document.createElement('button');
        saveBtn.type = 'button';
        saveBtn.className = 'btn btn-primary btn-block';
        saveBtn.textContent = t('save_admin_priv_btn');
        saveBtn.addEventListener('click', async () => {
            const ap = await askApproval({
                title: t('admin_priv_modal_title'),
                desc: `${t('ask_save_admin_priv')}
👤 ${targetLabel}`,
                danger: false,
                icon: '🛡️'
            });
            if (!ap.approved) return;
            const permsPayload = {};
            Object.keys(permInputs).forEach(k => {
                permsPayload[k] = permInputs[k].checked ? 1 : 0;
            });
            saveBtn.disabled = true;
            const r = await apiCall('member_role', {
                chat_id: chat.id,
                user_id: target.id || target.user_id || 0,
                username: target.username || '',
                role: selRole.value,
                perms: permsPayload
            });
            saveBtn.disabled = false;
            if (r.ok) {
                if (r.data && r.data.chats) {
                    store.chats = r.data.chats;
                    renderChatList();
                    renderActiveChatHeader();
                }
                toast(`${t('admin_priv_saved_toast')} (${targetLabel})`);
                close();
                openChatInfoModal('members');
            } else {
                toast(r.message || t('err_generic'), true);
            }
        });
        body.appendChild(saveBtn);
    });
}

/* ---------------- CHAT INFO, GROUP/CHANNEL SETTINGS, INVITE LINKS & MEMBER LIST ---------------- */
async function openChatInfoModal(initialTab = 'overview') {
    const chat = getActiveChat();
    if (!chat) return;
    const activeSecInit = (typeof initialTab === 'string' && ['overview', 'settings', 'members'].includes(initialTab)) ? initialTab : 'overview';

    const res = await apiCall('chat_members', { chat_id: chat.id });
    const members = res.ok ? (res.data.members || []) : [];
    // The server sends where we stand in the chat ladder (3 super-admin, 2 owner,
    // 1 admin, 0 member) so the member list can hide actions it would refuse.
    const myRank = res.ok ? (parseInt(res.data.my_rank, 10) || 0) : 0;
    const invites = res.ok ? (res.data.invites || []) : [];
    const membersHidden = res.ok && !!res.data.members_hidden;

    const isSuper = store.user && store.user.role === 'superadmin';
    const isOwner = chat.my_role === 'owner' || (store.user && chat.owner_id === store.user.id);
    const isAdmin = isSuper || isOwner || chat.my_role === 'admin';
    const myPerms = chat.my_perms || {};
    const chatPermsTop = chat.perms || {};
    const memberInviteFlag = Number(chat.member_invite !== undefined ? chat.member_invite : (chatPermsTop.member_invite || 0)) === 1;
    const canEditInfo = isSuper || isOwner || (chat.my_role === 'admin' && myPerms.edit_info !== 0);
    const canRevokeInvites = isSuper || isOwner || (chat.my_role === 'admin' && (myPerms.invite_users !== 0 && myPerms.manage_invites !== 0));
    const canInvite = canRevokeInvites || ((chat.type === 'group' || chat.type === 'channel') && !chat.is_ghost && chat.my_role === 'member' && memberInviteFlag);
    const canBanUsers = isSuper || isOwner || (chat.my_role === 'admin' && myPerms.ban_users !== 0);
    const canManageContent = isSuper || isOwner || (chat.my_role === 'admin' && myPerms.manage_content !== 0);
    const canManageCalls = isSuper || isOwner || (chat.my_role === 'admin' && myPerms.manage_calls !== 0);
    const canManageAdmins = isSuper || isOwner || (chat.my_role === 'admin' && !!myPerms.manage_admins);
    const canControlOtherAdmins = isSuper || isOwner || (chat.my_role === 'admin' && !!myPerms.control_other_admins);

    let pendingRequests = [];
    if ((chat.type === 'group' || chat.type === 'channel') && canRevokeInvites) {
        const jrRes = await apiCall('join_requests_list', { chat_id: chat.id });
        if (jrRes.ok && Array.isArray(jrRes.data.requests)) {
            pendingRequests = jrRes.data.requests;
        }
    }

    const displayTitle = formatChatTitle(chat);
    const isGroupOrChannel = (chat.type === 'group' || chat.type === 'channel');
    const isSaved = (chat.type === 'saved');
    const isSystemChat = (chat.type === 'system');

    openModal(t('chat_info_title'), async (body, close) => {
        const hero = document.createElement('div');
        hero.className = 'chat-info-hero';

        const avWrap = document.createElement('div');
        avWrap.className = 'chat-avatar-edit-wrap';
        const avEl = document.createElement('div');
        avEl.className = 'avatar avatar-lg';
        renderAvatarNode(avEl, displayTitle, chat.avatar, isSaved, isSystemChat);
        avWrap.appendChild(avEl);

        let currentSection = activeSecInit;

        const runRoleScopedChatReset = async () => {
            if (isSystemChat || chat.is_ghost) return;
            const isTwoWay = (chat.type === 'dm' || chat.type === 'secret');
            let descTxt = t('chat_reset_desc_personal');
            let optSharedChk = undefined;
            let optSharedDefault = true;

            if (isSaved) {
                descTxt = t('chat_reset_desc_dm');
            } else if (isTwoWay) {
                descTxt = t('chat_reset_desc_dm');
                optSharedChk = t('chat_reset_shared_timers_chk');
                optSharedDefault = true;
            } else if (isGroupOrChannel && (canEditInfo || canManageContent || canManageCalls || isSuper)) {
                const scopeParts = [];
                if (canEditInfo) scopeParts.push(t('chat_scope_edit_info'));
                if (canManageContent) scopeParts.push(t('chat_scope_manage_content'));
                if (canManageCalls) scopeParts.push(t('chat_scope_manage_calls'));
                if (isSuper) scopeParts.push(t('chat_scope_superadmin'));
                descTxt = t('chat_reset_desc_admin_tpl').replace('{scopes}', scopeParts.join('، '));
            }

            const ap = await askApproval({
                title: t('chat_reset_settings_title'),
                desc: descTxt + '\n💬 ' + displayTitle,
                checkboxLabel: optSharedChk || t('chat_reset_confirm_chk'),
                checkboxDefault: optSharedChk ? optSharedDefault : false,
                checkboxRequired: !optSharedChk,
                danger: false,
                icon: '🔄'
            });
            if (!ap.approved) return;

            const resetSharedVal = optSharedChk ? (ap.checked ? 1 : 0) : 1;
            const r = await apiCall('chat_settings_reset', {
                chat_id: chat.id,
                confirmed: 1,
                reset_shared: resetSharedVal
            });
            if (r.ok) {
                if (r.data && Array.isArray(r.data.chats)) {
                    store.chats = r.data.chats;
                }
                if (store.chatDrafts) delete store.chatDrafts[chat.id];
                if (store.draftMetaByChat) delete store.draftMetaByChat[chat.id];
                if (Number(store.activeChatId) === Number(chat.id) && !store.editMsg) {
                    restoreChatComposerDraft(chat.id);
                }
                syncTtlControlUI();
                renderChatList();
                renderActiveChatHeader();
                toast(t('chat_reset_done_toast'));
                openChatInfoModal(currentSection);
            } else {
                toast(r.message || t('err_generic'), true);
            }
        };

        if (isGroupOrChannel && canEditInfo) {
            const hiddenGroupAvInput = document.createElement('input');
            hiddenGroupAvInput.type = 'file';
            hiddenGroupAvInput.accept = 'image/*';
            hiddenGroupAvInput.className = 'hidden';
            const camBtn = document.createElement('button');
            camBtn.type = 'button';
            camBtn.className = 'chat-avatar-cam-btn';
            camBtn.title = stripLeadingEmoji(t('group_avatar_btn'));
            camBtn.appendChild(makeHdrSvgNode(HDR_SVG.camera));
            camBtn.addEventListener('click', () => hiddenGroupAvInput.click());
            hiddenGroupAvInput.addEventListener('change', async () => {
                if (!hiddenGroupAvInput.files || !hiddenGroupAvInput.files[0]) return;
                try {
                    const dataUri = await resizeImageFileToAvatarDataUri(hiddenGroupAvInput.files[0]);
                    const r = await apiCall('chat_update', { chat_id: chat.id, avatar: dataUri });
                    if (r.ok) {
                        const lRes = await apiCall('chats_list');
                        if (lRes.ok) store.chats = lRes.data.chats;
                        chat.avatar = dataUri;
                        renderAvatarNode(avEl, displayTitle, dataUri, false);
                        renderChatList();
                        renderActiveChatHeader();
                        toast(t('group_avatar_saved_toast'));
                        openChatInfoModal(currentSection);
                    } else {
                        toast(r.message || t('err_generic'), true);
                    }
                } catch (err) {
                    toast(t('err_generic'), true);
                }
            });
            avWrap.appendChild(camBtn);
            avWrap.appendChild(hiddenGroupAvInput);
        }
        hero.appendChild(avWrap);

        if (isGroupOrChannel && canEditInfo && chat.avatar) {
            const rmAvBtn = document.createElement('button');
            rmAvBtn.type = 'button';
            rmAvBtn.className = 'btn btn-secondary btn-sm';
            rmAvBtn.style.cssText = 'font-size:11px;padding:3px 9px;margin-bottom:6px;display:inline-flex;align-items:center;gap:5px';
            rmAvBtn.appendChild(makeHdrSvgNode(HDR_SVG.trash));
            rmAvBtn.appendChild(document.createTextNode(stripLeadingEmoji(t('group_avatar_remove_btn'))));
            rmAvBtn.addEventListener('click', async () => {
                const r = await apiCall('chat_update', { chat_id: chat.id, avatar: '' });
                if (r.ok) {
                    const lRes = await apiCall('chats_list');
                    if (lRes.ok) store.chats = lRes.data.chats;
                    chat.avatar = '';
                    renderChatList();
                    renderActiveChatHeader();
                    toast(t('group_avatar_saved_toast'));
                    openChatInfoModal(currentSection);
                }
            });
            hero.appendChild(rmAvBtn);
        }

        const hTitle = document.createElement('div');
        hTitle.className = 'chat-info-title';
        hTitle.style.cssText = 'display:inline-flex;align-items:center;justify-content:center;gap:6px';
        if (isSaved) hTitle.appendChild(makeHdrSvgNode(HDR_SVG.bookmark));
        else if (chat.type === 'secret') hTitle.appendChild(makeHdrSvgNode(HDR_SVG.lock));
        hTitle.appendChild(document.createTextNode(displayTitle));
        hero.appendChild(hTitle);

        const hSub = document.createElement('div');
        hSub.className = 'chat-info-sub';
        if (chat.type === 'dm' || chat.type === 'secret') {
            if (chat.peer) {
                const pHandle = document.createElement('bdi');
                pHandle.setAttribute('dir', 'ltr');
                pHandle.textContent = formatHandleLabel(chat.peer);
                hSub.appendChild(pHandle);
                const stPill = document.createElement('span');
                stPill.className = 'adm-badge-pill ' + (chat.peer.online ? 'success' : '');
                if (chat.peer.online) {
                    stPill.style.cssText = 'display:inline-flex;align-items:center;gap:5px';
                    const od = document.createElement('span');
                    od.className = 'hdr-online-dot';
                    stPill.appendChild(od);
                    stPill.appendChild(document.createTextNode(t('online')));
                } else {
                    stPill.textContent = (chat.type === 'secret' ? 'E2EE' : 'DM');
                }
                hSub.appendChild(stPill);
            }
        } else if (isGroupOrChannel) {
            const typeBadge = document.createElement('span');
            typeBadge.className = 'adm-badge-pill primary';
            typeBadge.textContent = stripLeadingEmoji(chat.type === 'channel' ? t('nc_type_channel') : t('nc_type_group'));
            hSub.appendChild(typeBadge);

            const visBadge = document.createElement('span');
            visBadge.className = 'adm-badge-pill';
            visBadge.textContent = stripLeadingEmoji(chat.visibility === 'public' ? t('nc_vis_public') : t('nc_vis_private'));
            hSub.appendChild(visBadge);

            if (chat.handle) {
                const hBdi = document.createElement('bdi');
                hBdi.setAttribute('dir', 'ltr');
                hBdi.style.fontWeight = '700';
                hBdi.style.color = 'var(--primary)';
                hBdi.textContent = '@' + chat.handle;
                hSub.appendChild(hBdi);
            }
            if (chat.is_ghost) {
                const ghSpan = document.createElement('span');
                ghSpan.className = 'ghost-pill-badge';
                ghSpan.style.cssText = 'display:inline-flex;align-items:center;gap:4px';
                ghSpan.appendChild(makeHdrSvgNode(HDR_SVG.ghost));
                ghSpan.appendChild(document.createTextNode(stripLeadingEmoji(t('ghost_badge_short'))));
                hSub.appendChild(ghSpan);
            }
            const cntSpan = document.createElement('span');
            cntSpan.textContent = `• ${formatMemberCount(chat.member_count || members.length || 0)} ${t('members')}`;
            hSub.appendChild(cntSpan);
        } else if (isSaved) {
            hSub.textContent = t('saved_messages_sub');
        } else if (isSystemChat) {
            hSub.textContent = t('system_chat_subtitle');
        }
        hero.appendChild(hSub);

        const descTxt = (chat.type === 'dm' || chat.type === 'secret')
            ? (chat.peer && chat.peer.bio ? formatUserBio(chat.peer.bio) : '')
            : formatChatDescription(chat);
        if (descTxt) {
            const dEl = document.createElement('p');
            dEl.style.cssText = 'font-size:13px;color:var(--text-secondary);margin:8px 0 0;max-width:460px;line-height:1.55';
            dEl.textContent = descTxt;
            hero.appendChild(dEl);
        }
        body.appendChild(hero);

        const quickGrid = document.createElement('div');
        quickGrid.className = 'info-quick-grid';
        const makeQuickTile = (svgIcon, label, onClick, danger = false) => {
            const b = document.createElement('button');
            b.type = 'button';
            b.className = 'info-quick-tile' + (danger ? ' danger' : '');
            const cleanLbl = stripLeadingEmoji(label);
            b.innerHTML = `<span class="iqt-ico">${svgIcon}</span><span>${esc(cleanLbl)}</span>`;
            b.addEventListener('click', onClick);
            return b;
        };

        if (chat.is_ghost) {
            quickGrid.appendChild(makeQuickTile(HDR_SVG.plus, t('ghost_join_normal_btn'), async () => {
                close();
                await joinGhostChatNormally(chat.id);
            }));
            quickGrid.appendChild(makeQuickTile(HDR_SVG.folder, t('info_quick_files'), () => {
                close();
                openMyUploadedFilesModal(chat.id);
            }));
            quickGrid.appendChild(makeQuickTile(HDR_SVG.close, t('ghost_exit_btn'), () => {
                close();
                exitGhostChatView();
            }));
        } else {
            if (!isSaved) {
                quickGrid.appendChild(makeQuickTile(
                    chat.muted === 1 ? HDR_SVG.bell : HDR_SVG.bellOff,
                    chat.muted === 1 ? t('info_quick_unmute') : t('info_quick_mute'),
                    async () => {
                        await toggleChatNotifMute(chat);
                        openChatInfoModal(currentSection);
                    }
                ));
            }

            if (!isSaved && !isSystemChat) {
                quickGrid.appendChild(makeQuickTile(HDR_SVG.pin, t('info_quick_pinned'), () => {
                    close();
                    openPinnedMessagesModal(chat);
                }));
            }

            if (!isSystemChat) {
                quickGrid.appendChild(makeQuickTile(HDR_SVG.folder, t('info_quick_files'), () => {
                    close();
                    openMyUploadedFilesModal(chat.id);
                }));
            }

            if (!isSaved) {
                quickGrid.appendChild(makeQuickTile(
                    chat.is_pinned === 1 ? HDR_SVG.pinOff : HDR_SVG.pin,
                    chat.is_pinned === 1 ? t('unpin') : t('pin'),
                    async () => {
                        await toggleChatPin(chat);
                        openChatInfoModal(currentSection);
                    }
                ));
            }
        }

        if ((chat.type === 'dm' || chat.type === 'secret') && chat.peer) {
            quickGrid.appendChild(makeQuickTile(HDR_SVG.user, t('view_peer_profile'), () => {
                close();
                openUserMiniProfile(chat.peer.id);
            }));
            const peerBlocked = Boolean(
                (Array.isArray(store.blockedIds) && store.blockedIds.includes(chat.peer.id))
                || chat.peer_is_blocked
                || (chat.peer && chat.peer.is_blocked)
            );
            quickGrid.appendChild(makeQuickTile(
                HDR_SVG.ban || HDR_SVG.shield || '🚫',
                peerBlocked ? t('dm_unblock_peer_btn') : t('dm_block_peer_btn'),
                async () => {
                    const ap = await askApproval({
                        title: peerBlocked ? t('dm_unblock_peer_btn') : t('dm_block_peer_btn'),
                        desc: `👤 ${chat.peer.name || chat.peer.username || ''}`,
                        danger: !peerBlocked,
                        icon: peerBlocked ? '✅' : '🚫'
                    });
                    if (!ap.approved) return;
                    const br = await apiCall(peerBlocked ? 'unblock_user' : 'block_user', { user_id: chat.peer.id });
                    if (br.ok) {
                        if (Array.isArray(br.data && br.data.blocked_ids)) {
                            store.blockedIds = br.data.blocked_ids;
                        }
                        const nowBlocked = Array.isArray(store.blockedIds) ? store.blockedIds.includes(chat.peer.id) : !peerBlocked;
                        chat.peer_is_blocked = nowBlocked;
                        if (chat.peer) chat.peer.is_blocked = nowBlocked;
                        toast((nowBlocked ? t('user_blocked_toast') : t('user_unblocked_toast')) + ` (${formatHandleLabel(chat.peer)})`);
                        openChatInfoModal(currentSection);
                    } else {
                        toast(br.message || t('err_generic'), true);
                    }
                },
                !peerBlocked
            ));
        }

        if (chat.type === 'dm' || chat.type === 'secret' || isSaved) {
            quickGrid.appendChild(makeQuickTile(
                HDR_SVG.trash,
                isSaved ? t('clear_saved_btn') : t('info_quick_delete'),
                async () => {
                    close();
                    await leaveOrDeleteChatAction(chat, 'delete');
                },
                true
            ));
            if (chat.type === 'dm') {
                quickGrid.appendChild(makeQuickTile(
                    HDR_SVG.leave,
                    t('del_dm_for_me_btn'),
                    async () => {
                        close();
                        await deleteDmForMeAction(chat, displayTitle);
                    },
                    true
                ));
            }
        } else if (isGroupOrChannel) {
            if (isSuper && !chat.is_ghost) {
                quickGrid.appendChild(makeQuickTile(HDR_SVG.ghost, t('ghost_switch_btn'), async () => {
                    close();
                    await switchChatToGhostMode(chat.id, displayTitle);
                }));
            }
            const canLeave = !chat.is_ghost && !(chat.is_default === 1 && chat.type === 'channel' && !isSuper);
            if (canLeave) {
                quickGrid.appendChild(makeQuickTile(HDR_SVG.leave, t('info_quick_leave'), async () => {
                    const ap = await askApproval({
                        title: t('leave_chat_btn'),
                        desc: `${t('ask_leave_chat')}\n💬 ${displayTitle}`,
                        danger: true,
                        icon: '👋'
                    });
                    if (!ap.approved) return;
                    const r = await apiCall('chat_leave', { chat_id: chat.id });
                    if (r.ok) {
                        store.chats = r.data.chats;
                        close();
                        showNoChatSelected();
                        toast(`${t('left_chat_toast')} (${displayTitle})`);
                    } else {
                        toast(r.message || t('cannot_leave_default_channel'), true);
                    }
                }, true));
            }
            if ((isOwner || isSuper) && chat.is_default !== 1) {
                quickGrid.appendChild(makeQuickTile(HDR_SVG.trash, t('info_quick_delete'), async () => {
                    close();
                    await leaveOrDeleteChatAction(chat, 'delete');
                }, true));
            }
        }
        body.appendChild(quickGrid);

        const secContainer = document.createElement('div');

        if (isGroupOrChannel) {
            const navTabs = document.createElement('div');
            navTabs.className = 'info-section-tabs';
            const availableTabs = [['overview', HDR_SVG.clipboard, stripLeadingEmoji(t('info_tab_overview'))]];
            if (canEditInfo || canManageContent || canManageCalls || canInvite) {
                availableTabs.push(['settings', HDR_SVG.sliders, stripLeadingEmoji(t('info_tab_settings'))]);
            }
            if (!(isGroupOrChannel && (!isAdmin && membersHidden))) {
                const memCntStr = formatLocalizedCount(members.length);
                const badgeSuffix = pendingRequests.length > 0
                    ? ` (${memCntStr} • +${formatLocalizedCount(pendingRequests.length)})`
                    : ` (${memCntStr})`;
                availableTabs.push(['members', HDR_SVG.users, stripLeadingEmoji(t('info_tab_members')) + badgeSuffix]);
            }
            if (!availableTabs.some(x => x[0] === currentSection)) {
                currentSection = 'overview';
            }
            availableTabs.forEach(([key, svgIcon, lbl]) => {
                const tb = document.createElement('button');
                tb.type = 'button';
                tb.className = 'info-sec-tab' + (currentSection === key ? ' active' : '');
                tb.innerHTML = svgIcon;
                tb.appendChild(document.createTextNode(lbl));
                tb.addEventListener('click', () => {
                    currentSection = key;
                    navTabs.querySelectorAll('.info-sec-tab').forEach(el => el.classList.remove('active'));
                    tb.classList.add('active');
                    renderSectionContent();
                });
                navTabs.appendChild(tb);
            });
            body.appendChild(navTabs);
        }

        body.appendChild(secContainer);

        const renderSectionContent = async () => {
            secContainer.innerHTML = '';

            if (currentSection === 'overview') {
                const kv = document.createElement('div');
                kv.className = 'ui-kv-list';
                const addKv = (label, valNodeOrStr) => {
                    const r = document.createElement('div');
                    r.className = 'ui-kv-row';
                    const l = document.createElement('span');
                    l.className = 'ui-kv-label';
                    l.textContent = label;
                    const v = document.createElement('span');
                    v.className = 'ui-kv-val';
                    if (valNodeOrStr instanceof Node) v.appendChild(valNodeOrStr);
                    else v.textContent = String(valNodeOrStr);
                    r.appendChild(l);
                    r.appendChild(v);
                    kv.appendChild(r);
                };

                if ((chat.type === 'dm' || chat.type === 'secret') && chat.peer) {
                    addKv(t('display_name'), chat.peer.name);
                    const bdiU = document.createElement('bdi');
                    bdiU.setAttribute('dir', 'ltr');
                    bdiU.textContent = formatHandleLabel(chat.peer);
                    addKv(t('username'), bdiU);
                }
                if (isGroupOrChannel) {
                    addKv(t('nc_type_label'), chat.type === 'channel' ? t('nc_type_channel') : t('nc_type_group'));
                    addKv(t('nc_vis_label'), chat.visibility === 'public' ? t('nc_vis_public') : t('nc_vis_private'));
                    if (chat.handle) {
                        const bdiH = document.createElement('bdi');
                        bdiH.setAttribute('dir', 'ltr');
                        bdiH.textContent = '@' + chat.handle;
                        addKv(t('nc_handle_label'), bdiH);
                    }
                    addKv(t('auto_ttl_label'), chat.default_ttl > 0 ? `${chat.default_ttl}s` : '—');
                    if (chat.type === 'group') {
                        addKv(t('slow_mode_label'), chat.slow_mode > 0 ? `${chat.slow_mode}s` : '—');
                    }
                    const curIdle = getChatIdleStatus(chat);
                    addKv(t('idle_chat_sec_title'), curIdle.active
                        ? (curIdle.mode === 'auto' ? `${t('idle_status_active_auto')} (${curIdle.start}–${curIdle.end})` : t('idle_status_active_manual'))
                        : t('idle_status_normal'));
                }
                if (kv.children.length > 0) {
                    secContainer.appendChild(kv);
                }

                if (chat.type === 'secret') {
                    const fpBox = document.createElement('div');
                    fpBox.className = 'card-box';
                    const fpTitle = document.createElement('div');
                    fpTitle.className = 'card-title';
                    fpTitle.textContent = t('secret_info_title');
                    const fpDesc = document.createElement('div');
                    fpDesc.style.cssText = 'font-size:12.5px;color:var(--text-secondary);line-height:1.55';
                    fpDesc.textContent = t('secret_info_desc');
                    const fpLabel = document.createElement('div');
                    fpLabel.style.cssText = 'margin-top:10px;font-size:12px;font-weight:700;color:var(--text-muted)';
                    fpLabel.textContent = t('safety_numbers_label');
                    const fpStr = await E2EE.safetyFingerprint(chat);
                    const fpVal = document.createElement('div');
                    fpVal.style.cssText = 'font-family:monospace;font-size:12.5px;margin-top:5px;padding:8px 10px;border-radius:8px;background:var(--bg-surface);border:1px solid var(--border);color:var(--primary);word-break:break-all';
                    fpVal.textContent = fpStr;
                    const fpCopyBtn = document.createElement('button');
                    fpCopyBtn.type = 'button';
                    fpCopyBtn.className = 'btn btn-secondary btn-sm';
                    fpCopyBtn.style.marginTop = '8px';
                    fpCopyBtn.textContent = t('copy_safety_fp_btn');
                    fpCopyBtn.addEventListener('click', async () => {
                        await copyTextToClipboard(fpVal.textContent || fpStr);
                        toast(t('safety_fp_copied_toast'));
                    });
                    fpBox.dataset.dmCat = 'overview privacy';
                    const e2eeHealthPill = document.createElement('div');
                    e2eeHealthPill.style.cssText = 'margin-top:8px;padding:6px 10px;border-radius:8px;background:var(--bg-subtle);border:1px solid var(--border);font-size:12px;font-weight:700;color:var(--primary)';
                    const derivedReady = await E2EE.deriveChatKey(chat);
                    e2eeHealthPill.textContent = derivedReady ? t('e2ee_keys_healthy_badge') : ('⏳ ' + t('e2ee_waiting_exchange'));

                    const fpActionsRow = document.createElement('div');
                    fpActionsRow.className = 'resp-action-row';
                    fpActionsRow.style.marginTop = '8px';
                    fpCopyBtn.style.marginTop = '0';
                    const resyncKeysBtn = document.createElement('button');
                    resyncKeysBtn.type = 'button';
                    resyncKeysBtn.id = 'btn-secret-resync-keys';
                    resyncKeysBtn.className = 'btn btn-primary btn-sm';
                    resyncKeysBtn.textContent = t('e2ee_resync_keys_btn');
                    resyncKeysBtn.addEventListener('click', async () => {
                        resyncKeysBtn.disabled = true;
                        await E2EE.reSyncKeysForChat(chat.id);
                        const freshChat = getActiveChat() || chat;
                        const nextKey = await E2EE.deriveChatKey(freshChat);
                        fpVal.textContent = await E2EE.safetyFingerprint(freshChat);
                        e2eeHealthPill.textContent = nextKey ? t('e2ee_keys_healthy_badge') : ('⏳ ' + t('e2ee_waiting_exchange'));
                        resyncKeysBtn.disabled = false;
                        toast(t('e2ee_resync_done_toast'));
                    });
                    fpActionsRow.appendChild(fpCopyBtn);
                    fpActionsRow.appendChild(resyncKeysBtn);

                    fpBox.appendChild(fpTitle);
                    fpBox.appendChild(fpDesc);
                    fpBox.appendChild(e2eeHealthPill);
                    fpBox.appendChild(fpLabel);
                    fpBox.appendChild(fpVal);
                    fpBox.appendChild(fpActionsRow);
                    secContainer.appendChild(fpBox);
                }

                if (isGroupOrChannel && canInvite) {
                    const invCard = document.createElement('div');
                    invCard.className = 'card-box';
                    const invHead = document.createElement('div');
                    invHead.style.cssText = 'display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap;margin-bottom:8px';
                    const invLbl = document.createElement('span');
                    invLbl.style.fontWeight = '800';
                    invLbl.textContent = '🔗 ' + t('info_quick_share');
                    const newInvBtn = document.createElement('button');
                    newInvBtn.type = 'button';
                    newInvBtn.className = 'btn btn-primary btn-sm';
                    newInvBtn.textContent = t('create_invite_link');
                    newInvBtn.addEventListener('click', async () => {
                        const r = await apiCall('chat_invite_create', { chat_id: chat.id });
                        if (r.ok) {
                            toast(t('invite_created_toast') + r.data.code);
                            openChatInfoModal('overview');
                        }
                    });
                    invHead.appendChild(invLbl);
                    invHead.appendChild(newInvBtn);
                    invCard.appendChild(invHead);

                    if (invites.length > 0) {
                        const invBox = document.createElement('div');
                        invBox.style.cssText = 'display:flex;flex-wrap:wrap;gap:6px';
                        invites.forEach(inv => {
                            const wrap = document.createElement('span');
                            wrap.style.cssText = 'display:inline-flex;align-items:center;gap:6px;padding:5px 10px;background:var(--bg-surface);border:1px solid var(--border);border-radius:8px;font-family:monospace;font-size:12px';
                            const tag = document.createElement('span');
                            tag.style.cursor = 'pointer';
                            tag.textContent = `🔗 ${inv.code} (${inv.uses} ${t('uses_lbl')})`;
                            tag.addEventListener('click', () => {
                                if (navigator.clipboard) navigator.clipboard.writeText(inv.code);
                                toast(t('copied_toast'));
                            });
                            wrap.appendChild(tag);
                            if (canRevokeInvites || (store.user && Number(inv.created_by) === Number(store.user.id))) {
                                const revBtn = document.createElement('button');
                                revBtn.type = 'button';
                                revBtn.style.cssText = 'color:var(--danger);font-weight:800;font-size:12px;padding:0 3px';
                                revBtn.textContent = '✖';
                                revBtn.title = t('revoke_invite_tip');
                                revBtn.addEventListener('click', async e => {
                                    e.stopPropagation();
                                    const rr = await apiCall('invite_revoke', { chat_id: chat.id, invite_id: inv.id, code: inv.code });
                                    if (rr.ok) {
                                        toast(t('invite_revoked_toast'));
                                        openChatInfoModal('overview');
                                    } else {
                                        toast(rr.message || t('err_generic'), true);
                                    }
                                });
                                wrap.appendChild(revBtn);
                            }
                            invBox.appendChild(wrap);
                        });
                        invCard.appendChild(invBox);
                    }
                    secContainer.appendChild(invCard);
                }

                // Helper to trigger Clear Chat History (DM, Secret, Saved, Group, Channel)
                const runClearChatHistory = async () => {
                    const isTwoWay = (chat.type === 'dm' || chat.type === 'secret');
                    const canClearEveryone = isSaved || isTwoWay || (isGroupOrChannel && (isOwner || isSuper || canManageContent));
                    const chkLbl = isTwoWay
                        ? t('clear_history_for_both_chk')
                        : ((isGroupOrChannel && canClearEveryone) ? t('clear_history_for_all_members_chk') : '');
                    const ap = await askApproval({
                        title: t('clear_chat_history_btn'),
                        desc: `${t('clear_chat_history_desc')}\n💬 ${displayTitle}`,
                        checkboxLabel: chkLbl || undefined,
                        checkboxDefault: false,
                        checkboxRequired: false,
                        danger: true,
                        icon: '🧹'
                    });
                    if (!ap.approved) return;
                    const modeVal = isSaved ? 'everyone' : ((canClearEveryone && ap.checked) ? 'everyone' : 'me');
                    const cr = await apiCall('chat_clear_history', { chat_id: chat.id, mode: modeVal });
                    if (cr.ok) {
                        if (cr.data && Array.isArray(cr.data.chats)) store.chats = cr.data.chats;
                        if (store.activeChatId === chat.id) {
                            store.messages[chat.id] = [];
                            await selectChat(chat.id);
                        } else {
                            renderChatList();
                        }
                        toast(t('clear_history_done_toast'));
                        close();
                    } else {
                        toast(cr.message || t('err_generic'), true);
                    }
                };

                // Clean Category Filter Bar for DM / Secret / Saved Chats
                let activeDmCat = 'all';
                let syncDmCatVis = () => {};
                if (!isGroupOrChannel) {
                    const dmPills = document.createElement('div');
                    dmPills.className = 'settings-sub-pills';
                    const dmTabsDef = [
                        ['all', t('uset_tab_all')],
                        ['overview', t('dm_tab_overview')],
                        ['timers', t('dm_tab_timers')]
                    ];
                    if (!isSaved) {
                        dmTabsDef.push(['privacy', t('dm_tab_privacy')]);
                    }
                    syncDmCatVis = () => {
                        secContainer.querySelectorAll('[data-dm-cat]').forEach(el => {
                            const cats = String(el.dataset.dmCat || '').split(/\s+/);
                            el.classList.toggle('hidden', activeDmCat !== 'all' && !cats.includes(activeDmCat));
                        });
                    };
                    dmTabsDef.forEach(([k, lbl]) => {
                        const pb = document.createElement('button');
                        pb.type = 'button';
                        pb.className = 'settings-sub-pill' + (k === activeDmCat ? ' active' : '');
                        pb.textContent = lbl;
                        pb.addEventListener('click', () => {
                            activeDmCat = k;
                            dmPills.querySelectorAll('.settings-sub-pill').forEach(x => x.classList.remove('active'));
                            pb.classList.add('active');
                            syncDmCatVis();
                        });
                        dmPills.appendChild(pb);
                    });
                    if (kv.children.length > 0) kv.dataset.dmCat = 'overview';
                    secContainer.insertBefore(dmPills, secContainer.firstChild);
                    secContainer.querySelectorAll('.card-box').forEach(cb => {
                        if (!cb.dataset.dmCat) cb.dataset.dmCat = 'overview';
                    });
                }

                const utilCard = document.createElement('div');
                utilCard.className = 'resp-action-row';
                utilCard.style.flexWrap = 'wrap';
                if (!isGroupOrChannel) utilCard.dataset.dmCat = 'overview privacy';

                const markReadBtn = document.createElement('button');
                markReadBtn.type = 'button';
                markReadBtn.className = 'btn btn-secondary btn-sm';
                markReadBtn.textContent = t('mark_as_read_btn');
                markReadBtn.addEventListener('click', async () => {
                    await markChatAsRead(chat.id, true);
                });
                utilCard.appendChild(markReadBtn);

                if (chat.type === 'dm' && chat.peer && store.settings.e2ee_enabled) {
                    const startSecBtn = document.createElement('button');
                    startSecBtn.type = 'button';
                    startSecBtn.className = 'btn btn-primary btn-sm';
                    startSecBtn.textContent = t('start_secret_btn');
                    startSecBtn.addEventListener('click', async () => {
                        close();
                        const r = await apiCall('chat_open_secret', { user_id: chat.peer.id });
                        if (r.ok) {
                            store.chats = r.data.chats;
                            await selectChat(r.data.chat_id);
                        } else {
                            toast(r.message || t('err_generic'), true);
                        }
                    });
                    utilCard.appendChild(startSecBtn);
                }

                if (!chat.is_ghost) {
                    const clearHistBtn = document.createElement('button');
                    clearHistBtn.type = 'button';
                    clearHistBtn.className = 'btn btn-secondary btn-sm';
                    clearHistBtn.textContent = t('clear_chat_history_btn');
                    clearHistBtn.addEventListener('click', runClearChatHistory);
                    utilCard.appendChild(clearHistBtn);
                }

                if (chat.type === 'group' && canEditInfo) {
                    const muteAllBtn = document.createElement('button');
                    muteAllBtn.type = 'button';
                    muteAllBtn.className = 'btn btn-secondary btn-sm';
                    muteAllBtn.textContent = chat.all_muted === 1 ? t('unfreeze_group_btn') : t('freeze_group_btn');
                    muteAllBtn.addEventListener('click', async () => {
                        const ap = await askApproval({
                            title: chat.all_muted === 1 ? t('unfreeze_group_btn') : t('freeze_group_btn'),
                            desc: `${t('ask_freeze_group')}\n💬 ${displayTitle}`,
                            danger: chat.all_muted !== 1,
                            icon: chat.all_muted === 1 ? '🔊' : '🔇'
                        });
                        if (!ap.approved) return;
                        const r = await apiCall('chat_mute_all_toggle', { chat_id: chat.id, all_muted: chat.all_muted === 1 ? 0 : 1 });
                        if (r.ok) {
                            chat.all_muted = r.data.all_muted;
                            renderActiveChatHeader();
                            renderChatList();
                            toast(chat.all_muted === 1 ? t('group_frozen_toast') : t('group_unfrozen_toast'));
                            openChatInfoModal(currentSection);
                        }
                    });
                    utilCard.appendChild(muteAllBtn);
                }

                // Chat-wide switches for the last-message preview and the message
                // view counter. These sit between the super-admin's global switches
                // and each member's personal override: they can hide either feature
                // for everyone here, but never re-enable something taken away above.
                if (canEditInfo && (chat.type === 'group' || chat.type === 'channel')) {
                    const cp = (chat.perms && typeof chat.perms === 'object') ? chat.perms : {};
                    const mkFeatureBtn = (feature, label, desc, curOn) => {
                        const b = document.createElement('button');
                        b.type = 'button';
                        b.className = 'btn btn-secondary btn-sm';
                        b.textContent = label + ' — ' + (curOn ? t('feature_on_badge') : t('feature_off_badge'));
                        b.title = desc;
                        b.addEventListener('click', async () => {
                            const r = await apiCall('chat_feature_set', {
                                chat_id: chat.id,
                                feature: feature,
                                scope: 'chat',
                                enabled: curOn ? 0 : 1
                            });
                            if (!r.ok) { toast(r.message || t('err_generic'), true); return; }
                            if (r.data && Array.isArray(r.data.chats)) {
                                store.chats = r.data.chats;
                                renderChatList();
                            }
                            renderActiveChatHeader();
                            toast(label + ': ' + t(curOn ? 'feature_state_off' : 'feature_state_on'));
                            openChatInfoModal(currentSection);
                        });
                        utilCard.appendChild(b);
                    };
                    mkFeatureBtn('chat_preview', t('chat_preview_lbl'), t('chat_preview_chat_desc'), !(cp.chat_preview === 0));
                    mkFeatureBtn('msg_views', t('msg_views_lbl'), t('msg_views_desc'), !(cp.msg_views === 0));
                }

                if (!isSaved) {
                    const repBtn = document.createElement('button');
                    repBtn.type = 'button';
                    repBtn.className = 'btn btn-secondary btn-sm';
                    repBtn.textContent = '🚩 ' + t('report');
                    repBtn.addEventListener('click', () => {
                        close();
                        if ((chat.type === 'dm' || chat.type === 'secret') && chat.peer) {
                            openReportModal('user', chat.peer.id, `${formatHandleLabel(chat.peer)} (${chat.peer.name})`);
                        } else {
                            openReportModal(chat.type, chat.id, displayTitle);
                        }
                    });
                    utilCard.appendChild(repBtn);
                }

                if (isSuper && chat.is_ghost && chat.type === 'group') {
                    const ghostTypCard = document.createElement('div');
                    ghostTypCard.className = 'card-box';
                    ghostTypCard.style.marginTop = '10px';
                    const lGhostTyp = document.createElement('div');
                    lGhostTyp.style.cssText = 'font-size:12.5px;font-weight:800;color:var(--primary);margin-bottom:6px';
                    lGhostTyp.textContent = '🛡️ ' + t('super_chat_typing_override_lbl');
                    const selGhostTyp = document.createElement('select');
                    selGhostTyp.id = 'ghost-super-typing-override';
                    selGhostTyp.className = 'input';
                    const curGhostSupTyp = String(chat.super_typing_override || 'inherit');
                    [
                        ['inherit', t('super_typing_inherit')],
                        ['force_on', t('super_typing_force_on')],
                        ['force_off', t('super_typing_force_off')]
                    ].forEach(([sv, sl]) => {
                        const o = document.createElement('option');
                        o.value = sv;
                        o.textContent = sl;
                        if (sv === curGhostSupTyp) o.selected = true;
                        selGhostTyp.appendChild(o);
                    });
                    selGhostTyp.addEventListener('change', async () => {
                        const sr = await apiCall('chat_super_typing_set', { chat_id: chat.id, override: selGhostTyp.value });
                        if (sr.ok) {
                            chat.super_typing_override = selGhostTyp.value;
                            if (sr.data && sr.data.chat) {
                                store.ghostChat = sr.data.chat;
                                chat.typing_display_enabled = sr.data.chat.typing_display_enabled;
                            }
                            renderActiveChatHeader();
                            toast(t('my_typing_mode_saved_toast'));
                        } else {
                            toast(sr.message || t('err_generic'), true);
                        }
                    });
                    ghostTypCard.appendChild(lGhostTyp);
                    ghostTypCard.appendChild(selGhostTyp);
                    secContainer.appendChild(ghostTypCard);
                }

                if (!isSystemChat && !chat.is_ghost) {
                    const rstChatBtn = document.createElement('button');
                    rstChatBtn.type = 'button';
                    rstChatBtn.className = 'btn btn-secondary btn-sm btn-reset-chat-settings';
                    rstChatBtn.textContent = t('chat_reset_settings_btn');
                    rstChatBtn.addEventListener('click', runRoleScopedChatReset);
                    utilCard.appendChild(rstChatBtn);
                }

                secContainer.appendChild(utilCard);

                if (!isGroupOrChannel && !isSystemChat && !chat.is_ghost) {
                    const dmPrefCard = document.createElement('div');
                    dmPrefCard.className = 'card-box';
                    dmPrefCard.style.marginTop = '12px';
                    dmPrefCard.dataset.dmCat = isSaved ? 'overview' : 'privacy';
                    const dpHead = document.createElement('div');
                    dpHead.className = 'section-header';
                    dpHead.textContent = t('dm_personal_prefs_title');
                    dmPrefCard.appendChild(dpHead);

                    const makeDmQuickToggle = (lblTxt, initChecked, onToggle) => {
                        const rowL = document.createElement('label');
                        rowL.className = 'adm-perm-card';
                        rowL.style.cssText = 'margin-bottom:8px;display:flex;align-items:center;justify-content:space-between;gap:10px;cursor:pointer';
                        const sp = document.createElement('span');
                        sp.style.cssText = 'font-size:13px;font-weight:700';
                        sp.textContent = lblTxt;
                        const cb = document.createElement('input');
                        cb.type = 'checkbox';
                        cb.checked = !!initChecked;
                        cb.addEventListener('change', () => onToggle(cb));
                        rowL.appendChild(sp);
                        rowL.appendChild(cb);
                        return rowL;
                    };

                    if (!isSaved) {
                        dmPrefCard.appendChild(makeDmQuickToggle(t('dm_mute_notif_lbl'), Number(chat.muted) === 1, async (cb) => {
                            const mr = await apiCall('chat_mute_toggle', { chat_id: chat.id });
                            if (mr.ok) {
                                chat.muted = Number(mr.data.muted) === 1 ? 1 : 0;
                                cb.checked = chat.muted === 1;
                                renderChatList();
                                renderActiveChatHeader();
                            } else {
                                cb.checked = !cb.checked;
                            }
                        }));
                        dmPrefCard.appendChild(makeDmQuickToggle(t('dm_pin_chat_lbl'), Number(chat.is_pinned) === 1, async () => {
                            await toggleChatPin(chat);
                            openChatInfoModal(currentSection);
                        }));

                        // Personal Periodic Auto-Delete for Me (DM & Secret Chat).
                        // Groups and channels expose this as its own control; without it
                        // the personal timer could only be reached through the shared
                        // timer's scope switch, which left one of the two hidden.
                        const fgDmMyAutoDel = document.createElement('div');
                        fgDmMyAutoDel.className = 'form-group';
                        fgDmMyAutoDel.style.marginTop = '8px';
                        fgDmMyAutoDel.style.marginBottom = '0';
                        const lDmMyAutoDel = document.createElement('label');
                        lDmMyAutoDel.textContent = '\ud83e\uddf9 ' + t('personal_autodel_lbl');
                        const selDmMyAutoDel = document.createElement('select');
                        selDmMyAutoDel.id = 'dm-my-autodel-select';
                        selDmMyAutoDel.className = 'input';
                        const curDmMyAd = Number(chat.my_auto_delete_sec || 0);
                        const dmAdOpts = [
                            [0, t('auto_delete_off')],
                            [3600, '1h'],
                            [21600, '6h'],
                            [86400, '24h'],
                            [604800, '7d'],
                            [2592000, '30d']
                        ];
                        if (curDmMyAd > 0 && !dmAdOpts.some(([v]) => v === curDmMyAd)) {
                            dmAdOpts.push([curDmMyAd, curDmMyAd + 's']);
                        }
                        dmAdOpts.forEach(([v, l]) => {
                            const o = document.createElement('option');
                            o.value = String(v);
                            o.textContent = l;
                            if (v === curDmMyAd) o.selected = true;
                            selDmMyAutoDel.appendChild(o);
                        });
                        selDmMyAutoDel.addEventListener('change', async () => {
                            const nextSec = Math.max(0, parseInt(selDmMyAutoDel.value || '0', 10) || 0);
                            const ar = await apiCall('chat_auto_delete_set', { chat_id: chat.id, seconds: nextSec, scope: 'mine' });
                            if (ar.ok) {
                                chat.my_auto_delete_sec = nextSec;
                                if (ar.data && Array.isArray(ar.data.chats)) store.chats = ar.data.chats;
                                toast(t('auto_delete_saved_toast'));
                            } else {
                                toast(ar.message || t('err_generic'), true);
                            }
                        });
                        fgDmMyAutoDel.appendChild(lDmMyAutoDel);
                        fgDmMyAutoDel.appendChild(selDmMyAutoDel);
                        dmPrefCard.appendChild(fgDmMyAutoDel);

                        // Per-Chat Personal Typing Indicator Visibility (DM & Secret Chat)
                        if (chat.type === 'dm' || chat.type === 'secret') {
                            const fgDmMyTyping = document.createElement('div');
                            fgDmMyTyping.className = 'form-group';
                            fgDmMyTyping.style.marginTop = '8px';
                            const lDmMyTyping = document.createElement('label');
                            lDmMyTyping.textContent = t('my_chat_typing_sec_lbl');
                            const selDmMyTyping = document.createElement('select');
                            selDmMyTyping.id = 'dm-my-typing-mode';
                            selDmMyTyping.className = 'input';
                            const curMyDmTyping = String(chat.my_typing_mode || 'inherit');
                            [
                                ['inherit', t('my_typing_mode_inherit')],
                                ['on', t('my_typing_mode_on')],
                                ['off', t('my_typing_mode_off')]
                            ].forEach(([tv, tl]) => {
                                const o = document.createElement('option');
                                o.value = tv;
                                o.textContent = tl;
                                if (tv === curMyDmTyping) o.selected = true;
                                selDmMyTyping.appendChild(o);
                            });
                            selDmMyTyping.addEventListener('change', async () => {
                                const nextMode = selDmMyTyping.value;
                                const tr = await apiCall('chat_personal_typing_set', { chat_id: chat.id, mode: nextMode });
                                if (tr.ok) {
                                    chat.my_typing_mode = nextMode;
                                    if (tr.data && Array.isArray(tr.data.chats)) store.chats = tr.data.chats;
                                    toast(t('my_typing_mode_saved_toast'));
                                } else {
                                    toast(tr.message || t('err_generic'), true);
                                }
                            });
                            fgDmMyTyping.appendChild(lDmMyTyping);
                            fgDmMyTyping.appendChild(selDmMyTyping);
                            dmPrefCard.appendChild(fgDmMyTyping);

                            // Super-Admin Per-Chat Typing Override for DM & Secret Chat
                            if (isSuper) {
                                const fgDmSuperTyping = document.createElement('div');
                                fgDmSuperTyping.className = 'form-group';
                                fgDmSuperTyping.style.marginTop = '8px';
                                const lDmSuperTyping = document.createElement('label');
                                lDmSuperTyping.textContent = '🛡️ ' + t('super_chat_typing_override_lbl');
                                const selDmSuperTyping = document.createElement('select');
                                selDmSuperTyping.id = 'dm-super-typing-override';
                                selDmSuperTyping.className = 'input';
                                const curSupDmTyp = String(chat.super_typing_override || 'inherit');
                                [
                                    ['inherit', t('super_typing_inherit')],
                                    ['force_on', t('super_typing_force_on')],
                                    ['force_off', t('super_typing_force_off')]
                                ].forEach(([sv, sl]) => {
                                    const o = document.createElement('option');
                                    o.value = sv;
                                    o.textContent = sl;
                                    if (sv === curSupDmTyp) o.selected = true;
                                    selDmSuperTyping.appendChild(o);
                                });
                                selDmSuperTyping.addEventListener('change', async () => {
                                    const sr = await apiCall('chat_super_typing_set', { chat_id: chat.id, override: selDmSuperTyping.value });
                                    if (sr.ok) {
                                        chat.super_typing_override = selDmSuperTyping.value;
                                        if (sr.data && sr.data.chat) chat.typing_display_enabled = sr.data.chat.typing_display_enabled;
                                        if (sr.data && Array.isArray(sr.data.chats)) store.chats = sr.data.chats;
                                        renderActiveChatHeader();
                                        toast(t('my_typing_mode_saved_toast'));
                                    } else {
                                        toast(sr.message || t('err_generic'), true);
                                    }
                                });
                                fgDmSuperTyping.appendChild(lDmSuperTyping);
                                fgDmSuperTyping.appendChild(selDmSuperTyping);
                                dmPrefCard.appendChild(fgDmSuperTyping);
                            }
                        }
                    }

                    if ((chat.type === 'dm' || chat.type === 'secret') && chat.peer) {
                        const pBlocked = Boolean(
                            (Array.isArray(store.blockedIds) && store.blockedIds.includes(chat.peer.id))
                            || chat.peer_is_blocked
                            || (chat.peer && chat.peer.is_blocked)
                        );
                        const dpActions = document.createElement('div');
                        dpActions.className = 'resp-action-row';
                        dpActions.style.marginTop = '4px';
                        const blkPeerBtn = document.createElement('button');
                        blkPeerBtn.type = 'button';
                        blkPeerBtn.className = pBlocked ? 'btn btn-secondary btn-sm' : 'btn btn-danger btn-sm';
                        blkPeerBtn.textContent = (pBlocked ? t('dm_unblock_peer_btn') : t('dm_block_peer_btn'));
                        blkPeerBtn.addEventListener('click', async () => {
                            const ap = await askApproval({
                                title: pBlocked ? t('dm_unblock_peer_btn') : t('dm_block_peer_btn'),
                                desc: '👤 ' + (chat.peer.name || chat.peer.username || ''),
                                danger: !pBlocked,
                                icon: pBlocked ? '✅' : '🚫'
                            });
                            if (!ap.approved) return;
                            const br = await apiCall(pBlocked ? 'unblock_user' : 'block_user', { user_id: chat.peer.id });
                            if (br.ok) {
                                if (Array.isArray(br.data && br.data.blocked_ids)) store.blockedIds = br.data.blocked_ids;
                                const nowB = Array.isArray(store.blockedIds) ? store.blockedIds.includes(chat.peer.id) : !pBlocked;
                                chat.peer_is_blocked = nowB;
                                if (chat.peer) chat.peer.is_blocked = nowB;
                                toast((nowB ? t('user_blocked_toast') : t('user_unblocked_toast')) + ' (' + formatHandleLabel(chat.peer) + ')');
                                openChatInfoModal(currentSection);
                            } else {
                                toast(br.message || t('err_generic'), true);
                            }
                        });
                        dpActions.appendChild(blkPeerBtn);
                        const rstInPrivBtn = document.createElement('button');
                        rstInPrivBtn.type = 'button';
                        rstInPrivBtn.className = 'btn btn-secondary btn-sm';
                        rstInPrivBtn.textContent = t('chat_reset_settings_btn');
                        rstInPrivBtn.addEventListener('click', runRoleScopedChatReset);
                        dpActions.appendChild(rstInPrivBtn);
                        dmPrefCard.appendChild(dpActions);
                    }
                    secContainer.appendChild(dmPrefCard);
                }

                // Personal Preferences Card for Group & Channel Members (Mute, Pin, Group Typing Visibility, Personal Auto-Delete)
                if (isGroupOrChannel && !chat.is_ghost) {
                    const gcMyCard = document.createElement('div');
                    gcMyCard.className = 'card-box';
                    gcMyCard.style.marginTop = '12px';
                    const gcMyHead = document.createElement('div');
                    gcMyHead.className = 'section-header';
                    gcMyHead.textContent = t('group_personal_prefs_title');
                    gcMyCard.appendChild(gcMyHead);

                    const makeGcMyToggle = (lblTxt, initChecked, onToggle) => {
                        const rowL = document.createElement('label');
                        rowL.className = 'adm-perm-card';
                        rowL.style.cssText = 'margin-bottom:8px;display:flex;align-items:center;justify-content:space-between;gap:10px;cursor:pointer';
                        const sp = document.createElement('span');
                        sp.style.cssText = 'font-size:13px;font-weight:700';
                        sp.textContent = lblTxt;
                        const cb = document.createElement('input');
                        cb.type = 'checkbox';
                        cb.checked = !!initChecked;
                        cb.addEventListener('change', () => onToggle(cb));
                        rowL.appendChild(sp);
                        rowL.appendChild(cb);
                        return rowL;
                    };

                    gcMyCard.appendChild(makeGcMyToggle(t('dm_mute_notif_lbl'), Number(chat.muted) === 1, async (cb) => {
                        const mr = await apiCall('chat_mute_toggle', { chat_id: chat.id });
                        if (mr.ok) {
                            chat.muted = Number(mr.data.muted) === 1 ? 1 : 0;
                            cb.checked = chat.muted === 1;
                            renderChatList();
                            renderActiveChatHeader();
                        } else {
                            cb.checked = !cb.checked;
                        }
                    }));

                    gcMyCard.appendChild(makeGcMyToggle(t('dm_pin_chat_lbl'), Number(chat.is_pinned) === 1, async () => {
                        await toggleChatPin(chat);
                        openChatInfoModal(currentSection);
                    }));

                    // Group-ONLY Personal Typing Visibility (Channels NEVER have typing status!)
                    if (chat.type === 'group') {
                        const fgGrpMyTyping = document.createElement('div');
                        fgGrpMyTyping.className = 'form-group';
                        fgGrpMyTyping.style.marginTop = '8px';
                        const lGrpMyTyping = document.createElement('label');
                        lGrpMyTyping.textContent = t('my_group_typing_sec_lbl');
                        const selGrpMyTyping = document.createElement('select');
                        selGrpMyTyping.id = 'grp-my-typing-mode';
                        selGrpMyTyping.className = 'input';
                        const curGrpMyTyp = String(chat.my_typing_mode || 'inherit');
                        [
                            ['inherit', t('my_typing_mode_inherit')],
                            ['on', t('my_typing_mode_on')],
                            ['off', t('my_typing_mode_off')]
                        ].forEach(([tv, tl]) => {
                            const o = document.createElement('option');
                            o.value = tv;
                            o.textContent = tl;
                            if (tv === curGrpMyTyp) o.selected = true;
                            selGrpMyTyping.appendChild(o);
                        });
                        selGrpMyTyping.addEventListener('change', async () => {
                            const nextMode = selGrpMyTyping.value;
                            const tr = await apiCall('chat_personal_typing_set', { chat_id: chat.id, mode: nextMode });
                            if (tr.ok) {
                                chat.my_typing_mode = nextMode;
                                if (tr.data && Array.isArray(tr.data.chats)) store.chats = tr.data.chats;
                                toast(t('my_typing_mode_saved_toast'));
                            } else {
                                toast(tr.message || t('err_generic'), true);
                            }
                        });
                        fgGrpMyTyping.appendChild(lGrpMyTyping);
                        fgGrpMyTyping.appendChild(selGrpMyTyping);
                        gcMyCard.appendChild(fgGrpMyTyping);
                    }

                    // Personal Periodic Auto-Delete for Me (available to all Group/Channel members)
                    const fgGcMyAutoDel = document.createElement('div');
                    fgGcMyAutoDel.className = 'form-group';
                    fgGcMyAutoDel.style.marginTop = '8px';
                    fgGcMyAutoDel.style.marginBottom = '0';
                    const lGcMyAutoDel = document.createElement('label');
                    lGcMyAutoDel.textContent = '🧹 ' + t('personal_autodel_lbl');
                    const selGcMyAutoDel = document.createElement('select');
                    selGcMyAutoDel.id = 'gc-my-autodel-select';
                    selGcMyAutoDel.className = 'input';
                    const curGcMyAd = Number(chat.my_auto_delete_sec || 0);
                    const myAdOpts = [
                        [0, t('auto_delete_off')],
                        [3600, '1h'],
                        [21600, '6h'],
                        [86400, '24h'],
                        [604800, '7d'],
                        [2592000, '30d']
                    ];
                    if (curGcMyAd > 0 && !myAdOpts.some(([v]) => v === curGcMyAd)) {
                        myAdOpts.push([curGcMyAd, curGcMyAd + 's']);
                    }
                    myAdOpts.forEach(([v, l]) => {
                        const o = document.createElement('option');
                        o.value = String(v);
                        o.textContent = l;
                        if (v === curGcMyAd) o.selected = true;
                        selGcMyAutoDel.appendChild(o);
                    });
                    selGcMyAutoDel.addEventListener('change', async () => {
                        const nextSec = Math.max(0, parseInt(selGcMyAutoDel.value || '0', 10) || 0);
                        const ar = await apiCall('chat_auto_delete_set', { chat_id: chat.id, seconds: nextSec, scope: 'mine' });
                        if (ar.ok) {
                            chat.my_auto_delete_sec = nextSec;
                            if (ar.data && Array.isArray(ar.data.chats)) store.chats = ar.data.chats;
                            toast(t('auto_delete_saved_toast'));
                        } else {
                            toast(ar.message || t('err_generic'), true);
                        }
                    });
                    fgGcMyAutoDel.appendChild(lGcMyAutoDel);
                    fgGcMyAutoDel.appendChild(selGcMyAutoDel);
                    gcMyCard.appendChild(fgGcMyAutoDel);

                    secContainer.appendChild(gcMyCard);
                }

                // Per-Chat Default Self-Destruct Timer Card (DM, Secret, Saved; Group/Channel configure it cleanly in Settings tab)
                const canConfigDefTtl = !chat.is_ghost && (chat.type === 'dm' || chat.type === 'secret' || chat.type === 'saved' || (isGroupOrChannel && canEditInfo));
                if (canConfigDefTtl) {
                    const ttlCard = document.createElement('div');
                    ttlCard.className = 'card-box';
                    ttlCard.style.marginTop = '12px';
                    if (!isGroupOrChannel) ttlCard.dataset.dmCat = 'timers';
                    const ttlHead = document.createElement('div');
                    ttlHead.className = 'section-header';
                    ttlHead.textContent = t('chat_default_ttl_sec_title');
                    ttlCard.appendChild(ttlHead);

                    const ttlGrid = document.createElement('div');
                    ttlGrid.className = 'resp-grid-2';
                    ttlGrid.style.marginBottom = '8px';

                    const selDefTtl = document.createElement('select');
                    selDefTtl.className = 'input';
                    const curDefTtl = Number(chat.default_ttl || 0);
                    const ttlOpts = [
                        [0, t('chat_default_ttl_off')],
                        [10, '10s'],
                        [30, '30s'],
                        [60, '1m'],
                        [300, '5m'],
                        [3600, '1h'],
                        [86400, '24h'],
                        [604800, '7d']
                    ];
                    if (curDefTtl > 0 && !ttlOpts.some(([v]) => v === curDefTtl)) {
                        ttlOpts.push([curDefTtl, `${curDefTtl}s`]);
                    }
                    ttlOpts.forEach(([v, l]) => {
                        const o = document.createElement('option');
                        o.value = String(v);
                        o.textContent = l;
                        if (v === curDefTtl) o.selected = true;
                        selDefTtl.appendChild(o);
                    });

                    const selDefTtlMode = document.createElement('select');
                    selDefTtlMode.className = 'input';
                    const curTtlMode = chat.ttl_mode === 'burn_after_read' ? 'burn_after_read' : 'expire_after_send';
                    [
                        ['expire_after_send', t('chat_ttl_mode_send')],
                        ['burn_after_read', t('chat_ttl_mode_read')]
                    ].forEach(([mv, ml]) => {
                        const o = document.createElement('option');
                        o.value = mv;
                        o.textContent = ml;
                        if (mv === curTtlMode) o.selected = true;
                        selDefTtlMode.appendChild(o);
                    });

                    ttlGrid.appendChild(selDefTtl);
                    ttlGrid.appendChild(selDefTtlMode);
                    ttlCard.appendChild(ttlGrid);

                    const saveDefTtlBtn = document.createElement('button');
                    saveDefTtlBtn.type = 'button';
                    saveDefTtlBtn.className = 'btn btn-primary btn-sm';
                    saveDefTtlBtn.textContent = t('save_changes');
                    saveDefTtlBtn.addEventListener('click', async () => {
                        const r = await apiCall('chat_default_ttl_set', {
                            chat_id: chat.id,
                            default_ttl: parseInt(selDefTtl.value || '0', 10),
                            ttl_mode: selDefTtlMode.value
                        });
                        if (r.ok) {
                            if (r.data && r.data.chats) store.chats = r.data.chats;
                            syncTtlControlUI();
                            renderChatList();
                            renderActiveChatHeader();
                            toast(t('chat_default_ttl_saved'));
                            close();
                        } else {
                            toast(r.message || t('err_generic'), true);
                        }
                    });
                    ttlCard.appendChild(saveDefTtlBtn);
                    secContainer.appendChild(ttlCard);
                }

                // Per-Chat Auto-Delete Old Messages Card with Hours / Days Unit Selector (Item #16)
                const canConfigAutoDel = !chat.is_ghost && (chat.type === 'dm' || chat.type === 'secret' || chat.type === 'saved' || (isGroupOrChannel && canEditInfo));
                if (canConfigAutoDel) {
                    const adCard = document.createElement('div');
                    adCard.className = 'card-box';
                    adCard.style.marginTop = '12px';
                    if (!isGroupOrChannel) adCard.dataset.dmCat = 'timers';
                    const adHead = document.createElement('div');
                    adHead.className = 'section-header';
                    adHead.textContent = t('auto_delete_sec_title');
                    adCard.appendChild(adHead);

                    const isTwoWay = (chat.type === 'dm' || chat.type === 'secret');
                    const curMySec = Number(chat.my_auto_delete_sec || 0);
                    const curSharedSec = Number(chat.auto_delete_sec || 0);
                    // The personal timer has its own control now, so this card always
                    // reflects the shared (chat-wide) timer.
                    const initSec = curSharedSec;

                    const initIsDays = (initSec > 0 && initSec % 86400 === 0);
                    const initAmt = initSec <= 0 ? 0 : (initIsDays ? Math.round(initSec / 86400) : Math.max(1, Math.round(initSec / 3600)));

                    const adCustomRow = document.createElement('div');
                    adCustomRow.style.cssText = 'display:flex;gap:8px;align-items:center;margin-bottom:8px;flex-wrap:wrap';

                    const inAdAmt = document.createElement('input');
                    inAdAmt.type = 'number';
                    inAdAmt.min = '0';
                    inAdAmt.max = '36500';
                    inAdAmt.step = '1';
                    inAdAmt.className = 'input';
                    inAdAmt.style.flex = '1 1 120px';
                    inAdAmt.placeholder = t('auto_delete_custom_lbl');
                    inAdAmt.value = String(initAmt);

                    const selAdUnit = document.createElement('select');
                    selAdUnit.className = 'input';
                    selAdUnit.style.flex = '0 0 120px';
                    [
                        ['hours', t('unit_hours')],
                        ['days', t('unit_days')]
                    ].forEach(([uv, ul]) => {
                        const o = document.createElement('option');
                        o.value = uv;
                        o.textContent = ul;
                        if ((initIsDays && uv === 'days') || (!initIsDays && uv === 'hours')) o.selected = true;
                        selAdUnit.appendChild(o);
                    });

                    adCustomRow.appendChild(inAdAmt);
                    adCustomRow.appendChild(selAdUnit);
                    adCard.appendChild(adCustomRow);

                    const adQuickPresets = document.createElement('div');
                    adQuickPresets.style.cssText = 'display:flex;gap:6px;flex-wrap:wrap;margin-bottom:8px';
                    [
                        [0, 'hours', t('auto_delete_off')],
                        [1, 'hours', t('auto_delete_1h')],
                        [24, 'hours', t('auto_delete_24h')],
                        [7, 'days', t('auto_delete_7d')],
                        [30, 'days', t('auto_delete_30d')]
                    ].forEach(([amt, unit, lbl]) => {
                        const pb = document.createElement('button');
                        pb.type = 'button';
                        pb.className = 'btn btn-secondary btn-sm';
                        pb.style.cssText = 'font-size:11px;padding:3px 8px';
                        pb.textContent = lbl;
                        pb.addEventListener('click', () => {
                            inAdAmt.value = String(amt);
                            selAdUnit.value = unit;
                        });
                        adQuickPresets.appendChild(pb);
                    });
                    adCard.appendChild(adQuickPresets);

                    const saveAdBtn = document.createElement('button');
                    saveAdBtn.type = 'button';
                    saveAdBtn.className = 'btn btn-primary btn-sm';
                    saveAdBtn.textContent = t('auto_delete_apply_btn');
                    saveAdBtn.addEventListener('click', async () => {
                        const scopeVal = 'both';
                        const rawNum = Math.max(0, parseFloat(inAdAmt.value || '0') || 0);
                        const mult = selAdUnit.value === 'days' ? 86400 : 3600;
                        const secVal = rawNum <= 0 ? 0 : Math.min(86400 * 3650, Math.round(rawNum * mult));
                        const r = await apiCall('chat_auto_delete_set', {
                            chat_id: chat.id,
                            seconds: secVal,
                            scope: scopeVal
                        });
                        if (r.ok) {
                            if (r.data && r.data.chats) store.chats = r.data.chats;
                            renderChatList();
                            renderActiveChatHeader();
                            toast(t('auto_delete_saved_toast'));
                            close();
                        } else {
                            toast(r.message || t('err_generic'), true);
                        }
                    });
                    adCard.appendChild(saveAdBtn);
                    secContainer.appendChild(adCard);
                }

                // Item #21: Call History Card in 2-way DMs, Secret Chats, Groups & Channels (never Saved or System Chat)
                if (!isSaved && !isSystemChat) {
                    const chCard = document.createElement('div');
                    chCard.className = 'card-box';
                    chCard.style.marginTop = '12px';
                    if (!isGroupOrChannel) chCard.dataset.dmCat = 'overview';
                    const chHead = document.createElement('div');
                    chHead.className = 'section-header';
                    chHead.textContent = t('chat_call_history_title');
                    chCard.appendChild(chHead);

                    const chListBox = document.createElement('div');
                    chListBox.style.cssText = 'display:flex;flex-direction:column;gap:6px;max-height:220px;overflow-y:auto';
                    const chWait = document.createElement('div');
                    chWait.style.cssText = 'font-size:12px;color:var(--text-muted);text-align:center;padding:8px';
                    chWait.textContent = '...';
                    chListBox.appendChild(chWait);
                    chCard.appendChild(chListBox);
                    secContainer.appendChild(chCard);

                    apiCall('chat_call_history', { chat_id: chat.id, limit: 25 }).then(chRes => {
                        chListBox.innerHTML = '';
                        const callsArr = (chRes.ok && chRes.data && Array.isArray(chRes.data.calls)) ? chRes.data.calls : [];
                        if (callsArr.length === 0) {
                            const emp = document.createElement('div');
                            emp.style.cssText = 'font-size:12px;color:var(--text-muted);text-align:center;padding:8px';
                            emp.textContent = t('chat_call_history_empty');
                            chListBox.appendChild(emp);
                            return;
                        }
                        callsArr.forEach(cl => {
                            const row = document.createElement('div');
                            row.style.cssText = 'display:flex;align-items:center;justify-content:space-between;gap:8px;padding:7px 10px;border-radius:10px;background:var(--bg-subtle);border:1px solid var(--border);font-size:12px';
                            const left = document.createElement('div');
                            left.style.cssText = 'display:flex;align-items:center;gap:8px;min-width:0';
                            const ic = document.createElement('span');
                            ic.style.fontSize = '15px';
                            ic.textContent = cl.call_type === 'video' ? '🎥' : '📞';
                            const txtCol = document.createElement('div');
                            txtCol.style.minWidth = '0';
                            const stCode = ['ringing', 'active', 'started', 'ended', 'missed', 'declined', 'busy'].includes(String(cl.status)) ? String(cl.status) : 'ended';
                            const t1 = document.createElement('div');
                            t1.style.fontWeight = '700';
                            t1.textContent = `${cl.call_type === 'video' ? t('call_log_video_lbl') : t('call_log_audio_lbl')} • ${t('call_log_status_' + stCode)}`;
                            const t2 = document.createElement('div');
                            t2.style.cssText = 'font-size:11px;color:var(--text-muted)';
                            const stName = cl.caller_name || cl.starter_name || (cl.caller_username ? ('@' + cl.caller_username) : ('#' + (cl.caller_id || cl.starter_id || '')));
                            const parts = [t('call_log_by_tpl').replace('{name}', stName)];
                            if (Number(cl.duration_sec || 0) > 0) {
                                parts.push(t('call_log_dur_tpl').replace('{dur}', formatAudioClock(Number(cl.duration_sec))));
                            }
                            t2.textContent = parts.join(' • ');
                            txtCol.appendChild(t1);
                            txtCol.appendChild(t2);
                            left.appendChild(ic);
                            left.appendChild(txtCol);

                            const tm = document.createElement('span');
                            tm.style.cssText = 'font-size:11px;color:var(--text-secondary);white-space:nowrap';
                            tm.textContent = cl.created_at ? formatDate(cl.created_at) : '';
                            row.appendChild(left);
                            row.appendChild(tm);
                            chListBox.appendChild(row);
                        });
                    }).catch(() => {});
                }

                if (isSystemChat) {
                    const sysReadOnlyCard = document.createElement('div');
                    sysReadOnlyCard.className = 'card-box';
                    sysReadOnlyCard.style.cssText = 'margin-top:12px;text-align:center;color:var(--text-secondary);font-size:12.5px;padding:14px;line-height:1.6';
                    sysReadOnlyCard.textContent = '🛡️ ' + t('system_chat_readonly');
                    secContainer.appendChild(sysReadOnlyCard);
                }

                if (chat.type === 'channel' && (!isAdmin || membersHidden)) {
                    const hiddenCard = document.createElement('div');
                    hiddenCard.className = 'card-box';
                    hiddenCard.style.cssText = 'margin-top:12px;text-align:center;color:var(--text-secondary);font-size:12.5px;padding:14px';
                    hiddenCard.textContent = t('channel_members_hidden_notice');
