                }
                return;
            }

            if (currentSection === 'settings' && isGroupOrChannel && (canEditInfo || canManageContent || canManageCalls || canInvite)) {
                const editCard = document.createElement('div');
                editCard.className = 'card-box';

                if (canEditInfo || canManageContent || canManageCalls) {
                    // Item #24 & #30: Live Search + Clean Sub-Category Filter Pills for Group & Channel Settings
                    const csetSearchWrap = document.createElement('div');
                    csetSearchWrap.className = 'settings-live-search-wrap';
                    const csetSearchIn = document.createElement('input');
                    csetSearchIn.type = 'search';
                    csetSearchIn.id = 'chat-settings-search-input';
                    csetSearchIn.className = 'input';
                    csetSearchIn.placeholder = t('chat_settings_search_ph');
                    csetSearchWrap.appendChild(csetSearchIn);
                    editCard.appendChild(csetSearchWrap);

                    const csetPills = document.createElement('div');
                    csetPills.className = 'settings-sub-pills';
                    let activeCsetSub = 'all';
                    const syncCsetSubVis = () => {
                        const q = csetSearchIn.value.trim().toLowerCase();
                        editCard.querySelectorAll('[data-cset-sub]').forEach(el => {
                            if (el.dataset.permHidden === '1') {
                                el.classList.add('hidden');
                                return;
                            }
                            if (q) {
                                const hit = (el.textContent || '').toLowerCase().includes(q);
                                el.classList.toggle('hidden', !hit);
                                return;
                            }
                            const cats = String(el.dataset.csetSub || '').split(/\s+/);
                            el.classList.toggle('hidden', activeCsetSub !== 'all' && !cats.includes(activeCsetSub));
                        });
                    };
                    csetSearchIn.addEventListener('input', syncCsetSubVis);
                    [
                        ['all', t('cset_sub_all')],
                        ['identity', t('cset_sub_identity')],
                        ['perms', t('cset_sub_perms')],
                        ['calls_timers', t('cset_sub_calls_timers')],
                        ['danger', t('cset_sub_danger')]
                    ].forEach(([subKey, subLbl]) => {
                        const pb = document.createElement('button');
                        pb.type = 'button';
                        pb.className = 'settings-sub-pill' + (subKey === activeCsetSub ? ' active' : '');
                        pb.textContent = subLbl;
                        pb.addEventListener('click', () => {
                            activeCsetSub = subKey;
                            csetPills.querySelectorAll('.settings-sub-pill').forEach(b => b.classList.remove('active'));
                            pb.classList.add('active');
                            syncCsetSubVis();
                        });
                        csetPills.appendChild(pb);
                    });
                    editCard.appendChild(csetPills);

                    const basicInfoWrap = document.createElement('div');
                    if (!canEditInfo && !canManageContent) {
                        basicInfoWrap.dataset.permHidden = '1';
                        basicInfoWrap.classList.add('hidden');
                    }
                    const identityWrap = document.createElement('div');
                    identityWrap.dataset.csetSub = 'identity';
                    if (!canEditInfo) {
                        identityWrap.dataset.permHidden = '1';
                        identityWrap.classList.add('hidden');
                    }
                    const gForm = document.createElement('div');
                    gForm.className = 'resp-grid-2';

                    const makeLabeled = (lblText, inputEl) => {
                        const fg = document.createElement('div');
                        fg.className = 'form-group';
                        const l = document.createElement('label');
                        l.textContent = lblText;
                        fg.appendChild(l);
                        fg.appendChild(inputEl);
                        return fg;
                    };

                    const inTitle = document.createElement('input');
                    inTitle.className = 'input';
                    inTitle.value = formatChatTitle(chat);

                    const inHandle = document.createElement('input');
                    inHandle.className = 'input';
                    inHandle.value = chat.handle || '';
                    inHandle.placeholder = '@handle';
                    inHandle.dir = 'ltr';

                    const selVis = document.createElement('select');
                    selVis.className = 'input';
                    [['public', t('nc_vis_public')], ['private', t('nc_vis_private')]].forEach(([v, l]) => {
                        const o = document.createElement('option');
                        o.value = v;
                        o.textContent = l;
                        if (chat.visibility === v) o.selected = true;
                        selVis.appendChild(o);
                    });

                    const selType = document.createElement('select');
                    selType.className = 'input';
                    [['group', t('chat_type_group')], ['channel', t('chat_type_channel')]].forEach(([v, l]) => {
                        const o = document.createElement('option');
                        o.value = v;
                        o.textContent = l;
                        if (chat.type === v) o.selected = true;
                        selType.appendChild(o);
                    });
                    if (Number(chat.is_default) === 1) {
                        selType.disabled = true;
                    }

                    const selHist = document.createElement('select');
                    selHist.className = 'input';
                    [['all', t('nc_hist_all')], ['from_join', t('nc_hist_join')]].forEach(([v, l]) => {
                        const o = document.createElement('option');
                        o.value = v;
                        o.textContent = l;
                        if (chat.history_vis === v) o.selected = true;
                        selHist.appendChild(o);
                    });

                    const inSlow = document.createElement('input');
                    inSlow.type = 'number';
                    inSlow.className = 'input';
                    inSlow.value = String(chat.slow_mode || 0);

                    const inTtl = document.createElement('input');
                    inTtl.type = 'number';
                    inTtl.min = '0';
                    inTtl.className = 'input';
                    inTtl.value = String(chat.default_ttl || 0);

                    const selSettingsTtlMode = document.createElement('select');
                    selSettingsTtlMode.className = 'input';
                    [
                        ['expire_after_send', t('ttl_mode_after_send')],
                        ['burn_after_read', t('ttl_mode_after_read')]
                    ].forEach(([mv, ml]) => {
                        const o = document.createElement('option');
                        o.value = mv;
                        o.textContent = ml;
                        if ((chat.ttl_mode || 'expire_after_send') === mv) o.selected = true;
                        selSettingsTtlMode.appendChild(o);
                    });

                    const curSuperCeiling = Number(chat.superadmin_ceiling || (chat.type === 'channel' ? (store.settings.max_channel_members ?? 2000) : (store.settings.max_group_members ?? 500)) || 0);
                    const inMaxMembers = document.createElement('input');
                    inMaxMembers.type = 'number';
                    inMaxMembers.min = '0';
                    inMaxMembers.max = (!isSuper && curSuperCeiling > 0) ? String(curSuperCeiling) : '1000000';
                    inMaxMembers.className = 'input';
                    inMaxMembers.value = String(Number(chat.max_members || 0));

                    let inSuperMaxMembers = null;
                    if (isSuper) {
                        inSuperMaxMembers = document.createElement('input');
                        inSuperMaxMembers.type = 'number';
                        inSuperMaxMembers.min = '-1';
                        inSuperMaxMembers.max = '1000000';
                        inSuperMaxMembers.className = 'input';
                        inSuperMaxMembers.placeholder = t('adm_chat_cap_custom_ph');
                        inSuperMaxMembers.value = String(Number(chat.super_max_members || 0));
                    }

                    const handleFieldWrap = makeLabeled(t('nc_handle_label'), inHandle);
                    const privHandleHint = document.createElement('div');
                    privHandleHint.style.cssText = 'font-size:11.5px;color:var(--text-muted);margin:2px 0 6px';
                    privHandleHint.textContent = t('private_handle_hint');

                    const syncVisHandleUI = () => {
                        const isPriv = selVis.value === 'private';
                        handleFieldWrap.classList.toggle('hidden', isPriv);
                        privHandleHint.classList.toggle('hidden', !isPriv);
                    };
                    selVis.addEventListener('change', syncVisHandleUI);
                    syncVisHandleUI();

                    const basicSecHdr = document.createElement('div');
                    basicSecHdr.style.cssText = 'font-size:13px;font-weight:800;color:var(--primary);margin-bottom:8px';
                    basicSecHdr.textContent = t('chat_settings_sec_basic');
                    identityWrap.appendChild(basicSecHdr);

                    let pendingChatAvDataUri = undefined;
                    const csetAvRow = document.createElement('div');
                    csetAvRow.style.cssText = 'display:flex;align-items:center;gap:10px;padding:8px 10px;margin-bottom:10px;border:1px solid var(--border);border-radius:12px;background:var(--bg-subtle);flex-wrap:wrap';
                    const csetAvPrev = document.createElement('div');
                    csetAvPrev.className = 'avatar avatar-sm';
                    renderAvatarNode(csetAvPrev, displayTitle, chat.avatar || '', false, false);
                    const csetAvLbl = document.createElement('span');
                    csetAvLbl.style.cssText = 'font-size:12.5px;font-weight:700;flex:1;min-width:110px';
                    csetAvLbl.textContent = t('chat_avatar_sec_lbl');
                    const csetAvIn = document.createElement('input');
                    csetAvIn.type = 'file';
                    csetAvIn.accept = 'image/*';
                    csetAvIn.className = 'hidden';
                    const csetAvPick = document.createElement('button');
                    csetAvPick.type = 'button';
                    csetAvPick.className = 'btn btn-secondary btn-sm';
                    csetAvPick.textContent = t('chat_pick_avatar_btn');
                    const csetAvRem = document.createElement('button');
                    csetAvRem.type = 'button';
                    csetAvRem.className = 'btn btn-secondary btn-sm' + (chat.avatar ? '' : ' hidden');
                    csetAvRem.style.color = 'var(--danger)';
                    csetAvRem.textContent = '✖ ' + t('chat_remove_avatar_btn');
                    csetAvPick.addEventListener('click', () => csetAvIn.click());
                    csetAvIn.addEventListener('change', async () => {
                        if (!csetAvIn.files || !csetAvIn.files[0]) return;
                        try {
                            pendingChatAvDataUri = await resizeImageFileToAvatarDataUri(csetAvIn.files[0]);
                            renderAvatarNode(csetAvPrev, inTitle.value.trim() || displayTitle, pendingChatAvDataUri, false, false);
                            csetAvRem.classList.remove('hidden');
                            toast(t('avatar_ready_toast'));
                        } catch (e) {
                            toast(t('err_generic'), true);
                        }
                    });
                    csetAvRem.addEventListener('click', () => {
                        pendingChatAvDataUri = '';
                        csetAvIn.value = '';
                        renderAvatarNode(csetAvPrev, inTitle.value.trim() || displayTitle, '', false, false);
                        csetAvRem.classList.add('hidden');
                    });
                    csetAvRow.appendChild(csetAvPrev);
                    csetAvRow.appendChild(csetAvLbl);
                    csetAvRow.appendChild(csetAvPick);
                    csetAvRow.appendChild(csetAvRem);
                    csetAvRow.appendChild(csetAvIn);
                    identityWrap.appendChild(csetAvRow);

                    const slowFieldWrap = makeLabeled(t('slow_mode_label'), inSlow);
                    const ceilTxt = curSuperCeiling > 0 ? formatLocalizedCount(curSuperCeiling) : t('unlimited');
                    gForm.appendChild(makeLabeled(t('nc_title_label'), inTitle));
                    gForm.appendChild(makeLabeled(t('chat_type_lbl'), selType));
                    gForm.appendChild(makeLabeled(t('nc_vis_label'), selVis));
                    gForm.appendChild(handleFieldWrap);
                    gForm.appendChild(makeLabeled(t('nc_hist_label'), selHist));
                    gForm.appendChild(makeLabeled(t('chat_max_members_lbl').replace('{max}', ceilTxt), inMaxMembers));
                    if (isSuper && inSuperMaxMembers) {
                        gForm.appendChild(makeLabeled(t('adm_chat_cap_override_lbl'), inSuperMaxMembers));
                    }
                    gForm.appendChild(slowFieldWrap);
                    gForm.appendChild(makeLabeled(t('auto_ttl_label'), inTtl));
                    gForm.appendChild(makeLabeled(t('ttl_mode_select_lbl') || '⏱️', selSettingsTtlMode));
                    identityWrap.appendChild(gForm);
                    identityWrap.appendChild(privHandleHint);

                    const inDesc = document.createElement('textarea');
                    inDesc.className = 'input';
                    inDesc.rows = 2;
                    inDesc.value = chat.description || '';
                    identityWrap.appendChild(makeLabeled(t('nc_desc_label'), inDesc));
                    basicInfoWrap.appendChild(identityWrap);

                    const reactToggleWrap = document.createElement('label');
                    reactToggleWrap.className = 'adm-perm-card';
                    reactToggleWrap.dataset.csetSub = 'perms';
                    reactToggleWrap.style.cssText = 'margin-top:8px;display:flex;align-items:center;justify-content:space-between;gap:10px;cursor:pointer';
                    const reactToggleLbl = document.createElement('span');
                    reactToggleLbl.style.cssText = 'font-size:13px;font-weight:700';
                    reactToggleLbl.textContent = t('reactions_enabled_label');
                    const chkReactions = document.createElement('input');
                    chkReactions.type = 'checkbox';
                    chkReactions.checked = (chat.reactions_enabled !== 0);
                    reactToggleWrap.appendChild(reactToggleLbl);
                    reactToggleWrap.appendChild(chkReactions);
                    basicInfoWrap.appendChild(reactToggleWrap);

                    // Granular Per-Chat Content Protection Controls (Copy, Select, Download, Forward)
                    const cpBox = document.createElement('div');
                    cpBox.className = 'idle-control-box';
                    cpBox.style.marginTop = '10px';
                    const cpHead = document.createElement('div');
                    cpHead.style.cssText = 'font-size:13px;font-weight:800;margin-bottom:8px';
                    cpHead.textContent = t('content_prot_sec');
                    cpBox.appendChild(cpHead);

                    const chatPermsCur = chat.perms || {};
                    const makeChatCpToggle = (labelTxt, curVal) => {
                        const rowL = document.createElement('label');
                        rowL.className = 'adm-perm-card';
                        rowL.style.cssText = 'margin-bottom:6px;display:flex;align-items:center;justify-content:space-between;gap:10px;cursor:pointer';
                        const sp = document.createElement('span');
                        sp.style.cssText = 'font-size:12.5px;font-weight:700';
                        sp.textContent = labelTxt;
                        const cb = document.createElement('input');
                        cb.type = 'checkbox';
                        cb.checked = curVal;
                        rowL.appendChild(sp);
                        rowL.appendChild(cb);
                        cpBox.appendChild(rowL);
                        return cb;
                    };
                    const chkAllowCopy = makeChatCpToggle(t('allow_copy_msg_lbl'), chatPermsCur.allow_copy_msg === undefined ? true : Number(chatPermsCur.allow_copy_msg) !== 0);
                    const chkAllowSelect = makeChatCpToggle(t('allow_select_text_lbl'), chatPermsCur.allow_select_text === undefined ? true : Number(chatPermsCur.allow_select_text) !== 0);
                    const chkAllowDownload = makeChatCpToggle(t('allow_file_download_lbl'), chatPermsCur.allow_file_download === undefined ? true : Number(chatPermsCur.allow_file_download) !== 0);
                    const chkAllowForward = makeChatCpToggle(t('allow_forward_msg_lbl'), chatPermsCur.allow_forward_msg === undefined ? true : Number(chatPermsCur.allow_forward_msg) !== 0);
                    const chkAdminsOnly = makeChatCpToggle(t('group_admins_only_toggle_lbl'), Number(chatPermsCur.admins_only || 0) === 1);
                    const chkJoinApproval = makeChatCpToggle(
                        t('group_join_approval_lbl'),
                        Number(chat.join_approval !== undefined ? chat.join_approval : (chatPermsCur.join_approval || 0)) === 1
                    );
                    const chkHideMembers = makeChatCpToggle(
                        t('group_hide_members_lbl'),
                        Number(chat.hide_members !== undefined ? chat.hide_members : (chatPermsCur.hide_members || 0)) === 1
                    );
                    const chkMemberInvite = makeChatCpToggle(
                        t('group_member_invite_lbl'),
                        Number(chat.member_invite !== undefined ? chat.member_invite : (chatPermsCur.member_invite || 0)) === 1
                    );
                    const chkMemberPin = makeChatCpToggle(
                        t('group_member_pin_lbl'),
                        Number(chat.member_pin !== undefined ? chat.member_pin : (chatPermsCur.member_pin || 0)) === 1
                    );
                    const chkSendMedia = makeChatCpToggle(
                        t('chat_perm_send_media_lbl'),
                        chatPermsCur.send_media === undefined ? true : Number(chatPermsCur.send_media) !== 0
                    );
                    const chkSendVoice = makeChatCpToggle(
                        t('chat_perm_send_voice_lbl'),
                        chatPermsCur.send_voice === undefined ? true : Number(chatPermsCur.send_voice) !== 0
                    );
                    const chkShowTransferMsg = makeChatCpToggle(
                        t('owner_transfer_msg_toggle_lbl'),
                        chatPermsCur.show_admin_transfer_msg === undefined ? true : Number(chatPermsCur.show_admin_transfer_msg) !== 0
                    );
                    const chkHideEditBadge = makeChatCpToggle(
                        t('chat_hide_edit_badge_lbl'),
                        Number(chat.hide_edit_badge !== undefined ? chat.hide_edit_badge : (chatPermsCur.hide_edit_badge || 0)) === 1
                    );
                    chkHideEditBadge.id = 'cset-hide-edit-badge';
                    const chkShowTyping = makeChatCpToggle(
                        t('grp_show_typing_lbl'),
                        Number(chat.show_typing !== undefined ? chat.show_typing : (chatPermsCur.show_typing ?? 1)) !== 0
                    );
                    chkShowTyping.id = 'cset-show-typing';
                    let fgSuperTypingGroup = null;
                    let selSuperTypingOverride = null;
                    if (isSuper) {
                        fgSuperTypingGroup = document.createElement('div');
                        fgSuperTypingGroup.className = 'form-group';
                        fgSuperTypingGroup.style.marginTop = '8px';
                        const lSuperTyp = document.createElement('label');
                        lSuperTyp.textContent = '🛡️ ' + t('super_chat_typing_override_lbl');
                        selSuperTypingOverride = document.createElement('select');
                        selSuperTypingOverride.id = 'cset-super-typing-override';
                        selSuperTypingOverride.className = 'input';
                        const curSupTypGrp = String(chat.super_typing_override || 'inherit');
                        [
                            ['inherit', t('super_typing_inherit')],
                            ['force_on', t('super_typing_force_on')],
                            ['force_off', t('super_typing_force_off')]
                        ].forEach(([sv, sl]) => {
                            const o = document.createElement('option');
                            o.value = sv;
                            o.textContent = sl;
                            if (sv === curSupTypGrp) o.selected = true;
                            selSuperTypingOverride.appendChild(o);
                        });
                        fgSuperTypingGroup.appendChild(lSuperTyp);
                        fgSuperTypingGroup.appendChild(selSuperTypingOverride);
                        cpBox.appendChild(fgSuperTypingGroup);
                    }
                    if (!canEditInfo) {
                        [chkJoinApproval, chkHideMembers, chkMemberInvite, chkMemberPin, chkShowTransferMsg].forEach(cb => {
                            if (cb && cb.parentElement) cb.parentElement.classList.add('hidden');
                        });
                    }
                    const syncGroupOnlyPermToggles = () => {
                        const isGrp = selType.value === 'group';
                        if (slowFieldWrap) slowFieldWrap.classList.toggle('hidden', !isGrp);
                        [chkAdminsOnly, chkSendMedia, chkSendVoice, chkShowTyping].forEach(cb => {
                            if (cb && cb.parentElement) cb.parentElement.classList.toggle('hidden', !isGrp);
                        });
                        if (fgSuperTypingGroup) {
                            fgSuperTypingGroup.classList.toggle('hidden', !isGrp);
                        }
                        if (canEditInfo && chkMemberPin && chkMemberPin.parentElement) {
                            chkMemberPin.parentElement.classList.toggle('hidden', !isGrp);
                        }
                    };
                    selType.addEventListener('change', syncGroupOnlyPermToggles);
                    syncGroupOnlyPermToggles();
                    cpBox.dataset.csetSub = 'perms';
                    basicInfoWrap.appendChild(cpBox);

                    // Item #6: Group & Channel Message Viewers («مشاهده‌کنندگان پیام») Governance Card
                    const mvBox = document.createElement('div');
                    mvBox.className = 'idle-control-box';
                    mvBox.dataset.csetSub = 'perms';
                    mvBox.style.marginTop = '10px';
                    const mvHead = document.createElement('div');
                    mvHead.style.cssText = 'font-size:13px;font-weight:800;color:var(--primary);margin-bottom:4px';
                    mvHead.textContent = t('viewers_gov_sec_title');
                    mvBox.appendChild(mvHead);
                    const mvDesc = document.createElement('p');
                    mvDesc.style.cssText = 'font-size:12px;color:var(--text-secondary);margin:0 0 8px;line-height:1.5';
                    mvDesc.textContent = t('viewers_gov_chat_desc');
