                    selMvMode.className = 'input';
                    const curMvMode = String(chat.msg_viewers_mode || 'default');
                    const rebuildMvModeOptions = () => {
                        const prevVal = selMvMode.value || curMvMode;
                        selMvMode.innerHTML = '';
                        const defLbl = selType.value === 'channel' ? t('viewers_mode_default_channel') : t('viewers_mode_default_group');
                        [
                            ['default', defLbl],
                            ['everyone', t('viewers_mode_everyone')],
                            ['admins', t('viewers_mode_admins')],
                            ['off', t('viewers_mode_off')]
                        ].forEach(([val, lbl]) => {
                            const o = document.createElement('option');
                            o.value = val;
                            o.textContent = lbl;
                            if (val === prevVal) o.selected = true;
                            selMvMode.appendChild(o);
                        });
                    };
                    rebuildMvModeOptions();
                    selType.addEventListener('change', rebuildMvModeOptions);
                    fgMvMode.appendChild(lMvMode);
                    fgMvMode.appendChild(selMvMode);
                    mvBox.appendChild(fgMvMode);

