                        lSuperMv.textContent = t('viewers_super_chat_override_lbl');
                        selSuperMvOverride = document.createElement('select');
                        selSuperMvOverride.className = 'input';
                        const curSuperMv = String(chat.super_msg_viewers_override || 'inherit');
                        [
                            ['inherit', t('viewers_super_override_inherit')],
                            ['everyone', t('viewers_mode_everyone')],
                            ['admins', t('viewers_mode_admins')],
                            ['off', t('viewers_mode_off')]
                        ].forEach(([val, lbl]) => {
                            const o = document.createElement('option');
                            o.value = val;
                            o.textContent = lbl;
                            if (val === curSuperMv) o.selected = true;
                            selSuperMvOverride.appendChild(o);
                        });
                        fgSuperMv.appendChild(lSuperMv);
                        fgSuperMv.appendChild(selSuperMvOverride);
                        mvBox.appendChild(fgSuperMv);
                    }
                    if (!canEditInfo) {
                        mvBox.dataset.permHidden = '1';
                        mvBox.classList.add('hidden');
                    }
                    basicInfoWrap.appendChild(mvBox);

                    const csetAutoDelBox = document.createElement('div');
                    csetAutoDelBox.className = 'idle-control-box';
                    csetAutoDelBox.dataset.csetSub = 'calls_timers';
                    csetAutoDelBox.style.marginTop = '10px';
                    if (!canEditInfo) {
                        csetAutoDelBox.dataset.permHidden = '1';
                        csetAutoDelBox.classList.add('hidden');
                    }
                    const cadHdr = document.createElement('div');
                    cadHdr.style.cssText = 'font-size:13px;font-weight:800;margin-bottom:6px';
                    cadHdr.textContent = '🧹 ' + t('chat_periodic_autodel_lbl');
                    csetAutoDelBox.appendChild(cadHdr);
                    const curCadSec = Number(chat.auto_delete_sec || 0);
                    const selCsetAutoDel = document.createElement('select');
                    selCsetAutoDel.className = 'input';
                    const cadOpts = [
                        [0, t('chat_default_ttl_off')],
                        [3600, '1h'],
                        [21600, '6h'],
                        [86400, '24h'],
                        [604800, '7d'],
                        [2592000, '30d']
                    ];
                    if (curCadSec > 0 && !cadOpts.some(([v]) => v === curCadSec)) {
                        cadOpts.push([curCadSec, curCadSec + 's']);
                    }
                    cadOpts.forEach(([v, l]) => {
                        const o = document.createElement('option');
                        o.value = String(v);
                        o.textContent = l;
                        if (v === curCadSec) o.selected = true;
                        selCsetAutoDel.appendChild(o);
                    });
                    csetAutoDelBox.appendChild(selCsetAutoDel);
                    basicInfoWrap.appendChild(csetAutoDelBox);

                    const chatIdleBox = document.createElement('div');
                    chatIdleBox.className = 'idle-control-box';
                    chatIdleBox.dataset.csetSub = 'calls_timers';
