                        chatIdleBox.classList.add('hidden');
                    }
                    const ciTop = document.createElement('div');
                    ciTop.style.cssText = 'display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap;margin-bottom:8px';
                    const ciTitle = document.createElement('div');
                    ciTitle.style.cssText = 'font-size:13px;font-weight:800';
                    ciTitle.textContent = t('idle_chat_sec_title');

                    const curChatIdle = getChatIdleStatus(chat);
                    const ciPill = document.createElement('span');
                    ciPill.className = 'idle-status-pill' + (curChatIdle.active ? ' active' : '');
                    ciPill.textContent = curChatIdle.active
                        ? (curChatIdle.mode === 'auto' ? t('idle_status_active_auto') : t('idle_status_active_manual'))
                        : (curChatIdle.mode === 'auto' ? t('idle_status_scheduled') : t('idle_status_normal'));
                    ciTop.appendChild(ciTitle);
                    ciTop.appendChild(ciPill);
                    chatIdleBox.appendChild(ciTop);

                    const selChatIdleMode = document.createElement('select');
                    selChatIdleMode.className = 'input';
                    [['off', t('idle_mode_off')], ['manual', t('idle_mode_manual')], ['auto', t('idle_mode_auto')]].forEach(([val, lbl]) => {
                        const o = document.createElement('option');
                        o.value = val;
                        o.textContent = lbl;
                        if (curChatIdle.mode === val) o.selected = true;
                        selChatIdleMode.appendChild(o);
                    });
                    chatIdleBox.appendChild(selChatIdleMode);

                    const ciHoursGrid = document.createElement('div');
                    ciHoursGrid.className = 'idle-hours-grid' + (curChatIdle.mode === 'auto' ? '' : ' hidden');
                    const inChatIdleStart = document.createElement('input');
                    inChatIdleStart.type = 'time';
                    inChatIdleStart.className = 'input';
                    inChatIdleStart.dir = 'ltr';
                    inChatIdleStart.value = curChatIdle.start || '23:00';
                    const inChatIdleEnd = document.createElement('input');
                    inChatIdleEnd.type = 'time';
                    inChatIdleEnd.className = 'input';
                    inChatIdleEnd.dir = 'ltr';
                    inChatIdleEnd.value = curChatIdle.end || '07:00';
                    ciHoursGrid.appendChild(makeLabeled(t('idle_from_hour_lbl'), inChatIdleStart));
                    ciHoursGrid.appendChild(makeLabeled(t('idle_to_hour_lbl'), inChatIdleEnd));
                    chatIdleBox.appendChild(ciHoursGrid);

                    selChatIdleMode.addEventListener('change', () => {
                        ciHoursGrid.classList.toggle('hidden', selChatIdleMode.value !== 'auto');
                    });

                    const ciQuickManualBtn = document.createElement('button');
                    ciQuickManualBtn.type = 'button';
                    ciQuickManualBtn.className = 'btn btn-secondary btn-sm';
                    ciQuickManualBtn.style.marginTop = '8px';
                    ciQuickManualBtn.textContent = curChatIdle.active ? t('idle_quick_deactivate_btn') : t('idle_quick_activate_btn');
                    ciQuickManualBtn.addEventListener('click', async () => {
                        const nextMode = curChatIdle.active ? 'off' : 'manual';
                        const r = await apiCall('chat_update', Object.assign({
                            chat_id: chat.id,
                            type: selType.value,
                            title: inTitle.value.trim(),
                            handle: selVis.value === 'private' ? '' : inHandle.value.trim(),
                            visibility: selVis.value,
                            history_vis: selHist.value,
                            max_members: Math.max(0, parseInt(inMaxMembers.value || '0', 10) || 0),
                            slow_mode: parseInt(inSlow.value || '0', 10),
                            default_ttl: parseInt(inTtl.value || '0', 10),
                            ttl_mode: selSettingsTtlMode.value,
                            msg_viewers_mode: selMvMode.value,
                            reactions_enabled: chkReactions.checked ? 1 : 0,
                            allow_copy_msg: chkAllowCopy.checked ? 1 : 0,
                            allow_select_text: chkAllowSelect.checked ? 1 : 0,
                            allow_file_download: chkAllowDownload.checked ? 1 : 0,
                            allow_forward_msg: chkAllowForward.checked ? 1 : 0,
                            admins_only: chkAdminsOnly.checked ? 1 : 0,
                            join_approval: chkJoinApproval.checked ? 1 : 0,
                            hide_members: chkHideMembers.checked ? 1 : 0,
                            member_invite: chkMemberInvite.checked ? 1 : 0,
                            member_pin: chkMemberPin.checked ? 1 : 0,
                            show_admin_transfer_msg: chkShowTransferMsg.checked ? 1 : 0,
                            hide_edit_badge: chkHideEditBadge.checked ? 1 : 0,
                            idle_mode: nextMode,
                            idle_start: inChatIdleStart.value || '23:00',
                            idle_end: inChatIdleEnd.value || '07:00',
                            idle_tz_offset: -new Date().getTimezoneOffset(),
                            description: inDesc.value.trim()
                        }, (isSuper && selSuperMvOverride) ? { super_msg_viewers_override: selSuperMvOverride.value } : {}, (isSuper && inSuperMaxMembers) ? { super_max_members: parseInt(inSuperMaxMembers.value || '0', 10) || 0 } : {}));
                        if (r.ok) {
                            const lRes = await apiCall('chats_list');
                            if (lRes.ok) store.chats = lRes.data.chats;
                            renderChatList();
                            renderActiveChatHeader();
                            toast(t('idle_saved_toast'));
                            openChatInfoModal('settings');
                        } else {
                            toast(r.message || t('err_generic'), true);
                        }
                    });
                    chatIdleBox.appendChild(ciQuickManualBtn);
                    basicInfoWrap.appendChild(chatIdleBox);
                    editCard.appendChild(basicInfoWrap);

                    // Per-Chat Granular Content/Media Type Restrictions (Respecting Super-Admin Global Locks)
                    const ALL_CTYPES = ['photo', 'video', 'video_note', 'audio', 'voice', 'document', 'link', 'location'];
                    const globalBlockedSet = new Set(Array.isArray(store.settings.global_restricted_content_types) ? store.settings.global_restricted_content_types : []);
                    const chatRestRes = chat.content_restrictions || {};
                    const curChatBlockedSet = new Set(Array.isArray(chatRestRes.chat_blocked) ? chatRestRes.chat_blocked : []);
                    const ctCheckboxes = {};

                    const ctBox = document.createElement('div');
                    ctBox.className = 'card-box' + (canManageContent ? '' : ' hidden');
                    ctBox.dataset.csetSub = 'perms';
                    if (!canManageContent) ctBox.dataset.permHidden = '1';
                    ctBox.style.cssText = 'margin:12px 0 0;padding:12px';
                    const ctHead = document.createElement('div');
                    ctHead.style.cssText = 'font-weight:800;font-size:13px;color:var(--primary);margin-bottom:4px';
                    ctHead.textContent = t('content_restrict_sec_title');
                    ctBox.appendChild(ctHead);
                    const ctDesc = document.createElement('p');
                    ctDesc.style.cssText = 'font-size:12px;color:var(--text-secondary);margin:0 0 10px;line-height:1.5';
                    ctDesc.textContent = t('content_restrict_chat_desc');
                    ctBox.appendChild(ctDesc);
                    const ctGrid = document.createElement('div');
                    ctGrid.className = 'resp-grid-2';
                    ALL_CTYPES.forEach(ct => {
                        const lockedBySuper = globalBlockedSet.has(ct);
                        const lbl = document.createElement('label');
                        // Same touch target and weight as the permission cards above;
                        // this list used to be noticeably smaller and inconsistent.
                        lbl.className = 'adm-perm-card';
                        lbl.style.cssText = 'justify-content:flex-start;gap:10px;font-size:12.5px;font-weight:700;cursor:' + (lockedBySuper && !isSuper ? 'not-allowed' : 'pointer');
                        const chk = document.createElement('input');
                        chk.type = 'checkbox';
                        chk.checked = lockedBySuper || curChatBlockedSet.has(ct);
                        if (lockedBySuper && !isSuper) chk.disabled = true;
                        ctCheckboxes[ct] = { chk, lockedBySuper };
                        const sp = document.createElement('span');
                        sp.textContent = t('ctype_' + ct) + (lockedBySuper ? ` (${t('locked_by_superadmin_badge')})` : '');
                        lbl.appendChild(chk);
                        lbl.appendChild(sp);
                        ctGrid.appendChild(lbl);
                    });
                    ctBox.appendChild(ctGrid);
                    editCard.appendChild(ctBox);

                    // Per-Chat Live Voice/Video Call & Participation Governance (Call Quality is Super-Admin-Only!)
                    const rawChatPol = ((chat.call_policy && chat.call_policy.chat_raw) ? chat.call_policy.chat_raw : {}) || {};
                    const gCallVoiceOff = Number(store.settings.calls_voice_enabled) === 0;
                    const gCallVideoOff = Number(store.settings.calls_video_enabled) === 0;
                    const callGovBox = document.createElement('div');
                    callGovBox.className = 'card-box' + (canManageCalls ? '' : ' hidden');
                    callGovBox.dataset.csetSub = 'calls_timers';
                    if (!canManageCalls) callGovBox.dataset.permHidden = '1';
                    callGovBox.style.cssText = 'margin:12px 0 0;padding:12px';
                    const cgHead = document.createElement('div');
                    cgHead.style.cssText = 'font-weight:800;font-size:13px;color:var(--primary);margin-bottom:8px';
                    cgHead.textContent = t('call_gov_sec_title');
                    callGovBox.appendChild(cgHead);

                    const cgToggleWrap = document.createElement('div');
                    cgToggleWrap.className = 'resp-grid-2';
                    cgToggleWrap.style.marginBottom = '10px';
                    const mkSimpleChk = (txt, checked, dis) => {
                        const l = document.createElement('label');
                        l.className = 'adm-perm-card';
                        l.style.cssText = 'justify-content:flex-start;gap:10px;font-size:12.5px;font-weight:700'
                            + (dis ? ';opacity:.65;cursor:not-allowed' : '');
                        const c = document.createElement('input');
                        c.type = 'checkbox';
                        c.checked = !!checked;
                        c.disabled = !!dis;
                        const s = document.createElement('span');
                        s.textContent = txt + (dis ? ` (${t('locked_by_superadmin_badge')})` : '');
                        l.appendChild(c);
                        l.appendChild(s);
                        return { l, c };
                    };
                    const cgVoice = mkSimpleChk(t('call_gov_voice_enable'), !gCallVoiceOff && rawChatPol.voice_enabled !== 0, gCallVoiceOff && !isSuper);
                    const cgVideo = mkSimpleChk(t('call_gov_video_enable'), !gCallVideoOff && rawChatPol.video_enabled !== 0, gCallVideoOff && !isSuper);
                    cgToggleWrap.appendChild(cgVoice.l);
                    cgToggleWrap.appendChild(cgVideo.l);
                    callGovBox.appendChild(cgToggleWrap);

                    const fgWho = document.createElement('div');
                    fgWho.className = 'form-group';
                    const lWho = document.createElement('label');
                    lWho.textContent = t('call_gov_who_lbl');
                    const selWho = document.createElement('select');
                    selWho.className = 'input';
                    const defStarterMode = rawChatPol.starter_mode || (chat.type === 'channel' ? 'admins' : 'all');
                    [
                        ['all', t('call_who_all_members')],
                        ['admins', t('call_who_admins_only')],
                        ['specific_admins', t('call_who_specific_admins')]
                    ].forEach(([wv, wl]) => {
                        const o = document.createElement('option');
                        o.value = wv;
                        o.textContent = wl;
                        if (wv === defStarterMode) o.selected = true;
                        selWho.appendChild(o);
                    });
                    fgWho.appendChild(lWho);
                    fgWho.appendChild(selWho);
                    callGovBox.appendChild(fgWho);

                    const specAdminsWrap = document.createElement('div');
                    specAdminsWrap.style.cssText = 'margin:6px 0 10px;padding:8px 10px;border:1px dashed var(--border-strong);border-radius:10px';
                    const specLbl = document.createElement('div');
                    specLbl.style.cssText = 'font-size:12px;font-weight:700;margin-bottom:6px';
                    specLbl.textContent = t('call_gov_pick_admins_lbl');
                    specAdminsWrap.appendChild(specLbl);
                    const specAllowedSet = new Set(Array.isArray(rawChatPol.allowed_admin_ids) ? rawChatPol.allowed_admin_ids.map(Number) : []);
                    const specAdminChecks = [];
                    const chatAdminsList = members.filter(m => m.role === 'owner' || m.role === 'admin' || m.chat_role === 'owner' || m.chat_role === 'admin');
                    chatAdminsList.forEach(adm => {
                        const al = document.createElement('label');
                        al.style.cssText = 'display:inline-flex;align-items:center;gap:6px;margin-inline-end:12px;margin-bottom:4px;font-size:12px;cursor:pointer';
                        const ac = document.createElement('input');
                        ac.type = 'checkbox';
                        ac.checked = specAllowedSet.has(Number(adm.id));
                        specAdminChecks.push({ id: Number(adm.id), chk: ac });
                        const as = document.createElement('span');
                        as.textContent = `${adm.name} (@${adm.username || adm.id})`;
                        al.appendChild(ac);
                        al.appendChild(as);
                        specAdminsWrap.appendChild(al);
                    });
                    const syncSpecAdminsVis = () => {
                        specAdminsWrap.classList.toggle('hidden', selWho.value !== 'specific_admins');
                    };
                    selWho.addEventListener('change', syncSpecAdminsVis);
                    syncSpecAdminsVis();
                    callGovBox.appendChild(specAdminsWrap);

                    // Participation Permission Mode (Groups & Channels)
                    const fgPartMode = document.createElement('div');
                    fgPartMode.className = 'form-group';
                    const lPartMode = document.createElement('label');
                    lPartMode.textContent = t('call_part_mode_label');
                    const selPartMode = document.createElement('select');
                    selPartMode.className = 'input';
                    const curPartMode = rawChatPol.participation_mode || 'open';
                    [
                        ['open', t('call_part_mode_open')],
                        ['members_ask', t('call_part_mode_members_ask')],
                        ['all_ask', t('call_part_mode_all_ask')]
                    ].forEach(([pv, pl]) => {
                        const o = document.createElement('option');
                        o.value = pv;
                        o.textContent = pl;
                        if (pv === curPartMode) o.selected = true;
                        selPartMode.appendChild(o);
                    });
                    fgPartMode.appendChild(lPartMode);
                    fgPartMode.appendChild(selPartMode);
                    if (chat.type === 'channel') {
                        const chPartHint = document.createElement('div');
                        chPartHint.style.cssText = 'font-size:11.5px;color:var(--text-secondary);margin-top:5px;line-height:1.5';
                        chPartHint.textContent = 'ℹ️ ' + t('call_channel_part_hint');
                        fgPartMode.appendChild(chPartHint);
                    }
                    callGovBox.appendChild(fgPartMode);

                    const fgMaxDur = document.createElement('div');
                    fgMaxDur.className = 'form-group';
                    const lMaxDur = document.createElement('label');
                    lMaxDur.textContent = t('call_gov_max_dur_lbl');
                    const inMaxDur = document.createElement('input');
                    inMaxDur.type = 'number';
                    inMaxDur.min = '0';
                    inMaxDur.max = '1440';
                    inMaxDur.className = 'input';
                    inMaxDur.value = String(Math.round(Number(rawChatPol.max_duration_sec || 0) / 60));
                    fgMaxDur.appendChild(lMaxDur);
                    fgMaxDur.appendChild(inMaxDur);
                    callGovBox.appendChild(fgMaxDur);

                    const qSuperNote = document.createElement('div');
                    qSuperNote.style.cssText = 'font-size:11.5px;color:var(--text-muted);margin-top:4px;line-height:1.5';
                    qSuperNote.textContent = '🛡️ ' + t('call_superadmin_quality_only_note');
                    callGovBox.appendChild(qSuperNote);
                    editCard.appendChild(callGovBox);

                    // Sensitive / Maintenance Operations Card inside Group & Channel Settings
                    const csetDangerBox = document.createElement('div');
                    csetDangerBox.className = 'danger-card';
                    csetDangerBox.dataset.csetSub = 'danger';
                    csetDangerBox.style.cssText = 'margin:12px 0 0;padding:12px';
                    const cdgHead = document.createElement('div');
                    cdgHead.style.cssText = 'font-weight:800;font-size:13px;color:var(--danger);margin-bottom:6px';
                    cdgHead.textContent = t('cset_sub_danger');
                    csetDangerBox.appendChild(cdgHead);
                    const cdgBtns = document.createElement('div');
                    cdgBtns.className = 'resp-action-row';
                    if (!chat.is_ghost) {
                        const csetClearHistBtn = document.createElement('button');
                        csetClearHistBtn.type = 'button';
                        csetClearHistBtn.className = 'btn btn-secondary btn-sm';
                        csetClearHistBtn.textContent = t('clear_chat_history_btn');
                        csetClearHistBtn.addEventListener('click', async () => {
                            const canClearAll = isOwner || isSuper || canManageContent;
                            const ap = await askApproval({
                                title: t('clear_chat_history_btn'),
                                desc: `${t('clear_chat_history_desc')}\n💬 ${displayTitle}`,
                                checkboxLabel: canClearAll ? t('clear_history_for_all_members_chk') : undefined,
                                checkboxDefault: false,
                                checkboxRequired: false,
                                danger: true,
                                icon: '🧹'
                            });
                            if (!ap.approved) return;
                            const modeVal = (canClearAll && ap.checked) ? 'everyone' : 'me';
                            const cr = await apiCall('chat_clear_history', { chat_id: chat.id, mode: modeVal });
                            if (cr.ok) {
                                if (cr.data && Array.isArray(cr.data.chats)) store.chats = cr.data.chats;
                                if (store.activeChatId === chat.id) {
                                    store.messages[chat.id] = [];
                                    await selectChat(chat.id);
                                } else {
                                    renderChatList();
                                }
                                toast(t('clear_history_done_toast'));
                                close();
                            } else {
                                toast(cr.message || t('err_generic'), true);
                            }
                        });
                        cdgBtns.appendChild(csetClearHistBtn);

                        const csetResetBtn = document.createElement('button');
                        csetResetBtn.type = 'button';
                        csetResetBtn.className = 'btn btn-secondary btn-sm btn-reset-chat-settings';
                        csetResetBtn.textContent = t('chat_reset_settings_btn');
                        csetResetBtn.addEventListener('click', runRoleScopedChatReset);
                        cdgBtns.appendChild(csetResetBtn);
                    }
                    if ((isOwner || isSuper) && members.length > 1) {
                        const jumpTransferBtn = document.createElement('button');
                        jumpTransferBtn.type = 'button';
                        jumpTransferBtn.className = 'btn btn-secondary btn-sm';
                        jumpTransferBtn.textContent = t('transfer_ownership_btn');
                        jumpTransferBtn.addEventListener('click', () => {
                            currentSection = 'members';
                            body.querySelectorAll('.info-sec-tab').forEach((el, idx) => {
                                el.classList.toggle('active', idx === body.querySelectorAll('.info-sec-tab').length - 1);
                            });
                            renderSectionContent();
                        });
                        cdgBtns.appendChild(jumpTransferBtn);
                    }
                    if ((isOwner || isSuper) && chat.is_default !== 1) {
                        const delChatDangerBtn = document.createElement('button');
                        delChatDangerBtn.type = 'button';
                        delChatDangerBtn.className = 'btn btn-danger btn-sm';
                        delChatDangerBtn.textContent = '🗑️ ' + stripLeadingEmoji(t('info_quick_delete'));
                        delChatDangerBtn.addEventListener('click', async () => {
                            close();
                            await leaveOrDeleteChatAction(chat, 'delete');
                        });
                        cdgBtns.appendChild(delChatDangerBtn);
                    }
                    /* Erase the whole group/channel globally.
                       Only shown where it adds a capability the "Delete" button does
                       not already have: for a non-default space, chat_delete_conversation
                       already destroys it globally for the owner/super-admin (and the
                       confirmation now says so), so this explicit control is reserved for
                       default spaces, which the super-admin alone may erase. */
                    const canEraseGlobally = (chat.type === 'group' || chat.type === 'channel')
                        && isSuper
                        && chat.is_default === 1;
                    if (canEraseGlobally) {
                        const delChatAllBtn = document.createElement('button');
                        delChatAllBtn.type = 'button';
                        delChatAllBtn.className = 'btn btn-danger btn-sm btn-erase-chat-global';
                        const isChannel = chat.type === 'channel';
                        delChatAllBtn.textContent = '🗑️ ' + t(isChannel ? 'del_all_btn_channel' : 'del_all_btn_group');
                        delChatAllBtn.title = t('chat_delete_all_hint');
                        delChatAllBtn.addEventListener('click', async () => {
                            const memberCount = (members || []).length;
                            const ap = await askApproval({
                                title: t(isChannel ? 'del_all_title_channel' : 'del_all_title_group'),
                                desc: t(isChannel ? 'del_all_desc_channel' : 'del_all_desc_group') + '\n💬 ' + formatChatTitle(chat) + '\n👥 ' + String(memberCount),
                                danger: true,
                                icon: '🗑️'
                            });
                            if (!ap.approved) return;
                            const r = await apiCall('chat_delete', { chat_id: chat.id });
                            if (r.ok) {
                                store.chats = r.data.chats || [];
                                delete store.messages[chat.id];
                                if (store.activeChatId === chat.id) {
                                    showNoChatSelected();
                                } else {
                                    renderChatList();
                                }
                                toast(t('chat_deleted_all_toast'));
                                try { close(); } catch (e) {}
                            } else {
                                toast(r.message || t('cannot_leave_default_channel'), true);
                            }
                        });
                        cdgBtns.appendChild(delChatAllBtn);
                    }
                    csetDangerBox.appendChild(cdgBtns);
                    editCard.appendChild(csetDangerBox);

                    const stickySaveWrap = document.createElement('div');
                    stickySaveWrap.className = 'settings-sticky-save-bar';
                    const saveBtn = document.createElement('button');
                    saveBtn.type = 'button';
                    saveBtn.className = 'btn btn-primary btn-block';
                    saveBtn.textContent = t('save_changes');
                    saveBtn.addEventListener('click', async () => {
                        const updPayload = { chat_id: chat.id };
                        if (canEditInfo) {
                            Object.assign(updPayload, {
                                type: selType.value,
                                title: inTitle.value.trim(),
                                handle: selVis.value === 'private' ? '' : inHandle.value.trim(),
                                visibility: selVis.value,
                                history_vis: selHist.value,
                                max_members: Math.max(0, parseInt(inMaxMembers.value || '0', 10) || 0),
                                slow_mode: parseInt(inSlow.value || '0', 10),
                                default_ttl: parseInt(inTtl.value || '0', 10),
                                ttl_mode: selSettingsTtlMode.value,
                                auto_delete_sec: Math.max(0, parseInt(selCsetAutoDel.value || '0', 10) || 0),
                                msg_viewers_mode: selMvMode.value,
                                reactions_enabled: chkReactions.checked ? 1 : 0,
                                allow_copy_msg: chkAllowCopy.checked ? 1 : 0,
                                allow_select_text: chkAllowSelect.checked ? 1 : 0,
                                allow_file_download: chkAllowDownload.checked ? 1 : 0,
                                allow_forward_msg: chkAllowForward.checked ? 1 : 0,
                                admins_only: chkAdminsOnly.checked ? 1 : 0,
                                send_media: chkSendMedia.checked ? 1 : 0,
                                send_voice: chkSendVoice.checked ? 1 : 0,
                                join_approval: chkJoinApproval.checked ? 1 : 0,
                                hide_members: chkHideMembers.checked ? 1 : 0,
                                member_invite: chkMemberInvite.checked ? 1 : 0,
                                member_pin: chkMemberPin.checked ? 1 : 0,
                                show_admin_transfer_msg: chkShowTransferMsg.checked ? 1 : 0,
                                show_typing: selType.value === 'group' ? (chkShowTyping.checked ? 1 : 0) : 0,
                                hide_edit_badge: chkHideEditBadge.checked ? 1 : 0,
                                idle_mode: selChatIdleMode.value,
                                idle_start: inChatIdleStart.value || '23:00',
                                idle_end: inChatIdleEnd.value || '07:00',
                                idle_tz_offset: -new Date().getTimezoneOffset(),
                                description: inDesc.value.trim()
                            });
                            if (pendingChatAvDataUri !== undefined) {
                                updPayload.avatar = pendingChatAvDataUri;
                            }
                        }
                        if (isSuper && selSuperMvOverride) {
                            updPayload.super_msg_viewers_override = selSuperMvOverride.value;
                        }
                        if (isSuper && selSuperTypingOverride) {
                            updPayload.super_typing_override = selType.value === 'group' ? selSuperTypingOverride.value : 'inherit';
                        }
                        if (isSuper && inSuperMaxMembers) {
                            updPayload.super_max_members = parseInt(inSuperMaxMembers.value || '0', 10) || 0;
                        }
                        if (canManageContent) {
                            if (!canEditInfo) {
                                Object.assign(updPayload, {
                                    reactions_enabled: chkReactions.checked ? 1 : 0,
                                    allow_copy_msg: chkAllowCopy.checked ? 1 : 0,
                                    allow_select_text: chkAllowSelect.checked ? 1 : 0,
                                    allow_file_download: chkAllowDownload.checked ? 1 : 0,
                                    allow_forward_msg: chkAllowForward.checked ? 1 : 0,
                                    admins_only: chkAdminsOnly.checked ? 1 : 0,
                                    send_media: chkSendMedia.checked ? 1 : 0,
                                    send_voice: chkSendVoice.checked ? 1 : 0,
                                    show_typing: selType.value === 'group' ? (chkShowTyping.checked ? 1 : 0) : 0,
                                    hide_edit_badge: chkHideEditBadge.checked ? 1 : 0
                                });
                            }
                            const nextBlockedTypes = [];
                            ALL_CTYPES.forEach(ct => {
                                const item = ctCheckboxes[ct];
                                if (item && item.chk.checked && !(item.lockedBySuper && !curChatBlockedSet.has(ct) && !isSuper)) {
                                    nextBlockedTypes.push(ct);
                                }
                            });
                            updPayload.restricted_content_types = nextBlockedTypes;
                        }
                        if (canManageCalls) {
                            updPayload.call_policy = {
                                voice_enabled: cgVoice.c.checked ? 1 : 0,
                                video_enabled: cgVideo.c.checked ? 1 : 0,
                                starter_mode: selWho.value,
                                participation_mode: selPartMode.value,
                                allowed_admin_ids: specAdminChecks.filter(x => x.chk.checked).map(x => x.id),
                                max_duration_sec: Math.max(0, Math.min(86400, (parseInt(inMaxDur.value || '0', 10) || 0) * 60))
                            };
                        }
                        const r = await apiCall('chat_update', updPayload);
                        if (r.ok) {
                            const lRes = await apiCall('chats_list');
                            if (lRes.ok) store.chats = lRes.data.chats;
                            renderChatList();
                            renderActiveChatHeader();
                            await selectChat(chat.id);
                            toast(`${t('chat_settings_saved_toast')} (${inTitle.value.trim() || formatChatTitle(chat)})`);
                            close();
                        } else {
                            toast(r.message || t('err_generic'), true);
                        }
                    });
                    stickySaveWrap.appendChild(saveBtn);
                    editCard.appendChild(stickySaveWrap);
                }
                secContainer.appendChild(editCard);
                return;
            }

            if (currentSection === 'members' && isGroupOrChannel) {
                if (canInvite && !chat.is_ghost) {
                    const addMemCard = document.createElement('div');
                    addMemCard.className = 'card-box';
                    const amHead = document.createElement('div');
                    amHead.className = 'section-header';
                    amHead.textContent = t('add_member_section');
                    addMemCard.appendChild(amHead);

                    const amRow = document.createElement('div');
                    amRow.className = 'resp-action-row';
                    const amInput = document.createElement('input');
                    amInput.className = 'input';
                    amInput.style.flex = '1';
                    amInput.placeholder = t('add_member_input_ph');
                    amInput.dir = 'ltr';
                    const amBtn = document.createElement('button');
                    amBtn.type = 'button';
                    amBtn.className = 'btn btn-primary btn-sm';
                    amBtn.textContent = t('add_member_btn');
                    const doAddMember = async () => {
                        const rawTarget = amInput.value.trim();
                        if (!rawTarget) {
                            amInput.focus();
                            return;
                        }
                        amBtn.disabled = true;
                        const payload = /^\d+$/.test(rawTarget)
                            ? { chat_id: chat.id, user_id: parseInt(rawTarget, 10) }
                            : { chat_id: chat.id, username: rawTarget.replace(/^@+/, '') };
                        const mr = await apiCall('member_add', payload);
                        amBtn.disabled = false;
                        if (mr.ok) {
                            if (mr.data && Array.isArray(mr.data.chats)) {
                                store.chats = mr.data.chats;
                                renderChatList();
                                renderActiveChatHeader();
                            }
                            toast(t('member_added_toast') + rawTarget);
                            openChatInfoModal('members');
                        } else {
                            toast(mr.message || t('err_generic'), true);
                        }
                    };
                    amBtn.addEventListener('click', doAddMember);
                    amInput.addEventListener('keydown', ev => {
                        if (ev.key === 'Enter') {
                            ev.preventDefault();
                            doAddMember();
                        }
                    });
                    amRow.appendChild(amInput);
                    amRow.appendChild(amBtn);
                    addMemCard.appendChild(amRow);
                    secContainer.appendChild(addMemCard);
                }

                if (canRevokeInvites && pendingRequests.length > 0) {
                    const reqCard = document.createElement('div');
                    reqCard.className = 'card-box';
                    const rqHead = document.createElement('div');
                    rqHead.className = 'section-header';
                    rqHead.textContent = `${t('pending_join_requests_sec')} (${pendingRequests.length})`;
                    reqCard.appendChild(rqHead);

                    pendingRequests.forEach(req => {
                        const rRow = document.createElement('div');
                        rRow.className = 'adm-item-card';
                        rRow.style.marginBottom = '8px';
                        const rTop = document.createElement('div');
                        rTop.className = 'adm-item-top';

                        const rLeft = document.createElement('div');
                        rLeft.style.cssText = 'display:flex;align-items:center;gap:8px;min-width:0;flex:1';
                        const rAv = document.createElement('div');
                        rAv.className = 'avatar avatar-sm';
                        renderAvatarNode(rAv, req.name, req.avatar);
                        const rInf = document.createElement('div');
                        rInf.style.minWidth = '0';
                        const rNm = document.createElement('div');
                        rNm.style.cssText = 'font-weight:700;font-size:13.5px';
                        rNm.textContent = req.name;
                        const rUn = document.createElement('div');
                        rUn.style.cssText = 'font-size:11.5px;color:var(--text-muted)';
                        rUn.textContent = formatHandleLabel(req);
                        rInf.appendChild(rNm);
                        rInf.appendChild(rUn);
                        rLeft.appendChild(rAv);
                        rLeft.appendChild(rInf);

                        const rAct = document.createElement('div');
                        rAct.style.cssText = 'display:flex;gap:6px;flex-wrap:wrap';
                        const appBtn = document.createElement('button');
                        appBtn.type = 'button';
                        appBtn.className = 'btn btn-primary btn-sm';
                        appBtn.textContent = t('approve_join_btn');
                        appBtn.addEventListener('click', async () => {
                            const dr = await apiCall('join_requests_decide', { chat_id: chat.id, user_id: req.user_id, approve: 1, decision: 'approve' });
                            if (dr.ok) {
                                toast(t('join_approved_toast') + formatHandleLabel(req));
                                const cRes = await apiCall('chats_list');
                                if (cRes.ok) { store.chats = cRes.data.chats; renderChatList(); renderActiveChatHeader(); }
                                openChatInfoModal('members');
                            } else {
                                toast(dr.message || t('err_generic'), true);
                            }
                        });
                        const rejBtn = document.createElement('button');
                        rejBtn.type = 'button';
                        rejBtn.className = 'btn btn-danger btn-sm';
                        rejBtn.textContent = t('reject_join_btn');
                        rejBtn.addEventListener('click', async () => {
                            const dr = await apiCall('join_requests_decide', { chat_id: chat.id, user_id: req.user_id, approve: 0, decision: 'reject' });
                            if (dr.ok) {
                                toast(t('join_rejected_toast') + formatHandleLabel(req));
                                openChatInfoModal('members');
                            } else {
                                toast(dr.message || t('err_generic'), true);
                            }
                        });
                        rAct.appendChild(appBtn);
                        rAct.appendChild(rejBtn);
                        rTop.appendChild(rLeft);
                        rTop.appendChild(rAct);
                        rRow.appendChild(rTop);
                        reqCard.appendChild(rRow);
                    });
                    secContainer.appendChild(reqCard);
                }

                if (canManageAdmins) {
                    const addAdmCard = document.createElement('div');
                    addAdmCard.className = 'card-box';
                    const aaHead = document.createElement('div');
                    aaHead.className = 'section-header';
                    aaHead.textContent = t('add_admin_section');
                    addAdmCard.appendChild(aaHead);

                    const aaRow = document.createElement('div');
                    aaRow.className = 'resp-action-row';
                    const aaInput = document.createElement('input');
                    aaInput.className = 'input';
                    aaInput.style.flex = '1';
                    aaInput.placeholder = t('add_admin_input_ph');
                    aaInput.dir = 'ltr';

                    const aaBtn = document.createElement('button');
                    aaBtn.type = 'button';
                    aaBtn.className = 'btn btn-primary btn-sm';
                    aaBtn.textContent = t('add_admin_open_btn');
                    aaBtn.addEventListener('click', () => {
                        const uname = aaInput.value.trim().replace(/^@/, '');
                        if (!uname) {
                            toast(t('username'), true);
                            aaInput.focus();
                            return;
                        }
                        const existingMem = members.find(m => (m.username || '').toLowerCase() === uname.toLowerCase());
                        close();
                        openAdminPrivilegesModal(chat, existingMem || { username: uname, defaultRole: 'admin' });
                    });
                    aaRow.appendChild(aaInput);
                    aaRow.appendChild(aaBtn);
                    addAdmCard.appendChild(aaRow);
                    secContainer.appendChild(addAdmCard);
                }

                const memCard = document.createElement('div');
                memCard.className = 'card-box';
                const mTitle = document.createElement('div');
                mTitle.className = 'section-header';
                const activeCountOnly = members.filter(mx => !mx.is_banned).length;
                mTitle.textContent = `${t('members_list_header')} (${formatLocalizedCount(activeCountOnly)})`;
                memCard.appendChild(mTitle);

                // Member Search & Role/Ban Filter Toolbar
                const modToolbar = document.createElement('div');
                modToolbar.className = 'member-mod-toolbar';
                const memSearchIn = document.createElement('input');
                memSearchIn.className = 'input';
                memSearchIn.placeholder = t('mem_search_ph');
                modToolbar.appendChild(memSearchIn);

                const memRolePills = document.createElement('div');
                memRolePills.className = 'settings-sub-pills';
                memRolePills.style.margin = '0';
                let activeMemFilter = 'all';
                const bannedCount = members.filter(mx => !!mx.is_banned).length;
                const shadowCount = members.filter(mx => !!mx.shadow_banned).length;
                const adminCount = members.filter(mx => !mx.is_banned && (mx.chat_role === 'owner' || mx.chat_role === 'admin')).length;
                const memFilterDefs = [
                    ['all', `${t('mem_filter_all')} (${formatLocalizedCount(activeCountOnly)})`],
                    ['admins', `${t('mem_filter_admins')} (${formatLocalizedCount(adminCount)})`]
                ];
                if (canBanUsers && bannedCount > 0) {
                    memFilterDefs.push(['banned', `${t('mem_filter_banned')} (${formatLocalizedCount(bannedCount)})`]);
                }
                if (shadowCount > 0) {
                    memFilterDefs.push(['shadow', `${t('mem_filter_shadow')} (${formatLocalizedCount(shadowCount)})`]);
                }
                const memRowsWrap = document.createElement('div');
                const applyMemFilter = () => {
                    const q = memSearchIn.value.trim().toLowerCase().replace(/^@+/, '');
                    memRowsWrap.querySelectorAll('[data-mem-row]').forEach(rowEl => {
                        const rRole = rowEl.dataset.memRole || 'member';
                        const rBanned = rowEl.dataset.memBanned === '1';
                        const rShadow = rowEl.dataset.memShadow === '1';
                        const rSearch = rowEl.dataset.memSearch || '';
                        let roleOk = true;
                        if (activeMemFilter === 'all') roleOk = !rBanned;
                        else if (activeMemFilter === 'admins') roleOk = !rBanned && (rRole === 'owner' || rRole === 'admin');
                        else if (activeMemFilter === 'banned') roleOk = rBanned;
                        else if (activeMemFilter === 'shadow') roleOk = rShadow;
                        const qOk = !q || rSearch.includes(q);
                        rowEl.classList.toggle('hidden', !(roleOk && qOk));
                    });
                };
                memFilterDefs.forEach(([fk, fl]) => {
                    const fp = document.createElement('button');
                    fp.type = 'button';
                    fp.className = 'settings-sub-pill' + (fk === activeMemFilter ? ' active' : '');
                    fp.textContent = fl;
                    fp.addEventListener('click', () => {
                        activeMemFilter = fk;
                        memRolePills.querySelectorAll('.settings-sub-pill').forEach(x => x.classList.remove('active'));
                        fp.classList.add('active');
                        applyMemFilter();
                    });
                    memRolePills.appendChild(fp);
                });
                memSearchIn.addEventListener('input', applyMemFilter);
                modToolbar.appendChild(memRolePills);
                memCard.appendChild(modToolbar);
                memCard.appendChild(memRowsWrap);

                members.forEach(m => {
                    const isMemBanned = Boolean(m.is_banned || (m.banned_until && Number(m.banned_until) > Math.floor(Date.now() / 1000)));
                    const isMemShadow = Number(m.shadow_banned) === 1;
                    const isMe = !!(store.user && Number(m.id) === Number(store.user.id));
                    const targetRank = Number(m.rank || 0);

                    const row = document.createElement('div');
                    row.className = 'adm-item-card mem-card';
                    row.dataset.memRow = '1';
                    row.dataset.memRole = m.chat_role || 'member';
                    row.dataset.memBanned = isMemBanned ? '1' : '0';
                    row.dataset.memShadow = isMemShadow ? '1' : '0';
                    row.dataset.memSearch = `${m.name || ''} ${m.username || ''} ${m.id || ''}`.toLowerCase();

                    /* ---- zone 1: identity. Tapping it opens the profile, which is
                            what the old header promised but the crowded layout hid. ---- */
                    const idRow = document.createElement('div');
                    idRow.className = 'mem-identity';
                    idRow.title = t('members_list_header');
                    idRow.addEventListener('click', () => {
                        close();
                        openUserMiniProfile(m.id);
                    });

                    const av = document.createElement('div');
                    av.className = 'avatar avatar-sm';
                    renderAvatarNode(av, m.name, m.avatar);
                    idRow.appendChild(av);

                    const info = document.createElement('div');
                    info.className = 'mem-identity-text';

                    const nLine = document.createElement('div');
                    nLine.className = 'mem-name-line';
                    const ns = document.createElement('span');
                    ns.className = 'mem-name';
                    ns.textContent = m.name;
                    nLine.appendChild(ns);
                    if (m.has_admin_badge) nLine.appendChild(createAdminBadgeNode());

                    if (isMemBanned) {
                        const banChip = document.createElement('span');
                        banChip.className = 'status-chip-banned';
                        banChip.textContent = t('mem_banned_badge');
                        nLine.appendChild(banChip);
                    } else {
                        const roleBadge = document.createElement('span');
                        roleBadge.className = 'adm-badge-pill ' + (m.chat_role === 'owner' ? 'primary' : (m.chat_role === 'admin' ? 'success' : ''));
                        roleBadge.textContent = m.chat_role === 'owner' ? t('role_owner') : (m.chat_role === 'admin' ? t('role_admin') : t('role_member'));
                        nLine.appendChild(roleBadge);
                    }
                    // A banned member already has no voice, so the shadow chip would
                    // just repeat it; only show it when it says something extra.
                    if (isMemShadow && !isMemBanned) {
                        const shadowChip = document.createElement('span');
                        shadowChip.className = 'status-chip-shadow';
                        shadowChip.textContent = t('mem_shadow_badge');
                        nLine.appendChild(shadowChip);
                    }

                    const uLine = document.createElement('div');
                    uLine.className = 'mem-handle';
                    uLine.textContent = formatHandleLabel(m);
                    info.appendChild(nLine);
                    info.appendChild(uLine);
                    idRow.appendChild(info);
                    row.appendChild(idRow);

                    /* ---- zone 2: actions, on their own row so they can never
                            collide with the name, the badges or each other. ---- */
                    const canEditTargetRole = !isMemBanned
                        && m.chat_role !== 'owner'
                        && !(m.is_superadmin && !isSuper)
                        && (isSuper || isOwner || (store.user && m.id !== store.user.id))
                        && (m.chat_role === 'admin' ? canControlOtherAdmins : canManageAdmins);

                    // Strict ladder: a rank may only shadow-ban ranks below itself.
                    const canShadowTarget = !isMe && !isMemBanned && myRank >= 1 && myRank > targetRank;

                    const actRow = document.createElement('div');
                    actRow.className = 'mem-actions';

                    const makeActBtn = (label, cls, onClick) => {
                        const b = document.createElement('button');
                        b.type = 'button';
                        b.className = 'btn btn-sm ' + cls;
                        b.textContent = label;
                        b.addEventListener('click', e => { e.stopPropagation(); onClick(); });
                        return b;
                    };

                    if (canEditTargetRole) {
                        actRow.appendChild(makeActBtn(t('manage_admin_btn'), 'btn-secondary', () => {
                            close();
                            openAdminPrivilegesModal(chat, m);
                        }));
                    }

                    if (canShadowTarget) {
                        actRow.appendChild(makeActBtn(
                            isMemShadow ? t('shadow_unban_btn') : t('shadow_ban_btn'),
                            isMemShadow ? 'btn-primary' : 'btn-secondary',
                            async () => {
                                if (isMemShadow) {
                                    const rr = await apiCall('chat_member_mod', { chat_id: chat.id, user_id: m.id, mod_action: 'unshadowban' });
                                    if (rr.ok) {
                                        toast(t('shadow_unbanned_toast') + formatHandleLabel(m));
                                        openChatInfoModal('members');
                                    } else {
                                        toast(rr.message || t('err_generic'), true);
                                    }
                                    return;
                                }
                                const ap = await askApproval({
                                    title: t('shadow_ban_title'),
                                    desc: `${t('shadow_ban_desc')}\n\n👤 ${m.name} (${formatHandleLabel(m)})`,
                                    checkboxLabel: t('shadow_ban_chk'),
                                    checkboxRequired: true,
                                    danger: true,
                                    icon: '🌒'
                                });
                                if (!ap.approved) return;
                                const rr = await apiCall('chat_member_mod', { chat_id: chat.id, user_id: m.id, mod_action: 'shadowban' });
                                if (rr.ok) {
                                    toast(t('shadow_banned_toast') + formatHandleLabel(m));
                                    openChatInfoModal('members');
                                } else if (rr.error === 'shadow_rank_denied') {
                                    toast(t('shadow_rank_denied_msg'), true);
                                } else {
                                    toast(rr.message || t('err_generic'), true);
                                }
                            }
                        ));
                    }

                    // The two restriction toggles are the ones an admin reaches
                    // for most, so they sit up front with the other row actions
                    // instead of hiding behind the kebab.
                    const canRestrictTarget = !isMemBanned
                        && chat.type === 'group'
                        && canBanUsers
                        && store.user
                        && m.id !== store.user.id
                        && m.chat_role === 'member';

                    if (canRestrictTarget) {
                        [['mute_send', 'mem_restrict_send'], ['mute_react', 'mem_restrict_react']].forEach(([fieldKey, labelKey]) => {
                            const on = Number(m[fieldKey]) === 1;
                            const rb = makeActBtn(t(labelKey), on ? 'btn-primary' : 'btn-secondary', async () => {
                                const payload = { chat_id: chat.id, user_id: m.id };
                                payload[fieldKey] = on ? 0 : 1;
                                const mr = await apiCall('member_restrict', payload);
                                if (mr.ok) {
                                    toast(t('mem_restrict_saved_toast') + m.name);
                                    openChatInfoModal('members');
                                } else {
                                    toast(mr.message || t('err_generic'), true);
                                }
                            });
                            // the filled style carries the on/off state, so the
                            // label stays a clean single line
                            rb.setAttribute('aria-pressed', on ? 'true' : 'false');
                            rb.title = t(labelKey);
                            actRow.appendChild(rb);
                        });
                    }

                    /* ---- the rest lives behind one kebab, so a row never grows
                            into a wall of buttons on a phone. ---- */
                    const overflowItems = [];
                    const canModerateTarget = canBanUsers
                        && store.user
                        && m.id !== store.user.id
                        && m.chat_role !== 'owner'
                        && !(m.is_superadmin && !isSuper)
                        && (m.chat_role === 'admin' ? canControlOtherAdmins : true);

                    if (!isMemBanned && (isOwner || isSuper) && m.chat_role !== 'owner' && Number(m.id) !== Number(chat.owner_id)) {
                        overflowItems.push({
                            ico: '👑',
                            label: t('transfer_ownership_btn'),
                            danger: true,
                            run: async () => {
                                const ap = await askApproval({
                                    title: t('transfer_ownership_title'),
                                    desc: `${t('transfer_ownership_desc')}\n👑 ${m.name} (${formatHandleLabel(m)})`,
                                    checkboxLabel: t('transfer_ownership_chk'),
                                    checkboxRequired: true,
                                    input: isSuper ? null : { label: t('current_password_lbl'), type: 'password', dir: 'ltr' },
                                    danger: true,
                                    icon: '👑'
                                });
                                if (!ap.approved) return;
                                if (!isSuper && !ap.value) {
                                    toast(t('current_password_lbl'), true);
                                    return;
                                }
                                const tr = await apiCall('chat_transfer_ownership', {
                                    chat_id: chat.id,
                                    target_user_id: m.id,
                                    current_password: ap.value || ''
                                });
                                if (tr.ok) {
                                    if (tr.data && Array.isArray(tr.data.chats)) store.chats = tr.data.chats;
                                    renderChatList();
                                    renderActiveChatHeader();
                                    await selectChat(chat.id);
                                    toast(t('transfer_ownership_done_toast') + m.name);
                                    close();
                                } else {
                                    toast(tr.message || t('err_generic'), true);
                                }
                            }
                        });
                    }

                    if (canModerateTarget) {
                        if (isMemBanned) {
                            overflowItems.push({
                                ico: '♻️',
                                label: t('unban_member_btn'),
                                run: async () => {
                                    const ubr = await apiCall('chat_member_mod', { chat_id: chat.id, user_id: m.id, mod_action: 'unban' });
                                    if (ubr.ok) {
                                        toast(`${t('member_unbanned_toast')}${formatHandleLabel(m)}`);
                                        openChatInfoModal('members');
                                    } else {
                                        toast(ubr.message || t('err_generic'), true);
                                    }
                                }
                            });
                        } else {
                            overflowItems.push({
                                ico: '⛔',
                                label: t('ban_member_btn'),
                                danger: true,
                                run: async () => {
                                    const ap = await askApproval({
                                        title: t('ban_member_btn'),
                                        desc: `${t('ask_ban_member')}\n👤 ${m.name} (${formatHandleLabel(m)})`,
                                        danger: true,
                                        icon: '⛔'
                                    });
                                    if (!ap.approved) return;
                                    const br = await apiCall('chat_member_mod', { chat_id: chat.id, user_id: m.id, mod_action: 'ban' });
                                    if (br.ok) {
                                        toast(`${t('member_banned_toast')}${formatHandleLabel(m)}`);
                                        openChatInfoModal('members');
                                    } else {
                                        toast(br.message || t('err_generic'), true);
                                    }
                                }
                            });
                        }

                        overflowItems.push({
                            ico: '🚫',
                            label: t('kick_btn'),
                            danger: true,
                            run: async () => {
                                const ap = await askApproval({
                                    title: t('kick_btn'),
                                    desc: `${t('ask_kick_member')}\n👤 ${m.name} (${formatHandleLabel(m)})`,
                                    danger: true,
                                    icon: '🚫'
                                });
                                if (!ap.approved) return;
                                const kr = await apiCall('chat_member_mod', { chat_id: chat.id, user_id: m.id, mod_action: 'kick' });
                                if (kr.ok) {
                                    toast(`${t('member_kicked_toast')}${formatHandleLabel(m)}`);
                                    openChatInfoModal('members');
                                } else {
                                    toast(kr.message || t('err_generic'), true);
                                }
                            }
                        });
                    }

                    if (overflowItems.length > 0) {
                        actRow.appendChild(makeActBtn(t('mem_actions_more_btn'), 'btn-secondary mem-more-btn', () => {
                            // A sub-modal, not the main one: dismissing the menu must
                            // return to the member list instead of closing the whole
                            // chat-info dialog the user came from.
                            openSubModal(t('mem_actions_title'), (mBody, mClose) => {
                                const head = document.createElement('div');
                                head.className = 'mem-overflow-head';
                                const hAv = document.createElement('div');
                                hAv.className = 'avatar avatar-sm';
                                renderAvatarNode(hAv, m.name, m.avatar);
                                head.appendChild(hAv);
                                const hName = document.createElement('div');
                                hName.style.cssText = 'font-weight:800;font-size:13.5px';
                                hName.textContent = m.name;
                                head.appendChild(hName);
                                mBody.appendChild(head);

                                overflowItems.forEach(item => {
                                    const it = document.createElement('button');
                                    it.type = 'button';
                                    it.className = 'msg-mini-item';
                                    if (item.danger) {
                                        it.style.color = 'var(--danger)';
                                    }
                                    const ic = document.createElement('span');
                                    ic.className = 'mmi-ico';
                                    ic.textContent = item.ico;
                                    // Several labels already lead with the same
                                    // pictograph as the icon; showing both
                                    // repeats it side by side.
                                    let lblTxt = String(item.label || '');
                                    if (item.ico && lblTxt.indexOf(String(item.ico)) === 0) {
                                        lblTxt = lblTxt.slice(String(item.ico).length).replace(/^\s+/, '');
                                    }
                                    const tx = document.createElement('span');
                                    tx.textContent = lblTxt;
                                    it.appendChild(ic);
                                    it.appendChild(tx);
                                    it.addEventListener('click', async () => {
                                        mClose();
                                        await item.run();
                                    });
                                    mBody.appendChild(it);
                                });
                            });
                        }));
                    }

                    if (actRow.children.length > 0) {
                        row.appendChild(actRow);
                    }

                    memRowsWrap.appendChild(row);
                });
                applyMemFilter();
                secContainer.appendChild(memCard);
            }
        };

        await renderSectionContent();
    });
}

/* ---------------- NEW CHAT / GROUP / CHANNEL / JOIN MODAL ---------------- */
function openNewChatModal() {
    openModal('➕ ' + t('new_chat'), (body, close) => {
        const dmCard = document.createElement('div');
        dmCard.className = 'card-box';
        const dmTitle = document.createElement('div');
        dmTitle.className = 'section-header';
        dmTitle.textContent = t('nc_dm_section');
        dmCard.appendChild(dmTitle);

        const dmInput = document.createElement('input');
        dmInput.className = 'input';
        dmInput.placeholder = '@username';
        dmInput.dir = 'ltr';
        dmInput.style.marginBottom = '10px';
        dmCard.appendChild(dmInput);

        const dmBtns = document.createElement('div');
        dmBtns.className = 'resp-action-row';
        const btnOpenDm = document.createElement('button');
        btnOpenDm.className = 'btn btn-primary btn-sm';
        btnOpenDm.textContent = t('nc_open_dm');
        btnOpenDm.addEventListener('click', async () => {
            const u = dmInput.value.trim();
