        if (store.user && store.user.role !== 'superadmin') {
            const gUsed = Number(store.user.created_groups_count || 0);
            const cUsed = Number(store.user.created_channels_count || 0);
            const gMaxRaw = Number(store.user.effective_max_created_groups ?? (store.settings && store.settings.max_user_created_groups) ?? 10);
            const cMaxRaw = Number(store.user.effective_max_created_channels ?? (store.settings && store.settings.max_user_created_channels) ?? 10);
            const gMaxLbl = gMaxRaw <= 0 ? t('nc_quota_unlimited') : formatLocalizedCount(gMaxRaw);
