        [['public', t('nc_vis_public')], ['private', t('nc_vis_private')]].forEach(([v, l]) => {
            const o = document.createElement('option');
            o.value = v;
            o.textContent = l;
            selVis.appendChild(o);
        });
        fgVis.appendChild(lblVis);
        fgVis.appendChild(selVis);
        crGrid.appendChild(fgVis);

        const fgName = document.createElement('div');
        fgName.className = 'form-group';
        const lblName = document.createElement('label');
        lblName.textContent = t('nc_title_label');
        const inName = document.createElement('input');
        inName.className = 'input';
        fgName.appendChild(lblName);
        fgName.appendChild(inName);
        crGrid.appendChild(fgName);

        const fgHnd = document.createElement('div');
        fgHnd.className = 'form-group';
        const lblHnd = document.createElement('label');
        lblHnd.textContent = t('nc_handle_label');
        const inHnd = document.createElement('input');
        inHnd.className = 'input';
        inHnd.placeholder = '@my_group';
        inHnd.dir = 'ltr';
        fgHnd.appendChild(lblHnd);
        fgHnd.appendChild(inHnd);
        crGrid.appendChild(fgHnd);

        crCard.appendChild(crGrid);

        const ncPrivHint = document.createElement('div');
        ncPrivHint.className = 'hidden';
        ncPrivHint.style.cssText = 'font-size:11.5px;color:var(--text-muted);margin:0 0 10px';
        ncPrivHint.textContent = t('private_handle_hint');
        crCard.appendChild(ncPrivHint);

        const syncNewChatVis = () => {
            const isPriv = selVis.value === 'private';
            fgHnd.classList.toggle('hidden', isPriv);
            ncPrivHint.classList.toggle('hidden', !isPriv);
