        };
        selVis.addEventListener('change', syncNewChatVis);
        syncNewChatVis();

        const fgHist = document.createElement('div');
        fgHist.className = 'form-group';
        const lblHist = document.createElement('label');
        lblHist.textContent = t('nc_hist_label');
        const selHist = document.createElement('select');
        selHist.className = 'input';
        [['all', t('nc_hist_all')], ['from_join', t('nc_hist_join')]].forEach(([v, l]) => {
            const o = document.createElement('option');
            o.value = v;
            o.textContent = l;
            selHist.appendChild(o);
        });
        fgHist.appendChild(lblHist);
        fgHist.appendChild(selHist);
        crCard.appendChild(fgHist);

        const fgDesc = document.createElement('div');
        fgDesc.className = 'form-group';
        const lblDesc = document.createElement('label');
        lblDesc.textContent = t('nc_desc_label');
        const inDesc = document.createElement('input');
        inDesc.className = 'input';
        fgDesc.appendChild(lblDesc);
        fgDesc.appendChild(inDesc);
        crCard.appendChild(fgDesc);

        let newChatAvatarDataUri = '';
        const avRow = document.createElement('div');
        avRow.style.cssText = 'display:flex;align-items:center;gap:10px;margin-bottom:12px;flex-wrap:wrap';
        const avPrev = document.createElement('div');
        avPrev.className = 'avatar avatar-sm';
        renderAvatarNode(avPrev, 'G', '');
        const avFileIn = document.createElement('input');
        avFileIn.type = 'file';
        avFileIn.accept = 'image/*';
        avFileIn.className = 'hidden';
        const avPickBtn = document.createElement('button');
        avPickBtn.type = 'button';
        avPickBtn.className = 'btn btn-secondary btn-sm';
        avPickBtn.textContent = t('group_avatar_btn');
        const avClearBtn = document.createElement('button');
        avClearBtn.type = 'button';
        avClearBtn.className = 'btn btn-secondary btn-sm hidden';
        avClearBtn.textContent = '✖ ' + t('group_avatar_remove_btn');
        avPickBtn.addEventListener('click', () => avFileIn.click());
        avFileIn.addEventListener('change', async () => {
            if (!avFileIn.files || !avFileIn.files[0]) return;
            try {
                newChatAvatarDataUri = await resizeImageFileToAvatarDataUri(avFileIn.files[0]);
                renderAvatarNode(avPrev, inName.value.trim() || 'G', newChatAvatarDataUri);
                avClearBtn.classList.remove('hidden');
                toast(t('avatar_ready_toast'));
            } catch (e) {
                toast(t('err_generic'), true);
            }
        });
        avClearBtn.addEventListener('click', () => {
            newChatAvatarDataUri = '';
            avFileIn.value = '';
            renderAvatarNode(avPrev, inName.value.trim() || 'G', '');
            avClearBtn.classList.add('hidden');
        });
        avRow.appendChild(avPrev);
        avRow.appendChild(avPickBtn);
        avRow.appendChild(avClearBtn);
        avRow.appendChild(avFileIn);
        crCard.appendChild(avRow);

        const crBtn = document.createElement('button');
        crBtn.className = 'btn btn-primary btn-block';
        crBtn.textContent = t('nc_create_btn');
        crBtn.addEventListener('click', async () => {
            const title = inName.value.trim();
            if (!title) {
                toast(t('nc_title_label'), true);
                return;
            }
            const r = await apiCall('chat_create', {
                type: selType.value,
                title,
                handle: inHnd.value.trim(),
                visibility: selVis.value,
                history_vis: selHist.value,
                description: inDesc.value.trim(),
                avatar: newChatAvatarDataUri
            });
            if (r.ok) {
                store.chats = r.data.chats;
                if (store.user) {
                    if (selType.value === 'channel') {
                        store.user.created_channels_count = Number(store.user.created_channels_count || 0) + 1;
                    } else {
                        store.user.created_groups_count = Number(store.user.created_groups_count || 0) + 1;
                    }
                }
                close();
                await selectChat(r.data.chat_id);
            } else {
                toast(r.message || t('err_generic'), true);
            }
        });
        crCard.appendChild(crBtn);
        body.appendChild(crCard);
    });
}

/* ---------------- SETTINGS, PRIVACY, ADMIN BADGE, 2FA, SESSIONS & ACCOUNT DELETION ---------------- */
/* ---------------- SHARED SIGN-OUT FLOW (Sidebar Header + User Settings) ----------------
 * Single source of truth for logging out: asks for confirmation, flushes drafts,
 * tears down every live sub-system (player, calls, drafts, E2EE caches) and
 * returns to the auth screen. `afterConfirm` runs right after the user confirms,
 * so callers can close their own modal/drawer before the UI swaps.
 */
async function performLogoutFlow(afterConfirm) {
    const ap = await askApproval({
        title: t('logout_btn'),
        desc: t('ask_logout'),
        danger: true,
        icon: '🚪'
    });
    if (!ap.approved) return false;
    if (typeof afterConfirm === 'function') {
        try { afterConfirm(); } catch (e) {}
    }
    try { await DraftSyncManager.flushBeforeSessionExit(); } catch (e) {}
    const outRes = await apiCall('logout');
    if (UniversalPlayer.isOpen) UniversalPlayer.close(false);
    if (typeof LiveCallManager !== 'undefined') LiveCallManager.cleanupSessionLocally();
    DraftSyncManager.resetLocalStateOnLogout();
    E2EE.clearDerivedCaches();
    store.user = null;
    store.chats = [];
    store.activeChatId = null;
    clearAllAuthFormsCompletely(true);
    const shellEl = document.getElementById('messenger-shell');
    const authEl = document.getElementById('auth-screen');
    if (shellEl) shellEl.classList.add('hidden');
    if (authEl) authEl.classList.remove('hidden');
    clearAllAuthFormsCompletely(true);
    document.title = formatSiteName();
    // Whatever the super-admin forces for everybody has to stand in front of the
    // login screen again the instant the account is closed - here and now, with
    // no reload in between, or signing out would be a way around it.
    const outData = (outRes && outRes.data) ? outRes.data : null;
    if (outData) {
        if (Number(outData.preauth_decoy) === 1) {
            // The decoy needs no session, so it is the same barrier a fresh
            // visitor gets. With nobody signed in it runs in pre-login mode.
            if (typeof showDecoyScreen === 'function') showDecoyScreen();
        } else if (Number(outData.preauth_lock) === 1) {
            store.lockPreauth = true;
            if (typeof showMessengerLockScreen === 'function') showMessengerLockScreen();
        }
    }
    return true;
}

function openSettingsModal() {
    if (!store.user) return;
    openModal('⚙️ ' + t('settings'), (body, close) => {
        const u = store.user;

        const refCard = document.createElement('div');
        refCard.className = 'card-box';
        refCard.dataset.usetOrder = '20';
        const refCardHead = document.createElement('div');
        refCardHead.className = 'section-header';
        refCardHead.textContent = t('uset_quick_access_sec');
        refCard.appendChild(refCardHead);
        refCard.style.cssText = 'display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px';
        const refLeft = document.createElement('div');
        const refLbl = document.createElement('div');
        refLbl.style.cssText = 'font-size:12px;color:var(--text-muted)';
        refLbl.textContent = t('my_invite_code_label');
        const refValRow = document.createElement('div');
        refValRow.style.cssText = 'display:flex;align-items:center;gap:8px;margin-top:4px';
        const refCodeSpan = document.createElement('span');
        refCodeSpan.style.cssText = 'font-weight:800;font-size:15px;font-family:monospace;color:var(--primary)';
        refCodeSpan.textContent = u.invite_code;
        const copyCodeBtn = document.createElement('button');
        copyCodeBtn.className = 'btn btn-secondary btn-sm';
        copyCodeBtn.textContent = '📋 ' + t('copy_btn');
        copyCodeBtn.addEventListener('click', () => {
            if (navigator.clipboard) navigator.clipboard.writeText(u.invite_code);
            toast(t('copied_toast'));
        });
        refValRow.appendChild(refCodeSpan);
        refValRow.appendChild(copyCodeBtn);
        refLeft.appendChild(refLbl);
        refLeft.appendChild(refValRow);
        refCard.appendChild(refLeft);

        const refBtns = document.createElement('div');
        refBtns.className = 'resp-action-row';
        const outBtn = document.createElement('button');
        outBtn.className = 'btn btn-danger btn-sm';
        outBtn.textContent = t('logout_btn');
        outBtn.addEventListener('click', () => {
            performLogoutFlow(() => close());
        });
        const myFilesBtn = document.createElement('button');
        myFilesBtn.type = 'button';
        myFilesBtn.className = 'btn btn-primary btn-sm';
        myFilesBtn.textContent = t('my_files_btn');
        myFilesBtn.addEventListener('click', () => {
            close();
            openMyUploadedFilesModal(0);
        });
        refBtns.appendChild(myFilesBtn);
        refBtns.appendChild(outBtn);
        refCard.appendChild(refBtns);
        refCard.dataset.usetCat = 'profile';

        // Item #22: Live Search Input for User Settings
        const usetSearchWrap = document.createElement('div');
        usetSearchWrap.className = 'settings-live-search-wrap';
        const usetSearchIn = document.createElement('input');
        usetSearchIn.type = 'search';
        usetSearchIn.id = 'user-settings-search-input';
        usetSearchIn.className = 'input';
        usetSearchIn.placeholder = t('settings_search_ph');
        usetSearchWrap.appendChild(usetSearchIn);
        const usetEmptyMsg = document.createElement('div');
        usetEmptyMsg.className = 'settings-search-empty hidden';
        usetEmptyMsg.textContent = t('settings_search_empty');

        // Clean User Settings Quick-Category Filter Tabs (Matching Admin Panel .adm-nav-pills / .adm-nav-btn)
        const usetTabs = document.createElement('div');
        usetTabs.className = 'adm-nav-pills';
        let activeUsetCat = 'all';
        const getSearchableCardText = (el) => {
            const parts = [el.textContent || ''];
            el.querySelectorAll('input, textarea, select').forEach(inp => {
                if (inp.placeholder) parts.push(inp.placeholder);
                if (inp.tagName === 'SELECT') {
                    Array.from(inp.options || []).forEach(o => parts.push(o.textContent || ''));
                }
            });
            return parts.join(' ').toLowerCase();
        };
        const syncUsetFilter = () => {
            const q = usetSearchIn.value.trim().toLowerCase();
            let shownCount = 0;
            body.querySelectorAll('[data-uset-cat]').forEach(el => {
                if (q) {
                    const hit = getSearchableCardText(el).includes(q);
                    el.classList.toggle('hidden', !hit);
                    if (hit) shownCount++;
                } else {
                    const cats = String(el.dataset.usetCat || '').split(/\s+/);
                    const vis = (activeUsetCat === 'all' || cats.includes(activeUsetCat));
                    el.classList.toggle('hidden', !vis);
                    if (vis) shownCount++;
                }
            });
            usetEmptyMsg.classList.toggle('hidden', !(q && shownCount === 0));
        };
        usetSearchIn.addEventListener('input', syncUsetFilter);
        [
            ['all', t('uset_tab_all')],
            ['profile', t('uset_tab_profile')],
            ['appearance', t('uset_tab_appearance')],
            ['data', t('uset_tab_data')],
            ['privacy', t('uset_tab_privacy')],
            ['security', t('uset_tab_security')]
        ].forEach(([catKey, catLbl]) => {
            const tb = document.createElement('button');
            tb.type = 'button';
            tb.className = 'adm-nav-btn' + (catKey === activeUsetCat ? ' active' : '');
            tb.textContent = catLbl;
            tb.addEventListener('click', () => {
                activeUsetCat = catKey;
                usetTabs.querySelectorAll('.adm-nav-btn').forEach(b => b.classList.remove('active'));
                tb.classList.add('active');
                syncUsetFilter();
            });
            usetTabs.appendChild(tb);
        });
        body.appendChild(usetSearchWrap);
        body.appendChild(usetTabs);
        body.appendChild(usetEmptyMsg);
        body.appendChild(refCard);

        // Item #14: Zero-Temp-Disk Streaming .ZIP Self-Backup Card (Excludes Secret Chats & Enforces Traffic Quota)
        const backupZipCard = document.createElement('div');
        backupZipCard.className = 'card-box';
        backupZipCard.dataset.usetCat = 'data';
        backupZipCard.dataset.usetOrder = '50';
        const bzHead = document.createElement('div');
        bzHead.className = 'section-header';
        bzHead.textContent = t('user_backup_sec_title');
        backupZipCard.appendChild(bzHead);
        const bzDesc = document.createElement('p');
        bzDesc.style.cssText = 'font-size:12.5px;color:var(--text-secondary);margin:0 0 10px;line-height:1.55';
        bzDesc.textContent = t('user_backup_sec_desc');
        backupZipCard.appendChild(bzDesc);
        const bzActions = document.createElement('div');
        bzActions.className = 'resp-action-row';
        const bzBtn = document.createElement('button');
        bzBtn.type = 'button';
        bzBtn.className = 'btn btn-primary btn-sm';
        bzBtn.textContent = t('user_backup_dl_btn');
        bzBtn.addEventListener('click', async () => {
            bzBtn.disabled = true;
            const origTxt = bzBtn.textContent;
            bzBtn.textContent = t('user_backup_preparing');
            const pf = await apiCall('user_backup_preflight', {});
            if (!pf.ok) {
                bzBtn.disabled = false;
                bzBtn.textContent = origTxt;
                toast(pf.message || t('user_backup_traffic_err_generic'), true);
                return;
            }
            // Stream directly via native POST form submission (zero temp disk on server, zero RAM blob buffer in browser)
            const dlForm = document.createElement('form');
            dlForm.method = 'POST';
            dlForm.action = '?a=user_backup_zip';
            dlForm.style.display = 'none';
            const csrfIn = document.createElement('input');
            csrfIn.type = 'hidden';
            csrfIn.name = 'csrf_token';
            csrfIn.value = store.csrf || '';
            dlForm.appendChild(csrfIn);
            document.body.appendChild(dlForm);
            dlForm.submit();
            dlForm.remove();
            toast(t('user_backup_started_toast'));
            setTimeout(async () => {
                bzBtn.disabled = false;
                bzBtn.textContent = origTxt;
                const bRes = await apiCall('boot', {});
                if (bRes.ok && bRes.data && bRes.data.user) {
                    store.user = bRes.data.user;
                    renderUserQuotasCard(store.user);
                }
            }, 1400);
        });
        bzActions.appendChild(bzBtn);
        const bzFilesBtn = document.createElement('button');
        bzFilesBtn.type = 'button';
        bzFilesBtn.className = 'btn btn-secondary btn-sm';
        bzFilesBtn.textContent = t('my_files_manage_shortcut_btn');
        bzFilesBtn.addEventListener('click', () => {
            close();
            openMyUploadedFilesModal(0);
        });
        bzActions.appendChild(bzFilesBtn);
        backupZipCard.appendChild(bzActions);

        // User Traffic & Storage Quotas Live Summary Card (Items #3 & #4) — appended below security for clean priority ordering
        const quotasCard = document.createElement('div');
        quotasCard.className = 'card-box';
        quotasCard.dataset.usetCat = 'data';
        quotasCard.dataset.usetOrder = '40';
        const renderUserQuotasCard = (userObj) => {
            quotasCard.innerHTML = '';
            const qHead = document.createElement('div');
            qHead.className = 'section-header';
            qHead.textContent = t('user_quotas_card_title');
            quotasCard.appendChild(qHead);

            const qGrid = document.createElement('div');
            qGrid.className = 'resp-grid-2';

            // 1. Traffic Quota Box
            const tr = (userObj && userObj.traffic_status) || {};
            const trUsed = Number(tr.used_bytes || 0);
            const trLim = Number(tr.limit_bytes || 0);
            const trExempt = Boolean(tr.is_exempt) || (userObj && userObj.role === 'superadmin');
            const trRem = trLim > 0 && !trExempt ? Math.max(0, trLim - trUsed) : -1;
            const trPct = (trLim > 0 && !trExempt) ? Math.min(100, Math.round((trUsed / trLim) * 100)) : 8;

            const trBox = document.createElement('div');
            trBox.style.cssText = 'padding:10px 12px;border:1px solid var(--border);border-radius:12px;background:var(--bg-subtle)';
            const trTitle = document.createElement('div');
            trTitle.style.cssText = 'font-weight:800;font-size:13px;margin-bottom:6px;color:var(--primary)';
            trTitle.textContent = t('user_traffic_sec_label');
            trBox.appendChild(trTitle);

            const trTrack = document.createElement('div');
            trTrack.className = 'quota-meter-track';
            const trFill = document.createElement('div');
            trFill.className = 'quota-meter-fill' + (trPct >= 95 ? ' danger' : (trPct >= 80 ? ' warn' : ''));
            trFill.style.width = `${trPct}%`;
            trTrack.appendChild(trFill);
            trBox.appendChild(trTrack);

            const mkQLine = (lbl, val) => {
                const row = document.createElement('div');
                row.style.cssText = 'display:flex;justify-content:space-between;gap:8px;font-size:12px;margin-top:4px';
                const s1 = document.createElement('span');
                s1.style.color = 'var(--text-secondary)';
                s1.textContent = lbl;
                const s2 = document.createElement('strong');
                s2.textContent = val;
                row.appendChild(s1);
                row.appendChild(s2);
                return row;
            };
            trBox.appendChild(mkQLine(t('user_traffic_used_label'), formatBytes(trUsed)));
            trBox.appendChild(mkQLine(t('user_traffic_limit_label'), (trLim > 0 && !trExempt) ? formatBytes(trLim) : t('quota_unlimited')));
            trBox.appendChild(mkQLine(t('user_traffic_rem_label'), trRem >= 0 ? formatBytes(trRem) : t('quota_unlimited')));
            if (!trExempt && trLim > 0) {
                const resetStr = Number(tr.reset_at || 0) > 0
                    ? formatDate(Number(tr.reset_at))
                    : t('quota_permanent_no_reset');
                trBox.appendChild(mkQLine(t('user_traffic_reset_label'), resetStr));
            }
            qGrid.appendChild(trBox);

            // 2. File Storage Quota Box
            const st = (userObj && userObj.storage_status) || {};
            const stUsed = Number(st.used_bytes || 0);
            const stLim = Number(st.limit_bytes || 0);
            const stExempt = Boolean(st.is_exempt) || (userObj && userObj.role === 'superadmin');
            const stRem = stLim > 0 && !stExempt ? Math.max(0, stLim - stUsed) : -1;
            const stPct = (stLim > 0 && !stExempt) ? Math.min(100, Math.round((stUsed / stLim) * 100)) : 8;

            const stBox = document.createElement('div');
            stBox.style.cssText = 'padding:10px 12px;border:1px solid var(--border);border-radius:12px;background:var(--bg-subtle)';
            const stTitle = document.createElement('div');
            stTitle.style.cssText = 'font-weight:800;font-size:13px;margin-bottom:6px;color:var(--primary)';
            stTitle.textContent = t('user_storage_sec_label');
            stBox.appendChild(stTitle);

            const stTrack = document.createElement('div');
            stTrack.className = 'quota-meter-track';
            const stFill = document.createElement('div');
            stFill.className = 'quota-meter-fill' + (stPct >= 95 ? ' danger' : (stPct >= 80 ? ' warn' : ''));
            stFill.style.width = `${stPct}%`;
            stTrack.appendChild(stFill);
            stBox.appendChild(stTrack);

            stBox.appendChild(mkQLine(t('user_storage_used_label'), formatBytes(stUsed)));
            stBox.appendChild(mkQLine(t('user_storage_limit_label'), (stLim > 0 && !stExempt) ? formatBytes(stLim) : t('quota_unlimited')));
            stBox.appendChild(mkQLine(t('user_storage_rem_label'), stRem >= 0 ? formatBytes(stRem) : t('quota_unlimited')));
            qGrid.appendChild(stBox);

            quotasCard.appendChild(qGrid);
        };
        renderUserQuotasCard(u);
        apiCall('boot').then(br => {
            if (br && br.ok && br.data) {
                if (br.data.settings) {
                    store.settings = Object.assign(store.settings || {}, br.data.settings);
                    const freshLim = getIdentityLenLimits();
                    if (inName.isConnected) {
                        inName.minLength = freshLim.nMin;
                        inName.maxLength = freshLim.nMax;
                        hintNameProf.textContent = formatDisplayNameLenHint(freshLim.nMin, freshLim.nMax);
