        const saveProfBtn = document.createElement('button');
        saveProfBtn.className = 'btn btn-primary btn-sm';
        saveProfBtn.textContent = t('save_profile_btn');
        saveProfBtn.addEventListener('click', async () => {
            const curLimP = getIdentityLenLimits();
            const nextNameVal = inName.value.trim();
            const nextUnameVal = chkNoUname.checked ? '' : inUname.value.trim().replace(/^@+/, '').toLowerCase();
            if (nextNameVal !== String(u.name || '')) {
                const nLen = countUnicodeChars(nextNameVal);
                if (nLen < curLimP.nMin || nLen > curLimP.nMax) {
                    toast(formatInvalidDisplayNameErr(curLimP.nMin, curLimP.nMax), true);
                    inName.focus();
                    return;
                }
            }
            if (!chkNoUname.checked && (nextUnameVal !== String(u.username || '') || Number(u.no_username) === 1)) {
                if (!/^[a-z0-9_]+$/.test(nextUnameVal) || nextUnameVal.length < curLimP.uMin || nextUnameVal.length > curLimP.uMax) {
                    toast(formatInvalidUsernameErr(curLimP.uMin, curLimP.uMax), true);
                    inUname.focus();
                    return;
                }
            }
            store.cal = selCal.value;
            localStorage.setItem('pm_cal', store.cal);
            const payload = {
                name: nextNameVal,
                username: nextUnameVal,
                no_username: chkNoUname.checked ? 1 : 0,
                bio: inBio.value.trim(),
                theme: selTheme.value,
                lang: selLang.value
            };
            if (pendingAvatarDataUrl) payload.avatar = pendingAvatarDataUrl;
            else if (removeAvatarFlag) payload.remove_avatar = 1;
            if (chkBadge !== null) payload.show_admin_badge = chkBadge.checked ? 1 : 0;

            const r = await apiCall('profile_update', payload);
            if (r.ok && r.data.user) {
                store.user = r.data.user;
                applyLangAndTheme(selLang.value, selTheme.value, false);
                renderSelfDock();
                renderChatList();
                renderActiveChatHeader();
                await renderMessagesViewport(false);
                toast(t('profile_saved_toast'));
                close();
            } else {
                toast(r.message || t('err_generic'), true);
            }
        });
