        // Item #17: Per-User Default Sent-Message Auto-Delete (TTL seconds..days + after_send vs after_read + shortest-time priority)
        const defTtlBox = document.createElement('div');
        defTtlBox.style.cssText = 'margin:12px 0;padding:12px;border:1px solid var(--border);border-radius:12px;background:var(--bg-subtle)';
