        const curUserTtlSec = Math.max(0, Number(u.user_default_ttl || 0));
        let initTtlUnit = 1;
        let initTtlVal = 0;
        if (curUserTtlSec > 0) {
            if (curUserTtlSec % 86400 === 0) { initTtlUnit = 86400; initTtlVal = curUserTtlSec / 86400; }
            else if (curUserTtlSec % 3600 === 0) { initTtlUnit = 3600; initTtlVal = curUserTtlSec / 3600; }
            else if (curUserTtlSec % 60 === 0) { initTtlUnit = 60; initTtlVal = curUserTtlSec / 60; }
            else { initTtlUnit = 1; initTtlVal = curUserTtlSec; }
        }

