        // Item #4: Save Privacy Settings button styled green (btn-primary) matching all other primary save buttons
        const savePrivBtn = document.createElement('button');
        savePrivBtn.type = 'button';
        savePrivBtn.className = 'btn btn-primary btn-sm';
        savePrivBtn.textContent = t('save_privacy_btn');
        savePrivBtn.addEventListener('click', async () => {
            const rawTtlNum = Math.max(0, parseFloat(inUserTtlNum.value || '0') || 0);
            const rawTtlMult = Math.max(1, parseInt(selUserTtlUnit.value || '1', 10) || 1);
            const computedUserDefTtl = rawTtlNum <= 0 ? 0 : Math.min(31536000, Math.round(rawTtlNum * rawTtlMult));
            const r = await apiCall('privacy_update', {
                last_seen_mode: selSeenMode.value,
                hide_last_seen: selSeenMode.value === 'recently' ? 1 : 0,
                show_online: cOnline.input.checked ? 1 : 0,
                read_receipts: cReadRec.input.checked ? 1 : 0,
                show_my_typing: cShowMyTyping.input.checked ? 1 : 0,
                user_ghost_mode: cUserGhost.input.checked ? 1 : 0,
                hide_edit_badge: cHideEditBadge.input.checked ? 1 : 0,
                hide_search: cSearch.input.checked ? 1 : 0,
                deny_dm: cDm.input.checked ? 1 : 0,
                deny_calls: cCalls.input.checked ? 1 : 0,
                deny_group_invite: cGrpInv.input.checked ? 1 : 0,
                inactivity_days: parseInt(inInact.value || '0', 10),
                user_default_ttl: computedUserDefTtl,
                user_default_ttl_mode: selUserTtlMode.value
            });
            if (r.ok && r.data.user) {
                store.user = r.data.user;
                renderSelfDock();
                renderActiveChatHeader();
                toast(t('privacy_saved_toast'));
            } else {
                toast(r.message || t('err_generic'), true);
            }
        });
        privCard.appendChild(savePrivBtn);
