        // Numbered, Paginated, Searchable Blocked Users List Card (Item #16)
        const blkCard = document.createElement('div');
        blkCard.className = 'card-box';
        blkCard.dataset.usetCat = 'privacy';
        blkCard.dataset.usetOrder = '70';
        const blkHead = document.createElement('div');
        blkHead.className = 'section-header';
        blkHead.textContent = t('blocked_users_sec_title');
        blkCard.appendChild(blkHead);

        const blkAddRow = document.createElement('div');
        blkAddRow.className = 'resp-action-row';
        blkAddRow.style.marginBottom = '10px';
        const blkAddIn = document.createElement('input');
        blkAddIn.className = 'input';
        blkAddIn.style.flex = '1';
        blkAddIn.dir = 'ltr';
        blkAddIn.placeholder = t('block_by_username_ph');
        const blkAddBtn = document.createElement('button');
        blkAddBtn.type = 'button';
        blkAddBtn.className = 'btn btn-danger btn-sm';
        blkAddBtn.textContent = t('block_user_add_btn');
        blkAddRow.appendChild(blkAddIn);
        blkAddRow.appendChild(blkAddBtn);
        blkCard.appendChild(blkAddRow);

        const blkSearchIn = document.createElement('input');
        blkSearchIn.className = 'input';
        blkSearchIn.style.marginBottom = '10px';
        blkSearchIn.placeholder = t('blocked_users_search_ph');
        blkCard.appendChild(blkSearchIn);

        const blkListWrap = document.createElement('div');
        const blkPagerWrap = document.createElement('div');
        blkCard.appendChild(blkListWrap);
        blkCard.appendChild(blkPagerWrap);
        body.appendChild(blkCard);

        let blockedUsersItems = [];
        let blkPage = 1;
        let blkPageSize = 10;

        const renderBlockedUsersUI = () => {
            blkListWrap.innerHTML = '';
            blkPagerWrap.innerHTML = '';
            const q = blkSearchIn.value.trim().toLowerCase().replace(/^@+/, '');
            const filtered = blockedUsersItems.filter(bu => {
                if (!q) return true;
                return String(bu.name || '').toLowerCase().includes(q)
                    || String(bu.username || '').toLowerCase().includes(q)
                    || String(bu.id || '') === q;
            });

            if (filtered.length === 0) {
                const emp = document.createElement('div');
                emp.style.cssText = 'font-size:12.5px;color:var(--text-muted);text-align:center;padding:12px 6px';
                emp.textContent = t('blocked_users_empty');
                blkListWrap.appendChild(emp);
                return;
            }

            const pager = buildAdminPaginationControls({
                totalItems: filtered.length,
                page: blkPage,
                pageSize: blkPageSize,
                pageSizeOptions: [5, 10, 20, 50],
                onPageChange: (nextP) => { blkPage = nextP; renderBlockedUsersUI(); },
                onPageSizeChange: (nextSz) => { blkPageSize = nextSz; blkPage = 1; renderBlockedUsersUI(); }
            });
            blkPage = pager.curPage;
            const slice = filtered.slice(pager.fromOffset, pager.toOffset);

            slice.forEach((bu, idx) => {
                const rowNum = pager.fromOffset + idx + 1;
                const itemCard = document.createElement('div');
                itemCard.className = 'adm-item-card';
                itemCard.style.marginBottom = '8px';

                const top = document.createElement('div');
                top.className = 'adm-item-top';

                const left = document.createElement('div');
                left.style.cssText = 'display:flex;align-items:center;gap:8px;min-width:0;flex:1';

                const numBadge = document.createElement('span');
                numBadge.className = 'adm-row-num';
                numBadge.textContent = '#' + formatLocalizedCount(rowNum);
                left.appendChild(numBadge);

                const av = document.createElement('div');
                av.className = 'avatar avatar-sm';
                renderAvatarNode(av, bu.name || 'U', bu.avatar || '');
                left.appendChild(av);

                const inf = document.createElement('div');
                inf.style.minWidth = '0';
                const nm = document.createElement('div');
                nm.style.cssText = 'font-weight:700;font-size:13.5px;display:flex;align-items:center;gap:6px;flex-wrap:wrap';
                nm.textContent = bu.name || ('#' + bu.id);
                if (bu.username) {
                    const chip = createCopyUsernameChip(bu.username);
                    if (chip) nm.appendChild(chip);
                }
                inf.appendChild(nm);
                left.appendChild(inf);
                top.appendChild(left);

                const unblkBtn = document.createElement('button');
                unblkBtn.type = 'button';
                unblkBtn.className = 'btn btn-secondary btn-sm';
                unblkBtn.textContent = '🔓 ' + t('unblock_btn');
                unblkBtn.addEventListener('click', async () => {
                    unblkBtn.disabled = true;
                    const ur = await apiCall('unblock_user', { user_id: bu.id });
                    if (ur.ok) {
                        if (Array.isArray(ur.data.blocked_ids)) store.blockedIds = ur.data.blocked_ids;
                        await loadBlockedUsersList();
                        toast(t('unblocked_toast'));
                    } else {
                        unblkBtn.disabled = false;
                        toast(ur.message || t('err_generic'), true);
                    }
                });
                top.appendChild(unblkBtn);
                itemCard.appendChild(top);
                blkListWrap.appendChild(itemCard);
            });

            blkPagerWrap.appendChild(pager.bar);
        };

        const loadBlockedUsersList = async () => {
            const br = await apiCall('blocked_users_list', {});
            if (br.ok && br.data) {
                blockedUsersItems = Array.isArray(br.data.blocked_users) ? br.data.blocked_users : [];
                if (Array.isArray(br.data.blocked_ids)) store.blockedIds = br.data.blocked_ids;
                renderBlockedUsersUI();
            }
        };

        blkAddBtn.addEventListener('click', async () => {
            const rawTarget = blkAddIn.value.trim();
            if (!rawTarget) return;
            blkAddBtn.disabled = true;
            const isNumericId = /^\d+$/.test(rawTarget);
            const payload = isNumericId ? { user_id: parseInt(rawTarget, 10) } : { username: rawTarget };
            const br = await apiCall('block_user', payload);
            blkAddBtn.disabled = false;
            if (br.ok) {
                blkAddIn.value = '';
                if (Array.isArray(br.data.blocked_ids)) store.blockedIds = br.data.blocked_ids;
                await loadBlockedUsersList();
                toast(t('blocked_toast'));
            } else {
                toast(br.message || t('err_generic'), true);
            }
        });
        blkSearchIn.addEventListener('input', () => {
            blkPage = 1;
            renderBlockedUsersUI();
        });
        loadBlockedUsersList();

        // Media Auto-Download, Silent Browser Notification & Master App Sound Mute Settings Card (Item #5)
