        const cAppSoundsMuted = makeChk(Number(u.app_sounds_muted) === 1, t('app_sounds_muted_lbl'));
        const muteHintEl = document.createElement('div');
        muteHintEl.style.cssText = 'font-size:11.5px;color:var(--text-muted);margin:0 0 8px;line-height:1.5';
        muteHintEl.textContent = t('app_sounds_muted_hint');

        const fgSendKey = document.createElement('div');
