        permBadge.id = 'uset-notif-perm-badge';
        permBadge.style.fontWeight = '800';
        const syncNotifPermBadge = () => {
            if (!('Notification' in window)) {
                permBadge.textContent = t('notif_status_unsupported');
            } else if (Notification.permission === 'granted') {
                permBadge.textContent = t('notif_status_granted');
            } else if (Notification.permission === 'denied') {
                permBadge.textContent = t('notif_status_denied');
            } else {
                permBadge.textContent = t('notif_status_default');
            }
        };
        syncNotifPermBadge();
        permBox.appendChild(permLeft);
        permBox.appendChild(permBadge);

        cBrNotif.input.addEventListener('change', async () => {
            if (cBrNotif.input.checked && 'Notification' in window && Notification.permission === 'default') {
                try {
