                } catch (e) {}
            }
        });

        mediaNotifCard.appendChild(fgSendKey);
        mediaNotifCard.appendChild(cChatSounds.wrap);
        mediaNotifCard.appendChild(cBgPush.wrap);
        mediaNotifCard.appendChild(cAppSoundsMuted.wrap);
        mediaNotifCard.appendChild(muteHintEl);
        mediaNotifCard.appendChild(cAutoImg.wrap);
        mediaNotifCard.appendChild(cAutoVid.wrap);
        mediaNotifCard.appendChild(cAutoAud.wrap);
        mediaNotifCard.appendChild(cAutoplayGifs.wrap);
        mediaNotifCard.appendChild(cBrNotif.wrap);
