        const saveMnBtn = document.createElement('button');
        saveMnBtn.type = 'button';
        saveMnBtn.className = 'btn btn-primary btn-sm';
        saveMnBtn.textContent = t('save_media_notif_btn');
        saveMnBtn.addEventListener('click', async () => {
            if (cBrNotif.input.checked && 'Notification' in window && Notification.permission === 'default') {
                try { await Notification.requestPermission(); syncNotifPermBadge(); } catch (e) {}
            }
            const nextMuted = cAppSoundsMuted.input.checked ? 1 : 0;
            const r = await apiCall('profile_update', {
                send_key_mode: selSendKey.value,
                chat_sounds_enabled: cChatSounds.input.checked ? 1 : 0,
                bg_push_enabled: cBgPush.input.checked ? 1 : 0,
                app_sounds_muted: nextMuted,
                auto_dl_images: cAutoImg.input.checked ? 1 : 0,
                auto_dl_videos: cAutoVid.input.checked ? 1 : 0,
                auto_dl_audio: cAutoAud.input.checked ? 1 : 0,
                autoplay_gifs: cAutoplayGifs.input.checked ? 1 : 0,
                browser_notif: cBrNotif.input.checked ? 1 : 0,
                notif_preview: cNotifPreview.input.checked ? 1 : 0,
                notif_silent: cSilentNotif.input.checked ? 1 : 0
            });
            if (r.ok && r.data.user) {
                store.user = r.data.user;
                if (typeof window.syncNotifMasterBtn === 'function') window.syncNotifMasterBtn();
                if (nextMuted === 1 && typeof LiveCallManager !== 'undefined') {
                    LiveCallManager.stopRingtone();
                }
                if (typeof syncBackgroundServiceWorkerAndPush === 'function') {
                    syncBackgroundServiceWorkerAndPush(cBgPush.input.checked);
                }
                await renderMessagesViewport(false);
                toast(t('media_notif_saved_toast'));
            } else {
                toast(r.message || t('err_generic'), true);
