        testNotifBtn.textContent = t('test_device_notif_btn');
        testNotifBtn.addEventListener('click', async () => {
            if (!('Notification' in window)) {
                toast(t('notif_status_unsupported'), true);
                return;
            }
            let perm = Notification.permission;
            if (perm === 'default') {
                try { perm = await Notification.requestPermission(); syncNotifPermBadge(); } catch (e) {}
            }
            if (perm !== 'granted') {
                toast(t('notif_perm_denied'), true);
                return;
            }
            await showDeviceNotification({
                title: t('test_device_notif_title'),
                body: t('test_device_notif_body'),
                tag: 'm3-test-notif',
                chatId: store.activeChatId || 0,
                silent: Boolean(cSilentNotif.input.checked)
            });
            toast(t('test_device_notif_sent'));
        });
