        secCard.dataset.usetOrder = '80';
        const sHead = document.createElement('div');
        sHead.className = 'section-header';
        sHead.textContent = t('security_2fa_sec');
        secCard.appendChild(sHead);

        const totpBox = document.createElement('div');
        totpBox.className = 'resp-action-row';
        totpBox.style.marginBottom = '10px';
        const twoFaAllowed = (u.totp_allowed === undefined || u.totp_allowed === null) ? true : (Number(u.totp_allowed) === 1);
        if (!twoFaAllowed) {
            const twoFaNotice = document.createElement('p');
            twoFaNotice.style.cssText = 'font-size:12px;color:var(--text-secondary);background:var(--bg-subtle);border:1px solid var(--border);border-radius:10px;padding:9px 11px;margin:0 0 10px;line-height:1.6';
            twoFaNotice.textContent = (Number(store.settings && store.settings.twofa_enabled) === 0)
                ? t('twofa_unavailable_global')
                : t('twofa_unavailable_user');
            secCard.appendChild(twoFaNotice);
            if (u.totp_enabled === 1) {
                const suspHint = document.createElement('p');
                suspHint.style.cssText = 'font-size:11.5px;color:var(--text-muted);margin:0 0 10px;line-height:1.6';
                suspHint.textContent = t('twofa_suspended_hint');
                secCard.appendChild(suspHint);
            }
        } else if (u.totp_enabled === 1) {
            const disBtn = document.createElement('button');
            disBtn.type = 'button';
            disBtn.className = 'btn btn-danger btn-sm';
            disBtn.textContent = t('disable_2fa_btn');
            disBtn.addEventListener('click', async () => {
                const ap = await askApproval({
                    title: t('disable_2fa_btn'),
                    desc: t('security_2fa_sec'),
                    danger: true,
                    icon: '🔓',
                    input: { label: t('totp_disable_prompt_lbl'), type: 'password', required: true, dir: 'ltr' }
                });
                if (!ap.approved) return;
                const r = await apiCall('totp_disable', { password: ap.value, code: ap.value });
                if (r.ok) {
                    store.user.totp_enabled = 0;
                    toast(t('twofa_disabled_toast'));
                    close();
                    openSettingsModal();
                } else {
                    toast(r.message || t('err_generic'), true);
                }
            });
            totpBox.appendChild(disBtn);
        } else {
            const enBtn = document.createElement('button');
            enBtn.type = 'button';
            enBtn.className = 'btn btn-secondary btn-sm';
            enBtn.textContent = t('enable_2fa_btn');
            enBtn.addEventListener('click', async () => {
                const r = await apiCall('totp_setup');
                if (r.ok) {
                    const secretDescNode = document.createElement('div');
                    secretDescNode.style.cssText = 'display:flex;flex-direction:column;gap:8px;align-items:flex-start';
                    const lblSpan = document.createElement('span');
                    lblSpan.textContent = t('twofa_secret_lbl');
                    const copyChip = document.createElement('button');
                    copyChip.type = 'button';
                    copyChip.className = 'copyable-secret-chip';
                    copyChip.title = t('totp_secret_click_copy_tip');
                    copyChip.setAttribute('dir', 'ltr');
                    copyChip.textContent = `📋 ${r.data.secret}`;
                    copyChip.addEventListener('click', e => {
                        e.preventDefault();
                        e.stopPropagation();
                        if (navigator.clipboard) navigator.clipboard.writeText(r.data.secret);
                        toast(t('copied_toast'));
                    });
                    const tipSmall = document.createElement('span');
                    tipSmall.style.cssText = 'font-size:11.5px;color:var(--text-muted)';
                    tipSmall.textContent = '👆 ' + t('totp_secret_click_copy_tip');
                    secretDescNode.appendChild(lblSpan);
                    secretDescNode.appendChild(copyChip);
                    secretDescNode.appendChild(tipSmall);

                    const ap = await askApproval({
                        title: t('enable_2fa_btn'),
                        descNode: secretDescNode,
                        danger: false,
                        icon: '🔐',
                        input: { label: t('totp_code'), type: 'text', placeholder: '123456', required: true, dir: 'ltr' }
                    });
                    if (ap.approved && ap.value) {
                        const vr = await apiCall('totp_enable', { code: ap.value.trim(), secret: r.data.secret });
