        // Item #15: Clean top spacing above «🔄 ذخیره رمز عبور جدید»
        const savePwBtn = document.createElement('button');
        savePwBtn.type = 'button';
        savePwBtn.className = 'btn btn-primary btn-sm';
        savePwBtn.style.marginTop = '10px';
        savePwBtn.textContent = t('change_password_btn');
        savePwBtn.addEventListener('click', async () => {
            const pOld = curPwF.inp.value;
            const pNew = newPwF.inp.value;
            const pCnf = cnfPwF.inp.value;
            if (!pOld) { curPwF.inp.focus(); return; }
            const pwChk = validateStrongPasswordClient(pNew);
            if (!pwChk.valid) {
                syncUsetPwGuide();
                toast(pwChk.message, true);
                newPwF.inp.focus();
                return;
            }
            if (pNew !== pCnf) {
                syncUsetPwGuide();
                toast(t('inst_pass_mismatch'), true);
                cnfPwF.inp.focus();
                return;
            }
            const r = await apiCall('password_change', { old_password: pOld, new_password: pNew });
            if (r.ok) {
                try { await E2EE.syncWithPassword(pNew); } catch (e) {}
                curPwF.inp.value = '';
                newPwF.inp.value = '';
                cnfPwF.inp.value = '';
                syncUsetPwGuide();
                toast(t('password_changed_toast'));
            } else {
                toast(r.message || t('err_generic'), true);
            }
        });
        pwDiv.appendChild(savePwBtn);
        secCard.appendChild(pwDiv);
        if (typeof enhancePasswordFields === 'function') {
            enhancePasswordFields(pwDiv);
        }

        // Duress / Self-Destruct Password Section (Item 2)
        const durDiv = document.createElement('div');
        durDiv.style.cssText = 'border-block-start:1px solid var(--border);margin-block-start:14px;padding-block-start:12px';

        const durTop = document.createElement('div');
        durTop.style.cssText = 'display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap;margin-bottom:6px';
        const durTitle = document.createElement('div');
        durTitle.style.cssText = 'font-weight:800;font-size:13.5px;color:var(--danger)';
        durTitle.textContent = t('duress_sec_title');
        const durBadge = document.createElement('span');
        const syncDurBadge = (active) => {
            durBadge.className = 'adm-badge-pill ' + (active ? 'danger' : '');
            durBadge.textContent = active ? t('duress_status_active') : t('duress_status_inactive');
        };
        syncDurBadge(Boolean(store.user && store.user.has_duress_password));
        durTop.appendChild(durTitle);
        durTop.appendChild(durBadge);
        durDiv.appendChild(durTop);

        const durDesc = document.createElement('p');
        durDesc.style.cssText = 'font-size:12px;color:var(--text-secondary);margin:0 0 10px;line-height:1.6';
        durDesc.textContent = t('duress_sec_desc');
        durDiv.appendChild(durDesc);

        const durCurPw = mkPwGroup(t('duress_cur_pw_lbl'), '••••••••', 'current-password');
        const durNewPw = mkPwGroup(t('duress_new_pw_lbl'), '••••••••', 'new-password');
        const durConfirmPw = mkPwGroup(t('duress_new_pw_confirm_lbl'), '••••••••', 'new-password');
        durDiv.appendChild(durCurPw.g);
        durDiv.appendChild(durNewPw.g);
        durDiv.appendChild(durConfirmPw.g);

        const durActions = document.createElement('div');
        durActions.className = 'resp-action-row';

        const durSaveBtn = document.createElement('button');
        durSaveBtn.type = 'button';
        durSaveBtn.className = 'btn btn-danger btn-sm';
        durSaveBtn.textContent = t('duress_save_btn');
        durSaveBtn.addEventListener('click', async () => {
            const mp = durCurPw.inp.value;
            const dp = durNewPw.inp.value;
            const dp2 = durConfirmPw.inp.value;
            if (!mp) { durCurPw.inp.focus(); return; }
            if (dp.length < 6) {
                toast(t('inst_pass_short'), true);
                durNewPw.inp.focus();
                return;
            }
            if (dp !== dp2) {
                toast(t('duress_pw_mismatch_err'), true);
                durConfirmPw.inp.focus();
                return;
            }
            const r = await apiCall('duress_password_set', {
                current_password: mp,
                duress_password: dp,
                duress_password_confirm: dp2
            });
            if (r.ok) {
                durCurPw.inp.value = '';
                durNewPw.inp.value = '';
                durConfirmPw.inp.value = '';
                if (store.user) store.user.has_duress_password = 1;
                syncDurBadge(true);
                durRemBtn.classList.remove('hidden');
                toast(t('duress_saved_toast'));
            } else {
                toast(r.message || t('err_generic'), true);
            }
        });
        durActions.appendChild(durSaveBtn);

        const durRemBtn = document.createElement('button');
        durRemBtn.type = 'button';
        durRemBtn.className = 'btn btn-secondary btn-sm' + ((store.user && store.user.has_duress_password) ? '' : ' hidden');
        durRemBtn.textContent = t('duress_remove_btn');
        durRemBtn.addEventListener('click', async () => {
            const mp = durCurPw.inp.value;
            if (!mp) { durCurPw.inp.focus(); return; }
            const r = await apiCall('duress_password_set', { current_password: mp, remove: 1 });
            if (r.ok) {
                durCurPw.inp.value = '';
                durNewPw.inp.value = '';
                if (store.user) store.user.has_duress_password = 0;
                syncDurBadge(false);
                durRemBtn.classList.add('hidden');
                toast(t('duress_removed_toast'));
            } else {
                toast(r.message || t('err_generic'), true);
            }
        });
        durActions.appendChild(durRemBtn);
        durDiv.appendChild(durActions);
        secCard.appendChild(durDiv);
        if (typeof enhancePasswordFields === 'function') {
            enhancePasswordFields(durDiv);
        }

        // Item 12: Messenger Lock Screen Configuration Card
        const lockDiv = document.createElement('div');
        lockDiv.style.cssText = 'border-top:1px solid var(--border);margin-top:14px;padding-top:14px';
        const lockHead = document.createElement('div');
        lockHead.style.cssText = 'font-weight:800;font-size:13.5px;color:var(--primary);margin-bottom:4px';
        lockHead.textContent = t('lock_screen_sec_title');
        lockDiv.appendChild(lockHead);
        const lockDesc = document.createElement('p');
        lockDesc.style.cssText = 'font-size:12px;color:var(--text-secondary);margin:0 0 10px;line-height:1.6';
        lockDesc.textContent = t('lock_screen_sec_desc');
        lockDiv.appendChild(lockDesc);

        const lockEnableLbl = document.createElement('label');
        lockEnableLbl.className = 'settings-chk-row';
        lockEnableLbl.style.cssText = 'font-weight:700;margin-bottom:6px';
        const chkLockEnable = document.createElement('input');
        chkLockEnable.type = 'checkbox';
        // Their own lock screen, not one the super-admin is forcing. The effective
        // flag is on for a forced lock too, so the toggle used to look switched on
        // with nothing behind it - and saving then demanded a password the user
        // never meant to set, which is what made it look like nothing ever saved.
        chkLockEnable.checked = !!(store.user && Number(store.user.lock_own_active) === 1);
        const spLockEnable = document.createElement('span');
        spLockEnable.textContent = t('lock_screen_enable_toggle');
        lockEnableLbl.appendChild(chkLockEnable);
        lockEnableLbl.appendChild(spLockEnable);
        lockDiv.appendChild(lockEnableLbl);

        // When the super-admin forces a lock for everybody, this account shows as
        // locked even with nothing of its own. Say so, so an unticked toggle above
        // is not read as a save that silently failed.
        const lockForcedNote = document.createElement('p');
        lockForcedNote.className = 'muted-notice';
        lockForcedNote.textContent = t('lock_forced_no_pw_hint');
        lockDiv.appendChild(lockForcedNote);

        const fgLockTimeout = document.createElement('div');
        fgLockTimeout.className = 'form-group';
        const lblLockTimeout = document.createElement('label');
        lblLockTimeout.textContent = t('lock_screen_timeout_lbl');
        const selLockTimeout = document.createElement('select');
        selLockTimeout.className = 'input';
        const curAutoSec = Number((store.user && store.user.lock_auto_sec !== undefined)
            ? store.user.lock_auto_sec
            : ((store.user && store.user.lock_timeout_sec !== undefined) ? store.user.lock_timeout_sec : 300));
        [
            [0, t('lock_timeout_manual')],
            [60, t('lock_timeout_1m')],
            [300, t('lock_timeout_5m')],
            [900, t('lock_timeout_15m')],
            [1800, t('lock_timeout_30m')],
            [3600, t('lock_timeout_60m')]
        ].forEach(([secVal, secTxt]) => {
            const o = document.createElement('option');
            o.value = String(secVal);
            o.textContent = secTxt;
            if (secVal === curAutoSec) o.selected = true;
            selLockTimeout.appendChild(o);
        });
        fgLockTimeout.appendChild(lblLockTimeout);
        fgLockTimeout.appendChild(selLockTimeout);
        lockDiv.appendChild(fgLockTimeout);

        const lockCurPw = mkPwGroup(t('duress_cur_pw_lbl'), '••••••••', 'current-password');
        const lockNewPw = mkPwGroup(t('lock_screen_new_pw_lbl'), '••••••••', 'new-password');
        const lockConfirmPw = mkPwGroup(t('lock_screen_confirm_pw_lbl'), '••••••••', 'new-password');
        lockDiv.appendChild(lockCurPw.g);
        lockDiv.appendChild(lockNewPw.g);
        lockDiv.appendChild(lockConfirmPw.g);

        const lockActions = document.createElement('div');
        lockActions.className = 'resp-action-row';
        const lockSaveBtn = document.createElement('button');
        lockSaveBtn.type = 'button';
        lockSaveBtn.className = 'btn btn-primary btn-sm';
        lockSaveBtn.textContent = t('lock_screen_save_btn');
        lockSaveBtn.addEventListener('click', async () => {
            const mp = lockCurPw.inp.value;
            const lp = lockNewPw.inp.value;
            const lp2 = lockConfirmPw.inp.value;
            const enOn = chkLockEnable.checked ? 1 : 0;
            if (!mp) { lockCurPw.inp.focus(); return; }
            if (enOn && !(store.user && store.user.has_lock_password) && lp.length < 4) {
                toast(t('lock_screen_new_pw_lbl'), true);
                lockNewPw.inp.focus();
                return;
            }
            if ((lp !== '' || lp2 !== '') && lp !== lp2) {
                toast(t('duress_pw_mismatch_err'), true);
                lockConfirmPw.inp.focus();
                return;
            }
            const selLockSecVal = parseInt(selLockTimeout.value, 10) || 0;
            const hadLockPw = !!(store.user && store.user.has_lock_password);
            const payload = {
                enabled: enOn,
                timeout_sec: selLockSecVal,
                auto_lock_sec: selLockSecVal,
                current_password: mp,
                lock_password: lp,
                lock_password_confirm: lp2
            };
            // Unticking the box has to mean there is no lock password left
            // behind either. Simply disabling kept the stored credential in the
            // database, which is why a second "remove" button existed at all -
            // but that is a step nobody should have to remember. One button, one
            // checkbox: off means off, password included.
            if (!enOn) { payload.remove = 1; payload.remove_password = 1; }
            const r = await apiCall('lock_screen_set', payload);
            if (r.ok && r.data) {
                lockCurPw.inp.value = '';
                lockNewPw.inp.value = '';
                lockConfirmPw.inp.value = '';
                if (r.data.user) {
                    store.user = r.data.user;
                } else if (store.user) {
                    store.user.lock_screen_enabled = r.data.lock_screen_enabled ? 1 : 0;
                    store.user.has_lock_password = r.data.has_lock_password ? 1 : 0;
                    store.user.lock_auto_sec = Number(r.data.lock_auto_sec || 0);
                    store.user.lock_timeout_sec = Number(r.data.lock_auto_sec || 0);
                }
                if (typeof syncQuickLockButtonVisibility === 'function') syncQuickLockButtonVisibility();
                chkLockEnable.checked = !!(store.user && Number(store.user.lock_own_active) === 1);
                if (!chkLockEnable.checked) decoyChk.checked = false;
                syncLockAndDecoyUi();
                // Say what actually happened: switching the lock off now takes the
                // stored password with it, so it is not merely a saved setting.
                toast(t((!enOn && hadLockPw) ? 'lock_screen_removed_toast' : 'lock_screen_saved_toast'));
            } else {
                toast(r.message || t('err_generic'), true);
            }
        });
        lockActions.appendChild(lockSaveBtn);

        lockDiv.appendChild(lockActions);
        if (typeof enhancePasswordFields === 'function') {
            enhancePasswordFields(lockDiv);
        }
        secCard.appendChild(lockDiv);

        // Decoy page: stands in for the lock screen so an onlooker only ever
        // sees an ordinary page. It can only run while a lock screen is active.
        // "Own" = the account's own lock screen, not one the admin forced.
        const decoyDiv = document.createElement('div');
        decoyDiv.style.cssText = 'border-top:1px solid var(--border);margin-top:14px;padding-top:14px';
        const decoyHead = document.createElement('div');
        decoyHead.className = 'section-header';
        decoyHead.textContent = t('decoy_sec_title');
        decoyDiv.appendChild(decoyHead);
        const decoyHint = document.createElement('p');
        decoyHint.className = 'muted-notice';
        decoyHint.textContent = t('decoy_hint');
        decoyDiv.appendChild(decoyHint);
        // Which configuration governs this section right now: theirs, or the
        // super-admin's global one. Both notes live in the document permanently
        // and are only ever hidden, because saving the lock screen just above can
        // flip which one applies and the section has to follow without a rebuild.
        const scopeNote = document.createElement('p');
        scopeNote.className = 'muted-notice';
        decoyDiv.appendChild(scopeNote);
        const decoyForcedNote = document.createElement('p');
        decoyForcedNote.className = 'muted-notice';
        decoyForcedNote.textContent = t('lock_forced_no_pw_hint');
        decoyDiv.appendChild(decoyForcedNote);

        const decoyToggleRow = document.createElement('label');
        decoyToggleRow.className = 'adm-perm-card';
        decoyToggleRow.style.marginBottom = '8px';
        const decoyToggleTxt = document.createElement('span');
        decoyToggleTxt.style.cssText = 'font-size:13px;font-weight:600';
        decoyToggleTxt.textContent = t('decoy_enable_lbl');
        const decoyChk = document.createElement('input');
        decoyChk.type = 'checkbox';
        decoyChk.checked = Number((store.user && store.user.decoy_enabled) || 0) === 1;
        decoyToggleRow.appendChild(decoyToggleTxt);
        decoyToggleRow.appendChild(decoyChk);
        decoyDiv.appendChild(decoyToggleRow);

        const mkDecoyField = (labelTxt, fieldVal) => {
            const fg = document.createElement('div');
            fg.className = 'form-group';
            const lb = document.createElement('label');
            lb.textContent = labelTxt;
            const inp = document.createElement('input');
            inp.type = 'text';
            inp.className = 'input';
            inp.dir = store.lang === 'en' ? 'ltr' : 'rtl';
            inp.value = fieldVal;
            fg.appendChild(lb);
            fg.appendChild(inp);
            return { fg, inp };
        };
        const fDecoyTitle = mkDecoyField(t('decoy_title_lbl'),
            (store.user && typeof store.user.decoy_title === 'string' && store.user.decoy_title !== '')
                ? store.user.decoy_title : t('decoy_default_title'));
        const fDecoySub = mkDecoyField(t('decoy_subtitle_lbl'),
            (store.user && typeof store.user.decoy_subtitle === 'string' && store.user.decoy_subtitle !== '')
                ? store.user.decoy_subtitle : t('decoy_default_subtitle'));
        decoyDiv.appendChild(fDecoyTitle.fg);
        decoyDiv.appendChild(fDecoySub.fg);

        const decoyWarn = document.createElement('p');
        decoyWarn.className = 'muted-notice';
        decoyWarn.textContent = t('decoy_needs_lock_hint');
        decoyDiv.appendChild(decoyWarn);

        // Read the state when it is needed, not once when the panel was built:
        // a lock screen saved a few seconds ago has to count at once, or the decoy
        // refuses to save until the whole panel is closed and opened again.
        const decoyOwnNow = () => !!(store.user && Number(store.user.lock_own_active) === 1);
        const syncLockAndDecoyUi = () => {
            const own = decoyOwnNow();
            const forced = Number(store.user && store.user.lock_forced) === 1
                || Number(store.user && store.user.decoy_forced) === 1;
            scopeNote.textContent = own ? t('decoy_scope_own_lbl') : t('decoy_scope_global_lbl');
            decoyWarn.classList.toggle('hidden', own);
            decoyForcedNote.classList.toggle('hidden', own || !forced);
            lockForcedNote.classList.toggle('hidden', own || !forced);
        };
        syncLockAndDecoyUi();

        const decoyActions = document.createElement('div');
        decoyActions.className = 'resp-action-row';
        const decoySaveBtn = document.createElement('button');
        decoySaveBtn.type = 'button';
        decoySaveBtn.className = 'btn btn-primary btn-sm';
        decoySaveBtn.textContent = t('decoy_save_btn');
        decoySaveBtn.addEventListener('click', async () => {
            // A personal decoy replaces the lock screen, so it can only be
            // switched on once there is a lock password for it to check. Read it
            // now rather than when the panel was built: the lock may have been
            // saved a moment ago, in the very same visit to this screen.
            if (decoyChk.checked && !decoyOwnNow()) {
                toast(t('decoy_needs_lock_hint'), true);
                decoyWarn.classList.remove('hidden');
                return;
            }
            const r = await apiCall('decoy_screen_set', {
                enabled: decoyChk.checked ? 1 : 0,
                decoy_title: fDecoyTitle.inp.value.trim(),
                decoy_subtitle: fDecoySub.inp.value.trim()
            });
            if (r.ok && r.data) {
                if (r.data.user) store.user = r.data.user;
                fDecoyTitle.inp.value = (store.user && typeof store.user.decoy_title === 'string' && store.user.decoy_title !== '')
                    ? store.user.decoy_title : t('decoy_default_title');
                fDecoySub.inp.value = (store.user && typeof store.user.decoy_subtitle === 'string' && store.user.decoy_subtitle !== '')
                    ? store.user.decoy_subtitle : t('decoy_default_subtitle');
                decoyChk.checked = Number((store.user && store.user.decoy_enabled) || 0) === 1;
                syncLockAndDecoyUi();
                toast(t('decoy_saved_toast'));
            } else {
                toast(r.message || t('err_generic'), true);
            }
        });
        decoyActions.appendChild(decoySaveBtn);
        decoyDiv.appendChild(decoyActions);
        secCard.appendChild(decoyDiv);

        // Auto log-out after inactivity - a personal limit that can only ever
        // be stricter than the site-wide policy set by the admin.
        const aloDiv = document.createElement('div');
        aloDiv.style.cssText = 'border-top:1px solid var(--border);margin-top:14px;padding-top:14px';
        const aloHead = document.createElement('div');
        aloHead.className = 'section-header';
        aloHead.textContent = t('auto_logout_lbl');
        aloDiv.appendChild(aloHead);
        const aloDesc = document.createElement('p');
        aloDesc.className = 'muted-notice';
        aloDesc.textContent = t('auto_logout_hint');
        aloDiv.appendChild(aloDesc);

        const aloRow = document.createElement('div');
        aloRow.className = 'resp-action-row keep-inline';
        aloRow.style.flexWrap = 'wrap';

        const aloAmt = document.createElement('input');
        aloAmt.type = 'number';
        aloAmt.className = 'input';
        aloAmt.min = '0';
        aloAmt.max = '525600';
        aloAmt.step = '1';
        aloAmt.dir = 'ltr';
        aloAmt.style.flex = '1 1 110px';
        aloAmt.style.minWidth = '0';
        aloAmt.id = 'uset-auto-logout-amount';

        const aloUnit = document.createElement('select');
        aloUnit.className = 'input';
        aloUnit.style.flex = '0 0 120px';
        aloUnit.id = 'uset-auto-logout-unit';
        [[60, t('auto_logout_unit_min')], [3600, t('auto_logout_unit_hour')], [86400, t('auto_logout_unit_day')]].forEach(([mult, lbl]) => {
            const o = document.createElement('option');
            o.value = String(mult);
            o.textContent = lbl;
            aloUnit.appendChild(o);
        });

        const aloOwn = Number((store.user && store.user.auto_logout_own_sec) || 0);
        let aloUnitSel = 60, aloAmtVal = 0;
        if (aloOwn >= 86400 && aloOwn % 86400 === 0) { aloUnitSel = 86400; aloAmtVal = aloOwn / 86400; }
        else if (aloOwn >= 3600 && aloOwn % 3600 === 0) { aloUnitSel = 3600; aloAmtVal = aloOwn / 3600; }
        else if (aloOwn > 0) { aloUnitSel = 60; aloAmtVal = Math.max(1, Math.round(aloOwn / 60)); }
        aloAmt.value = String(aloAmtVal);
        aloUnit.value = String(aloUnitSel);
        aloUnit.addEventListener('change', () => {
            aloAmt.max = String(Math.floor(31536000 / (parseInt(aloUnit.value || '60', 10) || 60)));
        });

        aloRow.appendChild(aloAmt);
        aloRow.appendChild(aloUnit);
        aloDiv.appendChild(aloRow);

        const aloSave = document.createElement('button');
        aloSave.type = 'button';
        aloSave.className = 'btn btn-primary btn-sm';
        aloSave.style.marginTop = '8px';
        aloSave.textContent = t('auto_logout_save_btn');
        aloSave.addEventListener('click', async () => {
            const amtN = Math.max(0, parseInt(aloAmt.value || '0', 10) || 0);
            const multN = Math.max(1, parseInt(aloUnit.value || '60', 10) || 60);
            const secVal = amtN <= 0 ? 0 : Math.min(31536000, amtN * multN);
            const r = await apiCall('profile_update', { auto_logout_sec: secVal });
            if (r.ok) {
                if (r.data && r.data.user) store.user = r.data.user;
                store._autoLogoutLastActive = Date.now();
                toast(t('auto_logout_saved_toast'));
            } else {
                toast(r.message || t('err_generic'), true);
            }
        });
        aloDiv.appendChild(aloSave);

        secCard.appendChild(aloDiv);

        body.appendChild(secCard);
        body.appendChild(quotasCard);
        body.appendChild(backupZipCard);

        // Redesigned Danger Zone Card (100% Contained Inside Box on All Screens)
        const delCard = document.createElement('div');
        delCard.className = 'danger-card';
        delCard.dataset.usetCat = 'security';
        delCard.dataset.usetOrder = '90';
        const dHead = document.createElement('div');
        dHead.className = 'section-header';
        dHead.style.color = 'var(--danger)';
        dHead.textContent = t('danger_zone_sec');
        delCard.appendChild(dHead);

        const isMeSuperAdmin = (u.role === 'superadmin');
        const superDelWarnSuffix = isMeSuperAdmin ? ('\n\n' + t('superadmin_del_modal_warn')) : '';

        const dDesc = document.createElement('p');
        dDesc.style.cssText = 'font-size:12.5px;color:var(--text-secondary);margin:0 0 12px;line-height:1.5';
        dDesc.textContent = t('danger_zone_desc');
        delCard.appendChild(dDesc);

        if (isMeSuperAdmin) {
            const saBanner = document.createElement('div');
            saBanner.className = 'superadmin-transfer-banner';
            saBanner.id = 'superadmin-del-warning-banner';
            saBanner.textContent = t('superadmin_del_banner');
            delCard.appendChild(saBanner);
        }

        const schedStatusBox = document.createElement('div');
        schedStatusBox.className = 'sched-status-box' + (u.delete_at ? ' active' : '');
        schedStatusBox.textContent = u.delete_at
            ? (t('scheduled_delete_active') + formatDate(u.delete_at))
            : t('no_sched_del_active');
        delCard.appendChild(schedStatusBox);

        const schedGrid = document.createElement('div');
        schedGrid.className = 'danger-schedule-grid';

        const sch24 = document.createElement('button');
        sch24.type = 'button';
        sch24.className = 'btn btn-secondary';
        sch24.textContent = t('sched_24h_btn');
        sch24.addEventListener('click', async () => {
            const ap = await askApproval({
                title: t('sched_24h_btn'),
                desc: t('ask_sched_acc_del') + superDelWarnSuffix,
                danger: true,
                icon: '⏳'
            });
            if (!ap.approved) return;
            const r = await apiCall('account_schedule_delete', { mode: '24h' });
            if (r.ok && r.data) {
                store.user.delete_at = r.data.delete_at;
                toast(t('acc_del_sched_toast') + formatDate(r.data.delete_at));
                close();
                openSettingsModal();
            }
        });
        schedGrid.appendChild(sch24);

        const sch7d = document.createElement('button');
        sch7d.type = 'button';
        sch7d.className = 'btn btn-secondary';
        sch7d.textContent = t('sched_7d_btn');
        sch7d.addEventListener('click', async () => {
            const ap = await askApproval({
                title: t('sched_7d_btn'),
                desc: t('ask_sched_acc_del') + superDelWarnSuffix,
                danger: true,
                icon: '⏳'
            });
            if (!ap.approved) return;
            const r = await apiCall('account_schedule_delete', { mode: '7d' });
            if (r.ok && r.data) {
                store.user.delete_at = r.data.delete_at;
                toast(t('acc_del_sched_toast') + formatDate(r.data.delete_at));
                close();
                openSettingsModal();
            }
        });
        schedGrid.appendChild(sch7d);
        delCard.appendChild(schedGrid);

        // Custom Time (Hours / Days) Scheduled Account Deletion Control
        const customSchedBox = document.createElement('div');
        customSchedBox.style.cssText = 'background:var(--bg-surface);border:1px solid var(--border);border-radius:var(--radius-sm);padding:10px;margin:8px 0 10px;display:flex;flex-direction:column;gap:8px';
        const customSchedLbl = document.createElement('label');
        customSchedLbl.style.cssText = 'font-size:12px;font-weight:700;color:var(--text-secondary)';
        customSchedLbl.textContent = t('sched_custom_lbl');
        customSchedBox.appendChild(customSchedLbl);

        const customSchedRow = document.createElement('div');
        customSchedRow.style.cssText = 'display:flex;gap:8px;flex-wrap:wrap;align-items:center';

        const customAmtIn = document.createElement('input');
        customAmtIn.type = 'number';
        customAmtIn.id = 'user-sched-del-amount';
        customAmtIn.className = 'input';
        customAmtIn.min = '1';
        customAmtIn.max = '3650';
        customAmtIn.step = '1';
        customAmtIn.value = '12';
        customAmtIn.dir = 'ltr';
        customAmtIn.style.cssText = 'width:96px;flex:0 0 96px;text-align:center;font-weight:700';

        const customUnitSel = document.createElement('select');
        customUnitSel.id = 'user-sched-del-unit';
        customUnitSel.className = 'input';
        customUnitSel.style.cssText = 'flex:1;min-width:140px';
        [['hours', t('sched_unit_hours')], ['days', t('sched_unit_days')]].forEach(([uv, ul]) => {
            const o = document.createElement('option');
            o.value = uv;
            o.textContent = ul;
            customUnitSel.appendChild(o);
        });

        const customApplyBtn = document.createElement('button');
        customApplyBtn.type = 'button';
        customApplyBtn.id = 'btn-user-sched-custom';
        customApplyBtn.className = 'btn btn-secondary';
        customApplyBtn.style.cssText = 'flex:1 1 auto;white-space:nowrap';
        customApplyBtn.textContent = t('sched_custom_apply_btn');
        customApplyBtn.addEventListener('click', async () => {
            const amt = parseFloat(customAmtIn.value);
            if (!Number.isFinite(amt) || amt <= 0) {
                toast(t('sched_custom_invalid_toast'), true);
                customAmtIn.focus();
                return;
            }
            const unitVal = customUnitSel.value === 'days' ? 'days' : 'hours';
            const unitText = unitVal === 'days' ? t('sched_unit_days') : t('sched_unit_hours');
            const ap = await askApproval({
                title: t('sched_custom_apply_btn'),
                desc: `${t('ask_sched_acc_del')}\n⏳ ${formatLocalizedCount(amt)} ${unitText}${superDelWarnSuffix}`,
                danger: true,
                icon: '⏳'
            });
            if (!ap.approved) return;
            customApplyBtn.disabled = true;
            const r = await apiCall('account_schedule_delete', { amount: amt, unit: unitVal });
            customApplyBtn.disabled = false;
            if (r.ok && r.data) {
                store.user.delete_at = r.data.delete_at;
                toast(t('acc_del_sched_toast') + formatDate(r.data.delete_at));
                close();
                openSettingsModal();
            } else {
                toast((r && r.message) || t('err_generic'), true);
            }
        });

        customSchedRow.appendChild(customAmtIn);
        customSchedRow.appendChild(customUnitSel);
        customSchedRow.appendChild(customApplyBtn);
        customSchedBox.appendChild(customSchedRow);
        delCard.appendChild(customSchedBox);

        // Always-visible Cancel Scheduled Account Deletion Button (ALWAYS prompts confirmation popup)
        const cancelSchedAccBtn = document.createElement('button');
        cancelSchedAccBtn.type = 'button';
        cancelSchedAccBtn.id = 'btn-cancel-sched-acc';
        cancelSchedAccBtn.className = u.delete_at ? 'btn btn-primary btn-block' : 'btn btn-secondary btn-block';
        cancelSchedAccBtn.style.marginBottom = '10px';
        cancelSchedAccBtn.textContent = t('cancel_sched_acc_btn');
        cancelSchedAccBtn.addEventListener('click', async () => {
            const ap = await askApproval({
                title: t('cancel_sched_acc_btn'),
                desc: u.delete_at
                    ? `${t('ask_cancel_acc_del')}\n⏳ ${formatDate(u.delete_at)}`
                    : t('ask_cancel_acc_del_none'),
                checkboxLabel: t('confirm_cancel_sched_acc_chk'),
                checkboxRequired: true,
                danger: false,
                icon: '✅'
            });
            if (!ap.approved) return;
            const r = await apiCall('account_delete_cancel', { confirmed: 1 });
            if (r.ok) {
                store.user.delete_at = null;
                toast(t('sched_acc_cancelled_toast'));
                close();
                openSettingsModal();
            }
        });
        delCard.appendChild(cancelSchedAccBtn);

        const panicBtn = document.createElement('button');
        panicBtn.type = 'button';
        panicBtn.id = 'btn-delete-account-now';
        panicBtn.className = 'btn btn-danger danger-panic-btn';
        panicBtn.textContent = t('panic_wipe_btn');
        panicBtn.addEventListener('click', async () => {
            const ap = await askApproval({
                title: t('panic_wipe_btn'),
                desc: t('ask_panic_acc_wipe') + superDelWarnSuffix,
                checkboxLabel: t('confirm_understand_chk'),
                checkboxRequired: true,
                danger: true,
                icon: '🚨'
            });
            if (!ap.approved) return;
            const r = await apiCall('account_delete_now', { confirmed: 1 });
            if (r.ok) {
                await E2EE.wipeLocalKeys();
                localStorage.clear();
                clearAllAuthFormsCompletely(true);
                location.reload();
            } else {
                toast(r.message || t('err_generic'), true);
            }
        });
        delCard.appendChild(panicBtn);

        const resetUsetCard = document.createElement('div');
        resetUsetCard.className = 'card-box';
        resetUsetCard.dataset.usetCat = 'profile appearance privacy';
        resetUsetCard.dataset.usetOrder = '100';
        const ruHead = document.createElement('div');
        ruHead.className = 'section-header';
        ruHead.textContent = t('uset_reset_sec_title');
        const ruDesc = document.createElement('p');
        ruDesc.style.cssText = 'font-size:12.5px;color:var(--text-secondary);margin:0 0 10px;line-height:1.55';
        ruDesc.textContent = t('uset_reset_sec_desc');
        const ruBtn = document.createElement('button');
        ruBtn.type = 'button';
        ruBtn.id = 'btn-user-reset-settings';
        ruBtn.className = 'btn btn-secondary btn-sm';
        ruBtn.textContent = t('uset_reset_btn');
        ruBtn.addEventListener('click', async () => {
            const ap = await askApproval({
                title: t('uset_reset_sec_title'),
                desc: t('uset_reset_sec_desc'),
                checkboxLabel: t('uset_reset_chk_lbl'),
                checkboxRequired: true,
                danger: false,
                icon: '🔄'
            });
            if (!ap.approved) return;
            const rr = await apiCall('user_settings_reset', { confirmed: 1 });
            if (rr.ok && rr.data && rr.data.user) {
                store.user = rr.data.user;
                store.cal = store.user.cal || 'jalali';
                localStorage.setItem('pm_cal', store.cal);
                applyLangAndTheme(getLoginLangForUser(store.user.lang, store.lang), store.user.theme || 'auto');
                renderSelfDock();
                renderChatList();
                renderActiveChatHeader();
                syncTtlControlUI();
                toast(t('uset_reset_done_toast'));
                openSettingsModal();
            } else {
                toast(rr.message || t('err_generic'), true);
            }
        });
        resetUsetCard.appendChild(ruHead);
        resetUsetCard.appendChild(ruDesc);
        resetUsetCard.appendChild(ruBtn);
        body.appendChild(resetUsetCard);

        body.appendChild(delCard);

        // Item #11: Place all 'data' (Quota & Backup) cards immediately after 'profile' cards in DOM order!
        const profileCards = Array.from(body.querySelectorAll('[data-uset-cat="profile"]'));
        const dataCards = Array.from(body.querySelectorAll('[data-uset-cat="data"]'));
        if (profileCards.length > 0 && dataCards.length > 0) {
            let anchorAfter = profileCards[profileCards.length - 1];
            dataCards.forEach(dc => {
                body.insertBefore(dc, anchorAfter.nextSibling);
                anchorAfter = dc;
            });
        }

        // Developer & GitHub Suggestions Footer (lowest section in User Settings for every user)
        const creditsFooter = document.createElement('div');
        creditsFooter.className = 'settings-credits-footer';

        const devLine = document.createElement('p');
        devLine.className = 'settings-credits-line';
        const devPrefix = document.createElement('span');
        devPrefix.setAttribute('data-i18n', 'settings_dev_prefix');
        devPrefix.textContent = t('settings_dev_prefix');
        const devLink = document.createElement('a');
        devLink.className = 'settings-credit-link';
        devLink.href = 'https://mehdisayyadnahed.ir';
        devLink.target = '_blank';
        devLink.rel = 'noopener noreferrer';
        devLink.setAttribute('data-i18n', 'settings_dev_name');
        devLink.textContent = t('settings_dev_name');
        const devSuffix = document.createElement('span');
        devSuffix.setAttribute('data-i18n', 'settings_dev_suffix');
        devSuffix.textContent = t('settings_dev_suffix');
        devLine.appendChild(devPrefix);
        devLine.appendChild(devLink);
        devLine.appendChild(devSuffix);

        const ghLine = document.createElement('p');
        ghLine.className = 'settings-credits-line';
        const ghPrefix = document.createElement('span');
        ghPrefix.setAttribute('data-i18n', 'settings_github_prefix');
        ghPrefix.textContent = t('settings_github_prefix');

        const ghInline = document.createElement('span');
        ghInline.className = 'settings-github-inline';

        const svgNS = 'http://www.w3.org/2000/svg';
        const ghSvg = document.createElementNS(svgNS, 'svg');
        ghSvg.setAttribute('class', 'settings-github-logo');
        ghSvg.setAttribute('viewBox', '0 0 16 16');
        ghSvg.setAttribute('width', '16');
        ghSvg.setAttribute('height', '16');
        ghSvg.setAttribute('aria-hidden', 'true');
        const ghPath = document.createElementNS(svgNS, 'path');
        ghPath.setAttribute('fill', 'currentColor');
        ghPath.setAttribute('d', 'M8 0c4.42 0 8 3.58 8 8a8.013 8.013 0 0 1-5.45 7.59c-.4.08-.55-.17-.55-.38 0-.27.01-1.13.01-2.2 0-.75-.25-1.23-.54-1.48 1.78-.2 3.65-.88 3.65-3.95 0-.88-.31-1.59-.82-2.15.08-.2.36-1.02-.08-2.12 0 0-.67-.22-2.2.82-.64-.18-1.32-.27-2-.27-.68 0-1.36.09-2 .27-1.53-1.03-2.2-.82-2.2-.82-.44 1.1-.16 1.92-.08 2.12-.51.56-.82 1.28-.82 2.15 0 3.06 1.86 3.75 3.64 3.95-.23.2-.44.55-.51 1.07-.46.21-1.61.55-2.33-.66-.15-.24-.6-.83-1.23-.82-.67.01-.27.38.01.53.34.19.73.9.82 1.13.16.45.68 1.31 2.69.94 0 .67.01 1.3.01 1.49 0 .21-.15.45-.55.38A7.995 7.995 0 0 1 0 8c0-4.42 3.58-8 8-8Z');
        ghSvg.appendChild(ghPath);

        const ghLink = document.createElement('a');
        ghLink.className = 'settings-credit-link';
        ghLink.href = 'https://github.com/mehdisayyadnahed/my-mini-messenger';
        ghLink.target = '_blank';
        ghLink.rel = 'noopener noreferrer';
        ghLink.setAttribute('data-i18n', 'settings_github_name');
        ghLink.textContent = t('settings_github_name');

        ghInline.appendChild(ghLink);
        ghInline.appendChild(ghSvg);
        ghLine.appendChild(ghPrefix);
        ghLine.appendChild(ghInline);

        // UX: in the "All sections" view, keep cards grouped in the same order as the
        // category pills (Profile -> Appearance -> Data -> Privacy -> Security -> Reset)
        // instead of the raw creation order, which interleaved unrelated groups.
        const rankOfUsetCard = (el) => {
            const v = parseInt(el.dataset.usetOrder || '999', 10);
            return isNaN(v) ? 999 : v;
        };
        Array.from(body.querySelectorAll('[data-uset-cat]'))
            .sort((a, b) => rankOfUsetCard(a) - rankOfUsetCard(b))
            .forEach(el => body.appendChild(el));

        const versionLine = document.createElement('p');
        versionLine.className = 'settings-credits-line settings-credits-version';
        versionLine.setAttribute('data-i18n', 'settings_app_version');
        versionLine.textContent = t('settings_app_version');

        creditsFooter.appendChild(versionLine);
        creditsFooter.appendChild(devLine);
        creditsFooter.appendChild(ghLine);
        body.appendChild(creditsFooter);
    });
}


/* ---------------- REDESIGNED ADMIN CONTROL CENTER (CLEAN, MOBILE-SAFE & 100% BILINGUAL) ---------------- */
async function renderAdminAnalyticsTab(container) {
    container.innerHTML = '';
    let activeRange = '7d';
    let activeMetric = 'messages';
    const nowSecInit = Math.floor(Date.now() / 1000);
    let customStartDaySec = Math.floor((nowSecInit - 6 * 86400) / 86400) * 86400;
    let customEndDaySec = Math.floor(nowSecInit / 86400) * 86400;
    let customFromTime = '00:00';
    let customToTime = '23:59';
    let calPickingStep = 0;

    const headCard = document.createElement('div');
    headCard.className = 'card-box';
    const hTop = document.createElement('div');
    hTop.style.cssText = 'display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:10px;margin-bottom:10px';
    const hLeft = document.createElement('div');
    hLeft.innerHTML = `<div style="font-weight:900;font-size:15px">${esc(t('adm_an_title'))}</div><div style="font-size:11.5px;color:var(--text-muted);margin-top:2px">${esc(t('adm_an_subtitle'))}</div>`;
    const copyBtn = document.createElement('button');
    copyBtn.type = 'button';
    copyBtn.id = 'btn-adm-analytics-copy';
    copyBtn.className = 'btn btn-secondary btn-sm';
    copyBtn.textContent = t('adm_an_export_json_btn');
    hTop.appendChild(hLeft);
    hTop.appendChild(copyBtn);
    headCard.appendChild(hTop);

    const toolbar = document.createElement('div');
    toolbar.className = 'adm-analytics-toolbar';
    const rangeDefs = [
        ['1h', 'adm_an_range_1h'],
        ['24h', 'adm_an_range_24h'],
        ['7d', 'adm_an_range_7d'],
        ['30d', 'adm_an_range_30d'],
        ['90d', 'adm_an_range_90d'],
        ['180d', 'adm_an_range_180d'],
        ['1y', 'adm_an_range_1y'],
        ['all', 'adm_an_range_all'],
        ['custom', 'adm_an_range_custom']
    ];

    const calDrawer = document.createElement('div');
    calDrawer.id = 'adm-analytics-cal-drawer';
    calDrawer.className = 'adm-cal-drawer hidden';

    const resultsBox = document.createElement('div');
    let lastReportPayload = null;

    copyBtn.addEventListener('click', () => {
        if (!lastReportPayload) return;
        copyTextToClipboard(JSON.stringify(lastReportPayload, null, 2));
        toast(t('adm_an_copied_toast'));
    });

    const isJalali = () => (store.cal || 'jalali') === 'jalali';
    const initDate = new Date();
    let viewYear = isJalali() ? gregorianToJalali(initDate.getFullYear(), initDate.getMonth() + 1, initDate.getDate())[0] : initDate.getFullYear();
    let viewMonth = isJalali() ? gregorianToJalali(initDate.getFullYear(), initDate.getMonth() + 1, initDate.getDate())[1] : (initDate.getMonth() + 1);

    const jMonthsFa = ['فروردین','اردیبهشت','خرداد','تیر','مرداد','شهریور','مهر','آبان','آذر','دی','بهمن','اسفند'];
    const jMonthsEn = ['Farvardin','Ordibehesht','Khordad','Tir','Mordad','Shahrivar','Mehr','Aban','Azar','Dey','Bahman','Esfand'];
    const gMonthsFa = ['ژانویه','فوریه','مارس','آوریل','مه','ژوئن','ژوئیه','اوت','سپتامبر','اکتبر','نوامبر','دسامبر'];
    const gMonthsEn = ['January','February','March','April','May','June','July','August','September','October','November','December'];

    const computeCustomBounds = () => {
        const [fh, fm] = String(customFromTime || '00:00').split(':').map(n => parseInt(n, 10) || 0);
        const [th, tm] = String(customToTime || '23:59').split(':').map(n => parseInt(n, 10) || 0);
        const sDay = Math.min(customStartDaySec, customEndDaySec);
        const eDay = Math.max(customStartDaySec, customEndDaySec);
        const dStart = new Date(sDay * 1000);
        dStart.setHours(fh, fm, 0, 0);
        const dEnd = new Date(eDay * 1000);
        dEnd.setHours(th, tm, 59, 0);
        return {
            from_ts: Math.floor(dStart.getTime() / 1000),
            to_ts: Math.max(Math.floor(dStart.getTime() / 1000) + 60, Math.floor(dEnd.getTime() / 1000))
        };
    };

    const renderCalendarDrawer = () => {
        calDrawer.innerHTML = '';
        const jal = isJalali();
        const nav = document.createElement('div');
        nav.style.cssText = 'display:flex;align-items:center;justify-content:space-between;margin-bottom:8px;gap:8px';
        const prevBtn = document.createElement('button');
        prevBtn.type = 'button';
        prevBtn.className = 'btn btn-secondary btn-sm';
        prevBtn.textContent = store.lang === 'fa' ? '‹' : '‹';
        const nextBtn = document.createElement('button');
        nextBtn.type = 'button';
        nextBtn.className = 'btn btn-secondary btn-sm';
        nextBtn.textContent = store.lang === 'fa' ? '›' : '›';
        const mTitle = document.createElement('div');
        mTitle.style.cssText = 'font-weight:900;font-size:13.5px';
        const mNames = jal ? (store.lang === 'fa' ? jMonthsFa : jMonthsEn) : (store.lang === 'fa' ? gMonthsFa : gMonthsEn);
        mTitle.textContent = `${mNames[viewMonth - 1]} ${formatLocalizedCount(viewYear)}`;

        prevBtn.addEventListener('click', () => {
            viewMonth--;
            if (viewMonth < 1) { viewMonth = 12; viewYear--; }
            renderCalendarDrawer();
        });
        nextBtn.addEventListener('click', () => {
            viewMonth++;
            if (viewMonth > 12) { viewMonth = 1; viewYear++; }
            renderCalendarDrawer();
        });
        nav.appendChild(prevBtn);
        nav.appendChild(mTitle);
        nav.appendChild(nextBtn);
        calDrawer.appendChild(nav);

        const grid = document.createElement('div');
        grid.className = 'adm-cal-grid';
        const wds = jal
            ? (store.lang === 'fa' ? ['ش','ی','د','س','چ','پ','ج'] : ['Sa','Su','Mo','Tu','We','Th','Fr'])
            : (store.lang === 'fa' ? ['ی','د','س','چ','پ','ج','ش'] : ['Su','Mo','Tu','We','Th','Fr','Sa']);
        wds.forEach(w => {
            const c = document.createElement('div');
            c.className = 'adm-cal-wd';
            c.textContent = w;
            grid.appendChild(c);
        });

        let daysInMonth = 30;
        let firstWeekdayOffset = 0;
        if (jal) {
            daysInMonth = getJalaliMonthDays(viewYear, viewMonth);
            const [gy, gm, gd] = jalaliToGregorian(viewYear, viewMonth, 1);
            const jsDow = new Date(gy, gm - 1, gd).getDay();
            firstWeekdayOffset = (jsDow + 1) % 7;
        } else {
            daysInMonth = new Date(viewYear, viewMonth, 0).getDate();
            firstWeekdayOffset = new Date(viewYear, viewMonth - 1, 1).getDay();
        }

        for (let e = 0; e < firstWeekdayOffset; e++) {
            const emp = document.createElement('div');
            emp.className = 'adm-cal-day is-empty';
            grid.appendChild(emp);
        }

        const minSel = Math.min(customStartDaySec, customEndDaySec);
        const maxSel = Math.max(customStartDaySec, customEndDaySec);
        const todayMid = (() => { const d = new Date(); d.setHours(0,0,0,0); return Math.floor(d.getTime() / 1000); })();

        for (let dayNum = 1; dayNum <= daysInMonth; dayNum++) {
            let gY = viewYear, gM = viewMonth, gD = dayNum;
            if (jal) [gY, gM, gD] = jalaliToGregorian(viewYear, viewMonth, dayNum);
            const cellDate = new Date(gY, gM - 1, gD, 0, 0, 0, 0);
            const daySec = Math.floor(cellDate.getTime() / 1000);

            const btn = document.createElement('button');
            btn.type = 'button';
            btn.className = 'adm-cal-day';
            btn.setAttribute('data-cal-day', String(dayNum));
            if (daySec === todayMid) btn.classList.add('is-today');
            if (daySec === minSel) btn.classList.add('is-start');
            if (daySec === maxSel) btn.classList.add('is-end');
            if (daySec > minSel && daySec < maxSel) btn.classList.add('in-range');
            btn.textContent = formatLocalizedCount(dayNum);
            btn.addEventListener('click', () => {
                if (calPickingStep === 0) {
                    customStartDaySec = daySec;
                    customEndDaySec = daySec;
                    calPickingStep = 1;
                } else {
                    if (daySec < customStartDaySec) {
                        customEndDaySec = customStartDaySec;
                        customStartDaySec = daySec;
                    } else {
                        customEndDaySec = daySec;
                    }
                    calPickingStep = 0;
                }
                renderCalendarDrawer();
            });
            grid.appendChild(btn);
        }
        calDrawer.appendChild(grid);

        const timeRow = document.createElement('div');
        timeRow.className = 'resp-grid-2';
        timeRow.style.marginTop = '10px';

        const boundsPreview = computeCustomBounds();
        const mkTimeBox = (lblTxt, curVal, previewTs, onChange) => {
            const fg = document.createElement('div');
            fg.className = 'form-group';
            fg.style.marginBottom = '6px';
            const l = document.createElement('label');
            l.style.fontSize = '11.5px';
            l.textContent = `${lblTxt} (${formatDate(previewTs, false)})`;
            const inp = document.createElement('input');
            inp.type = 'time';
            inp.className = 'input';
            inp.value = curVal;
            inp.addEventListener('change', () => onChange(inp.value || curVal));
            fg.appendChild(l);
            fg.appendChild(inp);
            return fg;
        };
        timeRow.appendChild(mkTimeBox(t('adm_an_from_lbl'), customFromTime, boundsPreview.from_ts, v => { customFromTime = v; }));
        timeRow.appendChild(mkTimeBox(t('adm_an_to_lbl'), customToTime, boundsPreview.to_ts, v => { customToTime = v; }));
        calDrawer.appendChild(timeRow);

        const applyRow = document.createElement('div');
        applyRow.style.cssText = 'display:flex;justify-content:flex-end;margin-top:6px';
        const applyBtn = document.createElement('button');
        applyBtn.type = 'button';
        applyBtn.id = 'btn-adm-analytics-apply-custom';
        applyBtn.className = 'btn btn-primary btn-sm';
        applyBtn.textContent = t('adm_an_apply_range_btn');
        applyBtn.addEventListener('click', () => loadAnalytics('custom'));
        applyRow.appendChild(applyBtn);
        calDrawer.appendChild(applyRow);
    };

    rangeDefs.forEach(([rk, lblKey]) => {
        const chip = document.createElement('button');
        chip.type = 'button';
        chip.className = 'adm-range-chip' + (rk === activeRange ? ' active' : '');
        chip.setAttribute('data-analytics-range', rk);
        chip.textContent = t(lblKey);
        chip.addEventListener('click', () => {
            activeRange = rk;
            toolbar.querySelectorAll('.adm-range-chip').forEach(c => c.classList.toggle('active', c.getAttribute('data-analytics-range') === rk));
            if (rk === 'custom') {
                calDrawer.classList.remove('hidden');
                renderCalendarDrawer();
            } else {
                calDrawer.classList.add('hidden');
                loadAnalytics(rk);
            }
        });
        toolbar.appendChild(chip);
    });

    headCard.appendChild(toolbar);
    headCard.appendChild(calDrawer);
    container.appendChild(headCard);
    container.appendChild(resultsBox);

    const buildDeltaPill = (cur, prev, hideDelta) => {
        if (hideDelta) return '';
        const c = Number(cur || 0);
        const p = Number(prev || 0);
        if (p === 0 && c === 0) return '<span class="adm-analytics-delta flat">0%</span>';
        if (p === 0 && c > 0) return '<span class="adm-analytics-delta up">+100%</span>';
        const pct = Math.round(((c - p) / p) * 100);
        const cls = pct > 0 ? 'up' : (pct < 0 ? 'down' : 'flat');
        const sign = pct > 0 ? '+' : '';
        return `<span class="adm-analytics-delta ${cls}">${sign}${pct}%</span>`;
    };

    const renderSvgChart = (chartHost, timeline, metricKey) => {
        chartHost.innerHTML = '';
        const pts = Array.isArray(timeline) ? timeline : [];
        if (!pts.length) return;
        const vals = pts.map(b => Number(b[metricKey] || 0));
        const maxVal = Math.max(1, ...vals);
        const W = 680, H = 195, padL = 36, padR = 16, padT = 18, padB = 34;
        const plotW = W - padL - padR;
        const plotH = H - padT - padB;

        const coords = pts.map((b, idx) => {
            const x = pts.length === 1 ? (padL + plotW / 2) : (padL + (idx / (pts.length - 1)) * plotW);
            const y = padT + plotH - ((Number(b[metricKey] || 0) / maxVal) * plotH);
            return { x, y, val: Number(b[metricKey] || 0), start: b.start_ts, end: b.end_ts };
        });

        const polyPts = coords.map(c => `${c.x.toFixed(1)},${c.y.toFixed(1)}`).join(' ');
        const areaPts = `${coords[0].x.toFixed(1)},${(padT + plotH).toFixed(1)} ${polyPts} ${coords[coords.length - 1].x.toFixed(1)},${(padT + plotH).toFixed(1)}`;

        let gridLines = '';
        [0, 0.5, 1].forEach(r => {
            const gy = (padT + plotH - r * plotH).toFixed(1);
            const gVal = formatLocalizedCount(Math.round(r * maxVal));
            gridLines += `<line x1="${padL}" y1="${gy}" x2="${W - padR}" y2="${gy}" stroke="currentColor" stroke-opacity="0.1" stroke-dasharray="4 4"/>`;
            gridLines += `<text x="${padL - 6}" y="${Number(gy) + 4}" text-anchor="end" font-size="10" fill="currentColor" opacity="0.6">${esc(gVal)}</text>`;
        });

        let circles = '';
        let xLabels = '';
        const stepLbl = Math.max(1, Math.ceil(coords.length / 6));
        coords.forEach((c, idx) => {
            const tip = `${formatFullTime(c.start)} → ${formatLocalizedCount(c.val)}`;
            circles += `<circle cx="${c.x.toFixed(1)}" cy="${c.y.toFixed(1)}" r="4" fill="#009687" stroke="#ffffff" stroke-width="1.8"><title>${esc(tip)}</title></circle>`;
            if (idx % stepLbl === 0 || idx === coords.length - 1) {
                const shortLbl = (c.end - c.start) <= 7200 ? formatTimeOnly(c.start) : formatDate(c.start, false);
                xLabels += `<text x="${c.x.toFixed(1)}" y="${H - 10}" text-anchor="middle" font-size="9.5" fill="currentColor" opacity="0.68">${esc(shortLbl)}</text>`;
            }
        });

        chartHost.innerHTML = `<svg viewBox="0 0 ${W} ${H}" style="width:100%;height:auto;display:block;overflow:visible">
            <defs>
                <linearGradient id="m3AnGrad" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="0%" stop-color="#009687" stop-opacity="0.34"/>
                    <stop offset="100%" stop-color="#009687" stop-opacity="0.02"/>
                </linearGradient>
            </defs>
            ${gridLines}
            <polygon points="${areaPts}" fill="url(#m3AnGrad)"/>
            <polyline points="${polyPts}" fill="none" stroke="#009687" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"/>
            ${circles}
            ${xLabels}
        </svg>`;
    };

    const loadAnalytics = async (rk) => {
        resultsBox.innerHTML = '<div style="padding:24px;text-align:center;color:var(--text-muted);font-weight:700">⏳ ...</div>';
        const reqPayload = { range: rk };
        if (rk === 'custom') Object.assign(reqPayload, computeCustomBounds());
        const r = await apiCall('admin_analytics', reqPayload);
        if (!r.ok || !r.data) {
            resultsBox.innerHTML = `<div class="card-box" style="color:var(--danger)">${esc(r.message || t('err_generic'))}</div>`;
            return;
        }
        lastReportPayload = r.data;
        const d = r.data;
        const k = d.kpis || {};
        const hideDelta = (d.range === 'all');
        resultsBox.innerHTML = '';

        // 1. KPI Summary Grid (8 comprehensive cards)
        const kpiGrid = document.createElement('div');
        kpiGrid.className = 'adm-analytics-kpi-grid';
        const addKpi = (titleTxt, mainVal, deltaHtml, subTxt) => {
            const card = document.createElement('div');
            card.className = 'adm-analytics-kpi-card';
            card.innerHTML = `
                <div style="display:flex;align-items:center;justify-content:space-between;gap:6px">
                    <span style="font-size:12px;font-weight:800;color:var(--text-secondary)">${esc(titleTxt)}</span>
                    ${deltaHtml}
                </div>
                <div class="adm-analytics-kpi-val">${esc(mainVal)}</div>
                <div class="adm-analytics-kpi-sub">${esc(subTxt)}</div>
            `;
            kpiGrid.appendChild(card);
        };

        addKpi(
            t('adm_an_kpi_msgs'),
            formatLocalizedCount(k.messages_in_range || 0),
            buildDeltaPill(k.messages_in_range, k.prev_messages_in_range, hideDelta),
            `${t('adm_an_active_senders')}: ${formatLocalizedCount(k.active_senders_in_range || 0)} • ✏️ ${formatLocalizedCount(k.edited_in_range || 0)} • ⏱️ ${formatLocalizedCount(k.ttl_in_range || 0)}`
        );
        addKpi(
            t('adm_an_kpi_users'),
            formatLocalizedCount(k.new_users_in_range || 0),
            buildDeltaPill(k.new_users_in_range, k.prev_new_users, hideDelta),
            `👥 ${formatLocalizedCount(k.total_users || 0)} • 🟢 ${formatLocalizedCount(k.online_users_now || 0)} • 24h: ${formatLocalizedCount(k.active_users_24h || 0)} • 🔐 2FA: ${formatLocalizedCount(k.totp_users_total || 0)}`
        );
        const nc = k.new_chats_by_type || {};
        addKpi(
            t('adm_an_kpi_chats'),
            formatLocalizedCount(k.new_chats_in_range || 0),
            buildDeltaPill(k.new_chats_in_range, k.prev_new_chats, hideDelta),
            `DM: ${formatLocalizedCount(nc.dm || 0)} • 🔒 ${formatLocalizedCount(nc.secret || 0)} • 👥 ${formatLocalizedCount(nc.group || 0)} • 📢 ${formatLocalizedCount(nc.channel || 0)}`
        );
        addKpi(
            t('adm_an_kpi_files'),
            `${formatLocalizedCount(k.files_in_range_count || 0)} (${formatBytes(k.files_in_range_bytes || 0)})`,
            buildDeltaPill(k.files_in_range_count, k.prev_files_count, hideDelta),
            `${t('adm_an_total_disk')}: ${formatBytes(k.total_disk_bytes || 0)} • DB: ${formatBytes(k.db_size_bytes || 0)}`
        );
        const cl = k.calls || {};
        addKpi(
            t('adm_an_kpi_calls'),
            formatLocalizedCount(cl.total || 0),
            '',
            `📞 ${formatLocalizedCount(cl.voice || 0)} • 🎥 ${formatLocalizedCount(cl.video || 0)} • ✅ ${formatLocalizedCount(cl.answered || 0)} • ↙️ ${formatLocalizedCount(cl.missed || 0)}`
        );
        const rp = k.reports || {};
        const fw = k.firewall_stats || {};
        addKpi(
            t('adm_an_kpi_moderation'),
            formatLocalizedCount(rp.total || 0),
            '',
            `⏳ ${formatLocalizedCount(rp.pending_all_time || 0)} • 🛡️ ${formatLocalizedCount(fw.total_blocked || 0)} • 🚫 ${formatLocalizedCount(k.blocked_users_total || 0)}`
        );
        addKpi(
            t('adm_an_kpi_engagement'),
            formatLocalizedCount(k.reactions_in_range || 0),
            '',
            `${t('adm_an_new_joins')}: ${formatLocalizedCount(k.new_memberships || 0)} • 📌 ${formatLocalizedCount(k.pinned_in_range || 0)}`
        );
        addKpi(
            t('adm_an_active_sessions'),
            formatLocalizedCount(k.active_sessions_total || 0),
            '',
            `+${formatLocalizedCount(k.sessions_in_range || 0)} (${formatFullTime(d.window.from_ts)} → ${formatFullTime(d.window.to_ts)})`
        );
        resultsBox.appendChild(kpiGrid);

        // 2. Interactive Multi-Metric Trend Chart
        const chartCard = document.createElement('div');
        chartCard.className = 'card-box';
        const cHead = document.createElement('div');
        cHead.style.cssText = 'display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:8px;margin-bottom:8px';
        const cTitle = document.createElement('div');
        cTitle.style.cssText = 'font-weight:800;font-size:13.5px';
        cTitle.textContent = t('adm_an_chart_title');
        const mSwitch = document.createElement('div');
        mSwitch.style.cssText = 'display:flex;gap:5px;flex-wrap:wrap';
        const svgWrap = document.createElement('div');
        svgWrap.className = 'adm-svg-chart-wrap';

        [
            ['messages', 'adm_an_metric_msgs'],
            ['new_users', 'adm_an_metric_users'],
            ['files', 'adm_an_metric_files'],
            ['calls', 'adm_an_metric_calls']
        ].forEach(([mk, ml]) => {
            const b = document.createElement('button');
            b.type = 'button';
            b.className = 'settings-sub-pill' + (mk === activeMetric ? ' active' : '');
            b.textContent = t(ml);
            b.addEventListener('click', () => {
                activeMetric = mk;
                mSwitch.querySelectorAll('.settings-sub-pill').forEach(x => x.classList.remove('active'));
                b.classList.add('active');
                renderSvgChart(svgWrap, d.timeline, activeMetric);
            });
            mSwitch.appendChild(b);
        });
        cHead.appendChild(cTitle);
        cHead.appendChild(mSwitch);
        chartCard.appendChild(cHead);
        chartCard.appendChild(svgWrap);
        renderSvgChart(svgWrap, d.timeline, activeMetric);
        resultsBox.appendChild(chartCard);

        // 3. Two-Column Breakdown: Message/Media Kinds + Active Chats & Top Groups/Channels + Top Emojis
        const splitGrid = document.createElement('div');
        splitGrid.className = 'resp-grid-2';

        const kindsCard = document.createElement('div');
        kindsCard.className = 'card-box';
        const kHead = document.createElement('div');
        kHead.className = 'section-header';
        kHead.textContent = t('adm_an_kinds_title');
        kindsCard.appendChild(kHead);

        const mkMap = d.message_kinds || {};
        const kindLabels = [
            ['text', t('adm_an_kind_text')],
            ['image', t('ctype_photo')],
            ['video', t('ctype_video')],
            ['voice', t('ctype_voice')],
            ['video_note', t('ctype_video_note')],
            ['audio', t('ctype_audio')],
            ['file', t('ctype_document')],
            ['call_log', t('adm_an_kpi_calls')],
            ['system', t('adm_an_kind_system')]
        ];
        const totalKindCount = Math.max(1, kindLabels.reduce((acc, [key]) => acc + Number((mkMap[key] && mkMap[key].count) || 0), 0));
        kindLabels.forEach(([key, lbl]) => {
            const obj = mkMap[key] || { count: 0, bytes: 0 };
            const cnt = Number(obj.count || 0);
            const pct = Math.min(100, Math.round((cnt / totalKindCount) * 100));
            const row = document.createElement('div');
            row.className = 'adm-bar-row';
            const szPart = Number(obj.bytes || 0) > 0 ? ` • ${formatBytes(obj.bytes)}` : '';
            row.innerHTML = `
                <div style="display:flex;justify-content:space-between;font-size:12px;font-weight:700">
                    <span>${esc(lbl)}</span>
                    <span>${esc(formatLocalizedCount(cnt))}${esc(szPart)} (${formatLocalizedCount(pct)}%)</span>
                </div>
                <div class="adm-bar-track"><div class="adm-bar-fill" style="width:${pct}%"></div></div>
            `;
            kindsCard.appendChild(row);
        });
        splitGrid.appendChild(kindsCard);

        const rightCol = document.createElement('div');
        rightCol.style.cssText = 'display:flex;flex-direction:column;gap:12px';

        const distCard = document.createElement('div');
        distCard.className = 'card-box';
        const tcAll = k.total_chats_by_type || {};
        distCard.innerHTML = `
            <div class="section-header">${esc(t('adm_an_chats_dist_title'))}</div>
            <div style="display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;font-size:12.5px;font-weight:700">
                <div style="padding:8px 10px;border-radius:10px;background:var(--bg-subtle)">💬 DM: <strong>${esc(formatLocalizedCount(tcAll.dm || 0))}</strong></div>
                <div style="padding:8px 10px;border-radius:10px;background:var(--bg-subtle)">🔒 Secret: <strong>${esc(formatLocalizedCount(tcAll.secret || 0))}</strong></div>
                <div style="padding:8px 10px;border-radius:10px;background:var(--bg-subtle)">👥 ${esc(stripLeadingEmoji(t('nc_type_group')))}: <strong>${esc(formatLocalizedCount(tcAll.group || 0))}</strong></div>
                <div style="padding:8px 10px;border-radius:10px;background:var(--bg-subtle)">📢 ${esc(stripLeadingEmoji(t('nc_type_channel')))}: <strong>${esc(formatLocalizedCount(tcAll.channel || 0))}</strong></div>
            </div>
        `;
        rightCol.appendChild(distCard);

        const topCard = document.createElement('div');
        topCard.className = 'card-box';
        const topHead = document.createElement('div');
        topHead.className = 'section-header';
        topHead.textContent = t('adm_an_top_chats_title');
        topCard.appendChild(topHead);
        const topChats = Array.isArray(d.top_chats) ? d.top_chats : [];
        if (!topChats.length) {
            const emp = document.createElement('div');
            emp.style.cssText = 'font-size:12px;color:var(--text-muted)';
            emp.textContent = t('adm_an_top_chats_empty');
            topCard.appendChild(emp);
        } else {
            topChats.forEach(tc => {
                const rItem = document.createElement('div');
                rItem.style.cssText = 'display:flex;align-items:center;justify-content:space-between;gap:8px;padding:6px 0;border-bottom:1px solid var(--border);font-size:12.5px';
                const icon = tc.type === 'channel' ? '📢' : '👥';
                rItem.innerHTML = `<span style="font-weight:700;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${icon} ${esc(tc.title || '')}</span><span class="adm-badge-pill primary">${esc(formatLocalizedCount(tc.msg_count))} 💬 • ${esc(formatMemberCount(tc.member_count))} 👤</span>`;
                topCard.appendChild(rItem);
            });
        }
        rightCol.appendChild(topCard);

        const emoCard = document.createElement('div');
        emoCard.className = 'card-box';
        const emoHead = document.createElement('div');
        emoHead.className = 'section-header';
        emoHead.textContent = t('adm_an_top_emojis_title');
        emoCard.appendChild(emoHead);
        const topEmos = Array.isArray(d.top_emojis) ? d.top_emojis : [];
        if (!topEmos.length) {
            const empE = document.createElement('div');
            empE.style.cssText = 'font-size:12px;color:var(--text-muted)';
            empE.textContent = t('adm_an_top_emojis_empty');
            emoCard.appendChild(empE);
        } else {
            const emoWrap = document.createElement('div');
            emoWrap.style.cssText = 'display:flex;flex-wrap:wrap;gap:6px';
            topEmos.forEach(em => {
                const pill = document.createElement('span');
                pill.className = 'adm-badge-pill';
                pill.style.fontSize = '13px';
                pill.textContent = `${em.emoji} × ${formatLocalizedCount(em.count)}`;
                emoWrap.appendChild(pill);
            });
            emoCard.appendChild(emoWrap);
        }
        rightCol.appendChild(emoCard);

        splitGrid.appendChild(rightCol);
        resultsBox.appendChild(splitGrid);
    };

    await loadAnalytics(activeRange);
}

function openAdminPanelModal(initialTab = 'dashboard') {
    if (!store.user || store.user.role !== 'superadmin') return;

    openModal('🛡️ ' + t('admin_panel'), (body, close) => {
        const hubHead = document.createElement('div');
        hubHead.className = 'adm-hub-header';
        const hubLeft = document.createElement('div');
        hubLeft.style.cssText = 'display:flex;align-items:center;gap:10px;min-width:0';
        const hubLogo = document.createElement('span');
        hubLogo.className = 'brand-logo has-custom-logo';
        const lImg = document.createElement('img');
        lImg.src = getEffectiveSiteLogoUri();
        lImg.alt = 'Logo';
        hubLogo.appendChild(lImg);
        const hubTexts = document.createElement('div');
        hubTexts.style.minWidth = '0';
        hubTexts.innerHTML = `<div style="font-weight:800;font-size:15px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${esc(formatSiteName())}</div><div style="font-size:11.5px;color:var(--text-muted)">🛡️ ${esc(t('admin_panel'))}</div>`;
        hubLeft.appendChild(hubLogo);
        hubLeft.appendChild(hubTexts);
        const hubRight = document.createElement('span');
        hubRight.className = 'adm-badge-pill primary';
        hubRight.textContent = 'M3 Admin Hub';
        hubHead.appendChild(hubLeft);
        hubHead.appendChild(hubRight);
        body.appendChild(hubHead);

        // Item #24: Global Cross-Tab Admin Panel Search Bar (searches across ALL Admin Panel tabs & settings)
        const globalSearchWrap = document.createElement('div');
        globalSearchWrap.className = 'settings-live-search-wrap';
        globalSearchWrap.style.marginBottom = '8px';
        const globalSearchIn = document.createElement('input');
        globalSearchIn.type = 'search';
        globalSearchIn.id = 'admin-global-hub-search';
        globalSearchIn.className = 'input';
        globalSearchIn.placeholder = t('adm_global_search_ph');
        globalSearchWrap.appendChild(globalSearchIn);
        const globalSearchJumpRow = document.createElement('div');
        globalSearchJumpRow.className = 'resp-action-row hidden';
        globalSearchJumpRow.style.cssText = 'margin:0 0 8px;gap:6px;align-items:center';
        body.appendChild(globalSearchWrap);
        body.appendChild(globalSearchJumpRow);

        const tabsBar = document.createElement('div');
        tabsBar.className = 'adm-nav-pills';

        const tabContent = document.createElement('div');

        if (initialTab === 'chats') initialTab = 'groups';
        const tabs = [
            ['dashboard', t('adm_tab_dashboard')],
            ['analytics', t('adm_tab_analytics')],
            ['users', t('adm_tab_users')],
            ['lineage', t('adm_tab_lineage')],
            ['reports', t('adm_tab_reports')],
            ['groups', t('adm_tab_groups_sep')],
            ['channels', t('adm_tab_channels_sep')],
            ['dm_chats', t('adm_tab_dms_sep')],
            ['storage', t('adm_tab_storage_clean')],
            ['emergency', t('adm_tab_emergency')],
            ['settings', t('adm_tab_settings_only')],
            ['backup', t('adm_tab_backup_restore')]
        ];
        const ADM_TAB_SEARCH_INDEX = {
            dashboard: 'داشبورد سلامت سرور آنلاین آمار پیام رم دیسک پایگاه‌داده dashboard health kpi online stats',
            analytics: 'آمار گزارشات تحلیلی نمودار بازه زمانی تقویم پیام کاربران فایل تماس واکنش analytics reports charts calendar range metrics',
            users: 'کاربران آنلاین آخرین بازدید مسدود نشست رمز کد بازیابی سهمیه ترافیک دو مرحله‌ای users online last seen sessions force password reset quota 2fa',
            lineage: 'درخت دعوت کدهای دعوت معرف شاخه lineage invite codes referral tree',
            reports: 'گزارش‌ها تخلف بررسی روح گفتگو reports moderation ghost',
            groups: 'گروه‌ها ظرفیت اعضا مشاهده‌کنندگان پیام groups members capacity viewers',
            channels: 'کانال‌ها ظرفیت اعضا مشاهده‌کنندگان پیام channels members capacity viewers',
            dm_chats: 'چت‌های دوطرفه شخصی محرمانه dm secret chats block',
            storage: 'فضا ترافیک پاکسازی فایل‌های قدیمی حجم مصرفی سهمیه storage traffic cleanup purge quota',
            emergency: 'پاکسازی اضطراری رمز اضطراری زمان‌بندی حذف کل پیام‌رسان emergency panic wipe duress',
            settings: 'تنظیمات عمومی فایروال کپچا ضدربات هانی‌پات پیش‌نویس حذف خودکار تماس ساعت منطقه زمانی لوگو نام سامانه کوکی آخرین بازدید انتقال سوپرادمین خودگردانی firewall captcha honeypot draft sync ttl branding timezone cookie governance autonomous',
            backup: 'پشتیبان‌گیری بازنشانی مهاجرت پایگاه‌داده sqlite mysql زیست‌بوم فایل m3b backup restore migrate database'
        };
        let currentRenderedAdmTab = initialTab;
        // Every kind of card any admin tab can put on screen, so the search is
        // not limited to the settings tab.
        const ADM_SEARCH_CARD_SEL = '.card-box, .danger-card, .adm-user-card, .adm-item-card, .adm-stat-card, .settings-save-bar';
        const admNodeHaystack = (el) => {
            const parts = [el.textContent || ''];
            el.querySelectorAll('input, textarea, select').forEach(inp => {
                if (inp.placeholder) parts.push(inp.placeholder);
                if (inp.type !== 'password' && inp.value) parts.push(inp.value);
                if (inp.tagName === 'SELECT') {
                    Array.from(inp.options || []).forEach(o => parts.push(o.textContent || ''));
                }
            });
            return parts.join(' ').toLowerCase();
        };
        let admAutoJumpQ = '';
        let admAutoJumpTimer = null;
        const applyGlobalAdminSearch = () => {
            const q = globalSearchIn.value.trim().toLowerCase();
            globalSearchJumpRow.innerHTML = '';
            if (admAutoJumpTimer) { clearTimeout(admAutoJumpTimer); admAutoJumpTimer = null; }
            if (!q) {
                globalSearchJumpRow.classList.add('hidden');
                tabContent.querySelectorAll(ADM_SEARCH_CARD_SEL).forEach(el => el.classList.remove('hidden'));
                if (typeof tabContent._admSubSync === 'function') tabContent._admSubSync();
                admAutoJumpQ = '';
                return;
            }
            const matchedTabs = tabs.filter(([tid, tlbl]) => {
                const hay = (tlbl + ' ' + (ADM_TAB_SEARCH_INDEX[tid] || '')).toLowerCase();
                return hay.includes(q);
            });
            if (matchedTabs.length > 0) {
                const lbl = document.createElement('span');
                lbl.style.cssText = 'font-size:11.5px;font-weight:700;color:var(--text-muted)';
                lbl.textContent = t('adm_global_search_jump_lbl');
                globalSearchJumpRow.appendChild(lbl);
                matchedTabs.forEach(([tid, tlbl]) => {
                    const chip = document.createElement('button');
                    chip.type = 'button';
                    chip.className = 'settings-sub-pill' + (tid === currentRenderedAdmTab ? ' active' : '');
                    chip.textContent = tlbl;
                    chip.addEventListener('click', async () => {
                        await renderTab(tid);
                        applyGlobalAdminSearch();
                    });
                    globalSearchJumpRow.appendChild(chip);
                });
                globalSearchJumpRow.classList.remove('hidden');
            } else {
                globalSearchJumpRow.classList.add('hidden');
            }
            // Filter whatever is on screen right now, whatever kind of card the
            // current tab happened to build.
            let localHits = 0;
            tabContent.querySelectorAll(ADM_SEARCH_CARD_SEL).forEach(card => {
                const hit = admNodeHaystack(card).includes(q);
                card.classList.toggle('hidden', !hit);
                if (hit) localHits++;
            });
            // Nothing on this tab: move to the most relevant one, so the search
            // really covers every section instead of only the settings tab.
            if (localHits === 0 && matchedTabs.length > 0 && admAutoJumpQ !== q) {
                const target = matchedTabs.find(([tid]) => tid !== currentRenderedAdmTab);
                if (target) {
                    admAutoJumpQ = q;
                    admAutoJumpTimer = setTimeout(() => {
                        admAutoJumpTimer = null;
                        renderTab(target[0]).then(() => applyGlobalAdminSearch()).catch(() => {});
                    }, 320);
                }
            }
        };
        globalSearchIn.addEventListener('input', applyGlobalAdminSearch);

        let admDefaultPageSize = 20;
        let admLiveClockTimer = null;

        const renderTab = async (tabId) => {
            if (tabId === 'chats') tabId = 'groups';
            currentRenderedAdmTab = tabId;
            if (admLiveClockTimer) {
                clearInterval(admLiveClockTimer);
                admLiveClockTimer = null;
            }
            Array.from(tabsBar.children).forEach(el => {
                el.classList.toggle('active', el.dataset.tab === tabId);
            });
            tabContent.innerHTML = '<div style="padding:28px;text-align:center;color:var(--text-muted);font-weight:700">⏳ ...</div>';

            if (tabId === 'analytics') {
                await renderAdminAnalyticsTab(tabContent);
                return;
            }

            if (tabId === 'dashboard') {
                const res = await apiCall('admin_stats');
                const hRes = await apiCall('admin_health');
                tabContent.innerHTML = '';
                if (!res.ok) return;
                const d = res.data;

                if (d.messenger_delete_at && Number(d.messenger_delete_at) > 0) {
                    const warnBox = document.createElement('div');
                    warnBox.className = 'sched-status-box active';
                    const wTxt = document.createElement('span');
                    wTxt.textContent = t('adm_msg_sched_active') + formatDate(d.messenger_delete_at);
                    const wCancel = document.createElement('button');
                    wCancel.type = 'button';
                    wCancel.className = 'btn btn-secondary btn-sm';
                    wCancel.textContent = t('adm_msg_cancel_wipe_btn');
                    wCancel.addEventListener('click', async () => {
                        const ap = await askApproval({
                            title: t('adm_msg_cancel_wipe_btn'),
                            desc: `${t('ask_adm_cancel_wipe')}\n⏳ ${formatDate(d.messenger_delete_at)}`,
                            checkboxLabel: t('confirm_cancel_sched_msg_chk'),
                            checkboxRequired: true,
                            danger: false,
                            icon: '✅'
                        });
                        if (!ap.approved) return;
                        await apiCall('admin_messenger_cancel_wipe', { confirmed: 1 });
                        if (store.settings) store.settings.messenger_delete_at = 0;
                        toast(t('adm_msg_wipe_cancel_toast'));
                        renderTab('dashboard');
                    });
                    warnBox.appendChild(wTxt);
                    warnBox.appendChild(wCancel);
                    tabContent.appendChild(warnBox);
                }

                // 1. Executive KPI Grid with Icons (including Live Online Users — Item #19)
                const grid = document.createElement('div');
                grid.className = 'adm-kpi-grid';
                [
                    ['🟢', t('adm_kpi_online_users'), formatLocalizedCount(d.online_users || 0)],
                    ['👥', t('adm_kpi_users'), d.users],
                    ['💬', t('adm_kpi_chats'), d.chats],
                    ['📨', t('adm_kpi_msgs_today'), d.messages_today],
                    ['🚩', t('adm_kpi_reports'), d.pending_reports],
                    ['📡', t('adm_traffic_sec_title'), formatBytes((d.system_traffic && d.system_traffic.used_bytes) || 0)],
                    ['💾', t('adm_kpi_storage'), formatBytes(d.disk_usage_bytes || 0)],
                    ['🗄️', t('adm_kpi_db'), formatBytes(d.db_size_bytes || 0)]
                ].forEach(([icon, lbl, val]) => {
                    const c = document.createElement('div');
                    c.className = 'adm-kpi';
                    const icDiv = document.createElement('div');
                    icDiv.className = 'adm-kpi-icon';
                    icDiv.textContent = icon;
                    const bDiv = document.createElement('div');
                    bDiv.className = 'adm-kpi-body';
                    const vDiv = document.createElement('div');
                    vDiv.className = 'val';
                    vDiv.textContent = String(val);
                    const lDiv = document.createElement('div');
                    lDiv.className = 'lbl';
                    lDiv.textContent = lbl;
                    bDiv.appendChild(vDiv);
                    bDiv.appendChild(lDiv);
                    c.appendChild(icDiv);
                    c.appendChild(bDiv);
                    grid.appendChild(c);
                });
                tabContent.appendChild(grid);

                // 2. Quick Admin Actions Card
                const qaCard = document.createElement('div');
                qaCard.className = 'card-box';
                const qaHead = document.createElement('div');
                qaHead.className = 'section-header';
                qaHead.textContent = t('adm_quick_actions');
                qaCard.appendChild(qaHead);

                const qaRow = document.createElement('div');
                qaRow.className = 'resp-action-row';
                [
                    [t('adm_tab_users'), () => renderTab('users'), 'btn-primary'],
                    [t('adm_tab_storage_clean'), () => renderTab('storage'), 'btn-secondary'],
                    [t('adm_tab_emergency'), () => renderTab('emergency'), 'btn-danger'],
                    [t('adm_tab_backup_restore'), () => renderTab('backup'), 'btn-secondary'],
                    [t('adm_tab_lineage'), () => renderTab('lineage'), 'btn-secondary'],
                    [`${t('adm_tab_reports')} (${formatLocalizedCount(d.pending_reports || 0)})`, () => renderTab('reports'), d.pending_reports > 0 ? 'btn-danger' : 'btn-secondary']
                ].forEach(([label, fn, cls]) => {
                    const b = document.createElement('button');
                    b.type = 'button';
                    b.className = `btn ${cls} btn-sm`;
                    b.textContent = label;
                    b.addEventListener('click', fn);
                    qaRow.appendChild(b);
                });
                qaCard.appendChild(qaRow);
                tabContent.appendChild(qaCard);

                // 3. Redesigned Server Health & Technical Diagnostics
                if (hRes.ok) {
                    const hd = hRes.data || {};
                    const hc = document.createElement('div');
                    hc.className = 'card-box';
                    const hTitle = document.createElement('div');
                    hTitle.className = 'section-header';
                    hTitle.textContent = t('hlth_sec_title');
                    hc.appendChild(hTitle);

                    const hGrid = document.createElement('div');
                    hGrid.className = 'adm-health-grid';

                    const dbName = String(hd.db_driver || 'sqlite').toLowerCase() === 'mysql' ? 'MySQL / MariaDB' : 'SQLite 3';
                    const storageOk = Boolean(hd.data_dir_writable && hd.files_dir_writable !== false);
                    const guardOk = hd.htaccess_exists !== false;
                    const freeStr = formatBytes(hd.disk_free_bytes || 0);
                    const totalStr = hd.disk_total_bytes > 0 ? formatBytes(hd.disk_total_bytes) : '—';
                    const memStr = formatBytes(hd.memory_usage_bytes || 0);
                    const memLim = hd.memory_limit || '—';
                    const upMax = hd.upload_max_filesize || '—';
                    const zeroLogOk = hd.zero_log_active !== false;
                    const cryptoOk = hd.openssl_ok !== false;

                    const healthRows = [
                        {
                            ico: '⚙️',
                            title: t('hlth_php_title'),
                            sub: t('hlth_php_sub'),
                            badge: `PHP ${hd.php_version || ''}`,
                            ok: true
                        },
                        {
                            ico: '🗄️',
                            title: t('hlth_db_title'),
                            sub: t('hlth_db_sub'),
                            badge: dbName,
                            ok: true
                        },
                        {
                            ico: '📂',
                            title: t('hlth_storage_title'),
                            sub: storageOk ? t('hlth_storage_ok_sub') : t('hlth_storage_err_sub'),
                            badge: storageOk ? t('hlth_badge_healthy') : t('hlth_badge_warn'),
                            ok: storageOk
                        },
                        {
                            ico: '💿',
                            title: t('hlth_disk_title'),
                            sub: t('hlth_disk_sub_tpl').replace('{total}', totalStr),
                            badge: freeStr,
                            ok: (hd.disk_free_bytes || 0) > 20 * 1048576 || !hd.disk_free_bytes
                        },
                        {
                            ico: '🚀',
                            title: t('hlth_mem_title'),
                            sub: t('hlth_mem_sub_tpl').replace('{mem}', memStr).replace('{limit}', memLim).replace('{up}', upMax),
                            badge: t('hlth_badge_ready'),
                            ok: true
                        },
                        {
                            ico: '🛡️',
                            title: t('hlth_guard_title'),
                            sub: guardOk ? t('hlth_guard_ok_sub') : t('hlth_guard_warn_sub'),
                            badge: guardOk ? t('hlth_badge_active') : t('hlth_badge_warn'),
                            ok: guardOk
                        },
                        {
                            ico: '🕵️',
                            title: t('hlth_zerolog_title'),
                            sub: t('hlth_zerolog_sub'),
                            badge: zeroLogOk ? t('hlth_badge_active') : t('hlth_badge_warn'),
                            ok: zeroLogOk
                        },
                        {
                            ico: '🔐',
                            title: t('hlth_crypto_title'),
                            sub: t('hlth_crypto_sub'),
                            badge: cryptoOk ? 'OpenSSL' : t('hlth_badge_warn'),
                            ok: cryptoOk
                        }
                    ];

                    healthRows.forEach(item => {
                        const card = document.createElement('div');
                        card.className = 'hlth-card';

                        const main = document.createElement('div');
                        main.className = 'hlth-card-main';

                        const ico = document.createElement('span');
                        ico.className = 'hlth-ico';
                        ico.textContent = item.ico;

                        const texts = document.createElement('div');
                        texts.className = 'hlth-texts';
                        const ttl = document.createElement('div');
                        ttl.className = 'hlth-title';
                        ttl.textContent = item.title;
                        const sub = document.createElement('div');
                        sub.className = 'hlth-sub';
                        sub.textContent = item.sub;
                        sub.title = item.sub;
                        texts.appendChild(ttl);
                        texts.appendChild(sub);

                        main.appendChild(ico);
                        main.appendChild(texts);

                        const bdg = document.createElement('span');
                        bdg.className = 'hlth-badge ' + (item.ok ? 'ok' : 'warn');
                        bdg.textContent = item.badge;

                        card.appendChild(main);
                        card.appendChild(bdg);
                        hGrid.appendChild(card);
                    });

                    hc.appendChild(hGrid);
                    tabContent.appendChild(hc);
                }
            } else if (tabId === 'users') {
                const res = await apiCall('admin_users_list');
                tabContent.innerHTML = '';

                const allUsersRaw = (res.ok && Array.isArray(res.data.users)) ? res.data.users : [];
                const totalOnlineCount = (res.ok && res.data.online_count !== undefined)
                    ? Number(res.data.online_count || 0)
                    : allUsersRaw.filter(u => Number(u.is_online) === 1).length;

                // Item #19: Live Online Users Banner at top of Users Tab
                const onlineBanner = document.createElement('div');
                onlineBanner.className = 'adm-online-banner';
                const obLeft = document.createElement('div');
                obLeft.style.cssText = 'display:flex;align-items:center;gap:8px;font-weight:800;font-size:13.5px';
                const obDot = document.createElement('span');
                obDot.className = 'adm-online-dot';
                const obTxt = document.createElement('span');
                obTxt.textContent = t('adm_online_banner_tpl')
                    .replace('{online}', formatLocalizedCount(totalOnlineCount))
                    .replace('{total}', formatLocalizedCount(allUsersRaw.length));
                obLeft.appendChild(obDot);
                obLeft.appendChild(obTxt);
                onlineBanner.appendChild(obLeft);
                tabContent.appendChild(onlineBanner);

                // Item #14: Global User Sessions & Forced Recovery Password Reset Card
                const globSecCard = document.createElement('div');
                globSecCard.className = 'card-box';
                const gsHead = document.createElement('div');
                gsHead.className = 'section-header';
                gsHead.textContent = t('adm_sec_global_card_title');
                globSecCard.appendChild(gsHead);
                const gsDesc = document.createElement('p');
                gsDesc.style.cssText = 'font-size:12px;color:var(--text-secondary);margin:0 0 10px;line-height:1.55';
                gsDesc.textContent = t('adm_sec_global_card_desc');
                globSecCard.appendChild(gsDesc);
                const gsBtnRow = document.createElement('div');
                gsBtnRow.className = 'resp-action-row';
                [
                    ['keep_latest_sessions_all', t('adm_sec_keep_latest_all_btn'), 'btn-secondary', false],
                    ['revoke_all_users_sessions', t('adm_sec_revoke_all_btn'), 'btn-amber-action', true],
                    ['force_pw_reset_all_users', t('adm_sec_force_pw_all_btn'), 'btn-danger', true]
                ].forEach(([opName, opLbl, btnCls, isDanger]) => {
                    const b = document.createElement('button');
                    b.type = 'button';
                    b.className = `btn ${btnCls} btn-sm`;
                    b.textContent = opLbl;
                    b.addEventListener('click', async () => {
                        const ap = await askApproval({
                            title: opLbl,
                            desc: t('adm_sec_global_card_desc'),
                            danger: isDanger,
                            icon: '🛡️'
                        });
                        if (!ap.approved) return;
                        b.disabled = true;
                        const gr = await apiCall('admin_global_security_action', { security_action: opName });
                        b.disabled = false;
                        if (gr.ok) {
                            toast(t('adm_sec_action_done_toast'));
                            renderTab('users');
                        } else {
                            toast(gr.message || t('err_generic'), true);
                        }
                    });
                    gsBtnRow.appendChild(b);
                });
                globSecCard.appendChild(gsBtnRow);
                tabContent.appendChild(globSecCard);

                // Manual User Creation Card
                const crCard = document.createElement('div');
                crCard.className = 'card-box';
                const crHead = document.createElement('div');
                crHead.className = 'section-header';
                crHead.textContent = t('adm_create_user_title');
                crCard.appendChild(crHead);

                const crRow = document.createElement('div');
                crRow.className = 'resp-grid-2';

                const admCrLim = getIdentityLenLimits();
                const uIn = document.createElement('input');
                uIn.id = 'adm-create-username';
                uIn.className = 'input';
                uIn.minLength = admCrLim.uMin;
                uIn.maxLength = admCrLim.uMax;
                uIn.placeholder = t('username') + ' (' + formatIdentityNum(admCrLim.uMin) + '–' + formatIdentityNum(admCrLim.uMax) + ')';
                uIn.dir = 'ltr';

                const nIn = document.createElement('input');
                nIn.id = 'adm-create-display-name';
                nIn.className = 'input';
                nIn.minLength = admCrLim.nMin;
                nIn.maxLength = admCrLim.nMax;
                nIn.placeholder = t('display_name') + ' (' + formatIdentityNum(admCrLim.nMin) + '–' + formatIdentityNum(admCrLim.nMax) + ')';

                const pIn = document.createElement('input');
                pIn.type = 'password';
                pIn.className = 'input';
                pIn.placeholder = t('password');
                pIn.dir = 'ltr';

                const pConfIn = document.createElement('input');
                pConfIn.type = 'password';
                pConfIn.className = 'input';
                pConfIn.placeholder = t('password_confirm');
                pConfIn.dir = 'ltr';

                const rSel = document.createElement('select');
                rSel.className = 'input';
                [['user', t('role_regular_user')], ['superadmin', t('role_superadmin')]].forEach(([v, l]) => {
                    const o = document.createElement('option');
                    o.value = v;
                    o.textContent = l;
                    rSel.appendChild(o);
                });

                crRow.appendChild(uIn);
                crRow.appendChild(nIn);
                crRow.appendChild(pIn);
                crRow.appendChild(pConfIn);
                crRow.appendChild(rSel);
                crCard.appendChild(crRow);

                const crPwHint = document.createElement('div');
                crPwHint.style.cssText = 'font-size:11.5px;color:var(--text-muted);margin-top:6px';
                crPwHint.textContent = t('pw_policy_hint');
                crCard.appendChild(crPwHint);

                const crBtnRow = document.createElement('div');
                crBtnRow.className = 'resp-action-row';
                crBtnRow.style.marginTop = '10px';
                const crBtn = document.createElement('button');
                crBtn.type = 'button';
                crBtn.className = 'btn btn-primary btn-sm';
                crBtn.textContent = t('adm_create_user_btn');
                crBtn.addEventListener('click', async () => {
                    const crLimNow = getIdentityLenLimits();
                    const candU = uIn.value.trim().toLowerCase();
                    const candN = nIn.value.trim();
                    if (!/^[a-z0-9_]+$/.test(candU) || candU.length < crLimNow.uMin || candU.length > crLimNow.uMax) {
                        toast(formatInvalidUsernameErr(crLimNow.uMin, crLimNow.uMax), true);
                        uIn.focus();
                        return;
                    }
                    if (candN !== '') {
                        const candNLen = countUnicodeChars(candN);
                        if (candNLen < crLimNow.nMin || candNLen > crLimNow.nMax) {
                            toast(formatInvalidDisplayNameErr(crLimNow.nMin, crLimNow.nMax), true);
                            nIn.focus();
                            return;
                        }
                    }
                    if (pIn.value !== pConfIn.value) {
                        toast(t('pw_mismatch_err'), true);
                        return;
                    }
                    const pwChk = validateStrongPasswordClient(pIn.value);
                    if (!pwChk.valid) {
                        toast(pwChk.message, true);
                        return;
                    }
                    const r = await apiCall('admin_user_create', {
                        username: uIn.value.trim(),
                        name: nIn.value.trim(),
                        password: pIn.value,
                        password_confirm: pConfIn.value,
                        role: rSel.value
                    });
                    if (r.ok) {
                        uIn.value = '';
                        nIn.value = '';
                        pIn.value = '';
                        pConfIn.value = '';
                        await askApproval({
                            title: t('signup_ok_title'),
                            descNode: buildRecoveryCodeDescNode(t('signup_ok_desc'), r.data.recovery_code),
                            confirmText: t('copy_and_continue_btn'),
                            hideCancel: true,
                            danger: false,
                            icon: '🔑'
                        });
                        await copyTextToClipboard(r.data.recovery_code);
                        renderTab('users');
                    } else {
                        toast(r.message || t('err_generic'), true);
                    }
                });
                crBtnRow.appendChild(crBtn);
                crCard.appendChild(crBtnRow);
                tabContent.appendChild(crCard);

                // Search & Filter Toolbar
                const toolbar = document.createElement('div');
                toolbar.className = 'adm-toolbar';

                const searchIn = document.createElement('input');
                searchIn.className = 'input';
                searchIn.style.flex = '1';
                searchIn.style.minWidth = '200px';
                searchIn.placeholder = t('adm_search_users');

                const filterGroup = document.createElement('div');
                filterGroup.style.cssText = 'display:flex;gap:4px;flex-wrap:wrap';
                let userStatusFilter = 'all';

                const bulkBarMount = document.createElement('div');
                const listWrap = document.createElement('div');
                const pagerMount = document.createElement('div');
                const allUsers = (res.ok && res.data.users) ? res.data.users : [];
                const selectedUserIds = new Set();
                let usersPage = 1;
                let usersPageSize = admDefaultPageSize;

                const runBulkUsersAction = async (bulkOp) => {
                    const ids = Array.from(selectedUserIds);
                    if (!ids.length) return;
                    const ap = await askApproval({
                        title: t('adm_tab_users'),
                        desc: `${t('adm_ask_bulk_action')} (${formatLocalizedCount(ids.length)})`,
                        danger: bulkOp === 'delete' || bulkOp === 'block',
                        icon: bulkOp === 'delete' ? '🗑️' : '🛡️'
                    });
                    if (!ap.approved) return;
                    const r = await apiCall('admin_bulk_users', { user_ids: ids, bulk_op: bulkOp });
                    if (r.ok) {
                        selectedUserIds.clear();
                        toast(t('adm_bulk_done_toast'));
                        renderTab('users');
                    } else {
                        toast(r.message || t('err_generic'), true);
                    }
                };

                const renderUsersBulkBar = (pageSlice) => {
                    bulkBarMount.innerHTML = '';
                    const bar = document.createElement('div');
                    bar.className = 'adm-bulk-bar';

                    const leftB = document.createElement('div');
                    leftB.style.cssText = 'display:flex;align-items:center;gap:6px;flex-wrap:wrap;font-size:12.5px;font-weight:800';
                    const cnt = document.createElement('span');
                    cnt.textContent = t('adm_bulk_selected_lbl').replace('{n}', formatLocalizedCount(selectedUserIds.size));
                    leftB.appendChild(cnt);

                    const selPageBtn = document.createElement('button');
                    selPageBtn.type = 'button';
                    selPageBtn.className = 'btn btn-secondary btn-sm';
                    selPageBtn.textContent = t('adm_bulk_select_page_btn');
                    selPageBtn.addEventListener('click', () => {
                        pageSlice.forEach(u => {
                            if (u.id !== store.user.id && u.role !== 'superadmin') selectedUserIds.add(u.id);
                        });
                        drawUsers();
                    });
                    leftB.appendChild(selPageBtn);

                    if (selectedUserIds.size > 0) {
                        const clrBtn = document.createElement('button');
                        clrBtn.type = 'button';
                        clrBtn.className = 'btn btn-secondary btn-sm';
                        clrBtn.textContent = t('adm_bulk_clear_btn');
                        clrBtn.addEventListener('click', () => {
                            selectedUserIds.clear();
                            drawUsers();
                        });
                        leftB.appendChild(clrBtn);
                    }
                    bar.appendChild(leftB);

                    if (selectedUserIds.size > 0) {
                        const rightB = document.createElement('div');
                        rightB.style.cssText = 'display:flex;align-items:center;gap:6px;flex-wrap:wrap';
                        [
                            ['block', t('adm_bulk_block_btn'), 'btn-secondary'],
                            ['unblock', t('adm_bulk_unblock_btn'), 'btn-secondary'],
                            ['mute_send', t('adm_bulk_mute_send_btn'), 'btn-secondary'],
                            ['unmute_send', t('adm_bulk_unmute_send_btn'), 'btn-secondary'],
                            ['delete', t('adm_bulk_delete_btn'), 'btn-danger']
                        ].forEach(([op, lbl, cls]) => {
                            const b = document.createElement('button');
                            b.type = 'button';
                            b.className = `btn ${cls} btn-sm`;
                            b.textContent = lbl;
                            b.addEventListener('click', () => runBulkUsersAction(op));
                            rightB.appendChild(b);
                        });
                        bar.appendChild(rightB);
                    }
                    bulkBarMount.appendChild(bar);
                };

                const drawUsers = () => {
                    listWrap.innerHTML = '';
                    pagerMount.innerHTML = '';
                    const ql = searchIn.value.trim().toLowerCase();
                    const filtered = allUsers.filter(u => {
                        if (userStatusFilter === 'active' && u.status !== 'active') return false;
                        if (userStatusFilter === 'blocked' && u.status !== 'blocked') return false;
                        if (userStatusFilter === 'online' && Number(u.is_online) !== 1) return false;
                        if (userStatusFilter === 'admins' && u.role !== 'superadmin') return false;
                        if (!ql) return true;
                        const uLogin = String(u.login_username || u.username || '').toLowerCase();
                        const uPub = String(u.username || '').toLowerCase();
                        const uName = String(u.name || '').toLowerCase();
                        const uCode = String(u.invite_code || '').toLowerCase();
                        const uInv = String(u.inviter_username || '').toLowerCase();
                        return uLogin.includes(ql) || uPub.includes(ql) || uName.includes(ql) || uCode.includes(ql) || uInv.includes(ql) || (`#${u.id}` === ql);
                    });

                    const pg = buildAdminPaginationControls({
                        totalItems: filtered.length,
                        page: usersPage,
                        pageSize: usersPageSize,
                        onPageChange: nextP => { usersPage = nextP; drawUsers(); },
                        onPageSizeChange: nextSz => { usersPageSize = nextSz; admDefaultPageSize = nextSz; usersPage = 1; drawUsers(); }
                    });
                    usersPage = pg.curPage;
                    pagerMount.appendChild(pg.bar);

                    if (filtered.length === 0) {
                        const emp = document.createElement('div');
                        emp.className = 'card-box';
                        emp.style.textAlign = 'center';
                        emp.textContent = t('adm_no_results');
                        listWrap.appendChild(emp);
                        return;
                    }

                    const pageSlice = filtered.slice(pg.fromOffset, pg.toOffset);
                    renderUsersBulkBar(pageSlice);

                    pageSlice.forEach(u => {
                        const row = document.createElement('div');
                        row.className = 'adm-user-card';

                        const top = document.createElement('div');
                        top.className = 'adm-item-top';

                        const left = document.createElement('div');
                        left.style.cssText = 'display:flex;align-items:center;gap:10px;min-width:0;flex:1';

                        if (u.id !== store.user.id && u.role !== 'superadmin') {
                            const uChk = document.createElement('input');
                            uChk.type = 'checkbox';
                            uChk.className = 'adm-select-chk';
                            uChk.checked = selectedUserIds.has(u.id);
                            uChk.addEventListener('change', () => {
                                if (uChk.checked) selectedUserIds.add(u.id);
                                else selectedUserIds.delete(u.id);
                                renderUsersBulkBar(pageSlice);
                            });
                            left.appendChild(uChk);
                        }

                        const av = document.createElement('div');
                        av.className = 'avatar avatar-sm';
                        renderAvatarNode(av, u.name, u.avatar || '');
                        left.appendChild(av);

                        const info = document.createElement('div');
                        info.style.minWidth = '0';
                        const titleDiv = document.createElement('div');
                        titleDiv.className = 'adm-item-title';
                        const nSpan = document.createElement('span');
                        const dispHandle = u.no_username ? `${t('no_username_badge')} [${u.login_username}]` : `@${u.username || u.login_username}`;
                        nSpan.textContent = `${u.name} (${dispHandle})`;
                        titleDiv.appendChild(nSpan);
                        const uCopyChip = createCopyUsernameChip(u.username || u.login_username);
                        if (uCopyChip) titleDiv.appendChild(uCopyChip);

                        const rolePill = document.createElement('span');
                        rolePill.className = 'adm-badge-pill ' + (u.role === 'superadmin' ? 'primary' : '');
                        rolePill.textContent = u.role === 'superadmin' ? t('role_superadmin') : t('role_regular_user');
                        titleDiv.appendChild(rolePill);

                        const anyBlocked = (u.status === 'blocked' || Number(u.ban_send) === 1 || Number(u.ban_react) === 1);
                        const stPill = document.createElement('span');
                        stPill.className = 'adm-badge-pill ' + (anyBlocked ? 'danger' : 'success');
                        stPill.textContent = u.status === 'blocked' ? t('status_blocked') : t('status_active');
                        titleDiv.appendChild(stPill);

                        // Item #19: Per-user Live Online / Last-Seen Status Badge in Admin Users List
                        const onlinePill = document.createElement('span');
                        const isUOnline = Number(u.is_online) === 1;
                        onlinePill.className = 'adm-badge-pill ' + (isUOnline ? 'success' : '');
                        onlinePill.textContent = isUOnline
                            ? ('🟢 ' + t('online'))
                            : ('🕒 ' + (u.last_seen_at ? (t('last_seen_prefix') + formatDate(u.last_seen_at)) : t('last_seen_recently')));
                        titleDiv.appendChild(onlinePill);

                        if (Number(u.has_2fa) === 1) {
                            const tfaPill = document.createElement('span');
                            tfaPill.className = 'status-chip-2fa';
                            tfaPill.textContent = t('adm_user_2fa_badge');
                            titleDiv.appendChild(tfaPill);
                        }
                        if (Number(u.force_pw_reset) === 1) {
                            const fprPill = document.createElement('span');
                            fprPill.className = 'adm-badge-pill warning';
                            fprPill.textContent = t('adm_user_force_pw_badge');
                            titleDiv.appendChild(fprPill);
                        }
                        if (Number(u.sessions_count || 0) > 0) {
                            const sessPill = document.createElement('span');
                            sessPill.className = 'adm-badge-pill';
                            sessPill.textContent = t('adm_user_sessions_badge_tpl').replace('{n}', formatLocalizedCount(Number(u.sessions_count || 0)));
                            titleDiv.appendChild(sessPill);
                        }

                        const metaDiv = document.createElement('div');
                        metaDiv.className = 'adm-item-meta';
                        metaDiv.style.cssText = 'display:flex;align-items:center;gap:6px;flex-wrap:wrap';
                        const quotaTxt = Number(u.storage_quota_mb) > 0 ? `${u.storage_quota_mb} ${t('unit_mb')}` : t('adm_default_lbl');
                        const uTrSt = u.traffic_status || {};
                        const trUsedTxt = formatBytes(Number(uTrSt.used_bytes || 0));
                        const trLimTxt = (Number(uTrSt.limit_bytes || 0) > 0 && !uTrSt.is_exempt) ? formatBytes(Number(uTrSt.limit_bytes)) : t('quota_unlimited');
                        const metaTextSpan = document.createElement('span');
                        metaTextSpan.textContent = `📡 ${trUsedTxt} / ${trLimTxt} • 💾 ${formatBytes(u.used_storage_bytes || 0)} (${u.files_count || 0} ${t('adm_files_lbl')} • ${t('adm_quota_lbl')}: ${quotaTxt}) • 🎟️ ${u.invite_code || '-'} • ${t('adm_invited_by_lbl')}: ${u.inviter_username ? ('@' + u.inviter_username) : (store.lang === 'fa' ? 'ریشه سیستم' : 'System Root')}`;
                        metaDiv.appendChild(metaTextSpan);
                        if (u.inviter_username) {
                            const invChip = createCopyUsernameChip(u.inviter_username);
                            if (invChip) metaDiv.appendChild(invChip);
                        }
                        info.appendChild(titleDiv);
                        info.appendChild(metaDiv);
                        left.appendChild(info);
                        top.appendChild(left);
                        row.appendChild(top);

                        // 3 Independent Global Block Toggles: Login Block, Message-Write Block, Reaction Block
                        if (u.id !== store.user.id) {
                            const banRow = document.createElement('div');
                            banRow.className = 'restrict-pills-row';
                            banRow.style.marginTop = '8px';

                            const makeGlobalBanPill = (flagKey, labelKey) => {
                                const pBtn = document.createElement('button');
                                pBtn.type = 'button';
                                const syncPill = () => {
                                    const isOn = flagKey === 'ban_login' ? (u.status === 'blocked' || Number(u.ban_login) === 1) : (Number(u[flagKey]) === 1);
                                    pBtn.className = 'restrict-pill-toggle' + (isOn ? ' is-blocked' : '');
                                    pBtn.textContent = t(labelKey) + (isOn ? ' ✓' : '');
                                };
                                syncPill();
                                pBtn.addEventListener('click', async () => {
                                    const curOn = flagKey === 'ban_login' ? (u.status === 'blocked' || Number(u.ban_login) === 1) : (Number(u[flagKey]) === 1);
                                    const nextOn = curOn ? 0 : 1;
                                    const payload = { user_id: u.id };
                                    payload[flagKey] = nextOn;
                                    const r = await apiCall('admin_user_update', payload);
                                    if (r.ok) {
                                        u[flagKey] = nextOn;
                                        if (flagKey === 'ban_login') {
                                            u.status = nextOn ? 'blocked' : 'active';
                                            stPill.textContent = u.status === 'blocked' ? t('status_blocked') : t('status_active');
                                        }
                                        const hasAny = (u.status === 'blocked' || Number(u.ban_send) === 1 || Number(u.ban_react) === 1);
                                        stPill.className = 'adm-badge-pill ' + (hasAny ? 'danger' : 'success');
                                        syncPill();
                                        toast(t('ban_updated_toast') + u.name);
                                    } else {
                                        toast(r.message || t('err_generic'), true);
                                    }
                                });
                                return pBtn;
                            };

                            banRow.appendChild(makeGlobalBanPill('ban_login', 'ban_type_login'));
                            banRow.appendChild(makeGlobalBanPill('ban_send', 'ban_type_send'));
                            banRow.appendChild(makeGlobalBanPill('ban_react', 'ban_type_react'));

                            // Item 13: Per-user complete upload disable pill
                            const upDisBtn = document.createElement('button');
                            upDisBtn.type = 'button';
                            const syncUpDisPill = () => {
                                const on = Number(u.upload_disabled) === 1;
                                upDisBtn.className = 'ban-pill' + (on ? ' active' : '');
                                upDisBtn.textContent = `${on ? '🚫 ' : '🟢 '}${stripLeadingEmoji(t('adm_user_upload_disable_pill'))}`;
                            };
                            syncUpDisPill();
                            upDisBtn.addEventListener('click', async () => {
                                const nextVal = Number(u.upload_disabled) === 1 ? 0 : 1;
                                const r = await apiCall('admin_user_update', { user_id: u.id, upload_disabled: nextVal });
                                if (r.ok) {
                                    u.upload_disabled = nextVal;
                                    syncUpDisPill();
                                    toast((nextVal ? t('adm_user_upload_disabled_on') : t('adm_user_upload_disabled_off')) + u.name);
                                } else {
                                    toast(r.message || t('err_generic'), true);
                                }
                            });
                            banRow.appendChild(upDisBtn);
                            row.appendChild(banRow);
                        }

                        const acts = document.createElement('div');
                        acts.className = 'adm-item-actions';
                        acts.style.marginTop = '8px';

                        if (u.role !== 'superadmin' && typeof openAdminUserPoliciesSubModal === 'function') {
                            const polBtn = document.createElement('button');
                            polBtn.type = 'button';
                            polBtn.className = 'btn btn-secondary btn-sm';
                            polBtn.dataset.admUserPoliciesBtn = String(u.id);
                            polBtn.textContent = t('content_restrict_user_btn');
                            polBtn.addEventListener('click', () => openAdminUserPoliciesSubModal(u));
                            acts.appendChild(polBtn);
                        }

                        if (u.id !== store.user.id) {
                            const runSecMod = async (secAct, btnLbl, toastKey) => {
                                const ap = await askApproval({
                                    title: `${btnLbl} — ${u.name}`,
                                    desc: `${t('ask_adm_user_sec_act')}\n👤 ${u.name} (@${u.username || u.login_username || u.id})`,
                                    danger: true,
                                    icon: '🛡️'
                                });
                                if (!ap.approved) return;
                                const sr = await apiCall('admin_user_security_action', { user_id: u.id, security_action: secAct });
                                if (sr.ok) {
                                    toast(t(toastKey) + u.name);
                                    renderTab('users');
                                } else {
                                    toast(sr.message || t('err_generic'), true);
                                }
                            };

                            const keepLatestSessBtn = document.createElement('button');
                            keepLatestSessBtn.type = 'button';
                            keepLatestSessBtn.className = 'btn btn-secondary btn-sm';
                            keepLatestSessBtn.textContent = t('adm_user_keep_latest_btn');
                            keepLatestSessBtn.addEventListener('click', () => runSecMod('keep_latest_session', t('adm_user_keep_latest_btn'), 'adm_sec_action_done_toast'));
                            acts.appendChild(keepLatestSessBtn);

                            const revSessBtn = document.createElement('button');
                            revSessBtn.type = 'button';
                            revSessBtn.className = 'btn btn-secondary btn-sm';
                            revSessBtn.textContent = t('adm_user_revoke_sessions_btn');
                            revSessBtn.addEventListener('click', () => runSecMod('revoke_sessions', t('adm_user_revoke_sessions_btn'), 'adm_user_sessions_revoked_toast'));
                            acts.appendChild(revSessBtn);

                            if (u.role !== 'superadmin') {
                                const forcePwBtn = document.createElement('button');
                                forcePwBtn.type = 'button';
                                forcePwBtn.className = 'btn btn-amber-action btn-sm';
                                forcePwBtn.textContent = t('adm_user_force_pw_btn');
                                forcePwBtn.addEventListener('click', () => runSecMod('force_pw_reset', t('adm_user_force_pw_btn'), 'adm_sec_action_done_toast'));
                                acts.appendChild(forcePwBtn);
                            }

                            if (Number(u.twofa_disabled) === 1) {
                                const en2faBtn = document.createElement('button');
                                en2faBtn.type = 'button';
                                en2faBtn.className = 'btn btn-secondary btn-sm';
                                en2faBtn.textContent = t('adm_user_enable_2fa_btn');
                                en2faBtn.addEventListener('click', () => runSecMod('enable_2fa', t('adm_user_enable_2fa_btn'), 'adm_user_2fa_enabled_toast'));
                                acts.appendChild(en2faBtn);
                            } else {
                                const dis2faBtn = document.createElement('button');
                                dis2faBtn.type = 'button';
                                dis2faBtn.className = 'btn btn-secondary btn-sm';
                                dis2faBtn.textContent = t('adm_user_disable_2fa_btn');
                                dis2faBtn.addEventListener('click', () => runSecMod('disable_2fa', t('adm_user_disable_2fa_btn'), 'adm_user_2fa_disabled_toast'));
                                acts.appendChild(dis2faBtn);
                            }

                            if (u.avatar || u.bio) {
                                const clrProfBtn = document.createElement('button');
                                clrProfBtn.type = 'button';
                                clrProfBtn.className = 'btn btn-secondary btn-sm';
                                clrProfBtn.textContent = t('adm_user_clear_profile_btn');
                                clrProfBtn.addEventListener('click', () => runSecMod('clear_profile', t('adm_user_clear_profile_btn'), 'adm_user_profile_cleared_toast'));
                                acts.appendChild(clrProfBtn);
                            }
                        }

                        const quotaBtn = document.createElement('button');
                        quotaBtn.type = 'button';
                        quotaBtn.className = 'btn btn-secondary btn-sm';
                        quotaBtn.textContent = `${t('adm_user_quota_btn')} (${Number(u.storage_quota_mb) > 0 ? (u.storage_quota_mb + ' ' + t('unit_mb')) : t('adm_default_lbl')})`;
                        quotaBtn.addEventListener('click', async () => {
                            const ap = await askApproval({
                                title: `${t('adm_user_quota_btn')} — ${u.name}`,
                                desc: t('adm_user_quota_prompt'),
                                danger: false,
                                icon: '💾',
                                input: { label: t('adm_quota_input_lbl'), type: 'number', defaultValue: String(u.storage_quota_mb || 0), dir: 'ltr' }
                            });
                            if (!ap.approved) return;
                            const val = Math.max(0, parseFloat(ap.value) || 0);
                            const r = await apiCall('admin_user_update', { user_id: u.id, storage_quota_mb: val });
                            if (r.ok) {
                                toast(`${t('adm_quota_saved_toast')}${u.name} (${val > 0 ? val + ' ' + t('unit_mb') : t('adm_default_lbl')})`);
                                renderTab('users');
                            } else {
                                toast(r.message || t('err_generic'), true);
                            }
                        });
                        acts.appendChild(quotaBtn);

                        // Item #3: Per-User Traffic Quota + Period + Reset Button
                        if (u.role !== 'superadmin') {
                            const curTrMb = (u.traffic_quota_mb !== undefined && u.traffic_quota_mb !== null) ? Number(u.traffic_quota_mb) : -1;
                            const curTrDays = (u.traffic_period_days !== undefined && u.traffic_period_days !== null) ? Number(u.traffic_period_days) : -1;
                            const trBtnLbl = curTrMb < 0 ? t('adm_default_lbl') : (curTrMb === 0 ? t('quota_unlimited') : `${curTrMb} ${t('unit_mb')}`);
                            const trfBtn = document.createElement('button');
                            trfBtn.type = 'button';
                            trfBtn.className = 'btn btn-secondary btn-sm';
                            trfBtn.textContent = `${t('user_traffic_sec_label')} (${trBtnLbl})`;
                            trfBtn.addEventListener('click', () => {
                                openSubModal(`${t('user_traffic_sec_label')} — ${u.name}`, (sb, closeSub) => {
                                    const uTr = u.traffic_status || {};
                                    const stSummary = document.createElement('div');
                                    stSummary.className = 'card-box';
                                    stSummary.style.fontSize = '12.5px';
                                    stSummary.textContent = `${t('user_traffic_used_label')}: ${formatBytes(Number(uTr.used_bytes || 0))} • ${t('user_traffic_rem_label')}: ${Number(uTr.limit_bytes || 0) > 0 ? formatBytes(Number(uTr.remaining_bytes || 0)) : t('quota_unlimited')}`;
                                    sb.appendChild(stSummary);

                                    const fgMb = document.createElement('div');
                                    fgMb.className = 'form-group';
                                    const lMb = document.createElement('label');
                                    lMb.textContent = t('adm_user_traffic_quota_lbl');
                                    const inMb = document.createElement('input');
                                    inMb.type = 'number';
                                    inMb.step = 'any';
                                    inMb.min = '-1';
                                    inMb.className = 'input';
                                    inMb.dir = 'ltr';
                                    inMb.value = String(curTrMb);
                                    fgMb.appendChild(lMb);
                                    fgMb.appendChild(inMb);
                                    sb.appendChild(fgMb);

                                    const fgDays = document.createElement('div');
                                    fgDays.className = 'form-group';
                                    const lDays = document.createElement('label');
                                    lDays.textContent = t('adm_user_traffic_period_lbl');
                                    const inDays = document.createElement('input');
                                    inDays.type = 'number';
                                    inDays.step = '1';
                                    inDays.min = '-1';
                                    inDays.max = '3650';
                                    inDays.className = 'input';
                                    inDays.dir = 'ltr';
                                    inDays.value = String(curTrDays);
                                    fgDays.appendChild(lDays);
                                    fgDays.appendChild(inDays);
                                    sb.appendChild(fgDays);

                                    const btnRow = document.createElement('div');
                                    btnRow.className = 'resp-action-row';
                                    btnRow.style.marginTop = '12px';

                                    const svBtn = document.createElement('button');
                                    svBtn.type = 'button';
                                    svBtn.className = 'btn btn-primary btn-sm';
                                    svBtn.textContent = t('save_changes');
                                    svBtn.addEventListener('click', async () => {
                                        const nextMb = parseFloat(inMb.value);
                                        const nextDays = parseInt(inDays.value, 10);
                                        const r = await apiCall('admin_user_update', {
                                            user_id: u.id,
                                            traffic_quota_mb: isNaN(nextMb) || nextMb < 0 ? -1 : nextMb,
                                            traffic_period_days: isNaN(nextDays) || nextDays < 0 ? -1 : nextDays
                                        });
                                        if (r.ok) {
                                            toast(t('adm_settings_saved_toast'));
                                            closeSub();
                                            renderTab('users');
                                        } else {
                                            toast(r.message || t('err_generic'), true);
                                        }
                                    });

                                    const rstBtn = document.createElement('button');
                                    rstBtn.type = 'button';
                                    rstBtn.className = 'btn btn-danger btn-sm';
                                    rstBtn.textContent = t('adm_user_traffic_reset_btn');
                                    rstBtn.addEventListener('click', async () => {
                                        const rr = await apiCall('admin_user_traffic_reset', { user_id: u.id });
                                        if (rr.ok) {
                                            toast(t('adm_traffic_reset_done_toast'));
                                            closeSub();
                                            renderTab('users');
                                        } else {
                                            toast(rr.message || t('err_generic'), true);
                                        }
                                    });

                                    btnRow.appendChild(svBtn);
                                    btnRow.appendChild(rstBtn);
                                    sb.appendChild(btnRow);
                                });
                            });
                            acts.appendChild(trfBtn);
                        }

                        if (u.id !== store.user.id) {

                            const roleBtn = document.createElement('button');
                            roleBtn.type = 'button';
                            roleBtn.className = 'btn btn-secondary btn-sm';
                            roleBtn.textContent = u.role === 'superadmin' ? t('adm_make_user_btn') : t('adm_make_admin_btn');
                            roleBtn.addEventListener('click', async () => {
                                const makeSuper = u.role !== 'superadmin';
                                const ap = await askApproval({
                                    title: makeSuper ? t('adm_make_admin_btn') : t('adm_make_user_btn'),
                                    desc: `${t('ask_adm_role_change')}
👤 ${u.name} (@${u.username})`,
                                    danger: true,
                                    icon: '👑'
                                });
                                if (!ap.approved) return;
                                const r = await apiCall('admin_user_update', { user_id: u.id, role: makeSuper ? 'superadmin' : 'user' });
                                if (r.ok) {
                                    toast((makeSuper ? t('adm_user_promoted_toast') : t('adm_user_demoted_toast')) + `@${u.username}`);
                                    renderTab('users');
                                } else {
                                    toast(r.message || t('err_generic'), true);
                                }
                            });
                            acts.appendChild(roleBtn);

                            // Item #10: Dual Strong Password Reset Sub-Modal
                            const pwBtn = document.createElement('button');
                            pwBtn.type = 'button';
                            pwBtn.className = 'btn btn-secondary btn-sm';
                            pwBtn.textContent = '🔑 ' + t('adm_reset_pass_btn');
                            pwBtn.addEventListener('click', () => {
                                const targetHandle = u.username || u.login_username || String(u.id);
                                openSubModal(`🔑 ${t('adm_reset_pass_btn')} — @${targetHandle}`, (sb, closeSub) => {
                                    const desc = document.createElement('p');
                                    desc.style.cssText = 'font-size:12.5px;color:var(--text-secondary);margin:0 0 10px';
                                    desc.textContent = `👤 ${u.name} (@${targetHandle}) — ${t('pw_policy_hint')}`;
                                    sb.appendChild(desc);

                                    const fg1 = document.createElement('div');
                                    fg1.className = 'form-group';
                                    const l1 = document.createElement('label');
                                    l1.textContent = t('new_password');
                                    const in1 = document.createElement('input');
                                    in1.type = 'password';
                                    in1.className = 'input';
                                    in1.dir = 'ltr';
                                    in1.autocomplete = 'new-password';
                                    fg1.appendChild(l1);
                                    fg1.appendChild(in1);

                                    const fg2 = document.createElement('div');
                                    fg2.className = 'form-group';
                                    const l2 = document.createElement('label');
                                    l2.textContent = t('adm_reset_pw_confirm_lbl');
                                    const in2 = document.createElement('input');
                                    in2.type = 'password';
                                    in2.className = 'input';
                                    in2.dir = 'ltr';
                                    in2.autocomplete = 'new-password';
                                    fg2.appendChild(l2);
                                    fg2.appendChild(in2);

                                    sb.appendChild(fg1);
                                    sb.appendChild(fg2);

                                    const svPwBtn = document.createElement('button');
                                    svPwBtn.type = 'button';
                                    svPwBtn.className = 'btn btn-primary btn-block';
                                    svPwBtn.textContent = '🔑 ' + t('adm_reset_pass_btn');
                                    svPwBtn.addEventListener('click', async () => {
                                        if (in1.value !== in2.value) {
                                            toast(t('pw_mismatch_err'), true);
                                            return;
                                        }
                                        const chk = validateStrongPasswordClient(in1.value);
                                        if (!chk.valid) {
                                            toast(chk.message, true);
                                            return;
                                        }
                                        const r = await apiCall('admin_user_action', {
                                            user_id: u.id,
                                            user_action: 'reset_password',
                                            new_password: in1.value,
                                            new_password_confirm: in2.value
                                        });
                                        if (r.ok) {
                                            toast(`${t('adm_pass_reset_toast')}@${targetHandle}`);
                                            closeSub();
                                        } else {
                                            toast(r.message || t('err_generic'), true);
                                        }
                                    });
                                    sb.appendChild(svPwBtn);
                                });
                            });
                            acts.appendChild(pwBtn);

                            const delBtn = document.createElement('button');
                            delBtn.type = 'button';
                            delBtn.className = 'btn btn-danger btn-sm';
                            delBtn.textContent = '🗑️ ' + t('adm_delete_btn');
                            delBtn.addEventListener('click', async () => {
                                const ap = await askApproval({
                                    title: '🗑️ ' + t('adm_delete_btn'),
                                    desc: `${t('ask_adm_del_user')}
👤 ${u.name} (@${u.username})`,
                                    danger: true,
                                    icon: '🗑️'
                                });
                                if (!ap.approved) return;
                                const r = await apiCall('admin_user_action', { user_id: u.id, user_action: 'delete' });
                                if (r.ok) {
                                    toast(`${t('adm_user_deleted_toast')}@${u.username}`);
                                    renderTab('users');
                                } else {
                                    toast(r.message || t('err_generic'), true);
                                }
                            });
                            acts.appendChild(delBtn);

                        }
                        row.appendChild(acts);

                        listWrap.appendChild(row);
                    });
                };

                [
                    ['all', t('adm_filter_all')],
                    ['online', t('adm_filter_online')],
                    ['active', t('adm_filter_active')],
                    ['blocked', t('adm_filter_blocked')],
                    ['admins', t('adm_filter_admins')]
                ].forEach(([fId, fLbl]) => {
                    const fb = document.createElement('button');
                    fb.type = 'button';
                    fb.className = 'filter-pill' + (userStatusFilter === fId ? ' active' : '');
                    fb.textContent = fLbl;
                    fb.addEventListener('click', () => {
                        userStatusFilter = fId;
                        usersPage = 1;
                        Array.from(filterGroup.children).forEach(c => c.classList.remove('active'));
                        fb.classList.add('active');
                        drawUsers();
                    });
                    filterGroup.appendChild(fb);
                });

                toolbar.appendChild(searchIn);
                toolbar.appendChild(filterGroup);
                tabContent.appendChild(toolbar);
                tabContent.appendChild(bulkBarMount);
                tabContent.appendChild(listWrap);
                tabContent.appendChild(pagerMount);

                searchIn.addEventListener('input', () => {
                    usersPage = 1;
                    drawUsers();
                });
                drawUsers();
            } else if (tabId === 'lineage') {
                const res = await apiCall('admin_referral_tree');
                const invRes = await apiCall('admin_invites_list');
                tabContent.innerHTML = '';

                // 1. Global Invite Code Regeneration Card
                const regenCard = document.createElement('div');
                regenCard.className = 'card-box';
                const rgTitle = document.createElement('div');
                rgTitle.className = 'section-header';
                rgTitle.textContent = t('adm_regen_title');
                const rgDesc = document.createElement('p');
                rgDesc.style.cssText = 'font-size:12.5px;color:var(--text-secondary);margin:0 0 10px;line-height:1.5';
                rgDesc.textContent = t('adm_regen_desc');
                const rgBtn = document.createElement('button');
                rgBtn.type = 'button';
                rgBtn.className = 'btn btn-danger btn-sm';
                rgBtn.textContent = t('adm_regen_btn');
                rgBtn.addEventListener('click', async () => {
                    const ap = await askApproval({
                        title: t('adm_regen_title'),
                        desc: t('adm_regen_desc'),
                        danger: true,
                        icon: '🔄'
                    });
                    if (!ap.approved) return;
                    const r = await apiCall('admin_invites_regenerate_all');
                    if (r.ok) {
                        if (store.user && r.data.my_invite_code) {
                            store.user.invite_code = r.data.my_invite_code;
                            renderSelfDock();
                        }
                        toast(store.lang === 'fa' ? `کد دعوت شخصی ${r.data.regenerated_count} کاربر با موفقیت چرخش یافت.` : `Rotated personal invite codes for ${r.data.regenerated_count} users.`);
                        renderTab('lineage');
                    }
                });
                regenCard.appendChild(rgTitle);
                regenCard.appendChild(rgDesc);
                regenCard.appendChild(rgBtn);
                tabContent.appendChild(regenCard);

                // 2. Custom Invite Codes Card
                const custCard = document.createElement('div');
                custCard.className = 'card-box';
                const cHead = document.createElement('div');
                cHead.className = 'section-header';
                cHead.textContent = t('adm_custom_codes_title');
                custCard.appendChild(cHead);

                const cRow = document.createElement('div');
                cRow.className = 'resp-grid-3';
                const cCodeIn = document.createElement('input');
                cCodeIn.className = 'input';
                cCodeIn.placeholder = t('adm_custom_code_ph');
                cCodeIn.dir = 'ltr';
                const cUsesIn = document.createElement('input');
                cUsesIn.type = 'number';
                cUsesIn.className = 'input';
                cUsesIn.value = '10';
                cUsesIn.placeholder = t('adm_custom_uses_ph');
                const cAddBtn = document.createElement('button');
                cAddBtn.type = 'button';
                cAddBtn.className = 'btn btn-primary btn-sm';
                cAddBtn.textContent = t('adm_custom_create_btn');
                cAddBtn.addEventListener('click', async () => {
                    const r = await apiCall('admin_invite_create', { code: cCodeIn.value.trim(), max_uses: parseInt(cUsesIn.value || '10', 10) });
                    if (r.ok) {
                        toast(t('invite_created_toast') + r.data.code);
                        renderTab('lineage');
                    }
                });
                cRow.appendChild(cCodeIn);
                cRow.appendChild(cUsesIn);
                cRow.appendChild(cAddBtn);
                custCard.appendChild(cRow);

                if (invRes.ok && invRes.data.invites && invRes.data.invites.length > 0) {
                    const allInvCodes = invRes.data.invites;
                    let codesPage = 1;
                    let codesPageSize = admDefaultPageSize;

                    const codeSearchIn = document.createElement('input');
                    codeSearchIn.type = 'text';
                    codeSearchIn.className = 'input';
                    codeSearchIn.style.marginTop = '12px';
                    codeSearchIn.placeholder = t('adm_search_inv_codes_ph');
                    custCard.appendChild(codeSearchIn);

                    const chipsWrap = document.createElement('div');
                    chipsWrap.style.cssText = 'display:flex;flex-wrap:wrap;gap:8px;margin-top:10px';
                    const codesPagerMount = document.createElement('div');
                    custCard.appendChild(chipsWrap);
                    custCard.appendChild(codesPagerMount);

                    const drawInviteCodes = () => {
                        chipsWrap.innerHTML = '';
                        codesPagerMount.innerHTML = '';
                        const cq = codeSearchIn.value.trim().toLowerCase();
                        const matchedCodes = allInvCodes.filter(ic => !cq || String(ic.code || '').toLowerCase().includes(cq));
                        const pgC = buildAdminPaginationControls({
                            totalItems: matchedCodes.length,
                            page: codesPage,
                            pageSize: codesPageSize,
                            onPageChange: nextP => { codesPage = nextP; drawInviteCodes(); },
                            onPageSizeChange: nextSz => { codesPageSize = nextSz; admDefaultPageSize = nextSz; codesPage = 1; drawInviteCodes(); }
                        });
                        codesPage = pgC.curPage;
                        if (allInvCodes.length > 5 || cq !== '') {
                            codesPagerMount.appendChild(pgC.bar);
                        }
                        if (matchedCodes.length === 0) {
                            const emp = document.createElement('div');
                            emp.style.cssText = 'font-size:12.5px;color:var(--text-muted);padding:6px 0';
                            emp.textContent = t('adm_no_results');
                            chipsWrap.appendChild(emp);
                            return;
                        }
                        matchedCodes.slice(pgC.fromOffset, pgC.toOffset).forEach(ic => {
                            const chip = document.createElement('div');
                            chip.style.cssText = 'display:inline-flex;align-items:center;gap:8px;font-size:12px;font-family:monospace;padding:5px 10px;background:var(--bg-surface);border:1px solid var(--border);border-radius:8px';
                            const codeTxt = document.createElement('span');
                            codeTxt.style.cursor = 'pointer';
                            codeTxt.style.fontWeight = '800';
                            codeTxt.style.color = 'var(--primary)';
                            codeTxt.textContent = `🎟️ ${ic.code} (${ic.uses}/${ic.max_uses})`;
                            codeTxt.addEventListener('click', () => {
                                if (navigator.clipboard) navigator.clipboard.writeText(ic.code);
                                toast(t('copied_toast'));
                            });
                            const editIc = document.createElement('button');
                            editIc.type = 'button';
                            editIc.className = 'btn-edit-invite-code';
                            editIc.style.cssText = 'color:var(--primary);font-weight:800;font-size:12px';
                            editIc.textContent = '✏️';
                            editIc.title = t('adm_inv_edit_btn');
                            editIc.setAttribute('aria-label', t('adm_inv_edit_btn'));
                            editIc.addEventListener('click', async () => {
                                const ap = await askApproval({
                                    title: '🎯 ' + t('adm_inv_edit_title'),
                                    desc: t('adm_inv_edit_desc') + '\n🎯 ' + ic.code + ' (' + String(ic.uses) + '/' + String(ic.max_uses) + ')',
                                    danger: false,
                                    icon: '✏️',
                                    input: {
                                        type: 'number',
                                        label: t('adm_inv_new_max_uses'),
                                        placeholder: String(ic.max_uses || 10),
                                        defaultValue: String(ic.max_uses || 10)
                                    }
                                });
                                if (!ap.approved) return;
                                const newMax = parseInt((ap.value || '').toString().trim(), 10);
                                if (!isFinite(newMax) || newMax < 1) {
                                    toast(t('adm_inv_edit_invalid'), true);
                                    return;
                                }
                                const err = await apiCall('admin_invitecode_edit', {
                                    code: ic.code,
                                    max_uses: newMax,
                                    uses_left: newMax
                                });
                                if (err.ok) {
                                    toast(t('adm_inv_edited_toast') + ic.code);
                                    renderTab('lineage');
                                } else {
                                    toast(err.message || t('err_generic'), true);
                                }
                            });
                            const delIc = document.createElement('button');
                            delIc.type = 'button';
                            delIc.style.cssText = 'color:var(--danger);font-weight:800;font-size:12px';
                            delIc.textContent = '✖';
                            delIc.addEventListener('click', async () => {
                                const ap = await askApproval({
                                    title: '🗑️ ' + ic.code,
                                    desc: `${t('ask_adm_del_inv')}\n🎟️ ${ic.code}`,
                                    danger: true,
                                    icon: '🗑️'
                                });
                                if (!ap.approved) return;
                                await apiCall('admin_invitecode_delete', { code: ic.code });
                                toast(t('adm_inv_deleted_toast') + ic.code);
                                renderTab('lineage');
                            });
                            chip.appendChild(codeTxt);
                            chip.appendChild(editIc);
                            chip.appendChild(delIc);
                            chipsWrap.appendChild(chip);
                        });
                    };
                    codeSearchIn.addEventListener('input', () => { codesPage = 1; drawInviteCodes(); });
                    drawInviteCodes();
                }
                tabContent.appendChild(custCard);

                // 3. Referral Tree & Lineage Inspector
                const treeCard = document.createElement('div');
                treeCard.className = 'card-box';
                const tHead = document.createElement('div');
                tHead.className = 'section-header';
                tHead.textContent = t('adm_lineage_title');
                treeCard.appendChild(tHead);

                const nodes = (res.ok && res.data.nodes) ? res.data.nodes : [];
                const byParent = {};
                const byId = {};
                nodes.forEach(n => {
                    byId[n.id] = n;
                    const pid = n.invited_by || 0;
                    if (!byParent[pid]) byParent[pid] = [];
                    byParent[pid].push(n);
                });

                const openLineageTraceWindow = (targetNode) => {
                    if (!targetNode) return;
                    const chainNodes = [];
                    let cur = byId[targetNode.id] || targetNode;
                    let guard = 0;
                    while (cur && guard < 150) {
                        chainNodes.unshift(cur);
                        cur = cur.invited_by ? byId[cur.invited_by] : null;
                        guard++;
                    }

                    const downstreamNodes = [];
                    const collectDownstream = (pid, depth) => {
                        const kids = byParent[pid] || [];
                        kids.forEach(k => {
                            downstreamNodes.push({ node: k, depth });
                            collectDownstream(k.id, depth + 1);
                        });
                    };
                    collectDownstream(targetNode.id, 1);

                    const modalTitle = t('lineage_modal_title').replace('{name}', `${targetNode.name} (@${targetNode.username})`);
                    openSubModal(modalTitle, (sBody) => {
                        const buildPersonRow = (u, stepNum, extraBadgeText) => {
                            const card = document.createElement('div');
                            card.className = 'lineage-step-card' + (u.id === targetNode.id ? ' is-target' : '');

                            const left = document.createElement('div');
                            left.style.cssText = 'display:flex;align-items:center;gap:10px;min-width:0;flex:1';

                            const numEl = document.createElement('span');
                            numEl.className = 'lineage-step-num';
                            numEl.textContent = String(stepNum);
                            left.appendChild(numEl);

                            const info = document.createElement('div');
                            info.style.minWidth = '0';
                            const nameRow = document.createElement('div');
                            nameRow.style.cssText = 'display:flex;align-items:center;gap:6px;flex-wrap:wrap;font-weight:800;font-size:13px';
                            const nm = document.createElement('span');
                            nm.textContent = `${u.name} (@${u.username})`;
                            nameRow.appendChild(nm);

                            if (extraBadgeText) {
                                const b = document.createElement('span');
                                b.className = 'adm-badge-pill primary';
                                b.textContent = extraBadgeText;
                                nameRow.appendChild(b);
                            }

                            const stB = document.createElement('span');
                            stB.className = 'adm-badge-pill ' + (u.status === 'blocked' ? 'danger' : 'success');
                            stB.textContent = u.status === 'blocked' ? t('status_blocked') : t('status_active');
                            nameRow.appendChild(stB);

                            const codeMeta = document.createElement('div');
                            codeMeta.style.cssText = 'font-size:11.5px;color:var(--text-muted);margin-top:2px;direction:ltr;text-align:start';
                            codeMeta.textContent = `🎟️ ${u.invite_code || t('lineage_no_invite_code')}`;

                            info.appendChild(nameRow);
                            info.appendChild(codeMeta);
                            left.appendChild(info);

                            const actions = document.createElement('div');
                            actions.style.cssText = 'display:flex;align-items:center;gap:6px;flex-wrap:wrap;flex-shrink:0';

                            const copyUserBtn = document.createElement('button');
                            copyUserBtn.type = 'button';
                            copyUserBtn.className = 'btn btn-secondary btn-sm';
                            copyUserBtn.textContent = t('lineage_copy_username');
                            copyUserBtn.addEventListener('click', async () => {
                                await copyTextToClipboard(u.username || u.name || '');
                                toast(t('lineage_username_copied'));
                            });
                            actions.appendChild(copyUserBtn);

                            const copyCodeBtn = document.createElement('button');
                            copyCodeBtn.type = 'button';
                            copyCodeBtn.className = 'btn btn-secondary btn-sm';
                            copyCodeBtn.disabled = !u.invite_code;
                            copyCodeBtn.textContent = t('lineage_copy_invite');
                            copyCodeBtn.addEventListener('click', async () => {
                                if (!u.invite_code) return;
                                await copyTextToClipboard(u.invite_code);
                                toast(t('lineage_invite_copied'));
                            });
                            actions.appendChild(copyCodeBtn);

                            card.appendChild(left);
                            card.appendChild(actions);
                            return card;
                        };

                        const scrollWrap = document.createElement('div');
                        scrollWrap.className = 'lineage-trace-list';

                        const ancHead = document.createElement('div');
                        ancHead.style.cssText = 'font-size:12px;font-weight:800;color:var(--primary);margin-bottom:4px';
                        ancHead.textContent = t('lineage_ancestry_sec').replace('{count}', String(chainNodes.length));
                        scrollWrap.appendChild(ancHead);

                        chainNodes.forEach((u, idx) => {
                            let badge = '';
                            if (idx === 0 && !u.invited_by) badge = t('lineage_root_badge');
                            if (u.id === targetNode.id) badge = t('lineage_target_badge');
                            scrollWrap.appendChild(buildPersonRow(u, idx + 1, badge));
                            if (idx < chainNodes.length - 1) {
                                const arr = document.createElement('div');
                                arr.className = 'lineage-arrow-sep';
                                arr.textContent = '↓';
                                scrollWrap.appendChild(arr);
                            }
                        });

                        if (downstreamNodes.length > 0) {
                            const descHead = document.createElement('div');
                            descHead.style.cssText = 'font-size:12px;font-weight:800;color:var(--primary);margin:12px 0 4px';
                            descHead.textContent = t('lineage_descendants_sec').replace('{count}', String(downstreamNodes.length));
                            scrollWrap.appendChild(descHead);

                            downstreamNodes.forEach((entry, dIdx) => {
                                const row = buildPersonRow(entry.node, dIdx + 1, `+${entry.depth}`);
                                scrollWrap.appendChild(row);
                            });
                        }

                        sBody.appendChild(scrollWrap);
                    });
                };

                const flatTreeEntries = [];
                const visitedTreeIds = new Set();
                const collectDfs = (parentId, depth) => {
                    const children = byParent[parentId] || [];
                    children.forEach(n => {
                        if (visitedTreeIds.has(n.id)) return;
                        visitedTreeIds.add(n.id);
                        flatTreeEntries.push({ node: n, depth });
                        if (byParent[n.id] && byParent[n.id].length > 0) {
                            collectDfs(n.id, depth + 1);
                        }
                    });
                };
                collectDfs(0, 0);
                nodes.forEach(n => {
                    if (!visitedTreeIds.has(n.id)) {
                        visitedTreeIds.add(n.id);
                        flatTreeEntries.push({ node: n, depth: 0 });
                    }
                });

                const treeSearchIn = document.createElement('input');
                treeSearchIn.type = 'text';
                treeSearchIn.className = 'input';
                treeSearchIn.style.marginBottom = '10px';
                treeSearchIn.placeholder = t('adm_search_lineage_ph');
                treeCard.appendChild(treeSearchIn);

                const treeListWrap = document.createElement('div');
                const treePagerMount = document.createElement('div');
                let treePage = 1;
                let treePageSize = admDefaultPageSize;

                const renderLineageNodeCard = (n, depth, container) => {
                    {
                        const nodeWrap = document.createElement('div');
                        if (depth > 0) {
                            nodeWrap.style.paddingInlineStart = `${Math.min(depth, 6) * 16}px`;
                            nodeWrap.style.borderInlineStart = '2px solid var(--border)';
                            nodeWrap.style.marginInlineStart = '6px';
                        }
                        const itemRow = document.createElement('div');
                        itemRow.className = 'adm-item-card';
                        itemRow.style.marginBottom = '8px';

                        const top = document.createElement('div');
                        top.className = 'adm-item-top';

                        const lbl = document.createElement('div');
                        const titleDiv = document.createElement('div');
                        titleDiv.className = 'adm-item-title';
                        const nTxtSpan = document.createElement('span');
                        nTxtSpan.textContent = `${n.name} (@${n.username})`;
                        titleDiv.appendChild(nTxtSpan);
                        const nCopyChip = createCopyUsernameChip(n.username || n.login_username);
                        if (nCopyChip) titleDiv.appendChild(nCopyChip);

                        const stBadge = document.createElement('span');
                        stBadge.className = 'adm-badge-pill ' + (n.status === 'blocked' ? 'danger' : 'success');
                        stBadge.textContent = n.status === 'blocked' ? t('status_blocked') : t('status_active');
                        titleDiv.appendChild(stBadge);

                        const subBadge = document.createElement('span');
                        subBadge.className = 'adm-badge-pill primary';
                        subBadge.textContent = `🌳 ${t('adm_subtree_lbl')}: ${n.total_descendants_count}`;
                        titleDiv.appendChild(subBadge);

                        const metaDiv = document.createElement('div');
                        metaDiv.className = 'adm-item-meta';
                        metaDiv.textContent = `🎟️ ${t('adm_code_lbl')}: ${n.invite_code} • ${t('adm_direct_inv_lbl')}: ${n.direct_invitees_count}`;
                        lbl.appendChild(titleDiv);
                        lbl.appendChild(metaDiv);
                        top.appendChild(lbl);
                        itemRow.appendChild(top);

                        const actBtns = document.createElement('div');
                        actBtns.className = 'adm-item-actions';

                        const chainBtn = document.createElement('button');
                        chainBtn.type = 'button';
                        chainBtn.className = 'btn btn-secondary btn-sm';
                        chainBtn.textContent = t('adm_trace_root_btn');
                        chainBtn.addEventListener('click', () => {
                            openLineageTraceWindow(n);
                        });
                        actBtns.appendChild(chainBtn);

                        const isSelfOrSuper = (store.user && n.id === store.user.id) || n.role === 'superadmin';
                        if (!isSelfOrSuper) {
                            const totalWithSelf = 1 + Number(n.total_descendants_count || 0);
                            const isBlockedNow = n.status === 'blocked';

                            // Option 1: Simultaneously Block (or Unblock) User + All Subtree Descendants
                            const blockSelfAndTreeBtn = document.createElement('button');
                            blockSelfAndTreeBtn.type = 'button';
                            blockSelfAndTreeBtn.className = isBlockedNow ? 'btn btn-secondary btn-sm' : 'btn btn-danger btn-sm';
                            blockSelfAndTreeBtn.textContent = `${isBlockedNow ? t('adm_unblock_user_and_subtree') : t('adm_block_user_and_subtree')} (${totalWithSelf})`;
                            blockSelfAndTreeBtn.addEventListener('click', async () => {
                                const ap = await askApproval({
                                    title: isBlockedNow ? t('adm_unblock_user_subtree_title') : t('adm_block_user_subtree_title'),
                                    desc: (isBlockedNow ? t('adm_unblock_user_subtree_desc') : t('adm_block_user_subtree_desc'))
                                        .replace('{name}', `${n.name} (@${n.username})`)
                                        .replace('{count}', String(totalWithSelf)),
                                    checkboxLabel: t('adm_user_subtree_chk'),
                                    checkboxRequired: true,
                                    checkboxDefault: false,
                                    danger: !isBlockedNow,
                                    icon: isBlockedNow ? '✅' : '🚫'
                                });
                                if (!ap.approved) return;
                                const r = await apiCall('admin_referral_branch_action', {
                                    root_user_id: n.id,
                                    branch_action: isBlockedNow ? 'unblock_branch' : 'block_branch',
                                    include_root: 1
                                });
                                if (r.ok) {
                                    toast(store.lang === 'fa'
                                        ? (isBlockedNow ? `✅ مسدودیت ${r.data.affected_count} حساب (@${n.username} و زیرشاخه‌ها) برطرف شد.` : `🚫 ${r.data.affected_count} حساب (@${n.username} و زیرشاخه‌ها) مسدود شد.`)
                                        : (isBlockedNow ? `✅ Unblocked ${r.data.affected_count} accounts (@${n.username} & subtree).` : `🚫 Blocked ${r.data.affected_count} accounts (@${n.username} & subtree).`));
                                    renderTab('lineage');
                                }
                            });
                            actBtns.appendChild(blockSelfAndTreeBtn);

                            // Option 2: Simultaneously Delete User + All Subtree Descendants
                            const delSelfAndTreeBtn = document.createElement('button');
                            delSelfAndTreeBtn.type = 'button';
                            delSelfAndTreeBtn.className = 'btn btn-danger btn-sm';
                            delSelfAndTreeBtn.textContent = `${t('adm_delete_user_and_subtree')} (${totalWithSelf})`;
                            delSelfAndTreeBtn.addEventListener('click', async () => {
                                const ap = await askApproval({
                                    title: t('adm_delete_user_subtree_title'),
                                    desc: t('adm_delete_user_subtree_desc')
                                        .replace('{name}', `${n.name} (@${n.username})`)
                                        .replace('{count}', String(totalWithSelf)),
                                    checkboxLabel: t('adm_user_subtree_chk'),
                                    checkboxRequired: true,
                                    checkboxDefault: false,
                                    danger: true,
                                    icon: '🗑️'
                                });
                                if (!ap.approved) return;
                                const r = await apiCall('admin_referral_branch_action', {
                                    root_user_id: n.id,
                                    branch_action: 'delete_branch',
                                    include_root: 1
                                });
                                if (r.ok) {
                                    toast(store.lang === 'fa'
                                        ? `🗑️ ${r.data.affected_count} حساب کاربری (@${n.username} و زیرشاخه‌ها) حذف شد.`
                                        : `🗑️ Deleted ${r.data.affected_count} accounts (@${n.username} & subtree).`);
                                    renderTab('lineage');
                                }
                            });
                            actBtns.appendChild(delSelfAndTreeBtn);
                        }

                        if (n.total_descendants_count > 0) {
                            const banBranchBtn = document.createElement('button');
                            banBranchBtn.type = 'button';
                            banBranchBtn.className = 'btn btn-secondary btn-sm';
                            banBranchBtn.textContent = `${t('adm_ban_branch_btn')} (${n.total_descendants_count})`;
                            banBranchBtn.addEventListener('click', async () => {
                                const ap = await askApproval({
                                    title: `${t('adm_ban_branch_btn')} — @${n.username}`,
                                    desc: `🌳 ${t('adm_subtree_size_desc')} ${n.total_descendants_count} (@${n.username})`,
                                    checkboxLabel: t('adm_user_subtree_chk'),
                                    checkboxRequired: true,
                                    checkboxDefault: false,
                                    danger: true,
                                    icon: '🚫'
                                });
                                if (!ap.approved) return;
                                const r = await apiCall('admin_referral_branch_action', {
                                    root_user_id: n.id,
                                    branch_action: 'block_branch',
                                    include_root: 0
                                });
                                if (r.ok) {
                                    toast(store.lang === 'fa' ? `🚫 ${r.data.affected_count} حساب در زیرشاخه @${n.username} مسدود شد.` : `🚫 Blocked ${r.data.affected_count} accounts in @${n.username}'s subtree.`);
                                    renderTab('lineage');
                                }
                            });
                            actBtns.appendChild(banBranchBtn);

                            const delBranchBtn = document.createElement('button');
                            delBranchBtn.type = 'button';
                            delBranchBtn.className = 'btn btn-secondary btn-sm';
                            delBranchBtn.textContent = t('adm_del_branch_btn');
                            delBranchBtn.addEventListener('click', async () => {
                                const ap = await askApproval({
                                    title: `${t('adm_del_branch_btn')} — @${n.username}`,
                                    desc: `🗑️ ${t('adm_del_descendants_desc')} ${n.total_descendants_count} (@${n.username})`,
                                    checkboxLabel: t('adm_user_subtree_chk'),
                                    checkboxRequired: true,
                                    checkboxDefault: false,
                                    danger: true,
                                    icon: '🗑️'
                                });
                                if (!ap.approved) return;
                                const r = await apiCall('admin_referral_branch_action', {
                                    root_user_id: n.id,
                                    branch_action: 'delete_branch',
                                    include_root: 0
                                });
                                if (r.ok) {
                                    toast(store.lang === 'fa' ? `🗑️ ${r.data.affected_count} حساب از زیرشاخه @${n.username} حذف شد.` : `🗑️ Deleted ${r.data.affected_count} accounts from @${n.username}'s subtree.`);
                                    renderTab('lineage');
                                }
                            });
                            actBtns.appendChild(delBranchBtn);
                        }

                        itemRow.appendChild(actBtns);
                        nodeWrap.appendChild(itemRow);
                        container.appendChild(nodeWrap);
                    }
                };

                const drawLineageTreePage = () => {
                    treeListWrap.innerHTML = '';
                    treePagerMount.innerHTML = '';
                    const tq = treeSearchIn.value.trim().toLowerCase();
                    const matchedTree = flatTreeEntries.filter(({ node: n }) => {
                        if (!tq) return true;
                        const nm = String(n.name || '').toLowerCase();
                        const un = String(n.username || '').toLowerCase();
                        const cd = String(n.invite_code || '').toLowerCase();
                        const iv = String(n.inviter_username || '').toLowerCase();
                        return nm.includes(tq) || un.includes(tq) || cd.includes(tq) || iv.includes(tq) || (`#${n.id}` === tq);
                    });
                    const pgT = buildAdminPaginationControls({
                        totalItems: matchedTree.length,
                        page: treePage,
                        pageSize: treePageSize,
                        onPageChange: nextP => { treePage = nextP; drawLineageTreePage(); },
                        onPageSizeChange: nextSz => { treePageSize = nextSz; admDefaultPageSize = nextSz; treePage = 1; drawLineageTreePage(); }
                    });
                    treePage = pgT.curPage;
                    treePagerMount.appendChild(pgT.bar);

                    if (matchedTree.length === 0) {
                        const emp = document.createElement('div');
                        emp.style.cssText = 'text-align:center;padding:16px;color:var(--text-muted)';
                        emp.textContent = t('adm_no_results');
                        treeListWrap.appendChild(emp);
                        return;
                    }
                    matchedTree.slice(pgT.fromOffset, pgT.toOffset).forEach(({ node, depth }) => {
                        renderLineageNodeCard(node, tq ? 0 : depth, treeListWrap);
                    });
                };

                treeSearchIn.addEventListener('input', () => { treePage = 1; drawLineageTreePage(); });
                treeCard.appendChild(treeListWrap);
                treeCard.appendChild(treePagerMount);
                drawLineageTreePage();
                tabContent.appendChild(treeCard);
            } else if (tabId === 'reports') {
                const res = await apiCall('admin_reports_list', { status: 'all' });
                tabContent.innerHTML = '';
                const reports = (res.ok && res.data.reports) ? res.data.reports : [];
                if (reports.length === 0) {
                    const emptyBox = document.createElement('div');
                    emptyBox.className = 'card-box';
                    emptyBox.style.textAlign = 'center';
                    emptyBox.textContent = t('adm_rep_empty');
                    tabContent.appendChild(emptyBox);
                    return;
                }
                const repTypeMap = { user: t('rep_type_user'), group: t('rep_type_group'), channel: t('rep_type_channel'), message: t('rep_type_message') };
                const repStMap = { pending: t('rep_status_pending'), resolved: t('rep_status_resolved'), dismissed: t('rep_status_dismissed') };
                const repReasonMap = { spam: t('rep_reason_spam'), abuse: t('rep_reason_abuse'), scam: t('rep_reason_scam'), illegal: t('rep_reason_illegal'), other: t('rep_reason_other') };

                const repToolbar = document.createElement('div');
                repToolbar.className = 'adm-toolbar';
                const repSearchIn = document.createElement('input');
                repSearchIn.type = 'text';
                repSearchIn.className = 'input';
                repSearchIn.style.flex = '1';
                repSearchIn.style.minWidth = '200px';
                repSearchIn.placeholder = t('adm_search_reports_ph');

                const repFilterGrp = document.createElement('div');
                repFilterGrp.style.cssText = 'display:flex;gap:4px;flex-wrap:wrap';
                let repStatusFilter = 'all';
                let reportsPage = 1;
                let reportsPageSize = admDefaultPageSize;

                const repListWrap = document.createElement('div');
                const repPagerMount = document.createElement('div');

                const drawReportsList = () => {
                    repListWrap.innerHTML = '';
                    repPagerMount.innerHTML = '';
                    const rq = repSearchIn.value.trim().toLowerCase();
                    const filteredReps = reports.filter(rp => {
                        if (repStatusFilter !== 'all' && rp.status !== repStatusFilter) return false;
                        if (!rq) return true;
                        const hay = `#${rp.id} ${rp.target_summary || ''} ${rp.description || ''} ${rp.reporter_username || ''} ${rp.reporter_name || ''} ${rp.reason || ''} ${repReasonMap[rp.reason] || ''}`.toLowerCase();
                        return hay.includes(rq);
                    });

                    const pgR = buildAdminPaginationControls({
                        totalItems: filteredReps.length,
                        page: reportsPage,
                        pageSize: reportsPageSize,
                        onPageChange: nextP => { reportsPage = nextP; drawReportsList(); },
                        onPageSizeChange: nextSz => { reportsPageSize = nextSz; admDefaultPageSize = nextSz; reportsPage = 1; drawReportsList(); }
                    });
                    reportsPage = pgR.curPage;
                    repPagerMount.appendChild(pgR.bar);

                    if (filteredReps.length === 0) {
                        const emp = document.createElement('div');
                        emp.className = 'card-box';
                        emp.style.textAlign = 'center';
                        emp.textContent = t('adm_no_results');
                        repListWrap.appendChild(emp);
                        return;
                    }

                    filteredReps.slice(pgR.fromOffset, pgR.toOffset).forEach(rp => {
                    const card = document.createElement('div');
                    card.className = 'adm-item-card';

                    const head = document.createElement('div');
                    head.className = 'adm-item-title';
                    const idSpan = document.createElement('span');
                    idSpan.textContent = `#${rp.id} • ${repTypeMap[rp.target_type] || rp.target_type}: ${rp.target_summary}`;
                    head.appendChild(idSpan);

                    const stPill = document.createElement('span');
                    stPill.className = 'adm-badge-pill ' + (rp.status === 'pending' ? 'warning' : (rp.status === 'resolved' ? 'success' : ''));
                    stPill.textContent = repStMap[rp.status] || rp.status;
                    head.appendChild(stPill);

                    const reasonPill = document.createElement('span');
                    reasonPill.className = 'adm-badge-pill danger';
                    reasonPill.textContent = repReasonMap[rp.reason] || rp.reason;
                    head.appendChild(reasonPill);

                    const desc = document.createElement('div');
                    desc.className = 'adm-quote-box';
                    desc.textContent = rp.description;

                    const meta = document.createElement('div');
                    meta.className = 'adm-item-meta';
                    meta.style.cssText = 'display:flex;align-items:center;gap:6px;flex-wrap:wrap';
                    const metaSpan = document.createElement('span');
                    metaSpan.textContent = `🚩 ${t('adm_rep_by')} @${rp.reporter_username} (${formatDisplayName(rp.reporter_name)}) • ${formatDate(rp.created_at)}`;
                    meta.appendChild(metaSpan);
                    if (rp.reporter_username) {
                        const repChip = createCopyUsernameChip(rp.reporter_username);
                        if (repChip) meta.appendChild(repChip);
                    }
                    if (rp.target_username) {
                        const tgtChip = createCopyUsernameChip(rp.target_username);
                        if (tgtChip) meta.appendChild(tgtChip);
                    }

                    card.appendChild(head);
                    card.appendChild(desc);
                    card.appendChild(meta);

                    const btns = document.createElement('div');
                    btns.className = 'adm-item-actions';

                    const actCall = async (ra) => {
                        const isDestructive = (ra === 'ban_target_user' || ra === 'delete_target' || ra === 'delete_report');
                        const ap = await askApproval({
                            title: `#${rp.id} — ${rp.target_summary}`,
                            desc: t('ask_adm_report_act'),
                            danger: isDestructive,
                            icon: isDestructive ? '🚨' : '🛡️'
                        });
                        if (!ap.approved) return;
                        const rr = await apiCall('admin_report_action', { report_id: rp.id, report_action: ra });
                        if (rr.ok) {
                            const toastMap = {
                                resolve: t('adm_rep_resolved_toast'),
                                dismiss: t('adm_rep_dismissed_toast'),
                                ban_target_user: t('adm_rep_banned_toast'),
                                delete_target: t('adm_rep_deleted_toast'),
                                delete_report: t('adm_rep_record_deleted_toast')
                            };
                            toast(toastMap[ra] || t('adm_rep_resolved_toast'));
                            renderTab('reports');
                        } else {
                            toast(rr.message || t('err_generic'), true);
                        }
                    };

                    if (rp.can_ghost && Number(rp.chat_id) > 0) {
                        const bGhost = document.createElement('button');
                        bGhost.type = 'button';
                        bGhost.className = 'btn btn-secondary btn-sm';
                        bGhost.textContent = t('adm_rep_ghost_inspect_btn');
                        bGhost.addEventListener('click', async () => {
                            close();
                            await switchChatToGhostMode(Number(rp.chat_id), rp.target_summary || `#${rp.chat_id}`);
                        });
                        btns.appendChild(bGhost);
                    }

                    if (rp.status === 'pending') {
                        const bRes = document.createElement('button');
                        bRes.type = 'button';
                        bRes.className = 'btn btn-primary btn-sm';
                        bRes.textContent = t('adm_rep_resolve_btn');
                        bRes.addEventListener('click', () => actCall('resolve'));

                        const bBan = document.createElement('button');
                        bBan.type = 'button';
                        bBan.className = 'btn btn-danger btn-sm';
                        bBan.textContent = t('adm_rep_ban_btn');
                        bBan.addEventListener('click', () => actCall('ban_target_user'));

                        const bDel = document.createElement('button');
                        bDel.type = 'button';
                        bDel.className = 'btn btn-danger btn-sm';
                        bDel.textContent = t('adm_rep_del_btn');
                        bDel.addEventListener('click', () => actCall('delete_target'));

                        const bDis = document.createElement('button');
                        bDis.type = 'button';
                        bDis.className = 'btn btn-secondary btn-sm';
                        bDis.textContent = t('adm_rep_dismiss_btn');
                        bDis.addEventListener('click', () => actCall('dismiss'));

                        btns.appendChild(bRes);
                        btns.appendChild(bBan);
                        btns.appendChild(bDel);
                        btns.appendChild(bDis);
                    }

                    const bDelRec = document.createElement('button');
                    bDelRec.type = 'button';
                    bDelRec.className = 'btn btn-secondary btn-sm';
                    bDelRec.textContent = t('adm_rep_del_record_btn');
                    bDelRec.addEventListener('click', () => actCall('delete_report'));
                    btns.appendChild(bDelRec);

                    card.appendChild(btns);
                    repListWrap.appendChild(card);
                    });
                };

                [
                    ['all', t('adm_filter_all')],
                    ['pending', t('rep_status_pending')],
                    ['resolved', t('rep_status_resolved')],
                    ['dismissed', t('rep_status_dismissed')]
                ].forEach(([stId, stLbl]) => {
                    const b = document.createElement('button');
                    b.type = 'button';
                    b.className = 'filter-pill' + (repStatusFilter === stId ? ' active' : '');
                    b.textContent = stLbl;
                    b.addEventListener('click', () => {
                        repStatusFilter = stId;
                        reportsPage = 1;
                        Array.from(repFilterGrp.children).forEach(c => c.classList.remove('active'));
                        b.classList.add('active');
                        drawReportsList();
                    });
                    repFilterGrp.appendChild(b);
                });

                if (reports.some(rx => rx.status !== 'pending')) {
                    const clrHandledBtn = document.createElement('button');
                    clrHandledBtn.type = 'button';
                    clrHandledBtn.className = 'btn btn-secondary btn-sm';
                    clrHandledBtn.textContent = t('adm_rep_clear_handled_btn');
                    clrHandledBtn.addEventListener('click', async () => {
                        const ap = await askApproval({
                            title: t('adm_rep_clear_handled_btn'),
                            desc: t('ask_adm_report_act'),
                            danger: true,
                            icon: '🧹'
                        });
                        if (!ap.approved) return;
                        const cr = await apiCall('admin_report_action', { report_action: 'clear_handled' });
                        if (cr.ok) {
                            toast(t('adm_rep_cleared_handled_toast'));
                            renderTab('reports');
                        } else {
                            toast(cr.message || t('err_generic'), true);
                        }
                    });
                    repFilterGrp.appendChild(clrHandledBtn);
                }

                repToolbar.appendChild(repSearchIn);
                repToolbar.appendChild(repFilterGrp);
                tabContent.appendChild(repToolbar);
                tabContent.appendChild(repListWrap);
                tabContent.appendChild(repPagerMount);

                repSearchIn.addEventListener('input', () => { reportsPage = 1; drawReportsList(); });
                drawReportsList();
            } else if (tabId === 'groups' || tabId === 'channels' || tabId === 'dm_chats') {
                const reqType = tabId === 'groups' ? 'group' : (tabId === 'channels' ? 'channel' : 'dm_all');
                const res = await apiCall('admin_chats_list', { chat_type: reqType });
                tabContent.innerHTML = '';
                const chats = (res.ok && res.data.chats) ? res.data.chats : [];
                const isDmSection = (tabId === 'dm_chats');

                const searchWrap = document.createElement('div');
                searchWrap.className = 'adm-toolbar';
                const chatSearchIn = document.createElement('input');
                chatSearchIn.type = 'text';
                chatSearchIn.className = 'input';
                chatSearchIn.style.flex = '1';
                chatSearchIn.style.minWidth = '200px';
                chatSearchIn.placeholder = isDmSection ? t('adm_dm_search_ph') : t('adm_chat_search_ph');
                searchWrap.appendChild(chatSearchIn);

                const chatFilterGrp = document.createElement('div');
                chatFilterGrp.style.cssText = 'display:flex;gap:4px;flex-wrap:wrap';
                let chatKindVisFilter = 'all';
                const chatFilterDefs = isDmSection
                    ? [
                        ['all', t('adm_filter_all')],
                        ['dm', t('adm_filter_normal_dm')],
                        ['secret', t('adm_filter_secret_dm')],
                        ['blocked', t('status_blocked')]
                    ]
                    : [
                        ['all', t('adm_filter_all')],
                        ['public', t('adm_filter_public')],
                        ['private', t('adm_filter_private')],
                        ['blocked', t('status_blocked')]
                    ];
                searchWrap.appendChild(chatFilterGrp);
                tabContent.appendChild(searchWrap);

                const bulkChatsMount = document.createElement('div');
                const listWrap = document.createElement('div');
                const chatsPagerMount = document.createElement('div');
                tabContent.appendChild(bulkChatsMount);
                tabContent.appendChild(listWrap);
                tabContent.appendChild(chatsPagerMount);

                const selectedChatIds = new Set();
                let chatsPage = 1;
                let chatsPageSize = admDefaultPageSize;

                const runBulkChatsAction = async (bulkOp) => {
                    const ids = Array.from(selectedChatIds);
                    if (!ids.length) return;
                    const ap = await askApproval({
                        title: tabId === 'groups' ? t('adm_tab_groups_sep') : (tabId === 'channels' ? t('adm_tab_channels_sep') : t('adm_tab_dms_sep')),
                        desc: `${t('adm_ask_bulk_action')} (${formatLocalizedCount(ids.length)})`,
                        danger: bulkOp === 'delete' || bulkOp === 'block',
                        icon: bulkOp === 'delete' ? '🗑️' : '🛡️'
                    });
                    if (!ap.approved) return;
                    const r = await apiCall('admin_bulk_chats', { chat_ids: ids, bulk_op: bulkOp });
                    if (r.ok) {
                        selectedChatIds.clear();
                        toast(t('adm_bulk_done_toast'));
                        renderTab(tabId);
                    } else {
                        toast(r.message || t('err_generic'), true);
                    }
                };

                const renderChatsBulkBar = (pageSlice) => {
                    bulkChatsMount.innerHTML = '';
                    const bar = document.createElement('div');
                    bar.className = 'adm-bulk-bar';

                    const leftB = document.createElement('div');
                    leftB.style.cssText = 'display:flex;align-items:center;gap:6px;flex-wrap:wrap;font-size:12.5px;font-weight:800';
                    const cnt = document.createElement('span');
                    cnt.textContent = t('adm_bulk_selected_lbl').replace('{n}', formatLocalizedCount(selectedChatIds.size));
                    leftB.appendChild(cnt);

                    const selPageBtn = document.createElement('button');
                    selPageBtn.type = 'button';
                    selPageBtn.className = 'btn btn-secondary btn-sm';
                    selPageBtn.textContent = t('adm_bulk_select_page_btn');
                    selPageBtn.addEventListener('click', () => {
                        pageSlice.forEach(c => { selectedChatIds.add(c.id); });
                        renderAdminChatsRows();
                    });
                    leftB.appendChild(selPageBtn);

                    if (selectedChatIds.size > 0) {
                        const clrBtn = document.createElement('button');
                        clrBtn.type = 'button';
                        clrBtn.className = 'btn btn-secondary btn-sm';
                        clrBtn.textContent = t('adm_bulk_clear_btn');
                        clrBtn.addEventListener('click', () => {
                            selectedChatIds.clear();
                            renderAdminChatsRows();
                        });
                        leftB.appendChild(clrBtn);
                    }
                    bar.appendChild(leftB);

                    if (selectedChatIds.size > 0) {
                        const rightB = document.createElement('div');
                        rightB.style.cssText = 'display:flex;align-items:center;gap:6px;flex-wrap:wrap';
                        [
                            ['block', t('adm_bulk_block_btn'), 'btn-secondary'],
                            ['unblock', t('adm_bulk_unblock_btn'), 'btn-secondary'],
                            ['delete', t('adm_bulk_delete_btn'), 'btn-danger']
                        ].forEach(([op, lbl, cls]) => {
                            const b = document.createElement('button');
                            b.type = 'button';
                            b.className = `btn ${cls} btn-sm`;
                            b.textContent = lbl;
                            b.addEventListener('click', () => runBulkChatsAction(op));
                            rightB.appendChild(b);
                        });
                        bar.appendChild(rightB);
                    }
                    bulkChatsMount.appendChild(bar);
                };

                const renderAdminChatsRows = () => {
                    listWrap.innerHTML = '';
                    chatsPagerMount.innerHTML = '';
                    const q = chatSearchIn.value.trim().toLowerCase();
                    const filteredChats = chats.filter(c => {
                        if (chatKindVisFilter === 'blocked' && c.status !== 'blocked') return false;
                        if (isDmSection) {
                            if (chatKindVisFilter === 'dm' && c.type !== 'dm') return false;
                            if (chatKindVisFilter === 'secret' && c.type !== 'secret') return false;
                        } else {
                            if (chatKindVisFilter === 'public' && c.visibility !== 'public') return false;
                            if (chatKindVisFilter === 'private' && c.visibility !== 'private') return false;
                        }
                        if (!q) return true;
                        const dt = (isDmSection ? String(c.dm_title || c.title || '') : formatChatTitle(c)).toLowerCase();
                        const hd = String(c.handle || '').toLowerCase();
                        const pTxt = Array.isArray(c.participants)
                            ? c.participants.map(p => `${p.name || ''} ${p.username || ''} ${p.login_username || ''}`).join(' ').toLowerCase()
                            : '';
                        return dt.includes(q) || hd.includes(q) || pTxt.includes(q) || (`#${c.id}` === q);
                    });

                    const pgCh = buildAdminPaginationControls({
                        totalItems: filteredChats.length,
                        page: chatsPage,
                        pageSize: chatsPageSize,
                        onPageChange: nextP => { chatsPage = nextP; renderAdminChatsRows(); },
                        onPageSizeChange: nextSz => { chatsPageSize = nextSz; admDefaultPageSize = nextSz; chatsPage = 1; renderAdminChatsRows(); }
                    });
                    chatsPage = pgCh.curPage;
                    chatsPagerMount.appendChild(pgCh.bar);

                    const pageSlice = filteredChats.slice(pgCh.fromOffset, pgCh.toOffset);
                    renderChatsBulkBar(pageSlice);

                    if (filteredChats.length === 0) {
                        const emp = document.createElement('div');
                        emp.className = 'card-box';
                        emp.style.textAlign = 'center';
                        emp.textContent = t('adm_no_results');
                        listWrap.appendChild(emp);
                        return;
                    }

                    pageSlice.forEach(c => {
                        const row = document.createElement('div');
                        row.className = 'adm-user-card';

                        const top = document.createElement('div');
                        top.className = 'adm-item-top';

                        const leftWrap = document.createElement('div');
                        leftWrap.style.cssText = 'display:flex;align-items:center;gap:10px;min-width:0;flex:1';

                        const cChk = document.createElement('input');
                        cChk.type = 'checkbox';
                        cChk.className = 'adm-select-chk';
                        cChk.checked = selectedChatIds.has(c.id);
                        cChk.addEventListener('change', () => {
                            if (cChk.checked) selectedChatIds.add(c.id);
                            else selectedChatIds.delete(c.id);
                            renderChatsBulkBar(pageSlice);
                        });
                        leftWrap.appendChild(cChk);

                        const cAv = document.createElement('div');
                        cAv.className = 'avatar avatar-sm';
                        const dispTitle = isDmSection ? String(c.dm_title || c.title || `#${c.id}`) : formatChatTitle(c);
                        renderAvatarNode(cAv, dispTitle, c.avatar || '');
                        leftWrap.appendChild(cAv);

                        const info = document.createElement('div');
                        info.style.minWidth = '0';
                        const titleDiv = document.createElement('div');
                        titleDiv.className = 'adm-item-title';
                        const tSpan = document.createElement('span');
                        tSpan.textContent = isDmSection ? dispTitle : `${dispTitle} ${c.handle ? ('(@' + c.handle + ')') : ''}`;
                        titleDiv.appendChild(tSpan);

                        if (isDmSection) {
                            const dmTypeBadge = document.createElement('span');
                            dmTypeBadge.className = 'adm-badge-pill ' + (c.type === 'secret' ? 'warning' : 'primary');
                            dmTypeBadge.textContent = c.type === 'secret' ? t('adm_dm_secret_badge') : t('adm_dm_normal_badge');
                            titleDiv.appendChild(dmTypeBadge);
                        } else {
                            const typeBadge = document.createElement('span');
                            typeBadge.className = 'adm-badge-pill primary';
                            typeBadge.textContent = c.type === 'channel' ? t('type_channel') : t('type_group');
                            titleDiv.appendChild(typeBadge);

                            const visPill = document.createElement('span');
                            visPill.className = 'adm-badge-pill ' + (c.visibility === 'public' ? '' : 'warning');
                            visPill.textContent = (c.visibility === 'public' ? '🌐 ' + t('vis_public_short') : '🔒 ' + t('vis_private_short'));
                            titleDiv.appendChild(visPill);

                            const amMember = Number(c.am_member) > 0;
                            const memPill = document.createElement('span');
                            memPill.className = amMember ? 'adm-badge-pill success' : 'ghost-pill-badge';
                            memPill.textContent = amMember ? t('adm_member_yes_badge') : t('adm_member_no_badge');
                            titleDiv.appendChild(memPill);
                        }

                        if (!isDmSection && c.history === 'from_join') {
                            const hBadge = document.createElement('span');
                            hBadge.className = 'adm-badge-pill';
                            hBadge.textContent = t('adm_hist_closed_badge');
                            titleDiv.appendChild(hBadge);
                        }
                        if (Number(c.is_default) === 1) {
                            const defBadge = document.createElement('span');
                            defBadge.className = 'adm-badge-pill success';
                            defBadge.textContent = t('badge_default');
                            titleDiv.appendChild(defBadge);
                        }
                        if (Number(c.all_muted) === 1) {
                            const mBadge = document.createElement('span');
                            mBadge.className = 'adm-badge-pill warning';
                            mBadge.textContent = t('badge_muted');
                            titleDiv.appendChild(mBadge);
                        }
                        if (c.status === 'blocked') {
                            const bBadge = document.createElement('span');
                            bBadge.className = 'adm-badge-pill danger';
                            bBadge.textContent = t('status_blocked');
                            titleDiv.appendChild(bBadge);
                        }

                        const metaDiv = document.createElement('div');
                        metaDiv.className = 'adm-item-meta';
                        metaDiv.style.cssText = 'display:flex;align-items:center;gap:6px;flex-wrap:wrap';
                        if (isDmSection && Array.isArray(c.participants)) {
                            const peersMeta = c.participants.map(p => {
                                const hdl = p.no_username ? `[${p.login_username}]` : `@${p.username || p.login_username}`;
                                return `${p.name} (${hdl})`;
                            }).join('  •  ');
                            const mSpan = document.createElement('span');
                            mSpan.textContent = `${peersMeta} • #${c.id}`;
                            metaDiv.appendChild(mSpan);
                            c.participants.forEach(p => {
                                const pChip = createCopyUsernameChip(p.username || p.login_username);
                                if (pChip) metaDiv.appendChild(pChip);
                            });
                        } else {
                            const effCap = Number(c.effective_max_members || 0);
                            const capSuffix = effCap > 0 ? ` / ${formatLocalizedCount(effCap)}` : '';
                            const mSpan = document.createElement('span');
                            mSpan.textContent = `👥 ${formatMemberCount(c.member_count)}${capSuffix} ${t('members')} • #${c.id}${c.owner_username ? (' • 👑 @' + c.owner_username) : ''}`;
                            metaDiv.appendChild(mSpan);
                            if (c.owner_username) {
                                const owChip = createCopyUsernameChip(c.owner_username);
                                if (owChip) metaDiv.appendChild(owChip);
                            }
                        }
                        info.appendChild(titleDiv);
                        info.appendChild(metaDiv);
                        leftWrap.appendChild(info);
                        top.appendChild(leftWrap);
                        row.appendChild(top);

                        const btns = document.createElement('div');
                        btns.className = 'adm-item-actions';
                        btns.style.marginTop = '8px';

                        if (isDmSection) {
                            // Item 11: Ghost View ONLY for normal 2-way DMs, strictly excluded for Secret Chats!
                            if (c.type === 'dm') {
                                const ghostBtn = document.createElement('button');
                                ghostBtn.type = 'button';
                                ghostBtn.className = 'btn btn-primary btn-sm';
                                ghostBtn.textContent = t('ghost_enter_btn');
                                ghostBtn.addEventListener('click', async () => {
                                    close();
                                    await enterChatAsGhost(c.id);
                                });
                                btns.appendChild(ghostBtn);
                            }

                            (c.participants || []).forEach(p => {
                                const cpPeerBtn = document.createElement('button');
                                cpPeerBtn.type = 'button';
                                cpPeerBtn.className = 'btn btn-secondary btn-sm';
                                const hdl = p.username ? `@${p.username}` : `@${p.login_username || ''}`;
                                cpPeerBtn.textContent = t('adm_dm_copy_one_peer_tpl').replace('{name}', p.name || hdl);
                                cpPeerBtn.addEventListener('click', async () => {
                                    const txt = `${p.name} (${hdl})`;
                                    await copyTextToClipboard(txt);
                                    toast(t('adm_dm_one_peer_copied_toast') + txt);
                                });
                                btns.appendChild(cpPeerBtn);
                            });

                            const blkDmBtn = document.createElement('button');
                            blkDmBtn.type = 'button';
                            blkDmBtn.className = 'btn btn-secondary btn-sm';
                            blkDmBtn.textContent = c.status === 'blocked' ? t('adm_dm_unblock_write_btn') : t('adm_dm_block_write_btn');
                            blkDmBtn.addEventListener('click', async () => {
                                const willBlock = c.status !== 'blocked';
                                const ap = await askApproval({
                                    title: willBlock ? t('adm_dm_block_write_btn') : t('adm_dm_unblock_write_btn'),
                                    desc: `${t('ask_adm_block_chat')}\n💬 ${dispTitle}`,
                                    danger: willBlock,
                                    icon: willBlock ? '🚫' : '✅'
                                });
                                if (!ap.approved) return;
                                const r = await apiCall('admin_dm_block_toggle', { chat_id: c.id, blocked: willBlock ? 1 : 0 });
                                if (r.ok) {
                                    toast((willBlock ? t('adm_chat_blocked_toast') : t('adm_chat_unblocked_toast')) + ` (${dispTitle})`);
                                    renderTab(tabId);
                                } else {
                                    toast(r.message || t('err_generic'), true);
                                }
                            });
                            btns.appendChild(blkDmBtn);

                            const delDmBtn = document.createElement('button');
                            delDmBtn.type = 'button';
                            delDmBtn.className = 'btn btn-danger btn-sm';
                            delDmBtn.textContent = '🗑️ ' + t('adm_delete_btn');
                            delDmBtn.addEventListener('click', async () => {
                                const ap = await askApproval({
                                    title: '🗑️ ' + t('adm_delete_btn'),
                                    desc: (c.type === 'secret' ? t('adm_del_desc_secret') : t('adm_del_desc_dm')) + '\n💬 ' + dispTitle,
                                    danger: true,
                                    icon: '🗑️'
                                });
                                if (!ap.approved) return;
                                const r = await apiCall('admin_chat_delete', { chat_id: c.id });
                                if (r.ok) {
                                    toast(`${t('adm_chat_deleted_toast')} (${dispTitle})`);
                                    renderTab(tabId);
                                } else {
                                    toast(r.message || t('err_generic'), true);
                                }
                            });
                            btns.appendChild(delDmBtn);
                        } else {
                            const amMember = Number(c.am_member) > 0;
                            if (!amMember) {
                                const ghostBtn = document.createElement('button');
                                ghostBtn.type = 'button';
                                ghostBtn.className = 'btn btn-primary btn-sm';
                                ghostBtn.textContent = t('ghost_enter_btn');
                                ghostBtn.addEventListener('click', async () => {
                                    close();
                                    await enterChatAsGhost(c.id);
                                });
                                btns.appendChild(ghostBtn);

                                const normJoinBtn = document.createElement('button');
                                normJoinBtn.type = 'button';
                                normJoinBtn.className = 'btn btn-secondary btn-sm';
                                normJoinBtn.textContent = t('ghost_join_normal_btn');
                                normJoinBtn.addEventListener('click', async () => {
                                    close();
                                    await joinGhostChatNormally(c.id);
                                });
                                btns.appendChild(normJoinBtn);
                            } else {
                                const openChatBtn = document.createElement('button');
                                openChatBtn.type = 'button';
                                openChatBtn.className = 'btn btn-primary btn-sm';
                                openChatBtn.textContent = t('adm_open_joined_chat_btn');
                                openChatBtn.addEventListener('click', async () => {
                                    close();
                                    store.ghostChat = null;
                                    await selectChat(c.id);
                                });
                                btns.appendChild(openChatBtn);

                                const toGhostBtn = document.createElement('button');
                                toGhostBtn.type = 'button';
                                toGhostBtn.className = 'btn btn-secondary btn-sm';
                                toGhostBtn.textContent = t('ghost_switch_btn');
                                toGhostBtn.addEventListener('click', async () => {
                                    close();
                                    await switchChatToGhostMode(c.id, dispTitle);
                                });
                                btns.appendChild(toGhostBtn);
                            }

                            const capBtn = document.createElement('button');
                            capBtn.type = 'button';
                            capBtn.className = 'btn btn-secondary btn-sm';
                            capBtn.textContent = t('adm_btn_chat_cap');
                            capBtn.addEventListener('click', async () => {
                                const curOvr = Number(c.super_max_members || 0);
                                const ap = await askApproval({
                                    title: t('adm_chat_cap_modal_title'),
                                    desc: `${dispTitle}\n${t('adm_chat_cap_override_lbl')}`,
                                    danger: false,
                                    icon: '👥',
                                    input: {
                                        label: t('adm_chat_cap_custom_ph'),
                                        type: 'number',
                                        value: String(curOvr),
                                        placeholder: '0',
                                        required: true,
                                        dir: 'ltr'
                                    }
                                });
                                if (!ap.approved) return;
                                const nextVal = parseInt(String(ap.value || '0').trim(), 10);
                                const r = await apiCall('admin_chat_capacity_override', {
                                    chat_id: c.id,
                                    super_max_members: Number.isFinite(nextVal) ? nextVal : 0
                                });
                                if (r.ok) {
                                    toast(t('adm_chat_cap_saved'));
                                    const cr = await apiCall('chats_list');
                                    if (cr.ok && cr.data && cr.data.chats) {
                                        store.chats = cr.data.chats;
                                        renderChatList();
                                    }
                                    renderTab(tabId);
                                } else {
                                    toast(r.message || t('err_generic'), true);
                                }
                            });
                            btns.appendChild(capBtn);

                            const defBtn = document.createElement('button');
                            defBtn.type = 'button';
                            defBtn.className = 'btn btn-secondary btn-sm';
                            defBtn.textContent = Number(c.is_default) === 1 ? t('adm_unset_default_btn') : t('adm_set_default_btn');
                            defBtn.addEventListener('click', async () => {
                                const nextDef = Number(c.is_default) === 1 ? 0 : 1;
                                const ap = await askApproval({
                                    title: dispTitle,
                                    desc: t('ask_adm_default_chat'),
                                    danger: false,
                                    icon: '⭐'
                                });
                                if (!ap.approved) return;
                                const r = await apiCall('admin_default_chat_set', { chat_id: c.id, is_default: nextDef });
                                if (r.ok) {
                                    toast((nextDef === 1 ? t('adm_chat_def_on_toast') : t('adm_chat_def_off_toast')) + ` (${dispTitle})`);
                                    renderTab(tabId);
                                }
                            });
                                btns.appendChild(defBtn);

                            const mvAdmBtn = document.createElement('button');
                            mvAdmBtn.type = 'button';
                            mvAdmBtn.className = 'btn btn-secondary btn-sm';
                            const curOvBadge = (c.super_msg_viewers_override && c.super_msg_viewers_override !== 'inherit') ? ` (${c.super_msg_viewers_override})` : '';
                            mvAdmBtn.textContent = t('adm_chat_viewers_btn') + curOvBadge;
                            mvAdmBtn.addEventListener('click', () => {
                                openAdminChatViewersOverrideModal(c, dispTitle, () => renderTab(tabId));
                            });
                            btns.appendChild(mvAdmBtn);

                            const blkChatBtn = document.createElement('button');
                            blkChatBtn.type = 'button';
                            blkChatBtn.className = 'btn btn-secondary btn-sm';
                            blkChatBtn.textContent = c.status === 'blocked' ? t('adm_unblock_chat_btn') : t('adm_block_chat_btn');
                            blkChatBtn.addEventListener('click', async () => {
                                const willBlock = c.status !== 'blocked';
                                const ap = await askApproval({
                                    title: willBlock ? t('adm_block_chat_btn') : t('adm_unblock_chat_btn'),
                                    desc: `${t('ask_adm_block_chat')}\n💬 ${dispTitle}`,
                                    danger: willBlock,
                                    icon: willBlock ? '🚫' : '✅'
                                });
                                if (!ap.approved) return;
                                const r = await apiCall('admin_chat_block', { chat_id: c.id, status: willBlock ? 'blocked' : 'active' });
                                if (r.ok) {
                                    toast((willBlock ? t('adm_chat_blocked_toast') : t('adm_chat_unblocked_toast')) + ` (${dispTitle})`);
                                    renderTab(tabId);
                                }
                            });
                            btns.appendChild(blkChatBtn);

                            if (Number(c.is_default) !== 1) {
                                const delBtn = document.createElement('button');
                                delBtn.type = 'button';
                                delBtn.className = 'btn btn-danger btn-sm';
                                delBtn.textContent = '🗑️ ' + t('adm_delete_btn');
                                delBtn.addEventListener('click', async () => {
                                    const ap = await askApproval({
                                        title: '🗑️ ' + t('adm_delete_btn'),
                                        desc: (c.type === 'channel' ? t('adm_del_desc_channel') : t('adm_del_desc_group')) + '\n💬 ' + dispTitle,
                                        danger: true,
                                        icon: '🗑️'
                                    });
                                    if (!ap.approved) return;
                                    const r = await apiCall('admin_chat_delete', { chat_id: c.id });
                                    if (r.ok) {
                                        toast(`${t('adm_chat_deleted_toast')} (${dispTitle})`);
                                        renderTab(tabId);
                                    }
                                });
                                btns.appendChild(delBtn);
                            }
                        }

                        row.appendChild(btns);
                        listWrap.appendChild(row);
                    });
                };
                chatFilterDefs.forEach(([fk, fl]) => {
                    const b = document.createElement('button');
                    b.type = 'button';
                    b.className = 'filter-pill' + (chatKindVisFilter === fk ? ' active' : '');
                    b.textContent = fl;
                    b.addEventListener('click', () => {
                        chatKindVisFilter = fk;
                        chatsPage = 1;
                        Array.from(chatFilterGrp.children).forEach(x => x.classList.remove('active'));
                        b.classList.add('active');
                        renderAdminChatsRows();
                    });
                    chatFilterGrp.appendChild(b);
                });
                chatSearchIn.addEventListener('input', () => { chatsPage = 1; renderAdminChatsRows(); });
                renderAdminChatsRows();
            } else if (tabId === 'storage') {
                const stRes = await apiCall('admin_stats');
                const sRes = await apiCall('admin_settings_get');
                tabContent.innerHTML = '';

                const d = (stRes.ok && stRes.data) ? stRes.data : {};
                const curSettings = (sRes.ok && sRes.data.settings) ? sRes.data.settings : store.settings;

                let usedTotalBytes = Number(d.disk_usage_bytes || 0);
                let maxTotalMb = Number(curSettings.max_total_storage_mb || 0);
                let maxUserMb = Number(curSettings.max_user_storage_mb || 0);
                let maxFileMb = Number(curSettings.max_file_mb || curSettings.max_upload_mb || 16);
                let autoHours = Number(curSettings.file_auto_delete_hours || 0);

                // 1. Server Total Upload Storage Usage Meter + Quotas Card
                const qCard = document.createElement('div');
                qCard.className = 'card-box';
                const qHead = document.createElement('div');
                qHead.className = 'section-header';
                qHead.textContent = t('adm_storage_quotas_title');
                qCard.appendChild(qHead);

                const meterWrap = document.createElement('div');
                meterWrap.className = 'storage-meter-wrap';
                const mTop = document.createElement('div');
                mTop.className = 'storage-meter-top';
                const mLbl = document.createElement('span');
                mLbl.textContent = `💾 ${t('adm_kpi_storage')} (${d.files_count || 0} ${t('adm_files_lbl')})`;
                const mVal = document.createElement('span');
                mVal.style.color = 'var(--primary)';
                const mBar = document.createElement('div');
                mBar.className = 'storage-meter-bar';
                const mFill = document.createElement('div');
                mFill.className = 'storage-meter-fill';
                mBar.appendChild(mFill);

                const refreshGlobalMeter = () => {
                    if (maxTotalMb > 0) {
                        const maxB = maxTotalMb * 1048576;
                        const pct = Math.min(100, Math.round((usedTotalBytes / maxB) * 100));
                        mVal.textContent = `${formatBytes(usedTotalBytes)} / ${maxTotalMb} ${t('unit_mb')} (${pct}%)`;
                        mFill.style.width = `${pct}%`;
                        mFill.classList.toggle('warn', pct >= 80);
                    } else {
                        mVal.textContent = `${formatBytes(usedTotalBytes)} / ${t('storage_unlimited')}`;
                        mFill.style.width = '12%';
                        mFill.classList.remove('warn');
                    }
                };
                refreshGlobalMeter();
                mTop.appendChild(mLbl);
                mTop.appendChild(mVal);
                meterWrap.appendChild(mTop);
                meterWrap.appendChild(mBar);
                qCard.appendChild(meterWrap);

                const qGrid = document.createElement('div');
                qGrid.className = 'resp-grid-2';

                const fgTotal = document.createElement('div');
                fgTotal.className = 'form-group';
                const lTotal = document.createElement('label');
                lTotal.textContent = t('adm_max_total_storage_lbl');
                const inTotalMb = document.createElement('input');
                inTotalMb.type = 'number';
                inTotalMb.min = '0';
                inTotalMb.step = 'any';
                inTotalMb.className = 'input';
                inTotalMb.value = String(maxTotalMb);
                fgTotal.appendChild(lTotal);
                fgTotal.appendChild(inTotalMb);

                const fgUser = document.createElement('div');
                fgUser.className = 'form-group';
                const lUser = document.createElement('label');
                lUser.textContent = t('adm_max_user_storage_lbl');
                const inUserMb = document.createElement('input');
                inUserMb.type = 'number';
                inUserMb.min = '0';
                inUserMb.step = 'any';
                inUserMb.className = 'input';
                inUserMb.value = String(maxUserMb);
                fgUser.appendChild(lUser);
                fgUser.appendChild(inUserMb);

                const fgMaxFileMb = document.createElement('div');
                fgMaxFileMb.className = 'form-group';
                const lMaxFileMb = document.createElement('label');
                lMaxFileMb.textContent = t('adm_max_upload_mb');
                const inMaxFileMb = document.createElement('input');
                inMaxFileMb.type = 'number';
                inMaxFileMb.id = 'adm-storage-max-file-mb';
                inMaxFileMb.min = '0.5';
                inMaxFileMb.max = '2048';
                inMaxFileMb.step = 'any';
                inMaxFileMb.className = 'input';
                inMaxFileMb.value = String(maxFileMb);
                fgMaxFileMb.appendChild(lMaxFileMb);
                fgMaxFileMb.appendChild(inMaxFileMb);

                qGrid.appendChild(fgTotal);
                qGrid.appendChild(fgUser);
                qGrid.appendChild(fgMaxFileMb);
                qCard.appendChild(qGrid);

                // Auto-Delete Old Files Section inside same policy form
                const adHead = document.createElement('div');
                adHead.className = 'section-header';
                adHead.style.marginTop = '8px';
                adHead.textContent = t('adm_auto_del_files_title');
                qCard.appendChild(adHead);

                const adGrid = document.createElement('div');
                adGrid.className = 'resp-grid-2';

                const isEvenDays = autoHours >= 24 && (autoHours % 24 === 0);
                const initAutoAmount = isEvenDays ? (autoHours / 24) : autoHours;
                const initAutoUnit = isEvenDays ? 'days' : 'hours';

                const fgAutoAmt = document.createElement('div');
                fgAutoAmt.className = 'form-group';
                const lAutoAmt = document.createElement('label');
                lAutoAmt.textContent = t('adm_auto_del_amount_lbl');
                const inAutoAmt = document.createElement('input');
                inAutoAmt.type = 'number';
                inAutoAmt.min = '0';
                inAutoAmt.step = 'any';
                inAutoAmt.className = 'input';
                inAutoAmt.value = String(initAutoAmount);
                fgAutoAmt.appendChild(lAutoAmt);
                fgAutoAmt.appendChild(inAutoAmt);

                const fgAutoUnit = document.createElement('div');
                fgAutoUnit.className = 'form-group';
                const lAutoUnit = document.createElement('label');
                lAutoUnit.textContent = t('adm_auto_del_unit_lbl');
                const selAutoUnit = document.createElement('select');
                selAutoUnit.className = 'input';
                [['hours', t('unit_hours')], ['days', t('unit_days')]].forEach(([v, l]) => {
                    const o = document.createElement('option');
                    o.value = v;
                    o.textContent = l;
                    if (initAutoUnit === v) o.selected = true;
                    selAutoUnit.appendChild(o);
                });
                fgAutoUnit.appendChild(lAutoUnit);
                fgAutoUnit.appendChild(selAutoUnit);

                adGrid.appendChild(fgAutoAmt);
                adGrid.appendChild(fgAutoUnit);
                qCard.appendChild(adGrid);

                const globUpDisRow = document.createElement('label');
                globUpDisRow.style.cssText = 'display:flex;align-items:center;gap:10px;padding:10px 12px;margin:10px 0 12px;border-radius:12px;border:1px solid var(--danger);background:rgba(239,68,68,0.08);font-weight:700;font-size:12.5px;cursor:pointer';
                const chkGlobalDisableUploads = document.createElement('input');
                chkGlobalDisableUploads.type = 'checkbox';
                // Same 18px control as everywhere else; this row keeps its danger styling.
                chkGlobalDisableUploads.style.cssText = 'width:18px;height:18px;flex-shrink:0;accent-color:var(--danger)';
                chkGlobalDisableUploads.checked = Number(curSettings.uploads_disabled) === 1;
                const spGlobalDisableUploads = document.createElement('span');
                spGlobalDisableUploads.textContent = t('adm_disable_all_uploads_toggle');
                globUpDisRow.appendChild(chkGlobalDisableUploads);
                globUpDisRow.appendChild(spGlobalDisableUploads);
                qCard.appendChild(globUpDisRow);

                const saveQuotaBtn = document.createElement('button');
                saveQuotaBtn.type = 'button';
                saveQuotaBtn.className = 'btn btn-primary btn-block';
                saveQuotaBtn.textContent = t('adm_save_storage_btn');
                saveQuotaBtn.addEventListener('click', async () => {
                    const totVal = Math.max(0, parseFloat(inTotalMb.value) || 0);
                    const usrVal = Math.max(0, parseFloat(inUserMb.value) || 0);
                    const fileMbVal = Math.max(0.5, Math.min(2048, parseFloat(inMaxFileMb.value) || 16));
                    const rawAmt = Math.max(0, parseFloat(inAutoAmt.value) || 0);
                    const computedHours = selAutoUnit.value === 'days' ? (rawAmt * 24) : rawAmt;

                    const r = await apiCall('admin_settings_update', {
                        max_total_storage_mb: totVal,
                        max_user_storage_mb: usrVal,
                        max_file_mb: fileMbVal,
                        file_auto_delete_hours: computedHours,
                        uploads_disabled: chkGlobalDisableUploads.checked ? 1 : 0
                    });
                    if (r.ok) {
                        maxTotalMb = totVal;
                        maxUserMb = usrVal;
                        maxFileMb = fileMbVal;
                        autoHours = computedHours;
                        store.settings = Object.assign(store.settings, r.data.settings || {});
                        refreshGlobalMeter();
                        toast(t('adm_storage_saved_toast'));
                    } else {
                        toast(r.message || t('err_generic'), true);
                    }
                });
                qCard.appendChild(saveQuotaBtn);
                tabContent.appendChild(qCard);

                // 2. Manual Purge of Older Uploaded Files Card
                const mpCard = document.createElement('div');
                mpCard.className = 'card-box';
                const mpHead = document.createElement('div');
                mpHead.className = 'section-header';
                mpHead.textContent = t('adm_manual_purge_title');
                mpCard.appendChild(mpHead);

                const mpDesc = document.createElement('p');
                mpDesc.style.cssText = 'font-size:12.5px;color:var(--text-secondary);margin:0 0 12px;line-height:1.5';
                mpDesc.textContent = t('adm_manual_purge_desc');
                mpCard.appendChild(mpDesc);

                const mpRow = document.createElement('div');
                mpRow.className = 'resp-grid-3';

                const inMpAmt = document.createElement('input');
                inMpAmt.type = 'number';
                inMpAmt.min = '0';
                inMpAmt.step = 'any';
                inMpAmt.className = 'input';
                inMpAmt.value = '24';

                const selMpUnit = document.createElement('select');
                selMpUnit.className = 'input';
                [['hours', t('unit_hours')], ['days', t('unit_days')]].forEach(([v, l]) => {
                    const o = document.createElement('option');
                    o.value = v;
                    o.textContent = l;
                    selMpUnit.appendChild(o);
                });

                const mpBtn = document.createElement('button');
                mpBtn.type = 'button';
                mpBtn.className = 'btn btn-danger';
                mpBtn.textContent = t('adm_manual_purge_btn');
                mpBtn.addEventListener('click', async () => {
                    const amt = Math.max(0, parseFloat(inMpAmt.value) || 0);
                    const unit = selMpUnit.value;
                    const ap = await askApproval({
                        title: t('adm_manual_purge_btn'),
                        desc: `${t('adm_manual_purge_desc')}
⏱️ > ${amt} ${unit === 'days' ? t('unit_days') : t('unit_hours')}`,
                        danger: true,
                        icon: '🧹'
                    });
                    if (!ap.approved) return;
                    const r = await apiCall('admin_files_purge_older', { amount: amt, unit });
                    if (r.ok) {
                        toast(store.lang === 'fa' ? `🧹 ${r.data.deleted_count} فایل قدیمی حذف شد (${formatBytes(r.data.freed_bytes)} فضا آزاد گردید).` : `🧹 Purged ${r.data.deleted_count} old files (${formatBytes(r.data.freed_bytes)} freed).`);
                        renderTab('storage');
                    } else {
                        toast(r.message || t('err_generic'), true);
                    }
                });

                mpRow.appendChild(inMpAmt);
                mpRow.appendChild(selMpUnit);
                mpRow.appendChild(mpBtn);
                mpCard.appendChild(mpRow);
                tabContent.appendChild(mpCard);

                // 3. System-Wide & Default Per-User Traffic Accounting & Quotas Card (Item #3)
                const trfCard = document.createElement('div');
                trfCard.className = 'card-box';
                const trfHead = document.createElement('div');
                trfHead.className = 'section-header';
                trfHead.textContent = t('adm_traffic_sec_title');
                trfCard.appendChild(trfHead);

                const sysTr = d.system_traffic || curSettings.system_traffic || {};
                const sysUsed = Number(sysTr.used_bytes || 0);
                const sysLim = Number(sysTr.limit_bytes || 0);
                const sysRem = sysLim > 0 ? Math.max(0, sysLim - sysUsed) : -1;
                const sysPct = sysLim > 0 ? Math.min(100, Math.round((sysUsed / sysLim) * 100)) : 8;

                const sysBox = document.createElement('div');
                sysBox.style.cssText = 'padding:10px 12px;border:1px solid var(--border);border-radius:12px;background:var(--bg-subtle);margin-bottom:12px';
                const sysTrack = document.createElement('div');
                sysTrack.className = 'quota-meter-track';
                const sysFill = document.createElement('div');
                sysFill.className = 'quota-meter-fill' + (sysPct >= 95 ? ' danger' : (sysPct >= 80 ? ' warn' : ''));
                sysFill.style.width = `${sysPct}%`;
                sysTrack.appendChild(sysFill);
                sysBox.appendChild(sysTrack);

                const sysMeta = document.createElement('div');
                sysMeta.style.cssText = 'font-size:12.5px;display:flex;justify-content:space-between;flex-wrap:wrap;gap:8px;margin-top:6px';
                const sysResetTxt = sysLim > 0
                    ? (Number(sysTr.reset_at || 0) > 0 ? formatDate(Number(sysTr.reset_at)) : t('quota_permanent_no_reset'))
                    : t('quota_unlimited');
                sysMeta.textContent = `${t('adm_sys_traffic_used_lbl')}: ${formatBytes(sysUsed)} / ${sysLim > 0 ? formatBytes(sysLim) : t('quota_unlimited')} • ${t('user_traffic_rem_label')}: ${sysRem >= 0 ? formatBytes(sysRem) : t('quota_unlimited')} • ${t('user_traffic_reset_label')}: ${sysResetTxt}`;
                sysBox.appendChild(sysMeta);
                trfCard.appendChild(sysBox);

                const trfGrid = document.createElement('div');
                trfGrid.className = 'resp-grid-2';

                const fgSysLim = document.createElement('div');
                fgSysLim.className = 'form-group';
                const lSysLim = document.createElement('label');
                lSysLim.textContent = t('adm_sys_traffic_limit_lbl');
                const inSysLim = document.createElement('input');
                inSysLim.type = 'number';
                inSysLim.min = '0';
                inSysLim.step = 'any';
                inSysLim.className = 'input';
                inSysLim.dir = 'ltr';
                inSysLim.value = String(curSettings.system_traffic_limit_mb || 0);
                fgSysLim.appendChild(lSysLim);
                fgSysLim.appendChild(inSysLim);

                const fgSysPer = document.createElement('div');
                fgSysPer.className = 'form-group';
                const lSysPer = document.createElement('label');
                lSysPer.textContent = t('adm_sys_traffic_period_lbl');
                const inSysPer = document.createElement('input');
                inSysPer.type = 'number';
                inSysPer.min = '0';
                inSysPer.max = '3650';
                inSysPer.step = '1';
                inSysPer.className = 'input';
                inSysPer.dir = 'ltr';
                inSysPer.value = String(curSettings.system_traffic_period_days || 0);
                fgSysPer.appendChild(lSysPer);
                fgSysPer.appendChild(inSysPer);

                const fgDefUsrLim = document.createElement('div');
                fgDefUsrLim.className = 'form-group';
                const lDefUsrLim = document.createElement('label');
                lDefUsrLim.textContent = t('adm_def_user_traffic_lbl');
                const inDefUsrLim = document.createElement('input');
                inDefUsrLim.type = 'number';
                inDefUsrLim.min = '0';
                inDefUsrLim.step = 'any';
                inDefUsrLim.className = 'input';
                inDefUsrLim.dir = 'ltr';
                inDefUsrLim.value = String(curSettings.default_user_traffic_mb || 0);
                fgDefUsrLim.appendChild(lDefUsrLim);
                fgDefUsrLim.appendChild(inDefUsrLim);

                const fgDefUsrPer = document.createElement('div');
                fgDefUsrPer.className = 'form-group';
                const lDefUsrPer = document.createElement('label');
                lDefUsrPer.textContent = t('adm_def_user_traffic_period_lbl');
                const inDefUsrPer = document.createElement('input');
                inDefUsrPer.type = 'number';
                inDefUsrPer.min = '0';
                inDefUsrPer.max = '3650';
                inDefUsrPer.step = '1';
                inDefUsrPer.className = 'input';
                inDefUsrPer.dir = 'ltr';
                inDefUsrPer.value = String(curSettings.default_user_traffic_period_days || 0);
                fgDefUsrPer.appendChild(lDefUsrPer);
                fgDefUsrPer.appendChild(inDefUsrPer);

                trfGrid.appendChild(fgSysLim);
                trfGrid.appendChild(fgSysPer);
                trfGrid.appendChild(fgDefUsrLim);
                trfGrid.appendChild(fgDefUsrPer);
                trfCard.appendChild(trfGrid);

                const trfPeriodHint = document.createElement('div');
                trfPeriodHint.style.cssText = 'font-size:11.5px;color:var(--text-muted);margin:4px 0 10px';
                trfPeriodHint.textContent = `0 = ${t('adm_traffic_period_0')} • 1 = ${t('adm_traffic_period_1')} • 7 = ${t('adm_traffic_period_7')} • 30 = ${t('adm_traffic_period_30')}`;
                trfCard.appendChild(trfPeriodHint);

                const trfBtnRow = document.createElement('div');
                trfBtnRow.className = 'resp-action-row';

                const saveTrfBtn = document.createElement('button');
                saveTrfBtn.type = 'button';
                saveTrfBtn.className = 'btn btn-primary btn-sm';
                saveTrfBtn.textContent = t('save_changes');
                saveTrfBtn.addEventListener('click', async () => {
                    const r = await apiCall('admin_settings_update', {
                        system_traffic_limit_mb: Math.max(0, parseFloat(inSysLim.value) || 0),
                        system_traffic_period_days: Math.max(0, parseInt(inSysPer.value, 10) || 0),
                        default_user_traffic_mb: Math.max(0, parseFloat(inDefUsrLim.value) || 0),
                        default_user_traffic_period_days: Math.max(0, parseInt(inDefUsrPer.value, 10) || 0)
                    });
                    if (r.ok) {
                        store.settings = Object.assign(store.settings, r.data.settings || {});
                        toast(t('adm_settings_saved_toast'));
                        renderTab('storage');
                    } else {
                        toast(r.message || t('err_generic'), true);
                    }
                });

                const resetSysTrfBtn = document.createElement('button');
                resetSysTrfBtn.type = 'button';
                resetSysTrfBtn.className = 'btn btn-danger btn-sm';
                resetSysTrfBtn.textContent = t('adm_sys_traffic_reset_btn');
                resetSysTrfBtn.addEventListener('click', async () => {
                    const ap = await askApproval({
                        title: t('adm_sys_traffic_reset_btn'),
                        desc: t('adm_traffic_sec_title'),
                        danger: true,
                        icon: '🔄'
                    });
                    if (!ap.approved) return;
                    const rr = await apiCall('admin_system_traffic_reset', {});
                    if (rr.ok) {
                        toast(t('adm_traffic_reset_done_toast'));
                        renderTab('storage');
                    } else {
                        toast(rr.message || t('err_generic'), true);
                    }
                });

                trfBtnRow.appendChild(saveTrfBtn);
                trfBtnRow.appendChild(resetSysTrfBtn);
                trfCard.appendChild(trfBtnRow);
                tabContent.appendChild(trfCard);

            } else if (tabId === 'emergency') {
                const stRes = await apiCall('admin_stats');
                const sRes = await apiCall('admin_settings_get');
                tabContent.innerHTML = '';

                const d = (stRes.ok && stRes.data) ? stRes.data : {};
                const curSettings = (sRes.ok && sRes.data.settings) ? sRes.data.settings : store.settings;
                let msgDeleteAt = Number(curSettings.messenger_delete_at || d.messenger_delete_at || 0);

                // Dedicated Emergency Tab: Scheduled Messenger Deletion, Hard Reset & Zero-Trace Panic Wipe
                const wipeCard = document.createElement('div');
                wipeCard.className = 'danger-card';
                markFounderOnly(wipeCard);
                const wHead = document.createElement('div');
                wHead.className = 'section-header';
                wHead.style.color = 'var(--danger)';
                wHead.textContent = t('adm_messenger_wipe_title');
                wipeCard.appendChild(wHead);

                const wDesc = document.createElement('p');
                wDesc.style.cssText = 'font-size:12.5px;color:var(--text-secondary);margin:0 0 12px;line-height:1.5';
                wDesc.textContent = t('adm_messenger_wipe_desc');
                wipeCard.appendChild(wDesc);

                const wStatusBox = document.createElement('div');
                wStatusBox.className = 'sched-status-box' + (msgDeleteAt > 0 ? ' active' : '');
                wStatusBox.textContent = msgDeleteAt > 0
                    ? (t('adm_msg_sched_active') + formatDate(msgDeleteAt))
                    : t('adm_msg_sched_none');
                wipeCard.appendChild(wStatusBox);

                // Preset schedule buttons (24h & 7d)
                const presetGrid = document.createElement('div');
                presetGrid.className = 'danger-schedule-grid';

                const bSch24 = document.createElement('button');
                bSch24.type = 'button';
                bSch24.className = 'btn btn-secondary';
                bSch24.textContent = t('adm_msg_sched_24h');
                bSch24.addEventListener('click', async () => {
                    const ap = await askApproval({
                        title: t('adm_msg_sched_24h'),
                        desc: t('ask_adm_sched_wipe'),
                        danger: true,
                        icon: '⏳'
                    });
                    if (!ap.approved) return;
                    const r = await apiCall('admin_messenger_schedule_wipe', { amount: 24, unit: 'hours' });
                    if (r.ok) {
                        if (store.settings) store.settings.messenger_delete_at = r.data.messenger_delete_at;
                        toast(t('adm_msg_wipe_sched_toast') + formatDate(r.data.messenger_delete_at));
                        renderTab('emergency');
                    }
                });

                const bSch7d = document.createElement('button');
                bSch7d.type = 'button';
                bSch7d.className = 'btn btn-secondary';
                bSch7d.textContent = t('adm_msg_sched_7d');
                bSch7d.addEventListener('click', async () => {
                    const ap = await askApproval({
                        title: t('adm_msg_sched_7d'),
                        desc: t('ask_adm_sched_wipe'),
                        danger: true,
                        icon: '⏳'
                    });
                    if (!ap.approved) return;
                    const r = await apiCall('admin_messenger_schedule_wipe', { amount: 7, unit: 'days' });
                    if (r.ok) {
                        if (store.settings) store.settings.messenger_delete_at = r.data.messenger_delete_at;
                        toast(t('adm_msg_wipe_sched_toast') + formatDate(r.data.messenger_delete_at));
                        renderTab('emergency');
                    }
                });

                presetGrid.appendChild(bSch24);
                presetGrid.appendChild(bSch7d);
                wipeCard.appendChild(presetGrid);

                // Custom Scheduled Messenger Deletion Row (Amount + Hours/Days + Set Button)
                const custSchRow = document.createElement('div');
                custSchRow.className = 'resp-grid-3';
                custSchRow.style.marginBottom = '10px';

                const inCustAmt = document.createElement('input');
                inCustAmt.type = 'number';
                inCustAmt.min = '1';
                inCustAmt.step = 'any';
                inCustAmt.className = 'input';
                inCustAmt.value = '12';

                const selCustUnit = document.createElement('select');
                selCustUnit.className = 'input';
                [['hours', t('unit_hours')], ['days', t('unit_days')]].forEach(([v, l]) => {
                    const o = document.createElement('option');
                    o.value = v;
                    o.textContent = l;
                    selCustUnit.appendChild(o);
                });

                const bCustSch = document.createElement('button');
                bCustSch.type = 'button';
                bCustSch.className = 'btn btn-secondary';
                bCustSch.textContent = t('adm_msg_sched_custom_btn');
                bCustSch.addEventListener('click', async () => {
                    const amt = Math.max(0.1, parseFloat(inCustAmt.value) || 1);
                    const ap = await askApproval({
                        title: t('adm_msg_sched_custom_btn'),
                        desc: `${t('ask_adm_sched_wipe')}
⏱️ ${amt} ${selCustUnit.value === 'days' ? t('unit_days') : t('unit_hours')}`,
                        danger: true,
                        icon: '⏳'
                    });
                    if (!ap.approved) return;
                    const r = await apiCall('admin_messenger_schedule_wipe', { amount: amt, unit: selCustUnit.value });
                    if (r.ok) {
                        if (store.settings) store.settings.messenger_delete_at = r.data.messenger_delete_at;
                        toast(t('adm_msg_wipe_sched_toast') + formatDate(r.data.messenger_delete_at));
                        renderTab('emergency');
                    }
                });

                custSchRow.appendChild(inCustAmt);
                custSchRow.appendChild(selCustUnit);
                custSchRow.appendChild(bCustSch);
                wipeCard.appendChild(custSchRow);

                // Always-visible Cancel Scheduled Messenger Deletion Button (ALWAYS prompts confirmation popup)
                const bCancelMsgWipe = document.createElement('button');
                bCancelMsgWipe.type = 'button';
                bCancelMsgWipe.id = 'btn-adm-cancel-msg-wipe';
                bCancelMsgWipe.className = msgDeleteAt > 0 ? 'btn btn-primary btn-block' : 'btn btn-secondary btn-block';
                bCancelMsgWipe.style.marginBottom = '12px';
                bCancelMsgWipe.textContent = t('adm_msg_cancel_wipe_btn');
                bCancelMsgWipe.addEventListener('click', async () => {
                    const ap = await askApproval({
                        title: t('adm_msg_cancel_wipe_btn'),
                        desc: msgDeleteAt > 0
                            ? `${t('ask_adm_cancel_wipe')}\n⏳ ${formatDate(msgDeleteAt)}`
                            : t('ask_adm_cancel_wipe_none'),
                        checkboxLabel: t('confirm_cancel_sched_msg_chk'),
                        checkboxRequired: true,
                        danger: false,
                        icon: '✅'
                    });
                    if (!ap.approved) return;
                    const r = await apiCall('admin_messenger_cancel_wipe', { confirmed: 1 });
                    if (r.ok) {
                        if (store.settings) store.settings.messenger_delete_at = 0;
                        toast(t('adm_msg_wipe_cancel_toast'));
                        renderTab('emergency');
                    }
                });
                wipeCard.appendChild(bCancelMsgWipe);

                // 1. HARD RESET EVERYTHING (Factory Reset to Fresh Install — keeps index.php, shows Install Wizard!)
                const hardResetBox = document.createElement('div');
                hardResetBox.className = 'hard-reset-card';
                markFounderOnly(hardResetBox);
                const hrHead = document.createElement('div');
                hrHead.className = 'section-header';
                hrHead.style.color = '#d97706';
                hrHead.textContent = t('adm_hard_reset_title');
                hardResetBox.appendChild(hrHead);

                const hrDesc = document.createElement('p');
                hrDesc.style.cssText = 'font-size:12.5px;color:var(--text-secondary);margin:0 0 10px;line-height:1.55';
                hrDesc.textContent = t('adm_hard_reset_desc');
                hardResetBox.appendChild(hrDesc);

                const bHardReset = document.createElement('button');
                bHardReset.type = 'button';
                bHardReset.className = 'btn btn-primary btn-block';
                bHardReset.style.cssText = 'background:#d97706;border-color:#d97706;color:#fff;font-weight:800';
                bHardReset.textContent = t('adm_hard_reset_btn');
                bHardReset.addEventListener('click', async () => {
                    const ap = await askApproval({
                        title: t('adm_hard_reset_title'),
                        desc: t('adm_hard_reset_confirm_desc'),
                        danger: true,
                        icon: '🔄',
                        checkboxLabel: t('adm_hard_reset_chk'),
                        checkboxRequired: true
                    });
                    if (!ap.approved || !ap.checked) return;
                    bHardReset.disabled = true;
                    const r = await apiCall('admin_messenger_hard_reset', { confirmed: 1 });
                    if (r.ok) {
                        await E2EE.wipeLocalKeys();
                        localStorage.clear();
                        sessionStorage.clear();
                        window.location.href = window.location.pathname;
                    } else {
                        bHardReset.disabled = false;
                        toast(r.message || t('err_generic'), true);
                    }
                });
                hardResetBox.appendChild(bHardReset);
                tabContent.appendChild(hardResetBox);

                // 2. ZERO-TRACE PANIC WIPE (Deletes ALL Data, Files, chat_data/ AND index.php itself from the server!)
                const panicDiffNote = document.createElement('div');
                panicDiffNote.style.cssText = 'font-size:12px;font-weight:700;color:var(--danger);background:rgba(239,68,68,0.08);border:1px dashed var(--danger);border-radius:10px;padding:10px 12px;margin-bottom:10px;line-height:1.55';
                panicDiffNote.textContent = t('adm_panic_zero_trace_note');
                wipeCard.appendChild(panicDiffNote);

                const bPanicMessenger = document.createElement('button');
                bPanicMessenger.type = 'button';
                bPanicMessenger.className = 'btn btn-danger danger-panic-btn';
                bPanicMessenger.textContent = t('adm_msg_panic_wipe_btn');
                bPanicMessenger.addEventListener('click', async () => {
                    const ap = await askApproval({
                        title: t('adm_msg_panic_wipe_btn'),
                        desc: t('adm_msg_panic_confirm'),
                        danger: true,
                        icon: '🚨',
                        checkboxLabel: t('adm_panic_zero_trace_chk'),
                        checkboxRequired: true
                    });
                    if (!ap.approved || !ap.checked) return;
                    bPanicMessenger.disabled = true;
                    const r = await apiCall('admin_messenger_panic_wipe', { confirmed: 1 });
                    if (r.ok) {
                        await triggerClientZeroTraceBlankOut();
                    } else {
                        bPanicMessenger.disabled = false;
                        toast(r.message || t('err_generic'), true);
                    }
                });
                wipeCard.appendChild(bPanicMessenger);
                tabContent.appendChild(wipeCard);

                // Item 11: Messenger Panic Duress Password Card (Full Messenger + Files Wipe on Login/Unlock without 2FA)
                const pdCard = document.createElement('div');
                pdCard.className = 'danger-card';
                pdCard.style.marginTop = '12px';
                markFounderOnly(pdCard);
                const pdHead = document.createElement('div');
                pdHead.className = 'section-header';
                pdHead.style.color = 'var(--danger)';
                pdHead.textContent = t('adm_panic_duress_title');
                pdCard.appendChild(pdHead);
                const pdDesc = document.createElement('p');
                pdDesc.style.cssText = 'font-size:12.5px;color:var(--text-secondary);margin:0 0 12px;line-height:1.6';
                pdDesc.textContent = t('adm_panic_duress_desc');
                pdCard.appendChild(pdDesc);

                const mkAdmPwField = (lblTxt) => {
                    const fg = document.createElement('div');
                    fg.className = 'form-group';
                    const l = document.createElement('label');
                    l.textContent = lblTxt;
                    const inp = document.createElement('input');
                    inp.type = 'password';
                    inp.className = 'input';
                    inp.dir = 'ltr';
                    inp.placeholder = '••••••••';
                    inp.autocomplete = 'new-password';
                    fg.appendChild(l);
                    fg.appendChild(inp);
                    return { fg, inp };
                };
                const pdCur = mkAdmPwField(t('adm_panic_duress_cur_pw'));
                const pdNew = mkAdmPwField(t('adm_panic_duress_new_pw'));
                const pdConf = mkAdmPwField(t('adm_panic_duress_confirm_pw'));
                pdCard.appendChild(pdCur.fg);
                pdCard.appendChild(pdNew.fg);
                pdCard.appendChild(pdConf.fg);

                const pdActs = document.createElement('div');
                pdActs.className = 'resp-action-row';
                const pdSaveBtn = document.createElement('button');
                pdSaveBtn.type = 'button';
                pdSaveBtn.className = 'btn btn-danger btn-sm';
                pdSaveBtn.textContent = t('adm_panic_duress_save_btn');
                const pdRemBtn = document.createElement('button');
                pdRemBtn.type = 'button';
                pdRemBtn.className = 'btn btn-secondary btn-sm' + (Number(curSettings.has_panic_duress_password) === 1 ? '' : ' hidden');
                pdRemBtn.textContent = t('adm_panic_duress_remove_btn');

                pdSaveBtn.addEventListener('click', async () => {
                    const mp = pdCur.inp.value;
                    const np = pdNew.inp.value;
                    const np2 = pdConf.inp.value;
                    if (!mp) { pdCur.inp.focus(); return; }
                    if (np.length < 6) {
                        toast(t('inst_pass_short'), true);
                        pdNew.inp.focus();
                        return;
                    }
                    if (np !== np2) {
                        toast(t('duress_pw_mismatch_err'), true);
                        pdConf.inp.focus();
                        return;
                    }
                    const r = await apiCall('admin_panic_duress_set', {
                        current_password: mp,
                        duress_password: np,
                        duress_password_confirm: np2
                    });
                    if (r.ok) {
                        pdCur.inp.value = '';
                        pdNew.inp.value = '';
                        pdConf.inp.value = '';
                        pdRemBtn.classList.remove('hidden');
                        toast(r.data && r.data.shared_with_account_duress ? t('adm_panic_duress_shared_note') : t('adm_panic_duress_saved_toast'));
                    } else {
                        toast(r.message || t('err_generic'), true);
                    }
                });
                pdRemBtn.addEventListener('click', async () => {
                    const mp = pdCur.inp.value;
                    if (!mp) { pdCur.inp.focus(); return; }
                    const r = await apiCall('admin_panic_duress_set', { current_password: mp, remove: 1 });
                    if (r.ok) {
                        pdCur.inp.value = '';
                        pdRemBtn.classList.add('hidden');
                        toast(t('adm_panic_duress_removed_toast'));
                    } else {
                        toast(r.message || t('err_generic'), true);
                    }
                });
                pdActs.appendChild(pdSaveBtn);
                pdActs.appendChild(pdRemBtn);
                pdCard.appendChild(pdActs);
                if (typeof enhancePasswordFields === 'function') enhancePasswordFields(pdCard);
                tabContent.appendChild(pdCard);

            } else if (tabId === 'settings') {
                const sRes = await apiCall('admin_settings_get');
                tabContent.innerHTML = '';

                const curSettings = (sRes.ok && sRes.data.settings) ? sRes.data.settings : store.settings;

                // Item #22: Live Search Input for Admin Settings
                // Clean Sub-Category Filter Bar for Admin Settings. Searching is
                // done by the single global hub search above, so this bar only
                // narrows the categories - there is no second search box here.
                const admSetSubBar = document.createElement('div');
                admSetSubBar.className = 'settings-sub-pills';
                let activeAdmSetSub = 'all';
                const syncAdmSetSubVis = () => {
                    tabContent.querySelectorAll('[data-admset-sub]').forEach(el => {
                        const cats = String(el.dataset.admsetSub || '').split(/\s+/);
                        el.classList.toggle('hidden', activeAdmSetSub !== 'all' && !cats.includes(activeAdmSetSub));
                    });
                    if (typeof saveBarCard !== 'undefined' && saveBarCard) {
                        saveBarCard.classList.toggle('hidden', activeAdmSetSub === 'danger');
                    }
                };
                tabContent._admSubSync = syncAdmSetSubVis;
                [
                    ['all', t('adm_set_sub_all')],
                    ['brand', t('adm_set_sub_brand')],
                    ['auth', t('adm_set_sub_auth')],
                    ['msg', t('adm_set_sub_msg')],
                    ['calls', t('adm_set_sub_calls')],
                    ['danger', t('adm_set_sub_danger')]
                ].forEach(([sk, sl]) => {
                    const sb = document.createElement('button');
                    sb.type = 'button';
                    sb.className = 'settings-sub-pill' + (sk === activeAdmSetSub ? ' active' : '');
                    sb.textContent = sl;
                    sb.addEventListener('click', () => {
                        activeAdmSetSub = sk;
                        admSetSubBar.querySelectorAll('.settings-sub-pill').forEach(x => x.classList.remove('active'));
                        sb.classList.add('active');
                        syncAdmSetSubVis();
                    });
                    admSetSubBar.appendChild(sb);
                });
                tabContent.appendChild(admSetSubBar);

                // Global Messenger Idle Time Card (Manual Active/Deactive OR Automatic From Hour ... To Hour ...)
                const idleCard = document.createElement('div');
                idleCard.className = 'card-box';
                idleCard.dataset.admsetSub = 'danger';
                const idleHead = document.createElement('div');
                idleHead.className = 'section-header';
                idleHead.textContent = t('idle_global_sec_title');
                idleCard.appendChild(idleHead);

                const idleDesc = document.createElement('p');
                idleDesc.style.cssText = 'font-size:12.5px;color:var(--text-secondary);margin:0 0 10px;line-height:1.55';
                idleDesc.textContent = t('idle_global_sec_desc');
                idleCard.appendChild(idleDesc);

                const curGIdle = evaluateIdleWindowJS(
                    curSettings.idle_mode || 'off',
                    curSettings.idle_start || '23:00',
                    curSettings.idle_end || '07:00',
                    curSettings.idle_tz_offset ?? (-new Date().getTimezoneOffset())
                );

                const gStatusRow = document.createElement('div');
                gStatusRow.style.cssText = 'display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap;margin-bottom:10px';
                const gPill = document.createElement('span');
                gPill.className = 'idle-status-pill' + (curGIdle.active ? ' active' : '');
                gPill.textContent = curGIdle.active
                    ? (curGIdle.mode === 'auto' ? `${t('idle_status_active_auto')} (${curGIdle.start}–${curGIdle.end})` : t('idle_status_active_manual'))
                    : (curGIdle.mode === 'auto' ? `${t('idle_status_scheduled')} (${curGIdle.start}–${curGIdle.end})` : t('idle_status_normal'));
                gStatusRow.appendChild(gPill);

                const gQuickToggleBtn = document.createElement('button');
                gQuickToggleBtn.type = 'button';
                gQuickToggleBtn.className = curGIdle.active ? 'btn btn-primary btn-sm' : 'btn btn-secondary btn-sm';
                gQuickToggleBtn.textContent = curGIdle.active ? t('idle_quick_deactivate_btn') : t('idle_quick_activate_btn');
                gStatusRow.appendChild(gQuickToggleBtn);
                idleCard.appendChild(gStatusRow);

                const fgGMode = document.createElement('div');
                fgGMode.className = 'form-group';
                const lblGMode = document.createElement('label');
                lblGMode.textContent = t('idle_mode_label');
                const selGIdleMode = document.createElement('select');
                selGIdleMode.className = 'input';
                [
                    ['off', t('idle_mode_off')],
                    ['manual', t('idle_mode_manual')],
                    ['auto', t('idle_mode_auto')]
                ].forEach(([v, l]) => {
                    const o = document.createElement('option');
                    o.value = v;
                    o.textContent = l;
                    if (curGIdle.mode === v) o.selected = true;
                    selGIdleMode.appendChild(o);
                });
                fgGMode.appendChild(lblGMode);
                fgGMode.appendChild(selGIdleMode);
                idleCard.appendChild(fgGMode);

                const gHoursGrid = document.createElement('div');
                gHoursGrid.className = 'idle-hours-grid' + (curGIdle.mode === 'auto' ? '' : ' hidden');

                const fgGFrom = document.createElement('div');
                fgGFrom.className = 'form-group';
                const lblGFrom = document.createElement('label');
                lblGFrom.textContent = t('idle_from_hour_lbl');
                const inGIdleStart = document.createElement('input');
                inGIdleStart.type = 'time';
                inGIdleStart.className = 'input';
                inGIdleStart.dir = 'ltr';
                inGIdleStart.value = curGIdle.start || '23:00';
                fgGFrom.appendChild(lblGFrom);
                fgGFrom.appendChild(inGIdleStart);

                const fgGTo = document.createElement('div');
                fgGTo.className = 'form-group';
                const lblGTo = document.createElement('label');
                lblGTo.textContent = t('idle_to_hour_lbl');
                const inGIdleEnd = document.createElement('input');
                inGIdleEnd.type = 'time';
                inGIdleEnd.className = 'input';
                inGIdleEnd.dir = 'ltr';
                inGIdleEnd.value = curGIdle.end || '07:00';
                fgGTo.appendChild(lblGTo);
                fgGTo.appendChild(inGIdleEnd);

                gHoursGrid.appendChild(fgGFrom);
                gHoursGrid.appendChild(fgGTo);
                idleCard.appendChild(gHoursGrid);

                selGIdleMode.addEventListener('change', () => {
                    gHoursGrid.classList.toggle('hidden', selGIdleMode.value !== 'auto');
                });

                const applyGlobalIdleSettings = async (targetMode) => {
                    if (targetMode !== 'off' && !curGIdle.active) {
                        const ap = await askApproval({
                            title: t('idle_global_sec_title'),
                            desc: t('ask_global_idle_on'),
                            danger: false,
                            icon: '🌙'
                        });
                        if (!ap.approved) return;
                    }
                    const r = await apiCall('admin_settings_update', {
                        idle_mode: targetMode,
                        idle_start: inGIdleStart.value || '23:00',
                        idle_end: inGIdleEnd.value || '07:00',
                        idle_tz_offset: -new Date().getTimezoneOffset()
                    });
                    if (r.ok) {
                        store.settings = Object.assign(store.settings, r.data.settings || {});
                        renderGlobalIdleBanner();
                        renderActiveChatHeader();
                        toast(t('idle_saved_toast'));
                        renderTab('settings');
                    } else {
                        toast(r.message || t('err_generic'), true);
                    }
                };

                gQuickToggleBtn.addEventListener('click', () => {
                    applyGlobalIdleSettings(curGIdle.active ? 'off' : 'manual');
                });

                const saveGIdleBtn = document.createElement('button');
                saveGIdleBtn.type = 'button';
                saveGIdleBtn.className = 'btn btn-primary btn-sm';
                saveGIdleBtn.style.marginTop = '8px';
