                saveGIdleBtn.addEventListener('click', () => {
                    applyGlobalIdleSettings(selGIdleMode.value);
                });
                idleCard.appendChild(saveGIdleBtn);
                tabContent.appendChild(idleCard);

                // Item #28: Clean User-Settings-Style Modular Cards for Admin General Settings (100% of options preserved!)
                const makeToggleCard = (labelTxt, checked) => {
                    const l = document.createElement('label');
                    l.className = 'adm-perm-card';
                    l.style.marginBottom = '6px';
                    const s = document.createElement('span');
                    s.style.cssText = 'font-size:13px;font-weight:600';
                    s.textContent = labelTxt;
                    const c = document.createElement('input');
                    c.type = 'checkbox';
