                brandCardHead.className = 'section-header';
                brandCardHead.textContent = t('adm_sec_branding');
                brandCard.appendChild(brandCardHead);

                const brandGrid = document.createElement('div');
                brandGrid.className = 'resp-grid-2';

                const fgSiteFa = document.createElement('div');
                fgSiteFa.className = 'form-group';
                const lSiteFa = document.createElement('label');
                lSiteFa.textContent = t('adm_site_name_fa');
                const inSiteFa = document.createElement('input');
                inSiteFa.className = 'input';
                inSiteFa.value = curSettings.site_name_fa || 'پیامرسان کوچک من (M3)';
                fgSiteFa.appendChild(lSiteFa);
                fgSiteFa.appendChild(inSiteFa);

                const fgSiteEn = document.createElement('div');
                fgSiteEn.className = 'form-group';
                const lSiteEn = document.createElement('label');
                lSiteEn.textContent = t('adm_site_name_en');
                const inSiteEn = document.createElement('input');
                inSiteEn.className = 'input';
                inSiteEn.dir = 'ltr';
