                brandGrid.appendChild(fgSiteFa);
                brandGrid.appendChild(fgSiteEn);
                brandCard.appendChild(brandGrid);

                let draftSiteLogo = String(curSettings.site_logo || '');
                let draftSiteFavicon = String(curSettings.site_favicon || '');

                const brandAssetsGrid = document.createElement('div');
                brandAssetsGrid.className = 'resp-grid-2';
                brandAssetsGrid.style.marginBottom = '10px';

                const makeBrandAssetControl = (lblText, hintText, pickText, initialUri, maxDim, onChange, fallbackImgUrl = '') => {
                    const fg = document.createElement('div');
                    fg.className = 'form-group';
                    const lbl = document.createElement('label');
                    lbl.textContent = lblText;
                    fg.appendChild(lbl);

                    const box = document.createElement('div');
                    box.className = 'brand-asset-box';

                    const prev = document.createElement('div');
                    prev.className = 'brand-asset-preview';
                    const syncPreview = (uri) => {
                        prev.innerHTML = '';
                        const srcToShow = uri || fallbackImgUrl;
                        if (srcToShow) {
                            const im = document.createElement('img');
                            im.src = srcToShow;
                            im.alt = 'Preview';
                            prev.appendChild(im);
                        } else {
                            prev.textContent = 'M3';
                        }
                    };
                    syncPreview(initialUri);

                    const fileIn = document.createElement('input');
                    fileIn.type = 'file';
                    fileIn.accept = 'image/png,image/jpeg,image/webp,image/gif,image/x-icon';
                    fileIn.className = 'hidden';

                    const infoCol = document.createElement('div');
                    infoCol.style.cssText = 'flex:1;min-width:0;display:flex;flex-direction:column;gap:6px';
                    const hintEl = document.createElement('div');
                    hintEl.style.cssText = 'font-size:11px;color:var(--text-muted)';
                    hintEl.textContent = hintText;

                    const btns = document.createElement('div');
                    btns.style.cssText = 'display:flex;gap:6px;flex-wrap:wrap';
                    const pickBtn = document.createElement('button');
                    pickBtn.type = 'button';
                    pickBtn.className = 'btn btn-secondary btn-sm';
                    pickBtn.textContent = pickText;
                    pickBtn.addEventListener('click', () => fileIn.click());

                    const resetBtn = document.createElement('button');
                    resetBtn.type = 'button';
                    resetBtn.className = 'btn btn-secondary btn-sm';
                    resetBtn.textContent = t('adm_reset_brand_btn');
                    resetBtn.addEventListener('click', () => {
                        syncPreview('');
                        onChange('');
                    });

                    fileIn.addEventListener('change', async () => {
                        if (!fileIn.files || !fileIn.files[0]) return;
                        try {
                            const dataUrl = await resizeImageToDataUrl(fileIn.files[0], maxDim, 0.9, true);
                            syncPreview(dataUrl);
                            onChange(dataUrl);
                        } catch (err) {
                            toast(t('err_generic'), true);
                        }
                        fileIn.value = '';
                    });

                    btns.appendChild(pickBtn);
                    btns.appendChild(resetBtn);
                    infoCol.appendChild(hintEl);
                    infoCol.appendChild(btns);
                    box.appendChild(prev);
                    box.appendChild(infoCol);
                    box.appendChild(fileIn);
                    fg.appendChild(box);
                    return fg;
                };

                brandAssetsGrid.appendChild(makeBrandAssetControl(
                    t('adm_logo_lbl'),
                    t('adm_logo_hint'),
                    t('adm_pick_logo_btn'),
                    draftSiteLogo,
                    160,
                    val => { draftSiteLogo = val; },
                    getDefaultSiteLogoDataUri()
                ));
                brandAssetsGrid.appendChild(makeBrandAssetControl(
                    t('adm_favicon_lbl'),
                    t('adm_favicon_hint'),
                    t('adm_pick_favicon_btn'),
                    draftSiteFavicon,
                    64,
                    val => { draftSiteFavicon = val; },
                    '?a=icon&v=009687'
                ));
                brandCard.appendChild(brandAssetsGrid);

                const brandSubGrid = document.createElement('div');
