                const lDefTheme = document.createElement('label');
                lDefTheme.textContent = t('adm_default_theme');
                const selDefTheme = document.createElement('select');
                selDefTheme.className = 'input';
                [['auto', t('theme_auto')], ['light', t('theme_light')], ['dark', t('theme_dark')]].forEach(([v, l]) => {
                    const o = document.createElement('option');
                    o.value = v;
                    o.textContent = l;
                    if (curSettings.default_theme === v) o.selected = true;
                    selDefTheme.appendChild(o);
                });
                fgDefTheme.appendChild(lDefTheme);
                fgDefTheme.appendChild(selDefTheme);

                const fgAnn = document.createElement('div');
                fgAnn.className = 'form-group';
                const lAnn = document.createElement('label');
                lAnn.textContent = t('adm_announcement');
                const inAnn = document.createElement('input');
                inAnn.className = 'input';
