                brandSubGrid.appendChild(fgDefTheme);
                brandSubGrid.appendChild(fgDefLang);
                brandCard.appendChild(brandSubGrid);
                brandCard.appendChild(fgAnn);
                tabContent.appendChild(brandCard);

                // CARD 2: Registration, Access, Persistent Sessions & Global Last-Seen Privacy
                const accessCard = document.createElement('div');
