                const tMaint = makeToggleCard(t('adm_maint_mode'), Number(curSettings.maintenance_mode) === 1);
                accessCard.appendChild(tMaint.wrap);

                // Persistent Login Cookie Duration («مرا به خاطر داشته باش»)
                const cookieCard = document.createElement('div');
                cookieCard.style.cssText = 'margin:10px 0 0;padding:12px;border:1px solid var(--border);border-radius:12px;background:var(--bg-subtle)';
                const ckHead = document.createElement('div');
                ckHead.style.cssText = 'font-weight:800;font-size:13px;color:var(--primary);margin-bottom:4px';
                ckHead.textContent = t('adm_cookie_dur_label');
