                ckHint.textContent = t('adm_cookie_dur_hint') + ' — ' + t('adm_cookie_sliding_hint');
                cookieCard.appendChild(ckHint);

                const curCookieSec = Math.max(300, Math.min(31536000, Number(curSettings.remember_cookie_sec || 2592000)));
                const cookieUseDays = (curCookieSec % 86400 === 0);
                const ckGrid = document.createElement('div');
                ckGrid.className = 'resp-grid-2';
                const inCookieVal = document.createElement('input');
                inCookieVal.type = 'number';
                inCookieVal.min = '1';
                inCookieVal.max = '8760';
                inCookieVal.className = 'input';
                inCookieVal.value = String(cookieUseDays ? Math.max(1, Math.round(curCookieSec / 86400)) : Math.max(1, Math.round(curCookieSec / 3600)));
                const selCookieUnit = document.createElement('select');
                selCookieUnit.className = 'input';
                [
                    ['days', t('adm_cookie_unit_days')],
                    ['hours', t('adm_cookie_unit_hours')]
                ].forEach(([uv, ul]) => {
                    const o = document.createElement('option');
                    o.value = uv;
                    o.textContent = ul;
                    if ((cookieUseDays ? 'days' : 'hours') === uv) o.selected = true;
                    selCookieUnit.appendChild(o);
                });
                ckGrid.appendChild(inCookieVal);
                ckGrid.appendChild(selCookieUnit);
                cookieCard.appendChild(ckGrid);
                accessCard.appendChild(cookieCard);

                // Admin Global Hide Everyone's Last Seen + High-Contrast Action Button (Item #22)
                const seenAdmBox = document.createElement('div');
                seenAdmBox.style.cssText = 'margin:10px 0 0;padding:12px;border-radius:10px;border:1px solid var(--border);background:var(--bg-soft)';
                const seenAdmWrap = document.createElement('label');
                seenAdmWrap.className = 'settings-chk-row';
                seenAdmWrap.style.cssText = 'font-weight:700;color:var(--text-main)';
                const chkForceHideSeen = document.createElement('input');
                chkForceHideSeen.type = 'checkbox';
                chkForceHideSeen.id = 'adm-force-hide-last-seen-chk';
                chkForceHideSeen.checked = Number(curSettings.force_hide_last_seen) === 1;
                const seenAdmTxt = document.createElement('span');
                seenAdmTxt.textContent = t('adm_force_hide_last_seen_lbl');
                seenAdmWrap.appendChild(chkForceHideSeen);
                seenAdmWrap.appendChild(seenAdmTxt);
                seenAdmBox.appendChild(seenAdmWrap);

                const btnHideAllSeen = document.createElement('button');
                btnHideAllSeen.type = 'button';
                btnHideAllSeen.id = 'btn-adm-hide-all-seen';
                btnHideAllSeen.className = 'btn btn-amber-action btn-sm';
                btnHideAllSeen.style.marginTop = '10px';
                btnHideAllSeen.textContent = t('adm_hide_all_last_seen_btn');
                btnHideAllSeen.addEventListener('click', async () => {
                    const ap = await askApproval({
                        title: t('adm_hide_all_last_seen_btn'),
                        desc: t('adm_hide_all_last_seen_confirm'),
                        danger: false,
                        icon: '🙈'
                    });
                    if (!ap.approved) return;
                    btnHideAllSeen.disabled = true;
                    const hr = await apiCall('admin_hide_all_last_seen', { force_hide_last_seen: 1, force_global: 1 });
                    btnHideAllSeen.disabled = false;
                    if (hr.ok) {
                        chkForceHideSeen.checked = true;
                        store.settings.force_hide_last_seen = 1;
                        if (store.user) {
                            store.user.last_seen_mode = 'recently';
                            store.user.hide_last_seen = 1;
                        }
                        renderChatList();
                        if (store.activeChatId) renderActiveChatHeader();
                        toast(t('adm_hide_all_last_seen_done'));
                    } else {
                        toast(hr.message || t('err_generic'), true);
                    }
                });
                seenAdmBox.appendChild(btnHideAllSeen);
                accessCard.appendChild(seenAdmBox);

                const fgResHandles = document.createElement('div');
                fgResHandles.className = 'form-group';
                fgResHandles.style.marginTop = '10px';
                const lResHandles = document.createElement('label');
                lResHandles.textContent = t('adm_reserved_handles_lbl');
                const inResHandles = document.createElement('input');
                inResHandles.type = 'text';
