                inResHandles.className = 'input';
                inResHandles.dir = 'ltr';
                inResHandles.value = String(curSettings.reserved_handles || 'admin,root,system,support,security,official,m3');
                fgResHandles.appendChild(lResHandles);
                fgResHandles.appendChild(inResHandles);
                accessCard.appendChild(fgResHandles);

                tabContent.appendChild(accessCard);

                // Identity Character Length Limits Card (Display Name & @Username)
                const identityLenCard = document.createElement('div');
                identityLenCard.className = 'card-box';
                identityLenCard.id = 'adm-identity-length-card';
                identityLenCard.dataset.admsetSub = 'auth msg';
                const idLenHead = document.createElement('div');
                idLenHead.className = 'section-header';
                idLenHead.textContent = t('adm_id_len_sec_title');
                identityLenCard.appendChild(idLenHead);

                const idLenDesc = document.createElement('p');
                idLenDesc.style.cssText = 'font-size:12px;color:var(--text-secondary);margin:0 0 10px;line-height:1.55';
                idLenDesc.textContent = t('adm_id_len_sec_desc');
                identityLenCard.appendChild(idLenDesc);

                const mkIdNumBox = (lblTxt, valNum, minV, maxV, idStr) => {
                    const fg = document.createElement('div');
                    fg.className = 'form-group';
                    fg.style.marginBottom = '8px';
                    const lb = document.createElement('label');
                    lb.htmlFor = idStr;
                    lb.textContent = lblTxt;
                    const inp = document.createElement('input');
                    inp.type = 'number';
                    inp.id = idStr;
                    inp.min = String(minV);
                    inp.max = String(maxV);
                    inp.dir = 'ltr';
                    inp.className = 'input';
                    inp.value = String(valNum);
                    fg.appendChild(lb);
                    fg.appendChild(inp);
                    return { fg, inp };
                };

                const fAdmUnameMin = mkIdNumBox(t('adm_uname_min_len_lbl'), Math.max(2, Math.min(32, Number(curSettings.username_min_len ?? 3))), 2, 32, 'adm-username-min-len');
                const fAdmUnameMax = mkIdNumBox(t('adm_uname_max_len_lbl'), Math.max(3, Math.min(64, Number(curSettings.username_max_len ?? 24))), 3, 64, 'adm-username-max-len');
                const fAdmDnameMin = mkIdNumBox(t('adm_dname_min_len_lbl'), Math.max(1, Math.min(60, Number(curSettings.display_name_min_len ?? 2))), 1, 60, 'adm-display-name-min-len');
                const fAdmDnameMax = mkIdNumBox(t('adm_dname_max_len_lbl'), Math.max(2, Math.min(120, Number(curSettings.display_name_max_len ?? 40))), 2, 120, 'adm-display-name-max-len');

                const idGridU = document.createElement('div');
                idGridU.className = 'resp-grid-2';
                idGridU.appendChild(fAdmUnameMin.fg);
                idGridU.appendChild(fAdmUnameMax.fg);
                identityLenCard.appendChild(idGridU);

                const idGridN = document.createElement('div');
                idGridN.className = 'resp-grid-2';
                idGridN.appendChild(fAdmDnameMin.fg);
                idGridN.appendChild(fAdmDnameMax.fg);
                identityLenCard.appendChild(idGridN);

                const readNormalizedIdLenPayload = () => {
                    let uMin = Math.max(2, Math.min(32, parseInt(fAdmUnameMin.inp.value || '3', 10) || 3));
                    let uMax = Math.max(3, Math.min(64, parseInt(fAdmUnameMax.inp.value || '24', 10) || 24));
                    if (uMin > uMax) uMin = uMax;
                    let nMin = Math.max(1, Math.min(60, parseInt(fAdmDnameMin.inp.value || '2', 10) || 2));
                    let nMax = Math.max(2, Math.min(120, parseInt(fAdmDnameMax.inp.value || '40', 10) || 40));
                    if (nMin > nMax) nMin = nMax;
                    fAdmUnameMin.inp.value = String(uMin);
                    fAdmUnameMax.inp.value = String(uMax);
                    fAdmDnameMin.inp.value = String(nMin);
                    fAdmDnameMax.inp.value = String(nMax);
                    return {
                        username_min_len: uMin,
                        username_max_len: uMax,
                        display_name_min_len: nMin,
                        display_name_max_len: nMax
                    };
                };

                const idLenBtnRow = document.createElement('div');
                idLenBtnRow.className = 'resp-action-row';
                idLenBtnRow.style.marginTop = '6px';
                // No save button of its own any more: the pinned bar at the
                // bottom already sends readNormalizedIdLenPayload() along with
                // everything else, so a second one only ever saved this card in
                // isolation and left the rest of the tab untouched. Say where
                // saving went, so the missing button is not read as a broken card.
                const btnResetIdLen = document.createElement('button');
                btnResetIdLen.type = 'button';
                btnResetIdLen.id = 'btn-adm-reset-identity-limits';
                btnResetIdLen.className = 'btn btn-secondary btn-sm';
                btnResetIdLen.textContent = t('adm_id_len_reset_btn');
