                    fAdmUnameMin.inp.value = '3';
                    fAdmUnameMax.inp.value = '24';
                    fAdmDnameMin.inp.value = '2';
                    fAdmDnameMax.inp.value = '40';
                    const idPayload = readNormalizedIdLenPayload();
                    btnResetIdLen.disabled = true;
                    const ir = await apiCall('admin_settings_update', idPayload);
                    btnResetIdLen.disabled = false;
                    if (ir.ok && ir.data && ir.data.settings) {
                        Object.assign(curSettings, ir.data.settings);
                        store.settings = Object.assign(store.settings || {}, ir.data.settings);
                        applyAuthIdentityInputLimits();
                        toast(t('adm_settings_saved_toast'));
                    } else {
                        toast(ir.message || t('err_generic'), true);
                    }
                });

                idLenBtnRow.appendChild(btnResetIdLen);
                identityLenCard.appendChild(idLenBtnRow);

