                const tFwCaptcha = makeToggleCard(t('adm_fw_captcha_enable_lbl'), Number(curSettings.fw_captcha_enabled ?? 1) !== 0);
                const tFwHoneypot = makeToggleCard(t('adm_fw_honeypot_enable_lbl'), Number(curSettings.fw_honeypot_enabled ?? 1) !== 0);
