                fwRpmGrid.style.marginTop = '8px';
                const fgFwRateRpm = document.createElement('div');
                fgFwRateRpm.className = 'form-group';
                const lFwRateRpm = document.createElement('label');
                lFwRateRpm.textContent = t('adm_fw_rate_rpm_lbl');
