                const lFwAuthRpm = document.createElement('label');
                lFwAuthRpm.textContent = t('adm_fw_auth_rpm_lbl');
                const inFwAuthRpm = document.createElement('input');
                inFwAuthRpm.type = 'number';
                inFwAuthRpm.min = '5';
                inFwAuthRpm.max = '600';
                inFwAuthRpm.dir = 'ltr';
                inFwAuthRpm.className = 'input';
                inFwAuthRpm.value = String(Math.max(5, Math.min(600, Number(curSettings.fw_auth_limit_rpm ?? 20))));
                fgFwAuthRpm.appendChild(lFwAuthRpm);
                fgFwAuthRpm.appendChild(inFwAuthRpm);
                fwRpmGrid.appendChild(fgFwRateRpm);
                fwRpmGrid.appendChild(fgFwAuthRpm);
                fwCard.appendChild(fwRpmGrid);

                const fwStatsMount = document.createElement('div');
                fwStatsMount.style.marginTop = '10px';
                const loadFwStatsUI = async () => {
                    const fwr = await apiCall('admin_firewall_stats');
                    fwStatsMount.replaceChildren();
                    const st = (fwr.ok && fwr.data && fwr.data.stats) ? fwr.data.stats : {};
                    const nHoney = Math.max(0, Number(st.honeypot_blocked ?? st.honeypot_blocks ?? 0));
                    const nCap   = Math.max(0, Number(st.captcha_blocked ?? st.captcha_blocks ?? 0));
                    const nRate  = Math.max(0, Number(st.ratelimit_blocked ?? st.rate_blocks ?? 0));
                    const nPay   = Math.max(0, Number(st.payload_blocked ?? st.waf_blocks ?? 0));
                    const nTotal = Math.max(nHoney + nCap + nRate + nPay, Number(st.total_blocked || 0));
                    const lastResetTs = Number(st.last_reset_at || 0);

                    const panel = document.createElement('div');
                    panel.className = 'fw-telemetry-panel';

                    const headRow = document.createElement('div');
                    headRow.className = 'fw-telemetry-head';
                    const titleEl = document.createElement('div');
                    titleEl.className = 'fw-telemetry-title';
                    titleEl.textContent = '📊 ' + t('fw_telemetry_title');
                    const resetMetaEl = document.createElement('div');
                    resetMetaEl.className = 'fw-telemetry-meta';
                    resetMetaEl.textContent = t('fw_last_reset_lbl') + ' ' + (lastResetTs > 0 ? formatFullTime(lastResetTs) : t('fw_last_reset_never'));
                    headRow.appendChild(titleEl);
                    headRow.appendChild(resetMetaEl);
                    panel.appendChild(headRow);

                    const hero = document.createElement('div');
                    hero.className = 'fw-stat-hero';
                    const heroMain = document.createElement('div');
                    heroMain.className = 'fw-stat-hero-main';
                    const heroVal = document.createElement('div');
                    heroVal.className = 'fw-stat-hero-val';
                    heroVal.id = 'fw-stat-total-val';
                    heroVal.textContent = formatLocalizedCount(nTotal);
                    const heroLbl = document.createElement('div');
                    heroLbl.className = 'fw-stat-hero-lbl';
                    heroLbl.textContent = t('adm_fw_stat_total');
                    heroMain.appendChild(heroVal);
                    heroMain.appendChild(heroLbl);

                    const statusPill = document.createElement('span');
                    const syncFwStatusBadge = () => {
                        const isOn = tFwEnable.input.checked;
                        statusPill.className = 'fw-stat-status-pill' + (isOn ? '' : ' is-off');
                        statusPill.textContent = (isOn ? '🛡️ ' : '⏸️ ') + (isOn ? t('fw_status_active_badge') : t('fw_status_paused_badge'));
                    };
                    syncFwStatusBadge();
                    tFwEnable.input.addEventListener('change', syncFwStatusBadge);
                    hero.appendChild(heroMain);
                    hero.appendChild(statusPill);
                    panel.appendChild(hero);

                    const cats = [
                        { key: 'honeypot', ico: '🍯', lbl: t('adm_fw_stat_honeypot'), val: nHoney, color: '#f59e0b', bg: 'rgba(245, 158, 11, 0.14)' },
                        { key: 'captcha',  ico: '🔢', lbl: t('adm_fw_stat_captcha'),  val: nCap,   color: '#0ea5e9', bg: 'rgba(14, 165, 233, 0.14)' },
                        { key: 'rate',     ico: '⚡', lbl: t('adm_fw_stat_rate'),     val: nRate,  color: '#8b5cf6', bg: 'rgba(139, 92, 246, 0.14)' },
                        { key: 'waf',      ico: '🧱', lbl: t('adm_fw_stat_waf'),      val: nPay,   color: '#ef4444', bg: 'rgba(239, 68, 68, 0.14)' }
                    ];

                    if (nTotal > 0) {
                        const barTrack = document.createElement('div');
                        barTrack.className = 'fw-stat-bar-track';
                        cats.forEach(c => {
                            if (c.val <= 0) return;
                            const seg = document.createElement('div');
                            seg.className = 'fw-stat-bar-seg';
                            seg.style.width = Math.max(3, Math.round((c.val / nTotal) * 100)) + '%';
                            seg.style.background = c.color;
                            seg.title = `${c.lbl}: ${formatLocalizedCount(c.val)}`;
                            barTrack.appendChild(seg);
                        });
                        panel.appendChild(barTrack);
                    } else {
                        const zeroHint = document.createElement('div');
                        zeroHint.style.cssText = 'font-size:11.5px;color:var(--text-muted)';
                        zeroHint.textContent = '✨ ' + t('fw_zero_blocks_hint');
                        panel.appendChild(zeroHint);
                    }

                    const kGrid = document.createElement('div');
                    kGrid.className = 'fw-stat-grid';
                    cats.forEach(c => {
                        const card = document.createElement('div');
                        card.className = 'fw-stat-card';
                        card.dataset.fwMetric = c.key;
                        const icoEl = document.createElement('div');
                        icoEl.className = 'fw-stat-ico';
                        icoEl.style.background = c.bg;
                        icoEl.style.color = c.color;
                        icoEl.textContent = c.ico;

                        const bodyEl = document.createElement('div');
                        bodyEl.className = 'fw-stat-body';
                        const vRow = document.createElement('div');
                        vRow.className = 'fw-stat-val-row';
                        const vNum = document.createElement('span');
                        vNum.className = 'fw-stat-val';
                        vNum.textContent = formatLocalizedCount(c.val);
                        const vPct = document.createElement('span');
                        vPct.className = 'fw-stat-pct';
                        const pct = nTotal > 0 ? Math.round((c.val / nTotal) * 100) : 0;
                        vPct.textContent = formatLocalizedCount(pct) + '%';
                        vRow.appendChild(vNum);
                        vRow.appendChild(vPct);

                        const lEl = document.createElement('div');
                        lEl.className = 'fw-stat-lbl';
                        lEl.textContent = c.lbl;

                        bodyEl.appendChild(vRow);
                        bodyEl.appendChild(lEl);
                        card.appendChild(icoEl);
                        card.appendChild(bodyEl);
                        kGrid.appendChild(card);
                    });
                    panel.appendChild(kGrid);

                    const actRow = document.createElement('div');
                    actRow.className = 'resp-action-row';
                    actRow.style.marginTop = '2px';

                    const refFwBtn = document.createElement('button');
                    refFwBtn.type = 'button';
                    refFwBtn.id = 'btn-adm-fw-refresh-stats';
                    refFwBtn.className = 'btn btn-secondary btn-sm';
                    refFwBtn.textContent = '🔄 ' + t('fw_refresh_stats_btn');
                    refFwBtn.addEventListener('click', async () => {
                        refFwBtn.disabled = true;
                        await loadFwStatsUI();
                    });

                    const rstFwBtn = document.createElement('button');
                    rstFwBtn.type = 'button';
                    rstFwBtn.id = 'btn-adm-fw-reset-stats';
                    rstFwBtn.className = 'btn btn-secondary btn-sm';
                    rstFwBtn.textContent = t('adm_fw_reset_btn');
                    rstFwBtn.addEventListener('click', async () => {
                        const rr = await apiCall('admin_firewall_reset');
                        if (rr.ok) {
                            toast(t('adm_fw_reset_done_toast'));
                            await loadFwStatsUI();
                        } else {
                            toast(rr.message || t('err_generic'), true);
                        }
                    });
                    actRow.appendChild(refFwBtn);
                    actRow.appendChild(rstFwBtn);
                    panel.appendChild(actRow);
                    fwStatsMount.appendChild(panel);
                };
                fwCard.appendChild(fwStatsMount);
                tabContent.appendChild(fwCard);

                // ---- CARD: Global 2FA support + session revocation grace period ----
                const twoFaCard = document.createElement('div');
                twoFaCard.className = 'card-box';
                twoFaCard.dataset.admsetSub = 'auth';
                const twoFaHead = document.createElement('div');
                twoFaHead.className = 'section-header';
                twoFaHead.textContent = t('adm_twofa_sec_title');
                twoFaCard.appendChild(twoFaHead);

                const twoFaDesc = document.createElement('p');
                twoFaDesc.style.cssText = 'font-size:12px;color:var(--text-secondary);margin:0 0 10px;line-height:1.55';
                twoFaDesc.textContent = t('adm_twofa_sec_desc');
                twoFaCard.appendChild(twoFaDesc);

                const tTwoFaGlobal = makeToggleCard(t('adm_twofa_global_lbl'), Number(curSettings.twofa_enabled ?? 1) !== 0);
                twoFaCard.appendChild(tTwoFaGlobal.wrap);
                const twoFaHint = document.createElement('p');
                twoFaHint.style.cssText = 'font-size:11.5px;color:var(--text-muted);margin:0 0 10px;line-height:1.6';
                twoFaHint.textContent = t('adm_twofa_global_hint');
                twoFaCard.appendChild(twoFaHint);

                const graceCard = document.createElement('div');
                graceCard.style.cssText = 'margin:4px 0 0;padding:12px;border:1px solid var(--border);border-radius:12px;background:var(--bg-subtle)';
                const graceHead = document.createElement('div');
                graceHead.style.cssText = 'font-weight:800;font-size:13px;color:var(--primary);margin-bottom:4px';
                graceHead.textContent = t('adm_sess_grace_lbl');
                graceCard.appendChild(graceHead);
                const graceHint = document.createElement('p');
                graceHint.style.cssText = 'font-size:11.5px;color:var(--text-secondary);margin:0 0 8px;line-height:1.6';
                graceHint.textContent = t('adm_sess_grace_hint');
                graceCard.appendChild(graceHint);

                const curGraceSec = Math.max(0, Math.min(86400, Number(curSettings.session_revoke_grace_sec ?? 600)));
                const graceUseHours = (curGraceSec > 0 && curGraceSec % 3600 === 0);
                const graceGrid = document.createElement('div');
                graceGrid.className = 'resp-grid-2';
                const inGraceVal = document.createElement('input');
                inGraceVal.type = 'number';
                inGraceVal.min = '0';
                inGraceVal.max = '1440';
                inGraceVal.dir = 'ltr';
                inGraceVal.className = 'input';
                inGraceVal.value = String(graceUseHours ? Math.round(curGraceSec / 3600) : Math.round(curGraceSec / 60));
                const selGraceUnit = document.createElement('select');
                selGraceUnit.className = 'input';
                [
                    ['minutes', t('session_grace_min_unit')],
                    ['hours', t('session_grace_hour_unit')]
                ].forEach(([uv, ul]) => {
                    const o = document.createElement('option');
                    o.value = uv;
                    o.textContent = ul;
                    if ((graceUseHours ? 'hours' : 'minutes') === uv) o.selected = true;
                    selGraceUnit.appendChild(o);
                });
                const syncGraceMax = () => {
                    if (selGraceUnit.value === 'hours') { inGraceVal.max = '24'; inGraceVal.min = '0'; }
                    else { inGraceVal.max = '1440'; inGraceVal.min = '0'; }
                };
                selGraceUnit.addEventListener('change', () => {
                    const wasHours = (Number(inGraceVal.value) > 24 && selGraceUnit.value === 'hours');
                    if (wasHours) inGraceVal.value = '24';
                    syncGraceMax();
                });
                syncGraceMax();
                graceGrid.appendChild(inGraceVal);
                graceGrid.appendChild(selGraceUnit);
                graceCard.appendChild(graceGrid);
                const graceOffNote = document.createElement('div');
                graceOffNote.style.cssText = 'font-size:11px;color:var(--text-muted);margin-top:6px';
                graceOffNote.textContent = '0 = ' + t('adm_sess_grace_off');
                graceCard.appendChild(graceOffNote);
                twoFaCard.appendChild(graceCard);

                // Global inactivity auto-logout, applied to every account.
                const aloCard = document.createElement('div');
                aloCard.style.cssText = 'margin:10px 0 0;padding:12px;border:1px solid var(--border);border-radius:12px;background:var(--bg-subtle)';
                const aloHead = document.createElement('div');
                aloHead.style.cssText = 'font-weight:800;font-size:13px;color:var(--primary);margin-bottom:4px';
                aloHead.textContent = t('auto_logout_admin_lbl');
                aloCard.appendChild(aloHead);
                const aloHint = document.createElement('p');
                aloHint.style.cssText = 'font-size:11.5px;color:var(--text-secondary);margin:0 0 8px;line-height:1.6';
                aloHint.textContent = t('auto_logout_admin_hint');
                aloCard.appendChild(aloHint);

                const curAloSec = Math.max(0, Math.min(31536000, Number(curSettings.auto_logout_sec ?? 0)));
                const aloUnitPick = (curAloSec >= 86400 && curAloSec % 86400 === 0) ? 86400
                    : ((curAloSec >= 3600 && curAloSec % 3600 === 0) ? 3600 : 60);
                const aloGrid = document.createElement('div');
                aloGrid.className = 'resp-grid-2';
                const inAloVal = document.createElement('input');
                inAloVal.type = 'number';
                inAloVal.min = '0';
                inAloVal.max = '525600';
                inAloVal.dir = 'ltr';
                inAloVal.className = 'input';
                inAloVal.value = String(curAloSec > 0 ? Math.round(curAloSec / aloUnitPick) : 0);
                const selAloUnit = document.createElement('select');
                selAloUnit.className = 'input';
                [
                    ['60', t('auto_logout_unit_min')],
                    ['3600', t('auto_logout_unit_hour')],
                    ['86400', t('auto_logout_unit_day')]
                ].forEach(([uv, ul]) => {
                    const o = document.createElement('option');
                    o.value = uv;
                    o.textContent = ul;
                    if (String(aloUnitPick) === uv) o.selected = true;
                    selAloUnit.appendChild(o);
                });
                const syncAloMax = () => {
                    const m = Number(selAloUnit.value || 60);
                    inAloVal.max = String(Math.floor(31536000 / m));
                };
                selAloUnit.addEventListener('change', syncAloMax);
                syncAloMax();
                aloGrid.appendChild(inAloVal);
                aloGrid.appendChild(selAloUnit);
                aloCard.appendChild(aloGrid);
                const aloOffNote = document.createElement('div');
                aloOffNote.style.cssText = 'font-size:11px;color:var(--text-muted);margin-top:6px';
                aloOffNote.textContent = '0 = ' + t('auto_logout_off');
                aloCard.appendChild(aloOffNote);
                twoFaCard.appendChild(aloCard);

                // Decoy page and the globally forced lock screen.
                const decoyAdmCard = document.createElement('div');
                decoyAdmCard.style.cssText = 'margin:10px 0 0;padding:12px;border:1px solid var(--border);border-radius:12px;background:var(--bg-subtle)';
                const decoyAdmHead = document.createElement('div');
                decoyAdmHead.style.cssText = 'font-weight:800;font-size:13px;color:var(--primary);margin-bottom:4px';
                decoyAdmHead.textContent = t('adm_decoy_sec_title');
                decoyAdmCard.appendChild(decoyAdmHead);

                const tForceLock = makeToggleCard(t('adm_force_lock_lbl'), Number(curSettings.force_lock_screen ?? 0) === 1);
                decoyAdmCard.appendChild(tForceLock.wrap);
                const tForceDecoy = makeToggleCard(t('adm_force_decoy_lbl'), Number(curSettings.force_decoy_screen ?? 0) === 1);
                decoyAdmCard.appendChild(tForceDecoy.wrap);

                const decoyAdmHint = document.createElement('p');
                decoyAdmHint.style.cssText = 'font-size:11.5px;color:var(--text-secondary);margin:0 0 8px;line-height:1.6';
                decoyAdmHint.textContent = t('adm_global_decoy_hint');
                decoyAdmCard.appendChild(decoyAdmHint);

                const mkDecoyAdmField = (labelTxt, phTxt, fieldVal) => {
                    const fg = document.createElement('div');
                    fg.className = 'form-group';
                    const lb = document.createElement('label');
                    lb.textContent = labelTxt;
                    const inp = document.createElement('input');
                    inp.type = 'text';
                    inp.className = 'input';
                    inp.placeholder = phTxt;
                    inp.value = fieldVal;
                    fg.appendChild(lb);
                    fg.appendChild(inp);
                    return { fg, inp };
                };
                const fAdmDecoyTitle = mkDecoyAdmField(t('adm_global_decoy_title_lbl'), t('decoy_default_title'), String(curSettings.global_decoy_title || ''));
                const fAdmDecoySub = mkDecoyAdmField(t('adm_global_decoy_subtitle_lbl'), t('decoy_default_subtitle'), String(curSettings.global_decoy_subtitle || ''));
                decoyAdmCard.appendChild(fAdmDecoyTitle.fg);
                decoyAdmCard.appendChild(fAdmDecoySub.fg);

                const decoyAdmNote = document.createElement('div');
                decoyAdmNote.style.cssText = 'font-size:11px;color:var(--text-muted);margin-top:6px;line-height:1.6';
                decoyAdmNote.textContent = t('lock_forced_no_pw_hint');
                decoyAdmCard.appendChild(decoyAdmNote);
                twoFaCard.appendChild(decoyAdmCard);
                tabContent.appendChild(twoFaCard);
                loadFwStatsUI().catch(() => {});

                // CARD 4: Messaging, Content Protection, Cross-Session Draft Sync & Global Default Auto-Delete (Items #11, #17, #28)
                const msgCard = document.createElement('div');
                msgCard.className = 'card-box';
                msgCard.dataset.admsetSub = 'msg';
                const msgCardHead = document.createElement('div');
                msgCardHead.className = 'section-header';
                msgCardHead.textContent = t('adm_set_sub_msg');
                msgCard.appendChild(msgCardHead);

                const tVoice = makeToggleCard(t('adm_voice_enabled'), Number(curSettings.voice_enabled ?? 1) === 1);
                const tVideoNote = makeToggleCard(t('adm_video_note_enabled'), Number(curSettings.video_note_enabled ?? 1) === 1);
                const tE2ee = makeToggleCard(t('adm_e2ee_enabled'), Number(curSettings.e2ee_enabled ?? 1) === 1);
                const tGlobalHideEdit = makeToggleCard(t('adm_global_hide_edit_badge_lbl'), Number(curSettings.global_hide_edit_badge ?? 0) === 1);
                tGlobalHideEdit.input.id = 'adm-global-hide-edit-badge';
                // Layered global switches: the master switch, then the per-type
                // switches. Chat admins and members can still switch a feature off
                // below these, but never back on against them.
                const tViews = makeToggleCard(t('adm_msg_views_enabled'), Number(curSettings.msg_views_enabled ?? 1) === 1);
                const tViewsGroups = makeToggleCard(t('adm_msg_views_groups'), Number(curSettings.msg_views_enabled_groups ?? 1) === 1);
                const tViewsChannels = makeToggleCard(t('adm_msg_views_channels'), Number(curSettings.msg_views_enabled_channels ?? 1) === 1);
                const tPreview = makeToggleCard(t('adm_chat_preview_enabled'), Number(curSettings.chat_preview_enabled ?? 1) === 1);
                const tPreviewGroups = makeToggleCard(t('adm_chat_preview_groups'), Number(curSettings.chat_preview_enabled_groups ?? 1) === 1);
                const tPreviewChannels = makeToggleCard(t('adm_chat_preview_channels'), Number(curSettings.chat_preview_enabled_channels ?? 1) === 1);
                msgCard.appendChild(tVoice.wrap);
                msgCard.appendChild(tVideoNote.wrap);
                msgCard.appendChild(tE2ee.wrap);
                msgCard.appendChild(tGlobalHideEdit.wrap);

                // The six master switches are site-wide, so they belong to the
                // founder. Super-admins get the per-chat layer below instead, and
                // see nothing of this block at all rather than a row they cannot
                // actually save.
                const featWrap = document.createElement('div');
                featWrap.className = 'adm-feature-block';
                const featHead = document.createElement('div');
                featHead.className = 'adm-feature-head';
                featHead.textContent = t('adm_global_feature_head');
                const featNote = document.createElement('p');
                featNote.className = 'adm-feature-note';
                featNote.textContent = t('adm_global_feature_note');
                featWrap.appendChild(featHead);
                featWrap.appendChild(featNote);
                featWrap.appendChild(tViews.wrap);
                featWrap.appendChild(tViewsGroups.wrap);
                featWrap.appendChild(tViewsChannels.wrap);
                featWrap.appendChild(tPreview.wrap);
                featWrap.appendChild(tPreviewGroups.wrap);
                featWrap.appendChild(tPreviewChannels.wrap);
                markFounderOnly(featWrap);
                msgCard.appendChild(featWrap);

                // Per-chat override. This is the layer a super-admin owns: pick a
                // group or channel and force either feature off for it, on top of
                // whatever the founder set globally.
                const pcWrap = document.createElement('div');
                pcWrap.className = 'adm-feature-block';
                const pcHead = document.createElement('div');
                pcHead.className = 'adm-feature-head';
                pcHead.textContent = t('adm_per_chat_head');
                const pcNote = document.createElement('p');
                pcNote.className = 'adm-feature-note';
                pcNote.textContent = t('adm_per_chat_note');
                pcWrap.appendChild(pcHead);
                pcWrap.appendChild(pcNote);

                const pcSel = document.createElement('select');
                pcSel.className = 'input';
                const pcLoading = document.createElement('option');
                pcLoading.textContent = t('adm_per_chat_loading');
                pcSel.appendChild(pcLoading);
                pcSel.disabled = true;
                pcWrap.appendChild(pcSel);

                const pcPreview = makeToggleCard(t('chat_preview_lbl'), true);
                const pcViews = makeToggleCard(t('msg_views_lbl'), true);
                pcPreview.input.disabled = true;
                pcViews.input.disabled = true;
                pcWrap.appendChild(pcPreview.wrap);
                pcWrap.appendChild(pcViews.wrap);
                msgCard.appendChild(pcWrap);

                let pcChats = [];
                const applyPcState = () => {
                    const cid = Number(pcSel.value || 0);
                    const c = pcChats.find(x => Number(x.id) === cid) || null;
                    const offPrev = c ? (Array.isArray(c.preview_off_chats) ? c.preview_off_chats : []) : [];
                    pcPreview.input.disabled = !c;
                    pcViews.input.disabled = !c;
                    if (!c) return;
                    pcPreview.input.checked = (Number(c.preview_forced_off) !== 1);
                    pcViews.input.checked = (c.type === 'group' || c.type === 'channel') ? (Number(c.views_forced_off) !== 1) : true;
                    pcViews.wrap.style.display = (c.type === 'group' || c.type === 'channel') ? '' : 'none';
                };
                const savePc = async (feature, on) => {
                    const cid = Number(pcSel.value || 0);
                    if (!cid) return;
                    const r = await apiCall('admin_chat_feature_force', { chat_id: cid, feature, enabled: on ? 1 : 0 });
                    if (!r.ok) { toast(r.message || t('err_generic'), true); return; }
                    const c = pcChats.find(x => Number(x.id) === cid);
                    if (c) {
                        if (feature === 'chat_preview') c.preview_forced_off = on ? 0 : 1;
                        else c.views_forced_off = on ? 0 : 1;
                    }
                    toast(t(feature === 'chat_preview' ? 'chat_preview_lbl' : 'msg_views_lbl') + ': ' + t(on ? 'feature_state_on' : 'feature_state_off'));
                };
                pcPreview.input.addEventListener('change', () => savePc('chat_preview', pcPreview.input.checked));
                pcViews.input.addEventListener('change', () => savePc('msg_views', pcViews.input.checked));
                pcSel.addEventListener('change', applyPcState);

                (async () => {
                    try {
                        const r = await apiCall('admin_chats_list', { filter_type: 'groups_channels' });
                        pcChats = (r && r.ok && Array.isArray(r.data && r.data.chats)) ? r.data.chats : [];
                    } catch (e) { pcChats = []; }
                    pcSel.innerHTML = '';
                    if (!pcChats.length) {
                        const o = document.createElement('option');
                        o.textContent = t('adm_per_chat_none');
                        pcSel.appendChild(o);
                        pcSel.disabled = true;
                        return;
                    }
                    pcSel.disabled = false;
                    for (const c of pcChats) {
                        const o = document.createElement('option');
                        o.value = String(c.id);
                        o.textContent = `${(c.type === 'channel' ? t('channel_label') : t('group_label'))} — ${c.title || ('#' + c.id)}`;
                        pcSel.appendChild(o);
                    }
                    applyPcState();
                })();

                // Cross-Session Draft Sync Section (Item #11)
                const draftAdmBox = document.createElement('div');
                draftAdmBox.style.cssText = 'margin:12px 0;padding:12px;border:1px solid var(--border);border-radius:12px;background:var(--bg-subtle)';
                const draftAdmHead = document.createElement('div');
                draftAdmHead.style.cssText = 'font-weight:800;font-size:13px;color:var(--primary);margin-bottom:6px';
                draftAdmHead.textContent = t('adm_draft_sync_sec_title');
                draftAdmBox.appendChild(draftAdmHead);
                const tDraftSync = makeToggleCard(t('adm_draft_sync_enable_lbl'), Number(curSettings.draft_sync_enabled ?? 1) !== 0);
                draftAdmBox.appendChild(tDraftSync.wrap);
                const fgDraftIntv = document.createElement('div');
                fgDraftIntv.className = 'form-group';
                fgDraftIntv.style.marginBottom = '0';
                const lDraftIntv = document.createElement('label');
