                tmHead.textContent = t('adm_time_sec_title');
                timeCard.appendChild(tmHead);

                const liveRow = document.createElement('div');
                liveRow.style.cssText = 'display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap;padding:10px 12px;border-radius:10px;background:var(--bg-body);border:1px solid var(--border);margin-bottom:10px';
                const liveLbl = document.createElement('span');
                liveLbl.style.cssText = 'font-size:12.5px;font-weight:700;color:var(--text-secondary)';
                liveLbl.textContent = t('adm_time_live_clock_lbl');
                const liveClockVal = document.createElement('bdi');
                liveClockVal.dir = 'ltr';
                liveClockVal.style.cssText = 'font-size:13.5px;font-weight:900;color:var(--primary)';
                let tzAppSel = null;
                const updateLiveClock = () => {
                    const mNow = getMessengerNowSec();
                    const dObj = new Date(mNow * 1000);
                    const effTz = (tzAppSel && tzAppSel.value)
                        ? (tzAppSel.value === 'browser' ? undefined : tzAppSel.value)
                        : getEffectiveAppTimeZone();
                    const loc = store.lang === 'fa' ? 'fa-IR-u-ca-persian' : 'en-US';
                    const dOpts = { year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false };
                    if (effTz) dOpts.timeZone = effTz;
                    try {
                        liveClockVal.textContent = new Intl.DateTimeFormat(loc, dOpts).format(dObj);
                    } catch (e) {
                        const [jy, jm, jd] = gregorianToJalali(dObj.getFullYear(), dObj.getMonth() + 1, dObj.getDate());
                        const pad2 = n => String(n).padStart(2, '0');
                        const hms = `${pad2(dObj.getHours())}:${pad2(dObj.getMinutes())}:${pad2(dObj.getSeconds())}`;
                        liveClockVal.textContent = store.lang === 'fa'
                            ? `${jy}/${pad2(jm)}/${pad2(jd)} — ${hms}`
                            : `${dObj.getFullYear()}-${pad2(dObj.getMonth() + 1)}-${pad2(dObj.getDate())} ${hms}`;
                    }
                };
                updateLiveClock();
                admLiveClockTimer = setInterval(() => {
                    if (!document.body.contains(liveClockVal)) {
                        clearInterval(admLiveClockTimer);
                        admLiveClockTimer = null;
                        return;
                    }
                    updateLiveClock();
                }, 1000);
                liveRow.appendChild(liveLbl);
                liveRow.appendChild(liveClockVal);
                timeCard.appendChild(liveRow);

                // Item #14: Configurable Messenger Timezone in Admin Panel -> Settings
