                tzAppSel.className = 'input';
                const curAppTz = String(curSettings.app_timezone || store.settings.app_timezone || 'Asia/Tehran');
                const tzChoices = [
                    ['Asia/Tehran', 'Asia/Tehran (تهران — UTC+03:30)'],
                    ['browser', t('adm_app_timezone_browser')],
                    ['UTC', 'UTC (ساعت هماهنگ جهانی — UTC+00:00)'],
                    ['Asia/Kabul', 'Asia/Kabul (کابل — UTC+04:30)'],
                    ['Asia/Dubai', 'Asia/Dubai (دبی — UTC+04:00)'],
                    ['Asia/Baghdad', 'Asia/Baghdad (بغداد — UTC+03:00)'],
                    ['Europe/Istanbul', 'Europe/Istanbul (استانبول — UTC+03:00)'],
                    ['Asia/Baku', 'Asia/Baku (باکو — UTC+04:00)'],
                    ['Asia/Yerevan', 'Asia/Yerevan (ایروان — UTC+04:00)'],
                    ['Europe/Moscow', 'Europe/Moscow (مسکو — UTC+03:00)'],
                    ['Europe/Berlin', 'Europe/Berlin (برلین / فرانکفورت — CET/CEST)'],
                    ['Europe/London', 'Europe/London (لندن — GMT/BST)'],
                    ['Europe/Paris', 'Europe/Paris (پاریس — CET/CEST)'],
                    ['Asia/Tashkent', 'Asia/Tashkent (تاشکند — UTC+05:00)'],
                    ['Asia/Karachi', 'Asia/Karachi (کراچی — UTC+05:00)'],
                    ['Asia/Kolkata', 'Asia/Kolkata (دهلی — UTC+05:30)'],
                    ['Asia/Bangkok', 'Asia/Bangkok (بانکوک — UTC+07:00)'],
                    ['Asia/Shanghai', 'Asia/Shanghai (شانگهای — UTC+08:00)'],
                    ['Asia/Tokyo', 'Asia/Tokyo (توکیو — UTC+09:00)'],
                    ['Australia/Sydney', 'Australia/Sydney (سیدنی — AEST/AEDT)'],
                    ['America/New_York', 'America/New_York (نیویورک — EST/EDT)'],
                    ['America/Chicago', 'America/Chicago (شیکاگو — CST/CDT)'],
                    ['America/Los_Angeles', 'America/Los_Angeles (لس‌آنجلس — PST/PDT)'],
                    ['America/Toronto', 'America/Toronto (تورنتو — EST/EDT)']
                ];
                if (!tzChoices.some(c => c[0] === curAppTz)) {
                    tzChoices.unshift([curAppTz, curAppTz]);
                }
                tzChoices.forEach(([val, lbl]) => {
                    const o = document.createElement('option');
                    o.value = val;
                    o.textContent = lbl;
                    if (val === curAppTz) o.selected = true;
                    tzAppSel.appendChild(o);
                });
                const tzAppHint = document.createElement('div');
                tzAppHint.style.cssText = 'font-size:11.5px;color:var(--text-muted);margin-top:4px;line-height:1.5';
                tzAppHint.textContent = t('adm_app_timezone_hint');
                tzAppFg.appendChild(tzAppLbl);
                tzAppFg.appendChild(tzAppSel);
                tzAppFg.appendChild(tzAppHint);
                tzAppSel.addEventListener('change', () => updateLiveClock());
                timeCard.appendChild(tzAppFg);
                updateLiveClock();

                const selTimeMode = document.createElement('select');
                selTimeMode.className = 'input';
                selTimeMode.style.marginBottom = '8px';
                const curTimeMode = String(curSettings.messenger_time_mode || 'server');
                [
                    ['server', t('adm_time_mode_server')],
                    ['custom', t('adm_time_mode_custom')]
                ].forEach(([tv, tl]) => {
                    const o = document.createElement('option');
                    o.value = tv;
                    o.textContent = tl;
                    if (tv === curTimeMode) o.selected = true;
                    selTimeMode.appendChild(o);
                });
                timeCard.appendChild(selTimeMode);

                const customTimeGroup = document.createElement('div');
                customTimeGroup.className = 'form-group' + (curTimeMode === 'custom' ? '' : ' hidden');
                const customTimeLbl = document.createElement('label');
                customTimeLbl.textContent = t('adm_time_pick_lbl');
                const customTimeInput = document.createElement('input');
                customTimeInput.type = 'datetime-local';
                customTimeInput.className = 'input';
                customTimeInput.dir = 'ltr';
                const toLocalIsoMinute = (sec) => {
                    const d = new Date(sec * 1000);
                    const p = n => String(n).padStart(2, '0');
                    return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}T${p(d.getHours())}:${p(d.getMinutes())}`;
                };
                customTimeInput.value = toLocalIsoMinute(Number(curSettings.messenger_now || getMessengerNowSec()));
                customTimeGroup.appendChild(customTimeLbl);
                customTimeGroup.appendChild(customTimeInput);
                timeCard.appendChild(customTimeGroup);

                selTimeMode.addEventListener('change', () => {
                    customTimeGroup.classList.toggle('hidden', selTimeMode.value !== 'custom');
                });

                // No button of its own: the pinned bar at the bottom now sends
                // these values along with everything else.
                tabContent.appendChild(timeCard);

                const admCallCtrls = {
                    chkVoice: admChkVoice.c,
                    chkVideo: admChkVideo.c,
                    selAud: admSelAud.sel,
                    selVid: admSelVid.sel,
                    inDur: inAdmDur
                };

                // The save bar sticks to the bottom of the scroll area: the tab is
                // long, and a button you have to scroll away from the top to reach
                // is a button that gets forgotten. It stays inside the flow of the
                // tab rather than floating over the whole page, so it still hides
                // with the danger sub-category, which saves through its own button.
                const saveBarCard = document.createElement('div');
                saveBarCard.className = 'card-box adm-sticky-save-card';
                saveBarCard.style.padding = '12px 14px';
                const bRow = document.createElement('div');
                bRow.className = 'settings-save-bar resp-action-row';
                bRow.style.cssText = 'margin:0;padding:0;border-top:none;justify-content:flex-end';

                const saveSBtn = document.createElement('button');
                saveSBtn.type = 'button';
                saveSBtn.id = 'btn-adm-save-general-settings';
                saveSBtn.className = 'btn btn-primary btn-sm';
                saveSBtn.textContent = t('save_changes');
                saveSBtn.addEventListener('click', async () => {
                    if (tMaint.input.checked) {
                        const ap = await askApproval({
                            title: t('adm_settings_title'),
                            desc: t('ask_adm_maint_on'),
                            danger: true,
                            icon: '🔧'
                        });
                        if (!ap.approved) return;
                    }
                    const nextFa = inSiteFa.value.trim() || 'پیامرسان کوچک من (M3)';
                    const nextEn = inSiteEn.value.trim() || 'My Mini Messenger (M3)';
                    // Caught here as well as on the server, so the owner is told
                    // before anything is sent rather than after a round trip.
                    if (tForceLock.input.checked && tForceDecoy.input.checked) {
                        toast(t('adm_lock_decoy_exclusive'), true);
                        return;
                    }
                    const timePayload = { messenger_time_mode: selTimeMode.value };
                    if (selTimeMode.value === 'custom' && customTimeInput.value) {
                        const parsedMs = new Date(customTimeInput.value).getTime();
                        if (Number.isFinite(parsedMs) && parsedMs > 0) {
                            timePayload.custom_messenger_ts = Math.floor(parsedMs / 1000);
                        }
                    } else {
                        timePayload.messenger_time_offset_sec = 0;
                    }
                    const r = await apiCall('admin_settings_update', {
                        ...timePayload,
                        site_name_fa: nextFa,
                        site_name_en: nextEn,
                        site_name: store.lang === 'en' ? nextEn : nextFa,
                        site_logo: draftSiteLogo,
                        site_favicon: draftSiteFavicon,
                        reg_mode: selReg.value,
                        default_theme: selDefTheme.value,
                        default_lang: selDefLang.value,
                        reserved_handles: inResHandles.value.trim(),
                        ...readNormalizedIdLenPayload(),
                        announcement: inAnn.value.trim(),
                        maintenance_mode: tMaint.input.checked ? 1 : 0,
                        voice_enabled: tVoice.input.checked ? 1 : 0,
                        video_note_enabled: tVideoNote.input.checked ? 1 : 0,
                        msg_views_enabled: tViews.input.checked ? 1 : 0,
                        msg_views_enabled_groups: tViewsGroups.input.checked ? 1 : 0,
                        msg_views_enabled_channels: tViewsChannels.input.checked ? 1 : 0,
                        chat_preview_enabled: tPreview.input.checked ? 1 : 0,
                        chat_preview_enabled_groups: tPreviewGroups.input.checked ? 1 : 0,
                        chat_preview_enabled_channels: tPreviewChannels.input.checked ? 1 : 0,
                        e2ee_enabled: tE2ee.input.checked ? 1 : 0,
                        global_hide_edit_badge: tGlobalHideEdit.input.checked ? 1 : 0,
                        global_typing_policy: selGlobalTypingPol.value,
                        allow_copy_msg: tAllowCopy.input.checked ? 1 : 0,
                        allow_select_text: tAllowSelect.input.checked ? 1 : 0,
                        allow_file_download: tAllowDownload.input.checked ? 1 : 0,
                        allow_forward_msg: tAllowForward.input.checked ? 1 : 0,
                        show_superadmin_transfer_msg: tShowSuperTransfer.input.checked ? 1 : 0,
                        global_restricted_content_types: collectAdmGlobalBlockedTypes(),
                        calls_voice_enabled: admCallCtrls.chkVoice.checked ? 1 : 0,
                        calls_video_enabled: admCallCtrls.chkVideo.checked ? 1 : 0,
                        calls_audio_policy: admCallCtrls.selAud.value,
                        calls_video_policy: admCallCtrls.selVid.value,
                        calls_max_duration_sec: Math.max(0, Math.min(86400, (parseInt(admCallCtrls.inDur.value || '0', 10) || 0) * 60)),
                        default_ttl: Math.max(0, Math.min(31536000, parseInt(inGlobalDefTtl.value || '0', 10) || 0)),
                        default_ttl_mode: selGlobalDefTtlMode.value,
                        draft_sync_enabled: tDraftSync.input.checked ? 1 : 0,
                        draft_sync_interval_sec: Math.max(2, Math.min(120, parseInt(inDraftIntv.value || '3', 10) || 3)),
                        fw_enabled: tFwEnable.input.checked ? 1 : 0,
                        fw_captcha_enabled: tFwCaptcha.input.checked ? 1 : 0,
                        fw_honeypot_enabled: tFwHoneypot.input.checked ? 1 : 0,
                        fw_payload_shield: tFwPayload.input.checked ? 1 : 0,
                        fw_rate_limit_rpm: Math.max(30, Math.min(5000, parseInt(inFwRateRpm.value || '240', 10) || 240)),
                        fw_auth_limit_rpm: Math.max(5, Math.min(600, parseInt(inFwAuthRpm.value || '20', 10) || 20)),
                        edit_window_sec: Math.max(0, Math.min(8760, parseInt(inEditWinHrs.value || '0', 10) || 0)) * 3600,
                        delete_mode: selDelMode.value,
                        allowed_exts: inAllowedExts.value.trim(),
                        max_msg_len: Math.max(100, Math.min(32000, parseInt(fMaxMsgLen.inp.value || '2000', 10) || 2000)),
                        max_total_users: Math.max(0, Math.min(10000000, parseInt(fMaxTotalUsers.inp.value || '0', 10) || 0)),
                        max_user_chats: Math.max(0, Math.min(100000, parseInt(fMaxUserChats.inp.value || '0', 10) || 0)),
                        max_user_created_groups: Math.max(0, Math.min(100000, parseInt(fMaxCreatedGroups.inp.value || '0', 10) || 0)),
                        max_user_created_channels: Math.max(0, Math.min(100000, parseInt(fMaxCreatedChannels.inp.value || '0', 10) || 0)),
                        max_group_members: Math.max(0, Math.min(1000000, parseInt(fMaxGroupMem.inp.value || '0', 10) || 0)),
                        max_channel_members: Math.max(0, Math.min(1000000, parseInt(fMaxChanMem.inp.value || '0', 10) || 0)),
                        remember_cookie_sec: Math.max(300, Math.min(31536000, (Math.max(1, parseInt(inCookieVal.value || '30', 10) || 30)) * (selCookieUnit.value === 'hours' ? 3600 : 86400))),
                        twofa_enabled: tTwoFaGlobal.input.checked ? 1 : 0,
                        session_revoke_grace_sec: Math.max(0, Math.min(86400, (Math.max(0, parseInt(inGraceVal.value || '0', 10) || 0)) * (selGraceUnit.value === 'hours' ? 3600 : 60))),
                        auto_logout_sec: Math.max(0, Math.min(31536000, (Math.max(0, parseInt(inAloVal.value || '0', 10) || 0)) * Math.max(1, parseInt(selAloUnit.value || '60', 10) || 60))),
                        msg_viewers_policy: selGlobalMvPolicy.value,
                        force_hide_last_seen: chkForceHideSeen.checked ? 1 : 0,
                        force_lock_screen: tForceLock.input.checked ? 1 : 0,
                        force_decoy_screen: tForceDecoy.input.checked ? 1 : 0,
                        global_decoy_title: fAdmDecoyTitle.inp.value.trim(),
                        global_decoy_subtitle: fAdmDecoySub.inp.value.trim(),
                        app_timezone: (document.getElementById('adm-app-timezone-select') && document.getElementById('adm-app-timezone-select').value) || curSettings.app_timezone || 'Asia/Tehran'
                    });
                    if (r.ok) {
                        store.settings = Object.assign(store.settings, r.data.settings || {});
                        applyAuthIdentityInputLimits();
                        DraftSyncManager.restartLoop();
                        document.documentElement.setAttribute('data-site-fa', store.settings.site_name_fa || nextFa);
                        document.documentElement.setAttribute('data-site-en', store.settings.site_name_en || nextEn);
                        applySiteBrandingAssets(store.settings.site_logo || '', store.settings.site_favicon || '');
                        const authTitleEl = document.getElementById('auth-site-title');
                        if (authTitleEl) authTitleEl.textContent = formatSiteName();
                        hubTexts.innerHTML = `<div style="font-weight:800;font-size:15px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${esc(formatSiteName())}</div><div style="font-size:11.5px;color:var(--text-muted)">🛡️ ${esc(t('admin_panel'))}</div>`;
                        renderChatList();
                        if (typeof syncComposerMediaPolicyButtons === 'function') syncComposerMediaPolicyButtons(getActiveChat());
                        if (store.activeChatId) {
                            renderActiveChatHeader();
                            await renderMessagesViewport(false);
                        }
                        // The live clock reads the settings that were just
                        // written, so it has to be told to redraw.
                        updateLiveClock();
                        toast(t('adm_settings_saved_toast'));
                    }
                });
                bRow.appendChild(saveSBtn);
                saveBarCard.appendChild(bRow);
                tabContent.appendChild(saveBarCard);

                // The sentinel sits just past the bar, so it only comes into view
                // once the bar has reached the end of the content and settled into
                // its own place. Until then the bar is pinned, which is the only
                // time its bottom corners need squaring off.
                const saveBarSentinel = document.createElement('div');
                saveBarSentinel.setAttribute('aria-hidden', 'true');
                saveBarSentinel.style.cssText = 'height:1px';
                tabContent.appendChild(saveBarSentinel);
                if (typeof IntersectionObserver === 'function' && tabContent.parentElement) {
                    const saveBarIo = new IntersectionObserver(entries => {
                        // The tab is rebuilt on every visit; stop watching once
                        // this bar is gone so observers do not pile up.
                        if (!document.body.contains(saveBarCard)) {
                            saveBarIo.disconnect();
                            return;
                        }
                        const last = entries[entries.length - 1];
                        saveBarCard.classList.toggle('adm-save-stuck', !last.isIntersecting);
                    }, { root: tabContent.parentElement, threshold: 0 });
                    saveBarIo.observe(saveBarSentinel);
                }



                // Item #23: Unified Super-Admin Handover & Permanent Autonomous Governance Card
                const govUnifiedCard = document.createElement('div');
                govUnifiedCard.className = 'danger-card';
                govUnifiedCard.id = 'adm-unified-governance-card';
                govUnifiedCard.dataset.admsetSub = 'auth danger';
                const guHead = document.createElement('div');
                guHead.className = 'section-header';
                guHead.style.color = 'var(--danger)';
                guHead.textContent = t('adm_gov_unified_card_title');
                govUnifiedCard.appendChild(guHead);

                const rtSubHead = document.createElement('div');
                rtSubHead.style.cssText = 'font-weight:800;font-size:13px;color:var(--text-main);margin-bottom:6px';
                rtSubHead.textContent = t('adm_role_transfer_sec_title');
                govUnifiedCard.appendChild(rtSubHead);

                tShowSuperTransfer.wrap.style.marginBottom = '12px';
                tShowSuperTransfer.input.addEventListener('change', async () => {
                    const nextFlag = tShowSuperTransfer.input.checked ? 1 : 0;
                    const rr = await apiCall('admin_settings_update', { show_superadmin_transfer_msg: nextFlag });
                    if (rr.ok && rr.data && rr.data.settings) {
                        store.settings = Object.assign(store.settings, rr.data.settings);
                        toast(t('adm_settings_saved_toast'));
                    }
                });
                govUnifiedCard.appendChild(tShowSuperTransfer.wrap);

                const relDivider = markFounderOnly(document.createElement('div'));
                relDivider.style.cssText = 'border-top:1px solid var(--border);margin:12px 0';
                govUnifiedCard.appendChild(relDivider);

                const relHead = markFounderOnly(document.createElement('div'));
                relHead.style.cssText = 'font-weight:800;font-size:13px;color:var(--danger);margin-bottom:6px';
                relHead.textContent = t('adm_relinquish_sec_title');
                govUnifiedCard.appendChild(relHead);

                const relDesc = markFounderOnly(document.createElement('p'));
                relDesc.style.cssText = 'font-size:12.5px;color:var(--text-secondary);margin:0 0 10px;line-height:1.6';
                relDesc.textContent = t('adm_relinquish_sec_desc');
                govUnifiedCard.appendChild(relDesc);

                const relBtn = markFounderOnly(document.createElement('button'));
                relBtn.type = 'button';
                relBtn.className = 'btn btn-danger btn-sm';
                relBtn.textContent = t('adm_relinquish_btn');
                relBtn.addEventListener('click', async () => {
                    const ap = await askApproval({
                        title: t('adm_relinquish_sec_title'),
                        desc: t('adm_relinquish_sec_desc'),
                        checkboxLabel: t('adm_relinquish_chk'),
                        checkboxRequired: true,
                        danger: true,
                        icon: '🏛️'
                    });
                    if (!ap.approved) return;
                    const r = await apiCall('admin_relinquish_superadmin', { confirmed: 1 });
                    if (r.ok) {
                        if (r.data && r.data.user) store.user = r.data.user;
                        if (r.data && r.data.settings) store.settings = Object.assign(store.settings, r.data.settings);
                        close();
                        renderSelfDock();
                        renderActiveChatHeader();
                        if (store.activeChatId) await selectChat(store.activeChatId);
                        toast(t('adm_relinquish_done_toast'));
                    } else {
                        toast(r.message || t('err_generic'), true);
                    }
                });
                govUnifiedCard.appendChild(relBtn);
                tabContent.appendChild(govUnifiedCard);

                const admResetCard = markFounderOnly(document.createElement('div'));
                admResetCard.className = 'card-box';
                admResetCard.setAttribute('data-admset-sub', 'brand auth msg calls general security media timers');
                const arHead = document.createElement('div');
                arHead.className = 'section-header';
                arHead.textContent = t('adm_reset_settings_sec_title');
                const arDesc = document.createElement('p');
                arDesc.style.cssText = 'font-size:12.5px;color:var(--text-secondary);margin:0 0 10px;line-height:1.55';
                arDesc.textContent = t('adm_reset_settings_sec_desc');
                const arBtn = document.createElement('button');
                arBtn.type = 'button';
                arBtn.id = 'btn-adm-reset-settings';
                arBtn.className = 'btn btn-secondary btn-sm';
                arBtn.textContent = t('adm_reset_settings_btn');
                arBtn.addEventListener('click', async () => {
                    const ap = await askApproval({
                        title: t('adm_reset_settings_sec_title'),
                        desc: t('adm_reset_settings_sec_desc'),
                        checkboxLabel: t('adm_reset_settings_chk_lbl'),
                        checkboxRequired: true,
                        danger: false,
                        icon: '🔄'
                    });
                    if (!ap.approved) return;
                    const rr = await apiCall('admin_settings_reset', { confirmed: 1 });
                    if (rr.ok && rr.data && rr.data.settings) {
                        store.settings = Object.assign(store.settings || {}, rr.data.settings);
                        applyAuthIdentityInputLimits();
                        if (store.settings.site_name_fa) document.documentElement.setAttribute('data-site-fa', store.settings.site_name_fa);
                        if (store.settings.site_name_en) document.documentElement.setAttribute('data-site-en', store.settings.site_name_en);
                        applySiteBrandingAssets(store.settings.site_logo || '', store.settings.site_favicon || '');
                        renderGlobalIdleBanner();
                        renderActiveChatHeader();
                        syncTtlControlUI();
                        toast(t('adm_reset_settings_done_toast'));
                        await renderTab('settings');
                    } else {
                        toast(rr.message || t('err_generic'), true);
                    }
                });
                admResetCard.appendChild(arHead);
                admResetCard.appendChild(arDesc);
                admResetCard.appendChild(arBtn);
                tabContent.appendChild(admResetCard);

                if (globalSearchIn && globalSearchIn.value.trim()) {
                    applyGlobalAdminSearch();
                }

            } else if (tabId === 'backup') {
                const stRes = await apiCall('admin_stats');
                tabContent.innerHTML = '';
                const d = (stRes.ok && stRes.data) ? stRes.data : {};

                // 1. Download Backups Card (3 Modes: Database / Files / Full)
                const dlCard = document.createElement('div');
                dlCard.className = 'card-box';
                const dlHead = document.createElement('div');
                dlHead.className = 'section-header';
                dlHead.textContent = t('adm_bak_sec_title');
                dlCard.appendChild(dlHead);

                const dlDesc = document.createElement('p');
                dlDesc.style.cssText = 'font-size:12.5px;color:var(--text-secondary);margin:0 0 10px;line-height:1.55';
                dlDesc.textContent = `${t('adm_bak_sec_desc')} (🗄️ DB: ${formatBytes(d.db_size_bytes || 0)} • 📂 ${formatLocalizedCount(d.files_count || 0)} ${t('adm_files_lbl')}: ${formatBytes(d.disk_usage_bytes || 0)})`;
                dlCard.appendChild(dlDesc);

                const dlGrid = document.createElement('div');
                dlGrid.className = 'backup-modes-grid';

                const triggerBackupDownload = async (mode, btnEl, origLabel) => {
                    btnEl.disabled = true;
                    btnEl.textContent = t('adm_bak_downloading_wait');
                    try {
                        const headers = { 'Content-Type': 'application/json' };
                        if (store.csrf) headers['X-CSRF-Token'] = store.csrf;
                        const resp = await fetch(`?a=api&do=admin_backup_download` + (store.csrf ? `&csrf_token=${encodeURIComponent(store.csrf)}` : ''), {
                            method: 'POST',
                            headers,
                            credentials: 'same-origin',
                            body: JSON.stringify({ do: 'admin_backup_download', mode, csrf_token: store.csrf || '' })
                        });
                        if (!resp.ok) {
                            let errMsg = t('err_generic');
                            try { const j = await resp.json(); if (j && j.message) errMsg = j.message; } catch (e) {}
                            toast(errMsg, true);
                            return;
                        }
                        const blob = await resp.blob();
                        const cd = resp.headers && typeof resp.headers.get === 'function' ? (resp.headers.get('Content-Disposition') || '') : '';
                        const fnMatch = cd.match(/filename="([^"]+)"/);
                        const dlFilename = fnMatch ? fnMatch[1] : `m3_${mode}_backup_${Date.now()}.m3b`;
                        const url = URL.createObjectURL(blob);
                        const a = document.createElement('a');
                        a.href = url;
                        a.download = dlFilename;
                        document.body.appendChild(a);
                        a.click();
                        a.remove();
                        setTimeout(() => { try { URL.revokeObjectURL(url); } catch (e) {} }, 2000);
                        toast(t('adm_bak_downloaded_toast'));
                    } catch (err) {
                        toast(t('err_generic'), true);
                    } finally {
                        btnEl.disabled = false;
                        btnEl.textContent = origLabel;
                    }
                };

                [
                    { mode: 'db', id: 'btn-bak-dl-db', title: t('adm_bak_db_title'), desc: t('adm_bak_db_desc'), btn: t('adm_bak_db_btn'), cls: 'btn-secondary' },
                    { mode: 'files', id: 'btn-bak-dl-files', title: t('adm_bak_files_title'), desc: t('adm_bak_files_desc'), btn: t('adm_bak_files_btn'), cls: 'btn-secondary' },
                    { mode: 'full', id: 'btn-bak-dl-full', title: t('adm_bak_full_title'), desc: t('adm_bak_full_desc'), btn: t('adm_bak_full_btn'), cls: 'btn-primary' }
                ].forEach(cfg => {
                    const mc = document.createElement('div');
                    mc.className = 'backup-mode-card';
                    const topDiv = document.createElement('div');
                    const h4 = document.createElement('h4');
                    h4.textContent = cfg.title;
                    const p = document.createElement('p');
                    p.textContent = cfg.desc;
                    topDiv.appendChild(h4);
                    topDiv.appendChild(p);

                    const b = document.createElement('button');
                    b.type = 'button';
                    b.id = cfg.id;
                    b.className = `btn ${cfg.cls} btn-sm btn-block`;
                    b.textContent = cfg.btn;
                    b.addEventListener('click', () => triggerBackupDownload(cfg.mode, b, cfg.btn));

                    mc.appendChild(topDiv);
                    mc.appendChild(b);
                    dlGrid.appendChild(mc);
                });

                dlCard.appendChild(dlGrid);
                tabContent.appendChild(dlCard);

                // 2. Restore Backups Card (3 Modes: Database / Files / Full)
                const rsCard = markFounderOnly(document.createElement('div'));
                rsCard.className = 'card-box';
                const rsHead = document.createElement('div');
                rsHead.className = 'section-header';
                rsHead.textContent = t('adm_rest_sec_title');
                rsCard.appendChild(rsHead);

                const rsDesc = document.createElement('p');
                rsDesc.style.cssText = 'font-size:12.5px;color:var(--text-secondary);margin:0 0 12px;line-height:1.55';
                rsDesc.textContent = t('adm_rest_sec_desc');
                rsCard.appendChild(rsDesc);

                const fgMode = document.createElement('div');
                fgMode.className = 'form-group';
                const lMode = document.createElement('label');
                lMode.textContent = t('adm_rest_mode_lbl');
                const selRestMode = document.createElement('select');
                selRestMode.id = 'adm-restore-mode-select';
                selRestMode.className = 'input';
                [
                    ['full', t('adm_rest_mode_full')],
                    ['db', t('adm_rest_mode_db')],
                    ['files', t('adm_rest_mode_files')]
                ].forEach(([mv, ml]) => {
                    const o = document.createElement('option');
                    o.value = mv;
                    o.textContent = ml;
                    selRestMode.appendChild(o);
                });
                fgMode.appendChild(lMode);
                fgMode.appendChild(selRestMode);
                rsCard.appendChild(fgMode);

                const pickRow = document.createElement('div');
                pickRow.style.cssText = 'display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:12px';

                const restFileIn = document.createElement('input');
                restFileIn.type = 'file';
                restFileIn.accept = '.m3b,application/octet-stream';
                restFileIn.className = 'hidden';

                const pickFileBtn = document.createElement('button');
                pickFileBtn.type = 'button';
                pickFileBtn.id = 'btn-adm-restore-pick';
                pickFileBtn.className = 'btn btn-secondary btn-sm';
                pickFileBtn.textContent = t('adm_rest_pick_btn');

                const pickedFileLbl = document.createElement('span');
                pickedFileLbl.id = 'adm-restore-picked-name';
                pickedFileLbl.style.cssText = 'font-size:12.5px;color:var(--text-secondary);font-weight:700;word-break:break-all';
                pickedFileLbl.textContent = t('adm_rest_no_file');

                let selectedBackupFile = null;
                pickFileBtn.addEventListener('click', () => restFileIn.click());
                restFileIn.addEventListener('change', () => {
                    const f = restFileIn.files && restFileIn.files[0];
                    if (!f) return;
                    selectedBackupFile = f;
                    pickedFileLbl.textContent = `📦 ${f.name} (${formatBytes(f.size)})`;
                    const fnLow = f.name.toLowerCase();
                    if (fnLow.includes('_db_backup')) selRestMode.value = 'db';
                    else if (fnLow.includes('_files_backup')) selRestMode.value = 'files';
                    else if (fnLow.includes('_full_backup')) selRestMode.value = 'full';
                });

                pickRow.appendChild(restFileIn);
                pickRow.appendChild(pickFileBtn);
                pickRow.appendChild(pickedFileLbl);
                rsCard.appendChild(pickRow);

                const progWrap = document.createElement('div');
                progWrap.className = 'restore-progress-wrap hidden';
                const progText = document.createElement('div');
                progText.style.cssText = 'font-size:12px;font-weight:700;color:var(--text-main)';
                const progTrack = document.createElement('div');
                progTrack.className = 'restore-progress-track';
                const progFill = document.createElement('div');
                progFill.className = 'restore-progress-fill';
                progTrack.appendChild(progFill);
                progWrap.appendChild(progText);
                progWrap.appendChild(progTrack);
                rsCard.appendChild(progWrap);

                const startRestBtn = document.createElement('button');
                startRestBtn.type = 'button';
                startRestBtn.id = 'btn-adm-restore-start';
                startRestBtn.className = 'btn btn-primary btn-block';
                startRestBtn.textContent = t('adm_rest_start_btn');
                startRestBtn.addEventListener('click', async () => {
                    if (!selectedBackupFile) {
                        toast(t('adm_rest_no_file'), true);
                        pickFileBtn.focus();
                        return;
                    }
                    const rMode = selRestMode.value;
                    const confirmDescMap = {
                        db: t('adm_rest_confirm_db'),
                        files: t('adm_rest_confirm_files'),
                        full: t('adm_rest_confirm_full')
                    };
                    const ap = await askApproval({
                        title: t('adm_rest_sec_title'),
                        desc: `${confirmDescMap[rMode] || confirmDescMap.full}\n📦 ${selectedBackupFile.name} (${formatBytes(selectedBackupFile.size)})`,
                        checkboxLabel: t('adm_rest_chk_lbl'),
                        checkboxRequired: true,
                        danger: true,
                        icon: '♻️'
                    });
                    if (!ap.approved) return;

                    startRestBtn.disabled = true;
                    pickFileBtn.disabled = true;
                    progWrap.classList.remove('hidden');
                    progFill.style.width = '2%';
                    progText.textContent = t('adm_rest_uploading_pct').replace('{pct}', formatLocalizedCount(0));

                    const upRes = await uploadBlobInChunks('admin_backup_upload_chunk', selectedBackupFile, pct => {
                        progFill.style.width = `${Math.max(5, Math.round(pct * 0.85))}%`;
                        progText.textContent = t('adm_rest_uploading_pct').replace('{pct}', formatLocalizedCount(pct));
                    });
                    if (!upRes.ok) {
                        startRestBtn.disabled = false;
                        pickFileBtn.disabled = false;
                        progWrap.classList.add('hidden');
                        toast(upRes.message || t('err_generic'), true);
                        return;
                    }

                    progFill.style.width = '92%';
                    progText.textContent = t('adm_rest_applying_wait');
                    const applyRes = await apiCall('admin_backup_restore', {
                        upload_id: upRes.upload_id,
                        restore_mode: rMode
                    });

                    startRestBtn.disabled = false;
                    pickFileBtn.disabled = false;

                    if (!applyRes.ok) {
                        progWrap.classList.add('hidden');
                        toast(applyRes.message || t('err_generic'), true);
                        return;
                    }

                    progFill.style.width = '100%';
                    toast(t('adm_rest_done_toast'));

                    if (applyRes.data && applyRes.data.relogin_required) {
                        setTimeout(() => location.reload(), 600);
                        return;
                    }

                    const bRes = await apiCall('bootstrap');
                    if (bRes.ok && bRes.data && bRes.data.authenticated) {
                        store.user = bRes.data.user;
                        store.chats = bRes.data.chats || [];
                        store.settings = bRes.data.settings || store.settings;
                        store.messages = {};
                        applySiteBrandingAssets(store.settings.site_logo || '', store.settings.site_favicon || '');
                        renderSelfDock();
                        renderChatList();
                        if (store.activeChatId) {
                            renderActiveChatHeader();
                            await renderMessagesViewport(false);
                        }
                    }
                    renderTab('backup');
                });
                rsCard.appendChild(startRestBtn);
                tabContent.appendChild(rsCard);

                // 3. Item 15: Bidirectional Live Database Migration Card (SQLite <-> MariaDB / MySQL)
                if (typeof buildAdminLiveDbMigrationCard === 'function') {
                    const migCard = await buildAdminLiveDbMigrationCard(() => renderTab('backup'));
                    if (migCard) tabContent.appendChild(migCard);
                }

                // 3b. Schema repair: only meaningful when the marker and the real columns disagree.
                if (typeof buildAdminSchemaRepairCard === 'function') {
                    const repCard = await buildAdminSchemaRepairCard(() => renderTab('backup'));
                    if (repCard) tabContent.appendChild(repCard);
                }
            }
            // Re-apply on every tab render: founder-only cards must stay hidden
            // for appointed super-admins even when they switch admin tabs.
            applyFounderOnlyVisibility(tabContent);
        };

        tabs.forEach(([id, label]) => {
            const b = document.createElement('button');
            b.type = 'button';
            b.className = 'adm-nav-btn';
            b.dataset.tab = id;
            b.textContent = label;
            b.addEventListener('click', () => renderTab(id));
            tabsBar.appendChild(b);
        });

        body.appendChild(tabsBar);
        body.appendChild(tabContent);
        renderTab(initialTab);
    }, true);
}

/* ---------------- IN-PLACE VOICE RECORDING CONTROLLER (CROSS-BROWSER & NO TOASTS) ---------------- */
function pickSupportedAudioMime() {
    if (typeof MediaRecorder === 'undefined') return { mime: '', ext: 'webm' };
    const candidates = [
        { mime: 'audio/webm;codecs=opus', ext: 'webm' },
        { mime: 'audio/webm', ext: 'webm' },
        { mime: 'audio/ogg;codecs=opus', ext: 'ogg' },
        { mime: 'audio/ogg', ext: 'ogg' },
        { mime: 'audio/mp4', ext: 'm4a' }
    ];
    for (const c of candidates) {
        if (typeof MediaRecorder.isTypeSupported === 'function' && MediaRecorder.isTypeSupported(c.mime)) {
            return c;
        }
    }
    return { mime: '', ext: 'webm' };
}

function updateVoiceTimerDisplay() {
    const el = document.getElementById('voice-rec-timer');
    if (!el) return;
    const elapsed = Math.max(0, Math.floor((Date.now() - store.recStartTime) / 1000));
    const mm = String(Math.floor(elapsed / 60)).padStart(2, '0');
    const ss = String(elapsed % 60).padStart(2, '0');
    el.textContent = `${mm}:${ss}`;
}

function showComposerRecordingUI(recording) {
    const recBar = document.getElementById('composer-recording-bar');
    const micBtn = document.getElementById('btn-record-voice');
    // Always display recording bar cleanly ABOVE #composer-active-bar without hiding the text input!
    if (recBar) recBar.classList.toggle('hidden', !recording);
    if (micBtn) micBtn.classList.toggle('recording-active', Boolean(recording));
}

async function startVoiceRecording() {
    if (store.mediaRecorder && store.mediaRecorder.state === 'recording') {
        stopAndSendVoiceRecording();
        return;
    }
    if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
        toast(t('mic_denied'), true);
        return;
    }
    try {
        const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
        store.audioChunks = [];
        store.recCancelled = false;
        const chosen = pickSupportedAudioMime();
        const options = chosen.mime ? { mimeType: chosen.mime } : {};
        store.mediaRecorder = new MediaRecorder(stream, options);

        store.mediaRecorder.ondataavailable = e => {
            if (e.data && e.data.size > 0) store.audioChunks.push(e.data);
        };

        store.mediaRecorder.onstop = () => {
            clearInterval(store.recTimerInterval);
            store.recTimerInterval = null;
            stream.getTracks().forEach(tr => tr.stop());
            showComposerRecordingUI(false);

            if (store.recCancelled || store.audioChunks.length === 0) {
                store.audioChunks = [];
                return;
            }
            const actualMime = store.mediaRecorder.mimeType || chosen.mime || 'audio/webm';
            let ext = chosen.ext || 'webm';
            if (actualMime.includes('mp4') || actualMime.includes('aac') || actualMime.includes('m4a')) ext = 'm4a';
            else if (actualMime.includes('ogg')) ext = 'ogg';
            else if (actualMime.includes('wav')) ext = 'wav';

            const recSec = Math.max(1, Math.round((Date.now() - (store.recStartTime || Date.now())) / 1000));
            const blob = new Blob(store.audioChunks, { type: actualMime });
            const file = new File([blob], `voice_${recSec}s_${Date.now()}.${ext}`, { type: actualMime });
            openFileUploadWithCaptionModal(file, 'voice');
        };

        store.recStartTime = Date.now();
        updateVoiceTimerDisplay();
        store.recTimerInterval = setInterval(updateVoiceTimerDisplay, 500);
        showComposerRecordingUI(true);
        store.mediaRecorder.start();
    } catch (err) {
        toast(t('mic_denied'), true);
    }
}

function stopAndSendVoiceRecording() {
    if (store.mediaRecorder && store.mediaRecorder.state === 'recording') {
        store.recCancelled = false;
        store.mediaRecorder.stop();
    }
}

function cancelVoiceRecording() {
    if (store.mediaRecorder && store.mediaRecorder.state === 'recording') {
        store.recCancelled = true;
        store.mediaRecorder.stop();
        toast(t('voice_cancelled'));
    } else {
        showComposerRecordingUI(false);
    }
}

function isAppSoundsMuted() {
    return Boolean(store.user && Number(store.user.app_sounds_muted) === 1);
}

function isChatSoundsEnabled() {
    if (isAppSoundsMuted()) return false;
    return !store.user || Number(store.user.chat_sounds_enabled ?? 1) !== 0;
}

function playChatActionSound(kind = 'send') {
    if (!isChatSoundsEnabled()) return;
    try {
        const AudioCtx = window.AudioContext || window.webkitAudioContext;
        if (!AudioCtx) return;
        const ctx = new AudioCtx();
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        if (kind === 'receive') {
            osc.type = 'sine';
            osc.frequency.setValueAtTime(520, ctx.currentTime);
            osc.frequency.exponentialRampToValueAtTime(740, ctx.currentTime + 0.085);
            gain.gain.setValueAtTime(0.048, ctx.currentTime);
            gain.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + 0.13);
            osc.connect(gain);
            gain.connect(ctx.destination);
            osc.start();
            osc.stop(ctx.currentTime + 0.14);
        } else {
            osc.type = 'triangle';
            osc.frequency.setValueAtTime(410, ctx.currentTime);
            osc.frequency.exponentialRampToValueAtTime(640, ctx.currentTime + 0.065);
            gain.gain.setValueAtTime(0.042, ctx.currentTime);
            gain.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + 0.1);
            osc.connect(gain);
            gain.connect(ctx.destination);
            osc.start();
            osc.stop(ctx.currentTime + 0.11);
        }
        setTimeout(() => { try { ctx.close(); } catch (e) {} }, 220);
    } catch (e) {}
}

function urlBase64ToUint8Array(base64String) {
    const padding = '='.repeat((4 - (base64String.length % 4)) % 4);
    const base64 = (base64String + padding).replace(/-/g, '+').replace(/_/g, '/');
    const rawData = window.atob(base64);
    const out = new Uint8Array(rawData.length);
    for (let i = 0; i < rawData.length; ++i) out[i] = rawData.charCodeAt(i);
    return out;
}

async function syncBackgroundServiceWorkerAndPush(forceEnable = null) {
    if (!('serviceWorker' in navigator) || !store.user) return;
    const enabled = forceEnable !== null ? Boolean(forceEnable) : (Number(store.user.bg_push_enabled ?? 1) !== 0);
    try {
        const reg = await navigator.serviceWorker.register('./?a=sw', { scope: './' });
        if (!store._swMsgListenerBound) {
            store._swMsgListenerBound = true;
            navigator.serviceWorker.addEventListener('message', ev => {
                if (ev.data && ev.data.type === 'M3_OPEN_FROM_NOTIF' && ev.data.chat_id) {
                    selectChat(Number(ev.data.chat_id));
                }
            });
        }
        const maxKnownId = typeof getLastKnownMessageId === 'function' ? Number(getLastKnownMessageId() || 0) : 0;
        if (reg.active && maxKnownId > 0) {
            try { reg.active.postMessage({ type: 'M3_SYNC_SEEN_ID', id: maxKnownId }); } catch (e) {}
        }
        if (!enabled) {
            if (reg.pushManager) {
                const sub = await reg.pushManager.getSubscription();
                if (sub) {
                    const ep = sub.endpoint || '';
                    try { await sub.unsubscribe(); } catch (e) {}
                    await apiCall('push_unsubscribe', { endpoint: ep });
                }
            }
            return;
        }
        if ('periodicSync' in reg) {
            try { await reg.periodicSync.register('m3-bg-periodic', { minInterval: 60000 }); } catch (e) {}
        }
        if (reg.pushManager && 'Notification' in window && Notification.permission === 'granted') {
            const vapidPub = String((store.settings && store.settings.vapid_public_key) || '');
            if (vapidPub.length >= 40) {
                let sub = await reg.pushManager.getSubscription();
                if (!sub) {
                    sub = await reg.pushManager.subscribe({
                        userVisibleOnly: true,
                        applicationServerKey: urlBase64ToUint8Array(vapidPub)
                    });
                }
                if (sub && sub.endpoint && store._lastSyncedPushEndpoint !== sub.endpoint) {
                    const sr = await apiCall('push_subscribe', { endpoint: sub.endpoint });
                    if (sr.ok) store._lastSyncedPushEndpoint = sub.endpoint;
                }
            }
        }
    } catch (err) {}
}

/* ---------------- LONG-POLLING LOOP FOR REAL-TIME MESSAGES & SEEN TICKS ---------------- */
async function playNotificationChime() {
    if (isAppSoundsMuted()) return;
    try {
        const AudioCtx = window.AudioContext || window.webkitAudioContext;
        if (!AudioCtx) return;
        const ctx = new AudioCtx();
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.type = 'sine';
        osc.frequency.setValueAtTime(587.33, ctx.currentTime);
        osc.frequency.setValueAtTime(880, ctx.currentTime + 0.08);
        gain.gain.setValueAtTime(0.06, ctx.currentTime);
        gain.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + 0.25);
        osc.connect(gain);
        gain.connect(ctx.destination);
        osc.start();
        osc.stop(ctx.currentTime + 0.26);
        setTimeout(() => { try { ctx.close(); } catch (e) {} }, 350);
    } catch (e) {}
}

async function showDeviceNotification(opts = {}) {
    if (!('Notification' in window) || Notification.permission !== 'granted') return null;
    const title = String(opts.title || formatSiteName());
    const silent = Boolean(opts.silent);
    const chatId = Number(opts.chatId || 0);
    const callId = Number(opts.callId || 0);
    const tag = String(opts.tag || (chatId > 0 ? ('m3-msg-' + chatId) : 'm3-notif'));
    const notifOpts = {
        body: String(opts.body || ''),
        icon: './?a=icon&s=192',
        badge: './?a=icon&s=96',
        tag,
        renotify: true,
        silent,
        requireInteraction: Boolean(opts.requireInteraction),
        vibrate: silent ? [] : (opts.vibrate || [180, 90, 180]),
        data: { chat_id: chatId, call_id: callId }
    };
    if (opts.seenMsgId && Number(opts.seenMsgId) > 0 && 'serviceWorker' in navigator && navigator.serviceWorker.controller) {
        try { navigator.serviceWorker.controller.postMessage({ type: 'M3_SYNC_SEEN_ID', id: Number(opts.seenMsgId) }); } catch (e) {}
    }
    if ('serviceWorker' in navigator) {
        try {
            const reg = await navigator.serviceWorker.getRegistration('./');
            if (reg && typeof reg.showNotification === 'function') {
                await reg.showNotification(title, notifOpts);
                return { via: 'sw' };
            }
        } catch (swErr) {}
    }
    try {
        const n = new Notification(title, {
            body: notifOpts.body,
            icon: '?a=icon&s=192',
            silent: notifOpts.silent,
            requireInteraction: notifOpts.requireInteraction,
            tag: notifOpts.tag
        });
        n.onclick = () => {
            try { window.focus(); } catch (e) {}
            if (chatId > 0) selectChat(chatId);
            n.close();
        };
        return n;
    } catch (err) {
        return null;
    }
}

function handleIncomingChatNotifications(prevChats, nextChats) {
    if (!store.user || !Array.isArray(prevChats) || !Array.isArray(nextChats)) return;
    const prevMap = new Map();
    prevChats.forEach(c => {
        prevMap.set(c.id, c.last_message ? Number(c.last_message.id || 0) : 0);
    });

    const soundsMuted = isAppSoundsMuted();
    // A global mute means nothing at all: no chime and no pop-up. Messages
    // still arrive; only the notification side is switched off.
    if (soundsMuted) return;
    const isSilent = Boolean(store.user.notif_silent === 1 || soundsMuted);
    const browserNotifOn = store.user.browser_notif !== 0;
    const showPreview = store.user.notif_preview !== 0 && !store.isSessionLocked;
    let playedSound = false;
    let playedInChatReceive = false;

    nextChats.forEach(chat => {
        if (!chat.last_message) return;
        const newId = Number(chat.last_message.id || 0);
        const oldId = prevMap.has(chat.id) ? prevMap.get(chat.id) : newId;
        if (newId <= oldId) return;
        if (Number(chat.last_message.user_id) === Number(store.user.id)) return;
        if (chat.last_message.kind === 'call_log') return;

        const isCurrentVisibleChat = !document.hidden && document.hasFocus && document.hasFocus() && Number(chat.id) === Number(store.activeChatId);
        if (isCurrentVisibleChat) {
            if (!soundsMuted && !playedInChatReceive && Number(chat.muted) !== 1 && isChatSoundsEnabled()) {
                playedInChatReceive = true;
                playChatActionSound('receive');
            }
            return;
        }
        // Respect per-user chat/group/channel mute!
        if (Number(chat.muted) === 1) return;

        if (!soundsMuted && !isSilent && !playedSound) {
            playedSound = true;
            playNotificationChime();
        }

        if (browserNotifOn && 'Notification' in window && Notification.permission === 'granted') {
            const nTitle = showPreview ? formatChatTitle(chat) : formatSiteName();
            const nBody = !showPreview
                ? t('notif_masked_body')
                : (chat.type === 'secret'
                    ? t('e2ee_encrypted_preview')
                    : (formatDynamicServerText(chat.last_message.body) || t('media_attachment')));
            showDeviceNotification({
                title: nTitle,
                body: nBody,
                tag: 'm3-msg-' + chat.id,
                chatId: chat.id,
                seenMsgId: newId,
                silent: isSilent
            });
        }
    });
}

function applyActivatedBurnsToStore(chatId, burns) {
    if (!chatId || !Array.isArray(burns) || burns.length === 0) return;
    const list = store.messages[chatId];
    if (!Array.isArray(list)) return;
    const burnMap = {};
    burns.forEach(b => { if (b && b.id) burnMap[Number(b.id)] = b; });
    let changed = false;
    list.forEach(m => {
        const hit = burnMap[Number(m.id)];
        if (hit) {
            m.first_read_at = hit.first_read_at;
            m.expires_at = hit.expires_at;
            changed = true;
        }
    });
    if (changed && store.activeChatId === chatId) {
        updateVisibleTtlCountdowns();
    }
}

function updateVisibleTtlCountdowns() {
    if (!store.activeChatId || !store.messages[store.activeChatId]) return;
    const nowSec = Math.floor(Date.now() / 1000);
    const byId = {};
    store.messages[store.activeChatId].forEach(m => { byId[String(m.id)] = m; });
    document.querySelectorAll('#messages-viewport .ttl-pill[data-msg-id]').forEach(el => {
        const m = byId[el.dataset.msgId];
        if (!m) return;
        if (m.expires_at && Number(m.expires_at) > 0) {
            const rem = Math.max(0, Number(m.expires_at) - nowSec);
            el.textContent = `⏱️ ${formatCoarseRemainingTtl(rem)}`;
        } else if (m.burn_after && Number(m.burn_after) > 0) {
            el.textContent = `🔥 ${formatCoarseRemainingTtl(m.burn_after)} (${t('self_destruct_wait_view')})`;
        }
    });
}

function sweepClientExpiredMessages() {
    const nowSec = Math.floor(Date.now() / 1000);
    let anyExpiredActive = false;

    Object.keys(store.messages || {}).forEach(cidKey => {
        const arr = store.messages[cidKey];
        if (!Array.isArray(arr) || !arr.length) return;
        const expiredMsgs = arr.filter(m => m.expires_at && Number(m.expires_at) > 0 && Number(m.expires_at) <= nowSec);
        if (!expiredMsgs.length) return;

        expiredMsgs.forEach(em => {
            store.selectedMsgIds.delete(Number(em.id));
            delete store.decryptedTextCache[em.id];
            const fid = em.file && em.file.id ? Number(em.file.id) : 0;
            SharedMediaPool.evictByIds(em.id, fid);
            if (UniversalPlayer.isOpen && (
                (UniversalPlayer.sourceMsgId && Number(UniversalPlayer.sourceMsgId) === Number(em.id)) ||
                (fid > 0 && UniversalPlayer.sourceFileId && Number(UniversalPlayer.sourceFileId) === fid)
            )) {
                UniversalPlayer.forceBurnClose();
                toast(t('self_destruct_media_closed_toast'));
            }
            if (fid > 0 && store.txtCache) {
                delete store.txtCache[fid];
            }
            if (fid > 0 && store.decryptedBlobUrls && store.decryptedBlobUrls[fid]) {
                try { URL.revokeObjectURL(store.decryptedBlobUrls[fid]); } catch (e) {}
                delete store.decryptedBlobUrls[fid];
            }
        });

        store.messages[cidKey] = arr.filter(m => !(m.expires_at && Number(m.expires_at) > 0 && Number(m.expires_at) <= nowSec));
        if (Number(cidKey) === Number(store.activeChatId)) {
            anyExpiredActive = true;
        }
    });

    if (anyExpiredActive) {
        if (store.selectedMsgIds.size > 0) syncMultiSelectUI();
        renderMessagesViewport(false);
        fetch('?a=cron', { credentials: 'same-origin' }).catch(() => {});
    } else if (store.activeChatId && store.messages[store.activeChatId]) {
        updateVisibleTtlCountdowns();
    }
}

function startLiveTtlCountdownTicker() {
    if (store.ttlTickerId) return;
    store.ttlTickerId = setInterval(() => {
        if (!store.user) return;
        sweepClientExpiredMessages();
    }, 1000);
}

/* Maintenance mode refuses the actions one at a time, so on its own it says
   nothing until somebody tries something. This puts the reason on the screen
   instead: on the login screen before anybody types a password, and over the
   messenger for an account that was signed in when maintenance began. */
function showMaintenanceNotice() {
    let el = document.getElementById('maint-notice');
    if (!el) {
        el = document.createElement('div');
        el.id = 'maint-notice';
        el.dataset.i18n = 'maint_notice';
        el.style.cssText = 'position:fixed;left:0;right:0;top:0;z-index:2147483646;'
            + 'padding:10px 14px;text-align:center;font-size:12.5px;font-weight:700;'
            + 'line-height:1.6;color:#7c2d12;background:#fef3c7;border-bottom:1px solid #fcd34d';
        el.textContent = t('maint_notice');
        document.body.appendChild(el);
    }
    el.classList.remove('hidden');
}

function hideMaintenanceNotice() {
    const el = document.getElementById('maint-notice');
    if (el) el.classList.add('hidden');
}

async function startSyncPollLoop() {
    startLiveTtlCountdownTicker();
    if (store.polling) return;
    store.polling = true;
    while (store.user) {
        try {
            if (store.isSessionLocked) {
                await new Promise(r => setTimeout(r, 1200));
                continue;
            }
            sweepClientExpiredMessages();
            const userActiveFlag = (Date.now() - Number(store.lastUserInteractionAt || 0)) <= 65000 ? '1' : '0';
            const pollAbort = new AbortController();
            window._m3WakeSyncPoll = () => { try { pollAbort.abort(); } catch (e) {} };
            const url = `?a=poll&tick=${encodeURIComponent(store.tick)}&typing_tick=${encodeURIComponent(store.typingTick || '0')}&active_chat_id=${store.activeChatId || 0}&udig=${encodeURIComponent(store.udig || '')}&chat_id=${store.activeChatId || 0}&last_msg_id=${getLastKnownMessageId()}${userActiveFlag === '1' ? '&active=1' : ''}`;
            let res;
            try {
                res = await fetch(url, { credentials: 'same-origin', signal: pollAbort.signal, cache: 'no-store' });
            } catch (fetchErr) {
                if (fetchErr && fetchErr.name === 'AbortError') continue;
                throw fetchErr;
            }
            const json = await res.json();
            if (json && (json.error === 'messenger_wiped' || json.wiped === true)) {
                await triggerClientZeroTraceBlankOut();
                break;
            }
            if (json && !json.ok && json.error === 'session_locked') {
                if (typeof showMessengerLockScreen === 'function') showMessengerLockScreen(store.user);
                await new Promise(r => setTimeout(r, 1200));
                continue;
            }
            if (json && !json.ok && json.error === 'maintenance_mode') {
                showMaintenanceNotice();
                // Back off instead of retrying every second: nothing can change
                // within a second, and the longer wait lets the messenger pick
                // itself back up the moment maintenance ends.
                await new Promise(r => setTimeout(r, 30000));
                continue;
            }
            if (json && json.ok && json.data) {
                hideMaintenanceNotice();
                if (json.data.tick) store.tick = String(json.data.tick);
                if (json.data.typing_tick !== undefined) {
                    store.typingTick = String(json.data.typing_tick || '0');
                }
                if (Number(json.data.typing_chat_id || 0) > 0 && Array.isArray(json.data.typing_users)) {
                    TypingIndicatorManager.applyServerTypingUsers(Number(json.data.typing_chat_id), json.data.typing_users, json.data.typing_tick);
                }
                if (json.data.changed) {
                    const prevChatsSnapshot = (store.chats || []).slice();
                    const cRes = await apiCall('chats_list');
                    if (!cRes.ok && cRes.error === 'unauthorized') {
                        store.user = null;
                        location.reload();
                        break;
                    }
                    if (cRes.ok) {
                        if (typeof cRes.data.udig === 'string') {
                            store.udig = cRes.data.udig;
                        }
                        if (Array.isArray(cRes.data.blocked_ids)) {
                            store.blockedIds = cRes.data.blocked_ids;
                        }
                        if (cRes.data.user && store.user) {
                            const prevLang = store.lang;
                            const prevTheme = store.theme;
                            const prevCal = store.cal;
                            const prevRole = store.user.role;
                            store.user = cRes.data.user;
                            if (store.user.cal && store.user.cal !== prevCal) {
                                store.cal = store.user.cal;
                                localStorage.setItem('pm_cal', store.cal);
                            }
                            if ((store.user.lang && store.user.lang !== prevLang) || (store.user.theme && store.user.theme !== prevTheme)) {
                                if (hasLangExplicitOverride()) {
                                    // A hand-picked language always wins over an account sync.
                                    applyLangAndTheme(prevLang, store.user.theme || store.theme);
                                } else {
                                    applyLangAndTheme(store.user.lang || store.lang, store.user.theme || store.theme);
                                }
                            }
                            if (typeof DraftSyncManager !== 'undefined' && DraftSyncManager.initFromBootUser) {
                                DraftSyncManager.initFromBootUser(store.user);
                            }
                            const admBtnSync = document.getElementById('btn-admin-panel');
                            if (admBtnSync && store.user.role !== prevRole) {
                                admBtnSync.classList.toggle('hidden', store.user.role !== 'superadmin');
                            }
                            renderSelfDock();
                        }
                        if (cRes.data.global_idle) {
                            store.settings.idle_mode = cRes.data.global_idle.mode;
                            store.settings.idle_start = cRes.data.global_idle.start;
                            store.settings.idle_end = cRes.data.global_idle.end;
                            store.settings.idle_tz_offset = cRes.data.global_idle.tz_offset;
                        }
                        if (cRes.data.identity_limits) {
                            Object.assign(store.settings, cRes.data.identity_limits);
                            applyAuthIdentityInputLimits();
                        }
                        if (cRes.data.content_protections) {
                            Object.assign(store.settings, cRes.data.content_protections);
                        }
                        if (cRes.data.app_timezone) {
                            store.settings.app_timezone = cRes.data.app_timezone;
                        }
                        if (typeof cRes.data.force_hide_last_seen !== 'undefined') {
                            store.settings.force_hide_last_seen = Number(cRes.data.force_hide_last_seen) ? 1 : 0;
                        }
                        handleIncomingChatNotifications(prevChatsSnapshot, cRes.data.chats || []);
                        store.chats = cRes.data.chats;
                        if (typeof LiveCallManager !== 'undefined' && LiveCallManager.onChatsSynced) {
                            LiveCallManager.onChatsSynced(store.chats);
                        }
                        if (store.ghostChat) {
                            if (store.chats.some(c => c.id === store.ghostChat.id)) {
                                store.ghostChat = null;
                            } else if (store.activeChatId === store.ghostChat.id) {
                                const gSync = await apiCall('admin_ghost_open', { chat_id: store.ghostChat.id });
                                if (gSync.ok && gSync.data && gSync.data.chat) {
                                    store.ghostChat = gSync.data.chat;
                                } else {
                                    store.ghostChat = null;
                                }
                            }
                        }
                        // If the active chat was deleted or left in another session, smoothly close active view
                        if (store.activeChatId && !store.ghostChat && !store.chats.some(c => Number(c.id) === Number(store.activeChatId))) {
                            store.activeChatId = null;
                            const acv = document.getElementById('active-chat-view');
                            const ecs = document.getElementById('empty-chat-state');
                            const sh = document.getElementById('messenger-shell');
                            if (acv) acv.classList.add('hidden');
                            if (ecs) ecs.classList.remove('hidden');
                            if (sh) sh.classList.remove('chat-open');
                        }
                        renderGlobalIdleBanner();
                        renderChatList();
                        if (store.activeChatId) renderActiveChatHeader();
                        syncTtlControlUI();
                    }
                    const cidAtReq = store.activeChatId;
                    const searchBarEl = document.getElementById('in-chat-search-bar');
                    const searchInEl = document.getElementById('in-chat-search-input');
                    const isSearchingChat = searchBarEl && !searchBarEl.classList.contains('hidden') && searchInEl && searchInEl.value.trim() !== '';
                    const isBusyPagingOrSending = Boolean(
                        Number(store._sendingMessageCount || 0) > 0 ||
                        (cidAtReq && (store.loadingOlderByChat[cidAtReq] || store.loadingNewerByChat[cidAtReq]))
                    );
                    if (cidAtReq && !isSearchingChat && !isBusyPagingOrSending) {
                        const prevMsgsAtStart = (store.messages[cidAtReq] || []).filter(m => !m._optimistic && m.id > 0);
                        const prevMaxKnownId = prevMsgsAtStart.length > 0 ? Math.max(...prevMsgsAtStart.map(m => Number(m.id || 0))) : 0;
                        const mRes = await apiCall('messages_list', { chat_id: cidAtReq, limit: 80 });
                        if (mRes.ok && store.activeChatId === cidAtReq && !store.loadingOlderByChat[cidAtReq] && !store.loadingNewerByChat[cidAtReq] && !MessageDragSelector.active) {
                            const prevMsgsInChat = (store.messages[cidAtReq] || []).filter(m => !m._optimistic && m.id > 0);
                            const optimistic = (store.messages[cidAtReq] || []).filter(m => m._optimistic);
                            const serverMsgs = mRes.data.messages || [];
                            const myUid = Number((store.user && store.user.id) || 0);
                            const newlyArrivedIncoming = prevMaxKnownId > 0
                                ? serverMsgs.filter(m => Number(m.id) > prevMaxKnownId && Number(m.user_id) !== myUid && m.kind !== 'system')
                                : [];
                            const actChat = getActiveChat();
                            if (actChat) actChat.peer_last_read_id = mRes.data.peer_last_read_id || 0;
                            const vpSyncCheck = document.getElementById('messages-viewport');
                            const syncMaxCheck = vpSyncCheck ? Math.max(0, vpSyncCheck.scrollHeight - vpSyncCheck.clientHeight) : 0;
                            // Item #8 & #9: If user is already at the bottom (within 95px), keep them pinned to newest message without marking it unread!
                            const userAlreadyAtBottom = !vpSyncCheck
                                || (!store.hasMoreAfterByChat[cidAtReq] && (syncMaxCheck <= 28 || (syncMaxCheck - vpSyncCheck.scrollTop) <= 95))
                                || Boolean(store._forcePinBottomUntil && Date.now() < store._forcePinBottomUntil);

                            if (newlyArrivedIncoming.length > 0 && !(actChat && actChat.is_ghost)) {
                                if (userAlreadyAtBottom) {
                                    store.inChatUnreadByChat[cidAtReq] = 0;
                                    store.firstUnreadByChat[cidAtReq] = 0;
                                } else {
                                    if (!store.firstUnreadByChat[cidAtReq]) {
                                        store.firstUnreadByChat[cidAtReq] = Number(newlyArrivedIncoming[0].id);
                                    }
                                    store.inChatUnreadByChat[cidAtReq] = Number(store.inChatUnreadByChat[cidAtReq] || 0) + newlyArrivedIncoming.length;
                                }
                            }

                            if (store.hasMoreAfterByChat[cidAtReq]) {
                                // User is currently reading an older history slice — keep their window intact and update ↓ badge
                                renderActiveChatHeader();
                                updateScrollBottomFab(false);
                            } else {
                                const firstSrvId = serverMsgs.length > 0 ? Number(serverMsgs[0].id) : 0;
                                const olderLoadedPrefix = firstSrvId > 0
                                    ? prevMsgsInChat.filter(m => Number(m.id) < firstSrvId)
                                    : [];
                                let merged = olderLoadedPrefix.concat(serverMsgs);
                                if (merged.length > MSG_DOM_WINDOW_CAP) {
                                    merged = merged.slice(merged.length - MSG_DOM_WINDOW_CAP);
                                    store.hasMoreBeforeByChat[cidAtReq] = true;
                                } else if (olderLoadedPrefix.length === 0) {
                                    store.hasMoreBeforeByChat[cidAtReq] = Boolean(mRes.data.has_more_before);
                                }
                                const calcMsgWinSig = (arr, peerRead) => String(peerRead || 0) + '|' + arr.map(m => [
                                    m.id || m.tempId || '',
                                    m.edited_at || '',
                                    m.edited_silent || '',
                                    Array.isArray(m.edit_history) ? m.edit_history.length : 0,
                                    m.deleted_at || '',
                                    m.pinned ? 1 : 0,
                                    m.tick_status || '',
                                    m.expires_at || '',
                                    m.body ? (m.body.length + ':' + hashStringIdx(m.body)) : 0,
                                    m.cipher ? m.cipher.slice(0, 20) : '',
                                    JSON.stringify(m.reactions || [])
                                ].join(':')).join(',');
                                const prevPeerRead = actChat ? (actChat._lastRenderedPeerRead || 0) : 0;
                                const nextPeerRead = Number(mRes.data.peer_last_read_id || 0);
                                const prevSig = calcMsgWinSig(prevMsgsInChat.concat(optimistic), prevPeerRead);
                                const nextList = merged.concat(optimistic);
                                const nextSig = calcMsgWinSig(nextList, nextPeerRead);
                                store.messages[cidAtReq] = nextList;
                                if (actChat) actChat._lastRenderedPeerRead = nextPeerRead;
                                if (prevSig !== nextSig) {
                                    const inPlaceMediaSnap = collectActiveInlineMediaStatesInViewport().map(st => ({
                                        kind: st.kind,
                                        msgId: st.msgId,
                                        fileId: st.fileId,
                                        currentTime: st.currentTime,
                                        playbackRate: st.playbackRate,
                                        unmuted: st.unmuted,
                                        wasPlaying: st.wasPlaying
                                    }));
                                    await renderMessagesViewport(userAlreadyAtBottom);
                                    inPlaceMediaSnap.forEach(sn => applyInlineMediaStateSnapshot(sn));
                                }
                                renderActiveChatHeader();
                                updateScrollBottomFab(false);
                                if (serverMsgs.length > 0 && !(Number(store.inChatUnreadByChat[cidAtReq] || 0) > 0)) {
                                    const maxId = serverMsgs[serverMsgs.length - 1].id;
                                    const mrPoll = await apiCall('message_read', { chat_id: cidAtReq, message_id: maxId });
                                    if (mrPoll && mrPoll.ok && mrPoll.data && Array.isArray(mrPoll.data.activated_burns) && mrPoll.data.activated_burns.length > 0) {
                                        applyActivatedBurnsToStore(cidAtReq, mrPoll.data.activated_burns);
                                    }
                                }
                            }
                        }
                    }
                }
            }
        } catch (e) {
            await new Promise(r => setTimeout(r, 2500));
        }
        await new Promise(r => setTimeout(r, 700));
    }
    store.polling = false;
}

function getLastKnownMessageId() {
    if (!store.activeChatId || !store.messages[store.activeChatId]) return 0;
    const list = store.messages[store.activeChatId];
    return list.length > 0 ? list[list.length - 1].id : 0;
}

/* ---------------- BOOTSTRAP & EVENT WIRING ---------------- */
function wireInstallerEvents() {
    startPasswordFieldObserver();
    const instForm = document.getElementById('installer-form');
    if (instForm) {
        applyLangAndTheme(store.lang, store.theme);
    }

    const drvSel = document.getElementById('inst-db-driver');
    const mysqlBox = document.getElementById('inst-mysql-fields');
    if (drvSel && mysqlBox) {
        drvSel.addEventListener('change', () => {
            mysqlBox.classList.toggle('hidden', drvSel.value !== 'mysql');
        });
    }

    const passInput = document.getElementById('inst-admin-pass');
    const passConfirmInput = document.getElementById('inst-admin-pass-confirm');
    const matchHint = document.getElementById('inst-pass-match-hint');

    const checkPasswordMatch = () => {
        if (!passInput || !passConfirmInput || !matchHint) return true;
        const p1 = passInput.value;
        const p2 = passConfirmInput.value;
        matchHint.classList.remove('hidden');
        if (!p1 && !p2) {
            matchHint.className = 'pw-match-hint';
            matchHint.textContent = t('pw_policy_hint');
            return false;
        }
        renderPasswordStrengthGuideNode(matchHint, p1, p2);
        const chk = validateStrongPasswordClient(p1);
        return chk.valid && p1 === p2;
    };

    const instLangBtn = document.getElementById('inst-lang-btn');
    const instLangSel = document.getElementById('inst-lang-select');
    if (instLangBtn) {
        instLangBtn.addEventListener('click', () => {
            applyLangAndTheme(store.lang === 'fa' ? 'en' : 'fa', store.theme, true);
            checkPasswordMatch();
            toast(t('lang_switched_toast'));
        });
    }
    if (instLangSel) {
        instLangSel.addEventListener('change', () => {
            applyLangAndTheme(instLangSel.value, store.theme);
            checkPasswordMatch();
        });
    }

    if (passInput && passConfirmInput) {
        passInput.addEventListener('input', checkPasswordMatch);
        passConfirmInput.addEventListener('input', checkPasswordMatch);
    }

    const subBtn = document.getElementById('inst-submit-btn');
    const resBox = document.getElementById('inst-result');

    if (instForm) {
        instForm.addEventListener('submit', async e => {
            e.preventDefault();
            const p1 = passInput ? passInput.value : '';
            const p2 = passConfirmInput ? passConfirmInput.value : '';
            const pwChk = validateStrongPasswordClient(p1);
            if (!pwChk.valid) {
                checkPasswordMatch();
                toast(pwChk.message, true);
                if (passInput) passInput.focus();
                return;
            }
            if (p1 !== p2) {
                checkPasswordMatch();
                toast(t('inst_pass_mismatch'), true);
                if (passConfirmInput) passConfirmInput.focus();
                return;
            }

            const fd = new FormData(instForm);
            const payload = {};
            fd.forEach((v, k) => { payload[k] = v; });

            const errBox = document.getElementById('inst-error-box');
            if (errBox) {
                errBox.classList.add('hidden');
                errBox.textContent = '';
                errBox._lastErr = null;
            }
            if (subBtn) {
                subBtn.disabled = true;
                subBtn.textContent = t('inst_installing_btn');
            }

            try {
                const res = await fetch('?a=install', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify(payload),
                    credentials: 'same-origin'
                });
                const json = await res.json();
                if (json && json.ok) {
                    const recCode = (json.data && json.data.recovery_code) ? json.data.recovery_code : '';
                    instForm.classList.add('hidden');
                    if (resBox) {
                        resBox.classList.remove('hidden');
                        resBox.innerHTML = '';

                        const okTitle = document.createElement('div');
                        okTitle.style.cssText = 'font-weight:800;font-size:15px;color:var(--accent);margin-bottom:8px';
                        okTitle.textContent = t('inst_done_title');
                        resBox.appendChild(okTitle);

                        const recNode = buildRecoveryCodeDescNode(t('inst_done_desc'), recCode);
                        recNode.style.marginBottom = '12px';
                        resBox.appendChild(recNode);

                        const enterBtn = document.createElement('button');
                        enterBtn.type = 'button';
                        enterBtn.className = 'btn btn-primary btn-block';
                        enterBtn.textContent = t('inst_copy_enter_btn');
                        enterBtn.addEventListener('click', async () => {
                            await copyTextToClipboard(recCode);
                            window.location.href = window.location.pathname;
                        });
                        resBox.appendChild(enterBtn);
                    } else {
                        window.location.href = window.location.pathname;
                    }
                } else {
                    if (subBtn) {
                        subBtn.disabled = false;
                        subBtn.textContent = t('inst_submit_btn');
                    }
                    const friendlyMsg = (json && json.error)
                        ? localizeApiError(json.error, json.message, json.details)
                        : t('inst_fail_err');
                    if (errBox) {
                        errBox._lastErr = json ? { code: json.error, message: json.message, details: json.details } : null;
                        errBox.textContent = '⚠️ ' + friendlyMsg;
                        errBox.classList.remove('hidden');
                    }
                    toast(friendlyMsg, true);
                }
            } catch (err) {
                if (subBtn) {
                    subBtn.disabled = false;
                    subBtn.textContent = t('inst_submit_btn');
                }
                toast(t('inst_net_err'), true);
            }
        });
    }
}

function normalizeCaptchaDigits(str) {
    return String(str || '')
        .replace(/[۰-۹]/g, d => String(d.charCodeAt(0) - 0x06F0))
        .replace(/[٠-٩]/g, d => String(d.charCodeAt(0) - 0x0660))
        .replace(/[^0-9]/g, '');
}

const AuthShield = {
    challenge: null,
    jsToken: '',
    hpFieldName: 'm3_hp_website',
    captchaEnabled: true,
    honeypotEnabled: true,
    applyFromData(dataObj) {
        const s = (dataObj && dataObj.settings) ? dataObj.settings : (store.settings || {});
        if (s.fw_hp_field_name) this.hpFieldName = String(s.fw_hp_field_name);
        if (dataObj && dataObj.fw_js_token) this.jsToken = String(dataObj.fw_js_token);
        else if (s.fw_js_token) this.jsToken = String(s.fw_js_token);
        this.captchaEnabled = Number(s.fw_captcha_enabled ?? 1) !== 0;
        this.honeypotEnabled = Number(s.fw_honeypot_enabled ?? 1) !== 0;
        const ch = (dataObj && dataObj.captcha_challenge) ? dataObj.captcha_challenge : s.captcha_challenge;
        if (ch && ch.token) {
            this.challenge = ch;
        }
        this.syncDom();
    },
    syncDom(markInvalidKind = '') {
        document.querySelectorAll('.m3-hp-input').forEach(inp => {
            inp.setAttribute('name', this.hpFieldName || 'm3_hp_website');
            inp.value = '';
        });
        document.querySelectorAll('.m3-wpa-js-field').forEach(inp => {
            inp.value = this.jsToken || '';
        });
        document.querySelectorAll('[data-captcha-wrap]').forEach(wrap => {
            const formKind = wrap.getAttribute('data-captcha-wrap');
            wrap.classList.toggle('hidden', !this.captchaEnabled);
            const lblEl = wrap.querySelector('.m3-captcha-label');
            if (lblEl) lblEl.textContent = t('captcha_box_lbl');
            const hintEl = wrap.querySelector(`[data-captcha-hint="${formKind}"]`);
            const qEl = wrap.querySelector(`[data-captcha-q="${formKind}"]`);
            if (qEl && this.challenge) {
                const isEn = store.lang === 'en';
                const nA = isEn ? this.challenge.num_a_en : this.challenge.num_a_fa;
                const wA = isEn ? this.challenge.word_a_en : this.challenge.word_a_fa;
                const nB = isEn ? this.challenge.num_b_en : this.challenge.num_b_fa;
                const wB = isEn ? this.challenge.word_b_en : this.challenge.word_b_fa;
                if (nA !== undefined && nB !== undefined) {
                    qEl.innerHTML = `<span class="m3-cap-operand"><span class="m3-cap-num">${esc(nA)}</span><span class="m3-cap-word">${esc(wA || '')}</span></span><span class="m3-cap-op">+</span><span class="m3-cap-operand"><span class="m3-cap-num">${esc(nB)}</span><span class="m3-cap-word">${esc(wB || '')}</span></span><span class="m3-cap-eq">=</span>`;
                } else {
                    qEl.textContent = (isEn ? (this.challenge.question_en || this.challenge.question_fa) : (this.challenge.question_fa || this.challenge.question_en)) || '';
                }
            }
            const ansEl = wrap.querySelector(`[data-captcha-ans="${formKind}"]`);
            if (ansEl) {
                ansEl.placeholder = store.lang === 'en' ? '?' : '؟';
                if (!ansEl._capBound) {
                    ansEl._capBound = true;
                    ansEl.addEventListener('input', () => {
                        const raw = ansEl.value;
                        const caret = (ansEl.selectionStart === null) ? raw.length : ansEl.selectionStart;
                        // Fold Persian/Arabic digits to Latin and drop anything that is not a
                        // digit, tracking where the caret lands as we go. Assigning .value
                        // outright would throw the caret to the end on every keystroke, which
                        // makes the field's contents jump for no reason and stops you editing
                        // in the middle of an answer.
                        let norm = '', newCaret = 0;
                        for (let i = 0; i < raw.length; i++) {
                            const c = raw.charCodeAt(i);
                            let d = -1;
                            if (c >= 0x06F0 && c <= 0x06F9) d = c - 0x06F0;
                            else if (c >= 0x0660 && c <= 0x0669) d = c - 0x0660;
                            else if (c >= 0x0030 && c <= 0x0039) d = c - 0x0030;
                            if (d < 0) continue;
                            if (i < caret) newCaret++;
                            norm += String(d);
                        }
                        if (norm !== raw) {
                            ansEl.value = norm;
                            try { ansEl.setSelectionRange(newCaret, newCaret); } catch (e) {}
                        }
                        // Deliberately neutral: only the server can judge the answer, so
                        // typing anything must never look like a confirmation.
                        wrap.classList.remove('is-invalid');
                        if (hintEl) hintEl.textContent = t('captcha_ux_sub');
                    });
                }
                if (markInvalidKind && markInvalidKind === formKind) {
                    wrap.classList.add('is-invalid');
                    if (hintEl) hintEl.textContent = t('captcha_ux_invalid');
                } else {
                    wrap.classList.remove('is-invalid');
                    if (hintEl) hintEl.textContent = t('captcha_ux_sub');
                }
            }
            const refBtn = wrap.querySelector(`[data-captcha-refresh="${formKind}"]`);
            if (refBtn) refBtn.title = t('captcha_refresh_tip');
        });
        document.querySelectorAll('.m3-captcha-token-field').forEach(inp => {
            inp.value = (this.challenge && this.challenge.token) ? this.challenge.token : '';
        });
    },
    async refreshChallenge(clearAnswers = true, markInvalidKind = '') {
        document.querySelectorAll('[data-captcha-refresh]').forEach(btn => btn.classList.add('is-spinning'));
        const r = await apiCall('captcha_challenge', {});
        setTimeout(() => {
            document.querySelectorAll('[data-captcha-refresh]').forEach(btn => btn.classList.remove('is-spinning'));
        }, 460);
        if (r.ok && r.data) {
            if (r.data.fw_js_token) this.jsToken = String(r.data.fw_js_token);
            if (r.data.captcha_challenge) this.challenge = r.data.captcha_challenge;
            if (clearAnswers) {
                document.querySelectorAll('[data-captcha-ans]').forEach(inp => { inp.value = ''; });
            }
            this.syncDom(markInvalidKind);
        }
    },
    collectFormFields(formEl) {
        if (!formEl) return {};
        const out = {
            m3_wpa_js: this.jsToken || (formEl.querySelector('.m3-wpa-js-field') ? formEl.querySelector('.m3-wpa-js-field').value : '')
        };
        const hpIn = formEl.querySelector('.m3-hp-input');
        const hpKey = (hpIn && hpIn.getAttribute('name')) || this.hpFieldName || 'm3_hp_website';
        out[hpKey] = hpIn ? hpIn.value : '';
        const tokIn = formEl.querySelector('.m3-captcha-token-field');
        const ansIn = formEl.querySelector('[data-captcha-ans]');
        out.captcha_token = (tokIn && tokIn.value) || (this.challenge ? this.challenge.token : '') || '';
        out.captcha_answer = ansIn ? normalizeCaptchaDigits(ansIn.value) : '';
        const stepPassEl = formEl.querySelector('#login-captcha-step-pass');
        if (stepPassEl && stepPassEl.value) {
            out.captcha_step_pass = stepPassEl.value;
        }
        return out;
    }
};

async function bootApp(bootOpts = {}) {
    if (!IS_INSTALLED) return;

    applyLangAndTheme(store.lang, store.theme);

    if ('serviceWorker' in navigator) {
        navigator.serviceWorker.register('?a=sw').catch(() => {});
    }

    window.addEventListener('online', () => document.getElementById('offline-banner').classList.add('hidden'));
    window.addEventListener('offline', () => document.getElementById('offline-banner').classList.remove('hidden'));

    const res = await apiCall('bootstrap');
    if (!res.ok) return;

    store.csrf = res.data.csrf_token || '';
    store.settings = res.data.settings || {};
    applyAuthIdentityInputLimits();
    store.tick = String(res.data.tick || '0');
    store.typingTick = String(res.data.typing_tick || '0');
    AuthShield.applyFromData(res.data);
    if (store.settings.site_name_fa) {
        document.documentElement.setAttribute('data-site-fa', store.settings.site_name_fa);
    }
    if (store.settings.site_name_en) {
        document.documentElement.setAttribute('data-site-en', store.settings.site_name_en);
    }
    applySiteBrandingAssets(store.settings.site_logo || '', store.settings.site_favicon || '');

    const siteTitleEl = document.getElementById('auth-site-title');
    if (siteTitleEl) {
        siteTitleEl.textContent = formatSiteName();
    }

    const annBanner = document.getElementById('announce-banner');
    if (annBanner) {
        if (store.settings.announcement) {
            annBanner.textContent = '📢 ' + store.settings.announcement;
            annBanner.classList.remove('hidden');
        } else {
            annBanner.classList.add('hidden');
        }
    }

    if (!res.data.authenticated) {
        clearAllAuthFormsCompletely(true);
        document.getElementById('auth-screen').classList.remove('hidden');
        document.getElementById('messenger-shell').classList.add('hidden');
        clearAllAuthFormsCompletely(true);
        AuthShield.syncDom();
        if (AuthShield.captchaEnabled && !AuthShield.challenge) {
            AuthShield.refreshChallenge(true);
        }
        const invGroup = document.getElementById('reg-invite-group');
        if (invGroup) {
            invGroup.classList.toggle('hidden', store.settings.reg_mode === 'open');
        }
        // Nothing to raise here: the barrier a visitor who is not signed in
        // meets is served by the server as a document of its own, so this page
        // only ever loads after it has been passed.
        if (Number(store.settings.maintenance_mode) === 1) {
            showMaintenanceNotice();
        } else {
            hideMaintenanceNotice();
        }
        return;
    }

    store.user = res.data.user;
    if (typeof window.syncNotifMasterBtn === 'function') window.syncNotifMasterBtn();
    applyLangAndTheme(getLoginLangForUser(store.user.lang, store.lang), store.user.theme || store.theme);
    document.getElementById('auth-screen').classList.add('hidden');
    document.getElementById('messenger-shell').classList.remove('hidden');

    if (res.data.session_locked) {
        if (typeof syncQuickLockButtonVisibility === 'function') syncQuickLockButtonVisibility();
        if (typeof showMessengerLockScreen === 'function') showMessengerLockScreen(store.user);
        return;
    }

    store.isSessionLocked = false;
    store.udig = res.data.udig || '';
    store.chats = res.data.chats || [];
    store.blockedIds = res.data.blocked_ids || [];
    DraftSyncManager.initFromBootUser(store.user);
    if (!window._m3VisWakeBound) {
        window._m3VisWakeBound = true;
        document.addEventListener('visibilitychange', () => {
            if (document.hidden) {
                if (store.user && store.activeChatId && !store.editMsg) {
                    saveChatComposerDraft(store.activeChatId);
                    DraftSyncManager.syncNow(false);
                }
            } else if (typeof window._m3WakeSyncPoll === 'function') {
                window._m3WakeSyncPoll();
            }
        });
    }

    const adminBtn = document.getElementById('btn-admin-panel');
    if (adminBtn) {
        adminBtn.classList.toggle('hidden', store.user.role !== 'superadmin');
    }
    if (typeof syncQuickLockButtonVisibility === 'function') syncQuickLockButtonVisibility();
    if (typeof initInactivityAutoLock === 'function') initInactivityAutoLock();
    if (typeof initAutoLogoutTimer === 'function') initAutoLogoutTimer();
    if (typeof initMobileBackNavStack === 'function') initMobileBackNavStack();

    renderSelfDock();
    renderChatList();
    if (typeof LiveCallManager !== 'undefined' && LiveCallManager.onChatsSynced) {
        LiveCallManager.onChatsSynced(store.chats);
    }
    if (bootOpts && bootOpts.preLoginPassword) {
        try {
            await E2EE.syncWithPassword(bootOpts.preLoginPassword);
        } catch (e) {}
    }
    await E2EE.ensureIdentityKeys();

    if (store.chats.length > 0 && !store.activeChatId) {
        // Nothing is opened automatically: the messenger waits on the
        // placeholder until the user picks a conversation.
        showNoChatSelected();
        if (typeof LiveCallManager !== 'undefined' && LiveCallManager.onChatsSynced) {
            LiveCallManager.onChatsSynced(store.chats);
        }
    }

    if (location.hash === '#/admin' && store.user.role === 'superadmin') {
        openAdminPanelModal('dashboard');
    }

    renderGlobalIdleBanner();
    if (!store._idleClockInterval) {
        store._idleClockInterval = setInterval(() => {
            if (!store.user) return;
            renderGlobalIdleBanner();
            renderChatList();
            if (store.activeChatId) renderActiveChatHeader();
        }, 15000);
    }
    syncBackgroundServiceWorkerAndPush();
    try {
        const uParams = new URLSearchParams(window.location.search || '');
        const openCid = parseInt(uParams.get('open_chat') || '0', 10);
        if (openCid > 0 && (store.chats || []).some(c => Number(c.id) === openCid)) {
            history.replaceState(history.state || null, '', window.location.pathname);
            selectChat(openCid);
        }
    } catch (e) {}
    startSyncPollLoop();
}

function syncMobileVisualViewportHeight() {
    if (!window.visualViewport) return;
    const vv = window.visualViewport;
    const vp = document.getElementById('messages-viewport');
    const prevMax = vp ? Math.max(0, vp.scrollHeight - vp.clientHeight) : 0;
    const wasNearBottom = vp ? (prevMax <= 28 || (prevMax - vp.scrollTop) <= 95) : false;
    if (window.innerWidth <= 780) {
        document.documentElement.style.setProperty('--app-vvh', Math.round(vv.height) + 'px');
        document.documentElement.style.setProperty('--app-vvt', Math.max(0, Math.round(vv.offsetTop || 0)) + 'px');
        if (window.scrollY > 0) window.scrollTo(0, 0);
        syncComposerHeightVar();
        if (wasNearBottom && vp) {
            vp.scrollTop = vp.scrollHeight;
            requestAnimationFrame(() => { vp.scrollTop = vp.scrollHeight; });
        }
    } else {
        document.documentElement.style.removeProperty('--app-vvh');
        document.documentElement.style.removeProperty('--app-vvt');
        syncComposerHeightVar();
    }
}

function wireEvents() {
    startPasswordFieldObserver();
    // A decoy written straight into the HTML - in front of the login screen, or
    // for a session the server locked on this very page load - never passes
    // through showDecoyScreen(), so its key handler has to be bound here.
    // Without this the page is a dead end: Enter does nothing.
    if (typeof wireDecoyScreen === 'function') wireDecoyScreen();
    if (!IS_INSTALLED) {
        wireInstallerEvents();
        return;
    }

    document.querySelectorAll('[data-captcha-refresh]').forEach(btn => {
        btn.addEventListener('click', () => AuthShield.refreshChallenge(true));
    });

    document.querySelectorAll('[data-auth-tab]').forEach(btn => {
        btn.addEventListener('click', () => {
            document.querySelectorAll('[data-auth-tab]').forEach(b => b.classList.remove('active'));
            btn.classList.add('active');
            const tab = btn.dataset.authTab;
            document.getElementById('login-form').classList.toggle('hidden', tab !== 'login');
            document.getElementById('register-form').classList.toggle('hidden', tab !== 'register');
            document.getElementById('recovery-form').classList.toggle('hidden', tab !== 'recovery');
            AuthShield.syncDom();
        });
    });

    const btnAuthLang = document.getElementById('auth-lang-btn');
    if (btnAuthLang) {
        btnAuthLang.addEventListener('click', () => {
            applyLangAndTheme(store.lang === 'fa' ? 'en' : 'fa', store.theme, true);
            AuthShield.syncDom();
            const pwResetNotice = document.getElementById('login-pw-reset-notice');
            if (pwResetNotice && !pwResetNotice.classList.contains('hidden')) {
                pwResetNotice.textContent = t('pw_reset_required_banner');
            }
            toast(t('lang_switched_toast'));
        });
    }
    const btnAuthTheme = document.getElementById('auth-theme-btn');
    if (btnAuthTheme) {
        btnAuthTheme.addEventListener('click', () => {
            const next = store.theme === 'auto' ? 'dark' : (store.theme === 'dark' ? 'light' : 'auto');
            applyLangAndTheme(store.lang, next);
            AuthShield.syncDom();
            toast(next === 'light' ? t('theme_toast_light') : (next === 'dark' ? t('theme_toast_dark') : t('theme_toast_auto')));
        });
    }

    const loginForm = document.getElementById('login-form');
    if (loginForm) {
        loginForm.addEventListener('submit', async e => {
            e.preventDefault();
            const fd = new FormData(loginForm);
            const remChk = document.getElementById('login-remember-me');
            const pwResetNotice = document.getElementById('login-pw-reset-notice');
            if (pwResetNotice) pwResetNotice.classList.add('hidden');
            const shieldFields = AuthShield.collectFormFields(loginForm);
            const basePayload = Object.assign({
                username: fd.get('username'),
                password: fd.get('password'),
                totp_code: fd.get('totp_code') || '',
                remember_me: (remChk && remChk.checked) ? 1 : 0
            }, shieldFields);
            let r = await apiCall('login', basePayload);
            if (!r.ok && r.error === 'pow_required' && r.pow && r.pow.nonce) {
                if (r.captcha_challenge || r.details && r.details.captcha_challenge) {
                    AuthShield.challenge = r.captcha_challenge || r.details.captcha_challenge;
                    AuthShield.syncDom();
                }
                const sol = await solvePowChallenge(r.pow.nonce, r.pow.difficulty || 3);
                r = await apiCall('login', Object.assign({}, basePayload, AuthShield.collectFormFields(loginForm), {
                    pow_nonce: r.pow.nonce,
                    pow_solution: sol
                }));
            }
            if (r.ok) {
                const rawLoginPw = String(fd.get('password') || '');
                const stepPassEl = document.getElementById('login-captcha-step-pass');
                if (stepPassEl) stepPassEl.value = '';
                clearAllAuthFormsCompletely(true);
                await bootApp({ preLoginPassword: (rawLoginPw && !r.data?.duress) ? rawLoginPw : '' });
            } else if (r.error === 'totp_required') {
                document.getElementById('login-totp-group').classList.remove('hidden');
                const stepPass = (r.details && r.details.captcha_step_pass) || r.captcha_step_pass || '';
                const stepPassEl = document.getElementById('login-captcha-step-pass');
                if (stepPassEl && stepPass) stepPassEl.value = stepPass;
                toast(r.message, true);
            } else if (r.error === 'password_reset_required') {
                // Item #14: Dedicated forced-password-reset message guiding user to Recovery Code (preserving active 2FA)
                if (pwResetNotice) {
                    pwResetNotice.textContent = t('pw_reset_required_banner');
                    pwResetNotice.classList.remove('hidden');
                }
                const recUserIn = document.querySelector('#recovery-form input[name="username"]');
                if (recUserIn && fd.get('username')) {
                    recUserIn.value = String(fd.get('username'));
                }
                await AuthShield.refreshChallenge(true);
                toast(t('pw_reset_required_banner'), true);
            } else {
                await AuthShield.refreshChallenge(true, r.error && r.error.includes('captcha') ? 'login' : '');
                toast(r.message || t('err_login_failed'), true);
            }
        });
    }

    const regForm = document.getElementById('register-form');
    if (regForm) {
        const regPwIn = document.getElementById('reg-password-input');
        const regPwConfIn = document.getElementById('reg-password-confirm-input');
        const regPwHint = document.getElementById('reg-pw-hint');
        const updateRegPwHint = () => {
            if (!regPwIn || !regPwConfIn || !regPwHint) return;
            const p1 = regPwIn.value;
            const p2 = regPwConfIn.value;
            renderPasswordStrengthGuideNode(regPwHint, p1, p2);
        };
        if (regPwIn) regPwIn.addEventListener('input', updateRegPwHint);
        if (regPwConfIn) regPwConfIn.addEventListener('input', updateRegPwHint);

        regForm.addEventListener('submit', async e => {
            e.preventDefault();
            const fdCheck = new FormData(regForm);
            const regLim = getIdentityLenLimits();
            const rawRegU = String(fdCheck.get('username') || '').trim().toLowerCase();
            const rawRegN = String(fdCheck.get('name') || '').trim();
            if (!/^[a-z0-9_]+$/.test(rawRegU) || rawRegU.length < regLim.uMin || rawRegU.length > regLim.uMax) {
                toast(formatInvalidUsernameErr(regLim.uMin, regLim.uMax), true);
                const uEl = document.getElementById('reg-username-input');
                if (uEl) uEl.focus();
                return;
            }
            const regNLen = countUnicodeChars(rawRegN);
            if (regNLen < regLim.nMin || regNLen > regLim.nMax) {
                toast(formatInvalidDisplayNameErr(regLim.nMin, regLim.nMax), true);
                const nEl = document.getElementById('reg-name-input');
                if (nEl) nEl.focus();
                return;
            }
            const pwVal = String(fdCheck.get('password') || '');
            const pwConfVal = String(fdCheck.get('password_confirm') || '');
            if (pwVal !== pwConfVal) {
                updateRegPwHint();
                toast(t('pw_mismatch_err'), true);
                if (regPwConfIn) regPwConfIn.focus();
                return;
            }
            const pwChk = validateStrongPasswordClient(pwVal);
            if (!pwChk.valid) {
                updateRegPwHint();
                toast(pwChk.message, true);
                if (regPwIn) regPwIn.focus();
                return;
            }
            const powRes = await apiCall('pow_challenge', { username: 'global' });
            let powNonce = '';
            let solution = '0';
            if (powRes.ok && powRes.data && powRes.data.nonce) {
                powNonce = powRes.data.nonce;
                solution = await solvePowChallenge(powRes.data.nonce, powRes.data.difficulty || 2);
            }
            const fd = new FormData(regForm);
            const regPayload = Object.assign({
                username: fd.get('username'),
                name: fd.get('name'),
                password: fd.get('password'),
                password_confirm: fd.get('password_confirm'),
                invite_code: fd.get('invite_code') || '',
                pow_bucket: 'global',
                pow_nonce: powNonce,
                pow_solution: solution,
                lang: store.lang,
                theme: store.theme
            }, AuthShield.collectFormFields(regForm));
            let r = await apiCall('register', regPayload);
            if (!r.ok && r.error === 'pow_required' && r.pow && r.pow.nonce) {
                const retrySol = await solvePowChallenge(r.pow.nonce, r.pow.difficulty || 2);
                r = await apiCall('register', Object.assign({}, regPayload, AuthShield.collectFormFields(regForm), {
                    pow_nonce: r.pow.nonce,
                    pow_solution: retrySol
                }));
            }
            if (r.ok) {
                const rawRegPw = pwVal;
                clearAllAuthFormsCompletely(true);
                await askApproval({
                    title: t('signup_ok_title'),
                    descNode: buildRecoveryCodeDescNode(t('signup_ok_desc'), r.data.recovery_code),
                    confirmText: t('copy_and_continue_btn'),
                    hideCancel: true,
                    danger: false,
                    icon: '🔑'
                });
                await copyTextToClipboard(r.data.recovery_code);
                await bootApp({ preLoginPassword: rawRegPw || '' });
            } else {
                await AuthShield.refreshChallenge(true, r.error && r.error.includes('captcha') ? 'register' : '');
                toast(r.message || t('err_reg_failed'), true);
            }
        });
    }

    const recForm = document.getElementById('recovery-form');
    if (recForm) {
        const recPwIn = recForm.querySelector('input[name="new_password"]');
        const recPwConfIn = recForm.querySelector('input[name="new_password_confirm"]');
        let recPwGuide = null;
        if (recPwIn && recPwIn.parentElement) {
            recPwGuide = document.createElement('div');
            recPwGuide.className = 'pw-strength-guide';
            recPwGuide.textContent = t('pw_policy_hint');
            const guideAnchor = recPwIn.closest('.resp-grid-2') || recPwIn.parentElement;
            guideAnchor.insertAdjacentElement('afterend', recPwGuide);
            const syncRecGuide = () => renderPasswordStrengthGuideNode(recPwGuide, recPwIn.value, recPwConfIn ? recPwConfIn.value : undefined);
            recPwIn.addEventListener('input', syncRecGuide);
            if (recPwConfIn) recPwConfIn.addEventListener('input', syncRecGuide);
        }
        recForm.addEventListener('submit', async e => {
            e.preventDefault();
            const fd = new FormData(recForm);
            const newPwVal = String(fd.get('new_password') || '');
            const newPwConfVal = String(fd.get('new_password_confirm') || '');
            const pwChk = validateStrongPasswordClient(newPwVal);
            if (!pwChk.valid) {
                if (recPwGuide) renderPasswordStrengthGuideNode(recPwGuide, newPwVal, newPwConfVal);
                toast(pwChk.message, true);
                if (recPwIn) recPwIn.focus();
                return;
            }
            if (newPwVal !== newPwConfVal) {
                if (recPwGuide) renderPasswordStrengthGuideNode(recPwGuide, newPwVal, newPwConfVal);
                toast(t('pw_mismatch_err'), true);
                if (recPwConfIn) recPwConfIn.focus();
                return;
            }
            const r = await apiCall('recover_password', Object.assign({
                username: fd.get('username'),
                recovery_code: fd.get('recovery_code'),
                totp_code: fd.get('totp_code') || '',
                new_password: newPwVal,
                new_password_confirm: newPwConfVal
            }, AuthShield.collectFormFields(recForm)));
            if (r.ok) {
                clearAllAuthFormsCompletely(true);
                await askApproval({
                    title: t('recovery_ok_title'),
                    descNode: buildRecoveryCodeDescNode(t('recovery_ok_desc'), r.data.new_recovery_code),
                    confirmText: t('copy_and_continue_btn'),
                    hideCancel: true,
                    danger: false,
                    icon: '🔑'
                });
                await copyTextToClipboard(r.data.new_recovery_code);
                location.reload();
            } else if (r.error === 'totp_required') {
                const recTotpGrp = document.getElementById('recovery-totp-group');
                if (recTotpGrp) recTotpGrp.classList.remove('hidden');
                const recTotpIn = document.getElementById('recovery-totp-input');
                if (recTotpIn) recTotpIn.focus();
                await AuthShield.refreshChallenge(true);
                toast(r.message || t('recovery_totp_hint'), true);
            } else {
                await AuthShield.refreshChallenge(true);
                toast(r.message || t('err_rec_failed'), true);
            }
        });
    }

    // 1. Desktop Resizable Sidebar (RTL & LTR exact geometry + persistent width + double-click reset)
    (function initDesktopSidebarResizer() {
        const DEFAULT_SIDEBAR_W = 420;
        const MIN_SIDEBAR_W = 300;
        const getMaxSidebarW = () => Math.max(MIN_SIDEBAR_W + 40, Math.min(680, Math.floor((window.innerWidth || 1280) * 0.60)));
        const clampSidebarW = w => Math.max(MIN_SIDEBAR_W, Math.min(getMaxSidebarW(), Math.round(w)));

        const savedW = parseInt(localStorage.getItem('m3_sidebar_width') || '', 10);
        if (!isNaN(savedW) && savedW >= MIN_SIDEBAR_W) {
            document.documentElement.style.setProperty('--sidebar-width', clampSidebarW(savedW) + 'px');
        } else {
            document.documentElement.style.setProperty('--sidebar-width', clampSidebarW(DEFAULT_SIDEBAR_W) + 'px');
        }

        const resizer = document.getElementById('sidebar-resizer');
        const sidebar = document.getElementById('app-sidebar') || document.querySelector('.sidebar');
        if (!resizer || !sidebar) return;

        let dragging = false;
        let anchorEdge = 0;
        let isRtlDrag = false;
        let latestWidth = DEFAULT_SIDEBAR_W;

        const onMouseMove = ev => {
            if (!dragging) return;
            ev.preventDefault();
            const rawWidth = isRtlDrag ? (anchorEdge - ev.clientX) : (ev.clientX - anchorEdge);
            latestWidth = clampSidebarW(rawWidth);
            document.documentElement.style.setProperty('--sidebar-width', latestWidth + 'px');
        };

        const stopDrag = () => {
            if (!dragging) return;
            dragging = false;
            resizer.classList.remove('is-dragging');
            document.body.classList.remove('sidebar-resizing');
            window.removeEventListener('mousemove', onMouseMove);
            window.removeEventListener('mouseup', stopDrag);
            try { localStorage.setItem('m3_sidebar_width', String(latestWidth)); } catch (err) {}
        };

        resizer.addEventListener('mousedown', ev => {
            if (ev.button !== 0 || window.innerWidth <= 780) return;
            ev.preventDefault();
            const rect = sidebar.getBoundingClientRect();
            isRtlDrag = (document.documentElement.dir === 'rtl');
            anchorEdge = isRtlDrag ? rect.right : rect.left;
            latestWidth = clampSidebarW(rect.width);
            dragging = true;
            resizer.classList.add('is-dragging');
            document.body.classList.add('sidebar-resizing');
            window.addEventListener('mousemove', onMouseMove);
            window.addEventListener('mouseup', stopDrag);
        });

        resizer.addEventListener('dblclick', () => {
            if (window.innerWidth <= 780) return;
            const w = clampSidebarW(DEFAULT_SIDEBAR_W);
            document.documentElement.style.setProperty('--sidebar-width', w + 'px');
            try { localStorage.removeItem('m3_sidebar_width'); } catch (err) {}
            toast(t('sidebar_width_reset_toast'));
        });

        window.addEventListener('resize', () => {
            if (window.innerWidth <= 780) return;
            const curVar = parseInt(getComputedStyle(document.documentElement).getPropertyValue('--sidebar-width'), 10);
            if (!isNaN(curVar)) {
                document.documentElement.style.setProperty('--sidebar-width', clampSidebarW(curVar) + 'px');
            }
        });
    })();

    // 2. Horizontal Scrollable & Left-Click Mouse-Draggable Filter Buttons Under Search Field
    (function initFilterPillsDragScroll() {
        const pillsBar = document.getElementById('chat-filter-pills');
        if (!pillsBar) return;

        let isMouseDown = false;
        let hasDragged = false;
        let suppressNextClick = false;
        let startClientX = 0;
        let startScrollLeft = 0;

        pillsBar.addEventListener('dragstart', ev => ev.preventDefault());

        pillsBar.addEventListener('mousedown', ev => {
            if (ev.button !== 0) return; // Strictly left mouse button
            isMouseDown = true;
            hasDragged = false;
            startClientX = ev.clientX;
            startScrollLeft = pillsBar.scrollLeft;
        });

        window.addEventListener('mousemove', ev => {
            if (!isMouseDown) return;
            const dx = ev.clientX - startClientX;
            if (!hasDragged && Math.abs(dx) >= 4) {
                hasDragged = true;
                pillsBar.classList.add('is-dragging');
            }
            if (hasDragged) {
                ev.preventDefault();
                pillsBar.scrollLeft = startScrollLeft - dx;
            }
        }, { passive: false });

        const endMouseDrag = () => {
            if (!isMouseDown) return;
            isMouseDown = false;
            pillsBar.classList.remove('is-dragging');
            if (hasDragged) {
                suppressNextClick = true;
                setTimeout(() => { suppressNextClick = false; }, 100);
            }
            hasDragged = false;
        };

        window.addEventListener('mouseup', endMouseDrag);
        window.addEventListener('blur', endMouseDrag);

        // Suppress accidental button click right after finishing a drag pan
        pillsBar.addEventListener('click', ev => {
            if (suppressNextClick) {
                ev.preventDefault();
                ev.stopPropagation();
                suppressNextClick = false;
            }
        }, true);

        // Smooth mouse-wheel horizontal scroll assist on filter bar
        pillsBar.addEventListener('wheel', ev => {
            if (pillsBar.scrollWidth <= pillsBar.clientWidth) return;
            if (Math.abs(ev.deltaY) > Math.abs(ev.deltaX)) {
                ev.preventDefault();
                const dirSign = (document.documentElement.dir === 'rtl') ? -1 : 1;
                pillsBar.scrollLeft += ev.deltaY * dirSign;
            }
        }, { passive: false });
    })();

    document.querySelectorAll('#chat-filter-pills .filter-pill[data-chat-filter]').forEach(pill => {
        pill.addEventListener('click', () => {
            document.querySelectorAll('#chat-filter-pills .filter-pill[data-chat-filter]').forEach(p => p.classList.remove('active'));
            pill.classList.add('active');
            store.chatFilter = pill.dataset.chatFilter || 'all';
            pill.scrollIntoView({ behavior: 'smooth', block: 'nearest', inline: 'nearest' });
            renderChatList();
        });
        bindContextAndHold(pill, (cx, cy) => {
            openFilterPillContextMenu(pill.dataset.chatFilter || 'all', cx, cy);
        });
    });

    // Item #14 & #15: Swipe Left/Right on Main Chat List to Switch Category Filter Tabs + Prevent Text Selection on Chat List
    (() => {
        const sidebarEl = document.querySelector('#messenger-shell .sidebar');
        const listCont = document.getElementById('chat-list-container');
        if (listCont) {
            listCont.addEventListener('selectstart', e => e.preventDefault());
            listCont.addEventListener('dragstart', e => e.preventDefault());
        }
        if (!sidebarEl) return;
        let swStartX = 0;
        let swStartY = 0;
        let swTracking = false;
        sidebarEl.addEventListener('touchstart', ev => {
            if (!ev.touches || ev.touches.length !== 1) return;
            if (ev.target && ev.target.closest('input, textarea, select, #chat-filter-pills, .sidebar-header, .self-dock')) return;
            swStartX = ev.touches[0].clientX;
            swStartY = ev.touches[0].clientY;
            swTracking = true;
        }, { passive: true });
        sidebarEl.addEventListener('touchend', ev => {
            if (!swTracking || !ev.changedTouches || ev.changedTouches.length === 0) return;
            swTracking = false;
            const dx = ev.changedTouches[0].clientX - swStartX;
            const dy = ev.changedTouches[0].clientY - swStartY;
            if (Math.abs(dx) < 52 || Math.abs(dx) < Math.abs(dy) * 1.4) return;
            const pills = Array.from(document.querySelectorAll('#chat-filter-pills .filter-pill[data-chat-filter]'));
            if (pills.length < 2) return;
            let curIdx = pills.findIndex(p => (p.dataset.chatFilter || 'all') === (store.chatFilter || 'all'));
            if (curIdx < 0) curIdx = 0;
            const isRtl = (document.documentElement.dir || 'rtl') === 'rtl';
            // Natural content swipe: in RTL tabs go right-to-left (0 at right, N at left): swiping right (dx > 0) advances to next tab on the left; in LTR swiping left (dx < 0) advances to next tab on the right
            const step = isRtl ? (dx > 0 ? 1 : -1) : (dx < 0 ? 1 : -1);
            const nextIdx = Math.max(0, Math.min(pills.length - 1, curIdx + step));
            if (nextIdx === curIdx) return;
            pills.forEach(p => p.classList.remove('active'));
            const nextPill = pills[nextIdx];
            nextPill.classList.add('active');
            store.chatFilter = nextPill.dataset.chatFilter || 'all';
            nextPill.scrollIntoView({ behavior: 'smooth', block: 'nearest', inline: 'nearest' });
            renderChatList();
        }, { passive: true });
    })();
    const btnMarkAllRead = document.getElementById('btn-mark-all-read');
    if (btnMarkAllRead) {
        btnMarkAllRead.addEventListener('click', () => markAllUnreadChatsRead());
    }

    const btnSidebarTheme = document.getElementById('btn-theme-toggle');
    if (btnSidebarTheme) {
        btnSidebarTheme.addEventListener('click', async () => {
            const next = store.theme === 'auto' ? 'dark' : (store.theme === 'dark' ? 'light' : 'auto');
            applyLangAndTheme(store.lang, next);
            toast(next === 'light' ? t('theme_toast_light') : (next === 'dark' ? t('theme_toast_dark') : t('theme_toast_auto')));
            renderChatList();
            renderActiveChatHeader();
            if (store.user) {
                await apiCall('profile_update', { theme: next });
            }
        });
    }

    /* Sidebar notification switch. Asks for the browser permission while it is
       still undecided; once granted it mutes or unmutes every notification.
       Emoji: 🔕 not yet allowed · 🔔 on · 🔇 muted · 🚫 blocked by the browser. */
    const syncNotifMasterBtn = () => {
        const btn = document.getElementById('btn-notif-master');
        const ico = document.getElementById('notif-master-svg');
        if (!btn || !ico) return;
        const supported = ('Notification' in window);
        const perm = supported ? Notification.permission : 'unsupported';
        const muted = Number((store.user && store.user.app_sounds_muted) || 0) === 1;
        // Monochrome line icons, so the control matches the theme and language
        // buttons beside it: bell+plus = not allowed yet, bell = on,
        // bell+slash = muted. Blocked keeps the slash and is dimmed as well.
        const inner = (svgStr) => String(svgStr || '').replace(/^<svg[^>]*>/, '').replace(/<\/svg>$/, '');
        const GLYPH = {
            default: inner(HDR_SVG.bellPlus),
            on: inner(HDR_SVG.bell),
            muted: inner(HDR_SVG.bellOff),
            denied: inner(HDR_SVG.bellOff)
        };
        let key = 'notif_state_default', stateVal = 'default';
        if (!supported || perm === 'denied') {
            key = 'notif_state_denied'; stateVal = 'denied';
        } else if (perm === 'granted') {
            key = muted ? 'notif_state_muted' : 'notif_state_on';
            stateVal = muted ? 'muted' : 'on';
        }
        ico.innerHTML = GLYPH[stateVal] || GLYPH.default;
        btn.classList.toggle('is-blocked', stateVal === 'denied');
        btn.title = t(key);
        btn.setAttribute('data-i18n-title', key);
        btn.dataset.notifState = stateVal;
        btn.setAttribute('aria-label', t(key));
    };
    window.syncNotifMasterBtn = syncNotifMasterBtn;

    const btnSidebarNotif = document.getElementById('btn-notif-master');
    if (btnSidebarNotif) {
        btnSidebarNotif.addEventListener('click', async () => {
            const supported = ('Notification' in window);
            if (supported && Notification.permission === 'default') {
                try { await Notification.requestPermission(); } catch (e) {}
                syncNotifMasterBtn();
                if (Notification.permission !== 'granted') {
                    toast(t('notif_perm_denied_toast'), true);
                }
                return;
            }
            if (!supported || Notification.permission === 'denied') {
                toast(t('notif_perm_denied_toast'), true);
                return;
            }
            const muted = Number((store.user && store.user.app_sounds_muted) || 0) === 1;
            const ap = await askApproval({
                title: t(muted ? 'notif_unmute_confirm_title' : 'notif_mute_confirm_title'),
                desc: t(muted ? 'notif_unmute_confirm_desc' : 'notif_mute_confirm_desc'),
                danger: !muted,
                icon: muted ? '🔔' : '🔇'
            });
            if (!ap.approved) return;
            const r = await apiCall('profile_update', { app_sounds_muted: muted ? 0 : 1 });
            if (r.ok) {
                if (r.data && r.data.user) store.user = r.data.user;
                syncNotifMasterBtn();
                toast(t(muted ? 'notif_unmuted_toast' : 'notif_muted_toast'));
            } else {
                toast(r.message || t('err_generic'), true);
            }
        });
        syncNotifMasterBtn();
    }

    const btnSidebarLang = document.getElementById('btn-lang-toggle');
    if (btnSidebarLang) {
