        if (!chat || chat.type !== 'group') return;
        const ap = await askApproval({
            title: chat.all_muted === 1 ? t('unfreeze_group_btn') : t('freeze_group_btn'),
            desc: `${t('ask_freeze_group')}
💬 ${formatChatTitle(chat)}`,
            danger: chat.all_muted !== 1,
            icon: chat.all_muted === 1 ? '🔊' : '🔇'
        });
        if (!ap.approved) return;
        const r = await apiCall('chat_mute_all_toggle', { chat_id: chat.id, all_muted: chat.all_muted === 1 ? 0 : 1 });
