    const pinBarEl = document.getElementById('pinned-message-bar');
    if (pinBarEl) {
        pinBarEl.addEventListener('click', async e => {
            if (e.target && e.target.closest('#btn-unpin-msg')) return;
            const chat = getActiveChat();
            const pinnedMid = (chat && chat.pinned_message && chat.pinned_message.id) ? Number(chat.pinned_message.id) : 0;
            if (chat && pinnedMid > 0) {
                await jumpToMessageInChat(chat.id, pinnedMid);
            }
        });
    }

    document.getElementById('btn-unpin-msg').addEventListener('click', async e => {
        e.stopPropagation();
        const chat = getActiveChat();
        if (!chat || chat.type === 'system' || chat.is_ghost) return;
        const pinnedMid = (chat.pinned_message && chat.pinned_message.id) ? chat.pinned_message.id : 0;
        const isTopPersonal = Boolean(chat.pinned_message && chat.pinned_message.scope === 'me');
        const isSuperOrOwner = (store.user && store.user.role === 'superadmin') || chat.my_role === 'owner';
        const myPerms = chat.my_perms || {};
        const canPinBoth = chat.type === 'saved' || chat.type === 'dm' || chat.type === 'secret' || isSuperOrOwner || (chat.my_role === 'admin' && myPerms.pin_messages !== 0);
        const pinScope = isTopPersonal ? 'me' : (canPinBoth ? 'both' : 'dismiss_both');
        const upRes = await apiCall('unpin', { chat_id: chat.id, message_id: pinnedMid, scope: pinScope });
        if (!upRes.ok) {
            toast(upRes.message || t('err_generic'), true);
            return;
        }
        if (pinScope === 'both' && Array.isArray(store.messages[chat.id])) {
            store.messages[chat.id].forEach(m => { m.pinned = 0; });
        }
        if (upRes.data && upRes.data.chats) store.chats = upRes.data.chats;
        renderActiveChatHeader();
        await renderMessagesViewport(false);
        toast(t('msg_unpinned_toast'));
    });

    document.getElementById('btn-chat-search').addEventListener('click', () => {
        const bar = document.getElementById('in-chat-search-bar');
        bar.classList.toggle('hidden');
        if (!bar.classList.contains('hidden')) {
            document.getElementById('in-chat-search-input').focus();
        }
    });
    document.getElementById('btn-close-chat-search').addEventListener('click', async () => {
        const searchBar = document.getElementById('in-chat-search-bar');
        const searchIn = document.getElementById('in-chat-search-input');
        if (searchBar) searchBar.classList.add('hidden');
        if (searchIn) searchIn.value = '';
        if (store.activeChatId) await selectChat(store.activeChatId);
    });
    let inChatSearchTimer = null;
    const runInChatSearch = async (qStr) => {
        if (!store.activeChatId) return;
        const cid = store.activeChatId;
        if (!qStr) {
            await selectChat(cid, { preserveScrollBottom: true });
            return;
        }
        const r = await apiCall('search_chat', { chat_id: cid, q: qStr });
        if (r.ok && r.data.messages && store.activeChatId === cid) {
            let list = r.data.messages;
            const chatObj = getActiveChat();
            if (r.data.client_e2ee_filter && chatObj && chatObj.type === 'secret') {
                const ql = qStr.toLowerCase();
                const matched = [];
                for (const m of list) {
                    let plain = m.body || '';
                    if (m.cipher && m.iv) {
                        plain = await E2EE.decryptText(chatObj, m.cipher, m.iv);
                    }
                    const fName = (m.file && m.file.display_name) ? String(m.file.display_name) : '';
                    if (String(plain).toLowerCase().includes(ql) || fName.toLowerCase().includes(ql)) {
                        matched.push(m);
                    }
                }
                list = matched;
            }
            store.inChatSearchActive = true;
            store.inChatSearchChatId = cid;
            store.messages[cid] = list;
            await renderMessagesViewport(false);
        }
    };
    document.getElementById('in-chat-search-input').addEventListener('input', e => {
        clearTimeout(inChatSearchTimer);
        const q = e.target.value.trim();
        inChatSearchTimer = setTimeout(() => runInChatSearch(q), 260);
    });
    document.getElementById('in-chat-search-input').addEventListener('keydown', async e => {
        if (e.key === 'Enter' && store.activeChatId) {
            e.preventDefault();
            clearTimeout(inChatSearchTimer);
            await runInChatSearch(e.target.value.trim());
        }
    });

    let searchTimer = null;
    document.getElementById('global-search-input').addEventListener('input', e => {
        clearTimeout(searchTimer);
        const q = e.target.value.trim();
        const gsRes = document.getElementById('global-search-results');
        if (!q) {
            if (gsRes) gsRes.classList.add('hidden');
            renderChatList();
            return;
        }
        searchTimer = setTimeout(async () => {
            const r = await apiCall('search_global', { q });
            if (!r.ok) return;
            const container = gsRes || document.getElementById('chat-list-container');
            if (gsRes) gsRes.classList.remove('hidden');
            container.innerHTML = '';
            (r.data.users || []).forEach(u => {
                const div = document.createElement('div');
                div.className = 'chat-item';
                div.textContent = `👤 ${u.name} (${formatHandleLabel(u)})`;
                div.addEventListener('click', () => {
                    if (gsRes) gsRes.classList.add('hidden');
                    openUserMiniProfile(u.id);
                });
                container.appendChild(div);
            });
            (r.data.chats || []).forEach(c => {
                const div = document.createElement('div');
                div.className = 'chat-item';
                div.textContent = `💬 ${c.title} ${c.handle ? ('(@' + c.handle + ')') : ''}`;
                div.addEventListener('click', async () => {
                    if (gsRes) gsRes.classList.add('hidden');
                    const jr = await apiCall('chat_join', { chat_id: c.id });
                    if (jr.ok) {
                        store.chats = jr.data.chats;
                        await selectChat(c.id);
                    }
                });
                container.appendChild(div);
            });
            const msgHits = Array.isArray(r.data.messages) ? r.data.messages : [];
            if (msgHits.length > 0) {
                const secHdr = document.createElement('div');
                secHdr.style.cssText = 'padding:6px 12px 4px;font-size:11.5px;font-weight:800;color:var(--text-muted);border-top:1px solid var(--border-subtle);margin-top:4px';
                secHdr.textContent = t('global_search_msgs_hdr');
                container.appendChild(secHdr);
                msgHits.forEach(mh => {
                    const row = document.createElement('div');
                    row.className = 'chat-item global-msg-hit';
                    row.style.cssText = 'display:flex;align-items:center;justify-content:space-between;gap:8px;padding:8px 10px';
                    const infoCol = document.createElement('div');
                    infoCol.style.cssText = 'min-width:0;flex:1;display:flex;flex-direction:column;gap:2px';
                    const topLine = document.createElement('div');
                    topLine.style.cssText = 'font-size:12.5px;font-weight:800;white-space:nowrap;overflow:hidden;text-overflow:ellipsis';
                    const rawChatTitle = mh.chat_type === 'saved' ? t('saved_messages_title') : (mh.chat_type === 'system' ? t('system_chat_title') : (mh.chat_title || ''));
                    topLine.textContent = rawChatTitle + (mh.sender_name ? (' • ' + mh.sender_name) : '');
                    const snipLine = document.createElement('div');
                    snipLine.style.cssText = 'font-size:12px;color:var(--text-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis';
                    snipLine.setAttribute('dir', 'auto');
                    snipLine.textContent = mh.snippet || '';
                    infoCol.appendChild(topLine);
                    infoCol.appendChild(snipLine);

                    const jumpBtn = document.createElement('button');
                    jumpBtn.type = 'button';
                    jumpBtn.className = 'btn btn-primary btn-sm global-search-jump-btn';
                    jumpBtn.style.cssText = 'flex-shrink:0;padding:4px 9px;font-size:11.5px;border-radius:999px;white-space:nowrap';
                    jumpBtn.textContent = t('show_in_chat_btn');

                    const goToHit = async (ev) => {
                        if (ev) ev.stopPropagation();
                        if (gsRes) gsRes.classList.add('hidden');
                        await selectChat(Number(mh.chat_id), { aroundId: Number(mh.id) });
                    };
                    jumpBtn.addEventListener('click', goToHit);
                    row.addEventListener('click', goToHit);

                    row.appendChild(infoCol);
                    row.appendChild(jumpBtn);
                    container.appendChild(row);
                });
            }
        }, 300);
    });

    const vp = document.getElementById('messages-viewport');
    const scrollFab = document.getElementById('btn-scroll-bottom');
    const compWrapObs = document.querySelector('#active-chat-view .composer-wrap');
    if (compWrapObs && typeof ResizeObserver !== 'undefined') {
        const ro = new ResizeObserver(() => {
            syncComposerHeightVar();
        });
        ro.observe(compWrapObs);
    }
    if (vp && scrollFab) {
        vp.addEventListener('scroll', () => {
            updateScrollBottomFab(true);
            maybePaginateChatMessagesOnScroll();
        }, { passive: true });
        scrollFab.addEventListener('click', async () => {
            const cidNow = store.activeChatId;
            if (!cidNow) return;
            const curChatObj = getActiveChat();
            const unreadCountHere = Math.max(
                Number((store.inChatUnreadByChat && store.inChatUnreadByChat[cidNow]) || 0),
                Number((curChatObj && curChatObj.unread_count) || 0)
            );
            const firstUnreadId = Number((store.firstUnreadByChat && store.firstUnreadByChat[cidNow]) || 0);

            // Item #9: Jump to the FIRST unread message first (rather than skipping past all new messages to the end)
            if (unreadCountHere > 0 && firstUnreadId > 0) {
                let targetEl = vp.querySelector('.unread-divider-pill') || vp.querySelector(`.msg-row[data-msg-id="${firstUnreadId}"]`);
                if (!targetEl) {
                    await selectChat(cidNow, { aroundId: firstUnreadId });
                    targetEl = vp.querySelector('.unread-divider-pill') || vp.querySelector(`.msg-row[data-msg-id="${firstUnreadId}"]`);
                }
                if (targetEl) {
                    const desiredTop = Math.max(0, targetEl.offsetTop - 44);
                    if (Math.abs(vp.scrollTop - desiredTop) > 36) {
                        vp.scrollTop = desiredTop;
                        const rowToFlash = vp.querySelector(`.msg-row[data-msg-id="${firstUnreadId}"]`);
                        if (rowToFlash) {
                            rowToFlash.classList.add('msg-jump-highlight');
                            setTimeout(() => rowToFlash.classList.remove('msg-jump-highlight'), 1800);
                        }
                        updateScrollBottomFab(true);
                        return;
                    }
                }
            }

            if (store.inChatUnreadByChat) store.inChatUnreadByChat[cidNow] = 0;
            if (store.firstUnreadByChat) store.firstUnreadByChat[cidNow] = 0;
            scrollFab.classList.add('hidden');
            const badgeEl = document.getElementById('scroll-bottom-unread-badge');
            if (badgeEl) {
                badgeEl.textContent = '';
                badgeEl.classList.add('hidden');
            }
            if (store.hasMoreAfterByChat && store.hasMoreAfterByChat[cidNow]) {
                store.hasMoreAfterByChat[cidNow] = false;
                store._forcePinBottomUntil = Date.now() + 1400;
                await selectChat(cidNow);
                return;
            }
            store._forcePinBottomUntil = Date.now() + 900;
            pinViewportToBottom(vp, 350);
            await acknowledgeActiveChatBottomRead(cidNow);
        });
    }

    // Track real user activity for sliding cookie expiration (Item #13) + Mobile VisualViewport upward composer lock (Item #5)
    ['pointerdown', 'keydown', 'touchstart', 'wheel'].forEach(evName => {
        window.addEventListener(evName, () => {
            store.lastUserInteractionAt = Date.now();
        }, { passive: true });
    });
    if (window.visualViewport) {
        window.visualViewport.addEventListener('resize', syncMobileVisualViewportHeight);
        window.visualViewport.addEventListener('scroll', syncMobileVisualViewportHeight);
        syncMobileVisualViewportHeight();
    }

    document.getElementById('btn-cancel-context').addEventListener('click', () => {
        if (store.editMsg) {
            cancelEditAndRestoreDraft();
        } else {
            store.replyToMsg = null;
            updateComposerContextBar();
        }
    });

    const btnTtl = document.getElementById('btn-ttl-cycle');
    const btnTtlCancel = document.getElementById('btn-ttl-cancel');
    const ttlPop = document.getElementById('ttl-popover');

    if (btnTtl && ttlPop) {
        btnTtl.addEventListener('click', e => {
            e.stopPropagation();
            const emPop = document.getElementById('emoji-popover');
            if (emPop) emPop.classList.add('hidden');
            const willOpen = ttlPop.classList.contains('hidden');
            if (willOpen) {
                renderTtlPopoverMenu();
                ttlPop.classList.remove('hidden');
            } else {
                ttlPop.classList.add('hidden');
            }
        });
    }

    if (btnTtlCancel) {
        btnTtlCancel.addEventListener('click', e => {
            e.stopPropagation();
            setComposerTtl(0, true);
        });
    }

    document.addEventListener('click', e => {
        const ctxMenu = document.getElementById('chat-context-menu');
        if (ctxMenu && !ctxMenu.classList.contains('hidden') && !e.target.closest('#chat-context-menu')) {
            closeChatContextMenu();
        }
        if (ttlPop && !ttlPop.classList.contains('hidden') && !e.target.closest('#ttl-popover') && !e.target.closest('#ttl-pill-group')) {
            ttlPop.classList.add('hidden');
        }
        const emPop = document.getElementById('emoji-popover');
        if (emPop && !emPop.classList.contains('hidden') && !e.target.closest('#emoji-popover') && !e.target.closest('#btn-emoji-picker')) {
            emPop.classList.add('hidden');
        }
    });
    document.addEventListener('keydown', e => {
        if (e.key === 'Escape') closeChatContextMenu();
    });
    const chatListScrollEl = document.getElementById('chat-list-container');
    if (chatListScrollEl) {
        chatListScrollEl.addEventListener('scroll', () => closeChatContextMenu(), { passive: true });
    }

    document.getElementById('btn-send-msg').addEventListener('click', sendCurrentMessage);
    const compTextareaEl = document.getElementById('composer-textarea');
    compTextareaEl.addEventListener('input', () => {
        if (store.editMsg) {
            syncComposerEditMaxLength();
        }
        autoResizeComposerInput();
        if (store.activeChatId && !store.editMsg) {
            saveChatComposerDraft(store.activeChatId);
            TypingIndicatorManager.onComposerInput();
        }
    });
    compTextareaEl.addEventListener('blur', () => {
        if (store.activeChatId) {
            TypingIndicatorManager.stopTyping(store.activeChatId);
        }
    });
    compTextareaEl.addEventListener('focus', () => {
        if (window.innerWidth <= 780) {
            setTimeout(syncMobileVisualViewportHeight, 80);
            setTimeout(syncMobileVisualViewportHeight, 260);
        }
    });
    compTextareaEl.addEventListener('keydown', e => {
        if (e.key !== 'Enter' || e.isComposing) return;
        if (e.ctrlKey || e.metaKey) {
            e.preventDefault();
            sendCurrentMessage();
            return;
        }
        const mode = String((store.user && store.user.send_key_mode) || 'ctrl_enter');
        if (mode === 'enter' && !e.shiftKey && !e.altKey) {
            e.preventDefault();
            sendCurrentMessage();
        }
    });

    document.addEventListener('keydown', e => {
        if (e.defaultPrevented || e.ctrlKey || e.metaKey || e.altKey || e.isComposing) return;
        if (!store.user || store.isSessionLocked || !store.activeChatId) return;
        const shellEl = document.getElementById('messenger-shell');
        const activeViewEl = document.getElementById('active-chat-view');
        if (!shellEl || shellEl.classList.contains('hidden') || !activeViewEl || activeViewEl.classList.contains('hidden')) return;
        if (window.innerWidth <= 780 && !shellEl.classList.contains('chat-open')) return;
        if (document.querySelector('dialog[open]')) return;
        const gsResEl = document.getElementById('global-search-results');
        if (gsResEl && !gsResEl.classList.contains('hidden')) return;
        const inSearchBarEl = document.getElementById('in-chat-search-bar');
        const activeEl = document.activeElement;
        if (activeEl) {
            if (activeEl === compTextareaEl) return;
            const tag = String(activeEl.tagName || '').toUpperCase();
            if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT' || activeEl.isContentEditable) return;
            if (inSearchBarEl && !inSearchBarEl.classList.contains('hidden') && inSearchBarEl.contains(activeEl)) return;
        }
        if (!compTextareaEl || compTextareaEl.disabled || compTextareaEl.readOnly || compTextareaEl.offsetParent === null) return;
        const voiceBarEl = document.getElementById('composer-voice-rec-bar');
        const vnoteBarEl = document.getElementById('composer-vnote-rec-bar');
        if ((voiceBarEl && !voiceBarEl.classList.contains('hidden')) || (vnoteBarEl && !vnoteBarEl.classList.contains('hidden'))) return;
        try {
            const sel = window.getSelection ? window.getSelection() : null;
            if (sel && String(sel.toString() || '').trim().length > 0) return;
        } catch (selErr) {}

        if (e.key === 'Process' || e.keyCode === 229) {
            compTextareaEl.focus({ preventScroll: true });
            return;
        }
        if (typeof e.key !== 'string' || e.key.length !== 1) return;
        if (e.key === ' ' && !compTextareaEl.value) return;

        e.preventDefault();
        compTextareaEl.focus({ preventScroll: true });
        const curLen = compTextareaEl.value.length;
        const sStart = typeof compTextareaEl.selectionStart === 'number' ? compTextareaEl.selectionStart : curLen;
        const sEnd = typeof compTextareaEl.selectionEnd === 'number' ? compTextareaEl.selectionEnd : curLen;
        compTextareaEl.setRangeText(e.key, sStart, sEnd, 'end');
        compTextareaEl.dispatchEvent(new Event('input', { bubbles: true }));
    });

    const emojiPop = document.getElementById('emoji-popover');
    document.getElementById('btn-emoji-picker').addEventListener('click', e => {
        e.stopPropagation();
        if (ttlPop) ttlPop.classList.add('hidden');
        if (emojiPop.children.length === 0) {
            ['😀','😂','😍','🥰','😎','🤔','😭','😡','👍','👎','❤️','🔥','🎉','👏','🙏','💯','🌹','✨','🚀','✅','⚡','💎','🤝','🎯'].forEach(em => {
                const sp = document.createElement('span');
                sp.className = 'emoji-cell';
                sp.textContent = em;
                sp.addEventListener('click', () => {
                    const ta = document.getElementById('composer-textarea');
                    if (store.editMsg) {
                        const maxCp = Math.max(100, Number((store.settings && store.settings.max_msg_len) || 2000));
                        const curCps = Array.from(ta.value || '').length;
                        const emCps = Array.from(em).length;
                        if (curCps + emCps > maxCp) {
                            toast(t('err_msg_too_long_tpl').replace('{max}', formatLocalizedCount(maxCp)), true);
                            return;
                        }
                    }
                    ta.value += em;
                    if (store.editMsg) syncComposerEditMaxLength();
                    autoResizeComposerInput();
                    if (store.activeChatId && !store.editMsg) {
                        saveChatComposerDraft(store.activeChatId);
                    }
                    emojiPop.classList.add('hidden');
                    ta.focus();
                });
                emojiPop.appendChild(sp);
            });
        }
        emojiPop.classList.toggle('hidden');
    });

    const fileIn = document.getElementById('file-upload-input');
    document.getElementById('btn-attach-file').addEventListener('click', () => fileIn.click());
    fileIn.addEventListener('change', () => {
        if (fileIn.files && fileIn.files[0]) {
            openFileUploadWithCaptionModal(fileIn.files[0], 'file');
            fileIn.value = '';
        }
    });

    const mainCol = document.getElementById('chat-pane-dropzone');
    const dropOverlay = document.getElementById('dropzone-overlay');
    if (mainCol && dropOverlay) {
        let dragDepth = 0;
        const hasDraggedFiles = e => e.dataTransfer && Array.from(e.dataTransfer.types || []).includes('Files');

        mainCol.addEventListener('dragenter', e => {
            if (!store.activeChatId || !hasDraggedFiles(e)) return;
            e.preventDefault();
            dragDepth++;
            dropOverlay.classList.remove('hidden');
        });
        mainCol.addEventListener('dragover', e => {
            if (!store.activeChatId || !hasDraggedFiles(e)) return;
            e.preventDefault();
            if (e.dataTransfer) e.dataTransfer.dropEffect = 'copy';
            dropOverlay.classList.remove('hidden');
        });
        mainCol.addEventListener('dragleave', e => {
            if (!store.activeChatId) return;
            e.preventDefault();
            dragDepth = Math.max(0, dragDepth - 1);
            if (dragDepth === 0) dropOverlay.classList.add('hidden');
        });
        mainCol.addEventListener('drop', e => {
            e.preventDefault();
            dragDepth = 0;
            dropOverlay.classList.add('hidden');
            if (!store.activeChatId) return;
            const actBar = document.getElementById('composer-active-bar');
            if (actBar && actBar.classList.contains('hidden')) return;
            if (e.dataTransfer && e.dataTransfer.files && e.dataTransfer.files[0]) {
                openFileUploadWithCaptionModal(e.dataTransfer.files[0], 'file');
            }
        });
    }

    // Ctrl+V / Clipboard File & Screenshot Paste Support
    document.addEventListener('paste', e => {
        if (!store.user || !store.activeChatId) return;
        const actBar = document.getElementById('composer-active-bar');
        if (actBar && actBar.classList.contains('hidden')) return;
        const confirmDlg = document.getElementById('confirm-modal');
        if (confirmDlg && confirmDlg.open) return;
        const appDlg = document.getElementById('app-modal');
        if (appDlg && appDlg.open) return;

        const cd = e.clipboardData;
        if (!cd) return;

        let pastedFile = null;
        if (cd.files && cd.files.length > 0) {
            pastedFile = cd.files[0];
        } else if (cd.items && cd.items.length > 0) {
            for (let i = 0; i < cd.items.length; i++) {
                const it = cd.items[i];
                if (it.kind === 'file') {
                    pastedFile = it.getAsFile();
                    if (pastedFile) break;
                }
            }
        }

        if (pastedFile) {
            e.preventDefault();
            let finalFile = pastedFile;
            if (!pastedFile.name || pastedFile.name === 'image.png' || pastedFile.name === 'blob') {
                const mime = (pastedFile.type || 'application/octet-stream').toLowerCase();
                let ext = 'bin';
                if (mime.includes('png')) ext = 'png';
                else if (mime.includes('jpeg') || mime.includes('jpg')) ext = 'jpg';
                else if (mime.includes('gif')) ext = 'gif';
                else if (mime.includes('webp')) ext = 'webp';
                else if (mime.includes('mp4')) ext = 'mp4';
                else if (mime.includes('webm')) ext = 'webm';
                else if (mime.includes('ogg')) ext = 'ogg';
                else if (mime.includes('mpeg') || mime.includes('mp3')) ext = 'mp3';
                else if (mime.includes('wav')) ext = 'wav';
                else if (mime.includes('pdf')) ext = 'pdf';
                else if (mime.includes('plain')) ext = 'txt';
                try {
                    finalFile = new File([pastedFile], `pasted_${Date.now()}.${ext}`, { type: pastedFile.type || 'application/octet-stream' });
                } catch (err) {}
            }
            toast(t('pasted_file_ready'));
            openFileUploadWithCaptionModal(finalFile, 'file');
        }
    });

    document.getElementById('btn-record-voice').addEventListener('click', startVoiceRecording);
    document.getElementById('btn-finish-voice').addEventListener('click', stopAndSendVoiceRecording);
    document.getElementById('btn-cancel-voice').addEventListener('click', cancelVoiceRecording);

    // Schema v8: Quick Lock, Location, Instant Video Note, Live Call Buttons & Mobile Composer Auto-Fit
    const btnQuickLock = document.getElementById('btn-quick-lock');
    if (btnQuickLock) btnQuickLock.addEventListener('click', () => lockMessengerNow());
    const btnSendLoc = document.getElementById('btn-send-location');
    if (btnSendLoc) btnSendLoc.addEventListener('click', () => openSendLocationModal());
    const btnSnapPhoto = document.getElementById('btn-snap-photo');
    const camFallbackIn = document.getElementById('camera-fallback-input');
    if (camFallbackIn) {
        camFallbackIn.addEventListener('change', () => {
            if (camFallbackIn.files && camFallbackIn.files[0]) {
                openFileUploadWithCaptionModal(camFallbackIn.files[0], 'file');
                camFallbackIn.value = '';
            }
        });
    }
    if (btnSnapPhoto) {
        btnSnapPhoto.addEventListener('click', () => openDirectCameraCaptureModal());
    }
    const btnRecVNote = document.getElementById('btn-record-video-note');
    if (btnRecVNote) btnRecVNote.addEventListener('click', () => startVideoNoteRecording());
    const btnFlipVNote = document.getElementById('btn-flip-vnote');
    if (btnFlipVNote) btnFlipVNote.addEventListener('click', () => flipVideoNoteCamera());
    const btnCancelVNote = document.getElementById('btn-cancel-vnote');
    if (btnCancelVNote) btnCancelVNote.addEventListener('click', () => cancelVideoNoteRecording());
    const btnFinishVNote = document.getElementById('btn-finish-vnote');
    if (btnFinishVNote) btnFinishVNote.addEventListener('click', () => stopAndSendVideoNote());
    const btnVoiceCallHdr = document.getElementById('btn-chat-voice-call');
    if (btnVoiceCallHdr) btnVoiceCallHdr.addEventListener('click', () => LiveCallManager.startOrJoinFromHeader('voice'));
    const btnVideoCallHdr = document.getElementById('btn-chat-video-call');
    if (btnVideoCallHdr) btnVideoCallHdr.addEventListener('click', () => LiveCallManager.startOrJoinFromHeader('video'));

    const compTaForAux = document.getElementById('composer-textarea');
    const compBarForAux = document.getElementById('composer-active-bar');
    if (compTaForAux && compBarForAux) {
        const syncAuxVis = () => {
            compBarForAux.classList.toggle('composer-has-text', compTaForAux.value.trim().length > 0);
        };
        compTaForAux.addEventListener('input', syncAuxVis);
        syncAuxVis();
    }
    if (typeof wireLockScreenDialogEvents === 'function') wireLockScreenDialogEvents();
    if (typeof LiveCallManager !== 'undefined' && LiveCallManager.wireDom) LiveCallManager.wireDom();

    bindAppModalBackdropDismiss(document.getElementById('app-modal'));
    document.getElementById('app-modal-close').addEventListener('click', () => {
        document.getElementById('app-modal').close();
    });
}

// Both headers collapse the same way: the bar keeps the primary actions and
// everything else is listed here. Every row drives the real button, so the
// behaviour - including the role and state gating that hides some of them - is
// identical to pressing it in the bar.
function openHeaderActionMenu(rows) {
    openModal(t('tip_more_options'), (body, close) => {
        const list = document.createElement('div');
        list.style.cssText = 'display:flex;flex-direction:column;gap:8px';
        // A few labels ship with a decorative emoji in front of the text. The
        // row already carries a monochrome icon, so a leading one is dropped.
        const plain = txt => String(txt).replace(
            /^(?:[\u2190-\u27BF\u2B00-\u2BFF\u{1F000}-\u{1FAFF}]\uFE0F?[\s\u200D]*)+/u, '');
        const pick = v => (typeof v === 'function') ? v() : v;
        rows.forEach(([btnId, svgHtml, labelTxt]) => {
            const real = document.getElementById(btnId);
            if (!real || real.classList.contains('hidden')) return;
            const b = document.createElement('button');
            b.type = 'button';
            b.className = 'btn btn-secondary btn-block';
            b.style.cssText = 'justify-content:flex-start;gap:10px';
            const ico = document.createElement('span');
            ico.style.cssText = 'width:18px;height:18px;display:inline-flex;align-items:center;justify-content:center';
            ico.innerHTML = pick(svgHtml);
            const sp = document.createElement('span');
            sp.textContent = plain(pick(labelTxt));
            b.appendChild(ico);
            b.appendChild(sp);
            b.addEventListener('click', () => { close(); real.click(); });
            list.appendChild(b);
        });
        body.appendChild(list);
    });
}

// Row icons are sized explicitly: unlike the buttons in the bar they are not
// covered by the `.icon-btn svg` rule.
const menuIcon = h => '<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">' + h + '</svg>';

function openChatHeaderMoreModal() {
    const chat = getActiveChat();
    if (!chat) return;
    openHeaderActionMenu([
        ['btn-chat-my-files', menuIcon('<path d="M22 19a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h5l2 3h9a2 2 0 0 1 2 2z"/>'), t('my_files_chat_title')],
        ['btn-chat-calendar', menuIcon('<rect x="3" y="4" width="18" height="18" rx="2" ry="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/>'), t('tip_calendar_jump')],
        ['btn-group-mute-all',
            () => menuIcon(chat.all_muted === 1
                ? '<polygon points="11 5 6 9 2 9 2 15 6 15 11 19 11 5"/><path d="M15.54 8.46a5 5 0 0 1 0 7.07"/><path d="M19.07 4.93a10 10 0 0 1 0 14.14"/>'
                : '<polygon points="11 5 6 9 2 9 2 15 6 15 11 19 11 5"/><line x1="23" y1="9" x2="17" y2="15"/><line x1="17" y1="9" x2="23" y2="15"/>'),
            () => chat.all_muted === 1 ? t('unfreeze_group_btn') : t('freeze_group_btn')],
        ['btn-chat-report', menuIcon('<path d="M4 15s1-1 4-1 5 2 8 2 4-1 4-1V3s-1 1-4 1-5-2-8-2-4 1-4 1z"/><line x1="4" y1="22" x2="4" y2="15"/>'), t('tip_report')]
    ]);
}

// Same treatment as the chat header: when the toolbar runs out of room the
// secondary actions collapse into this menu instead of being squeezed out.
function openSidebarMoreModal() {
    openHeaderActionMenu([
        ['btn-lang-toggle', menuIcon('<circle cx="12" cy="12" r="10"/><line x1="2" y1="12" x2="22" y2="12"/><path d="M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z"/>'), t('tip_lang')],
        ['btn-my-files', menuIcon('<path d="M22 19a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h5l2 3h9a2 2 0 0 1 2 2z"/>'), t('my_files_title')],
        ['btn-settings', menuIcon('<circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 0 1 0 2.83 2 2 0 0 1-2.83 0l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 0 1-2 2 2 2 0 0 1-2-2v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 0 1-2.83 0 2 2 0 0 1 0-2.83l.06-.06a1.65 1.65 0 0 0 .33-1.82 1.65 1.65 0 0 0-1.51-1H3a2 2 0 0 1-2-2 2 2 0 0 1 2-2h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 0 1 0-2.83 2 2 0 0 1 2.83 0l.06.06a1.65 1.65 0 0 0 1.82.33H9a1.65 1.65 0 0 0 1-1.51V3a2 2 0 0 1 2-2 2 2 0 0 1 2 2v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 0 1 2.83 0 2 2 0 0 1 0 2.83l-.06.06a1.65 1.65 0 0 0-.33 1.82V9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 0 1 2 2 2 2 0 0 1-2 2h-.09a1.65 1.65 0 0 0-1.51 1z"/>'), t('tip_settings')],
        ['btn-admin-panel', menuIcon('<path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"/>'), t('tip_admin')]
    ]);
}


function openChatCalendarModal() {
    const chat = getActiveChat();
    if (!chat) return;

    const isJalali = (store.lang === 'fa');
    const jMonths = ['فروردین', 'اردیبهشت', 'خرداد', 'تیر', 'مرداد', 'شهریور', 'مهر', 'آبان', 'آذر', 'دی', 'بهمن', 'اسفند'];
    const gMonths = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
    const jWeekdays = ['ش', 'ی', 'د', 'س', 'چ', 'پ', 'ج'];
    const gWeekdays = ['Su', 'Mo', 'Tu', 'We', 'Th', 'Fr', 'Sa'];

    const nowDate = new Date(getMessengerNowSec() * 1000);
    const [todayJy, todayJm, todayJd] = gregorianToJalali(nowDate.getFullYear(), nowDate.getMonth() + 1, nowDate.getDate());
    let curYear = isJalali ? todayJy : nowDate.getFullYear();
    let curMonth = isJalali ? todayJm : (nowDate.getMonth() + 1);

    openModal(t('cal_modal_title'), (body, close) => {
        const calCard = document.createElement('div');
        calCard.className = 'card-box';

        const hdr = document.createElement('div');
        hdr.className = 'm3-cal-header';

        const prevBtn = document.createElement('button');
        prevBtn.type = 'button';
        prevBtn.className = 'btn btn-secondary btn-sm';
        prevBtn.textContent = '‹';
        prevBtn.title = t('cal_prev_month');

        const titleSpan = document.createElement('div');
        titleSpan.style.cssText = 'font-weight:900;font-size:14.5px;text-align:center;flex:1';

        const todayBtn = document.createElement('button');
        todayBtn.type = 'button';
        todayBtn.className = 'btn btn-secondary btn-sm';
        todayBtn.textContent = t('cal_today_btn');

        const nextBtn = document.createElement('button');
        nextBtn.type = 'button';
        nextBtn.className = 'btn btn-secondary btn-sm';
        nextBtn.textContent = '›';
        nextBtn.title = t('cal_next_month');

        hdr.appendChild(prevBtn);
        hdr.appendChild(titleSpan);
        hdr.appendChild(todayBtn);
        hdr.appendChild(nextBtn);
        calCard.appendChild(hdr);

        const wkRow = document.createElement('div');
        wkRow.className = 'm3-cal-weekdays';
        (isJalali ? jWeekdays : gWeekdays).forEach(w => {
            const s = document.createElement('span');
            s.textContent = w;
            wkRow.appendChild(s);
        });
        calCard.appendChild(wkRow);

        const grid = document.createElement('div');
        grid.className = 'm3-cal-grid';
        calCard.appendChild(grid);
        body.appendChild(calCard);

        const rngCard = document.createElement('div');
        rngCard.className = 'card-box';
        const rngHead = document.createElement('div');
        rngHead.className = 'section-header';
        rngHead.textContent = t('cal_range_sec_title');
        rngCard.appendChild(rngHead);

        const rngGrid = document.createElement('div');
        rngGrid.className = 'resp-grid-2';
        const fgFrom = document.createElement('div');
        fgFrom.className = 'form-group';
        const lFrom = document.createElement('label');
        lFrom.textContent = t('cal_from_lbl');
        const inFrom = document.createElement('input');
        inFrom.type = 'date';
        inFrom.className = 'input';
        inFrom.dir = 'ltr';
        fgFrom.appendChild(lFrom);
        fgFrom.appendChild(inFrom);

        const fgTo = document.createElement('div');
        fgTo.className = 'form-group';
        const lTo = document.createElement('label');
        lTo.textContent = t('cal_to_lbl');
        const inTo = document.createElement('input');
        inTo.type = 'date';
        inTo.className = 'input';
        inTo.dir = 'ltr';
        fgTo.appendChild(lTo);
        fgTo.appendChild(inTo);
        rngGrid.appendChild(fgFrom);
        rngGrid.appendChild(fgTo);
        rngCard.appendChild(rngGrid);

        const jumpRangeBtn = document.createElement('button');
        jumpRangeBtn.type = 'button';
        jumpRangeBtn.className = 'btn btn-primary btn-block';
        jumpRangeBtn.textContent = t('cal_jump_range_btn');
        jumpRangeBtn.addEventListener('click', async () => {
            if (!inFrom.value) { inFrom.focus(); return; }
            const fDate = new Date(inFrom.value + 'T00:00:00');
            const tDate = inTo.value ? new Date(inTo.value + 'T23:59:59') : new Date(inFrom.value + 'T23:59:59');
            const startTs = Math.floor(fDate.getTime() / 1000);
            const endTs = Math.floor(tDate.getTime() / 1000);
            const r = await apiCall('messages_by_date', { chat_id: chat.id, start_ts: startTs, end_ts: endTs });
            if (r.ok && r.data) {
                if (Number(r.data.target_id) > 0) {
                    close();
                    await selectChat(chat.id, { aroundId: Number(r.data.target_id) });
                    toast(r.data.exact_in_range ? t('cal_jumped_toast') : t('cal_no_msgs_exact_toast'));
                } else {
                    toast(t('cal_no_msgs_at_all_toast'), true);
                }
            }
        });
        rngCard.appendChild(jumpRangeBtn);
        body.appendChild(rngCard);

        const renderMonthGrid = async () => {
            grid.innerHTML = '';
            let daysInMonth = 30;
            let startWeekday = 0;
            let monthStartSec = 0;
            let monthEndSec = 0;

            if (isJalali) {
                daysInMonth = getJalaliMonthDays(curYear, curMonth);
                titleSpan.textContent = `${jMonths[curMonth - 1]} ${formatLocalizedCount(curYear)}`;
                const [gy1, gm1, gd1] = jalaliToGregorian(curYear, curMonth, 1);
                const [gy2, gm2, gd2] = jalaliToGregorian(curYear, curMonth, daysInMonth);
                const d1 = new Date(gy1, gm1 - 1, gd1, 0, 0, 0);
                const d2 = new Date(gy2, gm2 - 1, gd2, 23, 59, 59);
                startWeekday = (d1.getDay() + 1) % 7;
                monthStartSec = Math.floor(d1.getTime() / 1000);
                monthEndSec = Math.floor(d2.getTime() / 1000);
            } else {
                daysInMonth = new Date(curYear, curMonth, 0).getDate();
                titleSpan.textContent = `${gMonths[curMonth - 1]} ${curYear}`;
                const d1 = new Date(curYear, curMonth - 1, 1, 0, 0, 0);
                const d2 = new Date(curYear, curMonth - 1, daysInMonth, 23, 59, 59);
                startWeekday = d1.getDay();
                monthStartSec = Math.floor(d1.getTime() / 1000);
                monthEndSec = Math.floor(d2.getTime() / 1000);
            }

            const tzOffsetMin = -new Date().getTimezoneOffset();
            const activeDaysSet = new Set();
            const dRes = await apiCall('calendar_month_days', {
                chat_id: chat.id,
                start_ts: monthStartSec,
                end_ts: monthEndSec,
                tz_offset: tzOffsetMin
            });
            if (dRes.ok && dRes.data && Array.isArray(dRes.data.days)) {
                dRes.data.days.forEach(ymd => activeDaysSet.add(String(ymd)));
            }

            for (let e = 0; e < startWeekday; e++) {
                const emptyCell = document.createElement('div');
                emptyCell.className = 'm3-cal-day empty';
                grid.appendChild(emptyCell);
            }

            const pad2 = n => String(n).padStart(2, '0');
            for (let day = 1; day <= daysInMonth; day++) {
                let gy = curYear, gm = curMonth, gd = day;
                if (isJalali) {
                    [gy, gm, gd] = jalaliToGregorian(curYear, curMonth, day);
                }
                const gYmd = `${gy}-${pad2(gm)}-${pad2(gd)}`;
                const isToday = isJalali
                    ? (curYear === todayJy && curMonth === todayJm && day === todayJd)
                    : (gy === nowDate.getFullYear() && gm === (nowDate.getMonth() + 1) && gd === nowDate.getDate());

                const cell = document.createElement('button');
                cell.type = 'button';
                cell.className = 'm3-cal-day' + (isToday ? ' today' : '') + (activeDaysSet.has(gYmd) ? ' has-msgs' : '');
                cell.textContent = isJalali ? formatLocalizedCount(day) : String(day);
                cell.addEventListener('click', async () => {
                    const startD = new Date(gy, gm - 1, gd, 0, 0, 0);
                    const endD = new Date(gy, gm - 1, gd, 23, 59, 59);
                    const r = await apiCall('messages_by_date', {
                        chat_id: chat.id,
                        start_ts: Math.floor(startD.getTime() / 1000),
                        end_ts: Math.floor(endD.getTime() / 1000)
                    });
                    if (r.ok && r.data && Number(r.data.target_id) > 0) {
                        close();
                        await selectChat(chat.id, { aroundId: Number(r.data.target_id) });
                        toast(r.data.exact_in_range ? t('cal_jumped_toast') : t('cal_no_msgs_exact_toast'));
                    } else {
                        toast(t('cal_no_msgs_at_all_toast'), true);
                    }
                });
                grid.appendChild(cell);
            }
        };

        prevBtn.addEventListener('click', () => {
            curMonth--;
            if (curMonth < 1) { curMonth = 12; curYear--; }
            renderMonthGrid();
        });
        nextBtn.addEventListener('click', () => {
            curMonth++;
            if (curMonth > 12) { curMonth = 1; curYear++; }
            renderMonthGrid();
        });
        todayBtn.addEventListener('click', () => {
            curYear = isJalali ? todayJy : nowDate.getFullYear();
            curMonth = isJalali ? todayJm : (nowDate.getMonth() + 1);
            renderMonthGrid();
        });

        renderMonthGrid();
    });
}

/* ============================================================================
 * 11E. SCHEMA V8 MODULES: LOCK SCREEN, MOBILE BACK STACK, POLICIES, DB MIGRATION,
 *      LOCATION SHARING, INSTANT VIDEO NOTES & STANDALONE LIVE CALL MANAGER
 * ============================================================================ */

function syncQuickLockButtonVisibility() {
    const btn = document.getElementById('btn-quick-lock');
    if (!btn) return;
    const active = Boolean(store.user && Number(store.user.lock_screen_enabled) === 1
        && (Number(store.user.lock_forced) === 1 || Number(store.user.decoy_forced) === 1
            || Number(store.user.has_lock_password) === 1));
    btn.classList.toggle('hidden', !active);
}

async function lockMessengerNow() {
    if (!store.user || !store.user.lock_screen_enabled) return;
    const r = await apiCall('session_lock', {});
    if (r.ok || r.error === 'session_locked') {
        showMessengerLockScreen(store.user);
    } else if (r.message) {
        toast(r.message, true);
    }
}

/* Nothing of the lock screen is written into the served document. It is built the
   first time it is actually needed, exactly like the decoy: a page somebody never
   locks carries no password field, no unlock button and no sign-out button, and
   anything reading the HTML finds no trace of them. The data-i18n attributes are
   kept so a language switch still reaches the copy built here. */
function buildLockScreenDialog() {
    const existing = document.getElementById('lock-screen-dialog');
    if (existing) return existing;

    const dlg = document.createElement('dialog');
    dlg.id = 'lock-screen-dialog';
    dlg.className = 'lock-screen-dialog';
    dlg.setAttribute('aria-labelledby', 'lock-screen-title');

    const card = document.createElement('div');
    card.className = 'lock-screen-card';

    const title = document.createElement('div');
    title.id = 'lock-screen-title';
    title.style.cssText = 'font-size:13px;font-weight:700;color:var(--primary);margin-bottom:6px';
    title.dataset.i18n = 'lock_screen_locked_title';
    title.textContent = t('lock_screen_locked_title');

    const desc = document.createElement('p');
    desc.id = 'lock-screen-desc';
    desc.style.cssText = 'font-size:12px;color:var(--text-secondary);margin:0 0 14px;line-height:1.55';
    desc.dataset.i18n = 'lock_screen_unlock_desc';
    desc.textContent = t('lock_screen_unlock_desc');

    // Only shown when the dialog is standing in front of the login screen.
    const preauthDesc = document.createElement('p');
    preauthDesc.id = 'lock-screen-preauth-desc';
    preauthDesc.className = 'hidden';
    preauthDesc.style.cssText = 'font-size:12px;color:var(--text-secondary);margin:0 0 14px;line-height:1.55';
    preauthDesc.dataset.i18n = 'lock_preauth_desc';
    preauthDesc.textContent = t('lock_preauth_desc');

    const form = document.createElement('form');
    form.id = 'lock-screen-form';
    form.autocomplete = 'off';

    const pwWrap = document.createElement('div');
    pwWrap.className = 'form-group';
    pwWrap.id = 'lock-screen-pw-wrap';
    pwWrap.style.cssText = 'text-align:start;margin-bottom:12px';
    const pwIn = document.createElement('input');
    pwIn.type = 'password';
    pwIn.id = 'lock-screen-pw-input';
    pwIn.className = 'input';
    pwIn.dir = 'ltr';
    pwIn.placeholder = '\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022';
    pwIn.autocomplete = 'current-password';
    pwIn.required = true;
    pwWrap.appendChild(pwIn);

    const errEl = document.createElement('div');
    errEl.id = 'lock-screen-err';
    errEl.className = 'hidden';
    errEl.style.cssText = 'font-size:12px;font-weight:700;color:var(--danger);margin-bottom:10px';

    const subBtn = document.createElement('button');
    subBtn.type = 'submit';
    subBtn.className = 'btn btn-primary btn-block';
    subBtn.id = 'lock-screen-submit-btn';
    subBtn.dataset.i18n = 'lock_screen_unlock_btn';
    subBtn.textContent = t('lock_screen_unlock_btn');

    form.appendChild(pwWrap);
    form.appendChild(errEl);
    form.appendChild(subBtn);

    const logoutBtn = document.createElement('button');
    logoutBtn.type = 'button';
    logoutBtn.className = 'btn btn-secondary btn-sm';
    logoutBtn.id = 'lock-screen-logout-btn';
    logoutBtn.style.marginTop = '12px';
    logoutBtn.dataset.i18n = 'logout_btn';
    logoutBtn.textContent = t('logout_btn');

    card.appendChild(title);
    card.appendChild(desc);
    card.appendChild(preauthDesc);
    card.appendChild(form);
    card.appendChild(logoutBtn);
    dlg.appendChild(card);
    document.body.appendChild(dlg);
    return dlg;
}

function showMessengerLockScreen() {
    store.isSessionLocked = true;

    // Standing in front of the login screen rather than guarding a session:
    // nobody is signed in and there is no session to unlock, so this is only a
    // barrier that steps aside when it is dismissed.
    const preauth = (store.lockPreauth === true) || !store.user;

    // When the decoy is on it is the lock screen - the dialog is never shown.
    if (!preauth && store.user && Number(store.user.decoy_active) === 1) {
        showDecoyScreen();
        return;
    }

    // Built on demand: a page that is never locked never carries this markup.
    const dlg = buildLockScreenDialog();
    if (!dlg) return;
    wireLockScreenDialogEvents();

    // A globally forced lock screen opens with a single tap, so it has no
    // password field at all - and neither does the pre-login barrier, because
    // there is nothing here to check a password against.
    const lockNeedsPw = preauth ? false : !(store.user && Number(store.user.lock_needs_password) === 0);
    const pwWrapEl = document.getElementById('lock-screen-pw-wrap');
    if (pwWrapEl) pwWrapEl.classList.toggle('hidden', !lockNeedsPw);
    const descEl = document.getElementById('lock-screen-desc');
    const preauthDescEl = document.getElementById('lock-screen-preauth-desc');
    const preauthLogoutEl = document.getElementById('lock-screen-logout-btn');
    if (descEl) descEl.classList.toggle('hidden', preauth);
    if (preauthDescEl) preauthDescEl.classList.toggle('hidden', !preauth);
    if (preauthLogoutEl) preauthLogoutEl.classList.toggle('hidden', preauth);

    const pwIn = document.getElementById('lock-screen-pw-input');
    const errEl = document.getElementById('lock-screen-err');
    if (errEl) {
        errEl.classList.add('hidden');
        errEl.textContent = '';
    }
    if (pwIn) {
        pwIn.value = '';
        pwIn.required = !!lockNeedsPw;
        pwIn.disabled = !lockNeedsPw;
    }

    if (typeof UniversalPlayer !== 'undefined' && UniversalPlayer.activeMediaEl && !UniversalPlayer.activeMediaEl.paused) {
        try { UniversalPlayer.activeMediaEl.pause(); } catch (e) {}
    }

    try {
        if (dlg.open) dlg.close();
        dlg.showModal();
    } catch (e) {
        dlg.setAttribute('open', 'open');
    }
    if (typeof enhancePasswordFields === 'function') enhancePasswordFields(dlg);
    setTimeout(() => { if (pwIn) pwIn.focus(); }, 40);
}

function wireLockScreenDialogEvents() {
    const dlg = document.getElementById('lock-screen-dialog');
    if (!dlg || dlg._v8Bound) return;
    dlg._v8Bound = true;

    dlg.addEventListener('cancel', e => { e.preventDefault(); });

    const form = document.getElementById('lock-screen-form');
    const pwIn = document.getElementById('lock-screen-pw-input');
    const errEl = document.getElementById('lock-screen-err');
    const subBtn = document.getElementById('lock-screen-submit-btn');
    const logoutBtn = document.getElementById('lock-screen-logout-btn');

    if (form) {
        form.addEventListener('submit', async e => {
            e.preventDefault();
            // Standing in front of the login screen: there is no session to
            // unlock, so the barrier simply gets out of the way.
            if (store.lockPreauth === true) {
                store.lockPreauth = false;
                store.isSessionLocked = false;
                try { dlg.close(); } catch (err) { dlg.removeAttribute('open'); }
                return;
            }
            const pw = pwIn ? pwIn.value : '';
            // A globally forced lock screen has no password - one tap opens it.
            if (!pw && !(store.user && Number(store.user.lock_needs_password) === 0)) return;
            if (subBtn) subBtn.disabled = true;
            if (errEl) errEl.classList.add('hidden');
            try {
                const r = await apiCall('session_unlock', { password: pw });
                if (subBtn) subBtn.disabled = false;
                if (r && r.ok) {
                    if (pwIn) pwIn.value = '';
                    store.isSessionLocked = false;
                    if (typeof disarmLockTamperGuard === 'function') disarmLockTamperGuard();
                    try { dlg.close(); } catch (err) { dlg.removeAttribute('open'); }
                    store._lastActivityTs = Date.now();
                    await bootApp();
                } else if (r && (r.wiped_account || r.error === 'invalid_credentials')) {
                    localStorage.clear();
                    location.href = './';
                } else {
                    if (errEl) {
                        errEl.textContent = (r && r.message) ? r.message : t('lock_screen_wrong_pw');
                        errEl.classList.remove('hidden');
                    }
                    if (pwIn) { pwIn.select(); pwIn.focus(); }
                }
            } catch (err) {
                if (subBtn) subBtn.disabled = false;
            }
        });
    }

    if (logoutBtn) {
        logoutBtn.addEventListener('click', async () => {
            try { await DraftSyncManager.flushBeforeSessionExit(); } catch (e) {}
            await apiCall('logout', {});
            DraftSyncManager.resetLocalStateOnLogout();
            E2EE.clearDerivedCaches();
            store.user = null;
            store.isSessionLocked = false;
            if (typeof disarmLockTamperGuard === 'function') disarmLockTamperGuard();
            try { dlg.close(); } catch (e) {}
            location.reload();
        });
    }
}

/* ----------------------------------------------------------------------------
 * Decoy ("fake") lock screen
 * -------------------------------------------------------------------------- */
function decoyScreenEl() {
    return document.getElementById('decoy-screen');
}

function buildDecoyScreen() {
    const existing = decoyScreenEl();
    if (existing) return existing;
    const wrap = document.createElement('div');
    wrap.id = 'decoy-screen';
    wrap.className = 'decoy-screen hidden';
    wrap.dataset.decoyMode = 'lock';
    const inner = document.createElement('div');
    inner.className = 'decoy-inner';
    const h = document.createElement('h1');
    h.className = 'decoy-title';
    h.id = 'decoy-title';
    const layer = document.createElement('div');
    layer.className = 'decoy-field-layer';
    const p = document.createElement('p');
    p.className = 'decoy-subtitle';
    p.id = 'decoy-subtitle';
    const form = document.createElement('form');
    form.id = 'decoy-form';
    form.autocomplete = 'off';
    const inp = document.createElement('input');
    inp.id = 'decoy-pw-input';
    inp.className = 'decoy-pw';
    inp.type = 'password';
    inp.autocomplete = 'off';
    inp.spellcheck = false;
    inp.tabIndex = -1;
    inp.setAttribute('aria-hidden', 'true');
    inp.setAttribute('enterkeyhint', 'go');
    form.appendChild(inp);
    layer.appendChild(p);
    layer.appendChild(form);
    inner.appendChild(h);
    inner.appendChild(layer);
    wrap.appendChild(inner);
    document.body.insertBefore(wrap, document.body.firstChild);
    return wrap;
}

function showDecoyScreen() {
    const el = buildDecoyScreen();
    const u = store.user || {};
    const title = (typeof u.decoy_title === 'string' && u.decoy_title.trim() !== '') ? u.decoy_title : t('decoy_default_title');
    const sub = (typeof u.decoy_subtitle === 'string' && u.decoy_subtitle.trim() !== '') ? u.decoy_subtitle : t('decoy_default_subtitle');
    const tEl = el.querySelector('#decoy-title');
    const sEl = el.querySelector('#decoy-subtitle');
    const inp = el.querySelector('#decoy-pw-input');
    if (tEl) tEl.textContent = title;
    if (sEl) sEl.textContent = sub;
    el.dir = (store.lang === 'en') ? 'ltr' : 'rtl';
    el.classList.remove('hidden');
    // This overlay may have been rendered by the server in front of the login
    // screen, and it stays in the document when somebody logs in without a page
    // reload. So the mode is re-derived here every time instead of trusting the
    // baked-in attribute: a stale 'preauth' would make Enter merely hide the page
    // instead of unlocking the session, and the very next poll would bring it
    // straight back - a loop, every few seconds.
    el.dataset.decoyMode = (store.user && store.user.id) ? 'lock' : 'preauth';
    if (inp) {
        inp.value = '';
        inp.disabled = false;
        // Before login there is no reason to summon the on-screen keyboard on an
        // ordinary error page - it would give the decoy away.
        if (el.dataset.decoyMode !== 'preauth') {
            setTimeout(() => { try { inp.focus(); } catch (e) {} }, 60);
        }
    }
    store.isSessionLocked = true;
    wireDecoyScreen();
}

function hideDecoyScreen() {
    const el = decoyScreenEl();
    if (!el) return;
    const inp = el.querySelector('#decoy-pw-input');
    if (inp) { inp.value = ''; inp.disabled = true; }
    el.classList.add('hidden');
}

async function submitDecoyPassword() {
    const el = decoyScreenEl();
    const inp = el ? el.querySelector('#decoy-pw-input') : null;
    if (!inp) return;
    // Before login there is no session and nobody to authenticate: the decoy is
    // only standing in front of the login screen, so any input reveals it.
    if (el && el.dataset.decoyMode === 'preauth') {
        inp.value = '';
        // Nothing is locked any more: there is no session behind this page and
        // the overlay is on its way out. Leaving the flag raised would keep the
        // mobile back button and every confirm dialog behaving as though a lock
        // were still standing in front of them.
        store.isSessionLocked = false;
        hideDecoyScreen();
        // Booting unhides this too, but dismissing the decoy before the first
        // bootstrap comes back would otherwise focus a field inside a hidden
        // screen - which silently does nothing and leaves a blank page behind.
        const authScr = document.getElementById('auth-screen');
        if (authScr) authScr.classList.remove('hidden');
        const loginFocus = document.getElementById('login-username-input')
            || document.getElementById('login-username')
            || document.getElementById('auth-username')
            || document.querySelector('#auth-screen input');
        if (loginFocus) setTimeout(() => { try { loginFocus.focus(); } catch (e) {} }, 60);
        return;
    }
    const pw = inp.value;
    inp.disabled = true;
    try {
        const r = await apiCall('session_unlock', { password: pw, decoy: 1 });
        if (r && r.ok) {
            inp.value = '';
            store.isSessionLocked = false;
            if (typeof disarmLockTamperGuard === 'function') disarmLockTamperGuard();
            hideDecoyScreen();
            store._lastActivityTs = Date.now();
            await bootApp();
            return;
        }
        // A duress password destroys the account or the messenger and ends the
        // session, which the decoy reports as a plain expired session.
        if (r && (r.panic_wiped || r.wiped_account || r.error === 'session_wiped' || r.error === 'unauthorized' || r.error === 'invalid_credentials')) {
            try { localStorage.clear(); } catch (e) {}
            location.href = './';
            return;
        }
        // Wrong password: the decoy must not react at all. No message, no shake,
        // nothing that would reveal this page is not what it looks like.
        inp.value = '';
        inp.disabled = false;
        try { inp.focus(); } catch (e) {}
    } catch (err) {
        inp.value = '';
        inp.disabled = false;
    }
}

function wireDecoyScreen() {
    const el = decoyScreenEl();
    if (!el || el._decoyBound) return;
    el._decoyBound = true;
    const inp = el.querySelector('#decoy-pw-input');
    if (!inp) return;
    // A real form is what makes the mobile keyboard show a "Go" key that
    // actually submits; a bare keydown listener is unreliable on phones.
    const form = el.querySelector('#decoy-form');
    if (form) {
        form.addEventListener('submit', e => {
            e.preventDefault();
            submitDecoyPassword();
        });
    }
    inp.addEventListener('keydown', e => {
        if (e.key === 'Enter' || e.keyCode === 13) {
            e.preventDefault();
            submitDecoyPassword();
        }
    });
    el.addEventListener('contextmenu', e => e.preventDefault());
}

/* Inactivity auto-logout. The server drops the session too, but this runs
   entirely in the browser so it also fires when the device is offline: once the
   window has passed, the session is closed and the document is replaced by a
   blank page. */
async function performAutoLogout() {
    // The response is needed: it says which gate, if any, is forced for
    // everybody once this session is gone.
    let outData = null;
    try {
        const outRes = await apiCall('logout', {});
        outData = (outRes && outRes.data) ? outRes.data : null;
    } catch (e) {}
    try { if (typeof DraftSyncManager !== 'undefined') DraftSyncManager.resetLocalStateOnLogout(); } catch (e) {}
    try { if (typeof E2EE !== 'undefined') E2EE.clearDerivedCaches(); } catch (e) {}
    try { if (typeof disarmLockTamperGuard === 'function') disarmLockTamperGuard(); } catch (e) {}
    try { localStorage.clear(); } catch (e) {}
    try { sessionStorage.clear(); } catch (e) {}
    try {
        store.user = null;
        store.chats = [];
        store.messages = {};
        store.activeChatId = null;
        store.blockedIds = [];
    } catch (e) {}
    // Going idle must not become a way around what the super-admin forces for
    // everybody. Load afresh and the server itself serves the decoy or the lock
    // document, so a forced gate still stands in front of the login screen - and
    // a fresh document leaves nothing of the session behind either.
    if (outData && (Number(outData.preauth_decoy) === 1 || Number(outData.preauth_lock) === 1)) {
        try { location.replace('./'); } catch (e) { try { location.reload(); } catch (e2) {} }
        return;
    }
    // Nothing is forced for everybody, so there is no gate to stand in front.
    // Leave nothing behind: a bare white document.
    try {
        document.documentElement.innerHTML =
            '<head><meta charset="utf-8"><title></title></head>' +
            '<body style="margin:0;padding:0;background:#ffffff"></body>';
    } catch (e) {
        try { document.body.innerHTML = ''; } catch (e2) {}
    }
}

function initAutoLogoutTimer() {
    store._autoLogoutLastActive = Date.now();
    if (store._autoLogoutBound) return;
    store._autoLogoutBound = true;

    const bumpAuto = () => { store._autoLogoutLastActive = Date.now(); };
    ['pointerdown', 'keydown', 'touchstart', 'wheel', 'scroll'].forEach(evName => {
        window.addEventListener(evName, bumpAuto, { passive: true, capture: true });
    });

    setInterval(() => {
        if (!store.user || store.isSessionLocked) return;
        const limitSec = Number(store.user.auto_logout_sec || 0);
        if (limitSec <= 0) return;
        // never cut a live call off mid-conversation
        if (typeof LiveCallManager !== 'undefined' && LiveCallManager.currentCall) return;
        const idleSec = (Date.now() - (store._autoLogoutLastActive || Date.now())) / 1000;
        if (idleSec >= limitSec) performAutoLogout();
    }, 5000);
}

function initInactivityAutoLock() {
    store._lastActivityTs = Date.now();
    if (store._inactivityBound) return;
    store._inactivityBound = true;

    const bump = () => {
        if (!store.isSessionLocked) store._lastActivityTs = Date.now();
    };
    ['pointerdown', 'keydown', 'touchstart', 'scroll'].forEach(evName => {
        window.addEventListener(evName, bump, { passive: true, capture: true });
    });

    setInterval(() => {
        if (!store.user || store.isSessionLocked) return;
        if (Number(store.user.lock_screen_enabled) !== 1) return;
        if (Number(store.user.lock_forced) !== 1 && Number(store.user.decoy_forced) !== 1
            && Number(store.user.has_lock_password) !== 1) return;
        const limitSec = Number(store.user.lock_auto_sec || 0);
        if (limitSec <= 0) return;
        if (typeof LiveCallManager !== 'undefined' && LiveCallManager.currentCall) return;
        const idleSec = (Date.now() - (store._lastActivityTs || Date.now())) / 1000;
        if (idleSec >= limitSec) lockMessengerNow();
    }, 4000);
}

/* ---------------- ITEM 8: MOBILE BACK BUTTON STEP-BY-STEP NAVIGATION ---------------- */
function hasClosableUiLayerForBack() {
    if (store.isSessionLocked) return true;
    for (const pid of ['emoji-popover', 'ttl-popover', 'chat-context-menu']) {
        const el = document.getElementById(pid);
        if (el && !el.classList.contains('hidden')) return true;
    }
    const confDlg = document.getElementById('confirm-modal');
    if (confDlg && confDlg.open) return true;
    const subDlg = document.getElementById('sub-modal');
    if (subDlg && subDlg.open) return true;
    const appDlg = document.getElementById('app-modal');
    if (appDlg && appDlg.open) return true;
    const lcw = document.getElementById('live-call-window');
    if (lcw && !lcw.classList.contains('hidden') && lcw.dataset.mode !== 'minimized') return true;
    const ump = document.getElementById('universal-media-player');
    if (ump && !ump.classList.contains('hidden') && ump.dataset.mode !== 'minimized') return true;
    if (store.vnoteRecorder && store.vnoteRecorder.state === 'recording') return true;
    if (store.mediaRecorder && store.mediaRecorder.state === 'recording') return true;
    if (store.selectedMsgIds && store.selectedMsgIds.size > 0) return true;
    const searchBar = document.getElementById('in-chat-search-bar');
    if (searchBar && !searchBar.classList.contains('hidden')) return true;
    const shell = document.getElementById('messenger-shell');
    if (shell && shell.classList.contains('chat-open') && window.innerWidth <= 780) return true;
    return false;
}

function consumeTopMostUiLayerOnBack() {
    if (store.isSessionLocked) return true;
    for (const pid of ['chat-context-menu', 'emoji-popover', 'ttl-popover']) {
        const el = document.getElementById(pid);
        if (el && !el.classList.contains('hidden')) {
            el.classList.add('hidden');
            return true;
        }
    }
    const confDlg = document.getElementById('confirm-modal');
    if (confDlg && confDlg.open) {
        const cancelBtn = document.getElementById('confirm-modal-cancel');
        if (cancelBtn) cancelBtn.click(); else confDlg.close();
        return true;
    }
    const subDlg = document.getElementById('sub-modal');
    if (subDlg && subDlg.open) {
        subDlg.close();
        return true;
    }
    const appDlg = document.getElementById('app-modal');
    if (appDlg && appDlg.open) {
        appDlg.close();
        return true;
    }
    const lcw = document.getElementById('live-call-window');
    if (lcw && !lcw.classList.contains('hidden') && lcw.dataset.mode !== 'minimized') {
        LiveCallManager.setWindowMode('minimized');
        return true;
    }
    const ump = document.getElementById('universal-media-player');
    if (ump && !ump.classList.contains('hidden') && ump.dataset.mode !== 'minimized') {
        if (ump.dataset.mode === 'maximized' && typeof UniversalPlayer !== 'undefined') UniversalPlayer.setMode('normal');
        else if (typeof UniversalPlayer !== 'undefined') UniversalPlayer.close();
        return true;
    }
    if (store.vnoteRecorder && store.vnoteRecorder.state === 'recording') {
        cancelVideoNoteRecording();
        return true;
    }
    if (store.mediaRecorder && store.mediaRecorder.state === 'recording') {
        cancelVoiceRecording();
        return true;
    }
    if (store.selectedMsgIds && store.selectedMsgIds.size > 0) {
        clearMessageSelection();
        return true;
    }
    const searchBar = document.getElementById('in-chat-search-bar');
    if (searchBar && !searchBar.classList.contains('hidden')) {
        const btnCloseS = document.getElementById('btn-close-chat-search');
        if (btnCloseS) btnCloseS.click(); else searchBar.classList.add('hidden');
        return true;
    }
    const shell = document.getElementById('messenger-shell');
    if (shell && shell.classList.contains('chat-open') && window.innerWidth <= 780) {
        exitChatToMobileList();
        return true;
    }
    return false;
}

function ensureNavGuardHistoryEntry() {
    if (!window.history || typeof window.history.pushState !== 'function') return;
    if (!history.state || !history.state.m3NavGuard) {
        try { history.pushState({ m3NavGuard: true }, ''); } catch (e) {}
    }
}

function initMobileBackNavStack() {
    if (store._navBackBound) return;
    store._navBackBound = true;
    ensureNavGuardHistoryEntry();

    window.addEventListener('click', () => {
        setTimeout(() => {
            if (hasClosableUiLayerForBack()) ensureNavGuardHistoryEntry();
        }, 30);
    }, { passive: true });

    window.addEventListener('popstate', () => {
        const handled = consumeTopMostUiLayerOnBack();
        if (handled || hasClosableUiLayerForBack()) ensureNavGuardHistoryEntry();
    });
}

/* ---------------- COMPOSER MEDIA & UPLOAD RESTRICTION BUTTON SYNC ---------------- */
function isContentTypeBlockedForMeInChat(chat, ctype) {
    if (store.user && store.user.role === 'superadmin') return false;
    const glob = Array.isArray(store.settings.global_restricted_content_types) ? store.settings.global_restricted_content_types : [];
    if (glob.includes(ctype)) return true;
    const usr = (store.user && Array.isArray(store.user.restricted_content_types)) ? store.user.restricted_content_types : [];
    if (usr.includes(ctype)) return true;
    if (chat && (chat.type === 'group' || chat.type === 'channel')) {
        const isChatAdmin = chat.my_role === 'owner' || chat.my_role === 'admin';
        if (!isChatAdmin && chat.content_restrictions && Array.isArray(chat.content_restrictions.effective_blocked)) {
            if (chat.content_restrictions.effective_blocked.includes(ctype)) return true;
        }
    }
    return false;
}

function areUploadsDisabledForMe() {
    if (store.user && store.user.role === 'superadmin') return false;
    if (Number(store.settings.uploads_disabled) === 1) return true;
    if (store.user && Number(store.user.upload_disabled) === 1) return true;
    return false;
}

function syncComposerMediaPolicyButtons(chat) {
    const isSuper = !!(store.user && store.user.role === 'superadmin');
    const upOff = areUploadsDisabledForMe();
    const btnAttach = document.getElementById('btn-attach-file');
    const btnLoc = document.getElementById('btn-send-location');
    const btnSnap = document.getElementById('btn-snap-photo');
    const btnVNote = document.getElementById('btn-record-video-note');
    const btnVoice = document.getElementById('btn-record-voice');

    const allFilesBlocked = upOff || (
        isContentTypeBlockedForMeInChat(chat, 'photo') &&
        isContentTypeBlockedForMeInChat(chat, 'video') &&
        isContentTypeBlockedForMeInChat(chat, 'audio') &&
        isContentTypeBlockedForMeInChat(chat, 'document')
    );
    if (btnAttach) btnAttach.classList.toggle('hidden', allFilesBlocked);
    if (btnSnap) btnSnap.classList.toggle('hidden', upOff || isContentTypeBlockedForMeInChat(chat, 'photo'));
    if (btnLoc) btnLoc.classList.toggle('hidden', isContentTypeBlockedForMeInChat(chat, 'location'));
    if (btnVNote) {
        const vnoteOff = upOff || (!isSuper && Number(store.settings.video_note_enabled) === 0) || isContentTypeBlockedForMeInChat(chat, 'video_note');
        btnVNote.classList.toggle('hidden', vnoteOff);
    }
    if (btnVoice) {
        const voiceOff = upOff || (!isSuper && Number(store.settings.voice_enabled) === 0) || isContentTypeBlockedForMeInChat(chat, 'voice');
        btnVoice.classList.toggle('hidden', voiceOff);
    }
}

/* ---------------- ITEM #21: DIRECT CAMERA PHOTO CAPTURE & SEND MODAL ---------------- */
function openDirectCameraCaptureModal() {
    const chat = getActiveChat();
    if (!chat) return;
    if (areUploadsDisabledForMe() || isContentTypeBlockedForMeInChat(chat, 'photo')) {
        toast(t('err_uploads_disabled') || t('err_generic'), true);
        return;
    }
    if (!navigator.mediaDevices || typeof navigator.mediaDevices.getUserMedia !== 'function') {
        const fb = document.getElementById('camera-fallback-input');
        if (fb) fb.click();
        return;
    }

    const taEl = document.getElementById('composer-textarea');
    const initialCaption = taEl ? taEl.value : '';
    if (taEl && initialCaption) {
        taEl.value = '';
        if (typeof autoResizeComposerInput === 'function') autoResizeComposerInput();
    }

    let activeStream = null;
    let facingMode = (window.innerWidth <= 900) ? 'environment' : 'user';
    let capturedBlob = null;
    let capturedUrl = null;
    let committedSend = false;

    const stopCamStream = () => {
        if (activeStream) {
            try { activeStream.getTracks().forEach(tr => tr.stop()); } catch (e) {}
            activeStream = null;
        }
    };

    openModal(t('cam_modal_title'), (body, close) => {
        const stage = document.createElement('div');
        stage.className = 'cam-capture-stage';
        const videoEl = document.createElement('video');
        videoEl.autoplay = true;
        videoEl.playsInline = true;
        videoEl.muted = true;
        const previewImg = document.createElement('img');
        previewImg.className = 'hidden';
        previewImg.alt = 'Captured photo';
        stage.appendChild(videoEl);
        stage.appendChild(previewImg);
        body.appendChild(stage);

        const camCtrlRow = document.createElement('div');
        camCtrlRow.style.cssText = 'display:flex;gap:8px;justify-content:center;align-items:center;margin:12px 0;flex-wrap:wrap';

        const snapBtn = document.createElement('button');
        snapBtn.type = 'button';
        snapBtn.id = 'btn-cam-shutter';
        snapBtn.className = 'btn btn-primary';
        snapBtn.textContent = t('cam_shutter_btn');

        const flipBtn = document.createElement('button');
        flipBtn.type = 'button';
        flipBtn.id = 'btn-cam-flip';
        flipBtn.className = 'btn btn-secondary';
        flipBtn.textContent = t('cam_flip_btn');

        const retakeBtn = document.createElement('button');
        retakeBtn.type = 'button';
        retakeBtn.id = 'btn-cam-retake';
        retakeBtn.className = 'btn btn-secondary hidden';
        retakeBtn.textContent = t('cam_retake_btn');

        const pickGalleryBtn = document.createElement('button');
        pickGalleryBtn.type = 'button';
        pickGalleryBtn.className = 'btn btn-secondary btn-sm';
        pickGalleryBtn.textContent = '🖼️ ' + t('tip_attach');
        pickGalleryBtn.addEventListener('click', () => {
            committedSend = true;
            stopCamStream();
            close();
            if (taEl && initialCaption) {
                taEl.value = initialCaption;
                if (typeof autoResizeComposerInput === 'function') autoResizeComposerInput();
            }
            const fb = document.getElementById('camera-fallback-input');
            if (fb) fb.click();
        });

        camCtrlRow.appendChild(snapBtn);
        camCtrlRow.appendChild(flipBtn);
        camCtrlRow.appendChild(retakeBtn);
        camCtrlRow.appendChild(pickGalleryBtn);
        body.appendChild(camCtrlRow);

        // Spoiler / Covered Display Option
        const spLabel = document.createElement('label');
        spLabel.style.cssText = 'display:flex;align-items:flex-start;gap:8px;padding:10px 12px;margin-bottom:10px;border-radius:10px;background:var(--bg-soft);border:1px solid var(--border);cursor:pointer;user-select:none';
        const chkSpoiler = document.createElement('input');
        chkSpoiler.type = 'checkbox';
        const spTxtCol = document.createElement('div');
        spTxtCol.style.cssText = 'min-width:0;flex:1';
        const spMain = document.createElement('div');
        spMain.style.cssText = 'font-size:13px;font-weight:800;color:var(--text-main)';
        spMain.textContent = t('upload_spoiler_opt_lbl');
        const spDesc = document.createElement('div');
        spDesc.style.cssText = 'font-size:11.5px;color:var(--text-secondary);line-height:1.5;margin-top:3px';
        spDesc.textContent = t('upload_spoiler_opt_desc');
        spTxtCol.appendChild(spMain);
        spTxtCol.appendChild(spDesc);
        spLabel.appendChild(chkSpoiler);
        spLabel.appendChild(spTxtCol);
        body.appendChild(spLabel);

        const capGroup = document.createElement('div');
        capGroup.className = 'form-group';
        const capLbl = document.createElement('label');
        capLbl.textContent = t('caption_label');
        const capInput = document.createElement('textarea');
        capInput.className = 'input';
        capInput.rows = 2;
        capInput.placeholder = t('caption_placeholder');
        if (initialCaption) capInput.value = initialCaption;
        capGroup.appendChild(capLbl);
        capGroup.appendChild(capInput);
        body.appendChild(capGroup);

        const sendPhotoBtn = document.createElement('button');
        sendPhotoBtn.type = 'button';
        sendPhotoBtn.id = 'btn-cam-send-photo';
        sendPhotoBtn.className = 'btn btn-primary btn-block';
        sendPhotoBtn.disabled = true;
        sendPhotoBtn.textContent = t('cam_send_btn');
        body.appendChild(sendPhotoBtn);

        const startPreviewStream = async () => {
            stopCamStream();
            stage.classList.toggle('mirrored', facingMode === 'user');
            try {
                activeStream = await navigator.mediaDevices.getUserMedia({
                    video: { facingMode: { ideal: facingMode }, width: { ideal: 1920 }, height: { ideal: 1440 } },
                    audio: false
                });
                videoEl.srcObject = activeStream;
                await videoEl.play().catch(() => {});
            } catch (err) {
                try {
                    activeStream = await navigator.mediaDevices.getUserMedia({ video: true, audio: false });
                    videoEl.srcObject = activeStream;
                    await videoEl.play().catch(() => {});
                } catch (err2) {
                    toast(t('cam_err_access'), true);
                    committedSend = true;
                    close();
                    if (taEl && initialCaption) {
                        taEl.value = initialCaption;
                        if (typeof autoResizeComposerInput === 'function') autoResizeComposerInput();
                    }
                    const fb = document.getElementById('camera-fallback-input');
                    if (fb) fb.click();
                }
            }
        };

        snapBtn.addEventListener('click', () => {
            if (!videoEl.videoWidth || !videoEl.videoHeight) return;
            const canvas = document.createElement('canvas');
            canvas.width = videoEl.videoWidth;
            canvas.height = videoEl.videoHeight;
            const ctx = canvas.getContext('2d');
            if (facingMode === 'user') {
                ctx.translate(canvas.width, 0);
                ctx.scale(-1, 1);
            }
            ctx.drawImage(videoEl, 0, 0, canvas.width, canvas.height);
            canvas.toBlob(blob => {
                if (!blob) return;
                capturedBlob = blob;
                if (capturedUrl) { try { URL.revokeObjectURL(capturedUrl); } catch (e) {} }
                capturedUrl = URL.createObjectURL(blob);
                previewImg.src = capturedUrl;
                previewImg.classList.remove('hidden');
                videoEl.classList.add('hidden');
                stage.classList.remove('mirrored');
                snapBtn.classList.add('hidden');
                flipBtn.classList.add('hidden');
                retakeBtn.classList.remove('hidden');
                sendPhotoBtn.disabled = false;
                stopCamStream();
            }, 'image/jpeg', 0.92);
        });

        flipBtn.addEventListener('click', async () => {
            facingMode = (facingMode === 'user') ? 'environment' : 'user';
            await startPreviewStream();
        });

        retakeBtn.addEventListener('click', async () => {
            capturedBlob = null;
            if (capturedUrl) { try { URL.revokeObjectURL(capturedUrl); } catch (e) {} capturedUrl = null; }
            previewImg.classList.add('hidden');
            videoEl.classList.remove('hidden');
            snapBtn.classList.remove('hidden');
            flipBtn.classList.remove('hidden');
            retakeBtn.classList.add('hidden');
            sendPhotoBtn.disabled = true;
            await startPreviewStream();
        });

        sendPhotoBtn.addEventListener('click', async () => {
            if (!capturedBlob) return;
            const stamp = new Date().toISOString().replace(/[-:T]/g, '').slice(0, 15);
            const photoFile = new File([capturedBlob], `photo_${stamp}.jpg`, { type: 'image/jpeg' });
            const maxMb = Number((store.settings && store.settings.max_file_mb) || 16);
            if (maxMb > 0 && photoFile.size > Math.round(maxMb * 1048576)) {
                toast(`${t('err_upload_failed')} (${formatLocalizedCount(maxMb)} ${t('unit_mb')})`, true);
                return;
            }
            sendPhotoBtn.disabled = true;
            sendPhotoBtn.textContent = t('uploading_wait');
            committedSend = true;

            const ttlPayloadVal = getEffectiveComposerTtlPayload();
            const spoilerVal = chkSpoiler.checked ? 1 : 0;
            const capText = capInput.value.trim();
            let uploadBlob = photoFile;
            let encryptedFlag = 0;
            let fileIvStr = '';
            let cipherCap = '';
            let ivCap = '';

            if (chat.type === 'secret') {
                try {
                    const encFile = await E2EE.encryptBlob(chat, photoFile);
                    uploadBlob = encFile.blob;
                    encryptedFlag = 1;
                    fileIvStr = encFile.iv;
                    if (capText) {
                        const enc = await E2EE.encryptText(chat, capText);
                        cipherCap = enc.cipher;
                        ivCap = enc.iv;
                    }
                } catch (e) {
                    sendPhotoBtn.disabled = false;
                    sendPhotoBtn.textContent = t('cam_send_btn');
                    toast(e.message || t('e2ee_key_not_ready'), true);
                    return;
                }
            }

            let replyMsgId = 0;
            if (store.replyToMsg) {
                replyMsgId = store.replyToMsg.id;
                store.replyToMsg = null;
                updateComposerContextBar();
            }

            let res;
            const srvSafeChunk = Math.min(1048576, Math.max(65536, Number((store.settings && store.settings.server_upload_chunk_bytes) || 1048576)));
            const chunkThreshold = Math.min(900000, Math.floor(srvSafeChunk * 0.85));
            if (uploadBlob.size > chunkThreshold) {
                const chunkRes = await uploadBlobInChunks('upload_chunk', uploadBlob, pct => {
                    sendPhotoBtn.textContent = `${t('uploading_wait')} (${formatLocalizedCount(pct)}%)`;
                });
                if (!chunkRes.ok) {
                    sendPhotoBtn.disabled = false;
                    sendPhotoBtn.textContent = t('cam_send_btn');
                    toast(chunkRes.message || t('err_upload_failed'), true);
                    return;
                }
                const upMeta = {
                    chat_id: chat.id,
                    kind: 'file',
                    ttl: ttlPayloadVal,
                    spoiler: spoilerVal,
                    chunk_upload_id: chunkRes.upload_id,
                    file_name: photoFile.name
                };
                if (encryptedFlag) {
                    upMeta.encrypted = 1;
                    upMeta.file_iv = fileIvStr;
                    if (cipherCap) { upMeta.cipher = cipherCap; upMeta.iv = ivCap; }
                } else {
                    upMeta.caption = capText;
                }
                if (replyMsgId > 0) upMeta.reply_to = replyMsgId;
                res = await apiCall('upload', upMeta);
            } else {
                const fd = new FormData();
                fd.append('chat_id', String(chat.id));
                fd.append('kind', 'file');
                fd.append('ttl', String(ttlPayloadVal));
                if (spoilerVal) fd.append('spoiler', '1');
                if (encryptedFlag) {
                    fd.append('encrypted', '1');
                    fd.append('file_iv', fileIvStr);
                    if (cipherCap) { fd.append('cipher', cipherCap); fd.append('iv', ivCap); }
                } else {
                    fd.append('caption', capText);
                }
                if (replyMsgId > 0) fd.append('reply_to', String(replyMsgId));
                fd.append('file', uploadBlob, photoFile.name);
                res = await apiCall('upload', fd, true);
            }

            stopCamStream();
            close();
            if (res && res.ok && res.data && res.data.message) {
                store._forcePinBottomUntil = Date.now() + 2200;
                resetComposerTtlAfterSend();
                if (typeof playChatActionSound === 'function') playChatActionSound('send');
                upsertChatMessage(chat.id, res.data.message);
                await renderMessagesViewport(true);
                pinViewportToBottom(document.getElementById('messages-viewport'));
                const cRes = await apiCall('chats_list');
                if (cRes.ok) {
                    store.chats = cRes.data.chats;
                    renderChatList();
                }
                toast(t('file_sent_ok'));
            } else {
                toast((res && res.message) || t('err_upload_failed'), true);
            }
        });

        const appDlgEl = document.getElementById('app-modal');
        if (appDlgEl) {
            appDlgEl.addEventListener('close', () => {
                stopCamStream();
                if (capturedUrl) { try { URL.revokeObjectURL(capturedUrl); } catch (e) {} capturedUrl = null; }
                if (!committedSend && initialCaption) {
                    const taNow = document.getElementById('composer-textarea');
                    const txtBack = capInput.value.trim() !== '' ? capInput.value : initialCaption;
                    if (taNow && txtBack) {
                        taNow.value = taNow.value.trim() ? (taNow.value + '\n' + txtBack) : txtBack;
                        if (typeof autoResizeComposerInput === 'function') autoResizeComposerInput();
                    }
                }
            }, { once: true });
        }

        startPreviewStream();
    });
}

/* ---------------- ITEM #7: DESKTOP <select> CUSTOM POPUP ENHANCER (ZERO TEXT CLIPPING) ---------------- */
(function initDesktopCustomSelectEnhancer() {
    let activePopup = null;
    let activeSelect = null;
    let popupOpenedAt = 0;

    const closeActivePopup = () => {
        if (activePopup) {
            try { activePopup.remove(); } catch (e) {}
            activePopup = null;
        }
        activeSelect = null;
    };

    const isDesktopFinePointer = () => {
        if ((window.innerWidth || 0) <= 768) return false;
        if (window.matchMedia && window.matchMedia('(pointer: coarse)').matches && !window.matchMedia('(pointer: fine)').matches) {
            return false;
        }
        return true;
    };

    const openCustomSelectPopup = (sel) => {
        if (!sel || sel.disabled || sel.multiple || (Number(sel.size || 0) > 1)) return;
        if (activeSelect === sel && activePopup) {
            closeActivePopup();
            return;
        }
        closeActivePopup();
        activeSelect = sel;

        const hostDialog = sel.closest('dialog[open]');
        const mountRoot = hostDialog || document.body;
        const pop = document.createElement('div');
        pop.className = 'm3-custom-select-popup';
        pop.setAttribute('role', 'listbox');
        pop.dir = document.documentElement.dir || 'rtl';

        const opts = Array.from(sel.options || []);
        let activeOptBtn = null;
        opts.forEach((opt, idx) => {
            const btn = document.createElement('button');
            btn.type = 'button';
            btn.className = 'm3-custom-select-opt' + (idx === sel.selectedIndex ? ' is-selected' : '');
            btn.disabled = !!opt.disabled;
            btn.setAttribute('role', 'option');
            btn.setAttribute('aria-selected', idx === sel.selectedIndex ? 'true' : 'false');

            const txt = document.createElement('span');
            txt.style.cssText = 'flex:1;min-width:0;unicode-bidi:plaintext;word-break:break-word';
            txt.textContent = opt.textContent || opt.label || '';

            const chk = document.createElement('span');
            chk.className = 'm3-opt-check';
            chk.textContent = idx === sel.selectedIndex ? '✓' : '';

            btn.appendChild(txt);
            btn.appendChild(chk);
            btn.addEventListener('click', (ev) => {
                ev.preventDefault();
                ev.stopPropagation();
                if (opt.disabled) return;
                const prevIdx = sel.selectedIndex;
                sel.selectedIndex = idx;
                sel.value = opt.value;
                closeActivePopup();
                if (prevIdx !== idx) {
                    sel.dispatchEvent(new Event('input', { bubbles: true }));
                    sel.dispatchEvent(new Event('change', { bubbles: true }));
                }
                try { sel.focus({ preventScroll: true }); } catch (e) {}
            });
            if (idx === sel.selectedIndex) activeOptBtn = btn;
            pop.appendChild(btn);
        });

        mountRoot.appendChild(pop);
        activePopup = pop;

        const rect = sel.getBoundingClientRect();
        const vw = window.innerWidth || document.documentElement.clientWidth || 1280;
        const vh = window.innerHeight || document.documentElement.clientHeight || 800;
        const minW = Math.min(vw - 24, Math.max(Math.ceil(rect.width), 240));
        pop.style.minWidth = minW + 'px';
        pop.style.maxWidth = Math.min(540, vw - 24) + 'px';

        const popRect = pop.getBoundingClientRect();
        const actualW = Math.max(minW, Math.ceil(popRect.width));
        let leftPx = (document.documentElement.dir === 'rtl') ? (rect.right - actualW) : rect.left;
        if (leftPx + actualW > vw - 12) leftPx = vw - 12 - actualW;
        if (leftPx < 12) leftPx = 12;

        const spaceBelow = vh - rect.bottom - 14;
        const spaceAbove = rect.top - 14;
        let topPx = rect.bottom + 6;
        if (spaceBelow < 200 && spaceAbove > spaceBelow) {
            const maxH = Math.min(320, Math.max(120, spaceAbove));
            pop.style.maxHeight = maxH + 'px';
            const measuredH = Math.min(maxH, pop.scrollHeight + 12);
            topPx = Math.max(12, rect.top - measuredH - 6);
        } else {
            pop.style.maxHeight = Math.min(320, Math.max(140, spaceBelow)) + 'px';
        }

        pop.style.left = Math.round(leftPx) + 'px';
        pop.style.top = Math.round(topPx) + 'px';
        popupOpenedAt = Date.now();

        if (activeOptBtn) {
            pop.scrollTop = Math.max(0, activeOptBtn.offsetTop - Math.floor(pop.clientHeight / 2));
        }
    };

    document.addEventListener('mousedown', (ev) => {
        if (activePopup && activePopup.contains(ev.target)) return;
        const sel = ev.target && ev.target.closest ? ev.target.closest('select') : null;
        if (sel && isDesktopFinePointer() && !sel.multiple && Number(sel.size || 0) <= 1) {
            ev.preventDefault();
            try { sel.focus({ preventScroll: true }); } catch (e) {}
            openCustomSelectPopup(sel);
            return;
        }
        if (activePopup) closeActivePopup();
    }, true);

    document.addEventListener('keydown', (ev) => {
        if (ev.key === 'Escape' && activePopup) {
            ev.preventDefault();
            ev.stopPropagation();
            const prevSel = activeSelect;
            closeActivePopup();
            if (prevSel) { try { prevSel.focus({ preventScroll: true }); } catch (e) {} }
            return;
        }
        const focused = document.activeElement;
        if (focused && focused.tagName === 'SELECT' && isDesktopFinePointer() && !focused.multiple && Number(focused.size || 0) <= 1) {
            if (ev.key === ' ' || ev.key === 'Enter' || (ev.altKey && ev.key === 'ArrowDown')) {
                ev.preventDefault();
                openCustomSelectPopup(focused);
            }
        }
    }, true);

    window.addEventListener('resize', closeActivePopup, { passive: true });
    document.addEventListener('scroll', (ev) => {
        if (!activePopup || (Date.now() - popupOpenedAt) < 120) return;
        if (ev.target && (ev.target === activePopup || (activePopup.contains && activePopup.contains(ev.target)))) return;
        closeActivePopup();
    }, true);
})();

/* ---------------- USER ACTIVE SESSIONS MANAGER SUB-MODAL (ZERO METADATA — ITEM #14) ---------------- */
async function openUserSessionsSubModal() {
    openSubModal(t('sessions_modal_title'), async (body) => {
        body.innerHTML = `<div style="padding:18px;text-align:center;color:var(--text-muted)">${esc(t('loading'))}</div>`;
        let lastGraceTimer = null;
        const renderList = async () => {
            if (lastGraceTimer) { clearInterval(lastGraceTimer); lastGraceTimer = null; }
            const sr = await apiCall('session_list');
            body.innerHTML = '';
            if (!sr.ok) {
                body.innerHTML = `<div style="padding:16px;color:var(--danger)">${esc(sr.message || t('err_generic'))}</div>`;
                return;
            }
            const privBanner = document.createElement('div');
            privBanner.style.cssText = 'font-size:12px;color:var(--text-secondary);background:var(--bg-subtle);border:1px solid var(--border);border-radius:10px;padding:9px 11px;margin-bottom:10px;line-height:1.55';
            privBanner.textContent = t('session_zero_meta_note');
            body.appendChild(privBanner);

            const list = Array.isArray(sr.data && sr.data.sessions) ? sr.data.sessions : [];
            const graceSec = Math.max(0, Number((sr.data && sr.data.revoke_grace_sec) || 0));
            let graceLeftSec = Math.max(0, Number((sr.data && sr.data.revoke_grace_left_sec) || 0));
            const graceLocked = (graceSec > 0 && graceLeftSec > 0);

            // Coarse single-unit countdown (matches global TTL countdown style)
            const coarseLeft = (sec) => {
                const s = Math.max(0, Math.round(sec));
                if (s <= 0) return '0';
                if (s >= 3600) {
                    const h = Math.floor(s / 3600);
                    const m = Math.round((s % 3600) / 60);
                    return m >= 30 ? (h + 1) + ' ' + t('session_grace_hour_unit') : h + ' ' + t('session_grace_hour_unit');
                }
                if (s >= 60) return Math.ceil(s / 60) + ' ' + t('session_grace_min_unit');
                return s + '';
            };
            const toFaDigitsLocal = (v) => (store.lang === 'fa' ? String(v).replace(/\d/g, d => '۰۱۲۳۴۵۶۷۸۹'[Number(d)]) : String(v));

            let graceBanner = null;
            let graceTimer = null;
            const lockedBtns = [];
            const refreshGraceUi = () => {
                const stillLocked = (graceSec > 0 && graceLeftSec > 0);
                lockedBtns.forEach(b => {
                    b.disabled = stillLocked;
                    b.style.opacity = stillLocked ? '0.45' : '';
                    b.style.cursor = stillLocked ? 'not-allowed' : '';
                    b.title = stillLocked ? t('session_grace_disabled_hint') : '';
                });
                if (graceBanner) {
                    graceBanner.textContent = stillLocked
                        ? '⏳ ' + t('session_grace_locked_lbl') + ' — ' + t('session_grace_locked_note') + toFaDigitsLocal(coarseLeft(graceLeftSec))
                        : '';
                }
            };
            if (graceLocked) {
                graceBanner = document.createElement('div');
                graceBanner.style.cssText = 'font-size:12px;font-weight:700;color:var(--text-main);background:var(--bg-soft);border:1px solid var(--border);border-radius:10px;padding:9px 11px;margin-bottom:10px;line-height:1.6';
                body.appendChild(graceBanner);
                refreshGraceUi();
                if (lastGraceTimer) { clearInterval(lastGraceTimer); lastGraceTimer = null; }
                lastGraceTimer = graceTimer;
                graceTimer = setInterval(() => {
                    graceLeftSec -= 1;
                    if (graceLeftSec <= 0) {
                        graceLeftSec = 0;
                        clearInterval(graceTimer);
                        graceTimer = null;
                        lastGraceTimer = null;
                        refreshGraceUi();
                        return;
                    }
                    refreshGraceUi();
                }, 1000);
            }
            if (list.length > 1) {
                const topAct = document.createElement('div');
                topAct.className = 'resp-action-row';
                topAct.style.cssText = 'justify-content:flex-end;margin-bottom:10px';

                const keepLatestBtn = document.createElement('button');
                keepLatestBtn.type = 'button';
                keepLatestBtn.className = 'btn btn-secondary btn-sm';
                keepLatestBtn.textContent = t('session_keep_latest_btn');
                lockedBtns.push(keepLatestBtn);
                keepLatestBtn.addEventListener('click', async () => {
                    if (graceSec > 0 && graceLeftSec > 0) {
                        toast(t('sessions_revoke_locked_toast'), true);
                        return;
                    }
                    const ap = await askApproval({
                        title: t('session_keep_latest_btn'),
                        desc: t('session_zero_meta_note'),
                        danger: true,
                        icon: '🧹'
                    });
                    if (!ap.approved) return;
                    const rr = await apiCall('session_revoke', { session_id: 'keep_latest' });
                    if (rr.ok) {
                        toast(t('sessions_revoked_toast'));
                        await renderList();
                    } else {
                        toast(rr.message || t('err_generic'), true);
                    }
                });
                topAct.appendChild(keepLatestBtn);

                const revOthersBtn = document.createElement('button');
                revOthersBtn.type = 'button';
                revOthersBtn.className = 'btn btn-danger btn-sm';
                revOthersBtn.textContent = '🛡️ ' + t('revoke_other_sessions');
                lockedBtns.push(revOthersBtn);
                revOthersBtn.addEventListener('click', async () => {
                    if (graceSec > 0 && graceLeftSec > 0) {
                        toast(t('sessions_revoke_locked_toast'), true);
                        return;
                    }
                    const ap = await askApproval({
                        title: t('revoke_other_sessions'),
                        desc: list.filter(x => !x.is_current).map(x => `• ${t('session_login_time_lbl')}: ${formatFullTime(x.created_at)}`).join('\n'),
                        danger: true,
                        icon: '🛡️'
                    });
                    if (!ap.approved) return;
                    const rr = await apiCall('session_revoke', { session_id: 'others' });
                    if (rr.ok) {
                        toast(t('sessions_revoked_toast'));
                        await renderList();
                    } else {
                        toast(rr.message || t('err_generic'), true);
                    }
                });
                topAct.appendChild(revOthersBtn);
                body.appendChild(topAct);
            }
            refreshGraceUi();

            list.forEach(s => {
                const card = document.createElement('div');
                card.className = 'card-box';
                card.style.cssText = 'margin-bottom:8px;padding:10px 12px;display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap';
                const info = document.createElement('div');
                info.style.minWidth = '0';
                const titleRow = document.createElement('div');
                titleRow.style.cssText = 'display:flex;align-items:center;gap:6px;flex-wrap:wrap;font-weight:700;font-size:13px';
                if (s.is_current) {
                    const curPill = document.createElement('span');
                    curPill.className = 'adm-badge-pill success';
                    curPill.textContent = t('session_current_tag');
                    titleRow.appendChild(curPill);
                }
                const loginTimeSpan = document.createElement('span');
                // Item #14: Display ONLY login timestamp — zero IP, location, browser, or OS!
                loginTimeSpan.textContent = `${t('session_login_time_lbl')}: ${formatFullTime(s.created_at)}`;
                titleRow.appendChild(loginTimeSpan);
                info.appendChild(titleRow);
                card.appendChild(info);

                if (!s.is_current) {
                    const revOneBtn = document.createElement('button');
                    revOneBtn.type = 'button';
                    revOneBtn.className = 'btn btn-danger btn-sm';
                    revOneBtn.textContent = t('session_revoke_one_btn');
                    lockedBtns.push(revOneBtn);
                    revOneBtn.addEventListener('click', async () => {
                        if (graceSec > 0 && graceLeftSec > 0) {
                            toast(t('sessions_revoke_locked_toast'), true);
                            return;
                        }
                        const ap = await askApproval({
                            title: t('session_revoke_one_btn'),
                            desc: `${t('session_login_time_lbl')}: ${formatFullTime(s.created_at)}`,
                            danger: true,
                            icon: '🔌'
                        });
                        if (!ap.approved) return;
                        const rr = await apiCall('session_revoke', { session_id: s.id });
                        if (rr.ok) {
                            toast(t('session_revoked_one_toast'));
                            await renderList();
                        } else {
                            toast(rr.message || t('err_generic'), true);
                        }
                    });
                    card.appendChild(revOneBtn);
                }
                body.appendChild(card);
            });
        };
        await renderList();
    });
}

/* ---------------- ADMIN PER-CHAT MESSAGE VIEWERS OVERRIDE SUB-MODAL ---------------- */
function openAdminChatViewersOverrideModal(c, dispTitle, onSaved) {
    openSubModal(`${t('adm_chat_viewers_btn')} — ${dispTitle}`, (body, closeSub) => {
        const desc = document.createElement('p');
        desc.style.cssText = 'font-size:12.5px;color:var(--text-secondary);margin:0 0 12px;line-height:1.55';
        desc.textContent = t('viewers_gov_chat_desc');
        body.appendChild(desc);

        const fgSuper = document.createElement('div');
        fgSuper.className = 'form-group';
        const lSuper = document.createElement('label');
        lSuper.textContent = t('viewers_super_chat_override_lbl');
        const selSuper = document.createElement('select');
        selSuper.className = 'input';
        const curSuper = String(c.super_msg_viewers_override || 'inherit');
        [
            ['inherit', t('viewers_super_override_inherit')],
            ['everyone', t('viewers_mode_everyone')],
            ['admins', t('viewers_mode_admins')],
            ['off', t('viewers_mode_off')]
        ].forEach(([val, lbl]) => {
            const o = document.createElement('option');
            o.value = val;
            o.textContent = lbl;
            if (val === curSuper) o.selected = true;
            selSuper.appendChild(o);
        });
        fgSuper.appendChild(lSuper);
        fgSuper.appendChild(selSuper);
        body.appendChild(fgSuper);

        const fgChatMode = document.createElement('div');
        fgChatMode.className = 'form-group';
        const lChatMode = document.createElement('label');
        lChatMode.textContent = t('viewers_gov_chat_lbl');
        const selChatMode = document.createElement('select');
        selChatMode.className = 'input';
        const curChatMode = String(c.msg_viewers_mode || 'default');
        const defLbl = c.type === 'channel' ? t('viewers_mode_default_channel') : t('viewers_mode_default_group');
        [
            ['default', defLbl],
            ['everyone', t('viewers_mode_everyone')],
            ['admins', t('viewers_mode_admins')],
            ['off', t('viewers_mode_off')]
        ].forEach(([val, lbl]) => {
            const o = document.createElement('option');
            o.value = val;
            o.textContent = lbl;
            if (val === curChatMode) o.selected = true;
            selChatMode.appendChild(o);
        });
        fgChatMode.appendChild(lChatMode);
        fgChatMode.appendChild(selChatMode);
        body.appendChild(fgChatMode);

        const saveBtn = document.createElement('button');
        saveBtn.type = 'button';
        saveBtn.className = 'btn btn-primary btn-block';
        saveBtn.style.marginTop = '10px';
        saveBtn.textContent = t('save_changes');
        saveBtn.addEventListener('click', async () => {
            const r = await apiCall('admin_chat_viewers_override', {
                chat_id: c.id,
                super_msg_viewers_override: selSuper.value,
                msg_viewers_mode: selChatMode.value
            });
            if (r.ok) {
                c.super_msg_viewers_override = selSuper.value;
                c.msg_viewers_mode = selChatMode.value;
                const liveChat = store.chats.find(x => x.id === c.id);
                if (liveChat) {
                    liveChat.super_msg_viewers_override = selSuper.value;
                    liveChat.msg_viewers_mode = selChatMode.value;
                }
                closeSub();
                toast(t('adm_chat_viewers_saved_toast'));
                if (typeof onSaved === 'function') onSaved();
            } else {
                toast(r.message || t('err_generic'), true);
            }
        });
        body.appendChild(saveBtn);
    });
}

/* ---------------- ADMIN PER-USER CONTENT, CALL & MESSAGE VIEWERS POLICIES SUB-MODAL ---------------- */
function openAdminUserPoliciesSubModal(u) {
    openSubModal(t('content_restrict_user_title').replace('{name}', u.name || u.username), (body, closeSub) => {
        const ALL_CTYPES = ['photo', 'video', 'video_note', 'audio', 'voice', 'document', 'link', 'location'];
        const curUserSet = new Set(Array.isArray(u.restricted_content_types) ? u.restricted_content_types : []);
        const ctHead = document.createElement('div');
        ctHead.style.cssText = 'font-weight:800;font-size:13px;color:var(--primary);margin-bottom:8px';
        ctHead.textContent = t('content_restrict_sec_title');
        body.appendChild(ctHead);

        const ctGrid = document.createElement('div');
        ctGrid.className = 'resp-grid-2';
        const chks = {};
        ALL_CTYPES.forEach(ct => {
            const lbl = document.createElement('label');
            lbl.className = 'adm-perm-card';
lbl.style.cssText = 'justify-content:flex-start;gap:10px;font-size:12.5px;font-weight:700;cursor:pointer';
            const c = document.createElement('input');
            c.type = 'checkbox';
            c.checked = curUserSet.has(ct);
