            const s = document.createElement('span');
            s.textContent = t('ctype_' + ct);
            lbl.appendChild(c);
            lbl.appendChild(s);
            ctGrid.appendChild(lbl);
        });
        body.appendChild(ctGrid);

        const uCall = (u.call_policy && typeof u.call_policy === 'object') ? u.call_policy : {};
        const cgHead = document.createElement('div');
        cgHead.style.cssText = 'font-weight:800;font-size:13px;color:var(--primary);margin:14px 0 8px';
        cgHead.textContent = t('call_gov_sec_title');
        body.appendChild(cgHead);

        const mkSel = (lblTxt, curVal, opts) => {
            const fg = document.createElement('div');
            fg.className = 'form-group';
            const l = document.createElement('label');
            l.textContent = lblTxt;
            const sel = document.createElement('select');
            sel.className = 'input';
            opts.forEach(([v, tx]) => {
                const o = document.createElement('option');
                o.value = v;
                o.textContent = tx;
                if (String(v) === String(curVal)) o.selected = true;
                sel.appendChild(o);
            });
            fg.appendChild(l);
            fg.appendChild(sel);
            return { fg, sel };
        };

        const sVoice = mkSel(t('tip_voice_call'), Number(uCall.voice_enabled) === 0 ? '0' : '-1', [
            ['-1', t('call_user_voice_allow')],
            ['0', t('call_user_voice_deny')]
