            ['-1', t('call_user_video_allow')],
            ['0', t('call_user_video_deny')]
        ]);
        const qPolOpts = [
            ['free', t('call_pol_free')],
            ['max:low', t('call_pol_max_low')],
            ['max:medium', t('call_pol_max_medium')],
            ['max:high', t('call_pol_max_high')],
            ['max:hd', t('call_pol_max_hd')],
            ['lock:low', t('call_pol_lock_low')],
            ['lock:medium', t('call_pol_lock_medium')],
            ['lock:high', t('call_pol_lock_high')],
            ['lock:hd', t('call_pol_lock_hd')]
        ];
        const sAudPol = mkSel(t('call_gov_aud_pol_lbl'), uCall.audio_policy || 'free', qPolOpts.filter(x => !x[0].endsWith(':hd')));
        const sVidPol = mkSel(t('call_gov_vid_pol_lbl'), uCall.video_policy || 'free', qPolOpts);
        const fgDur = document.createElement('div');
        fgDur.className = 'form-group';
        const lDur = document.createElement('label');
        lDur.textContent = t('call_gov_max_dur_lbl');
        const inDur = document.createElement('input');
        inDur.type = 'number';
        inDur.min = '0';
        inDur.max = '1440';
        inDur.className = 'input';
        inDur.value = String(Math.round(Number(uCall.max_duration_sec || 0) / 60));
        fgDur.appendChild(lDur);
