    curRow.appendChild(curInp);
    card.appendChild(curRow);

    const fgTarget = document.createElement('div');
    fgTarget.className = 'form-group';
    const lTarget = document.createElement('label');
    lTarget.textContent = t('adm_db_mig_target_lbl');
    const selTarget = document.createElement('select');
    selTarget.className = 'input';
