    const mUser = mkIn(t('inst_db_user'), info.mysql_user || 'root');
    const mPass = mkIn(t('inst_db_pass'), '', 'password');
    const g1 = document.createElement('div');
    g1.className = 'resp-grid-2';
    g1.appendChild(mHost.fg);
    g1.appendChild(mPort.fg);
    mysqlWrap.appendChild(g1);
    mysqlWrap.appendChild(mName.fg);
    const g2 = document.createElement('div');
    g2.className = 'resp-grid-2';
    g2.appendChild(mUser.fg);
    g2.appendChild(mPass.fg);
    mysqlWrap.appendChild(g2);

    const rmOldLbl = document.createElement('label');
    rmOldLbl.className = 'settings-chk-row';
    rmOldLbl.style.cssText = 'font-size:12px;margin-top:6px;margin-bottom:0';
    const chkRmOldSq = document.createElement('input');
    chkRmOldSq.type = 'checkbox';
    const spRmOldSq = document.createElement('span');
    spRmOldSq.textContent = t('adm_db_mig_remove_old_sq');
    rmOldLbl.appendChild(chkRmOldSq);
    rmOldLbl.appendChild(spRmOldSq);
    mysqlWrap.appendChild(rmOldLbl);
    if (typeof enhancePasswordFields === 'function') enhancePasswordFields(mysqlWrap);
    card.appendChild(mysqlWrap);

    const syncTargetVis = () => { mysqlWrap.classList.toggle('hidden', selTarget.value !== 'mysql'); };
    selTarget.addEventListener('change', syncTargetVis);
    syncTargetVis();

    const btnRow = document.createElement('div');
    btnRow.className = 'resp-action-row';
    const buildPayload = (confirmed = false) => ({
        target_driver: selTarget.value,
        db_host: mHost.i.value.trim() || '127.0.0.1',
        db_port: parseInt(mPort.i.value || '3306', 10) || 3306,
        db_name: mName.i.value.trim(),
        db_user: mUser.i.value.trim(),
        db_pass: mPass.i.value,
        remove_old_sqlite: chkRmOldSq.checked ? 1 : 0,
        confirmed: confirmed ? 1 : 0
    });

    const testBtn = document.createElement('button');
    testBtn.type = 'button';
    testBtn.className = 'btn btn-secondary btn-sm';
    testBtn.textContent = t('adm_db_mig_test_btn');
    testBtn.addEventListener('click', async () => {
        testBtn.disabled = true;
        const r = await apiCall('admin_db_migrate_test', buildPayload(false));
        testBtn.disabled = false;
        if (r.ok && r.data) toast(t('adm_db_mig_test_ok') + (r.data.server_version || selTarget.value));
        else toast(r.message || t('err_generic'), true);
    });

    const runBtn = document.createElement('button');
    runBtn.type = 'button';
    runBtn.className = 'btn btn-primary btn-sm';
    runBtn.textContent = t('adm_db_mig_run_btn');
    runBtn.addEventListener('click', async () => {
        const ap = await askApproval({
            title: t('adm_db_mig_sec_title'),
            desc: `${t('adm_db_mig_sec_desc')}\n➡️ ${selTarget.value === 'mysql' ? 'MariaDB / MySQL' : 'SQLite'}`,
            checkboxLabel: t('adm_db_mig_confirm_chk'),
            checkboxRequired: true,
            danger: false,
            icon: '🔄'
        });
        if (!ap.approved) return;
        runBtn.disabled = true;
        testBtn.disabled = true;
        const r = await apiCall('admin_db_migrate_run', buildPayload(true));
        runBtn.disabled = false;
        testBtn.disabled = false;
        if (r.ok && r.data) {
            toast(t('adm_db_mig_done_toast') + String(r.data.active_driver || selTarget.value).toUpperCase());
            if (typeof onMigrated === 'function') onMigrated();
        } else {
            toast(r.message || t('err_generic'), true);
        }
    });

    btnRow.appendChild(testBtn);
    btnRow.appendChild(runBtn);
    card.appendChild(btnRow);
    return card;
}

/* ---------------- ITEM 13 & 17: SEND LOCATION (STATIC & LIVE) & LOCATION CARD ---------------- */
function formatFullDateTimeExact(unixTs) {
    if (!unixTs) return '';
    try {
        const d = new Date(Number(unixTs) * 1000);
        const loc = store.lang === 'fa' ? 'fa-IR' : 'en-US';
        const tz = getEffectiveAppTimeZone();
        const opts = {
            year: 'numeric',
            month: '2-digit',
            day: '2-digit',
            hour: '2-digit',
            minute: '2-digit',
            second: '2-digit'
        };
        if (tz) opts.timeZone = tz;
        return new Intl.DateTimeFormat(loc, opts).format(d);
    } catch (e) {
        return formatDate(unixTs);
    }
}

const LiveLocationSender = {
    sessions: {},
    start(chat, msgId, intervalSec, expiresAt, labelStr) {
        this.stopLocalOnly(msgId);
        const ivMs = Math.max(5, Number(intervalSec) || 15) * 1000;
        const pushOnce = () => {
            if (!store.user) {
                this.stopLocalOnly(msgId);
                return;
            }
            const nowSec = Math.floor(Date.now() / 1000);
            if (expiresAt > 0 && nowSec >= expiresAt) {
                this.stop(chat, msgId, true);
                return;
            }
            if (!navigator.geolocation) return;
            navigator.geolocation.getCurrentPosition(async pos => {
                const sess = this.sessions[msgId];
                if (!sess) return;
                const lat = Math.round(Number(pos.coords.latitude) * 1000000) / 1000000;
                const lng = Math.round(Number(pos.coords.longitude) * 1000000) / 1000000;
                const acc = Math.round(Number(pos.coords.accuracy || 0));
                const updTs = Math.floor(Date.now() / 1000);
                const payload = { message_id: msgId };
                if (chat && chat.type === 'secret') {
                    try {
                        const locObj = {
                            lat,
                            lng,
                            label: labelStr || '',
                            acc,
                            is_live: 1,
                            live_active: 1,
                            live_interval_sec: Math.round(ivMs / 1000),
                            live_expires_at: expiresAt,
                            updated_at: updTs
                        };
                        const enc = await E2EE.encryptText(chat, JSON.stringify(locObj));
                        payload.cipher = enc.cipher;
                        payload.iv = enc.iv;
                    } catch (e) {
                        return;
                    }
                } else {
                    payload.latitude = lat;
                    payload.longitude = lng;
                    payload.accuracy = acc;
                }
                const r = await apiCall('location_live_update', payload);
                if (r.ok && r.data && r.data.message) {
                    delete store.decryptedTextCache[msgId];
                    upsertChatMessage(chat.id, r.data.message);
                    if (store.activeChatId === chat.id) renderMessagesViewport(false);
                } else if (r.error === 'live_expired') {
                    this.stopLocalOnly(msgId);
                }
            }, () => {}, { enableHighAccuracy: true, maximumAge: 3000, timeout: 8000 });
        };
        const timerId = setInterval(pushOnce, ivMs);
        this.sessions[msgId] = { timerId, chatId: chat.id, expiresAt, labelStr };
    },
    stopLocalOnly(msgId) {
        const s = this.sessions[msgId];
        if (s) {
            clearInterval(s.timerId);
            delete this.sessions[msgId];
        }
    },
    async stop(chat, msgId, silent = false) {
        const sess = this.sessions[msgId];
        const labelKeep = sess ? sess.labelStr : '';
        this.stopLocalOnly(msgId);
        const payload = { message_id: msgId };
        if (chat && chat.type === 'secret') {
            try {
                const msgList = store.messages[chat.id] || [];
                const curMsg = msgList.find(x => Number(x.id) === Number(msgId));
                let prevLoc = {};
                if (curMsg && store.decryptedTextCache[msgId]) {
                    try { prevLoc = JSON.parse(store.decryptedTextCache[msgId]); } catch (e) {}
                }
                const stoppedObj = Object.assign({}, prevLoc, {
                    label: prevLoc.label || labelKeep || '',
                    is_live: 1,
                    live_active: 0,
                    stopped_at: Math.floor(Date.now() / 1000)
                });
                const enc = await E2EE.encryptText(chat, JSON.stringify(stoppedObj));
                payload.cipher = enc.cipher;
                payload.iv = enc.iv;
            } catch (e) {}
        }
        const r = await apiCall('location_live_stop', payload);
        if (r.ok && r.data && r.data.message) {
            delete store.decryptedTextCache[msgId];
            upsertChatMessage(chat.id, r.data.message);
            if (store.activeChatId === chat.id) renderMessagesViewport(false);
            if (!silent) toast(t('loc_live_stopped_toast'));
        }
    }
};

